INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-02392','杂歌谣辞 步虚词 十四','韋渠牟','quantangshi','','卷3','珠佩紫霞缨，夫人会八灵。
太霄犹有观，绝宅岂无形。
暮雨徘徊降，仙歌宛转听。
谁逢玉妃辇，应检九真经。','',''),('quantangshi-02393','杂歌谣辞 步虚词 十五','韋渠牟','quantangshi','','卷3','西海辞金母，东方拜木公。
云行疑带雨，星步欲凌风。
羽袖挥丹凤，霞巾曳彩虹。
飘颻九霄外，下视望仙宫。','',''),('quantangshi-02394','杂歌谣辞 步虚词 十六','韋渠牟','quantangshi','','卷3','玉树杂金花，天河织女家。
月邀丹凤舄，风送紫鸾车。
雾縠笼绡带，云屏列锦霞。
瑶台千万里，不觉往来赊。','',''),('quantangshi-02395','杂歌谣辞 步虚词 十七','韋渠牟','quantangshi','','卷3','舞凤凌天出，歌麟入夜听。
云容衣眇眇，风韵曲泠泠。
扣齿端金简，焚香检玉经。
仙宫知不远，只近太微星。','',''),('quantangshi-02396','杂歌谣辞 步虚词 十八','韋渠牟','quantangshi','','卷3','紫府与玄洲，谁来物外游。
无烦骑白鹿，不用驾青牛。
金化颜应驻，云飞鬓不秋。
仍闻碧海上，更用玉为楼。','',''),('quantangshi-02397','杂歌谣辞 步虚词 十九','韋渠牟','quantangshi','','卷3','辔鹤复骖鸾，全家去不难。
鸡声随羽化，犬影入云看。
酿玉当成酒，烧金且转丹。
何妨五色绶，次第给仙官。','',''),('quantangshi-02398','杂歌谣辞 步虚词','僧皎然','quantangshi','','卷3','予因览真诀，遂感西域君。
玉笙下青冥，人间未曾闻。
日华炼魂魄，皎皎无垢氛。
谓我有仙骨，且令饵氤氲。
俯仰愧灵颜，愿随鸾鹤羣。
俄然动风驭，缥眇归青云。','',''),('quantangshi-02399','杂歌谣辞 步虚词','高駢','quantangshi','','卷3','青溪道士人不识，上天下天鹤一只。
洞门深[锁]碧窗寒，滴露妍朱写周易。','',''),('quantangshi-02400','杂歌谣辞 步虚引','陳陶','quantangshi','','卷3','小隐山人十洲客，莓苔为衣双耳白。
青编为我忽降书，暮雨虹霓一千尺。
赤城门闭六丁直，晓日已烧东海色。
朝天半夜闻玉鸡，星斗离离碍龙翼。','',''),('quantangshi-02401','咏汉高祖','王珪','quantangshi','','卷3','汉祖起丰沛，乘运以跃鳞。
手奋三尺劒，西灭无道秦。
十月五星聚，七年四海宾。
高抗威宇宙，贵有天下人。
忆昔与项王，契阔时未伸。
鸿门既薄蚀，荥阳亦蒙尘。
虮虱生介胄，将卒多苦辛。
爪牙驱信越，腹心谋张陈。
赫赫西楚国，化为丘与榛。','',''),('quantangshi-02402','咏淮阴侯','王珪','quantangshi','','卷3','秦王日凶慝，豪杰争共亡。
信亦胡为者，剑歌从项梁。
项羽不能用，脱身归汉王。
道契君臣合，时来名位彰。
北讨燕承命，东驱楚绝粮。
斩龙堰濉水，擒豹熸夏阳。
功成享天禄，建旗还南昌。
千金答漂母，百钱酬下乡。
吉凶成纠缠，倚伏难预详。
弓藏狡兔尽，慷慨念心伤。','',''),('quantangshi-02403','早春桂林殿应诏','陳叔達','quantangshi','','卷3','金铺照春色，玉律动年华。
朱楼云似盖，丹桂雪如花。
水岸衔阶转，风条出柳斜。
轻舆临太液，湛露酌流霞。','',''),('quantangshi-02404','后渚置酒','陳叔達','quantangshi','','卷3','大渚初惊夜，中流沸鼓鼙。
寒沙满曲浦，夕雾上邪溪。
岸广凫飞急，云深雁度低。
严关犹未遂，此夕待晨鸡。','',''),('quantangshi-02405','听邻人琵琶','陳叔達','quantangshi','','卷3','本是龙门桐，因妍入汉宫。
香缘罗袖里，声逐朱弦中。
虽有相思韵，翻将入塞同。
关山临却月，花蘂散回风。
为将金谷引，添令曲未终。','',''),('quantangshi-02406','州城西园入斋祠社','陳叔達','quantangshi','','卷3','升坛预洁祀，诘早肃分司。
达气风霜积，登光日色迟。
农教先八政，阳和秩四时。
祈年服垂冕，告币动褰帷。
瘗地尊余奠，人天庶有资。
椒兰卒清酌，簠簋彻香萁。
折俎分归胙，充庭降受厘。
方凭知礼节，况奉化雍熙。','',''),('quantangshi-02407','春首','陳叔達','quantangshi','','卷3','雪花联玉树，冰彩散瑶池。
翔禽遥出没，积翠远参差。','',''),('quantangshi-02408','初年','陳叔達','quantangshi','','卷3','和风起天路，严气消冰井。
索索枝未柔，厌厌漏犹永。','',''),('quantangshi-02409','咏菊','陳叔達','quantangshi','','卷3','霜间开紫蔕，露下发金英。
但令逢采摘，宁辞独晚荣。','',''),('quantangshi-02410','自君之出矣','王融','quantangshi','','卷3','自君之出矣，金炉香不然。
思君当明烛，终宵空自煎。','',''),('quantangshi-02411','自君之出矣 一','陳叔達','quantangshi','','卷3','自君之出矣，红颜转憔悴。
思君如明烛，煎心且衔泪。','',''),('quantangshi-02412','自君之出矣 二','陳叔達','quantangshi','','卷3','自君之出矣，明镜罢红妆。
思君如夜烛，煎泪几千行。','',''),('quantangshi-02413','赋饮马长城窟','袁朗','quantangshi','','卷3','朔风动秋草，清跸长安道。
长城连不穷，所以隔华戎。
规模惟圣作，负荷晓成功。
鸟庭已向内，龙荒更凿空。
玉关尘卷静，金微路已通。
汤征随北怨，舜咏起南风。
画地功初立，绥边事云集。
朝服践狼居，凯歌旋马邑。
山响传凤吹，霜华藻琼鈒。
属国拥节归，单于款关入。
日落寒风起，惊蓬被原隰。
零落叶已寒，河流清且急。
四时徭役尽，千载干戈戢。
太平今若斯，汗马竟无施。
唯当事笔砚，归去草封禅。','',''),('quantangshi-02414','和洗掾登城南坂望京邑','袁朗','quantangshi','','卷3','二华连陌塞，九陇统金方。
奥区称富贵，重险擅雄强。
龙飞灞水上，凤集岐山阳。
神皐多瑞迹，列代有兴王。
我后膺灵命，爰求宅兹土。
宸居法太微，建国资天府。
玄风叶黎庶，德泽浸区宇。
醒醉各相扶，讴歌从圣主。
南登少陵岸，还望帝城中。
帝城何郁郁，佳气乃葱葱。
金凤凌绮观，璇题敞兰宫。
复道东西合，交衢南北通。
万国朝前殿，羣公议宣室。
鸣佩含早风，华蝉曜朝日。
栢梁宴初罢，千钟欢未毕。
端拱肃岩廊，思贤听琴瑟。
逶迤万雉列，隐轸千闾布。
飞甍夹御沟，曲台临上路。
处处歌钟鸣，喧阗车马度。
日落长楸间，含情两相顾。
是月冬之季，阴寒昼不开。
惊风四面集，飞雪千里回。
狐白登廊庙，牛衣出草莱。
讵知韩长孺，无复重然灰。','',''),('quantangshi-02415','秋日应诏','袁朗','quantangshi','','卷3','玉树凉风举，金塘细草萎。
叶落商飙观，鸿归明月池。
迎寒桂酒熟，含露菊花垂。
一奉章台宴，千秋长愿斯。','',''),('quantangshi-02416','秋夜独坐','袁朗','quantangshi','','卷3','危弦断客心，虚弹落惊禽。
新秋百虑净，独夜九愁深。
枯蓬唯逐吹，坠叶不归林。
如何悲此曲，坐作白头吟。','',''),('quantangshi-02417','出塞曲','竇威','quantangshi','','卷3','匈奴屡不平，汉将欲纵横。
看云方结阵，却月始连营。
潜军度马邑，扬斾掩龙城。
会勒燕然石，方传车骑名。','',''),('quantangshi-02418','新曲二首 一','長孫無忌','quantangshi','','卷3','阿侬家住朝歌下，早传名。
结伴来游淇水上，旧长情。
玉佩金钿随步远，云罗雾縠逐风轻。
转目机心悬自许，何须更待听琴声。','',''),('quantangshi-02419','新曲二首 二','長孫無忌','quantangshi','','卷3','回雪凌波游洛浦，遇陈王。
婉约娉婷工语笑，侍兰房。
芙蓉绮帐还开揜，翡翠珠被烂齐光。
长愿今宵奉颜色，不爱吹箫逐凤皇。','',''),('quantangshi-02420','灞桥待李将军','長孫無忌','quantangshi','','卷3','飒飒风叶下，遥遥烟景曛。
霸陵无醉尉，谁滞李将军。','',''),('quantangshi-02421','奉和正日临朝','顏師古','quantangshi','','卷3','七府璇衡始，三元宝历新。
负扆延百辟，垂旒御九宾。
肃肃皆鵷鹭，济济盛簪绅。
天涯致重译，日域献奇珍。','',''),('quantangshi-02422','召拜御史大夫赠袁天纲','杜淹','quantangshi','','卷3','伊吕深可慕，松乔定是虚。
系风终不得，脱屣欲安如。
且珍纨素美，当与薜萝疎。
既逢杨得意，非复久闲居。','',''),('quantangshi-02423','咏寒食鬬鸡应秦王教','杜淹','quantangshi','','卷3','寒食东郊道，扬鞲竞出笼。
花冠初照日，芥羽正生风。
顾敌知心勇，先鸣觉气雄。
长翘频扫阵，利爪屡通中。
飞毛遍绿野，洒血渍芳丛。
虽然百战胜，会自不论功。','',''),('quantangshi-02424','寄赠齐公','杜淹','quantangshi','','卷3','冠盖游梁日，诗书问志年。
佩兰长坂上，攀桂小山前。
结交澹若水，履道直如弦。
此欢终未极，于兹独播迁。
赭衣登蜀道，白首别秦川。
泪随沟水逝，心逐晓旌悬。
去去逾千里，悠悠隔九天。
郊野间长薄，城阙隐凝烟。
关门共月对，山路与云连。
此时寸心里，难用尺书传。','',''),('quantangshi-02425','五郊乐章 黄帝宫音','魏徵','quantangshi','','卷3','黄中正位，含章居贞。
既长六律，兼和五声。
毕陈万舞，乃荐斯牲。
神其下降，永祚休平。','',''),('quantangshi-02426','五郊乐章 黄帝宫音 肃和','魏徵','quantangshi','','卷3','眇眇方舆，苍苍圜盖。
至哉枢纽，宅中图大。
气调四序，风和万籁。
祚我明德，时雍道泰。','',''),('quantangshi-02427','五郊乐章 黄帝宫音 雍和','魏徵','quantangshi','','卷3','金悬夕肆，玉俎朝陈。
飨荐黄道，芬流紫辰。
廼诚廼敬，载享载禋。
崇荐斯在，惟皇是宾。','',''),('quantangshi-02428','五郊乐章 黄帝宫音 舒和','魏徵','quantangshi','','卷3','御征乘宫出郊甸，安歌率舞逓将迎。
自有云门符帝赏，犹持雷鼓答天成。','',''),('quantangshi-02429','五郊乐章 青帝角音','魏徵','quantangshi','','卷3','鹤云旦起，鸟星昏集。
律候新风，阳开初蛰。
至德可飨，行潦斯挹。
锡以无疆，烝人乃粒。','',''),('quantangshi-02430','五郊乐章 青帝角音 肃和','魏徵','quantangshi','','卷3','玄鸟司春，苍龙登岁。
节物变柳，光风转蕙。
瑶席降神，朱弦飨帝。
诚备祝嘏，礼殚圭币。','',''),('quantangshi-02431','五郊乐章 青帝角音 雍和','魏徵','quantangshi','','卷3','大乐稀音，至诚简礼。
文物棣棣，声名济济。
六变有成，三登无体。
廼眷丰絜，恩覃恺悌。','',''),('quantangshi-02432','五郊乐章 青帝角音 舒和','魏徵','quantangshi','','卷3','笙歌龠舞属年韶，鹭鼓凫钟展时豫。
调露初迎绮春节，承云遽践苍霄驭。','',''),('quantangshi-02433','五郊乐章 赤帝征音','魏徵','quantangshi','','卷3','青阳告谢，朱明戒序。
咸长是祈，敬陈椒醑。
博硕斯荐，笙镛备举。
庶尽肃恭，非馨稷黍。','',''),('quantangshi-02434','五郊乐章 赤帝征音 肃和','魏徵','quantangshi','','卷3','离位克明，火中宵见。
峯云暮起，景风晨扇。
木槿初荣，含桃可荐。
芬馥百品，铿锵三变。','',''),('quantangshi-02435','五郊乐章 赤帝征音 雍和','魏徵','quantangshi','','卷3','昭昭丹陆，帟帟炎方。
礼陈牲币，乐备箎簧。
琼羞溢俎，玉𨣧浮觞。
恭惟正直，歆此馨香。','',''),('quantangshi-02436','五郊乐章 赤帝征音 舒和','魏徵','quantangshi','','卷3','千里温风飘降羽，十枝炎景媵朱干。
陈觞荐俎歌三献，拊石摐金会七盘。','',''),('quantangshi-02437','五郊乐章 白帝商音','魏徵','quantangshi','','卷3','白藏应节，天高气清。
岁功既阜，庶类收成。
万方静谧，九土和平。
馨香是荐，受祚聪明。','',''),('quantangshi-02438','五郊乐章 白帝商音 肃和','魏徵','quantangshi','','卷3','金行在节，素灵居正。
气肃霜严，林凋草劲。
豺祭隼击，潦收川镜。
九谷已登，万箱流咏。','',''),('quantangshi-02439','五郊乐章 白帝商音 雍和','魏徵','quantangshi','','卷3','律应西成，气躔南吕。
圭币咸列，笙竽备举。
苾苾兰羞，芬芬桂醑。
式资宴贶，用调霜序。','',''),('quantangshi-02440','五郊乐章 白帝商音 舒和','魏徵','quantangshi','','卷3','璇仪气爽惊缇龠，玉吕灰飞含素商。
鸣鞞奏管芳羞荐，会舞安歌葆眊扬。','',''),('quantangshi-02441','五郊乐章 黑帝羽音','魏徵','quantangshi','','卷3','严冬季月，星回风厉。
享祀报功，方祚来岁。','',''),('quantangshi-02442','五郊乐章 黑帝羽音 肃和','魏徵','quantangshi','','卷3','律周玉琯，星回金度。
次极阳乌，纪穷阴兔。
火林霰雪，阳泉凝冱。
八蜡已登，三农息务。','',''),('quantangshi-02443','五郊乐章 黑帝羽音 雍和','魏徵','quantangshi','','卷3','阳月斯纪，应钟在候。
载絜牲牷，爰登俎豆。
既高既远，无声无臭。
静言格思，惟神保佑。','',''),('quantangshi-02444','五郊乐章 黑帝羽音 舒和','魏徵','quantangshi','','卷3','执龠持羽初终曲，朱干玉鏚始分行。
七德九功咸已畅，明灵降福具穰穰。','',''),('quantangshi-02445','享太庙乐章 永和','魏徵','quantangshi','','卷3','于穆烈祖，弘此丕基。
永言配命，子孙保之。
百神既洽，万国在兹。
是用孝享，神其格思。','',''),('quantangshi-02446','享太庙乐章 肃和','魏徵','quantangshi','','卷3','大哉至德，允兹明圣。
格于上下，聿遵诚敬。
嘉乐斯登，鸣球以咏。
神其降止，式隆景命。','',''),('quantangshi-02447','享太庙乐章 雍和','魏徵','quantangshi','','卷3','崇兹享祀，诚敬兼至。
乐以感灵，礼以昭事。
粢盛咸絜，牲牷孔备。
永言孝思，庶几不匮。','',''),('quantangshi-02448','享太庙乐章 长发舞','魏徵','quantangshi','','卷3','浚哲惟唐，长发其祥。
帝命斯佑，王业克昌。
配天载德，就日重光。
本枝百代，申锡无疆。','',''),('quantangshi-02449','享太庙乐章 大基舞','魏徵','quantangshi','','卷3','猗与祖业，皇矣帝先。
剪商德厚，封唐庆延。
在姬犹稷，方晋逾宣。
基我鼎运，于斯万年。','',''),('quantangshi-02450','享太庙乐章 大成舞','魏徵','quantangshi','','卷3','周穆王季，晋美帝文。
明明盛德，穆穆齐芬。
藏用四履，屈道参分。
铿锵钟石，载纪鸿勋。','',''),('quantangshi-02451','享太庙乐章 大明舞','魏徵','quantangshi','','卷3','五纪更运，三正逓升。
勋华既没，禹汤勃兴。
神武命代，灵睠是膺。
望云彰德，察纬告征。
上纽天维，下安地轴。
征师涿野，万国咸服。
偃伯灵台，九官允穆。
殊域委赆，怀生介福。
大礼既饰，大乐已和。
黑章扰囿，赤字浮河。
功宣载籍，德被咏歌。
克昌厥后，百禄是荷。','',''),('quantangshi-02452','享太庙乐章 寿和','魏徵','quantangshi','','卷3','八音斯奏，三献毕陈。
宝祚惟永，晖光日新。','',''),('quantangshi-02453','享太庙乐章 舒和','魏徵','quantangshi','','卷3','圣敬通神光七庙，灵心荐祚和万方。
严禋克配鸿基远，明德惟馨凤历昌。','',''),('quantangshi-02454','享太庙乐章 雍和','魏徵','quantangshi','','卷3','于穆清庙，聿修严祀。
四县载陈，三献斯止。
笾豆撤荐，人祗介祉。
神惟格思，锡祚不已。','',''),('quantangshi-02455','享太庙乐章 永和','魏徵','quantangshi','','卷3','肃肃清祀，烝烝孝思。
荐享昭备，虔恭在兹。
雍歌撤俎，祝嘏陈辞。
用光武志，永固鸿基。','',''),('quantangshi-02456','赋西汉','魏徵','quantangshi','','卷3','受降临轵道，争长趣鸿门。
驱传渭桥上，观兵细柳屯。
夜宴经柏谷，朝游出杜原。
终藉叔孙礼，方知皇帝尊。','',''),('quantangshi-02457','暮秋言怀','魏徵','quantangshi','','卷3','首夏别京辅，杪秋滞三河。
沈沈蓬莱阁，日夕乡思多。
霜剪凉阶蕙，风捎幽渚荷。
岁芳坐沦歇，感此式微歌。','',''),('quantangshi-02458','述怀','魏徵','quantangshi','','卷3','中原初逐鹿，投笔事戎轩。
纵横计不就，慷慨志犹存。
杖策谒天子，驱马出关门。
请缨系南粤，凭轼下东藩。
郁纡陟高岫，出没望平原。
古木鸣寒鸟，空山啼夜猿。
既伤千里目，还惊九折魂。
岂不惮艰险，深怀国士恩。
季布无二诺，侯嬴重一言。
人生感意气，功名谁复论。','',''),('quantangshi-02459','奉和正日临朝应诏','魏徵','quantangshi','','卷3','百灵侍轩后，万国会涂山。
岂如今睿哲，迈古独光前。
声教溢四海，朝宗引百川。
锵洋鸣玉佩，灼烁耀金蝉。
淑景辉雕辇，高旌扬翠烟。
庭实超王会，广乐盛钧天。
既欣东日户，复咏南风篇。
愿奉光华庆，从斯亿万年。','',''),('quantangshi-02460','祈谷乐章 肃和','褚亮','quantangshi','','卷3','履艮斯绳，居中体正。
龙运垂祉，昭符启圣。
式事严禋，聿怀嘉庆。
惟帝永锡，时皇休命。','',''),('quantangshi-02461','祈谷乐章 雍和','褚亮','quantangshi','','卷3','殷荐乘春，太坛临曙。
八簋盈和，六瑚登御。
嘉稷匪歆，德馨斯饫。
祝嘏无易，灵心有豫。','',''),('quantangshi-02462','祈谷乐章 舒和','褚亮','quantangshi','','卷3','玉帛牺牲申敬享，金丝鏚羽盛音容。
庶俾亿龄禔景福，长欣万宇洽时邕。','',''),('quantangshi-02463','明堂乐章 肃和','褚亮','quantangshi','','卷3','象天御宇，乘时布政。
严配申虔，宗禋展敬。
罇罍盈列，树羽交暎。
玉币通诚，祚隆皇圣。','',''),('quantangshi-02464','明堂乐章 雍和','褚亮','quantangshi','','卷3','八牖晨披，五精朝奠。
雾凝璇篚，风清金县。
神涤备全，明粢丰衍。
载[絜]彝俎，陈诚以荐。','',''),('quantangshi-02465','明堂乐章 舒和','褚亮','quantangshi','','卷3','御扆合宫承宝历，席图重馆奉明灵。
偃武修文九围泰，沈烽静柝八荒宁。','',''),('quantangshi-02466','雩祀乐章 肃和','褚亮','quantangshi','','卷3','朱鸟开辰，苍龙启暎。
大帝昭飨，羣生展敬。
礼备怀柔，功宣舞咏。
旬液应序，年祥叶庆。','',''),('quantangshi-02467','雩祀乐章 雍和','褚亮','quantangshi','','卷3','绀筵分彩，珤图吐绚。
凤管晨凝，云歌晓啭。
肃事苹藻，虔申桂奠。
百谷斯登，万箱攸荐。','',''),('quantangshi-02468','雩祀乐章 舒和','褚亮','quantangshi','','卷3','凤曲登歌调令序，龙雩集舞泛祥风。
彩旞云回昭睿德，朱干电发表神功。','',''),('quantangshi-02469','享先农乐章 诚和','褚亮','quantangshi','','卷3','粒食伊始，农之所先。
古今攸赖，是曰人天。
耕斯帝籍，播厥公田。
式崇明祀，神其福焉。','',''),('quantangshi-02470','享先农乐章 肃和','褚亮','quantangshi','','卷3','罇彝既列，瑚簋方荐。
歌工载登，币礼斯奠。
肃肃享祀，颙颙缨弁。
神之听之，福流寰县。','',''),('quantangshi-02471','享先农乐章 雍和','褚亮','quantangshi','','卷3','前夕视牲，质明奉俎。
沐芳整弁，其仪式序。
盛礼毕陈，嘉乐备举。
歆我懿德，非馨稷黍。','',''),('quantangshi-02472','享先农乐章 舒和','褚亮','quantangshi','','卷3','羽龠低昂文缀已，干戚蹈厉武行初。
望岁祈农神所听，延祥介福岂云虚。','',''),('quantangshi-02473','祭神州乐章 肃和','褚亮','quantangshi','','卷3','大矣坤仪，至哉神县。
包含日域，牢笼月竁。
露絜三清，风调六变。
皇祗届止，式歆恭荐。','',''),('quantangshi-02474','祭神州乐章 雍和','褚亮','quantangshi','','卷3','泰圻严享，阴郊展敬。
礼以导神，乐以和性。
黝牲在列，黄琮俯暎。
九土既平，万邦贻庆。','',''),('quantangshi-02475','祭神州乐章 舒和','褚亮','quantangshi','','卷3','坤道降祥和庶品，灵心载德厚羣生。
水土既调三极泰，文武毕备九区平。','',''),('quantangshi-02476','祭方丘乐章 顺和','褚亮','quantangshi','','卷3','万物资以化，交泰属升平。
易从业惟简，得一道斯宁。
具仪光玉帛，送舞变咸英。
黍稷良非贵，明德信惟馨。','',''),('quantangshi-02477','祭方丘乐章 肃和','褚亮','quantangshi','','卷3','至矣坤德，皇哉地祗。
开元统纽，合大承规。
九宫肃列，六典相仪。
永言配命，长保无亏。','',''),('quantangshi-02478','祭方丘乐章 雍和','褚亮','quantangshi','','卷3','柔而能方，直而能敬。
厚载以德，大亨以正。
有涤斯牷，有馨斯盛。
介兹景福，祚我休庆。','',''),('quantangshi-02479','祭方丘乐章 舒和','褚亮','quantangshi','','卷3','玉币牲牷分荐享，羽旄干鏚遰成容。
一德惟宁两仪泰，三材保合四时邕。','',''),('quantangshi-02480','祭方丘乐章 顺和','褚亮','quantangshi','','卷3','阴祗协赞，厚载方贞。
牲币具举，箫管备成。
其礼惟肃，其德惟明。
神之听矣，式鉴虔诚。','',''),('quantangshi-02481','临高台','褚亮','quantangshi','','卷3','高台暂俯临，飞翼耸轻音。
浮光随日度，漾影逐波深。
回瞰周平野，开怀畅远襟。
独此三休上，还伤千岁心。','',''),('quantangshi-02482','赋得蜀都','褚亮','quantangshi','','卷3','列宿光参井，分芒跨梁岷。
沈犀对江浦，驷马入城闉。
英图多霸迹，历选有名臣。
连骑簪缨满，含章词赋新。
得上仙槎路，无待访严遵。','',''),('quantangshi-02483','奉和咏日午','褚亮','quantangshi','','卷3','曦车日亭午，浮箭未移晖。
日光无落照，树影正中围。
草萎看稍靡，叶燥望疑稀。
昼寝慙经笥，暂解入朝衣。','',''),('quantangshi-02484','奉和望月应魏王教','褚亮','quantangshi','','卷3','层轩登皎月，流照满中天。
色共梁珠远，光随赵璧圆。
落影临秋扇，虚轮入夜弦。
所欣东馆里，预奉西园篇。','',''),('quantangshi-02485','咏花烛','褚亮','quantangshi','','卷3','兰迳香风满，梅梁暖日斜。
言是东方骑，来寻南陌车。
靥星临夜烛，眉月隐轻纱。
莫言春稍晚，自有镇开花。','',''),('quantangshi-02486','在陇头哭潘学士','褚亮','quantangshi','','卷3','陇底嗟长别，流襟一恸君。
何言幽咽所，更作死生分。
转蓬飞不息，悲松断更闻。
谁能驻征马，回首望孤坟。','',''),('quantangshi-02487','奉和禁苑饯别应令','褚亮','quantangshi','','卷3','大藩初锡瑞，出牧迩皇京。
暂以绿车重，言承朱传荣。
舒桃临远骑，垂柳映京营。
惠化宣千里，威风动百城。
禁籞芳嘉节，神襟饯送情。
金笳催别景，玉琯切离声。
野花开更落，山鸟哢还惊。
微臣夙多幸，薄宦奉储明。
钓台慙作赋，伊水滥闻笙。
怀德良知久，酬恩识命轻。','',''),('quantangshi-02488','和御史韦大夫喜霁之作','褚亮','quantangshi','','卷3','晴天度旅雁，斜影照残虹。
野净余烟尽，山明远色同。
沙平寒水落，叶脆晚枝空。
白简光朝幰，彤驺出禁中。
息驾游兰[坂]，雕文折桂丛。
无因轻羽扇，徒自仰仁风。','',''),('quantangshi-02489','晚别乐记室彦','褚亮','quantangshi','','卷3','穷途属岁晚，临水忽分悲。
抱影同为客，伤情共此时。
雾色侵虚牖，霜氛冷薄帷。
举袂惨将别，停杯怅不怡。
风严征雁远，雪暗去篷迟。','',''),('quantangshi-02490','伤始平李少府正己','褚亮','quantangshi','','卷3','劳息本相循，悲欢理自均。
谁能免玄夜，惜尔正青春。
迈德惟家宝，生才谅国珍。
高文缀翡翠，茂学掩麒麟。
述作纷无已，言谈妙入神。
断肠虽累月，分手未盈旬。
辅嗣俄长往，颜生即短辰。
声华满昭代，形影委穷尘。
禅草回中使，生刍引吊宾。
同游祕府日，方驾直城闉。
并拜黄图右，分曹清渭滨。
风期嵇吕好，存殁范张亲。
虚座怜王述，遗篇恸景纯。
精灵与毫翰，千祀寿何人。','',''),('quantangshi-02491','秋雁','褚亮','quantangshi','','卷3','日暮霜风急，羽翮转难任。
为有传书意，翩翩入上林。','',''),('quantangshi-02492','句','褚亮','quantangshi','','卷3','神羊既不触，夕鸟欲依人。','',''),('quantangshi-02493','冬日宴羣公于宅各赋一字得杯','于志寧','quantangshi','','卷3','陋巷朱轩拥，衡门缇骑来。
俱裁七步咏，同倾三雅杯。
色动迎春柳，花发犯寒梅。
宾筵未半醉，骊歌不用催。','',''),('quantangshi-02494','冬日宴于庶子宅各赋一字得趣','令狐德棻','quantangshi','','卷3','高门聊命赏，羣英于此遇。
放旷山水情，留连文酒趣。
夕烟起林兰，霜枝殒庭树。
落景虽已倾，归轩幸能驻。','',''),('quantangshi-02495','冬日宴于庶子宅各赋一字得色','封行高','quantangshi','','卷3','夫君敬爱重，欢言情不极。
雅引发清音，丽藻穷雕饰。
水结曲池冰，日暖平亭色。
引满既杯倾，终之以弁侧。','',''),('quantangshi-02496','冬日宴于庶子宅各赋一字得节','杜正倫','quantangshi','','卷3','李门余妄进，徐榻君恒设。
清论畅玄言，雅琴飞白雪。
寒云暧落景，朔风凄暮节。
方欣投辖情，且驻当归别。','',''),('quantangshi-02497','玄武门侍宴','杜正倫','quantangshi','','卷3','大君端扆暇，睿赏狎林泉。
开轩临禁籞，藉野列芳筵。
参差歌管扬，容裔羽旗悬。
玉池流若醴，云阁聚非烟。
湛露曦尧日，熏风入舜弦。
大德侔玄造，微物荷陶甄。
谬陪瑶水宴，仍厕栢梁篇。
阚名徒上月，邹辩讵谈天。
既喜光华旦，还伤迟暮年。
犹冀升中日，簪裾奉肃然。','',''),('quantangshi-02498','奉和正日临朝','岑文本','quantangshi','','卷3','时雍表昌运，日正叶灵符。
德兼三代礼，功包四海图。
逾沙纷在列，执玉俨相趋。
清跸喧辇道，张乐骇天衢。
拂霓九旗暎，仪凤八音殊。
佳气浮仙掌，熏风绕帝梧。
天文光七政，皇恩被九区。
方陪瘗玉礼，珥笔岱山隅。','',''),('quantangshi-02499','奉述飞白书势','岑文本','quantangshi','','卷3','六文开玉篆，八体曜银书。
飞毫列锦绣，拂素起龙鱼。
凤举崩云绝，鸾惊游雾疎。
别有临池草，恩霑垂露余。','',''),('quantangshi-02500','冬日宴于庶子宅各赋一字得平','岑文本','quantangshi','','卷3','金兰笃惠好，尊酒畅生平。
既欣投辖赏，暂缓望乡情。
爱景含霜晦，落照带风轻。
于兹欢宴洽，宠辱讵相惊。','',''),('quantangshi-02501','安德山池宴集','岑文本','quantangshi','','卷3','甲第多清赏，芳辰命羽巵。
书帷通竹径，琴台枕槿篱。
池疑夜壑徙，山似郁洲移。
雕楹网萝薜，激濑合埙篪。
鸟戏翻新叶，鱼跃动清漪。
自得淹留趣，宁劳攀桂枝。','',''),('quantangshi-02502','安德山池宴集','劉洎','quantangshi','','卷3','平阳擅歌舞，金谷盛招携。
何如兼往烈，会赏叶幽栖。
已均朝野致，还欣物我齐。
春晚花方落，兰深径渐迷。
蒲新节尚短，荷小盖犹低。
无劳拂长袖，直待夜乌啼。','',''),('quantangshi-02503','安德山池宴集','褚遂良','quantangshi','','卷3','伏枥丹霞外，遮园焕景舒。
行云泛层阜，蔽月下清渠。
亭中奏赵瑟，席上舞燕裾。
花落春莺晚，风光夏叶初。
良朋比兰蕙，雕藻迈琼琚。
独有狂歌客，来承欢宴余。','',''),('quantangshi-02504','安德山池宴集','楊續','quantangshi','','卷3','狭斜通凤阙，上路抵青楼。
簪绂启宾馆，轩盖临御沟。
西城多妙舞，主第出名讴。
列峰疑宿雾，疏壑拟藏舟。
花蝶辞风影，苹藻含春流。
酒阑高宴毕，自反山之幽。','',''),('quantangshi-02505','游清都观寻沈道士得仙字','劉孝孫','quantangshi','','卷3','纷吾因暇豫，行乐极留连。
寻真谒紫府，披雾觌青天。
缅怀金阙外，遐想玉京前。
飞轩俯松柏，抗殿接云烟。
滔滔清夏景，嘒嘒早秋蝉。
横琴对危石，酌醴临寒泉。
聊祛尘俗累，宁希龟鹤年。
无劳生羽翼，自可狎神仙。','',''),('quantangshi-02506','早发成皐望河','劉孝孫','quantangshi','','卷3','清晨发岩邑，车马走轘辕。
回瞰黄河上，惝怳屡飞魂。
鸿流遵积石，惊浪下龙门。
仙槎不辨处，沈璧想犹存。
远近洲渚出，飒沓凫雁喧。
怀古空延伫，叹逝将何言。','',''),('quantangshi-02507','游灵山寺','劉孝孫','quantangshi','','卷3','吾王游胜地，骖驾历祗园。
临风画角愤，耀日采旗翻。
永怀筌了义，寂念启玄门。
深溪穷地脉，高嶂接云根。
信美谐心赏，幽邃且攀援。
曳裾欣扈从，方悟屏尘喧。','',''),('quantangshi-02508','冬日宴于庶子宅各赋一字得鲜','劉孝孫','quantangshi','','卷3','解襟游胜地，披云促宴筵。
清文振笔妙，高论写言泉。
冻柳含风落，寒梅照日鲜。
骊歌虽欲奏，归驾且留连。','',''),('quantangshi-02509','送刘散员同赋陈思王诗游人久不归','劉孝孫','quantangshi','','卷3','乡关渺天末，引领怅怀归。
羁旅久淫滞，物色屡芳菲。
稍觉私意尽，行看蓬鬓衰。
如何千里外，伫立霑裳衣。','',''),('quantangshi-02510','咏笛','劉孝孫','quantangshi','','卷3','凉秋夜笛鸣，流风韵九成。
调高时慷慨，曲变或凄清。
征客怀离绪，邻人思旧情。
幸以知音顾，千载有奇声。','',''),('quantangshi-02511','赋得春莺送友人','劉孝孫','quantangshi','','卷3','流莺拂绣羽，二月上林期。
待雪消金禁，衔花向玉墀。
翅掩飞燕舞，啼恼婕妤悲。
料取金闺意，因君问所思。','',''),('quantangshi-02512','巫山高','陸敬','quantangshi','','卷3','巫岫郁岧嶤，高高入紫霄。
白云抱危石，玄猨挂迥条。
悬崖激巨浪，脆叶陨惊飙。
别有阳台处，风雨共飘颻。','',''),('quantangshi-02513','游隋故都','陸敬','quantangshi','','卷3','洛城聊顾步，长想遂留连。
水鬬宫初毁，风变鼎将迁。
皐陶德不建，汾隅祀忽焉。
宗祊旷无象，声朔缅谁传。
枌榆何冷落，禾黍郁芊緜。
悲歌尽商颂，太息悯周篇。
来苏伫圣德，濡足乃乘干。
正始淳风被，人劳用息肩。
舞象文思泽，偃伯武功宣。
则百昌厥后，于万永斯年。
兹辰素商节，灰管变星躔。
平原悴秋草，乔木敛寒烟。
翻黄坠疎叶，凝翠积高天。
参差海曲雁，寂寞柳门蝉。
兴悼今如此，悲愁复在旃。
彷徨不忍去，杖策屡回邅。','',''),('quantangshi-02514','游清都观寻沈道士得都字','陸敬','quantangshi','','卷3','聊排灵琐闼，徐步入清都。
青溪冥寂士，思玄徇道枢。
十芒生药笥，七焰发丹炉。
缥袠桐君录，朱书王母符。
宫槐散绿穗，日槿落青柎。
矫翰雷门鹤，飞来叶县凫。
凌风自可御，安事迫中区。
方追羽化侣，从此得玄珠。','',''),('quantangshi-02515','七夕赋咏成篇','陸敬','quantangshi','','卷3','夙驾鸣鸾启阊阖，霓裳遥裔俨天津。
五明霜纨开羽扇，百和香车动画轮。
婉娈夜分能几许，靓妆冶服为谁新。
片时欢娱自有极，已复长望隔年人。','',''),('quantangshi-02516','七夕赋咏成篇','沈叔安','quantangshi','','卷3','皎皎宵月丽秋光，耿耿天津横复长。
停梭且复留残纬，拂镜及早更新妆。
彩凤齐驾初成辇，雕鹊填河已作梁。
虽喜得同今夜枕，还愁重空明日牀。','',''),('quantangshi-02517','七夕赋咏成篇','何仲宣','quantangshi','','卷3','日日思归勤理鬓，朝朝伫望嬾调梭。
凌风宝扇遥临月，映水仙车远渡河。
历历珠星疑拖佩，冉冉云衣似曳罗。
通宵道意终无尽，向晓离愁已复多。','',''),('quantangshi-02518','游清都观寻沈道士得芳字','趙中虛','quantangshi','','卷3','青溪阻千仞，姑射藐汾阳。
未若游兹境，探玄众妙场。
鹤来疑羽客，云泛似霓裳。
寓目虽灵宇，游神乃帝乡。
道存真理得，心灰俗累忘。
烟霞凝抗殿，松桂肃长廊。
早蝉清暮响，崇兰散晚芳。
即此翔寥廓，非复控榆枋。','',''),('quantangshi-02519','送刘散员赋得陈思王诗明月照高楼','楊濬','quantangshi','','卷3','高楼一何绮，素月复流明。
重轩望不极，余晖揽讵盈。
镜华当牖照，钩影隔帘生。
逆愁异尊酒，对此难为情。','',''),('quantangshi-02520','陇头水','楊師道','quantangshi','','卷3','陇头秋月明，陇水带关城。
笳添离别曲，风送断肠声。
映雪峰犹暗，乘冰马屡惊。
雾中寒雁至，沙上转蓬轻。
天山传羽檄，汉地急征兵。
阵开都护道，劒聚伏波营。
于兹觉无渡，方共濯胡缨。','',''),('quantangshi-02521','中书寓直咏雨简褚起居上官学士','楊師道','quantangshi','','卷3','云暗苍龙阙，沈沈殊未开。
窗临凤凰沼，飒飒雨声来。
电影入飞阁，风威凌吹台。
长檐响奔溜，清簟肃浮埃。
早荷叶稍没，新篁枝半摧。
兹晨怅多绪，怀友自难裁。
况复重城内，日暮独裴回。
玉阶良史笔，金马掞天才。
高甍通散骑，复道驾蓬莱。
思君赠桃李，于此冀琼瓌。','',''),('quantangshi-02522','阙题','楊師道','quantangshi','','卷3','汉家伊洛九重城，御路浮桥万里平。
桂户雕梁连绮翼，虹梁绣柱映丹楹。
朝光欲动千门曙，丽日初照百花明。
燕赵蛾眉旧倾国，楚宫腰细本传名。
二月桑津期结伴，三春淇水逐关情。
兰丛有意飞双蝶，柳叶无趣隐啼莺。
扇里细妆将夜并，风前独舞共花荣。
两鬟百万谁论价，一笑千金判是轻。
不为披图来侍寝，非因主第奉身迎。
羊车讵畏青门闭，兔月今宵照后庭。','',''),('quantangshi-02523','初秋夜坐应诏','楊師道','quantangshi','','卷3','玉琯凉初应，金壶夜渐阑。
沧池流稍洁，仙掌露方漙。
雁声风处断，树影月中寒。
爽气长空净，高吟觉思宽。','',''),('quantangshi-02524','赋终南山用风字韵应诏','楊師道','quantangshi','','卷3','眷言怀隐逸，辍驾践幽丛。
白云飞夏雨，碧岭横春虹。
草绿长杨路，花疎五柞宫。
登临日将晚，兰桂起香风。','',''),('quantangshi-02525','咏饮马应诏','楊師道','quantangshi','','卷3','清晨控龙马，弄影出花林。
躞蹀依春涧，联翩度碧浔。
苔流染丝络，水洁写雕簪。
一御瑶池驾，讵忆长城阴。','',''),('quantangshi-02526','初宵看婚','楊師道','quantangshi','','卷3','洛城花烛动，戚里画新蛾。
隐扇羞应惯，含情愁已多。
轻啼湿红粉，微睇转横波。
更笑巫山曲，空传暮雨过。','',''),('quantangshi-02527','侍宴赋得起坐弹鸣琴二首 一','楊師道','quantangshi','','卷3','北林鹊夜飞，南轩月初进。
调弦发清征，荡心祛褊吝。
变作离鸿声，还入思归引。
长叹未终极，秋风飘素鬓。','',''),('quantangshi-02528','侍宴赋得起坐弹鸣琴二首 二','楊師道','quantangshi','','卷3','丝传园客意，曲奏楚妃情。
罕有知音者，空劳流水声。','',''),('quantangshi-02529','咏琴','楊師道','quantangshi','','卷3','久擅龙门质，孤竦峄阳名。
齐娥初发弄，赵女正调声。
嘉客勿遽反，繁弦曲未成。','',''),('quantangshi-02530','咏笙','楊師道','quantangshi','','卷3','短长插凤翼，洪细摹鸾音。
能令楚妃叹，复使荆王吟。
切切孤竹管，来应云和琴。','',''),('quantangshi-02531','应诏咏巢乌','楊師道','quantangshi','','卷3','桂树春晖满，巢乌刷羽仪。
朝飞丽城上，夜宿碧林陲。
背风藏密叶，向日逐疎枝。
仰德还能哺，依仁遂可窥。
惊鸣雕辇侧，王吉自相知。','',''),('quantangshi-02532','奉和夏日晚景应诏','楊師道','quantangshi','','卷3','辇路夹垂杨，离宫通建章。
日落横峰影，云归起夕凉。
雕轩动流吹，羽盖息回塘。
剃草生还绿，残花落尚香。
青岩类姑射，碧涧似汾阳。
幸属无为日，欢娱尚未央。','',''),('quantangshi-02533','奉和圣制春日望海','楊師道','quantangshi','','卷3','春山临渤海，征旅辍晨装。
回瞰卢龙塞，斜瞻肃慎乡。
洪波回地轴，孤屿映云光。
落日惊涛上，浮天骇浪长。
仙台隐螭驾，水府泛鼋梁。
碣石朝烟灭，之罘归雁翔。
北巡非汉后，东幸异秦皇。
搴旗羽林客，跋距少年场。
龙击驱辽水，鹏飞出带方。
将举青丘缴，安访白霓裳。','',''),('quantangshi-02534','春朝闲步','楊師道','quantangshi','','卷3','休沐乘闲豫，清晨步北林。
池塘藉芳草，兰芷袭幽衿。
雾中分晓日，花里弄春禽。
野迳香恒满，山阶笋屡侵。
何须命轻盖，桃李自成阴。','',''),('quantangshi-02535','还山宅','楊師道','quantangshi','','卷3','暮春还旧岭，徙倚翫年华。
芳草无行迳，空山正落花。
垂藤扫幽石，卧柳碍浮槎。
鸟散茅檐静，云披涧户斜。
依然此泉路，犹是昔烟霞。','',''),('quantangshi-02536','咏马','楊師道','quantangshi','','卷3','宝马权奇出未央，雕鞍照曜紫金装。
春草初生驰上苑，秋风欲动戏长杨。
鸣珂屡度章台侧，细蹀经向濯龙傍。
徒令汉将连年去，宛城今已献名王。','',''),('quantangshi-02537','奉和咏弓','楊師道','quantangshi','','卷3','霜重麟胶劲，风高月影圆。
乌飞随帝辇，雁落逐鸣弦。','',''),('quantangshi-02538','咏砚','楊師道','quantangshi','','卷3','圆池类璧水，轻翰染烟华。
将军欲定远，见弃不应赊。','',''),('quantangshi-02539','奉和正日临朝应诏','楊師道','quantangshi','','卷3','皇猷被寰宇，端扆属元辰。
九重丽天邑，千门临上春。','',''),('quantangshi-02540','咏舞','楊師道','quantangshi','','卷3','二八如回雪，三春类早花。
分行向烛转，一种逐风斜。','',''),('quantangshi-02541','奉和执契静三边应诏','許敬宗','quantangshi','','卷3','玄塞隔阴戎，朱光分昧谷。
地游穷北际，云崖尽西陆。
星次绝轩台，风衢乖禹服。
寰区无所外，天覆今咸育。
窜苗犹有孽，戮负自贻辜。
疎网妖鲵漏，盘薮怪禽逋。
髯飞尚假息，乳视暂稽诛。
干灵振玉弩，神略运璇枢。
日羽廓游气，天阵清华野。
升晅光西夜，驰恩溢东泻。
挥袂静昆炎，开关纳流赭。
锦轺凌右地，华缨羇大夏。
清台映罗叶，玄沚控瑶池。
驼鹿输珍贶，树羽飨来仪。
辍肴观化宇，栖籞萃条支。
熏风交阆阙，就日泛蒙漪。
充庭延饮至，绚简敷春藻。
迎姜已创图，命力方论道。
昔托游河乘，再备商山皓。
欣逢德化流，思效登封草。','',''),('quantangshi-02542','奉和行经破薛举战地应制','許敬宗','quantangshi','','卷3','混元分大象，长策挫修鲸。
于斯建宸极，由此创鸿名。
一戎干宇泰，千祀德流清。
垂衣凝庶绩，端拱铸羣生。
复整瑶池驾，还临官渡营。
周游寻曩迹，旷望动天情。
帷宫面丹浦，帐殿瞩宛城。
虏场栖九穗，前歌被六英。
战地甘泉涌，阵处景云生。
普天霑凯泽，相携欣颂平。','',''),('quantangshi-02543','奉和入潼关','許敬宗','quantangshi','','卷3','曦驭循黄道，星陈引翠旗。
济潼纡万乘，临河耀六师。
前旌弥陆海，后骑发通伊。
势逾回地轴，威盛转天机。
是节岁穷纪，关树荡凉飔。
仙露含灵掌，瑞鼎照川湄。
冲襟赏临睨，高咏入京畿。','',''),('quantangshi-02544','奉和春日望海','許敬宗','quantangshi','','卷3','韩夷愆奉賮，凭险乱天常。
乃神弘庙畧，横海剪吞航。
电野清玄菟，腾笳振白狼。
连云飞巨舰，编石架浮梁。
周游临大壑，降望极遐荒。
桃门通山拚，蓬渚降霓裳。
惊涛含蜃阙，骇浪掩晨光。
青丘绚春组，丹谷耀华桑。
长驱七萃卒，成功百战场。
俄且旋戎路，饮至肃岩廊。','',''),('quantangshi-02545','奉和元日应制','許敬宗','quantangshi','','卷3','天正开初节，日观上重轮。
百灵滋景祚，万玉庆惟新。
待旦敷玄造，韬旒御紫宸。
武帐临光宅，文卫象钩陈。
广庭扬九奏，大帛丽三辰。
发生同化育，播物体陶钧。
霜空澄晓气，霞景莹芳春。
德辉覃率[土]，相贺奉还淳。','',''),('quantangshi-02546','奉和初春登楼即目应诏','許敬宗','quantangshi','','卷3','旭日临重壁，天眷极中京。
春晖发芳甸，佳气满层城。
去鸟随看没，来云逐望生。
歌里非烟扬，琴上凯风清。
文波浮镂槛，摛景焕雕楹。
璇玑体宽政，隆栋象端衡。
创规虽有作，凝拱遂无营。
沐恩空改鬓，将何谢夏成。','',''),('quantangshi-02547','奉和秋日即目应制','許敬宗','quantangshi','','卷3','玉露交珠网，金风度绮钱。
昆明秋景淡，岐岫落霞然。
辞燕归寒海，来鸿出远天。
叶动罗帷扬，花映绣裳鲜。
规空升暗魄，笼野散轻烟。
鹊度林光起，凫没水文圆。
无机络秋纬，如管奏寒蝉。
乃睠情何极，宸襟豫有旃。','',''),('quantangshi-02548','奉和秋暮言志应制','許敬宗','quantangshi','','卷3','秋深桂初发，寒窗菊余菲。
波拥羣凫至，秋飘朔雁归。
月荚生还落，云枝似复非。
凝宸阅栖亩，观文伫少微。
圣敬韬前哲，先天谅不违。','',''),('quantangshi-02549','奉和喜雪应制','許敬宗','quantangshi','','卷3','嵰州表奇贶，閟竹应遐巡。
何如御京洛，流霰下天津。
忽若琼林曙，俄同李径春。
姑峯映仙质，郢路杂歌尘。
伏槛观花瑞，称觞庆冬积。
飘河共泻银，委树还重璧。
连山分掩翠，绵霄远韬碧。
千里徧浮空，五轫咸沦迹。
机前辉裂素，池上伴凌波。
腾华承玉宇，凝照混金娥。
是日松筠性，欣奉柏梁歌。','',''),('quantangshi-02550','奉和登陕州城楼应制','許敬宗','quantangshi','','卷3','挹河澄绿宇，御沟映朱宫。
辰旗翻丽景，星盖曳雕虹。
学嚬齐柳嫩，妍笑发春藂。
锦鳞文碧浪，绣羽绚青空。
眷念三阶静，遥想二南风。','',''),('quantangshi-02551','游清都观寻沈道士得清字','許敬宗','quantangshi','','卷3','幽人蹈箕颍，方士访蓬瀛。
岂若逢真气，齐契体无名。
既诠众妙理，聊畅远游情。
纵心驰贝阙，怡神想玉京。
或命余杭酒，时听洛滨笙。
风衢通阆苑，星使下层城。
蕙帐晨飙动，芝房夕露清。
方叶栖迟趣，于此听钟声。','',''),('quantangshi-02552','奉和七夕宴悬圃应制二首 一','許敬宗','quantangshi','','卷3','牛闺临浅汉，鸾驷涉秋河。
两怀萦别绪，一宿庆停梭。
星模铅里靥，月写黛中蛾。
奈许今宵度，长婴离恨多。','',''),('quantangshi-02553','奉和七夕宴悬圃应制二首 二','許敬宗','quantangshi','','卷3','婺闺期今夕，娥轮泛浅潢。
迎秋伴暮雨，待暝合神光。
荐寝低云鬓，呈态解霓裳。
喜中愁漏促，别后怨天长。','',''),('quantangshi-02554','奉和仪鸾殿早秋应制','許敬宗','quantangshi','','卷3','睿想追嘉豫，临轩御早秋。
斜晖丽粉壁，清吹肃朱楼。
高殿凝阴满，雕窗艳曲流。
小臣参广宴，大造谅难酬。','',''),('quantangshi-02555','奉和咏雨应诏','許敬宗','quantangshi','','卷3','舞商初赴节，湘燕远迎秋。
飘丝交殿网，乱滴起池沤。
激溜分龙阙，斜飞洒凤楼。
崇朝方浃宇，宸盼俯凝旒。','',''),('quantangshi-02556','奉和过慈恩寺应制','許敬宗','quantangshi','','卷3','凤阙隣金地，龙旗拂宝台。
云楣将叶并，风牖送花来。
月宫清晚桂，虹梁绚早梅。
梵境留宸瞩，掞发丽天才。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-02557','冬日宴于庶子宅各赋一字得归','許敬宗','quantangshi','','卷3','倦游嗟落拓，短翮慕追飞。
周醪忽同醉，牙弦乃共挥。
油云澹寒色，落景霭霜霏。
累日方投分，兹夕谅无归。','',''),('quantangshi-02558','送刘散员同赋得陈思王诗山树郁苍苍','許敬宗','quantangshi','','卷3','乔木托危岫，积翠绕连冈。
叶疎犹漏影，花少未流芳。
风来闻肃肃，雾罢见苍苍。
此中饯行迈，不异上河梁。','',''),('quantangshi-02559','侍宴莎册宫应制得情字','許敬宗','quantangshi','','卷3','三星希曙景，万骑翊天行。
葆羽翻风队，腾吹掩山楹。
暖日晨光浅，飞烟旦彩轻。
塞寒桃变色，冰断箭流声。
渐奏长安道，神皐动睿情。','',''),('quantangshi-02560','奉和过旧宅应制','許敬宗','quantangshi','','卷3','飞云临紫极，出震表青光。
自尔家寰海，今兹返帝乡。
情深感代国，乐甚宴谯方。
白水浮佳气，黄星聚太常。
岐凤鸣层阁，酆雀贺雕梁。
桂山犹总翠，蘅薄尚流芳。
攀鳞有遗皓，沐德拚称觞。','',''),('quantangshi-02561','奉和宴中山应制','許敬宗','quantangshi','','卷3','飞云旋碧海，解网宥青丘。
养贤停八骏，观风驻五牛。
张乐临尧野，扬麾历舜州。
中山献仙酤，赵媛发清讴。
塞门朱雁入，郊薮紫麟游。
一举氛霓静，千龄德化流。','',''),('quantangshi-02562','奉和圣制登三台言志应制','許敬宗','quantangshi','','卷3','中天表云榭，载极耸昆楼。
圣作规玄造，轩阿复聿修。
高门符令节，形胜总神州。
企翼抟禽萃，飞甍燕雀游。
缀星罗百拱，缘汉转三休。
旦云生玉舃，初月上银钩。
妙管含秦凤，仙姿丽斗牛。
形言防处逸，粹藻发嘉猷。
荷生无以谢，尽瘁竟何酬。','',''),('quantangshi-02563','安德山池宴集','許敬宗','quantangshi','','卷3','戚里欢娱地，园林瞩望新。
山庭带芳杜，歌吹叶阳春。
台榭疑巫峡，荷蕖似洛滨。
风花萦少女，虹梁聚美人。
宴游穷至乐，谈笑毕良辰。
独叹高阳晚，归路不知津。','',''),('quantangshi-02564','奉和圣制送来济应制','許敬宗','quantangshi','','卷3','万乘腾镳警岐路，百壶供帐饯离宫。
御沟分水声难绝，广宴当歌曲易终。
兴言共伤千里道，俯迹聊示五情同。
良哉既深留帝念，沃化方有赞天聪。','',''),('quantangshi-02565','七夕赋咏成篇','許敬宗','quantangshi','','卷3','一年抱怨嗟长别，七夕含态始言归。
飘飘罗袜光天步，灼灼新妆鉴月辉。
情催巧笑开星靥，不惜呈露解云衣。
所叹却随更漏尽，掩泣还弄昨宵机。','',''),('quantangshi-02566','拟江令于长安归扬州九日赋','許敬宗','quantangshi','','卷3','本逐征鸿去，还随落叶来。
菊花应未满，请待诗人开。','',''),('quantangshi-02567','拟江令于长安归扬州九日赋','許敬宗','quantangshi','','卷3','游人倦蓬转，乡思逐雁来。
偏想临潭菊，芳蘂对谁开。','',''),('quantangshi-02568','和边城秋气早','李義府','quantangshi','','卷3','金微凝素节，玉律应清葭。
边马秋声急，征鸿晓阵斜。
关树凋凉叶，塞草落寒花。
雾暗长川景，云昏大漠沙。
溪深路难越，川平望超忽。
极望断烟飘，遥落惊蓬没。
霜结龙城吹，水照龟林月。
日色夏犹冷，霜华春未歇。
睿作高紫宸，分明映玄阙。','',''),('quantangshi-02569','招谕有怀赠同行人','李義府','quantangshi','','卷3','远游冒艰阻，深入劳存谕。
春去辞国门，秋还在边戍。
轩车行未返，节序催难驻。
陌上悲转蓬，园中想芳树。
蜀山自纷纠，岷水恒奔注。
临泛多苦怀，登攀寡欢趣。
永夕飞淫雨，崇朝蒸毒雾。
不求绥岭桃，宁美邛乡蒟。
白狼行欲静，骢马何常驱。
愿接轺斾尘，联翩东北骛。','',''),('quantangshi-02570','宣正殿芝草','李義府','quantangshi','','卷3','明王敦孝感，宝殿秀灵芝。
色带朝阳净，光涵雨露滋。
且标宣德重，更引国恩施。
圣祚今无限，微臣乐未移。','',''),('quantangshi-02571','咏鹦鹉','李義府','quantangshi','','卷3','牵弋辞重海，触网去层峦。
戢翼雕笼际，延思彩霞端。
慕侣朝声切，离羣夜影寒。
能言殊可贵，相助忆长安。','',''),('quantangshi-02572','在巂州遥敍封禅','李義府','quantangshi','','卷3','天齐标巨镇，日观启崇朝。
岧嶤临渤澥，隐嶙控河沂。
眺迥分吴乘，凌高属汉祠。
建岳诚为长，升功谅在兹。
帝猷符广运，玄范畅文思。
飞声总地络，腾化抚干维。
瑞策开珍凤，祯图荐宝龟。
创封超昔夏，修禅掩前姬。
东后方肆觐，西都导六师。
肃驾移星苑，扬罕驭风司。
沸鼓喧平陆，凝跸静通逵。
汶阳驰月羽，蒙阴警电麾。
岩花飘曙辇，峰叶荡春旗。
石闾环藻卫，金坛映黼帷。
仙阶溢祕秬，灵检耀祥芝。
张乐分韶濩，观礼纵华夷。
佳气浮丹谷，荣光泛绿坻。
三始贻遐贶，万岁受重厘。
菲质陶恩奖，趋迹奉轩墀。
触网沦幽裔，乘徼限明时。
周南昔已叹，邛西今复悲。','',''),('quantangshi-02573','堂堂词二首 一','李義府','quantangshi','','卷3','镂月成歌扇，裁云作舞衣。
自怜回雪影，好取洛川归。','',''),('quantangshi-02574','堂堂词二首 二','李義府','quantangshi','','卷3','嬾整鸳鸯被，羞褰玳瑁牀。
春风别有意，密处也寻香。','',''),('quantangshi-02575','咏乌','李義府','quantangshi','','卷3','日里扬朝彩，琴中伴夜啼。
上林如许树，不借一枝栖。','',''),('quantangshi-02576','从军行二首 一','虞世南','quantangshi','','卷3','涂山烽候惊，弭节度龙城。
冀马楼兰将，燕犀上谷兵。
劒寒花不落，弓晓月逾明。
凛凛严霜节，冰壮黄河绝。
蔽日卷征蓬，浮天散飞雪。
全兵值月满，精骑乘胶折。
结发早驱驰，辛苦事旌麾。
马冻重关冷，轮摧九折危。
独有西山将，年年属数奇。','',''),('quantangshi-02577','从军行二首 二','虞世南','quantangshi','','卷3','烽火发金微，连营出武威。
孤城塞云起，绝阵虏尘飞。
侠客吸龙劒，恶少缦胡衣。
朝摩骨都垒，夜解谷蠡围。
萧关远无极，蒲海广难依。
沙磴离旌断，晴川候马归。
交河梁已毕，燕山斾欲挥。
方知万里相，侯服见光辉。','',''),('quantangshi-02578','拟饮马长城窟','虞世南','quantangshi','','卷3','驰马渡河干，流深马渡难。
前逢锦车使，都护在楼兰。
轻骑犹衔勒，疑兵尚解鞍。
温池下绝涧，栈道接危峦。
拓地勋未赏，亡城律岂宽。
有月关犹暗，经春陇尚寒。
云昏无复影，冰合不闻湍。
怀君不可遇，聊持报一飱。','',''),('quantangshi-02579','出塞','虞世南','quantangshi','','卷3','上将三略远，元戎九命尊。
缅怀古人节，思酬明主恩。
山西多勇气，塞北有游魂。
扬桴上陇坂，勒骑下平原。
誓将绝沙漠，悠然去玉门。
轻赍不遑舍，惊策骛戎轩。
凛凛边风急，萧萧征马烦。
雪暗天山道，冰塞交河源。
雾锋黯无色，霜旗冻不翻。
耿介倚长劒，日落风尘昏。','',''),('quantangshi-02580','结客少年场行','虞世南','quantangshi','','卷3','韩魏多奇节，倜傥遗声利。
共矜然诺心，各负纵横志。
结交一言重，相期千里至。
绿沈明月弦，金络浮云辔。
吹箫入吴市，击筑游燕肆。
寻源博望侯，结客远相求。
少年怀一顾，长驱背陇头。
焰焰戈霜动，耿耿劒虹浮。
天山冬夏雪，交河南北流。
云起龙沙暗，木落雁门秋。
轻生殉知己，非是为身谋。','',''),('quantangshi-02581','怨歌行','虞世南','quantangshi','','卷3','紫殿秋风冷，雕甍落日沈。
裁纨凄断曲，织素别离心。
掖庭羞改画，长门不惜金。
宠移恩稍薄，情疎恨转深。
香销翠羽帐，弦断凤皇琴。
镜前红粉歇，阶上绿苔侵。
谁言掩歌扇，翻作白头吟。','',''),('quantangshi-02582','中妇织流黄','虞世南','quantangshi','','卷3','寒闺织素锦，含怨敛双蛾。
综新交缕澁，经脆断丝多。
衣香逐举袖，钏动应鸣梭。
还恐裁缝罢，无信达交河。','',''),('quantangshi-02583','门有车马客','虞世南','quantangshi','','卷3','陈遵重交结，田蚡擅豪华。
曲台临上路，高轩抵狭斜。
赭汗千金马，绣轴五香车。
白鹤随飞盖，朱鹭入鸣笳。
夏莲开劒水，春桃发绶花。
高谈辩飞兔，摛藻握灵蛇。
逢恩出毛羽，失路委泥沙。
暧暧风烟晚，路长归骑远。
日斜青琐第，尘飞金谷苑。
危弦促柱奏巴渝，遗簪堕珥解罗襦。
如何守直道，翻使谷名愚。','',''),('quantangshi-02584','飞来双白鹤','虞世南','quantangshi','','卷3','飞来双白鹤，奋翼远凌烟。
俱栖集紫盖，一举背青田。
扬影过伊洛，流声入管弦。
鸣羣倒景外，刷羽阆风前。
暎海疑浮雪，拂涧泻飞泉。
燕雀宁知去，蜉蝣不识还。
何言别俦侣，从此间山川。
顾步已相失，裴回各自怜。
危心犹警露，哀响讵闻天。
无因振六翮，轻举复随仙。','',''),('quantangshi-02585','奉和幽山雨后应令','虞世南','quantangshi','','卷3','肃城邻上苑，黄山迩桂宫。
雨歇连峰翠，烟开竟野通。
排虚翔戏鸟，跨水落长虹。
日下林全暗，云收岭半空。
山泉鸣石涧，地籁响岩风。','',''),('quantangshi-02586','赋得吴都','虞世南','quantangshi','','卷3','画野通淮泗，星躔应斗牛。
玉牒宏图表，黄旗美气浮。
三分开霸业，万里宅神州。
高台临茂苑，飞阁跨澄流。
江涛如素盖，海气似朱楼。
吴趋自有乐，还似镜中游。','',''),('quantangshi-02587','赋得慎罚','虞世南','quantangshi','','卷3','帝图光往册，上德表鸿名。
道冠二仪始，风高三代英。
乐和知化洽，讼息表刑清。
罚轻犹在念，忽喜尚留情。
明慎全无枉，哀矜在好生。
五疵过亦察，二辟理弥精。
幪巾示廉耻，嘉石务详平。
每削繁苛性，常深恻隐诚。
政宽思济猛，疑罪必从轻。
于张惩不滥，陈郭宪无倾。
刑措谅斯在，欢然仰颂声。','',''),('quantangshi-02588','奉和咏日午','虞世南','quantangshi','','卷3','高天净秋色，长汉转曦车。
玉树阴初正，桐圭影未斜。
翠盖飞圆彩，明镜发轻花。
再中良表瑞，共仰璧晖赊。','',''),('quantangshi-02589','发营逢雨应诏','虞世南','quantangshi','','卷3','豫游欣胜地，皇泽乃先天。
油云阴御道，膏雨润公田。
陇麦霑逾翠，山花湿更然。
稼穑良所重，方复悦丰年。','',''),('quantangshi-02590','赋得临池竹应制','虞世南','quantangshi','','卷3','葱翠梢云质，垂彩暎清池。
波泛含风影，流摇防露枝。
龙鳞漾嶰谷，凤翅拂涟漪。
欲识凌冬性，唯有岁寒知。','',''),('quantangshi-02591','侍宴应诏赋韵得前字','虞世南','quantangshi','','卷3','芬芳禁林晚，容与桂丹前。
横空一鸟度，照水百花然。
绿野明斜日，青山澹晚烟。
滥陪终宴赏，握管类窥天。','',''),('quantangshi-02592','侍宴归雁堂','虞世南','quantangshi','','卷3','歌堂面渌水，舞馆接金塘。
竹开霜后翠，梅动雪前香。
凫归初命侣，雁起欲分行。
刷羽同栖集，怀恩愧稻粱。','',''),('quantangshi-02593','凌晨早朝','虞世南','quantangshi','','卷3','万瓦宵光曙，重檐夕雾收。
玉花停夜烛，金壶送晓筹。
日晖青琐殿，霞生结绮楼。
重门应启路，通籍引王侯。','',''),('quantangshi-02594','奉和咏风应魏王教','虞世南','quantangshi','','卷3','逐舞飘轻袖，传歌共绕梁。
动枝生乱影，吹花送远香。','',''),('quantangshi-02595','初晴应教','虞世南','quantangshi','','卷3','初日明燕馆，新溜满梁池。
归云半入岭，残滴尚悬枝。','',''),('quantangshi-02596','春夜','虞世南','quantangshi','','卷3','春苑月裴回，竹堂侵夜开。
惊鸟排林度，风花隔水来。','',''),('quantangshi-02597','咏舞','虞世南','quantangshi','','卷3','繁弦奏渌水，长袖转回鸾。
一双俱应节，还似镜中看。','',''),('quantangshi-02598','咏萤','虞世南','quantangshi','','卷3','的历流光小，飘颻弱翅轻。
恐畏无人识，独自暗中明。','',''),('quantangshi-02599','蝉','虞世南','quantangshi','','卷3','垂緌饮清露，流响出疎桐。
居高声自远，非是藉秋风。','',''),('quantangshi-02600','秋雁','虞世南','quantangshi','','卷3','日暮霜风急，羽翮转难任。
为有传书意，联翩入上林。','',''),('quantangshi-02601','奉和月夜观星应令','虞世南','quantangshi','','卷3','早秋炎景暮，初弦月彩新。
清风涤暑气，零露净嚣尘。
薄雾销轻縠，鲜云卷夕鳞。
休光灼前曜，瑞彩接重轮。
缘情摛圣藻，并作命徐陈。
宿草诚渝滥，吹嘘偶搢绅。
天文岂易述，徒知仰北辰。','',''),('quantangshi-02602','和銮舆顿戏下','虞世南','quantangshi','','卷3','重轮依紫极，前耀奉丹霄。
天经恋宸扆，帝命扈仙镳。
乘[星]开鹤禁，带月下虹桥。
银书含晓色，金辂转晨飙。
雾澈轩营近，尘暗苑城遥。
莲花分秀蕚，竹箭下惊潮。
抚己慙龙干，承恩集凤条。
瑶山盛风乐，抽简荐徒谣。','',''),('quantangshi-02603','奉和至寿春应令','虞世南','quantangshi','','卷3','瑶山盛风乐，南巡务逸游。
如何事巡抚，民瘼谅斯求。
文鹤扬轻盖，苍龙饰桂舟。
泛沫萦沙屿，寒澌拥急流。
路指八仙馆，途经百尺楼。
眷言昔游践，廻驾且淹留。
后车喧凤吹，前旌暎彩旒。
龙骖驻六马，飞阁上三休。
调谐金石奏，欢洽羽觞浮。
天文徒可仰，何以厕琳球。','',''),('quantangshi-02604','奉和幸江都应诏','虞世南','quantangshi','','卷3','南国行周化，稽山秘夏图。
百王岂殊轨，千载协前谟。
肆觐遵时豫，顺动悦来苏。
安流进玉轴，戒道翼金吾。
龙旗焕辰象，凤吹溢川涂。
封唐昔敷锡，分陕被荆吴。
沐道咸知让，慕义久成都。
冬律初飞管，阳鸟正衔芦。
严飙肃林薄，暧景澹江湖。
鸿私浃幽远，厚泽润凋枯。
虞琴起歌咏，汉筑动巴歈。
多幸霑行苇，无庸类散樗。','',''),('quantangshi-02605','奉和献岁宴宫臣','虞世南','quantangshi','','卷3','履端初起节，长苑命高筵。
肆夏喧金奏，重润响朱弦。
春光催柳色，日彩泛槐烟。
微臣同滥吹，谬得仰钧天。','',''),('quantangshi-02606','奉和出颍至淮应令','虞世南','quantangshi','','卷3','良晨喜利涉，解缆入淮浔。
寒流泛鷁首，霜吹响哀吟。
潜鳞波里跃，水鸟浪前沈。
邗沟非复远，怅望悦宸襟。','',''),('quantangshi-02607','应诏嘲司花女','虞世南','quantangshi','','卷3','学画鸦黄半未成，垂肩軃嚲袖太憨生。
缘憨却得君王惜，长把花枝傍辇行。','',''),('quantangshi-02608','古意六首 一','王績','quantangshi','','卷3','幽人在何所？紫岩有仙躅。
月下横宝琴，此外将安欲。
材抽峄山干，徽点昆丘玉。
漆抱蛟龙唇，丝缠凤凰足。
前弹广陵罢，后以明光续。
百金买一声，千金传一曲。
世无钟子期，谁知心所属。','',''),('quantangshi-02609','古意六首 二','王績','quantangshi','','卷3','竹生大夏溪，苍苍富奇质。
绿叶吟风劲，翠茎犯霄密。
霜霰封其柯，鵷鸾食其实。
宁知轩辕后，更有伶伦出。
刀斧俄见寻，根株坐相失。
裁为十二管，吹作雄雌律。
有用虽自伤，无心复招疾。
不如山上草，离离保终吉。','',''),('quantangshi-02610','古意六首 三','王績','quantangshi','','卷3','宝龟尺二寸，由来宅深水。
浮游五湖内，宛转三江里。
何不深复深，轻然至溱洧。
溱洧源流狭，春秋不濡轨。
渔人递往还，网罟相萦藟。
一朝失运会，刳肠血流死。
丰骨输庙堂，鲜腴籍笾簋。
弃置谁怨尤，自我招此否。
余灵寄明卜，复来钦所履。','',''),('quantangshi-02611','古意六首 四','王績','quantangshi','','卷3','松生北岩下，由来人径绝。
布叶捎云烟，插根拥岩穴。
自言生得地，独负凌云洁。
何时畏斤斧，几度经霜雪。
风惊西北枝，雹陨东南节。
不知岁月久，稍觉枝干折。
藤萝上下碎，枝干纵横裂。
行当糜烂尽，坐共灰尘灭。
宁关匠石顾，岂为王孙折。
盛衰自有时，圣贤未尝屑。
寄言悠悠者，无为嗟大耋。','',''),('quantangshi-02612','古意六首 五','王績','quantangshi','','卷3','桂树何苍苍，秋来花更芳。
自言岁寒性，不知露与霜。
幽人重其德，徙植临前堂。
连拳八九树，偃蹇二三行。
枝枝自相纠，叶叶还相当。
去来双鸿鹄，栖息两鸳鸯。
荣荫诚不厚，斤斧亦勿伤。
赤心许君时，此意那可忘。','',''),('quantangshi-02613','古意六首 六','王績','quantangshi','','卷3','彩凤欲将归，提罗出郊访。
罗张大泽已，凤入重云扬。
朝栖昆阆木，夕饮蓬壶涨。
问凤那远飞，贤君坐相望。
凤言荷深德，微禽安足尚。
但使雏卵全，无令[矰]缴放。
皇臣力牧举，帝乐箫韶畅。
自有来巢时，明年阿阁上。','',''),('quantangshi-02614','石竹咏','王績','quantangshi','','卷3','萋萋结绿枝，晔晔垂朱英。
常恐零露降，不得全其生。
叹息聊自思，此生岂我情。
昔我未生时，谁者令我萌。
弃置勿重陈，委化何足惊。','',''),('quantangshi-02615','田家三首 一','王績','quantangshi','','卷3','阮籍生涯懒，嵇康意气疎。
相逢一醉饱，独坐数行书。
小池聊养鹤，闲田且牧猪。
草生元亮径，花暗子云居。
倚牀看妇织，登壠课儿锄。
回头寻仙事，并是一空虚。','',''),('quantangshi-02616','田家三首 二','王績','quantangshi','','卷3','家住箕山下，门枕颍川滨。
不知今有汉，唯言昔避秦。
琴伴前庭月，酒劝后园春。
自得中林士，何忝上皇人。','',''),('quantangshi-02617','田家三首 三','王績','quantangshi','','卷3','平生唯酒乐，作性不能无。
朝朝访乡里，夜夜遣人酤。
家贫留客久，不暇道精麤。
抽帘持益炬，拔箦更燃炉。
恒闻饮不足，何见有残壶。','',''),('quantangshi-02618','赠李征君大寿','王績','quantangshi','','卷3','孔淳辞散骑，陆昶谢中郎。
幅巾朝帝罢，杖策去官忙。
附车还赵郡，乘船向武昌。
九征书未已，十辟誉弥彰。
副君迎绮季，天子送严光。
灞陵幽径近，磻溪隐路长。
编蓬还作室，绩草更为裳。
会稽置樵处，兰陵卖药行。
看书惟道德，开教止农桑。
别有幽怀侣，由来高让王。
前年辞厚币，今岁返寒乡。
有书横石架，无毡坐土牀。
兰英犹足酿，竹实本无粮。
涧松寒转直，山菊秋自香。
管宁存祭礼，王霸重朝章。
去去相随去，披裘骄盛唐。','',''),('quantangshi-02619','山中敍志','王績','quantangshi','','卷3','物外知何事，山中无所有。
风鸣静夜琴，月照芳春酒。
直置百年内，谁论千载后。
张奉娉贤妻，老莱籍嘉偶。
孟光傥未嫁，梁鸿正须妇。','',''),('quantangshi-02620','赠梁公','王績','quantangshi','','卷3','我欲图世乐，斯乐难可常。
位大招讥嫌，禄极生祸殃。
圣莫若周公，忠岂逾霍光。
成王已兴诮，宣帝如负芒。
范蠡何智哉，单舟戒轻装。
疏广岂不怀，策杖还故乡。
朱门虽足悦，赤族亦可伤。
履霜成坚冰，知足胜不祥。
我今穷家子，自言此见长。
功成皆能退，在昔谁灭亡。','',''),('quantangshi-02621','薛记室收过庄见寻率题古意以赠','王績','quantangshi','','卷3','伊昔逢丧乱，历数闰当余。
豺狼塞衢路，桑梓成丘墟。
余及尔皆亡，东西各异居。
尔为背风鸟，我为涸辙鱼。
逮承云雷后，欣逢天地初。
东川聊下钓，南亩试挥锄。
资税幸不及，伏腊常有储。
散诞时须酒，萧条嬾向书。
朽木不可雕，短翮将焉摅。
故人有深契，过我蓬高庐。
曳裾出门迎，握手登前除。
相看非旧颜，忽若形骸疎。
追道宿昔事，切切心相于。
忆我少年时，携手游东渠。
梅李夹两岸，花枝何扶疏。
同志亦不多，西庄有姚徐。
尝爱陶渊明，酌醴焚枯鱼。
尝学公孙弘，策杖牧羣猪。
追念甫如昨，奄忽成空虚。
人生讵能几，岁岁常不舒。
赖有北山僧，教我以真如。
使我视听遣，自觉尘累祛。
何事须筌蹄，今已得兔鱼。
旧游傥多暇，同此释纷拏。','',''),('quantangshi-02622','晚年敍志示翟处士','王績','quantangshi','','卷3','弱龄慕奇调，无事不兼修。
望气登重阁，占星上小楼。
明经思待诏，学剑觅封侯。
弃繻频北上，怀刺几西游。
中年逢丧乱，非复昔追求。
失路青门隐，藏名白社游。
风云私所爱，屠博暗为俦。
解纷曾霸越，释难颇存周。
晚岁聊长想，生涯太若浮。
归来南亩上，更坐北溪头。
古岸多磐石，春泉足细流。
东隅诚已谢，西景惧难收。
无谓退耕近，伏念已经秋。
庚桑逢处跪，陶潜见人羞。
三晨宁举火，五月镇披裘。
自有居常乐，谁知身世忧。','',''),('quantangshi-02623','春日','王績','quantangshi','','卷3','前旦出园游，林华都未有。
今朝下堂来，池冰开已久。
雪被南轩梅，风催北庭柳。
遥呼竈前妾，却报机中妇。
年光恰恰来，满瓮营春酒。','',''),('quantangshi-02624','采药','王績','quantangshi','','卷3','野情贪药饵，郊居倦蓬荜。
青龙护道符，白犬游仙术。
腰镰戊己月，负锸庚辛日。
时时断嶂遮，往往孤峰出。
行披葛仙经，坐检神农帙。
龟蛇采二苓，赤白寻双术。
地冻根难尽，藂枯苗易失。
从容肉作名，薯蓣高成质。
家丰松叶酒，器贮参花蜜。
且复归去来，刀圭辅衰疾。','',''),('quantangshi-02625','在京思故园见乡人问','王績','quantangshi','','卷3','旅泊多年岁，老去不知回。
忽逢门前客，道发故乡来。
敛眉俱握手，破涕共衔杯。
殷勤访朋旧，屈曲问童孩。
衰宗多弟侄，若个赏池台。
旧园今在否，新树也应栽。
柳行疎密布，茅斋宽窄裁。
经移何处竹？别种几株梅。
渠当无绝水，石计总生苔。
院果谁先熟，林花那后开。
羇心祗欲问，为报不须猜。
行当驱下泽，去剪故园莱。','',''),('quantangshi-02626','春桂问答二首 一','王績','quantangshi','','卷3','问春桂：桃李正芬华，年光随处满，何事独无花。','',''),('quantangshi-02627','春桂问答二首 二','王績','quantangshi','','卷3','春桂答：春华讵能久，风霜摇落时，独秀君知不。','',''),('quantangshi-02628','北山','王績','quantangshi','','卷3','旧知山里绝氛埃，登高日暮心悠哉。
子平一去何时返？仲叔长游遂不来。
幽兰独夜清琴曲，桂树凌云浊酒杯。
槁项同枯木，丹心等死灰。','',''),('quantangshi-02629','野望','王績','quantangshi','','卷3','东皐薄暮望，徙倚欲何依。
树树皆秋色，山山唯落晖。
牧人驱犊返，猎马带禽归。
相顾无相识，长歌怀采薇。','',''),('quantangshi-02630','赠程处士','王績','quantangshi','','卷3','百年长扰扰，万事悉悠悠。
日光随意落，河水任情流。
礼乐囚姬旦，诗书缚孔丘。
不如高枕枕，时取醉消愁。','',''),('quantangshi-02631','九月九日赠崔使君善为','王績','quantangshi','','卷3','野人迷节候，端坐隔尘埃。
忽见黄花吐，方知素节回。
映岩千段发，临浦万株开。
香气徒盈把，无人送酒来。','',''),('quantangshi-02632','独坐','王績','quantangshi','','卷3','问君樽酒外，独坐更何须。
有客谈名理，无人索地租。
三男婚令族，五女嫁贤夫。
百年随分了，未羡陟方壶。','',''),('quantangshi-02633','游仙四首 一','王績','quantangshi','','卷3','暂出东陂路，过访北岩前。
蔡经新学道，王烈旧成仙。
驾鹤来无日，乘龙去几年。
三山银作地，八洞玉为天。
金精飞欲尽，石髓溜应坚。
自悲生世促，无暇待桑田。','',''),('quantangshi-02634','游仙四首 二','王績','quantangshi','','卷3','上月芝兰径，中岩紫翠房。
金壶新练乳，玉釜始煎香。
六局黄公术，三门赤帝方。
吹沙聊作鸟，动石试为羊。
缑氏还程促，瀛洲会日长。
谁知北岩下，延首咏霓裳。','',''),('quantangshi-02635','游仙四首 三','王績','quantangshi','','卷3','结衣寻野路，负杖入山门。
道士言无宅，仙人更有村。
斜溪横桂渚，小径入桃源。
玉牀尘稍冷，金炉火尚温。
心疑游北极，望似陟西昆。
逆愁归旧里，萧条访子孙。','',''),('quantangshi-02636','游仙四首 四','王績','quantangshi','','卷3','真经知那是，仙骨定何为。
许迈心长切，嵇康命似奇。
桑疎金阙迥，苔重石梁危。
照水然犀角，游山费虎皮。
鸭桃闻已种，龙竹未经骑。
为向天仙道，栖遑君讵知。','',''),('quantangshi-02637','策杖寻隐士','王績','quantangshi','','卷3','策杖寻隐士，行行路渐赊。
石梁横涧断，土室映山斜。
孝然纵有舍，威辇遂无家。
置酒烧枯叶，披书坐落花。
新垂滋水钓，旧结茂陵罝。
岁岁长如此，方知轻世华。','',''),('quantangshi-02638','赠学仙者','王績','quantangshi','','卷3','采药层城远，寻师海路赊。
玉壶横日月，金阙断烟霞。
仙人何处在？道士未还家。
谁知彭泽意，更覔步兵那。
春酿煎松叶，秋杯浸菊花。
相逢宁可醉，定不学丹砂。','',''),('quantangshi-02639','黄颊山','王績','quantangshi','','卷3','别有青溪道，斜亘碧岩隈。
崩榛横古蔓，荒石拥寒苔。
野心长寂寞，山径本幽回。
步步攀藤上，朝朝负药来。
几看松叶秀，频值菊花开。
无人堪作伴，岁晚独悠哉。','',''),('quantangshi-02640','建德破后入长安咏秋蓬示辛学士','王績','quantangshi','','卷3','遇坎聊知止，逢风或未归。
孤根何处断？轻叶强能飞。','',''),('quantangshi-02641','过酒家五首 一','王績','quantangshi','','卷3','洛阳无大宅，长安乏主人。
黄金销未尽，祗为酒家贫。','',''),('quantangshi-02642','过酒家五首 二','王績','quantangshi','','卷3','此日长昏饮，非关养性灵。
眼看人尽醉，何忍独为醒。','',''),('quantangshi-02643','过酒家五首 三','王績','quantangshi','','卷3','竹叶连糟翠，蒲萄带麴红。
相逢不令尽，别后为谁空。','',''),('quantangshi-02644','过酒家五首 四','王績','quantangshi','','卷3','对酒但知饮，逢人莫强牵。
倚炉便得睡，横瓮足堪眠。','',''),('quantangshi-02645','过酒家五首 五','王績','quantangshi','','卷3','有客须教饮，无钱可别沽。
来时长道贳，慙愧酒家胡。','',''),('quantangshi-02646','夜还东溪','王績','quantangshi','','卷3','石苔应可践，丛枝幸易攀。
青溪归路直，乘月夜歌还。','',''),('quantangshi-02647','山中别李处士','王績','quantangshi','','卷3','为向东溪道，人来路渐赊。
山中春酒熟，何处得停家。','',''),('quantangshi-02648','初春','王績','quantangshi','','卷3','春来日渐长，醉客喜年光。
稍觉池亭好，偏宜酒瓮香。','',''),('quantangshi-02649','醉后','王績','quantangshi','','卷3','阮籍醒时少，陶潜醉日多。
百年何足度，乘兴且长歌。','',''),('quantangshi-02650','题酒店壁','王績','quantangshi','','卷3','昨夜瓶始尽，今朝瓮即开。
梦中占梦罢，还向酒家来。','',''),('quantangshi-02651','戏题卜铺壁','王績','quantangshi','','卷3','旦逐刘伶去，宵随毕卓眠。
不应长卖卜，须得杖头钱。','',''),('quantangshi-02652','尝春酒','王績','quantangshi','','卷3','野觞浮郑酌，山酒漉陶巾。
但令千日醉，何惜两三春。','',''),('quantangshi-02653','独酌','王績','quantangshi','','卷3','浮生知几日，无状逐空名。
不知多酿酒，时向竹林倾。','',''),('quantangshi-02654','秋夜喜遇王处士','王績','quantangshi','','卷3','北场芸藿罢，东皐刈黍归。
相逢秋月满，更值夜萤飞。','',''),('quantangshi-02655','山夜调琴','王績','quantangshi','','卷3','促轸乘明月，抽弦对白云。
从来山水韵，不使俗人闻。','',''),('quantangshi-02656','看酿酒','王績','quantangshi','','卷3','六月调神麴，正朝汲美泉。
从来作春酒，未省不经年。','',''),('quantangshi-02657','食后','王績','quantangshi','','卷3','田家无所有，晚食遂为常。
菜剪三秋绿，飧炊百日黄。
胡麻山麨样，楚豆野麋方。
始暴松皮脯，新添杜若浆。
葛花消酒毒，萸蔕发羹香。
鼓腹聊乘兴，宁知逢世昌。','',''),('quantangshi-02658','过汉故城','王績','quantangshi','','卷3','大汉昔未定，强秦犹擅场。
中原逐鹿罢，高祖郁龙骧。
经始谋帝坐，兹焉壮未央。
规模穷栋宇，表里浚城隍。
羣后崇长乐，中朝增建章。
钩陈被兰錡，乐府奏芝房。
翡翠明珠帐，鸳鸯白玉堂。
清晨宝鼎食，闲夜郁金香。
天马来东道，佳人倾北方。
何其赫隆盛，自谓保灵长。
历数有时尽，哀平嗟不昌。
冰坚成巨猾，火德遂颓纲。
奥位匪虚校，贪天竟速亡。
魂神吁社稷，豺虎鬬岩廊。
金狄移灞岸，铜盘向洛阳。
君王无处所，年代几荒凉。
宫阙谁家域，蓁芜罥我裳。
井田唯有草，海水变为桑。
在昔高门内，于今岐路傍。
余基不可识，古墓列成行。
狐兔惊魍魉，鸱鸮吓獝狂。
空城寒日晚，平野暮云黄。
烈烈焚青棘，萧萧吹白杨。
千秋并万岁，空使咏歌伤。','',''),('quantangshi-02659','益州城西张超亭观妓','王績','quantangshi','','卷3','落日明歌席，行云逐舞人。
江南飞暮雨，梁上下轻尘。
冶服看疑画，妆台望似春。
高车勿遽返，长袖欲相亲。','',''),('quantangshi-02660','咏妓','王績','quantangshi','','卷3','妖姬饰靓妆，窈窕出兰房。
日照当轩影，风吹满路香。
早时歌扇薄，今日舞衫长。
不应令曲误，持此试周郎。','',''),('quantangshi-02661','辛司法宅观妓','王績','quantangshi','','卷3','南国佳人至，北堂罗荐开。
长裙随凤管，促柱送鸾杯。
云光身后荡，雪态掌中回。
到愁金谷晚，不怪玉山颓。','',''),('quantangshi-02662','咏巫山','王績','quantangshi','','卷3','电影江前落，雷声峡外长。
霁云无处所，台馆晓苍苍。','',''),('quantangshi-02663','咏怀','王績','quantangshi','','卷3','故乡行云是，虚室坐间同。
日落西山暮，方知天下空。','',''),('quantangshi-02664','句','王績','quantangshi','','卷3','琴曲唯留古，书多半是经。
横裁桑节杖，直剪竹皮巾。
鹤警琴亭夜，莺啼酒瓮春。
颜回唯乐道，原宪岂伤贫。
寄身千载下，聊游万物初。
欲令无作有，翻觉实成虚。
双关防易断，只眼畏难全。
鱼鳞张九拒，鹤翅拥三边。','',''),('quantangshi-02665','咏舞','蕭德言','quantangshi','','卷3','低身锵玉佩，举袖拂罗衣。
对檐疑燕起，映雪似花飞。','',''),('quantangshi-02666','过严君平古井','鄭世翼','quantangshi','','卷3','严平本高尚，远蹈古人风。
卖卜成都市，流名大汉中。
旧井改人世，寒泉久不通。
多年既罢汲，无禽乃遂空。
如何属秋气，唯见落双桐。','',''),('quantangshi-02667','登北邙还望京洛','鄭世翼','quantangshi','','卷3','步登北邙坂，踟蹰聊写望。
宛洛盛皇居，规模穷大壮。
三河分设险，两崤资巨防。
飞观紫烟中，层台碧云上。
青槐夹驰道，迢迢修且旷。
左右多第宅，参差居将相。
清晨谒帝返，车马相追访。
胥徒各异流，文物纷殊状。
嚣尘暗天起，箫管从风扬。
伊余孤且直，生平独沦丧。
山幽有桂丛，何为坐惆怅。','',''),('quantangshi-02668','巫山高','鄭世翼','quantangshi','','卷3','巫山凌太清，岧嶤类削成。
霏霏暮雨合，霭霭朝云生。
危峯入鸟道，深谷写猨声。
别有幽栖客，淹留攀桂情。','',''),('quantangshi-02669','看新婚','鄭世翼','quantangshi','','卷3','初筓梦桃李，新妆应摽梅。
疑逐朝云去，翻随暮雨来。
杂佩含风响，丛花隔扇开。
姮娥对此夕，何用久裴回。','',''),('quantangshi-02670','见佳人负钱出路','鄭世翼','quantangshi','','卷3','独负千金价，应从买笑来。
秖持难发口，经为几人开。','',''),('quantangshi-02671','送金竟陵入蜀','崔信明','quantangshi','','卷3','金门去蜀道，玉垒望长安。
岂言千里远，方寻九折难。
西上君飞葢，东归我挂冠。
猨声出峡断，月彩落江寒。
从今与君别，花月几新残。','',''),('quantangshi-02672','句','崔信明','quantangshi','','卷3','枫落吴江冷。','',''),('quantangshi-02673','侍宴咏石榴','孔紹安','quantangshi','','卷3','可惜庭中树，移根逐汉臣。
只为来时晚，花开不及春。','',''),('quantangshi-02674','咏夭桃','孔紹安','quantangshi','','卷3','结叶还临影，飞香欲徧空。
不意余花落，翻沈露井中。','',''),('quantangshi-02675','赠蔡君','孔紹安','quantangshi','','卷3','畴昔同幽谷，伊尔迁乔木。
赫奕盛青紫，讨论穷简牍。','',''),('quantangshi-02676','结客少年场行','孔紹安','quantangshi','','卷3','结客佩吴钩，横行度陇头。
雁在弓前落，云从阵后浮。
吴师惊燧象，燕将警奔牛。
转蓬飞不息，冰河结未流。
若使三边定，当封万户侯。','',''),('quantangshi-02677','伤顾学士','孔紹安','quantangshi','','卷3','迢遰双崤道，超忽三川湄。
此中俱失路，思君不可思。
游人行变橘，逝者遽焚芝。
忆昔江湖上，同咏子衿诗。
何言陵谷徙，翻惊邻笛悲。
陈根非席卉，穗帐异书帷。
与善成空说，歼良信在兹。
今日严夫子，哀命不哀时。','',''),('quantangshi-02678','别徐永元秀才','孔紹安','quantangshi','','卷3','金汤既失险，玉石乃同焚。
坠叶还相覆，落羽更为羣。
岂谓三秋节，重伤千里分。
远离弦易转，幽咽水难闻。
欲识相思处，山川间白云。','',''),('quantangshi-02679','落叶','孔紹安','quantangshi','','卷3','早秋惊落叶，飘零似客心。
翻飞未肯下，犹言惜故林。','',''),('quantangshi-02680','踏歌词三首 一','謝偃','quantangshi','','卷3','春景娇春台，新露泣新梅。
春叶参差吐，新花重叠开。
花影飞莺去，歌声度鸟来。
倩看飘颻雪，何如舞袖回。','',''),('quantangshi-02681','踏歌词三首 二','謝偃','quantangshi','','卷3','逶迤度香合，顾步出兰闺。
欲绕鸳鸯殿，先过桃李蹊。
风带舒还卷，簪花举复低。
欲问今宵乐，但听歌声齐。','',''),('quantangshi-02682','踏歌词三首 三','謝偃','quantangshi','','卷3','夜久星沈没，更深月影斜。
裙轻才动佩，鬟薄不胜花。
细风吹宝袂，轻露湿红纱。
相看乐未已，兰灯照九华。','',''),('quantangshi-02683','乐府新歌应教','謝偃','quantangshi','','卷3','青楼绮阁已含春，凝妆艳粉复如神。
细细轻裙全漏影，离离薄扇讵障尘。
樽中酒色恒宜满，曲里歌声不厌新。
紫燕欲飞先遶栋，黄莺始哢即娇人。
撩乱垂丝昏柳陌，参差浓叶暗桑津。
上客莫畏斜光晚，自有西园明月轮。','',''),('quantangshi-02684','奉和出颖至淮应令','蔡允恭','quantangshi','','卷3','久倦川涂曲，忽此望淮圻。
波长泛淼淼，眺迥情依依。
稍觉金乌转，渐见锦帆稀。
欲知仁化洽，讴歌满路归。','',''),('quantangshi-02685','和卫尉寺柳','杜之松','quantangshi','','卷3','汉将本屯营，辽河有戍城。
大夫曾取姓，先生亦得名。
高枝拂远雁，疎影度遥星。
不辞攀折苦，为入管弦声。','',''),('quantangshi-02686','答王无功冬夜载酒乡馆','崔善爲','quantangshi','','卷3','颁条忝贵郡，悬榻久相望。
处士同杨郑，邦君谢李疆。
讵知方拥彗，逢子敬惟桑。
明朝蓬户侧，会自谒任棠。','',''),('quantangshi-02687','答王无功九日','崔善爲','quantangshi','','卷3','秋来菊花气，深山客重寻。
露叶疑涵玉，风花似散金。
摘来还泛酒，独坐即徐斟。
王弘贪自醉，无复觅杨林。','',''),('quantangshi-02688','答王无功问故园','朱仲晦','quantangshi','','卷3','我从铜州来，见子上京客。
问我故乡事，慰子羁旅色。
子问我所知，我对子应识。
朋游总强健，童稚各长成。
华宗盛文史，连墙富池亭。
独子园最古，旧林间新坰。
柳行随堤势，茅斋看地形。
竹从去年移，梅是今年荣。
渠水经夏响，石苔终岁青。
院果早晚熟，林花先后明。
语罢相叹息，浩然起深情。
归哉且五斗，饷子东皐耕。','',''),('quantangshi-02689','从军行','王宏','quantangshi','','卷3','儿生三日掌上珠，燕颔猨肱穠李肤。
十五学劒北击胡，羌歌燕筑送城隅。
城隅路接伊川驿，河阳渡头邯郸陌。
可怜少年把手时，黄鸟双飞梨花白。
秦王筑城三千里，西自临洮东辽水。
山边叠叠黑云飞，海畔莓莓青草死。
从来战鬬不求勋，杀身为君君不闻。
凤皇楼上吹急管，落日裴回肠先断。','',''),('quantangshi-02690','文德皇后挽歌','朱子奢','quantangshi','','卷3','神京背紫陌，缟驷结行輈。
北去横桥道，西分清渭流。
寒光向垄没，霜气入松楸。
今日泉台路，非是濯龙游。','',''),('quantangshi-02691','大酺乐','張文收','quantangshi','','卷3','泪滴珠难尽，容残玉易销。
倘随明月去，莫道梦魂遥。','',''),('quantangshi-02692','与琳法师','毛明素','quantangshi','','卷3','冶长倦缧绁，韩安叹死灰。
始验山中木，方知贵不材。','',''),('quantangshi-02693','上之回','陳子良','quantangshi','','卷3','承平重游乐，诏跸上之回。
属车响流水，清笳转落梅。
岭云盖道转，岩花映绶开。
下辇便高宴，何如在瑶台。','',''),('quantangshi-02694','新成安乐宫','陳子良','quantangshi','','卷3','春色照兰宫，秦女坐牕中。
柳叶来眉上，桃花落脸红。
拂尘开扇匣，卷帐却薰笼。
衫薄偏憎日，裙轻更畏风。','',''),('quantangshi-02695','夏晚寻于政世置酒赋韵','陳子良','quantangshi','','卷3','聊从嘉遯所，酌醴共抽簪。
以兹山水地，留连风月心。
长榆落照尽，高柳暮蝉吟。
一返桃源路，别后难追寻。','',''),('quantangshi-02696','入蜀秋夜宿江渚','陳子良','quantangshi','','卷3','我行逢日暮，弭棹独维舟。
水雾一边起，风林两岸秋。
山阴黑断碛，月影素寒流。
故乡千里外，何以慰羁愁。','',''),('quantangshi-02697','赋得妓','陳子良','quantangshi','','卷3','金谷多欢宴，佳丽正芳菲。
流霞席上满，回雪掌中飞。
明月临歌扇，行云接舞衣。
何必桃将李，别有待春晖。','',''),('quantangshi-02698','酬萧侍中春园听妓','陳子良','quantangshi','','卷3','微雨散芳菲，中园照落晖。
红树摇歌扇，绿珠飘舞衣。
繁弦调对酒，杂引动思归。
愁人当此夕，羞见落花飞。','',''),('quantangshi-02699','游侠篇','陳子良','quantangshi','','卷3','洛阳丽春色，游侠骋轻肥。
水逐车轮转，尘随马足飞。
云影遥临盖，花气近薰衣。
东郊鬬鸡罢，南皮射雉归。
日暮河桥上，扬鞭惜晚晖。','',''),('quantangshi-02700','春晚看羣公朝还人为八韵','陳子良','quantangshi','','卷3','游子惜春暮，策杖出蒿莱。
正直康庄晚，羣公谒帝回。
履度南宫至，车从北阙来。
珂影傍明月，笳声动落梅。
迎风采旄转，照日绶花开。
红尘掩鹤盖，翠柳拂龙媒。
绮云临舞阁，丹霞薄吹台。
轻肥宁所羡，未若反山隈。','',''),('quantangshi-02701','赞德上越国公杨素','陳子良','quantangshi','','卷3','君侯称上宰，命世挺才英。
本超骐骥足，复蕴风云情。
摅藻掞锦绮，育德润瑶琼。
已踵四知举，非无三杰名。
济世同舟檝，匡政本阿衡。
雍容入青锁，肃穆侍丹楹。
桂宫擅鸣佩，槐路独飞缨。
高门罗虎戟，绮阁丽雕甍。
金罇酌湛湛，歌扇掩盈盈。
匈奴轶燕蓟，烽火照幽并。
天子名薄伐，受脤事专征。
七德播雄略，十万骋行兵。
雁行蔽虏甸，鱼贯出长城。
交河方饮马，瀚海盛扬旌。
拔劒倚天外，蒙犀辉日精。
弯弧穿伏石，挥戈斩大鲸。
鼓鼙朝作气，刁斗夜偏鸣。
六郡多壮士，三边岂足平。
岭云朝合阵，山月夜临营。
胡尘暗马色，芳树动笳声。
关云未尽散，塞雾常自生。
川长蔓草绿，峯逈杂花明。
小人愧王氏，雕文慙马卿。
滥此叨书记，何以谢过荣。
高山徒仰止，终是恨才轻。','',''),('quantangshi-02702','于塞北春日思归','陳子良','quantangshi','','卷3','我家吴会青山远，他乡关塞白云深。
为许羁愁长下泪，那堪春色更伤心。
惊鸟屡飞恒失侣，落花一去不归林。
如何此日嗟迟暮，悲来还作白头吟。','',''),('quantangshi-02703','送别','陳子良','quantangshi','','卷3','落叶聚还散，征禽去不归。
以我穷途泣，沾君出塞衣。','',''),('quantangshi-02704','七夕看新妇隔巷停车','陳子良','quantangshi','','卷3','隔巷遥停幰，非复为来迟。
只言更尚浅，未是渡河时。','',''),('quantangshi-02705','咏春雪','陳子良','quantangshi','','卷3','光映妆楼月，花承歌扇风。
欲妬梅将柳，故落早春中。','',''),('quantangshi-02706','骢马','庾抱','quantangshi','','卷3','枥上浮云骢，本出吴门中。
发迹来东道，长鸣起北风。
回鞍拂桂白，赬汗类尘红。
灭没徒留影，无因图汉宫。','',''),('quantangshi-02707','别蔡参军','庾抱','quantangshi','','卷3','人世多飘忽，沟水易西东。
今日欢娱尽，何年风月同？
悲生万里外，恨起一杯中。
性灵如未失，南北有征鸿。','',''),('quantangshi-02708','赋得胥台露','庾抱','quantangshi','','卷3','胥台既落构，荆棘稍侵扉。
栋拆连云影，梁摧照日晖。
翔鶤逐不及，巢燕[反]无归。
唯有团阶露，承晓共沾衣。','',''),('quantangshi-02709','卧疴喜霁开扉望月简宫内知友','庾抱','quantangshi','','卷3','秋雨移弦望，疲疴倦苦辛。
忽对荆山璧，委照越吟人。
高高侵地镜，皎皎彻天津。
色丽班姬箧，光润洛川神。
轮辉池上动，桂影隙中新。
怀贤虽不见，忽似暂参辰。','',''),('quantangshi-02710','和乐记室忆江水','庾抱','quantangshi','','卷3','遥想观涛处，犹意采莲歌。
无因关塞叶，共下洞庭波。','',''),('quantangshi-02711','凌朝浮江旅思','馬周','quantangshi','','卷3','太清上初日，春水送孤舟。
山远疑无树，潮平似不流。
岸花开且落，江鸟没还浮。
羁望伤千里，长歌遣四愁。','',''),('quantangshi-02712','句','馬周','quantangshi','','卷3','何惜邓林树，不借一枝栖。','',''),('quantangshi-02713','出玉关','來濟','quantangshi','','卷3','歛辔遵龙汉，衔凄渡玉关。
今日流沙外，垂涕念生还。','',''),('quantangshi-02714','七夕','張文恭','quantangshi','','卷3','凤律惊秋气，龙梭静夜机。
星桥百枝动，云路七香飞。
映月回雕扇，凌霞曳绮衣。
含情向华幄，流态入重闱。
欢余夕漏尽，怨结晓骖归。
谁念分河汉，还忆两心违。','',''),('quantangshi-02715','佳人照镜','張文恭','quantangshi','','卷3','倦采蘼芜叶，贪怜照胆明。
两边俱拭泪，一处有啼声。','',''),('quantangshi-02716','奉和同太子监守违恋','薛元超','quantangshi','','卷3','储禁铜扉启，宸行玉軑遥。
空怀寿街吏，尚隔寝门朝。
北首瞻龙戟，尘外想鸾镳。
飞文映仙榜，沥思叶神飙。
帝念纡苍璧，干文焕紫霄。
归塘横笔海，平圃振词条。
欲应重轮曲，锵洋韵九韶。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-02717','答辨才探得招字','蕭翼','quantangshi','','卷3','邂逅欵良宵，殷勤荷胜招。
弥天俄若旧，初地岂成遥。
酒蚁倾还泛，心猨躁似调。
谁怜失羣雁，长苦业风飘。','',''),('quantangshi-02718','道失','歐陽詢','quantangshi','','卷3','已惑孔贵嫔，又被辞人侮。
花牋一何荣，七字谁曾许。
不下结绮阁，空迷江令语。
雕戈动地来，悞杀陈后主。','',''),('quantangshi-02719','巫山高','閻立本','quantangshi','','卷3','君不见巫山高高半天起，绝壁千寻尽相似。
君不见巫山磕匝翠屏开，湘江碧水遶山来。
绿树春娇明月峡，红花朝覆白云台。
台上朝云无定所，此中窕窈神仙女。
仙女盈盈仙骨飞，清容出没有光辉。
欲暮高唐行雨送，今宵定入荆王梦。
荆王梦里爱穠华，枕席初开红帐遮。
可怜欲晓啼猨处，说道巫山是妾家。','',''),('quantangshi-02720','同潘屯田冬日早朝','張文琮','quantangshi','','卷3','假寐怀古人，夙兴瞻晓月。
通晨禁门启，冠盖趋朝谒。
霜霭清九衢，霞光照双阙。
纷纶文物纪，焕烂声明发。
腰劒动陆离，鸣玉和清越。','',''),('quantangshi-02721','蜀道难','張文琮','quantangshi','','卷3','梁山镇地险，积石阻云端。
深谷下寥廓，层岩上郁盘。
飞梁驾绝岭，栈道接危峦。
揽辔独长息，方知斯路难。','',''),('quantangshi-02722','昭君怨','張文琮','quantangshi','','卷3','戒途飞万里，回首望三秦。
忽见天山雪，还疑上苑春。
玉痕垂粉泪，罗袂拂胡尘。
为得胡中曲，还悲远嫁人。','',''),('quantangshi-02723','咏水','張文琮','quantangshi','','卷3','标名资上善，流派表灵长。
地图罗四渎，天文载五潢。
方流涵玉润，圆折动珠光。
独有蒙园吏，栖偃翫濠梁。','',''),('quantangshi-02724','赋桥','張文琮','quantangshi','','卷3','造舟浮渭日，鞭石表秦初。
星文遥写汉，虹势尚凌虚。
已授文成履，空题武骑书。
别有临濠上，栖偃独观鱼。','',''),('quantangshi-02725','和杨舍人咏中书省花树','張文琮','quantangshi','','卷3','花萼映芳丛，参差间早红。
因风时落砌，杂雨乍浮空。
影照凤池水，香飘鸡树风。
岂不爱攀折，希君怀袖中。','',''),('quantangshi-02726','奉和过旧宅应制','上官儀','quantangshi','','卷3','石关清晚夏，璇舆御早秋。
神麾扬珠雨，仙吹响飞流。
沛水祥云泛，宛郊瑞气浮。
大风迎汉筑，藂烟入舜球。
翠梧临凤邸，滋兰带鹤舟。
偃伯歌玄化，扈跸颂王游。
遗簪谬昭奖，珥笔荷恩休。','',''),('quantangshi-02727','早春桂林殿应诏','上官儀','quantangshi','','卷3','步辇出披香，清歌临太液。
晓树流莺满，春堤芳草积。
风光翻露文，雪华上空碧。
花蝶来未已，山光暧将夕。','',''),('quantangshi-02728','安德山池宴集','上官儀','quantangshi','','卷3','上路抵平津，后堂罗荐陈。
缔交开狎赏，丽席展芳辰。
密树风烟积，回塘荷芰新。
雨霁虹桥晚，花落凤台春。
翠钗低舞席，文杏散歌尘。
方惜流觞满，夕鸟已城闉。','',''),('quantangshi-02729','酬薛舍人万年宫晚景寓直怀友','上官儀','quantangshi','','卷3','奕奕九成台，窈窕绝尘埃。
苍苍万年树，玲珑下冥雾。
池色摇晚空，岩花歛余煦。
清切丹禁静，浩荡文河注。
留连穷胜托，夙期暌善谑。
东望安仁省，西临子云阁。
长啸披烟霞，高步寻兰若。
金狄掩通门，雕鞍归骑喧。
燕姝对明月，荆艳促芳尊。
别有青山路，策杖访王孙。','',''),('quantangshi-02730','奉和颍川公秋夜','上官儀','quantangshi','','卷3','泬寥空色远，芸黄凄序变。
涸浦落遵鸿，长飙送巢燕。
千秋流夕景，万籁含宵唤。
峻雉聆金柝，层台切银箭。','',''),('quantangshi-02731','谢都督挽歌','上官儀','quantangshi','','卷3','漠漠佳城幽，苍苍松槚暮。
鲁幕飘欲卷，宛驷悲还顾。
楚挽绕卢山，胡笳临武库。
怅然郊原静，烟生归鸟度。','',''),('quantangshi-02732','八咏应制二首 一','上官儀','quantangshi','','卷3','启重帷，重帷照文杏。
翡翠藻轻花，流苏媚浮影。
瑶笙燕始归，金堂露初曦。
风随少女至，虹共美人归。
罗荐已擘鸳鸯被，绮衣复有蒲萄带。
残红艳粉映帘中，戏蝶流莺聚窗外。
洛滨春雪回，巫峡暮云来。
雪花飘玉辇，云光上璧台。
共待新妆出，清歌送落梅。','',''),('quantangshi-02733','八咏应制二首 二','上官儀','quantangshi','','卷3','入丛台，丛台裛春露。
滴沥间深红，参差散轻素。
妆蝶惊复聚，黄鹂飞且顾。
攀折殊未已，复值惊飞起。
送影舞衫前，飘香歌扇里。
望望惜春晖，行行犹未归。
暂得佳游趣，更愁花鸟稀。
且学鸟声调凤管，方移花影入鸳机。','',''),('quantangshi-02734','和太尉戏赠高阳公','上官儀','quantangshi','','卷3','薰炉御史出神仙，云鞍羽盖下芝田。
红尘正起浮桥路，青楼遥敞御沟前。
倾城比态芳菲节，绝世相娇是六年。
惯是洛滨要解佩，本是河间好数钱。
翠钗照耀衔云发，玉步逶迤动罗袜。
石榴绞带轻花转，桃枝绿扇微风发。
无情拂袂欲留宾，讵恨深潭不可越。
天津一别九秋长，岂若随闻三日香。
南国自然胜掌上，东家复是忆王昌。','',''),('quantangshi-02735','王昭君','上官儀','quantangshi','','卷3','玉关春色晚，金河路几千。
琴悲桂条上，笛怨柳花前。
雾掩临妆月，风惊入鬓蝉。
缄书待还使，泪尽白云天。','',''),('quantangshi-02736','咏雪应诏','上官儀','quantangshi','','卷3','禁园凝朔气，瑞雪掩晨曦。
花明栖凤阁，珠散影娥池。
飘素迎歌上，翻光向舞移。
幸因千里映，还绕万年枝。','',''),('quantangshi-02737','奉和山夜临秋','上官儀','quantangshi','','卷3','殿帐清炎气，辇道含秋阴。
凄风移汉筑，流水入虞琴。
云飞送断雁，月上净疎林。
滴沥露枝响，空蒙烟壑深。','',''),('quantangshi-02738','江王太妃挽歌','上官儀','quantangshi','','卷3','黄鹤悲歌绝，椒花清颂余。
埃凝写邻镜，网结和扉鱼。
银消风烛尽，珠灭夜轮虚。
别有南陵路，幽丛临叶疎。','',''),('quantangshi-02739','故北平公挽歌','上官儀','quantangshi','','卷3','木落园林旷，庭虚风露寒。
北里清音绝，南陔芳草残。
远气犹标劒，浮云尚写冠。
寂寂琴台晚，秋阴入井干。','',''),('quantangshi-02740','高密长公主挽歌','上官儀','quantangshi','','卷3','湘渚韬灵迹，娥台静瑞音。
凤逐清箫远，鸾随幽镜沈。
霜处华芙落，风前银烛侵。
寂寞平阳宅，月冷洞房深。','',''),('quantangshi-02741','咏画障','上官儀','quantangshi','','卷3','芳晨丽日桃花浦，珠帘翠帐凤凰楼。
蔡女菱歌移锦缆，燕姬春望上琼钩。
新妆漏影浮轻扇，冶袖飘香入浅流。
未减行雨荆台下，自比凌波洛浦游。','',''),('quantangshi-02742','奉和秋日即目应制','上官儀','quantangshi','','卷3','上苑通平乐，神池迩建章。
楼台相掩映，城阙互相望。
缇油泛行幔，箫吹转浮梁。
晚云含朔气，斜照荡秋光。
落叶飘蝉影，平流写雁行。
槿散凌风缛，荷销裛露香。
仙歌临枍诣，玄豫历长杨。
归路乘明月，千门开未央。','',''),('quantangshi-02743','入朝洛堤步行','上官儀','quantangshi','','卷3','脉脉广川流，驱马历长洲。
鹊飞山月曙，蝉噪野风秋。','',''),('quantangshi-02744','春日','上官儀','quantangshi','','卷3','花轻蝶乱仙人杏，叶密莺啼帝女桑。
飞云阁上春应至，明月楼中夜未央。','',''),('quantangshi-02745','从驾闾山咏马','上官儀','quantangshi','','卷3','桂香尘处减，练影月前空。
定惑由关吏，徒嗟塞上翁。','',''),('quantangshi-02746','中和乐九章 歌登封第一','盧照鄰','quantangshi','','卷3','炎图丧宝，黄历开璇。
祖武类帝，宗文配天。
玉銮垂日，翠华陵烟。
东云干吕，南风入弦。
山称万岁，河庆千年。
金绳永结，璧丽长悬。','',''),('quantangshi-02747','中和乐九章 歌明堂第二','盧照鄰','quantangshi','','卷3','穆穆圣皇，雍雍明堂。
左平右墄，上圆下方。
调均风雨，制度阴阳。
四牕八达，五室九房。
南通夏火，西瞰秋霜。
天子临御，万玉锵锵。','',''),('quantangshi-02748','中和乐九章 歌东军第三','盧照鄰','quantangshi','','卷3','遐哉庙畧，赫矣台臣。
横戈碣石，倚劒浮津。
风丘拂箨，日域清尘。
岛夷复祀，龙伯来宾。
休兵宇县，献馘天闉。
斾海凯入，耀辉震震。','',''),('quantangshi-02749','中和乐九章 歌南郊第四','盧照鄰','quantangshi','','卷3','虔郊上帝，肃事圆丘。
龙驾四牡，鸾旗九斿。
钟歌晚引，紫炀高浮。
日丽苍璧，云飞鸣球。
皇之庆矣，万寿千秋。','',''),('quantangshi-02750','中和乐九章 歌中宫第五','盧照鄰','quantangshi','','卷3','祥游沙麓，庆洽瑶衣。
黄云昼聚，白气宵飞。
居中履正，禀和体微。
仪刑赤县，演教椒闱。
陶钧万国，丹青四妃。
河洲在咏，风化攸归。','',''),('quantangshi-02751','中和乐九章 歌储宫第六','盧照鄰','quantangshi','','卷3','波澄少海，景丽前星。
高禖诞圣，甲观升灵。
承规翠所，问寝瑶庭。
宗儒侧席，问道横经。
山宾皎皎，国胄青青。
黄裳元吉，邦家以宁。','',''),('quantangshi-02752','中和乐九章 歌诸王第七','盧照鄰','quantangshi','','卷3','星陈帝子，岳列天孙。
义光带砺，象着干坤。
我有明德，利建攸存。
苴以茅社，锡以牺尊。
藩屏王室，翼亮尧门。
八才两献，夫何足论。','',''),('quantangshi-02753','中和乐九章 歌公卿第八','盧照鄰','quantangshi','','卷3','蹇蹇三事，师师百僚。
羣龙在职，振鹭盈朝。
丰金辉首，佩玉鸣腰。
青蒲翼翼，丹地翘翘。
歌云佐汉，捧日匡尧。
天工人代，邈邈昭昭。','',''),('quantangshi-02754','中和乐九章 总歌第九','盧照鄰','quantangshi','','卷3','明明天子兮圣德扬，穆穆皇后兮阴化康。
登若木兮坐明堂，池蒙汜兮家扶桑。
武化偃兮文化昌，礼乐昭兮股肱良。
君臣已定兮君永无疆，颜子更生兮徒皇皇。
若有人兮天一方，忠为衣兮信为裳。
飡白玉兮饮琼芳，心思荃兮路阻长。','',''),('quantangshi-02755','关山月','盧照鄰','quantangshi','','卷3','塞垣通碣石，虏障抵[祁]连。
相思在万里，明月正孤悬。
影移金岫北，光断玉门前。
寄言闺中妇，时看鸿雁天。','',''),('quantangshi-02756','上之回','盧照鄰','quantangshi','','卷3','回中道路险，萧关烽候多。
五营屯北地，万乘出西河。
单于拜玉玺，天子按雕戈。
振旅汾川曲，秋风横大歌。','',''),('quantangshi-02757','紫骝马','盧照鄰','quantangshi','','卷3','骝马照金鞍，转战入皐兰。
塞门风稍急，长城水正寒。
雪暗鸣珂重，山长喷玉难。
不辞横绝漠，流血几时干。','',''),('quantangshi-02758','战城南','盧照鄰','quantangshi','','卷3','将军出紫塞，冒顿在乌贪。
笳喧雁门北，阵翼龙城南。
雕弓夜宛转，铁骑晓参驔。
应须驻白日，为待战方酣。','',''),('quantangshi-02759','梅花落','盧照鄰','quantangshi','','卷3','梅岭花初发，天山雪未开。
雪处疑花落，花边似雪回。
因风入舞袖，杂粉向妆台。
匈奴几万里，春至不知来。','',''),('quantangshi-02760','结客少年场行','盧照鄰','quantangshi','','卷3','长安重游侠，洛阳富财雄。
玉劒浮云骑，金鞭明月弓。
鬬鸡过渭北，走马向关东。
孙宾遥见待，郭解暗相通。
不受千金爵，谁论万里功。
将军下天上，虏骑入云中。
烽火夜似月，兵气晓成虹。
横行徇知己，负羽远从戎。
龙旌昏朔雾，鸟阵卷胡风。
追奔瀚海咽，战罢阴山空。
归来谢天子，何如马上翁。','',''),('quantangshi-02761','咏史四首 一','盧照鄰','quantangshi','','卷3','季生昔未达，身辱功不成。
髠钳为台隶，灌园变姓名。
幸逢滕将军，兼遇曹丘生。
汉祖广招纳，一朝拜公卿。
百金孰云重，一诺良匪轻。
廷议斩樊哙，羣公寂无声。
处身孤且直，遭时坦而平。
丈夫当如此，唯唯何足荣。','',''),('quantangshi-02762','咏史四首 二','盧照鄰','quantangshi','','卷3','大汉昔云季，小人道遂振。
玉帛委奄尹，斧锧婴缙绅。
邈哉郭先生，卷舒得其真。
雍容谢朝廷，谈笑奖人伦。
在晦不绝俗，处乱不为亲。
诸侯不得友，天子不得臣。
冲情甄负甑，重价折角巾。
悠悠天下士，相送洛桥津。
谁知仙舟上寂寂无四邻。','',''),('quantangshi-02763','咏史四首 三','盧照鄰','quantangshi','','卷3','公业负奇志，交结尽才雄。
良田四百顷，所食常不充。
一为侍御史，慷慨说何公。
何公何为败，吾谋适不同。
仲頴恣残忍，废兴良在躬。
死人如乱麻，天子如转蓬。
干戈及黄屋，荆棘生紫宫。
郑生运其谋，将以清国戎。
时来命不遂，脱身归山东。
凛凛千载下，穆然怀春风。','',''),('quantangshi-02764','咏史四首 四','盧照鄰','quantangshi','','卷3','昔有平陵男，姓朱名阿游。
直发上冲冠，壮气横三秋。
愿得斩马劒，先断佞臣头。
天子玉槛折，将军丹血流。
捐生不肯拜，视死其若休。
归来教乡里，童蒙远相求。
弟子数百人，散在十二州。
三公不敢吏，五鹿何能酬。
名与日月悬，义与天壤俦。
何必疲执戟，区区在封侯。
伟哉旷达士，知命固不忧。','',''),('quantangshi-02765','赠李荣道士','盧照鄰','quantangshi','','卷3','锦节衔天使，琼仙驾羽君。
投金翠山曲，奠璧清江濆。
圆洞开丹鼎，方坛聚绛云。
宝贶幽难识，空歌迥易分。
风摇十洲影，日乱九江文。
敷诚归上帝，应诏在明君。
独有南冠客，耿耿泣离羣。
遥看八会所，真气晓氤氲。','',''),('quantangshi-02766','赠李荣道士','盧照鄰','quantangshi','','卷3','锦节衔天使，琼仙驾羽君。
投金翠山曲，奠璧清江濆。
圆洞开丹鼎，方坛聚绛云。
宝贶幽难识，空歌迥易分。','',''),('quantangshi-02767','早度分水岭','盧照鄰','quantangshi','','卷3','丁年游蜀道，班鬓向长安。
徒费周王粟，空弹汉吏冠。
马蹄穿欲尽，貂裘敝转寒。
层冰横九折，积石凌七盘。
重溪既下漱，峻峰亦上干。
陇头闻戍鼓，岭外咽飞湍。
瑟瑟松风急，苍苍山月团。
传语后来者，斯路诚独难。','',''),('quantangshi-02768','三月曲水宴得尊字','盧照鄰','quantangshi','','卷3','风烟彭泽里，山水仲长园。
由来弃铜墨，本自重琴尊。
高情邈不嗣，雅道今复存。
有美光时彦，养德坐山樊。
门开芳杜迳，室距桃花源。
公子黄金勒，仙人紫气轩。
长怀去城市，高咏狎兰荪。
连沙飞白鹭，孤屿啸玄猿。
日影岩前落，云花江上翻。
兴兰车马散，林塘夕鸟喧。','',''),('quantangshi-02769','奉使益州至长安发钟阳驿','盧照鄰','quantangshi','','卷3','跻险方未夷，乘春聊骋望。
落花赴丹谷，奔流下青嶂。
葳蕤晓树滋，滉漾春江涨。
平川看钓侣，狭径闻樵唱。
蝶戏绿苔前，莺歌白云上。
耳目多异赏，风烟有奇状。
峻阻将长城，高标吞巨舫。
联翩事羁靮，辛苦劳疲恙。
夕济几潺湲，晨登每惆怅。
谁念复刍狗，山河独偏丧。','',''),('quantangshi-02770','和王奭秋夜有所思','盧照鄰','quantangshi','','卷3','寂寂南轩夜，悠然怀所知。
长河落雁苑，明月下鲸池。
凤台有清曲，此曲何人吹？
丹唇间玉齿，妙响入云涯。
穷巷秋风叶，空庭寒露枝。
劳歌欲有和，星鬓已将垂。','',''),('quantangshi-02771','望宅中树有所思','盧照鄰','quantangshi','','卷3','我家有庭树，秋叶正离离。
上舞双栖鸟，中秀合欢枝。
劳思复劳望，相见不相知。
何当共攀折？歌笑此堂垂。','',''),('quantangshi-02772','宿晋安亭','盧照鄰','quantangshi','','卷3','闻有弦歌地，穿凿本多奇。
游人试一览，临翫果忘疲。
窗横暮卷叶，檐卧古生枝。
旧石开红鲜，新河覆绿池。
孤猿稍断绝，宿鸟复参差。
泛滟月华晓，裴回星鬓垂。
今日删书客，凄惶君讵知。','',''),('quantangshi-02773','于时春也慨然有江湖之思寄赠柳九陇','盧照鄰','quantangshi','','卷3','提琴一万里，负书三十年。
晨攀偃蹇树，暮宿清泠泉。
翔禽鸣我侧，旅兽过我前。
无人且无事，独酌还独眠。
遥闻彭泽宰，高弄武城弦。
形骸寄文墨，意气托神仙。
我有壶中要，题为物外篇。
将以贻好道，道远莫致旃。
相思劳日夜，相望阻风烟。
坐惜春华晚，徒令客思悬。
水去东南地，气凝西北天。
关山悲蜀道，花鸟忆秦川。
天子何时问，公卿本亦怜。
自哀还自乐，归薮复归田。
海屋银为栋，云车电作鞭。
倘遇鸾将鹤，谁论貂与蝉。
莱洲频度浅，桃实几成圆。
寄言飞凫舃，岁[晏]同联翩。','',''),('quantangshi-02774','至望喜瞩目言怀贻剑外知己','盧照鄰','quantangshi','','卷3','圣图夷九折，神化掩三分。
缄愁赴蜀道，题拙奉虞薰。
隐辚度深谷，遥褭上高云。
碧流递萦注，青山互纠纷。
涧松咽风绪，岩花濯露文。
思北常依驭，图南每丧羣。','',''),('quantangshi-02775','赤谷安禅师塔','盧照鄰','quantangshi','','卷3','独坐岩之曲，悠然无俗纷。
酌酒呈丹桂，思诗赠白云。
烟霞朝晚聚，猿鸟岁时闻。
水华竞秋色，山翠含夕曛。
高谈十二部，细核五千文。
如如数冥味，生生理氛氲。
古人有糟粕，轮扁情未分。
且当事芝术，从吾所好云。','',''),('quantangshi-02776','赠益府裴录事','盧照鄰','quantangshi','','卷3','忽忽岁云暮，相望限风烟。
长歌欲对酒，危坐遂停弦。
停弦变霜露，对酒怀朋故。
朝看桂蟾晚，夜闻鸿雁度。
鸿度何时还？桂晚不同攀。
浮云映丹壑，明月满青山。
青山云路深，丹壑月华临。
耿耿离忧积，空令星鬓侵。','',''),('quantangshi-02777','赠益府羣官','盧照鄰','quantangshi','','卷3','一鸟自北燕，飞来向西蜀。
单栖剑门上，独舞岷山足。
昂藏多古貌，哀怨有新曲。
羣凤从之游，问之何所欲？
答言寒乡子，飘颻万余里。
不息恶木枝，不饮盗泉水。
常思稻粱遇，愿栖梧桐树。
智者不我邀，愚夫余不顾。
所以成独立，耿耿岁云暮。
日夕苦风霜，思归赴洛阳。
羽翮毛衣短，关山道路长。
明月流客思，白云迷故乡。
谁能借风便，一举凌苍苍。','',''),('quantangshi-02778','送梓州高参军还京','盧照鄰','quantangshi','','卷3','京洛风尘远，褒斜烟露深。
北游君似智，南飞我异禽。
别路琴声断，秋山猿鸟吟。
一乖青岩酌，空伫白云心。','',''),('quantangshi-02779','大剑送别刘右史','盧照鄰','quantangshi','','卷3','金碧禺山远，关梁蜀道难。
相逢属晚岁，相送动征鞍。
地咽緜川冷，云凝剑阁寒。
倘遇忠孝所，为道忆长安。','',''),('quantangshi-02780','同临津纪明府孤雁','盧照鄰','quantangshi','','卷3','三秋违北地，万里向南翔。
河洲花稍白，关塞叶初黄。
避缴风霜劲，怀书道路长。
水流疑箭动，月照似弓伤。
横天无有阵，度海不成行。
会刷能鸣羽，还赴上林乡。','',''),('quantangshi-02781','失羣雁','盧照鄰','quantangshi','','卷3','三秋北地雪皑皑，万里南翔渡海来。
欲随石燕沈湘水，试逐铜乌绕帝台。
帝台银阙距金塘，中间鵷鹭已成行。
先过上苑传书信，暂下中州戏稻粱。
虞人负缴来相及，齐客虚弓忽见伤。
毛翎频顿飞无力，羽翮摧颓君不识。
唯有庄周解爱鸣，复道郊哥重奇色。
惆怅惊思悲未已，裴回自怜中罔极。
传闻有鸟集朝阳，讵胜仙凫迩帝乡。
云间海上应鸣舞，远得鵾弦犹独抚。
金龟全写中牟印，玉鹄当变莱芜釜。
愿君弄影凤皇池，时忆笼中摧折羽。','',''),('quantangshi-02782','行路难','盧照鄰','quantangshi','','卷3','君不见长安城北渭桥边，枯木横槎卧古田。
昔日含红复含紫，常时留雾亦留烟。
春景春风花似雪，香车玉轝恒阗咽。
若个游人不竞攀，若个娼家不来折。
娼家宝袜蛟龙帔，公子银鞍千万骑。
黄莺一一向花娇，青鸟双双将子戏。
千尺长条百尺枝，月桂星榆相蔽亏。
珊瑚叶上鸳鸯鸟，凤皇巢里雏鵷儿。
巢倾枝折凤归去，条枯叶落任风吹。
一朝零落无人问，万古摧残君讵知。
人生贵贱无终始，倏忽须臾难久恃。
谁家能驻西山日，谁家能堰东流水。
汉家陵树满秦川，行来行去尽哀怜。
自昔公卿二千石，咸拟荣华一万年。
不见朱唇将白貌，唯闻素棘与黄泉。
金貂有时换美酒，玉麈但摇莫计钱。
寄言坐客神仙署，一生一死交情处。
苍龙阙下君不来，白鹤山前我应去。
云间海上邈难期，赤心会合在何时。
但愿尧年一百万，长作巢由也不辞。','',''),('quantangshi-02783','长安古意','盧照鄰','quantangshi','','卷3','长安大道连狭斜，青牛白马七香车。
玉辇纵横过主第，金鞭络绎向侯家。
龙衔宝盖承朝日，凤吐流苏带晚霞。
百丈游丝争绕树，一羣娇鸟共啼花。
啼花戏蝶千门侧，碧树银台万种色。
复道交窗作合欢，双阙连薨垂凤翼。
梁家画阁天中起，汉帝金茎云外直。
楼前相望不相知，陌上相逢讵相识。
借问吹箫向紫烟，曾经学舞度芳年。
得成比目何辞死，愿作鸳鸯不羡仙。
比目鸳鸯真可羡，双去双来君不见。
生憎帐额绣孤鸾，好取门帘帖双燕。
双燕双飞绕画梁，罗帏翠被郁金香。
片片行云着蝉鬓，纤纤初月上鸦黄。
鸦黄粉白车中出，含娇含态情非一。
妖童宝马铁连钱，娼妇盘龙金屈膝。
御史府中乌夜啼，廷尉门前雀欲栖。
隐隐朱城临玉道，遥遥翠幰没金堤。
挟弹飞鹰杜陵北，探丸借客渭桥西。
俱邀侠客芙蓉剑，共宿娼家桃李蹊。
娼家日暮紫罗裙，清歌一啭口氛氲。
北堂夜夜人如月，南陌朝朝骑似云。
南陌北堂连北里，五剧三条控三市。
弱柳青槐拂地垂，佳气红尘暗天起。
汉代金吾千骑来，翡翠屠苏鹦鹉杯。
罗襦宝带为君解，燕歌赵舞为君开。
别有豪华称将相，转日回天不相让。
意气由来排灌夫，专权判不容萧相。
专权意气本豪雄，青虬紫燕坐春风。
自言歌舞长千载，自谓骄奢凌五公。
节物风光不相待，桑田碧海须臾改。
昔时金阶白玉堂，即今唯见青松在。
寂寂寥寥[扬]子居，年年岁岁一牀书。
独有南山桂花发，飞来飞去袭人裾。','',''),('quantangshi-02784','明月引','盧照鄰','quantangshi','','卷3','洞庭波起兮鸿雁翔，风瑟瑟兮野苍苍。
浮云卷霭，明月流光。
荆南兮赵北，碣石兮潇湘。
澄清规于万里，照离思于千行。
横桂枝于西第，绕菱花于北堂。
高楼思妇，飞盖君王。
文姬绝域，侍子他乡。
见胡鞍之似练，知汉剑之如霜。
试登高而骋目，莫不变而回肠。','',''),('quantangshi-02785','狱中学骚体','盧照鄰','quantangshi','','卷3','夫何秋夜之无情兮，皎皛悠悠而太长。
圜户杳其幽邃兮，愁人披此严霜。
见河汉之西落，闻鸿雁之南翔。
山有桂兮桂有芳，心思君兮君不将。
忧与忧兮相积，欢与欢兮两忘。
风袅袅兮木纷纷，凋绿叶兮吹白云。
寸步千里兮不相闻，思公子兮日将曛。
林已暮兮鸟羣飞，重门掩兮人径稀。
万族皆有所托兮，蹇独淹留而不归。','',''),('quantangshi-02786','怀仙引','盧照鄰','quantangshi','','卷3','若有人兮山之曲，驾青虬兮乘白鹿。
往从之游愿心足，披涧户，访岩轩。
石濑潺湲横石径，松萝幂䍥掩松门。
下空蒙而无鸟，上巉岩而有猨。
怀飞阁，度飞梁。
休余马于幽谷，挂余冠于夕阳。
曲复曲兮烟庄邃，行复行兮天路长。
修途杳其未半，飞雨忽以茫茫。
山坱轧，磴连褰。
攀石壁而无据，溯泥溪而不前。
向无情之白日，窃有恨于皇天。
回行遵故道，通川遍流潦。
回首望羣峰，白云正溶溶。
珠为阙兮玉为楼，青云盖兮紫霜裘。
天长地久时相忆，千龄万代一来游。','',''),('quantangshi-02787','七日登乐游故墓','盧照鄰','quantangshi','','卷3','四序周缇龠，三正纪璇耀。
绿野变初黄，阳山开晓眺。
中天擢露掌，匝地分星徼。
汉寝睠遗灵，秦江想余吊。
蚁泛青田酌，莺歌紫芝调。
柳色摇岁华，冰文荡春照。
远迹谢羣动，高情符众妙。
兰游澹未归，倾光下岩窈。','',''),('quantangshi-02788','释疾文三歌 一','盧照鄰','quantangshi','','卷3','岁将暮兮欢不再，时已晚兮忧来多。
东郊绝此麒麟笔，西山秘此凤凰柯。','',''),('quantangshi-02789','释疾文三歌 二','盧照鄰','quantangshi','','卷3','岁去忧来兮东流水，地久天长兮人共死。
明镜羞窥兮向十年，骏马停驱兮几千里。
麟兮凤兮，自古吞恨无已。','',''),('quantangshi-02790','释疾文三歌 三','盧照鄰','quantangshi','','卷3','茨山有薇兮颍水有漪，夷为柏兮秋有实。
叔为柳兮春向飞，倏尔而笑，泛沧浪兮不归。','',''),('quantangshi-02791','酬杨比部员外暮宿琴堂朝跻书阁率尔见赠之作','盧照鄰','quantangshi','','卷3','闲拂檐尘看，鸣琴候月弹。
桃源迷汉姓，松径有秦官。
空谷归人少，青山背日寒。
羡君栖隐处，遥望在云端。','',''),('quantangshi-02792','刘生','盧照鄰','quantangshi','','卷3','刘生气不平，抱剑欲专征。
报恩为豪侠，死难在横行。
翠羽装刀鞘，黄金饰马铃。
但令一顾重，不恡百身轻。','',''),('quantangshi-02793','陇头水','盧照鄰','quantangshi','','卷3','陇阪高无极，征人一望乡。
关河别去水，沙塞断归肠。
马系千年树，旌悬九月霜。
从来共呜咽，皆是为勤王。','',''),('quantangshi-02794','巫山高','盧照鄰','quantangshi','','卷3','巫山望不极，望望下朝氛。
莫辨啼猿树，徒看神女云。
惊涛乱水脉，骤雨暗峯文。
霑裳即此地，况复远思君。','',''),('quantangshi-02795','芳树','盧照鄰','quantangshi','','卷3','芳树本多奇，年华复在斯。
结翠成新幄，开红满故枝。
风归花历乱，日度影参差。
容色朝朝落，思君君不知。','',''),('quantangshi-02796','雨雪曲','盧照鄰','quantangshi','','卷3','虏骑三秋入，关云万里平。
雪似胡沙暗，冰如汉月明。
高阙银为阙，长城玉作城。
节旄零落尽，天子不知名。','',''),('quantangshi-02797','昭君怨','盧照鄰','quantangshi','','卷3','合殿恩中绝，交河使渐稀。
肝肠辞玉辇，形影向金微。
汉地草应绿，胡庭沙正飞。
愿逐三秋雁，年年一度归。','',''),('quantangshi-02798','折杨柳','盧照鄰','quantangshi','','卷3','倡楼启曙扉，杨柳正依依。
莺啼知岁隔，条变识春归。
露叶凝愁黛，风花乱舞衣。
攀折聊将寄，军中音信稀。','',''),('quantangshi-02799','十五夜观灯','盧照鄰','quantangshi','','卷3','锦里开芳宴，兰缸艳早年。
缛彩遥分地，繁光远缀天。
接汉疑星落，依楼似月悬。
别有千金笑，来映九枝前。','',''),('quantangshi-02800','入秦川界','盧照鄰','quantangshi','','卷3','陇阪长无极，苍山望不穷。
石径萦疑断，回流映似空。
花开绿野雾，莺啭紫岩风。
春芳勿遽尽，留赏故人同。','',''),('quantangshi-02801','文翁讲堂','盧照鄰','quantangshi','','卷3','锦里淹中馆，岷山稷下亭。
空梁无燕雀，古壁有丹青。
槐落犹疑市，苔深不辨铭。
良哉二千石，江汉表遗灵。','',''),('quantangshi-02802','相如琴台','盧照鄰','quantangshi','','卷3','闻有雍容地，千年无四邻。
园院风烟古，池台松槚春。
云疑作赋客，月似听琴人。
寂寂啼莺处，空伤游子神。','',''),('quantangshi-02803','石镜寺','盧照鄰','quantangshi','','卷3','古墓芙蓉塔，神铭松柏烟。
鸾沈仙镜底，花没梵轮前。
铢衣千古佛，宝月两重圆。
隐隐香台夜，钟声彻九天。','',''),('quantangshi-02804','辛法司宅观妓','盧照鄰','quantangshi','','卷3','南国佳人至，北棠罗荐开。
长帬随凤管，促柱送鸾杯。
云光身后落，雪态掌中回。
到愁金谷晚，不怪玉山颓。','',''),('quantangshi-02805','春晚山庄率题二首 一','盧照鄰','quantangshi','','卷3','顾步三春晚，田园四望通。
游丝横惹树，戏蝶乱依藂。
竹懒偏宜水，花狂不待风。
唯余诗酒意，当了一生中。','',''),('quantangshi-02806','春晚山庄率题二首 二','盧照鄰','quantangshi','','卷3','田家无四邻，独坐一园春。
莺啼非选树，鱼戏不惊纶。
山水弹琴尽，风花酌酒频。
年华已可乐，高兴复留人。','',''),('quantangshi-02807','江中望月','盧照鄰','quantangshi','','卷3','江水向涔阳，澄澄写月光。
镜圆珠留彻，弦满箭波长。
沈钩摇兔影，浮桂动丹芳。
延照相思夕，千里共霑裳。','',''),('quantangshi-02808','元日述怀','盧照鄰','quantangshi','','卷3','筮仕无中秩，归耕有外臣。
人歌小岁酒，花舞大唐春。
草色迷三径，风光动四邻。
愿得长如此，年年物候新。','',''),('quantangshi-02809','益州城西张超亭观妓','盧照鄰','quantangshi','','卷3','落日明歌席，行云逐舞人。
江前飞暮雨，梁上下轻尘。
冶服看疑画，妆楼望似春。
高车勿遽返，长袖欲相亲。','',''),('quantangshi-02810','还京赠别','盧照鄰','quantangshi','','卷3','风月清江夜，山水白云朝。
万里同为客，三秋契不凋。
戏凫分断岸，归骑别高标。
一去仙桥道，还望锦城遥。','',''),('quantangshi-02811','至陈仓晓晴望京邑','盧照鄰','quantangshi','','卷3','拂曙驱飞传，初晴带晓凉。
雾歛长安树，云归仙帝乡。
涧流漂素沫，岩景霭朱光。
今朝好风色，延瞰极天庄。','',''),('quantangshi-02812','晚渡滹沱敬赠魏大','盧照鄰','quantangshi','','卷3','津谷朝行远，冰川夕望曛。
霞明深浅浪，风卷去来云。
澄波泛月影，激浪聚沙文。
谁忍仙舟上，携手独思君。','',''),('quantangshi-02813','和吴侍御被使燕然','盧照鄰','quantangshi','','卷3','春归龙塞北，骑指雁门垂。
胡笳折杨柳，汉使采燕支。
戍城聊一望，花雪几参差。
关山有新曲，应向笛中吹。','',''),('quantangshi-02814','七夕泛舟二首 一','盧照鄰','quantangshi','','卷3','汀葭肃徂暑，江树起初凉。
水疑通织室，舟似泛仙潢。
连桡渡急响，鸣棹下浮光。
日晚菱歌唱，风烟满夕阳。','',''),('quantangshi-02815','七夕泛舟二首 二','盧照鄰','quantangshi','','卷3','凤杼秋期至，凫舟野望开。
微吟翠塘侧，延想白云隈。
石似支机罢，槎疑犯宿来。
天潢殊漫漫，日暮独悠哉。','',''),('quantangshi-02816','西使兼送孟学士南游','盧照鄰','quantangshi','','卷3','地道巴陵北，天山弱水东。
相看万余里，共倚一征蓬。
零雨悲王粲，清尊别孔融。
裴回闻夜鹤，怅望待秋鸿。
骨肉胡秦外，风尘关塞中。
唯余剑锋在，耿耿气成虹。','',''),('quantangshi-02817','送郑司仓入蜀','盧照鄰','quantangshi','','卷3','离人丹水北，游客锦城东。
别意还无已，离忧自不穷。
陇云朝结阵，江月夜临空。
关塞疲征马，霜氛落早鸿。
潘年三十外，蜀道五千中。
送君秋水曲，酌酒对清风。','',''),('quantangshi-02818','绵州官池赠别同赋湾字','盧照鄰','quantangshi','','卷3','輶轩遵上国，仙佩下灵关。
尊酒方无地，联绻喜暂攀。
离言欲赠策，高辨正连环。
野迳浮云断，荒池春草斑。
残花落古树，度鸟入澄湾。
欲敍他乡别，幽谷有绵蛮。','',''),('quantangshi-02819','还赴蜀中贻示京邑游好','盧照鄰','quantangshi','','卷3','籞宿花初满，章台柳向飞。
如何正此日，还望昔多违。
怅别风期阻，将乖云会稀。
歛衽辞丹阙，悬旗陟翠微。
野禽喧戍鼓，春草变征衣。
回顾长安道，关山起夕霏。','',''),('quantangshi-02820','初夏日幽庄','盧照鄰','quantangshi','','卷3','闻有高踪客，耿介坐幽庄。
林壑人事少，风烟鸟路长。
瀑水含秋气，垂藤引夏凉。
苗深全覆陇，荷上半侵塘。
钓渚青凫没，村田白鹭翔。
知君振奇藻，还嗣海隅芳。','',''),('quantangshi-02821','山庄休沐','盧照鄰','quantangshi','','卷3','兰署乘闲日，蓬扉狎遁栖。
龙柯疎玉井，凤叶下金堤。
川光摇水箭，山气上云梯。
亭幽闻唳鹤，窗晓听鸣鸡。
玉轸临风奏，琼浆映月携。
田家自有乐，谁肯谢青溪。','',''),('quantangshi-02822','山林休日田家','盧照鄰','quantangshi','','卷3','归休乘暇日，饁稼返秋场。
径草疏王彗，岩枝落帝桑。
耕田虞讼寝，凿井汉机忘。
戎葵朝委露，齐枣夜含霜。
南涧泉初冽，东篱菊正芳。
还思北窗下，高卧偃羲皇。','',''),('quantangshi-02823','宴梓州南亭得池字','盧照鄰','quantangshi','','卷3','二条开胜迹，大隐叶冲规。
亭阁分危岫，楼台遶曲池。
长薄秋烟起，飞梁古蔓垂。
水鸟翻荷叶，山虫咬桂枝。
游人惜将晚，公子爱忘疲。
愿得回三舍，琴尊长若斯。','',''),('quantangshi-02824','山行寄刘李二参军','盧照鄰','quantangshi','','卷3','万里烟尘客，三春桃李时。
事去纷无限，愁来不自持。
狂歌欲叹凤，失路反占龟。
草碍人行缓，花繁鸟度迟。
彼美参卿事，留连求友诗。
安知倦游子，两鬓渐如丝。','',''),('quantangshi-02825','首春贻京邑文士','盧照鄰','quantangshi','','卷3','寂寂罢将迎，门无车马声。
横琴答山水，披卷阅公卿。
忽闻岁云晏，倚杖出檐楹。
寒辞杨柳陌，春满凤皇城。
梅花扶院吐，兰叶遶阶生。
览镜改容色，藏书留姓名。
时来不假问，生死任交情。','',''),('quantangshi-02826','赠许左丞从驾万年宫','盧照鄰','quantangshi','','卷3','闻道上之回，诏跸下蓬莱。
中枢移北斗，左辖去南台。
黄山闻凤笛，清跸侍龙媒。
曳日朱旗卷，参云金障开。
朝参五城柳，夕宴柏梁杯。
汉畤光如月，秦祠听似雷。
寂寂芸香阁，离思独悠哉。','',''),('quantangshi-02827','晚渡渭桥寄示京邑游好','盧照鄰','quantangshi','','卷3','我行背城阙，驱马独悠悠。
寥落百年事，裴回万里忧。
途遥日向夕，时晚鬓将秋。
滔滔俯东逝，耿耿泣西浮。
长虹掩钓浦，落雁下星洲。
草变黄山曲，花飞清渭流。
迸水惊愁鹭，腾沙起狎鸥。
一赴清泥道，空思玄灞游。','',''),('quantangshi-02828','羁卧山中','盧照鄰','quantangshi','','卷3','卧壑迷时代，行歌任死生。
红颜意气尽，白璧故交轻。
涧户无人迹，山窗听鸟声。
春色缘岩上，寒光入溜平。
雪尽松帷暗，云开石路明。
夜伴饥鼯宿，朝随驯雉行。
度溪犹忆处，寻洞不知名。
紫书常日阅，丹药几年成。
扣钟鸣天鼓，烧香厌地精。
倘遇浮丘鹤，飘颻凌太清。','',''),('quantangshi-02829','酬张少府柬之','盧照鄰','quantangshi','','卷3','昔余与夫子，相遇汉川阴。
珠浦龙犹卧，檀溪马正沈。
价重瑶山曲，词惊丹凤林。
十年暌赏慰，万里隔招寻。
毫翰风期阻，荆衡云路深。
鹏飞俱望昔，蠖屈共悲今。
谁谓青衣道，还叹白头吟。
地接神仙磵，江连云雨岑。
飞泉如散玉，落日似悬金。
重以瑶华赠，空怀舞咏心。','',''),('quantangshi-02830','过东山谷口','盧照鄰','quantangshi','','卷3','不知名利险，辛苦滞皇州。
始觉飞尘倦，归来事绿畴。
桃源迷处所，桂树可淹留。
迹异人间俗，禽同海上鸥。
古苔依井被，新乳傍崖流。
野老堪成鹤，山神或化鸠。
泉鸣碧涧底，花落紫岩幽。
日暮飡龟壳，天寒御鹿裘。
不辨秦将汉，宁知春与秋。
多谢青溪客，去去赤松游。','',''),('quantangshi-02831','送幽州陈参军赴任寄呈乡曲父老','盧照鄰','quantangshi','','卷3','蓟北三千里，关西二十年。
冯唐犹在汉，乐毅不归燕。
人同黄鹤远，乡共白云连。
郭隗池台处，昭王尊酒前。
故人当已老，旧壑几成田。
红颜如昨日，衰鬓似秋天。
西蜀桥应毁，东周石尚全。
灞池水犹绿，榆关月早圆。
塞云初上雁，庭树欲销蝉。
送君之旧国，挥泪独澘然。','',''),('quantangshi-02832','哭金部韦郎中','盧照鄰','quantangshi','','卷3','金曹初受拜，玉地始含香。
翻同五日尹，遽见一星亡。
贺客犹扶路，哀人遂上堂。
歌筵长寂寂，哭位自苍苍。
岁时宾径断，朝暮雀罗张。
书留魏主阙，魂掩汉家牀。
徒令永平帝，千载罢撞郎。','',''),('quantangshi-02833','哭明堂裴主簿','盧照鄰','quantangshi','','卷3','缔欢三十载，通家数百年。
潘杨称代穆，秦晋忝姻连。
风云洛阳道，花月茂陵田。
相悲共相乐，交骑复交筵。
始谓调金鼎，如何掩玉泉。
黄公酒炉处，青眼竹林前。
故琴无复雪，新树但生烟。
遽痛兰襟断，徒令宝剑悬。
客散同秋叶，人亡似夜川。
送君一长恸，松台路几千。','',''),('quantangshi-02834','同崔录事哭郑员外','盧照鄰','quantangshi','','卷3','文学秋天远，郎官星位尊。
伊人表时彦，飞誉满司存。
楚席光文雅，瑶山侍讨论。
凤词凌汉阁，龟辩罩周园。
已陪东岳驾，将逝北溟鲲。
如何万化尽，空叹九飞魂。
白马西京驿，青松北海门。
夜台无晓箭，朝奠有虚尊。
一代儒风没，千年陇雾昏。
梁山送夫子，湘水吊王孙。
仆本多悲泪，沾裳不待猿。
闻君绝弦曲，吞恨更无言。','',''),('quantangshi-02835','登玉清','盧照鄰','quantangshi','','卷3','绝顶横临日，孤峰半倚天。
裴回拜真老，万里见风烟。','',''),('quantangshi-02836','曲池荷','盧照鄰','quantangshi','','卷3','浮香绕曲岸，圆影覆华池。
常恐秋风早，飘零君不知。','',''),('quantangshi-02837','浴浪鸟','盧照鄰','quantangshi','','卷3','独舞依磐石，羣飞动轻浪。
奋迅碧沙前，长怀白云上。','',''),('quantangshi-02838','临阶竹','盧照鄰','quantangshi','','卷3','封霜连锦砌，防露拂瑶阶。
聊将仪凤质，暂与俗人谐。','',''),('quantangshi-02839','含风蝉','盧照鄰','quantangshi','','卷3','高情临爽月，急响送秋风。
独有危冠意，还将衰鬓同。','',''),('quantangshi-02840','葮川独泛','盧照鄰','quantangshi','','卷3','倚棹春江上，横舟石岸前。
山瞑行人断，迢迢独泛仙。','',''),('quantangshi-02841','送二兄入蜀','盧照鄰','quantangshi','','卷3','关山客子路，花柳帝王城。
此中一分手，相顾怜无声。','',''),('quantangshi-02842','宿玄武二首 一','盧照鄰','quantangshi','','卷3','方池开晓色，圆月下秋阴。
已乘千里兴，还抚一弦琴。','',''),('quantangshi-02843','宿玄武二首 二','盧照鄰','quantangshi','','卷3','庭摇北风柳，院绕南溟禽。
累宿恩方重，穷秋叹不深。','',''),('quantangshi-02844','九陇津集','盧照鄰','quantangshi','','卷3','落落树阴紫，澄澄水华碧。
复有翻飞禽，裴回疑曳舃。','',''),('quantangshi-02845','游昌化山精舍','盧照鄰','quantangshi','','卷3','宝地乘峰出，香台接汉高。
稍觉真途近，方知人事劳。','',''),('quantangshi-02846','登封大酺歌四首 一','盧照鄰','quantangshi','','卷3','明君封禅日重光，天子垂衣历数长。
九州四海常无事，万岁千秋乐未央。','',''),('quantangshi-02847','登封大酺歌四首 二','盧照鄰','quantangshi','','卷3','日观仙云随凤辇，天门瑞雪照龙衣。
繁弦绮席方终夜，妙舞清歌欢未归。','',''),('quantangshi-02848','登封大酺歌四首 三','盧照鄰','quantangshi','','卷3','翠凤逶迤登介丘，仙鹤裴回天上游。
借问干封何所乐，人皆寿命得千秋。','',''),('quantangshi-02849','登封大酺歌四首 四','盧照鄰','quantangshi','','卷3','千年圣主应昌期，万国淳风王化基。
请比上古无为代，何如今日太平时。','',''),('quantangshi-02850','九月九日登玄武山','盧照鄰','quantangshi','','卷3','九月九日眺山川，归心归望积风烟。
他乡共酌金花酒，万里同悲鸿雁天。','',''),('quantangshi-02851','句','盧照鄰','quantangshi','','卷3','城狐尾独束，山鬼面参覃。','',''),('quantangshi-02852','少年行','李百藥','quantangshi','','卷3','少年飞翠盖，上路勒金镳。
始酌文君酒，新吹弄玉箫。
少年不欢乐，何以尽芳朝。
千金笑里面，一搦掌中腰。
挂缨岂惮宿，落珥不胜娇。
寄语少年子，无辞归路遥。','',''),('quantangshi-02853','渡汉江','李百藥','quantangshi','','卷3','东流既弥弥，南纪信滔滔。
水激沈碑岸，波骇弄珠皐。
含星映浅石，浮盖下奔涛。
溜阔霞光近，川长晓气高。
樯乌转轻翼，戏鸟落风毛。
客心既多绪，长歌且代劳。','',''),('quantangshi-02854','秋晚登古城','李百藥','quantangshi','','卷3','日落征途远，怅然临古城。
颓墉寒雀集，荒堞晚乌惊。
萧森灌木上，迢遰孤烟生。
霞景焕余照，露气澄晚清。
秋风转摇落，此志安可平。','',''),('quantangshi-02855','途中述怀','李百藥','quantangshi','','卷3','伯喈迁塞北，亭伯之辽东。
伊余何为客，独守云台中。
途遥已日暮，时泰道斯穷。
拔心悲岸草，半死落岩桐。
目送衡阳雁，情伤江上枫。
福兮良所伏，今也信难通。
丈夫自有志，宁伤官不公。','',''),('quantangshi-02856','郢城怀古','李百藥','quantangshi','','卷3','客心悲暮序，登墉瞰平陆。
林泽窅芊緜，山川郁重复。
王公资设险，名都拒江隩。
方城次北门，溟海穷南服。
长策挫吴豕，雄图竞周鹿。
万乘重沮漳，九鼎轻伊谷。
大搜云梦掩，壮观章华筑。
人世更盛衰，吉凶良倚伏。
遽见邻交断，仍覩贤臣逐。
南风忽不竞，西师日侵蹙。
运圯属驰驱，时屯恣敲朴。
莫救夷陵火，无复秦庭哭。
鄢郢遂丘墟，风尘俄惨黩。
狐兔时游践，霜露日霑沐。
钓渚故池平，神台层宇覆。
阵云埋夏首，穷阴惨荒谷。
怅矣舟壑迁，悲哉年祀倏。
虽异三春望，终伤千里目。','',''),('quantangshi-02857','晚渡江津','李百藥','quantangshi','','卷3','寂寂江山晚，苍苍原野暮。
秋气怀易悲，长波淼难溯。
索索风叶下，离离早鸿度。
丘壑列夕阴，葭菼凝寒雾。
日落亭皐远，独此怀归慕。','',''),('quantangshi-02858','王师渡汉水经襄阳','李百藥','quantangshi','','卷3','导漾疏源远，归海会流长。
延波接荆梦，通望迩沮漳。
高岸沈碑影，曲溆丽珠光。
云昏翠岛没，水广素涛扬。
阅川已多叹，遐睇几增伤。
临溪犹驻马，望岘欲霑裳。
乔木下寒叶，亭林落晓霜。
山公不可遇，谁与访高阳。','',''),('quantangshi-02859','谒汉高庙','李百藥','quantangshi','','卷3','纂尧灵命启，灭楚余闰终。
飞名膺帝箓，沈迹韫神功。
瑞气朝浮砀，祥符夜告丰。
抑扬驾人杰，叱咤掩时雄。
缔构三灵改，经纶五纬同。
干戈革宇内，声教尽寰中。
运谢年逾远，魂归道未穷。
树碑留故邑，抗殿表祠宫。
沐兰祈泗上，谒帝动深衷。
英威肃如在，文物杳成空。
竹皮聚寒径，枌社落霜丛。
萧索阴云晚，长川起大风。','',''),('quantangshi-02860','登叶县故城谒沈诸梁庙','李百藥','quantangshi','','卷3','总辔临秋原，登城望寒日。
烟霞共掩映，林野俱萧瑟。
楚塞郁不穷，吴山高渐出。
客行殊未已，沐澡期终吉。
椒桂奠芳樽，风云下虚室。
馆宇肃而静，神心康且逸。
伊我非真龙，勿惊疲朽质。','',''),('quantangshi-02861','安德山池宴集','李百藥','quantangshi','','卷3','朝宰论思暇，高宴临方塘。
云飞凤台管，风动令君香。
细草开金埒，流霞泛羽觞。
虹桥分水态，镜石引菱光。
上才同振藻，小技谬连章。
怀音自兰室，徐步返山庄。','',''),('quantangshi-02862','和许侍郎游昆明池','李百藥','quantangshi','','卷3','神池望不极，沧波接远天。
仪星似河汉，落景类虞泉。
年深平馆宇，道泰偃戈船。
差池下凫雁，掩映生云烟。
浪花开已合，风文直且连。
税马金堤外，横舟石岸前。
羽觞倾绿蚁，飞日落红鲜。
积水浮深智，明珠曜雅篇。
大鲸方远击，沈灰独未然。
知君啸俦侣，短翮徒联翩。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-02863','赋得魏都','李百藥','quantangshi','','卷3','炎运精华歇，清都宝命开。
帝里三方盛，王庭万国来。
玄武疏遥磴，金凤上层台。
乍进仙童药，时倾避暑杯。
南馆招奇士，西园引上才。
还惜刘公干，疲病清漳隈。','',''),('quantangshi-02864','赋礼记','李百藥','quantangshi','','卷3','玉帛资王会，郊丘叶圣情。
重广开环堵，至道轶金籝。
盘薄依厚地，遥裔腾太清。
方悦升中礼，足以慰余生。','',''),('quantangshi-02865','奉和正日临朝应诏','李百藥','quantangshi','','卷3','化历昭唐典，承天顺夏正。
百灵警朝禁，三辰扬斾旌。
充庭富礼乐，高宴齿簪缨。
献寿符万岁，移风韵九成。','',''),('quantangshi-02866','妾薄命','李百藥','quantangshi','','卷3','团扇秋风起，长门夜月明。
羞闻拊背入，恨说舞腰轻。
太常先已醉，刘君恒带酲。
横陈每虚设，吉梦竟何成。','',''),('quantangshi-02867','火凤词二首 一','李百藥','quantangshi','','卷3','歌声扇后出，妆影镜中轻。
未能令掩笑，何处欲障声。
知音自不惑，得念是分明。
莫见双嚬歛，疑人含笑情。','',''),('quantangshi-02868','火凤词二首 二','李百藥','quantangshi','','卷3','佳人靓晚妆，清唱动兰房。
影出含风扇，声飞照日梁。
娇嚬眉际歛，逸韵口中香。
自有横陈会，应怜秋夜长。','',''),('quantangshi-02869','奉和初春出游应令','李百藥','quantangshi','','卷3','鸣笳出望苑，飞盖下芝田。
水光浮落照，霞彩淡轻烟。
柳色迎三月，梅花隔二年。
日斜归骑动，余兴满山川。','',''),('quantangshi-02870','寄杨公','李百藥','quantangshi','','卷3','公子盛西京，光华早着名。
分庭接游士，虚馆待时英。
高阁浮香出，长廊宝钏鸣。
面花无隔笑，歌扇不障声。','',''),('quantangshi-02871','戏赠潘徐城门迎两新妇','李百藥','quantangshi','','卷3','秦晋称旧匹，潘徐有世亲。
三星宿已会，四德婉而嫔。
霞光鬓里薄，月影扇中新。
年华与妆面，共作一芳春。','',''),('quantangshi-02872','送别','李百藥','quantangshi','','卷3','眷言一杯酒，凄怆起离忧。
夜花飘露气，暗水急还流。
雁行遥上月，虫声迥映秋。
明日河梁上，谁与论仙舟。','',''),('quantangshi-02873','雨后','李百藥','quantangshi','','卷3','晚来风景丽，晴初物色华。
薄云向空尽，轻虹逐望斜。
后窗临岸竹，前阶枕浦沙。
寂寥无与晤，尊酒论风花。','',''),('quantangshi-02874','文德皇后挽歌','李百藥','quantangshi','','卷3','裴回两仪殿，怅望九成台。
玉辇终辞宴，瑶筐遂不开。
野旷阴风积，川长思鸟来。
寒山寂已暮，虞殡有余哀。','',''),('quantangshi-02875','咏蝉','李百藥','quantangshi','','卷3','清心自饮露，哀响乍吟风。
未上华冠侧，先惊翳叶中。','',''),('quantangshi-02876','咏萤火示情人','李百藥','quantangshi','','卷3','窗里怜灯暗，阶前畏月明。
不辞逢露湿，祗为重宵行。','',''),('quantangshi-02877','春眺','李百藥','quantangshi','','卷3','疲疴荷拙患，沦踬合幽襟。
栖息在何处？丘中鸣素琴。','',''),('quantangshi-02878','句','李百藥','quantangshi','','卷3','今日持团扇，非是为秋风。','',''),('quantangshi-02879','奉和太子纳妃太平公主出降','劉禕之','quantangshi','','卷3','梦梓光青陛，穠桃蔼紫宫。
德优宸念远，礼备国姻崇。
万户声明发，三条骑吹通。
香轮送重景，彩斾引仙虹。','',''),('quantangshi-02880','奉和别越王','劉禕之','quantangshi','','卷3','周屏辞金殿，梁骖整玉珂。
管声依折柳，琴韵动流波。
鹤盖分阴促，龙轩别念多。
延襟小山路，还起大风歌。','',''),('quantangshi-02881','酬郑沁州','劉禕之','quantangshi','','卷3','麒阁一代良，熊轩千里躅。
缉图昭国典，按部留宸瞩。
匪厌承明庐，伫兼司隶局。
芸书暂辍载，竹使方临俗。
节变风绪高，秋深露华溽。
寒山敛轻霭，霁野澄初旭。
已切长年悲，谁堪岐路促。
遥林征马迅，别馆嘶骖局。
雅赠响摐金，索居暌倚玉。
凄断离鸿引，劳歌思足曲。','',''),('quantangshi-02882','孝敬皇帝挽歌','劉禕之','quantangshi','','卷3','戒奢虚蜃辂，锡号纪鸿名。
地叶苍梧野，途经紫聚城。
重照掩寒色，晨飙断曙声。
一随仙骥远，霜雪愁阴生。','',''),('quantangshi-02883','九成宫秋初应诏','劉禕之','quantangshi','','卷3','帝圃疏金阙，仙台驻玉銮。
野分鸣鸑岫，路接宝鸡坛。
林树千霜积，山宫四序寒。
蝉急知秋早，莺疎觉夏阑。
怡神紫气外，凝睇白云端。
舜海词波发，空惊游圣难。','',''),('quantangshi-02884','奉和别鲁王','李敬玄','quantangshi','','卷3','绿车旋楚服，丹跸伫秦川。
珠皐转归骑，金岸引行旃。
一朝限原隰，千里间风烟。
莺喧上林谷，凫响御沟泉。
断云移鲁盖，离歌动舜弦。
别念凝神扆，崇恩洽玳筵。
顾惟慙叩寂，徒自仰钧天。','',''),('quantangshi-02885','奉和别越王','李敬玄','quantangshi','','卷3','飞盖回兰坂，宸襟伫柏梁。
别馆分泾渭，归路指衡漳。
关山通曙色，林籞徧春光。
帝念纡千里，词波照五潢。','',''),('quantangshi-02886','奉和别越王','張大安','quantangshi','','卷3','盛藩资右戚，连蕚重皇情。
离襟怆睢苑，分途指邺城。
丽日开芳甸，佳气积神京。
何时骖驾入，还见谒承明。','',''),('quantangshi-02887','奉和太子纳妃太平公主出降','萬頃','quantangshi','','卷3','象辂初乘雁，璇宫早结褵。
离元应春夕，帝子降秋期。
鸣瑜合清响，冠玉丽穠姿。
和声跻凤掖，交影步鸾墀。','',''),('quantangshi-02888','奉和春日池台','萬頃','quantangshi','','卷3','日影飞花殿，风文积草池。
凤楼通夜敞，虬辇望春移。','',''),('quantangshi-02889','奉和春日二首 一','萬頃','quantangshi','','卷3','花轻蘂乱仙人杏，叶密莺喧帝女桑。
飞云阁上春应至，明月楼中夜未央。','',''),('quantangshi-02890','奉和春日二首 二','萬頃','quantangshi','','卷3','凤辇迎风乘紫阁，鸾车避日转彤闱。
中堂促管淹春望，后殿清歌开夜扉。','',''),('quantangshi-02891','奉和太子纳妃太平公主出降','郭正一','quantangshi','','卷3','桂宫初服冕，兰掖早升筓。
礼盛亲迎晋，声芬出降齐。
金龟开瑞钮，宝翟上仙袿。
转扇承宵月，扬旌照夕霓。','',''),('quantangshi-02892','奉和太子纳妃太平公主出降三首 一','胡元範','quantangshi','','卷3','帝子威仪绝，储妃礼度优。
叠鼓陪仙观，凝笳翼画輈。
郁郁神香满，奕奕彩云浮。
排空列锦罽，腾欢溢皇州。','',''),('quantangshi-02893','奉和太子纳妃太平公主出降三首 二','胡元範','quantangshi','','卷3','金闺未息火，玉树钟天爱。
月路饰还装，星津动归佩。
紫极流宸渥，清规伫慈诲。
恩波洽九流，光辉轶千载。','',''),('quantangshi-02894','奉和太子纳妃太平公主出降三首 三','胡元範','quantangshi','','卷3','列席诏亲贤，式宴坐神仙。
圣文飞圣笔，天乐奏钧天。
曲池涵瑞景，文宇孕祥烟。
小臣同百兽，率舞悦尧年。','',''),('quantangshi-02895','奉和太子纳妃太平公主出降','任希古','quantangshi','','卷3','帝子升青陛，王姬降紫宸。
星光移杂佩，月彩荐重轮。
龙旌翻地杪，凤管扬天滨。
槐阴浮浅濑，葆吹翼轻尘。','',''),('quantangshi-02896','和东观羣贤七夕临泛昆明池','任希古','quantangshi','','卷3','秋风始摇落，秋水正澄鲜。
飞眺牵牛渚，激赏镂鲸川。
岸珠沦晓魄，池灰敛曙烟。
泛查分写汉，仪星别构天。
云光波处动，日影浪中悬。
惊鸿絓蒲弋，游鲤入庄筌。
萍叶疑江上，菱花似镜前。
长林代轻幄，细草即芳筵。
文峰开翠潋，笔海控清涟。
不挹兰樽圣，空仰桂舟仙。','',''),('quantangshi-02897','和左仆射燕公春日端居述怀','任希古','quantangshi','','卷3','丰野光三杰，嬀庭赞五臣。
绨缃歌美誉，丝竹咏芳尘。
圣历开环象，昌年降甫申。
高门非舍筑，华构岂垂纶。
凤邸抟霄翰，龙池跃海鳞。
玉鼎升黄阁，金章谒紫宸。
礼闱通政本，文昌总国均。
调风振薄俗，清教叙彝伦。
星回应缇管，日御警寅宾。
叶上曾槐变，花发小堂春。
思挂五都冕，言访北山巾。
赫赫容台上，千祀耀平津。','',''),('quantangshi-02898','和长孙祕监伏日苦热','任希古','quantangshi','','卷3','玉署三时晓，金羁五日归。
北林开逸径，东阁敞闲扉。
池镜分天色，云峰减日辉。
游鳞映荷聚，惊翰遶林飞。
披襟[扬]子宅，舒啸仰重闱。','',''),('quantangshi-02899','和李公七夕','任希古','quantangshi','','卷3','落日照高牖，凉风起庭树。
悠悠天宇平，昭昭月华度。
开轩卷绡幕，延首曦云路。
层汉有灵妃，仙居无与晤。
履化悲流易，临川怨迟暮。
昔从九春徂，方此三秋遇。
瑶驾越星河，羽盖凝珠露。
便妍耀井色，窈窕凌波步。
始阅故人新，俄见新人故。
掩泪收机石，衔啼襞纨素。
惆怅何伤已，裴回劳永慕。
无由西北归，空自东南顾。','',''),('quantangshi-02900','和长孙祕监七夕','任希古','quantangshi','','卷3','二秋叶神媛，七夕望仙妃。
影照河阳妓，色丽平津闱。
鹊桥波里出，龙车霄外飞。
露泫低珠佩，云移荐锦衣。
更深黄月落，夜久靥星稀。
空接灵台下，方恧辨支机。','',''),('quantangshi-02901','奉和太子纳妃太平公主出降三首 一','裴守真','quantangshi','','卷3','瑜佩升青殿，穠华降紫微。
还如桃李发，更似凤皇飞。
金屋真离象，瑶台起婺徽。
彩缨纷碧坐，[缋]羽泛褕衣。','',''),('quantangshi-02902','奉和太子纳妃太平公主出降三首 二','裴守真','quantangshi','','卷3','云路移彤辇，天津转明镜。
仙珠照乘归，宝月重轮映。
望园嘉宴洽，主第欢娱盛。
丝竹扬帝熏，簪裾奉宸庆。','',''),('quantangshi-02903','奉和太子纳妃太平公主出降三首 三','裴守真','quantangshi','','卷3','藂云霭晓光，湛露曦朝阳。
天文天景丽，睿藻睿词芳。
玉庭散秋色，银宫生夕凉。
太平超邃古，万寿乐无疆。','',''),('quantangshi-02904','奉和圣制过温汤','楊思玄','quantangshi','','卷3','丰城观汉迹，温谷幸秦余。
地接幽王垒，涂分郑国渠。
风威肃文卫，日彩镜雕舆。
远岫凝氛重，寒丛对影疎。
回瞻汉章阙，佳气满宸居。','',''),('quantangshi-02905','奉和别鲁王','楊思玄','quantangshi','','卷3','元王诗传博，文后宠灵优。
鹤盖动宸眷，龙章送远游。
函关疏别道，灞岸引行舟。
北林分苑树，东流溢御沟。
鸟声含羽碎，骑影曳花浮。
圣泽九垓普，天文七曜周。
方图献雅乐，簪带奉鸣球。','',''),('quantangshi-02906','奉和圣制过温汤','王德真','quantangshi','','卷3','握图开万宇，属圣启千年。
骊阜疏缇骑，惊鸿映彩旃。
玉霜鸣凤野，金阵藻龙川。
祥烟聚危岫，德水溢飞泉。
停舆兴睿览，还举大风篇。','',''),('quantangshi-02907','奉和圣制过温汤','鄭義真','quantangshi','','卷3','洛川方驻跸，丰野暂停銮。
汤泉恒独涌，温谷岂知寒。
漏鼓依岩畔，相风出树端。
岭烟遥聚草，山月迥临鞍。
日用诚多幸，天文遂仰观。','',''),('quantangshi-02908','奉和展礼岱宗涂经濮济','蕭楚材','quantangshi','','卷3','拂汉星旗转，分霄日羽明。
将追会阜迹，更勒岱宗铭。
林戈咽济岸，兽鼓震河庭。
叶箭凌寒矫，鸟弓望晓惊。
已降汾水作，仍深迎渭情。','',''),('quantangshi-02909','奉和展礼岱宗涂经濮济','薛克構','quantangshi','','卷3','龙图冠胥陆，凤驾指云亭。
非烟泛济浦，绿字启河汀。
画裳晨应月，文戟曙分星。
四田巡揖礼，三驱道契经。
行欣奉万岁，窃拚偶千龄。','',''),('quantangshi-02910','日暮望泾水','徐珩','quantangshi','','卷3','导源径陇阪，属汭贯嬴都。
下濑波常急，回圻溜亦纡。
毒流秦卒毙，泥粪汉田腴。
独有迷津客，怀归轸暮途。','',''),('quantangshi-02911','赠韩思彦','賀遂亮','quantangshi','','卷3','意气百年内，平生一寸心。
欲交天下士，未面已虚襟。
君子重名义，直道冠衣簪。
风云行可托，怀抱自然深。
落霞静霜景，坠叶下风林。
若上南登岸，希访北山岑。','',''),('quantangshi-02912','酬贺遂亮','韓思彥','quantangshi','','卷3','古人一言重，尝谓百年轻。
今投欢会面，顾盼尽平生。
簪裾非所托，琴酒冀相倂。
累日同游处，通宵欵素诚。
霜飘知柳脆，雪冒觉松贞。
愿言何所道，幸得岁寒名。','',''),('quantangshi-02913','自御史左授山阳丞','魏求己','quantangshi','','卷3','朝升照日槛，夕次下乌台。
风竿一眇邈，月树几裴回。
翼向高标敛，声随下调哀。
怀燕首自白，非是为年催。','',''),('quantangshi-02914','赠右台监察邓茂迁左台殿中','劉懷一','quantangshi','','卷3','惟昔参多士，无双仰异才。
鹰鹯同效逐，鵷鹭忝游陪。
入仕光三命，迁荣历二台。
隔墙钦素躅，对问限清埃。
紫署春光早，兰闱曙色催。
谁言夕鸟至，空想邓林隈。','',''),('quantangshi-02915','湘川新曲二首 一','杜易簡','quantangshi','','卷3','昭潭深无底，橘洲浅而浮。
本欲凌波去，翻为目成留。
愿君稍弭檝，无令贱妾羞。','',''),('quantangshi-02916','湘川新曲二首 二','杜易簡','quantangshi','','卷3','二八相招携，采菱渡前溪。
弱腕随桡起，纤腰向舸低。
自解看花笑，憎闻染竹啼。','',''),('quantangshi-02917','落成会咏一首','陳元光','quantangshi','','卷3','泉潮天万里，一镇屹天中。
筮宅龙钟地，承恩燕翼宫。
环堂巍岳秀，带砺大江雄。
轮奂云霄望，晶华日月通。
凌烟乔木茂，献宝介圭崇。
昆俊歌常棣，民和教即戎。
盘庚迁美士，陶侃效兼庸。
设醴延张老，开轩礼吕蒙。
无孤南国仰，庶补圣皇功。','',''),('quantangshi-02918','示珦','陳元光','quantangshi','','卷3','恩衔枫陛渥，策向桂渊弘。
载笔沿儒习，持弓缵祖风。
祛灾剿猛虎，溥德翊飞龙。
日阅书开士，星言驾劝农。
勤劳思命重，戏谑逐时空。
百粤雾纷满，诸戎泽普通。
愿言加壮努，勿坐鬓霜蓬。','',''),('quantangshi-02919','太母魏氏半径题石','陳元光','quantangshi','','卷3','乔岳标仙迹，玄扃妥寿姬。
乌号非岭海，鹤仰向京师。
系牒公侯裔，悬弧将相儿。
清贞蜚简籍，规范肃门楣。
万里提兵路，三年报母慈。
劒埋龙守壤，石卧虎司碑。
忧阕情犹结，祥回禫届期。
竹符忠介凛，桐杖孝思凄。
许史峋嶙篆，曹侯感旧诗。
鸿蒙山暝启，骏彩德昭垂。
华表瑶池冥，清漳玉树枝。
昭题盟岳渎，展墓庆重熙。','',''),('quantangshi-02920','和陈元光平潮寇诗','許天正','quantangshi','','卷3','抱磴从天上，驱车返岭东。
气昂无丑虏，策妙诎羣雄。
飞絮随风散，余氛响日镕。
长戈收百甲，聚骑破千重。
落劒惟戎首，游绳系胁从。
四野无坚壁，羣生未化融。
龙湖膏泽下，早晚徧枯穷。','',''),('quantangshi-02921','咏牛应制','許圉師','quantangshi','','卷3','逸足还同骥，奇毛自偶麟。
欲知花迹远，云影入天津。','',''),('quantangshi-02922','答户部员外贺遂涉戏赠','趙謙光','quantangshi','','卷3','锦帐随情设，金炉任意熏。
惟愁员外署，不应列星文。','',''),('quantangshi-02923','送苏尚书赴益州','鄭惟忠','quantangshi','','卷3','离忧将岁尽，归望逐春来。
庭花如有意，留艳待人开。','',''),('quantangshi-02924','咏燕','張鷟','quantangshi','','卷3','变石身犹重，衔泥力尚微。
从来赴甲第，两起一双飞。','',''),('quantangshi-02925','岭外守岁','李福業','quantangshi','','卷3','冬去更筹尽，春随斗柄回。
寒暄一夜隔，客鬓两年催。','',''),('quantangshi-02926','奉和进船洛水应制','薛眘惑','quantangshi','','卷3','禁园纡睿览，仙棹叶宸游。
洛北风花树，江南彩画舟。
荣生兰蕙草，春入凤皇楼。
兴尽离宫暮，烟光起夕流。','',''),('quantangshi-02927','奉和九月九日应制','賀敱','quantangshi','','卷3','商飙凝素龠，玄览贲黄图。
晓霜惊断雁，晨吹结栖乌。
寒花低岸菊，凉叶下庭梧。
泽宫申旧典，相圃叶前模。
玉砌分雕戟，金沟转镂衢。
带星飞夏箭，映月上轩弧。
庆展簪裾洽，恩融雨露濡。
天文发丹篆，宝思掩玄珠。
承欢徒拚舞，负弛窃忘躯。','',''),('quantangshi-02928','奉和圣制夏日游石淙山','狄仁傑','quantangshi','','卷3','宸晖降望金舆转，仙路峥嵘碧涧幽。
羽杖遥临鸾鹤驾，帷宫直坐凤麟洲。
飞泉洒液恒疑雨，密树含凉镇似秋。
老臣预陪悬圃宴，余年方共赤松游。','',''),('quantangshi-02929','修书院学士奉勅宴梁王宅','魏元忠','quantangshi','','卷3','大君敦宴赏，万乘下梁园。
酒助闲平乐，人霑雨露恩。
荣光开帐殿，佳气满旌门。
愿陪南岳寿，长奉北宸樽。','',''),('quantangshi-02930','银潢宫侍宴应制','魏元忠','quantangshi','','卷3','别殿秋云上，离宫夏景移。
寒风生玉树，凉气下瑶池。
堑花仍吐叶，岩木尚抽枝。
愿奉南山寿，千秋长若斯。','',''),('quantangshi-02931','折杨柳','韋承慶','quantangshi','','卷3','万里边城地，三春杨柳节。
叶似镜中眉，花如关外雪。
征人远乡思，倡妇高楼别。
不忍掷年华，含情寄攀折。','',''),('quantangshi-02932','寒食应制','韋承慶','quantangshi','','卷3','凤城春色晚，龙禁早晖通。
旧火收槐燧，余寒入桂宫。
莺啼正隐叶，鸡鬬始开笼。
蔼蔼瑶山满，仙歌始乐风。','',''),('quantangshi-02933','凌朝浮江旅思','韋承慶','quantangshi','','卷3','天晴上初日，春水送孤舟。
山远疑无树，潮平似不流。
岸花开且落，江鸟没还浮。
羁望伤千里，长歌遣四愁。','',''),('quantangshi-02934','直中书省','韋承慶','quantangshi','','卷3','清切凤皇池，扶疎鸡树枝。
唯应集鸾鹭，何为宿羁雌。
大造干坤辟，深恩雨露垂。
昆蚑皆含养，驽骀亦驱驰。
木偶翻为用，芝泥忽滥窥。
九思空自勉，五字本无施。
徒喜逢千载，何阶答二仪。
萤光向日尽，蚊力负山疲。
禁宇庭除阔，闲宵钟箭移。
暗花临户发，残月下帘欹。
白发随年改，丹心为主披。
命将时共泰，言与行俱危。
寄谢巢由客，尧年正在斯。','',''),('quantangshi-02935','南行别弟','韋承慶','quantangshi','','卷3','澹澹长江水，悠悠远客情。
落花相与恨，到地一无声。','',''),('quantangshi-02936','南中咏雁','韋承慶','quantangshi','','卷3','万里人南去，三春雁北飞。
不知何岁月？得与尔同归。','',''),('quantangshi-02937','江楼','韋承慶','quantangshi','','卷3','独酌芳春酒，登楼已半曛。
谁惊一行雁，冲断过江云。','',''),('quantangshi-02938','凝碧池侍宴看竞渡应制','李懷遠','quantangshi','','卷3','上苑清銮路，高居重豫游。
前对芙蓉沼，傍临杜若洲。
地如玄扈望，波似洞庭秋。
列筵飞翠斝，分曹戏鷁舟。
湍高棹影没，岸近榜歌遒。
舞曲依鸾殿，箫声下凤楼。
忽闻天上乐，疑逐海查流。','',''),('quantangshi-02939','奉和九月九日登慈恩寺浮图应制','崔日用','quantangshi','','卷3','紫宸欢每洽，绀殿法初隆。
菊泛延龄酒，兰吹解愠风。
咸英调正乐，香梵徧秋空。
临幸浮天瑞，重阳日再中。','',''),('quantangshi-02940','奉和圣制送张说巡边','崔日用','quantangshi','','卷3','轩相推风后，周官重夏卿。
庙谋能允迪，韬略又纵横。
吉日四黄马，宣王六月兵。
拟清鸡鹿塞，先指朔方城。
列将怀威抚，匈奴畏盛名。
去当推毂送，来伫出郊迎。
绝漠蓬将断，华筵槿正荣。
壮心看舞劒，别绪应悬旌。
睿锡承优旨，干文复宠行。
暂劳期永逸，赫矣振天声。','',''),('quantangshi-02941','奉和立春游苑迎春应制','崔日用','quantangshi','','卷3','乘时迎气正璇衡，灞浐烟氛向晚清。
剪绮裁红妙春色，宫梅殿柳识天情。
瑶筐彩燕先呈端，金缕晨鸡未学鸣。
圣泽阳和宜宴乐，年年捧日向东城。','',''),('quantangshi-02942','奉和圣制春日幸望春宫应制','崔日用','quantangshi','','卷3','东郊风物正熏馨，素浐凫鹥戏绿汀。
凤阁斜通平乐观，龙旗直逼望春亭。
光风摇动兰英紫，淑气依迟柳色青。
渭浦明晨修禊事，羣公倾贺水心铭。','',''),('quantangshi-02943','奉和人日重宴大明宫恩赐彩缕人胜应制','崔日用','quantangshi','','卷3','新年宴乐坐东朝，钟鼓铿鍠大乐调。
金屋瑶筐开宝胜，花笺彩笔颂春椒。
曲池苔色冰前液，上苑梅香雪里娇。
宸极此时飞圣藻，微臣窃拚预闻韶。','',''),('quantangshi-02944','奉和圣制龙池篇','崔日用','quantangshi','','卷3','龙兴白水汉兴符，圣主时乘运斗枢。
岸上䒠茸五花树，波中的皪千金珠。
操环昔闻迎夏启，发匣先来瑞有虞。
风色云光随隐见，赤云神化象江湖。','',''),('quantangshi-02945','夜宴安乐公主宅','崔日用','quantangshi','','卷3','银烛金屏坐碧堂，只言河汉动神光。
主家盛时欢不极，才子能歌夜未央。','',''),('quantangshi-02946','饯唐永昌','崔日用','quantangshi','','卷3','洛阳桴鼓今不鸣，朝野咸推重太平。
冬至冰霜俱怨别，春来花鸟若为情。','',''),('quantangshi-02947','奉和送金城公主适西蕃','崔日用','quantangshi','','卷3','圣后经纶远，谋臣计画多。
受降追汉策，筑馆计戎和。
俗化乌孙垒，春生积石河。
六龙今出饯，双鹤愿为歌。','',''),('quantangshi-02948','句','崔日用','quantangshi','','卷3','彼名流兮左氏癖，意玄远兮冠今夕。','',''),('quantangshi-02949','奉和人日清晖阁宴羣臣遇雪应制','宗楚客','quantangshi','','卷3','窈窕神仙阁，参差云汉间。
九重中叶启，七日早春还。
太液天为水，蓬莱雪作山。
今朝上林树，无处不堪攀。','',''),('quantangshi-02950','安乐公主移入新宅侍宴应制','宗楚客','quantangshi','','卷3','星桥他日创，仙牓此时开。
马向铺钱埒，箫闻弄玉台。
人同卫叔美，客似长卿才。
借问游天汉，谁能取石回。','',''),('quantangshi-02951','正月晦日侍宴浐水应制赋得长字','宗楚客','quantangshi','','卷3','御辇出明光，乘流泛羽觞。
珠胎随月减，玉漏与年长。
寒尽梅犹白，风迟柳未黄。
日斜旌骑转，休气满林塘。','',''),('quantangshi-02952','奉和幸上阳宫侍宴应制','宗楚客','quantangshi','','卷3','紫庭金凤阙，丹禁玉鸡川。
似立蓬瀛上，疑游昆阆前。
鸟将歌合转，花共锦争鲜。
湛露飞尧酒，熏风入舜弦。
水光摇落日，树色带晴烟。
向夕回雕辇，佳气满岩泉。','',''),('quantangshi-02953','奉和幸安乐公主山庄应制','宗楚客','quantangshi','','卷3','玉楼银牓枕严城，翠盖红旗列禁营。
日映层岩图画色，风摇杂树管弦声。
水边重阁含飞动，云里孤峰类削成。
幸覩八龙游阆苑，无劳万里访蓬瀛。','',''),('quantangshi-02954','奉和圣制喜雪应制','宗楚客','quantangshi','','卷3','飘飘瑞雪下山川，散漫轻飞集九埏。
似絮还飞垂柳陌，如花更绕落梅前。
影随明月团纨扇，声将流水杂鸣弦。
共荷神功万庾积，终朝圣寿百千年。','',''),('quantangshi-02955','句','宗楚客','quantangshi','','卷3','竹町罗千卫，兰莛降两宫。
七萃銮舆动，千年瑞检开。
彩旗临凤阙，翠幕遶龟津。','',''),('quantangshi-02956','奉和九日幸临渭亭登高应制得晖字','蘇瓌','quantangshi','','卷3','重阳早露曦，睿赏瞰秋矶。
菊气先熏酒，萸香更袭衣。
清切丝桐会，纵横文雅飞。
恩深答效浅，留醉奉宸晖。','',''),('quantangshi-02957','兴庆池侍宴应制','蘇瓌','quantangshi','','卷3','金阙平明宿雾收，瑶池式宴俯清流。
瑞凤飞来随帝辇，祥鱼出戏跃王舟。
帷齐绿树当筵密，盖转缃荷接岸浮。
如临窃比微臣惧，若济叨陪圣主游。','',''),('quantangshi-02958','奉和圣制烛龙斋祭','張九齡','quantangshi','','卷3','上帝临下，鉴亦有光。
孰云阴隲，惟圣克彰。
六月徂暑，四郊愆阳。
我后其勤，告于坛场。
精意允溢，羣灵鼓舞。
蔚兮朝云，沛然时雨。
雨我原田，亦既有年。
烛龙煌煌，明宗报祀。
于以助之，天人帝子。
闻诗有训，国风兹始。','',''),('quantangshi-02959','奉和圣制喜雨','張九齡','quantangshi','','卷3','艰我稼穑，载育载亭。
随物应之，曷圣与灵。
谓我何凭，惟德之馨。
谁云天远，以诚必至。
太清无云，羲和顿辔。
于斯烝人，瞻彼非觊。
阴冥倏忽，沛泽咸洎。
何以致之，我后之感。
无皐无隰，黍稷黯黯。
无卉无木，敷芬黮黤。
黄龙勿来，鸣鸟不思。
人和年丰，皇心则怡。
岂与周宣，云汉徒诗。','',''),('quantangshi-02960','南郊文武出入舒和之乐','張九齡','quantangshi','','卷3','祝史辞正，人神庆叶。
福以德昭，享以诚接。
六变云备，百礼斯浃。
祀事孔明，祚流万叶。','',''),('quantangshi-02961','奉和圣制幸晋阳宫','張九齡','quantangshi','','卷3','隋季失天策，万方罹凶残。
皇祖称义旗，三灵皆获安。
圣期将申锡，王业成艰难。
盗移未改命，历在终履端。
彼汾惟帝乡，雄都信郁盘。
一月朔巡狩，羣后陪清銮。
霸迹在沛庭，旧仪覩汉官。
唐风思何深？舜典敷更宽。
户蒙枌榆复，邑争牛酒欢。
缅惟翦商后，岂独微禹叹。
三后既在天，万年斯不刊。
尊祖实我皇，天文皆仰观。','',''),('quantangshi-02962','奉和圣制次成皐先圣擒建德之所','張九齡','quantangshi','','卷3','天命诚有集，王业初惟艰。
翦商自文祖，夷项在兹山。
地识斩蛇处，河临饮马间。
威加昔运往，泽流今圣还。
尊祖颂先烈，赓歌安用攀。
绍成即我后，封岱出天关。','',''),('quantangshi-02963','奉和圣制赐诸州刺史以题座右','張九齡','quantangshi','','卷3','圣人合天德，洪覆在元元。
每劳苍生念，不以黄屋尊。
兴化俟羣辟，择贤守列藩。
得人此为盛，咨岳今复存。
降鉴引君道，殷勤启政门。
容光无不照，有象必为言。
成宪知所奉，致理归其根。
肃肃禀玄猷，煌煌戒朱轩。
岂徒任遇重，兼尔宴锡繁。
载闻励臣节，持答明主恩。','',''),('quantangshi-02964','奉和圣制送十道采访使及朝集使','張九齡','quantangshi','','卷3','三年一上计，万国趋河洛。
课最力已陈，赏延恩复博。
垂衣深共理，改瑟其咸若。
首路回竹符，分镳扬木铎。
戒程有攸往，诏饯无淹泊。
昭晰动天文，殷勤在人瘼。
持久望兹念，克终期所托。
行矣当自强，春耕庶秋获。','',''),('quantangshi-02965','奉和圣制谒玄元皇帝庙斋','張九齡','quantangshi','','卷3','兴运昔有感，建祠北山巅。
云雷初缔构，日月今悠然。
紫气尚蓊郁，玄元如在焉。
迨兹事追远，轮奂复增鲜。
洞府香林处，斋坛清汉边。
吾君乃尊祖，夙驾此留连。
乐动人神会，钟成律度圆。
笙歌下鸾鹤，芝术萃灵仙。
曾是福黎庶，岂唯味虚玄。
赓歌徒有作，微薄谢昭宣。','',''),('quantangshi-02966','巫山高','張九齡','quantangshi','','卷3','巫山与天近，烟景长青荧。
此中楚王梦，梦得神女灵。
神女去已久，云雨空冥冥。
唯有巴猿啸，哀音不可听。','',''),('quantangshi-02967','和黄门卢监望秦始皇陵','張九齡','quantangshi','','卷3','秦帝始求仙，骊山何遽卜。
中年既无效，兹地所宜复。
徒役如雷奔，珍怪亦云蓄。
黔首无寄命，赭衣相追逐。
人怨神亦怒，身死宗遂覆。
土崩失天下，龙鬬入函谷。
国为项籍屠，君同华元戮。
始掘既由楚，终焚乃因牧。
上宰议扬贤，中阿感桓速。
一闻过秦论，载怀空杼轴。','',''),('quantangshi-02968','酬周判官巡至始兴会改秘书少监见贻之作兼呈耿广州','張九齡','quantangshi','','卷3','惟昔迁乐土，迨今已重世。
阴庆荷先德，素风慙后裔。
唯益梓桑恭，岂禀山川丽。
于时初自勉，揆己无兼济。
瘠土资劳力，良书启蒙蔽。
一探石室文，再擢金门第。
既起南宫草，复掌西掖制。
过举及小人，便蕃在中岁。
亚司河海秩，转牧江湖澨。
勿谓符竹轻，但觉涓尘细。
一麾尚云忝，十驾宜求税。
心息已如灰，迹牵且为赘。
忽捧天书委，将革海隅弊。
朝闻循诚节，夕饮蒙瘴疠。
义疾耻无勇，盗憎攻亦锐。
葵藿是倾心，豺狼何反噬。
履险甘所受，劳贤恧相曳。
揽辔但荒服，循陔便私第。
嘉庆始获申，恩华复相继。
无庸我先举，同事君犹滞。
当推奉使绩，且结拜亲契。
更延怀安旨，曾是虑危际。
善谋虽若兹，至理焉可替。
所杖有神道，况承明主惠。','',''),('quantangshi-02969','和吏部李侍郎见示秋夜望月忆诸侍郎之什其卒章有前后行之戏因命仆继作','張九齡','quantangshi','','卷3','清秋发高兴，凉月复闲宵。
光逐露华满，情因水镜摇。
同时亦所见，异路无相招。
美景向空尽，欢言随事销。
忽听金华作，诚如玉律调。
南宫尚为后，东观何其辽。
名数虽云隔，风期幸未遥。
今来重余论，怀此更终朝。','',''),('quantangshi-02970','登南岳事毕谒司马道士','張九齡','quantangshi','','卷3','将命祈灵岳，回策诣真士。
绝迹寻一径，异香闻数里。
分庭八桂树，肃容两童子。
入室希把袖，登牀愿启齿。
诱我弃智诀，迨兹长生理。
吸精反自然，炼药求不死。
斯言眇霄汉，顾余婴纷滓。
相去九牛毛，慙叹知何已。','',''),('quantangshi-02971','九月九日登龙山','張九齡','quantangshi','','卷3','郡庭常窘束，凉野求昭旷。
楚客凛秋时，桓公旧台上。
清明风日好，历落江山望。
极远何萧条，中留坐惆怅。
东弥夏首阔，西拒荆门壮。
夷险虽异时，古今岂殊状。
先贤杳不接，故老犹可访。
投吊伤昔人，挥斤感前匠。
自为本疎散，未始忘幽尚。
际会非有欲，往来是无妄。
为邦复多幸，去国殊迁放。
且泛篱下菊，还聆郢中唱。
灌园亦何为，于陵乃逃相。','',''),('quantangshi-02972','登郡城南楼','張九齡','quantangshi','','卷3','闭阁幸无事，登楼聊永日。
云霞千里开，洲渚万形出。
澹澹澄江漫，飞飞度鸟疾。
邑人半舻舰，津树多枫橘。
感别时已屡，凭眺情非一。
远怀不我同，孤兴与谁悉。
平生本单绪，邂逅承优秩。
谬忝为邦寄，多慙理人术。
驽铅虽自勉，仓廪素非实。
陈力倘无効，谢病从芝术。','',''),('quantangshi-02973','岁初巡属县登高安南楼言怀','張九齡','quantangshi','','卷3','山城本孤峻，凭高结层轩。
江气偏宜早，林英粲已繁。
余滋含宿霁，众妍在朝暾。
拂衣释簿领，伏槛遗纷喧。
深俯东溪澳，远延南山樊。
归云纳前岭，去鸟投遥村。
目尽有余意，心恻不可谖。
朅来彭蠡泽，载经敷浅原。
春及但生思，时哉无与言。
不才叨过举，唯力酬明恩。
美化犹寂蔑，迅节徒飞奔。
虽无成立効，庶以去思论。
行复徇孤迹，亦云吾道存。','',''),('quantangshi-02974','秋晚登楼望南江入始兴郡路','張九齡','quantangshi','','卷3','潦收沙衍出，霜降天宇晶。
伏槛一长眺，津途多远情。
思来江山外，望尽烟云生。
滔滔不自辨，役役且何成。
我来飒衰鬓，孰云飘华缨。
枥马苦蜷局，笼禽念遐征。
岁阴向晼晚，日夕空屏营。
物生贵得性，身累由近名。
内顾觉今是，追叹何时平。','',''),('quantangshi-02975','登古阳云台','張九齡','quantangshi','','卷3','庭树日衰飒，风霜未云已。
驾言遣忧思，乘兴求相似。
楚国兹故都，兰台有余址。
传闻襄王世，仍立巫山祀。
方此全盛时，岂无婵娟子。
色荒神女至，魂荡宫观启。
蔓草今如积，朝云为谁起。','',''),('quantangshi-02976','与生公寻幽居处','張九齡','quantangshi','','卷3','同方久厌俗，相与事遐讨。
及此云山去，窅然岩径好。
疑入武陵源，如逢汉阴老。
清谐欣有得，幽闲歘盈抱。
我本玉阶侍，偶访金仙道。
兹焉求卜筑，所过皆神造。
岁晚林始敷，日晏崖方杲。
不种缘岭竹，岂植临潭草。
即途可淹留，随日成黼藻。
期为静者说，曾是终焉保。
今为简书畏，秖令归思浩。','',''),('quantangshi-02977','与生公游石窟山','張九齡','quantangshi','','卷3','探秘孰云远，忘怀复尔同。
日寻高深意，宛是神仙中。
跻险构灵室，诡制非人功。
潜洞黝无底，殊庭忽似梦。
岂如武安凿，自若茅山通。
造物良有寄，嬉游乃惬衷。
犹希咽玉液，从此升云空。
咄咄共携手，泠然且驭风。','',''),('quantangshi-02978','郡舍南有园畦杂树聊以永日','張九齡','quantangshi','','卷3','为郡久无补，越乡空复深。
苟能秉素节，安用叨华簪。
却步园畦里，追吾野逸心。
形骸拘俗吏，光景赖闲林。
内讼诚知止，外言犹匪忱。
成蹊谢李径，衞足感葵阴。
荣达岂不伟，孤生非所任。
江城何寂历，秋树亦萧森。
下有北流水，上有南飞禽。
我愿从归翼，无然坐自沈。','',''),('quantangshi-02979','临泛东湖','張九齡','quantangshi','','卷3','郡庭日休暇，湖曲邀胜践。
乐职在中和，灵心挹上善。
乘流坐清旷，举目眺悠缅。
林与西山重，云因北风卷。
晶明画不逮，阴影镜无辨。
晚秀复芬敷，秋光更遥衍。
万族纷可佳，一游岂能展。
羇孤忝邦牧，顾己非时选。
梁公世不容，长孺心亦褊。
永念出笼絷，常思退疲蹇。
岁徂风露严，日恐兰苕剪。
佳辰不可得，良会何其鲜。
罢兴还江城，闭关聊自遣。','',''),('quantangshi-02980','始兴南山下有林泉尝卜居焉荆州卧病有怀此地','張九齡','quantangshi','','卷3','出处各有在，何者为陆沈。
幸无迫贱事，聊可祛迷襟。
世路少夷坦，孟门未岖嵚。
多慙入火术，常惕履冰心。
一跌不自保，万全焉可寻。
行行念归路，眇眇惜光阴。
浮生如过隙，先达已吾箴。
敢忘丘山施，亦云年病侵。
力衰在所养，时谢良不任。
但忆旧栖息，愿言遂窥临。
云间日孤秀，山下面清深。
萝茑自为幄，风泉何必琴。
归此老吾老，还当日千金。','',''),('quantangshi-02981','晨坐斋中偶而成咏','張九齡','quantangshi','','卷3','寒露洁秋空，遥山纷在瞩。
孤顶乍修耸，微云复相续。
人兹赏地偏，鸟亦爱林旭。
结念凭幽远，抚躬曷羁束。
仰霄谢逸翰，临路嗟疲足。
徂岁方暌携，归心亟踯躅。
休闲倘有素，岂负南山曲。','',''),('quantangshi-02982','咏史','張九齡','quantangshi','','卷3','大德始无颇，中智是所是。
居然已不一，况乃务相诡。
小道致泥难，巧言因萋毁。
穰侯或见迟，苏生得阴揣。
轻既长沙傅，重亦边郡徙。
势倾不幸然，迹在胡宁尔。
沧溟所为大，江汉日来委。
沣水虽复清，鱼鼈岂游此。
贤哉有小白，雠中有管氏。
若人不世生，悠悠多如彼。','',''),('quantangshi-02983','龙门旬宴得月字韵','張九齡','quantangshi','','卷3','恩华逐芳岁，形胜兼韶月。
中席傍鱼潭，前山倚龙阙。
花迎妙妓至，鸟避仙舟发。
宴赏良在兹，再来情不歇。','',''),('quantangshi-02984','骊山下逍遥公旧居游集','張九齡','quantangshi','','卷3','君子体清尚，归处有兼资。
虽然经济日，无忘幽栖时。
卜居旧何所，休澣尝来兹。
岑寂罕人至，幽深获我思。
松涧聆遗风，兰林览余滋。
往事诚已矣，道存犹可追。
遗子后黄金，作歌先紫芝。
明德有自来，奕世皆秉彝。
岂与磻溪老，崛起周太师。
我心希硕人，逮此问元龟。
怊怅既怀远，沈吟亦省私。
已云宠禄过，况在华发衰。
轩盖有迷复，丘壑无磷缁。
感物重所怀，何但止足斯。','',''),('quantangshi-02985','杂诗五首 一','張九齡','quantangshi','','卷3','孤桐亦胡为，百尺傍无枝。
疎阴不自覆，修干欲何施。
高冈地复迥，弱植风屡吹。
凡鸟已相噪，凤皇安得知。','',''),('quantangshi-02986','杂诗五首 二','張九齡','quantangshi','','卷3','萝茑必有托，风霜不能落。
酷在兰将蕙，甘从葵与藿。
运命虽为宰，寒暑自回薄。
悠悠天地间，委顺无不乐。','',''),('quantangshi-02987','杂诗五首 三','張九齡','quantangshi','','卷3','良辰不可遇，心赏更蹉跎。
终日块然坐，有时劳者歌。
庭前揽芳蕙，江上托微波。
路远无能达，忧情空复多。','',''),('quantangshi-02988','杂诗五首 四','張九齡','quantangshi','','卷3','湘水吊灵妃，斑竹为情绪。
汉水访游女，解佩欲谁与。
同心不可见，异路空延伫。
浦上青枫林，津傍白沙渚。
行吟至落日，坐望秖愁予。
神物亦岂孤，佳期竟何许。','',''),('quantangshi-02989','杂诗五首 五','張九齡','quantangshi','','卷3','木直几自寇，石坚亦他攻。
何言为用薄，而与火膏同。
物类有固然，谁能取径通。
纤纤良田草，靡靡唯从风。
日夜沐甘泽，春秋等芳丛。
生性苟不夭，香臭谁为中。
道家贵至柔，儒生何固穷。
终始行一意，无乃过愚公。','',''),('quantangshi-02990','感遇十二首 一','張九齡','quantangshi','','卷3','兰叶春葳蕤，桂华秋皎洁。
欣欣此生意，自尔为佳节。
谁知林栖者，闻风坐相悦。
草木有本心，何求美人折。','',''),('quantangshi-02991','感遇十二首 二','張九齡','quantangshi','','卷3','幽林归独卧，滞虑洗孤清。
持此谢高鸟，因之传远情。
日夕怀空意，人谁感至精。
飞沈理自隔，何所慰吾诚。','',''),('quantangshi-02992','感遇十二首 三','張九齡','quantangshi','','卷3','鱼游乐深池，鸟栖欲高枝。
嗟尔蜉蝣羽，薨薨亦何为。
有生岂不化，所感奚若斯。
神理日微灭，吾心安得知。
浩叹杨朱子，徒然泣路岐。','',''),('quantangshi-02993','感遇十二首 四','張九齡','quantangshi','','卷3','孤鸿海上来，池潢不敢顾。
侧见双翠鸟，巢在三珠树。
矫矫珍木巅，得无金丸惧。
美服患人指，高明逼神恶。
今我游冥冥，弋者何所慕。','',''),('quantangshi-02994','感遇十二首 五','張九齡','quantangshi','','卷3','吴越数千里，梦寐今夕见。
形骸非我亲，衾枕即乡县。
化蝶犹不识，川鱼安可羡。
海上有仙山，归期觉神变。','',''),('quantangshi-02995','感遇十二首 六','張九齡','quantangshi','','卷3','西日下山隐，北风乘夕流。
燕雀感昏旦，檐楹呼匹俦。
鸿鹄虽自远，哀音非所求。
贵人弃疵贱，下士尝殷忧。
众情累外物，恕己忘内修。
感叹长如此，使我心悠悠。','',''),('quantangshi-02996','感遇十二首 七','張九齡','quantangshi','','卷3','江南有丹橘，经冬犹绿林。
岂伊地气暖，自有岁寒心。
可以荐嘉客，奈何阻重深。
运命唯所遇，循环不可寻。
徒言树桃李，此木岂无阴。','',''),('quantangshi-02997','感遇十二首 八','張九齡','quantangshi','','卷3','永日徒离忧，临风怀蹇修。
美人何处所？孤客空悠悠。
青鸟跂不至，朱鳖谁云浮。
夜分起踯躅，时逝曷淹留。','',''),('quantangshi-02998','感遇十二首 九','張九齡','quantangshi','','卷3','抱影吟中夜，谁闻此叹息。
美人适异方，庭树含幽色。
白云愁不见，沧海飞无翼。
凤皇一朝来，竹花斯可食。','',''),('quantangshi-02999','感遇十二首 十','張九齡','quantangshi','','卷3','汉上有游女，求思安可得。
袖中一札书，欲寄双飞翼。
冥冥愁不见，耿耿徒缄忆。
紫兰秀空蹊，皓露夺幽色。
馨香岁欲晚，感叹情何极。
白云在南山，日暮长太息。','',''),('quantangshi-03000','感遇十二首 十一','張九齡','quantangshi','','卷3','我有异乡忆，宛在云溶溶。
凭此目不觏，要之心所钟。
但欲附高鸟，安敢攀飞龙。
至精无感遇，悲惋填心胸。
归来扣寂寞，人愿天岂从。','',''),('quantangshi-03001','感遇十二首 十二','張九齡','quantangshi','','卷3','闭门迹羣化，凭林结所思。
啸叹此寒木，畴昔乃芳蕤。
朝阳凤安在，日暮蝉独悲。
浩思极中夜，深嗟欲待谁。
所怀诚已矣，既往不可追。
鼎食非吾事，云仙尝我期。
胡越方杳杳，车马何迟迟。
天壤一何异，幽嘿卧帘帷。','',''),('quantangshi-03002','江上遇疾风','張九齡','quantangshi','','卷3','疾风江上起，鼓怒扬烟埃。
白昼晦如夕，洪涛声若雷。
投林鸟铩羽，入浦鱼曝鳃。
瓦飞屋且发，帆快樯已摧。
不知天地气，何为此喧豗。','',''),('quantangshi-03003','南阳道中作','張九齡','quantangshi','','卷4','登郢属岁阴，及宛懵所适。
复闻东汉主，遗此南都迹。
佳气蔼厥初，霸图纷在昔。
兹邦称贵近，与世尝薰赫。
遭遇感风云，变衰空草泽。
不识邓公树，犹传阴后石。
驱马历闉闍，荆榛翳阡陌。
事去物无象，感来心不怿。
怀古对穷秋，兴言伤远客。
眇默遵岐路，辛勤弊行役。
云雁号相呼，林麕走自索。
顾忆徇书剑，未尝安枕席。
岂暇墨突黔，空持辽豕白。
迷复期非远，归欤赏农隙。','',''),('quantangshi-03004','湘中作','張九齡','quantangshi','','卷4','湘流绕南岳，绝目转青青。
怀禄未能已，瞻途屡所经。
烟屿宜春望，林猿莫夜听。
永路日多绪，孤舟天复冥。
浮没从此去，嗟嗟劳我形。','',''),('quantangshi-03005','彭蠡湖上','張九齡','quantangshi','','卷4','沿涉经大湖，湖流多行泆。
决晨趋北渚，逗浦已西日。
所适虽淹旷，中流且闲逸。
瑰诡良复多，感见乃非一。
庐山直阳浒，孤石当阴术。
一水云际飞，数峰湖心出。
象类何交乣，形言岂深悉。
且知皆自然，高下无相恤。','',''),('quantangshi-03006','入庐山仰望瀑布水','張九齡','quantangshi','','卷4','绝顶有悬泉，喧喧出烟杪。
不知几时岁，但见无昏晓。
闪闪青崖落，鲜鲜白日皎。
洒流湿行云，溅沫惊飞鸟。
雷吼何喷薄，箭驰入窈窕。
昔闻山下蒙，今乃林峦表。
物情有诡激，坤元曷纷矫。
默然置此去，变化谁能了。','',''),('quantangshi-03007','出为豫章郡途次庐山东岩下','張九齡','quantangshi','','卷4','兹山镇何所，乃在澄湖阴。
下有蛟螭伏，上与虹霓寻。
灵仙未始旷，窟宅何其深。
双阙出云峙，三宫入烟沈。
攀崖犹昔境，种杏非旧林。
想像终古迹，惆怅独往心。
纷吾婴世网，数载忝朝簪。
孤根自靡托，量力况不任。
多谢周身防，常恐横议侵。
岂匪鵷鸿列，惕如泉壑临。
迨兹刺江郡，来此涤尘襟。
有趣逢樵客，忘怀狎野禽。
栖闲义未果，用拙欢在今。
愿言答休命，归事丘中琴。','',''),('quantangshi-03008','巡属县道中作','張九齡','quantangshi','','卷4','春令夙所奉，驾言遵此行。
途中却郡掾，林下招村氓。
至邑无纷剧，来人但欢迎。
岂伊念邦政，尔实在时清。
短才滥符竹，弱岁起柴荆。
再入江村道，永怀山薮情。
矧逢阳节献，默听时禽鸣。
迹与素心别，感从幽思盈。
流芳日不待，夙志蹇无成。
知命且何欲，所图唯退耕。
华簪极身泰，衰鬓慙木荣。
苟得不可遂，吾其谢世婴。','',''),('quantangshi-03009','夏日奉使南海在道中作','張九齡','quantangshi','','卷4','缅然万里露，赫曦三伏时。
飞走逃深林，流烁恐生疵。
行李岂无苦，而我方自怡。
肃事诚在公，拜庆遂及私。
展力慙浅效，衔恩感深慈。
且欲汤火蹈，况无鬼神欺。
朝发高山阿，夕济长江湄。
秋瘴宁我毒，夏水胡不夷。
信知道存者，但问心所之。
吕梁有出入，乃觉非虚词。','',''),('quantangshi-03010','巡按自漓水南行','張九齡','quantangshi','','卷4','理棹虽云远，饮冰宁有惜。
况乃佳山川，怡然傲潭石。
奇峰岌前转，茂树隈中积。
猿鸟声自呼，风泉气相激。
目因诡容逆，心与清晖涤。
纷吾谬执简，行郡将移檄。
即事聊独欢，素怀岂兼适。
悠悠咏靡盬，庶以穷日夕。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-03011','使还都湘东作','張九齡','quantangshi','','卷4','仓庚昨归候，阳鸟今去时。
感物遽如此，劳生安可思。
养真无上格，图进岂前期。
清节往来苦，壮容离别衰。
盛明非不遇，弱操自云私。
孤楫清川泊，征衣寒露滋。
风朝津树落，日夕岭猿悲。
牵役而无悔，坐愁秪自怡。
当须报恩已，终尔谢尘缁。','',''),('quantangshi-03012','冬中至玉泉山寺属穷阴冰闭崖谷无色及仲春行县复往焉故有此作','張九齡','quantangshi','','卷4','灵境信幽绝，芳时重暄妍。
再来及兹胜，一遇非无缘。
万木柔可结，千花敷欲然。
松间鸣好鸟，竹下流清泉。
石壁开精舍，金光照法筵。
真空本自寂，假有聊相宣。
复此灰心者，仍追巢顶禅。
简书虽有畏，身世亦相捐。','',''),('quantangshi-03013','郢城西北有大古冢数十观其封域多是楚时诸王而年代久远不复可识唯直西有樊妃冢因后人为植松柏故行路尽知之','張九齡','quantangshi','','卷4','苹藻生南涧，蕙兰秀中林。
嘉名有所在，芳气无幽深。
楚子初逞志，樊妃尝献箴。
能令更择士，非直罢从禽。
旧国皆湮灭，先王亦莫寻。
唯传贤媛陇，犹结后人心。
牢落山川意，萧疎松柏阴。
破墙时直上，荒径或斜侵。
惠问终不绝，风流独至今。
千春思窈窕，黄鸟复哀音。','',''),('quantangshi-03014','荆州作二首 一','張九齡','quantangshi','','卷4','先达志其大，求意不约文。
士伸在知己，已况仕于君。
微诚夙所尚，细故不足云。
时来忽易失，事往良难分。
顾念凡近姿，焉欲殊常勋。
亦以行则是，岂必素有闻。
千虑且犹失，万绪何其纷。
进士苟非党，免相安得羣。
众口金可铄，孤心丝共棼。
意忠仗朋信，语勇同败军。
古剑徒有气，幽兰秪自薰。
高秩向所忝，于义如浮云。','',''),('quantangshi-03015','荆州作二首 二','張九齡','quantangshi','','卷4','千载一遭遇，往贤所至难。
问余奚为者，无阶忽上抟。
明圣不世出，翼亮非苟安。
崇高自有配，孤陋何足干。
遇恩一时来，窃位三岁寒。
谁谓诚不尽，知穷力亦殚。
虽至负乘寇，初无挟术钻。
浩荡出江湖，翻覆如波澜。
心伤不材树，自念独飞翰。
徇义在匹夫，报恩犹一餐。
况乃山海泽，效无毫发端。
内讼已慙沮，积毁今摧残。
胡为复惕息，伤鸟畏虚弹。','',''),('quantangshi-03016','在郡秋怀二首 一','張九齡','quantangshi','','卷4','秋风入前林，萧瑟鸣高枝。
寂寞游子思，寤叹何人知。
宦成名不立，志存岁已驰。
五十而无闻，古人深所疵。
平生去外饰，直道如不羁。
未得操割效，忽复寒暑移。
物情自古然，身退毁亦随。
悠悠沧江渚，望望白云涯。
露下霜且降，泽中草离披。
兰艾若不分，安用馨香为。','',''),('quantangshi-03017','在郡秋怀二首 二','張九齡','quantangshi','','卷4','庭芜生白露，岁候感遐心。
策蹇慙远途，巢枝思故林。
小人恐致寇，终日如临深。
鱼鸟好自逸，池笼安所钦。
挂冠东都门，采蕨南山岑。
议道诚愧昔，览分还惬今。
怃然忧成老，空尔白头吟。','',''),('quantangshi-03018','忝官二十年尽在内职及为郡尝积恋因赋诗焉','張九齡','quantangshi','','卷4','江流去朝宗，昼夜兹不舍。
仲尼在川上，子牟存阙下。
圣达有由然，孰是无心者。
一郡苟能化，百城岂云寡。
爱礼谁为羊，恋主吾犹马。
感初时不载，思奋翼无假。
闲宇常自闭，沈心何用写。
揽衣步前庭，登陴临旷野。
白水生迢递，清风寄潇洒。
愿言采芳泽，终朝不盈把。','',''),('quantangshi-03019','二弟宰邑南海见羣雁南飞因成咏以寄','張九齡','quantangshi','','卷4','鸿雁自北来，嗷嗷度烟景。
常怀稻粱惠，岂惮江山永。
小大每相从，羽毛当自整。
双凫侣晨泛，独鹤参宵警。
为我更南飞，因书至梅岭。','',''),('quantangshi-03020','将发还乡示诸弟','張九齡','quantangshi','','卷4','岁阳亦颓止，林意日萧摵。
云胡当此时，缅迈复为客。
至爱孰能舍，名义来相迫。
负德良不赀，输诚靡所惜。
一木逢厦构，纤尘愿山益。
无力主君恩，宁利客卿璧。
去去荣归养，怃然叹行役。','',''),('quantangshi-03021','叙怀二首 一','張九齡','quantangshi','','卷4','弱岁读羣史，抗迹追古人。
被褐有怀玉，佩印从负薪。
志合岂兄弟，道行无贱贫。
孤根亦何赖，感激此为邻。','',''),('quantangshi-03022','叙怀二首 二','張九齡','quantangshi','','卷4','晚节从卑秩，岐路良非一。
既闻持两端，复见挟三术。
木瓜诚有报，玉楮论无实。
已矣直躬者，平生壮图失。
去去勿重陈，归来茹芝术。','',''),('quantangshi-03023','题画山水障','張九齡','quantangshi','','卷4','心累犹不尽，果为物外牵。
偶因耳目好，复假丹青妍。
尝抱野间意，而迫区中缘。
尘事固已矣，秉意终不迁。
良工适我愿，妙墨挥岩泉。
变化合羣有，高深侔自然。
置陈北堂上，仿像南山前。
静无户庭出，行已兹地偏。
萱草忧可树，合欢忿益蠲。
所因本微物，况乃凭幽筌。
言象会自泯，意色聊自宣。
对玩有佳趣，使我心渺绵。','',''),('quantangshi-03024','奉和圣制瑞雪篇','張九齡','quantangshi','','卷4','万年春，三朝日，上御明台旅庭实。
初瑞雪兮霏微，俄同云兮蒙密。
此时骚切阴风生，先过金殿有余清。
信宿婵娟飞雪度，能使玉人俱掩嫮。
皓皓楼前月初白，纷纷陌上尘皆素。
昨讶骄阳积数旬，始知和气待迎新。
匪惟在人利，曾是扶天意。
天意岂云遥，雪下不崇朝。
皇情玩无斁，雪委方盈尺。
草树纷早荣，京坻宛先积。
君恩诚谓何，岁稔复人和。
预数斯箱庆，应如此雪多。
朝冕旒兮载悦，想籉笠兮农节。
倚瑶琴兮或歌，续薰风兮瑞雪。
福浸昌，应尤盛，瑞雪年年常感圣。
愿以柏梁作，长为柳花咏。','',''),('quantangshi-03025','奉和圣制温泉歌','張九齡','quantangshi','','卷4','有时神物待圣人，去后汤还冷，来时树亦春。
今兹十月自东归，羽斾逶迤上翠微。
温谷葱葱佳气色，离宫奕奕叶光辉。
临渭川，近天邑。
浴日温泉复在兹，羣仙洞府那相及。
吾君利物心，玄泽浸苍黔。
渐渍神汤无疾苦，薰歌一曲感人深。','',''),('quantangshi-03026','南郊太尉酌献武舞作凯安之乐','張九齡','quantangshi','','卷4','馨香惟后德，明命光天保。
肃祀崇圣灵，陈信表黄道。
玉戚初蹈厉，金匏既静好。
介福何穰穰，精诚格穹昊。','',''),('quantangshi-03027','奉和圣制经孔子旧宅','張九齡','quantangshi','','卷4','孔门太山下，不见登封时。
徒有先王法，今为明主思。
恩加万乘幸，礼致一牢祠。
旧宅千年外，光华空在兹。','',''),('quantangshi-03028','奉和圣制次琼岳韵','張九齡','quantangshi','','卷4','山祗亦望幸，云雨见灵心。
岳馆逢朝霁，关门解宿阴。
咸京天上近，清渭日边临。
我武因冬狩，何言是即禽。','',''),('quantangshi-03029','奉和圣制送李尚书入蜀','張九齡','quantangshi','','卷4','眷言感忠义，何有间山川。
徇节今如此，离情空复然。
皇心在勤恤，德泽委昭宣。
周月成功后，明年或劳还。','',''),('quantangshi-03030','奉和圣制初出洛城','張九齡','quantangshi','','卷4','东土淹龙驾，西人望翠华。
山川祗询物，宫观岂为家。
十月回星斗，千官捧日车。
洛阳无怨思，巡幸更非赊。','',''),('quantangshi-03031','奉和圣制途次陕州作','張九齡','quantangshi','','卷4','驰道当河陕，陈诗问国风。
川原三晋别，襟带两京同。
后殿函关尽，前旌阙塞通。
行看洛阳陌，光景丽天中。','',''),('quantangshi-03032','勅赐宁王池宴','張九齡','quantangshi','','卷4','贤王有池馆，明主赐春游。
淑气林间发，恩光水上浮。
徒慙和鼎地，终谢巨川舟。
皇泽空如此，轻生莫可酬。','',''),('quantangshi-03033','天津桥东旬宴得歌字韵','張九齡','quantangshi','','卷4','清洛象天河，东流形胜多。
朝来逢宴喜，春尽却妍和。
泉鲔欢时跃，林莺醉里歌。','',''),('quantangshi-03034','上阳水窗旬宴得移字韵','張九齡','quantangshi','','卷4','河汉非应到，汀洲忽在斯。
仍逢帝乐下，如逐海槎窥。
春赏时将换，皇恩岁不移。
今朝游宴所，莫比天泉池。','',''),('quantangshi-03035','折杨柳','張九齡','quantangshi','','卷4','纤纤折杨柳，持此寄情人。
一枝何足贵，怜是故园春。
迟景那能久，芳菲不及新。
更愁征戍客，容鬓老边尘。','',''),('quantangshi-03036','剪彩','張九齡','quantangshi','','卷4','姹女矜容色，为花不让春。
既争芳意早，谁待物华真。
叶作参差发，枝从点缀新。
自然无限态，长在艳阳晨。','',''),('quantangshi-03037','和崔黄门寓直夜听蝉之作','張九齡','quantangshi','','卷4','蝉嘶玉树枝，向夕惠风吹。
幸入连宵听，应缘饮露知。
思深秋欲近，声静夜相宜。
不是黄金饰，清香徒尔为。','',''),('quantangshi-03038','和姚令公从幸温汤喜雪','張九齡','quantangshi','','卷4','万乘飞黄马，千金狐白裘。
正逢银霰积，如向玉京游。
瑞色铺驰道，花文拂彩旒。
还闻吉甫颂，不共郢歌俦。','',''),('quantangshi-03039','立春日晨起对积雪','張九齡','quantangshi','','卷4','忽对林亭雪，瑶华处处开。
今年迎气始，昨夜伴春回。
玉润窗前竹，花繁院里梅。
东郊斋祭所，应见五神来。','',''),('quantangshi-03040','三月三日申王园亭宴集','張九齡','quantangshi','','卷4','稽亭追往事，睢苑胜前闻。
飞阁凌芳树，华池落彩云。
藉草人留酌，衔花鸟赴羣。
向来同赏处，惟恨碧林曛。','',''),('quantangshi-03041','三月三日登龙山','張九齡','quantangshi','','卷4','伊川与灞津，今日祓除人。
岂似龙山上，还同湘水滨。
衰颜忧更老，淑景望非春。
禊饮岂吾事，聊将偶俗尘。','',''),('quantangshi-03042','和王司马折梅寄京邑昆弟','張九齡','quantangshi','','卷4','离别念同嬉，芬荣欲共持。
独攀南国树，遥寄北风时。
林惜迎春早，花愁去日迟。
还闻折梅处，更有棣华诗。','',''),('quantangshi-03043','晚霁登王六东阁','張九齡','quantangshi','','卷4','试上江楼望，初逢山雨晴。
连空青嶂合，向晚白云生。
彼美要殊观，萧条见远情。
情来不可极，日暮水流清。','',''),('quantangshi-03044','苏侍郎紫薇庭各赋一物得芍药','張九齡','quantangshi','','卷4','仙禁生红药，微芳不自持。
幸因清切地，还遇艳阳时。
名见桐君箓，香闻郑国诗。
孤根若可用，非直爱华滋。','',''),('quantangshi-03045','和黄门卢侍御咏竹','張九齡','quantangshi','','卷4','清切紫庭垂，葳蕤防露枝。
色无玄月变，声有惠风吹。
高节人相重，虚心世所知。
凤皇佳可食，一去一来仪。','',''),('quantangshi-03046','和韦尚书答梓州兄南亭宴集','張九齡','quantangshi','','卷4','棠棣闻余兴，乌衣有旧游。
门前杜城陌，池上曲江流。
暇日尝繁会，清风咏阻修。
始知西峙岳，同气此相求。','',''),('quantangshi-03047','答陈拾遗赠竹簪','張九齡','quantangshi','','卷4','与君尝此志，因物复知心。
遗我龙钟节，非无玳瑁簪。
幽素宜相重，雕华岂所任。
为君安首饰，怀此代兼金。','',''),('quantangshi-03048','赠澧阳韦明府','張九齡','quantangshi','','卷4','君有百炼刃，堪断七重犀。
谁开太阿匣，持割武城鸡。
竟与尚书佩，遥应天子提。
何时遇操宰，当使玉如泥。','',''),('quantangshi-03049','在洪州答綦毋学士','張九齡','quantangshi','','卷4','旬雨不愆期，由来自若时。
尔无言郡政，吾岂欲天欺。
常念涓尘益，惟欢草树滋。
课成非所拟，人望在东菑。','',''),('quantangshi-03050','酬王六霁后书怀见示','張九齡','quantangshi','','卷4','云雨俱行罢，江天已洞开。
炎氛霁后灭，边绪望中来。
作骥君垂耳，为鱼我曝鳃。
更怜湘水赋，还是洛阳才。','',''),('quantangshi-03051','酬王六寒朝见诒','張九齡','quantangshi','','卷4','贾生流寓日，扬子寂寥时。
在物多相背，唯君独见思。
渔为江上曲，雪作郢中词。
忽枉兼金讯，长怀伐木诗。','',''),('quantangshi-03052','林亭咏','張九齡','quantangshi','','卷4','穿筑非求丽，幽闲欲寄情。
偶怀因壤石，真意在蓬瀛。
苔益山文古，池添竹气清。
从兹果萧散，无事亦无营。','',''),('quantangshi-03053','晨出郡舍林下','張九齡','quantangshi','','卷4','晨兴步北林，萧散一开襟。
复见林上月，娟娟犹未沈。
片云自孤远，丛筱亦清深。
无事由来贵，方知物外心。','',''),('quantangshi-03054','园中时蔬尽皆锄理唯秋兰数本委而不顾彼虽一物有足悲者遂赋二章 一','張九齡','quantangshi','','卷4','场藿已成岁，园葵亦向阳。
兰时独不偶，露节渐无芳。
旨异菁为蓄，甘非蔗有浆。
人多利一饱，谁复惜馨香。','',''),('quantangshi-03055','园中时蔬尽皆锄理唯秋兰数本委而不顾彼虽一物有足悲者遂赋二章 二','張九齡','quantangshi','','卷4','幸得不锄去，孤苗守旧根。
无心羡旨蓄，岂欲近名园。
遇赏宁充佩，为生莫碍门。
幽林芳意在，非是为人论。','',''),('quantangshi-03056','林亭寓言','張九齡','quantangshi','','卷4','林居逢岁晏，遇物使情多。
蘅茝不时与，芬荣奈汝何。
更怜篱下菊，无如松上萝。
因依自有命，非是隔阳和。','',''),('quantangshi-03057','送使广州','張九齡','quantangshi','','卷4','家在湘源住，君今海峤行。
经过正中道，相送倍为情。
心逐书邮去，形随世网婴。
因声谢远别，缘义不缘名。','',''),('quantangshi-03058','送姚评事入蜀各赋一物得卜肆','張九齡','quantangshi','','卷4','蜀严化已久，沈冥空所思。
尝闻卖卜处，犹忆下帘时。
驱传应经此，怀贤倘问之。
归来说往事，历历偶心期。','',''),('quantangshi-03059','送窦校书见饯得云中辨江树','張九齡','quantangshi','','卷4','江水天连色，无涯净野氛。
微明岸傍树，凌乱渚前云。
举棹形徐转，登舻意渐分。
渺茫从此去，空复惜离羣。','',''),('quantangshi-03060','饯王司马入计同用洲字','張九齡','quantangshi','','卷4','元僚行上计，举饯出林丘。
忽望题舆远，空思解榻游。
别筵铺柳岸，征棹倚芦洲。
独叹湘江水，朝宗向北流。','',''),('quantangshi-03061','东湖临泛饯王司马','張九齡','quantangshi','','卷4','南土秋虽半，东湖草未黄。
聊乘风日好，来泛芰荷香。
兰棹无劳速，菱歌不厌长。
忽怀京洛去，难与共清光。','',''),('quantangshi-03062','饯济阴梁明府各探一物得荷叶','張九齡','quantangshi','','卷4','荷叶生幽渚，芳华信在兹。
朝朝空此地，采采欲因谁。
但恐星霜改，还将蒲稗衰。
怀君美人别，聊以赠心期。','',''),('quantangshi-03063','饯陈学士还江南同用征字','張九齡','quantangshi','','卷4','荷蓧旋江澳，衔杯饯霸陵。
别前林鸟息，归处海烟凝。
风土乡情接，云山客念凭。
圣朝岩穴选，应待鹤书征。','',''),('quantangshi-03064','通化门外送别','張九齡','quantangshi','','卷4','屡别容华改，长愁意绪微。
义将私爱隔，情与故人归。
薄宦无时赏，劳生有事机。
离魂今夕梦，先绕旧林飞。','',''),('quantangshi-03065','送杨道士往天台','張九齡','quantangshi','','卷4','鬼谷还成道，天台去学仙。
行应松子化，留与世人传。
此地烟波远，何时羽驾旋？
当须一把袂，城郭共依然。','',''),('quantangshi-03066','送杨府李功曹','張九齡','quantangshi','','卷4','平生属良友，结绶望光辉。
何知人事拙，相与宦情非。
别路穿林尽，征帆际海归。
居然已多意，况复两乡违。','',''),('quantangshi-03067','送宛句赵少府','張九齡','quantangshi','','卷4','解巾行作吏，尊酒谢离居。
修竹含清景，华池澹碧虚。
地将幽兴惬，人与旧游疎。
林下纷相送，多逢长者车。','',''),('quantangshi-03068','送韦城李少府','張九齡','quantangshi','','卷4','送客南昌尉，离亭西候春。
野花看欲尽，林鸟听犹新。
别酒青门路，归轩白马津。
相知无远近，万里尚为邻。','',''),('quantangshi-03069','送苏主簿赴偃师','張九齡','quantangshi','','卷4','我与文雄别，胡然邑吏归。
贤人安下位，鸷鸟欲卑飞。
激节轻华冕，移官徇彩衣。
羡君行乐处，从此拜庭闱。','',''),('quantangshi-03070','送广州周判官','張九齡','quantangshi','','卷4','海郡雄蛮落，津亭壮越台。
城隅百雉映，水曲万家开。
里树桄榔出，时禽翡翠来。
观风犹未尽，早晚使车回。','',''),('quantangshi-03071','郡江南上别孙侍御','張九齡','quantangshi','','卷4','云嶂天涯尽，川途海县穷。
何言此地僻，忽与故人同。
身负邦君弩，情纡御史骢。
王程不我驻，离思逐秋风。','',''),('quantangshi-03072','道逢北使题赠京邑亲知','張九齡','quantangshi','','卷4','征骖稍靡靡，去国方迟迟。
路遶南登岸，情摇北上旗。
故人怜别日，旅雁逐归时。','',''),('quantangshi-03073','江上使风呈裴宣州耀卿','張九齡','quantangshi','','卷4','江路与天连，风帆何淼然。
遥林浪出没，孤舫鸟联翩。
常爱千钧重，深思万事捐。
报恩非徇禄，还逐贾人船。','',''),('quantangshi-03074','溪行寄王震','張九齡','quantangshi','','卷4','山气朝来爽，溪流日向清。
远心何处惬，闲棹此中行。
丛桂林间待，羣鸥水上迎。
徒然适我愿，幽独为谁情。','',''),('quantangshi-03075','自豫章南还江上作','張九齡','quantangshi','','卷4','归去南江水，磷磷见底清。
转逢空阔处，聊洗滞留情。
浦树遥如待，江鸥近若迎。
津途别有趣，况乃濯吾缨。','',''),('quantangshi-03076','将至岳阳有怀赵二','張九齡','quantangshi','','卷4','湘岸多深林，青冥昼结阴。
独无谢客赏，况复贾生心。
草色虽云发，天光或未临。
江潭非所遇，为尔白头吟。','',''),('quantangshi-03077','使还湘水','張九齡','quantangshi','','卷4','归舟宛何处，正值楚江平。
夕逗烟村宿，朝缘浦树行。
于役已弥岁，言旋今惬情。
乡郊尚千里，流目夏云生。','',''),('quantangshi-03078','初发道中寄远','張九齡','quantangshi','','卷4','日夜乡山远，秋风复此时。
旧闻胡马思，今听楚猿悲。
念别朝昏苦，怀归岁月迟。
壮图空不息，常恐发如丝。','',''),('quantangshi-03079','自湘水南行','張九齡','quantangshi','','卷4','落日摧行舫，逶迤洲渚间。
虽云有物役，乘此更休闲。
暝色生前浦，清晖发近山。
中流澹容与，唯爱鸟飞还。','',''),('quantangshi-03080','初入湘中有喜','張九齡','quantangshi','','卷4','征鞍穷郢路，归棹入湘流。
望鸟唯贪疾，闻猿亦罢愁。
两边枫作岸，数处橘为洲。
却记从来意，翻疑梦里游。','',''),('quantangshi-03081','耒阳溪夜行','張九齡','quantangshi','','卷4','乘夕棹归舟，缘源路转幽。
月明看岭树，风静听溪流。
岚气船间入，霜华衣上浮。
猿声虽此夜，不是别家愁。','',''),('quantangshi-03082','江上','張九齡','quantangshi','','卷4','长林何缭绕，远水复悠悠。
尽日余无见，为心那不愁。
忆将亲爱别，行为主恩酬。
感激空如此，芳时屡已遒。','',''),('quantangshi-03083','自彭蠡湖初入江','張九齡','quantangshi','','卷4','江岫殊空阔，云烟处处浮。
上来羣噪鸟，中去独行舟。
牢落谁相顾，逶迤日自愁。
更将心问影，于役复何求。','',''),('quantangshi-03084','赴使泷峡','張九齡','quantangshi','','卷4','溪路日幽深，寒空入两嵚。
霜清百丈水，风落万重林。
夕鸟联归翼，秋猿断去心。
别离多远思，况乃岁方阴。','',''),('quantangshi-03085','湖口望庐山瀑布泉','張九齡','quantangshi','','卷4','万丈洪泉落，迢迢半紫氛。
奔飞流杂树，洒落出重云。
日照虹霓似，天清风雨闻。
灵山多秀色，空水共氤氲。','',''),('quantangshi-03086','浈阳峡','張九齡','quantangshi','','卷4','行舟傍越岑，窈窕越溪深。
水暗先秋冷，山晴当昼阴。
重林间五色，对壁耸千寻。
惜此生遐远，谁知造化心。','',''),('quantangshi-03087','使至广州','張九齡','quantangshi','','卷4','昔年尝不调，兹地亦邅回。
本谓双凫少，何知驷马来。
人非汉使橐，郡是越王台。
去去虽殊事，山川长在哉。','',''),('quantangshi-03088','春江晚景','張九齡','quantangshi','','卷4','江林多秀发，云日复相鲜。
征路那逢此，春心益渺然。
兴来秪自得，佳气莫能传。
薄暮津亭下，余花满客船。','',''),('quantangshi-03089','与王六履震广州津亭晓望','張九齡','quantangshi','','卷4','明发临前渚，寒来净远空。
水纹天上碧，日气海边红。
景物纷为异，人情赖此同。
乘槎自有适，非欲破长风。','',''),('quantangshi-03090','初发曲江溪中','張九齡','quantangshi','','卷4','溪流清且深，松石复阴临。
正尔可嘉处，胡为无赏心。
我由不忍别，物亦有缘侵。
自匪常行迈，谁能知此音。','',''),('quantangshi-03091','旅宿淮阳亭口号','張九齡','quantangshi','','卷4','日暮荒亭上，悠悠旅思多。
故乡临桂水，今夜渺星河。
暗草霜华发，空亭雁影过。
兴来谁与晤，劳者自为歌。','',''),('quantangshi-03092','望月怀远','張九齡','quantangshi','','卷4','海上生明月，天涯共此时。
情人怨遥夜，竟夕起相思。
灭烛怜光满，披衣觉露滋。
不堪盈手赠，还寝梦佳期。','',''),('quantangshi-03093','秋夕望月','張九齡','quantangshi','','卷4','清逈江城月，流光万里同。
所思如梦里，相望在庭中。
皎洁青苔露，萧条黄叶风。
含情不得语，频使桂华空。','',''),('quantangshi-03094','咏燕','張九齡','quantangshi','','卷4','海燕何微眇，乘春亦蹔来。
岂知泥滓贱，秪见玉堂开。
绣户时双入，华轩日几回。
无心与物竞，鹰隼莫相猜。','',''),('quantangshi-03095','故刑部李尚书荆谷山集会','張九齡','quantangshi','','卷4','尝闻继老耼，身退道弥耽。
结宇倚青壁，疎泉喷碧潭。
苔石随人古，烟花寄酒酣。
山光纷向夕，归兴杜城南。','',''),('quantangshi-03096','戏题春意','張九齡','quantangshi','','卷4','一作江南守，江林三四春。
相鸣不及鸟，相乐喜关人。
日守朱丝直，年催华发新。
淮阳秪有卧，持此度芳辰。','',''),('quantangshi-03097','庭梅咏','張九齡','quantangshi','','卷4','芳意何能早，孤荣亦自危。
更怜花蔕弱，不受岁寒移。
朝雪那相妬，阴风已屡吹。
馨香虽尚尔，飘荡复谁知。','',''),('quantangshi-03098','听筝','張九齡','quantangshi','','卷4','端居正无绪，那复发秦筝。
纤指传新意，繁弦起怨情。
悠扬思欲绝，掩抑态还生。
岂是声能感，人心自不平。','',''),('quantangshi-03099','初秋忆金均两弟','張九齡','quantangshi','','卷4','江渚秋风至，他乡离别心。
孤云愁自远，一叶感何深。
忧喜尝同域，飞鸣忽异林。
青山西北望，堪作白头吟。','',''),('quantangshi-03100','秋怀','張九齡','quantangshi','','卷4','感惜芳时换，谁知客思悬。
忆随鸿向暖，愁学马思边。
留滞机还息，纷拏网自牵。','',''),('quantangshi-03101','故刑部李尚书挽词三首 一','張九齡','quantangshi','','卷4','仙宗出赵北，相业起山东。
明德尝为礼，嘉谋屡作忠。
论经白虎殿，献赋甘泉宫。
与善今何在？苍生望已空。','',''),('quantangshi-03102','故刑部李尚书挽词三首 二','張九齡','quantangshi','','卷4','宿昔三台践，荣华驷马归。
印从青琐拜，翰入紫宸挥。
题剑恩方重，藏舟事已非。
龙门不可望，感激涕沾衣。','',''),('quantangshi-03103','故刑部李尚书挽词三首 三','張九齡','quantangshi','','卷4','永叹常山宝，沈埋京兆阡。
同盟会五月，华表记千年。
渺漫野中草，微茫空里烟。
共悲人事绝，唯对杜陵田。','',''),('quantangshi-03104','故徐州刺史赠吏部侍郎苏公挽歌词三首 一','張九齡','quantangshi','','卷4','韦玄方继相，荀爽复齐名。
在贵兼天爵，能贤出世卿。
学闻金马诏，神见玉人清。
藏壑今如此，为山遂不成。','',''),('quantangshi-03105','故徐州刺史赠吏部侍郎苏公挽歌词三首 二','張九齡','quantangshi','','卷4','相如只谢病，子敬忽云亡。
岂悟瑶台雪，分雕玉树行。
清规留草议，故事在封章。
本谓山公启，而今殁始扬。','',''),('quantangshi-03106','故徐州刺史赠吏部侍郎苏公挽歌词三首 三','張九齡','quantangshi','','卷4','返葬长安陌，秋风箫鼓悲。
奈何相送者，不是平生时。
寒影催年急，哀歌助晚迟。
宁知建旟罢，丹旐向京师。','',''),('quantangshi-03107','故荥阳君苏氏挽歌词三首 一','張九齡','quantangshi','','卷4','门绪公侯列，嫔风诗礼行。
松萝方有寄，桃李忽无成。
剑去双龙别，雏哀九凤鸣。
何言峄山树，还似半心生。','',''),('quantangshi-03108','故荥阳君苏氏挽歌词三首 二','張九齡','quantangshi','','卷4','永叹芳魂断，行看草露滋。
二宗荣盛日，千古别离时。
竟罢生刍赠，空留画扇悲。','',''),('quantangshi-03109','故荥阳君苏氏挽歌词三首 三','張九齡','quantangshi','','卷4','缟服纷相送，玄扃翳不开。
更悲泉火灭，徒见柳车回。
旧室容衣奠，新茔拱树栽。
唯应月照簟，潘岳此时哀。','',''),('quantangshi-03110','眉州康司马挽歌词','張九齡','quantangshi','','卷4','家受专门学，人称入室贤。
刘桢徒有气，管辂独无年。
谪去长沙国，魂归京兆阡。
从兹匣中劒，埋没罢冲天。','',''),('quantangshi-03111','奉和圣制早发三乡山行','張九齡','quantangshi','','卷4','羽衞森森西向秦，山川历历在清晨。
晴云稍卷寒岩树，宿雨能销御路尘。
圣德由来合天道，灵符即此应时巡。
遗贤一一皆羁致，犹欲高深访隐沦。','',''),('quantangshi-03112','奉和圣制龙池篇','張九齡','quantangshi','','卷4','天启神龙生碧泉，泉水灵源浸迤延。
飞龙已向珠潭出，积水仍将银汉连。
岸傍花柳看胜画，浦上楼台问是仙。
我后元符从此得，方为万岁寿图川。','',''),('quantangshi-03113','奉和圣制南郊礼毕酺宴','張九齡','quantangshi','','卷4','配天昭圣业，率土庆辉光。
春发三条路，酺开百戏场。
流恩均庶品，纵观聚康庄。
妙舞来平乐，新声出建章。
分曹日抱戴，赴节凤归昌。
幸奏承云乐，同曦湛露阳。
气和皆有感，泽厚自无疆。
饱德君臣醉，连歌奉柏梁。','',''),('quantangshi-03114','奉和圣制早渡蒲津关','張九齡','quantangshi','','卷4','魏武中流处，轩皇问道回。
长堤春树发，高掌曙云开。
龙负王舟渡，人占仙气来。
河津会日月，天仗役风雷。
东顾重关尽，西驰万国陪。
还闻股肱郡，元首咏康哉。','',''),('quantangshi-03115','奉和圣制同二相南出雀鼠谷','張九齡','quantangshi','','卷4','设险诸侯地，承平圣主巡。
东君朝二月，南斾拥三辰。
寒出重关尽，年随行漏新。
瑞云丛捧日，芳树曲迎春。
舞咏先驰道，恩华及从臣。
汾川花鸟意，并奉属车尘。','',''),('quantangshi-03116','奉和圣制经河上公庙','張九齡','quantangshi','','卷4','昔者河边叟，谁知隐与仙。
姓名终不识，章句此空传。
迹为坐忘晦，言犹强着诠。
精灵竟何所，祠宇独依然。
道在纡宸睠，风行动睿篇。
从兹化天下，清净复何先。','',''),('quantangshi-03117','奉和圣制送尚书燕国公赴朔方','張九齡','quantangshi','','卷4','宗臣事有征，庙筭在休兵。
天与三台座，人当万里城。
朔南方偃革，河右暂扬旌。
宠锡从仙禁，光华出汉京。
山川勤远畧，原隰轸皇情。
为奏薰琴唱，仍题宝劒名。
闻风六郡伏，计日五戎平。
山甫归应疾，留侯功复成。
歌钟旋可望，袵席岂难行。
四牡何时入？吾君忆履声。','',''),('quantangshi-03118','奉和圣制途经华山','張九齡','quantangshi','','卷4','万乘华山下，千岩云汉中。
灵居虽窅密，睿览忽玄同。
日月临高掌，神仙仰大风。
攒峯势岌岌，翊辇气雄雄。
揆物知幽赞，铭勋表圣衷。
会应陪玉检，来此告成功。','',''),('quantangshi-03119','奉和圣制早登太行山率尔言志','張九齡','quantangshi','','卷4','孟月摄提贞，乘时我后征。
晨严九折度，暮戒六军行。
日御驰中道，风师卷太清。
戈鋋林表出，组练雪间明。
动植希皇豫，高深奉睿情。
陪游七圣列，望幸百神迎。
气色烟犹喜，恩光草尚荣。
之罘称万岁，今此复同声。','',''),('quantangshi-03120','奉和圣制登封礼毕洛城酺宴','張九齡','quantangshi','','卷4','大君毕能事，端扆乐成功。
运与千龄合，欢将万国同。
汉酺歌圣酒，韶乐舞薰风。
河洛荣光遍，云烟喜气通。
春华顿觉早，天泽倍知崇。
草木皆沾被，犹言不在躬。','',''),('quantangshi-03121','恩赐乐游园宴应制','張九齡','quantangshi','','卷4','宝筵延厚命，供帐序羣公。
形胜宜春接，威仪建礼同。
曦阳人似露，解愠物从风。
朝庆千龄始，年华二月中。
辉光遍草木，和气发丝桐。
岁岁无为化，宁知乐九功。','',''),('quantangshi-03122','奉和圣制过王浚墓','張九齡','quantangshi','','卷4','汉王思钜鹿，晋将在弘农。
入蜀举长筭，平吴成大功。
与浑虽不协，归皓实为雄。
孤绩沦千载，流名感圣衷。
万乘度荒陇，一顾凛生风。
古节犹不弃，今人争效忠。','',''),('quantangshi-03123','奉和吏部崔尚书雨后大明朝堂望南山','張九齡','quantangshi','','卷4','迢递终南顶，朝朝阊阖前。
朅来青绮外，高在翠微先。
双凤褰为阙，羣龙俨若仙。
还知到玄圃，更是谒甘泉。
夜雨尘初灭，秋空月正悬。
诡容纷入望，霁色宛成妍。
东极华阴践，西弥嶓冢连。
奔峰出岭外，瀑水落云边。
汉帝宫将苑，商君陌与阡。
林华铺近甸，烟霭遶晴川。
既庶仁斯及，分忧政已宣。
山公启事罢，吉甫颂声传。
济济金门步，洋洋玉树篇。
徒歌虽有属，清越岂同年。','',''),('quantangshi-03124','和崔尚书喜雨','張九齡','quantangshi','','卷4','积阳虽有晦，经月未为灾。
上念人天重，先祈云汉回。
仁心及草木，号令起风雷。
照烂阴霞止，交纷瑞雨来。
三辰破黍稷，四达屏氛埃。
池溜因添满，林芳为洒开。
听中声滴沥，望处影徘徊。
惠泽成丰岁，昌言发上才。
无论验石鼓，不是御云台。
直颂皇恩浃，崇朝遍九垓。','',''),('quantangshi-03125','和许给事中直夜简诸公','張九齡','quantangshi','','卷4','未央钟漏晚，仙宇蔼沈沈。
武衞千庐合，严扃万户深。
左掖知天近，南窗见月临。
树摇金掌露，庭徙玉楼阴。
他日闻更直，中宵属所钦。
声华大国宝，夙夜近臣心。
逸兴乘高阁，雄飞在禁林。
宁思窃拚者，情发为知音。','',''),('quantangshi-03126','和苏侍郎小园夕霁寄诸弟','張九齡','quantangshi','','卷4','清风阊阖至，轩盖承明归。
云月爱秋景，林堂开夜扉。
何言兼济日，尚与宴私违。
兴逐蒹葭变，文因棠棣飞。
人伦用忠孝，帝德已光辉。
赠弟今为贵，方知陆氏微。','',''),('quantangshi-03127','酬宋使君见赠之作','張九齡','quantangshi','','卷4','时来不自意，宿昔谬枢衡。
翊圣负明主，妨贤愧友生。
罢归犹右职，待罪尚南荆。
政有留棠旧，风因继组成。
高轩问疾苦，烝庶荷仁明。
衰废时所薄，秪言僚故情。','',''),('quantangshi-03128','酬宋使君见诒','張九齡','quantangshi','','卷4','陟邻初禀训，献策幸逢时。
朝列且云忝，君恩复若兹。
庭闱际海曲，轺传荷天慈。
顾己欢乌鸟，闻君泣素丝。
才明应主召，福善岂神欺。
但愿白心在，终然湼不淄。','',''),('quantangshi-03129','酬通事舍人寓直见示篇中兼起居陆舍人景献','張九齡','quantangshi','','卷4','轩掖殊清秘，才华固在斯。
兴因膏泽洒，情与惠风吹。
所美应人誉，何私亦我仪。
同声感乔木，比翼谢长离。
价以陆生减，贤慙鲍叔知。
薄游尝独愧，芳讯乃兼施。
此夜金闺籍，伊人琼树枝。
飞鸣复何远，相顾幸媞媞。','',''),('quantangshi-03130','与袁补阙寻蔡拾遗会此公出行后蔡有五韵诗见赠以此篇答焉','張九齡','quantangshi','','卷4','辙迹陈家巷，诗书孟子邻。
偶来乘兴者，不值草玄人。
契是忘年合，情非累日申。
闻君还薄暮，见眷及兹辰。','',''),('quantangshi-03131','酬赵二侍御使西军赠两省旧僚之作','張九齡','quantangshi','','卷4','石室先鸣者，金门待制同。
操刀尝愿割，持斧竟称雄。
应敌兵初起，缘边虏欲空。
使车经陇月，征斾绕河风。
忽枉兼金讯，非徒秣马功。
气清蒲海曲，声满柏台中。
顾己尘华省，欣君震远戎。
明时独匪报，尝欲退微躬。','',''),('quantangshi-03132','武司功初有幽庭春暄见贻夏首获见以诗报焉','張九齡','quantangshi','','卷4','芳月尽离居，幽怀重起予。
虽言春事晚，尚想物华初。
迟日皦方照，高斋澹复虚。
笋成林向密，花落树应疎。
赠鲤情无间，求莺思有余。
暄妍不相待，含叹欲焉如。','',''),('quantangshi-03133','酬王履震游园林见贻','張九齡','quantangshi','','卷4','宅生惟海县，素业守郊园。
中览霸王说，上徼明主恩。
一行罢兰径，数载历金门。
既负潘生拙，俄从周任言。
逶迤恋轩陛，萧散反丘樊。
旧迳稀人迹，前池耗水痕。
并看芳树老，唯觉敝庐存。
自我栖幽谷，逢君翳覆盆。
孟轲应有命，贾谊得无冤。
江上行伤远，林间偶避喧。
地偏人事绝，时霁鸟声繁。
独善心俱闭，穷居道共尊。
乐因南涧藻，忧岂北堂萱。
幽意加投漆，新诗重赠轩。
平生徇知己，穷达与君论。','',''),('quantangshi-03134','饯王尚书出边','張九齡','quantangshi','','卷4','汉相推人杰，殷宗伐鬼方。
还闻出将重，坐见即戎良。
上策应为豫，中权且用光。
令申兵气倍，威憺虏魂亡。
树比公孙大，城如道济长。
夏云登陇首，秋露泫辽阳。
武德舒宸睠，文思饯乐章。
感恩身既许，激节胆犹尝。
祖帐倾朝列，军麾驻道傍。
诗人何所咏，尚父欲鹰扬。','',''),('quantangshi-03135','送赵都护赴安西','張九齡','quantangshi','','卷4','将相有更践，简心良独难。
远图尝画地，超拜乃登坛。
戎即昆山序，车同渤海单。
义无中国费，情必远人安。
他日文兼武，而今栗且宽。
自然来月窟，何用刺楼兰。
南至三冬晚，西驰万里寒。
封侯自有处，征马去嘽嘽。','',''),('quantangshi-03136','奉使自蓝田玉山南行','張九齡','quantangshi','','卷4','征骖入云壑，始忆步金门。
通籍微躯幸，归途明主恩。
匪唯徇行役，兼得慰晨昏。
是节暑云炽，纷吾心所尊。
海县且悠缅，山邮日骏奔。
徒知恶嚣事，未暇息阴论。
峣武经陈迹，衡湘指故园。
水闻南涧险，烟望北林繁。
远霭千岩合，幽声百籁喧。
阴泉夏犹冻，阳景昼方暾。
懿此高深极，徒令梦想存。
盛明期有报，长往复奚言。','',''),('quantangshi-03137','贺给事尝诣蔡起居郊馆有诗因命同作','張九齡','quantangshi','','卷4','记言闻直史，筑室面层阿。
岂不承明入，终云幽意多。
沈冥高士致，休澣故人过。
前岭游氛灭，中林芳气和。
兹辰阻佳趣，望美独如何。','',''),('quantangshi-03138','南山下旧居闲放','張九齡','quantangshi','','卷4','秪役已云久，乘闲返服初。
块然屏尘事，幽独坐林闾。
清旷前山远，纷喧此地疎。
乔木凌青霭，修篁媚绿渠。
耳和绣翼鸟，目畅锦鳞鱼。
寂寞心还间，飘颻体自虚。
兴来命旨酒，临罢阅仙书。
但乐多幽意，宁知有毁誉。
尚想争名者，谁云要路居。
都忘下流叹，倾夺竟何如。','',''),('quantangshi-03139','高斋闲望言怀','張九齡','quantangshi','','卷4','高斋复晴景，延眺属清秋。
风物动归思，烟林生远愁。
纷吾自穷海，薄宦此中州。
取路无高足，随波适下流。
岁华空冉冉，心曲且悠悠。
坐惜芳时歇，胡然久滞留。','',''),('quantangshi-03140','别乡人南还','張九齡','quantangshi','','卷4','橘柚南中暖，桑榆北地阴。
何言荣落异，因见别离心。
吾亦江乡子，思归梦寐深。
闻君去水宿，结思渺云林。
牵缀从浮事，迟回谢所钦。
东南行舫远，秋浦念猿吟。','',''),('quantangshi-03141','初发江陵有怀','張九齡','quantangshi','','卷4','极望涔阳浦，江天渺不分。
扁舟从此去，鸥鸟自为羣。
他日怀真赏，中年负俗纷。
适来果微尚，倏尔会斯文。
复想金闺籍，何如梦渚云。
我行多胜寄，浩思独氛氲。','',''),('quantangshi-03142','同綦毋学士月夜闻雁','張九齡','quantangshi','','卷4','栖宿岂无意，飞飞更远寻。
长途未及半，中夜有遗音。
月思关山笛，风号流水琴。
空声两相应，幽感一何深。
避缴归南浦，离羣呌北林。
联翩俱不定，怜尔越乡心。','',''),('quantangshi-03143','登总持寺阁','張九齡','quantangshi','','卷4','香阁起崔嵬，高高沙版开。
攀跻千仞上，纷诡万形来。
草间商君陌，云重汉后台。
山从函谷断，川向斗城回。
林里春容变，天边客思催。
登临信为美，怀远独悠哉。','',''),('quantangshi-03144','晚憩王少府东阁','張九齡','quantangshi','','卷4','披轩肆流览，云壑见深重。
空水秋弥净，林烟晚更浓。
坐隅分洞府，檐际列羣峰。
窈窕生幽意，参差多异容。
还慙大隐迹，空想列仙踪。
赖此升攀处，萧条得所从。','',''),('quantangshi-03145','登城楼望西山作','張九齡','quantangshi','','卷4','城楼枕南浦，日夕顾西山。
宛宛鸾鹤处，高高烟雾间。
仙井今犹在，洪厓久不还。
金编莫我授，羽驾亦难攀。
檐际千峰出，云中一鸟闲。
纵观穷水国，游思徧人寰。
勿复尘埃事，归来且闭关。','',''),('quantangshi-03146','祠紫盖山经玉泉山寺','張九齡','quantangshi','','卷4','指涂跻楚望，策马傍荆岑。
稍稍松篁入，泠泠磵谷深。
观奇逐幽暎，历险忘岖嵚。
上界投佛影，中天扬梵音。
焚香忏在昔，礼足誓来今。
灵异若有对，神仙真可寻。
高僧闻逝者，远俗是初心。
藓驳经行处，猿啼燕坐林。
归真已寂灭，留迹岂[湮沈]。
法地自兹广，何云千万金。','',''),('quantangshi-03147','洪州西山祈雨是日辄应因赋诗言事','張九齡','quantangshi','','卷4','兹山蕴灵异，走望良有归。
丘祷虽已久，甿心难重违。
迟明申藻荐，先夕旅岩扉。
独宿云峰下，萧条人吏稀。
我来不外适，幽抱自中微。
静入风泉奏，凉生松栝围。
穷年滞远想，寸晷阅清晖。
虚美怅无属，素情缄所依。
诡随嫌弱操，羇束谢贞肥。
义济亦吾道，诚存为物祈。
灵心倏已应，甘液幸而飞。
闭阁且无责，随车安敢希。
多慙德不感，知复是耶非。','',''),('quantangshi-03148','经江宁览旧迹至玄武湖','張九齡','quantangshi','','卷4','南国更数世，北湖方十洲。
天清华林苑，日晏景阳楼。
果下回仙骑，津傍驻彩斿。
凫鹥喧凤管，荷芰鬬龙舟。
七子陪诗赋，千人和棹讴。
应言在镐乐，不让横汾秋。
风俗因纾慢，江山成易由。
驹王信不武，孙叔是无谋。
佳气日将歇，霸功谁与修。
桑田东海变，麋鹿姑苏游。
否运争三国，康时劣九州。
山虽幕府在，馆岂豫章留。
水淀还相阅，菱歌亦故遒。
雄图不足问，唯想事风流。','',''),('quantangshi-03149','登襄阳岘山','張九齡','quantangshi','','卷4','昔年亟攀践，征马复来过。
信若山川旧，谁如岁月何。
蜀相吟安在，羊公碣已磨。
令图犹寂寞，嘉会亦蹉跎。
宛宛樊城岸，悠悠汉水波。
逶迤春日远，感寄客情多。
地本原林秀，朝来烟景和。
同心不同赏，留叹此岩阿。','',''),('quantangshi-03150','登荆州城楼','張九齡','quantangshi','','卷4','天宇何其旷，江城坐自拘。
层楼百余尺，迢递在西隅。
暇日时登眺，荒郊临故都。
累累见陈迹，寂寂想雄图。
古往山川在，今来郡邑殊。
北疆虽入郑，东距岂防吴。
几代传荆国，当时敌陕郛。
上流空有处，中土复何虞。
枕席夷三峡，关梁豁五湖。
承平无异境，守隘莫论夫。
自罢金门籍，来参竹使符。
端居向林薮，微尚在桑榆。
直似王陵戆，非如甯武愚。
今兹对南浦，乘雁与双凫。','',''),('quantangshi-03151','登乐游原春望书怀','張九齡','quantangshi','','卷4','城隅有乐游，表里见皇州。
策马既长远，云山亦悠悠。
万壑清光满，千门喜气浮。
花间直城路，草际曲江流。
凭眺兹为美，离居方独愁。
已惊玄发换，空度绿荑柔。
奋翼笼中鸟，归心海上鸥。
既伤日月逝，且欲桑榆收。
豹变焉能及，莺鸣非可求。
愿言从所好，初服返林丘。','',''),('quantangshi-03152','候使登石头驿楼作','張九齡','quantangshi','','卷4','山槛凭南望，川途眇北流。
远林天翠合，前浦日华浮。
万井缘津渚，千艘咽渡头。
渔商多末事，耕稼少良畴。
自守陈蕃榻，尝登王粲楼。
徒然骋目处，岂是获心游。
向迹虽愚谷，求名异盗丘。
息阴芳木所，空复越乡忧。','',''),('quantangshi-03153','登临沮楼','張九齡','quantangshi','','卷4','高深不可厌，巡属复来过。
本与众山绝，况兹韶景和。
危楼入水倒，飞槛向空摩。
杂树缘青壁，樛枝挂绿萝。
潭清能彻底，鱼乐好跳波。
有象言虽具，无端思转多。
同怀不在此，孤赏欲如何。','',''),('quantangshi-03154','陪王司马登薛公逍遥台','張九齡','quantangshi','','卷4','尝闻薛公泪，非直雍门琴。
窜逐留遗迹，悲凉见此心。
府中因暇豫，江上幸招寻。
人事已成古，风流独至今。
闲情多感叹，清景暂登临。
无复甘棠在，空余蔓草深。
晴光送远目，胜气入幽襟。
水去朝沧海，春来换碧林。
赋怀湘浦吊，碑想汉川沈。
曾是陪游日，徒为梁父吟。','',''),('quantangshi-03155','尝与大理丞袁公太府丞田公偶诣一所林沼尤胜因并坐其次相得甚欢遂赋诗焉以咏其事','張九齡','quantangshi','','卷4','方驾与吾友，同怀不异寻。
偶逢池竹处，便会江湖心。
夏近林方密，春余水更深。
清华两辉暎，闲步亦窥临。
苹藻复佳色，凫鹥亦好音。
韶芳媚洲渚，蕙气袭衣襟。
萧散皆为乐，裴回从所钦。
谓予成夙志，岁晚共抽簪。','',''),('quantangshi-03156','与弟游家园','張九齡','quantangshi','','卷4','定省荣君赐，来归是昼游。
林乌飞旧里，园果让新秋。
枝长南庭树，池临北涧流。
星霜屡尔别，兰麝为谁幽。
善积家方庆，恩深国未酬。
栖栖将义动，安得久情留。','',''),('quantangshi-03157','郡内闲斋','張九齡','quantangshi','','卷4','郡阁昼常掩，庭芜日复滋。
檐风落鸟毳，窗叶挂虫丝。
拙病宦情少，羇闲秋气悲。
理人无异绩，为郡但经时。
唯有江湖意，沈冥空在兹。','',''),('quantangshi-03158','城南隅山池春中田袁二公盛称其美夏首获赏果会夙言故有此咏','張九齡','quantangshi','','卷4','忆昨闻佳境，驾言寻昔蹊。
非惟初物变，亦与旧游暌。
幽渚为君说，清晨即我携。
途深独睥睨，历险共攀跻。
林笋苞青箨，津杨委绿荑。
荷香初出浦，草色复缘堤。
乐处将鸥狎，谭端用马齐。
且言临海郡，兼话武陵溪。
异壤风烟绝，空山岩迳迷。
如何际朝野，从此待金闺。','',''),('quantangshi-03159','西江夜行','張九齡','quantangshi','','卷4','遥夜人何在，澄潭月里行。
悠悠天宇旷，切切故乡情。
外物寂无扰，中流澹自清。
念归林叶换，愁坐露华生。
犹有汀洲鹤，宵分乍一鸣。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-03160','南还湘水言怀','張九齡','quantangshi','','卷4','拙宦今何有？劳歌念不成。
十年乖夙志，一别悔前行。
归去田园老，倘来轩冕轻。
江间稻正熟，林里桂初荣。
鱼意思在藻，鹿心怀食苹。
时哉苟不达，取乐遂吾情。','',''),('quantangshi-03161','商洛山行怀古','張九齡','quantangshi','','卷4','园绮值秦末，嘉遁此山阿。
陈迹向千古，荒途始一过。
硕人久沦谢，乔木自森罗。
故事昔尝览，遗风今岂讹。
泌泉空活活，樵叟独皤皤。
是处清晖满，从中幽兴多。
长怀赤松意，复忆紫芝歌。
避世辞轩冕，逢时解薜萝。
盛明今在运，吾道竟如何。','',''),('quantangshi-03162','南还以诗代书赠京师旧僚','張九齡','quantangshi','','卷4','薄宦晨昏阙，尊尊义取斯。
穷愁年貌改，寂历尔胡为。
不谄词多忤，无容礼益卑。
微生尚何有？远迹固其宜。
思扰梁山曲，情遥越鸟枝。
故园从海上，良友邈天涯。
云雨叹一别，川原劳载驰。
上慙伯乐顾，中负叔牙知。
去国诚寥落，经途弊险巇。
岁逢霜雪苦，林属蕙兰萎。
欲赠幽芳歇，行悲旧赏移。
一从关作限，两见月成规。
苒苒穷年龠，行行尽路岐。
征鞍税北渚，归帆指南垂。
树晚犹葱蒨，江寒尚渺弥。
土风从楚别，山水入湘奇。
石濑相奔触，烟林更蔽亏。
层崖夹洞浦，轻舸泛澄漪。
松筱行皆傍，禽鱼动輙随。
惜哉边地隔，不与故人窥。
畴昔陪鵷鹭，朝阳振羽仪。
来音虽寂寞，接景每逶迤。
朝罢冥尘事，宾来话酒巵。
邀欢逐芳草，结兴选华池。
及此风成叹，何时雾可披。
自怜无用者，谁念有情离。
望美音容阔，怀贤梦想疲。
因声达霄汉，持拙守东陂。','',''),('quantangshi-03163','初发道中赠王司马兼寄诸公','張九齡','quantangshi','','卷4','昔岁尝陈力，中年退屏居。
承颜方弄鸟，放性或观鱼。
曾是安疵拙，诚非议卷舒。
林园事益简，烟月赏恒余。
不意栖愚谷，无阶奉诏书。
湛恩均大造，弱植愧空虚。
肃命趋仙阙，侨装抚传车。
念行开祖帐，怜别降题舆。
谁谓风期许，叨延礼数殊。
义沾投分末，情及解携初。
追饯扶江介，光辉烛里闾。
子云应寂寞，公叔为吹嘘。
景物春来异，音容日向疎。
川原行稍稳，钟鼓听犹徐。
林隔王公轝，云迷班氏庐。
恋亲唯委咽，思德更踌躇。
徇义当由此，怀安乃阙如。
愿酬明主惠，行矣岂徒欤。','',''),('quantangshi-03164','自始兴溪夜上赴岭','張九齡','quantangshi','','卷4','尝蓄名山意，兹为世网牵。
征途屡及此，初服已非然。
日落青岩际，溪行绿筱边。
去舟乘月后，归鸟息人前。
数曲迷幽嶂，连圻触暗泉。
深林风绪结，遥夜客情悬。
非梗胡为泛，无膏亦自煎。','',''),('quantangshi-03165','当涂界寄裴宣州','張九齡','quantangshi','','卷4','故人宣城守，亦在江南偏。
如何分虎竹，相与间山川。
章绶胡为者，形骸非自然。
含情津渡阔，倚望脰空延。
远近闻佳政，平生仰大贤。
推心徒有属，会面良无缘。
日夕遵前渚，江村投暮烟。
念行秪意默，怀远岂言宣。
委曲风波事，难为尺素传。','',''),('quantangshi-03166','郡中每晨兴輙见羣鹤东飞至暮又行列而返哢唳云路甚和乐焉予愧独处江城常目送此意有所羡遂赋以诗','張九齡','quantangshi','','卷4','云间有数鹤，抚翼意无违。
晓日东田去，烟霄北渚归。
欢呼良自适，罗列好相依。
远集长江静，高翔众鸟稀。
岂烦仙子驭，何畏野人机。
却念乘轩者，拘留不得飞。','',''),('quantangshi-03167','和裴侍中承恩拜扫旋辔途中有怀寄州县官僚乡国亲故','張九齡','quantangshi','','卷4','嵩岳神惟降，汾川鼎气雄。
生才作霖雨，继代有清通。
天下称贤相，朝端挹至公。
自家来佐国，移孝入为忠。
霜露多前感，丘园想旧风。
扈巡过晋北，问俗到河东。
便道恩华降，还乡礼教崇。
野尊延故老，朝服见儿童。','',''),('quantangshi-03168','和姚令公哭李尚书乂','張九齡','quantangshi','','卷4','贵贱虽殊等，平生窃下风。
云泥势已绝，山海纳还通。
忽叹登龙者，翻将吊鹤同。
琴诗犹可托，剑履独成空。
畴昔尝论礼，兴言每匪躬。
人思崔琰议，朝掩祭遵公。
作善神何酷，依仁命不融。
天文虚北斗，人事罢南宫。
上幸既伤旧，下流弥感衷。
无恩报国士，徒欲问玄穹。','',''),('quantangshi-03169','奉和圣制经函谷关作','張九齡','quantangshi','','卷4','函谷虽云险，黄河已复清。
圣心无所隔，空此置关城。','',''),('quantangshi-03170','奉和圣制度潼关口号','張九齡','quantangshi','','卷4','嶙嶙故城垒，荒凉空戍楼。
在德不在险，方知王道休。','',''),('quantangshi-03171','答太常靳博士见赠一绝','張九齡','quantangshi','','卷4','上苑春先入，中园花尽开。
唯余幽径草，尚待日光催。','',''),('quantangshi-03172','登荆州城望江二首 一','張九齡','quantangshi','','卷4','滔滔大江水，天地相终始。
经阅几世人，复叹谁家子。','',''),('quantangshi-03173','登荆州城望江二首 二','張九齡','quantangshi','','卷4','东望何悠悠，西来昼夜流。
岁月既如此，为心那不愁。','',''),('quantangshi-03174','赋得自君之出矣','張九齡','quantangshi','','卷4','自君之出矣，不复理残机。
思君如满月，夜夜减清辉。','',''),('quantangshi-03175','答陆澧','張九齡','quantangshi','','卷4','松叶堪为酒，春来酿几多。
不辞山路远，踏雪也相过。','',''),('quantangshi-03176','奉和上元酺宴应诏','楊炯','quantangshi','','卷4','甲乙遇灾年，周隋送上弦。
妖星六丈出，沴气七重悬。
赤县空无主，苍生欲问天。
龟龙开宝命，云火昭灵庆。
万物覩真人，千秋逢圣政。
祖宗玄泽远，文武休光盛。
大号域中平，皇威天下惊。
参辰昭文物，宇宙浃声名。
汉后三章令，周王五伐兵。
匈奴穷地角，本自远正朔。
骄子起天街，由来亏礼乐。
一衣扫风雨，再战夷屯剥。
清明日月旦，萧索烟云涣。
寒暑既平分，阴阳复贞观。
惟神谐妙物，乃圣符幽赞。
下武发祯祥，平阶属会昌。
金泥封日观，璧水匝明堂。
业盛勋华德，兴包天地皇。
孝思义罔极，易礼光前式。
天焕三辰辉，灵书五云色。
敬时穷发歛，卜代盈千亿。
五纬聚华轩，重光入望园。
公卿论至道，天子拜昌言。
雷解初开出，星空即便元。
瑶台凉景荐，银阙秋阴遍。
百戏骋鱼龙，千门壮宫殿。
深仁洽蛮徼，恺乐周寰县。
宣室召羣臣，明庭礼百神。
仰德还符日，霑恩更似春。
襄城非牧竖，楚国有巴人。','',''),('quantangshi-03177','广溪峡','楊炯','quantangshi','','卷4','广溪三峡首，旷望兼川陆。
山路遶羊肠，江城镇鱼腹。
乔林百丈偃，飞水千寻瀑。
惊浪回高天，盘涡转深谷。
汉氏昔云季，中原争逐鹿。
天下有英雄，襄阳有龙伏。
常山集军旅，永安兴版筑。
池台忽已倾，邦家遽沦覆。
庸才若刘禅，忠佐为心腹。
设险犹可存，当无贾生哭。','',''),('quantangshi-03178','巫峡','楊炯','quantangshi','','卷4','三峡七百里，唯言巫峡长。
重岩窅不极，叠嶂凌苍苍。
绝壁横天险，莓苔烂锦章。
入夜分明见，无风波浪狂。
忠信吾所蹈，泛舟亦何伤。
可以涉砥柱，可以浮吕梁。
美人今何在？灵芝徒有芳。
山空夜猿啸，征客泪沾裳。','',''),('quantangshi-03179','西陵峡','楊炯','quantangshi','','卷4','绝壁耸万仞，长波射千里。
盘薄荆之门，滔滔南国纪。
楚都昔全盛，高丘烜望祀。
秦兵一旦侵，夷陵火潜起。
四维不复设，关塞良难恃。
洞庭且忽焉，孟门终已矣。
自古天地辟，流为峡中水。
行旅相赠言，风涛无极已。
及余践斯地，瓌奇信为美。
江山若有灵，千载伸知己。','',''),('quantangshi-03180','从军行','楊炯','quantangshi','','卷4','烽火照西京，心中自不平。
牙璋辞凤阙，铁骑绕龙城。
雪暗凋旗画，风多杂鼓声。
宁为百夫长，胜作一书生。','',''),('quantangshi-03181','刘生','楊炯','quantangshi','','卷4','卿家本六郡，年长入三秦。
白璧酬知己，黄金谢主人。
剑锋生赤电，马足起红尘。
日暮歌钟发，喧喧动四邻。','',''),('quantangshi-03182','骢马','楊炯','quantangshi','','卷4','骢马铁连钱，长安侠少年。
帝畿平若水，官路直如弦。
夜玉妆车轴，秋金铸马鞭。
风霜但自保，穷达任皇天。','',''),('quantangshi-03183','出塞','楊炯','quantangshi','','卷4','塞外欲纷纭，雌雄犹未分。
明堂占气色，华盖辨星文。
二月河魁将，三千太乙军。
丈夫皆有志，会见立功勋。','',''),('quantangshi-03184','有所思','楊炯','quantangshi','','卷4','贱妾留南楚，征夫向北燕。
三秋方一日，少别比千年。
不掩嚬红楼，无论数绿钱。
相思明月夜，迢递白云天。','',''),('quantangshi-03185','梅花落','楊炯','quantangshi','','卷4','窗外一株梅，寒花五出开。
影随朝日远，香逐便风来。
泣对铜鈎障，愁看玉镜台。
行人断消息，春恨几裴回。','',''),('quantangshi-03186','折杨柳','楊炯','quantangshi','','卷4','边地遥无极，征人去不还。
秋容凋翠羽，别泪损红颜。
望断流星驿，心驰明月关。
藁砧何处在？杨柳自堪攀。','',''),('quantangshi-03187','紫骝马','楊炯','quantangshi','','卷4','侠客重周游，金鞭控紫骝。
蛇弓白羽箭，鹤辔赤茸秋。
发迹来南海，长鸣向北州。
匈奴今未灭，画地取封侯。','',''),('quantangshi-03188','战城南','楊炯','quantangshi','','卷4','塞北途辽远，城南战苦辛。
幡旗如鸟翼，甲胄似鱼鳞。
冻水寒伤马，悲风愁杀人。
寸心明白日，千里暗黄尘。','',''),('quantangshi-03189','送临津房少府','楊炯','quantangshi','','卷4','岐路三秋别，江津万里长。
烟霞驻征盖，弦奏促飞觞。
阶树含斜日，池风泛早凉。
赠言未终竟，流涕忽沾裳。','',''),('quantangshi-03190','送丰城王少府','楊炯','quantangshi','','卷4','愁结乱如麻，长天照落霞。
离亭隐乔树，沟水浸平沙。
左尉才何屈，东关望渐赊。
行看转牛斗，持此报张华。','',''),('quantangshi-03191','送郑州周司空','楊炯','quantangshi','','卷4','汉国临清渭，京城枕浊河。
居人下珠泪，宾御促骊歌。
望极关山远，秋深烟雾多。
唯余三五夕，明月暂经过。','',''),('quantangshi-03192','送梓州周司功','楊炯','quantangshi','','卷4','御沟一相送，征马屡盘桓。
言笑方无日，离忧独未宽。
举杯聊劝酒，破涕暂为欢。
别后风清夜，思君蜀路难。','',''),('quantangshi-03193','送杨处士反初卜居曲江','楊炯','quantangshi','','卷4','雁门归去远，垂老脱袈裟。
萧寺休为客，曹溪便寄家。
绿琪千岁树，黄槿四时花。
别怨应无限，门前桂水斜。','',''),('quantangshi-03194','途中','楊炯','quantangshi','','卷4','悠悠辞鼎邑，去去指金墉。
途路盈千里，山川亘百重。
风行常有地，云出本多峰。
郁郁园中柳，亭亭山上松。
客心殊不乐，乡泪独无从。','',''),('quantangshi-03195','送刘校书从军','楊炯','quantangshi','','卷4','天将下三宫，星门召五戎。
坐谋资庙略，飞檄伫文雄。
赤土流星剑，乌号明月弓。
秋阴生蜀道，杀气绕湟中。
风雨何年别，琴尊此日同。
离亭不可望，沟水自西东。','',''),('quantangshi-03196','游废观','楊炯','quantangshi','','卷4','青幛倚丹田，荒凉数百年。
犹知小山桂，尚识大罗天。
药败金炉火，苔昏玉女泉。
岁时无壁画，朝夕有阶烟。
花柳三春节，江山四望悬。
悠然出尘网，从此狎神仙。','',''),('quantangshi-03197','和石侍御山庄','楊炯','quantangshi','','卷4','烟霞非俗宇，岩壑只幽居。
水浸何曾畎，荒郊不复锄。
影浓山树密，香浅泽花疎。
阔堑防斜径，平堤夹小渠。
莲房若个实，竹节几重虚。
萧然隔城市，酌醴焚枯鱼。','',''),('quantangshi-03198','送李庶子致仕还洛','楊炯','quantangshi','','卷4','此地倾城日，由来供帐华。
亭逢李广骑，门接邵平瓜。
原野烟氛匝，关河游望赊。
白云断岩岫，绿草覆江沙。
诏赐扶阳宅，人荣御史车。
灞池一相送，流涕向烟霞。','',''),('quantangshi-03199','早行','楊炯','quantangshi','','卷4','敞朗东方彻，阑干北斗斜。
地气俄成雾，天云渐作霞。
河流才辨马，岩路不容车。
阡陌经三岁，闾阎对五家。
露文沾细草，风影转高花。
日月从来惜，关山犹自赊。','',''),('quantangshi-03200','和崔司空伤姬人','楊炯','quantangshi','','卷4','昔时南浦别，鹤怨宝琴弦。
今日东方至，鸾销珠镜前。
水流衔砌咽，月影向窗悬。
妆匣凄余粉，熏炉灭旧烟。
晚庭摧玉树，寒帐委金莲。
佳人不再得，云日几千年。','',''),('quantangshi-03201','和骞右丞省中暮望','楊炯','quantangshi','','卷4','故事闲台阁，仙门蔼已深。
旧章窥复道，云幌肃重阴。
玄律葭灰变，青阳斗柄临。
年光摇树色，春气绕兰心。
风响高窗度，流痕曲岸侵。
天门总枢辖，人镜辨衣簪。
日暮南宫静，瑶华振雅音。','',''),('quantangshi-03202','和酬虢州李司法','楊炯','quantangshi','','卷4','唇齿标形胜，关河壮邑居。
寒山抵方伯，秋水面鸿胪。
君子从游宦，忘情任卷舒。
风霜下刀笔，轩盖拥门闾。
平野芸黄遍，长洲鸿雁初。
菊花宜泛酒，浦叶好裁书。
昔我芝兰契，悠然云雨疎。
非君重千里，谁有惠双鱼。','',''),('quantangshi-03203','和郑雠校内省眺瞩思乡怀友','楊炯','quantangshi','','卷4','铜门初下辟，石馆始沈研。
游雾千金字，飞云五色牋。
楼台横紫极，城阙俯青田。
暄入瑶房里，春回玉宇前。
霞文埋落照，风物澹归烟。
翰墨三余隙，关山四望悬。
颓峰暌酌羽，流水旷鸣弦。
虽欣承白雪，终恨隔青天。','',''),('quantangshi-03204','和旻上人伤果禅师','楊炯','quantangshi','','卷4','净业初中日，浮生大小年。
无人本无我，非后亦非前。
箫鼓旁喧地，龙蛇直映天。
法门摧栋宇，觉海破舟船。
书镇秦王饷，经文宋国传。
声华周百亿，风烈被三千。
芜没青园寺，荒凉紫陌田。
德音殊未远，拱木已生烟。','',''),('quantangshi-03205','和刘侍郎入隆唐观','楊炯','quantangshi','','卷4','福地阴阳合，仙都日月开。
山川临四险，城树隐三台。
伏槛排云出，飞轩遶涧回。
参差凌倒影，潇洒轶浮埃。
百果珠为实，羣峰锦作苔。
悬萝暗疑雾，瀑布响成雷。
方士烧丹液，真人泛玉杯。
还如问桃水，更似得蓬莱。
汉帝求仙日，相如作赋才。
自然金石奏，何必上天台。','',''),('quantangshi-03206','和辅先入昊天观星瞻','楊炯','quantangshi','','卷4','遁甲爰皇里，星占太乙宫。
天门开奕奕，佳气郁葱葱。
碧落三干外，黄图四海中。
邑居环若水，城阙抵新丰。
玉槛昆仑侧，金枢地轴东。
上真朝北斗，元始咏南风。
汉君祠五帝，淮王礼八公。
道书编竹简，灵液灌梧桐。
草茂琼阶绿，花繁宝树红。
石楼纷似画，地镜淼如空。
桑海年应积，桃源路不穷。
黄轩若有问，三月住崆峒。','',''),('quantangshi-03207','和刘长史答十九兄','楊炯','quantangshi','','卷4','帝尧平百姓，高祖宅三秦。
子弟分河岳，衣冠动缙绅。
盛名恒不陨，历代几相因。
街巷涂山曲，门闾洛水滨。
五龙金作友，一子玉为人。
宝剑丰城气，明珠魏国珍。
风标自落落，文质且彬彬。
共许刁元亮，同推周伯仁。
石城俯天阙，钟阜对江津。
骥足方遐骋，狼心独未驯。
鼓鼙鸣九域，风火集重闉。
城势余三板，兵威乏四邻。
居然混玉石，直置保松筠。
耿介酬天子，危言数贼臣。
钟仪琴未奏，苏武节犹新。
受禄宁辞死，扬名不顾身。
精诚动天地，忠义感明神。
怪鸟俄垂翼，修蛇竟暴鳞。
来朝拜休命，述职下梁岷。
善政驰金马，嘉声绕玉轮。
三荆忽有赠，四海更相亲。
宫征谐鸣石，光辉掩烛银。
山川遥满目，零露坐沾巾。
友爱光天下，恩波浃后尘。
懦夫仰高节，下里继阳春。','',''),('quantangshi-03208','夜送赵纵','楊炯','quantangshi','','卷4','赵氏连城璧，由来天下传。
送君还旧府，明月满前川。','',''),('quantangshi-03209','息夫人','之問','quantangshi','','卷4','可怜楚破息，肠断息夫人。
仍为泉下骨，不作楚王嫔。
楚王宠莫盛，息君情更亲。
情亲怨生别，一朝俱杀身。','',''),('quantangshi-03210','初到陆浑山庄','之問','quantangshi','','卷4','授衣感穷节，策马凌伊关。
归齐逸人趣，日觉秋琴闲。
寒露衰北阜，夕阳破东山。
浩歌步榛樾，栖鸟随我还。','',''),('quantangshi-03211','夜饮东亭','之問','quantangshi','','卷4','春泉鸣大壑，皓月吐层岑。
岑壑景色佳，慰我远游心。
暗芳足幽气，惊栖多众音。
高兴南山曲，长谣横素琴。','',''),('quantangshi-03212','芳树','之問','quantangshi','','卷4','何地早芳菲，宛在长门殿。
夭桃色若绶，穠李光如练。
啼鸟弄花疎，游蜂饮香遍。
叹息春风起，飘零君不见。','',''),('quantangshi-03213','送赵六贞固','之問','quantangshi','','卷4','目断南浦云，心醉东郊柳。
怨别此何时，春芳来已久。
与君共时物，尽此盈樽酒。
始愿今不从，春风恋携手。','',''),('quantangshi-03214','题张老松树','之問','quantangshi','','卷4','岁晚东岩下，周顾何凄恻。
日落西山阴，众草起寒色。
中有乔松树，使我长叹息。
百尺无寸枝，一生自孤直。','',''),('quantangshi-03215','别之望后独宿蓝田山庄','之問','quantangshi','','卷4','鹡鸰有旧曲，调苦不成歌。
自叹兄弟少，常嗟离别多。
尔寻北京路，予卧南山阿。
泉晚更幽咽，云秋尚嵯峨。
药栏听蝉噪，书幌见禽过。
愁至愿甘寝，其如乡梦何。','',''),('quantangshi-03216','浣纱篇赠陆上人','之問','quantangshi','','卷4','越女颜如花，越王闻浣纱。
国微不自宠，献作吴宫娃。
山薮半潜匿，苎萝更蒙遮。
一行霸句践，再笑倾夫差。
艳色夺人目，斆嚬亦相夸。
一朝还旧都，靓妆寻若耶。
鸟惊入松网，鱼畏沈荷花。
始觉冶容妄，方悟羣心邪。
钦子秉幽意，世人共称嗟。
愿言托君怀，倘类蓬生麻。
家住雷门曲，高阁凌飞霞。
淋漓翠羽帐，旖旎采云军。
春风艳楚舞，秋月缠胡笳。
自昔专娇爱，袭玩唯矜奢。
达本知空寂，弃彼犹泥沙。
永割偏执性，自长薰修芽。
携妾不障道，来止妾西家。','',''),('quantangshi-03217','雨从箕山来','之問','quantangshi','','卷4','雨从箕山来，倏与飘风度。
晴明西峰日，绿缛南溪树。
此时客精庐，幸蒙真僧顾。
深入清净理，妙断往来趣。
意得两契如，言尽共忘喻。
观花寂不动，闻鸟悬可悟。
向夕闻天香，淹留不能去。','',''),('quantangshi-03218','初至崖口','之問','quantangshi','','卷4','崖口众山断，嵚崟耸天壁。
气冲落日红，影入春潭碧。
锦缋织苔藓，丹青画松石。
水禽泛容与，岩花飞的皪。
微路从此深，我来限于役。
惆怅情未已，羣峰暗将夕。','',''),('quantangshi-03219','自湘源至潭州衡山县','之問','quantangshi','','卷4','浮湘沿迅湍，逗浦凝远盼。
渐见江势阔，行嗟水流漫。
赤岸杂云霞，绿竹缘溪涧。
向背羣山转，应接良景晏。
沓障连夜猿，平沙覆阳雁。
纷吾望阙客，归桡速已惯。
中道方溯洄，迟念自兹撰。
赖欣衡阳美，持以蠲忧患。','',''),('quantangshi-03220','入崖口五渡寄李适','之問','quantangshi','','卷4','抱琴登绝壑，伐木溯清川。
路极意谓尽，势回趣转绵。
人远草木秀，山深云景鲜。
余负海峤情，自昔微尚然。
弥旷十余载，今来宛仍前。
未窥仙源极，独进野人船。
时攀乳窦憩，屡薄天窗眠。
夜弦响松月，朝楫弄苔泉。
因冥象外理，永谢区中缘。
碧潭可遗老，丹砂堪学仙。
莫使驰光暮，空令归鹤怜。','',''),('quantangshi-03221','洞庭湖','之問','quantangshi','','卷4','地尽天水合，朝及洞庭湖。
初日当中涌，莫辨东西隅。
晶耀目何在，滢荧心欲无。
灵光晏海若，游气耿天吴。
张乐轩皇至，征苗夏禹徂。
楚臣悲落叶，尧女泣苍梧。
野积九江润，山通五岳图。
风恬鱼自跃，云夕雁相呼。
独此临泛漾，浩将人代殊。
永言洗氛浊，卒岁为清娱。
要使功成退，徒劳越大夫。','',''),('quantangshi-03222','景龙四年春祠海','之問','quantangshi','','卷4','肃事祠春溟，宵斋洗蒙虑。
鸡鸣见日出，鹭下惊涛鹜。
地阔八荒近，天回百川澍。
筵端接空曲，目外唯雰雾。
暖气物象来，周游晦明互。
致牲匪玄享，禋涤期灵煦。
的的波际禽，沄沄岛间树。
安期今何在，方丈蔑寻路。
仙事与世隔，冥搜徒已屡。
四明背羣山，遗老莫辨处。
抚中良自慨，弱龄忝恩遇。
三入文史林，两拜神仙署。
虽叹出关远，始知临海趣。
赏来空自多，理胜孰能喻。
留楫竟何待，徙倚忽云暮。','',''),('quantangshi-03223','温泉庄卧病寄杨七炯','之問','quantangshi','','卷4','移疾卧兹岭，寥寥倦幽独。
赖有嵩丘山，高枕长在目。
兹山栖灵异，朝夜翳云族。
是日蒙雨晴，返景入岩谷。
幂幂涧畔草，青青山下木。
此意方无穷，环顾怅林麓。
伊洛何悠漫，川原信重复。
夏余鸟兽蕃，秋末禾黍熟。
秉愿守樊圃，归闲欣艺牧。
惜无载酒人，徒把凉泉掬。','',''),('quantangshi-03224','答田征君','之問','quantangshi','','卷4','家临清溪水，溪水绕盘石。
绿萝四面垂，褭褭百余尺。
风泉度丝管，苔藓铺茵席。
传闻颍阳人，霞外漱灵液。
忽枉岩中翰，吟望朝复夕。
何当遂远游，物色候逋客。','',''),('quantangshi-03225','自衡阳至韶州谒能禅师','之問','quantangshi','','卷4','谪居窜炎壑，孤帆淼不系。
别家万里余，流目三春际。
猿啼山馆晓，虹饮江皐霁。
湘岸竹泉幽，衡峯石囷闭。
岭嶂穷攀越，风涛极沿济。
吾师在韶阳，欣此得躬诣。
洗虑宾空寂，焚香结精誓。
愿以有漏躯，聿薰无生慧。
物用益冲旷，心源日闲细。
伊我获此途，游道回晚计。
宗师信舍法，摈落文史艺。
坐禅罗浮中，寻异穷海裔。
何辞御魑魅，自可乘炎疠。
回首望旧乡，云林浩亏蔽。
不作离别苦，归期多年岁。','',''),('quantangshi-03226','见南山夕阳召监师不至','之問','quantangshi','','卷4','夕阳黯晴碧，山翠互明灭。
此中意无限，要与开士说。
徒郁仲举思，讵回道林辙。
孤兴欲待谁，待此湖上月。','',''),('quantangshi-03227','游法华寺','之問','quantangshi','','卷4','薄游京都日，遥羡稽山名。
分刺江海郡，朅来征素情。
松露洗心眷，象筵敷念诚。
薄云界青嶂，皎日骞朱甍。
苔涧深不测，竹房闲且清。
感真六象见，垂兆二𪅝鸣。
古今信灵迹，中州莫与京。
林巘永栖业，岂伊佐一生。
浮悟虽已久，事试去来成。
观念幸相续，庶几最后明。','',''),('quantangshi-03228','宿云门寺','之問','quantangshi','','卷4','云门若邪里，泛鷁路才通。
夤缘绿筱岸，遂得青莲宫。
天香众壑满，夜梵前山空。
漾漾潭际月，飔飗杉上风。
兹焉多嘉遯，数子今莫同。
凤归慨处士，鹿化闻仙公。
樵路郑州北，举井阿岩东。
永夜岂云寐，曙华忽葱茏。
谷鸟啭尚涩，源桃惊未红。
再来期春暮，当造林端穷。
庶几踪谢客，开山投剡中。','',''),('quantangshi-03229','春湖古意','之問','quantangshi','','卷4','院梅发向尺，园鸟复成曲。
落日游南湖，果掷颜如玉。
含情不得语，转盼知所属。
惆怅未可归，宁关须采菉。','',''),('quantangshi-03230','游陆浑南山自歇马岭到枫香林以诗代书答李舍人适','之問','quantangshi','','卷4','晨登歇马岭，遥望伏牛山。
孤出羣峰首，熊熊元气间。
太和亦崔嵬，石扇横闪倏。
细岑互攒倚，浮巘竞奔蹙。
白云遥入怀，青霭近可掬。
徒寻灵异迹，周顾惬心目。
晨拂鸟路行，暮投人烟宿。
稉稻远弥秀，栗芋秋新熟。
石髓非一岩，药苗乃万族。
间关踏云雨，缭绕缘水木。
西见商山芝，南到楚乡竹。
楚竹幽且深，半杂枫香林。
浩歌清潭曲，寄尔桃源心。','',''),('quantangshi-03231','早发大庾岭','之問','quantangshi','','卷4','晨跻大庾险，驿鞍驰复息。
雾露昼未开，浩途不可测。
嵥起华夷界，信为造化力。
歇鞍问徒旅，乡关在西北。
出门怨别家，登岭恨辞国。
自惟勖忠孝，斯罪懵所得。
皇明颇照洗，延议日纷惑。
兄弟远沦居，妻子成异域。
羽翮伤已毁，童幼怜未识。
踌蹰恋北顾，亭午曦霁色。
春暖阴梅花，瘴回阳鸟翼。
含沙缘涧聚，吻草依林植。
适蛮悲疾首，怀巩泪沾臆。
感谢鵷鹭朝，勤修魑魅职。
生还倘非远，誓拟酬恩德。','',''),('quantangshi-03232','自洪府舟行直书其事','之問','quantangshi','','卷4','仲春辞国门，畏途横万里。
越淮乘楚嶂，造江泛吴汜。
严程无休隙，日夜涉风水。
昔闻垂堂言，将诫千金子。
问余何奇剥，迁窜极炎鄙。
揆己道德余，幼闻虚白旨。
贵身贱外物，抗迹远尘轨。
朝游伊水湄，夕卧箕山趾。
妙年拙自晦，皎洁弄文史。
谬辱紫泥书，挥翰青云里。
事往每增伤，宠来常誓止。
铭骨怀报称，逆鳞让金紫。
安位衅潜构，退耕祸犹起。
栖岩实吾策，触藩诚内耻。
济济同时人，台庭鸣劒履。
愚以卑自衞，兀坐去沈滓。
迨兹理已极，窃位申知己。
羣议负宿心，获戾光华始。
黄金忽销铄，素业坐沦毁。
浩叹诬平生，何独恋枌梓。
浦树浮郁郁，皐兰覆靡靡。
百越去魂断，九疑望心死。
未尽匡阜游，远欣罗浮美。
周旋本师训，佩服无生理。
异国多灵仙，幽探忘年纪。
敝庐嵩山下，空谷茂兰芷。
悠悠南溟远，采掇长已矣。','',''),('quantangshi-03233','下桂江县黎壁','之問','quantangshi','','卷4','放溜觌前溆，连山分上干。
江回云壁转，天小雾峯攒。
吼沫跳急浪，合流环峻滩。
欹离出漩划，缭绕避涡盘。
舟子怯桂水，最言斯路难。
吾生抱忠信，吟啸自安闲。
旦别已千岁，夜愁劳万端。
企予见夜月，委曲破林峦。
潭旷竹烟尽，洲香橘露团。
岂傲夙所好，对之与俱欢。
思君罢琴酌，泣此夜漫漫。','',''),('quantangshi-03234','奉使嵩山途经缑岭','之問','quantangshi','','卷4','侵星发洛城，城中歌吹声。
毕景至缑岭，岭上烟霞生。
草树饶野意，山川多古情。
大隐德所薄，归来可退耕。','',''),('quantangshi-03235','伤王七秘书监寄呈扬州陆长史通简府僚广陵以广好事','之問','quantangshi','','卷4','王氏贵先宗，衡门栖道风。
传心晤有物，秉化游无穷。
学奥九流异，机玄三语同。
书乃墨场绝，文称词伯雄。
白屋藩魏主，苍生期谢公。
一祗贤良诏，遂谒承明宫。
补衮望奚塞，尊儒位未充。
罢官七门里，归老一丘中。
尝忝长者辙，微言私谓通。
我行会稽郡，路出广陵东。
物在人已矣，都疑淮海空。','',''),('quantangshi-03236','使至嵩山寻杜四不遇慨然复伤田洗马韩观主因以题壁赠杜侯杜四','之問','quantangshi','','卷4','洛桥瞻太室，期子在云烟。
归来不相见，孤赏弄寒泉。
与君阔松石，于兹二十年。
田公谢昭世，韩子秘幽埏。
忆昔同携手，山栖接二贤。
笙歌入玄地，诗酒坐寥天。
旧友悉零落，罢琴私自怜。
逝者非药误，餐霞意可全。
为余理还策，相与事灵仙。','',''),('quantangshi-03237','翫郡斋海榴','之問','quantangshi','','卷4','泽国韶气早，开帘延霁天。
野禽宵未啭，山蜚昼仍眠。
目兹海榴发，列暎岩楹前。
熠爚御风静，葳蕤含景鲜。
清晨绿堪佩，亭午丹欲然。
昔忝金闺籍，尝见玉池莲。
未若宗族地，更逢荣耀全。
南金虽自贵，贺赏讵能迁。
抚躬万里绝，岂染一朝妍。
徒缘滞遐郡，常是惜流年。
越俗鄙章甫，扪心空自怜。','',''),('quantangshi-03238','长安路','之問','quantangshi','','卷4','秦地平如掌，层城出云汉。
楼阁九衢春，车马千门旦。
绿柳开复合，红尘聚还散。
日晚鬬鸡场，经过狭斜看。','',''),('quantangshi-03239','折杨柳','之問','quantangshi','','卷4','玉树朝日映，罗帐春风吹。
拭泪攀杨柳，长条宛地垂。
白花飞历乱，黄鸟思参差。
妾自肝肠断，傍人那得知。','',''),('quantangshi-03240','有所思','之問','quantangshi','','卷4','君子事行役，再空芳岁期。
美人旷遥伫，万里浮云思。
园桃绽红艳，郊叶柔绿滋。
坐看长夏晚，秋月生罗帷。','',''),('quantangshi-03241','军中人日登高赠房明府','之問','quantangshi','','卷4','幽郊昨夜阴风断，顿觉朝来阳吹暖。
泾水桥南柳欲黄，杜陵城北花应满。
长安昨夜寄春衣，短翮登兹一望归。
闻道凯旋乘骑入，看君走马见芳菲。','',''),('quantangshi-03242','寒食还陆浑别业','之問','quantangshi','','卷4','洛阳城里花如雪，陆浑山中今始发。
旦别河桥杨柳风，夕卧伊川桃李月。
伊川桃李正芳新，寒食山中酒复春。
野老不知尧舜力，酣歌一曲太平人。','',''),('quantangshi-03243','寒食江州满塘驿','之問','quantangshi','','卷4','去年上巳洛桥边，今年寒食庐山曲。
遥怜巩树花应满，复见吴洲草新绿。
吴洲春草兰杜芳，感物思归怀故乡。
驿骑明朝宿何处？猿声今夜断君肠。','',''),('quantangshi-03244','至端州驿见杜五审言沈三佺期阎五朝隐王二无竞题壁慨然成咏','之問','quantangshi','','卷4','逐臣北地承严谴，谓到南中每相见。
岂意南中岐路多，千山万水分乡县。
云摇雨散各翻飞，海阔天长音信稀。
处处山川同瘴疠，自怜能得几人归。','',''),('quantangshi-03245','绿竹引','之問','quantangshi','','卷4','青溪绿潭潭水侧，修竹婵娟同一色。
徒生仙实凤不游，老死空山人讵识。
妙年秉愿逃俗纷，归卧嵩丘弄白云。
含情傲睨慰心目，何可一日无此君。','',''),('quantangshi-03246','明河篇','之問','quantangshi','','卷4','八月凉风天气晶，万里无云河汉明。
昏见南楼清且浅，晓落西山纵复横。
洛阳城阙天中起，长河夜夜千门里。
复道连甍共蔽亏，画堂琼户特相宜。
云母帐前初泛滥，水精帘外转逶迤。
倬彼昭回如练白，复出东城接南陌。
南陌征人去不归，谁家今夜捣寒衣。
鸳鸯机上疎萤度，乌鹊桥边一雁飞。
雁飞萤度愁难歇，坐见明河渐微没。
已能舒卷任浮云，不惜光辉让流月。
明河可望不可亲，愿得乘槎一问津。
更将织女支机石，还访成都卖卜人。','',''),('quantangshi-03247','龙门应制','之問','quantangshi','','卷4','宿雨霁氛埃，流云度城阙。
河堤柳新翠，苑树花先发。
洛阳花柳此时浓，山水楼台暎几重。
羣公拂雾朝翔凤，天子乘春幸凿龙。
凿龙近出王城外，羽从琳琅拥轩盖。
云罕才临御水桥，天衣已入香山会。
山壁崭岩断复连，清流澄澈俯伊川。
雁塔遥遥绿波上，星龛奕奕翠微边。
层峦旧长千寻木，远壑初飞百丈泉。
彩仗霓旌遶香阁，下辇登高望河洛。
东城宫阙拟昭回，南陌沟塍殊绮错。
林下天香七宝台，山中春酒万年杯。
微风一起祥花落，仙乐初鸣瑞鸟来。
鸟来花落纷无已，称觞献寿烟霞里。
歌舞淹留景欲斜，石关犹驻五云车。
鸟旗翼翼留芳草，龙骑骎骎暎晚花。
千乘万骑銮舆出，水静山空严警跸。
郊外喧喧引看人，倾都南望属车尘。
嚣声引扬闻黄道，佳气周回入紫宸。
先王定鼎山河固，宝命乘周万物新。
吾皇不事瑶池乐，时雨来观农扈春。','',''),('quantangshi-03248','初宿淮口','之問','quantangshi','','卷4','孤舟汴河水，去国情无已。
晚泊投楚乡，明月清淮里。
汴河东泻路穷兹，洛阳西顾日增悲。
夜闻楚歌思欲断，况值淮南木落时。','',''),('quantangshi-03249','王子乔','之問','quantangshi','','卷4','王子乔，爱神仙，七月七日上宾天。
白虎摇瑟凤吹笙，乘骑云气吸日精。
吸日精，长不归，遗庙今在而人非。
空望山头草，草露湿人衣。','',''),('quantangshi-03250','放白鹇篇','之問','quantangshi','','卷4','故人赠我绿绮琴，兼致白鹇鸟。
琴是峄山桐，鸟出吴溪中。
我心松石清霞里，弄此幽弦不能已。
我心河海白云垂，怜此珍禽空自知。
着书晚下麒麟阁，幼稚骄痴候门乐。
乃言物性不可违，白鹇愁慕刷毛衣。
玉徽闭匣留为念，六翮开笼任尔飞。','',''),('quantangshi-03251','桂州三月三日','之問','quantangshi','','卷4','代业京华里，远投魑魅乡。
登高望不极，云海四茫茫。
伊昔承休盼，曾为人所羡。
两朝赐颜色，二纪陪欢宴。
昆明御宿侍龙媒，伊阙天泉复几回。
西夏黄河水心劒，东周清洛羽觞杯。
苑中落花扫还合，河畔垂杨拨不开。
千春万寿多行乐，柏梁和歌攀睿作。
赐金分帛奉恩辉，风举云摇入紫微。
晨趋北阙鸣珂至，夜出南宫把烛归。
载笔儒林多岁月，襆被文昌佐吴越。
越中山海高且深，兴来无处不登临。
永和九年刺海郡，暮春三月醉山阴。
愚谓嬉游长似昔，不言流寓歘成今。
始安繁华旧风俗，帐饮倾城沸江曲。
主人丝管清且悲，客子肝肠断还续。
荔浦蘅皐万里余，洛阳音信绝能疎。
故园今日应愁思，曲水何能更祓除。
逐伴谁怜合浦叶，思归岂食桂江鱼。
不求汉使金囊赠，愿得佳人锦字书。','',''),('quantangshi-03252','下山歌','之問','quantangshi','','卷4','下嵩山兮多所思，携佳人兮步迟迟。
松间明月长如此，君再游兮复何时。','',''),('quantangshi-03253','冬宵引赠司马承祯','之問','quantangshi','','卷4','河有冰兮山有雪，北户墐兮行人绝。
独坐山中兮对松月，怀美人兮屡盈缺。
明月的的寒潭中，青松幽幽吟劲风。
此情不向俗人说，爱而不见恨无穷。','',''),('quantangshi-03254','高山引','之問','quantangshi','','卷4','攀云窈窕兮上跻悬峰，长路浩浩兮此去何从。
水一曲兮肠一曲，山一重兮悲一重。
松槚邈已远，友于何日逢？
况满室兮童稚，攒众虑于心胷。
天高难诉兮远负明德，却望咸京兮挥涕龙钟。','',''),('quantangshi-03255','嵩山天门歌','之問','quantangshi','','卷4','登天门兮坐盘石之磷𥒘，前漎漎兮未半，下漠漠兮无垠。
纷窈窕兮岩倚披以鹏翅，洞胶葛兮峰棱层以龙鳞。
松移岫转，左变而右易。
风生云起，出鬼而入神。
吾亦不知其灵怪如此，愿游杳冥兮见羽人。
重曰：天门兮穹崇，回合兮攒藂。
松万接兮柱日，石千寻兮倚空。
晚阴兮足风，夕阳兮赩红。
试一望兮夺魄，况众妙之无穷。','',''),('quantangshi-03256','有所思','之問','quantangshi','','卷4','洛阳城东桃李花，飞来飞去落谁家。
幽闺女儿惜颜色，坐见落花长叹息。
今年花落颜色改，明年花开复谁在。
已见松柏摧为薪，更闻桑田变成海。
古人无复洛城东，今人还对落花风。
年年岁岁花相似，岁岁年年人不同。
寄言全盛红颜子，须怜半死白头翁。
此翁白头真可怜，伊昔红颜美少年。
公子王孙芳树下，清歌妙舞落花前。
光禄池台交锦绣，将军楼阁画神仙。
一朝卧病无相识，三春行乐在谁边。
婉转蛾眉能几时，须臾鹤发乱如丝。
但看古来歌舞地，唯有黄昏鸟雀飞。','',''),('quantangshi-03257','奉和立春日侍宴内出剪彩花应制','之問','quantangshi','','卷4','金阁妆新杏，琼筵弄绮梅。
人间都未识，天上忽先开。
蜨绕香丝住，蜂怜艳粉回。
今年春色早，应为剪刀催。','',''),('quantangshi-03258','春日芙蓉园侍宴应制','之問','quantangshi','','卷4','芙蓉秦地沼，卢橘汉家园。
谷转斜盘径，川回曲抱原。
风来花自舞，春入鸟能言。
侍宴瑶池夕，归途笳吹繁。','',''),('quantangshi-03259','夏日仙蕚亭应制','之問','quantangshi','','卷4','高岭逼星河，乘舆此日过。
野含时雨润，山杂夏云多。
睿藻光岩穴，宸襟洽薜萝。
悠然小天下，归路满笙歌。','',''),('quantangshi-03260','奉和九月九日登慈恩寺浮屠应制','之問','quantangshi','','卷4','凤刹侵云半，虹旌倚日边。
散花多宝塔，张乐布金田。
时菊芳仙酝，秋兰动睿篇。
香街稍欲晚，清跸扈归天。','',''),('quantangshi-03261','奉和九日幸临渭亭登高应制得欢字','之問','quantangshi','','卷4','令节三秋晚，重阳九日欢。
仙杯还泛菊，宝馔且调兰。
御气云霄近，乘高宇宙宽。
今朝万寿引，宜向曲中弹。','',''),('quantangshi-03262','奉和圣制闰九月九日登庄严总持二寺阁','之問','quantangshi','','卷4','闰月再重阳，仙舆历宝坊。
帝歌云稍白，御酒菊犹黄。
风铎喧行漏，天花拂舞行。
豫游多景福，梵宇日生光。','',''),('quantangshi-03263','麟趾殿侍宴应制','之問','quantangshi','','卷4','北阙层城峻，西宫复道悬。
乘舆历万户，置酒望三川。
花柳含丹日，山河入绮筵。
欲知陪赏处，空外有飞烟。','',''),('quantangshi-03264','上阳宫侍宴应制得林字','之問','quantangshi','','卷4','广乐张前殿，重裘感圣心。
砌蓂霜月尽，庭树雪云深。
旧渥骖宸御，慈恩忝翰林。
微臣一何幸，再得听瑶琴。','',''),('quantangshi-03265','幸少林寺应制','之問','quantangshi','','卷4','绀宇横天室，回銮指帝休。
曙阴迎日尽，春气抱岩流。
空乐繁行漏，香烟薄彩斿。
玉膏从此泛，仙驭接浮丘。','',''),('quantangshi-03266','幸岳寺应制','之問','quantangshi','','卷4','蹔幸珠筵地，俱怜石濑清。
泛流张翠幕，拂迥挂红旌。
雅曲龙调管，芳樽蚁泛觥。
陪欢玉座晚，复得听金声。','',''),('quantangshi-03267','扈从登封途中作','之問','quantangshi','','卷4','帐殿郁崔嵬，仙游实壮哉。
晓云连幕卷，夜火杂星回。
谷暗千旗出，山鸣万乘来。
扈从良可赋，终乏掞天才。','',''),('quantangshi-03268','扈从登封告成颂','之問','quantangshi','','卷4','复道开行殿，钩陈列禁兵。
和风吹鼓角，佳气动旗旌。
后骑回天苑，前山入御营。
万方俱下拜，相与乐升平。','',''),('quantangshi-03269','松山岭应制','之問','quantangshi','','卷4','翼翼高旌转，锵锵凤辇飞。
尘销清跸路，云湿从臣衣。
白羽摇丹壑，天营逼翠微。
芳声耀今古，四海警宸威。','',''),('quantangshi-03270','缑山庙','之問','quantangshi','','卷4','王子宾仙去，飘颻笙鹤飞。
徒闻沧海变，不见白云归。
天路何其远，人间此会稀。
空歌日云暮，霜月渐微微。','',''),('quantangshi-03271','奉和梁王宴龙泓应教得微字','之問','quantangshi','','卷4','水府沦幽壑，星轺下紫微。
鸟惊司仆驭，花落侍臣衣。
芳树摇春晚，晴云绕座飞。
淮王正留客，不醉莫言归。','',''),('quantangshi-03272','寿阳王花烛图','之問','quantangshi','','卷4','仙媛乘龙日，天孙捧雁来。
可怜桃李树，更绕凤皇台。
烛照香车入，花临宝扇开。
莫令银箭晓，为尽合欢杯。','',''),('quantangshi-03273','江南曲','之問','quantangshi','','卷4','妾住越城南，离居不自堪。
采花惊曙鸟，摘叶餧春蚕。
懒结茱萸带，愁安玳瑁簪。
待君消瘦尽，日暮碧江潭。','',''),('quantangshi-03274','牛女','之問','quantangshi','','卷4','粉席秋期缓，针楼别怨多。
奔龙争渡月，飞鹊乱填河。
失喜先临镜，含羞未解罗。
谁能留夜色，来夕倍还梭。','',''),('quantangshi-03275','冬夜寓直麟阁','之問','quantangshi','','卷4','直事披三省，重关闭七门。
广庭怜雪净，深屋喜炉温。
月幌花虚馥，风窗竹暗喧。
东山白云意，兹夕寄琴尊。','',''),('quantangshi-03276','登禅定寺阁','之問','quantangshi','','卷4','梵宇出三天，登临望八川。
开襟坐霄汉，挥手拂云烟。
函谷青山外，昆池落日边。
东京杨柳陌，少别已经年。','',''),('quantangshi-03277','陆浑山庄','之問','quantangshi','','卷4','归来物外情，负杖阅岩耕。
源水看花入，幽林采药行。
野人相问姓，山鸟自呼名。
去去独吾乐，无然愧此生。','',''),('quantangshi-03278','蓝田山庄','之問','quantangshi','','卷4','宦游非吏隐，心事好幽偏。
考室先依地，为农且用天。
辋川朝伐木，蓝水暮浇田。
独与秦山老，相欢春酒前。','',''),('quantangshi-03279','春日山家','之問','quantangshi','','卷4','今日游何处？春泉洗药归。
悠然紫芝曲，昼掩白云扉。
鱼乐偏寻藻，人闲屡采薇。
丘中无俗事，身世两相违。','',''),('quantangshi-03280','春日宴宋主簿山亭得寒字','之問','quantangshi','','卷4','公子正邀欢，林亭春未兰。
攀岩践苔易，迷路出花难。
窗覆垂杨暖，阶侵瀑水寒。
帝城归路直，留兴接鵷鸾。','',''),('quantangshi-03281','江亭晚望','之問','quantangshi','','卷4','浩渺浸云根，烟岚出远村。
鸟归沙有迹，帆过浪无痕。
望水知柔性，看山欲断魂。
纵情犹未已，回马欲黄昏。','',''),('quantangshi-03282','秋晚游普耀寺','之問','quantangshi','','卷4','薄暮曲江头，仁祠暂可留。
山形无隐霁，野色徧呈秋。
荷覆香泉密，藤缘宝树幽。
平生厌尘事，过此忽悠悠。','',''),('quantangshi-03283','答李司户夔','之問','quantangshi','','卷4','远方来下客，輶轩摄使臣。
弄琴宜在夜，倾酒贵逢春。
驷马留孤馆，双鱼赠故人。
明朝散云雨，遥仰德为邻。','',''),('quantangshi-03284','寄天台司马道士','之問','quantangshi','','卷4','卧来生白发，览镜忽成丝。
远愧餐霞子，童颜且自持。
旧游惜疎旷，微尚日磷缁。
不寄西山药，何由东海期。','',''),('quantangshi-03285','使往天平军马约与陈子昂新乡为期及还而不相遇','之問','quantangshi','','卷4','入衞期之子，吁嗟不少留。
情人去何处？淇水日悠悠。
恒碣青云断，衡漳白露秋。
知君心许国，不是爱封侯。','',''),('quantangshi-03286','过函谷关','之問','quantangshi','','卷4','二百四十载，海内何纷纷。
六国兵同合，七雄势未分。
从成拒秦帝，策决问苏君。
鸡鸣将狗盗，论德不论勋。','',''),('quantangshi-03287','送朔方何侍郎','之問','quantangshi','','卷4','闻道云中使，乘骢往复还。
河兵守阳月，塞虏失阴山。
拜职尝随骠，铭功不让班。
旋闻受降日，歌舞入萧关。','',''),('quantangshi-03288','送田道士使蜀投龙','之問','quantangshi','','卷4','风驭忽泠然，云台路几千。
蜀门峯势断，巴字水形连。
人隔壶中地，龙游洞里天。
赠言回驭日，图画彼山川。','',''),('quantangshi-03289','送许州宋司马赴任','之問','quantangshi','','卷4','颍郡水东流，荀陈兄弟游。
偏伤兹日远，独向聚星州。
河润在明德，人康非外求。
当闻力为政，遥慰我心愁。','',''),('quantangshi-03290','送赵司马赴蜀州','之問','quantangshi','','卷4','饯子西南望，烟緜劒道微。
桥寒金雁落，林曙碧鸡飞。
职拜舆方远，仙成履会归。
定知和氏璧，遥掩玉轮辉。','',''),('quantangshi-03291','送永昌萧赞府','之問','quantangshi','','卷4','柳变曲江头，送君函谷游。
弄琴宽别意，酌醴醉春愁。
恋本亦何极，赠言微所求。
莫令金谷水，不入故园流。','',''),('quantangshi-03292','送李侍御','之問','quantangshi','','卷4','行李恋庭闱，乘轺振彩衣。
南登指吴服，北走出秦畿。
去国夏云断，还乡秋雁飞。
旋闻郡计入，更有使臣归。','',''),('quantangshi-03293','饯湖州薛司马','之問','quantangshi','','卷4','别驾促严程，离筵多故情。
交深季作友，义重伯为兄。
镇静移吴俗，风流在汉京。
会看陈仲举，从此拜公卿。','',''),('quantangshi-03294','送杜审言','之問','quantangshi','','卷4','卧病人事绝，嗟君万里行。
河桥不相送，江树远含情。
别路追孙楚，维舟吊屈平。
可惜龙泉劒，流落在丰城。','',''),('quantangshi-03295','送武进郑明府','之問','quantangshi','','卷4','弦歌试宰日，城阙赏心违。
北谢苍龙去，南随黄鹄飞。
夏云海中出，吴山江上微。
甿谣岂云远，从此庆缁衣。','',''),('quantangshi-03296','送姚侍御出使江东','之問','quantangshi','','卷4','帝忧河朔郡，南发海陵仓。
坐叹青春别，逶迤碧水长。
饮冰朝受命，衣锦昼还乡。
为问东山桂，无人何自芳。','',''),('quantangshi-03297','留别之望舍弟','之問','quantangshi','','卷4','同气有三人，分飞在此晨。
西驰巴岭徼，东去洛阳滨。
强饮离前酒，终伤别后神。
谁怜散花蕚，独赴日南春。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-03298','汉江宴别','之問','quantangshi','','卷4','汉广不分天，舟移杳若仙。
秋虹暎晚日，江鹤弄晴烟。
积水浮冠盖，遥风逐管弦。
嬉游不可极，留恨此山川。','',''),('quantangshi-03299','初发荆府赠长史','之問','quantangshi','','卷4','□□□□□，□□□□□。
仍随五马谪，载与两禽奔。
明主无由见，羣公莫与言。
幸君逢圣日，何惜理虞翻。','',''),('quantangshi-03300','晚泊湘江','之問','quantangshi','','卷4','五岭恓惶客，三湘顦顇颜。
况复秋雨霁，表里见衡山。
路逐鹏南转，心依雁北还。
唯余望乡泪，更染竹成斑。','',''),('quantangshi-03301','过蛮洞','之問','quantangshi','','卷4','越岭千重合，蛮溪十里斜。
竹迷樵子径，萍匝钓人家。
林暗交枫叶，园香覆橘花。
谁怜在荒外，孤赏足云霞。','',''),('quantangshi-03302','经梧州','之問','quantangshi','','卷4','南国无霜霰，连年见物华。
青林暗换叶，红橤续开花。
春去闻山鸟，秋来见海槎。
流芳虽可悦，会自泣长沙。','',''),('quantangshi-03303','渡吴江别王长史','之問','quantangshi','','卷4','倚棹望兹川，销魂独黯然。
乡连江北树，云断日南天。
劒别龙初没，书成雁不传。
离舟意无限，催渡复催年。','',''),('quantangshi-03304','泛镜湖南溪','之問','quantangshi','','卷4','乘兴入幽栖，舟行日向低。
岩花候冬发，谷鸟作春啼。
沓嶂开天小，丛篁夹路迷。
犹闻可怜处，更在若邪溪。','',''),('quantangshi-03305','途中寒食题黄梅临江驿寄崔融','之問','quantangshi','','卷4','马上逢寒食，愁中属暮春。
可怜江浦望，不见洛阳人。
北极怀明主，南溟作逐臣。
故园肠断处，日夜柳条新。','',''),('quantangshi-03306','游韶州广界寺','之問','quantangshi','','卷4','影殿临丹壑，香台隐翠霞。
巢飞衔象鸟，砌蹋雨空花。
宝铎摇初霁，金池暎晚沙。
莫愁归路远，门外有三车。','',''),('quantangshi-03307','宿清远峡山寺','之問','quantangshi','','卷4','香岫悬金刹，飞泉届石门。
空山唯习静，中夜寂无喧。
说法初闻鸟，看心欲定猿。
寥寥隔尘市，何异武陵源。','',''),('quantangshi-03308','题大庾岭北驿','之問','quantangshi','','卷4','阳月南飞雁，传闻至此回。
我行殊未已，何日复归来？
江静潮初落，林昏瘴不开。
明朝望乡处，应见陇头梅。','',''),('quantangshi-03309','度大庾岭','之問','quantangshi','','卷4','度岭方辞国，停轺一望家。
魂随南翥鸟，泪尽北枝花。
山雨初含霁，江云欲变霞。
但令归有日，不敢恨长沙。','',''),('quantangshi-03310','端州别袁侍郎','之問','quantangshi','','卷4','合浦途未极，端溪行蹔临。
泪来空泣脸，愁至不知心。
客醉山月静，猿啼江树深。
明朝共分手，之子爱千金。','',''),('quantangshi-03311','过史正议宅','之問','quantangshi','','卷4','旧交此零落，雨泣访遗尘。
劒几传好事，池台伤故人。
国香兰已歇，里树橘犹新。
不见吴中隐，空余江海滨。','',''),('quantangshi-03312','梁宣王挽词三首 一','之問','quantangshi','','卷4','贵藩尧母族，外戚汉家亲。
业重兴王际，功高复辟辰。
爱贤唯报国，乐善不防身。
今日衣冠送，空伤置醴人。','',''),('quantangshi-03313','梁宣王挽词三首 二','之問','quantangshi','','卷4','金精何日闭，玉匣此时开。
东望连吾子，南瞻近帝台。
地形龟食报，坟土燕衔来。
可叹虞歌夕，纷纷骑吹回。','',''),('quantangshi-03314','梁宣王挽词三首 三','之問','quantangshi','','卷4','像设千年在，平生万事违。
彩旌翻葆吹，圭翣奠灵衣。
壠日寒无影，郊云冻不飞。','',''),('quantangshi-03315','鲁忠王挽词三首 一','之問','quantangshi','','卷4','同盟会五月，归葬出三条。
日惨咸阳树，天寒渭水桥。
稍看朱鹭转，尚识紫骝骄。
寂寂泉台恨，从兹罢玉箫。','',''),('quantangshi-03316','鲁忠王挽词三首 二','之問','quantangshi','','卷4','邦家锡宠光，存没贵忠良。
遂裂山河地，追尊父子王。
人悲槐里月，马踏槿原霜。
别向天京北，悠悠此路长。','',''),('quantangshi-03317','鲁忠王挽词三首 三','之問','quantangshi','','卷4','树羽迎朝日，撞钟望早霞。
故人悲宿草，中使惨晨笳。
气有冲天劒，星无犯斗槎。
唯余孔公宅，长接鲁王家。','',''),('quantangshi-03318','范阳王挽词二首 一','之問','quantangshi','','卷4','贤相称邦杰，清流举代推。
公才掩诸夏，文体变当时。
宾吊飜成鹤，人亡惜喻龟。
洛阳今纸贵，犹写太冲词。','',''),('quantangshi-03319','范阳王挽词二首 二','之問','quantangshi','','卷4','赠秩徽章洽，求书秘草成。
客随朝露尽，人逐夜舟惊。
蒿里衣冠送，松门印绶迎。
谁知杨伯起，今日重哀荣。','',''),('quantangshi-03320','故赵王属赠黄门侍郎上官公挽词二首 一','之問','quantangshi','','卷4','韦门旌旧德，班氏业前书。
谪去因丞相，归来为倢伃。
周原乌相冢，越岭雁随车。
冥漠辞昭代，空怜赋子虚。','',''),('quantangshi-03321','故赵王属赠黄门侍郎上官公挽词二首 二','之問','quantangshi','','卷4','绿车随帝子，青琐翊宸机。
昔枉朝歌骑，今虚夕拜闱。
柳河凄挽曲，薤露湿灵衣。
一厝穷泉闭，双鸾遂不飞。','',''),('quantangshi-03322','药','之問','quantangshi','','卷4','有卉祕神仙，君臣有礼焉。
忻当苦口喻，不畏入肠偏。
扁鹊功成日，神农定品年。
丹成如可待，鸡犬自闻天。','',''),('quantangshi-03323','奉和九日登慈恩寺浮图应制','之問','quantangshi','','卷4','瑞塔千寻起，仙舆九日来。
萸房陈宝席，菊蘂散花台。
御气鹏霄近，升高凤野开。
天歌将梵乐，空里共裴回。','',''),('quantangshi-03324','送沙门泓景道俊玄奘还荆州应制','之問','quantangshi','','卷4','三乘归净域，万骑饯通庄。
就日离亭近，弥天别路长。
荆南旋杖钵，渭北限津梁。
何日纡真果，还来入帝乡。','',''),('quantangshi-03325','春日芙蓉园侍宴应制','之問','quantangshi','','卷4','年光竹里遍，春色杏间遥。
烟气笼青阁，流文荡画桥。
飞花随蝶舞，艳曲伴莺娇。
今日陪欢豫，还疑陟紫霄。','',''),('quantangshi-03326','咏笛','之問','quantangshi','','卷4','羌笛写龙声，长吟入夜清。
关山孤月下，来向陇头鸣。
逐吹梅花落，含春柳色惊。
行观向子赋，坐忆旧邻情。','',''),('quantangshi-03327','咏钟','之問','quantangshi','','卷4','既接南邻磬，还随北里笙。
平陵通曙响，长乐警宵声。
秋至含霜动，春归应律鸣。
岂惟恒待扣，金簴有余清。','',''),('quantangshi-03328','花落','之問','quantangshi','','卷4','铁骑几时回，金闺怨早梅。
雪寒花已落，风暖叶还开。
夕逐新春管，香迎小岁杯。
盛时何足贵，书里报轮台。','',''),('quantangshi-03329','旅宿淮阳亭口号','之問','quantangshi','','卷4','日暮风亭上，悠悠旅思多。
故乡临桂水，今夜渺星河。
暗草霜华发，空亭雁影过。
兴来谁与语，劳者自为歌。','',''),('quantangshi-03330','内题赋得巫山雨','之問','quantangshi','','卷4','神女向高唐，巫山下夕阳。
裴回作行雨，婉恋逐荆王。
电影江前落，雷声峡外长。
霁云无处所，台馆晓苍苍。','',''),('quantangshi-03331','王昭君','之問','quantangshi','','卷4','非君惜鸾殿，非妾妬娥眉。
薄命由骄虏，无情是画师。
嫁来胡地日，不竝汉宫时。
辛苦无聊赖，何堪上马辞。','',''),('quantangshi-03332','铜雀台','之問','quantangshi','','卷4','昔年分鼎地，今日望陵台。
一旦雄图尽，千秋遗令开。
绮罗君不见，歌舞妾空来。
恩共漳河水，东流无重回。','',''),('quantangshi-03333','巫山高','之問','quantangshi','','卷4','巫山峯十二，环合象昭回。
俯听琵琶峡，平看云雨台。
古槎天外落，瀑水日边来。
何忍猨啼夜，荆王枕席开。','',''),('quantangshi-03334','望月有怀','之問','quantangshi','','卷4','天使下西楼，含光万里秋。
台前似挂镜，帘外如悬钩。
张尹将眉学，班姬取扇俦。
佳期应借问，为报大刀头。','',''),('quantangshi-03335','驾出长安','之問','quantangshi','','卷4','圣德超千古，皇风扇九围。
天回万象出，驾动六龙飞。
淑气来黄道，祥云覆紫微。
太平多扈从，文物有光辉。','',''),('quantangshi-03336','饯中书侍郎来济','之問','quantangshi','','卷4','暧暧去尘昏灞岸，飞飞轻盖指河梁。
云峰衣结千重叶，雪岫花开几树妆。
深悲黄鹤孤舟远，独对青山别路长。
却将分手霑襟泪，还用持添离席觞。','',''),('quantangshi-03337','奉和春初幸太平公主南庄应制','之問','quantangshi','','卷4','青门路接凤凰台，素浐宸游龙骑来。
涧草自迎香辇合，岩花应待御筵开。
文移北斗成天象，酒递南山作寿杯。
此日侍臣将石去，共欢明主赐金回。','',''),('quantangshi-03338','三阳宫侍宴应制得幽字','之問','quantangshi','','卷4','离宫祕苑胜瀛洲，别有仙人洞壑幽。
岩边树色含风冷，石上泉声带雨秋。
鸟向歌筵来度曲，云依帐殿结为楼。
微臣昔忝方明御，今日还陪八骏游。','',''),('quantangshi-03339','奉和晦日幸昆明池应制','之問','quantangshi','','卷4','春豫灵池会，沧波帐殿开。
舟淩石鲸度，槎拂斗牛回。
节晦蓂全落，春迟柳暗催。
象溟看浴景，烧劫辨沈灰。
镐饮周文乐，汾歌汉武才。
不愁明月尽，自有夜珠来。','',''),('quantangshi-03340','奉和幸大荐福寺','之問','quantangshi','','卷4','香刹中天起，宸游满路辉。
乘龙太子去，驾象法王归。
殿饰金人影，窗摇玉女扉。
稍迷新草木，徧识旧庭闱。
水入禅心定，云从宝思飞。
欲知皇劫远，初拂六铢衣。','',''),('quantangshi-03341','奉和幸三会寺应制','之問','quantangshi','','卷4','六飞回玉辇，双树谒金仙。
瑞鸟呈书字，神龙吐浴泉。
净心遥证果，睿想独超禅。
塔涌香花地，山围日月天。
梵音迎漏彻，空乐倚云悬。
今日登仁寿，长看法镜圆。','',''),('quantangshi-03342','奉和荐福寺应制','之問','quantangshi','','卷4','梵筵光圣邸，游豫览宏规。
不改灵光殿，因开功德池。
莲生新步叶，桂长昔攀枝。
涌塔庭中见，飞楼海上移。
闻韶三月幸，观象七星危。
欲识龙归处，朝朝云气随。','',''),('quantangshi-03343','奉和幸神皐亭应制','之問','quantangshi','','卷4','清跸喧黄道，乘舆降紫宸。
霜戈凝晓日，云管发阳春。
台古全疑汉，林余半识秦。
宴酣诗布泽，节改令行仁。
昔恃山河险，今依道德淳。
多慙献嘉颂，空累属车尘。','',''),('quantangshi-03344','奉和幸长安故城未央宫应制','之問','quantangshi','','卷4','汉王未息战，萧相乃营宫。
壮丽一朝尽，威灵千载空。
皇明怅前迹，置酒宴羣公。
寒轻彩仗外，春发幔城中。
乐思回斜日，歌词继大风。
今朝天子贵，不假叔孙通。','',''),('quantangshi-03345','奉和幸韦嗣立山庄侍宴应制','之問','quantangshi','','卷4','枢掖调梅暇，林园艺槿初。
入朝荣劒履，退食偶琴书。
地隐东岩室，天回北斗车。
旌门临䆗窱，辇道属扶疎。
云罕明丹壑，霜笳彻紫虚。
水疑投石处，溪似钓璜余。
帝泽颁巵酒，人欢颂里闾。
一承黄竹咏，长奉白茅居。','',''),('quantangshi-03346','扈从登封告成颂应制','之問','quantangshi','','卷4','御路回中岳，天营接下都。
百灵无后至，万国竞前驱。
文衞严清跸，幽仙读宝符。
贝花明汉果，芝草入尧厨。
济济衣冠会，喧喧夷夏俱。
宗禋仰神理，刊木望川途。
抚己贫非病，时来本不愚。
愿陪丹凤辇，率舞白云衢。','',''),('quantangshi-03347','宴安乐公主宅得空字','之問','quantangshi','','卷4','英藩筑外馆，爱主出王宫。
宾至星槎落，仙来月宇空。
玳梁飜贺燕，金埒倚晴虹。
箫奏秦台里，书开鲁壁中。
短歌能驻日，艳舞欲娇风。
闻有淹留处，山阿满桂丛。','',''),('quantangshi-03348','春日郑协律山亭陪宴饯郑卿同用楼字','之問','quantangshi','','卷4','潘园枕郊郭，爱客坐相求。
尊酒东城外，骖騑南陌头。
池平分洛水，林缺见嵩丘。
暗竹侵山径，垂杨拂妓楼。
彩云歌处断，迟日舞前留。
此地何年别，兰芳空自幽。','',''),('quantangshi-03349','和姚给事寓直之作','之問','quantangshi','','卷4','清论满朝阳，高才拜夕郎。
还从避马路，来接珥貂行。
宠就黄扉日，威回白简霜。
柏台迁鸟茂，兰署得人芳。
禁静钟初彻，更疎漏渐长。
晓河低武库，流火度文昌。
寓直恩徽重，乘秋藻翰扬。
暗投空欲报，下调不成章。','',''),('quantangshi-03350','和库部李员外秋夜寓直之作','之問','quantangshi','','卷4','相庭贻庆远，才子拜郎初。
起草徯仙阁，焚香卧直庐。
更深河欲断，节劲柳偏疎。
气耿凌云笔，心摇待漏车。
叨荣厕俦侣，省己恧空虚。
徒裴阳春和，难参丽曲余。','',''),('quantangshi-03351','酬李丹徒见赠之作','之問','quantangshi','','卷4','镇吴称奥里，试剧仰通才。
近挹人披雾，遥闻境震雷。
一朝逢解榻，累日共衔杯。
连辔登山尽，浮舟望海回。
以予慙拙宦，期子遇良媒。
赠曲南凫断，征途北雁催。
更怜江上月，还入镜中开。','',''),('quantangshi-03352','使过襄阳登凤林寺阁','之問','quantangshi','','卷4','香阁临清汉，丹梯隐翠微。
林篁天际密，人世谷中违。
苔石衔仙洞，莲舟泊钓矶。
山云浮栋起，江雨入庭飞。
信美虽南国，严程限北归。
幽寻不可再，留步惜芳菲。','',''),('quantangshi-03353','宋公宅送甯谏议','之問','quantangshi','','卷4','宋公爰创宅，庾氏更诛茅。
间出人三秀，平临楚四郊。
汉臣来绛节，荆牧动金铙。
尊溢宜城酒，笙裁曲沃匏。
露荷秋变节，风柳夕鸣梢。
一散阳台雨，方随越鸟巢。','',''),('quantangshi-03354','送合宫苏明府颋','之問','quantangshi','','卷4','铉府诞英规，公才天下知。
谓乘羔雁族，继入凤皇池。
赤县求人隐，青门起路岐。
翟回车少别，凫化舃遥驰。
神哭周南境，童歌渭北垂。
贤哉荀奉倩，衮职伫来仪。','',''),('quantangshi-03355','送杨六望赴金水','之問','quantangshi','','卷4','借问梁山道，嵚岑几万重。
遥州刀作字，绝壁劒为峰。
惜别路穷此，留欢意不从。
忧来生白发，时晚爱青松。
勿以西南远，夷歌寝盛容。
台阶有高位，宁复久临邛。','',''),('quantangshi-03356','下桂江龙目滩','之問','quantangshi','','卷4','停午出滩险，轻舟容易前。
峰攒入云树，崖喷落江泉。
巨石潜山怪，深篁隐洞仙。
鸟游溪寂寂，猿啸岭娟娟。
挥袂日凡几，我行途已千。
暝投苍梧郡，愁枕白云眠。','',''),('quantangshi-03357','入泷州江','之問','quantangshi','','卷4','孤舟泛盈盈，江流日纵横。
夜杂蛟螭寝，晨披瘴疠行。
潭蒸水沫起，山热火云生。
猿躩时能啸，鸢飞莫敢鸣。
海穷南徼尽，乡远北魂惊。
泣向文身国，悲看凿齿氓。
地偏多育蛊，风恶好相鲸。
余本岩栖客，悠哉慕玉京。
厚恩尝愿答，薄宦不祈成。
违隐乖求志，披荒为近名。
镜愁玄发改，心负紫芝荣。
运启中兴历，时逢外域清。
祗应保忠信，延促付神明。','',''),('quantangshi-03358','始安秋日','之問','quantangshi','','卷4','桂林风景异，秋似洛阳春。
晚霁江天好，分明愁杀人。
卷云山𧥄𧥄，碎石水磷磷。
世业事黄老，妙年孤隐沦。
归欤卧沧海，何物贵吾身。','',''),('quantangshi-03359','桂州黄潭舜祠','之問','quantangshi','','卷4','虞世巡百越，相传葬九疑。
精灵游此地，祠树日光辉。
禋祭忽羣望，丹青图二妃。
神来兽率舞，仙去凤还飞。
日暝山气落，江空潭霭微。
帝乡三万里，乘彼白云归。','',''),('quantangshi-03360','登粤王台','之問','quantangshi','','卷4','江上粤王台，登高望几回。
南溟天外合，北户日边开。
地湿烟尝起，山晴雨半来。
冬花采卢橘，夏果摘杨梅。
迹类虞翻枉，人非贾谊才。
归心不可见，白发重相催。','',''),('quantangshi-03361','早发始兴江口至虚氏村作','之問','quantangshi','','卷4','候晓逾闽峤，乘春望越台。
宿云鹏际落，残月蚌中开。
薜荔摇青气，桄榔翳碧苔。
桂香多露裛，石响细泉回。
抱叶玄猿啸，衔花翡翠来。
南中虽可悦，北思日悠哉。
鬒发俄成素，丹心已作灰。
何当首归路，行剪故园莱。','',''),('quantangshi-03362','发藤州','之問','quantangshi','','卷4','朝夕苦遄征，孤魂长自惊。
泛舟依雁渚，投馆听猿鸣。
石发缘溪蔓，林衣埽地轻。
云峰刻不似，苔藓画难成。
露裛千花气，泉和万籁声。
攀幽红处歇，跻险绿中行。
恋切芝兰砌，悲缠松柏茔。
丹心江北死，白发岭南生。
魑魅天边国，穷愁海上城。
劳歌意无限，今日为谁明。','',''),('quantangshi-03363','游称心寺','之問','quantangshi','','卷4','释事怀三隐，清襟谒四禅。
江鸣潮未落，林晓日初悬。
宝叶交香雨，金沙吐细泉。
望谐舟客趣，思发海人烟。
顾枥仍留马，乘杯久弃船。
未忧龟负岳，且识鸟耘田。
理契都无象，心冥不寄筌。
安期庶可揖，天地得齐年。','',''),('quantangshi-03364','游法华寺','之問','quantangshi','','卷4','高岫拟耆闍，真乘引妙车。
空中结楼殿，意表出云霞。
后果缠三足，前因感六牙。
宴林薰宝树，水溜滴金沙。
寒谷梅犹浅，温庭橘未华。
台香红药乱，塔影绿篁遮。
果渐轮王族，缘超梵帝家。
晨行踏忍草，夜诵得灵花。
江郡将何匹，天都亦未加。
朝来沿泛所，应是逐仙槎。','',''),('quantangshi-03365','夜渡吴松江怀古','之問','quantangshi','','卷4','宿帆震泽口，晓渡松江濆。
棹发鱼龙气，舟冲鸿雁羣。
寒潮顿觉满，暗浦稍将分。
气出海生日，光清湖起云。
水乡尽天衞，叹息为吴君。
谋士伏劒死，至今悲所闻。','',''),('quantangshi-03366','谒禹庙','之問','quantangshi','','卷4','夏王乘四载，兹地发金符。
峻命终不易，报功畴敢渝。
先驱总昌会，后至伏灵诛。
玉帛空天下，衣冠照海隅。
旋闻厌黄屋，更道出苍梧。
林表祠转茂，山阿井讵枯。
舟迁龙负壑，田变鸟芸芜。
旧物森如在，天威肃未殊。
玄夷届瑶席，玉女侍清都。
奕奕扃闱邃，轩轩杖衞趋。
气青连曙海，云白洗春湖。
猿啸有时答，禽言常自呼。
灵歆异蒸糈，至乐匪笙竽。
茅殿今文袭，梅梁古制无。
运遥日崇丽，业盛答昭苏。
伊昔力云尽，而今功尚敷。
揆材非美箭，精享愧生刍。
郡职昧为理，邦空宁自诬。
下车霰已积，摄事露行濡。
人隐冀多佑，曷唯霑薄躯。','',''),('quantangshi-03367','游禹穴回出若邪','之問','quantangshi','','卷4','禹穴今朝到，邪溪此路通。
着书闻太史，炼药有仙翁。
鹤往笼犹挂，龙飞劒已空。
石帆摇海上，天镜落湖中。
水低寒云白，山边坠叶红。
归舟何虑晚，日暮使樵风。','',''),('quantangshi-03368','灵隐寺”','之問','quantangshi','','卷4','鹫岭郁岧峣，龙宫锁寂寥。
楼观沧海日，门对浙江潮。
桂子月中落，天香云外飘。
扪萝登墖远，刳木取泉遥。
霜薄花更发，冰轻叶未凋。
夙龄尚遐异，搜对涤烦嚣。
待入天台路，看余度石桥。','',''),('quantangshi-03369','游云门寺','之問','quantangshi','','卷4','维舟探静域，作礼事尊经。
投迹一萧散，为心自杳冥。
龛依大禹穴，楼倚少微星。
沓嶂围兰若，回溪抱竹庭。
觉花涂砌白，甘露洗山青。
雁塔骞金地，虹桥转翠屏。
人天宵现景，神鬼昼潜形。
理胜常虚寂，缘空自感灵。
入禅从鸽遶，说法有龙听。
劫累终期灭，尘躬且未宁。
摇摇不安寐，待月咏岩扃。','',''),('quantangshi-03370','早发韶州','之問','quantangshi','','卷4','炎徼行应尽，回瞻乡路遥。
珠厓天外郡，铜柱海南标。
日夜清明少，春冬雾雨饶。
身经大火热，颜入瘴江消。
触影含沙怒，逢人女草摇。
露浓看菌湿，风飓觉船飘。
直御魑将魅，宁论鸱与鸮。
虞翻思报国，许靖愿归朝。
绿树秦京道，青云洛水桥。
故园长在目，魂去不须招。','',''),('quantangshi-03371','早入清远峡','之問','quantangshi','','卷4','传闻峡山好，旭日棹前沂。
雨色摇丹嶂，泉声聒翠微。
两岩天作带，万壑树披衣。
秋菊迎霜序，春藤碍日辉。
翳潭花似织，缘岭竹成围。
寂历环沙浦，葱茏转石圻。
露余江未热，风落瘴初稀。
猿饮排虚上，禽惊掠水飞。
榜童夷唱合，樵女越吟归。
良候斯为美，边愁自有违。
谁言望乡国，流涕失芳菲。','',''),('quantangshi-03372','发端州初入西江','之問','quantangshi','','卷4','问我将何去？清晨溯越溪。
翠微县宿雨，丹壑饮晴霓。
树影捎云密，藤阴覆水低。
潮回出浦驶，洲转望乡迷。
人意长怀北，江行日向西。
破颜看鹊喜，拭泪听猿嗁/。
骨肉初分爱，亲朋忽解携。
路遥魂欲断，身辱理能齐。
畴日三山意，于兹万绪暌。
金陵有仙馆，即事寻丹梯。','',''),('quantangshi-03373','渡汉江','之問','quantangshi','','卷4','岭外音书断，经冬复历春。
近乡情更怯，不敢问来人。','',''),('quantangshi-03374','嵩山夜还','之問','quantangshi','','卷4','家住嵩山下，好采旧山薇。
自省游泉石，何曾不夜归。','',''),('quantangshi-03375','湖中别鉴上人','之問','quantangshi','','卷4','愿与道林近，在意逍遥篇。
自有灵佳寺，何用沃洲禅。','',''),('quantangshi-03376','题鉴上人房二首 一','之問','quantangshi','','卷4','落花双树积，芳草一庭春。
玩之堪兴异，何必见幽人。','',''),('quantangshi-03377','题鉴上人房二首 二','之問','quantangshi','','卷4','晚入应真理，经行尚未回。
房中无俗物，林下有青苔。','',''),('quantangshi-03378','答田征君','之問','quantangshi','','卷4','出游杳何处？迟回伊洛间。
归寝忽成梦，宛在嵩丘山。','',''),('quantangshi-03379','伤曹娘二首 一','之問','quantangshi','','卷4','凤飞楼伎绝，鸾死镜台空。
独怜脂粉气，犹着舞衣中。','',''),('quantangshi-03380','伤曹娘二首 二','之問','quantangshi','','卷4','河伯怜娇态，冯夷要姝妓。
寄言游戏人，莫弄黄河水。','',''),('quantangshi-03381','河阳','之問','quantangshi','','卷4','昔日河阳县，氛氲香气多。
曹娘娇态尽，春树不堪过。','',''),('quantangshi-03382','燕巢军幕','之問','quantangshi','','卷4','北关怜翠幕，不是厌朱楼。
故来呈燕颔，报道欲封侯。','',''),('quantangshi-03383','苑中遇雪应制','之問','quantangshi','','卷4','紫禁仙舆诘旦来，青旗遥倚望春台。
不知庭霰今朝落，疑是林花昨夜开。','',''),('quantangshi-03384','送司马道士游天台','之問','quantangshi','','卷4','羽客笙歌此地违，离筵数处白云飞。
蓬莱阙下长相忆，桐柏山头去不归。','',''),('quantangshi-03385','登逍遥楼','之問','quantangshi','','卷4','逍遥楼上望乡关，绿水泓澄云雾间。
北去衡阳二千里，无因雁足系书还。','',''),('quantangshi-03386','奉和春日玩雪应制','之問','quantangshi','','卷4','北阙彤云掩曙霞，东风吹雪舞山家。
琼章定少千人和，银树长芳六出花。','',''),('quantangshi-03387','伤曹娘二首 一','之問','quantangshi','','卷4','可怜冥漠去何之，独立丰茸无见期。
君看水上芙蓉色，恰似生前歌舞时。','',''),('quantangshi-03388','伤曹娘二首 二','之問','quantangshi','','卷4','前溪妙舞今应尽，子夜新歌遂不传。
无复绮罗娇白日，直将珠玉闭黄泉。','',''),('quantangshi-03389','郡宅中斋','之問','quantangshi','','卷4','郡宅枕层岭，春湖绕芳甸。
云甍出万家，卧览皆已徧。
渔商汗成雨，廨邑明若练。
越俗镜中行，夏祠云表见。
兹都信盘郁，英远常栖眄。
王子事黄老，独乐恣游衍。
谢公念苍生，同忧感推荐。
灵越多秀士，运阔无由面。
神理翳青山，风流满黄卷。
揆予谬承奖，自惜从缨弁。
瑶水执仙羁，金闺负时选。
晨趋博望苑，夜直明光殿。
一朝罢台阁，万里违乡县。
风土足慰心，况悦年芳变。
淮廪伫滋实，沂歌非所羡。
讼寝归四明，龄颓亲九转。
微尚本江海，少留岂交战。
唯余后凋色，窃比东南箭。','',''),('quantangshi-03390','称心寺','之問','quantangshi','','卷4','步陟招提宫，北极山海观。
千岩递萦绕，万壑殊悠漫。
乔木转夕阳，文轩划清涣。
泄云多表里，惊潮每昏旦。
问予金门客，何事沧洲畔。
谬以三署资，来刺百城半。
人隐尚未弭，岁华岂兼玩。
东山桂枝芳，明发坐盈叹。','',''),('quantangshi-03391','新年作','之問','quantangshi','','卷4','乡心新岁切，天畔独澘然。
老至居人下，春归在客先。
岭猨同旦暮，江柳共风烟。
已似长沙傅，从今又几年。','',''),('quantangshi-03392','剪彩','之問','quantangshi','','卷4','驻想持金错，居然作管灰。
绮罗纤手制，桃李向春开。
拾藻蜂初泊，衔花鸟未回。
不言将巧笑，飜逐美人来。','',''),('quantangshi-03393','七夕','之問','quantangshi','','卷4','传道仙星媛，年年会水隅。
停梭借蟋蟀，留巧付蜘蛛。
去昼从云请，归轮竚日输。
莫言相见阔，天上日应殊。','',''),('quantangshi-03394','桂州陪王都督晦日宴逍遥楼','之問','quantangshi','','卷4','晦节高楼望，山川一半春。
意随蓂叶尽，愁共柳条新。
投刺登龙日，开怀纳鸟晨。
兀然心似醉，不觉有吾身。','',''),('quantangshi-03395','和赵员外桂阳桥遇佳人','之問','quantangshi','','卷4','江雨朝飞浥细尘，阳桥花柳不胜春。
金鞍白马来从赵，玉面红妆本姓秦。
妬女犹怜镜中发，侍儿堪感路傍人。
荡舟为乐非吾事，自叹空闺梦寐频。','',''),('quantangshi-03396','函谷关','之問','quantangshi','','卷4','至人□□识仙风，瑞霭丹光远郁葱。
灵迹才辞周柱下，祥氛已入函关中。
不从紫气台端候，何得青华观里逢。
欲访乘牛求宝箓，愿随鹤驾徧瑶空。','',''),('quantangshi-03397','咏省壁画鹤','之問','quantangshi','','卷4','粉壁图仙鹤，昂藏真气多。
骞飞竟不去，当是恋恩波。','',''),('quantangshi-03398','广州朱长史座观妓','之問','quantangshi','','卷4','歌舞须连夜，神仙莫放归。
参差随暮雨，前路湿人衣。','',''),('quantangshi-03399','谒二妃庙','之問','quantangshi','','卷4','还以金屋贵，留兹宝席尊。
江凫啸风雨，山鬼泣朝昏。','',''),('quantangshi-03400','赠严侍御','之問','quantangshi','','卷4','受脤清边服，乘骢历塞尘。
当闻汉雪耻，羞共虏和亲。','',''),('quantangshi-03401','在荆州重赴岭南','之問','quantangshi','','卷4','梦泽三秋日，苍梧一片云。
还将鵷鹭羽，重入鹧鸪羣。','',''),('quantangshi-03402','则天皇后挽歌','之問','quantangshi','','卷4','象物行周礼，衣冠集汉都。
谁怜事虞舜，下里泣苍梧。','',''),('quantangshi-03403','邓国太夫人挽歌','之問','quantangshi','','卷4','鸾死铅妆歇，人亡锦字空。
悲端若能减，渭水亦应穷。','',''),('quantangshi-03404','杨将军挽歌','之問','quantangshi','','卷4','亭寒照苦月，陇暗积愁云。
今日山门树，何处有将军。','',''),('quantangshi-03405','塞垣行','崔湜','quantangshi','','卷4','疾风卷溟海，万里扬砂砾。
仰望不见天，昏昏竟朝夕。
是时军两进，东拒复西敌。
蔽山张旗鼓，间道潜锋镝。
精骑突晓围，奇兵袭暗壁。
十月边塞寒，四山冱阴积。
雨雪雁南飞，风尘景西迫。
昔我事讨论，未尝怠经籍。
一朝弃笔砚，十年操矛戟。
岂要黄河誓，须勒燕然石。
可嗟牧羊臣，海上久为客。','',''),('quantangshi-03406','送梁卿王郎中使东蕃吊册','崔湜','quantangshi','','卷4','梁侯上卿秀，王子中台杰。
赠册绥九夷，旌旃下双阙。
西堂礼乐送，南陌轩车别。
征路入海云，行舟溯江月。
兹邦久钦化，历载归朝谒。
皇心谅所嘉，寄尔宣风烈。','',''),('quantangshi-03407','饯唐州高使君赴任','崔湜','quantangshi','','卷4','芳春桃李时，京都物华好。
为岳岂不贵，所悲涉远道。
远道不可思，宿昔梦见之。
赠君双佩刀，日夕视来期。','',''),('quantangshi-03408','冀北春望','崔湜','quantangshi','','卷4','回首览燕赵，春生两河间。
旷然万里余，际海不见山。
雨歇青林润，烟空绿野闲。
问乡何处所，目送白云还。','',''),('quantangshi-03409','景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志','崔湜','quantangshi','','卷4','余本燕赵人，秉心愚且直。
羣籍备所见，孤贞每自饬。
徇禄期代耕，受任亦量力。
幸逢休明时，朝野两荐推。
一朝趋金门，十载奉瑶墀。
入掌迁固笔，出参枚马词。
吏部既三践，中书亦五期。
进无负鼎说，退慙补衮诗。
常恐婴悔吝，不得少酬私。
嗷嗷路傍子，纳谤纷无已。
上动明主疑，下贻大臣耻。
毫发顾无累，冰壶邈自持。
天道何期平，幽冤终见明。
始佐庐陵郡，寻牧襄阳城。
彤帏荷新宠，朱黻蒙旧荣。
力薄慙任重，恩深知命轻。
饬徒留前路，行子悲且慕。
犹闻长乐钟，尚辨青门树。
慈亲不忍诀，昆弟默相顾。
去去勿重陈，川长日云暮。','',''),('quantangshi-03410','大漠行','崔湜','quantangshi','','卷4','单于犯蓟堧，骠骑略萧边。
南山木叶飞下地，北海蓬根乱上天。
科斗连营太原道，鱼丽合阵武威川。
三军遥倚杖，万里相驰逐。
旌斾悠悠静瀚源，鼙鼓喧喧动卢谷。
穷徼上幽陵，吁嗟倦寝兴。
马蹄冻溜石，胡毳暖生冰。
云沙泱漭天光闭，河塞阴沈海色凝。
崆峒异国谁能托，萧索边心常不乐。
近见行人畏白龙，遥闻公主愁黄鹤。
阳春半，岐路间。
瑶台苑，玉门关。
百花芳树红将歇，二月兰皐绿未还。
阵云不散鱼龙水，雨雪犹飞鸿雁山。
山嶂连緜不可极，路远辛勤梦颜色。
北堂萱草不寄来，东园桃李长相忆。
汉将纷纭攻战盈，胡寇萧条幽朔清。
韩君拜节偏知远，郑吉驱旌坐见迎。
火绝烟沈右西极，谷静山空左北平。
但使将军能百战，不须天子筑长城。','',''),('quantangshi-03411','奉和登骊山高顶寓目应制','崔湜','quantangshi','','卷4','名山何壮哉，玄览一徘徊。
御路穿林转，旌门倚石开。
烟霞肘后发，河塞掌中来。
不学蓬壶远，经年犹未回。','',''),('quantangshi-03412','侍宴长宁公主东庄应制','崔湜','quantangshi','','卷4','沁园东郭外，鸾驾一游盘。
水榭宜时陟，山楼向晚看。
席临天女贵，杯接近臣欢。
圣藻悬宸象，微臣窃仰观。','',''),('quantangshi-03413','奉和送金城公主适西蕃应制','崔湜','quantangshi','','卷4','怀戎前策备，降女旧因修。
箫鼓辞家怨，旌旃出塞愁。
尚孩中念切，方远御慈留。
顾乏谋臣用，仍劳圣主忧。','',''),('quantangshi-03414','幸白鹿观应制','崔湜','quantangshi','','卷4','御旗探紫箓，仙杖辟丹丘。
捧药芝童下，焚香桂女留。
鸾歌无岁月，鹤语记春秋。
臣朔真何幸，常陪汉武游。','',''),('quantangshi-03415','幸梨园亭观打球应制','崔湜','quantangshi','','卷4','年光陌上发，香辇禁中游。
草绿鸳鸯殿，花明翡翠楼。
宝杯承露酌，仙管杂风流。
今日陪欢豫，皇恩不可酬。','',''),('quantangshi-03416','慈恩寺九日应制','崔湜','quantangshi','','卷4','帝里重阳节，香园万乘来。
却邪萸结佩，献寿菊传杯。
塔类承天涌，门疑待佛开。
睿词悬日月，长得仰昭回。','',''),('quantangshi-03417','折杨柳','崔湜','quantangshi','','卷4','二月风光半，三边戍不还。
年华妾自惜，杨柳为君攀。
落絮萦衫袖，垂条拂髻鬟。
那堪音信断，流涕望阳关。','',''),('quantangshi-03418','边愁','崔湜','quantangshi','','卷4','九月蓬根断，三边草叶腓。
风尘马变色，霜雪劒生衣。
客思愁阴晚，边书驿骑归。
殷勤凤楼上，还袂及春晖。','',''),('quantangshi-03419','婕妤怨','崔湜','quantangshi','','卷4','不分君恩断，新妆视镜中。
容华尚春日，娇爱已秋风。
枕席临窗晓，帷屏向月空。
年年后庭树，荣落在深宫。','',''),('quantangshi-03420','酬杜麟台春思','崔湜','quantangshi','','卷4','春还上林苑，花满洛阳城。
鸳衾夜凝思，龙镜晓含情。
忆梦残灯落，离魂暗马惊。
可怜朝与暮，楼上独盈盈。','',''),('quantangshi-03421','寄天台司马先生','崔湜','quantangshi','','卷4','闻有三元客，祈仙九转成。
人间白云返，天上赤龙迎。
尚惜金芝晚，仍攀琪树荣。
何年缑岭上，一谢洛阳城。','',''),('quantangshi-03422','唐都尉山池','崔湜','quantangshi','','卷4','曲渚扬轻舟，前溪钓晚流。
雁翻蒲叶起，鱼拨荇花游。
金子悬湘柚，珠房折海榴。
幽寻惜未已，清月半西楼。','',''),('quantangshi-03423','江楼夕望','崔湜','quantangshi','','卷4','试陟江楼望，悠悠去国情。
楚山霞外断，汉水月中平。
公子留遗邑，夫人有旧城。','',''),('quantangshi-03424','襄城即事','崔湜','quantangshi','','卷4','子牟怀魏阙，元凯滞襄城。
冠盖仍为里，沙台尚识名。
山光晴后绿，江色晚来清。','',''),('quantangshi-03425','秦州薛都督挽词','崔湜','quantangshi','','卷4','十里绛山幽，千年汾水流。
碑传门客见，劒是故人留。
陇树烟含夕，山门月照秋。
古来钟鼎盛，共尽一嵩丘。','',''),('quantangshi-03426','奉和春日幸望春宫','崔湜','quantangshi','','卷4','澹荡春光满晓空，逍遥御辇入离宫。
山河眺望云天外，台榭参差烟雾中。
庭际花飞锦绣合，枝间鸟啭管弦同。
即此欢娱齐镐宴，唯应率舞乐薰风。','',''),('quantangshi-03427','奉和幸韦嗣立山庄侍宴应制','崔湜','quantangshi','','卷4','丞相登前府，尚书启旧林。
式闾明主睿，荣族圣嫔心。
川狭旌门抵，岩高蔽帐临。
闲窗凭柳暗，小径入松深。
云卷千峰色，泉和万籁吟。
兰迎天女佩，竹碍侍臣簪。
宸翰三光烛，朝荣四海钦。
还嗟绝机叟，白首汉川阴。','',''),('quantangshi-03428','同李员外春闺','崔湜','quantangshi','','卷4','落日啼连夜，孤灯坐彻明。
卷帘双燕入，披幌百花惊。
陇上寒应晚，闺中织未成。
管弦愁不意，梳洗懒无情。
去岁闻西伐，今年送北征。
容颜离别尽，流恨满长城。','',''),('quantangshi-03429','襄阳早秋寄岑侍郎','崔湜','quantangshi','','卷4','江城秋气早，旭旦坐南闱。
落叶惊衰鬓，清霜换旅衣。
时来矜早达，事往觉前非。
体道徒推理，防身终昧微。
故人金华省，肃穆秉天机。
谁念江汉广，蹉跎心事违。','',''),('quantangshi-03430','赠苏少府赴任江南余时还京','崔湜','quantangshi','','卷4','丈夫不叹别，达士自安卑。
揽泣固无趣，衔杯空尔为。
流云春窈窕，去水暮逶迤。
行舟忽东泛，归骑亦西驰。
秦地多芳草，江潭有桂枝。
谁言阻遐阔，所贵在相知。','',''),('quantangshi-03431','登总持寺阁','崔湜','quantangshi','','卷4','宿雨清龙界，晨晖满凤城。
升攀重阁迥，凭览四郊明。
井邑周秦地，山河今古情。
纡余一水合，寥落五陵平。
处处风烟起，欣欣草木荣。
故人不可见，冠盖满东京。','',''),('quantangshi-03432','早春边城怀归','崔湜','quantangshi','','卷4','大漠羽书飞，长城未解围。
山川凌玉嶂，旌节下金微。
路向南庭远，书因北雁稀。
乡关摇别思，风雪散戎衣。
岁尽仍为客，春还尚未归。
明年征骑返，歌舞及芳菲。','',''),('quantangshi-03433','至桃林塞作','崔湜','quantangshi','','卷4','去国未千里，离家已再旬。
丹心恒恋阙，白首更辞亲。
怀璧常贻训，捐金讵得邻。
抱冤非忤物，罹谤岂由人。
不滥辞终辨，无瑕理竟伸。
黻还中省旧，符与外台新。
塞上同迁客，江潭异逐臣。
泪垂非属岘，肠断固由秦。
岁月行遒尽，山川难重陈。
始知亭伯去，还是拙谋身。','',''),('quantangshi-03434','襄阳作','崔湜','quantangshi','','卷4','庙堂初解印，郡邸忽腰章。
按节巡河右，鸣驺入汉阳。
城临南岘出，树绕北津长。
好学风犹扇，夸才俗未忘。
江山跨七泽，烟雨接三湘。
蛟浦菱荷净，渔舟橘柚香。
醉中求习氏，梦里忆襄王。
宅坏仍思凤，碑存更忆羊。
下车慙政美，闭阁幸时康。
多谢南征术，于今尚不亡。','',''),('quantangshi-03435','喜入长安','崔湜','quantangshi','','卷4','云日能催晓，风光不惜年。
赖逢征客尽，归在落花前。','',''),('quantangshi-03436','奉和幸韦嗣立山庄应制','崔湜','quantangshi','','卷4','竹径桃源本出尘，松轩茅栋别惊新。
御跸何须林下驻，山公不是俗中人。','',''),('quantangshi-03437','踏歌词二首 一','崔液','quantangshi','','卷4','彩女迎金屋，仙姬出画堂。
鸳鸯裁锦袖，翡翠贴花黄。
歌响舞分行，艳色动流光。','',''),('quantangshi-03438','踏歌词二首 二','崔液','quantangshi','','卷4','庭际花微落，楼前汉已横。
金台催夜尽，罗袖拂寒轻。
乐笑畅欢情，未半着天明。','',''),('quantangshi-03439','代春闺','崔液','quantangshi','','卷4','江南日暖鸿始来，柳条初碧叶半开。
玉关遥遥戍未回，金闺日夕生绿苔。
寂寂春花烟色暮，檐燕双双落花度。
青楼明镜昼无光，红帐罗衣徒自香。
妾恨十年长独守，君情万里在渔阳。','',''),('quantangshi-03440','上元夜六首 一','崔液','quantangshi','','卷4','玉漏银壶且莫催，铁关金锁彻明开。
谁家见月能闲坐，何处闻灯不看来。','',''),('quantangshi-03441','上元夜六首 二','崔液','quantangshi','','卷4','神灯佛火百轮张，刻像图形七宝装。
影里如闻金口说，空中似散玉毫光。','',''),('quantangshi-03442','上元夜六首 三','崔液','quantangshi','','卷4','今年春色胜常年，此夜风光最可怜。
鳷鹊楼前新月满，凤皇台上宝灯燃。','',''),('quantangshi-03443','上元夜六首 四','崔液','quantangshi','','卷4','金勒银鞍控紫骝，玉轮珠幰驾青牛。
骖驔始散东城曲，倏忽还来南陌头。','',''),('quantangshi-03444','上元夜六首 五','崔液','quantangshi','','卷4','公子王孙意气骄，不论相识也相邀。
最怜长袖风前弱，更赏新弦暗里调。','',''),('quantangshi-03445','上元夜六首 六','崔液','quantangshi','','卷4','星移汉转日将微，露洒烟飘灯渐稀。
犹惜路傍歌舞处，踌蹰相顾不能归。','',''),('quantangshi-03446','冀北春望','崔液','quantangshi','','卷4','回首览燕赵，春生两河间。
旷然余万里，际海不见山。
雨歇青林润，烟空绿野闲。
问乡无处所，目送白云关。','',''),('quantangshi-03447','拟古神女宛转歌二首 一','崔液','quantangshi','','卷4','风已清，月朗琴复明。
掩抑悲千态，殷勤是一声。
歌宛转，宛转和更长。
愿为双鸿鹄，比翼共翱翔。','',''),('quantangshi-03448','拟古神女宛转歌二首 二','崔液','quantangshi','','卷4','日已暮，长檐鸟应度。
此时望君君不来，此时思君君不顾。
歌宛转，宛转那能异栖宿。
愿为形与影，出入恒相逐。','',''),('quantangshi-03449','望韩公堆','崔滌','quantangshi','','卷4','韩公堆上望秦川，渺渺关山西接连。
孤客一身千里外，未知归日是何年。','',''),('quantangshi-03450','倬彼我系 一','王勃','quantangshi','','卷4','倬彼我系，出自有周。
分疆锡社，派别支流。
居衞仕宋，臣嬴相刘。
廼武廼文，或公或侯。','',''),('quantangshi-03451','倬彼我系 二','王勃','quantangshi','','卷4','晋历崩坼，衣冠扰弊。
粤自太原，播徂江澨。
礼丧贤隐，时屯道闭。
王室如毁，生人多殪。','',''),('quantangshi-03452','倬彼我系 三','王勃','quantangshi','','卷4','伊我有器，思逢其主。
自东施西，择木开宇。
田彼河曲，家乎汾浦。
天未厌乱，吾将谁辅。','',''),('quantangshi-03453','倬彼我系 四','王勃','quantangshi','','卷4','伊我祖德，思济九埏。
不常厥所，于兹五迁。
欲及时也，夫岂愿焉。
其位虽屈，其言则传。','',''),('quantangshi-03454','倬彼我系 五','王勃','quantangshi','','卷4','爰述帝制，大搜王道。
曰天曰人，是祖是考。
礼乐咸若，诗书具草。
贻厥孙谋，永为家宝。','',''),('quantangshi-03455','倬彼我系 六','王勃','quantangshi','','卷4','伊余小子，信慙明哲。
彼网有条，彼车有辙。
思屏人事，克终前烈。
于嗟代网，卒余来絏。','',''),('quantangshi-03456','倬彼我系 七','王勃','quantangshi','','卷4','来絏伊何，谓余曰仕。
我瞻先达，三十方起。
夫岂不怀，高山仰止。
愿言毓德，啜菽饮水。','',''),('quantangshi-03457','倬彼我系 八','王勃','quantangshi','','卷4','有鸟反哺，其声嗷嗷。
言念旧德，忧心忉忉。
今我不养，岁月其滔。
僶俛从役，岂敢告劳。','',''),('quantangshi-03458','倬彼我系 九','王勃','quantangshi','','卷4','从役伊何，薄求卑位。
告劳伊何，来参卿事。
名存实爽，负信愆义。
静言遐思，中心是愧。','',''),('quantangshi-03459','上巳浮江宴韵得址字','王勃','quantangshi','','卷4','披观玉京路，驻赏金台址。
逸兴怀九仙，良辰倾四美。
松吟白云际，桂馥青溪里。
别有江海心，日暮情何已。','',''),('quantangshi-03460','春日宴乐游园赋韵得接字','王勃','quantangshi','','卷4','帝里寒光尽，神臯春望浃。
梅郊落晚英，柳甸惊初叶。
流水抽奇弄，崩云洒芳牒。
清尊湛不空，暂喜平生接。','',''),('quantangshi-03461','山亭夜宴','王勃','quantangshi','','卷4','桂宇幽襟积，山亭凉夜永。
森沈野径寒，肃穆岩扉静。
竹晦南汀色，荷翻北潭影。
清兴殊未阑，林端照初景。','',''),('quantangshi-03462','咏风','王勃','quantangshi','','卷4','肃肃凉景生，加我林壑清。
驱烟寻磵户，卷雾出山楹。
去来固无迹，动息如有情。
日落山水静，为君起松声。','',''),('quantangshi-03463','怀仙','王勃','quantangshi','','卷4','鹤岑有奇径，麟洲富仙家。
紫泉漱珠液，玄岩列丹葩。
常希披尘网，眇然登云车。
鸾情极霄汉，凤想疲烟霞。
道存蓬瀛近，意惬朝市赊。
无为坐惆怅，虚此江上华。','',''),('quantangshi-03464','忽梦游仙','王勃','quantangshi','','卷4','仆本江上客，牵迹在方内。
寤寐霄汉间，居然有灵对。
翕尔登霞首，依然蹑云背。
电策驱龙光，烟途俨鸾态。
乘月披金帔，连星解琼佩。
浮识俄易归，真游邈难再。
寥廓沈遐想，周遑奉遗诲。
流俗非我乡，何当释尘昧。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-03465','杂曲','王勃','quantangshi','','卷4','智琼神女，来访文君。
蛾眉始约，罗袖初薰。
歌齐曲韵，舞乱行纷。
若向阳台荐枕，何啻得胜朝云。','',''),('quantangshi-03466','秋夜长','王勃','quantangshi','','卷4','秋夜长，殊未央。
月明白露澄清光，层城绮阁遥相望。
遥相望，川无梁。
北风受节南雁翔，崇兰委质时菊芳。
鸣环曳履出长廊，为君秋夜捣衣裳。
纤罗对凤皇，丹绮双鸳鸯。
调砧乱杵思自伤，思自伤，征夫万里戍他乡。
鹤关音信断，龙门道路长。
君在天一方，寒衣徒自香。','',''),('quantangshi-03467','采莲曲','王勃','quantangshi','','卷4','采莲归，绿水芙蓉衣。
秋风起浪凫雁飞，桂棹兰桡下长浦。
罗裙玉腕轻摇橹，叶屿花潭极望平。
江讴越吹相思苦，相思苦，佳期不可驻。
塞外征夫犹未还，江南采莲今已暮。
今已暮，采莲花，渠今那必尽娼家。
官道城南把桑叶，何如江上采莲花。
莲花复莲花，花叶何稠叠。
叶翠本羞眉，花红强如颊。
佳人不在兹，怅望别离时。
牵花怜共蒂，折藕爱连丝。
故情无处所，新物从华滋。
不惜西津交佩解，还羞北海雁书迟。
采莲歌有节，采莲夜未歇。
正逢浩荡江上风，又值裴回江上月。
裴回莲浦夜相逢，吴姬越女何丰茸。
共问寒江千里外，征客关山路几重。','',''),('quantangshi-03468','临高台','王勃','quantangshi','','卷4','临高台，高台迢遰绝浮埃。
瑶轩绮构何崔嵬，鸾歌凤吹清且哀。
俯瞰长安道，萋萋御沟草。
斜对甘泉路，苍苍茂陵树。
高台四望同，帝乡佳气郁葱葱。
紫阁丹楼纷照耀，璧房锦殿相玲珑。
东弥长乐观，西指未央宫。
赤城映朝日，绿树摇春风。
旗亭百隧开新市，甲第千甍分戚里。
朱轮翠盖不胜春，叠榭层楹相对起。
复有青楼大道中，绣户文窗雕绮栊。
锦衾夜不襞，罗帷昼未空。
歌屏朝揜翠，妆镜晚窥红。
为君安宝髻，蛾眉罢花丛。
尘间狭路黯将暮，云间月色明如素。
鸳鸯池上两两飞，凤凰楼下双双度。
物色正如此，佳期那不顾。
银鞍绣毂盛繁华，可怜今夜宿娼家。
娼家少妇不须颦，东园桃李片时春。
君看旧日高台处，柏梁铜雀生黄尘。','',''),('quantangshi-03469','滕王阁','王勃','quantangshi','','卷4','滕王高阁临江渚，佩玉鸣鸾罢歌舞。
画栋朝飞南浦云，珠帘暮卷西山雨。
闲云潭影日悠悠，物换星移几度秋。
阁中帝子今何在？槛外长江空自流。','',''),('quantangshi-03470','江南弄','王勃','quantangshi','','卷4','江南弄，巫山连楚梦，行雨行云几相送。
瑶轩金谷上春时，玉童仙女无见期。
紫露香烟渺难托，清风明月遥相思。
遥相思，草徒绿，为听双飞凤凰曲。','',''),('quantangshi-03471','圣泉宴','王勃','quantangshi','','卷4','披襟乘石磴，列籍俯春泉。
兰气熏山酌，松声韵野弦。
影飘垂叶外，香度落花前。
兴洽林塘晚，重岩起夕烟。','',''),('quantangshi-03472','寻道观','王勃','quantangshi','','卷4','芝廛光分野，蓬阙盛规模。
碧坛清桂阈，丹洞肃松枢。
玉笈三山记，金箱五岳图。
苍虬不可得，空望白云衢。','',''),('quantangshi-03473','散关晨度','王勃','quantangshi','','卷4','关山凌旦开，石路无尘埃。
白马高谭去，青牛真气来。
重门临巨壑，连栋起崇隈。
即今扬策度，非是弃繻回。','',''),('quantangshi-03474','别薛华','王勃','quantangshi','','卷4','送送多穷路，遑遑独问津。
悲凉千里道，凄断百年身。
心事同漂泊，生涯共苦辛。
无论去与住，俱是梦中人。','',''),('quantangshi-03475','重别薛华','王勃','quantangshi','','卷4','明月沈珠浦，秋风濯锦川。
楼台临绝岸，洲渚亘长天。
旅泊成千里，栖遑共百年。
穷途唯有泪，还望独潸然。','',''),('quantangshi-03476','游梵宇三觉寺','王勃','quantangshi','','卷4','杏阁披青磴，雕台控紫岑。
叶齐山路狭，花积野坛深。
萝幌栖禅影，松门听梵音。
遽忻陪妙躅，延赏涤烦襟。','',''),('quantangshi-03477','麻平晚行','王勃','quantangshi','','卷4','百年怀土望，千里倦游情。
高低寻戍道，远近听泉声。
磵叶才分色，山花不辨名。
羁心何处尽？风急暮猨清。','',''),('quantangshi-03478','送卢主簿','王勃','quantangshi','','卷4','穷途非所恨，虚室自相依。
城阙居年满，琴尊俗事稀。
开襟方未已，分袂忽多违。
东岩富松竹，岁暮幸同归。','',''),('quantangshi-03479','饯韦兵曹','王勃','quantangshi','','卷4','征骖临野次，别袂惨江垂。
川霁浮烟歛，山明落照移。
鹰风凋晚叶，蝉露泣秋枝。
亭臯分远望，延想间云涯。','',''),('quantangshi-03480','白下驿饯唐少府','王勃','quantangshi','','卷4','下驿穷交日，昌亭旅食年。
相知何用早，怀抱即依然。
浦楼低晚照，乡路隔风烟。
去去如何道，长安在日边。','',''),('quantangshi-03481','杜少府之任蜀州','王勃','quantangshi','','卷4','城阙辅三秦，风烟望五津。
与君离别意，同是宦游人。
海内存知己，天涯若比隣。
无为在岐路，儿女共霑巾。','',''),('quantangshi-03482','仲春郊外','王勃','quantangshi','','卷4','东园垂柳径，西堰落花津。
物色连三月，风光绝四隣。
鸟飞村觉曙，鱼戏水知春。','',''),('quantangshi-03483','郊兴','王勃','quantangshi','','卷4','空园歌独酌，春日赋闲居。
泽兰侵小径，河柳覆长渠。
雨去花光湿，风归叶影疎。
山人不惜醉，唯畏绿尊虚。','',''),('quantangshi-03484','郊园即事','王勃','quantangshi','','卷4','烟霞春旦赏，松竹故年心。
断山疑画障，县溜泻鸣琴。
草徧南亭合，花开北院深。
闲居饶酒赋，随兴欲抽簪。','',''),('quantangshi-03485','观佛迹寺','王勃','quantangshi','','卷4','莲座神容俨，松崖圣趾余。
年长金迹浅，地久石文疎。
颓华临曲磴，倾影赴前除。
共嗟陵谷远，俄视化城虚。','',''),('quantangshi-03486','山居晚眺赠王道士','王勃','quantangshi','','卷4','金坛疎俗宇，玉洞侣仙羣。
花枝栖晚露，峰叶度晴云。
斜照移山影，回沙拥籀文。
琴尊方待兴，竹树已迎曛。','',''),('quantangshi-03487','八仙迳','王勃','quantangshi','','卷4','柰园欣八正，松岩访九仙。
援萝窥雾术，攀林俯云烟。
代北鸾骖至，辽西鹤骑旋。
终希脱尘网，连翼下芝田。','',''),('quantangshi-03488','春日还郊','王勃','quantangshi','','卷4','闲情兼嘿语，携杖赴岩泉。
草绿萦新带，榆青缀古钱。
鱼牀侵岸水，鸟路入山烟。
还题平子赋，花树满春田。','',''),('quantangshi-03489','对酒春园作','王勃','quantangshi','','卷4','投簪下山阁，携酒对河梁。
狭水牵长镜，高花送断香。
繁莺歌似曲，疎蝶舞成行。
自然催一醉，非但阅年光。','',''),('quantangshi-03490','观内怀仙','王勃','quantangshi','','卷4','玉架残书隐，金坛旧迹迷。
牵花寻紫涧，步叶下清溪。
琼浆犹类乳，石髓尚如泥。
自能成羽翼，何必仰云梯。','',''),('quantangshi-03491','秋日别王长史','王勃','quantangshi','','卷4','别路余千里，深恩重百年。
正悲西候日，更动北梁篇。
野色笼寒雾，山光歛暮烟。
终知难再奉，怀德自潸然。','',''),('quantangshi-03492','上巳浮江宴韵得遥字','王勃','quantangshi','','卷4','上巳年光促，中川兴绪遥。
绿齐山叶满，红泄片花销。
泉声喧后涧，虹影照前桥。
遽悲春望远，江路积波潮。','',''),('quantangshi-03493','长柳','王勃','quantangshi','','卷4','晨征犯烟磴，夕憩在云关。
晚风清近壑，新月照澄湾。
郊童樵唱返，津叟钓歌还。
客行无与晤，赖此释愁颜。','',''),('quantangshi-03494','铜雀妓二首 一','王勃','quantangshi','','卷4','金凤隣铜雀，漳河望邺城。
君王无处所，台榭若平生。
舞席纷何就，歌梁俨未倾。
西陵松槚冷，谁见绮罗情。','',''),('quantangshi-03495','铜雀妓二首 二','王勃','quantangshi','','卷4','妾本深宫妓，层城闭九重。
君王欢爱尽，歌舞为谁容。
锦衾不复襞，罗衣谁再缝。
高台西北望，流涕向青松。','',''),('quantangshi-03496','羁游饯别','王勃','quantangshi','','卷4','客心悬陇路，游子倦江干。
槿丰朝砌静，筱密夜窗寒。
琴声销别恨，风景驻离欢。
宁觉山川远，悠悠旅思难。','',''),('quantangshi-03497','易阳早发','王勃','quantangshi','','卷4','饬装侵晓月，奔策候残星。
危阁寻丹障，回梁属翠屏。
云间迷树影，雾里失峰形。
复此凉飙至，空山飞夜萤。','',''),('quantangshi-03498','焦岸早行和陆四','王勃','quantangshi','','卷4','侵星违旅馆，乘月戒征俦。
复嶂迷晴色，虚岩辨暗流。
猿吟山漏晓，萤散野风秋。
故人渺何际，乡关云雾浮。','',''),('quantangshi-03499','深湾夜宿','王勃','quantangshi','','卷4','津涂临巨壑，村宇架危岑。
堰绝滩声隐，风交树影深。
江童暮理楫，山女夜调砧。
此时故乡远，宁知游子心。','',''),('quantangshi-03500','伤裴录事丧子','王勃','quantangshi','','卷4','兰阶霜候早，松露穸台深。
魄散珠胎没，芳销玉树沈。
露文曦宿草，烟照惨平林。
芝焚空欢息，流恨满籝金。','',''),('quantangshi-03501','泥溪','王勃','quantangshi','','卷4','弭棹凌奔壑，低鞭蹑峻岐。
江涛出岸险，峰磴入云危。
溜急船文乱，岩斜骑影移。
水烟笼翠渚，山照落丹崖。
风生苹浦叶，露泣竹潭枝。
泛水虽云美，劳歌谁复知。','',''),('quantangshi-03502','三月曲水宴得烟字','王勃','quantangshi','','卷4','彭泽官初去，河阳赋始传。
田园归旧国，诗酒间长筵。
列室窥丹洞，分楼瞰紫烟。
萦回亘津渡，出没控郊鄽。
凤琴调上客，龙辔俨羣仙。
松石偏宜古，藤萝不记年。
重檐交密树，复磴拥危泉。
抗石曦南岭，乘沙眇北川。
傅岩来筑处，磻溪入钓前。
日斜真趣远，幽思梦凉蝉。','',''),('quantangshi-03503','秋日仙游观赠道士','王勃','quantangshi','','卷4','石图分帝宇，银牒洞灵宫。
回丹萦岫室，复翠上岩栊。
雾浓金竈静，云暗玉坛空。
野花常捧露，山叶自吟风。
林泉明月在，诗酒故人同。
待余逢石髓，从尔命飞鸿。','',''),('quantangshi-03504','晚留凤州','王勃','quantangshi','','卷4','宝鸡辞旧役，仙凤历遗墟。
去此近城阙，青山明月初。','',''),('quantangshi-03505','羁春','王勃','quantangshi','','卷4','客心千里倦，春事一朝归。
还伤北园里，重见落花飞。','',''),('quantangshi-03506','林塘怀友','王勃','quantangshi','','卷4','芳屏画春草，仙杼织朝霞。
何如山水路，对面即飞花。','',''),('quantangshi-03507','山扉夜坐','王勃','quantangshi','','卷4','抱琴开野室，携酒对情人。
林塘花月下，别似一家春。','',''),('quantangshi-03508','春庄','王勃','quantangshi','','卷4','山中兰叶径，城外李桃园。
岂知人事静，不觉鸟声喧。','',''),('quantangshi-03509','春游','王勃','quantangshi','','卷4','客念纷无极，春泪倍成行。
今朝花树下，不觉恋年光。','',''),('quantangshi-03510','春园','王勃','quantangshi','','卷4','山泉两处晚，花柳一园春。
还持千日醉，共作百年人。','',''),('quantangshi-03511','林泉独饮','王勃','quantangshi','','卷4','丘壑经涂赏，花柳遇时春。
相逢今不醉，物色自轻人。','',''),('quantangshi-03512','登城春望','王勃','quantangshi','','卷4','物外山川近，晴初景霭新。
芳郊花柳遍，何处不宜春。','',''),('quantangshi-03513','他乡叙兴','王勃','quantangshi','','卷4','缀叶归烟晚，乘花落照春。
边城琴酒处，俱是越乡人。','',''),('quantangshi-03514','夜兴','王勃','quantangshi','','卷4','野烟含夕渚，山月照秋林。
还将中散兴，来偶步兵琴。','',''),('quantangshi-03515','临江二首 一','王勃','quantangshi','','卷4','泛泛东流水，飞飞北上尘。
归骖将别棹，俱是倦游人。','',''),('quantangshi-03516','临江二首 二','王勃','quantangshi','','卷4','去骖嘶别路，归棹隐寒洲。
江臯木叶下，应想故城秋。','',''),('quantangshi-03517','江亭夜月送别二首 一','王勃','quantangshi','','卷4','江送巴南水，山横塞北云。
津亭秋月夜，谁见泣离羣。','',''),('quantangshi-03518','江亭夜月送别二首 二','王勃','quantangshi','','卷4','乱烟笼碧砌，飞月向南端。
寂寂离亭掩，江山此夜寒。','',''),('quantangshi-03519','别人四首 一','王勃','quantangshi','','卷4','久客逢余闰，他乡别故人。
自然堪下泪，谁忍望征尘。','',''),('quantangshi-03520','别人四首 二','王勃','quantangshi','','卷4','江上风烟积，山幽云雾多。
送君南浦外，还望将如何。','',''),('quantangshi-03521','别人四首 三','王勃','quantangshi','','卷4','桂轺虽不驻，兰筵幸未开。
林塘风月赏，还待故人来。','',''),('quantangshi-03522','别人四首 四','王勃','quantangshi','','卷4','霜华净天末，雾色笼江际。
客子常畏人，何为久留滞。','',''),('quantangshi-03523','赠李十四四首 一','王勃','quantangshi','','卷4','野客思茅宇，山人爱竹林。
琴尊唯待处，风月自相寻。','',''),('quantangshi-03524','赠李十四四首 二','王勃','quantangshi','','卷4','小径偏宜草，空庭不厌花。
平生诗与酒，自得会仙家。','',''),('quantangshi-03525','赠李十四四首 三','王勃','quantangshi','','卷4','乱竹开三径，飞花满四邻。
从来扬子宅，别有尚玄人。','',''),('quantangshi-03526','赠李十四四首 四','王勃','quantangshi','','卷4','风筵调桂轸，月径引藤杯。
直当花院里，书斋望晓开。','',''),('quantangshi-03527','早春野望','王勃','quantangshi','','卷4','江旷春潮白，山长晓岫青。
他乡临睨极，花柳映边亭。','',''),('quantangshi-03528','山中','王勃','quantangshi','','卷4','长江悲已滞，万里念将归。
况属高风晚，山山黄叶飞。','',''),('quantangshi-03529','冬郊行望','王勃','quantangshi','','卷4','桂密岩花白，梨疎林叶红。
江臯寒望尽，归念断征篷。','',''),('quantangshi-03530','寒夜思友三首 一','王勃','quantangshi','','卷4','久别侵怀抱，他乡变容色。
月下调鸣琴，相思此何极。','',''),('quantangshi-03531','寒夜思友三首 二','王勃','quantangshi','','卷4','云间征思断，月下归愁切。
鸿雁西南飞，如何故人别。','',''),('quantangshi-03532','寒夜思友三首 三','王勃','quantangshi','','卷4','朝朝翠山下，夜夜苍江曲。
复此遥相思，清尊湛芳绿。','',''),('quantangshi-03533','始平晚息','王勃','quantangshi','','卷4','观阙长安近，江山蜀路赊。
客行朝复夕，无处是乡家。','',''),('quantangshi-03534','扶风昼届离京浸远','王勃','quantangshi','','卷4','帝里金茎去，扶风石柱来。
山川殊未已，行路方悠哉。','',''),('quantangshi-03535','普安建阴题壁','王勃','quantangshi','','卷4','江汉深无极，梁岷不可攀。
山川云雾里，游子几时还。','',''),('quantangshi-03536','九日','王勃','quantangshi','','卷4','九日重阳节，开门有菊花。
不知来送酒，若个是陶家。','',''),('quantangshi-03537','秋江送别二首 一','王勃','quantangshi','','卷4','早是他乡值早秋，江亭明月带江流。
已觉逝川伤别念，复看津树隐离舟。','',''),('quantangshi-03538','秋江送别二首 二','王勃','quantangshi','','卷4','归舟归骑俨成行，江南江北互相望。
谁谓波澜才一水，已觉山川是两乡。','',''),('quantangshi-03539','蜀中九日','王勃','quantangshi','','卷4','九月九日望乡台，他席他乡送客杯。
人情已厌南中苦，鸿雁那从北地来。','',''),('quantangshi-03540','寒夜怀友杂体二首 一','王勃','quantangshi','','卷4','北山烟雾始茫茫，南津霜月正苍苍。
秋深客思纷无已，复值征鸿中夜起。','',''),('quantangshi-03541','寒夜怀友杂体二首 二','王勃','quantangshi','','卷4','复阁重楼向浦开，秋风明月度江来。
故人故情怀故宴，相望相思不相见。','',''),('quantangshi-03542','落花落','王勃','quantangshi','','卷4','落花落，落花纷漠漠。
绿叶青跗映丹萼，与君裴回上金阁。
影拂妆阶玳瑁筵，香飘舞馆茱萸幙。
落花飞，撩乱入中帷。
落花春正满，春人归不归。
落花度，氛氲遶高树。
落花春已繁，春人春不顾。
绮阁青台静且闲，罗袂红巾复往还。
盛年不再得，高枝难重攀。
试复旦游落花里，暮宿落花间。
与君落花院，台上起双鬟。','',''),('quantangshi-03543','九日怀封元寂','王勃','quantangshi','','卷4','九日郊原望，平野遍霜威。
兰气添新酌，花香染别衣。
九秋良会少，千里故人稀。
今日龙山外，当忆雁书归。','',''),('quantangshi-03544','出境游山二首 一','王勃','quantangshi','','卷4','源水终无路，山阿若有人。
驱羊先动石，走兔欲投巾。
洞晚秋泉冷，岩朝古树新。
峰斜连鸟翅，磴叠上鱼鳞。
化鹤千龄早，元龟六代春。
浮云今可驾，沧海自成尘。','',''),('quantangshi-03545','出境游山二首 二','王勃','quantangshi','','卷4','振翮凌霜吹，正月伫天浔。
回镳凌翠壑，飞轸控青岑。
岩深灵竈没，涧毁石渠沈。
宫阙云间近，江山物外临。
玉坛栖暮夜，珠洞结秋阴。
萧萧离俗影，扰扰望乡心。
谁意山游好屡伤人事侵。','',''),('quantangshi-03546','河阳桥代窦郎中佳人答杨中舍','王勃','quantangshi','','卷4','披风听鸟长河路，临津织女遥相妬。
判知秋夕带啼还，那及春朝携手度。','',''),('quantangshi-03547','晦日宴高氏林亭同用华字','王勔','quantangshi','','卷4','上序披林馆，中京视物华。
竹窗低露叶，梅迳起风花。
景落春台雾，池侵旧渚沙。
绮筵歌吹晚，暮雨泛香车。','',''),('quantangshi-03548','奉教追赴九成宫途中口号','李嶠','quantangshi','','卷4','委质承仙翰，只命遄遥策。
事偶从梁游，人非背淮客。
长驱历川阜，迥眺穷原泽。
郁郁桑柘繁，油油禾黍积。
雨余林气静，日下山光夕。
未攀丛桂岩，犹倦飘蓬陌。
行当奉麾盖，慰此劳行役。','',''),('quantangshi-03549','秋山望月酬李骑曹','李嶠','quantangshi','','卷4','愁客坐山隈，怀抱自悠哉。
况复高秋夕，明月正裴回。
亭亭出迥岫，皎皎映层台。
色带银河满，光含玉露开。
淡云笼影度，虚晕抱轮回。
谷邃凉阴静，山空夜响哀。
寒催数雁过，风送一萤来。
独轸离居恨，遥想故人杯。','',''),('quantangshi-03550','和同府李祭酒休沐田居','李嶠','quantangshi','','卷4','列位簪缨序，隐居林野躅。
徇物爽全直，栖真昧均俗。
若人兼吏隐，率性夷荣辱。
地藉朱邸基，家在青山足。
暂弭西园盖，言事东臯粟。
筑室俯涧滨，开扉面岩曲。
庭幽引夕雾，檐迥通晨旭。
迎秋谷黍黄，含露园葵绿。
胜情狎兰杜，雅韵锵金玉。
伊我怀丘园，愿心从所欲。','',''),('quantangshi-03551','扈从还洛呈侍从羣官','李嶠','quantangshi','','卷4','四海帝王家，两都周汉室。
观风昔来幸，御气今旋跸。
雷奋六合开，天行万乘出。
玄冥奉时驾，白拒参戎律。
后队咽笳箫，前驱严罕罼。
辉光射东井，禁令横西秩。
帐殿别阳秋，旌门临甲乙。
将交洛城雨，稍远长安日。
邙巩云外来，咸秦雾中失。
孟冬霜霰下，是月农功毕。
天道向归余，皇情美阴隲。
行存名岳礼，逓问高年疾。
祝鸟既开罗，调人更张瑟。
登原采讴诵，俯谷求才术。
邑罕悬磬贫，山无挂瓢逸。
施恩浃寰宇，展义该文质。
德泽盛轩游，哀矜深禹恤。
申歌地庐骇，献寿衢尊溢。
瑞色抱氤氲，寒光变萧飋。
宗枝旦奭辅，侍从王刘匹。
竝辑蛟龙书，同簪凤皇笔。
陶甄荷吹万，颂叹归明一。
欢与道路长，顾随谈笑密。
叨承廊庙选，谬齿夔龙弼。
喜构大厦成，慙非栋隆吉。','',''),('quantangshi-03552','奉使筑朔方六州城率尔而作','李嶠','quantangshi','','卷4','奉诏受边服，总徒筑朔方。
驱彼犬羊族，正此戎夏疆。
子来多悦豫，王事宁怠遑。
三旬无愆期，百雉郁相望。
雄视沙漠垂，有截北海阳。
二庭已顿颡，五岭尽来王。
驱车登崇墉，顾眄凌大荒。
千里何萧条，草木自悲凉。
凭轼讯古今，慨焉感兴亡。
汉障缘河远，秦城入海长。
顾无庙堂策，贻此中夏殃。
道隐前业衰，运开今化昌。
制为百王式，举合千载防。
马牛被路隅，锋镝销战场。
岂不怀贤劳，所图在永康。
王事何为者，称代陈颂章。','',''),('quantangshi-03553','早发苦竹馆','李嶠','quantangshi','','卷4','合沓岩嶂深，朦胧烟雾晓。
荒阡下樵客，野猿惊山鸟。
开门听潺湲，入径寻窈窕。
栖鼯抱寒木，流萤飞暗筱。
早霞稍霏霏，残月犹皎皎。
行看远星稀，渐觉游氛少。
我行抚轺传，兼得傍林沼。
贪玩水石奇，不知川路渺。
徒怜野心旷，讵恻浮年小。
方解宠辱情，永托累尘表。','',''),('quantangshi-03554','安辑岭表事平罢归','李嶠','quantangshi','','卷4','云端想京县，帝乡如可见。
天涯望越台，海路几悠哉。
六月飞鹏去，三年瑞雉来。
境遥铜柱出，山险石门开。
自我违瀍洛，瞻途屡挥霍。
朝朝寒路多，夜夜征衣薄。
白简承朝宪，朱方抚夷落。
既弘天覆广，且谕皇恩博。
皇恩溢外区，憬俗咏来苏。
声朔臣天子，坛场拜老夫。
降宫韬将略，黄石寝兵符。
返斾收龙虎，空营集鸟乌。
日落澄氛霭，凭高视襟带。
东瓯抗于越，南斗临吴会。
春色绕边陲，飞花出荒外。
卉服纷如积，长川思游客。
风生丹桂晚，云起苍梧夕。
去舳舣清江，归轩趋紫陌。
衣裳会百蛮，琛賮委重关。
不学金刀使，空持宝劒还。','',''),('quantangshi-03555','鹧鸪','李嶠','quantangshi','','卷4','可怜鹧鸪飞，飞向树南枝。
南枝日照暖，北枝霜露滋。
露滋不堪栖，使我常夜啼。
愿逢云中鹤，衔我向寥廓。
愿作城上乌，一年生九雏。
何不旧巢住，枝弱不得去。
何意道苦辛，客子常畏人。','',''),('quantangshi-03556','清明日龙门游泛','李嶠','quantangshi','','卷4','晴晓国门通，都门蔼将发。
纷纷洛阳道，南望伊川阙。
衍漾乘和风，清明送芬月。
林窥二山动，水见千龛越。
罗袂罥杨丝，香桡犯苔发。
羣心行乐未，唯恐流芳歇。','',''),('quantangshi-03557','云','李嶠','quantangshi','','卷4','大梁白云起，氛氲殊未歇。
锦文触石来，盖影凌天发。
烟煴万年树，掩映三秋月。
会入大风歌，从龙赴圆阙。','',''),('quantangshi-03558','拟古东飞伯劳西飞燕','李嶠','quantangshi','','卷4','传书青鸟迎箫凤，巫岭荆台数通梦。
谁家窈窕住园楼，五马千金照陌头。
罗裙玉佩当轩出，点翠施红竞春日。
佳人二八盛舞歌，羞将百万呈双蛾。
庭前芳树朝夕改，空驻妍华欲谁待。','',''),('quantangshi-03559','宝劒篇','李嶠','quantangshi','','卷4','吴山开，越溪涸，三金合冶成宝锷。
淬绿水，鉴红云，五采焰起光氛氲。
背上铭为万年字，胸前点作七星文。
龟甲参差白虹色，辘轳宛转黄金饰。
骇犀中断宁方利，骏马羣騑未拟直。
风霜凛凛匣上清，精气遥遥斗间明。
避灾朝穿晋帝屋，逃乱夜入楚王城。
一朝运偶逢大仙，虎吼龙鸣腾上天。
东皇提升紫微座，西皇佩下赤城田。
承平久息干戈事，侥幸得充文武备。
除灾辟患宜君王，益寿延龄后天地。','',''),('quantangshi-03560','汾阴行','李嶠','quantangshi','','卷4','君不见昔日西京全盛时，汾阴后土亲祭祠。
斋宫宿寝设储供，撞钟鸣鼓树羽旗。
汉家五叶才且雄，宾延万灵朝九戎。
栢梁赋诗高宴罢，诏书法驾幸河东。
河东太守亲扫除，奉迎至尊导銮舆。
五营夹道列容衞，三河纵观空里闾。
回旌驻跸降灵场，焚香奠醑邀百祥。
金鼎发色正焜煌，灵只炜烨摅景光。
埋玉陈牲礼神毕，举麾上马乘舆出。
彼汾之曲嘉可游，木兰为楫桂为舟。
棹歌微吟彩鷁浮，箫鼓哀鸣白云秋。
欢娱宴洽赐羣后，家家复除户牛酒。
声明动天乐无有，千秋万岁南山寿。
自从天子向秦关，玉辇金车不复还。
珠帘羽扇长寂寞，鼎湖龙髯安可攀。
千龄人事一朝空，四海为家此路穷。
豪雄意气今何在，坛场宫馆尽蒿篷。
路逢故老长叹息，世事回环不可测。
昔时青楼对歌舞，今日黄埃聚荆棘。
山川满目泪沾衣，富贵荣华能几时。
不见秪今汾水上，唯有年年秋雁飞。','',''),('quantangshi-03561','中宗降诞日长宁公主满月侍宴应制','李嶠','quantangshi','','卷4','神龙见像日，仙凤养雏年。
大火乘天正，明珠对月圆。
作新金箧里，歌奏玉筐前。
今日宜孙庆，还参祝寿篇。','',''),('quantangshi-03562','奉和送金城公主适西蕃应制','李嶠','quantangshi','','卷4','汉帝抚戎臣，丝言命锦轮。
还将弄机女，远嫁织皮人。
曲怨关山月，妆消道路尘。
所嗟穠李树，空对小榆春。','',''),('quantangshi-03563','侍宴长宁公主东庄应制','李嶠','quantangshi','','卷4','别业临青甸，鸣銮降紫霄。
长筵鵷鹭集，仙管凤皇调。
树接南山近，烟含北渚遥。
承恩咸已醉，恋赏未还镳。','',''),('quantangshi-03564','立春日侍宴内殿出剪彩花应制','李嶠','quantangshi','','卷4','早闻年欲至，剪彩学芳辰。
缀绿奇能似，裁红巧逼真。
花从箧里发，叶向手中春。
不与时光竞，何名天上人。','',''),('quantangshi-03565','奉和人日清晖阁宴羣臣遇雪应制','李嶠','quantangshi','','卷4','三阳偏胜节，七日最灵辰。
行庆传芳蚁，升高缀彩人。
阶前蓂候月，楼上雪惊春。
今日衔天造，还疑上汉津。','',''),('quantangshi-03566','奉和春日游苑喜雨应制','李嶠','quantangshi','','卷4','仙跸九成台，香筵万寿杯。
一旬初降雨，二月早闻雷。
叶向朝隮密，花含宿润开。
幸承天泽豫，无使日光催。','',''),('quantangshi-03567','春日侍宴幸芙蓉园应制','李嶠','quantangshi','','卷4','年光竹里遍，春色杏间遥。
烟气笼青阁，流文荡画桥。
飞花随蝶舞，艳曲伴鸎娇。
今日陪欢豫，还疑陟紫霄。','',''),('quantangshi-03568','甘露殿侍宴应制','李嶠','quantangshi','','卷4','月宇临丹地，云窗网碧纱。
御筵陈桂醑，天酒酌榴花。
水向浮桥直，城连禁苑斜。
承恩恣欢赏，归路满烟霞。','',''),('quantangshi-03569','奉和七夕两仪殿会宴应制','李嶠','quantangshi','','卷4','灵匹三秋会，仙期七夕过。
查来人泛海，桥渡鹊填河。
帝缕升银阁，天机罢玉梭。
谁言七襄咏，重入五弦歌。','',''),('quantangshi-03570','奉和九月九日登慈恩寺浮图应制','李嶠','quantangshi','','卷4','瑞塔千寻起，仙舆九日来。
萸房陈宝席，菊橤散花台。
御气鹏霄近，升高凤野开。
天歌将梵乐，空里共裴回。','',''),('quantangshi-03571','闰九月九日幸总持寺登浮图应制','李嶠','quantangshi','','卷4','闰节开重九，真游下大千。
花寒仍荐菊，座晚更披莲。
刹凤回雕辇，帆虹间彩旃。
还将西梵曲，助入南薰弦。','',''),('quantangshi-03572','奉和骊山高顶寓目应制','李嶠','quantangshi','','卷4','步辇陟山巅，山高入紫烟。
忠臣还捧日，圣后欲扪天。
迥识平陵树，低看华岳莲。
帝乡应不远，空见白云悬。','',''),('quantangshi-03573','游禁苑陪幸临渭亭遇雪应制','李嶠','quantangshi','','卷4','同云接野烟，飞雪暗长天。
拂树添梅色，过楼助粉妍。
光含班女扇，韵入楚王弦。
六出迎仙藻，千箱答瑞年。','',''),('quantangshi-03574','幸白鹿观应制','李嶠','quantangshi','','卷4','驻跸三天路，回旃万仞溪。
真庭羣帝飨，洞府百灵栖。
玉酒仙垆酿，金方暗壁题。
伫看青鸟入，还陟紫云梯。','',''),('quantangshi-03575','送沙门弘景道俊玄奘还荆州应制','李嶠','quantangshi','','卷4','三乘归净域，万骑饯通庄。
就日离亭近，弥天别路长。
荆南旋杖钵，渭北限津梁。
何日纡真果，还来入帝乡。','',''),('quantangshi-03576','酬杜五弟晴朝独坐见赠','李嶠','quantangshi','','卷4','平明坐虚馆，旷望几悠哉。
宿雾分空尽，朝光度隙来。
影低藤架密，香动药阑开。
未展山阳会，空留池上杯。','',''),('quantangshi-03577','同赋山居七夕','李嶠','quantangshi','','卷4','明月青山夜，高天白露秋。
花庭开粉席，云岫敞针楼。
石类支机影，池似泛槎流。
暂惊河女鹊，终狎野人鸥。','',''),('quantangshi-03578','送崔主簿赴沧州','李嶠','quantangshi','','卷4','紫陌追随日，青门相见时。
宦游从此去，离别几年期。
芳桂尊中酒，幽兰下调词。
他乡有明月，千里照相思。','',''),('quantangshi-03579','寒食清明日早赴王门率成','李嶠','quantangshi','','卷4','游客趋梁邸，朝光入楚台。
槐烟乘晓散，榆火应春开。
日带晴虹上，花随早蝶来。
雄风乘令节，余吹拂轻灰。','',''),('quantangshi-03580','和周记室从驾晓发合璧宫','李嶠','quantangshi','','卷4','濯龙春苑曙，翠凤晓旗舒。
野色开烟后，山光澹月余。
风长笳响咽，川迥骑行疎。
珠履陪仙驾，金声振属车。','',''),('quantangshi-03581','和杜侍御太清台宿直旦有怀','李嶠','quantangshi','','卷4','貂冠朝彩振，乌署晓光分。
欲啸迁乔侣，先飞掷地文。
庭虚麦雨润，林静蕙风薰。
嵇驾终难仰，梁凫且自羣。','',''),('quantangshi-03582','和杜学士江南初霁羁怀','李嶠','quantangshi','','卷4','大江开宿雨，征棹下春流。
雾卷晴山出，风恬晚浪收。
岸花明水树，川鸟乱沙洲。
羁眺伤千里，劳歌动四愁。','',''),('quantangshi-03583','晚景怅然简二三子','李嶠','quantangshi','','卷4','楚客秋悲动，梁台夕望赊。
梧桐稍下叶，山桂欲开花。
气引迎寒露，光收向晚霞。
长歌白水曲，空对绿池华。','',''),('quantangshi-03584','送李邕','李嶠','quantangshi','','卷4','落日荒郊外，风景正凄凄。
离人席上起，征马路傍嘶。
别酒倾壶赠，行书掩泪题。
殷勤御沟水，从此各东西。','',''),('quantangshi-03585','又送别','李嶠','quantangshi','','卷4','岐路方为客，芳尊暂解颜。
人随转蓬去，春伴落梅还。
白云度汾水，黄河遶晋关。
离心不可问，宿昔鬓成斑。','',''),('quantangshi-03586','饯骆四二首 一','李嶠','quantangshi','','卷4','平生何以乐，斗酒夜相逢。
曲中惊别绪，醉里失愁容。
星月悬秋汉，风霜入曙钟。
明日临沟水，青山几万重。','',''),('quantangshi-03587','饯骆四二首 二','李嶠','quantangshi','','卷4','甲第驱车入，良宵秉烛游。
人追竹林会，酒献菊花秋。
霜吹飘无已，星河漫不流。
重嗟欢赏地，翻召别离忧。','',''),('quantangshi-03588','春日游苑喜雨应诏','李嶠','quantangshi','','卷4','园楼春正归，入苑弄芳菲。
密雨迎仙步，低云拂御衣。
危花霑易落，度鸟湿难飞。
膏泽登千庾，欢情徧九围。','',''),('quantangshi-03589','九日应制得欢字','李嶠','quantangshi','','卷4','令节三秋晚，重阳九日欢。
仙杯还泛菊，宝馔且调兰。
御气云霄近，乘高宇宙宽。
今朝万寿引，宜向曲中弹。','',''),('quantangshi-03590','二月奉教作','李嶠','quantangshi','','卷4','柳陌鸎初啭，梅梁燕始归。
和风泛紫若，柔露濯青薇。
日艳临花影，霞翻入浪晖。
乘春重游豫，淹赏玩芳菲。','',''),('quantangshi-03591','三月奉教作','李嶠','quantangshi','','卷4','银井桐花发，金堂草色齐。
韶光爱日宇，淑气满风蹊。
蝶影将花乱，虹文向水低。
芳春随意晚，佳赏日无暌。','',''),('quantangshi-03592','四月奉教作','李嶠','quantangshi','','卷4','暄龠三春谢，炎钟九夏初。
润浮梅雨夕，凉散麦风余。
叶暗庭帏满，花残院锦疎。
胜情多赏托，尊酒狎林箊。','',''),('quantangshi-03593','五月奉教作','李嶠','quantangshi','','卷4','绿树炎氛满，朱楼夏景长。
池含冻雨气，山映火云光。
果院新樱熟，花庭曙槿芳。
欲逃三伏暑，还泛十旬觞。','',''),('quantangshi-03594','六月奉教作','李嶠','quantangshi','','卷4','养日暂裴回，畏景尚悠哉。
避暑移琴席，追凉□□□。
竹风依扇动，桂酒溢壶开。
劳饵□飞雪，自可□□□。','',''),('quantangshi-03595','八月奉教作','李嶠','quantangshi','','卷4','黄叶秋风起，苍葭晓露团。
鹤鸣初警候，雁上欲凌寒。
月镜如开匣，云缨似缀冠。
清尊对旻序，高宴有余欢。','',''),('quantangshi-03596','九月奉教作','李嶠','quantangshi','','卷4','曲池朝下雁，幽砌夕吟蛩。
叶径兰芳尽，花潭菊气浓。
寒催四序律，霜度九秋钟。
还当明月夜，飞盖远相从。','',''),('quantangshi-03597','十月奉教作','李嶠','quantangshi','','卷4','白藏初送节，玄律始迎冬。
林枯黄叶尽，水耗绿池空。
霜待临庭月，寒随入牖风。
别有欢娱地，歌舞应丝桐。','',''),('quantangshi-03598','十一月奉教作','李嶠','quantangshi','','卷4','凝阴结暮序，严气肃长飙。
霜犯狐裘夕，寒侵兽火朝。
冰深遥架浦，雪冻近封条。
平原已从猎，日暮整还镳。','',''),('quantangshi-03599','十二月奉教作','李嶠','quantangshi','','卷4','玉烛年行尽，铜史漏犹长。
池冷凝宵冻，庭寒积曙霜。
兰心未动色，梅馆欲含芳。
裴回临岁晚，顾步伫春光。','',''),('quantangshi-03600','和麴典设扈从东郊忆弟使往安西冬至日恨不得同申拜庆','李嶠','quantangshi','','卷4','玉关方叱驭，桂苑正陪舆。
桓岭嗟分翼，姜川限馈鱼。
雪花含□晚，云叶带荆舒。
重此西流咏，弥伤南至初。','',''),('quantangshi-03601','马武骑挽歌二首 一','李嶠','quantangshi','','卷4','五日皆休沐，三泉独不归。
池台金阙是，尊酒玳筵非。
巷静游禽入，门闲过客稀。
唯余昔年凤，尚绕故楼飞。','',''),('quantangshi-03602','马武骑挽歌二首 二','李嶠','quantangshi','','卷4','昔下天津馆，尝过帝子家。
夜倾金屋酒，春舞玉台花。
试马依红埒，吹箫弄紫霞。
谁言东郭路，翻枉北门车。','',''),('quantangshi-03603','武三思挽歌','李嶠','quantangshi','','卷4','玉匣金为缕，银钩石作铭。
短歌伤薤曲，长暮泣松扃。
事往昏朝雾，人亡折夜星。
忠贤良可惜，图画入丹青。','',''),('quantangshi-03604','天官崔侍郎夫人吴氏挽歌','李嶠','quantangshi','','卷4','宠服当年盛，芳魂此地穷。
劒飞龙匣在，人去鹊巢空。
簟怆孤生竹，琴哀半死桐。
唯当青史上，千载仰嫔风。','',''),('quantangshi-03605','日','李嶠','quantangshi','','卷4','旦出扶桑路，遥升若木枝。
云间五色满，霞际九光披。
东陆苍龙驾，南郊赤羽驰。
倾心比葵藿，朝夕奉光曦。','',''),('quantangshi-03606','月','李嶠','quantangshi','','卷4','桂满三五夕，蓂开二八时。
清辉飞鹊鉴，新影学蛾眉。
皎洁临疎牖，玲珑鉴薄帷。
愿言从爱客，清夜幸同嬉。','',''),('quantangshi-03607','星','李嶠','quantangshi','','卷4','蜀郡灵槎转，丰城宝劒新。
将军临北塞，天子入西秦。
未作三台辅，宁为五老臣。
今宵颍川曲，谁识聚贤人。','',''),('quantangshi-03608','风','李嶠','quantangshi','','卷4','落日生苹末，摇扬徧远林。
带花疑凤舞，向竹似龙吟。
月动临秋扇，松清入夜琴。
若至兰台下，还拂楚王襟。','',''),('quantangshi-03609','云','李嶠','quantangshi','','卷4','英英大梁国，郁郁秘书台。
碧落从龙起，青山触石来。
官名光邃古，盖影耿轻埃。
飞感高歌发，威加四海回。','',''),('quantangshi-03610','烟','李嶠','quantangshi','','卷4','瑞气凌青阁，空蒙上翠微。
迥浮双阙路，遥拂九仙衣。
桑柘迎寒色，松篁暗晚晖。
还当紫霄上，时接彩鸾飞。','',''),('quantangshi-03611','露','李嶠','quantangshi','','卷4','滴沥明花苑，葳蕤泫竹丛。
玉垂丹棘上，珠湛绿荷中。
夜警千年鹤，朝零七月风。
愿凝仙掌内，长奉未央宫。','',''),('quantangshi-03612','雾','李嶠','quantangshi','','卷4','曹公迷楚泽，汉帝出平城。
涿鹿妖氛静，丹山霁色明。
类烟飞稍重，方雨散还轻。
倘入非熊兆，宁思玄豹情。','',''),('quantangshi-03613','雨','李嶠','quantangshi','','卷4','西北云肤起，东南雨足来。
灵童出海见，神女向台回。
斜影风前合，圆文水上开。
十旬无破块，九土信康哉。','',''),('quantangshi-03614','雪','李嶠','quantangshi','','卷4','瑞雪惊千里，同云暗九霄。
地疑明月夜，山似白云朝。
逐舞花光动，临歌扇影飘。
大周天阙路，今日海神朝。','',''),('quantangshi-03615','山','李嶠','quantangshi','','卷4','地镇标神秀，峩峩上翠氛。
泉飞一道带，峰出半天云。
古壁丹青色，新花绮绣纹。
已开封禅所，希谒圣明君。','',''),('quantangshi-03616','石','李嶠','quantangshi','','卷4','宗子维城固，将军饮羽威。
岩花鉴里发，云叶锦中飞。
入宋星初陨，过湘燕早归。
倘因持补极，宁复想支机。','',''),('quantangshi-03617','原','李嶠','quantangshi','','卷4','王粲销忧日，江淹起恨年。
带川遥绮错，分隰迥阡眠。
□□横周甸，莓苔阙晋田。
方知急难响，长在脊令篇。','',''),('quantangshi-03618','野','李嶠','quantangshi','','卷4','凤出秦郊迥，鹑飞楚塞空。
苍梧云影去，涿鹿雾光通。
草暗少原绿，花明入蜀红。
谁言版筑士，犹处傅岩中。','',''),('quantangshi-03619','田','李嶠','quantangshi','','卷4','贡禹怀书日，张衡作赋辰。
杏花开凤轸，菖叶布龙鳞。
瑞麦两岐秀，嘉禾同颖新。
宁知帝王力，击壤自安贫。','',''),('quantangshi-03620','道','李嶠','quantangshi','','卷4','铜驼分巩洛，劒阁低临邛。
紫徼三千里，青楼十二重。
玉关尘似雪，金穴马如龙。
今日中衢上，尧尊更可逢。','',''),('quantangshi-03621','海','李嶠','quantangshi','','卷4','习坎疏丹壑，朝宗合紫微。
三山巨鳌涌，万里大鹏飞。
楼写春云色，珠含明月辉。
会因添雾露，方逐众川归。','',''),('quantangshi-03622','江','李嶠','quantangshi','','卷4','日夕三江望，灵潮万里回。
霞津锦浪动，月浦练花开。
湍似黄牛去，涛从白马来。
英灵已杰出，谁识卿云才。','',''),('quantangshi-03623','河','李嶠','quantangshi','','卷4','源出昆仑中，长波接汉空。
桃花来马颊，竹箭入龙宫。
德水千年变，荣光五色通。
若披兰叶检，□□□□□。','',''),('quantangshi-03624','洛','李嶠','quantangshi','','卷4','九洛韶光媚，三川物候新。
花明丹凤浦，日映玉鸡津。
元礼期仙客，陈王覩丽人。
神龟方锡瑞，绿字重来臻。','',''),('quantangshi-03625','城','李嶠','quantangshi','','卷4','四塞称天府，三河建洛都。
飞云霭层阙，白日丽南隅。
独下仙人凤，羣惊御史乌。
何辞一万里，边徼捍匈奴。','',''),('quantangshi-03626','门','李嶠','quantangshi','','卷4','奕奕彤闱下，煌煌紫禁隈。
阿房万户列，阊阖九重开。
疏广遗荣去，于公待驷来。
讵知金马侧，方朔有奇才。','',''),('quantangshi-03627','市','李嶠','quantangshi','','卷4','闤闠开三市，旗亭起百寻。
渐离初击筑，司马正弹琴。
细柳龙鳞映，长槐兔月阴。
徒知观衞玉，讵肯挂秦[金]。','',''),('quantangshi-03628','井','李嶠','quantangshi','','卷4','玉甃谈仙客，铜台赏魏君。
蜀都宵映火，杞国旦生云。
向日莲花净，含风李树薰。
已开千里国，还聚五星文。','',''),('quantangshi-03629','宅','李嶠','quantangshi','','卷4','寂寞蓬蒿径，喧喧湫隘庐。
屡逢长者辙，时引故人车。
孟母迁邻罢，将军辞第初。
谁怜草玄处，独对一牀书。','',''),('quantangshi-03630','池','李嶠','quantangshi','','卷4','彩棹浮太液，清触醉习家。
诗情对明月，云曲拂流霞。
烟散龙形净，波含凤影斜。
安仁动秋兴，鱼鸟思空赊。','',''),('quantangshi-03631','楼','李嶠','quantangshi','','卷4','百尺重城际，千寻大道隈。
汉宫井干起，吴国落星开。
笛怨绿珠去，箫随弄玉来。
销忧聊暇日，谁识仲宣才。','',''),('quantangshi-03632','桥','李嶠','quantangshi','','卷4','乌鹊填应满，黄公去不归。
势疑虹始见，形似雁初飞。
妙应七星制，高分半月辉。
秦王空构石，仙岛远难依。','',''),('quantangshi-03633','经','李嶠','quantangshi','','卷4','汉室鸿儒盛，邹堂大义明。
五千道德阐，三百礼仪成。
青紫方拾芥，黄金徒满籝。
谁知怀逸辩，重席冠羣英。','',''),('quantangshi-03634','史','李嶠','quantangshi','','卷4','马记天官设，班图地里新。
善谈方亹亹，青简见彬彬。
方朔初闻汉，荆轲昔向秦。
正辞堪载笔，终翼作良臣。','',''),('quantangshi-03635','诗','李嶠','quantangshi','','卷4','都尉仙凫远，梁王驷马来。
扇中纨素制，机上锦纹回。
天子三章传，陈王七步才。
缁衣久擅美，祖德信悠哉。','',''),('quantangshi-03636','赋','李嶠','quantangshi','','卷4','布义孙卿子，登高楚屈平。
铜台初下笔，乐观正飞缨。
乍有凌云势，时闻掷地声。
造端长体物，无复大夫名。','',''),('quantangshi-03637','书','李嶠','quantangshi','','卷4','削简龙文见，临池鸟迹舒。
河图八卦出，洛范九畴初。
垂露春光满，崩云骨气余。
请君看入木，一寸乃非虚。','',''),('quantangshi-03638','檄','李嶠','quantangshi','','卷4','羽檄本宣明，由来□木声。
联翩至汉国，迢递入燕营。
毛义持书去，张仪韫璧行。
曹风虽觉愈，陈草始知名。','',''),('quantangshi-03639','纸','李嶠','quantangshi','','卷4','妙迹蔡侯施，芳名左伯驰。
云飞锦绮落，花发缥红披。
舒卷随幽显，廉方合轨仪。
莫惊反掌字，当取葛洪规。','',''),('quantangshi-03640','笔','李嶠','quantangshi','','卷4','握管门庭侧，含毫山水隈。
霜辉简上发，锦字梦中开。
鹦鹉摛文至，麒麟绝句来。
何当遇良史，左右振奇才。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-03641','砚','李嶠','quantangshi','','卷4','左思裁赋日，王充作论年。
光随锦文发，形带石岩圆。
积润循毫里，开池小学前。
君苗徒见爇，谁咏士衡篇。','',''),('quantangshi-03642','墨','李嶠','quantangshi','','卷4','长安分石炭，上党结松心。
遶画蝇初落，含滋绶更深。
悲丝光易染，叠素彩还沈。
别有张芝学，书池幸见临。','',''),('quantangshi-03643','劒','李嶠','quantangshi','','卷4','我有昆吾劒，求趋夫子庭。
白虹时切玉，紫气夜干星。
锷上芙蓉动，匣中霜雪明。
倚天持报国，画地取雄名。','',''),('quantangshi-03644','刀','李嶠','quantangshi','','卷4','列辟鸣鸾至，惟良佩犊旋。
带环疑写月，引鉴似含泉。
入梦华梁上，含锋彩笔前。
莫惊开百炼，特拟定三边。','',''),('quantangshi-03645','箭','李嶠','quantangshi','','卷4','汉甸初收羽，燕城忽解围。
影随流水急，光带落星飞。
夏列三成范，尧沈九日辉。
断蛟云梦泽，希为识忘归。','',''),('quantangshi-03646','弹','李嶠','quantangshi','','卷4','侠客持苏合，佳游满帝乡。
避丸深可诮，求炙遂难忘。
金迸疑星落，珠沈似月光。
谁知少孺子，将此见吴王。','',''),('quantangshi-03647','弩','李嶠','quantangshi','','卷4','挺质本轩皇，申威振远方。
机张惊雉雊，玉彩耀星芒。
高鸟行应尽，清猿坐见伤。
苏秦六百步，持此说韩王。','',''),('quantangshi-03648','旗','李嶠','quantangshi','','卷4','桂影承宵月，虹辉接曙云。
纵横齐八阵，舒卷引三军。
日薄蛟龙影，风翻鸟隼文。
谁知怀勇志，蟠地几缤纷。','',''),('quantangshi-03649','旌','李嶠','quantangshi','','卷4','告善康庄侧，求贤市肆中。
拥麾分彩雉，持节曳丹虹。
影丽天山雪，光摇朔塞风。
方知美周政，抗斾赋车攻。','',''),('quantangshi-03650','戈','李嶠','quantangshi','','卷4','富父舂喉日，殷辛漂杵年。
晓霜含白刃，落影驻雕鋋。
夕摈金门侧，朝提玉塞前。
愿随龙影度，横□阵云边。','',''),('quantangshi-03651','鼓','李嶠','quantangshi','','卷4','舜日谐鼗响，尧年韵土声。
向楼疑吹击，震谷似雷惊。
仙鹤排门起，灵鼍带水鸣。
乐云行已奏，礼曰冀相成。','',''),('quantangshi-03652','弓','李嶠','quantangshi','','卷4','桃文称辟恶，桑质表初生。
宛转雕鞬际，依稀半月明。
遥弯落雁影，虚引怯猿声。
徒切乌号思，攀龙遂不成。','',''),('quantangshi-03653','琴','李嶠','quantangshi','','卷4','名士竹林隈，鸣琴宝匣开。
风前中散至，月下步兵来。
淮海多为室，梁岷旧作台。
子期如可听，山水响余哀。','',''),('quantangshi-03654','琴','李嶠','quantangshi','','卷4','隐士竹林隈，英声寳匣开。
风前緑绮弄，月下白云来。
淮海多为室，梁岷旧作台。
子期如可聴，山水响余哀。','',''),('quantangshi-03655','瑟','李嶠','quantangshi','','卷4','伏羲初制法，素女昔传名。
流水嘉鱼跃，丛台舞凤惊。
嘉宾饮未极，君子娱俱并。
倘入丘之户，应知由也情。','',''),('quantangshi-03656','琵琶','李嶠','quantangshi','','卷4','朱丝闻岱谷，铄质本多端。
半月分弦出，丛花拂面安。
将军曾制曲，司马屡陪观。
本是胡中乐，希君马上弹。','',''),('quantangshi-03657','筝','李嶠','quantangshi','','卷4','蒙恬芳轨设，游楚妙弹开。
新曲帐中发，清音指下来。
钿装模六律，柱列配三才。
莫听西秦奏，筝筝有剩哀。','',''),('quantangshi-03658','钟','李嶠','quantangshi','','卷4','既接南邻磬，还随北里笙。
平陵通曙响，长乐警宵声。
秋至含霜动，春归应律鸣。
欲知常待扣，金簴有余清。','',''),('quantangshi-03659','箫','李嶠','quantangshi','','卷4','虞舜调清管，王襃赋雅音。
参差横凤翼，搜索动人心。
□□□□□，□□□□□。
□□□□□，□□□□□。','',''),('quantangshi-03660','笛','李嶠','quantangshi','','卷4','羗笛写龙声，长吟入夜清。
关山孤月下，来向陇头鸣。
逐吹梅花落，含春柳色惊。
行观向子赋，坐忆旧邻情。','',''),('quantangshi-03661','笙','李嶠','quantangshi','','卷4','悬匏曲沃上，孤筱汶阳隈。
形写歌鸾翼，声随舞凤哀。
欢娱分北里，纯孝即南陔。
今日虞音奏，跄跄鸟兽来。','',''),('quantangshi-03662','歌','李嶠','quantangshi','','卷4','汉帝临汾水，周仙去洛滨。
郢中吟白雪，梁上绕飞尘。
响发行云驻，声随子夜新。
愿君听扣角，当自识贤臣。','',''),('quantangshi-03663','舞','李嶠','quantangshi','','卷4','妙伎游金谷，佳人满石城。
霞衣席上转，花岫雪前明。
仪凤谐清曲，回鸾应雅声。
非君一顾重，谁赏素腰轻。','',''),('quantangshi-03664','珠','李嶠','quantangshi','','卷4','灿烂金舆侧，玲珑玉殿隈。
昆池明月满，合浦夜光回。
彩逐灵蛇转，行随舞凤来。
甘泉宫起罢，花媚望风台。','',''),('quantangshi-03665','玉','李嶠','quantangshi','','卷4','映石先过魏，连城欲向秦。
洛阳陪胜友，燕赵类佳人。
方水晴虹媚，常山瑞马新。
徒为卞和识，不遇楚王珍。','',''),('quantangshi-03666','金','李嶠','quantangshi','','卷4','南楚标前贡，西秦识旧城。
祭天封汉岭，掷地警孙声。
向日披沙净，含风振铎鸣。
方同杨伯起，独有四知名。','',''),('quantangshi-03667','银','李嶠','quantangshi','','卷4','思妇屏辉掩，游人烛影长。
玉壶初下箭，桐井共安牀。
色带长河色，光浮满月光。
灵山有珍瓮，仙阙荐君王。','',''),('quantangshi-03668','钱','李嶠','quantangshi','','卷4','汉日五铢建，姬年九府流。
天龙带泉宝，地马列金沟。
赵壹囊初乏，何曾箸欲收。
金门应入论，玉井冀来求。','',''),('quantangshi-03669','锦','李嶠','quantangshi','','卷4','汉使巾车远，河阳步障陈。
云浮仙石日，霞满蜀江春。
机迥回文巧，绅兼束髪新。
若逢楚王贵，不作夜行人。','',''),('quantangshi-03670','罗','李嶠','quantangshi','','卷4','妙舞随裙动，行歌入扇清。
莲花依帐发，秋月鉴帷明。
云薄衣初卷，蝉飞翼转轻。
若珍三代服，同擅绮纨名。','',''),('quantangshi-03671','绫','李嶠','quantangshi','','卷4','金缕通秦国，为裘指魏君。
落花遥写雾，飞鹤近图云。
马眼冰凌影，竹根雪霰文。
何当画秦女，烟际坐氤氲。','',''),('quantangshi-03672','素','李嶠','quantangshi','','卷4','□□□□女，纤腰洛浦妃。
□□远方望，雁足上林飞。
妙夺鲛绡色，光腾月扇辉。
非君下路去，谁赏故人机。','',''),('quantangshi-03673','布','李嶠','quantangshi','','卷4','御绩创羲黄，缁冠表素王。
瀑飞临碧海，火浣擅炎方。
孙被登三相，刘衣阐四方。
伫因舂斗粟，来晓棣华芳。','',''),('quantangshi-03674','舟','李嶠','quantangshi','','卷4','征棹三江暮，连樯万里回。
相乌风际转，画鷁浪前开。
羽客乘霞至，仙人弄月来。
何当同傅说，特展巨川材。','',''),('quantangshi-03675','车','李嶠','quantangshi','','卷4','天子驭金根，蒲轮辟四门。
五神趋雪至，双毂似雷奔。
丹凤栖金辖，非熊载宝轩。
无阶忝虚左，珠乘奉王言。','',''),('quantangshi-03676','牀','李嶠','quantangshi','','卷4','传闻有象牀，畴昔献君王。
玳瑁千金起，珊瑚七宝妆。
桂筵含柏馥，兰席拂沈香。
愿奉罗帷夜，长乘秋月光。','',''),('quantangshi-03677','席','李嶠','quantangshi','','卷4','避席承宣父，重筵揖戴公。
桂香浮半月，兰气袭回风。
舞拂丹霞上，歌清白雪中。
伫将文绮色，舒卷帝王宫。','',''),('quantangshi-03678','帷','李嶠','quantangshi','','卷4','久闭先生户，高褰太守车。
罗将翡翠合，锦逐凤皇舒。
明月弹琴夜，清风入幌初。
方知决胜策，黄石受兵书。','',''),('quantangshi-03679','帘','李嶠','quantangshi','','卷4','清风时入燕，紫殿几含秋。
暧暧笼铃阁，纤纤上玉钩。
窗中翡翠动，户外水精浮。
巧作盘龙势，长迎飞燕游。','',''),('quantangshi-03680','屏','李嶠','quantangshi','','卷4','洞彻琉璃蔽，威纡屈膝回。
锦中云母列，霞上织成开。
山上含春动，神仙倒景来。
修身兼竭节，谁识作铭才。','',''),('quantangshi-03681','被','李嶠','quantangshi','','卷4','桂友寻东阁，兰交聚北堂。
象筵分锦绣，罗荐合鸳鸯。
光逸偷眠稳，王章泣恨长。
孔怀欣共寝，棣萼几含芳。','',''),('quantangshi-03682','鉴','李嶠','quantangshi','','卷4','明鉴掩尘埃，含情照魏台。
日中乌鹊至，花里凤皇来。
玉彩疑冰彻，金辉似月开。
方知乐彦辅，自有鉴人才。','',''),('quantangshi-03683','扇','李嶠','quantangshi','','卷4','翟羽旧传名，蒲葵价不轻。
花芳不满面，罗薄讵障声。
御热含风细，临秋带月明。
同心如可赠，持表合欢情。','',''),('quantangshi-03684','烛','李嶠','quantangshi','','卷4','兔月清光隐，龙盘画烛新。
三星花入夜，四序玉调晨。
浮炷依罗幌，吹香匝绮茵。
若逢燕国相，持用举贤人。','',''),('quantangshi-03685','酒','李嶠','quantangshi','','卷4','孔坐洽良俦，陈筵几献酬。
临风竹叶满，湛月桂香浮。
每接高阳宴，长陪河朔游。
会从玄石饮，云雨出圆丘。','',''),('quantangshi-03686','兰','李嶠','quantangshi','','卷4','虚室重招寻，忘言契断金。
英浮汉家酒，雪俪楚王琴。
广殿轻香发，高台远吹吟。
河汾应擢秀，谁肯访山阴。','',''),('quantangshi-03687','菊','李嶠','quantangshi','','卷4','玉律三秋暮，金精九日开。
荣舒洛媛浦，香泛野人杯。
靃靡寒潭侧，丰茸晓岸隈。
黄花今日晚，无复白衣来。','',''),('quantangshi-03688','竹','李嶠','quantangshi','','卷4','高簳楚江濆，婵娟含曙氛。
白花摇凤影，青节动龙文。
叶埽东南日，枝捎西北云。
谁知湘水上，流泪独思君。','',''),('quantangshi-03689','藤','李嶠','quantangshi','','卷4','吐叶依松磴，舒苗长石台。
神农尝药罢，质子寄书来。
色映蒲萄架，花分竹叶杯。
金堤不见识，玉润几重开。','',''),('quantangshi-03690','萱','李嶠','quantangshi','','卷4','屣步寻芳草，忘忧自结丛。
黄英开养性，绿叶正依笼。
色湛仙人露，香传少女风。
还依北堂下，曹植动文雄。','',''),('quantangshi-03691','茅','李嶠','quantangshi','','卷4','楚甸供王日，衡阳入贡年。
麏包青野外，鸱啸绮楹前。
尧帝成茨罢，殷汤祭雨旋。
方期大君锡，不惧小巫捐。','',''),('quantangshi-03692','荷','李嶠','quantangshi','','卷4','新溜满澄陂，圆荷影若规。
风来香气远，日落盖阴移。
鱼戏排缃叶，龟浮见绿池。
魏朝难接采，楚服但同披。','',''),('quantangshi-03693','萍','李嶠','quantangshi','','卷4','二月虹初见，三春蚁正浮。
青苹含吹转，紫蒂带波流。
屡逐明神荐，常随旅客游。
既能甜似蜜，还遶楚王舟。','',''),('quantangshi-03694','菱','李嶠','quantangshi','','卷4','钜野韶光暮，东平春溜通。
影摇江浦月，香引棹歌风。
日色翻池上，潭花发镜中。
五湖多赏乐，千里望难穷。','',''),('quantangshi-03695','瓜','李嶠','quantangshi','','卷4','欲识东陵味，青门五色瓜。
龙蹄远珠履，女臂动金花。
六子方呈瑞，三仙实可嘉。
终朝奉絺綌，谒帝伫非赊。','',''),('quantangshi-03696','松','李嶠','quantangshi','','卷4','郁郁高岩表，森森幽涧陲。
鹤栖君子树，风拂大夫枝。
百尺条阴合，千年盖影披。
岁寒终不改，劲节幸君知。','',''),('quantangshi-03697','桂','李嶠','quantangshi','','卷4','未[殖]银宫里，宁移玉殿幽。
枝生无限月，花满自然秋。
侠客条为马，仙人叶作舟。
愿君期道术，攀折可淹留。','',''),('quantangshi-03698','槐','李嶠','quantangshi','','卷4','暮律移寒火，春宫长旧栽。
叶生驰道侧，花落凤庭隈。
烈士怀忠触，鸿儒访业来。
何当赤墀下，疎干拟三台。','',''),('quantangshi-03699','柳','李嶠','quantangshi','','卷4','杨柳郁氤氲，金堤总翠氛。
庭前花类雪，楼际叶如云。
列宿分龙影，芳池写凤文。
短箫何以奏，攀折为思君。','',''),('quantangshi-03700','桐','李嶠','quantangshi','','卷4','孤秀峄阳岑，亭亭出众林。
春光杂凤影，秋月弄圭阴。
高映龙门迥，双依玉井深。
不因将入爨，谁谓作鸣琴。','',''),('quantangshi-03701','桃','李嶠','quantangshi','','卷4','独有成蹊处，穠华发井傍。
山风凝笑脸，朝露泫啼妆。
隐士颜应改，仙人路渐长。
还欣上林苑，千岁奉君王。','',''),('quantangshi-03702','李','李嶠','quantangshi','','卷4','潘岳闲居日，王戎戏陌辰。
蝶游芳径馥，鸎啭弱枝新。
叶暗青房晚，花明玉井春。
方知有灵干，特用表真人。','',''),('quantangshi-03703','梨','李嶠','quantangshi','','卷4','擅美玄光侧，传芳瀚海中。
凤文疎象郡，花影丽新丰。
色对瑶池紫，甘依大谷红。
若令逢汉主，还冀识张公。','',''),('quantangshi-03704','梅','李嶠','quantangshi','','卷4','大庾歛寒光，南枝独早芳。
雪含朝暝色，风引去来香。
妆面回青镜，歌尘起画梁。
若能遥止渴，何暇泛琼浆。','',''),('quantangshi-03705','橘','李嶠','quantangshi','','卷4','万里盘根植，千秋布叶繁。
既荣潘子赋，方重陆生言。
玉蘤含霜动，金衣逐吹翻。
愿辞湘水曲，长茂上林园。','',''),('quantangshi-03706','凤','李嶠','quantangshi','','卷4','有鸟居丹穴，其名曰凤皇。
九苞应灵瑞，五色成文章。
屡向秦楼侧，频过洛水阳。
鸣岐今日见，阿阁伫来翔。','',''),('quantangshi-03707','鹤','李嶠','quantangshi','','卷4','黄鹤远联翩，从鸾下紫烟。
翱翔一万里，来去几千年。
已憩青田侧，时游丹禁前。
莫言空警露，犹冀一闻天。','',''),('quantangshi-03708','乌','李嶠','quantangshi','','卷4','日路朝飞急，霜台夕影寒。
联翩依月树，迢递绕风竿。
白首何年改，青琴此夜弹。
灵台如可托，千里向长安。','',''),('quantangshi-03709','鹊','李嶠','quantangshi','','卷4','不分荆山抵，甘从石印飞。
危巢畏风急，绕树觉星稀。
喜逐行人至，愁随织女归。
倘游明镜里，朝夕动光辉。','',''),('quantangshi-03710','雁','李嶠','quantangshi','','卷4','春晖满朔方，归雁发衡阳。
望月惊弦影，排云结阵行。
往还倦南北，朝夕苦风霜。
寄语能鸣侣，相随入帝乡。','',''),('quantangshi-03711','凫','李嶠','quantangshi','','卷4','飒沓睢阳涘，浮游汉水隈。
钱飞出井见，鹤引入琴哀。
李陵赋诗罢，王乔曳舄来。
何当归太液，翱集动成雷。','',''),('quantangshi-03712','鸎','李嶠','quantangshi','','卷4','芳树杂花红，羣鸎乱晓空。
声分折杨吹，娇韵落梅风。
写啭清弦里，迁乔暗木中。
友生若可冀，幽谷响还通。','',''),('quantangshi-03713','雉','李嶠','quantangshi','','卷4','白雉振朝声，飞来表太平。
楚郊疑凤出，陈宝若鸡鸣。
童子怀仁至，中郎作赋成。
冀君看饮啄，耿介独含情。','',''),('quantangshi-03714','燕','李嶠','quantangshi','','卷4','天女伺辰至，玄衣澹碧空。
差池沐时雨，颉颃舞春风。
相贺雕阑侧，双飞翠幕中。
勿惊留爪去，犹冀识吴宫。','',''),('quantangshi-03715','雀','李嶠','quantangshi','','卷4','大厦初成日，嘉宾集杏梁。
衔书表周瑞，入幕应王祥。
暮宿江城里，朝游涟水傍。
愿齐鸿鹄至，希逐凤皇翔。','',''),('quantangshi-03716','龙','李嶠','quantangshi','','卷4','衔烛耀幽都，含章拟凤雏。
西秦饮渭水，东洛荐河图。
带火移星陆，升云出鼎湖。
希逢圣人步，庭阙正晨趋。','',''),('quantangshi-03717','麟','李嶠','quantangshi','','卷4','汉祀应祥开，鲁郊西狩回。
奇音中钟吕，成角喻英才。
画像临仙阁，藏书入帝台。
若惊能吐哺，为待凤皇来。','',''),('quantangshi-03718','象','李嶠','quantangshi','','卷4','郁林开郡毕，维扬作贡初。
万推方演梦，惠子正焚书。
执燧奔吴战，量舟入魏墟。
六牙行致远，千叶奉高居。','',''),('quantangshi-03719','马','李嶠','quantangshi','','卷4','天马本来东，嘶惊御史骢。
苍龙遥逐日，紫燕迥追风。
明月来鞍上，浮云落盖中。
得随穆天子，何假唐成公。','',''),('quantangshi-03720','牛','李嶠','quantangshi','','卷4','齐歌初入相，燕阵早横功。
欲向桃林下，先过梓树中。
在吴频喘月，奔梦屡惊风。
不用五丁士，如何九折通。','',''),('quantangshi-03721','豹','李嶠','quantangshi','','卷4','车法肇宗周，鼷文阐大猷。
还将君子变，来蕴太公筹。
委质超羊鞟，飞名列虎侯。
若令逢雨露，长隐南山幽。','',''),('quantangshi-03722','熊','李嶠','quantangshi','','卷4','导洛宜阳右，乘春别馆前。
昭仪忠汉日，太傅翊周年。
列射三侯满，兴师七步旋。
莫言舒紫褥，犹异饮清泉。','',''),('quantangshi-03723','鹿','李嶠','quantangshi','','卷4','涿鹿闻中冀，秦原辟帝畿。
柰花开旧苑，萍叶蔼前诗。
道士乘仙日，先生折角时。
方怀丈夫志，抗首别心期。','',''),('quantangshi-03724','羊','李嶠','quantangshi','','卷4','绝饮惩浇俗，行驱梦逸材。
仙人拥石去，童子驭车来。
夜玉含星动，晨毡映雪开。
莫言鸿渐力，长牧上林隈。','',''),('quantangshi-03725','兔','李嶠','quantangshi','','卷4','上蔡应初击，平冈远不稀。
目随槐叶长，形逐桂条飞。
汉月澄秋色，梁园映雪辉。
唯当感纯孝，郛郭引兵威。','',''),('quantangshi-03726','人日侍宴大明宫恩赐彩缕人胜应制','李嶠','quantangshi','','卷4','凤城景色已含韶，人日风光倍觉饶。
桂吐半轮迎此夜，蓂开七叶应今朝。
鱼猜水冻行犹澁，鸎喜春熙弄欲娇。
愧奉登高摇彩翰，欣逢御气上丹霄。','',''),('quantangshi-03727','奉和初春幸太平公主南庄应制','李嶠','quantangshi','','卷4','主家山第接云开，天子春游动地来。
羽骑参差花外转，霓旌摇曳日边回。
还将石溜调琴曲，更取峰霞入酒杯。
鸾辂已辞乌鹊渚，箫声犹绕凤皇台。','',''),('quantangshi-03728','太平公主山亭侍宴应制','李嶠','quantangshi','','卷4','黄金瑞牓绛河隈，白玉仙舆紫禁来。
碧树青岑云外耸，朱楼画阁水中开。
龙舟下瞰鲛人室，羽节高临凤女台。
遽惜欢娱歌吹晚，挥戈更却曜灵回。','',''),('quantangshi-03729','奉和拜洛应制','李嶠','quantangshi','','卷4','七萃銮舆动，千年瑞检开。
文如龟负出，图似凤衔来。
殷荐三神享，明禋万国陪。
周旗黄鸟集，汉幄紫云回。
日暮鈎陈转，清歌上帝台。','',''),('quantangshi-03730','奉和幸大荐福寺应制','李嶠','quantangshi','','卷4','雁沼开香域，鹦林降彩旃。
还窥图凤宇，更坐跃龙川。
桂轝朝羣辟，兰宫列四禅。
半空银阁断，分砌宝绳连。
甘雨苏燋泽，慈云动沛篇。
独慙贤作砺，空喜福成田。','',''),('quantangshi-03731','奉和幸长安故城未央宫应制','李嶠','quantangshi','','卷4','旧宫贤相筑，新苑圣君来。
运改城隍变，年深栋宇摧。
后池无复水，前殿久成灰。
莫辨祈风观，空传承露杯。
宸心千载合，睿律九韶开。
今日联章处，犹疑上柏台。','',''),('quantangshi-03732','奉和幸望春宫送朔方总管张仁亶','李嶠','quantangshi','','卷4','玉塞征骄子，金符命老臣。
三军张武斾，万乘饯行轮。
猛气凌玄朔，崇恩降紫宸。
投醪还结士，辞第本忘身。
露下鹰初击，风高雁欲宾。
方销塞北祲，还靖漠南尘。','',''),('quantangshi-03733','奉和幸三会寺应制','李嶠','quantangshi','','卷4','故台苍颉里，新邑紫泉居。
岁在开金寺，时来降玉舆。
龙形虽近刹，鸟迹尚留书。
竹是蒸青外，池仍点墨余。
天文光圣草，宝思合真如。
谬奉千龄日，欣陪十地初。','',''),('quantangshi-03734','奉和天枢成宴夷夏羣僚应制','李嶠','quantangshi','','卷4','辙迹光西崦，勋庸纪北燕。
何如万方会，颂德九门前。
灼灼临黄道，迢迢入紫烟。
仙盘正下露，高柱欲承天。
山类丛云起，珠疑大火悬。
声流尘作刼，业固海成田。
帝泽倾尧酒，宸歌掩舜弦。
欣逢下生日，还覩上皇年。','',''),('quantangshi-03735','皇帝上礼抚事述怀','李嶠','quantangshi','','卷4','配极辉光远，承天顾托隆。
负图济多难，脱履归成功。
圣道昭永锡，邕言让在躬。
还推万方重，咸仰四门聪。
恭己忘自逸，因人体至公。
垂旒沧海晏，解网法星空。
云散天五色，春还日再中。
称觞合缨弁，率舞应丝桐。
凯乐深居镐，传歌盛饮丰。
小臣滥簪笔，无以颂唐风。','',''),('quantangshi-03736','奉和幸韦嗣立山庄侍宴应制','李嶠','quantangshi','','卷4','南洛师臣契，东岩王佐居。
幽情遗绂冕，宸眷属樵渔。
制下峒山跸，恩回灞水舆。
松门驻旌盖，薜幄引簪裾。
石磴平黄陆，烟楼半紫虚。
云霞仙路近，琴酒俗尘疎。
乔木千龄外，悬泉百丈余。
崖深经炼药，穴古旧藏书。
树宿抟风鸟，池潜纵壑鱼。
宁知天子贵，尚忆武侯庐。','',''),('quantangshi-03737','倡妇行','李嶠','quantangshi','','卷4','十年倡家妇，三秋边地人。
红妆楼上歇，白发陇头新。
夜夜风霜苦，年年征戍频。
山西长落日，塞北久无春。
团扇辞恩宠，回文赠苦辛。
胡兵屡攻战，汉使绝和亲。
消息如瓶井，沈浮似路尘。
空余千里月，照妾两眉嚬。','',''),('quantangshi-03738','饯薛大夫护边','李嶠','quantangshi','','卷4','荒隅时未通，副相下临戎。
授律星芒动，分兵月晕空。
犀皮拥青橐，象齿饰雕弓。
决胜三河勇，长驱六郡雄。
登山窥代北，屈指计辽东。
伫见燕然上，抽毫颂武功。','',''),('quantangshi-03739','和杜学士旅次淮口阻风','李嶠','quantangshi','','卷4','夕吹生寒浦，清淮上暝潮。
迎风欲举棹，触浪反停桡。
淼漫烟波阔，参差林岸遥。
日沈丹气敛，天敞白云销。
水雁衔芦叶，沙鸥隐荻苗。
客行殊未已，川路几迢迢。','',''),('quantangshi-03740','送光禄刘主簿之洛','李嶠','quantangshi','','卷4','函谷双崤右，伊川二陕东。
仙舟窅将隔，芳斝暂云同。
朋席余欢尽，文房旧侣空。
他乡千里月，岐路九秋风。
背枥嘶班马，分洲呌断鸿。
别后青山外，相望白云中。','',''),('quantangshi-03741','送骆奉礼从军','李嶠','quantangshi','','卷4','玉塞边烽举，金坛庙略申。
羽书资锐笔，戎幕引英宾。
剑动三军气，衣飘万里尘。
琴尊留别赏，风景惜离晨。
笛梅含晚吹，营柳带余春。
希君勒石返，歌舞入城闉。','',''),('quantangshi-03742','王屋山第之侧杂构小亭暇日与羣公同游','李嶠','quantangshi','','卷4','桂亭依绝巘，兰榭俯回溪。
绮栋鱼鳞出，雕甍凤羽栖。
引泉聊涨沼，凿磴且通蹊。
席上山花落，帘前野树低。
弋林开曙景，钓渚发晴霓。
狎水惊梁雁，临风听楚鸡。
复看题柳叶，弥喜荫桐圭。','',''),('quantangshi-03743','奉和杜员外扈从教阅','李嶠','quantangshi','','卷4','杪冬严杀气，穷纪送颓光。
薄狩三农隙，大阅五戎塲。
菜田初起烧，兰野正开防。
夹岸虹旗转，分朋兽罟张。
燕弧带晓月，吴劒动秋霜。
原启前禽路，山萦后骑行。
云区坠日羽，星苑毙天狼。
礼振军容肃，威宣武节扬。
神心体殷祝，灵兆叶姬祥。
幸陪仙驾末，欣采翰林芳。','',''),('quantangshi-03744','军师凯旋自邕州顺流舟中','李嶠','quantangshi','','卷4','鸣鞞入嶂口，泛舸历川湄。
尚想江陵阵，犹疑下濑师。
岸回帆影疾，风逆鼓声迟。
萍叶沾兰桨，林花拂桂旗。
弓鸣苍隼落，劒动白猿悲。
芳树吟羗管，幽篁入楚词。
全军多胜策，无战在明时。
寄谢山东妙，长缨徒自欺。','',''),('quantangshi-03745','夏晚九成宫呈同僚','李嶠','quantangshi','','卷4','碣馆分襄野，平台架射峰。
英藩信炜烨，胜地本从容。
林引梧庭凤，泉归竹沼龙。
小轩恒共处，长坂属相从。
野席兰琴奏，山台桂酒醲。
一枰移昼景，六着尽宵钟。
枚藻清词律，邹谈耀辩锋。
结欢良有裕，联寀愧无庸。
暂悦丘中赏，还希物外踪。
风烟远近至，鱼鸟去来逢。
月涧横千丈，云崖列万重。
树红山果熟，崖绿水苔浓。
愿以西园柳，长间北岩松。','',''),('quantangshi-03746','田假限疾不获还庄载想田园兼思亲友率成短韵用写长怀赠杜幽素','李嶠','quantangshi','','卷4','游宦劳牵网，风尘久化衣。
迹驰东苑路，望阻北岩扉。
及此承休告，聊将狎遯肥。
十旬俄委疾，三径且殊归。
茂陵窅难即，灵台暂可依。
疲疴旅城寺，延想属郊畿。
夕梦园林是，晨瞻邑里非。
绿畴良已秽，清濠旷不追。
野花何处落？山月几秋辉。
彼美符商政，优游绝汉机。
高情物累遣，逸气烟霞飞。
乐道方无闷，怀贤独有违。
尊虚旧园酒，琴静故人徽。
夏沼莲初发，秋田麦稍稀。
何当携手去，岁暮采芳菲。','',''),('quantangshi-03747','刘侍读见和山邸十篇重申此赠','李嶠','quantangshi','','卷4','神岳瑶池圃，仙宫玉树林。
乘时警天御，清暑涤宸襟。
梁驾陪玄赏，淄庭掩翠岑。
对岩龙岫出，分壑雁池深。
檐迥松萝映，窗高石镜临。
落泉奔涧响，惊吹助猿吟。
野气迷凉燠，山花杂古今。
英藩盛宾侣，胜景想招寻。
践径披兰叶，攀崖引桂阴。
穆生时泛醴，邹子或调琴。
雉翳分塲合，鱼钩向浦沈。
朝游极斜景，夕宴待横参。
顾己慙铅锷，叨名齿玳簪。
暂依朱邸馆，还畅白云心。
丘壑信多美，烟霞得所钦。
寓言摅宿志，窃吹简知音。
奖价逾珍石，酬文重振金。
方从仁智所，携手濯清浔。','',''),('quantangshi-03748','晚秋喜雨','李嶠','quantangshi','','卷4','积阳躔首夏，隆旱届徂秋。
炎威振皇服，歊景暴神州。
气涤朝川朗，光澄夕照浮。
草木委林甸，禾黍悴原畴。
国惧流金眚，人深悬磬忧。
紫宸兢履薄，丹扆念推沟。
望肃坛场祀，冤申囹圄囚。
御车迁玉殿，荐菲撤琼羞。
济窘邦储发，蠲穷井赋优。
服闲云骥屏，冗术土龙修。
睿感通三极，天诚贯六幽。
夏祈良未拟，商祷讵为俦。
穴蚁祯符应，山蛇毒影收。
腾云八际满，飞雨四溟周。
聚霭笼仙阙，连霏绕画楼。
旱陂仍积水，涸沼更通流。
晚穗萎还结，寒苗瘁复抽。
九农欢岁阜，万宇庆时休。
野洽如坻咏，途喧击壤讴。
幸闻东李道，欣奉北场游。','',''),('quantangshi-03749','中秋月二首 一','李嶠','quantangshi','','卷4','盈缺青冥外，东风万古吹。
何人种丹桂，不长出轮枝。','',''),('quantangshi-03750','中秋月二首 二','李嶠','quantangshi','','卷4','圆魄上寒空，皆言四海同。
安知千里外，不有雨兼风。','',''),('quantangshi-03751','侍宴桃花园咏花应制','李嶠','quantangshi','','卷4','岁去无言忽顦顇，时来含笑吐氛氲。
不能拥路迷仙客，故欲开蹊待圣君。','',''),('quantangshi-03752','奉和圣制幸韦嗣立山庄应制','李嶠','quantangshi','','卷4','万骑千官拥帝车，八龙三马访仙家。
凤皇原上开青壁，鹦鹉杯中弄紫霞。','',''),('quantangshi-03753','游苑遇雪应制','李嶠','quantangshi','','卷4','散漫祥云逐圣回，飘颻瑞雪绕天来。
不能落后争飞絮，故欲迎前赛早梅。','',''),('quantangshi-03754','送司马先生','李嶠','quantangshi','','卷4','蓬阁桃源两处分，人间海上不相闻。
一朝琴里悲黄鹤，何日山头望白云。','',''),('quantangshi-03755','风','李嶠','quantangshi','','卷4','解落三秋叶，能开二月花。
过江千尺浪，入竹万竿斜。','',''),('quantangshi-03756','上清晖合遇雪','李嶠','quantangshi','','卷4','千钟圣酒御筵披，六出祥英乱绕枝。
即此神仙对琼圃，何须辙迹向瑶池。','',''),('quantangshi-03757','石淙','李嶠','quantangshi','','卷4','羽盖龙旗下绝冥，兰除薜幄坐云扃。
鸟和百籁疑调管，花发千岩似画屏。
金竈浮烟朝漠漠，石牀寒水夜泠泠。
自然碧洞窥仙境，何必丹丘是福庭。','',''),('quantangshi-03758','南海乱石山作','杜審言','quantangshi','','卷4','涨海积稽天，羣山高嶪地。
相传称乱石，图典失其事。
悬危悉可惊，大小都不类。
乍将云岛极，还与星河次。
上耸忽如飞，下临仍欲坠。
朝暾赩丹紫，夜魄炯青翠。
穹崇雾雨蓄，幽隐灵仙閟。
万寻挂鹤巢，千丈垂猿臂。
昔去景风涉，今来姑洗至。
观此得咏歌，长时想精异。','',''),('quantangshi-03759','送和西蕃使','杜審言','quantangshi','','卷4','使出凤皇池，京师阳春晚。
圣朝尚边策，诏谕兵戈偃。
拜手明光殿，摇心上林苑。
种落逾青羌，关山度赤坂。
疆场及无事，雅歌而餐饭。
宁独锡和戎，更当封定远。','',''),('quantangshi-03760','蓬莱三殿侍宴奉敕咏终南山应制','杜審言','quantangshi','','卷4','北斗挂城边，南山倚殿前。
云标金阙迥，树杪玉堂悬。
半岭通佳气，中峰绕瑞烟。
小臣持献寿，长此戴尧天。','',''),('quantangshi-03761','望春亭侍游应诏','杜審言','quantangshi','','卷4','帝出明光殿，天临太液池。
尧樽随步辇，舜乐绕行麾。
万寿祯祥献，三春景物滋。
小臣同酌海，歌颂答无为。','',''),('quantangshi-03762','宿羽亭侍宴应制','杜審言','quantangshi','','卷4','步辇千门出，离宫二月开。
风光新柳报，宴赏落花催。
碧水摇空阁，青山绕吹台。
圣情留晚兴，歌管送余杯。','',''),('quantangshi-03763','岁夜安乐公主满月侍宴应制','杜審言','quantangshi','','卷4','戚里生昌胤，天杯宴重臣。
画楼初满月，香殿早迎春。
睿作尧君宝，孙谋梁国珍。
明朝元会日，万寿乐章陈。','',''),('quantangshi-03764','奉和七夕侍宴两仪殿应制','杜審言','quantangshi','','卷4','一年衔别怨，七夕始言归。
敛泪开星靥，微步动云衣。
天回兔欲落，河旷鹊停飞。
那堪尽此夜，复往弄残机。','',''),('quantangshi-03765','大酺','杜審言','quantangshi','','卷4','圣后乘干日，皇明御历辰。
紫宫初启坐，苍璧正临春。
雷雨垂膏泽，金钱赠下人。
诏酺欢赏徧，交泰覩惟新。','',''),('quantangshi-03766','赋得妾薄命','杜審言','quantangshi','','卷4','草绿长门掩，苔青永巷幽。
宠移新爱夺，泪落故情留。
啼鸟惊残梦，飞花搅独愁。
自怜春色罢，团扇复迎秋。','',''),('quantangshi-03767','和韦承庆过义阳公主山池五首 一','杜審言','quantangshi','','卷4','野兴城中发，朝英物外求。
情悬朱绂望，契动赤泉游。
海燕巢书阁，山鸡舞画楼。
雨余清晚夏，共坐北岩幽。','',''),('quantangshi-03768','和韦承庆过义阳公主山池五首 二','杜審言','quantangshi','','卷4','迳转危峰逼，桥回缺岸妨。
玉泉移酒味，石髓换粳香。
绾雾青丝弱，牵风紫蔓长。
犹言宴乐少，别向后池塘。','',''),('quantangshi-03769','和韦承庆过义阳公主山池五首 三','杜審言','quantangshi','','卷4','携琴遶碧沙，摇笔弄青霞。
杜若幽庭草，芙蓉曲沼花。
宴游成野客，形胜得仙家。
往往留仙步，登攀日易斜。','',''),('quantangshi-03770','和韦承庆过义阳公主山池五首 四','杜審言','quantangshi','','卷4','攒石当轩倚，悬泉度牖飞。
鹿麛冲妓席，鹤子曳童衣。
园果尝难遍，池莲摘未稀。
卷帘唯待月，应在醉中归。','',''),('quantangshi-03771','和韦承庆过义阳公主山池五首 五','杜審言','quantangshi','','卷4','赏翫期他日，高深爱此时。
池分八水背，峰作九山疑。
地静鱼偏逸，人闲鸟欲欺。
青溪留别兴，更与白云期。','',''),('quantangshi-03772','和晋陵陆丞早春游望','杜審言','quantangshi','','卷4','独有宦游人，偏惊物候新。
云霞出海曙，梅柳渡江春。
淑气催黄鸟，晴光转绿苹。
忽闻歌古调，归思欲霑巾。','',''),('quantangshi-03773','秋夜宴临津郑明府宅','杜審言','quantangshi','','卷4','行止皆无地，招寻独有君。
酒中堪累月，身外即浮云。
露白宵钟彻，风清晓漏闻。
坐携余兴往，还似未离羣。','',''),('quantangshi-03774','和康五庭芝望月有怀','杜審言','quantangshi','','卷4','明月高秋迥，愁人独夜看。
暂将弓并曲，飜与扇俱团。
雾濯清辉苦，风飘素影寒。
罗衣一此鉴，顿使别离难。','',''),('quantangshi-03775','登襄阳城','杜審言','quantangshi','','卷4','旅客三秋至，层城四望开。
楚山横地出，汉水接天回。
冠盖非新里，章华即旧台。
习池风景异，归路满尘埃。','',''),('quantangshi-03776','旅寓安南','杜審言','quantangshi','','卷4','交趾殊风候，寒迟暖复催。
仲冬山果熟，正月野花开。
积雨生昏雾，轻霜下震雷。
故乡逾万里，客思倍从来。','',''),('quantangshi-03777','春日怀归','杜審言','quantangshi','','卷4','心是伤归望，春归异往年。
河山鉴魏阙，桑梓忆秦川。
花杂芳园鸟，风和绿野烟。
更怀欢赏地，车马洛桥边。','',''),('quantangshi-03778','代张侍御伤美人','杜審言','quantangshi','','卷4','二八泉扉掩，帷屏宠爱空。
泪痕消夜烛，愁绪乱春风。
巧笑人疑在，新妆曲未终。
应怜脂粉气，留着舞衣中。','',''),('quantangshi-03779','送高郎中北使','杜審言','quantangshi','','卷4','北狄愿和亲，东京发使臣。
马衔边地雪，衣染异方尘。
岁月催行旅，恩荣变苦辛。
歌钟期重锡，拜手落花春。','',''),('quantangshi-03780','都尉山亭','杜審言','quantangshi','','卷4','紫藤萦葛藟，绿刺罥蔷薇。
下钓看鱼跃，探巢畏鸟飞。
叶疎荷已晚，枝亚果新肥。
胜迹都无限，只应伴月归。','',''),('quantangshi-03781','夏日过郑七山斋','杜審言','quantangshi','','卷4','共有樽中好，言寻谷口来。
薜萝山迳入，荷芰水亭开。
日气含残雨，云阴送晚雷。
洛阳钟鼓至，车马系迟回。','',''),('quantangshi-03782','送崔融','杜審言','quantangshi','','卷4','君王行出将，书记远从征。
祖帐连河阙，军麾动洛城。
旌旃朝朔气，笳吹夜边声。
坐觉烟尘扫，秋风古北平。','',''),('quantangshi-03783','经行岚州','杜審言','quantangshi','','卷4','北地春光晚，边城气候寒。
往来花不发，新旧雪仍残。
水作琴中听，山疑画里看。
自惊牵远役，艰险促征鞍。','',''),('quantangshi-03784','重九日宴江阴','杜審言','quantangshi','','卷4','蟋蟀期归晚，茱萸节候新。
降霜青女月，送酒白衣人。
高兴要长寿，卑栖隔近臣。
龙沙即此地，旧俗坐为邻。','',''),('quantangshi-03785','除夜有怀','杜審言','quantangshi','','卷4','故节当歌守，新年把烛迎。
冬氛恋虬箭，春色候鸡鸣。
兴尽闻壶覆，宵阑见斗横。
还将万亿寿，更谒九重城。','',''),('quantangshi-03786','晦日宴游','杜審言','quantangshi','','卷4','日晦随蓂荚，春情着杏花。
解绅宜就水，张幕会连沙。
歌管风轻度，池台日半斜。
更看金谷骑，争向石崇家。','',''),('quantangshi-03787','七夕','杜審言','quantangshi','','卷4','白露含明月，青霞断绛河。
天街七襄转，阁道二神过。
袨服锵环佩，香筵拂绮罗。
年年今夜尽，机杼别情多。','',''),('quantangshi-03788','守岁侍宴应制','杜審言','quantangshi','','卷4','季冬除夜接新年，帝子王孙捧御筵。
宫阙星河低拂树，殿廷灯烛上薰天。
弹弦奏节梅风入，对局探钩柏酒传。
欲向正元歌万寿，暂留欢赏寄春前。','',''),('quantangshi-03789','大酺','杜審言','quantangshi','','卷4','毗陵震泽九州通，士女欢娱万国同。
伐鼓撞钟惊海上，新妆袨服照江东。
梅花落处疑残雪，柳叶开时任好风。
火德云官逢道泰，天长地久属年丰。','',''),('quantangshi-03790','春日京中有怀','杜審言','quantangshi','','卷4','今年游寓独游秦，愁思看春不当春。
上林苑里花徒发，细柳营前叶漫新。
公子南桥应尽兴，将军西第几留宾。
寄语洛城风日道，明年春色倍还人。','',''),('quantangshi-03791','扈从出长安应制','杜審言','quantangshi','','卷4','分野都畿列，时乘六御均。
京师旧西幸，洛道此东巡。
文物驱三统，声名走百神。
龙旗萦漏夕，凤辇拂鈎陈。
抚迹地灵古，游情皇鉴新。
山追散马日，水忆钓鱼人。
禹食传中使，尧樽遍下臣。
省方称国阜，问道识风淳。
岁晚天行吉，年丰景从亲。
欢娱包历代，宇宙忽疑春。','',''),('quantangshi-03792','春日江津游望','杜審言','quantangshi','','卷4','旅客摇边思，春江弄晚晴。
烟销垂柳弱，雾卷落花轻。
飞棹乘空下，回流向日平。
鸟啼移几处，蝶舞乱相迎。
忽叹人皆浊，堤防水至清。
谷王常不让，深可戒中盈。','',''),('quantangshi-03793','泛舟送郑卿入京','杜審言','quantangshi','','卷4','帝坐蓬莱殿，恩追社稷臣。
长安遥向日，宗伯正乘春。
相宅开基地，倾都送别人。
行舟萦渌水，列戟满红尘。
酒助欢娱洽，风催景气新。
此时光乃命，谁为惜无津。','',''),('quantangshi-03794','度石门山','杜審言','quantangshi','','卷4','石门千仞断，迸水落遥空。
道束悬崖半，桥欹绝涧中。
仰攀人屡息，直下骑才通。
泥拥奔虵径，云埋伏兽丛。
星躔牛斗北，地脉象牙东。
开塞随行变，高深触望同。
江声连骤雨，日气抱残虹。
未改朱明律，先含白露风。
坚贞深不惮，险澁谅难穷。
有异登临赏，徒为造化功。','',''),('quantangshi-03795','赠崔融二十韵','杜審言','quantangshi','','卷4','十年俱薄宦，万里各他方。
云天断书札，风土异炎凉。
太息幽兰紫，劳歌奇树黄。
日疑怀叔度，夜似忆真长。
北使从江表，东归在洛阳。
相逢慰畴昔，相对叙存亡。
草深穷巷毁，竹尽故园荒。
雅节君弥固，衰颜余自伤。
人事盈虚改，交游宠辱妨。
雀罗争去翟，鹤氅竞寻王。
思极欢娱至，朋情讵可忘。
琴樽横宴席，岩谷卧词场。
连骑追佳赏，城中及路傍。
三川宿雨霁，四月晚花芳。
复此开悬榻，宁唯入后堂。
兴酣鸲鹆舞，言洽凤皇翔。
高选俄迁职，严程已饬装。
抚躬衔道义，携手恋辉光。
玉振先推美，金铭旧所防。
勿嗟离别易，行役共时康。','',''),('quantangshi-03796','赠苏味道','杜審言','quantangshi','','卷4','北地寒应苦，南庭戍未归。
边声乱羗笛，朔气卷戎衣。
雨雪关山暗，风霜草木稀。
胡兵战欲尽，虏骑猎犹肥。
雁塞何时入，龙城几度围。
据鞍雄劒动，插笔羽书飞。
舆驾还京邑，朋游满帝畿。
方期来献凯，歌舞共春辉。','',''),('quantangshi-03797','和李大夫嗣真奉使存抚河东','杜審言','quantangshi','','卷4','六位干坤动，三微历数迁。
讴歌移火德，图谶在金天。
子月开阶统，房星受命年。
祯符龙马出，宝箓凤凰传。
地即交风雨，都仍卜涧瀍。
明堂唯御极，清庙乃尊先。
不宰神功运，无为大象悬。
八荒平物土，四海接人烟。
已属羣生泰，犹言至道偏。
玺书傍问俗，旌节近推贤。
秩比司空位，官临御史员。
雄词执刀笔，直谏罢楼船。
国有大臣器，朝加小会筵。
将行备礼乐，送别仰神仙。
城阙周京转，关河陕服连。
稍观汾水曲，俄指绛台前。
姑射聊长望，平阳遂宛然。
舜耕余草木，禹凿旧山川。
昔出诸侯上，无何霸业全。
中军归战敌，外府绝兵权。
隐隐帝乡远，瞻瞻肃命虔。
西河偃风俗，东壁挂星躔。
井邑枌榆社，陵园松柏田。
荣光晴掩代，佳气晓侵燕。
雨霈鸿私涤，风行睿旨宣。
茕嫠访疾苦，屠钓采贞坚。
人乐逢刑措，时康洽赏延。
赐逾秦氏级，恩倍汉家钱。
拥传咸翘首，称觞竞比肩。
拜迎弥道路，舞咏溢郊鄽。
杀气西衡白，穷阴北暝玄。
飞霜遥渡海，残月迥临边。
缅邈朝廷问，周流朔塞旋。
兴来探马策，俊发抱龙泉。
学总八千卷，文倾三百篇。
澄清得使者，作颂有人焉。
莫以崇班阂，而云胜托捐。
伟材何磊落，陋质几翩翾。
江海宁为让，巴渝转自牵。
一闻歌圣道，助曲荷陶甄。','',''),('quantangshi-03798','赠苏绾书记','杜審言','quantangshi','','卷4','知君书记本翩翩，为许从戎赴朔边。
红粉楼中应计日，燕支山下莫经年。','',''),('quantangshi-03799','渡湘江','杜審言','quantangshi','','卷4','迟日园林悲昔游，今春花鸟作边愁。
独怜京国人南窜，不似湘江水北流。','',''),('quantangshi-03800','戏赠赵使君美人','杜審言','quantangshi','','卷4','红粉青娥暎楚云，桃花马上石榴帬。
罗敷独向东方去，谩学他家作使君。','',''),('quantangshi-03801','三妇艳','董思恭','quantangshi','','卷4','大妇裁纨素，中妇弄明璫。
小妇多姿态，登楼红粉妆。
丈人且安坐，初日渐流光。','',''),('quantangshi-03802','感怀','董思恭','quantangshi','','卷4','野郊怆新别，河桥非旧饯。
惨日映峰沈，愁云随盖转。
哀笳时断续，悲旌乍舒卷。
望望情何极，浪浪泪空泫。
无复昔时人，芳春共谁遣。','',''),('quantangshi-03803','守岁二首 一','董思恭','quantangshi','','卷4','暮景斜芳殿，年华丽绮宫。
寒辞去冬雪，暖带入春风。
阶馥舒梅素，盘花卷烛红。
共欢新故岁，迎送一宵中。','',''),('quantangshi-03804','守岁二首 二','董思恭','quantangshi','','卷4','岁阴穷暮纪，献节启新芳。
冬尽今宵促，年开明日长。
冰销出镜水，梅散入风香。
对此欢终宴，倾壶待曙光。','',''),('quantangshi-03805','昭君怨二首 一','董思恭','quantangshi','','卷4','新年犹尚小，那堪远聘秦。
裾衫霑马汗，眉黛染胡尘。
举眼无相识，路逢皆异人。
唯有梅将李，犹带故乡春。','',''),('quantangshi-03806','昭君怨二首 二','董思恭','quantangshi','','卷4','琵琶马上弹，行路曲中难。
汉月正南远，燕山直北寒。
髻鬟风拂乱，眉黛雪霑残。
斟酌红颜改，徒劳握镜看。','',''),('quantangshi-03807','咏日','董思恭','quantangshi','','卷4','沧海十枝晖，悬圃重轮庆。
蕣华发晨楹，菱彩飜朝镜。
忽遇惊风飘，自有浮云映。
更也人皆仰，无待挥戈正。','',''),('quantangshi-03808','咏月','董思恭','quantangshi','','卷4','北堂未安寝，西园聊骋望。
玉户照罗帏，珠轩明绮障。
别客长安道，思妇高楼上。
所愿君莫违，清风时可访。','',''),('quantangshi-03809','咏星','董思恭','quantangshi','','卷4','历历东井舍，昭昭右掖垣。
云际龙文出，池中鸟色飜。
流辉下月路，坠影入河源。
方知颍川集，别有太丘门。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-03810','咏风','董思恭','quantangshi','','卷4','萧萧度阊阖，习习下庭闱。
花蝶自飘舞，兰蕙生光辉。
相乌正举翼，退鷁已惊飞。
方从列子御，更逐浮云归。','',''),('quantangshi-03811','咏云','董思恭','quantangshi','','卷4','帝乡白云起，飞盖上天衢。
带月绮罗映，从风枝叶敷。
参差过层阁，倏忽下苍梧。
因风望既远，安得久踟蹰。','',''),('quantangshi-03812','咏雪','董思恭','quantangshi','','卷4','天山飞雪度，言是落花朝。
惜哉不我与，萧索从风飘。
鲜洁凌纨素，纷糅下枝条。
良时竟何在，坐见容华销。','',''),('quantangshi-03813','咏露','董思恭','quantangshi','','卷4','夜色凝仙掌，晨甘下帝庭。
不觉九秋至，远向三危零。
芦渚花初白，葵园叶尚青。
曦阳一洒惠，方愿益沧溟。','',''),('quantangshi-03814','咏雾','董思恭','quantangshi','','卷4','苍山寂已暮，翠观黯将沈。
终南晨豹隐，巫峡夜猿吟。
天寒气不歇，景晦色方深。
待访公超市，将予赴华阴。','',''),('quantangshi-03815','咏虹','董思恭','quantangshi','','卷4','春暮萍生早，日落雨飞余。
横彩分长汉，倒色媚清渠。
梁前朝影出，桥上晚光舒。
愿逐旌旗转，飘飘侍直庐。','',''),('quantangshi-03816','咏桃','董思恭','quantangshi','','卷4','禁苑春光丽，花蹊几树装。
缀条深浅色，点露参差光。
向日分千笑，迎风共一香。
如何仙岭侧，独秀隐遥芳。','',''),('quantangshi-03817','咏李','董思恭','quantangshi','','卷4','盘根植瀛渚，交干横倚天。
舒华光四海，卷叶荫山川。','',''),('quantangshi-03818','咏弓','董思恭','quantangshi','','卷4','上弦明月半，激箭流星远。
落雁带书惊，啼猿映枝转。','',''),('quantangshi-03819','咏琵琶','董思恭','quantangshi','','卷4','半月无双影，金花有四时。
摧藏千里态，掩抑几重悲。
促节萦红袖，清音满翠帷。
驶弹风响急，缓曲钏声迟。
空余关陇恨，因此代相思。','',''),('quantangshi-03820','经庐岳回望江州想洛川有作','劉允濟','quantangshi','','卷4','龟山帝始营，龙门禹初凿。
出入经变化，俯仰凭寥廓。
未若兹山功，连延竝巫霍。
东北疏艮象，西南距坤络。
宏阜自郁盘，高标复回薄。
势入柴桑渚，阴开彭蠡壑。
九江杳无际，七泽纷相错。
云雨散吴会，风波腾鄬鄀。
迹随造化久，利与干坤博。
肸蠁精气通，纷纶潜怪作。
石渠忽见践，金房安可托。
地入天子都，岩有仙人药。
二门几迢遰，三宫何儵爚。
咫尺穷杳冥，跬步皆恬漠。
仙才惊羽翰，幽居静龙蠖。
明牧振雄词，棣华殊灼灼。
盛业匡西夏，深谋赞禹亳。
黄云覆鼎飞，绛气横川跃。
佐历符贤运，人期茂天爵。
礼乐富垂髫，诗书成舞勺。
清辉靖岩电，利器腾霜锷。
游圣挹衢尊，邻畿恭木铎。
岩仞包武侯，波澜控文若。
旋闻刈薪楚，遽覩升葵藿。
稷契序揆图，良平公辅略。
重地资出守，英藩谅求瘼。
豫章观伟材，江州访灵崿。
阳岫晓氛氲，阴崖暮萧索。
潜伏屡黥奔，雄飞更鸷搏。
惊𤢹透烟霞，腾猿乱枝格。
故园有归梦，他山飞赏乐。
帝乡徒可游，湟涧终旅泊。
景物观淮海，云霄望河洛。
城阙紫微星，图书玄扈阁。
神功多粉缋，元气犹斟酌。
丞相下南宫，将军趋北落。
横簪竝附蝉，列鼎俱调鹤。
四郊时迷路，五月先投龠。
池榭宣琼管，风花乱珠箔。
旧游劳梦寐，新知无悦乐。
天寒欲赠言，岁暮期交约。
夜琴清玉柱，秋灰变缇幕。
风云动翰林，宫征调文龠。
言泉激为浪，思绪飞成缴。
千里辉珠玑，五采含丹雘。
钟鼓旋惊鷃，瑾瑜俄抵鹊。
窃价慙庸怠，叨声逾寂莫。
长望限南溟，居然翳东郭。','',''),('quantangshi-03821','咏琴','劉允濟','quantangshi','','卷4','昔在龙门侧，谁想凤鸣时。
雕琢今为器，宫商不自持。
巴人缓疎节，楚客弄繁丝。
欲作高张引，飜成下调悲。','',''),('quantangshi-03822','怨情','劉允濟','quantangshi','','卷4','玉关芳信断，兰闺锦字新。
愁来好自抑，念切已含嚬。
虚牖风惊梦，空牀月厌人。
归期倘可促，勿度柳园春。','',''),('quantangshi-03823','见道边死人','劉允濟','quantangshi','','卷4','凄凉徒见日，冥寞讵知年。
魂兮不可问，应为直如弦。','',''),('quantangshi-03824','九日登玄武山旅眺','邵大震','quantangshi','','卷4','九月九日望遥空，秋水秋天生夕风。
寒雁一向南去远，游人几度菊花丛。','',''),('quantangshi-03825','军中行路难','辛常伯','quantangshi','','卷4','君不见封狐雄虺自成羣，凭深负固结妖氛。
玉玺分兵征恶少，金坛授律动将军。
将军拥麾宣庙略，战士横戈静夷落。
长驱一息背铜梁，直指三危登劒阁。
阁道岧峣起戍楼，劒门遥裔俯灵丘。
邛关九折无平路，江水双源有急流。
征役无期返，他乡岁华晚。
杳杳丘陵出，苍苍林薄远。
途危紫盖峰，路涩青泥坂。
去去指哀牢，行行入不毛。
绝壁千里险，连山四望高。
中外分区宇，夷夏殊风土。
交址枕南荒，昆弥临北户。
川原饶毒雾，溪谷多霪雨。
行潦四时流，崩查千岁古。
漂梗飞蓬不暂安，扪萝引葛陟危峦。
昔时闻道从军乐，今日方知行路难。
沧江绿水东流驶，炎州丹徼南中地。
南中南斗映星河，秦关秦塞阻烟波。
三春边地风光少，五月泸川瘴疠多。
朝驱疲斥候，夕息倦樵歌。
向月弯繁弱，连星转太阿。
重义轻生怀一顾，东伐西征凡几度。
夜夜朝朝斑鬓新，年年岁岁戎衣故。
灞城隅，滇池水。
天涯望转积，地际行无已。
徒觉炎凉节物非，不知关山千万里。
弃置勿重陈，重陈多苦辛。
且悦清笳梅柳曲，讵忆芳园桃李人。
绛节红旗分日羽，丹心白刃酬明主。
但令一被君王知，谁惮三边征战苦。
行路难，岐路几千端。
无复归云凭短翰，空余望日想长安。','',''),('quantangshi-03826','奉和圣制夏日游石淙山','姚崇','quantangshi','','卷4','二室三涂光地险，均霜揆日处天中。
石泉石镜恒留月，山鸟山花竞逐风。
周王久谢瑶池赏，汉主悬慙玉树宫。
别有祥烟伴佳气，能随轻辇共葱葱。','',''),('quantangshi-03827','故洛阳城侍宴应制','姚崇','quantangshi','','卷4','游豫停仙跸，登临对晚晴。
川凫连倒影，岩鸟应虚声。
野奏风成曲，山居云作缨。
今朝丘壑上，高兴小蓬瀛。','',''),('quantangshi-03828','春日洛阳城侍宴','姚崇','quantangshi','','卷4','南山开宝历，北渚对芳蹊。
的历风梅度，参差露草低。
尧樽临上席，舜乐下前溪。
任重由来醉，乘酣志转迷。','',''),('quantangshi-03829','秋夜望月','姚崇','quantangshi','','卷4','明月有余鉴，羁人殊未安。
桂含秋树晚，波入夜池寒。
灼灼云枝净，光光草露团。
所思迷所在，长望独长叹。','',''),('quantangshi-03830','夜渡江','姚崇','quantangshi','','卷4','夜渚带浮烟，苍茫晦远天。
舟轻不觉动，缆急始知牵。
听草遥寻岸，闻香暗识莲。
唯看孤帆影，常似客心悬。','',''),('quantangshi-03831','奉和圣制龙池篇','姚崇','quantangshi','','卷4','恭闻帝里生灵沼，应报明君鼎业新。
既协翠泉光宝命，还符白水出真人。
此时舜海潜龙跃，此地尧河带马巡。
独有前池一小雁，叨承旧惠入天津。','',''),('quantangshi-03832','句','姚崇','quantangshi','','卷4','扇掩将雏曲，钗承堕马鬟。','',''),('quantangshi-03833','奉和御制璟与张说源干曜同日上官命宴都堂赐诗应制','璟','quantangshi','','卷4','丞相邦之重，非贤谅不居。
老臣慵且惫，何德以当诸。
厚秩先为忝，崇班复此除。
太常陈礼乐，中掖降簪裾。
圣酒山河润，仙文象纬舒。
冒恩怀宠锡，陈力省空虚。
郭隗慙无骏，冯谖愧有鱼。
不知周勃者，荣幸定何如。','',''),('quantangshi-03834','奉和圣制同二相已下羣官乐游园宴','璟','quantangshi','','卷4','侍饮终酺会，承恩续胜游。
戴天惟庆幸，选地即殊尤。
北向祗双阙，南临赏一丘。
曲江新溜暖，上苑杂花稠。
亹亹韶弦屡，戋戋贲帛周。
醉归填畛陌，荣耀接轩裘。','',''),('quantangshi-03835','奉和圣制送张说巡边','璟','quantangshi','','卷4','帝道薄存兵，王师尚有征。
是关司马法，爰命总戎行。
画阃崇威信，分麾盛宠荣。
聚观方结辙，出祖遂倾城。
圣酒江河润，天词象纬明。
德风边草偃，胜气朔云平。
宰国推良器，为军挹壮声。
至和常得体，不战即亡精。
以智泉宁竭，其徐海自清。
迟还庙堂坐，赠别故人情。','',''),('quantangshi-03836','奉和圣制答张说扈从南出雀鼠谷','璟','quantangshi','','卷4','秦地雄西夏，并州近北胡。
禹行山启路，舜在邑为都。
忽视寒暄隔，深思险易殊。
四时宗伯叙，六义宰臣铺。
征作宫常应，星环日每纡。
盛哉逢道合，良以致亨衢。','',''),('quantangshi-03837','蒲津迎驾','璟','quantangshi','','卷4','回銮下蒲坂，飞斾指秦京。
雒上黄云送，关中紫气迎。
霞朝看马色，月晓听鸡鸣。
防拒连山险，长桥压水平。
省方知化洽，察俗觉时清。
天下长无事，空余襟带名。','',''),('quantangshi-03838','送苏尚书赴益州','璟','quantangshi','','卷4','我望风烟接，君行霰雪飞。
园亭若有送，杨柳最依依。','',''),('quantangshi-03839','初春行宫侍宴应制','蘇味道','quantangshi','','卷4','温液吐涓涓，跳波急应弦。
簪裾承睿赏，花柳发韶年。
圣酒千钟洽，宸章七曜悬。
微臣从此醉，还似梦钧天。','',''),('quantangshi-03840','单于川对雨二首 一','蘇味道','quantangshi','','卷4','崇朝遘行雨，薄晚屯密云。
缘阶起素沫，竟水聚圆文。
河柳低未举，山花落已芬。
清尊久不荐，淹留遂待君。','',''),('quantangshi-03841','单于川对雨二首 二','蘇味道','quantangshi','','卷4','飞雨欲迎旬，浮云已送春。
还从濯枝后，来应洗兵辰。
气合龙祠外，声过鲸海滨。
伐邢知有属，已见静边尘。','',''),('quantangshi-03842','正月十五夜','蘇味道','quantangshi','','卷4','火树银花合，星桥铁锁开。
暗尘随马去，明月逐人来。
游伎皆穠李，行歌尽落梅。
金吾不禁夜，玉漏莫相催。','',''),('quantangshi-03843','咏雾','蘇味道','quantangshi','','卷4','氤氲起洞壑，遥裔匝平畴。
乍似含龙劒，还疑映蜃楼。
拂林随雨密，度径带烟浮。
方谢公超步，终从彦辅游。','',''),('quantangshi-03844','咏虹','蘇味道','quantangshi','','卷4','纡余带星渚，窈窕架天浔。
空因壮士见，还共美人沈。
逸照含良玉，神花藻瑞金。
独留长劒彩，终负昔贤心。','',''),('quantangshi-03845','咏霜','蘇味道','quantangshi','','卷4','金只暮律尽，玉女暝氛归。
孕冷随钟彻，飘华逐劒飞。
带日浮寒影，乘风进晚威。
自有贞筠质，宁将庶草腓。','',''),('quantangshi-03846','咏井','蘇味道','quantangshi','','卷4','玲珑映玉槛，澄澈泻银牀。
流声集孔雀，带影出羵羊。
桐落秋蛙散，桃舒春锦芳。
帝力终何有，机心庶此忘。','',''),('quantangshi-03847','咏石','蘇味道','quantangshi','','卷4','济北甄神贶，河西濯锦文。
声应天池雨，影触岱宗云。
燕归犹可候，羊起自成羣。
何当握灵髓，高枕绝嚣氛。','',''),('quantangshi-03848','奉和受图温洛应制','蘇味道','quantangshi','','卷4','绿绮膺河检，清坛俯洛滨。
天旋俄制跸，孝享属严禋。
陟配光三祖，怀柔洎百神。
雾开中道日，雪歛属车尘。
预奉咸英奏，长歌亿万春。','',''),('quantangshi-03849','使岭南闻崔马二御史竝拜台郎','蘇味道','quantangshi','','卷4','振鹭齐飞日，迁莺远听闻。
明光共待漏，清鉴各披云。
喜得廊庙举，嗟为台阁分。
故林怀柏悦，新幄阻兰薰。
冠去神羊影，车迎瑞雉羣。
远从南斗外，遥仰列星文。','',''),('quantangshi-03850','赠封御史入台','蘇味道','quantangshi','','卷4','故事推三独，兹辰对两闱。
夕鸦共鸣舞，屈草接芳菲。
盛府持清橐，殊章动绣衣。
风连台阁起，霜就简书飞。
凛凛当朝色，行行满路威。
惟当击隼去，复覩落雕归。','',''),('quantangshi-03851','始背洛城秋郊瞩目奉怀台中诸侍御','蘇味道','quantangshi','','卷4','薄游忝霜署，直指戒冰心。
荔浦方南纪，蘅臯暂北临。
山晴关塞断，川暮广城阴。
场圃通圭甸，沟塍碍石林。
野童来捃拾，田叟去讴吟。
蟋蟀秋风起，蒹葭晚露深。
帝城犹郁郁，征传几骎骎。
回忆披书地，劳歌谢所钦。','',''),('quantangshi-03852','九江口南济北接蕲春南与浔阳岸','蘇味道','quantangshi','','卷4','江路一悠哉，滔滔九派来。
远潭昏似雾，前浦沸成雷。
鳞介多潜育，渔商几溯洄。
风摇蜀柹下，日照楚萍开。
近漱湓城曲，斜吹蠡泽隈。
锡龟犹入贡，浮兽罢为灾。
津吏挥桡疾，邮童整传催。
归心讵可问，为视落潮回。','',''),('quantangshi-03853','和武三思于天中寺寻复礼上人之作','蘇味道','quantangshi','','卷4','藩戚三雍暇，禅居二室隈。
忽闻从桂苑，移步践花台。
敏学推多艺，高谈属辩才。
是非宁滞着，空有掠嫌猜。
五行幽机畅，三蕃妙键开。
味同甘露洒，香似逆风来。
砌古留方石，池清辨烧灰。
人寻鹤洲返，月逐虎溪回。
企躅瞻飞盖，攀游想渡杯。
愿陪为善乐，从此去尘埃。','',''),('quantangshi-03854','嵩山石淙侍宴应制','蘇味道','quantangshi','','卷4','雕舆藻衞拥千官，仙洞灵溪访九丹。
隐暧源花迷近路，参差岭竹扫危坛。
重崖对耸霞文驳，瀑水交飞雨气寒。
天洛宸襟有余兴，裴回周矖驻归銮。','',''),('quantangshi-03855','古劒篇','郭震','quantangshi','','卷4','君不见昆吾铁冶飞炎烟，红光紫气俱赫然。
良工锻炼凡几年，铸得宝劒名龙泉。
龙泉颜色如霜雪，良工咨嗟叹奇绝。
琉璃玉匣吐莲花，错镂金环映明月。
正逢天下无风尘，幸得周防君子身。
精光黯黯青蛇色，文章片片绿龟鳞。
非直结交游侠子，亦曾亲近英雄人。
何言中路遭弃捐，零落漂沦古狱边。
虽复尘埋无所用，犹能夜夜气冲天。','',''),('quantangshi-03856','塞上','郭震','quantangshi','','卷4','塞外虏尘飞，频年出武威。
死生随玉劒，辛苦向金微。
久戍人将老，长征马不肥。
仍闻酒泉郡，已合数重围。','',''),('quantangshi-03857','寄刘校书','郭震','quantangshi','','卷4','俗吏三年何足论，每将荣辱在朝昏。
才微易向风尘老，身贱难酬知己恩。
御苑残莺啼落日，黄山细雨湿归轩。
回首汉家丞相府，昨来谁得扫重门。','',''),('quantangshi-03858','同徐员外除太子舍人寓直之作','郭震','quantangshi','','卷4','太子擅元良，宫臣命伟长。
除荣辞会府，直宿总书坊。
露湿幽岩桂，风吹便坐桑。
阁连云一色，池带月重光。
叶死兰无气，荷枯水不香。
遥闻秋兴作，言是晋中郎。','',''),('quantangshi-03859','春江曲','郭震','quantangshi','','卷4','江水春沈沈，上有双竹林。
竹叶坏水色，郎亦坏人心。','',''),('quantangshi-03860','王昭君三首 一','郭震','quantangshi','','卷4','自嫁单于国，长衔汉掖悲。
容颜日憔悴，有甚画图时。','',''),('quantangshi-03861','王昭君三首 二','郭震','quantangshi','','卷4','厌践冰霜域，嗟为边塞人。
思从漠南猎，一见汉家尘。','',''),('quantangshi-03862','王昭君三首 三','郭震','quantangshi','','卷4','闻有南河信，传言杀画师。
始知君念重，更肯惜蛾眉。','',''),('quantangshi-03863','子夜四时歌六首 春歌 一','郭震','quantangshi','','卷4','陌头杨柳枝，已被春风吹。
妾心正断绝，君怀那得知。','',''),('quantangshi-03864','子夜四时歌六首 春歌 二','郭震','quantangshi','','卷4','青楼含日光，绿池起风色。
赠子同心花，殷勤此何极。','',''),('quantangshi-03865','子夜四时歌六首 秋歌 一','郭震','quantangshi','','卷4','邀欢空伫立，望美频回顾。
何时复采菱，江中密相遇。','',''),('quantangshi-03866','子夜四时歌六首 秋歌 二','郭震','quantangshi','','卷4','辟恶茱萸囊，延年菊花酒。
与子结绸缪，丹心此何有。','',''),('quantangshi-03867','子夜四时歌六首 冬歌 一','郭震','quantangshi','','卷4','北极严气升，南至温风谢。
调丝竞短歌，拂枕怜长夜。','',''),('quantangshi-03868','子夜四时歌六首 冬歌 二','郭震','quantangshi','','卷4','帷横双翡翠，被卷两鸳鸯。
婉态不自得，宛转君王牀。','',''),('quantangshi-03869','二月乐游诗','郭震','quantangshi','','卷4','二月芳游始，开轩望晓池。
绿兰日吐叶，红蘂向盈枝。
柳色行将改，君心幸莫移。
阳春遽多意，唯愿两人知。','',''),('quantangshi-03870','十月乐游诗','郭震','quantangshi','','卷4','十月严阴盛，霜气下玉台。
罗衣羞自解，绮帐待君开。
银箭更筹缓，金炉香气来。
愁仍夜未几，已使炭成灰。','',''),('quantangshi-03871','萤','郭震','quantangshi','','卷4','秋风凛凛月依依，飞过高梧影里时。
暗处若教同众类，世间争得有人知。','',''),('quantangshi-03872','蛩','郭震','quantangshi','','卷4','愁杀离家未达人，一声声到枕前闻。
苦吟莫向朱门里，满耳笙歌不听君。','',''),('quantangshi-03873','云','郭震','quantangshi','','卷4','聚散虚空去复还，野人闲处倚筇看。
不知身是无根物，蔽月遮星作万端。','',''),('quantangshi-03874','野井','郭震','quantangshi','','卷4','纵无汲引味清澄，冷浸寒空月一轮。
凿处若教当要路，为君常济往来人。','',''),('quantangshi-03875','米囊花','郭震','quantangshi','','卷4','开花空道胜于草，结实何曾济得民。
却笑野田禾与黍，不闻弦管过青春。','',''),('quantangshi-03876','惜花','郭震','quantangshi','','卷4','艳拂衣襟蘂拂杯，遶枝闲共蝶徘徊。
春风满目还惆怅，半欲离披半未开。','',''),('quantangshi-03877','莲花','郭震','quantangshi','','卷4','脸腻香薰似有情，世间何物比轻盈。
湘妃雨后来池看，碧玉盘中弄水晶。','',''),('quantangshi-03878','弘农清岩曲有磐石可坐宋十一每拂拭待余寄诗赠之','田遊巖','quantangshi','','卷4','信彼称灵石，居然狎遁栖。
裴回承翠巘，斌驳带深溪。
夕阴起层岫，清景半虹霓。
风来应啸阮，波动可琴嵇。
仆也颍阳客，望彼空思齐。
傥见山人至，簪嵩且杖藜。','',''),('quantangshi-03879','和宋之问下山歌','王無競','quantangshi','','卷4','日云暮兮下嵩山，路连绵兮树石间。
出谷口兮见明月，心裴回兮不能还。','',''),('quantangshi-03880','北使长城','王無競','quantangshi','','卷4','秦世筑长城，长城无极已。
暴兵四十万，兴工九千里。
死人如乱麻，白骨相撑委。
殚弊未云悟，穷毒岂知止。
胡尘未北灭，楚兵遽东起。
六国复嚣嚣，两龙鬬觺觺。
卯金竟握谶，反璧俄沦祀。
仁义寝邦国，狙暴行终始。
一旦咸阳宫，翻为汉朝市。','',''),('quantangshi-03881','凤台曲','王無競','quantangshi','','卷4','凤台何逶迤，嬴女管参差。
一旦彩云至，身去无还期。
遗曲此台上，世人多学吹。
一吹一落泪，至今怜玉姿。','',''),('quantangshi-03882','铜雀台','王無競','quantangshi','','卷4','北登铜雀上，西望青松郭。
繐帐空苍苍，陵田纷漠漠。
平生事已变，歌吹宛犹昨。
长袖拂玉尘，遗情结罗幕。
妾怨在朝露，君恩岂中薄。
高台奏曲终，曲终泪横落。','',''),('quantangshi-03883','巫山','王無競','quantangshi','','卷4','神女向高唐，巫山下夕阳。
裴回行作雨，婉娈逐荆王。
电影江前落，雷声峡外长。
朝云无处所，台馆晓苍苍。','',''),('quantangshi-03884','和宋之问下山歌','賈曾','quantangshi','','卷4','良游晼晚兮月呈光，锦路逶迤兮山路长。
王孙不留兮岁将晏，嵩岩仙草兮为谁芳。','',''),('quantangshi-03885','孝和皇帝挽歌','賈曾','quantangshi','','卷4','新命千龄启，鸿图累圣余。
天行应潜跃，帝出受图书。
礼若传尧旧，功疑复夏初。
梦游长不返，何国是华胥。','',''),('quantangshi-03886','奉和春日出苑瞩目应令','賈曾','quantangshi','','卷4','铜龙晓辟问安回，金辂春游博望开。
渭北晴光摇草树，终南佳气入楼台。
招贤已得商山老，托乘还征邺下才。
臣在东周独留滞，忻逢睿藻日边来。','',''),('quantangshi-03887','有所思','賈曾','quantangshi','','卷4','洛阳城东桃李花，飞来飞去落谁家。
幽闺女儿爱颜色，坐见落花长叹息。
今岁花开君不待，明年花开复谁在。
故人不共洛阳东，今来空对落花风。
年年岁岁花相似，岁岁年年人不同。','',''),('quantangshi-03888','祭汾阴乐章','賈曾','quantangshi','','卷4','蠲我渐饎，洁我膋芗。
有豆孔硕，为羞既臧。
至城无昧，精意惟芳。
神其醉止，欣欣乐康。','',''),('quantangshi-03889','使至汴州喜逢宋之问','李夔','quantangshi','','卷4','阮籍蓬池上，孤韵竹林才。
巨源从吏道，正拥使车来。
相逢且交臂，相命且衔杯。
醉后长歌毕，余声绕吹台。','',''),('quantangshi-03890','祭汾阴乐章','崔玄童','quantangshi','','卷4','聿修严配，展事禋宗。
祥符宝鼎，礼备黄琮。
祝词以信，明德惟聪。
介兹景福，永永无穷。','',''),('quantangshi-03891','祭汾阴乐章','何鸞','quantangshi','','卷4','乐奏云阕，礼章载虔。
禋宗于地，昭假于天。
惟馨荐矣，既醉歆焉。
神之降福，永永万年。','',''),('quantangshi-03892','祭汾阴乐章','蔣挺','quantangshi','','卷4','维岁之吉，维辰之良。
圣君绂冕，肃事坛场。
大礼已备，大乐斯张。
神其醉止，降福无疆。','',''),('quantangshi-03893','关山月','崔融','quantangshi','','卷4','月生西海上，气逐边风壮。
万里度关山，苍茫非一状。
汉兵开郡国，胡马窥亭障。
夜夜闻悲笳，征人起南望。','',''),('quantangshi-03894','拟古','崔融','quantangshi','','卷4','饮马临浊河，浊河深不测。
河水日东注，河源乃西极。
思君正如此，谁为生羽翼。
日夕大川阴，云霞千里色。
所思在河处，宛在机中织。
离梦当有魂，愁容定无力。
夙龄负奇志，中夜三叹息。
拔劒斩长榆，弯弓射小棘。
班张固非拟，衞霍行可即。
寄谢闺中人，努力加飱食。','',''),('quantangshi-03895','西征军行遇风','崔融','quantangshi','','卷4','北风卷尘沙，左右不相识。
飒飒吹万里，昏昏同一色。
马烦莫敢进，人急未遑食。
曹木春更悲，天景昼相匿。
夙龄慕忠义，雅尚存孤直。
览史怀浸骄，读诗叹孔棘。
及兹戎旅地，忝从书记职。
兵气腾北荒，军声振西极。
坐觉威灵远，行看氛祲息。
愚臣何以报，倚马申微力。','',''),('quantangshi-03896','塞垣行','崔融','quantangshi','','卷4','疾风卷溟海，万里扬沙砾。
仰望不见天，昏昏竟朝夕。
是时军两进，东拒复西敌。
蔽山张旗鼓，间道潜锋镝。
精骑突晓围，奇兵袭暗壁。
十月边塞寒，四山冱阴积。
雨雪雁南飞，风尘景西迫。
昔我事讨论，未尝怠经籍。
一朝弃笔砚，十年操矛戟。
岂要黄河誓，须勒燕山石。
可嗟牧羊臣，海外久为客。','',''),('quantangshi-03897','登东阳沈隐侯八咏楼','崔融','quantangshi','','卷4','旦登西北楼，楼峻石墉厚。
宛生长定□，俯压三江口。
排阶衔鸟衡，交疏过牛斗。
左右会稽镇，出入具区薮。
越岩森其前，浙江漫其后。
此地实东阳，由来山水乡。
隐侯有遗咏，落简尚余芳。
具物昔未改，斯人今已亡。
粤余忝藩左，束髪事文场。
怅不见夫子，神期遥相望。','',''),('quantangshi-03898','从军行','崔融','quantangshi','','卷4','穹庐杂种乱金方，武将神兵下玉堂。
天子旌旗过细柳，匈奴运数尽枯杨。
关头落月横西岭，塞下凝云断北荒。
漠漠边尘飞众鸟，昏昏朔气聚羣羊。
依稀蜀杖迷新竹，仿髴胡牀识故桑。
临海旧来闻骠骑，寻河本自有中郎。
坐看战壁为平土，近待军营作破羌。','',''),('quantangshi-03899','和宋之问寒食题黄梅临江驿','崔融','quantangshi','','卷4','春分自淮北，寒食渡江南。
忽见浔阳水，疑是宋家潭。
明主阍难呌，孤臣逐未堪。
遥思故园陌，桃李正酣酣。','',''),('quantangshi-03900','留别杜审言并呈洛中旧游','崔融','quantangshi','','卷4','斑鬓今为别，红颜昨共游。
年年春不待，处处酒相留。
驻马西桥上，回车南陌头。
故人从此隔，风月坐悠悠。','',''),('quantangshi-03901','咏宝劒','崔融','quantangshi','','卷4','宝劒出昆吾，龟龙夹采珠。
五精初献术，千户竞沦都。
匣气冲牛斗，山形转辘轳。
欲知天下贵，持此问风胡。','',''),('quantangshi-03902','吴中好风景','崔融','quantangshi','','卷4','洛渚问吴潮，吴门想洛桥。
夕烟杨柳岸，春水木兰桡。
城邑高楼近，星辰北斗遥。
无因生羽翼，轻举托还飙。','',''),('quantangshi-03903','则天皇后挽歌二首 一','崔融','quantangshi','','卷4','宵陈虚禁夜，夕临空山阴。
日月昏尺景，天地惨何心。
紫殿金铺涩，黄陵玉座深。
镜匳长不启，圣主泪霑巾。','',''),('quantangshi-03904','则天皇后挽歌二首 二','崔融','quantangshi','','卷4','前殿临朝罢，长陵合葬归。
山川不可望，文物尽成非。
阴月霾中道，轩星落太微。
空余天子孝，松上景云飞。','',''),('quantangshi-03905','户部尚书崔公挽歌','崔融','quantangshi','','卷4','八座图书委，三台章奏盈。
举杯常有劝，曳履忽无声。
市若荆州罢，池如薛县平。
空余济南劒，天子署高名。','',''),('quantangshi-03906','韦长史挽词','崔融','quantangshi','','卷4','日落桑榆下，寒生松柏中。
冥冥多苦雾，切切有悲风。
京兆新阡辟，扶阳甲第空。
郭门从此去，荆棘渐蒙笼。','',''),('quantangshi-03907','和梁王众传张光禄是王子晋后身','崔融','quantangshi','','卷4','闻有冲天客，披云下帝畿。
三年上宾去，千载忽来归。
昔偶浮丘伯，今同丁令威。
中郎才貌是，柱史姓名非。
祗召趋龙阙，承恩拜虎闱。
丹成金鼎献，酒至玉杯挥。
天仗分旄节，朝容间羽衣。
旧坛何处所，新庙坐光辉。
汉主存仙要，淮南爱道机。
朝朝缑氏鹤，长向洛城飞。','',''),('quantangshi-03908','哭蒋詹事俨','崔融','quantangshi','','卷4','江上有长离，从容盛羽仪。
一鸣百兽舞，一举羣鸟随。
应我圣明代，巢君阿阁垂。
钩陈侍帷扆，环衞奉旌麾。
雅量沧海纳，完才庙廊施。
养亲光孝道，事主竭忠规。
贞节既已固，殊荣良不訾。
朝游云汉省，夕宴芙蓉池。
汲黯言当直，陈平智本奇。
功成喜身退，时往惜年驰。
镇国山基毁，中天柱石颓。
将军空有颂，刺史独留碑。
芜漫藏书壁，荒凉悬劒枝。
昔余参下位，数载忝牵羁。
置榻恩逾重，迎门礼自卑。
竹林常接兴，黍谷每逢吹。
逸翰金相发，清谈玉柄挥。
不轻文举少，深叹子云疲。
遗爱犹如在，残编尚可窥。
即今流水曲，何处俗人知。','',''),('quantangshi-03909','嵩山石淙侍宴应制','崔融','quantangshi','','卷4','洞口仙岩类削成，泉香石冷昼含清。
龙旗画月中天下，凤管披云此地迎。
树作帷屏阳景翳，芝如宫阙夏凉生。
今朝出豫临悬圃，明日陪游向赤城。','',''),('quantangshi-03910','塞上寄内','崔融','quantangshi','','卷4','旅魂惊塞北，归望断河西。
春风若可寄，暂为遶兰闺。','',''),('quantangshi-03911','侍从途中口号应制','閻朝隱','quantangshi','','卷4','疵贱出山东，忠贞任土风。
因敷河朔藻，得奉洛阳宫。
一顾侍御史，再顾给事中。
常愿粉肌骨，特答造化功。','',''),('quantangshi-03912','奉和圣制夏日游石淙山','閻朝隱','quantangshi','','卷4','金台隐隐陵黄道，玉辇亭亭下绛雰。
千种冈峦千种树，一重岩壑一重云。
花落风吹红的历，藤垂日晃绿葐蒀。
五百里内贤人聚，愿陪阊阖侍天文。','',''),('quantangshi-03913','鹦鹉猫儿篇','閻朝隱','quantangshi','','卷4','霹雳引，丰隆鸣，猛兽噫气蛇吼声。
鹦鹉鸟，同资造化兮殊粹精。
鷫鸘毛，翡翠翼。
鵷雏延颈，鵾鸡弄色。
鹦鹉鸟，同禀阴阳兮异埏埴。
彼何为兮，隐隐振振。
此何为兮，绿衣翠襟。
彼何为兮，窘窘蠢蠢。
此何为兮，好貌好音。
彷彷兮徉徉，似妖姬躧步兮动罗裳。
趋趋兮跄跄，若处子回眸兮登玉堂。
爰有兽也，安其忍，觜其脇，距其胸，与之放旷浪浪兮，从从容容。
钩爪锯牙也，宵行昼伏无以当，遇之兮忘味。
抟击腾掷也，朝飞暮噪无以拒，逢之兮屏气。
由是言之，贪残薄则智慧作，贪残临之兮不复攫。
由是言之，智慧周则贪残囚，智慧犯之兮不复忧。
菲形陋质虽贱微，皇王顾遇长光辉。
离宫别馆临朝市，妙舞繁弦杂宫征。
嘉喜堂前景福内，合欢殿上明光里。
云母屏风文彩合，流苏斗帐香烟起。
承恩宴盼接宴喜，高视七头金骆驼。
平怀五尺铜狮子，国有君兮国有臣。
君为主兮臣为宾，朝有贤兮朝有德。
贤为君兮德为饰，千年万岁兮心转忆。','',''),('quantangshi-03914','三日曲水侍宴应制','閻朝隱','quantangshi','','卷4','三月重三日，千春续万春。
圣泽如东海，天文似北辰。
荷叶珠盘净，莲花宝盖新。
陛下制万国，臣作水心人。','',''),('quantangshi-03915','奉和九日幸临渭亭登高应制得筵字','閻朝隱','quantangshi','','卷4','九九侍神仙，高高坐半天。
文章二曜动，气色五星连。
簪绂趋皇极，笙歌接御筵。
愿因茱菊酒，相守百千年。','',''),('quantangshi-03916','奉和送金城公主适西蕃应制','閻朝隱','quantangshi','','卷4','甥舅重亲地，君臣厚义乡。
还将贵公主，嫁与耨檀王。
卤簿山河暗，琵琶道路长。
回瞻父母国，日出在东方。','',''),('quantangshi-03917','奉和立春游苑迎春应制','閻朝隱','quantangshi','','卷4','管龠周移寰极里，乘舆望幸斗城闉。
草根未结青丝缕，萝茑犹垂绿帔巾。
鹊入巢中言改岁，燕衔书上道宜新。
愿得长绳系取日，光临天子万年春。','',''),('quantangshi-03918','奉和圣制春日幸望春宫应制','閻朝隱','quantangshi','','卷4','句芒人面乘两龙，道是春神衞九重。
彩胜年年逢七日，酴醿岁岁满千钟。
宫梅间雪祥光遍，城柳含烟淑气浓。
醉倒君前情未尽，愿因歌舞自为容。','',''),('quantangshi-03919','夜宴安乐公主新宅','閻朝隱','quantangshi','','卷4','凤皇鸣舞乐昌年，蜡炬开花夜管弦。
半醉徐击珊瑚树，已闻钟漏晓声传。','',''),('quantangshi-03920','饯唐永昌','閻朝隱','quantangshi','','卷4','洛阳难理若棼丝，椎破连环定不疑。
鹦鹉休言秦地乐，回头一顾一相思。','',''),('quantangshi-03921','明月歌','閻朝隱','quantangshi','','卷4','梅花雪白柳叶黄，云雾四起月苍苍，箭水泠泠刻漏长。
挥玉指，拂罗裳，为君一奏楚明光。','',''),('quantangshi-03922','采莲女','閻朝隱','quantangshi','','卷4','采莲女，采莲舟，春日春江碧水流。
莲衣承玉钏，莲刺罥银钩。
薄暮敛容歌一曲，氛氲香气满汀洲。','',''),('quantangshi-03923','奉和登骊山应制','閻朝隱','quantangshi','','卷4','龙行踏绛气，天半语相闻。
混沌疑初判，洪荒若始分。','',''),('quantangshi-03924','奉和九日幸临渭亭登高应制得月字','韋元旦','quantangshi','','卷4','云物开千里，天行乘九月。
丝言丹凤池，斾转苍龙阙。
灞水欢娱地，秦京游侠窟。
欣承解愠词，圣酒黄花发。','',''),('quantangshi-03925','奉和送金城公主适西蕃应制','韋元旦','quantangshi','','卷4','柔远安夷俗，和亲重汉年。
军容旌节送，国命锦车传。
琴曲悲千里，箫声恋九天。
唯应西海月，来就掌珠圆。','',''),('quantangshi-03926','饯唐州高使君赴任','韋元旦','quantangshi','','卷4','桐栢膺新命，芝兰惜旧游。
鸣臯夜鹤在，迁木早莺求。
传拥淮源路，尊空灞水流。
落花纷送远，春色引离忧。','',''),('quantangshi-03927','早朝','韋元旦','quantangshi','','卷4','震维芳月季，宸极众星尊。
佩玉朝三陛，鸣珂度九门。
挈壶分早漏，伏槛耀初暾。
北倚苍龙阙，西临紫凤垣。
词庭草欲奏，温室树无言。
鳞翰空为忝，长怀圣主恩。','',''),('quantangshi-03928','奉和立春游苑迎春应制','韋元旦','quantangshi','','卷4','灞涘长安恒近日，殷正腊月早迎新。
池鱼戏叶仍含冻，宫女裁花已作春。
向苑云疑承翠幄，入林风若起青苹。
年年斗柄东无限，愿挹琼觞寿北辰。','',''),('quantangshi-03929','奉和圣制春日幸望春宫应制','韋元旦','quantangshi','','卷4','九重楼阁半山霞，四望韶阳春未赊。
侍跸妍歌临灞涘，留觞艳舞出京华。
危竿竞捧中街日，戏马争衔上苑花。
景色欢娱长若此，承恩不醉不还家。','',''),('quantangshi-03930','奉和人日宴大明宫恩赐彩缕人胜应制','韋元旦','quantangshi','','卷4','鸾凤旌旗拂晓陈，鱼龙角抵大明辰。
青韶既肇人为日，绮胜初成日作人。
圣藻凌云裁栢赋，仙歌促宴摘梅春。
垂旒一庆宜年酒，朝野俱欢荐寿新。','',''),('quantangshi-03931','奉和幸安乐公主山庄应制','韋元旦','quantangshi','','卷4','银河南渚帝城隅，帝辇平明出九衢。
刻凤蟠螭凌桂邸，穿池叠石写蓬壶。
琼箫暂下钧天乐，绮缀长悬明月珠。
仙牓承恩争既醉，方知朝野更欢娱。','',''),('quantangshi-03932','兴庆池侍宴应制','韋元旦','quantangshi','','卷4','沧池漭沆帝城边，殊胜昆明凿汉年。
夹岸旌旗疏辇道，中流箫鼓振楼船。
云峰四起迎宸幄，水树千重入御筵。
宴乐已深鱼藻咏，承恩更欲奏甘泉。','',''),('quantangshi-03933','夜宴安乐公主宅','韋元旦','quantangshi','','卷4','主第新成银作牓，宾筵广宴玉为楼。
壶觞既卜仙人夜，歌舞宜停织女秋。','',''),('quantangshi-03934','奉和初春幸太平公主南庄应制','邵昇','quantangshi','','卷4','沁园佳丽夺蓬瀛，翠壁红泉绕上京。
二圣忽从鸾殿幸，双仙正下凤楼迎。
花含步辇空间出，树杂帷宫画里行。
无路乘槎窥汉渚，徒知访卜就君平。','',''),('quantangshi-03935','奉和送金城公主适西蕃应制','遠悊','quantangshi','','卷4','皇恩睠下人，割爱远和亲。
少女风游兑，姮娥月去秦。
龙笛迎金榜，骊歌送锦轮。
那堪桃李色，移向虏庭春。','',''),('quantangshi-03936','汾阴后土祠作','李適','quantangshi','','卷4','昔予读旧史，遍覩汉世君。
武皇实稽古，建兹百代勋。
号令垂懋典，旧经备阙文。
西巡历九嶷，舳舻被江滨。
勒兵十八万，旌旗何纷纷。
朅来茂陵下，英声不复闻。
我行岁方晏，极望山河分。
神光终冥漠，鼎气独氛氲。
揽涕步脽上，登高见彼汾。
雄图今安在，飞飞有白云。','',''),('quantangshi-03937','答宋十一崖口五渡见赠','李適','quantangshi','','卷4','闻君访远山，跻险造幽绝。
眇然青云境，观奇弥年月。
登岭亦溯溪，孤舟事沿越。
崿嶂传彩翠，崖磴互欹缺。
石林上攒藂，金涧下明灭。
扪壁窥丹井，梯苔瞰乳穴。
忽枉岩中赠，对翫未尝辍。
殷勤独往事，委曲炼药说。
邀余名山期，从尔泛海澨。
岁晏秉宿心，斯言非徒设。','',''),('quantangshi-03938','饯许州宋司马赴任','李適','quantangshi','','卷4','昔吾游箕山，朅来涉颍水。
复有许由庙，迢迢白云里。
闻君佐繁昌，临风怅怀此。
傥到平舆泉，寄谢干将里。','',''),('quantangshi-03939','奉和圣制九日侍宴应制得高字','李適','quantangshi','','卷4','禁苑秋光入，宸游霁色高。
萸房颁彩笥，菊蘂荐香醪。
后骑萦堤柳，前旌拂御桃。
王枚俱得从，浅浅愧飞毫。','',''),('quantangshi-03940','游禁苑幸临渭亭遇雪应制','李適','quantangshi','','卷4','长乐喜春归，披香瑞雪霏。
花从银合度，絮绕玉窗飞。
写曜衔天藻，呈祥拂御衣。
上林纷可望，无处不光辉。','',''),('quantangshi-03941','奉和九日登慈恩寺浮图应制','李適','quantangshi','','卷4','凤辇乘朝霁，鹦林对晚秋。
天文贝叶写，圣泽菊花浮。
塔似神功造，龛疑佛影留。
幸陪清汉跸，欣奉净居游。','',''),('quantangshi-03942','侍宴长宁公主东庄应制','李適','quantangshi','','卷4','凤楼纡睿幸，龙舸畅宸襟。
歌舞平阳第，园亭沁水林。
山花添圣酒，涧竹绕熏琴。
愿奉瑶池驾，千春侍德音。','',''),('quantangshi-03943','奉和送金城公主适西蕃应制','李適','quantangshi','','卷4','绛河从远聘，青海赴和亲。
月作临边晓，花为度陇春。
主歌悲顾鹤，帝策重安人。
独有琼箫去，悠悠思锦轮。','',''),('quantangshi-03944','安乐公主移入新宅','李適','quantangshi','','卷4','星桥他日创，仙榜此时开。
马向铺钱埒，箫闻奏玉台。
人疑衞叔美，客似长卿才。
借问游天使，谁能取石回。','',''),('quantangshi-03945','奉和幸望春宫送朔方军大总管张仁亶','李適','quantangshi','','卷4','地限骄南牧，天临饯北征。
解衣延宠命，横劒总威名。
豹略恭宸旨，雄文动睿情。
坐观膜拜入，朝夕受降城。','',''),('quantangshi-03946','人日宴大明宫恩赐彩缕人胜应制','李適','quantangshi','','卷4','朱城待凤韶年至，碧殿疏龙淑气来。
宝帐金屏人已帖，图花学鸟胜初裁。
林香近接宜春苑，山翠遥添献寿杯。
向夕凭高风景丽，天文垂耀象昭回。','',''),('quantangshi-03947','奉和春日幸望春宫应制','李適','quantangshi','','卷4','玉辇金舆天上来，花园四望锦屏开。
轻丝半拂朱门柳，细缬全披画阁梅。
舞蝶飞行飘御席，[歌莺]度曲绕仙杯。
圣词今日光辉满，汉主秋风莫道才。','',''),('quantangshi-03948','奉和立春游苑迎春','李適','quantangshi','','卷4','金舆翠辇迎嘉节，御苑仙宫待献春。
淑气初衔梅色浅，条风半拂柳墙新。
天杯庆寿齐南岳，圣藻光辉动北辰。
稍觉披香歌吹近，龙骖日暮下城闉。','',''),('quantangshi-03949','帝幸兴庆池戏竞渡应制','李適','quantangshi','','卷4','拂露金舆丹斾转，凌晨黼帐碧池开。
南山倒影从云落，北涧摇光写溜回。
急桨争标排荇度，轻帆截浦触荷来。
横汾宴镐欢无极，歌舞年年圣寿杯。','',''),('quantangshi-03950','侍宴安乐公主庄应制','李適','quantangshi','','卷4','平阳金牓凤皇楼，沁水银河鹦鹉洲。
彩仗遥临丹壑里，仙舆暂幸绿亭幽。
前池锦石莲花艳，后岭香炉桂蘂秋。
贵主称觞万年寿，还轻汉武济汾游。','',''),('quantangshi-03951','侍宴安乐公主新宅应制','李適','quantangshi','','卷4','银河半倚凤皇台，玉酒相传鹦鹉杯。
若见君平须借问，仙槎一去几时来。','',''),('quantangshi-03952','饯唐永昌赴任东都','李適','quantangshi','','卷4','闻道飞凫向洛阳，翩翩矫翮度文昌。
因声寄意三花树，少室岩前几过香。','',''),('quantangshi-03953','奉和圣制立春日侍宴内殿出剪彩花应制','劉憲','quantangshi','','卷4','上林宫馆好，春光独早知。
剪花疑始发，刻燕似新窥。
色浓轻雪点，香浅嫩风吹。
此日叨陪侍，恩荣得数枝。','',''),('quantangshi-03954','奉和人日清晖阁宴羣臣遇雪应制','劉憲','quantangshi','','卷4','舆辇乘人日，登临上凤京。
风寻歌曲扬，雪向舞行萦。
千官随兴合，万福与时并。
承恩长若此，微贱幸升平。','',''),('quantangshi-03955','奉和七夕宴两仪殿应制','劉憲','quantangshi','','卷4','秋吹过双阙，星仙动二灵。
更深移月镜，河浅度云軿。
殿上呼方朔，人间失武丁。
天文兹夜里，光映紫微庭。','',''),('quantangshi-03956','奉和九月九日圣制登慈恩寺浮图应制','劉憲','quantangshi','','卷4','飞塔云霄半，清晨羽斾游。
登临凭季月，寥廓见中州。
御酒新寒退，天文瑞景留。
辟邪将献寿，兹日奉千秋。','',''),('quantangshi-03957','闰九月九日幸总持寺登浮图应制','劉憲','quantangshi','','卷4','重阳登闰序，上界叶时巡。
驻辇天花落，开筵妓乐陈。
城端刹柱见，云表露盘新。
临睨光辉满，飞文动睿神。','',''),('quantangshi-03958','侍宴长宁公主东庄','劉憲','quantangshi','','卷4','公主林亭地，清晨降玉舆。
画桥飞渡水，仙阁涌临虚。
晴新看蛱蝶，夏早摘芙蕖。
文酒娱游盛，忻叨侍从余。','',''),('quantangshi-03959','奉和送金城公主入西蕃应制','劉憲','quantangshi','','卷4','外馆逾河右，行营指路岐。
和亲悲远嫁，忍爱泣将离。
旌斾羗风引，轩车汉月随。
那堪马上曲，时向管中吹。','',''),('quantangshi-03960','奉和圣制登骊山高顶寓目应制','劉憲','quantangshi','','卷4','骊阜镇皇都，銮游眺八区。
原隰旌门里，风云扆座隅。
直城如斗柄，官树似星榆。
从臣词赋末，滥得上天衢。','',''),('quantangshi-03961','奉和幸白鹿观应制','劉憲','quantangshi','','卷4','玄游乘落晖，仙宇蔼霏微。
石梁萦涧转，珠斾扫坛飞。
芝童荐膏液，松鹤舞骖騑。
还似瑶池上，歌成周驭归。','',''),('quantangshi-03962','折杨柳','劉憲','quantangshi','','卷4','沙塞三河道，金闺二月春。
碧烟杨柳色，红粉绮罗人。
露叶怜啼脸，风花思舞巾。
攀持君不见，为听曲中新。','',''),('quantangshi-03963','奉和立春日内出彩花树应制','劉憲','quantangshi','','卷4','禁苑韶年此日归，东郊道上转青旗。
柳色梅芳何处所，风前雪里觅芳菲。
开冰池内鱼新跃，剪彩花间燕始飞。
欲识王游布阳气，为观天藻竞春晖。','',''),('quantangshi-03964','奉和春日幸望春宫应制','劉憲','quantangshi','','卷4','暮春春色最便妍，苑里花开列御筵。
商山积翠临城起，浐水浮光共幕连。
莺藏嫩叶歌相唤，蝶碍芳丛舞不前。
欢娱节物今如此，愿奉宸游亿万年。','',''),('quantangshi-03965','奉和幸安乐公主山庄应制','劉憲','quantangshi','','卷4','主家别墅帝城隈，无劳海上觅蓬莱。
沓石悬流平地起，危楼曲阁半天开。
庭莎作荐舞行出，浦树相将歌棹回。
此日风光与形胜，只言作伴圣词来。','',''),('quantangshi-03966','兴庆池侍宴应制','劉憲','quantangshi','','卷4','苍龙阙下天泉池，轩驾来游箫管吹。
缘堤夏筱萦不散，冐水新荷卷复披。
帐殿疑从画里出，楼船直在镜中移。
自然东海神仙处，何用西昆辙迹疲。','',''),('quantangshi-03967','奉和幸大荐福寺应制','劉憲','quantangshi','','卷4','地灵传景福，天驾俨钩陈。
佳哉藩邸旧，赫矣梵宫新。
香塔鱼山下，禅堂雁水滨。
珠幡映白日，镜殿写青春。
甚欢延故吏，大觉拯生人。
幸承歌颂末，长奉属车尘。','',''),('quantangshi-03968','奉和幸三会寺应制','劉憲','quantangshi','','卷4','岧嶤仓史台，敞朗绀园开。
戒旦壶人集，翻霜羽骑来。
下辇登三袭，褰旒望九垓。
林披舘陶牓，水浸昆明灰。
网户飞花缀，幡竿度鸟回。
豫游仙唱动，潇洒出尘埃。','',''),('quantangshi-03969','奉和幸长安故城未央宫应制','劉憲','quantangshi','','卷4','汉宫千祀外，轩驾一来游。
夷荡长如此，威灵不复留。
凭高睿赏发，怀古圣情周。
寒向南山歛，春过北渭浮。
土功昔云盛，人英今所求。
幸听熏风曲，方知霸道羞。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-03970','奉和幸礼部尚书窦希玠宅应制','劉憲','quantangshi','','卷4','北斗枢机任，西京肺腑亲。
畴昔王门下，今兹御幸辰。
恩光山水被，圣作管弦新。
遶坐熏红药，当轩暗绿筠。
摘荷才早夏，听鸟尚余春。
行漏今徒晚，风烟起观津。','',''),('quantangshi-03971','奉和圣制幸望春宫送朔方大总管张仁亶','劉憲','quantangshi','','卷4','命将择耆年，图功胜必全。
光辉万乘饯，威武二庭宣。
中衢横鼓角，旷野蔽旌旃。
推食天厨至，投醪御酒传。
凉风过雁苑，杀气下鸡田。
分阃恩何极，临岐动睿篇。','',''),('quantangshi-03972','奉和幸韦嗣立山庄侍宴应制','劉憲','quantangshi','','卷4','东山有谢安，枉道降鸣銮。
缇骑分初日，霓旌度晓寒。
云跸岩间下，虹桥涧底盘。
幽栖俄以届，圣瞩宛余欢。
崖悬飞溜直，岸转绿潭宽。
桂华尧酒泛，松响舜琴弹。
明主恩斯极，贤臣节更殚。
不才叨侍从，咏德以濡翰。','',''),('quantangshi-03973','人日翫雪应制','劉憲','quantangshi','','卷4','胜日登临云叶起，芳风摇荡雪花飞。
呈晖幸得承金镜，扬彩还将奉玉衣。','',''),('quantangshi-03974','上巳日祓禊渭滨应制','劉憲','quantangshi','','卷4','桃花欲落柳条长，沙头水上足风光。
此时御跸来游处，愿奉年年祓禊觞。','',''),('quantangshi-03975','苑中遇雪应制','劉憲','quantangshi','','卷4','龙骖晓入望春宫，正逢春雪舞东风。
花光倂洒天文上，寒气行消御酒中。','',''),('quantangshi-03976','夜宴安乐公主新宅','劉憲','quantangshi','','卷4','层轩洞户旦新披，度曲飞觞夜不疲。
绮缀玲珑河色晓，珠帘隐映月华窥。','',''),('quantangshi-03977','奉和圣制幸韦嗣立山庄','劉憲','quantangshi','','卷4','非吏非隐晋尚书，一丘一壑降乘舆。
天藻缘情两曜合，山巵献寿万年余。','',''),('quantangshi-03978','饯唐永昌','劉憲','quantangshi','','卷4','始见郎官拜洛阳，旋闻近侍发雕章。
绪言已勖期年政，绮字当生满路光。','',''),('quantangshi-03979','晦日置酒林亭','高正臣','quantangshi','','卷4','正月符嘉节，三春翫物华。
忘怀寄尊酒，陶性狎山家。
柳翠含烟叶，梅芳带雪花。
光阴不相借，迟迟落景斜。','',''),('quantangshi-03980','晦日重宴','高正臣','quantangshi','','卷4','芳辰重游衍，乘景共追随。
班荆陪旧识，倾盖得新知。
水叶分莲沼，风花落柳枝。
自符河朔趣，宁羡高阳池。','',''),('quantangshi-03981','晦日宴高氏林亭','崔知賢','quantangshi','','卷4','上月河阳地，芳辰景物华。
緜蛮变时鸟，照曜起春霞。
柳摇风处色，梅散日前花。
淹留洛城晚，歌吹石崇家。','',''),('quantangshi-03982','上元夜效小庾体','崔知賢','quantangshi','','卷4','今夜启城闉，结伴戏芳春。
鼓声撩乱动，风光触处新。
月下多游骑，灯前饶看人。
欢乐无穷已，歌舞达明晨。','',''),('quantangshi-03983','三月三日宴王明府山亭','崔知賢','quantangshi','','卷4','京洛皇居，芳禊春余。
影媚元巳，和风上除。
云开翠帟，水鹜鲜居。
林渚萦暎，烟霞卷舒。
花飘粉蝶，藻跃文鱼。
沿波式宴，其乐只且。','',''),('quantangshi-03984','三月三日宴王明府山亭','席元明','quantangshi','','卷4','日惟上巳，时亨有巢。
中尊引桂，芳筵籍茅。
书僮橐笔，膳夫行炮。
烟霏万雉，花明四郊。
沼苹白带，山花紫苞。
同人聚饮，千载神交。','',''),('quantangshi-03985','晦日宴高氏林亭','韓仲宣','quantangshi','','卷4','欲知行有乐，芳尊对物华。
地接安仁县，园是季伦家。
柳处云疑叶，梅间雪似花。
日落归途远，留兴伴烟霞。','',''),('quantangshi-03986','晦日重宴','韓仲宣','quantangshi','','卷4','凤苑先吹晚，龙楼夕照披。
陈遵已投辖，山公正坐池。
落日催金奏，飞霞送玉巵。
此时陪绮席，不醉欲何为。','',''),('quantangshi-03987','上元夜效小庾体','韓仲宣','quantangshi','','卷4','他乡月夜人，相伴看灯轮。
光随九华出，影共百枝新。
歌钟盛北里，车马沸南邻。
今宵何处好？惟有洛城春。','',''),('quantangshi-03988','三月三日宴王明府山亭','韓仲宣','quantangshi','','卷4','河滨上巳，洛汭春华。
碧池涵日，翠斝澄霞。
沟垂细柳，岸拥平沙。
歌莺响树，舞蝶惊花。
云浮宝马，水韵香车。
熟记行乐，淹留景斜。','',''),('quantangshi-03989','晦日宴高氏林亭','周彥昭','quantangshi','','卷4','胜地临鸡浦，高会偶龙沙。
御柳惊春色，仙筇掩月华。
门邀千里驭，杯泛九光霞。
日落山亭晚，雷送七香车。','',''),('quantangshi-03990','晦日宴高氏林亭','高球','quantangshi','','卷4','温洛年光早，皇州景望华。
连镳寻上路，乘兴入山家。
轻苔网危石，春水架平沙。
赏极林塘暮，处处起烟霞。','',''),('quantangshi-03991','三月三日宴王[明]府山亭','高球','quantangshi','','卷4','洛城春禊，元巳芳年。
季伦园里，逸少亭前。
曲中举白，谈际生玄。
陆离轩盖，凄清管弦。
萍疎波荡，柳弱风牵。
未淹欢趣，林溪夕烟。','',''),('quantangshi-03992','晦日宴高氏林亭','弓嗣初','quantangshi','','卷4','上序春晖丽，中园物候华。
高才盛文雅，逸兴满烟霞。
参差金谷树，皎镜碧塘沙。
萧散林亭晚，倒载欲还家。','',''),('quantangshi-03993','晦日重宴','弓嗣初','quantangshi','','卷4','年华蔼芳隰，春溜满新池。
促赏依三友，延欢寄一巵。
鸟声随管变，花影逐风移。
行乐方无极，淹留惜晚曦。','',''),('quantangshi-03994','三月三日宴王明府山亭','高瑾','quantangshi','','卷4','暮春元巳，春服初裁。
童冠八九，于洛之隈。
河堤草变，巩树花开。
逸人谈发，仙御舟来。
间关黄鸟，瀺灂丹腮。
乐饮命席，优哉悠哉。','',''),('quantangshi-03995','晦日宴高氏林亭','高瑾','quantangshi','','卷4','试入山亭望，言是石崇家。
二月风光起，三春桃李华。
莺吟上乔木，雁往息平沙。
相看会取醉，宁知还路赊。','',''),('quantangshi-03996','晦日重宴','高瑾','quantangshi','','卷4','忽闻莺响谷，于此命相知。
正开彭泽酒，来向高阳池。
柳叶风前弱，梅花影处危。
赏洽林亭晚，落照下参差。','',''),('quantangshi-03997','上元夜效小庾体','高瑾','quantangshi','','卷4','初年三五夜，相知一两人。
连镳出巷口，飞毂下池漘。
灯光恰似月，人面倂如春。
遨游终未已，相欢待日轮。','',''),('quantangshi-03998','晦日宴高氏林亭','王茂時','quantangshi','','卷4','践胜寻良会，乘春翫物华。
还随张放友，来向石崇家。
止水分岩镜，闲庭枕浦沙。
未极林泉赏，参差落照斜。','',''),('quantangshi-03999','晦日宴高氏林亭','徐皓','quantangshi','','卷4','绮筵乘暇景，琼醑对年华。
门多金埒骑，路引璧人车。
苹早犹藏叶，梅残正落花。
蔼蔼林亭晚，余兴促流霞。','',''),('quantangshi-04000','晦日宴高氏林亭','長孫正隱','quantangshi','','卷4','晦晚属烟霞，遨游重岁华。
歌钟虽戚里，林薮是山家。
细雨犹开日，深池不涨沙。
淹留迷处所，岩岫几重花。','',''),('quantangshi-04001','上元夜效小庾体同用春字','長孫正隱','quantangshi','','卷4','薄晚啸游人，车马乱驱尘。
月光三五夜，灯焰一重春。
烟云迷北阙，箫管识南邻。
洛城终不闭，更出小平津。','',''),('quantangshi-04002','晦日宴高氏林亭','高紹','quantangshi','','卷4','啸侣入山家，临春翫物华。
葛弦调绿水，桂醑酌丹霞。
岸柳开新叶，庭梅落早花。
兴洽林亭晚，方还倒载车。','',''),('quantangshi-04003','晦日宴高氏林亭','郎餘令','quantangshi','','卷4','三春休晦节，九谷泛年华。
半晴余细雨，全晚澹残霞。
尊开疎竹叶，管应落梅花。
兴阑相顾起，流水送香车。','',''),('quantangshi-04004','晦日宴高氏林亭','陳嘉言','quantangshi','','卷5','公子申敬爱，携朋翫物华。
人是平阳客，地即石崇家。
水文生旧浦，风色满新花。
日暮连归骑，长川照晚霞。','',''),('quantangshi-04005','晦日重宴','陳嘉言','quantangshi','','卷5','高门引冠盖，下客抱支离。
绮席珍羞满，文场翰藻摛。
蓂华雕上月，柳色蔼春池。
日斜归戚里，连骑勒金羁。','',''),('quantangshi-04006','上元夜效小庾体','陳嘉言','quantangshi','','卷5','今夜可怜春，河桥多丽人。
宝马金为络，香车玉作轮。
连手窥潘掾，分头看洛神。
重城自不掩，出向小平津。','',''),('quantangshi-04007','晦日宴高氏林亭','周彥暉','quantangshi','','卷5','砌蓂收晦魄，津柳竞年华。
既狎忘筌友，方淹投辖车。
绮筵回舞雪，琼醑泛流霞。
云低上天晚，丝雨带风斜。','',''),('quantangshi-04008','晦日重宴','周彥暉','quantangshi','','卷5','春华归柳树，俯景落蓂枝。
置驿铜街右，开筵玉浦陲。
林烟含障密，竹雨带珠危。
兴阑巾倒戴，山公下习池。','',''),('quantangshi-04009','晦日宴高氏林亭','高嶠','quantangshi','','卷5','飞观写春望，开宴坐汀沙。
积溜含苔色，晴空荡日华。
歌入平阳第，舞对石崇家。
莫虑能骑马，投辖自停车。','',''),('quantangshi-04010','晦日重宴','高嶠','quantangshi','','卷5','驾言寻凤侣，乘欢俯雁池。
班荆逢旧识，斟桂喜深知。
紫兰方出径，黄莺未啭枝。
别有陶春日，青天云雾披。','',''),('quantangshi-04011','晦日宴高氏林亭','劉友賢','quantangshi','','卷5','春来日渐赊，琴酒逐年华。
欲向文通迳，先游武子家。
池碧新流满，岩红落照斜。
兴阑情未尽，步步惜风花。','',''),('quantangshi-04012','晦日宴高氏林亭','周思鈞','quantangshi','','卷5','早春惊柳穟，初晦掩蓂华。
骑出平阳里，筵开衞尉家。
竹影含云密，池纹带雨斜。
重惜林亭晚，上路满烟霞。','',''),('quantangshi-04013','晦日重宴','周思鈞','quantangshi','','卷5','绮筵乘晦景，高宴下阳池。
濯雨梅香散，含风柳色移。
轻尘依扇落，流水入弦危。
勿顾林亭晚，方欢云雾披。','',''),('quantangshi-04014','祭汾阴乐章','蘇頲','quantangshi','','卷5','礼物斯具，乐章乃陈。
谁其作主，皇考圣真。
对越在天，圣明佐神。
窅然汾上，厚泽如春。','',''),('quantangshi-04015','奉和圣制行次成皐途经先圣擒建德之所感而成诗应制','蘇頲','quantangshi','','卷5','汉东不执象，河朔方鬬龙。
夏灭渐宁乱，唐兴终奋庸。
皇威正赫赫，兵气何匈匈。
用武三川震，归淳六代醲。
成臯覩王业，天下致人雍。
即此巡于岱，曾孙受命封。','',''),('quantangshi-04016','奉和圣制登蒲州逍遥楼应制','蘇頲','quantangshi','','卷5','在昔尧舜禹，遗尘成典谟。
圣皇东巡狩，况乃经此都。
楼观纷迤逦，河山几萦纡。
缅怀祖宗业，相继文武图。
尚德既无险，观风谅有孚。
岂如汾水上，箫鼓事游娱。','',''),('quantangshi-04017','奉和圣制过晋阳宫应制','蘇頲','quantangshi','','卷5','隋运与天绝，生灵厌氛昏。
圣期在宁乱，士马兴太原。
立极万邦推，登庸四海尊。
庆膺神武帝，业付皇曾孙。
缅慕封唐道，追惟归沛魂。
诏书感先义，典礼巡旧藩。
高殿彩云合，春旗祥风翻。
率西见汾水，奔北空塞垣。
款曲童儿佐，依迟故老言。
里颁慈惠赏，家受复除恩。
下辇崇三教，建碑当九门。
孝思敦至美，亿载奉开元。','',''),('quantangshi-04018','奉和姚令公温汤旧馆永怀故人卢公之作','蘇頲','quantangshi','','卷5','树德岂孤迈，降神良竝出。
伟兹廊庙桢，调彼盐梅实。
正悦虞垂举，翻悲郑侨卒。
同心不可忘，交臂何为失。
清路荷前幸，明时称右弼。
曾联野外游，尚记帷中密。
新恸情莫遣，旧游词更述。
空令还辱和，长叹知音日。','',''),('quantangshi-04019','和杜主簿春日有所思','蘇頲','quantangshi','','卷5','朝上高楼上，俯见洛阳陌。
摇荡吹花风，落英纷已积。
美人不共此，芳好空所惜。
揽镜尘网滋，当窗苔藓碧。
缅怀在云汉，良愿暌枕席。
翻似无见时，如何久为客。','',''),('quantangshi-04020','饯郢州李使君','蘇頲','quantangshi','','卷5','楚有章华台，遥遥云梦泽。
复闻拥符传，及是收图籍。
佳政在离人，能声寄侯伯。
离怀朔风起，试望秋阴积。
中路凄以寒，羣山霭将夕。
伤心聊把袂，怊怅麒麟客。','',''),('quantangshi-04021','饯唐州高使君赴任','蘇頲','quantangshi','','卷5','永日奏文时，东风摇荡夕。
浩然思乐事，翻复饯征客。
淮水春流清，楚山暮云白。
勿言行路远，所贵专城伯。','',''),('quantangshi-04022','晓济胶川南入密界','蘇頲','quantangshi','','卷5','饮马胶川上，傍胶南趣密。
林遥飞鸟迟，云去晴山出。
落晖隐桑柘，秋原被花实。
惨然游子寒，风露将萧瑟。','',''),('quantangshi-04023','夜发三泉即事','蘇頲','quantangshi','','卷5','暗发三泉山，穷秋听骚屑。
北林夜鸣雨，南望晓成雪。
祗咏北风凉，讵知南土热。
沙溪忽沸渭，石道乍明灭。
宛若银碛横，复如瑶台结。
指程赋所恋，遇虞不遑歇。
重纩濡莫解，悬旌冻犹揭。
下奔泥栈榰，上觏云梯设。
[搏]颊羸马顿，回眸惴人跌。
憧憧往复还，心注思逾切。
冉冉年将病，力困衰怠竭。
天彭信方隅，地势诚斗绝。
忝曳尚书履，叨兼使臣节。
京坻有岁饶，亭障无边孽。
归奏丹墀左，骞能俟来哲。','',''),('quantangshi-04024','小园纳凉即事','蘇頲','quantangshi','','卷5','烦暑避蒸郁，居闲习高明。
长风自远来，层阁有余清。
散洒纳凉气，萧条遗世情。
奈何夸大隐，终日系尘缨。','',''),('quantangshi-04025','昆明池晏坐答王兵部珣三韵见示','蘇頲','quantangshi','','卷5','画舸疾如飞，遥遥泛夕晖。
石黥吹浪隐，玉女步尘归。
独有衔恩处，明珠在钓矶。','',''),('quantangshi-04026','奉和圣制春台望应制','蘇頲','quantangshi','','卷5','壮丽天之府，神明王者宅。
大君乘飞龙，登彼复怀昔。
圆阙朱光焰，横山翠微积。
河汧流作表，县聚开成陌。
即旧在皇家，维新具物华。
云连所上居恒属，日更时中望不斜。
三月沧池摇积水，万年青树缀新花。
暴嬴国此尝图霸，霸业后仁先以诈。
东破诸侯西入秦，咸阳北阪南渭津。
诗书焚爇散学士，高阁奢逾娇美人。
事往覆輈经远喻，春还按跸凭高赋。
戎观爱力深惟省，越厌陈方何足务。
清吹遥遥发帝台，宸文耿耿照天回。
伯夷位事愚臣忝，喜奏声成凤鸟来。','',''),('quantangshi-04027','长相思','蘇頲','quantangshi','','卷5','君不见天津桥下东流水，南望龙门北朝市。
杨柳青青宛地垂，桃红李白花参差。
花参差，柳堪结，此时忆君心断绝。','',''),('quantangshi-04028','蜀城哭台州乐安少府','蘇頲','quantangshi','','卷5','远游跻劒阁，长想属天台。
万里隔三载，此邦余重来。
音容旷不覩，梦寐殊悠哉。
边郡饶藉藉，晚庭正回回。
喜传上都封，因促傍吏开。
向悟海盐客，已而梁木摧。
变衣寝门外，挥涕少城隈。
却记分明得，犹持委曲猜。
师儒昔训奖，仲季时童孩。
服义题书箧，邀欢泛酒杯。
蹔令风雨散，仍迫岁时回。
其道惟正直，其人信美偲。
白头还作尉，黄绶固非才。
可叹悬蛇疾，先贻问鵩灾。
故乡闭穷壤，宿草生寒荄。
零落九原去，蹉跎四序催。
曩期冬赠橘，今哭夏成梅。
执礼谁为赗，居常不徇财。
北登嵔𡻱坂，东望姑苏台。
天路本悬绝，江波复溯洄。
念孤心易断，追往恨艰裁。
不遂卿将伯，孰云陈与雷。
吾衰亦如此，夫子复何哀。','',''),('quantangshi-04029','立春日侍宴内出剪彩花应制','蘇頲','quantangshi','','卷5','晓入宜春苑，穠芳吐禁中。
剪刀因裂素，妆粉为开红。
彩异惊流雪，香饶点便风。
裁成识天意，万物与花同。','',''),('quantangshi-04030','春日芙蓉园侍宴应制','蘇頲','quantangshi','','卷5','御道红旗出，芳园翠辇游。
绕花开水殿，架竹起山楼。
荷芰轻薰幄，鱼龙出负舟。
宁知穆天子，空赋白云秋。','',''),('quantangshi-04031','奉和圣制人日清晖阁宴羣臣遇雪应制','蘇頲','quantangshi','','卷5','楼观空烟里，初年瑞雪过。
苑花齐玉树，池水作银河。
七日祥图启，千春御赏多。
轻飞传彩胜，天上奉薰歌。','',''),('quantangshi-04032','奉和七夕宴两仪殿应制','蘇頲','quantangshi','','卷5','灵媛乘秋发，仙装警夜催。
月光窥欲渡，河色辨应来。
机石天文写，针楼御赏开。
窃观栖鸟至，疑向鹊桥回。','',''),('quantangshi-04033','奉和九日幸临渭亭登高应制得时字','蘇頲','quantangshi','','卷5','嘉会宜长日，高筵顺动时。
晓光云外洗，晴色雨余滋。
降鹤因韶德，吹花入御词。
愿陪阳数节，亿万九秋期。','',''),('quantangshi-04034','游禁苑幸临渭亭遇雪应制','蘇頲','quantangshi','','卷5','平明敞帝居，霰雪下凌虚。
写月含珠缀，从风薄绮疏。
年惊花絮早，春夜管弦初。
已属云天外，欣承霈泽余。','',''),('quantangshi-04035','奉和送金城公主适西蕃应制','蘇頲','quantangshi','','卷5','帝女出天津，和戎转罽轮。
川经断肠望，地与析支邻。
奏曲风嘶马，衔悲月伴人。
旋知偃兵革，长是汉家亲。','',''),('quantangshi-04036','奉和圣制登骊山高顶寓目应制','蘇頲','quantangshi','','卷5','仙跸御层氛，高高积翠分。
岩声中谷应，天语半空闻。
丰树连黄叶，函关入紫云。
圣图恢宇县，歌赋小横汾。','',''),('quantangshi-04037','幸白鹿观应制','蘇頲','quantangshi','','卷5','碧虚清吹下，蔼蔼入仙宫。
松磴攀云绝，花源接涧空。
受符邀羽使，传诀注香童。
讵似闲居日，徒闻有顺风。','',''),('quantangshi-04038','题寿安王主簿池馆','蘇頲','quantangshi','','卷5','洛邑通驰道，韩郊在属城。
馆将花雨映，潭与竹声清。
贤俊鸾栖棘，宾游马佩衡。
愿言随狎鸟，从此濯吾缨。','',''),('quantangshi-04039','扈从温泉奉和姚令公喜雪','蘇頲','quantangshi','','卷5','清道丰人望，乘时汉主游。
恩晖随霰下，庆泽与云浮。
泉暖惊银碛，花寒爱玉楼。
鼎臣今有问，河伯且应留。','',''),('quantangshi-04040','秋社日崇让园宴得新字','蘇頲','quantangshi','','卷5','鸣爵三农稔，勾龙百代神。
运昌叨辅弼，时泰喜黎民。
树缺池光近，云开日影新。
生全应有地，长愿乐交亲。','',''),('quantangshi-04041','奉和魏仆射秋日还乡有怀之作','蘇頲','quantangshi','','卷5','南宫夙拜罢，东道昼游初。
饮饯倾冠盖，传呼问里闾。
树悲悬劒所，溪想钓璜余。
明发辉光至，增荣驷马车。','',''),('quantangshi-04042','武[担]山寺','蘇頲','quantangshi','','卷5','武[担]独苍然，坟山下玉泉。
鳖灵时共尽，龙女事同迁。
松柏衔哀处，幡花种福田。
讵知留镜石，长与法轮圆。','',''),('quantangshi-04043','饯潞州陆长史再守汾州','蘇頲','quantangshi','','卷5','河尹政成期，为汾昔所推。
不荣三入地，还美再临时。
拥传云初合，闻莺日正迟。
道傍多出饯，别有吏民思。','',''),('quantangshi-04044','饯荆州崔司马','蘇頲','quantangshi','','卷5','茂礼雕龙昔，香名展骥初。
水连南海涨，星拱北辰居。
稍发仙人履，将题别驾舆。
明年征拜入，荆玉不藏诸。','',''),('quantangshi-04045','送吏部李侍郎东归得归字','蘇頲','quantangshi','','卷5','陌上有光辉，披云向洛畿。
赏来荣扈从，别至惜分飞。
泉溜含风急，山烟带日微。
茂曹今去矣，人物喜东归。','',''),('quantangshi-04046','送光禄姚卿还都','蘇頲','quantangshi','','卷5','汉室有英台，荀家宠俊才。
九卿朝已入，三子暮同来。
不授纶为草，还司鼎用梅。
两京王者宅，驷马日应回。','',''),('quantangshi-04047','春晚送瑕丘田少府还任因寄洛中镜上人','蘇頲','quantangshi','','卷5','闻道还沂上，因声寄洛滨。
别时花欲尽，归处酒应春。
聚散同行客，悲欢属故人。
少年追乐地，遥赠一霑巾。','',''),('quantangshi-04048','送贾起居奉使入洛取图书因便拜觐','蘇頲','quantangshi','','卷5','旧国才因地，当朝史命官。
遗文征阙简，还思采芳兰。
传发关门候，觞称邑里欢。
早持京副入，旋伫洛书刊。','',''),('quantangshi-04049','送常侍舒公归觐','蘇頲','quantangshi','','卷5','朝闻讲艺余，晨省拜恩初。
训胄尊庠序，荣亲耀里闾。
朱丹华毂送，斑白绮筵舒。
江上春流满，还应荐跃鱼。','',''),('quantangshi-04050','兴州出行','蘇頲','quantangshi','','卷5','危途晓未分，驱马傍江濆。
滴滴泣花露，微微出岫云。
松梢半吐月，萝翳渐移曛。
旅客肠应断，吟猿更使闻。','',''),('quantangshi-04051','边秋薄暮','蘇頲','quantangshi','','卷5','海外秋鹰击，霜前旅雁归。
边风思鞞鼓，落日惨旌麾。
浦暗渔舟入，川长猎骑稀。
客悲逢薄暮，况乃事戎机。','',''),('quantangshi-04052','晓发方骞驿','蘇頲','quantangshi','','卷5','传置远山蹊，龙钟蹴涧泥。
片阴常作雨，微照已生霓。
鬓髪愁氛换，心情险路迷。
方知向蜀者，偏识子规啼。','',''),('quantangshi-04053','经三泉路作','蘇頲','quantangshi','','卷5','三月松作花，春行日渐赊。
竹障山鸟路，藤蔓野人家。
透石飞梁下，寻云绝磴斜。
此中谁与乐，挥涕语年华。','',''),('quantangshi-04054','故高安大长公主挽词','蘇頲','quantangshi','','卷5','彤管承师训，青圭备礼容。
孟孙家代宠，元女国朝封。
柔轨题贞顺，闲规赋肃雍。
宁知落照尽，霜吹入悲松。','',''),('quantangshi-04055','赠司徒豆卢府君挽词','蘇頲','quantangshi','','卷5','宠赠追胡广，亲临比贺循。
几闻投劒客，多会服缌人。
草闭坟将古，松阴地不春。
二陵犹可望，存殁有忠臣。','',''),('quantangshi-04056','故右散骑常侍舒国公褚公挽词','蘇頲','quantangshi','','卷5','阳翟疏丰构，临平演庆源。
学筵尊授几，儒服宠乘轩。
审谕留中密，开陈与上言。
徂晖一不借，空有赐东园。','',''),('quantangshi-04057','奉和初春幸太平公主南庄应制','蘇頲','quantangshi','','卷5','主第山门起灞川，宸游风景入初年。
凤皇楼下交天仗，乌鹊桥头敞御筵。
往往花间逢彩石，时时竹里见红泉。
今朝扈跸平阳馆，不羡乘槎云汉边。','',''),('quantangshi-04058','奉和春日幸望春宫应制','蘇頲','quantangshi','','卷5','东望望春春可怜，更逢晴日柳含烟。
宫中下见南山尽，城上平临北斗悬。
细草徧承回辇处，轻花微落奉觞前。
宸游对此欢无极，鸟哢声声入管弦。','',''),('quantangshi-04059','人日重宴大明宫恩赐彩缕人胜应制','蘇頲','quantangshi','','卷5','疏龙磴道切昭回，建凤旗门绕帝台。
七叶仙蓂依月吐，千株御柳拂烟开。
初年竞贴宜春胜，长命先浮献寿杯。
是日皇灵知窃幸，羣心就捧大明来。','',''),('quantangshi-04060','侍宴安乐公主山庄应制','蘇頲','quantangshi','','卷5','骎骎羽骑历城池，帝女楼台向晚披。
雾洒旌旗云外出，风回岩岫雨中移。
当轩半落天河水，绕径全低月树枝。
箫鼓宸游陪宴日，和鸣双凤喜来仪。','',''),('quantangshi-04061','兴庆池侍宴应制','蘇頲','quantangshi','','卷5','降鹤池前回步辇，栖鸾树杪出行宫。
山光积翠遥疑逼，水态含青近若空。
直视天河垂象外，俯窥京室画图中。
皇欢未使恩波极，日暮楼船更起风。','',''),('quantangshi-04062','广达楼下夜侍酺宴应制','蘇頲','quantangshi','','卷5','东岳封廻宴洛京，西墉通晚会公卿。
楼台绝胜宜春苑，灯火还同不夜城。
正覩人间朝市乐，忽闻天上管弦声。
酺来万舞羣臣醉，喜戴千年圣主明。','',''),('quantangshi-04063','龙池乐章','蘇頲','quantangshi','','卷5','西京凤邸跃龙泉，佳气休光镇在天。
轩后雾图今已得，秦王水劒昔常传。
恩鱼不入昆明钓，瑞鹤长如太液仙。
愿侍巡游同旧里，更闻箫鼓济楼船。','',''),('quantangshi-04064','扈从鄠杜间奉呈刑部尚书舅崔黄门马常侍','蘇頲','quantangshi','','卷5','翠辇红旗出帝京，长杨鄠杜昔知名。
云山一一看皆美，竹树萧萧画不成。
羽骑将过持袂拂，香车欲度卷帘行。
汉家曾草巡游赋，何似今来应圣明。','',''),('quantangshi-04065','景龙观送裴士曹','蘇頲','quantangshi','','卷5','昔日尝闻公主第，今时变作列仙家。
池傍坐客穿丛筱，树下游人扫落花。
雨雪长疑向函谷，山泉直似到流沙。
君还洛邑分明记，此处同来阅岁华。','',''),('quantangshi-04066','春晚紫微省直寄内','蘇頲','quantangshi','','卷5','直省清华接建章，向来无事日犹长。
花间燕子栖鳷鹊，竹下鵷雏绕凤皇。
内史通宵承紫诰，中人落晚爱红妆。
别离不惯无穷忆，莫误卿卿学太常。','',''),('quantangshi-04067','赠彭州权别驾','蘇頲','quantangshi','','卷5','双流脉脉锦城开，追饯年年往复廻。
秪道歌谣迎半刺，徒闻礼数揖中台。
黄莺急啭春风尽，斑马长嘶落景催。
莫怆分飞岐路别，还当奏最掖垣来。','',''),('quantangshi-04068','寒食宴于中舍别驾兄弟宅','蘇頲','quantangshi','','卷5','子推山上歌龙罢，定国门前结驷来。
始覩元昆锵玉至，旋闻季子佩刀廻。
晴花处处因风起，御柳条条向日开。
自有长筵欢不极，还将彩服咏南陔。','',''),('quantangshi-04069','九月九日望蜀台','蘇頲','quantangshi','','卷5','蜀王望蜀旧台前，九日分明见一川。
北料乡关方自此，南辞城郭复依然。
青松系马攒岩畔，黄菊留人籍道边。
自昔登临湮灭尽，独闻忠孝两能传。','',''),('quantangshi-04070','奉和晦日幸昆明池应制','蘇頲','quantangshi','','卷5','炎历事边陲，昆明始凿池。
豫游光后圣，征战罢前规。
霁色清珍宇，年芳入锦陂。
御杯兰荐叶，仙仗柳交枝。
二石分河泻，双珠代月移。
微臣比翔泳，恩广自无涯。','',''),('quantangshi-04071','奉和圣制幸礼部尚书窦希玠宅应制','蘇頲','quantangshi','','卷5','尚书列侯第，外戚近臣家。
飞栋临青绮，回舆转翠华。
日交当户树，泉漾满池花。
圆顶图嵩石，方流拥魏沙。
豫游今听履，侍从昔鸣笳。
自有天文降，无劳访海槎。','',''),('quantangshi-04072','奉和幸韦嗣立山庄应制','蘇頲','quantangshi','','卷5','摐金寒野霁，步玉晓山幽。
帝幄期松子，臣庐访葛侯。
百工征往梦，七圣扈来游。
斗柄乘时转，台阶捧日留。
树重岩籁合，泉迸水光浮。
石径喧朝履，璜溪拥钓舟。
恩如犯星夜，欢拟济河秋。
不学尧年隐，空令傲许由。','',''),('quantangshi-04073','奉和圣制送张说上集贤学士赐宴得兹字','蘇頲','quantangshi','','卷5','肃肃金殿里，招贤固在兹。
锵锵石渠内，序拜亦同时。
宴锡欢谈道，文成贵说诗。
用儒今作相，敦学旧为师。
下际天光近，中来帝渥滋。
国朝良史载，能事日论思。','',''),('quantangshi-04074','奉和圣制途经华岳应制','蘇頲','quantangshi','','卷5','朝望莲华岳，神心就日来。
晴观五千仞，仙掌拓山开。
受命金符叶，过祥玉瑞陪。
雾披乘鹿见，云起驭龙廻。
偃树枝封雪，残碑石冐苔。
圣皇惟道契，文字勒岩隈。','',''),('quantangshi-04075','奉和圣制经河上公庙应制','蘇頲','quantangshi','','卷5','河流无日夜，河上有神仙。
辇路曾经此，坛场即宛然。
下疑成洞穴，高若在空烟。
善物遗方外，和光绕道边。
事因周史得，言与汉王传。
喜属膺期圣，邦家业又玄。','',''),('quantangshi-04076','奉和圣制答张说出雀鼠谷','蘇頲','quantangshi','','卷5','雨施巡方罢，云从训俗廻。
密途汾水衞，清跸晋郊陪。
寒着山边尽，春当日下来。
御祠玄鸟应，仙仗绿杨开。
作颂音传雅，观文色动台。
更知西向乐，宸藻协盐梅。','',''),('quantangshi-04077','奉和恩赐乐游园宴应制','蘇頲','quantangshi','','卷5','乐游光地选，酺饮庆天从。
座密千官盛，场开百戏容。
绿塍际山尽，缇幕倚云重。
下上花齐发，周廻柳遍浓。
夺晴纷劒履，喧听杂歌钟。
日晚衔恩散，尧人倂可封。','',''),('quantangshi-04078','恩制尚书省僚宴昆明池同用尧字','蘇頲','quantangshi','','卷5','露渥洒云霄，天官次斗杓。
昆明四十里，空水极晴朝。
雁似衔红叶，鲸疑喷海潮。
翠山来彻底，白日去廻标。
泳广渔杈溢，浮深妓舫摇。
饱恩皆醉止，合舞共歌尧。','',''),('quantangshi-04079','奉和圣制幸望春宫送[朔方]大总管张仁亶','蘇頲','quantangshi','','卷5','北风吹早雁，日夕渡河飞。
气冷胶应折，霜明草正腓。
老臣帷幄筭，元宰庙堂机。
饯饮廻仙跸，临戎解御衣。
军装乘晓发，师律候春归。
方伫勋庸盛，天词降紫微。','',''),('quantangshi-04080','奉和圣制登太行山中言志应制','蘇頲','quantangshi','','卷5','北山东入海，驰道上连天。
顺动三光柱，登临万象悬。
俛观河内邑，平指洛阳川。
按跸夷关险，张旗亘井泉。
晓岩中警柝，春事下搜田。
德重周王问，歌轻汉后传。
宸游铺令典，睿思起芳年。
愿以封书奏，廻銮禅肃然。','',''),('quantangshi-04081','奉和圣制漕桥东送新除岳牧','蘇頲','quantangshi','','卷5','宝贤不遗俊，台阁尽鵷鸾。
未若调人切，其如简帝难。
上才膺出典，中旨念分官。
特以专城贵，深惟列郡安。
政行思务本，风靡属胜残。
有令田知急，无分狱在宽。
至言题睿札，殊渥洒仙翰。
诏饯三台降，朝荣万国欢。
举杯临水发，张乐拥桥观。
式伫东封会，锵锵检玉坛。','',''),('quantangshi-04082','奉和圣制途次旧居应制','蘇頲','quantangshi','','卷5','潞国临淄邸，天王别驾舆。
出潜离隐际，小往大来初。
东陆行春典，南阳即旧居。
约川星罕驻，扶道日旗舒。
云覆连行在，风廻助扫除。
木行城邑望，臯落土田疏。
昔试邦兴后，今过俗徯予。
示威宁校猎，崇让不陈鱼。
府吏趋宸扆，乡耆捧帝车。
帐倾三饮处，闲整六飞余。
盛业铭汾鼎，昌期应洛书。
愿陪歌赋末，留比蜀相如。','',''),('quantangshi-04083','奉和圣制至长春宫登楼望稼穑之作','蘇頲','quantangshi','','卷5','帝迹奚其远，皇符之所崇。
敬时尧务作，尽力禹称功。
赫赫惟元后，经营自左冯。
变芜秔稻实，流恶水泉通。
国阜犹前豹，人疲讵昔熊。
黄图巡沃野，清吹入离宫。
是阅京坻富，仍观都邑雄。
凭轩一何绮，积溜写晴空。
礼节家安外，和平俗在中。
见龙垂渭北，辞雁指河东。
睿思方居镐，宸游若饮丰。
宁夸子云从，秪为猎扶风。','',''),('quantangshi-04084','利州北佛龛前重于去岁题处作','蘇頲','quantangshi','','卷5','重岩载看美，分塔起层标。
蜀守经涂处，巴人作礼朝。
地疑三界出，空是六尘销。
卧石铺苍藓，行塍覆绿条。
岁年书有记，非为学题桥。','',''),('quantangshi-04085','闲园即事寄韦侍郎','蘇頲','quantangshi','','卷5','结庐东城下，直望江南山。
青霭远相接，白云来复还。
拂筵红藓上，开幔绿条间。
物应春偏好，情忘趣转闲。
宪臣饶美度，联事惜徂颜。
有酒空盈酌，高车不可攀。','',''),('quantangshi-04086','扈从温泉同紫微黄门羣公泛渭川得齐字','蘇頲','quantangshi','','卷5','虹旗映绿荑，春仗汉丰西。
侍跸浮清渭，扬舲降紫泥。
近临钧石地，遥指钓璜溪。
岸转帆飞疾，川平棹举齐。
傅舟来是用，轩驭往应迷。
兴阕菱歌动，沙洲乱夕鹥。','',''),('quantangshi-04087','饯赵尚书摄御史大夫赴朔方军','蘇頲','quantangshi','','卷5','劲虏欲南窥，扬兵护朔陲。
赵尧宁易印，邓禹即分麾。
野饯廻三杰，军谋用六奇。
云边愁出塞，日下怆临岐。
拔劒行人舞，挥戈战马驰。
明年麟阁上，充国画于斯。','',''),('quantangshi-04088','晓发兴州入陈平路','蘇頲','quantangshi','','卷5','旌节指巴岷，年年行且巡。
暮来青嶂宿，朝去绿江春。
鱼贯梁缘马，猿奔树息人。
邑祠犹是汉，溪道即名陈。
旧史饶迁谪，恒情厌苦辛。
宁知报恩者，天子一忠臣。','',''),('quantangshi-04089','同饯阳将军兼源州都督御史中丞','蘇頲','quantangshi','','卷5','右地接龟沙，中朝任虎牙。
然明方改俗，去病不为家。
将礼登坛盛，军容出塞华。
朔风摇汉鼓，边马思胡笳。
旗合无邀正，冠危有触邪。
当看劳还日，及此御沟花。','',''),('quantangshi-04090','扈从凤泉和崔黄门喜恩旨解严罢围之作','蘇頲','quantangshi','','卷5','辇路岐山曲，储胥渭水湄。
教成提将鼓，礼备植虞旗。
不取从畋乐，先流去杀慈。
舜韶同舞日，汤祝尽飞时。
物应阳和施，人知雨露私。
何如穆天子，七萃几劳师。','',''),('quantangshi-04091','秋夜寓直中书呈黄门舅','蘇頲','quantangshi','','卷5','帘栊上夜钩，清列听更筹。
忽共鸡枝老，还如骑省秋。
循庭喜三入，对渚忆双游。
紫绂名初拜，黄缣迹尚留。
月舒当北幌，云赋直东楼。
恩渥迷天施，童蒙慰我求。
迟君台鼎节，闻义一承流。','',''),('quantangshi-04092','先是新昌小园期京兆尹一访兼郎官数子自顷沈疴年复一年兹愿不果率然成章','蘇頲','quantangshi','','卷5','独好中林隐，先期上月春。
闲花傍户落，喧鸟逼檐驯。
寂寞东坡叟，传呼北里人。
在山琴易调，开瓮酒归醇。
伫望应三接，弥留忽几旬。
不疑丹火变，空负绿条新。
鬬蚁闻常日，歌龙值此辰。
其如众君子，嘉会阻清尘。','',''),('quantangshi-04093','奉和马常侍寺中之作','蘇頲','quantangshi','','卷5','怨暑时云谢，愆阳泽暂偏。
鼎陈从祀日，钥动问刑年。
绛服龙雩寝，玄冠马使旋。
作霖期傅说，为旱听周宣。
河岳阴符启，星辰暗檄传。
浮凉吹景气，飞动洒空烟。
飒飒将秋近，沈沈与暝连。
分湍泾水石，合颖雍州田。
德施超三五，文雄赋十千。
及斯何以乐，明主敬人天。','',''),('quantangshi-04094','慈恩寺二月半寓言','蘇頲','quantangshi','','卷5','二月韶春半，三空霁景初。
献来应有受，灭尽竟无余。
化迹传官寺，归诚谒梵居。
殿堂花覆席，观阁柳垂疏。
共命枝间鸟，长生水上鱼。
问津窥彼岸，迷路得真车。
行密幽关静，谈精俗态祛。
稻麻欣所遇，蓬箨怆焉如。
不驻秦京陌，还题蜀郡舆。
爱离方自此，廻望独踌躇。','',''),('quantangshi-04095','饯泽州卢使君赴任','蘇頲','quantangshi','','卷5','闻道降纶书，为邦建彩旟。
政凭循吏往，才以贵卿除。
词赋良无敌，声华蔼有余。
荣承四岳后，请绝五天初。
关路通秦壁，城池接晋墟。
撰期行子赋，分典列侯居。
别望喧追饯，离言系惨舒。
平芜寒蛬乱，乔木夜蝉疎。
寥泬秋先起，推移月向诸。
旧交何以赠，客至待烹鱼。','',''),('quantangshi-04096','陈仓别陇州司户李维深','蘇頲','quantangshi','','卷5','京国自携手，同途欣解颐。
情言正的的，春物宛迟迟。
忽背雕戎役，旋瞻获宝祠。
蜀城余出守，吴岳尔归思。
欢惬更伤此，眷殷殊念兹。
扬麾北林径，跂石南涧湄。
中作壶觞饯，回添道路悲。
数花临磴日，百草覆田时。
有美同人意，无为行子辞。
酣歌拔劒起，毋是答恩私。','',''),('quantangshi-04097','奉和崔尚书赠大理陆卿鸿胪刘卿见示之作','蘇頲','quantangshi','','卷5','戏藻嘉鱼乐，栖梧见凤飞。
类从皆有召，声应乃无违。
美价逢时出，奇才选众稀。
避堂贻后政，扫第发前几。
出曳仙人履，还熏侍女衣。
省中何赫奕，庭际满芳菲。
吏部端清鉴，丞郎肃紫机。
会心歌咏是，廻迹宴言非。
北寺邻玄阙，南城写翠微。
参差交隐见，仿髴接光辉。
宾序尝柔德，刑孚已霁威。
巨源林下契，不速自同归。','',''),('quantangshi-04098','敬和崔尚书大明朝堂雨后望终南山见示之作','蘇頲','quantangshi','','卷5','奕奕轻车至，清晨朝未央。
未央在霄极，中路视咸阳。
委曲汉京近，周廻秦塞长。
日华动泾渭，天翠合岐梁。
五丈旌旗色，百层枌橑光。
东连归马地，南指鬬鸡场。
晴壑照金戺，秋云含璧璫。
由余窥霸国，萧相奉兴王。
功役隐不见，颂声存复扬。
权宜珍构绝，圣作宝图昌。
在德期巢燧，居安法禹汤。
冢卿才顺美，多士赋成章。
价重三台俊，名超百郡良。
焉知掖垣下，陈力自迷方。','',''),('quantangshi-04099','夜闻故梓州韦使君明当引绋感而成章','蘇頲','quantangshi','','卷5','恻矣南邻问，冥然东岱幽。
里閈宁相杵，朝叹忽迁舟。
君心惟伯仲，吾人复款游。
对连时亦早，交喜岁才周。
序发扶阳赠，文因司寇酬。
讵期危露尽，相续逝川流。
卧疾无三吊，居闲有百忧。
振风吟鼓夕，明月照帷秋。
藓驳题诗馆，杨疎奏伎楼。
共将歌笑叹，转为弟兄留。
感物存如梦，观生去若浮。
余非忘情者，雪涕报林丘。','',''),('quantangshi-04100','御箭连中双兔','蘇頲','quantangshi','','卷5','宸游经上苑，羽猎向闲田。
狡兔初迷窟，纤骊讵着鞭。
三驱仍百步，一发遂双连。
影射含霜草，魂消向月弦。
欢声动寒木，喜气满晴天。
那似陈王意，空随乐府篇。','',''),('quantangshi-04101','奉和圣制过潼津关','蘇頲','quantangshi','','卷5','在德何夷险，观风复往还。
自能同善闭，中路可无关。','',''),('quantangshi-04102','山鹧鸪词二首 一','蘇頲','quantangshi','','卷5','玉关征戍久，空闺人独愁。
寒露湿青苔，别来蓬鬓秋。','',''),('quantangshi-04103','山鹧鸪词二首 二','蘇頲','quantangshi','','卷5','人坐青楼晚，莺语百花时。
愁多人易老，断肠君不知。','',''),('quantangshi-04104','汾上惊秋','蘇頲','quantangshi','','卷5','北风吹白云，万里渡河汾。
心绪逢摇落，秋声不可闻。','',''),('quantangshi-04105','山驿闲卧即事','蘇頲','quantangshi','','卷5','息燕归檐静，飞花落院闲。
不愁愁自着，谁道忆乡关。','',''),('quantangshi-04106','将赴益州题小园壁','蘇頲','quantangshi','','卷5','岁穷惟益老，春至却辞家。
可惜东园树，无人也作花。','',''),('quantangshi-04107','咏礼部尚书厅后鹊','蘇頲','quantangshi','','卷5','怀印喜将归，窥巢恋且依。
自知栖不定，还欲向南飞。','',''),('quantangshi-04108','咏死兔','蘇頲','quantangshi','','卷5','兔子死兰弹，持来挂竹竿。
试将明镜照，何异月中看。','',''),('quantangshi-04109','夜宴安乐公主新宅','蘇頲','quantangshi','','卷5','车如流水马如龙，仙使高台十二重。
天上初移衡汉匹，可怜歌舞夜相从。','',''),('quantangshi-04110','侍宴桃花园咏桃花应制','蘇頲','quantangshi','','卷5','桃花灼灼有光辉，无数成蹊点更飞。
为见芳林含笑待，遂同温树不言归。','',''),('quantangshi-04111','奉和圣制幸韦嗣立庄应制','蘇頲','quantangshi','','卷5','树色参差隐翠微，泉流百尺向空飞。
传闻此处投竿住，遂使兹辰扈跸归。','',''),('quantangshi-04112','重送舒公','蘇頲','quantangshi','','卷5','散骑金貂服彩衣，松花水上逐春归。
悬知邑里遥相望，事主荣亲代所稀。','',''),('quantangshi-04113','句','蘇頲','quantangshi','','卷5','飞埃结红雾，游盖飘青云。
指如十挺墨，耳似两张匙。
丑虽有足，甲不全身。
见君无口，知伊少人。','',''),('quantangshi-04114','龙池篇','姜晞','quantangshi','','卷5','灵沼萦廻邸第前，浴日涵春写曙天。
始见龙台升凤阙，应如霄汉起神泉。
石匮渚傍还启圣，桃李初生更有仙。
欲化帝图从此受，正同河变一千年。','',''),('quantangshi-04115','龙池篇','姜皎','quantangshi','','卷5','龙池初出此龙山，常经此地谒龙颜。
日日芙蓉生夏水，年年杨柳变春湾。
尧坛宝匣余烟雾，舜海渔舟尚往还。
愿似飘颻五云影，从来从去九天关。','',''),('quantangshi-04116','奉和圣制龙池篇','蔡孚','quantangshi','','卷5','帝宅王家大道边，神马潜龙涌圣泉。
昔日昔时经此地，看来看去渐成川。
歌台舞榭宜正月，柳岸梅洲胜往年。
莫疑波上春云少，祗为从龙直上天。','',''),('quantangshi-04117','打球篇','蔡孚','quantangshi','','卷5','德阳宫北苑东头，云作高台月作楼。
金锤玉蓥千金地，宝杖雕文七宝球。
窦融一家三尚主，梁翼频封万户侯。
容色由来荷恩顾，意气平生事侠游。
共道用兵如断蔗，俱能走马入长楸。
红鬣锦鬃风騄骥，黄络青丝电紫骝。
奔星乱下花场里，初月飞来画杖头。
自有长鸣须决胜，能驰迅走满先筹。
薄暮汉宫愉乐罢，还归尧室晓垂旒。','',''),('quantangshi-04118','阮公体','徐晶','quantangshi','','卷5','秦王按劒怒，发卒戍龙沙。
雄图尚未毕，海内已纷拏。
黄尘暗天起，白日敛精华。
唯见长城外，僵尸如乱麻。','',''),('quantangshi-04119','同蔡孚五亭咏','徐晶','quantangshi','','卷5','章奏中京罢，云泉别业归。
拂琴铺野席，牵柳挂朝衣。
翡翠巢书幌，鸳鸯立钓矶。
幽栖可怜处，春事满林扉。','',''),('quantangshi-04120','蔡起居山亭','徐晶','quantangshi','','卷5','文史归休日，栖闲卧草亭。
蔷薇一架紫，石竹数重青。
垂露和仙药，烧香诵道经。
莫将山水弄，持与世人听。','',''),('quantangshi-04121','送友人尉蜀中','徐晶','quantangshi','','卷5','故友汉中尉，请为西蜀吟。
人家多种橘，风土爱弹琴。
水向昆明阔，山连大夏深。
理闲无别事，时寄一登临。','',''),('quantangshi-04122','赠温驸马汝阳王','徐晶','quantangshi','','卷5','畴昔承余论，文章幸滥推。
夜陪银汉赏，朝奉桂山词。
梁邸调歌日，秦楼按舞时。
登高频作赋，体物屡为诗。
连骑长楸下，浮觞曲水湄。
北堂留上客，南陌送佳期。
忆昨陪临泛，于今阻宴私。
再看冬雪满，三见夏花滋。
都尉朝青阁，淮王侍紫墀。
宁知倦游者，华髪老京师。','',''),('quantangshi-04123','边词','張敬忠','quantangshi','','卷5','五原春色旧来迟，二月垂杨未挂丝。
即今河畔冰开日，正是长安花落时。','',''),('quantangshi-04124','戏咏','張敬忠','quantangshi','','卷5','有意嫌兵部，专心望考功。
谁知脚蹭蹬，几落省墙东。','',''),('quantangshi-04125','题巴州光福寺楠木','史俊','quantangshi','','卷5','近郭城南山寺深，亭亭奇树出禅林。
结根幽壑不知岁，耸干摩天凡几寻。
翠色晚将岚气合，月光时有夜猨吟。
经行绿叶望成盖，宴坐黄花长满襟。
此木尝闻生豫章，今朝独秀在巴乡。
凌霜不肯让松柏，作宇由来称栋梁。
会待良工时一眄，应归法水作慈航。','',''),('quantangshi-04126','仪坤庙乐章 永和','徐彥伯','quantangshi','','卷5','猗若清庙，肃肃荧荧。
国荐严祀，坤兴淑灵。
有几在室，有乐在庭。
临兹孝享，百禄惟宁。','',''),('quantangshi-04127','仪坤庙乐章 金奏','徐彥伯','quantangshi','','卷5','阴灵效祉，轩曜降精。
祥符淑气，庆集柔明。
瑶俎既列，雕桐发声。
徽猷永远，比德皇英。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-04128','拟古三首 一','徐彥伯','quantangshi','','卷5','遥裔烟屿鸿，双影旦夕同。
交翰倚沙月，和鸣弄江风。
𦶜若茂芳序，君子从远戎。
云生阴海没，花落春潭空。
红泪掩促柱，锦衾罗薰笼。
自伤琼草绿，讵惜铅粉红。
裂帛附双燕，为予向辽东。','',''),('quantangshi-04129','拟古三首 二','徐彥伯','quantangshi','','卷5','读书三十载，驰骛周六经。
儒衣干时主，忠策献阙廷。
一朝奉休盼，从容厕羣英。
束身趋建礼，秉笔坐承明。
廨署相填噎，僚吏纷纵横。
五日休澣时，屠苏绕玉屏。
橘花覆北沼，桂树交西荣。
树栖两鸳鸯，含春向我鸣。
皎洁绮罗艳，便娟丝管清。
扰扰天地间，出处各有情。
何必岩石下，枯槁闲此生。','',''),('quantangshi-04130','拟古三首 三','徐彥伯','quantangshi','','卷5','頽光无淹晷，逝水有迅流。
绿苔纷易歇，红颜不再求。
歌笑当及春，无令壮志秋。
弱年仕关辅，簃门豁御沟。
敷愉东城际，婉娈南陌头。
荷花娇绿水，杨叶暖青楼。
中有绮罗人，可怜名莫愁。
画屏绕金膝，珠帘悬玉钩。
纤指调宝琴，泠泠哀且柔。
赠君鸳鸯带，因以鷫鸘裘。
窗晓吟日坐，闺夕秉烛游。
无作北门客，咄咄怀百忧。','',''),('quantangshi-04131','赠刘舍人古意','徐彥伯','quantangshi','','卷5','女牀閟灵鸟，文章世所希。
巢君碧梧树，舞君青琐闱。
或言凤池乐，抚翼更西飞。
凤池环禁林，仙阁霭沈沈。
璇题激流日，珠缀緜清阴。
郁穆丝言重，荧煌台座深。
风张丹戺翮，月弄紫庭音。
众彩结不散，孤英跂莫寻。
浩歌在西省，经传恣潜心。','',''),('quantangshi-04132','和李适答宋十一入崖口五渡见赠','徐彥伯','quantangshi','','卷5','闻有独往客，拂衣捐世心。
结欣薄枉渚，撰念萦旧林。
经亘去崖合，冥緜归壑深。
琪树环碧彩，金潭生翠阴。
沿洄弄沙榜，诡仄眺明岑。
夕闻桂里猿，晓玩松上禽。
杂佩蕴孤袖，琼敷缀双襟。
我怀沧州想，懿尔白云吟。
秉愿理方协，存期迹易寻。
兹言庶不负，为报岩中琴。','',''),('quantangshi-04133','雪','徐彥伯','quantangshi','','卷5','雪暗穷海云，洒空纷似露。
朔风吹故里，宛转玉阶树。
孤妾调玉瑟，早寒生锦衿。
况君张罗幕，愁坐北庭阴。','',''),('quantangshi-04134','比干墓','徐彥伯','quantangshi','','卷5','大位天下宝，维贤国之镇。
殷道微而在，受辛纂颓胤。
山鸣鬼又哭，地裂川亦震。
媟黩皆佞谀，虔刘尽英隽。
孤卿帝叔父，特进贞而顺。
玉牀逾皜洁，铜柱方歊焮。
奉国历三朝，观窍明一瞬。
季代猖狂主，蓄怒提白刃。
之子弥忠谠，愤然更勇进。
抚膺誓陨越，知死故不恡。
已矣竟剖心，哲妇亦同殉。
骊龙暴双骨，太岳摧孤仞。
周发次商郊，冤骸悲莫殣。
锋劒剿遗孽，报复一何迅。
驻罕歌淑灵，命徒对旅榇。
自尔衔幽酷，于嗟流景骏。
丘坟被宿莽，坛戺缘飞磷。
贞观戒北征，维皇念忠信。
荒坟护草木，刻桷吹煨烬。
代远恩更崇，身颓名益振。
帝词书乐石，国馔罗芳衅。
伟哉烈士图，奇英千古徇。','',''),('quantangshi-04135','题东山子李适碑阴二首 一','徐彥伯','quantangshi','','卷5','陇嶂萦紫气，金光赫氛氲。
美人含遥霭，桃李芳自薰。
图高黄鹤羽，宝夺骊龙羣。
忽惊薤露曲，掩噎东山云。','',''),('quantangshi-04136','题东山子李适碑阴二首 二','徐彥伯','quantangshi','','卷5','回也寔夭折，贾生亦脆促。
今复哀若人，危光迅风烛。
夜台沦清镜，穷尘埋结绿。
何以赠下泉，生刍唯一束。','',''),('quantangshi-04137','淮亭吟','徐彥伯','quantangshi','','卷5','贞寂虑兮淮山幽，怜芳若兮{临/手}中洲。
崩湍委咽日夜流，孤客危坐心自愁。
矧鹤唳兮风晓，复猿鸣兮霜秋。
熠耀飞兮蟋蟀吟，倚清瑟兮横凉琴。
撷瑶芳兮吊楚水，弄琪树兮歌越岑。
山崎礒兮隈曲，水涓涟兮洞汩。
金光延起兮骤兴没，青苔竟兮绿苹歇。
绿苹歇兮凋朱颜，美人寂历兮何时闲。
君不见可怜桐柏上，丰茸桂树花满山。','',''),('quantangshi-04138','芳树','徐彥伯','quantangshi','','卷5','玉花珍簟上，金缕画屏开。
晓月怜筝柱，春风忆镜台。
筝柱春风吹晓月，芳树落花朝暝歇。
藁砧刀头未有期，攀条拭泪坐相思。','',''),('quantangshi-04139','游禁苑幸临渭亭遇雪应制','徐彥伯','quantangshi','','卷5','玉律藏冰候，彤阶飞雪时。
日寒消不尽，风定舞还迟。
琼树留宸瞩，璇花入睿词。
悬知穆天子，黄竹谩言诗。','',''),('quantangshi-04140','奉和送金城公主适西蕃应制','徐彥伯','quantangshi','','卷5','凤扆怜箫曲，鸾闺念掌珍。
羗庭遥筑馆，庙策重和亲。
星转银河夕，花移玉树春。
圣心凄送远，留跸望征尘。','',''),('quantangshi-04141','幸白鹿观应制','徐彥伯','quantangshi','','卷5','凤舆乘八景，龟箓向三仙。
日月移平地，云霞缀小天。
金童擎紫药，玉女献青莲。
花洞留宸赏，还旗绕夕烟。','',''),('quantangshi-04142','胡无人行','徐彥伯','quantangshi','','卷5','十月繁霜下，征人远凿空。
云摇锦车节，海照角端弓。
暗碛埋沙树，冲飙卷塞蓬。
方随膜拜入，歌舞玉门中。','',''),('quantangshi-04143','倢伃','徐彥伯','quantangshi','','卷5','君恩忽断绝，妾思终未央。
巾栉不可见，枕席空余香。
窗暗网罗白，阶秋苔藓黄。
应门寂已闭，流涕向昭阳。','',''),('quantangshi-04144','采莲曲','徐彥伯','quantangshi','','卷5','妾家越水边，摇艇入江烟。
既觅同心侣，复采同心莲。
折藕丝能脆，开花叶正圆。
春歌弄明月，归棹落花前。','',''),('quantangshi-04145','孤烛叹','徐彥伯','quantangshi','','卷5','切切夜闺冷，微微孤烛然。
玉盘红泪滴，金烬彩光圆。
暖手缝轻素，嚬蛾续断弦。
相思咽不语，回向锦屏眠。','',''),('quantangshi-04146','闺怨','徐彥伯','quantangshi','','卷5','征客戍金微，愁闺独掩扉。
尘埃生半榻，花絮落残机。
褪暖蚕初卧，巢昏燕欲归。
春风日向尽，衔涕作征衣。','',''),('quantangshi-04147','饯唐州高使君赴任','徐彥伯','quantangshi','','卷5','香萼媚红滋，垂条萦绿丝。
情人拂瑶袂，共惜此芳时。
驌驦已踯躅，鸟隼方葳蕤。
跂予望太守，流润及京师。','',''),('quantangshi-04148','奉和幸新丰温泉宫应制','徐彥伯','quantangshi','','卷5','姬典歌时迈，虞篇记省方。
何如黑帝月，玄览白云乡。
翠仗萦船岸，明斾应萯阳。
风摇花眊彩，雪艳宝戈芒。
御陌开函次，离宫夹树行。
桂枝笼騕褭，松叶覆堂皇。
仙石含珠液，温池孕璧房。
涌疑神瀵溢，澄若帝台浆。
独沸流常热，潜蒸气转香。
青坛环玉甃，红础铄金光。
藻曜凝芳洁，葳蕤献淑祥。
五龙归宝算，九鳸叶时康。
同预华封老，中衢祝圣皇。','',''),('quantangshi-04149','同韦舍人元旦早朝','徐彥伯','quantangshi','','卷5','夕转清壶漏，晨惊长乐钟。
逶迤纶禁客，假寐守铜龙。
予亦趋三殿，肩随谒九重。
繁珂接曙响，华劒比春容。
相问韶光歇，弥怜芳意浓。
愿言乘日旰，携手即云峰。','',''),('quantangshi-04150','侍宴韦嗣立山庄应制','徐彥伯','quantangshi','','卷5','鼎臣休澣隙，方外结遥心。
别业青霞境，孤潭碧树林。
每驰东墅策，遥弄北溪琴。
帝眷纾时豫，台园赏岁阴。
移銮明月沼，张组白云岑。
御酒瑶觞落，仙坛竹径深。
三光悬圣藻，五等冠朝簪。
自昔皇恩感，咸言独自今。','',''),('quantangshi-04151','送特进李峤入都祔庙','徐彥伯','quantangshi','','卷5','特进三公下，台臣百揆先。
孝图开寝石，祠主卜牲筵。
恩级青纶赐，徂装紫橐悬。
绸缪金鼎席，宴饯玉潢川。
北斗分征路，东山起赠篇。
乐池歌绿藻，梁苑藉红荃。
骑转商岩日，旌摇关塞烟。
庙堂须鲠议，锦节伫来旋。','',''),('quantangshi-04152','春闺','徐彥伯','quantangshi','','卷5','戍客戍清波，幽闺幽思多。
暗梁闻语燕，夜烛见飞蛾。
宝鸭藏脂粉，金屏缀绮罗。
裁衣卷纹素，织锦度鸣梭。
有使通西极，缄书寄北河。
年光只恐尽，征战莫蹉跎。','',''),('quantangshi-04153','奉和兴庆池戏竞渡应制','徐彥伯','quantangshi','','卷5','夹道传呼翊翠虬，天回日转御芳洲。
青潭晓霭笼仙跸，红屿晴花隔彩旒。
香溢金杯环广坐，声传妓舸匝中流。
羣臣相庆嘉鱼乐，共哂横汾歌吹秋。','',''),('quantangshi-04154','苑中遇雪应制','徐彥伯','quantangshi','','卷5','千钟圣酒御筵披，六出祥英乱绕枝。
即此神仙对琼圃，何烦辙迹向瑶池。','',''),('quantangshi-04155','上巳日祓禊渭滨应制','徐彥伯','quantangshi','','卷5','晴风丽日满芳洲，柳色春筵祓锦流。
皆言侍跸横汾宴，暂似乘槎天汉游。','',''),('quantangshi-04156','夜宴安乐公主新宅应制','徐彥伯','quantangshi','','卷5','凤楼开阖引明光，花酎连添醉益香。
欲知帝女薰天贵，金柯玉柱夜成行。','',''),('quantangshi-04157','饯唐永昌','徐彥伯','quantangshi','','卷5','金溪碧水玉潭沙，凫舄翩翩弄日华。
鬬鸡香陌行春倦，为摘东园桃李花。','',''),('quantangshi-04158','侍宴桃花园','徐彥伯','quantangshi','','卷5','源水丛花无数开，丹跗红萼间青梅。
从今结子三千岁，预喜仙游复摘来。','',''),('quantangshi-04159','石淙','徐彥伯','quantangshi','','卷5','碧淀红涔崿嶂间，淙嵌洑岨洊成湾。
琪树琁娟花未落，银芝窋䆛露初还。
八风行殿开仙牓，七景飞舆下石关。
张茑席云平圃宴，焜煌金记蕴名山。','',''),('quantangshi-04160','夏日游德州赠高四','駱賓王','quantangshi','','卷5','日观邻全赵，星临俯旧吴。
鬲津开巨浸，稽阜镇名都。
紫云浮剑匣，青山孕宝符。
封疆恢霸道，问鼎竞雄图。
神光包四大，皇威震八区。
风烟通地轴，星象正天枢。
天枢限南北，地轴殊乡国。
辟门通舜宾，比屋封尧德。
言谢垂钩隐，来参负鼎职。
天子不见知，羣公讵相识。
未展从东骏，空戢图南翼。
时命欲何言，抚膺长叹息。
叹息将如何，游人意气多。
白雪梁山曲，寒风易水歌。
泣魏伤吴起，思赵切廉颇。
凄断韩王剑，生死翟公罗。
罗悲翟公意，剑负韩王气。
骄饵去易论，忌途良可畏。
夙昔怀江海，平生混泾渭。
千载契风云，一言忘贱贵。
去去访林泉，空谷有遗贤。
言投爵里刺，来泛野人船。
缔交君赠缟，投分我忘筌。
成风郢匠斲，流水伯牙弦。
牙弦忘道术，漳滨恣闲逸。
聊安张蔚庐，讵扫陈蕃室。
虚室狎招寻，敬爱混浮沈。
一诺黄金信，三复白圭心。
霜松贞雅节，月桂朗冲襟。
灵台万顷浚，学府九流深。
谈玄明毁璧，拾紫陋籝金。
鹭涛开碧海，凤彩缀词林。
林虚星华映，水澈霞光净。
霞水两分红，川源四望通。
雾卷天山静，烟销太史空。
鸟声流向薄，蝶影乱芳丛。
柳阴低椠水，荷气上薰风。
风月芳菲节，物华纷可悦。
将欢促席赏，遽尔又归别。
积水带吴门，通波连禹穴。
赠言虽欲尽，机心庶应绝。
潘岳本自闲，梁鸿不因热。
一瓢欣狎道，三月聊栖拙。
栖拙隐金华，狎道访仙查。
放旷愚公谷，消散野人家。
一顷南山豆，五色东陵瓜。
野衣裁薜叶，山酒酌藤花。
白云离望远，青溪隐路赊。
傥忆幽岩桂，犹冀折疎麻。','',''),('quantangshi-04161','在江南赠宋五之问','駱賓王','quantangshi','','卷5','井络双源浚，浔阳九派长。
沦波通地穴，输委下归塘。
别岛笼朝蜃，连洲拥夕涨。
韫珠澄积润，让璧动浮光。
浮光凝折水，积润疎圆沚。
玉轮涵地开，剑阁连星起。
风烟标迥秀，英灵信多美。
怀德践遗芳，端操慙谋己。
谋己谬观光，牵迹强凄惶。
揆拙迷三省，劳生昧两忘。
弹随空被笑，献楚自多伤。
一朝殊默语，千里易炎凉。
炎凉几迁贸，川陆疲臻凑。
积水架吴涛，连山横楚岫。
风月虽殊昔，星河犹是旧。
姑苏望南浦，邯郸通北走。
北走平生亲，南浦别离津。
潇湘一超忽，洞庭多苦辛。
秋江无绿芷，寒汀有白苹。
采之将何遗，故人漳水滨。
漳滨已辽远，江潭未旋返。
为听短歌行，当想长洲苑。
露金熏菊岸，风佩摇兰坂。
蝉鸣稻叶秋，雁起芦花晚。
晚秋云日明，亭臯风雾清。
独负平生气，重牵摇落情。
占星非聚德，梦月讵悬名。
寂寥伤楚奏，凄断泣秦声。
秦声怀旧里，楚奏悲无已。
郢路少知音，丛台富奇士。
温辉凌爱日，壮气惊寒水。
一顾重风云，三冬足文史。
文史盛纷纶，京洛多风尘。
犹轻五车富，未重一囊贫。
李仙非易托，苏鬼尚难因。
不惜劳歌尽，谁为听阳春。','',''),('quantangshi-04162','晚憩田家','駱賓王','quantangshi','','卷5','转蓬劳远役，披薜下田家。
山形类九折，水势急三巴。
悬梁接断岸，涩路拥崩查。
雾岩沦晓魄，风溆涨寒沙。
心迹一朝舛，关山万里赊。
龙章徒表越，闽俗本殊华。
旅行悲泛梗，离赠折疎麻。
唯有寒潭菊，独似故园花。','',''),('quantangshi-04163','出石门','駱賓王','quantangshi','','卷5','层岩远接天，绝岭上栖烟。
松低轻盖偃，藤细弱丝悬。
石明如挂镜，苔分似列钱。','',''),('quantangshi-04164','至分陕','駱賓王','quantangshi','','卷5','陕西开胜壤，召南分沃畴。
列树巢维鹊，平渚下雎鸠。
憩棠疑勿剪，曳葛似攀樛。
至今王化美，非独在隆周。','',''),('quantangshi-04165','寓居洛滨对雪忆谢二','駱賓王','quantangshi','','卷5','旅思眇难裁，冲飙恨易哀。
旷望洛川晚，飘颻瑞雪来。
积彩明书幌，流韵绕琴台。
色夺迎仙羽，花避犯霜梅。
谢庭赏方逸，袁扉掩未开。
高人傥有访，兴尽讵须回。','',''),('quantangshi-04166','北眺舂陵','駱賓王','quantangshi','','卷5','揽辔疲宵迈，驱马倦晨兴。
既出封泥谷，还过避雨陵。
山行明照上，溪宿密云蒸。
登高徒欲赋，词殚独抚膺。','',''),('quantangshi-04167','夏日游目聊作','駱賓王','quantangshi','','卷5','暂屏嚣尘累，言寻物外情。
致逸心逾默，神幽体自轻。
浦夏荷香满，田秋麦气清。
讵假沧浪上，将濯楚臣缨。','',''),('quantangshi-04168','同崔驸马晓初登楼思京','駱賓王','quantangshi','','卷5','丽谯通四望，繁忧起万端。
绮疏低晚魄，镂槛肃初寒。
白云乡思远，黄图归路难。
唯余西向笑，暂似当长安。','',''),('quantangshi-04169','月夜有怀简诸同病','駱賓王','quantangshi','','卷5','闲庭落景尽，疎帘夜月通。
山灵响似应，水净望如空。
栖枝犹绕鹊，遵渚未来鸿。
可叹高楼妇，悲思杳难终。','',''),('quantangshi-04170','叙寄员半千','駱賓王','quantangshi','','卷5','薄宦三河道，自负十余年。
不应惊若厉，秪为直如弦。
坐历山川险，吁嗟陵谷迁。
长吟空抱膝，短翮讵冲天。
魂归沧海上，望断白云前。
钓名劳拾紫，隐迹自谈玄。
不学多能圣，徒思鸿宝仙。
斯志良难已，此道岂徒然。
嗟为刀笔吏，耻从绳墨牵。
岐路情虽狎，人伦地本偏。
长揖谢时事，独往访林泉。
寄言二三子，生死不来旋。','',''),('quantangshi-04171','咏怀古意上裴侍郎','駱賓王','quantangshi','','卷5','三十二余罢，鬓是潘安仁。
四十九仍入，年非朱买臣。
纵横愁系越，坎壈倦游秦。
出笼穷短翮，委辙涸枯鳞。
穷经不霑用，弹铗欲谁申。
天子未驱策，岁月几沈沦。
轻生长慷慨，效死独殷勤。
徒歌易水客，空老渭川人。
一得视边塞，万里何苦辛。
剑匣胡霜影，弓开汉月轮。
金刀动秋色，铁骑想风尘。
为国坚诚款，捐躯忘贱贫。
勒功思比宪，决略暗欺陈。
若不犯霜雪，虚掷玉京春。','',''),('quantangshi-04172','春夜韦明府宅宴得春字','駱賓王','quantangshi','','卷5','酌桂陶芳夜，披薜啸幽人。
雅琴驯鲁雉，清歌落范尘。
宿云低迥盖，残月上虚轮。
幸此承恩洽，聊当故乡春。','',''),('quantangshi-04173','过张平子墓','駱賓王','quantangshi','','卷5','西鄂该通理，南阳擅德音。
玉巵浮藻丽，铜浑积思深。
忽怀今日昔，非复昔时今。
日落丰碑暗，风来古木吟。
惟叹穷泉下，终郁羡鱼心。','',''),('quantangshi-04174','从军中行路难二首 一','駱賓王','quantangshi','','卷5','君不见封狐雄虺自成羣，冯深负固结妖氛。
玉玺分兵征恶少，金坛受律动将军。
将军拥旄宣庙略，战士横行静夷落。
长驱一息背铜梁，直指三巴登剑阁。
阁道岧嶤起戍楼，剑门遥裔俯灵丘。
邛关九折无平路，江水双源有急流。
征役无期返，他乡岁华晚。
杳杳丘陵出，苍苍林薄远。
途危紫盖峰，路涩青泥坂。
去去指哀牢，行行入不毛。
绝壁千里险，连山四望高。
中外分区宇，夷夏殊风土。
交趾枕南荒，昆弥临北户。
川原绕毒雾，溪谷多淫雨。
行潦四时流，崩查千岁古。
漂梗飞蓬不自安，扪藤引葛度危峦。
昔时闻道从军乐，今日方知行路难。
沧江绿水东流驶，炎洲丹徼南中地。
南中南斗映星河，秦川秦塞阻烟波。
三春边地风光少，五月泸中瘴疠多。
朝驱疲斥候，夕息倦樵歌。
向月弯繁弱，连星转太阿。
重义轻生怀一顾，东伐西征凡几度。
夜夜朝朝斑鬓新，年年岁岁戎衣故。
灞城隅，滇池水。
天雅望转积，地际行无已。
徒觉炎凉节物非，不知关山千万里。
弃置勿重陈，征行多苦辛。
且悦清笳杨柳曲，讵忆芳园桃李人。
绛节朱旗分白羽，丹心白刃酬明主。
但令一被君王知，谁惮三边征战苦。
行路难，几千端。
无复归云凭短翰，空余望日想长安。','',''),('quantangshi-04175','从军中行路难二首 二','駱賓王','quantangshi','','卷5','君不见玉关尘色暗边庭，铜鞮杂虏寇长城。
天子按剑征余勇，将军受脤事横行。
七德龙韬开玉帐，千里鼍鼓垒金钲。
阴山苦雾埋高垒，交河孤月照连营。
连营去去无穷极，拥斾遥遥过绝国。
阵云朝结晦天山，寒沙夕涨迷疎勒。
龙鳞水上开鱼贯，马首山前振雕翼。
长驱万里讋祈连，分麾三命武功宣。
百发乌号遥碎柳，七尺龙文迥照莲。
春来秋去移灰琯，兰闺柳市芳尘断。
雁门迢递尺书稀，鸳被相思双带缓。
行路难，行路难，誓令氛祲静臯兰。
但使封侯龙頟贵，讵随中妇凤楼寒。','',''),('quantangshi-04176','帝京篇','駱賓王','quantangshi','','卷5','山河千里国，城阙九重门。
不覩皇居壮，安知天子尊。
皇居帝里崤函谷，鹑野龙山侯甸服。
五纬连影集星躔，八水分流横地轴。
秦塞重关一百二，汉家离宫三十六。
桂殿嵚岑对玉楼，椒房窈窕连金屋。
三条九陌丽城隈，万户千门平旦开。
复道斜通鳷鹊观，交衢直指凤皇台。
剑履南宫入，簪缨北阙来。
声名冠寰宇，文物象昭回。
钩陈肃兰戺，璧沼浮槐市。
铜羽应风回，金茎承露起。
校文天禄阁，习战昆明水。
朱邸抗平台，黄扉通戚里。
平台戚里带崇墉，炊金馔玉待鸣钟。
小堂绮帐三千户，大道青楼十二重。
宝盖雕鞍金络马，兰窗绣柱玉盘龙。
绣柱璇题粉壁映，锵金鸣玉王侯盛。
王侯贵人多近臣，朝游北里暮南邻。
陆贾分金将宴喜，陈遵投辖正留宾。
赵李经过密，萧朱交结亲。
丹凤朱城白日暮，青牛绀幰红尘度。
侠客珠弹垂杨道，倡妇银钩采桑路。
倡家桃李自芳菲，京华游侠盛轻肥。
延年女弟双凤入，罗敷使君千骑归。
同心结缕带，连理织成衣。
春朝桂尊尊百味，秋夜兰灯灯九微。
翠幌珠帘不独映，清歌宝瑟自相依。
且论三万六千是，宁知四十九年非。
古来荣利若浮云，人生倚伏信难分。
始见田窦相移夺，俄闻衞霍有功勋。
未厌金陵气，先开石椁文。
朱门无复张公子，灞亭谁畏李将军。
相顾百龄皆有待，居然万化咸应改。
桂枝芳气已销亡，柏梁高宴今何在？
春去春来苦自驰，争名争利徒尔为。
久留郎署终难遇，空扫相门谁见知。
当时一旦擅豪华，自言千载长骄奢。
倏忽抟风生羽翼，须臾失浪委泥沙。
黄雀徒巢桂，青门遂种瓜。
黄金销铄素丝变，一贵一贱交情见。
红颜宿昔白头新，脱粟布衣轻故人。
故人有湮沦，新知无意气。
灰死韩安国，罗伤翟廷尉。
已矣哉，归去来。
马卿辞蜀多文藻，扬雄仕汉乏良媒。
三冬自矜诚足用，十年不调几邅回。
汲黯薪逾积，孙弘阁未开。
谁惜长沙傅，独负洛阳才。','',''),('quantangshi-04177','畴昔篇','駱賓王','quantangshi','','卷5','少年重英侠，弱岁贱衣冠。
既托寰中赏，方承膝下欢。
遨游灞水曲，风月洛城端。
且知无玉馔，谁肯逐金丸。
金丸玉馔盛繁华，自言轻侮季伦家。
五霸争驰千里马，三条竞骛七香车。
掩映飞轩乘落照，参差步障引朝霞。
池中旧水如悬镜，屋里新妆不让花。
意气风云倏如昨，岁月春秋屡回薄。
上苑频经柳絮飞，中园几见梅花落。
当时门客今何在？畴昔交朋已疎索。
莫教憔悴损容仪，会得高秋云雾廓。
淹留坐帝乡，无事积炎凉。
一朝披短褐，六载奉长廊。
赋文慙昔马，执戟叹前扬。
挥戈出武帐，荷笔入文昌。
文昌隐隐皇城里，由来奕奕多才子。
潘陆词锋骆驿飞，张曹翰苑纵横起。
卿相未曾识，王侯宁见拟。
垂钓甘成白首翁，负薪何处逢知己？
判将运命赋穷通，从来奇舛任西东。
不应永弃同刍狗，且复飘颻类转蓬。
容鬓年年异，春华岁岁同。
荣观未尽礼，徇主欲申功。
脂车秣马辞乡国，萦辔西南使邛僰。
玉垒铜梁不易攀，地角天涯眇难测。
莺啭蝉吟有悲望，鸿来雁度无音息。
阳关积雾万里昏，剑阁连山千种色。
蜀路何悠悠，岷峯阻且修。
回肠随九折，迸泪连双流。
寒光千里暮，露气二江秋。
长途看束马，平水且沈牛。
华阳旧地标神制，石镜蛾眉真秀丽。
诸葛才雄已号龙，公孙跃马轻称帝。
五丁卓荦多奇力，四士英灵富文艺。
云气横开八阵形，桥形遥分七星势。
川平烟雾开，游戏锦城隈。
墉高龟望出，水净雁文回。
寻姝入酒肆，访客上琴台。
不识金貂重，偏惜玉山颓。
他乡冉冉消年月，帝里沈沈限城阙。
不见猿声助客啼，唯闻旅思将花发。
我家迢递关山里，关山迢递不可越。
故园梅柳尚余春，来时勿使芳菲歇。
解鞅欲言归，执袂怆多违。
北梁俱握手，南浦共沾衣。
别情伤去盖，离念惜徂辉。
知音何所托，木落雁南飞。
回来望平陆，春来酒应熟。
相将菌阁卧青溪，且用藤杯泛黄菊。
十年不调为贫贱，百日屡迁随倚伏。
祗为须求负郭田，使我再干州县禄。
百年郁郁少腾迁，万里遥遥入镜川。
涘江拂潮冲白日，淮海长波接远天。
丛竹凝朝露，孤山起暝烟。
赖有边城月，常伴客旌悬。
东南美箭称吴会，名都隐轸三江外。
涂山执玉应昌期，曲水开襟重文会。
仙镝流音鸣鹤岭，宝剑分辉落蛟濑。
未看白马对芦刍，且觉浮云似车盖。
江南节序多，文酒屡经过。
共踏春江曲，俱唱采菱歌。
舟移疑入镜，棹举若乘波。
风光无限极，归檝碍池荷。
眺听烟霞正流眄，即从王事归舻转。
芝田花月屡裴回，金谷佳期重游衍。
登高北望嗤梁叟，凭轼西征想潘掾。
峯开华岳耸疑莲，水激龙门急如箭。
人事谢光阴，俄遭霜露侵。
偷存七尺影，分没九泉深。
穷途行泣玉，愤路未藏金。
茹荼空有叹，怀橘独伤心。
年来岁去成销铄，怀抱心期渐寥落。
挂冠裂冕已辞荣，南亩东臯事耕凿。
宾阶客院常疏散，蓬径柴扉终寂寞。
自有林泉堪隐栖，何必山中事丘壑。
我住青门外，家临素浐滨。
遥瞻丹凤阙，斜望黑龙津。
荒衢通猎骑，穷巷抵樵轮。
时有桃源客，来访竹林人。
昨夜琴声奏悲调，旭旦含颦不成笑。
果乘骢马发嚣书，复道郎官禀纶诰。
冶长非罪曾缧絏，长孺然灰也经溺。
高门有阅不图封，峻笔无闻歛敷妙。
适离京兆谤，还从御史弹。
炎威资夏景，平曲况秋翰。
画地终难入，书空自不安。
吹毛未可待，摇尾且求餐。
丈夫坎壈多愁疾，契阔迍邅尽今日。
慎罚宁凭两造辞，严科直挂三章律。
邹衍衔悲系燕狱，李斯抱怨拘秦桎。
不应白发顿成丝，直为黄沙暗如漆。
紫禁终难呌，朱门不易排。
惊魂闻叶落，危魄逐轮埋。
霜威遥有厉，雪[枉]遂无阶。
含冤欲谁道，饮气独居怀。
忽闻驿使发关东，传道天波万里通。
涸鳞去辙还游海，幽禽释网便翔空。
舜泽尧曦方有极，谗言巧佞傥无穷。
谁能局迹依三辅，会就商山访四翁。','',''),('quantangshi-04178','艳情代郭氏答卢照邻','駱賓王','quantangshi','','卷5','迢迢芊路望芝田，眇眇函关恨蜀川。
归云已落涪江外，还雁应过洛水瀍。
洛水傍连帝城侧，帝宅层甍垂凤翼。
铜驼路上柳千条，金谷园中花几色。
柳叶园花处处新，洛阳桃李应芳春。
妾向双流窥石镜，君住三川守玉人。
此时离别那堪道，此日空牀对芳沼。
芳沼徒游比目鱼，幽径还生拔心艹。
流风回雪傥便娟，骥子鱼文实可怜。
掷果河阳君有分，货酒成都妾亦然。
莫言贫贱无人重，莫言富贵应须种。
绿珠犹得石崇怜，飞燕曾经汉皇宠。
良人何处醉纵横？直如循默守空名。
倒提新缣成慊慊，翻将故剑作平平。
离前吉梦成兰兆，别后啼痕上竹生。
别日分明相约束，已取宜家成诫勖。
当时拟弄掌中珠，岂谓先摧庭际玉。
悲鸣五里无人问，肠断三声谁为续。
思君欲上望夫台，端居懒听将雏曲。
沈沈落日向山低，檐前归燕竝头栖。
抱膝当窗看夕兔，侧耳空房听晓鸡。
舞蝶临阶秪自舞，啼鸟逢人亦助啼。
独坐伤孤枕，春来悲更甚。
峨眉山上月如眉，濯锦江中霞似锦。
锦字回文欲赠君，剑壁层峰自纠纷。
平江淼淼分清浦，长路悠悠间白云。
也知京洛多佳丽，也知山岫遥亏蔽。
无那短封即疎索，不在长情守期契。
传闻织女对牵牛，相望重河隔浅流。
谁分迢迢经两岁，谁能脉脉待三秋。
情知唾井终无理，情知覆水也难收。
不复下山能借问，更向卢家字莫愁。','',''),('quantangshi-04179','代女道士王灵妃赠道士李荣','駱賓王','quantangshi','','卷5','玄都五府风尘绝，碧海三山波浪深。
桃实千年非易待，桑田一变已难寻。
别有仙居对三市，金阙银宫相向起。
台前镜影伴仙娥，楼上箫声随凤史。
凤楼迢递绝尘埃，莺时物色正裴回。
灵芝紫检参差长，仙桂丹花重叠开。
双童绰约时游陟，三鸟联翩报消息。
尽言真侣出遨游，传道风光无限极。
轻花委砌惹裾香，残月窥窗觇幌色。
个时无数倂妖妍，个里无穷总可怜。
别有众中称黜帝，天上人间少流例。
洛滨仙驾启遥源，淮浦灵津符远筮。
自言少小慕幽玄，只言容易得神仙。
佩中邀勒经时序，箫里寻思复几年。
寻思许事真情变，二人容华识少选。
漫道烧丹止七飞，空传化石曾三转。
寄语天上弄机人，寄语河边值查客。
乍可悤悤共百年，谁使遥遥期七夕。
想知人意自相寻，果得深心共一心。
一心一意无穷已，投漆投胶非足拟。
只将羞涩当风流，持此相怜保终始。
相怜相念倍相亲，一生一代一双人。
不把丹心比玄石，惟将浊水况清尘。
只言柱下留期信，好欲将心学松蕣。
不能京兆画峨眉，翻向成都骋驺引。
青牛紫气度灵关，尺素赩鳞去不还。
连苔上砌无穷绿，修竹临坛几处斑。
此时空牀难独守，此日别离那可久。
梅花如雪柳如丝，年去年来不自持。
初言别在寒偏在，何悟春来春更思。
春时物色无端绪，双枕孤眠谁分许。
分念娇莺一种啼，生憎燕子千般语。
朝云旭日照青楼，迟晖丽色满皇州。
落花泛泛浮灵沼，垂柳长长拂御沟。
御沟大道多奇赏，侠客妖容递来往。
宝骑连花铁作钱，香轮骛水珠为网。
香轮宝骑竞繁华，可怜今夜宿倡家。
鹦鹉杯中浮竹叶，凤凰琴里落梅花。
许辈多情偏送款，为问春花几时满。
千回鸟信说众诸，百过莺啼说长短。
长短众诸判不寻，千回百过浪关心。
何曾举意西邻玉，未肯留情南陌金。
南陌西邻咸自保，还辔归期须及早。
为想三春狭斜路，莫辞九折邛关道。
假令白里似长安，须使青牛学剑端。
苹风入驭来应易，竹杖成龙去不难。
龙飙去去无消息，鸾镜朝朝减容色。
君心不记下山人，妾欲空期上林翼。
上林三月鸿欲稀，华表千年鹤未归。
不分淹留桑路待，秪应直取桂轮飞。','',''),('quantangshi-04180','从军行','駱賓王','quantangshi','','卷5','平生一顾重，意气溢三军。
野日分戈影，天星合剑文。
弓弦抱汉月，马足践胡尘。
不求生入塞，唯当死报君。','',''),('quantangshi-04181','王昭君','駱賓王','quantangshi','','卷5','歛容辞豹尾，缄恨度龙鳞。
金钿明汉月，玉筯染胡尘。
古镜菱花暗，愁眉柳叶颦。
唯有清笳曲，时闻芳树春。','',''),('quantangshi-04182','于紫云观赠道士','駱賓王','quantangshi','','卷5','碧落澄秋景，玄门启曙关。
人疑列御至，客似令威还。
羽盖徒欣仰，云车未可攀。
只应倾玉醴，时许寄颓颜。','',''),('quantangshi-04183','渡瓜步江','駱賓王','quantangshi','','卷5','捧檄辞幽径，鸣榔下贵洲。
惊涛疑跃马，积气似连牛。
月迥寒沙净，风急夜江秋。
不学浮云影，他乡空滞留。','',''),('quantangshi-04184','途中有怀','駱賓王','quantangshi','','卷5','睠然怀楚奏，怅矣背秦关。
涸鳞惊照辙，坠羽怯虚弯。
素服三川化，乌裘十上还。
莫言无皓齿，时俗薄朱颜。','',''),('quantangshi-04185','至分水戍','駱賓王','quantangshi','','卷5','行役忽离忧，复此怆分流。
溅石回湍咽，萦丛曲涧幽。
阴岩常结晦，宿莽竞含秋。
况乃霜晨早，寒风入戍楼。','',''),('quantangshi-04186','望乡夕泛','駱賓王','quantangshi','','卷5','归怀剩不安，促榜犯风澜。
落宿含楼近，浮月带江寒。
喜逐行前至，忧从望里宽。
今夜南枝鹊，应无绕树难。','',''),('quantangshi-04187','久客临海有怀','駱賓王','quantangshi','','卷5','天涯非日观，地屺望星楼。
练光摇乱马，剑气上连牛。
草湿姑苏夕，叶下洞庭秋。
欲知凄断意，江上涉安流。','',''),('quantangshi-04188','游兖部逢孔君自衞来欣然相遇若旧','駱賓王','quantangshi','','卷5','游人自衞返，背客隔淮来。
倾盖金兰合，忘筌玉叶开。
繁花明日柳，疎蕊落风梅。
将期重交态，时慰不然灰。','',''),('quantangshi-04189','西京守岁','駱賓王','quantangshi','','卷5','闲居寡言宴，独坐惨风尘。
忽见严冬尽，方知列宿春。
夜将寒色去，年共晓光新。
耿耿他乡夕，无由展旧亲。','',''),('quantangshi-04190','同辛簿简仰酬思玄上人林泉四首 一','駱賓王','quantangshi','','卷5','闻君招隐地，仿髴武陵春。
缉芰知还楚，披榛似避秦。
崩查年祀积，幽草岁时新。
一谢沧浪水，安知有逸人。','',''),('quantangshi-04191','同辛簿简仰酬思玄上人林泉四首 二','駱賓王','quantangshi','','卷5','芳晨临上月，幽赏狎中园。
有蝶堪成梦，无羊可触藩。
忘怀南涧藻，蠲思北堂萱。
坐叹华滋歇，思君谁为言。','',''),('quantangshi-04192','同辛簿简仰酬思玄上人林泉四首 三','駱賓王','quantangshi','','卷5','林泉恣探历，风景暂裴徊。
客有迁莺处，人无结驷来。
聚花如薄雪，沸水若轻雷。
今日徒招隐，终知异凿坏。','',''),('quantangshi-04193','同辛簿简仰酬思玄上人林泉四首 四','駱賓王','quantangshi','','卷5','俗远风尘隔，春还初服迟。
林疑中散地，人似上皇时。
芳杜湘君曲，幽兰楚客词。
山中有春草，长似寄相思。','',''),('quantangshi-04194','秋日饯陆道士陈文林','駱賓王','quantangshi','','卷5','青牛游华岳，赤马走吴宫。
玉柱离鸿怨，金罍浮蚁空。
日霁崤陵雨，尘起洛阳风。
唯当玄度月，千里与君同。','',''),('quantangshi-04195','送郑少府入辽共赋侠客远从戎','駱賓王','quantangshi','','卷5','边烽警榆塞，侠客度桑干。
柳叶开银镝，桃花照玉鞍。
满月临弓影，连星入剑端。
不学燕丹客，空歌易水寒。','',''),('quantangshi-04196','送费六还蜀','駱賓王','quantangshi','','卷5','星楼望蜀道，月峡指吴门。
万行流别泪，九折切惊魂。
雪影含花落，云阴带叶昏。
还愁三径晚，独对一清尊。','',''),('quantangshi-04197','秋日送侯四得弹字','駱賓王','quantangshi','','卷5','我留安豹隐，君去学鹏抟。
岐路分襟易，风云促膝难。
夕涨流波急，秋山落日寒。
惟有思归引，凄断为君弹。','',''),('quantangshi-04198','秋日送尹大赴京','駱賓王','quantangshi','','卷5','挂瓢余隐舜，负鼎尔干汤。
竹叶离罇满，桃花别路长。
低河耿秋色，落月抱寒光。
素书如可嗣，幽谷竚宾行。','',''),('quantangshi-04199','秋夜送閰五还润州','駱賓王','quantangshi','','卷5','通庄抵旧里，沟水泣新知。
断云飘易滞，连露积难披。
素风啼迥堞，惊月绕疎枝。
无力励短翰，轻举送长离。','',''),('quantangshi-04200','送王明府参选赋得鹤','駱賓王','quantangshi','','卷5','振衣游紫府，飞盖背青田。
虚心恒警露，孤影尚凌烟。
离歌凄妙曲，别操绕繁弦。
在阴如可和，轻响会闻天。','',''),('quantangshi-04201','秋日送别','駱賓王','quantangshi','','卷5','寂寥心事晚，摇落岁时秋。
共此伤年髪，相看惜去留。
当歌应破涕，哀命返穷愁。
别后能相忆，东陵有故侯。','',''),('quantangshi-04202','别李峤得胜字','駱賓王','quantangshi','','卷5','芳尊徒自满，别恨转难胜。
客似游江岸，人疑上灞陵。
寒更承夜永，凉景向秋澄。
离心何以赠，自有玉壶冰。','',''),('quantangshi-04203','在衮州饯宋五之问','駱賓王','quantangshi','','卷5','淮沂泗水地，梁甫汶阳东。
别路青骊远，离尊绿蚁空。
柳寒凋密翠，棠晚落疎红。
别后相思曲，凄断入琴风。','',''),('quantangshi-04204','游灵公观','駱賓王','quantangshi','','卷5','灵峰标胜境，神府枕通川。
玉殿斜连汉，金堂迥架烟。
断风疎晚竹，流水切危弦。
别有青门外，空怀玄圃仙。','',''),('quantangshi-04205','夏日游山家同夏少府','駱賓王','quantangshi','','卷5','返照下层岑，物外狎招寻。
兰径薰幽佩，槐庭落暗金。
谷静风声彻，山空月色深。
一遣樊笼累，唯余松桂心。','',''),('quantangshi-04206','初秋登王司马楼宴得同字','駱賓王','quantangshi','','卷5','展骥端居暇，登龙喜宴同。
缔赏三清满，承欢六义通。
野晦寒阴积，潭虚夕照空。
顾慙非梦鸟，滥此厕雕虫。','',''),('quantangshi-04207','初秋于窦六郎宅宴','駱賓王','quantangshi','','卷5','千里风云契，一朝心赏同。
意尽深交合，神灵俗累空。
草带销寒翠，花枝发夜红。
唯将澹若水，长揖古人风。','',''),('quantangshi-04208','冬日宴','駱賓王','quantangshi','','卷5','二三物外友，一百杖头钱。
赏洽袁公地，情披乐令天。
促席鸾觞满，当炉兽炭然。
何须攀桂树，逢此自留连。','',''),('quantangshi-04209','镂鸡子','駱賓王','quantangshi','','卷5','幸遇清明节，欣逢旧练人。
刻花争脸态，写月竞眉新。
晕罢空余月，诗成倂道春。
谁知怀玉者，含响未吟晨。','',''),('quantangshi-04210','咏美人在天津桥','駱賓王','quantangshi','','卷5','美女出东邻，容与上天津。
整衣香满路，移步袜生尘。
水下看妆影，眉头画月新。
寄言曹子建，个是洛川神。','',''),('quantangshi-04211','送宋五之问得凉字','駱賓王','quantangshi','','卷5','愿言游泗水，支离去二漳。
道术君所笃，筌蹄余自忘。
雪威侵竹冷，秋爽带池凉。
欲騐离襟切，岐路在他乡。','',''),('quantangshi-04212','宪台出絷寒夜有怀','駱賓王','quantangshi','','卷5','独坐怀明发，长谣苦未安。
自应迷北叟，谁肯问南冠。
生死交情异，殷忧岁序阑。
空余朝夕鸟，相伴夜啼寒。','',''),('quantangshi-04213','送郭少府探得忧字','駱賓王','quantangshi','','卷5','开筵枕德水，辍棹舣仙舟。
贝阙桃花浪，龙门竹箭流。
当歌凄别曲，对酒泣离忧。
还望青门外，空见白云浮。','',''),('quantangshi-04214','冬日过故人任处士书斋','駱賓王','quantangshi','','卷5','神交尚投漆，虚室罢游兰。
网积窗文乱，苔深履迹残。
雪明书帐冷，水静墨池寒。
独此琴台夜，流水为谁弹。','',''),('quantangshi-04215','送刘少府游越州','駱賓王','quantangshi','','卷5','一丘余枕石，三越尔怀铅。
离亭分鹤盖，别岸指龙川。
露下蝉声断，寒来雁影连。
如何沟水上，凄断听离弦。','',''),('quantangshi-04216','赋得白云抱幽石','駱賓王','quantangshi','','卷5','重岩抱危石，幽涧曳轻云。
绕镇仙衣动，飘蓬羽盖分。
锦色连花静，苔光带叶熏。
讵知吴会影，长抱谷城文。','',''),('quantangshi-04217','赋得春云处处生','駱賓王','quantangshi','','卷5','千里年光静，四望春云生。
椠日祥光举，疎云瑞叶轻。
盖阴笼迥树，阵影抱危城。
非将吴会远，飘荡帝乡情。','',''),('quantangshi-04218','在岳咏蝉','駱賓王','quantangshi','','卷5','西陆蝉声唱，南冠客思侵。
那堪玄鬓影，来对白头吟。
露重飞难进，风多响易沈。
无人信高洁，谁为表予心。','',''),('quantangshi-04219','咏水','駱賓王','quantangshi','','卷5','列名通地纪，疎派合天津。
波随月色净，态逐桃花春。
照霞如隐石，映柳似沈鳞。
终当挹上善，属意澹交人。','',''),('quantangshi-04220','同张二咏雁','駱賓王','quantangshi','','卷5','唼藻沧江远，衔卢紫塞长。
雾深迷晓景，风急断秋行。
阵照通宵月，书封几夜霜。
无复能鸣分，空知愧稻粱。','',''),('quantangshi-04221','咏雪','駱賓王','quantangshi','','卷5','龙云玉叶上，鹤雪瑞花新。
影乱铜乌吹，光销玉马津。
含辉明素篆，隐迹表祥轮。
幽兰不可俪，徒自绕阳春。','',''),('quantangshi-04222','咏云酒','駱賓王','quantangshi','','卷5','朔空曾纪历，带地旧疏泉。
色泛临砀瑞，香流赴蜀仙。
款交欣散玉，洽友悦沈钱。
无复中山赏，空吟吴会篇。','',''),('quantangshi-04223','尘灰','駱賓王','quantangshi','','卷5','洛川流雅韵，秦道擅苛威。
听歌梁上动，应律管中飞。
光飘神女袜，影落羽人衣。
愿言心未翳，终冀效轻微。','',''),('quantangshi-04224','秋晨同淄川毛司马秋九咏 秋风','駱賓王','quantangshi','','卷5','紫陌炎氛歇，青苹晚吹浮。
乱竹摇疎影，萦池织细流。
飘香曳舞袖，带粉泛妆楼。
不分君恩绝，纨扇曲中秋。','',''),('quantangshi-04225','秋晨同淄川毛司马秋九咏 秋云','駱賓王','quantangshi','','卷5','南陆铜浑改，西郊玉叶轻。
泛斗瑶光动，临阳瑞色明。
盖阴连凤阙，阵影翼龙城。
讵知时不遇，空伤流滞情。','',''),('quantangshi-04226','秋晨同淄川毛司马秋九咏 秋蝉','駱賓王','quantangshi','','卷5','九秋行已暮，一枝聊暂安。
隐榆非谏楚，噪柳异悲潘。
分形妆薄鬓，镂影饰危冠。
自怜疎影断，寒林夕吹寒。','',''),('quantangshi-04227','秋晨同淄川毛司马秋九咏 秋露','駱賓王','quantangshi','','卷5','玉关寒气早，金塘秋色归。
泛掌光逾净，添荷滴尚微。
变霜凝晓液，承月委圆辉。
别有吴台上，应湿楚臣衣。','',''),('quantangshi-04228','秋晨同淄川毛司马秋九咏 秋月','駱賓王','quantangshi','','卷5','云披玉绳净，月满镜轮圆。
裛露珠晖冷，凌霜桂影寒。
漏彩含疎薄，浮光漾急澜。
西园徒自赏，南飞终未安。','',''),('quantangshi-04229','秋晨同淄川毛司马秋九咏 秋水','駱賓王','quantangshi','','卷5','贝阙寒流彻，玉轮秋浪清。
图云锦色净，写月练花明。
泛曲鵾弦动，随轩凤辖惊。
唯当御沟上，凄断送归情。','',''),('quantangshi-04230','秋晨同淄川毛司马秋九咏 秋萤','駱賓王','quantangshi','','卷5','玉虬分静夜，金萤照晚凉。
含辉疑泛月，带火怯凌霜。
散彩萦虚牖，飘花绕洞房。
下帷如不倦，当解惜余光。','',''),('quantangshi-04231','秋晨同淄川毛司马秋九咏 秋菊','駱賓王','quantangshi','','卷5','擢秀三秋晚，开芳十步中。
分黄俱笑日，含翠共摇风。
碎影涵流动，浮香隔岸通。
金翘徒可泛，玉斝竟谁同。','',''),('quantangshi-04232','秋晨同淄川毛司马秋九咏 秋雁','駱賓王','quantangshi','','卷5','联翩辞海曲，遥曳指江干。
阵去金河冷，书归玉塞寒。
带月凌空易，迷烟逗浦难。
何当同顾影，刷羽泛清澜。','',''),('quantangshi-04233','乐大夫挽词五首 一','駱賓王','quantangshi','','卷5','可叹浮生促，吁嗟此路难。
丘陵一起恨，言笑几时懽。
萧索郊埏晚，荒凉井径寒。
谁当门下客，独见有任安。','',''),('quantangshi-04234','乐大夫挽词五首 二','駱賓王','quantangshi','','卷5','蒿里谁家地，松门何代丘。
百年三万日，一别几千秋。
返照寒无影，穷泉冻不流。','',''),('quantangshi-04235','乐大夫挽词五首 三','駱賓王','quantangshi','','卷5','昔去梅笳发，今来薤露曦。
彤驺朝帝阙，丹旐背王畿。
城郭犹疑是，原陵稍觉非。
九原如可作，千载与谁归。','',''),('quantangshi-04236','乐大夫挽词五首 四','駱賓王','quantangshi','','卷5','一旦先朝菌，千秋掩夜台。
青乌新兆去，白马故人来。
草露当春泣，松风向暮哀。
宁知荒壠外，吊鹤自裴徊。','',''),('quantangshi-04237','乐大夫挽词五首 五','駱賓王','quantangshi','','卷5','忽见泉台路，犹疑水镜悬。
何如开白日，非复覩青天。
华表迎千岁，幽扃送百年。
独嗟流水引，长掩伯牙弦。','',''),('quantangshi-04238','丹阳刺史挽词三首 一','駱賓王','quantangshi','','卷5','百龄嗟倏忽，一旦向山阿。
丹桂销已尽，青松哀更多。
薰风虚听曲，薤露反成歌。
自有藏舟处，谁怜隙驷过。','',''),('quantangshi-04239','丹阳刺史挽词三首 二','駱賓王','quantangshi','','卷5','恻怆恒山羽，留连棣萼篇。
佳城非旧日，京兆即新阡。
城郭三千岁，丘陵几万年。
唯余松柏壠，朝夕起寒烟。','',''),('quantangshi-04240','丹阳刺史挽词三首 三','駱賓王','quantangshi','','卷5','短歌三献曲，长夜九泉台。
此室玄扃掩，何年白日开。
荒郊疎古木，寒隧积陈荄。
独此伤心地，松声薄暮来。','',''),('quantangshi-04241','称心寺','駱賓王','quantangshi','','卷5','征帆恣远寻，逶迤过称心。
凝滞蘅𦶜岸，沿洄樝柚林。
穿溆不厌曲，舣潭惟爱深。
为乐凡几许，听取舟中琴。','',''),('quantangshi-04242','陪润州薛司空丹徒桂明府游招隐寺','駱賓王','quantangshi','','卷5','共寻招隐寺，初识戴颙家。
还依旧泉壑，应改昔云霞。
绿竹寒天笋，红蕉腊月花。
金绳倘留客，为系日光斜。','',''),('quantangshi-04243','棹歌行','駱賓王','quantangshi','','卷5','写月涂黄罢，凌波拾翠通。
镜花摇芰日，衣麝入荷风。
叶密舟难荡，莲疎浦易空。
凤媒羞自托，鸳翼恨难穷。
秋帐灯华翠，倡楼粉色红。
相思无别曲，倂在棹歌中。','',''),('quantangshi-04244','海曲书情','駱賓王','quantangshi','','卷5','薄游倦千里，劳生负百年。
未能槎上汉，讵肯剑游燕。
白云照春海，青山横曙天。
江涛让双璧，渭水掷三钱。
坐惜风光晚，长歌独块然。','',''),('quantangshi-04245','蓬莱镇','駱賓王','quantangshi','','卷5','旅客春心断，边城夜望高。
野楼疑海气，白鹭似江涛。
结绶疲三入，承冠泣二毛。
将飞怜弱羽，欲济乏轻舠。
赖有阳春曲，穷愁且代劳。','',''),('quantangshi-04246','和李明府','駱賓王','quantangshi','','卷5','传闻叶县履，飞向洛阳城。
驰道临层掖，津门对小平。
霞残疑制锦，云度似飘缨。
藻掞潘江澈，尘虚范甑清。
讵怜冲斗气，犹向匣中鸣。','',''),('quantangshi-04247','春晚从李长史游开道林故山','駱賓王','quantangshi','','卷5','幽寻极幽壑，春望陟春台。
云光栖断树，灵影入仙杯。
古藤依格上，野径约山隈。
落蘂飜风去，流莺满树来。
兴阑荀御动，归路起浮埃。','',''),('quantangshi-04248','冬日野望','駱賓王','quantangshi','','卷5','故人无与晤，安步陟山椒。
野静连云卷，川明断雾销。
灵岩闻晓籁，洞浦涨秋潮。
三江归望断，千里故乡遥。
劳歌徒自奏，客魂谁为招。','',''),('quantangshi-04249','晚渡黄河','駱賓王','quantangshi','','卷5','千里寻归路，一苇乱平源。
通波连马颊，迸水急龙门。
照日荣光净，惊风瑞浪翻。
棹唱临风断，樵讴入听喧。
岸迥秋霞落，潭深夕雾繁。
谁堪逝川上，日暮不归魂。','',''),('quantangshi-04250','宿山庄','駱賓王','quantangshi','','卷5','金陵一超忽，玉烛几还周。
露积吴台草，风入郢门楸。
林虚宿断雾，磴险挂悬流。
拾青非汉策，化缁类秦裘。
牵迹犹多蹇，劳生未寡尤。
独此他乡梦，空山明月秋。','',''),('quantangshi-04251','晚度天山有怀京邑','駱賓王','quantangshi','','卷5','忽上天山路，依然想物华。
云疑上苑叶，雪似御沟花。
行叹戎麾远，坐怜衣带赊。
交河浮绝塞，弱水浸流沙。
旅思徒漂梗，归期未及瓜。
宁知心断绝，夜夜泣胡笳。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-04252','夕次蒲类津','駱賓王','quantangshi','','卷5','二庭归望断，万里客心愁。
山路犹南属，河源自北流。
晚风连朔气，新月照边秋。
竈火通军壁，烽烟上戍楼。
龙庭但苦战，燕颔会封侯。
莫作兰山下，空令汉国羞。','',''),('quantangshi-04253','远使海曲春夜多怀','駱賓王','quantangshi','','卷5','长啸三春晚，端居百虑盈。
未安胡蝶梦，遽切鲁禽情。
别岛连寰海，离魂断戍城。
流星疑伴使，低月似依营。
怀禄宁期达，牵时匪狥名。
艰虞行已远，时迹自相惊。','',''),('quantangshi-04254','早发诸暨','駱賓王','quantangshi','','卷5','征夫怀远路，夙驾上危峦。
薄烟横绝巘，轻冻澁回湍。
野雾连空暗，山风入曙寒。
帝城临灞涘，禹穴枕江干。
橘性行应化，蓬心去不安。
独掩穷途泪，长歌行路难。','',''),('quantangshi-04255','望月有所思','駱賓王','quantangshi','','卷5','九秋凉风肃，千里月华开。
圆光随露湛，碎影逐波来。
似霜明玉砌，如镜写珠胎。
晚色依关近，边声杂吹哀。
离居分照耀，怨绪共裴徊。
自绕南飞羽，空忝北堂才。','',''),('quantangshi-04256','送吴七游蜀','駱賓王','quantangshi','','卷5','日观分齐壤，星桥接蜀门。
桃花嘶别路，竹叶泻离樽。
夏老兰犹茂，秋深柳尚繁。
雾销山望迥，风高野听喧。
劳歌徒欲奏，赠别竟无言。
唯有当秋月，空照野人园。','',''),('quantangshi-04257','西行别东台详正学士','駱賓王','quantangshi','','卷5','意气坐相亲，关河别故人。
客似秦川上，歌疑易水滨。
塞荒行辨玉，台远尚名轮。
泄井怀边将，寻源重汉臣。
上苑梅花早，御沟杨柳新。
只应持此曲，别作边城春。','',''),('quantangshi-04258','和王记室从赵王春日游陀山寺','駱賓王','quantangshi','','卷5','鸟旟陪访道，鹫岭狎栖真。
四禅明静业，三空广胜因。
祥河疎叠涧，慧日皎重轮。
叶暗龙宫密，花明鹿苑春。
雕谈筌奥旨，妙辩漱玄津。
雅曲终难和，徒自奏巴人。','',''),('quantangshi-04259','夏日夜忆张二','駱賓王','quantangshi','','卷5','伏枕忧思深，拥膝独长吟。
烹鲤无尺素，筌鱼劳寸心。
疎麻空有折，芳桂湛无斟。
广庭含夕气，闲宇澹虚阴。
织虫垂夜砌，惊鸟栖暝林。
驩娱百年促，羁病一生侵。
讵堪孤月夜，流水入鸣琴。','',''),('quantangshi-04260','寒夜独坐游子多怀简知己','駱賓王','quantangshi','','卷5','故乡眇千里，离忧积万端。
鹑服长悲碎，蜗庐未卜安。
富钩徒有想，贫铗为谁弹。
柳秋风叶脆，荷晓露文团。
晚金丛岸菊，余佩下幽兰。
伐木伤心易，维桑归去难。
独有孤明月，时照客庭寒。','',''),('quantangshi-04261','在军中赠先还知己','駱賓王','quantangshi','','卷5','蓬转俱行役，瓜时独未还。
魂迷金阙路，望断玉门关。
献凯多慙霍，论封几谢班。
风尘催白首，岁月损红颜。
落雁低秋塞，惊凫起暝湾。
胡霜如剑锷，汉月似刀环。
别后边庭树，相思几度攀。','',''),('quantangshi-04262','秋日山行简梁大官','駱賓王','quantangshi','','卷5','乘马陟层阜，回首睇山川。
攒峰衔宿雾，叠巘架寒烟。
百重含翠色，一道落飞泉。
香吹分岩桂，鲜云抱石莲。
地偏心易远，致默体逾玄。
得性虚游刃，忘言已弃筌。
弹冠劳巧拙，结绶倦牵缠。
不如从四皓，丘中鸣一弦。','',''),('quantangshi-04263','晚泊江镇','駱賓王','quantangshi','','卷5','四运移阴律，三翼泛阳侯。
荷香销晚夏，菊气入新秋。
夜乌喧粉堞，宿雁下芦洲。
海雾笼边徼，江风绕戍楼。
转蓬惊别渚，徙橘怆离忧。
魂飞灞陵岸，泪尽洞庭流。
振影希鸿陆，逃名谢蚁丘。
还嗟帝乡远，空望白云浮。','',''),('quantangshi-04264','浮槎','駱賓王','quantangshi','','卷5','昔负千寻质，高临九仞峰。
真心凌晚桂，劲节掩寒松。
忽值风飙折，坐为波浪冲。
摧残空有恨，拥肿遂无庸。
渤海三千里，泥沙几万重。
似舟飘不定，如梗泛何从。
仙客终难托，良工岂易逢。
徒怀万乘器，谁为一先容。','',''),('quantangshi-04265','晚泊河曲','駱賓王','quantangshi','','卷5','三秋倦行役，千里泛归潮。
通波竹箭水，轻舸木兰桡。
金堤连曲岸，贝阙影浮桥。
水净千年近，星飞五老遥。
叠花开宿浪，浮叶下凉飙。
浦荷疎晚菂，津柳渍寒条。
恓惶劳梗泛，凄断倦蓬飘。
仙槎不可托，河上独长谣。','',''),('quantangshi-04266','早发淮口望盱眙','駱賓王','quantangshi','','卷5','养蒙分四渎，习坎奠三荆。
徙帝留余地，封王表旧城。
岸昏涵蜃气，潮满应鸡声。
洲迥连沙静，川虚积溜明。
一朝从捧檄，千里倦悬旌。
背流桐柏远，逗浦木兰轻。
小山迷隐路，大块切劳生。
唯有贞心在，独映寒潭清。','',''),('quantangshi-04267','边城落日','駱賓王','quantangshi','','卷5','紫塞流沙北，黄图灞水东。
一朝辞俎豆，万里逐沙蓬。
候月恒持满，寻源屡凿空。
野昏边气合，烽迥戍烟通。
膂力风尘倦，疆场岁月穷。
河流控积石，山路远崆峒。
壮志凌苍兕，精诚贯白虹。
君恩如可报，龙剑有雌雄。','',''),('quantangshi-04268','宿温城望军营','駱賓王','quantangshi','','卷5','虏地寒胶折，边城夜柝闻。
兵符关帝阙，天策动将军。
塞静胡笳彻，沙明楚练分。
风旗翻翼影，霜剑转龙文。
白羽摇如月，青山断若云。
烟疎疑卷幔，尘灭似销氛。
投笔怀班业，临戎想顾勋。
还应雪汉耻，持此报明君。','',''),('quantangshi-04269','过故宋','駱賓王','quantangshi','','卷5','旧国千年尽，荒城四望通。
云浮非隐帝，日举类游童。
绮琴朝化洽，祥石夜论空。
马去遥奔郑，蛇分近带丰。
池文敛束水，竹影漏寒丛。
园兔承行月，川禽避断风。
故宋诚难定，从梁事未工。
唯当过周客，独愧吴台空。','',''),('quantangshi-04270','边夜有怀','駱賓王','quantangshi','','卷5','汉地行逾远，燕山去不穷。
城荒犹筑怨，碣毁尚铭功。
古戍烟尘满，边庭人事空。
夜关明陇月，秋塞急胡风。
倚伏良难定，荣枯岂易通。
旅魂劳泛梗，离恨断征蓬。
苏武封犹薄，崔駰宦不工。
惟余北叟意，欲寄南飞鸿。','',''),('quantangshi-04271','伤祝阿王明府','駱賓王','quantangshi','','卷5','洛川真气上，重泉惠政融。
含章光后烈，继武嗣前雄。
与善良难验，生涯忽易穷。
翔凫犹化履，狎雉尚驯童。
钱满荒阶绿，尘浮虚帐红。
夏余将宿草，秋近未惊蓬。
烟晦泉门闭，日尽夜台空。
谁堪孤陇外，独听白杨风。','',''),('quantangshi-04272','四月八日题七级','駱賓王','quantangshi','','卷5','化城分鸟堞，香阁俯龙川。
复栋侵黄道，重檐架紫烟。
铭书非晋代，壁画是梁年。
霸略今何在，王宫尚岿然。
二帝曾游圣，三卿是偶贤。
因兹游胜侣，超彼托良缘。
我出有为界，君登非想天。
悠悠青旷里，荡荡白云前。
今日经行处，曲音号盖烟。','',''),('quantangshi-04273','和孙长史秋日卧病','駱賓王','quantangshi','','卷5','霍第疏天府，潘园近帝台。
调弦三妇至，置驿五侯来。
尚想欢娱洽，吁嗟岁月催。
金坛分上将，玉帐引瓌材。
决胜鲸波静，腾谋鸟谷开。
白云淮水外，紫陌灞陵隈。
节变惊衰柳，笳繁思落梅。
调神和玉烛，掞藻握珠胎。
怅矣欣怀土，居然欲死灰。
还因承雅曲，暂喜跃沈鳃。','',''),('quantangshi-04274','饯郑安阳入蜀','駱賓王','quantangshi','','卷5','彭山折坂外，井络少城隈。
地是三巴俗，人非百里材。
畏途君怅望，岐路我裴徊。
心赏风烟隔，容华岁月催。
遥遥分凤野，去去转龙媒。
遗锦非前邑，鸣琴即旧台。
剑门千仞起，石路五丁开。
海客乘槎渡，仙童驭竹回。
魂将离鹤远，思逐断猿哀。
唯有双凫舄，飞去复飞来。','',''),('quantangshi-04275','咏怀','駱賓王','quantangshi','','卷5','少年识事浅，不知交道难。
一言芬若桂，四海臭如兰。
宝剑思存楚，金锤许报韩。
虚心徒有托，循迹谅无端。
太息关山险，吁嗟岁月阑。
忘机殊会俗，守拙异怀安。
阮籍空长啸，刘琨独未懽。
十步庭芳敛，三秋陇月团。
槐疎非尽意，松晚夜凌寒。
悲调弦中急，穷愁醉里宽。
莫将流水引，空向俗人弹。','',''),('quantangshi-04276','春日离长安客中言怀','駱賓王','quantangshi','','卷5','年华开早律，霁色荡芳晨。
城阙千门晓，山河四望春。
御沟通太液，戚里对平津。
宝瑟调中妇，金罍引上宾。
剧谈推曼倩，惊坐揖陈遵。
意气一言合，风期万里亲。
自惟安直道，守拙忌因人。
谈器非先木，图荣异后薪。
揶揄慙路鬼，憔悴切波臣。
玄草终疲汉，乌裘几滞秦。
生涯无岁月，岐路有风尘。
还嗟太行道，处处白头新。','',''),('quantangshi-04277','夕次旧吴','駱賓王','quantangshi','','卷5','维舟背楚服，振策下吴畿。
盛德弘三让，雄图枕九围。
黄池通霸迹，赤壁畅戎威。
文物俄迁谢，英灵有盛衰。
行叹鸱夷没，遽惜湛卢飞。
地古烟尘暗，年深馆宇稀。
山川四望是，人事一朝非。
悬剑空留信，亡珠尚识机。
郑风遥可托，关月眇难依。
西北云逾滞，东南气转微。
徒怀伯通隐，多谢买臣归。
唯有荒台露，薄暮湿征衣。','',''),('quantangshi-04278','早秋出塞寄东台详正学士','駱賓王','quantangshi','','卷5','促驾逾三水，长驱望五原。
天阶分斗极，地理接楼烦。
溪月明关陇，戎云聚塞垣。
山川殊物候，风壤异凉喧。
戍古秋尘合，沙寒宿雾繁。
昔余迷学步，投迹忝词源。
兰渚浮延阁，蓬山款禁园。
彯缨陪绂冕，载笔偶璵璠。
汲冢宁详蠹，秦牢讵辨冤。
一朝从篚服，千里骛轻轩。
乡梦随魂断，边声入听喧。
南图终铩翮，北上遽催辕。
吊影慙连茹，浮生倦触藩。
数奇何以托，桃李自无言。','',''),('quantangshi-04279','幽絷书情通简知己','駱賓王','quantangshi','','卷5','昔岁逢杨意，观光贵楚材。
穴疑丹凤起，场似白驹来。
一命沦骄饵，三缄慎祸胎。
不言劳倚伏，忽此遘邅回。
骢马刑章峻，苍鹰狱吏猜。
绝缣非易辨，疑璧果难裁。
揆画慙周道，端忧滞夏台。
生涯一灭裂，岐路几裴徊。
青陆春芳动，黄沙旅思催。
圆扉长寂寂，疎网尚恢恢。
入穽先摇尾，迷津正曝腮。
覆盆徒望日，蛰户未经雷。
霜歇兰犹败，风多木屡摧。
地幽蚕室闭，门静雀罗开。
自悯秦冤痛，谁怜楚奏哀。
汉阳穷鸟客，梁甫卧龙才。
有气还冲斗，无时会凿坏。
莫言韩长孺，长作不然灰。','',''),('quantangshi-04280','久戍边城有怀京邑','駱賓王','quantangshi','','卷5','扰扰风尘地，遑遑名利途。
盈虚一易舛，心迹两难俱。
弱龄小山志，宁期大丈夫。
九微光贲玉，千仞忽弹珠。
棘寺游三礼，蓬山簉八儒。
怀铅慙后进，投笔愿前驱。
北走非通赵，西之似化胡。
锦车朝促候，刁斗夜传呼。
战士青丝络，将军黄石符。
连星入宝剑，半月上雕弧。
拜井开疎勒，鸣桴动密须。
戎机习短蔗，祆祲静长榆。
季月炎初尽，边亭草早枯。
层阴笼古木，穷色变寒芜。
海鹤声嘹唳，城乌尾毕逋。
葭繁秋色引，桂满夕轮虚。
行役风霜久，乡园梦想孤。
灞池遥夏国，秦海望阳纡。
沙塞三千里，京城十二衢。
杨沟连凤阙，槐路拟鸿都。
璧殿规宸象，金堤法斗枢。
云浮西北盖，月照东南隅。
宝帐垂连理，银牀转辘轳。
广筵留上客，丰馔引中厨。
漏缓金徒箭，娇繁玉女壶。
秋涛飞喻马，秋水泛仙舻。
意气风云合，言忘道术趋。
共矜名已泰，讵肯沫相濡。
有志慙雕朽，无庸类散樗。
关山暂超忽，形影叹艰虞。
结网空知羡，图荣岂自诬。
忘情同塞马，比德类宛驹。
陇阪肝肠绝，阳关亭候迂。
迷魂惊落雁，离恨断飞凫。
春去荣华尽，年来岁月芜。
边愁伤郢调，乡思绕吴歈。
河气通中国，山途限外区。
相思若可寄，冰泮有衔芦。','',''),('quantangshi-04281','在军登城楼','駱賓王','quantangshi','','卷5','城上风威冷，江中水气寒。
戎衣何日定，歌舞入长安。','',''),('quantangshi-04282','于易水送人','駱賓王','quantangshi','','卷5','此地别燕丹，壮士髪冲冠。
昔时人已没，今日水犹寒。','',''),('quantangshi-04283','咏镜','駱賓王','quantangshi','','卷5','写月无芳桂，照日有花菱。
不持光谢水，翻将影学冰。','',''),('quantangshi-04284','挑灯杖','駱賓王','quantangshi','','卷5','禀质非贪热，焦心岂惮熬。
终知不自润，何处用脂膏。','',''),('quantangshi-04285','咏尘','駱賓王','quantangshi','','卷5','凌波起罗袜，含风染素衣。
别有知音调，闻歌应自飞。','',''),('quantangshi-04286','翫初月','駱賓王','quantangshi','','卷5','忌满光先缺，乘昏影暂流。
既能明似镜，何用曲如钩。','',''),('quantangshi-04287','送别','駱賓王','quantangshi','','卷5','寒更承夜永，凉夕向秋澄。
离心何以赠，自有玉壶冰。','',''),('quantangshi-04288','忆蜀地佳人','駱賓王','quantangshi','','卷5','东西吴蜀关山远，鱼来雁去两难闻。
莫怪常有千行泪，只为阳台一片云。','',''),('quantangshi-04289','咏鹅','駱賓王','quantangshi','','卷5','鹅，鹅，鹅，曲项向天歌。
白毛浮绿水，红掌拨清波。','',''),('quantangshi-04290','奉和圣制夏日游石淙山','武三思','quantangshi','','卷5','此地岩壑数千重，吾君驾鹤□乘龙。
掩暎叶光含翡翠，参差石影带芙蓉。
白日将移冲叠巘，玄云欲度碍高峰。
对酒鸣琴追野趣，时闻清吹入长松。','',''),('quantangshi-04291','仙鹤篇','武三思','quantangshi','','卷5','白鹤乘空何处来？青田紫盖本相依。
缑山七月虽长去，辽水千年会忆归。
缑山杳杳翔寥廓，辽水累累叹城郭。
经随羽客步丹丘，曾逐仙人游碧落。
迢迢碧落断氛埃，霞堂云阁几重开。
欲寻东海黄金竈，仍向西山白玉台。
九臯独唳方清切，五里惊羣俄断绝。
月下分行似度云，风前扬影疑回雪。
风前月下路漫漫，水宿云翔去几般。
宛转能倾吴国市，裴回巧拂汉皇坛。
琴中作曲从来易，鼓里传声有甚难。
夜夜恒飞银汉曲，朝朝常饮玉池澜。
别有闻箫出紫烟，还如化履上青天。
霜毛忽控三神下，玉羽俄看二客旋。
燕雀终迷横海志，蜉蝣岂识在阴年。
莫言一举轻千里，为与三山送九仙。','',''),('quantangshi-04292','宴龙泓','武三思','quantangshi','','卷5','登临开胜托，眺瞩尽良游。
岩崿萦纡上，澄潭屈曲流。
泛兰清兴洽，折桂野文遒。
别后相思处，崎岖碧涧幽。','',''),('quantangshi-04293','凝碧池侍宴应制得出水槎','武三思','quantangshi','','卷5','彼木生何代，为槎复几年。
欲乘银汉曲，先泛玉池边。
拥溜根横岸，沈波影倒悬。
无劳问蜀客，此处即高天。','',''),('quantangshi-04294','奉和宴小山池赋得溪字应制','武三思','quantangshi','','卷5','年光开碧沼，云色歛青溪。
冻解鱼方戏，风暄鸟欲啼。
岩泉飞野鹤，石镜舞山鸡。
柳发龙鳞出，松新麈尾齐。
九韶从此验，三月定应迷。','',''),('quantangshi-04295','奉和过梁王宅即目应制','武三思','quantangshi','','卷5','岩居多水石，野宅满风烟。
本谓开三径，俄欣降九天。
穿林移步辇，拂岸转行旃。
凤竹初垂箨，龟河未吐莲。
愿持山作寿，恒用劫为年。','',''),('quantangshi-04296','奉和春日游龙门应制','武三思','quantangshi','','卷5','凤架临香地，龙舆上翠微。
星宫含雨气，月殿抱春辉。
碧涧长虹下，雕梁早燕归。
云疑浮宝盖，石似拂天衣。
露草侵阶长，风花遶席飞。
日斜宸赏洽，清吹入重闱。','',''),('quantangshi-04297','秋日于天中寺寻复礼上人','武三思','quantangshi','','卷5','妙域三时殿，香岩七宝宫。
金绳先界道，玉柄即谈空。
喻筏知何极，传灯竟不穷。
弥天高义远，初地胜因通。
理诣归一处，心行不二中。
有无双惑遣，真俗两缘同。
摘叶疑焚翠，投花若散红。
网珠遥映日，檐铎近吟风。
定沼寒光素，禅枝暝色葱。
愿随方便力，长冀释尘笼。','',''),('quantangshi-04298','句','武三思','quantangshi','','卷5','云螭非易匹，月驷本难俦。','',''),('quantangshi-04299','奉和圣制夏日游石淙山','張易之','quantangshi','','卷5','六龙骧首晓骎骎，七圣陪轩集颍阴。
千丈松萝交翠幕，一丘山水当鸣琴。
青鸟白云王母使，垂藤断葛野人心。
山中日暮幽岩下，泠然香吹落花深。','',''),('quantangshi-04300','侍从过公主南宅侍宴探得风字应制','張易之','quantangshi','','卷5','逐赏平阳第，鸣笳上苑东。
鸟吟千户竹，蝶舞百花丛。
时攀小山桂，共挹大王风。
坐客无劳起，秦箫曲未终。','',''),('quantangshi-04301','出塞','張易之','quantangshi','','卷5','侠客重恩光，骏马饰金装。
瞥闻传羽檄，驰突救边荒。
转战磨笄地，横行戴斗乡。
将军占太白，小妇怨流黄。
騕褭青丝骑，娉婷红粉妆。
一春莺度曲，八月雁成行。
谁堪坐秋思，罗袖拂空牀。','',''),('quantangshi-04302','泛舟侍宴应制','張易之','quantangshi','','卷5','平明出御沟，解缆坐回舟。
绿水澄明月，红罗结绮楼。
弦歌争浦入，冠盖逐川流。
白鱼臣作伴，相对舞王舟。','',''),('quantangshi-04303','奉和圣制夏日游石淙山','張昌宗','quantangshi','','卷5','云车遥裔三珠树，帐殿交阴八桂丛。
磵险泉声疑度雨，川平桥势若晴虹。
叔夜弹琴歌白雪，孙登长啸韵清风。
即此陪欢游阆苑，无劳辛苦向崆峒。','',''),('quantangshi-04304','少年行','張昌宗','quantangshi','','卷5','少年不识事，落魄游韩魏。
珠轩流水车，玉勒浮云骑。
纵横意不一，然诺心无二。
白璧赠穰苴，黄金奉毛遂。
妙舞飘龙管，清歌吟凤吹。
三春小苑游，千日中山醉。
直言身可沈，谁论名与利。
依倚孟尝君，自知能市义。','',''),('quantangshi-04305','太平公主山亭侍宴','張昌宗','quantangshi','','卷5','淮南有小山，嬴女隐其间。
折桂芙蓉浦，吹箫明月湾。
扇掩将雏曲，钗承堕马鬟。
欢情本无限，莫掩洛城关。','',''),('quantangshi-04306','奉和圣制夏日游石淙山','薛曜','quantangshi','','卷5','玉洞幽寻更是天，朱霞绿景镇韶年。
飞花藉藉迷行路，啭鸟遥遥作管弦。
雾隐长林成翠幄，风吹细雨即虹泉。
此中碧酒恒参圣，浪道昆山别有仙。','',''),('quantangshi-04307','子夜冬歌','薛曜','quantangshi','','卷5','朔风扣羣木，严霜凋百草。
借问月中人，安得长不老。','',''),('quantangshi-04308','舞马篇','薛曜','quantangshi','','卷5','星精龙种竞腾骧，双眼黄金紫艳光。
一朝逢遇升平代，伏皂衔图事帝王。
我皇盛德苞六宇，俗泰时和虞石拊。
昔闻九代有余名，今日百兽先来舞。
钩陈周衞俨旌旄，钟鎛陶匏声殷地。
承云嘈囋骇日灵，调露铿鈜动天驷。
奔尘飞箭若麟螭，蹑景追风忽见知。
咀衔拉铁并权奇，被服雕章何陆离。
紫玉鸣珂临宝镫，青丝彩络带金羁。
随歌鼓而电惊，逐丸劒而飙驰。
态聚𨄳还急，骄凝骤不移。
光敌白日下，气拥绿烟垂。
婉转盘跚殊未已，悬空步骤红尘起。
惊凫翔鹭不堪俦，矫凤回鸾那足拟。
蘅垂桂褭香氛氲，长鸣汗血尽浮云。
不辞辛苦来东道，祗为箫韶朝夕闻。
阊阖间，玉台侧，承恩煦兮生光色。
鸾锵锵，车翼翼，备国容兮为戎饰。
充云翘兮天子庭，荷日用兮情无极。
吉良乘兮一千岁，神是得兮天地期。
大易占云南山寿，䟃𧽼共乐圣明时。','',''),('quantangshi-04309','正夜侍宴应诏','薛曜','quantangshi','','卷5','重关钟漏通，夕敞凤皇宫。
双阙祥烟里，千门明月中。
酒杯浮湛露，歌曲唱风流。
侍臣咸醉止，恒慙恩遇崇。','',''),('quantangshi-04310','送道士入天台','薛曜','quantangshi','','卷5','洛阳陌上多离别，蓬莱山下足波潮。
碧海桑田何处在？笙歌一听一遥遥。','',''),('quantangshi-04311','奉和圣制夏日游石淙山','楊敬述','quantangshi','','卷5','山中别有神仙地，屈曲幽深碧涧垂。
岩前暂驻黄金辇，席上还飞白玉巵。
远近风泉俱合杂，高低云石共参差。
林壑偏能留睿赏，长天莫遽下丹曦。','',''),('quantangshi-04312','奉和圣制夏日游石淙山','于季子','quantangshi','','卷5','九旗云布临嵩室，万骑星陈集颍川。
瑞液含滋登禹膳，飞流荐响入虞弦。
山扉野径朝花积，帐殿帷宫夏叶连。
微臣献寿迎千寿，愿奉尧年倚万年。','',''),('quantangshi-04313','咏云','于季子','quantangshi','','卷5','瑞云千里映，祥辉四望新。
随风乱鸟翅，泛水结鱼鳞。
布叶疑临夏，开花讵待春。
愿得承嘉景，无令掩桂轮。','',''),('quantangshi-04314','咏萤','于季子','quantangshi','','卷5','卉草诚幽贱，枯朽绝因依。
忽逢借羽翼，不觉生光辉。
直念恩华重，长嗟报効微。
方思助日月，为许愿曾飞。','',''),('quantangshi-04315','早春洛阳答杜审言','于季子','quantangshi','','卷5','梓泽年光往复来，杜霸游人去不回。
若非载笔登麟阁，定是吹箫伴凤台。
路傍桃李花犹嫩，波上芙蕖叶未开。
分明寄语长安道，莫教留滞洛阳才。','',''),('quantangshi-04316','咏项羽','于季子','quantangshi','','卷5','北伐虽全赵，东归不王秦。
空歌拔山力，羞作渡江人。','',''),('quantangshi-04317','咏汉高祖','于季子','quantangshi','','卷5','百战方夷项，三章且代秦。
功归萧相国，气尽戚夫人。','',''),('quantangshi-04318','南行别弟','于季子','quantangshi','','卷5','万里人南去，三春雁北飞。
不知何岁月？得与尔同归。','',''),('quantangshi-04319','长信宫中树','喬知之','quantangshi','','卷5','婀娜当轩树，䒠茸倚兰殿。
叶艳九春华，香摇五明扇。
余花鸟弄尽，新叶虫书徧。
零落心自知，芳菲君不见。','',''),('quantangshi-04320','下山逢故夫','喬知之','quantangshi','','卷5','妾身本薄命，轻弃城南隅。
庭前厌芍药，山上采蘼芜。
春风罥纨袖，零露湿罗襦。
羞将憔悴日，提笼逢故夫。','',''),('quantangshi-04321','巫山高','喬知之','quantangshi','','卷5','巫山十二峰，参差互隐见。
浔阳几千里，周览忽已徧。
想像神女姿，摘芳共珍荐。
楚云何逶迤，红树日葱蒨。
楚云没湘源，红树断荆门。
郢路不可见，况复夜闻猨。','',''),('quantangshi-04322','弃妾篇','喬知之','quantangshi','','卷5','妾本丛台右，君在雁门陲。
悠悠淇水曲，彩燕入桑枝。
不因媒结好，本以容相知。
容谢君应去，情移会有离。
还君结缕带，归妾识成诗。
此物虽轻贱，不用使人嗤。','',''),('quantangshi-04323','苦寒行','喬知之','quantangshi','','卷5','胡天夜清迥，孤云独飘扬。
遥裔出雁关，逶迤含晶光。
阴陵久裴回，幽都无多阳。
初寒冻巨海，杀气流大荒。
朔马饮寒冰，行子履胡霜。
路有从役倦，卧死黄沙场。
羁旅因相依，恸之泪霑裳。
由来从军行，赏存不赏亡。
亡者诚已矣，徒令存者伤。','',''),('quantangshi-04324','从军行','喬知之','quantangshi','','卷5','南庭结白露，北风扫黄叶。
此时鸿雁来，惊鸣催思妾。
曲房理针线，平砧捣文练。
鸳绮裁易成，龙乡信难见。
窈窕九重闺，寂寞十年啼。
纱窗白云宿，罗幌月光栖。
云月隐微微，夜上流黄机。
玉霜冻珠履，金吹薄罗衣。
汉家已得地，君去将何事。
宛转结蚕书，寂寥无雁使。
生平荷恩信，本为荣华进。
况复落红颜，蝉声催绿鬓。','',''),('quantangshi-04325','拟古赠陈子昂','喬知之','quantangshi','','卷5','惸惸孤形影，悄悄独游心。
以此从王事，常与子同衾。
别离三河间，征战二庭深。
胡天夜雨霜，胡雁晨南翔。
节物感离居，同衾违故乡。
南归日将远，北方尚蓬飘。
孟秋七月时，相送出外郊。
海风吹凉木，边声响梢梢。
勤役千万里，将临五十年。
心事为谁道，抽琴歌坐筵。
一弹再三叹，宾御泪潺湲。
送君竟此曲，从兹长绝弦。','',''),('quantangshi-04326','定情篇','喬知之','quantangshi','','卷5','共君结新婚，岁寒心未卜。
相与游春园，各随情所逐。
君爱菖蒲花，妾感苦寒竹。
菖花多艳姿，寒竹有贞叶。
此时妾比君，君心不如妾。
簪玉步河堤，妖韶援绿荑。
凫雁将子游，莺燕从双栖。
君念春光好，妾向春光啼。
君时不得意，弃妾还金闺。
结言本同心，悲欢何未齐。
怨咽前致辞，愿得申所悲。
人间丈夫易，世路妇难为。
始如经天月，终若流星驰。
天月相终始，流星无定期。
长信佳丽人，失意非蛾眉。
庐江小吏妇，非关织作迟。
本愿长相对，今已长相思。
复有游宦子，结援从梁陈。
燕居崇三朝，去来历九春。
誓心妾终始，蚕桑奉所亲。
归愿未克从，黄金赠路人。
洁妇怀明义，从泛河之津。
于今千万年，谁当问水滨。
更忆娼家楼，夫婿事封侯。
去时恩灼灼，去罢心悠悠。
不怜妾岁[晏]，十载陇西头。
以兹常惕惕，百虑恒盈积。
由来共结褵，几人同匪石。
故岁雕梁燕，双去今来只。
今日玉庭梅，朝红暮成碧。
碧荣始芬敷，黄叶已淅沥。
何用念芳春，芳春有流易。
何用重欢娱，欢娱俄戚戚。
家本巫山阳，归去路何长。
叙言情未尽，采菉已盈筐。
桑榆日及景，物色盈高冈。
下有碧流水，上有丹桂香。
桂花不须折，碧流清且洁。
赠君比芳菲，爱惠常不歇。
赠君比潺湲，相思无断绝。
妾有秦家镜，宝匣装珠玑。
鉴来年二八，不记易阴晖。
妾无光寂寂，委照影依依。
今日持为赠，相识莫相违。','',''),('quantangshi-04327','绿珠篇','喬知之','quantangshi','','卷5','石家金谷重新声，明珠十斛买娉婷。
此日可怜君自许，此时可喜得人情。
君家闺阁不曾难，常将歌舞借人看。
意气雄豪非分理，骄矜势力横相干。
辞君去君终不忍，徒劳掩袂伤铅粉。
百年离别在高楼，一旦红颜为君尽。','',''),('quantangshi-04328','和李侍郎古意','喬知之','quantangshi','','卷5','妾家巫山隔汉川，君度南庭向胡苑。
高楼迢遰想金天，河汉昭回更怆然。
夜如何其夜未央，闲花照月愁洞房。
自矜夫婿胜王昌，三十曾作侍中郎。
一从流落戍渔阳，怀哉万恨结中肠。
南山幂幂兔丝花，北陵青青女萝树。
由来花叶同一根，今日枝条分两处。
三星差池光照灼，北斗西指秋云薄。
茎枯花谢枝憔悴，香销色尽花零落。
美人长叹艳容萎，含情收取摧折枝。
调丝独弹声未移，感君行坐星岁迟。
闺中宛转今若斯，谁能为报征人知。','',''),('quantangshi-04329','倡女行','喬知之','quantangshi','','卷5','石榴酒，葡萄浆，兰桂芳，茱萸香。
愿君驻金鞍，暂此共年芳。
愿君解罗襦，一醉同匡牀。
文君正新寡，结念在歌倡。
昨宵绮帐迎韩寿，今朝罗袖引潘郎。
莫吹羌笛惊邻里，不用琵琶喧洞房。
且歌新夜曲，莫弄楚明光。
此曲怨且艳，哀音断人肠。','',''),('quantangshi-04330','羸骏篇','喬知之','quantangshi','','卷5','喷玉长鸣西北来，自言当代是龙媒。
万里铁关行入贡，九重金阙为君开。
蹀躞朝驰过上苑，䟃𧽼暝走发章台。
玉勒金鞍荷装饰，路傍观者无穷极。
小山桂树比权奇，上林桃花况颜色。
忽闻天将出龙沙，汉主持将驾鼓车。
去去山川劳日夜，遥遥关塞断烟霞。
山川关塞十年征，汗血流离赴月营。
肌肤销远道，膂力尽长城。
长城日夕苦风霜，中有连年百战场。
摇珂啮勒金羁尽，争锋足顿铁菱伤。
垂耳罢轻赍，弃置在寒溪。
大宛蒲海北，滇壑隽崖西。
沙平留缓步，路远暗频嘶。
从来力尽君须弃，何必寻途我已迷。
岁岁年年奔远道，朝朝暮暮催疲老。
扣冰晨饮黄河源，拂雪夜食天山草。
楚水澶溪征战事，吴塞乌江辛苦地。
持来报主不辞劳，宿昔立功非重利。
丹心素节本无求，长鸣向君君不留。
祗应澶漫归田里，万里低昂任生死。
君王倘若不见遗，白骨黄金犹可市。','',''),('quantangshi-04331','铜雀妓','喬知之','quantangshi','','卷5','金阁惜分香，铅华不重妆。
空余歌舞地，犹是为君王。
哀弦调已绝，艳曲不须长。
共看西陵暮，秋烟起白杨。','',''),('quantangshi-04332','侍宴应制得分字','喬知之','quantangshi','','卷5','紫禁肃晴氛，朱楼落晓云。
豫游龙驾转，天乐凤箫闻。
竹外仙亭出，花间辇路分。
微臣一何幸，词赋奉明君。','',''),('quantangshi-04333','梨园亭子侍宴','喬知之','quantangshi','','卷5','年光陌上发，香辇禁中游。
草绿鸳鸯殿，花红翡翠楼。
天杯承露酌，仙管杂风流。
今日陪欢豫，皇恩不可酬。','',''),('quantangshi-04334','和苏员外寓直','喬知之','quantangshi','','卷5','自昔重为郎，伊人练国章。
三旬登建礼，五夜直明光。
墨草尚书奏，衣飘侍御香。
开轩竹气静，拂簟蕙风凉。
晓漏离阊阖，鸣钟出未央。
从来宿台上，天子贵文强。','',''),('quantangshi-04335','哭故人','喬知之','quantangshi','','卷5','生死久离居，凄凉历旧庐。
叹兹三径断，不践十年余。
古木巢禽合，荒庭爱客疎。
匣留弹罢劒，牀积读残书。
玉没终无像，兰言强问虚。
平生不得意，泉路复何如。','',''),('quantangshi-04336','折杨柳','喬知之','quantangshi','','卷5','可怜濯濯春杨柳，攀折将来就纤手。
妾容与此同盛衰，何必君恩能独久。','',''),('quantangshi-04337','人日登高','喬侃','quantangshi','','卷5','仆本多悲者，年来不悟春。
登高一游目，始觉柳条新。
杜陵犹识汉，桃源不辨秦。
蹔若升云雾，还似出嚣尘。
赖得烟霞气，淹留攀桂人。','',''),('quantangshi-04338','出塞','喬備','quantangshi','','卷5','沙场三万里，猛将五千兵。
旌断冰溪戍，笳吹铁关城。
阴云暮下雪，寒日昼无晶。
直为怀恩苦，谁知边塞情。','',''),('quantangshi-04339','长门怨','喬備','quantangshi','','卷5','秋入长门殿，木落洞房虚。
妾思宵徒静，君恩日更疎。
坠露清金阁，流萤点玉除。
还将闺里恨，遥问马相如。','',''),('quantangshi-04340','将军行','劉希夷','quantangshi','','卷5','将军辟辕门，耿介当风立。
诸将欲言事，逡巡不敢入。
劒气射云天，鼓声振原隰。
黄尘塞路起，走马追兵急。
弯弓从此去，飞箭如雨集。
截围一百里，斩首五千级。
代马流血死，胡人抱鞍泣。
古来养甲兵，有事常讨袭。
乘我庙堂运，坐使干戈戢。
献凯归京师，军容何翕习。','',''),('quantangshi-04341','从军行','劉希夷','quantangshi','','卷5','秋天风飒飒，羣胡马行疾。
严城昼不开，伏兵暗相失。
天子庙堂拜，将军凶门出。
纷纷伊洛道，戎马几万匹。
军门压黄河，兵气冲白日。
平生怀仗劒，慷慨即投笔。
南登汉月孤，北走代云密。
近取韩彭计，早知孙吴术。
丈夫清万里，谁能扫一室。','',''),('quantangshi-04342','春女行','劉希夷','quantangshi','','卷5','春女颜如玉，怨歌阳春曲。
巫山春树红，沅湘春草绿。
自怜妖艳姿，妆成独见时。
愁心伴杨柳，春尽乱如丝。
目极千余里，悠悠春江水。
频想玉关人，愁卧金闺里。
尚言春花落，不知秋风起。
娇爱犹未终，悲凉从此始。
忆昔楚王宫，玉楼妆粉红。
纤腰弄明月，长袖舞春风。
容华委西山，光阴不可还。
桑林变东海，富贵今何在？
寄言桃李容，胡为闺合重。
但看楚王墓，唯有数株松。','',''),('quantangshi-04343','孤松篇','劉希夷','quantangshi','','卷5','蚕月桑叶青，鸎时柳花白。
澹艳烟雨姿，敷芬阳春陌。
如何秋风起，零落从此始。
独有南涧松，不叹东流水。
玄阴天地冥，皓雪朝夜零。
岂不罹寒暑，为君留青青。
青青好颜色，落落任孤直。
羣树遥相望，众草不敢逼。
灵龟卜真隐，仙鸟宜栖息。
耻受秦帝封，愿言唐侯食。
寒山夜月明，山冷气清清。
凄兮归凤集，吹之作琴声。
松子卧仙岑，寂听疑野心。
清泠有真曲，樵采无知音。
美人何时来？幽径委绿苔。
吁嗟深涧底，弃捐广厦材。','',''),('quantangshi-04344','嵩岳闻笙','劉希夷','quantangshi','','卷5','月出嵩山东，月明山益空。
山人爱清景，散髪卧秋风。
风止夜何清，独夜草虫鸣。
仙人不可见，乘月近吹笙。
绛唇吸灵气，玉指调真声。
真声是何曲，三山鸾鹤情。
昔去落尘俗，愿言闻此曲。
今来卧嵩岑，何幸承幽音。
神仙乐吾事，笙歌铭夙心。','',''),('quantangshi-04345','秋日题汝阳潭壁','劉希夷','quantangshi','','卷5','独坐秋阴生，悲来从所适。
行见汝阳潭，飞萝蒙水石。
悬瓢木叶上，风吹何历历。
幽人不耐烦，振衣步闲寂。
回流清见底，金沙覆银砾。
错落非一文，空胧几千尺。
鱼鳞可怜紫，鸭毛自然碧。
吟咏秋水篇，渺然忘损益。
秋水随形影，清浊混心迹。
岁暮归去来，东山余宿昔。','',''),('quantangshi-04346','采桑','劉希夷','quantangshi','','卷5','杨柳送行人，青青西入秦。
谁家采桑女，楼上不胜春。
盈盈灞水曲，步步春芳绿。
红脸耀明珠，绛唇含白玉。
回首渭桥东，遥怜春色同。
青丝娇落日，缃绮弄春风。
携笼长叹息，逶迟恋春色。
看花若有情，倚树疑无力。
薄暮思悠悠，使君南陌头。
相逢不相识，归去梦青楼。','',''),('quantangshi-04347','谒汉世祖庙','劉希夷','quantangshi','','卷5','舂陵气初发，渐台首未传。
列营百万众，持国十八年。
运开朱旗后，道合赤符先。
宛城劒鸣匣，昆阳镝应弦。
犷兽血涂地，巨人声沸天。
长驱过北赵，短兵出南燕。
太守迎门外，王郎死道边。
升坛九城陌，端拱千秋年。
朝廷方雀跃，劒佩几联翩。
至德刑四海，神仪翳九泉。
宗子行旧邑，恭闻清庙篇。
君容穆而圣，臣像俨犹贤。
攒木承危柱，疎萝挂朽椽。
祠庭巢鸟啄，祭器网虫缘。
怀古江山在，惟新历数迁。
空余今夜月，长似旧时悬。','',''),('quantangshi-04348','巫山怀古','劉希夷','quantangshi','','卷5','巫山幽阴地，神女艳阳年。
襄王伺容色，落日望悠然。
归来高唐夜，金釭焰青烟。
颓想卧瑶席，梦魂何翩翩。
摇落殊未已，荣华倏徂迁。
愁思潇湘浦，悲凉云梦田。
猿啼秋风夜，雁飞明月天。
巴歌不可听，听此益潺湲。','',''),('quantangshi-04349','归山','劉希夷','quantangshi','','卷5','归去嵩山道，烟花覆青草。
草绿山无尘，山青杨柳春。
日暮松声合，空歌思杀人。','',''),('quantangshi-04350','代闺人春日','劉希夷','quantangshi','','卷5','珠帘的晓光，玉颜艳春彩。
林间鸟鸣唤，户外花相待。
花鸟惜芳菲，鸟鸣花乱飞。
人今伴花鸟，日暮不能归。
池月怜歌扇，山云爱舞衣。
佳期杨柳陌，携手莫相违。','',''),('quantangshi-04351','蜀城怀古','劉希夷','quantangshi','','卷5','蜀土遶水竹，吴天积风霜。
穷览通表里，气色何苍苍。
旧国有年代，青楼思艳妆。
古人无岁月，白骨冥丘荒。
寂历弹琴地，幽流读书堂。
玄龟埋卜室，彩凤灭词场。
阵图一一在，栢树双双行。
鬼神清汉庙，鸟雀参秦仓。
叹世已多感，怀心益自伤。
赖蒙灵丘境，时当明月光。','',''),('quantangshi-04352','洛川怀古','劉希夷','quantangshi','','卷5','萋萋春草绿，悲歌牧征马。
行见白头翁，坐泣青竹下。
感叹前问之，赠予辛苦词。
岁月移今古，山河更盛衰。
晋家都洛滨，朝廷多近臣。
词赋归潘岳，繁华称季伦。
梓泽春草菲，河阳乱华飞。
绿珠不可夺，白首同所归。
高楼倏冥灭，茂林久摧折。
昔时歌舞台，今成狐兔穴。
人事互消亡，世路多悲伤。
北邙是吾宅，东岳为吾乡。
君看北邙道，髑髅萦蔓草。
芳□□□□，□□□□□。
碑茔或半存，荆棘敛幽魂。
挥涕弃之去，不忍闻此言。','',''),('quantangshi-04353','春日行歌','劉希夷','quantangshi','','卷5','山树落梅花，飞落野人家。
野人何所有，满瓮阳春酒。
携酒上春台，行歌伴落梅。
醉罢卧明月，乘梦游天台。','',''),('quantangshi-04354','江南曲八首 一','劉希夷','quantangshi','','卷5','暮宿南洲草，晨行北岸林。
日悬沧海阔，水隔洞庭深。
烟景无留意，风波有异浔。
岁游难极目，春戏易为心。
朝夕无荣遇，芳菲已满襟。','',''),('quantangshi-04355','江南曲八首 二','劉希夷','quantangshi','','卷5','艳唱潮初落，江花露未曦。
春洲惊翡翠，朱服弄芳菲。
画舫烟中浅，青阳日际微。
锦帆冲浪湿，罗袖拂行衣。
含情罢所采，相叹惜流晖。','',''),('quantangshi-04356','江南曲八首 三','劉希夷','quantangshi','','卷5','君为陇西客，妾遇江南春。
朝游含灵果，夕采弄风苹。
果气时不歇，苹花日自新。
以此江南物，持赠陇西人。
空盈万里怀，欲赠竟无因。','',''),('quantangshi-04357','江南曲八首 四','劉希夷','quantangshi','','卷5','皓如楚江月，霭若吴岫云。
波中自皎镜，山上亦氤氲。
明月留照妾，轻云持赠君。
山川各离散，光气乃殊分。
天涯一为别，江北不相闻。','',''),('quantangshi-04358','江南曲八首 五','劉希夷','quantangshi','','卷5','舣舟乘潮去，风帆振早凉。
潮平见楚甸，天际望维扬。
洄溯经千里，烟波接两乡。
云明江屿出，日照海流长。
此中逢岁[晏]，浦树落花芳。','',''),('quantangshi-04359','江南曲八首 六','劉希夷','quantangshi','','卷5','暮春三月晴，维扬吴楚城。
城临大江汜，回映洞浦清。
晴云曲金阁，珠楼碧烟里。
月明芳树羣鸟飞，风过长林杂花起。
可怜离别谁家子，于此一至情何已。','',''),('quantangshi-04360','江南曲八首 七','劉希夷','quantangshi','','卷5','北堂红草盛䒠茸，南湖碧水照芙蓉。
朝游暮起金花尽，渐觉罗裳珠露浓。
自惜妍华三五岁，已叹关山千万重。
人情一去无还日，欲赠怀芳怨不逢。','',''),('quantangshi-04361','江南曲八首 八','劉希夷','quantangshi','','卷5','忆昔江南年盛时，平生怨在长洲曲。
冠盖星繁江水上，冲风摽落洞庭渌。
落花两袖红纷纷，朝霞高阁洗晴云。
谁言此处婵娟子，珠玉为心以奉君。','',''),('quantangshi-04362','捣衣篇','劉希夷','quantangshi','','卷5','秋天瑟瑟夜漫漫，夜白风清玉露漙。
燕山游子衣裳薄，秦地佳人闺阁寒。
欲向楼中萦楚练，还来机上裂齐纨。
揽红袖兮愁徙倚，盼青砧兮怅盘桓。
盘桓徙倚夜已久，萤火双飞入帘牖。
西北风来吹细腰，东南月上浮纤手。
此时秋月可怜明，此时秋风别有情。
君看月下参差影，为听莎间断续声。
绛河转兮青云晓，飞鸟鸣兮行人少。
攒眉缉缕思纷纷，对影穿针魂悄悄。
闻道还家未有期，谁怜登陇不胜悲。
梦见形容亦旧日，为许裁缝改昔时。
缄书远寄交河曲，须及明年春草绿。
莫言衣上有斑斑，只为思君泪相续。','',''),('quantangshi-04363','公子行','劉希夷','quantangshi','','卷5','天津桥下阳春水，天津桥上繁华子。
马声回合青云外，人影动摇绿波里。
绿波荡漾玉为砂，青云离披锦作霞。
可怜杨柳伤心树，可怜桃李断肠花。
此日遨游邀美女，此时歌舞入娼家。
娼家美女郁金香，飞来飞去公子傍。
的的珠帘白日映，娥娥玉颜红粉妆。
花际裴回双蛱蝶，池边顾步两鸳鸯。
倾国倾城汉武帝，为云为雨楚襄王。
古来容光人所羡，况复今日遥相见。
愿作轻罗着细腰，愿为明镜分娇面。
与君相向转相亲，与君双栖共一身。
愿作贞松千岁古，谁论芳槿一朝新。
百年同谢西山日，千秋万古北邙尘。','',''),('quantangshi-04364','代悲白头吟','劉希夷','quantangshi','','卷5','洛阳城东桃李花，飞来飞去落谁家。
洛阳女儿好颜色，坐见落花长叹息。
今年花落颜色改，明年花开复谁在。
已见松柏摧为薪，更闻桑田变成海。
古人无复洛城东，今人还对落花风。
年年岁岁花相似，岁岁年年人不同。
寄言全盛红颜子，应怜半死白头翁。
此翁白头真可怜，伊昔红颜美少年。
公子王孙芳树下，清歌妙舞落花前。
光禄池台开锦绣，将军楼阁画神仙。
一朝卧病无相识，三春行乐在谁边。
宛转蛾眉能几时，须臾鹤髪乱如丝。
但看古来歌舞地，惟有黄昏鸟雀悲。','',''),('quantangshi-04365','代秦女赠行人','劉希夷','quantangshi','','卷5','鸾镜晓含春，蛾眉向影嚬。
开□衣裳破，那堪粉黛新。
春还洛阳道，为忆春阶草。
杨叶未能攀，梅花待君扫。
今朝喜鹊傍人飞，应是狂夫走马归。
遥想行歌共游乐，迎前含笑着春衣。','',''),('quantangshi-04366','洛中晴月送殷四入关','劉希夷','quantangshi','','卷5','清洛浮桥南渡头，天晶万里散华洲。
晴看石濑光无数，晓入寒潭浸不流。
微云一点曙烟起，南陌憧憧遍行子。
欲将此意与君论，复道秦关尚千里。','',''),('quantangshi-04367','入塞','劉希夷','quantangshi','','卷5','将军陷虏围，边务息戎机。
霜雪交河尽，旌旗入塞飞。
晓光随马度，春色伴人归。
课绩朝明主，临轩拜武威。','',''),('quantangshi-04368','览镜','劉希夷','quantangshi','','卷5','青楼挂明镜，临照不胜悲。
白发今如此，人生能几时。
秋风下山路，明月上春期。
叹息君恩尽，容颜不可思。','',''),('quantangshi-04369','晚春','劉希夷','quantangshi','','卷5','佳人眠洞房，回首见垂杨。
寒尽鸳鸯被，春生玳瑁牀。
庭阴幕青霭，帘影散红芳。
寄语同心伴，迎春且薄妆。','',''),('quantangshi-04370','送友人之新丰','劉希夷','quantangshi','','卷5','日暮秋风起，关山断别情。
泪随黄叶下，愁向绿樽生。
野路归骖转，河洲宿鸟惊。
宾游宽旅宴，王事促严程。','',''),('quantangshi-04371','饯李秀才赴举','劉希夷','quantangshi','','卷5','鸿鹄振羽翮，翻飞入帝乡。
朝鸣集银树，暝宿下金塘。
日月天门近，风烟夜路长。
自怜穷浦雁，岁岁不随阳。','',''),('quantangshi-04372','夜集张諲所居','劉希夷','quantangshi','','卷5','江南成久客，门馆日萧条。
惟有图书在，多伤鬓髪凋。
诸生陪讲诵，稚子给渔樵。
隐室寒灯净，空阶落叶飘。
沧洲自有趣，谁道隐须招。','',''),('quantangshi-04373','故园置酒','劉希夷','quantangshi','','卷5','酒熟人须饮，春还鬓已秋。
愿逢千日醉，得缓百年忧。
旧里多青草，新知尽白头。
风前灯易灭，川上月难留。
卒卒周姬旦，栖栖鲁孔丘。
平生能几日，不及且遨游。','',''),('quantangshi-04374','晚憩南阳旅馆','劉希夷','quantangshi','','卷5','旅馆何年废，征夫此日过。
途穷人自哭，春至鸟还歌。
行路新知少，荒田古径多。
池篁覆丹谷，坟树遶清波。
日照蓬阴转，风微野气和。
伤心不可去，回首怨如何。','',''),('quantangshi-04375','庆云章','陳子昂','quantangshi','','卷5','昆仑元气，实生庆云。
大人作矣，五色氤氲。
昔在帝嬀，南风既薰。
丛芳烂熳，郁郁纷纷。
旷矣千祀，庆云来止。
玉叶金柯，祚我天子。
非我天子，庆云谁昌。
非我圣母，庆云谁光。
庆云光矣，周道昌矣。
九万八千，天授皇年。','',''),('quantangshi-04376','感遇诗三十八首 一','陳子昂','quantangshi','','卷5','微月生西海，幽阳始代升。
圆光正东满，阴魂已朝凝。
太极生天地，三元更废兴。
至精谅斯在，三五谁能征。','',''),('quantangshi-04377','感遇诗三十八首 二','陳子昂','quantangshi','','卷5','兰若生春夏，芊蔚何青青。
幽独空林色，朱蕤冒紫茎。
迟迟白日晚，袅袅秋风生。
岁华尽摇落，芳意竟何成。','',''),('quantangshi-04378','感遇诗三十八首 三','陳子昂','quantangshi','','卷5','苍苍丁零塞，今古缅荒途。
亭堠何摧兀，暴骨无全躯。
黄沙幕南起，白日隐西隅。
汉甲三十万，曾以事匈奴。
但见沙场死，谁怜塞上孤。','',''),('quantangshi-04379','感遇诗三十八首 四','陳子昂','quantangshi','','卷5','乐羊为魏将，食子殉军功。
骨肉且相薄，他人安得忠。
吾闻中山相，乃属放麑翁。
孤兽犹不忍，况以奉君终。','',''),('quantangshi-04380','感遇诗三十八首 五','陳子昂','quantangshi','','卷5','市人矜巧智，于道若童蒙。
倾夺相夸侈，不知身所终。
曷见玄真子，观世玉壶中。
窅然遗天地，乘化入无穷。','',''),('quantangshi-04381','感遇诗三十八首 六','陳子昂','quantangshi','','卷5','吾观龙变化，乃知至阳精。
石林何冥密，幽洞无留行。
古之得仙道，信与元化并。
玄感非象识，谁能测沈冥。
世人拘目见，酣酒笑丹经。
昆仑有瑶树，安得采其英。','',''),('quantangshi-04382','感遇诗三十八首 七','陳子昂','quantangshi','','卷5','白日每不归，青阳时暮矣。
茫茫吾何思，林卧观无始。
众芳委时晦，鶗鴂鸣悲耳。
鸿荒古已颓，谁识巢居子。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-04383','感遇诗三十八首 八','陳子昂','quantangshi','','卷5','吾观昆仑化，日月沦洞冥。
精魄相交会，天壤以罗生。
仲尼推太极，老聃贵窈冥。
西方金仙子，崇义乃无明。
空色皆寂灭，缘业定何成。
名教信纷藉，死生俱未停。','',''),('quantangshi-04384','感遇诗三十八首 九','陳子昂','quantangshi','','卷5','圣人秘元命，惧世乱其真。
如何嵩公辈，诙谲误时人。
先天诚为美，阶乱祸谁因。
长城备胡寇，嬴祸发其亲。
赤精既迷汉，子年何救秦。
去去桃李花，多言死如麻。','',''),('quantangshi-04385','感遇诗三十八首 十','陳子昂','quantangshi','','卷5','深居观元化，悱然争朵颐。
谗说相啖食，利害纷㘈㘈。
便便夸毗子，荣耀更相持。
务光让天下，商贾竞刀锥。
已矣行采芝，万世同一时。','',''),('quantangshi-04386','感遇诗三十八首 十一','陳子昂','quantangshi','','卷5','吾爱鬼谷子，青溪无垢氛。
囊括经世道，遗身在白云。
七雄方龙鬬，天下久无君。
浮荣不足贵，遵养晦时文。
舒可弥宇宙，卷之不盈分。
岂徒山木寿，空与麋鹿羣。','',''),('quantangshi-04387','感遇诗三十八首 十二','陳子昂','quantangshi','','卷5','呦呦南山鹿，罹罟以媒和。
招摇青桂树，幽蠹亦成科。
世情甘近习，荣耀纷如何。
怨憎未相复，亲爱生祸罗。
瑶台倾巧笑，玉杯殒双蛾。
谁见枯城蘖，青青成斧柯。','',''),('quantangshi-04388','感遇诗三十八首 十三','陳子昂','quantangshi','','卷5','林居病时久，水木澹孤清。
闲卧观物化，悠悠念无生。
青春始萌达，朱火已满盈。
徂落方自此，感叹何时平。','',''),('quantangshi-04389','感遇诗三十八首 十四','陳子昂','quantangshi','','卷5','临岐泣世道，天命良悠悠。
昔日殷王子，玉马遂朝周。
宝鼎沦伊谷，瑶台成古丘。
西山伤遗老，东陵有故侯。','',''),('quantangshi-04390','感遇诗三十八首 十五','陳子昂','quantangshi','','卷5','贵人难得意，赏爱在须臾。
莫以心如玉，探他明月珠。
昔称夭桃子，今为舂市徒。
鸱鸮悲东国，麋鹿泣姑苏。
谁见鸱夷子，扁舟去五湖。','',''),('quantangshi-04391','感遇诗三十八首 十六','陳子昂','quantangshi','','卷5','圣人去已久，公道缅良难。
蚩蚩夸毗子，尧禹以为谩。
骄荣贵工巧，势利迭相干。
燕王尊乐毅，分国愿同欢。
鲁连让齐爵，遗组去邯郸。
伊人信往矣，感激为谁叹。','',''),('quantangshi-04392','感遇诗三十八首 十七','陳子昂','quantangshi','','卷5','幽居观天运，悠悠念羣生。
终古代兴没，豪圣莫能争。
三季沦周赧，七雄灭秦嬴。
复闻赤精子，提劒入咸京。
炎光既无象，晋虏复纵横。
尧禹道已昧，昏虐势方行。
岂无当世雄，天道与胡兵。
咄咄安可言，时醉而未醒。
仲尼溺东鲁，伯阳遁西溟。
大运自古来，旅人胡叹哉。','',''),('quantangshi-04393','感遇诗三十八首 十八','陳子昂','quantangshi','','卷5','逶迤势已久，骨鲠道斯穷。
岂无感激者，时俗颓此风。
灌园何其鄙，皎皎于陵中。
世道不相容，嗟嗟张长公。','',''),('quantangshi-04394','感遇诗三十八首 十九','陳子昂','quantangshi','','卷5','圣人不利己，忧济在元元。
黄屋非尧意，瑶台安可论。
吾闻西方化，清净道弥敦。
奈何穷金玉，雕刻以为尊。
云构山林尽，瑶图珠翠烦。
鬼工尚未可，人力安能存。
夸愚适增累，矜智道逾昏。','',''),('quantangshi-04395','感遇诗三十八首 二十','陳子昂','quantangshi','','卷5','玄天幽且默，羣议曷嗤嗤。
圣人教犹在，世运久陵夷。
一绳将何系？忧醉不能持。
去去行采芝，勿为尘所欺。','',''),('quantangshi-04396','感遇诗三十八首 二十一','陳子昂','quantangshi','','卷5','蜻蛉游天地，与世本无患。
飞飞未能止，黄雀来相干。
穰侯富秦宠，金石比交欢。
出入咸阳里，诸侯莫敢言。
宁知山东客，激怒秦王肝。
布衣取丞相，千载为辛酸。','',''),('quantangshi-04397','感遇诗三十八首 二十二','陳子昂','quantangshi','','卷5','微霜知岁晏，斧柯始青青。
况乃金天夕，浩露沾羣英。
登山望宇宙，白日已西暝。
云海方荡潏，孤鳞安得宁。','',''),('quantangshi-04398','感遇诗三十八首 二十三','陳子昂','quantangshi','','卷5','翡翠巢南海，雄雌珠树林。
何知美人意，骄爱比黄金。
杀身炎州里，委羽玉堂阴。
旖旎光首饰，葳蕤烂锦衾。
岂不在遐远，虞罗忽见寻。
多材信为累，叹息此珍禽。','',''),('quantangshi-04399','感遇诗三十八首 二十四','陳子昂','quantangshi','','卷5','挈瓶者谁子，姣服当青春。
三五明月满，盈盈不自珍。
高堂委金玉，微缕悬千钧。
如何负公鼎，被敓笑时人。','',''),('quantangshi-04400','感遇诗三十八首 二十五','陳子昂','quantangshi','','卷5','玄蝉号白露，兹岁已蹉跎。
羣物从大化，孤英将奈何？
瑶台有青鸟，远食玉山禾。
昆仑见玄凤，岂复虞云罗。','',''),('quantangshi-04401','感遇诗三十八首 二十六','陳子昂','quantangshi','','卷5','荒哉穆天子，好与白云期。
宫女多怨旷，层城闭蛾眉。
日耽瑶池乐，岂伤桃李时。
青苔空萎绝，白发生罗帷。','',''),('quantangshi-04402','感遇诗三十八首 二十七','陳子昂','quantangshi','','卷5','朝发宜都渚，浩然思故乡。
故乡不可见，路隔巫山阳。
巫山彩云没，高丘正微茫。
伫立望已久，涕落沾衣裳。
岂兹越乡感，忆昔楚襄王。
朝云无处所，荆国亦沦亡。','',''),('quantangshi-04403','感遇诗三十八首 二十八','陳子昂','quantangshi','','卷5','昔日章华宴，荆王乐荒淫。
霓旌翠羽盖，射兕云梦林。
朅来高唐观，怅望云阳岑。
雄图今何在？黄雀空哀吟。','',''),('quantangshi-04404','感遇诗三十八首 二十九','陳子昂','quantangshi','','卷5','丁亥岁云暮，西山事甲兵。
赢粮匝邛道，荷戟争羗城。
严冬阴风劲，穷岫泄云生。
昏噎无昼夜，羽檄复相惊。
拳局竞万仞，崩危走九冥。
籍籍峰壑里，哀哀冰雪行。
圣人御宇宙，闻道泰阶平。
肉食谋何失，藜藿缅纵横。','',''),('quantangshi-04405','感遇诗三十八首 三十','陳子昂','quantangshi','','卷5','可怜瑶台树，灼灼佳人姿。
碧华映朱实，攀折青春时。
岂不盛光宠，荣君白玉墀。
但恨红芳歇，凋伤感所思。','',''),('quantangshi-04406','感遇诗三十八首 三十一','陳子昂','quantangshi','','卷5','朅来豪游子，势利祸之门。
如何兰膏叹，感激自生冤。
众趋明所避，时弃道犹存。
云渊既已失，罗网与谁论。
箕山有高节，湘水有清源。
唯应白鸥鸟，可为洗心言。','',''),('quantangshi-04407','感遇诗三十八首 三十二','陳子昂','quantangshi','','卷5','索居犹几日，炎夏忽然衰。
阳彩皆阴翳，亲友尽暌违。
登山望不见，涕泣久涟洏。
宿梦感颜色，若与白云期。
马上骄豪子，驱逐正蚩蚩。','',''),('quantangshi-04408','感遇诗三十八首 三十三','陳子昂','quantangshi','','卷5','金鼎合神丹，世人将见欺。
飞飞骑羊子，胡乃在峨眉。
变化固幽类，芳菲能几时。
疲疴苦沦世，忧痗日侵淄。
眷然顾幽褐，白云空涕涕。','',''),('quantangshi-04409','感遇诗三十八首 三十四','陳子昂','quantangshi','','卷5','朔风吹海树，萧条边已秋。
亭上谁家子，哀哀明月楼。
自言幽燕客，结发事远游。
赤丸杀公吏，白刃报私雠。
避雠至海上，被役此边州。
故乡三千里，辽水复悠悠。
每愤胡兵入，常为汉国羞。
何知七十战，白首未封侯。','',''),('quantangshi-04410','感遇诗三十八首 三十五','陳子昂','quantangshi','','卷5','本为贵公子，平生实爱才。
感时思报国，拔劒起蒿莱。
西驰丁零塞，北上单于台。
登山见千里，怀古心悠哉。
谁言未忘祸，磨灭成尘埃。','',''),('quantangshi-04411','感遇诗三十八首 三十六','陳子昂','quantangshi','','卷5','浩然坐何慕，吾蜀有峨眉。
念与楚狂子，悠悠白云期。
时哉悲不会，涕泣久涟洏。
梦登绥山穴，南采巫山芝。
探元观羣化，遗世从云螭。
婉变时永矣，感悟不见之。','',''),('quantangshi-04412','感遇诗三十八首 三十七','陳子昂','quantangshi','','卷5','朝入云中郡，北望单于台。
胡秦何密迩，沙朔气雄哉。
藉藉天骄子，猖狂已复来。
塞垣无名将，亭堠空崔嵬。
咄嗟吾何叹，边人涂草莱。','',''),('quantangshi-04413','感遇诗三十八首 三十八','陳子昂','quantangshi','','卷5','仲尼探元化，幽鸿顺阳和。
大运自盈缩，春秋递来过。
盲飙忽号怒，万物相纷劘。
溟海皆震荡，孤凤其如何。','',''),('quantangshi-04414','观荆玉篇','陳子昂','quantangshi','','卷5','鸱夷双白玉，此玉有缁磷。
悬之千金价，举世莫知真。
丹青非异色，轻重有殊伦。
勿信玉工言，徒悲荆国人。','',''),('quantangshi-04415','鸳鸯篇','陳子昂','quantangshi','','卷5','飞飞鸳鸯鸟，举翼相蔽亏。
俱来绿潭里，共向白云涯。
音容相眷恋，羽翮两逶迤。
苹萍戏春渚，霜霰遶寒池。
浦沙连岸净，汀树拂潭垂。
年年此游翫，岁岁来追随。
凤凰起丹穴，独向梧桐枝。
鸿雁来紫塞，空忆稻粱肥。
乌啼倦依托，鹤鸣伤别离。
岂若此双禽，飞翻不异林。
刷尾青江浦，交颈紫山岑。
文章负奇色，和鸣多好音。
闻有鸳鸯绮，复有鸳鸯衾。
持为美人赠，勖此故交心。','',''),('quantangshi-04416','与东方左史虬修竹篇','陳子昂','quantangshi','','卷5','龙种生南岳，孤翠郁亭亭。
峰岭上崇崒，烟雨下微冥。
夜闻鼯鼠呌，昼聒泉鹤声。
春风正淡荡，白露已清泠。
哀响激金奏，密色滋玉英。
岁寒霜雪苦，含彩独青青。
岂不厌凝洌，羞比春木荣。
春木有荣歇，此节无凋零。
始愿与金石，终古保坚贞。
不意伶伦子，吹之学凤鸣。
遂偶云和瑟，张乐奏天庭。
妙曲方千变，箫韶亦九成。
信蒙雕斲美，常愿事仙灵。
驱驰翠虬驾，伊郁紫鸾笙。
结交嬴台女，吟弄升天行。
携手登白日，远游戏赤城。
低昂玄鹤舞，断续彩云生。
永随众仙逝，三山游玉京。','',''),('quantangshi-04417','蓟丘览古赠卢居士藏用七首 轩辕台','陳子昂','quantangshi','','卷5','北登蓟丘望，求古轩辕台。
应龙已不见，牧马空黄埃。
尚想广成子，遗迹白云隈。','',''),('quantangshi-04418','蓟丘览古赠卢居士藏用七首 燕昭王','陳子昂','quantangshi','','卷5','南登碣石坂，遥望黄金台。
丘陵尽乔木，昭王安在哉。
霸图怅已矣，驱马复归来。','',''),('quantangshi-04419','蓟丘览古赠卢居士藏用七首 乐生','陳子昂','quantangshi','','卷5','王道已沦昧，战国竞贪兵。
乐生何感激，仗义下齐城。
雄图竟中夭，遗叹寄阿衡。','',''),('quantangshi-04420','蓟丘览古赠卢居士藏用七首 燕太子','陳子昂','quantangshi','','卷5','秦王日无道，太子怨亦深。
一闻田光义，匕首赠千金。
其事虽不立，千载为伤心。','',''),('quantangshi-04421','蓟丘览古赠卢居士藏用七首 田光先生','陳子昂','quantangshi','','卷5','自古皆有死，狥义良独稀。
奈何燕太子，尚使田生疑。
伏劒诚已矣，感我涕沾衣。','',''),('quantangshi-04422','蓟丘览古赠卢居士藏用七首 邹衍','陳子昂','quantangshi','','卷5','大运沦三代，天人罕有窥。
邹子何寥廓，漫说九瀛垂。
兴亡已千载，今也则无推。','',''),('quantangshi-04423','蓟丘览古赠卢居士藏用七首 郭隗','陳子昂','quantangshi','','卷5','逢时独为贵，历代非无才。
隗君亦何幸，遂起黄金台。','',''),('quantangshi-04424','西还至散关答乔补阙知之','陳子昂','quantangshi','','卷5','葳蕤苍梧凤，嘹唳白露蝉。
羽翰本非匹，结交何独全。
昔君事胡马，余得奉戎旃。
携手向沙塞，关河缅幽燕。
芳岁几阳止，白日屡徂迁。
功业云台薄，平生玉佩捐。
叹此南归日，犹闻北戍边。
代水不可涉，巴江亦潺湲。
揽衣度函谷，衔涕望秦川。
蜀门自兹始，云山方浩然。','',''),('quantangshi-04425','度峡口山赠乔补阙知之王二无竞','陳子昂','quantangshi','','卷5','峡口大漠南，横绝界中国。
丛石何纷糺，赤山复翕赩。
远望多众容，逼之无异色。
崔崒乍孤断，逶迤屡回直。
信关胡马冲，亦距汉边塞。
岂依河山险，将顺休明德。
物壮诚有衰，势雄良易极。
逦迤忽而尽，泱漭平不息。
之子黄金躯，如何此荒域。
云台盛多士，待君丹墀侧。','',''),('quantangshi-04426','题居延古城赠乔十二知之','陳子昂','quantangshi','','卷5','闻君东山意，宿昔紫芝荣。
沧洲今何在？华髪旅边城。
还汉功既薄，逐胡策未行。
徒嗟白日暮，坐对黄云生。
桂枝芳欲晚，薏苡谤谁明。
无为空自老，含叹负生平。','',''),('quantangshi-04427','赠赵六贞固二首 一','陳子昂','quantangshi','','卷5','回中[烽]火入，塞上追兵起。
此时边朔寒，登陇思君子。
东顾望汉京，南山云雾里。','',''),('quantangshi-04428','赠赵六贞固二首 二','陳子昂','quantangshi','','卷5','赤螭媚其彩，婉娈苍梧泉。
昔者琅琊子，躬耕亦慨然。
美人岂遐旷，之子乃前贤。
良辰在何许，白日屡颓迁。
道心固微密，神用无留连。
舒可弥宇宙，揽之不盈拳。
蓬莱久芜没，金石徒精坚。
良宝委短褐，闲琴独婵娟。','',''),('quantangshi-04429','答韩使同在边','陳子昂','quantangshi','','卷5','汉家失中策，胡马屡南驱。
闻诏安边使，曾是故人谟。
废书怅怀古，负劒许良图。
出关岁方晏，乘障日多虞。
虏入白登道，烽交紫塞途。
连兵屯北地，清野备东胡。
边城方晏闭，斥堠始昭苏。
复闻韩长孺，辛苦事匈奴。
雨雪颜容改，纵横才位孤。
空怀老臣策，未获赵军租。
但蒙魏侯重，不受谤书诬。
当取金人祭，还歌凯入都。','',''),('quantangshi-04430','征东至淇门答宋十一参军之问','陳子昂','quantangshi','','卷5','南星中大火，将子涉清淇。
西林改微月，征斾空自持。
碧潭去已远，瑶华折遗谁。
若问辽阳戍，悠悠天际旗。','',''),('quantangshi-04431','答洛阳主人','陳子昂','quantangshi','','卷5','平生白云志，早爱赤松游。
事亲恨未立，从宦此中州。
主人亦何问，旅客非悠悠。
方谒明天子，清宴奉良筹。
再取连城璧，三陟平津侯。
不然拂衣去，归从海上鸥。
宁随当代子，倾侧且沈浮。','',''),('quantangshi-04432','酬晖上人秋夜山亭有赠','陳子昂','quantangshi','','卷5','皎皎白林秋，微微翠山静。
禅居感物变，独坐开轩屏。
风泉夜声杂，月露宵光冷。
多谢忘机人，尘忧未能整。','',''),('quantangshi-04433','酬李参军崇嗣旅馆见赠','陳子昂','quantangshi','','卷5','昨夜银河畔，星文犯遥汉。
今朝紫气新，物色果逢真。
言从天上落，乃是地仙人。
白璧疑冤楚，乌裘似入秦。
摧藏多古意，历览备艰辛。
乐广云虽覩，夷吾风未春。
凤歌空有问，龙性讵能驯。
宝劒终应出，骊珠会见珍。
未及冯公老，何惊孺子贫。
青云傥可致，北海忆孙宾。','',''),('quantangshi-04434','酬晖上人夏日林泉','陳子昂','quantangshi','','卷5','闻道白云居，窈窕青莲宇。
岩泉万丈流，树石千年古。
林卧对轩窗，山阴满庭户。
方释尘事劳，从君袭兰杜。','',''),('quantangshi-04435','同宋参军之问梦赵六赠卢陈二子之作','陳子昂','quantangshi','','卷5','晓霁望嵩丘，白云半岩足。
氛氲涵翠微，宛如嬴台曲。
故人昔所尚，幽琴歌断续。
变化竟无常，人琴遂两亡。
白云失处所，梦想暧容光。
畴昔疑缘业，儒道两相妨。
前期许幽报，迨此尚茫茫。
晤言既已失，感叹情何一。
始忆携手期，云台与峨眉。
达兼济天下，穷独善其时。
诸君推管乐，之子慕巢夷。
奈何苍生望，卒为黄绶欺。
铭鼎功未立，山林事亦微。
抚孤一流恸，怀旧日暌违。
卢子尚高节，终南卧松雪。
宋侯逢圣君，骖驭游青云。
而我独蹭蹬，语默道犹屯。
征戍在辽阳，蹉跎草再黄。
丹丘恨不及，白露已苍苍。
远闻山阳赋，感涕下沾裳。','',''),('quantangshi-04436','送别出塞','陳子昂','quantangshi','','卷5','平生闻高义，书劒百夫雄。
言登青云去，非此白头翁。
胡兵屯塞下，汉骑属云中。
君为白马将，腰佩騂角弓。
单于不敢射，天子伫深功。
蜀山余方隐，良会何时同。','',''),('quantangshi-04437','登蓟丘楼送贾兵曹入都','陳子昂','quantangshi','','卷5','东山宿昔意，北征非我心。
孤负平生愿，感涕下沾襟。
暮登蓟楼上，永望燕山岑。
辽海方漫漫，胡沙飞且深。
峨眉杳如梦，仙子曷由寻。
击劒起叹息，白日忽西沈。
闻君洛阳使，因子寄南音。','',''),('quantangshi-04438','夏日晖上人房别李参军崇嗣','陳子昂','quantangshi','','卷5','四十九变化，一十三死生。
翕忽玄黄里，驱驰风雨情。
是非纷妄作，宠辱坐相惊。
至人独幽鉴，窈窕随昏明。
咫尺山河道，轩窗日月庭。
别离焉足问，悲乐固能并。
我辈何为尔，栖皇犹未平。
金台可攀陟，宝界绝将迎。
户牖观天地，阶基上杳冥。
自超三界乐，安知万里征。
中国要荒内，人寰宇宙荣。
弦望如朝夕，宁嗟蜀道行。','',''),('quantangshi-04439','秋园卧病呈晖上人','陳子昂','quantangshi','','卷5','幽寂旷日遥，林园转清密。
疲疴澹无豫，独坐泛瑶瑟。
怀挟万古情，忧虞百年疾。
绵绵多滞念，忽忽每如失。
缅想赤松游，高寻白云逸。
荣吝始都丧，幽人遂贞吉。
图书纷满床，山水蔼盈室。
宿昔心所尚，平生自兹毕。
愿言谁见知，梵筵有同术。
八月高秋晚，凉风正萧瑟。','',''),('quantangshi-04440','登泽州城北楼宴','陳子昂','quantangshi','','卷5','平生倦游者，观化久无穷。
复来登此国，临望与君同。
坐见秦兵垒，遥闻赵将雄。
武安君何在，长平事已空。
且歌玄云曲，御酒舞薰风。
勿使青衿子，嗟尔白头翁。','',''),('quantangshi-04441','山水粉图','陳子昂','quantangshi','','卷5','山图之白云兮，若巫山之高丘。
纷羣翠之鸿溶，又似蓬瀛海水之周流。
信夫人之好道，爱云山以幽求。','',''),('quantangshi-04442','彩树歌','陳子昂','quantangshi','','卷5','嘉锦筵之珍树兮，错众彩之氛氲。
状瑶台之微月，点巫山之朝云。
青春兮不可逢，况蕙色之增芬。
结芳意而谁赏，怨绝世之无闻。
红荣碧艳坐看歇，素华流年不待君。
故吾思昆仑之琪树，厌桃李之缤纷。','',''),('quantangshi-04443','春台引','陳子昂','quantangshi','','卷5','感阳春兮生碧草之油油，怀宇宙以伤远，登高台而写忧。
迟美人兮不见，恐青岁之遂遒。
从毕公以酣饮，寄林塘而一留。
采芳荪于北渚，忆桂树于南州。
何云木之美丽，而池馆之崇幽。
星台秀士，月旦诸子。
嘉青鸟之辰，迎火龙之始。
挟宝书与瑶瑟，芳蕙华而兰靡。
乃掩白苹，藉绿芷。
酒既醉，乐未已。
击青钟，歌渌水。
怨青春之萎绝，赠瑶台之旖旎。
愿一见而道意，结众芳之绸缪。
曷余情之荡漾，瞩青云以增愁。
怅三山之飞鹤，忆海上之白鸥。
重曰：羣仙去兮青春颓，岁华歇兮黄鸟哀。
富贵荣乐几时兮，朱宫碧堂生青苔，白云兮归来。','',''),('quantangshi-04444','登幽州台歌','陳子昂','quantangshi','','卷5','前不见古人，后不见来者。
念天地之悠悠，独怆然而涕下。','',''),('quantangshi-04445','喜马参军相遇醉歌','陳子昂','quantangshi','','卷5','独幽默以三月兮，深林潜居。
时岁忽兮，孤愤遐吟。
谁知我心，孺子孺子，其可与理分。','',''),('quantangshi-04446','度荆门望楚','陳子昂','quantangshi','','卷5','遥遥去巫峡，望望下章台。
巴国山川尽，荆门烟雾开。
城分苍野外，树断白云隈。
今日狂歌客，谁知入楚来。','',''),('quantangshi-04447','晚次乐乡县','陳子昂','quantangshi','','卷5','故乡杳无际，日暮且孤征。
川原迷旧国，道路入边城。
野戍荒烟断，深山古木平。
如何此时恨，噭噭夜猿鸣。','',''),('quantangshi-04448','同王员外雨后登开元寺南楼因酬晖上人独坐山亭有赠','陳子昂','quantangshi','','卷5','钟梵经行罢，香林坐入禅。
岩庭交杂树，石濑泻鸣泉。
水月心方寂，云霞思独玄。
宁知人世里，疲病得攀缘。','',''),('quantangshi-04449','东征答朝臣相送','陳子昂','quantangshi','','卷5','平生白云意，疲薾愧为雄。
君王谬殊宠，旌节此从戎。
挼绳当系虏，单马岂邀功。
孤劒将何托，长谣塞上风。','',''),('quantangshi-04450','咏主人壁上画鹤寄乔主簿崔着作','陳子昂','quantangshi','','卷5','古壁仙人画，丹青尚有文。
独舞纷如雪，孤飞暧似云。
自矜彩色重，宁忆故池羣。
江海联翩翼，长鸣谁复闻。','',''),('quantangshi-04451','居延海树闻莺同作','陳子昂','quantangshi','','卷5','边地无芳树，莺声忽听新。
间关如有意，愁绝若怀人。
明妃失汉宠，蔡女没胡尘。
坐闻应落泪，况忆故园春。','',''),('quantangshi-04452','题李三书斋','陳子昂','quantangshi','','卷5','灼灼青春仲，悠悠白日升。
声容何足恃，荣吝坐相矜。
愿与金庭会，将待玉书征。
还丹应有术，烟驾共君乘。','',''),('quantangshi-04453','送魏大从军','陳子昂','quantangshi','','卷5','匈奴犹未灭，魏绛复从戎。
怅别三河道，言追六郡雄。
雁山横代北，狐塞接云中。
勿使燕然上，惟留汉将功。','',''),('quantangshi-04454','送殷大入蜀','陳子昂','quantangshi','','卷5','禺山金碧路，此地饶英灵。
送君一为别，凄断故乡情。
片云生极浦，斜日隐离亭。
坐看征骑没，惟见远山青。','',''),('quantangshi-04455','落第西还别刘祭酒高明府','陳子昂','quantangshi','','卷5','别馆分周国，归骖入汉京。
地连函谷塞，川接广阳城。
望迥楼台出，途遥烟雾生。
莫言长落羽，贫贱一交情。','',''),('quantangshi-04456','落第西还别魏四懔','陳子昂','quantangshi','','卷5','转蓬方不定，落羽自惊弦。
山水一为别，欢娱复几年。
离亭暗风雨，征路入云烟。
还因北山迳，归守东陂田。','',''),('quantangshi-04457','送客','陳子昂','quantangshi','','卷5','故人洞庭去，杨柳春风生。
相送河洲晚，苍茫别思盈。
白苹已堪把，绿芷复含荣。
江南多桂树，归客赠生平。','',''),('quantangshi-04458','春夜别友人二首 一','陳子昂','quantangshi','','卷5','银烛吐青烟，金樽对绮筵。
离堂思琴瑟，别路遶山川。
明月隐高树，长河没晓天。
悠悠洛阳道，此会在何年。','',''),('quantangshi-04459','春夜别友人二首 二','陳子昂','quantangshi','','卷5','紫塞白云断，青春明月初。
对此芳樽夜，离忧怅有余。
清冷花露满，滴沥檐宇虚。
怀君欲何赠，愿上大臣书。','',''),('quantangshi-04460','遂州南江别乡曲故人','陳子昂','quantangshi','','卷5','楚江复为客，征棹方悠悠。
故人悯追送，置酒此南洲。
平生亦何恨，夙昔在林丘。
违此乡山别，长谣去国愁。','',''),('quantangshi-04461','送东莱王学士无竞','陳子昂','quantangshi','','卷5','宝劒千金买，平生未许人。
怀君万里别，持赠结交亲。
孤松宜晚岁，众木爱芳春。
已矣将何道，无令白首新。','',''),('quantangshi-04462','送梁李二明府','陳子昂','quantangshi','','卷5','负书犹在汉，怀策未闻秦。
复此穷秋日，芳樽别故人。
黄金装屡尽，白首契逾新。
空羡双凫舄，俱飞向玉轮。','',''),('quantangshi-04463','送魏兵曹使嶲州得登字','陳子昂','quantangshi','','卷5','阳山淫雾雨，之子慎攀登。
羗笮多珍宝，人言有爱憎。
欲酬明主惠，当尽使臣能。
勿以王阳道，迢递畏崚嶒。','',''),('quantangshi-04464','送着作佐郎崔融等从梁王东征','陳子昂','quantangshi','','卷5','金天方肃杀，白露始专征。
王师非乐战，之子慎佳兵。
海气侵南部，边风扫北平。
莫卖卢龙塞，归邀麟阁名。','',''),('quantangshi-04465','春晦饯陶七于江南同用风字','陳子昂','quantangshi','','卷5','黄鹤烟云去，青江琴酒同。
离帆方楚越，沟水复西东。
芙蓉生夏浦，杨柳送春风。
明日相思处，应对菊花丛。','',''),('quantangshi-04466','喜遇冀侍御圭崔司议泰之二使','陳子昂','quantangshi','','卷5','谢病南山下，幽卧不知春。
使星入东井，云是故交亲。
惠风吹宝瑟，微月忆清真。
凭轩一留醉，江海寄情人。','',''),('quantangshi-04467','登蓟城西北楼送崔着作融入都','陳子昂','quantangshi','','卷5','蓟楼望燕国，负劒喜兹登。
清规子方奏，单戟我无能。
仲冬边风急，云汉复霜棱。
慷慨竟何道，西南恨失朋。','',''),('quantangshi-04468','月夜有怀','陳子昂','quantangshi','','卷5','美人挟赵瑟，微月在西轩。
寂寞夜何久，殷勤玉指繁。
清光委衾枕，遥思属湘沅。
空帘隔星汉，犹梦感精魂。','',''),('quantangshi-04469','夏日游晖上人房','陳子昂','quantangshi','','卷5','山水开精舍，琴歌列梵筵。
人疑白楼赏，地似竹林禅。
对户池光乱，交轩岩翠连。
色空今已寂，乘月弄澄泉。','',''),('quantangshi-04470','春日登金华观','陳子昂','quantangshi','','卷5','白玉仙台古，丹丘别望遥。
山川乱云日，楼榭入烟霄。
鹤舞千年树，虹飞百尺桥。
还疑赤松子，天路坐相邀。','',''),('quantangshi-04471','羣公集毕氏林亭','陳子昂','quantangshi','','卷5','金门有遗世，鼎实恣和邦。
默语谁能识，琴樽寄北窗。
子牟恋魏阙，渔父爱沧江。
良时信同此，岁晚迹难双。','',''),('quantangshi-04472','宴胡楚真禁所','陳子昂','quantangshi','','卷5','人生固有命，天道信无言。
青绳一相点，白璧遂成冤。
请室闲逾邃，幽庭春未暄。
寄谢韩安国，何惊狱吏尊。','',''),('quantangshi-04473','魏氏园林人赋一物得秋亭萱草','陳子昂','quantangshi','','卷5','昔时幽径里，荣耀杂春丛。
今来玉墀上，销歇畏秋风。
细叶犹含绿，鲜花未吐红。
忘忧谁见赏，空此北堂中。','',''),('quantangshi-04474','晦日宴高氏林亭','陳子昂','quantangshi','','卷5','寻春游上路，追宴入山家。
主第簪缨满，皇州景望华。
玉池初吐溜，珠树始开花。
欢娱方未极，林阁散余霞。','',''),('quantangshi-04475','晦日重宴高氏林亭','陳子昂','quantangshi','','卷5','公子好追随，爱客不知疲。
象筵开玉馔，翠羽饰金巵。
此时高宴所，讵减习家池。','',''),('quantangshi-04476','上元夜效小庾体','陳子昂','quantangshi','','卷5','三五月华新，遨游逐上春。
相邀洛城曲，追宴小平津。
楼上看珠妓，车中见玉人。
芳宵殊未极，随意守灯轮。','',''),('quantangshi-04477','洛城观酺应制','陳子昂','quantangshi','','卷5','圣人信恭己，天命允昭回。
苍极神功被，青云祕箓开。
垂衣受金册，张乐宴瑶台。
云凤休征满，鱼龙杂戏来。
崇恩逾五日，惠泽畅三才。
玉帛羣臣醉，徽章缛礼该。
方覩升中禅，言观拜洛回。
微臣固多幸，敢上万年杯。','',''),('quantangshi-04478','奉和皇帝上礼抚事述怀应制','陳子昂','quantangshi','','卷5','大君忘自我，应运居紫宸。
揖让期明辟，讴歌且顺人。
轩宫帝图盛，皇极礼容申。
南面朝万国，东堂会百神。
云陛旗常满，天庭玉帛陈。
钟石和睿思，雷雨被深仁。
承平信娱乐，王业本艰辛。
愿罢瑶池宴，来观农扈春。
卑宫昭夏德，尊老睦尧亲。
微臣敢拜手，歌舞颂维新。','',''),('quantangshi-04479','酬田逸人游岩见寻不遇题隐居里壁','陳子昂','quantangshi','','卷5','游人献书去，薄暮返灵台。
传道寻仙友，青囊卖卜来。
闻莺忽相访，题凤久裴回。
石髓空盈握，金经祕不开。
还疑缝掖子，复似洛阳才。','',''),('quantangshi-04480','白帝城怀古','陳子昂','quantangshi','','卷5','日落沧江晚，停桡问土风。
城临巴子国，台没汉王宫。
荒服任周甸，深山尚禹功。
岩悬青壁断，地险碧流通。
古木生云际，孤帆出雾中。
川途去无限，客思坐何穷。','',''),('quantangshi-04481','岘山怀古','陳子昂','quantangshi','','卷5','秣马临荒甸，登高览旧都。
犹悲堕泪碣，尚想卧龙图。
城邑遥分楚，山川半入吴。
丘陵徒自出，贤圣几凋枯。
野树苍烟断，津楼晚气孤。
谁知万里客，怀古正踌蹰。','',''),('quantangshi-04482','宿空舲峡青树邨浦','陳子昂','quantangshi','','卷5','的的明月水，啾啾寒夜猿。
客思浩方乱，洲浦寂无喧。
忆作千金子，宁知九逝魂。
虚闻事朱阙，结绶骛华轩。
委别高堂爱，窥觎明主恩。
今成转蓬去，叹息复何言。','',''),('quantangshi-04483','宿襄河驿浦','陳子昂','quantangshi','','卷5','沿流辞北渚，结缆宿南洲。
合岸昏初夕，廻塘暗不流。
卧闻塞鸿断，坐听峡猿愁。
沙浦明如月，汀葭晦若秋。
不及能鸣雁，徒思海上鸥。
天河殊未晓，沧海信悠悠。','',''),('quantangshi-04484','赠严仓曹乞推命录','陳子昂','quantangshi','','卷5','少学纵横术，游楚复游燕。
栖遑长委命，富贵未知天。
闻道沈冥客，青囊有秘篇。
九宫探万象，三算极重玄。
愿奉唐生诀，将知跃马年。
非同墨翟问，空滞杀龙川。','',''),('quantangshi-04485','和陆明府赠将军重出塞','陳子昂','quantangshi','','卷5','忽闻天上将，关塞重横行。
始返楼兰国，还向朔方城。
黄金装战马，白羽集神兵。
星月开天阵，山川列地营。
晚风吹画角，春色耀飞旌。
宁知班定远，犹是一书生。','',''),('quantangshi-04486','江上暂别萧四刘三旋欣接遇','陳子昂','quantangshi','','卷5','昨夜沧江别，言乖天汉游。
宁期此相遇，尚接武陵洲。
结绶还逢育，衔杯且对刘。
波潭一弥弥，临望几悠悠。
山水丹青杂，烟云紫翠浮。
终愧神仙友，来接野人舟。','',''),('quantangshi-04487','秋日遇荆州府崔兵曹使宴','陳子昂','quantangshi','','卷5','輶轩凤皇使，林薮鹖鸡冠。
江湖一相许，云雾坐交欢。
兴尽崔亭伯，言忘释道安。
林光稍欲暮，岁物已将阑。
古树苍烟断，虚亭白露寒。
瑶琴山水曲，今日为君弹。','',''),('quantangshi-04488','卧病家园','陳子昂','quantangshi','','卷5','世上无名子，人间岁月赊。
纵横策已弃，寂寞道为家。
卧病谁能问，闲居空物华。
犹忆灵台友，栖真隐太霞。
还丹奔日御，却老饵云芽。
宁知白社客，不厌青门瓜。','',''),('quantangshi-04489','于长史山池三日曲水宴','陳子昂','quantangshi','','卷5','摘兰藉芳月，祓宴坐廻汀。
泛滟清流满，葳蕤白芷生。
金弦挥赵瑟，玉指弄秦筝。
岩榭风光媚，郊园春树平。
烟花飞御道，罗绮照昆明。
日落红尘合，车马乱纵横。','',''),('quantangshi-04490','合州津口别舍弟至东阳峡步趂不及眷然有忆作以示之','陳子昂','quantangshi','','卷5','江潭共为客，洲浦独迷津。
思积芳庭树，心断白眉人。
同衾成楚越，别岛类胡秦。
林岸随天转，云峰逐望新。
遥遥终不见，默默坐含嚬。
念别疑三月，经游未一旬。
孤舟多逸兴，谁共尔为邻。','',''),('quantangshi-04491','万州晓发放舟乘涨还寄蜀中亲朋','陳子昂','quantangshi','','卷5','空蒙岩雨霁，烂熳晓云归。
啸旅乘明发，奔桡骛断矶。
苍茫林岫转，络绎涨涛飞。
远岸孤烟出，遥峰曙日微。
前瞻未能眴，坐望已相依。
曲直多今古，经过失是非。
还期方浩浩，征思日騑騑。
寄谢千金子，江海事多违。','',''),('quantangshi-04492','入峭峡安居溪伐木溪源幽邃林岭相映有奇致焉','陳子昂','quantangshi','','卷5','肃徒歌伐木，骛檝漾轻舟。
靡迤随廻水，潺湲溯浅流。
烟沙分两岸，露岛夹双洲。
古树连云密，交峰入浪浮。
岩潭相映媚，溪谷屡环周。
路迥光逾逼，山深兴转幽。
麕鼯寒思晚，猿鸟暮声秋。
誓息兰台策，将从桂树游。
因书谢亲爱，千岁觅蓬丘。','',''),('quantangshi-04493','入东阳峡与李明府舟前后不相及','陳子昂','quantangshi','','卷5','东岩初解缆，南浦遂离羣。
出没同洲岛，沿洄异渚濆。
风烟犹可望，歌笑浩难闻。
路转青山合，峰廻白日曛。
奔涛上漫漫，积水下沄沄。
倏忽犹疑及，差池复两分。
离离间远树，蔼蔼没遥氛。
地上巴陵道，星连牛斗文。
孤狖啼寒月，哀鸿呌断云。
仙舟不可见，摇思坐氛氲。','',''),('quantangshi-04494','同旻上人伤寿安傅少府','陳子昂','quantangshi','','卷5','生涯良浩浩，天命固谆谆。
闻道神仙尉，怀德遂为邻。
畴昔逢尧日，衣冠仕汉辰。
交游纷若凤，词翰宛如麟。
太息劳黄绶，长思谒紫宸。
金兰徒有契，玉树已埋尘。
把臂虽无托，平生固亦亲。
援琴一流涕，旧馆几霑巾。
杳杳泉中夜，悠悠世上春。
幽明长隔此，歌哭为何人。','',''),('quantangshi-04495','南山家园林木交映盛夏五月幽然清凉独坐思远率成十韵','陳子昂','quantangshi','','卷5','寂寥守寒巷，幽独卧空林。
松竹生虚白，阶庭横古今。
郁蒸炎夏晚，栋宇閟清阴。
轩窗交紫霭，檐户对苍岑。
凤蕴仙人箓，鸾歌素女琴。
忘机委人代，闭牖察天心。
蛱蝶怜红药，蜻蜓爱碧浔。
坐观万象化，方见百年侵。
扰扰将何息，青青长苦吟。
愿随白云驾，龙鹤相招寻。','',''),('quantangshi-04496','还至张掖古城闻东军告捷赠韦五虚己','陳子昂','quantangshi','','卷5','孟秋首归路，仲月旅边亭。
闻道兰山战，相邀在井陉。
屡鬬关月满，三捷虏云平。
汉军追北地，胡骑走南庭。
君为幕中士，畴昔好言兵。
白虎锋应出，青龙阵几成。
披图见丞相，按节入咸京。
宁知玉门道，翻作陇西行。
北海朱旄落，东归白露生。
纵横未得意，寂寞寡相迎。
负劒空叹息，苍茫登古城。','',''),('quantangshi-04497','题祀山烽树赠乔十二侍御','陳子昂','quantangshi','','卷5','汉庭荣巧宦，云阁薄边功。
可怜骢马使，白首为谁雄。','',''),('quantangshi-04498','初入峡苦风寄故乡亲友','陳子昂','quantangshi','','卷5','故乡今日友，欢会坐应同。
宁知巴峡路，辛苦石尤风。','',''),('quantangshi-04499','题田洗马游岩桔槔','陳子昂','quantangshi','','卷5','望苑长为客，商山遂不归。
谁怜北陵井，未息汉阴机。','',''),('quantangshi-04500','古意题徐令壁','陳子昂','quantangshi','','卷5','白云苍梧来，氛氲万里色。
闻君太平世，栖泊灵台侧。','',''),('quantangshi-04501','赠别冀侍御崔司议','陳子昂','quantangshi','','卷5','有道君匡国，无闷余在林。
白云峨眉上，岁晚来相寻。','',''),('quantangshi-04502','三月三日宴王明府山亭','陳子昂','quantangshi','','卷5','暮春嘉月，上巳芳辰。
羣公禊饮，于洛之滨。
奕奕车骑，粲粲都人。
连帷竞野，袨服缛津。
青郊树密，翠渚萍新。
今我不乐，含意□申。','',''),('quantangshi-04503','唐封泰山乐章 豫和六首 一','張說','quantangshi','','卷5','挹泰坛，紫泰清。
受天命，报天成。
竦皇心，荐乐声。
志上达，歌下迎。','',''),('quantangshi-04504','唐封泰山乐章 豫和六首 二','張說','quantangshi','','卷5','亿上帝，临下庭。
骑日月，陪列星。
嘉视信，大糦声。
澹神心，醉皇灵。','',''),('quantangshi-04505','唐封泰山乐章 豫和六首 三','張說','quantangshi','','卷5','相百辟，贡八荒。
九歌叙，万舞翔。
肃振振，铿皇皇。
帝欣欣，福穰穰。','',''),('quantangshi-04506','唐封泰山乐章 豫和六首 四','張說','quantangshi','','卷5','高在上，道光明。
物资始，德难名。
承眷命，牧苍生。
寰宇谧，泰阶平。','',''),('quantangshi-04507','唐封泰山乐章 豫和六首 五','張說','quantangshi','','卷5','天道无亲，至诚与邻。
山川遍礼，宫征惟新。
玉帛非盛，聪明会真。
正斯一德，通乎百神。','',''),('quantangshi-04508','唐封泰山乐章 豫和六首 六','張說','quantangshi','','卷5','享帝享亲，维孝维圣。
缉熙懿德，敷扬成命。
华夷志同，笙镛礼盛。
明灵降止，感此诚敬。','',''),('quantangshi-04509','唐封泰山乐章 太和','張說','quantangshi','','卷5','孝敬中发，和容外彰。
腾华照宇，如升太阳。
贞璧就奠，玄灵垂光。
礼乐具举，济济洋洋。','',''),('quantangshi-04510','唐封泰山乐章 肃和','張說','quantangshi','','卷5','奠祖配天，承天享帝。
百灵咸秩，四海来祭。
植我苍璧，布我玄制。
华日裴回，神烟容裔。','',''),('quantangshi-04511','唐封泰山乐章 雍和','張說','quantangshi','','卷5','俎豆有馥，粢盛絜丰。
亦有和羹，既戒既平。
鼓钟管磬，肃唱和鸣。
皇皇我祖，来我思成。','',''),('quantangshi-04512','唐封泰山乐章 寿和','張說','quantangshi','','卷5','烝烝我后，享献惟寅。
躬酌郁鬯，跪奠明神。
孝莫孝乎，配上帝亲。
敬莫敬乎，教天下臣。','',''),('quantangshi-04513','唐封泰山乐章 寿和','張說','quantangshi','','卷5','皇祖严配，配享皇天。
皇皇降嘏，天子万年。','',''),('quantangshi-04514','唐封泰山乐章 舒和','張說','quantangshi','','卷5','六钟翕协六变成，八佾徜徉八风生。
乐九[韶]兮[人神]感，美七德兮天地清。','',''),('quantangshi-04515','唐封泰山乐章 凯和','張說','quantangshi','','卷5','烈祖顺三灵，文宗威四海。
黄钺诛羣盗，朱旗扫多罪。
戢兵天下安，约法人心改。
大哉干羽意，常见风云在。','',''),('quantangshi-04516','唐封泰山乐章 豫和','張說','quantangshi','','卷5','礼乐终，[烟]燎上。
怀灵惠，结皇想。
归风疾，回风爽。
百[福]来，众神往。','',''),('quantangshi-04517','唐享太庙乐章 永和三首 一','張說','quantangshi','','卷5','肃九室，谐八音。
歌皇慕，动神心。
礼宿设，乐妙寻。
声明备，裸奠临。','',''),('quantangshi-04518','唐享太庙乐章 永和三首 二','張說','quantangshi','','卷5','律迓气，音入玄。
依玉几，御黼筵。
聆忾息，僾周旋。
九韶徧，百福传。','',''),('quantangshi-04519','唐享太庙乐章 永和三首 三','張說','quantangshi','','卷5','信工祝，永颂声。
来祖考，听和平。
相百辟，贡九瀛。
神休委，帝孝成。','',''),('quantangshi-04520','唐享太庙乐章 太和','張說','quantangshi','','卷5','时文圣后，清庙肃邕。
致诚勤荐，在貌思恭。
玉节肆夏，金锵五钟。
绳绳云步，穆穆天容。','',''),('quantangshi-04521','唐享太庙乐章 肃和','張說','quantangshi','','卷5','天子享孝，工歌溥将。
射裸郁鬯，乃焚膋芗。
臭以达旨，声以求阳。
奉时烝尝，永代不忘。','',''),('quantangshi-04522','唐享太庙乐章 雍和二首 一','張說','quantangshi','','卷5','在涤嘉豢，丽碑敬牲。
角握之牝，色纯之騂。
火传阳燧，水溉阴精。
太公胖俎，傅说和羹。','',''),('quantangshi-04523','唐享太庙乐章 雍和二首 二','張說','quantangshi','','卷5','俎豆有馥，齐盛絜丰。
亦有和羹，既戒既平。
鼓钟管磬，肃唱和鸣。
皇皇后祖，来我思成。','',''),('quantangshi-04524','唐享太庙乐章 文舞','張說','quantangshi','','卷5','圣谟九德，真言五千。
庆集昌胄，符开帝先。
高文杖钺，克配彼天。
三宗握镜，六合涣燃。
帝其承祀，率礼罔愆。
图书雾出，日月清悬。
舞形德类，咏谂功传。
黄龙蜿蟮，彩云蹁跹。
五行气顺，八佾风宣。
介此百禄，于皇万年。','',''),('quantangshi-04525','唐享太庙乐章 光大舞','張說','quantangshi','','卷5','肃肃艺祖，滔滔浚源。
有雄玉劒，作镇金门。
玄王贻绪，后稷谋孙。
肇禋九庙，四海来尊。','',''),('quantangshi-04526','唐享太庙乐章 长发舞','張說','quantangshi','','卷5','具礼崇德，备乐承风。
魏推幢主，周赠司空。
不行而至，无成有终。
神兴王业，天归帝功。','',''),('quantangshi-04527','唐享太庙乐章 大政舞','張說','quantangshi','','卷5','于赫元命，权舆帝文。
天齐八柱，地半三分。
宗庙观德，笙镛乐勋。
封唐之兆，成天下君。','',''),('quantangshi-04528','唐享太庙乐章 大成舞','張說','quantangshi','','卷5','帝舞季历，龙圣生昌。
后歌有蟜，胎炎孕黄。
天地合德，日月齐光。
肃雍孝享，祚我万方。','',''),('quantangshi-04529','唐享太庙乐章 大明舞','張說','quantangshi','','卷5','赤精乱德，四海困穷。
黄旗举义，三灵会同。
早望春雨，云披大风。
溥天来祭，高祖之功。','',''),('quantangshi-04530','唐享太庙乐章 崇德舞','張說','quantangshi','','卷5','皇合一德，朝宗百神。
削平天地，大拯生人。
上帝配食，单于入臣。
戎歌陈武，晔晔震震。','',''),('quantangshi-04531','唐享太庙乐章 钧天舞','張說','quantangshi','','卷5','高皇迈道，端拱无为。
化怀獯鬻，兵[戢]句骊。
礼尊封禅，乐盘来仪。
合位娲后，同称伏羲。','',''),('quantangshi-04532','唐享太庙乐章 大和舞','張說','quantangshi','','卷5','退居江水，郁起丹陵。
礼物还旧，朝章中兴。
龙图友及，骏命恭膺。
鸣球香瓒，大糦是承。','',''),('quantangshi-04533','唐享太庙乐章 景云舞','張說','quantangshi','','卷5','景云霏烂，告我帝符。
噫帝冲德，与天为徒。
笙镛遥远，俎豆虚无。
春秋孝献，回复此都。','',''),('quantangshi-04534','唐享太庙乐章 福和','張說','quantangshi','','卷5','备礼用乐，崇亲致尊。
诚通慈降，敬彻爱存。
献怀称寿，啐感承恩。
皇帝孝德，子孙千亿。
大包天域，长亘不极。','',''),('quantangshi-04535','唐享太庙乐章 舒和','張說','quantangshi','','卷5','六钟翕协六变成，八佾徜徉八风生。
乐九韶兮人神感，美七德兮天地清。','',''),('quantangshi-04536','唐享太庙乐章 凯安三首 一','張說','quantangshi','','卷5','瑟彼瑶爵，亚维上公。
室如屏气，门不容躬。
礼殷其本，乐执其中。
圣皇永慕，天地幽通。','',''),('quantangshi-04537','唐享太庙乐章 凯安三首 二','張說','quantangshi','','卷5','礼匝三献，乐徧九成。
降循轩陛，仰欷皇情。
福与仁合，德因孝明。
百年神畏，四海风行。','',''),('quantangshi-04538','唐享太庙乐章 凯安三首 三','張說','quantangshi','','卷5','总总干戚，填填鼓钟。
奋扬增气，坐作为容。
离若鸷鸟，合如战龙。
万方观德，肃肃邕邕。','',''),('quantangshi-04539','唐享太庙乐章 登歌','張說','quantangshi','','卷5','止笙磬，撤豆笾。
廓无响，窅入玄。
主在室，神在天。
情余慕，礼罔愆。
喜黍稷，屡丰年。','',''),('quantangshi-04540','唐享太庙乐章 永和','張說','quantangshi','','卷5','眇嘉乐，授灵爽。
感若来，思如往。
休气散，回风上。
返寂寞，还惚恍。
怀灵驾，结空想。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-04541','奉和圣制赐诸州刺史应制以题坐右','張說','quantangshi','','卷5','文明遍禹迹，鳏寡达尧心。
正在亲人守，能令王泽深。
朝廷多秀士，镕炼比精金。
犀节同分命，熊轩各外临。
圣主赋新诗，穆若听薰琴。
先言教为本，次言则是钦。
三时农不夺，午夜犬无侵。
愿使天宇内，品物遂浮沈。
寄情羣飞鹤，千里一扬音。
共蹑华胥梦，龚黄安足寻。','',''),('quantangshi-04542','奉和圣制送宇文融安辑户口应制','張說','quantangshi','','卷5','至德临天下，劳情遍九围。
念兹人去本，蓬转将何依。
外避征戍数，内伤亲党稀。
嗟不逢明盛，胡能照隐微。
柏台简行李，兰殿锡朝衣。
别曲动秋风，恩令生春辉。
使出四海安，诏下万心归。
怍非夔龙佐，徒歌鸿雁飞。','',''),('quantangshi-04543','奉和圣制过晋阳宫应制','張說','quantangshi','','卷5','太原俗尚武，高皇初奋庸。
星轩三晋躔，土乐二尧封。
北风遂举鹏，西河亦上龙。
至德起王业，继明赖人雍。
六合启昌期，再兴广圣踪。
传呼大驾来，文物如云从。
连营火百里，纵观人千重。
翠华渡汾水，白日临崒峰。
枌榆恩赏洽，桑梓旧情恭。
往运感不追，清时惜难逢。
诗发尊祖心，颂刊盛德容。
愿君及春事，廻舆绥万邦。','',''),('quantangshi-04544','奉和圣制行次成臯应制','張說','quantangshi','','卷5','夏氏阶隋乱，自言河朔雄。
王师进谷水，兵气临山东。
前扫成臯阵，却下洛阳宫。
义合帝图起，威加天宇同。
轩台百年外，虞典一巡中。
战龙思王业，倚马赋神功。','',''),('quantangshi-04545','奉和圣制温汤对雪应制','張說','quantangshi','','卷5','瑞雪带寒风，寒风入阴琯。
阴琯方凝闭，寒风复凄断。
宫似瑶林匝，庭如月华满。
正赓挟纩词，非近温汤暖。','',''),('quantangshi-04546','奉和圣制义成校猎喜雪应制','張說','quantangshi','','卷5','文教资武功，郊畋阅邦政。
不知仁育久，徒看禽兽盛。
夜霰氛埃灭，朝日山川净。
绰仗飞走繁，抨弦筋角劲。
帝射参神道，龙驰合人性。
五豝连一发，百中皆先命。
勇爵均万夫，雄图罗七圣。
星为吉符老，雪作丰年庆。
喜听行猎诗，威神入军令。','',''),('quantangshi-04547','清明日诏宴宁王山池赋得飞字','張說','quantangshi','','卷5','今日清明宴，佳境惜芳菲。
摇扬花杂下，娇啭鸎乱飞。
绿渚传歌榜，红桥度舞旗。
和风偏应律，细雨不霑衣。
承恩如改火，春去春来归。','',''),('quantangshi-04548','四月十三日诏宴宁王亭子赋得好字','張說','quantangshi','','卷5','何许承恩宴，山亭风日好。
绿嫩鸣鹤洲，阴穠鬬鸡道。
果思夏来茂，花嫌春去早。
行乐无限时，皇情及芳草。','',''),('quantangshi-04549','药园宴武辂沙将军赋得洛字','張說','quantangshi','','卷5','东第乘余兴，南园宴清洛。
文学引邹枚，歌钟陈衞霍。
风高大夫树，露下将军药。
待闻出塞还，丹青上麟阁。','',''),('quantangshi-04550','修书院学士奉敕宴梁王宅赋得树字','張說','quantangshi','','卷5','虎殿成鸿业，猿岩题凤赋。
既荷大君恩，还蒙小山遇。
秋吹迎弦管，凉云生竹树。
共惜朱邸欢，无辞洛城暮。','',''),('quantangshi-04551','夕宴房主簿舍','張說','quantangshi','','卷5','岁晏关雍空，风急河谓冰。
薄游羁物役，微尚惬远凭。
旅馆月宿永，闭扃云思兴。
伊人美修夜，朋酒惠来称。
交谈既清雅，琴吹亦凄凝。
不逢君蹇涸，幽意长郁蒸。','',''),('quantangshi-04552','行从方秀川与刘评事文同宿','張說','quantangshi','','卷5','方秀美盘游，频年降天罕。
水共伊川接，山将阙门断。
捧日照恩华，攀云引疲散。
野宿霜入帐，孤衾寒不暖。
静闻宫漏疎，卧视庭月满。
开炉命温酎，中夜发清管。
风送关山长，气遒星岁短。
寓言情思惬，适兴真意坦。
寰中病羁挂，方外嫌纵诞。
愿君乐盛时，无嗟带纕缓。','',''),('quantangshi-04553','送郭大夫元振再使吐蕃','張說','quantangshi','','卷5','犬戎废东献，汉使驰西极。
长策问酋渠，猜阻自夷殛。
容髪徂边岁，旌裘敝海色。
五年一见家，妻子不相识。
武库兵犹动，金方事未息。
远图待才智，苦节输筋力。
脱刀赠分手，书带加餐食。
知君万里侯，立功在异域。','',''),('quantangshi-04554','送李侍郎逈秀薛长史季昶同赋得水字','張說','quantangshi','','卷5','汉郡接胡庭，幽并对烽垒。
旌旗按部曲，文武惟卿士。
薛公善筹画，李相威边鄙。
中冀分两河，长城各万里。
藉马黄花塞，搜兵白狼水。
胜敌在安人，为君汗青史。','',''),('quantangshi-04555','别平一师','張說','quantangshi','','卷5','王子不事俗，高驾眇难追。
茅土非屑盼，倾城无乐资。
宴坐深林中，三世同一时。
皎皎独往心，不为尘网欺。
朅来已复去，今去何来思。
廻首谢同行，勤会安请期。','',''),('quantangshi-04556','送王光庭','張說','quantangshi','','卷5','同居洛阳陌，经日懒相求。
及尔江湖去，言别怅悠悠。
楚云眇羁翼，海月倦行舟。
爱而不可见，徒嗟芳岁流。','',''),('quantangshi-04557','新都南亭送郭元振卢崇道','張說','quantangshi','','卷5','竹径女萝蹊，莲洲文石堤。
静深人俗断，寻玩往还迷。
碧潭秀初月，素林惊夕栖。
褰幌纳蟾影，理琴听猿啼。
佳辰改宿昔，胜寄坐暌携。
长怀赏心爱，如玉复如圭。','',''),('quantangshi-04558','赠崔公','張說','quantangshi','','卷5','我闻西汉日，四老南山幽。
长歌紫芝秀，高卧白云浮。
朝野光尘绝，榛芜年貌秋。
一朝驱驷马，连辔入龙楼。
昔遯高皇去，今从太子游。
行藏惟圣节，福祸在人谋。
卒能匡惠帝，岂不赖留侯。
事随年代远，名与图籍留。
平生钦淳德，慷慨景前修。
蜯蛤伺阴兔，蛟龙望斗牛。
无嗟异飞伏，同气幸相求。','',''),('quantangshi-04559','赠赵公','張說','quantangshi','','卷5','湘东股肱守，心与帝乡期。
舟楫中途蹇，风波复来思。
嘉我常联翼，金貂侍玉墀。
迹参前马圣，名缀鬻熊师。
寒暑一何速，山川远间之。
宁知洞庭上，独得平生时。
精意微绝简，从权讨妙棋。
林壑为予请，纷霭发华滋。
流赏忽已散，惊帆杳难追。
送君在南浦，侘傺投此词。','',''),('quantangshi-04560','赠赵侍御','張說','quantangshi','','卷5','禄放迹异端，偏荒事同蹇。
苟忘风波累，俱会云壑践。
险式压西湖，侨庐对南岘。
夜楼江月入，朝幌山云卷。
山势远涛连，江途斜汉转。
坐啸予多暇，行吟子独善。
并辔躧郊郭，方舟玩游演。
虚声万籁分，水色千里辨。
不知岸阴谢，再见春露泫。
绿壤发欣颜，华年助虫篆。
上世时难接，古人情可选。
泊渚烦为媒，多才怨成褊。
长沙鵩作赋，任道可知浅。
请从三已心，荣辱两都遣。','',''),('quantangshi-04561','答李伯鱼桐竹','張說','quantangshi','','卷5','结庐桐竹下，室迩人相深。
接垣分竹径，隔户共桐阴。
落花朝满岸，明月夜披林。
竹有龙鸣管，桐留凤舞琴。
奇声与高节，非吾谁赏心。','',''),('quantangshi-04562','寄姚司马','張說','quantangshi','','卷5','共君春种瓜，本期清夏暑。
瓜成人已去，失望将谁语。
裛露摘香园，感味怀心许。
偶逢西风便，因之寄鄂渚。','',''),('quantangshi-04563','代书答姜七崔九','張說','quantangshi','','卷5','婀娜金闺树，离披野田草。
虽殊两地荣，幸共三春好。
花殊鸟飞处，叶镂虫行道。
真心独感人，惆怅令人老。','',''),('quantangshi-04564','代书寄吉十一','張說','quantangshi','','卷5','一雁雪上飞，值我衡阳道。
口衔离别字，远寄当归草。
目想春来迟，心惊寒去早。
忆乡乘羽翮，慕侣盈怀抱。
零落答故人，将随江树老。','',''),('quantangshi-04565','代书寄薛四','張說','quantangshi','','卷5','孤雁东飞来，寄我纹与素。
纹足经三象，素当综羣务。
远见故人心，一言重千金。
答之彩毛翰，继以瑶华音。
岁寒众木改，松柏心常在。','',''),('quantangshi-04566','过蜀道山','張說','quantangshi','','卷5','我行春三月，山中百花开。
披林入峭蒨，攀磴陟崔嵬。
白云半峰起，清江出峡来。
谁知高深意，缅邈心幽哉。','',''),('quantangshi-04567','蜀路二首 一','張說','quantangshi','','卷5','云埃夜澄廓，山日晓晴鲜。
叶落苍江岸，鸿飞白露天。
磷磷含水石，幂幂覆林烟。
客心久无绪，秋风殊未然。','',''),('quantangshi-04568','蜀路二首 二','張說','quantangshi','','卷5','徭蜀时未改，别家乡念盈。
忆昨出门日，春风发鲜荣。
及兹旋辕地，秋风满路生。
昏晓思魏阙，梦寐还秦京。
秦京开朱第，魏阙垂紫缨。
幽独玄虚阁，不闻人马声。
艺业为君重，名位为君轻。
玉琴知调苦，宝镜对胆清。
鹰饥常啄腥，凤饥亦待琼。
于君自有属，物外岂能轻。','',''),('quantangshi-04569','再使蜀道','張說','quantangshi','','卷5','眇眇葭萌道，苍苍褒斜谷。
烟壑争晦深，云山共重复。
古来风尘子，同眩望乡目。
芸阁有儒生，轺车倦驰逐。
青春客岷岭，白露摇江服。
岁月镇羁孤，山川俄反覆。
鱼游恋深水，鸟迁恋乔木。
如何别亲爱，坐去文章国。
蟋蟀鸣户庭，蟏蛸网琴筑。','',''),('quantangshi-04570','江路忆郡','張說','quantangshi','','卷5','雾敛江早明，星翻汉将没。
卧闻峡猿响，起视榜人发。
倚棹攀岸筱，凭船弄波月。
水宿厌洲渚，晨光屡挥忽。
林泽来不穷，烟波去无歇。
结思笙竽里，摇情游侠窟。
年貌不暂留，欢愉及玄髪。
云涓恋山海，禽马怀燕越。
自非行役人，安知慕城阙。','',''),('quantangshi-04571','过汉南城叹古坟','張說','quantangshi','','卷5','旧国多陵墓，荒凉无岁年。
汹涌蔽平冈，汩若波涛连。
上世千金子，潜卧九重泉。
松柏剪无余，碑记灭罔传。
葬于不毛地，咸谓楚先贤。
事尽情可识，使人心怅然。','',''),('quantangshi-04572','至尉氏','張說','quantangshi','','卷5','夕次阮公台，啸歌临爽垲。
高名安足赖，故物今皆改。
吾兄昔兹邑，遗爱称贤宰。
桑中雉未飞，屋上乌犹在。
途逢旧甿吏，城有同僚寀。
望尘远见迎，拂馆来欣待。
慈惠留千室，友于存四海。
始知鲁衞间，优劣相悬倍。','',''),('quantangshi-04573','襄州景空寺题融上人兰若','張說','quantangshi','','卷5','高名出汉阴，禅阁跨香岑。
众山既围绕，长川复回临。
云峰晓灵变，风木夜虚吟。
碧湫龙池满，苍松虎径深。
旧知青岩意，偏入杳冥心。
何由侣飞锡，从此脱朝簪。','',''),('quantangshi-04574','巡边在河北作','張說','quantangshi','','卷5','抚劒空余勇，弯弧遂无力。
老去事如何，据鞍长叹息。
故交索将尽，后进稀相识。
独怜半死心，尚有寒松直。','',''),('quantangshi-04575','入海二首 一','張說','quantangshi','','卷5','乘桴入南海，海旷不可临。
茫茫失方面，混混如凝阴。
云山相出没，天地互浮沈。
万里无涯际，云何测广深。
潮波自盈缩，安得会虚心。','',''),('quantangshi-04576','入海二首 二','張說','quantangshi','','卷5','海上三神山，逍遥集众仙。
灵心岂不同，变化无常全。
龙伯如人类，一钓两鳌连。
金台此沦没，玉真时播迁。
问子劳何事，江上泣经年。
隰中生红草，所美非美然。','',''),('quantangshi-04577','相州山池作','張說','quantangshi','','卷5','尝怀谢公咏，山水陶嘉月。
及此年事衰，徒看众花发。
观鱼乐何在，听鸟情都歇。
星汉流不停，蓬莱去难越。
邺中秋麦秀，淇上春云没。
日见尘物空，如何静心阙。','',''),('quantangshi-04578','岳州作','張說','quantangshi','','卷5','夜梦云阙间，从容簪履列。
朝游洞庭上，缅望京华绝。
潦收江未清，火退山更热。
重欷视欲醉，懵满气如噎。
器留鱼鼈腥，衣点蚊虻血。
髪白思益壮，心玄用弥拙。
冠劒日苔藓，琴书坐废撤。
唯有报恩字，刻意长不灭。','',''),('quantangshi-04579','岳州行郡竹篱','張說','quantangshi','','卷5','山郡不沟郭，荒居无翳壅。
爱人忠主利，善守闭为勇。
苟非小勤瘁，安得期逸宠。
版筑恐土疎，襄城嫌役重。
藩栅聊可固，筠篁近易奉。
差池截浦沙，缭绕缘隈壠。
矗似长云亘，森如高戟耸。
预绝豺狼忧，知免牛羊恐。
闾里宽矫步，榛丛恣踏踵。
始果游处心，终日成闲拱。','',''),('quantangshi-04580','游洞庭湖湘','張說','quantangshi','','卷5','缅邈洞庭岫，葱蒙水雾色。
宛在太湖中，可望不可即。
剖竹守穷渚，开门对奇域。
城池自絷笼，缨绶为徽纆。
靡日不思往，经时始愿克。
飞棹越溟波，维舟恣攀陟。
䆗窱入云步，崎岖倚松息。
岩坛有鹤过，壁字无人识。
滴石香乳溜，垂崖灵草植。
玩幽轻雾阻，讨异忘曛逼。
寒沙际水平，霜树笼烟直。
空宫闻莫覩，地道窥难测。
此处学金丹，何人生羽翼。
谁传九光要，几拜三仙职。
紫气徒想像，清潭长眇默。
霓裳若有来，觏我云峰侧。','',''),('quantangshi-04581','㴩湖山寺','張說','quantangshi','','卷5','楚老游山寺，提携观画壁。
扬袂指辟支，睩眄相鬬阋。
险哉透撞儿，千金赌一掷。
成败身自受，傍人那叹息。','',''),('quantangshi-04582','出湖寄赵冬曦','張說','quantangshi','','卷5','西泛平湖尽，参差入乱山。
东瞻岳阳郡，汗漫太虚间。
窘步同行乐，遒文互屡看。
山戍上云桂，江亭临水关。
川途倏忽间，风景依如昨。
湘浦未赐环，荆门犹主诺。','',''),('quantangshi-04583','岳阳早霁南楼','張說','quantangshi','','卷5','山水佳新霁，南楼玩初旭。
夜来枝半红，雨后洲全绿。
四运相终始，万形纷代续。
适临青草湖，再变黄鸎曲。
地穴穿东武，江流下西蜀。
歌闻枉渚邅，舞见长沙促。
心阻意徒驰，神和生自足。
白髪悲上春，知常谢先欲。','',''),('quantangshi-04584','岳阳石门墨山二山相连有禅堂观天下绝境','張說','quantangshi','','卷5','囷轮江上山，近在华容县。
常涉巴丘首，天晴遥可见。
佳游屡前诺，芳月愆幽眷。
及此符守移，欢言临道便。
既携赏心客，复有送行掾。
竹径入阴窅，松萝上空蒨。
草共林一色，云与峰万变。
探窥石门断，缘越沙涧转。
两山势争雄，峰巘相顾眄。
药妙灵仙宝，境华岩壑选。
清都西渊绝，金地东敞宴。
池果接园畦，风烟迩台殿。
高寻去石顶，旷览天宇遍。
千山纷满目，百川豁对面。
骑来云气迎，人去鸟声恋。
长揖桃源士，举世同企羡。','',''),('quantangshi-04585','和尹懋秋夜游㴩湖','張說','quantangshi','','卷5','坐啸人事闲，佳游野情发。
山门送落照，湖口升微月。
林寻猿狖居，水戏鼋鼍穴。
朔风吹飞雁，芳草亦云歇。','',''),('quantangshi-04586','五君咏五首 魏齐公元忠','張說','quantangshi','','卷5','齐公生人表，逈天闻鹤唳。
清论早揣摩，玄心晚超诣。
入相廊庙静，出军沙漠霁。
见深吕禄忧，举后陈平计。
甘心除君恶，足以报先帝。','',''),('quantangshi-04587','五君咏五首 苏许公瓌','張說','quantangshi','','卷5','许公信国桢，克美具瞻情。
百事资朝问，三章广世程。
处高心不有，临节自为名。
朱户传新戟，青松拱旧茔。
凄凉丞相府，余庆在玄成。','',''),('quantangshi-04588','五君咏五首 李赵公峤','張說','quantangshi','','卷5','李公实神敏，才华乃天授。
睦亲何用心，处贵不忘旧。
故事遵台阁，新诗冠宇宙。
在人忠所奉，恶我诚将宥。
南浦去莫归，嗟嗟蔑孙秀。','',''),('quantangshi-04589','五君咏五首 郭代公元振','張說','quantangshi','','卷5','代公举鹏翼，悬飞摩海雾。
志康天地屯，适与云雷遇。
兴丧一言决，安危万心注。
大勋书王府，舛命沦江路。
势倾北夏门，哀靡东平树。','',''),('quantangshi-04590','五君咏五首 赵耿公彦昭','張說','quantangshi','','卷5','耿公山岳秀，才杰心亦妙。
鸷鸟峻标立，哀玉扣清调。
协赞休明启，恩华日月照。
何意瑶台云，风吹落江徼。
湘流下浔阳，洒泪一投吊。','',''),('quantangshi-04591','游龙山静胜寺','張說','quantangshi','','卷5','每上襄阳楼，遥望龙山树。
郁茀吐冈岭，微蒙在烟雾。
下车岁已成，饰马闲余步。
苦霜裛野草，爱日扬江煦。
云对石上塔，风吹松下路。
禅室宴三空，神祠同六趣。
儿童共戏谑，猿鸟相惊顾。
南识桓公台，北望先贤墓。
世上人何在，时闻心不住。
但传无尽灯，可使有情悟。','',''),('quantangshi-04592','一柱观','張說','quantangshi','','卷5','旧说江陵观，初疑神化来。
空山结云阁，绮靡随风回。
奈何任一柱，斯焉容众材。
奇功非长世，今余草露台。','',''),('quantangshi-04593','登九里台是樊姬墓','張說','quantangshi','','卷5','楚国所以霸，樊姬有力焉。
不怀沈尹禄，谁谙叔敖贤。
万化茫无在，孤坟独岿然。
北分阳台陌，南识郢城阡。
漠漠渚宫树，苍苍云梦田。
登高形胜出，访古令名传。
自我来符守，因君树蕙荃。
诗书将变俗，絺纩忽弥年。
志阐三折后，愁值二毛前。
伫立帝京路，遥心寄此篇。','',''),('quantangshi-04594','过怀王墓','張說','quantangshi','','卷5','咿嚘不可信，以此败怀王。
客死峣关路，返葬岐江阳。
啼狖抱山月，饥狐猎野霜。
一闻怀沙事，千载尽悲凉。','',''),('quantangshi-04595','闻雨','張說','quantangshi','','卷5','多雨绝尘事，寥寥入太玄。
城阴疎复合，檐滴断还连。
念我劳造化，从来五十年。
误将心徇物，近得还自然。
闲居草木侍，虚室鬼神怜。
有时进美酒，有时泛清弦。
声真不世识，心醉岂言诠。','',''),('quantangshi-04596','夜坐','張說','quantangshi','','卷5','怀哉四壁时，未有五都价。
百金谁见许，斗酒难为贳。
落花生芳春，孤月皎清夜。
复逢利交客，题户遥相谢。','',''),('quantangshi-04597','山夜闻钟','張說','quantangshi','','卷5','夜卧闻夜钟，夜静山更响。
霜风吹寒月，䆗窱虚中上。
前声既舂容，后声复晃荡。
听之如可见，寻之定无像。
信知本际空，徒挂生灭想。','',''),('quantangshi-04598','冬日见牧牛人担青草归','張說','quantangshi','','卷5','塞上绵应折，江南草可结。
欲持梅岭花，远竞榆关雪。
日月无他照，山川何顿别。
苟齐两地心，天问将安说。','',''),('quantangshi-04599','咏镜','張說','quantangshi','','卷5','宝镜如明月，出自秦宫样。
隐起双蟠龙，衔珠俨相向。
常恐君不察，匣中委清量。
积翳掩菱花，虚心蔽尘状。
倘蒙罗袖拂，光生玉台上。','',''),('quantangshi-04600','咏瓢','張說','quantangshi','','卷5','美酒酌悬瓢，真淳好相映。
蜗房卷堕首，鹤颈抽长柄。
雅色素而黄，虚心轻且劲。
岂无雕刻者，贵此成天性。','',''),('quantangshi-04601','杂诗四首 一','張說','quantangshi','','卷5','抱薰心常焦，举斾心常摇。
天长地自久，欢乐能几朝。
君看西陵树，歌舞为谁娇。','',''),('quantangshi-04602','杂诗四首 二','張說','quantangshi','','卷5','山闲苦积雨，木落悲时遽。
赏心凡几人，良辰在何处？
触石满堂侈，洒我终夕虑。
客鸟怀主人，衔花未能去。
剖珠贵分明，琢玉思坚贞。
要君意如此，终始莫相轻。','',''),('quantangshi-04603','杂诗四首 三','張說','quantangshi','','卷5','问子青霞意，何事留朱轩。
自言心远俗，未始迹辞喧。
过蒙良时幸，侧息吏途烦。
簪缨非宿好，文史弃前言。
夕卧北窗下，梦归南山园。
白云慙幽谷，清风愧泉源。
十年兹赏废，佳期今复存。
挂冠谢朝侣，星驾别君门。','',''),('quantangshi-04604','杂诗四首 四','張說','quantangshi','','卷5','默念羣疑起，玄通百虑清。
初心灭阳艳，复见湛虚明。
悟灭心非尽，求虚见后生。
应将无住法，修到不成名。','',''),('quantangshi-04605','和张监游终南','張說','quantangshi','','卷5','宿怀终南意，及此语云峰。
夜闻竹涧静，晓望林岭重。
春烟生古石，时鸟戏幽松。
岂无山中赏，但畏心莫从。','',''),('quantangshi-04606','古泉驿','張說','quantangshi','','卷5','昔闻陈仲子，守义辞三公。
身赁妻织屦，乐亦在其中。
岂无穷贱苦，羞与倾巧同。
长白临河上，于陵入济东。
我行吊遗迹，感叹古泉空。','',''),('quantangshi-04607','河上公','張說','quantangshi','','卷5','尊师厌尘去，精魄知何明。
形气不复生，弟子空伤情。
济北神如在，淮南药未成。
共期终莫遂，寥落两无成。','',''),('quantangshi-04608','奉和圣制初入秦川路寒食应制','張說','quantangshi','','卷5','上阳柳色唤春归，临渭桃花拂水飞。
总为朝廷巡幸去，顿教京洛少光辉。
昨从分陕山南口，驰道依依渐花柳。
入关正投寒食前，还京遂落清明后。
路上天心重豫游，御前恩赐特风流。
便幕那能镂鸡子，行宫善巧帖毛球。
渭桥南渡花如扑，麦陇青青断人目。
汉家行树直新丰，秦地骊山抱温谷。
香池春溜水初平，预欢浴日照京城。
今岁随宜过寒食，明年陪宴作清明。','',''),('quantangshi-04609','时乐鸟篇','張說','quantangshi','','卷5','旧传南海出灵禽，时乐名闻不可寻。
形貌乍同鹦鹉类，精神别禀凤皇心。
千年待圣方轻举，万里呈才无伴侣。
红茸糅绣好毛衣，清泠讴鵶好言语。
内人试取御衣牵，啄手暝声不许前。
心愿阳乌恒保日，志嫌阴鹤欲凌天。
天情玩讶良无已，察图果见祥经里。
本持符瑞验明王，还用文章比君子。
自怜弱羽讵堪珍，喜共华篇来示人。
人见嘤嘤报恩鸟，多慙碌碌具官臣。','',''),('quantangshi-04610','安乐郡主花烛行','張說','quantangshi','','卷5','青宫朱邸翊皇闱，玉叶琼蕤发紫微。
姬姜本来舅甥国，卜筮俱道凤皇飞。
星昴殷冬献吉日，夭桃穠李遥相匹。
鸾车凤传王子来，龙楼月殿天孙出。
平台火树连上阳，紫炬红轮十二行。
丹炉飞铁驰炎焰，炎霞烁电吐明光。
绿軿绀幰纷如雾，节鼓清笳前启路。
城隅靡靡稍东还，桥上鳞鳞转南渡。
五方观者聚中京，四合尘烟涨洛城。
商女香车珠结网，天人宝马玉繁缨。
百壶渌酒千斤肉，大道连延障锦轴。
先祝圣人寿万年，复祷宜家承百禄。
珊瑚刻盘青玉尊，因之假道入梁园。
梁园山竹凝云汉，仰望高楼在天半。
翠幕兰堂苏合薰，珠帘挂户水波纹。
别起芙蓉织成帐，金镂鸳鸯两相向。
罽茵饰地承雕履，花烛分阶移锦帐。
织女西垂隐烛台，双童连缕合欢杯。
蔼蔼绮庭嫔从列，娥娥红粉扇中开。
黄金两印双花绶，富贵婚姻古无有。
清歌棠棣美王姬，流化邦人正夫妇。','',''),('quantangshi-04611','离会曲','張說','quantangshi','','卷5','何处送客洛桥头，洛水泛泛中行舟。
可怜河树叶萎蕤，关关河鸟声相思。
街鼓喧喧日将夕，去棹归轩两相迫。','',''),('quantangshi-04612','邺都引','張說','quantangshi','','卷5','君不见魏武草创争天禄，羣雄睚眦相驰逐。
昼携壮士破坚阵，夜接词人赋华屋。
都邑缭绕西山阳，桑榆汗漫漳河曲。
城郭为虚人代改，但有西园明月在。
邺傍高冢多贵臣，娥眉𥊑睩共灰尘。
试上铜台歌舞处，唯有秋风愁杀人。','',''),('quantangshi-04613','城南亭作','張說','quantangshi','','卷5','珂马朝归连万石，矟门洞启亲迎客。
北堂珍重琥珀酒，庭前列肆茱萸席。
长袖迟回意绪多，清商缓转[目]腾波。
旧传比翼侯家舞，新出将雏主第歌。
汉家绛灌余兵气，晋代浮虚安足贵。
正逢天下金镜清，偏加日饮醇醪意。
谁复遨游不复归，闲庭莫畏不芳菲。
会待城南春色至，竟将花柳拂罗衣。','',''),('quantangshi-04614','同赵侍御干湖作','張說','quantangshi','','卷5','江南湖水咽山川，春江溢入共湖连。
气色纷沦横罩海，波涛鼓怒上漫天。
鳞宗壳族嬉为府，弋叟罛师利焉聚。
欹帆侧柁弄风口，赴险临深绕湾浦。
一湾一浦怅邅回，千曲千溠怳迷哉。
乍见灵妃含笑往，复闻游女怨歌来。
暑来寒往运洄洑，潭生水落移陵谷。
云间坠翮散泥沙，波上浮查栖树木。
昨暮飞霜下北津，今朝行雁度南滨。
处处沟洚清源竭，年年旧苇白头新。
天地盈虚尚难保，人间倚伏何须道。
秋月皛皛泛澄澜，冬景青青步纤草。
念君宿昔观物变，安得踌蹰不衰老。','',''),('quantangshi-04615','巡边在河北作','張說','quantangshi','','卷5','去年六月西河西，今年六月北河北。
沙场碛路何为尔，重气轻生知许国。
人生在世能几时，壮年征战髪如丝。
会待安边报明主，作颂封山也未迟。','',''),('quantangshi-04616','赠崔二安平公乐世词','張說','quantangshi','','卷5','十五红妆侍绮楼，朝承握槊夜藏钩。
君臣一意金门宠，兄弟双飞玉殿游。
宁知宿昔恩华乐，变作潇湘离别愁。
地湿莓苔生舞袖，江声怨叹入箜篌。
自怜京兆双眉妩，会待南来五马留。','',''),('quantangshi-04617','送尹补阙元凯琴歌','張說','quantangshi','','卷5','凤哉凤哉！啄琅玕。
饮瑶池，栖昆仑之山哉。
中国有圣人，感和气。
飞来飞来，自歌自舞。
先王册府，麒鳞之台。
羇雌众雏故山曲，其鸣喈喈。
其鸣喈喈，欲往衔之歘去来。
去别鸾凤心徘徊，明年阿阁梧桐花叶开。
羣飞凤归来，羣飞凤归来。','',''),('quantangshi-04618','送考功武员外学士使嵩山署舍利塔','張說','quantangshi','','卷5','怀玉泉，恋仁者，寂灭真心不可见。
空留影塔嵩岩下，宝王四海转千轮。
金昙百粒送分身，山中二月娑罗会。
虚呗遥遥愁思人，我念过去微尘劫。
与子禅门同正法，虽在神仙兰省间。
常持清净莲花叶，来亦好，去亦好。
了观车行马不移，当见菩提离烦恼。','',''),('quantangshi-04619','遥同蔡起居偃松篇','張說','quantangshi','','卷5','清都众木总荣芬，传道孤松最出羣。
名接天庭长景色，气连宫阙借氛氲。
悬池的的停华露，偃盖重重拂瑞云。
不借流膏助仙鼎，愿将桢干捧明君。
莫比冥灵楚南树，朽老江边代不闻。','',''),('quantangshi-04620','奉和圣制登骊山瞩眺应制','張說','quantangshi','','卷5','寒山上半空，临眺尽寰中。
是日巡游处，晴光远近同。
川明分渭水，树暗辨新丰。
岩壑清音暮，天歌起大风。','',''),('quantangshi-04621','奉和圣制幸白鹿观应制','張說','quantangshi','','卷5','洞府寒山曲，天游日旰回。
披云看石镜，拂雪上金台。
竹径龙骖下，松庭鹤辔来。
双童还献药，五色耀仙材。','',''),('quantangshi-04622','奉和圣制送金城公主适西蕃应制','張說','quantangshi','','卷5','青海和亲日，潢星出降时。
戎王子壻宠，汉国舅家慈。
春野开离宴，云天起别词。
空弹马上曲，讵减凤楼思。','',''),('quantangshi-04623','奉和同皇太子过慈恩寺应制二首 一','張說','quantangshi','','卷5','翼翼宸恩永，煌煌福地开。
离光升宝殿，震气绕香台。
上界幡花合，中天伎乐来。
愿君无量寿，仙乐屡徘徊。','',''),('quantangshi-04624','奉和同皇太子过慈恩寺应制二首 二','張說','quantangshi','','卷5','朗朗神居峻，轩轩瑞象威。
圣君成愿果，太子拂天衣。
至乐三灵会，深仁四皓归。
还闻涡水曲，更绕白云飞。','',''),('quantangshi-04625','侍宴武三思山第应制赋得风字','張說','quantangshi','','卷5','梁王池馆好，晓日凤楼通。
竹町罗千衞，兰筵降两宫。
清歌芳树下，妙舞落花中。
臣觉筵中听，还如大国风。','',''),('quantangshi-04626','奉和圣制过宁王宅应制','張說','quantangshi','','卷5','进酒忘忧观，箫韶喜降临。
帝尧敦族礼，王季友兄心。
竹院龙鸣笛，梧宫凤遶林。
大风将小雅，一字尽千金。','',''),('quantangshi-04627','奉和圣制同玉真公主过大哥山池题石壁应制','張說','quantangshi','','卷5','绿竹初成苑，丹砂欲化金。
乘龙与骖凤，歌吹满山林。
爽气凝情逈，寒光映浦深。
忘忧题此观，为乐赏同心。','',''),('quantangshi-04628','奉和圣制赐王公千秋镜应制','張說','quantangshi','','卷5','宝镜颁神节，凝规写圣情。
千秋题作字，长寿带为名。
月向天边下，花从日里生。
不承悬象意，谁辨照心明。','',''),('quantangshi-04629','奉和圣制经邹鲁祭孔子应制','張說','quantangshi','','卷5','孔圣家邹鲁，儒风蔼典坟。
龙骖廻旧宅，凤德咏余芬。
入室神如在，升堂乐似闻。
悬知一王法，今日待明君。','',''),('quantangshi-04630','侍宴蘘荷亭应制','張說','quantangshi','','卷5','回銮青岳观，帐殿紫烟峰。
仙路迎三鸟，云衢驻两龙。
园林看化塔，坛墠识余封。
山外闻箫管，还如天上逢。','',''),('quantangshi-04631','侍宴浐水赋得浓字','張說','quantangshi','','卷5','千行发御柳，一叶下仙筇。
青浦宸游至，朱城佳气浓。
云霞交暮色，草树喜春容。
蔼蔼天旗转，清笳入九重。','',''),('quantangshi-04632','奉和圣制同刘晃喜雨应制','張說','quantangshi','','卷5','青气含春雨，知从岱岳来。
行云避师出，洒雨待车廻。
厌浥尘清道，空蒙柳映台。
最宜三五夜，晴月九重开。','',''),('quantangshi-04633','奉和圣制观拔河俗戏应制','張說','quantangshi','','卷5','今岁好拖钩，横衔敞御楼。
长绳系日住，贯索挽河流。
鬬力频催鼓，争都更上筹。
春来百种戏，天意在宜秋。','',''),('quantangshi-04634','奉和圣制途次陕州应制','張說','quantangshi','','卷5','周召尝分陕，诗书空复传。
何如万乘睠，追赏二南篇。
郡带洪河侧，宫临大道边。
洛城将日近，佳气满山川。','',''),('quantangshi-04635','奉和圣制野次喜雪应制','張說','quantangshi','','卷5','寒更玉漏催，晓色御前开。
泱漭云阴积，氤氲风雪廻。
山知银作瓮，宫见璧成台。
欲验丰年象，飘摇仙藻来。','',''),('quantangshi-04636','奉和圣制温泉言志应制','張說','quantangshi','','卷5','温谷媚新丰，骊山横半空。
汤池薰水殿，翠木暖烟宫。
起疾逾仙药，无私合圣功。
始知尧舜德，心与万人同。','',''),('quantangshi-04637','皇帝降诞日集贤殿赐宴','張說','quantangshi','','卷5','仲秋金帝起，五日土行昭。
瑞表壬寅露，光传甲子宵。
阴风吹大泽，梦日照昌朝。
不独华封老，千年喜祝尧。','',''),('quantangshi-04638','晦日诏宴永穆公主亭子赋得流字','張說','quantangshi','','卷5','堂邑山林美，朝恩晦日游。
园亭含淑气，竹树遶春流。
舞席千花妓，歌船五彩楼。
羣欢与王泽，岁岁满皇州。','',''),('quantangshi-04639','恩制赐食于丽正殿书院宴赋得林字','張說','quantangshi','','卷5','东壁图书府，西园翰墨林。
诵诗闻国政，讲易见天心。
位窃和羹重，恩叨醉酒深。
缓歌春兴曲，情竭为知音。','',''),('quantangshi-04640','羽林恩召观御书王太尉碑','張說','quantangshi','','卷5','陇首名公石，来承圣札归。
鱼龙生意态，钩劒动铓辉。
字得神明保，词慙少女徽。
谁家羽林将，又逐凤书飞。','',''),('quantangshi-04641','东都酺宴四首 一','張說','quantangshi','','卷5','重华升宝历，轩帝眇闲居。
政成天子孝，俗返上皇初。
忘味因观乐，欢心寄合酺。
自怜疲马意，恋恋主恩余。','',''),('quantangshi-04642','东都酺宴四首 二','張說','quantangshi','','卷5','朱城尘曀灭，翠幕景情开。
震震灵鼍起，翔翔舞凤来。
雕盘装草树，绮乘结楼台。
共喜光华日，酣歌捧玉杯。','',''),('quantangshi-04643','东都酺宴四首 三','張說','quantangshi','','卷5','晓月调金阙，朝暾对玉盘。
争驰羣鸟散，鬬伎百花团。
遇圣人知幸，承恩物自欢。
洛桥将举烛，醉舞拂归鞍。','',''),('quantangshi-04644','东都酺宴四首 四','張說','quantangshi','','卷5','恺宴惟今席，余欢殊未穷。
入云歌袅袅，向日伎丛丛。
驶管催酣兴，留关待曲终。
长安若为乐，应与万方同。','',''),('quantangshi-04645','道家四首奉敕撰 一','張說','quantangshi','','卷5','金坛启曙闱，真气肃微微。
落月衔仙窦，初霞拂羽衣。
香随龙节下，云逐凤箫飞。
暂住蓬莱戏，千年始一归。','',''),('quantangshi-04646','道家四首奉敕撰 二','張說','quantangshi','','卷5','窈窕流精观，深沈紫翠庭。
金匳调上药，宝案读仙经。
作赋看神雨，乘槎辨客星。
秪应谢人俗，轻举托云軿。','',''),('quantangshi-04647','道家四首奉敕撰 三','張說','quantangshi','','卷5','金炉承道诀，玉牒启玄机。
云逐笙歌度，星流宫殿飞。
乘风嬉浩荡，窥月弄光辉。
唯有三山鹤，应同千载归。','',''),('quantangshi-04648','道家四首奉敕撰 四','張說','quantangshi','','卷5','道记开中箓，真官表上清。
焚香三鸟至，炼药九仙成。
天上灵书下，空中妙伎迎。
迎来出烟雾，渺渺戏蓬瀛。','',''),('quantangshi-04649','凤楼寻胜地','張說','quantangshi','','卷5','西掖持醇酒，东山就白云。
开轩绿池映，命席紫兰芬。
舞度花为伴，莺来管作羣。
太平多乐事，春物共氛氲。','',''),('quantangshi-04650','幽州夜饮','張說','quantangshi','','卷5','凉风吹夜雨，萧瑟动寒林。
正有高堂宴，能忘迟暮心。
军中宜劒舞，塞上重笳音。
不作边城将，谁知恩遇深。','',''),('quantangshi-04651','崔礼部园亭得深字','張說','quantangshi','','卷5','窈窕留清馆，虚徐步晚阴。
水连伊阙近，树接夏阳深。
柳蔓怜垂拂，藤梢爱上寻。
讶君轩盖侣，非复俗人心。','',''),('quantangshi-04652','送郑大夫惟忠从公主入蕃','張說','quantangshi','','卷5','凤吹遥将断，龙旗送欲还。
倾都邀节使，传酌缓离颜。
春碛沙连海，秋城月对关。
和戎因赏魏，定远莫辞班。','',''),('quantangshi-04653','送崔二长史日知赴潞州','張說','quantangshi','','卷5','东山怀卧理，南省怅悲翁。
共见前途促，何知后会同。
莫轻一筵宴，明日半成空。
况尔新离阙，思归迷梦中。','',''),('quantangshi-04654','同贺八送兖公赴荆州','張說','quantangshi','','卷5','畴昔同声友，骞飞出凤池。
风云一荡薄，日月屡参差。
此别黄叶下，前期安可知。
谁怜楚南树，不为岁寒移。','',''),('quantangshi-04655','饯唐州高使君','張說','quantangshi','','卷5','常时好闲独，朋旧少相过。
及尔宣风去，方嗟别日多。
淮流春晼晚，江海路蹉跎。
百岁屡分散，欢言复几何。','',''),('quantangshi-04656','送王晙自羽林赴永昌令','張說','quantangshi','','卷5','将星移北洛，神雨避东京。
为负刚肠誉，还追强项名。
白云向伊阙，黄叶散昆明。
多谢弦歌宰，稀闻桴鼓声。','',''),('quantangshi-04657','同王仆射山亭饯岑广武羲得言字','張說','quantangshi','','卷5','闻道长岑令，奋翼宰旅门。
长安东陌上，送客满朱轩。
琴爵留佳境，山池借好园。
兹游恨不见，别后缀离言。','',''),('quantangshi-04658','送任御史江南发粮以赈河北百姓','張說','quantangshi','','卷5','河朔人无岁，荆南义廪开。
将兴泛舟役，必仗济川才。
夜月临江浦，春云历楚台。
调饥坐相望，绣服几时回。','',''),('quantangshi-04659','送王尚一严嶷二侍御赴司马都督军','張說','quantangshi','','卷5','汉掖通沙塞，边兵护草腓。
将行司马令，助以铁冠威。
白露鹰初下，黄尘骑欲飞。
明年春酒熟，留酌二星归。','',''),('quantangshi-04660','送李问政河北简兵','張說','quantangshi','','卷5','斗酒贻朋爱，踌蹰出御沟。
依然四牡别，更想八龙游。
密亲仕燕冀，连年迩寇讐。
因君阅河朔，垂泪语幽州。','',''),('quantangshi-04661','送薛植入京','張說','quantangshi','','卷5','青组言从史，鸿都忽见求。
款言人向老，饮别岁方秋。
仿髴长安陌，平生是旧游。
何时复相遇，宛在水中流。','',''),('quantangshi-04662','相州前池别许郑二判官景先神力','張說','quantangshi','','卷5','数步圆塘水，双鸿戢羽仪。
一飞乔木上，一返故林垂。
澹泊含秋景，虚明抱夜规。
无因留绝翰，云海意差池。','',''),('quantangshi-04663','岳州宴别潭州王熊二首 一','張說','quantangshi','','卷5','丝管清且哀，一曲倾一杯。
气将然诺重，心向友朋开。
古木无生意，寒云若死灰。
赠君芳杜草，为植建章台。','',''),('quantangshi-04664','岳州宴别潭州王熊二首 二','張說','quantangshi','','卷5','缙云连省阁，沟水遽西东。
然诺心犹在，荣华岁不同。
孤城临楚塞，远树入秦宫。
谁念三千里，江潭一老翁。','',''),('quantangshi-04665','广州萧都督入朝过岳州宴饯得冬字','張說','quantangshi','','卷5','孤城抱大江，节使往朝宗。
果是台中旧，依然水上逢。
京华遥比日，疲老飒如冬。
窃羡能言鸟，衔恩向九重。','',''),('quantangshi-04666','岳州别姚司马绍之制许归侍','張說','quantangshi','','卷5','和玉悲无已，长沙宦不成。
天从扇枕愿，人遂倚门情。
方外怀司马，江东忆步兵。
问君栖泊处，空岭夜猿惊。','',''),('quantangshi-04667','送岳州李十从军桂州','張說','quantangshi','','卷5','送客之江上，其人美且才。
风波万里阔，故旧十年来。
劒拔蛟随断，弓张鸟自摧。
阳桥书落落，驿马定先回。','',''),('quantangshi-04668','岳州别赵国公王十一琚入朝','張說','quantangshi','','卷5','昔滥貂蝉长，同承雨露霏。
今参鱼鳖守，望美洞庭归。
浦树悬秋影，江云烧落辉。
离魂似征帆，恒往帝乡飞。','',''),('quantangshi-04669','岳州别子均','張說','quantangshi','','卷5','离筵非燕喜，别酒正销魂。
念汝犹童孺，嗟予隔远藩。
津亭拔心草，江路断肠猿。
他日将何见，愁来独倚门。','',''),('quantangshi-04670','端州别高六戬','張說','quantangshi','','卷5','异壤同羁窜，途中喜共过。
愁多时举酒，劳罢或长歌。
南海风潮壮，西江瘴疠多。
于焉复分手，此别伤如何。','',''),('quantangshi-04671','南中别蒋五岑向青州','張說','quantangshi','','卷5','老亲依北海，贱子弃南荒。
有泪皆成血，无声不断肠。
此中逢故友，彼地送还乡。
愿作枫林叶，随君度洛阳。','',''),('quantangshi-04672','南中别陈七李十','張說','quantangshi','','卷5','二年共游处，一旦各西东。
请君聊驻马，看我转征蓬。
画鷁愁南海，离驹思北风。
何时似春雁，双入上林中。','',''),('quantangshi-04673','南中别王陵成崇','張說','quantangshi','','卷5','握手与君别，歧路赠一言。
曹卿礼公子，楚媪馈王孙。
倏尔生六翮，翻飞戾九门。
常怀客鸟意，会答主人恩。','',''),('quantangshi-04674','岭南送使','張說','quantangshi','','卷5','秋雁逢春返，流人何日归？
将余去国泪，洒子入乡衣。
饥狖啼相聚，愁猿喘更飞。
南中不可问，书此示京畿。','',''),('quantangshi-04675','幽州别阴长河行先','張說','quantangshi','','卷5','惠好交情重，辛勤世事多。
荆南久为别，蓟北远来过。
寄目云中鸟，留欢酒上歌。
影移春复间，迟暮两如何。','',''),('quantangshi-04676','和朱使欣道峡似巫山之作','張說','quantangshi','','卷5','江如晓天净，石似暮霞张。
征帆一流览，宛若巫山阳。
楚客思归路，秦人谪异乡。
猿鸣孤月夜，再使泪沾裳。','',''),('quantangshi-04677','和朱使欣二首 一','張說','quantangshi','','卷5','南土多为寇，西江尽畏途。
山行阻篁竹，水宿碍萑蒲。
使越才应有，征蛮力岂无。
空传人赠劒，不见虎衔珠。','',''),('quantangshi-04678','和朱使欣二首 二','張說','quantangshi','','卷5','江势连山远，天涯此夜愁。
霜空极天静，寒月带江流。
思起南征棹，文高北望楼。
自怜如坠叶，泛泛侣仙舟。','',''),('quantangshi-04679','过庾信宅','張說','quantangshi','','卷5','兰成追宋玉，旧宅偶词人。
笔涌江山气，文骄云雨神。
包胥非救楚，随会反留秦。
独有东阳守，来嗟古树春。','',''),('quantangshi-04680','卢巴驿闻张御史张判官欲到不得待留赠之','張說','quantangshi','','卷5','旅窜南方远，传闻北使来。
旧庭知玉树，合浦识珠胎。
白发因愁改，丹心托梦廻。
皇恩若再造，为忆不然灰。','',''),('quantangshi-04681','南中赠高六戬','張說','quantangshi','','卷5','北极辞明代，南溟宅放臣。
丹诚由义尽，白发带愁新。
鸟坠炎洲气，花飞洛水春。
平生歌舞席，谁忆不归人。','',''),('quantangshi-04682','岳州山城','張說','quantangshi','','卷5','山城丰日暇，闭户见天心。
东旷迎朝色，西楼引夕阴。
书观千载近，学静二毛深。
忽有南风至，吹君堂上琴。','',''),('quantangshi-04683','和尹懋秋夜游㴩湖','張說','quantangshi','','卷5','㴩湖佳可游，既近复能幽。
林里栖精舍，山间转去舟。
雁飞江月冷，猿啸野风秋。
不是迷乡客，寻奇处处留。','',''),('quantangshi-04684','与赵冬曦尹懋子均登南楼','張說','quantangshi','','卷5','危楼泻洞湖，积水照城隅。
命驾邀渔火，通家引凤雏。
山晴红蘂匝，洲晓绿苗铺。
举目思乡县，春光定不殊。','',''),('quantangshi-04685','游㴩湖上寺','張說','quantangshi','','卷5','湖上奇峰积，山中芳树春。
何知绝世境，来遇赏心人。
清旧岩前乐，呦嘤鸟兽驯。
静言观听里，万法自成轮。','',''),('quantangshi-04686','晦日','張說','quantangshi','','卷5','晦日嫌春浅，江浦看湔衣。
道傍花欲合，枝上鸟犹稀。
共忆浮桥晚，无人不醉归。
寄书题此日，雁过洛阳飞。','',''),('quantangshi-04687','湘州九日城北亭子','張說','quantangshi','','卷5','西楚茱萸节，南淮戏马台。
宁知沅水上，复有菊花杯。
亭帐凭高出，亲朋自远来。
短歌将急景，同使兴情催。','',''),('quantangshi-04688','翻着葛巾呈赵尹','張說','quantangshi','','卷5','昔日接㒿倒，今我葛巾翻。
宿酒何时醒，形骸不复存。
忽闻有嘉客，躧步出闲门。
桃花春径满，误识武陵源。','',''),('quantangshi-04689','戏题草树','張說','quantangshi','','卷5','忽惊石榴树，远出渡江来。
戏问芭蕉叶，何愁心不开。
微霜拂宫桂，凄吹扫庭槐。
荣盛更如此，慙君独见哀。','',''),('quantangshi-04690','岳州赠广平公宋大夫','張說','quantangshi','','卷5','亚相本时英，归来复国桢。
朝推长孺直，野慕隐之清。
传节还闽嶂，皇华入汉京。
宁思江上老，岁[晏]独无成。','',''),('quantangshi-04691','和魏仆射还乡','張說','quantangshi','','卷5','富贵还乡国，光华满旧林。
秋风树不静，君子叹何深。
故老空悬劒，邻交日散金。
众芳摇落尽，独有岁寒心。','',''),('quantangshi-04692','和张监观赦','張說','quantangshi','','卷5','日御临双阙，天街俨百神。
雷兹作解气，岁复建寅春。
喜候开星驿，欢声发市人。
金环能作赋，来入管弦声。','',''),('quantangshi-04693','寄天台司马道士','張說','quantangshi','','卷5','世上求真客，天台去不还。
传闻有仙要，梦寐在兹山。
朱阙青霞断，瑶堂紫月闲。
何时枉飞鹤，笙吹接人间。','',''),('quantangshi-04694','下江南向夔州','張說','quantangshi','','卷5','天明江雾歇，洲浦棹歌来。
绿水逶迤去，青山相向开。
城临蜀帝祀，云接楚王台。
旧知巫山上，游子共徘徊。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-04695','还至端州驿前与高六别处','張說','quantangshi','','卷5','旧馆分江日，凄然望落晖。
相逢传旅食，临别换征衣。
昔记山川是，今伤人代非。
往来皆此路，生死不同归。','',''),('quantangshi-04696','四月一日过江赴荆州','張說','quantangshi','','卷5','春色沅湘尽，三年客始回。
夏云随北帆，同日过江来。
水漫荆门出，山平郢路开。
比肩羊叔子，千载岂无才。','',''),('quantangshi-04697','湘州北亭','張說','quantangshi','','卷5','人务南亭少，风烟北院多。
山花迷径路，池水拂藤萝。
萍散鱼时跃，林幽鸟任歌。
悠然白云意，乘兴抱琴过。','',''),('quantangshi-04698','荆州亭入朝','張說','quantangshi','','卷5','巫山云雨峡，湘水洞庭波。
九辨人犹摈，三秋雁始过。
旃裘吴地尽，髫荐楚言多。
不果朝宗愿，其如江汉何。','',''),('quantangshi-04699','岳州守岁','張說','quantangshi','','卷5','除夜清樽满，寒庭燎火多。
舞衣连臂拂，醉坐合声歌。
至乐都忘我，冥心自委和。
今年只如此，来岁知如何。','',''),('quantangshi-04700','咏尘','張說','quantangshi','','卷5','仙浦生罗袜，神京染素衣。
裨山期益峻，照日幸增辉。
夕伴龙媒合，朝游凤辇归。
独怜范甑下，思绕画梁飞。','',''),('quantangshi-04701','阙题','張說','quantangshi','','卷5','婚礼知无贺，承家叹有辉。
亲迎骥子跃，吉兆凤雏飞。
温席开华扇，梁门换褧衣。
遥思桃李日，应赋采苹归。','',''),('quantangshi-04702','深渡驿','張說','quantangshi','','卷5','旅泊青山夜，荒庭白露秋。
洞房悬月影，高枕听江流。
猿响寒岩树，萤飞古驿楼。
他乡对摇落，倂觉起离忧。','',''),('quantangshi-04703','惠文太子挽歌二首 一','張說','quantangshi','','卷5','碣馆英灵在，瑶山美諡尊。
剪桐悲曩戏，攻玉怆新恩。
宫仗传驰道，朝衣送国门。
千秋谷门外，明月照西园。','',''),('quantangshi-04704','惠文太子挽歌二首 二','張說','quantangshi','','卷5','梁国深文雅，淮王爱道仙。
帝欢同宴日，神夺上宾年。
旒旐飞行树，帷宫宿野烟。
指言君爱弟，挥泪满山川。','',''),('quantangshi-04705','节义太子杨妃挽歌二首 一','張說','quantangshi','','卷5','西华三公族，东闱五可才。
玉环初受庆，金玦反逢灾。
桂殿花空落，桐园月自开。
朝云将暮雨，长绕望思台。','',''),('quantangshi-04706','节义太子杨妃挽歌二首 二','張說','quantangshi','','卷5','昔日三朝路，逶迤四望车。
绣腰长命绮，隐髻连枝花。
今春戾园树，索然无岁华。
共伤千载后，惟号一王家。','',''),('quantangshi-04707','韦谯公挽歌二首 一','張說','quantangshi','','卷5','五瑞分王国，双珠映后家。
文飞书上凤，武结笥中蛇。
出豫荣前马，回鸾丧后车。
衮衣将锡命，泉路有光华。','',''),('quantangshi-04708','韦谯公挽歌二首 二','張說','quantangshi','','卷5','国骋双骐骥，庭仪两凤皇。
将星连相位，玉树伴金乡。
歌舞侯家艳，轩裘戚里光。
安知杜陵下，碑版已相望。','',''),('quantangshi-04709','右丞相苏公挽歌二首 一','張說','quantangshi','','卷5','王宰丹青化，春卿礼乐才。
缁衣传旧职，华衮赠新哀。
路泣羣官送，山嘶驷马廻。
佳辰无白日，宾阁有青苔。','',''),('quantangshi-04710','右丞相苏公挽歌二首 二','張說','quantangshi','','卷5','门歌出野田，冠带寝穷泉。
万事皆身外，平生尚目前。
西垣紫泥綍，东岳白云篇。
自惜同声处，从今遂绝弦。','',''),('quantangshi-04711','崔尚书挽词','張說','quantangshi','','卷5','相宅隆坤宝，承家占海封。
庭中男执雁，门外女乘龙。
鸣玉游三省，摐金侍九重。
一朝宾客散，留劒在青松。','',''),('quantangshi-04712','右侍郎集贤院学士徐公挽词二首 一','張說','quantangshi','','卷5','才美临淄北，名高淮海东。
羽仪三省遍，渔猎五车通。
玉殿孤新榜，珠英落旧丛。','',''),('quantangshi-04713','右侍郎集贤院学士徐公挽词二首 二','張說','quantangshi','','卷5','叹息书林友，才华天下选。
并赋三阳宫，集诗集贤殿。
具物衣如在，咄嗟长不见。
既哀薤露词，岂忘平生眷。','',''),('quantangshi-04714','崔司业挽歌二首 一','張說','quantangshi','','卷5','海岱英灵气，胶庠礼乐资。
风流满天下，人物擅京师。
疾起扬雄赋，魂游谢客诗。
从今好文主，遗恨不同时。','',''),('quantangshi-04715','崔司业挽歌二首 二','張說','quantangshi','','卷5','象设存华馆，威仪下墓田。
凤池伤旧草，麟史泣遗编。
帷盖墟烟没，干旌陇日悬。
古来埋玉树，流恨满山川。','',''),('quantangshi-04716','李工部挽歌三首 一','張說','quantangshi','','卷5','锦帐为郎日，金门待诏时。
杨宫先上赋，柏殿几连诗。
瞬息琴歌断，凄凉箫挽悲。
那堪霸陵岸，回首望京师。','',''),('quantangshi-04717','李工部挽歌三首 二','張說','quantangshi','','卷5','宅兆西陵上，平生雅志从。
城临丹阙近，山望白云重。
会葬知元伯，看碑识蔡邕。
无由接神理，挥涕向青松。','',''),('quantangshi-04718','李工部挽歌三首 三','張說','quantangshi','','卷5','常时好宾客，永日对弦歌。
是日归泉下，伤心无奈何。
墓庭人已散，祭处鸟来过。
碑石生苔藓，荣名岂复多。','',''),('quantangshi-04719','赠工部尚书冯公挽歌三首 一','張說','quantangshi','','卷5','忠鲠难为事，平生尽畏途。
如弦心自直，秀木势恒孤。
诏葬南陵道，神游北斗枢。
贵门传万石，余庆在双珠。','',''),('quantangshi-04720','赠工部尚书冯公挽歌三首 二','張說','quantangshi','','卷5','爵位题龙旐，威仪出凤城。
路傍人泣送，门外马嘶迎。
万事非吾有，千悲是世情。
昔焉称夏日，今也谥冬卿。','',''),('quantangshi-04721','赠工部尚书冯公挽歌三首 三','張說','quantangshi','','卷5','窅然长夜台，举世可哀哉。
泉户一朝闭，松风四面来。
石碑填驳藓，珠服聚尘埃。
谁言辽东鹤，千年往复廻。','',''),('quantangshi-04722','徐高御挽歌','張說','quantangshi','','卷5','蒲密遥千载，鸣琴始一追。
公卿传世范，仁义续灵基。
不待南游禄，何先北帝期。
玉棺从此闭，金鼎代相欺。','',''),('quantangshi-04723','奉和圣制春日幸望春宫应制','張說','quantangshi','','卷5','别馆芳菲上苑东，飞花澹荡御筵红。
城临渭水天河静，阙对南山雨露通。
绕殿流莺凡几树，当蹊乱蝶许多丛。
春园既醉心和乐，共识皇恩造化同。','',''),('quantangshi-04724','侍宴隆庆池应制','張說','quantangshi','','卷5','灵池月满直城隈，黻帐天临御路开。
东沼初阳疑吐出，南山晓翠若浮来。
鱼龙百戏纷容与，凫鷁双舟较溯洄。
愿似金堤青草馥，长承瑶水白云杯。','',''),('quantangshi-04725','奉和圣制春日出苑应制','張說','quantangshi','','卷5','禁林艳裔发青阳，春望逍遥出画堂。
雨洗亭臯千亩绿，风吹梅李一园香。
鹤飞不去随青管，鱼跃翻来入彩航。
睿赏欢承天保定，遒文更覩日重光。','',''),('quantangshi-04726','扈从温泉宫献诗','張說','quantangshi','','卷5','温泉启蛰气氛氲，渭浦归鸿日数羣。
骑仗联联环北极，鸣笳步步引南熏。
松间彩殿笼佳气，山上朱旗绕瑞云。
不知远梦华胥国，何如亲奉帝尧君。','',''),('quantangshi-04727','三月三日诏宴定昆池宫庄赋得筵字','張說','quantangshi','','卷5','凤皇楼下对天泉，鹦鹉洲中匝管弦。
旧识平阳佳丽地，今逢上巳盛明年。
舟将水动千寻日，幕共林横两岸烟。
不降玉人观禊饮，谁令醉舞拂宾筵。','',''),('quantangshi-04728','先天应令','張說','quantangshi','','卷5','三阳丽景早芳辰，四序嘉园物候新。
梅花百般障行路，垂柳千条暗回津。
鸟惊直为飞风叶，鱼跃都由怯岸人。
唯愿圣主南山寿，何愁不赏万年春。','',''),('quantangshi-04729','舞马千秋万岁乐府词三首 一','張說','quantangshi','','卷5','金天诞圣千秋节，玉醴还分万寿觞。
试听紫骝歌乐府，何如騄骥舞华冈。
连骞势出鱼龙变，躞蹀骄生鸟兽行。
岁岁相传指树日，翩翩来伴庆云翔。','',''),('quantangshi-04730','舞马千秋万岁乐府词三首 二','張說','quantangshi','','卷5','圣皇至德与天齐，天马来仪自海西。
腕足徐行拜两膝，繁骄不进踏千蹄。
髬髵奋鬣时蹲踏，鼓怒骧身忽上跻。
更有衔杯终宴曲，垂头掉尾醉如泥。','',''),('quantangshi-04731','舞马千秋万岁乐府词三首 三','張說','quantangshi','','卷5','远听明君爱逸才，玉鞭金翅引龙媒。
不因兹白人间有，定是飞黄天上来。
影弄日华相照耀，喷含云色且裴徊。
莫言阙下桃花舞，别有河中兰叶开。','',''),('quantangshi-04732','同赵侍御巴陵早春作','張說','quantangshi','','卷5','江上春来早可观，巧将春物妬余寒。
水苔共绕留乌石，花鸟争开鬬鸭栏。
佩胜芳辰日渐暖，然灯美夜月初圆。
意随北雁云飞去，直待南州蕙草残。','',''),('quantangshi-04733','㴩湖山寺','張說','quantangshi','','卷5','空山寂历道心生，虚谷迢遥野鸟声。
禅室从来尘外赏，香台岂是世中情。
云间东岭千寻出，树里南湖一片明。
若使巢由知此意，不将萝薜易簪缨。','',''),('quantangshi-04734','幽州新岁作','張說','quantangshi','','卷5','去岁荆南梅似雪，今年蓟北雪如梅。
共知人事何常定，且喜年华去复来。
边镇戍歌连夜动，京城燎火彻明开。
遥遥西向长安日，愿上南山寿一杯。','',''),('quantangshi-04735','扈从幸韦嗣立山庄应制','張說','quantangshi','','卷5','寒灰飞玉琯，汤井驻金舆。
既得方明相，还寻大隗居。
悬泉珠贯下，列帐锦屏舒。
骑远林逾密，笳繁谷自虚。
门旗堑复磴，殿幕裹通渠。
舞凤迎公主，雕龙赋婕妤。
地幽天赏洽，酒乐御筵初。
菲才叨侍从，连藻愧应徐。','',''),('quantangshi-04736','奉和圣制喜雪应制','張說','quantangshi','','卷5','圣德与天同，封峦欲报功。
诏书期日下，灵感应时通。
触石云呈瑞，含花雪告丰。
积如沙照月，散似面从风。
舞集仙台上，歌流帝乐中。
遥知百神喜，洒路待行宫。','',''),('quantangshi-04737','奉和圣制寒食作应制','張說','quantangshi','','卷5','寒食春过半，花穠鸟复娇。
从来禁火日，会接清明朝。
鬬敌鸡殊胜，争球马绝调。
晴空数云点，香树百风摇。
改木迎新燧，封田表旧烧。
皇情爱嘉节，传曲与箫韶。','',''),('quantangshi-04738','奉和圣制赐崔日知往潞州应制','張說','quantangshi','','卷5','圣情留曩镇，佳气翊兴王。
增戟雄都府，高车转太常。
川横八练阔，山带五龙长。
连帅初恩命，天人旧纪纲。
饯涂飞御藻，阖境自生光。
明主征循吏，何年下凤皇。','',''),('quantangshi-04739','春晚侍宴丽正殿探得开字','張說','quantangshi','','卷5','圣政惟稽古，宾门引上才。
坊因购书立，殿为集贤开。
髦彦星辰下，仙章日月回。
字如龙负出，韵是凤衔来。
庭柳余春驻，宫莺早夏催。
喜承芸阁宴，幸奉柏梁杯。','',''),('quantangshi-04740','奉和圣制花蕚楼下宴应制','張說','quantangshi','','卷5','万心翘乐宴，三舍缓昌时。
山接夏云险，台留春日迟。
节移芳未歇，兴隔赏仍追。
醉后传嘉惠，楼前舞圣慈。
皇恩与时合，天意若人期。
故发前旬雨，新垂湛露诗。','',''),('quantangshi-04741','奉和圣制度蒲关应制','張說','quantangshi','','卷5','蒲坂横临晋，华芝晓望秦。
关城雄地险，桥路扼天津。
楼映行宫日，堤含宫树春。
黄云随宝鼎，紫气逐真人。
东咏唐虞迹，西观周汉尘。
山河非国宝，明主爱忠臣。','',''),('quantangshi-04742','奉和圣制途经华岳应制','張說','quantangshi','','卷5','西岳镇皇京，中峰入太清。
玉銮重岭应，缇[骑]薄云迎。
霁日悬高掌，寒空类削成。
轩游会神处，汉幸望仙情。
旧庙青林古，新碑绿字生。
羣臣愿封岱，还驾勒鸿名。','',''),('quantangshi-04743','奉和圣制过王浚墓应制','張說','quantangshi','','卷5','牛斗三分国，龙骧一统年。
智高宁受制，风急肯廻船。
有策擒吴嚭，无言让范宣。
援孤因势屈，功重为谗偏。
旧迹灰尘散，枯坟故老传。
百代逢明主，何辞死道边。','',''),('quantangshi-04744','奉和圣制经河上公庙应制','張說','quantangshi','','卷5','河上无名老，知非汉代人。
先探道德要，留待圣明辰。
玄妙为天下，清虚用谷神。
化将和气一，风与太初邻。
灵庙观遗像，仙歌入至真。
皇心齐万物，何处不同尘。','',''),('quantangshi-04745','奉和圣制幸凤汤泉应制','張說','quantangshi','','卷5','周狩闻岐礼，秦都辨雍名。
献禽天子孝，存老圣皇情。
温润宜冬幸，游畋乐岁成。
汤云出水殿，暖气入山营。
坎意无私洁，干心称物平。
帝歌流乐府，溪谷也增荣。','',''),('quantangshi-04746','恩赐乐游园宴','張說','quantangshi','','卷5','汉苑佳游地，轩庭近侍臣。
共持荣幸日，来赏艳阳春。
馔玉颁王篚，摐金下帝钧。
池台草色徧，宫观柳条新。
花绶光连榻，朱颜畅饮醇。
圣朝多乐事，天意每随人。','',''),('quantangshi-04747','三月二十日诏宴乐游园赋得风字','張說','quantangshi','','卷5','乐游形胜地，表里望郊宫。
北阙连天顶，南山对掌中。
皇恩贷芳月，旬宴美成功。
鱼戏芙蓉水，莺啼杨柳风。
春光看欲暮，天泽恋无穷。
长袖招斜日，留光待曲终。','',''),('quantangshi-04748','赴集贤院学士上赐宴应制得辉字','張說','quantangshi','','卷5','侍帝金华讲，千龄道固稀。
位将贤士设，书共学徒归。
首命深燕隗，通经浅汉韦。
列筵荣赐食，送客愧儒衣。
贺燕窥檐下，迁莺入殿飞。
欲知朝野庆，文教日光辉。','',''),('quantangshi-04749','端午三殿侍宴应制探得鱼字','張說','quantangshi','','卷5','小暑夏弦应，徽音商管初。
愿赍长命缕，来续大恩余。
三殿褰珠箔，羣官上玉除。
助阳尝麦彘，顺节进龟鱼。
甘露垂天酒，芝花捧御书。
合丹同蝘蜓，灰骨共蟾蜍。
今日伤蛇意，衔珠遂阙如。','',''),('quantangshi-04750','奉和圣制春中兴庆宫酺宴应制','張說','quantangshi','','卷5','千龄逢启圣，万域共来威。
庆接郊禋后，酺承农事稀。
御楼横广路，天乐下重闱。
鸾凤调歌曲，虹霓动舞衣。
合声云上聚，连步月中归。
物覩恩无外，神和道入微。
镐京陪乐饮，柏殿奉文飞。
徒竭秋云影，何资春日晖。','',''),('quantangshi-04751','奉和圣制千秋节宴应制','張說','quantangshi','','卷5','五德生王者，千龄启圣人。
赤光来照夜，黄云上覆晨。
海县衔恩久，朝章献舞新。
高居帝座出，夹道众官陈。
槊杖洗清景，磬管凝秋旻。
珠囊含瑞露，金镜抱仙轮。
何岁无乡饮，何田不报神。
薰歌与名节，传代幸羣臣。','',''),('quantangshi-04752','奉和圣制太行山中言志应制','張說','quantangshi','','卷5','六龙鸣玉銮，九折步云端。
河络南浮近，山经北上难。
羽仪映松雪，戈甲带春寒。
百谷晨笳动，千岩晓仗攒。
皇心感韶节，敷藻念人安。
既立省方馆，复建礼神坛。
扈跸参天老，承荣忝夏官。
长勤百年意，思见一胜残。','',''),('quantangshi-04753','奉和御制与宋璟源干曜同日上官命宴东堂赐诗应制','張說','quantangshi','','卷5','大块镕羣品，经生偶圣时。
猥承三事命，虚忝百僚师。
右揆谋华硕，前星傅重资。
连骞求旧礼，滥典乐贤诗。
赐釜同荣拜，摐金宴宰司。
菊花吹御酒，兰叶捧天词。
宝历休明盛，颓年晷漏衰。
少留青史笔，未敢赤松期。','',''),('quantangshi-04754','奉和圣制暇日与兄弟同游兴庆宫作应制','張說','quantangshi','','卷5','汉武横汾日，周王宴镐年。
何如造区夏，复此睦亲贤。
巢凤新成阁，飞龙旧跃泉。
棣华歌尚在，桐叶戏仍传。
禁籞氛埃隔，平台景物连。
圣慈良有裕，王道固无偏。
问俗兆人阜，观风五教宣。
献图开益地，张乐奏钧天。
侍酒衢樽满，询刍谏鼓悬。
永言形友爱，万国共周旋。','',''),('quantangshi-04755','奉和圣制送王晙巡边应制','張說','quantangshi','','卷5','六月歌周雅，三边遣夏卿。
欲施攻战法，先作简稽行。
礼乐知谋帅，春秋识用兵。
一劳堪定国，万里即长城。
策有和戎利，威传破虏名。
军前雨洒道，楼上月临营。
别藻瑶华降，同衣锦襮荣。
关山由义近，戎马为恩轻。
丝竹路傍散，风云马上生。
朝廷谓吉甫，邦国望君平。','',''),('quantangshi-04756','将赴朔方军应制','張說','quantangshi','','卷5','礼乐逢明主，韬钤用老臣。
恭凭神武策，远御鬼方人。
供帐荣恩饯，山川喜诏巡。
天文日月丽，朝赋管弦新。
幼志传三略，衰材谢六钧。
胆由忠作伴，心固道为邻。
汉保河南地，胡清塞北尘。
连年大军后，不日小康辰。
劒舞轻离别，歌酣忘苦辛。
从来思博望，许国不谋身。','',''),('quantangshi-04757','奉和圣制爰因巡省途次旧居应制','張說','quantangshi','','卷5','葱郁兴王郡，殷忧启圣图。
周成会西土，汉武幸南都。
岁卜銮舆迈，农祠雁政敷。
武威棱外域，文教靡中区。
警跸干戈捧，朝宗万玉趋。
旧藩人事革，新化国容殊。
壁有真龙画，庭余鸣凤梧。
丛觞祝尧寿，合鼎献汤厨。
阳乐寒初变，春恩蛰更苏。
三耆颁命服，五稔复田输。
君赋大风起，人歌湛露濡。
从臣观玉叶，方愿纪灵符。','',''),('quantangshi-04758','宿直温泉宫羽林献诗','張說','quantangshi','','卷5','冬狩美秦正，新丰乐汉行。
星陈玄武阁，月对羽林营。
寒木罗霜仗，空山响夜更。
恩深灵液暖，节劲古松贞。
文武皆王事，输心不为名。','',''),('quantangshi-04759','玄武门侍射','張說','quantangshi','','卷5','射观通玄阙，兵栏辟御筵。
雕弧月半上，画的晕重圆。
羿后神幽赞，灵王法暗传。
贯心精四返，饮羽妙三联。
雪鹤来衔箭，星麟下集弦。
一逢军宴洽，万庆武功宣。','',''),('quantangshi-04760','扈从南出雀鼠谷','張說','quantangshi','','卷5','豫动三灵赞，时巡四海威。
陕关凌曙出，平路半春归。
霍镇迎云罕，汾河送羽旗。
山南柳半密，谷北草全稀。
迟日宜华盖，和风入袷衣。
上林千里近，应见百花飞。','',''),('quantangshi-04761','洛桥北亭诏饯诸刺史','張說','quantangshi','','卷5','离亭拂御沟，别曲舞船楼。
诏饯朝廷牧，符分海县忧。
股肱还入郡，父母更临州。
扇逐仁风传，车随霖雨流。
恩光水上溢，荣色柳间浮。
预待羣方最，三公不远求。','',''),('quantangshi-04762','东都酺宴','張說','quantangshi','','卷5','尧舜传天下，同心致太平。
吾君内举圣，远合至公情。
锡命承丕业，崇亲享大名。
二天资广运，两曜益齐明。
道畅昆虫乐，恩深朽蠹荣。
皇舆久西幸，留镇在东京。
合宴千官入，分曹百戏呈。
乐来嫌景遽，酒着讶寒轻。
喜气连云阁，欢呼动洛城。
人间知几代，今日见河清。','',''),('quantangshi-04763','奉酬韦祭酒嗣立偶游龙门北溪忽怀骊山别业呈诸留守之作','張說','quantangshi','','卷5','石涧泉虚落，松崖路曲回。
闻君北溪下，想像南山隈。
近念鼎湖别，遥思云嶂陪。
不同奇觏往，空覩斯文来。
岁后寒初变，春前芳未开。
黄蕤袅岸柳，紫蕚折村梅。
尽室兹游玩，盈门几乐哉。
嗟留洛阳陌，梦诣建章台。
野失巢由性，朝非元凯才。
布怀钦远迹，幽意日尘埃。','',''),('quantangshi-04764','奉酬韦祭酒自汤还都经龙门北溪庄见贻之作','張說','quantangshi','','卷5','闻君汤井至，潇洒憇郊林。
拂曙携清赏，披云觏绿岑。
欢言游览意，款曲望归心。
是日期佳客，同山忽异寻。
桃花迂路转，杨柳间门深。
泛舟伊水涨，系马香树阴。
繁弦弄水族，娇吹狎沙禽。
春满汀色媚，景斜岚气侵。
怀仁殊未远，重德匪专临。
来藻敷幽思，连词报所钦。','',''),('quantangshi-04765','酬崔光禄冬日述怀赠答','張說','quantangshi','','卷5','徐陈尝并作，枚马亦同时。
各负当朝誉，俱承明主私。
夫君迈前侣，观国骋奇姿。
山似鸣威凤，泉如出宝龟。
才雄子云笔，学广仲舒帷。
紫绶拂三寺，朱门临九逵。
昔我含香日，联尔缙云司。
朝携兰省步，夕退竹林期。
中路一分手，数载来何迟。
求友还相得，羣英复在兹。
留台少人务，方驾递寻追。
涉玩怀同赏，霑芳忆共持。
迎宾南涧饮，载妓东城嬉。
春郊绿亩秀，秋涧白云滋。
名画披人物，良书讨滞疑。
兴来光不惜，欢往迹如遗。
岁晏罢行乐，层城间所思。
夜魂灯处厌，朝髪镜前衰。
忽枉崔駰什，兼流韦孟词。
曲高弥寡和，主善代为师。
齐戒观华玉，留连叹色丝。
终慙起予者，何足与言诗。','',''),('quantangshi-04766','同刘给事城南宴集','張說','quantangshi','','卷5','水竹幽闲地，簪缨近侍臣。
雍容乘暇日，潇洒出嚣尘。
树对思朋鸟，池深入养鳞。
管弦高逐吹，歌舞妙含春。
老子叨专席，欢邀隔缙绅。
此中情不浅，遥寄赏心人。','',''),('quantangshi-04767','温泉冯刘二监客舍观妓','張說','quantangshi','','卷5','温谷寒林薄，羣游乐事多。
佳人蹀骏马，乘月夜相过。
秀色然红黛，娇香发绮罗。
镜前鸾对舞，琴里凤传歌。
妬宠倾新意，衔恩奈老何。
为君留上客，欢笑敛双蛾。','',''),('quantangshi-04768','寄许八','張說','quantangshi','','卷5','万类春皆乐，徂颜独不怡。
年来人更老，花发意先衰。
乳鹊穿坛画，巢蜂触网丝。
平生美容色，宿昔影中疑。
远道何由梦，同心在者谁。
西风欲谁语，悯默遂无词。','',''),('quantangshi-04769','送苏合宫颋','張說','quantangshi','','卷5','都邑羣方首，商泉旧俗讹。
变风须恺悌，成化伫弦歌。
畴昔圭璋友，雍容文雅多。
振缨游省闼，锵玉宰京河。
别曲鸾初下，行轩雉尚过。
百壶非饯意，流咏在人和。','',''),('quantangshi-04770','送乔安邑备','張說','quantangshi','','卷5','书阁移年岁，文明难复辞。
欢言冬雪满，恨别夏云滋。
外尹方为政，高明自不欺。
老人骖驭往，童子狎雏嬉。
日茂西河俗，寂寥东观期。
遥怀秀才令，京洛见新诗。','',''),('quantangshi-04771','送赵二尚书彦昭北伐','張說','quantangshi','','卷5','虏地河冰合，边城备此时。
兵连紫塞路，将举白云司。
提劒荣中贵，衔珠盛出师。
日华光组练，风色焰旌旗。
投笔尊前起，横戈马上辞。
梅花吹别引，杨柳赋归诗。','',''),('quantangshi-04772','石门别杨六钦望','張說','quantangshi','','卷5','燕人同窜越，万里自相哀。
影响无期会，江山此地来。
暮年伤泛梗，累日慰寒灰。
潮水东南落，浮云西北回。
俱看石门远，倚棹两悲哉。','',''),('quantangshi-04773','南中送北使二首 一','張說','quantangshi','','卷5','传闻合浦叶，曾向洛阳飞。
何日南风至，还随北使归。
红颜渡岭歇，白首对秋衰。
高歌何由见，层堂不可违。
谁怜炎海曲，泪尽血沾衣。','',''),('quantangshi-04774','南中送北使二首 二','張說','quantangshi','','卷5','待罪居重译，穷愁暮雨秋。
山临鬼门路，城绕瘴江流。
人事今如此，生涯尚可求。
逢君入乡县，传我念京周。
别恨归途远，离言暮景遒。
夷歌翻下泪，芦酒未消愁。
闻有胡兵急，深怀汉国羞。
和亲先是诈，款塞果为讐。
释系应分爵，蠲徒几复侯。
廉颇诚未老，孙叔宜无谋。
若道冯唐事，皇恩尚可收。','',''),('quantangshi-04775','送赵顺直郎中赴安西副大都督','張說','quantangshi','','卷5','绝镇功难立，悬军命匪轻。
复承迁相后，弥重任贤情。
将起神仙地，才称礼乐英。
长心堪系虏，短语足论兵。
日授休门法，星教置阵名。
龙泉恩已着，燕颔相终成。
月窟穷天远，河源入塞清。
老天操别翰，承旨颂升平。','',''),('quantangshi-04776','送宋休远之蜀任','張說','quantangshi','','卷5','求友殊损益，行道异穷申。
缀我平生气，吐赠薄游人。
结恩事明主，忍爱远辞亲。
色丽成都俗，膏腴蜀水滨。
如何从宦子，坚白共缁磷。
日月千龄旦，河山万族春。
怀铅书瑞府，横草事边尘。
不及安人吏，能令王化淳。','',''),('quantangshi-04777','岳州别梁六入朝','張說','quantangshi','','卷5','远莅长沙渚，欣逢贾谊才。
江山疲应接，风日复晴开。
江树云间断，湘山水上来。
近洲朝鹭集，古戍夜猿哀。
