惟愿圣君无限寿，长取新年续旧年。','',''),('quantangshi-04848','苏摩遮五首 五','張說','quantangshi','','卷5','昭成皇后帝家亲，荣乐诸人不比伦。
往日霜前花委地，今年雪后树逢春。','',''),('quantangshi-04849','三月三日定昆池奉和萧令得潭字韵','張說','quantangshi','','卷5','暮春三月日重三，春水桃花满禊潭。
广乐逶迤天上下，仙舟摇衍镜中酣。','',''),('quantangshi-04850','和尹从事懋泛洞庭','張說','quantangshi','','卷5','平湖一望上连天，林景千寻下洞泉。
忽惊水上光华满，疑是乘舟到日边。','',''),('quantangshi-04851','送梁六自洞庭山作','張說','quantangshi','','卷5','巴陵一望洞庭秋，日见孤峰水上浮。
闻道神仙不可接，心随湖水共悠悠。','',''),('quantangshi-04852','同赵侍御望归舟','張說','quantangshi','','卷5','山庭迥迥面长川，江树重重极远烟。
形影相追高翥鸟，心肠倂断北风船。','',''),('quantangshi-04853','襄阳路逢寒食','張說','quantangshi','','卷5','去年寒食洞庭波，今年寒食襄阳路。
不辞着处寻山水，秪畏还家落春暮。','',''),('quantangshi-04854','咏方圆动静示李泌','張說','quantangshi','','卷5','方如棋局，圆如棋子。
动如棋生，静如棋死。','',''),('quantangshi-04855','和尹懋登南楼','張均','quantangshi','','卷5','客来已两春，更瞻韶光早。
花鸟既环合，江山复骈抱。
楼形写北潭，堞势凌青岛。
白云谢归雁，驰怀洛阳道。','',''),('quantangshi-04856','江上逢春','張均','quantangshi','','卷5','离忧耿未和，春虑忽蹉跎。
择木猿知去，寻泥燕独过。
惊花飜霁日，垂柳拂烟波。
激意屡怡赏，无如乡念何。','',''),('quantangshi-04857','九日巴丘登高','張均','quantangshi','','卷5','客心惊暮序，宾雁下沧洲。
共赏重阳节，言寻戏马游。
湖风扶戍柳，江雨暗山楼。
且酌东篱酒，聊祛南国忧。','',''),('quantangshi-04858','和尹懋秋夜游㴩湖二首 一','張均','quantangshi','','卷5','远水沈西日，寒沙聚夜鸥。
平湖乘月满，飞棹接星流。
黄叶鸣凄吹，苍葭扫暗洲。
愿移沧浦赏，归待颍川游。','',''),('quantangshi-04859','和尹懋秋夜游㴩湖二首 二','張均','quantangshi','','卷5','湾潭幽意深，杳霭涌寒岑。
石痕秋水落，岚气夕阳沈。
澄彻天为底，渊玄月作心。
青溪非大隐，归弄白云浔。','',''),('quantangshi-04860','岳阳晚景','張均','quantangshi','','卷5','晚景寒鵶集，秋风旅雁归。
水光浮日出，霞彩暎江飞。
洲白芦花吐，园红柿叶稀。
长沙卑湿地，九月未成衣。','',''),('quantangshi-04861','流合浦岭外作','張均','quantangshi','','卷5','瘴江西去火为山，炎徼南穷鬼作关。
从此更投人境外，生涯应在有无间。','',''),('quantangshi-04862','奉和岳州山城','張垍','quantangshi','','卷5','郡馆临清赏，开扃坐白云。
讼虚棠户曙，观静竹檐曛。
悬榻迎宾下，趋庭学礼闻。
风传琴上意，遥向日华纷。','',''),('quantangshi-04863','偶游龙门北溪忽怀骊山别业因以言志示弟淑奉呈诸大僚','韋嗣立','quantangshi','','卷5','幽谷杜陵边，风烟别几年。
偶来伊水曲，溪嶂觉依然。
傍浦怜芳树，寻崖爱绿泉。
岭云随马足，山鸟向人前。
地合心俱静，言因理自玄。
短才叨重寄，尸禄愧妨贤。
每挹挂冠侣，思从初服旋。
稻粱仍欲报，岁月坐空捐。
助岳无纤块，输溟谢末涓。
还悟北辕失，方求南涧田。','',''),('quantangshi-04864','奉和九日幸临渭亭登高应制得深字','韋嗣立','quantangshi','','卷5','层观远沈沈，鸾旗九日临。
帷宫压水岸，步辇入烟岑。
枝上萸新采，樽中菊始斟。
愿陪欢乐事，长与岁时深。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-04865','奉和张岳州王潭州别诗二首 一','韋嗣立','quantangshi','','卷5','茂先王佐才，作牧楚江隈。
登楼正欲赋，复遇仲宣来。
黄鹄飞将远，雕龙文为开。
宁知昔联事，听曲有余哀。','',''),('quantangshi-04866','奉和张岳州王潭州别诗二首 二','韋嗣立','quantangshi','','卷5','昔时陪二贤，缨冕会神仙。
一去驰江海，相逢共播迁。
无因千里驾，忽覩四愁篇。
览讽欢何已，欢终徒怆然。','',''),('quantangshi-04867','奉和初春幸太平公主南庄应制','韋嗣立','quantangshi','','卷5','主第岩扃架鹊桥，天门阊阖降鸾镳。
历乱旌旗转云树，参差台榭入烟霄。
林间花杂平阳舞，谷里莺和弄玉箫。
已陪沁水追欢日，行奉茅山访道朝。','',''),('quantangshi-04868','自汤还都经龙门北溪赠张左丞崔礼部崔光禄','韋嗣立','quantangshi','','卷5','栖闲有愚谷，好事枉朝轩。
树接前驱拥，岩传后骑喧。
褰帘出野院，植杖候柴门。
既拂林下席，仍携池上樽。
深期契幽赏，实谓展欢言。
末眷诚未易，佳游时更敦。
俄看啸俦侣，各已共飞骞。
延睇尽朝日，长怀通夜魂。
空闻岸竹动，徒见浦花繁。
多愧春莺曲，相求意独存。','',''),('quantangshi-04869','酬崔光禄冬日述怀赠答','韋嗣立','quantangshi','','卷5','亭伯负高名，羽仪称上京。
魏珠能烛乘，秦璧许连城。
六月飞将远，三冬学已精。
洛阳推贾谊，江夏贵黄琼。
推演中都术，旋参河尹声。
累迁登御府，移拜践名卿。
庭聚歌钟丽，门罗棨戟荣。
鹦杯飞广席，兽火列前楹。
散诞林园意，殷勤敬爱情。
无容抱衰疾，良宴每招迎。
契得心逾重，言忘道益真。
相勖忠义节，共谈词赋英。
雕虫曾靡弃，白凤已先鸣。
光接神愈骇，音来味不成。
短歌甘自思，鸿藻弥难清。
东里方希润，西河敢窃明。
厚诬空见迫，丧德岂无诚。
端守宫闱地，寒烟朝暮平。
顾才无术浅，怀器识忧盈。
月下对云阙，风前闻夜更。
昌年虽共偶，欢会此难并。
为怜漳浦曲，沈痼有刘桢。','',''),('quantangshi-04870','上巳日祓禊渭滨应制','韋嗣立','quantangshi','','卷5','乘春祓禊逐风光，扈跸陪銮渭渚傍。
还笑当时水滨老，衰年八十待文王。','',''),('quantangshi-04871','奉酬韦祭酒偶游龙门北溪忽怀骊山别业因以言志示弟淑奉呈诸大僚之作','魏奉古','quantangshi','','卷5','有美朝为贵，幽寻地自偏。
践临伊水汭，想望灞池边。
是遇皆新赏，兹游若旧年。
藤萝隐路接，杨柳御沟联。
道惬神情王，机忘俗理捐。
遂初诚已重，兼济实为贤。
迹是东山恋，心惟北阙悬。
顾慙经拾紫，多谢赋思玄。
未躧中林步，空承丽藻传。
阳春和已寡，扣寂竟徒然。','',''),('quantangshi-04872','奉酬韦祭酒偶游龙门北溪忽怀骊山别业因以言志示弟淑并呈诸大僚之作','崔日知','quantangshi','','卷5','夙龄秉微尚，中年忽有邻。
以兹山水癖，遂得狎通人。
迨我咸京道，闻君别业新。
岩前窥石镜，河畔踏芳茵。
既怜伊浦绿，复忆灞池春。
连词谢家子，同欢冀野宾。
趣闲鱼共乐，情洽鸟来驯。
讵念昔游者，只命独留秦。
萧条颖阳恋，冲漠汉阴真。
无由陪胜躅，空此翫书筠。','',''),('quantangshi-04873','冬日述怀奉呈韦祭酒张左丞兰台名贤','崔日知','quantangshi','','卷5','弱龄好经籍，披卷即怡然。
覃精四十载，驰骋数千言。
孔壁采遗篆，周韦考绝编。
袁公论劒术，孙子叙兵篇。
鲁史君臣道，姬书日月悬。
从师改炎燠，负笈遍山川。
上异西河夏，中非北海玄。
光荣拾青紫，名价接通贤。
既重万钟乐，宁思二顷田。
长戟同分虎，高冠亚附蝉。
晚怀重虚旷，养志息雕镌。
登高惭思拙，匠物谢情妍。
不慕张平子，宁希王仲宣。
谁谓登龙日，翻成刻鹄年。
循循劳善诱，轧轧思微牵。
琢磨才既竭，钻仰德弥坚。
朽木诚为谕，扪心徒自怜。
终期吞鸟梦，振翼上云烟。
赋成先掷地，词高直掞天。
更执抠衣礼，仍开函丈筵。
雾披槐市蔼，水静璧池圆。
愿逐从风叶，飞舞翰林前。','',''),('quantangshi-04874','奉酬韦嗣立祭酒偶游龙门北溪忽怀骊山别业因以言志示弟淑奉呈诸大僚之作','崔泰之','quantangshi','','卷5','关塞临伊水，骊山枕灞川。
俱临隐路侧，同在帝城边。
谢公兼出处，携妓翫林泉。
鸣驺喷梅雪，飞盖曳松烟。
闻琴幽谷里，看[弈]古岩前。
落日低帏帐，归云绕管弦。
叨荣惭北阙，微尚爱东田。
寂寞灰心尽，萧条尘事捐。
朝思登嶃绝，夜梦弄潺湲。
宿怀南涧意，况覩北溪篇。','',''),('quantangshi-04875','同光禄弟冬日述怀','崔泰之','quantangshi','','卷5','吾族白眉良，才华动洛阳。
观光初入仕，应宿始为郎。
飞萤翫书籍，白凤吐文章。
海卿逾往雅，河尹冠前张。
择材绥鄢郢，殊化被江湘。
高楼临广陌，甲第敞通庄。
列馆邙山下，疏亭洛水傍。
昌年赏丰陌，暇日悦林塘。
衣冠皆秀彦，罗绮尽名倡。
隔岸闻歌度，临池见舞行。
门庭寒变色，棨戟日生光。
穷阴方叆叇，杀气正苍茫。
感时兴盛作，晚岁共多伤。
积德韦丞相，通神张子房。
吟草徧簪绂，逸韵合宫商。
功名守留省，滥迹在文昌。
家园遥可见，台寺近相望。
无庸乘侍谒，有暇共翱翔。
棣华依雁序，竹叶拂鸾觞。
水坐怜秋月，山行弄晚芳。
恩华慙服冕，友爱勖垂堂。
无由报天德，相顾咏时康。','',''),('quantangshi-04876','奉和圣制送张尚书巡边','崔泰之','quantangshi','','卷5','南庭胡运尽，北斗将星飞。
旗鼓临沙漠，旌旄出洛畿。
关山遶玉塞，烽火映金微。
屡献帷谋策，频承庙胜威。
躞蹀临河骑，逶迤度陇旗。
地脉平千古，天声振九围。
车马生边气，戈鋋驻落晖。
夏近蓬犹转，秋深草木腓。
饯送纡天什，恩荣赐御衣。
伫勒燕然颂，鸣驺计日归。','',''),('quantangshi-04877','春夜寓直凤阁怀羣公','魏知古','quantangshi','','卷5','拜门传漏晚，寓直索居时。
昔重安仁赋，今称伯玉诗。
鸳池满不溢，鸡树久逾滋。
夙夜怀山甫，清风咏所思。','',''),('quantangshi-04878','奉和春日途中喜雨应诏','魏知古','quantangshi','','卷5','皇舆向洛城，时雨应天行。
丽日登岩送，阴云出野迎。
濯枝林杏发，润叶渚蒲生。
丝入纶言喜，花依锦字明。
微臣忝东观，载笔伫西成。','',''),('quantangshi-04879','从猎渭川献诗','魏知古','quantangshi','','卷5','尝闻夏太康，五弟训禽荒。
我后来冬狩，三驱盛礼张。
顺时鹰隼击，讲事武功扬。
奔走未及去，翾飞岂暇翔。
非熊从渭水，瑞翟想陈仓。
此欲诚难纵，兹游不可常。
子云陈羽猎，僖伯谏渔棠。
得失鉴齐楚，仁思念禹汤。
雍熙亮在宥，亭毒匪多伤。
辛甲今为史，虞箴遂孔彰。','',''),('quantangshi-04880','玄元观寻李先生不遇','魏知古','quantangshi','','卷5','羽客今何在，空寻伊洛间。
忽闻归苦县，复想入函关。
未作千年别，犹应七日还。
神仙不可见，寂寞返蓬山。','',''),('quantangshi-04881','招谕有怀赠同行人','李乂','quantangshi','','卷5','远游冒艰阻，深入劳存谕。
春去辞国门，秋还在边戍。
轩车行未返，节序催难驻。
陌上悲转蓬，园中想芳树。
蜀山自纷纠，岷水恒奔注。
临泛多苦怀，登攀寡欢趣。
永夕飞淫雨，崇朝蒸毒雾。
不求绥岭桃，宁美邛乡蒟。
白浪行欲静，骢马何尝驱。
愿接轺斾尘，联翩东北骛。','',''),('quantangshi-04882','春日侍宴芙蓉园应制','李乂','quantangshi','','卷5','水殿临丹籞，山楼绕翠微。
昔游人托乘，今幸帝垂衣。
涧筱缘峰合，岩花逗浦飞。
朝来江曲地，无处不光辉。','',''),('quantangshi-04883','奉和登骊山高顶寓目应制','李乂','quantangshi','','卷5','崖巘万寻悬，居高敞御筵。
行戈疑驻日，步辇若登天。
城阙雾中近，关河云外连。
谬陪登岱驾，欣奉济汾篇。','',''),('quantangshi-04884','奉和七夕两仪殿会宴应制','李乂','quantangshi','','卷5','桂宫明月夜，兰殿起秋风。
云汉弥年阻，星筵此夕同。
倏来疑有处，旋去已成空。
睿作钧天响，魂飞在梦中。','',''),('quantangshi-04885','奉和春日游苑喜雨应诏','李乂','quantangshi','','卷5','仙跸九成台，香筵万寿杯。
一旬初降雨，二月早闻雷。
叶向朝霁密，花含宿润开。
幸承天泽豫，无使日光催。','',''),('quantangshi-04886','奉和人日清晖阁宴羣臣遇雪应制','李乂','quantangshi','','卷5','上日登楼赏，中天御辇飞。
后庭联舞唱，前席仰恩辉。
睿作风云起，农祥雨雪霏。
幸陪人胜节，长愿奉垂衣。','',''),('quantangshi-04887','陪幸临渭亭遇雪应制','李乂','quantangshi','','卷5','青阳御紫微，白云下彤闱。
浃壤流天霈，绵区洒帝辉。
水如银度烛，云似玉披衣。
为得因风起，还来就日飞。','',''),('quantangshi-04888','奉和九日侍宴应制得浓字','李乂','quantangshi','','卷5','望幸纡千乘，登高自九重。
台疑临戏马，殿似接疏龙。
捧箧萸香遍，称觞菊气浓。
更看仙鹤舞，来此庆时雍。','',''),('quantangshi-04889','送沙门弘景道俊玄奘还荆州应制','李乂','quantangshi','','卷5','初日承归旨，秋风起赠言。
汉珠留道味，江璧返真源。
地出南关远，天回北斗尊。
宁知一柱观，却启四禅门。','',''),('quantangshi-04890','奉和九月九日登慈恩寺浮图应制','李乂','quantangshi','','卷5','涌塔临玄地，高层瞰紫微。
鸣銮陪帝出，攀橑翊天飞。
庆洽重阳寿，文含列象辉。
小臣叨载笔，欣此颂巍巍。','',''),('quantangshi-04891','闰九月九日幸总持寺登浮图应制','李乂','quantangshi','','卷5','清跸幸禅楼，前驱历御沟。
还疑九日豫，更想六年游。
圣藻辉缨络，仙花缀冕旒。
所欣延亿载，宁祗庆重秋。','',''),('quantangshi-04892','侍宴长宁公主东庄应制','李乂','quantangshi','','卷5','紫禁乘宵动，青门访水嬉。
贵游鳣序集，仙女凤楼期。
合宴簪绅满，承恩雨露滋。
北辰还捧日，东馆幸逢时。','',''),('quantangshi-04893','幸白鹿观应制','李乂','quantangshi','','卷5','制跸乘骊阜，回舆指凤京。
南山四皓谒，西岳两童迎。
云幄临悬圃，霞杯荐赤城。
神明近兹地，何必往蓬瀛。','',''),('quantangshi-04894','次苏州','李乂','quantangshi','','卷5','洛渚问吴潮，吴门想洛桥。
夕烟杨柳岸，春水木兰桡。
城邑南楼近，星辰北斗遥。
无因生羽翼，轻举托还飙。','',''),('quantangshi-04895','寄胡皓时在南中','李乂','quantangshi','','卷5','徭役苦流滞，风波限溯洄。
江流通地骨，山道绕天台。
有鸟图南去，无人见北来。
闭门沧海曲，云雾待君开。','',''),('quantangshi-04896','饯许州宋司马赴任','李乂','quantangshi','','卷5','展骥旌时杰，谈鸡美代贤。
暂离仙掖务，追送近郊筵。
地惨金商节，人康璧假田。
从来昆友事，咸以佩刀传。','',''),('quantangshi-04897','饯唐州高使君赴任','李乂','quantangshi','','卷5','淮源之水清，可以濯君缨。
彼美称才杰，亲人伫政声。
岁寒畴曩意，春晚别离情。
终叹临岐远，行看拥传荣。','',''),('quantangshi-04898','哭仆射鄂公杨再思','李乂','quantangshi','','卷5','端揆凝邦绩，台阶阐国猷。
方崇大厦栋，忽逝巨川舟。
白日铭安在，清风颂独留。
死生恩命毕，零落掩山丘。','',''),('quantangshi-04899','故赵王属赠黄门侍郎上官公挽词','李乂','quantangshi','','卷5','暮归泉壤隔，朝发城池恋。
汉畤结愁阴，秦陵下悲霰。
骎骎百驷驰，悯悯羣龙饯。
石马徒自施，玉人终不见。','',''),('quantangshi-04900','淮阳公主挽歌','李乂','quantangshi','','卷5','玉颜生汉渚，汤沐荣天女。
金缕化邙尘，哀荣感路人。
凤皇曾作伴，蝼蚁忽为亲。
畴日成蹊处，穠华不复春。','',''),('quantangshi-04901','故西台侍郎上官公挽歌','李乂','quantangshi','','卷5','宇内文儒重，朝端礼命优。
立言多启沃，论道盛谋猷。
顾日琴安在，冲星剑不留。
徒怀东武襚，更掩北原丘。','',''),('quantangshi-04902','高安公主挽歌二首 一','李乂','quantangshi','','卷5','汤沐三千赋，楼台十二重。
银炉称贵幸，玉辇盛过逢。
嫔则留中馈，娥辉没下舂。
平阳百岁后，歌舞为谁容。','',''),('quantangshi-04903','高安公主挽歌二首 二','李乂','quantangshi','','卷5','宾衞俨相依，横门启曙扉。
灵阴蟾兔缺，仙影凤皇飞。
一水秋难渡，三泉夜不归。
况临青女节，瑶草更前哀。','',''),('quantangshi-04904','奉和初春幸太平公主南庄应制','李乂','quantangshi','','卷5','平阳馆外有仙家，沁水园中好物华。
地出东郊回日御，城临南斗度云车。
风泉韵绕幽林竹，雨霰光摇杂树花。
已庆时来千亿寿，还言日暮九重赊。','',''),('quantangshi-04905','兴庆池侍宴应制','李乂','quantangshi','','卷5','神池泛滥水盈科，仙跸纡徐步辇过。
纵棹洄沿萍溜合，开轩眺赏麦风和。
潭鱼在藻供游咏，谷鸟含樱入赋歌。
寄语乘槎溟海客，回头来此问天河。','',''),('quantangshi-04906','侍宴安乐公主山庄应制','李乂','quantangshi','','卷5','金舆玉辇背三条，水阁山楼望九霄。
野外初迷七圣道，河边忽覩二灵桥。
悬冰滴滴依虬箭，清吹泠泠杂凤箫。
回晚平阳歌舞合，前溪更转木兰桡。','',''),('quantangshi-04907','奉和春日幸望春宫应制','李乂','quantangshi','','卷5','东城结宇敞千寻，北阙回舆具四临。
丽日祥烟承罕毕，轻荑弱草藉衣簪。
秦商重沓云岩近，河渭萦纡雾壑深。
谬接鵷鸿陪赏乐，还欣鱼鸟遂飞沈。','',''),('quantangshi-04908','人日重宴大明宫恩赐彩缕人胜应制','李乂','quantangshi','','卷5','诘旦行春上苑中，凭高却下大明宫。
千年执象寰瀛泰，七日为人庆赏隆。
铁凤曾骞摇瑞雪，铜乌细转入祥风。
此时朝野欢无算，此岁云天乐未穷。','',''),('quantangshi-04909','享龙池乐第八章','李乂','quantangshi','','卷5','星分邑里四人居，水洊源流万顷余。
魏国君王称象处，晋家蕃邸化龙初。
青蒲暂似游梁马，绿藻还疑宴镐鱼。
自有神灵滋液地，年年云物史官书。','',''),('quantangshi-04910','奉和幸礼部尚书窦希玠宅应制','李乂','quantangshi','','卷5','家住千门侧，亭临二水傍。
贵游开北地，宸眷幸西乡。
曳履迎中谷，鸣丝出后堂。
浦疑观万象，峰似驻三光。
草向琼筵乐，花承绣扆香。
圣情思旧重，留饮赋雕章。','',''),('quantangshi-04911','奉和晦日幸昆明池应制','李乂','quantangshi','','卷5','玉辂寻春赏，金堤重晦游。
川通黑水浸，地派紫泉流。
晃朗扶桑出，绵联杞树周。
乌疑填海处，人似隔河秋。
劫尽灰犹识，年移石故留。
汀洲归棹晚，箫鼓杂汾讴。','',''),('quantangshi-04912','奉和幸长安故城未央宫应制','李乂','quantangshi','','卷5','凤辇乘春陌，龙山访故台。
北宫才尽处，南斗独昭回。
肆览飞宸札，称觞引御杯。
已观蓬海变，谁厌柏梁灾。
代挹孙通礼，朝称贾谊才。
忝侪文雅地，先后各时来。','',''),('quantangshi-04913','陪幸韦嗣立山庄应制','李乂','quantangshi','','卷5','枢掖调梅暇，林园种槿初。
入朝荣劒履，退食偶琴书。
地隐东岩室，天回北斗车。
旌门临䆗窱，辇道属扶疎。
云罕明丹谷，霜笳彻紫虚。
水疑投石处，溪似钓璜余。
帝泽颁巵酒，人欢颂里闾。
一承黄竹咏，长奉白茆居。','',''),('quantangshi-04914','奉和幸望春宫送朔方军大总管张仁亶','李乂','quantangshi','','卷5','边郊草具腓，河塞有兵机。
上宰调梅寄，元戎细柳威。
武貔东道出，鹰隼北庭飞。
玉匣谋中野，金舆下太微。
投醪衔饯酌，缉衮事征衣。
勿谓公孙老，行闻奏凯归。','',''),('quantangshi-04915','奉和幸三会寺应制','李乂','quantangshi','','卷5','睿德总无边，神臯择胜缘。
二仪齐法驾，三会礼香筵。
汉阙中黄近，秦山太白连。
台疑观鸟日，池似刻鲸年。
满月临真境，秋风入御弦。
小臣叨下列，持管谬窥天。','',''),('quantangshi-04916','奉和幸大荐福寺','李乂','quantangshi','','卷5','象设隆新宇，龙潜想旧居。
碧楼披玉额，丹仗导金舆。
代日兴光近，周星掩曜初。
空歌清沛筑，梵乐奏胡书。
帝造环三界，天文贲六虚。
康哉孝理日，崇德在真如。','',''),('quantangshi-04917','夏日都门送司马员外逸客孙员外佺北征','李乂','quantangshi','','卷5','日逐滋南寇，天威抚北垂。
析圭行仗节，持印且分麾。
羽檄双凫去，兵车驷马驰。
虎旗悬气色，龙剑抱雄雌。
候月期戡翦，经时念别离。
坐闻关陇外，无复引弓儿。','',''),('quantangshi-04918','元日恩赐柏叶应制','李乂','quantangshi','','卷5','劲节凌冬劲，芳心待岁芳。
能令人益寿，非止麝含香。','',''),('quantangshi-04919','侍宴桃花园咏桃花应制','李乂','quantangshi','','卷5','绮蕚成蹊遍籞芳，红英扑地满筵香。
莫将秋宴传王母，来比春华奉圣皇。','',''),('quantangshi-04920','奉和三日祓禊渭滨','李乂','quantangshi','','卷5','上林花鸟暮春时，上巳陪游乐在兹。
此日欣逢临渭赏，昔年空道济汾词。','',''),('quantangshi-04921','奉和幸韦嗣立山庄侍宴应制','李乂','quantangshi','','卷5','曲榭回廊绕涧幽，飞泉喷下溢池流。
祗应感发明王梦，遂得邀迎圣帝游。','',''),('quantangshi-04922','侍宴安乐公主新宅应制','李乂','quantangshi','','卷5','牵牛南渡象昭回，学凤楼成帝女来。
平旦鵷鸾歌舞席，方宵鹦鹉献酬杯。','',''),('quantangshi-04923','饯唐永昌','李乂','quantangshi','','卷5','田郎才貌出咸京，潘子文华向洛城。
愿以深心留善政，当令强项谢高名。','',''),('quantangshi-04924','九日幸临渭亭登高应制得开字','盧藏用','quantangshi','','卷5','上月重阳满，中天万乘来。
萸依佩里发，菊向酒边开。
圣泽烟云动，宸文象纬回。
小臣无以答，愿奉亿千杯。','',''),('quantangshi-04925','奉和九月九日登慈恩寺浮图应制','盧藏用','quantangshi','','卷5','化塔龙山起，中天凤辇迂。
彩旒牵画刹，杂佩冒香萸。
宝叶擎千座，金英渍百盂。
秋云飘圣藻，霄极捧连珠。','',''),('quantangshi-04926','宋主簿鸣臯梦赵六予未及报而陈子云亡今追为此诗答宋兼贻平昔游旧','盧藏用','quantangshi','','卷5','暮川罕停波，朝云无留色。
故人琴与诗，可存不可识。
识心尚可亲，琴诗非故人。
鸣臯初梦赵，蜀国已悲陈。
感化伤沦灭，魂交惜未申。
冥期失幽报，兹理复今晨。
前嗟成后泣，已矣将何及。
旧感与新悲，虚怀酬昔时。
赵侯鸿宝气，独负青云姿。
羣有含妙识，众象悬清机。
雄谈尽物变，精义解人颐。
在阴既独善，幽跃自为疑。
踠彼千里足，伤哉一尉欺。
陈生富清理，卓荦兼文史。
思缛巫山云，调逸岷江水。
铿锵哀忠义，感激怀知己。
负劒登蓟门，孤游入燕市。
浩歌去京国，归守西山趾。
幽居探元化，立言见千祀。
埋没经济情，良图竟云已。
坐忆平生游，十载怀嵩丘。
题书满古壁，采药遍岩幽。
子微化金鼎，仙笙不可求。
荣哉宋与陆，名宦美中州。
存亡一暌阻，岐路方悠悠。
自予事山海，及兹人世改。
传闻当世荣，皆入古人名。
无复平原赋，空余邻笛声。
泣对西州使，悲访北邙茔。
新坟蔓宿草，旧阙毁残铭。
为君成此曲，因言寄友生。
默语无穷事，凋伤共此情。','',''),('quantangshi-04927','饯唐州高使君赴任','盧藏用','quantangshi','','卷5','饯酒临丰树，褰帷出鲁阳。
蕙兰春已晚，桐柏路犹长。
祖逖方城镇，安期外氏乡。
从来二千石，天子命唯良。','',''),('quantangshi-04928','饯许州宋司马赴任','盧藏用','quantangshi','','卷5','国为休征选，舆因仲举题。
山川襄野隔，朋酒灞亭暌。
零雨征轩骛，秋风别骥嘶。
骊歌一曲罢，愁望正凄凄。','',''),('quantangshi-04929','奉和立春游苑迎春应制','盧藏用','quantangshi','','卷5','天游龙辇驻城闉，上苑迟光晚更新。
瑶台半入黄山路，玉槛傍临玄霸津。
梅香欲待歌前落，兰气先过酒上春。
幸预柏台称献寿，愿陪千亩及农晨。','',''),('quantangshi-04930','奉和幸安乐公主山庄应制','盧藏用','quantangshi','','卷5','皇女璚台天汉浔，星桥月宇构山林。
飞萝半拂银题影，瀑布环流玉砌阴。
菊浦香随鹦鹉泛，箫楼韵逐凤凰吟。
瑶池驻跸恩方久，璧月无文兴转深。','',''),('quantangshi-04931','夜宴安乐公主宅','盧藏用','quantangshi','','卷5','侯家主第一时新，上席华年不惜春。
珠釭缀日那知夜，玉斝流霞畏底晨。','',''),('quantangshi-04932','九月九日幸临渭亭登高应制得涘字','岑羲','quantangshi','','卷5','重九开科历，千龄逢圣纪。
爰豫瞩秦坰，升高临灞涘。
玉醴浮仙菊，琼筵荐芳芷。
一闻帝舜歌，欢娱良未已。','',''),('quantangshi-04933','奉和九月九日登慈恩寺浮屠应制','岑羲','quantangshi','','卷5','宝台耸天外，玉辇步云端。
日丽重阳景，风摇季月寒。
梵堂遥集雁，帝乐近翔鸾。
愿献延龄酒，长承湛露欢。','',''),('quantangshi-04934','饯唐州高使君','岑羲','quantangshi','','卷5','苍茫南塞地，明媚上春时。
目极伤千里，怀君不自持。
征车别岐路，斜日下崦嵫。
一叹轺轩阻，悠悠即所思。','',''),('quantangshi-04935','奉和春日幸望春宫应制','岑羲','quantangshi','','卷5','和风助律应韶年，清跸乘高入望仙。
花笑莺歌迎帝辇，云披日霁俯皇川。
南山近压仙楼上，北斗平临御扆前。
一奉恩荣同镐宴，空知率舞听薰弦。','',''),('quantangshi-04936','奉和幸安乐公主山庄应制','岑羲','quantangshi','','卷5','银牓重楼出雾开，金舆步辇向天来。
泉声迥入吹箫曲，山势遥临献寿杯。
帝女含笑流飞电，干文动色象昭回。
诚愿北极拱尧日，微臣拚舞咏康哉。','',''),('quantangshi-04937','夜宴安乐公主新宅','岑羲','quantangshi','','卷5','金牓重楼开夜扉，琼筵爱客未言归。
衔欢不觉银河曙，尽醉那知玉漏稀。','',''),('quantangshi-04938','仪坤庙乐章二首 一','薛稷','quantangshi','','卷5','阳灵配德，阴魄昭升。
尧坛凤下，汉室龙兴。
俔天作对，前旒是凝。
化行南国，道盛西陵。
造舟集灌，无德而称。
我粢既洁，我醴既澄。
阴阴灵庙，光灵若凭。
德馨惟飨，孝思烝烝。','',''),('quantangshi-04939','仪坤庙乐章二首 二','薛稷','quantangshi','','卷5','干道既亨，坤元以贞。
肃雍攸在，辅佐斯成。
外睦九族，内光一庭。
克生睿哲，祚我休明。
钦若徽范，悠哉淑灵。
建兹清宫，于彼上京。
缩茅以献，絜秬惟馨。
实受其福，斯乎亿龄。','',''),('quantangshi-04940','九日幸临渭亭登高应制得历字','薛稷','quantangshi','','卷5','暮节乘原野，宣游俯崖壁。
秋登华实满，气严鹰隼击。
仙菊含霜泛，圣藻临云锡。
愿陪九九辰，长奉千千历。','',''),('quantangshi-04941','慈恩寺九日应制','薛稷','quantangshi','','卷5','宝宫星宿劫，香塔鬼神功。
王游盛尘外，睿览出区中。
日宇开初景，天词掩大风。
微臣谢时菊，薄采入芳丛。','',''),('quantangshi-04942','早春鱼亭山','薛稷','quantangshi','','卷5','春气动百草，纷荣时断续。
白云自高妙，裴回空山曲。
阳林花已红，寒涧苔未绿。
伊余息人事，萧寂无营欲。
客行虽云远，翫之聊自足。','',''),('quantangshi-04943','秋日还京陕西十里作','薛稷','quantangshi','','卷5','驱车越陕郊，北顾临大河。
隔河望乡邑，秋风水增波。
西登咸阳途，日暮忧思多。
傅岩既纡郁，首山亦嵯峨。
操筑无昔老，采薇有遗歌。
客游节回换，人生知几何。','',''),('quantangshi-04944','奉和送金城公主适西蕃应制','薛稷','quantangshi','','卷5','天道宁殊俗，慈仁乃戢兵。
怀荒寄赤子，忍爱鞠苍生。
月下琼娥去，星分宝婺行。
关山马上曲，相送不胜情。','',''),('quantangshi-04945','春日登楼野望','薛稷','quantangshi','','卷5','凭轩聊一望，春色几芬菲。
野外烟初合，楼前花正飞。
娇莺弄新响，斜日散余晖。
谁忍孤游客，言念独依依。','',''),('quantangshi-04946','饯许州宋司马赴任','薛稷','quantangshi','','卷5','令弟与名兄，高才振两京。
别序闻鸿燕，离章动鹡鸰。
远朋驰翰墨，胜地写丹青。
风月相思夜，劳望颍川星。','',''),('quantangshi-04947','奉和圣制春日幸望春宫应制','薛稷','quantangshi','','卷5','九春风景足林泉，四面云霞敞御筵。
花镂黄山绣作苑，草图玄灞锦为川。
飞觞竞醉心回日，走马争先眼着鞭。
喜奉仙游归路远，直言行乐不言旋。','',''),('quantangshi-04948','奉和幸安乐公主山庄应制','薛稷','quantangshi','','卷5','主家园囿极新规，帝郊游豫奉天仪。
欢宴瑶台镐京集，赏赐铜山蜀道移。
曲阁交映金精板，飞花乱下珊瑚枝。
借问今朝八龙驾，何如昔日望仙池。','',''),('quantangshi-04949','秋朝览镜','薛稷','quantangshi','','卷5','客心惊落木，夜坐听秋风。
朝日看容鬓，生涯在镜中。','',''),('quantangshi-04950','夜宴安乐公主新宅','薛稷','quantangshi','','卷5','秦楼宴喜月裴回，妓筵银烛满庭开。
坐中香气排花出，扇后歌声逐酒来。','',''),('quantangshi-04951','饯唐永昌','薛稷','quantangshi','','卷5','河洛风烟壮市朝，送君飞凫去渐遥。
更思明年桃李月，花红柳绿宴浮桥。','',''),('quantangshi-04952','九日幸临渭亭登高应制得酒字','馬懷素','quantangshi','','卷5','睿赏叶通三，宸游契重九。
兰将叶布席，菊用香浮酒。
落日下桑榆，秋风歇杨柳。
幸齐东户庆，希荐南山寿。','',''),('quantangshi-04953','奉和九月九日登慈恩寺浮图应制','馬懷素','quantangshi','','卷5','季月启重阳，金舆陟宝坊。
御旗横日道，仙塔俨云庄。
帝跸千官从，干词七曜光。
顾慙文墨职，无以颂时康。','',''),('quantangshi-04954','奉和送金城公主适西蕃应制','馬懷素','quantangshi','','卷5','帝子今何去？重姻适异方。
离情怆宸掖，别路遶关梁。
望绝园中柳，悲缠陌上桑。
空余愿黄鹤，东顾忆回翔。','',''),('quantangshi-04955','饯许州宋司马赴任','馬懷素','quantangshi','','卷5','颍川开郡邑，角宿分躔野。
君非仲举才，谁是题舆者。
悯悯琴上鹤，萧萧路傍马。
严程若可留，别袂希再把。','',''),('quantangshi-04956','饯唐州高使君赴任','馬懷素','quantangshi','','卷5','外牧资贤守，斯人奉帝俞。
淮南膺建隼，渭北暂分符。
坐叹烟波隔，行嗟物候殊。
何年升美课，回首北城隅。','',''),('quantangshi-04957','奉和立春游苑迎春应制','馬懷素','quantangshi','','卷5','玄龠飞灰出洞房，青郊迎气肇初阳。
仙舆暂下宜春苑，御醴行开荐寿觞。
映水轻苔犹隐绿，缘堤弱柳未舒黄。
唯有裁花饰簪鬓，恒随圣藻狎年光。','',''),('quantangshi-04958','奉和圣制春日幸望春宫应制','馬懷素','quantangshi','','卷5','彩仗雕舆俯碧浔，行春御气发皇心。
摇风细柳萦驰道，映日轻花出禁林。
遍野园亭开帟幕，连堤草树狎衣簪。
谬参西掖霑尧酒，愿沐南薰解舜琴。','',''),('quantangshi-04959','奉和人日宴大明宫恩赐彩缕人胜应制','馬懷素','quantangshi','','卷5','日宇千门平旦开，天容万象列昭回。
三阳候节金为胜，百福迎祥玉作杯。
就暖风光偏着柳，辞寒雪影半藏梅。
何幸得参词赋职，自怜终乏马卿才。','',''),('quantangshi-04960','奉和幸安乐公主山庄应制','馬懷素','quantangshi','','卷5','主家台沼胜平阳，帝幸欢娱乐未央。
掩映雕窗交极浦，参差绣户绕回塘。
泉声百处传歌曲，树影千重对舞行。
圣酒一霑何以报，唯欣颂德奉时康。','',''),('quantangshi-04961','兴庆池侍宴应制','馬懷素','quantangshi','','卷5','积水逶迤绕直城，[含]虚皎镜有余清。
图云曲榭连缇幕，映日中塘间彩旌。
赏洽犹闻箫管沸，欢留更睹木兰轻。
无劳海上寻仙客，即此蓬莱在帝京。','',''),('quantangshi-04962','夜宴安乐公主宅','馬懷素','quantangshi','','卷5','凤楼䆗窱凌三袭，翠幌玲珑瞰九衢。
复道中宵留宴衎，弥令上客想踟蹰。','',''),('quantangshi-04963','饯唐永昌','馬懷素','quantangshi','','卷5','闻君出宰洛阳隅，宾友称觞饯路衢。
别后相思在何处？祗应关下望仙凫。','',''),('quantangshi-04964','明冰篇','富嘉謨','quantangshi','','卷5','北陆苍茫河海凝，南山阑干昼夜冰。
素彩峨峨明月升，深山穷谷不自见。
安知采斵备嘉荐，阴房涸冱掩寒扇。
阳春二月朝始暾，春光潭沱度千门。
明冰时出御至尊，彤庭赫赫九仪备。
腰玉煌煌千官事，明冰毕赋周在位。
忆昨沙漠寒风涨，昆仑长河冰始壮。
漫汗崚嶒积亭障，噰噰鸣雁江上来。
禁苑池台冰复开，摇青涵绿映楼台。
豳歌七月王风始，凿冰藏用昭物轨，四时不忒千万祀。','',''),('quantangshi-04965','长门怨','吳少微','quantangshi','','卷5','月出映层城，孤圆上太清。
君王眷爱歇，枕席凉风生。
怨咽不能寝，踟蹰步前楹。
空阶白露色，百草寒虫鸣。
念昔金房里，犹嫌玉座轻。
如何娇所误，长夜泣恩情。','',''),('quantangshi-04966','和崔侍御日用游开化寺阁','吳少微','quantangshi','','卷5','左宪多才雄，故人尤鸷鹗。
护赠单于使，休轺太原郭。
馆次厌烦歊，清怀寻寂寞。
西缘十里余，北上开化阁。
初入云树间，冥蒙未昭廓。
渐出栏榥外，万里秋景焯。
岁晏风落山，天寒水归壑。
览物颂幽景，三乘动玄钥。
但敷利解言，永用忘昏着。','',''),('quantangshi-04967','哭富嘉谟','吳少微','quantangshi','','卷5','吾友适不死，于戏社稷臣。
直禄非造利，长怀大庇人。
乃通承明籍，遘此敦牂春。
药厉其可畏，皇穹故匪仁。
畴昔与夫子，孰云异天伦。
同病一相失，茫茫不重陈。
子之文章在，其殆尼父新。
鼓兴斡河岳，贞词毒鬼神。
可悲不可朽，车輤没荒榛。
圣主贤为宝，吁兹大国贫。','',''),('quantangshi-04968','过汉故城','吳少微','quantangshi','','卷5','大汉昔未定，强秦犹擅场。
中原逐鹿罢，高祖郁龙骧。
经始谋帝座，兹焉壮未央。
规模窥栋宇，表里浚城隍。
羣后崇长乐，中朝增建章。
句陈被兰錡，乐府奏芝房。
翡翠明珠帐，鸳鸯白玉堂。
清晨宝鼎食，闲夜郁金香。
天马来东道，佳人倾北方。
何其赫隆盛，自谓宝灵长。
历数有时尽，哀平嗟不昌。
冰坚成巨猾，火德遂颓纲。
奥位匪虚校，贪天竟速亡。
魂神吁社稷，豹虎鬬岩廊。
金狄移灞岸，铜盘向洛阳。
君王无处所，年代几荒凉。
宫阙谁家域，蓁芜罥我裳。
井田唯有草，海水变为桑。
昔在高门内，于今岐路傍。
余基不可识，古墓列成行。
狐兔惊魍魉，鸱鸟吓獝狂。
空城寒日晚，平野暮云黄。
烈烈樊青棘，萧萧吹白杨。
千秋并万岁，空使咏歌伤。','',''),('quantangshi-04969','古意','吳少微','quantangshi','','卷5','洛阳芳树向春开，洛阳女儿平旦来。
流车走马纷相催，折芳瑶华向曲台。
曲台自有千万行，重花累叶间垂杨。
北林朝日境明光，南国微风苏合香。
可怜窈窕女，不作邯郸娼。
妙舞轻回拂长袖，高歌浩唱发清商。
歌终舞罢欢无极，乐往悲来长叹息。
阳春白日不少留，红荣碧树无颜色。
碧树风花先春度，珠帘粉泽无人顾。
如何年少忽迟暮，坐见明月与白露。
明月白露夜已寒，香衣锦带空珊珊。
今日阳春一妙曲，凤皇楼上与君弹。','',''),('quantangshi-04970','怨歌行','吳少微','quantangshi','','卷5','城南有怨妇，含情傍芳丛。
自谓二八时，歌舞入汉宫。
皇恩数流眄，承幸玉堂中。
绿柏黄花催夜酒，锦衣罗袂逐春风。
建章西宫焕若神，燕赵美女三千人。
君王厌德不忘新，况羣艳冶纷来陈。
是时别君不再见，三十三春长信殿。
长信重门昼掩关，清房晓帐幽且闲。
绮窗虫网氛尘色，文轩莺对桃李颜。
天王贵宫不贮老，浩然含泪今来还。
自怜春色转晚暮，试逐佳游芳草路。
小腰丽女夺人奇，金鞍少年曾不顾。
归来谁为夫，请谢西家妇，莫辞先醉解罗襦。','',''),('quantangshi-04971','陇头水','員半千','quantangshi','','卷5','路出金河道，山连玉塞门。
旌旗云里度，杨柳曲中喧。
喋血多壮胆，裹革无怯魂。
严霜敛曙色，大明辞朝暾。
尘销营卒垒，沙静都尉垣。
雾卷白山出，风吹黄叶翻。
将军献凯入，万里绝河源。','',''),('quantangshi-04972','陇右途中遭非语','員半千','quantangshi','','卷5','赵有两毛遂，鲁闻二曾参。
慈母犹且惑，况在行路心。
冠冕无丑士，贿赂成知己。
名利我所无，清浊谁见理。
敝服空逢春，缓带不着身。
出游非怀璧，何忧乎忌人。
正须自保爱，振衣出世尘。','',''),('quantangshi-04973','仪坤庙乐章','員半千','quantangshi','','卷5','孝享云毕，维彻有章。
云感玄羽，风凄素商。
瞻望神座，祗恋匪遑。
礼终乐阕，肃雍锵锵。','',''),('quantangshi-04974','铜雀妓','王適','quantangshi','','卷5','日暮铜雀迥，秋深玉座清。
萧森松柏望，委郁绮罗情。
君恩不再得，妾舞为谁轻。','',''),('quantangshi-04975','蜀中言怀','王適','quantangshi','','卷5','独坐年将暮，常怀志不通。
有时须问影，无事却书空。
弃置如天外，平生似梦中。
蓬心犹是客，华髪欲成翁。
迹滞魂逾窘，情乖路转穷。
别离同夜月，愁思隔秋风。
老少悲颜驷，盈虚悟翟公。
时来不可问，何用求童蒙。','',''),('quantangshi-04976','古别离','王適','quantangshi','','卷5','昔岁惊杨柳，高楼悲独守。
今年芳树枝，孤栖怨别离。
珠帘昼不卷，罗幔晓长垂。
苦调琴先觉，愁容镜独知。
频年雁度无消息，罢却鸳文何用织。
夜还罗帐空有情，春着裙腰自无力。
青轩桃李落纷纷，紫庭兰蕙日氛氲。
已能顦顇今如此，更复含情一待君。','',''),('quantangshi-04977','江上有怀','王適','quantangshi','','卷5','湛湛江水见底清，荷花莲子傍江生。
采莲将欲寄同心，秋风落花空复情。
棹歌数曲如有待，正见明月度东海。
海上云尽月苍苍，万里分辉满洛阳。
洛阳闺阁夜何央，蛾眉婵娟断人肠。
寂寥金屏空自掩，青荧银烛不生光。
应怜水宿洞庭子，今夕迢遥天一方。','',''),('quantangshi-04978','江滨梅','王適','quantangshi','','卷5','忽见寒梅树，开花汉水滨。
不知春色早，疑是弄珠人。','',''),('quantangshi-04979','临水亭','王適','quantangshi','','卷5','高馆基曾山，微幂生花草。
傍对野村树，下临车马道。
清朗悟心术，幽遐备瞻讨。
回合峰隐云，联绵渚萦岛。
气似沧洲胜，风为青春好。
相及盛年时，无令叹衰老。','',''),('quantangshi-04980','长门怨','齊澣','quantangshi','','卷5','茕茕孤思逼，寂寂长门夜。
妾妬亦知非，君恩那不借。
携琴就玉阶，调悲声未谐。
将心托明月，流影入君怀。','',''),('quantangshi-04981','长门怨','齊澣','quantangshi','','卷5','宫殿沈沈月欲分，昭阳更漏不堪闻。
珊瑚枕上千行泪，不是思君是恨君。','',''),('quantangshi-04982','仪坤庙乐章','祝欽明','quantangshi','','卷5','閟宫实实，清庙微微。
降格无象，馨香有依。
式昭纂庆，方融嗣徽。
明禋是享，神保聿归。','',''),('quantangshi-04983','仪坤庙乐章','劉知幾','quantangshi','','卷5','妙算申帷幄，神谋出庙廷。
两阶文物备，七德武功成。
校猎长杨苑，屯军细柳营。
将军献凯入，歌舞溢重城。','',''),('quantangshi-04984','仪坤庙乐章','胡雄','quantangshi','','卷5','送文迎武递参差，一始一终光圣仪。
四海生人歌有庆，千龄孝享肃无亏。','',''),('quantangshi-04985','仪坤庙乐章','張齊賢','quantangshi','','卷5','裸圭既濯，郁鬯既陈。
画幕云举，黄流玉醇。
仪充献酌，礼盛众禋。
地察惟孝，愉焉飨亲。','',''),('quantangshi-04986','仪坤庙乐章','鄭善玉','quantangshi','','卷5','酌郁既灌，取萧方爇。
笾豆静器，簠簋芬飶。
鱼腊荐美，牲牷表絜。
是戢是将，载迎载列。','',''),('quantangshi-04987','仪坤庙乐章','丘悅','quantangshi','','卷5','孝哉我后，冲乎廻圣。
道映重华，德辉文命。
慕深视箧，情殷抚镜。
万国移命，兆人承庆。','',''),('quantangshi-04988','芳树','沈佺期','quantangshi','','卷5','何地早芳菲，宛在长门殿。
夭桃色若绶，穠李光如练。
啼鸟弄花疎，游蜂饮香遍。
叹息春风起，飘零君不见。','',''),('quantangshi-04989','长安道','沈佺期','quantangshi','','卷5','秦地平如掌，层城入云汉。
楼阁九衢春，车马千门旦。
绿槐开复合，红尘聚还散。
日晚鬬鸡还，经过狭斜看。','',''),('quantangshi-04990','有所思','沈佺期','quantangshi','','卷5','君子事行役，再空芳岁期。
美人旷延伫，万里浮云思。
园槿绽红艳，郊桑柔绿滋。
坐看长夏晚，秋月照罗帏。','',''),('quantangshi-04991','临高台','沈佺期','quantangshi','','卷5','高台临广陌，车马纷相续。
回首思旧乡，云山乱心曲。
远望河流缓，周看原野绿。
向夕林鸟还，忧来飞景促。','',''),('quantangshi-04992','凤笙曲','沈佺期','quantangshi','','卷5','忆昔王子晋，凤笙游云空。
挥手弄白日，安能恋青宫。
岂无婵娟子，结念罗帏中。
怜寿不贵色，身世两无穷。','',''),('quantangshi-04993','拟古别离','沈佺期','quantangshi','','卷5','白水东悠悠，中有西行舟。
舟行有返棹，水去无还流。
奈何生别者，戚戚怀远游。
远游谁当惜，所悲会难收。
自君阒芳躧，青阳四五遒。
皓月掩兰室，光风虚蕙楼。
相思无明晦，长叹累冬秋。
离居久迟暮，高驾何淹留。','',''),('quantangshi-04994','辛丑岁十月上幸长安时扈从出西岳作','沈佺期','quantangshi','','卷5','西镇何穹崇，壮哉信灵造。
诸岭皆峻秀，中峯特美好。
傍见巨掌存，势如石东倒。
颇闻首阳去，开坼此河道。
磅礴压洪源，巍峨壮清昊。
云泉纷乱瀑，天磴屹横抱。
子先呼其巅，宫女世不老。
下有府君庙，历载传洒扫。
皇明应天游，十月戒丰镐。
微未忝闲从，兼得事苹藻。
宿心爱兹山，意欲拾灵草。
阴壑已永閟，云窦绝探讨。
芳月期来过，回策思方浩。','',''),('quantangshi-04995','和杜麟台元志春情','沈佺期','quantangshi','','卷5','嘉树满中园，氛氲罗秀色。
不见仙山云，倚琴空太息。
沈思若在梦，缄怨似无忆。
青春坐南移，白日忽西匿。
蛾眉返清镜，闺中不相识。','',''),('quantangshi-04996','别侍御严凝','沈佺期','quantangshi','','卷5','七泽云梦林，三湘洞庭水。
自古传剽俗，有时逋恶子。
令君出使车，行迈方靡靡。
静言芟枳棘，慎勿伤兰芷。','',''),('quantangshi-04997','送乔随州侃','沈佺期','quantangshi','','卷5','结交三十载，同游一万里。
情为契阔生，心由别离死。
拜恩前后人，从宦差池起。
今尔归汉东，明珠报知己。','',''),('quantangshi-04998','送友人任括州','沈佺期','quantangshi','','卷5','青春浩无际，白日乃迟迟。
胡为赏心客，叹迈此芳时。
瓯粤迫兹守，京阙从此辞。
茫茫理云帆，草草念行期。
纷吾结远佩，帐饯出河湄。
太息东流水，盈觞难再持。','',''),('quantangshi-04999','饯远','沈佺期','quantangshi','','卷5','任子徇遐禄，结友开旧襟。
撰酌辍行叹，指途勤远心。
秋皛澄回壑，霁色肃明林。
暧然青轩暮，浩思非所任。','',''),('quantangshi-05000','同工部李侍郎适访司马子微','沈佺期','quantangshi','','卷5','紫微降天仙，丹地投云藻。
上言华顶事，中问长生道。
华顶居最高，大壑朝阳早。
长生术何妙，童颜后天老。
清晨朝凤京，静夜思鸿宝。
凭崖饮蕙气，过涧摘灵草。
人非冢已荒，海变田应燥。
昔尝游此郡，三霜弄溟岛。
绪言霞上开，机事尘外扫。
顷来迫世务，清旷未云保。
崎岖待漏恩，怵惕司言造。
轩皇重斋拜，汉武爱祈祷。
顺风怀崆峒，承露在丰镐。
泠然魏轻驭，复得散幽抱。
柱下留伯阳，储闱登四皓。','',''),('quantangshi-05001','自昌乐郡溯流至白石岭下行入郴州','沈佺期','quantangshi','','卷5','兹山界夷夏，天险横寥廓。
太史漏登探，文命限开凿。
北流自南泻，羣峰回众壑。
驰波如电腾，激石似雷落。
崖留盘古树，涧蓄神农药。
乳窦何淋漓，苔藓更彩错。
娟娟潭里虹，渺渺滩边鹤。
岁杪应流火，天高云物薄。
金风吹绿梢，玉露洗红箨。
溯舟始兴廨，登践桂阳郭。
匍匐缘修坂，穹窿曳长䋏。
碍林阻往来，遇堰每前却。
救艰不遑饭，毕昏无暇泊。
濯溪宁足惧，磴道谁云恶。
我行山水间，湍险皆不若。
安能独见闻，书此贻京洛。','',''),('quantangshi-05002','过蜀龙门','沈佺期','quantangshi','','卷5','龙门非禹凿，诡怪乃天功。
西南出巴峡，不与众山同。
长窦亘五里，宛转复嵌空。
伏湍喣潜石，瀑水生轮风。
流水无昼夜，喷薄龙门中。
潭河势不测，藻葩垂彩虹。
我行当季月，烟景共舂融。
江关勤亦甚，巘崿意难穷。
势将息机事，炼药此山东。','',''),('quantangshi-05003','入衞作','沈佺期','quantangshi','','卷5','淇上风日好，纷纷沿岸多。
绿芳幸未歇，泛滥此明波。
采蘩忆幽吹，理棹想荆歌。
郁然怀君子，浩旷将如何。','',''),('quantangshi-05004','夜泊越州逢北使','沈佺期','quantangshi','','卷6','天地降雷雨，放逐还国都。
重以风潮事，年月戒回舻。
容颜荒外老，心想域中愚。
憩泊在兹夜，炎云逐斗枢。
䬓{风兪}萦海若，霹雳耿天吴。
鳌拚羣岛失，鲸吞众流输。
偶逢金华使，握手泪相濡。
饥共噬齐枣，眠共席秦蒲。
既北思攸济，将南睿所图。
往来固无咎，何忽惮前桴。','',''),('quantangshi-05005','绍隆寺','沈佺期','quantangshi','','卷6','吾从释迦久，无上师涅盘。
探道三十载，得道天南端。
非胜适殊方，起喧归理难。
放弃乃良缘，世虑不曾干。
香界萦北渚，花龛隐南峦。
危昂阶下石，演漾窗中澜。
云盖看木秀，天空见藤盘。
处俗勒宴坐，居贫业行坛。
试将有漏躯，聊作无生观。
了然究诸品，弥觉静者安。','',''),('quantangshi-05006','神龙初废逐南荒途出郴口北望苏耽山','沈佺期','quantangshi','','卷6','少曾读仙史，知有苏耽君。
流望来南国，依然会昔闻。
泊舟问耆老，遥指孤山云。
孤山郴郡北，不与众山羣。
重崖下萦映，嶛峣上乣纷。
碧峰泉附落，红壁树傍分。
选地今方尔，升天因可云。
不才予窜迹，羽化子遗芬。
将览成麟凤，旋惊御鬼文。
此中迷出处，含思独氛氲。','',''),('quantangshi-05007','初达驩州','沈佺期','quantangshi','','卷6','流子一十八，命予偏不偶。
配远天遂穷，到迟日最后。
水行儋耳国，陆行雕题薮。
魂魄游鬼门，骸骨遗鲸口。
夜则忍饥卧，朝则抱病走。
搔首向南荒，拭泪看北斗。
何年赦书来？重饮洛阳酒。','',''),('quantangshi-05008','被弹','沈佺期','quantangshi','','卷6','知人昔不易，举非贵易失。
尔何按国章，无罪见呵叱。
平生守直道，遂为众所嫉。
少以文作吏，手不曾开律。
一旦法相持，荒忙意如漆。
幼子双囹圄，老夫一念室。
昆弟两三人，相次俱囚桎。
万铄当众怒，千谤无片实。
庶以白黑谗，显此泾渭质。
劾吏何咆哮，晨夜闻扑抶。
事间拾虚证，理外存枉笔。
怀痛不见伸，抱冤竟难悉。
穷囚多垢腻，愁坐饶虮虱。
三日唯一饭，两旬不再栉。
是时盛夏中，暵赫多瘵疾。
瞪目眠欲闭，暗呜气不出。
有风自扶摇，鼓荡无伦匹。
安得吹浮云，令我见白日。','',''),('quantangshi-05009','枉系二首 一','沈佺期','quantangshi','','卷6','吾怜曾家子，昔有投杼疑。
吾怜姬公旦，非无鸱鸮诗。
臣子竭忠孝，君亲惑谗欺。
萋斐离骨肉，含愁兴此辞。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-05010','枉系二首 二','沈佺期','quantangshi','','卷6','昔日公冶长，非罪遇缧絏。
圣人降其子，古来叹独绝。
我无毫髪瑕，苦心怀冰雪。
今代多秀士，谁能继明辙。','',''),('quantangshi-05011','黄鹤','沈佺期','quantangshi','','卷6','黄鹤佐丹凤，不能羣白鹇。
拂云游四海，弄影到三山。
遥忆君轩上，来下天池间。
明珠世不重，知有报恩环。','',''),('quantangshi-05012','伤王学土','沈佺期','quantangshi','','卷6','闭囚断外事，昧坐半余朞。
有言頴叔子，亡来已一时。
初闻宛不信，中话涕涟洏。
痛哉玄夜重，何遽青春姿。
忆汝曾旅食，屡空瀍涧湄。
吾徒禄未厚，筲斗愧相贻。
原宪贫无愁，颜回乐自持。
诏书择才善，君为王子师。
宠儒名可尚，论秩官犹欺。
化往不复见，情来安可思。
目绝毫翰洒，耳无歌讽期。
灵柩寄何处，精魂今何之？
恨予在丹棘，不得看素旗。
孀妻知己叹，幼子路人悲。
感游值商日，绝弦留此词。','',''),('quantangshi-05013','古镜','沈佺期','quantangshi','','卷6','莓苔翳清池，虾蟆蚀明月。
埋落今如此，照心未尝歇。
愿垂拂拭恩，为君鉴玄髪。','',''),('quantangshi-05014','凤箫曲','沈佺期','quantangshi','','卷6','八月凉风动高阁，千金丽人卷绡幕。
已怜池上歇芳菲，不念君恩坐摇落。
世上荣华如转蓬，朝随阡陌暮云中。
飞燕侍寝昭阳殿，班姬饮恨长信宫。
长信宫，昭阳殿，春来歌舞妾自知，秋至帘栊君不见。
昔时嬴女厌世纷，学吹凤箫乘彩云。
含情转睐向萧史，千载红颜持赠君。','',''),('quantangshi-05015','古歌','沈佺期','quantangshi','','卷6','落叶流风向玉台，夜寒秋思洞房开。
水晶帘外金波下，云母窗前银汉回。
玉阶阴阴苔藓色，君王屡綦难再得。
璇闺窈窕秋夜长，绣户徘徊明月光。
燕姬彩帐芙蓉色，秦女金炉兰麝香。
北斗七星横夜半，清歌一曲断君肠。','',''),('quantangshi-05016','七夕曝衣篇','沈佺期','quantangshi','','卷6','君不见昔日宜春太液边，披香画阁与天连。
灯火灼烁九微暎，香气氛氲百和然。
此夜星繁河正白，人传织女牵牛客。
宫中扰扰曝衣楼，天上娥娥红粉席。
曝衣何许曛半黄，宫中彩女提玉箱。
珠履奔腾上兰砌，金梯宛转出梅梁。
绛河里，碧烟上，双花伏兔画屏风，四子盘龙擎斗帐。
舒罗散縠云雾开，缀玉垂珠星汉回。
朝霞散彩羞衣架，晚月分光劣镜台。
上有仙人长命绺，中看玉女迎欢绣。
玳瑁帘中别作春，珊瑚窗里翻成昼。
椒房金屋宠新流，意气娇奢不自由。
汉文宜惜露台费，晋武须焚前殿裘。','',''),('quantangshi-05017','入少密溪','沈佺期','quantangshi','','卷6','云峯苔壁绕溪斜，江路香风夹岸花。
树密不言通鸟道，鸡鸣始觉有人家。
人家更在深岩口，涧水周流宅前后。
游鱼瞥瞥双钓童，伐木丁丁一樵叟。
自言避喧非避秦，薜衣耕凿帝尧人。
相留且待鸡黍熟，夕卧深山萝月春。','',''),('quantangshi-05018','霹雳引','沈佺期','quantangshi','','卷6','岁七月，火伏而金生。
客有鼓琴于门者，奏霹雳之商声。
始戛羽以騞砉，终扣宫而砰駖。
电耀耀兮龙跃，雷阗阗兮雨冥。
气呜唅以会雅，态歘翕以横生。
有如驱千旗，制五兵。
截荒虺，斮长鲸。
孰与广陵比，意别鹤俦精而已。
俾我雄子魄动，毅夫髪立。
怀恩不浅，武义双辑。
视胡若芥，剪羯如拾。
岂徒慷慨中筵，备羣娱之翕习哉。','',''),('quantangshi-05019','立春日内出彩花应制','沈佺期','quantangshi','','卷6','合殿春应早，开箱彩预知。
花迎宸翰发，叶待御筵披。
梅讶香全少，桃惊色顿移。
轻生承剪拂，长伴万年枝。','',''),('quantangshi-05020','晦日浐水应制','沈佺期','quantangshi','','卷6','素浐接宸居，青门盛祓除。
摘兰喧凤野，浮藻溢龙渠。
苑蝶飞殊懒，宫莺啭不疎。
星移天上入，歌舞向储胥。','',''),('quantangshi-05021','奉和洛阳翫雪应制','沈佺期','quantangshi','','卷6','周王甲子旦，汉后德阳宫。
洒瑞天庭里，惊春御苑中。
氛氲生浩气，飒杳舞回风。
宸藻光盈尺，赓歌乐岁丰。','',''),('quantangshi-05022','三日梨园侍宴','沈佺期','quantangshi','','卷6','九重驰道出，三巳禊堂开。
画鷁中流动，青龙上苑来。
野花飘御座，河柳拂天杯。
日晚迎祥处，笙镛下帝台。','',''),('quantangshi-05023','幸梨园亭观打球应制','沈佺期','quantangshi','','卷6','今春芳苑游，接武上琼楼。
宛转萦香骑，飘颻拂画球。
俯身迎未落，回辔逐傍流。
秖为看花鸟，时时误失筹。','',''),('quantangshi-05024','九日临渭亭侍宴应制得长字','沈佺期','quantangshi','','卷6','御气幸金方，凭高荐羽觞。
魏文颁菊蕋，汉武赐萸房。
秋变铜池色，晴添银树光。
年年重九庆，日月奉天长。','',''),('quantangshi-05025','岁夜安乐公主满月侍宴','沈佺期','quantangshi','','卷6','除夜子星回，天孙满月杯。
咏歌麟趾合，箫管凤雏来。
岁炬常然桂，春盘预折梅。
圣皇千万寿，垂晓御楼开。','',''),('quantangshi-05026','安乐公主移入新宅','沈佺期','quantangshi','','卷6','初闻衡汉来，移住斗城隈。
锦帐迎风转，琼筵拂雾开。
马香遗旧埒，凤吹绕新台。','',''),('quantangshi-05027','仙萼亭初成侍宴应制','沈佺期','quantangshi','','卷6','山中气色和，宸赏第中过。
辇路披仙掌，帷宫拂帝萝。
泉临香涧落，峰入翠云多。
无异登玄圃，东南望白河。','',''),('quantangshi-05028','送金城公主适西蕃应制','沈佺期','quantangshi','','卷6','金牓扶丹掖，银河属紫阍。
那堪将凤女，还以嫁乌孙。
玉就歌中怨，珠辞掌上恩。
西戎非我匹，明主至公存。','',''),('quantangshi-05029','幸白鹿观应制','沈佺期','quantangshi','','卷6','紫凤真人府，斑龙太上家。
天流芝盖下，山转桂旗斜。
圣藻垂寒露，仙杯落晚霞。
唯应问王母，桃作几时花。','',''),('quantangshi-05030','洛阳道','沈佺期','quantangshi','','卷6','九门开洛邑，双阙对河桥。
白日青春道，轩裳半下朝。
乘羊稚子看，拾翠美人娇。
行乐归恒晚，香尘扑地遥。','',''),('quantangshi-05031','骢马','沈佺期','quantangshi','','卷6','西北五花骢，来时道向东。
四蹄碧玉片，双眼黄金瞳。
鞍上留明月，嘶间动朔风。
借君驰沛艾，一战取云中。','',''),('quantangshi-05032','铜雀台','沈佺期','quantangshi','','卷6','昔年分鼎地，今日望陵台。
一旦雄图尽，千秋遗令开。
绮罗君不见，歌舞妾空来。
恩共漳河水，东流无重回。','',''),('quantangshi-05033','长门怨','沈佺期','quantangshi','','卷6','月皎风泠泠，长门次掖庭。
玉阶闻坠叶，罗幌见飞萤。
清露凝珠缀，流尘下翠屏。
妾心君未察，愁叹剧繁星。','',''),('quantangshi-05034','巫山高二首 一','沈佺期','quantangshi','','卷6','巫山峯十二，合沓隐昭回。
俯眺琵琶峡，平看云雨台。
古槎天外倚，瀑水日边来。
何忍猿啼夜，荆王枕席开。','',''),('quantangshi-05035','巫山高二首 二','沈佺期','quantangshi','','卷6','神女向高唐，巫山下夕阳。
裴回作行雨，婉娈逐荆王。
电影江前落，雷声峡外长。
霁云无处所，台馆晓苍苍。','',''),('quantangshi-05036','巫山高','沈佺期','quantangshi','','卷6','巫山高不极，合沓状奇新。
暗谷疑风雨，阴崖若鬼神。
月明三峡曙，潮满九江春。
为问阳台客，应知入梦人。','',''),('quantangshi-05037','七夕','沈佺期','quantangshi','','卷6','秋近雁行稀，天高鹊夜飞。
妆成应懒织，今夕渡河归。
月皎宜穿线，风轻得曝衣。
来时不可觉，神验有光辉。','',''),('quantangshi-05038','春闺','沈佺期','quantangshi','','卷6','铁马三军去，金闺二月还。
边愁离上国，春梦失阳关。
池水琉璃净，园花玳瑁斑。
岁华空自掷，忧思不胜颜。','',''),('quantangshi-05039','奉和圣制同皇太子游慈恩寺应制','沈佺期','quantangshi','','卷6','肃肃莲花界，荧荧贝叶宫。
金人来梦里，白马出城中。
涌塔初从地，焚香欲遍空。
天歌应春龠，非是为春风。','',''),('quantangshi-05040','和洛州康士曹庭芝望月有怀','沈佺期','quantangshi','','卷6','天使下西楼，光含万象秋。
台前疑挂镜，帘外似悬钩。
张尹将眉学，班姬取扇俦。
佳期应借问，为报在刀头。','',''),('quantangshi-05041','寿阳王花烛','沈佺期','quantangshi','','卷6','仙媛乘龙夕，天孙捧雁来。
可怜桃李树，更遶凤皇台。
烛送香车入，花临宝扇开。
莫令银箭晓，为尽合欢杯。','',''),('quantangshi-05042','陇头水','沈佺期','quantangshi','','卷6','陇山飞落叶，陇雁度寒天。
愁见三秋水，分为两地泉。
西流入羗郡，东下向秦川。
征客重回首，肝肠空自怜。','',''),('quantangshi-05043','关山月','沈佺期','quantangshi','','卷6','汉月生辽海，朣胧出半晖。
合昏玄菟郡，中夜白登围。
晕落关山迥，光含霜霰微。
将军听晓角，战马欲南归。','',''),('quantangshi-05044','折杨柳','沈佺期','quantangshi','','卷6','玉窗朝日暎，罗帐春风吹。
拭泪攀杨柳，长条踠地垂。
白花飞历乱，黄鸟思参差。
妾自肝肠断，傍人那得知。','',''),('quantangshi-05045','梅花落','沈佺期','quantangshi','','卷6','铁骑几时回，金闺怨早梅。
雪寒花已落，风暖叶应开。
夕逐新春管，香迎小岁杯。
盛时何足贵，书里报轮台。','',''),('quantangshi-05046','紫骝马','沈佺期','quantangshi','','卷6','青玉紫骝鞍，骄多影屡盘。
荷君能剪拂，躞蹀喷桑干。
踠足追奔易，长鸣遇赏难。
摐金一万里，霜露不辞寒。','',''),('quantangshi-05047','上之回','沈佺期','quantangshi','','卷6','制书下关右，天子问回中。
坛墠经过远，威仪侍从雄。
黄麾摇昼日，青幰曳松风。
回望甘泉道，龙山隐汉宫。','',''),('quantangshi-05048','王昭君','沈佺期','quantangshi','','卷6','非君惜鸾殿，非妾妬蛾眉。
薄命由骄虏，无情是画师。
嫁来胡地日，不并汉宫时。
心苦无聊赖，何堪马上辞。','',''),('quantangshi-05049','被试出塞','沈佺期','quantangshi','','卷6','十年通大漠，万里出长平。
寒日生戈劒，阴云拂斾旌。
饥乌啼旧垒，疲马恋空城。
辛苦臯兰北，胡霜损汉兵。','',''),('quantangshi-05050','牛女','沈佺期','quantangshi','','卷6','粉席秋期缓，针楼别怨多。
奔龙争度日，飞鹊乱填河。
失喜先临镜，含羞未解罗。
谁能留夜色，来夕倍还梭。','',''),('quantangshi-05051','杂诗三首 一','沈佺期','quantangshi','','卷6','落叶惊秋妇，高砧促暝机。
蜘蛛寻月度，萤火傍人飞。
清镜红埃入，孤灯绿焰微。
怨啼能至晓，独自懒缝衣。','',''),('quantangshi-05052','杂诗三首 二','沈佺期','quantangshi','','卷6','妾家临渭北，春梦着辽西。
何苦朝鲜郡，年年事鼓鼙。
燕来红壁语，莺向绿窗啼。
为许长相忆，阑干玉筯齐。','',''),('quantangshi-05053','杂诗三首 三','沈佺期','quantangshi','','卷6','闻道黄龙戍，频年不解兵。
可怜闺里月，长在汉家营。
少妇今春意，良人昨夜情。
谁能将旗鼓，一为取龙城。','',''),('quantangshi-05054','剪彩','沈佺期','quantangshi','','卷6','宫女怜芳树，裁花竞早荣。
寒依刀尺尽，春向绮罗生。
弱蔕盘丝发，香蕤结素成。
纤枝幸不弃，长就玉阶倾。','',''),('quantangshi-05055','和中书侍郎杨再思春夜宿直','沈佺期','quantangshi','','卷6','西禁青春满，南端皓月微。
千庐宵驾合，五夜晓钟稀。
星斗横纶阁，天河度琐闱。
烟光章奏里，纷向夕郎飞。','',''),('quantangshi-05056','和常州崔使君寒食夜','沈佺期','quantangshi','','卷6','闻道清明近，春闱向夕阑。
行游昼不厌，风物夜宜看。
斗柄更初转，梅香暗里残。
无劳秉华烛，晴月在南端。','',''),('quantangshi-05057','和崔正谏登秋日早朝','沈佺期','quantangshi','','卷6','鸡鸣朝谒满，露白禁门秋。
爽气临旌戟，朝光暎冕旒。
河宗来献宝，天子命焚裘。
独负池阳议，言从建礼游。','',''),('quantangshi-05058','答甯处州书','沈佺期','quantangshi','','卷6','书报天中赦，人从海上闻。
九泉开白日，六翮起青云。
质幸恩先贷，情孤枉未分。
自怜泾渭别，谁与奏明君。','',''),('quantangshi-05059','李舍人山园送庞邵','沈佺期','quantangshi','','卷6','符传有光辉，喧喧出帝畿。
东隣借山水，南陌驻骖騑。
握手凉风至，当歌秋日微。
高幨去勿缓，人吏待霜威。','',''),('quantangshi-05060','送陆侍御余庆北使','沈佺期','quantangshi','','卷6','古人贵将命，之子出輶轩。
受委当不辱，随时敢赠言。
朔途际辽海，春思绕轘辕。
安得回白日，留欢尽绿樽。','',''),('quantangshi-05061','洛州萧司兵谒兄还赴洛成礼','沈佺期','quantangshi','','卷6','棠棣日光辉，高襟应序归。
来成鸿雁聚，去作凤皇飞。
细草乘轻传，惊花惨别衣。
灞亭春有酒，岐路惜芬菲。','',''),('quantangshi-05062','饯高唐州询','沈佺期','quantangshi','','卷6','弱冠相知早，中年不见多。
生涯在王事，客鬓各蹉跎。
良守初分岳，嘉声即润河。
还从汉阙下，倾耳听中和。','',''),('quantangshi-05063','饯唐郎中洛阳令','沈佺期','quantangshi','','卷6','一台推往妙，三史伫来修。
应宰凫还集，辞郎雉少留。
郊筵乘落景，亭传理残秋。
愿以弦歌暇，芝兰想旧游。','',''),('quantangshi-05064','乐城白鹤寺','沈佺期','quantangshi','','卷6','碧海开龙藏，青云起雁堂。
潮声迎法鼓，雨气湿天香。
树接前山暗，溪承瀑水凉。
无言谪居远，清净得空王。','',''),('quantangshi-05065','游少林寺','沈佺期','quantangshi','','卷6','长歌游宝地，徙倚对珠林。
雁塔风霜古，龙池岁月深。
绀园澄夕霁，碧殿下秋阴。
归路烟霞晚，山蝉处处吟。','',''),('quantangshi-05066','岳馆','沈佺期','quantangshi','','卷6','洞壑仙人馆，孤峰玉女台。
空蒙朝气合，窈窕夕阳开。
流涧含轻雨，虚岩应薄雷。
正逢鸾与鹤，歌舞出天来。','',''),('quantangshi-05067','早发平昌岛','沈佺期','quantangshi','','卷6','解缆春风后，鸣榔晓涨前。
阳乌出海树，云雁下江烟。
积气冲长岛，浮光溢大川。
不能怀魏阙，心赏独泠然。','',''),('quantangshi-05068','夜宿七盘岭','沈佺期','quantangshi','','卷6','独游千里外，高卧七盘西。
晓月临窗近，天河入户低。
芳春平仲绿，清夜子规啼。
浮客空留听，褒城闻曙鸡。','',''),('quantangshi-05069','十三四时尝从巫峡过他日偶然有思','沈佺期','quantangshi','','卷6','小度巫山峡，荆南春欲分。
使君滩上草，神女馆前云。
树悉江中见，猿多天外闻。
别来如梦里，一想一氛氲。','',''),('quantangshi-05070','初达驩州','沈佺期','quantangshi','','卷6','自昔闻铜柱，行来向一年。
不知林邑地，犹隔道明天。
雨露何时及？京华若个边。
思君无限泪，堪作日南泉。','',''),('quantangshi-05071','岭表逢寒食','沈佺期','quantangshi','','卷6','岭外无寒食，春来不见饧。
洛阳新甲子，何日是清明？
花柳争朝发，轩车满路迎。
帝乡遥可念，肠断报亲情。','',''),('quantangshi-05072','驩州南亭夜望','沈佺期','quantangshi','','卷6','昨夜南亭望，分明梦洛中。
室家谁道别，儿女案尝同。
忽觉犹言是，沈思始悟空。
肝肠余几寸，拭泪坐春风。','',''),('quantangshi-05073','少游荆湘因有是题','沈佺期','quantangshi','','卷6','岘北焚蛟浦，巴东射雉田。
岁时宜楚俗，耆旧在襄川。
忆昨经过处，离今二十年。
因君访生死，相识几人全。','',''),('quantangshi-05074','咸阳览古','沈佺期','quantangshi','','卷6','咸阳秦帝居，千载坐盈虚。
版筑林光尽，坛场溜听疎。
野桥疑望日，山火类焚书。
唯有骊峰在，空闻厚葬余。','',''),('quantangshi-05075','览镜','沈佺期','quantangshi','','卷6','霏霏日摇蕙，骚骚风洒莲。
时芳固相夺，俗态岂恒坚。
恍忽夜川里，蹉跎朝镜前。
红颜与壮志，太息此流年。','',''),('quantangshi-05076','题椰子树','沈佺期','quantangshi','','卷6','日南椰子树，香褭出风尘。
丛生调木首，圆实槟榔身。
玉房九霄露，碧叶四时春。
不及涂林果，移根随汉臣。','',''),('quantangshi-05077','同狱者叹狱中无燕','沈佺期','quantangshi','','卷6','何许乘春燕，多知辨夏台。
三时欲并尽，双影未尝来。
食蕋嫌丛棘，衔泥怯死灰。
不如黄雀语，能雪冶长猜。','',''),('quantangshi-05078','则天门赦改年','沈佺期','quantangshi','','卷6','圣人宥天下，幽钥动圜狴。
六甲迎黄气，三元降紫泥。
笼僮上西鼓，振迅广阳鸡。
歌舞将金帛，汪洋被远黎。','',''),('quantangshi-05079','喜赦','沈佺期','quantangshi','','卷6','去岁投荒客，今春肆眚归。
律通幽谷暖，盆举太阳辉。
喜气迎冤气，青衣报白衣。
还将合浦叶，俱向洛城飞。','',''),('quantangshi-05080','秦州薛都督挽词','沈佺期','quantangshi','','卷6','十里绛山幽，千年汾水流。
碑传门客建，劒是故人留。
陇树烟含夕，山门月对秋。
古来钟鼎盛，共尽一蒿丘。','',''),('quantangshi-05081','天官崔侍郎夫人卢氏挽歌','沈佺期','quantangshi','','卷6','偕老言何谬，香魂事永违。
潘鱼从此隔，陈凤宛然飞。
埋镜泉中暗，藏镫地下微。
犹凭少君术，彷佛覩容辉。','',''),('quantangshi-05082','章怀太子靖妃挽词','沈佺期','quantangshi','','卷6','彤史佳声载，青宫懿范留。
形将鸾镜隐，魂伴凤笙游。
送马嘶残日，新萤落晚秋。
不知蒿里曙，空见陇云愁。','',''),('quantangshi-05083','奉和立春游苑迎春','沈佺期','quantangshi','','卷6','东郊暂转迎春仗，上苑初飞行庆杯。
风射蛟冰千片断，气冲鱼钥九关开。
林中觅草才生蕙，殿里争花并是梅。
歌吹衔恩归路晚，栖乌半下凤城来。','',''),('quantangshi-05084','人日重宴大明宫赐彩缕人胜应制','沈佺期','quantangshi','','卷6','拂旦鸡鸣仙衞陈，凭高龙首帝城春。
千官黼帐杯前寿，百福香匳胜里人。
山鸟初来犹怯啭，林花未发已偷新。
天文正应韶光转，设报悬知用此辰。','',''),('quantangshi-05085','奉和春初幸太平公主南庄应制','沈佺期','quantangshi','','卷6','主家山第早春归，御辇春游绕翠微。
买地铺金曾作埒，寻河取石旧支机。
云间树色千花满，竹里泉声百道飞。
自有神仙鸣凤曲，并将歌舞报恩晖。','',''),('quantangshi-05086','奉和春日幸望春宫应制','沈佺期','quantangshi','','卷6','芳郊绿野散春晴，复道离宫烟雾生。
杨柳千条花欲绽，蒲萄百丈蔓初萦。
林香酒气元相入，鸟啭歌声各自成。
定是风光牵宿醉，来晨复得幸昆明。','',''),('quantangshi-05087','侍宴安乐公主新宅应制','沈佺期','quantangshi','','卷6','皇家贵主好神仙，别业初开云汉边。
山出尽如鸣凤岭，池成不让饮龙川。
妆楼翠幌教春住，舞阁金铺借日悬。
敬从乘舆来此地，称觞献寿乐钧天。','',''),('quantangshi-05088','龙池篇','沈佺期','quantangshi','','卷6','龙池跃龙龙已飞，龙德先天天不违。
池开天汉分黄道，龙向天门入紫微。
邸第楼台多气色，君王凫雁有光辉。
为报寰中百川水，来朝此地莫东归。','',''),('quantangshi-05089','兴庆池侍宴应制','沈佺期','quantangshi','','卷6','碧水澄潭暎远空，紫云香驾御微风。
汉家城阙疑天上，秦地山川似镜中。
向浦回舟萍已绿，分林蔽殿槿初红。
古来徒羡横汾赏，今日宸游圣藻雄。','',''),('quantangshi-05090','从幸香山寺应制','沈佺期','quantangshi','','卷6','南山奕奕通丹禁，北阙峨峨连翠云。
岭上楼台千地起，城中钟鼓四天闻。
旃檀晓阁金舆度，鹦鹉晴林采眊分。
愿以醍醐参圣酒，还将[只]苑当秋汾。','',''),('quantangshi-05091','红楼院应制','沈佺期','quantangshi','','卷6','红楼疑见白毫光，寺逼宸居福盛唐。
支遁爱山情谩切，昙摩泛海路空长。
经声夜息闻天语，炉气晨飘接御香。
谁谓此中难可到，自怜深院得徊翔。','',''),('quantangshi-05092','再入道场纪事应制','沈佺期','quantangshi','','卷6','南方归去再生天，内殿今年异昔年。
见辟干坤新定位，看题日月更高悬。
行随香辇登仙路，坐近炉烟讲法筵。
自喜恩深陪侍从，两朝长在圣人前。','',''),('quantangshi-05093','嵩山石淙侍宴应制','沈佺期','quantangshi','','卷6','金舆旦下绿云衢，彩殿晴临碧涧隅。
溪水泠泠杂行漏，山烟片片绕香炉。
仙人六膳调神鼎，玉女三浆捧帝壶。
自惜汾阳纡道驾，无如太室览真图。','',''),('quantangshi-05094','古意呈补阙乔知之','沈佺期','quantangshi','','卷6','卢家少妇郁金堂，海燕双栖玳瑁梁。
九月寒砧催木叶，十年征戍忆辽阳。
白狼河北音书断，丹凤城南秋夜长。
谁谓含愁独不见，更教明月照流黄。','',''),('quantangshi-05095','遥同杜员外审言过岭','沈佺期','quantangshi','','卷6','天长地阔岭头分，去国离家见白云。
洛浦风光何所似，崇山瘴疠不堪闻。
南浮涨海人何处？北望衡阳雁几羣。','',''),('quantangshi-05096','和上巳连寒食有怀京洛','沈佺期','quantangshi','','卷6','天津御柳碧遥遥，轩骑相从半下朝。
行乐光辉寒食借，太平歌舞晚春饶。
红妆楼下东回辇，青草洲边南渡桥。
坐见司空扫西第，看君侍从落花朝。','',''),('quantangshi-05097','陪幸太平公主南庄诗','沈佺期','quantangshi','','卷6','主第山门起灞川，宸游风景入初年。
凤皇楼下交天仗，乌鹊桥头敞御筵。
往往花间逢彩石，时时竹里见红泉。
今朝扈跸平阳馆，不羡乘槎云汉边。','',''),('quantangshi-05098','守岁应制','沈佺期','quantangshi','','卷6','南渡轻冰解渭桥，东方树色起招摇。
天子迎春取今夜，王公献寿用明朝。
殿上灯人争烈火，宫中侲子乱驱妖。
宜将岁酒调神药，圣祚千春万国朝。','',''),('quantangshi-05099','陪幸韦嗣立山庄','沈佺期','quantangshi','','卷6','台阶好赤松，别业对青峯。
茆室承三顾，花源接九重。
虹旗萦秀木，凤辇拂疎筇。
迳直千官拥，溪长万骑容。
水堂开禹膳，山阁献尧钟。
皇鉴清居远，天文睿奖浓。
岩泉他夕梦，渔钓往年逢。
共荣丞相府，偏降逸人封。','',''),('quantangshi-05100','扈从出长安应制','沈佺期','quantangshi','','卷6','汉宅规模壮，周都景命隆。
西宾让东主，法驾幸天中。
太史占星应，春官奏日同。
旌门起长乐，帐殿出新丰。
翕习黄山下，纡徐清渭东。
金麾张画月，珠幰戴松风。
是节严阴始，寒郊散野蓬。
薄霜沾上路，残雪绕离宫。
赐帛矜耆老，褰旒问小童。
复除恩载洽，望秩礼新崇。
臣忝承明召，多慙献赋雄。','',''),('quantangshi-05101','初冬从幸汉故青门应制','沈佺期','quantangshi','','卷6','汉王建都邑，渭水对青门。
朝市俱东逝，坟陵共北原。
荒凉萧相阙，芜没邵平园。
全盛今何在，英雄难重论。
故基仍岳立，遗堞尚云屯。
当极土功壮，安知人力烦。
天游戒东首，怀昔驻龙轩。
何必金汤固，无如道德藩。
微臣谅多幸，参乘偶殊恩。
预此陈古事，敢奏兴亡言。','',''),('quantangshi-05102','昆明池侍宴应制','沈佺期','quantangshi','','卷6','武帝伐昆明，穿池习五兵。
水同河汉在，馆有豫章名。
我后光天德，垂衣文教成。
黩兵非帝念，劳物岂皇情。
春仗过鲸沼，云旗出凤城。
灵鱼衔宝跃，仙女废机迎。
柳拂旌门暗，兰依帐殿生。
还如流水曲，日晚棹歌清。','',''),('quantangshi-05103','白莲花亭侍宴应制','沈佺期','quantangshi','','卷6','九日陪天仗，三秋幸禁林。
霜威变绿树，云气落青岑。
水殿黄花合，山亭绛叶深。
朱旗夹小径，宝马驻清浔。
苑吏收寒果，饔人膳野禽。
承欢不觉暝，遥响素秋砧。','',''),('quantangshi-05104','仙萼池亭侍宴应制','沈佺期','quantangshi','','卷6','步辇寻丹嶂，行宫在翠微。
川长看鸟灭，谷转听猿稀。
天磴扶阶迥，云泉透户飞。
闲花开石竹，幽叶吐蔷薇。
径狭难留骑，亭寒欲进衣。
白龟来献寿，仙吹返彤闱。','',''),('quantangshi-05105','奉和晦日驾幸昆明池应制','沈佺期','quantangshi','','卷6','法驾乘春转，神池象汉廻。
双星移旧石，孤月隐残灰。
战鷁逢时去，恩鱼望幸来。
山花缇骑绕，堤柳幔城开。
思逸横汾唱，欢留宴镐杯。
微臣雕朽质，羞覩豫章材。','',''),('quantangshi-05106','奉和圣制幸礼部尚书窦希玠宅','沈佺期','quantangshi','','卷6','北阙垂旒暇，南宫听履廻。
天临翔凤转，恩向跃龙开。
兰气薰仙帐，榴花引御杯。
水从金穴吐，云是玉衣来。
池影摇歌席，林香散舞台。
不知行漏晚，清跸尚裴徊。','',''),('quantangshi-05107','钓竿篇','沈佺期','quantangshi','','卷6','朝日敛红烟，垂竿向绿川。
人疑天上坐，鱼似镜中悬。
避檝时惊透，猜钩每误牵。
湍危不理辖，潭静欲留船。
钓玉君徒尚，征金我未贤。
为看芳饵下，贪得会无筌。','',''),('quantangshi-05108','和户部岑尚书参迹枢揆','沈佺期','quantangshi','','卷6','大君制六合，良佐参万机。
大业永开泰，臣道日光辉。
盐梅和鼎食，家声众所归。
汉章题楚劒，郑武袭缁衣。
理识当朝远，文华振古希。
风云神契合，舟檝道心微。
庙堂喜容与，时物逓芳菲。
御柳垂仙掖，公槐覆礼闱。
昔陪鵷鹭后，今望鵾鹏飞。
徒御清风颂，巴歌聊自挥。','',''),('quantangshi-05109','同李舍人冬日集安乐公主山池','沈佺期','quantangshi','','卷6','尝闻天女贵，家即帝宫连。
亭插宜春果，山冲太液泉。
桥低乌鹊夜，台起凤皇年。
故事犹如此，新图更可怜。
紫岩妆阁透，青嶂妓楼悬。
峰夺香炉巧，池偷明镜圆。
梅花寒待雪，桂叶晚留烟。
兴尽方投辖，金声还复传。','',''),('quantangshi-05110','酬苏员外味道夏晚寓直省中见赠','沈佺期','quantangshi','','卷6','并命登仙阁，分曹直礼闱。
大官供宿膳，侍史护朝衣。
卷幔天河入，开窗月露微。
小池残暑退，高树早凉归。
冠劒无时释，轩车待漏飞。
明朝题汉柱，三署有光辉。','',''),('quantangshi-05111','和韦舍人早朝','沈佺期','quantangshi','','卷6','阊阖连云起，岩廊拂雾开。
玉珂龙影度，珠履雁行来。
长乐宵钟尽，明光晓奏催。
一经推旧德，五字擢英才。
俨若神仙去，纷从霄汉廻。
千春奉休历，分禁喜趋陪。','',''),('quantangshi-05112','自考功员外授给事中','沈佺期','quantangshi','','卷6','南省推丹地，东曹拜琐闱。
惠移双管笔，恩降五时衣。
出入宜真选，遭逢每滥飞。
器慙公理拙，才谢子云微。
案牍遗常礼，朋僚隔等威。
上台行揖让，中禁动光辉。
旭日千门起，初春八舍归。
赠兰闻宿昔，谈树隐芳菲。
何幸盐梅处，唯忧对问机。
省躬知任重，宁止冒荣非。','',''),('quantangshi-05113','和元舍人万顷临池翫月戏为新体','沈佺期','quantangshi','','卷6','春风摇碧树，秋雾卷丹台。
复有相宜夕，池清月正开。
玉流含吹动，金魄度云来。
熠爚光如沸，翩翾景若摧。
半环投积草，碎璧聚流杯。
夜久平无焕，天晴皎未颓。
镜将池作匣，珠以岸为胎。
有美司言暇，高兴独悠哉。
挥翰初难拟，飞名岂易陪。
夜光殊在握，了了见沈灰。','',''),('quantangshi-05114','酬杨给事兼见赠台中','沈佺期','quantangshi','','卷6','子云推辨博，公理擅词雄。
始自尚书省，旋闻给事中。
言从温室祕，籍向琐闱通。
顾我叨郎署，慙无草奏功。
分曹八舍断，解袂五时空。
宿昔陪余论，平生赖击蒙。
神仙应东掖，云雾限南宫。
忽枉琼瑶赠，长歌兰渚风。','',''),('quantangshi-05115','九真山净居寺谒无碍上人','沈佺期','quantangshi','','卷6','大士生天竺，分身化日南。
人中出烦恼，山下即伽蓝。
小涧香为刹，危峰石作龛。
候禅青鸽乳，窥讲白猿参。
藤爱云间壁，花怜石下潭。
泉行幽供好，林挂浴衣堪。
弟子哀无识，医王惜未谈。
机疑闻不二，蒙昧即朝三。
欲究因缘理，聊宽放弃慙。
超然虎溪夕，双树下虚岚。','',''),('quantangshi-05116','夜游','沈佺期','quantangshi','','卷6','今夕重门启，游春得夜芳。
月华连昼色，灯影杂星光。
南陌青丝骑，东邻红粉妆。
管弦遥辨曲，罗绮暗闻香。
人拥行歌路，车攒鬬舞场。
经过犹未已，钟鼓出长杨。','',''),('quantangshi-05117','登瀛州南城楼寄远','沈佺期','quantangshi','','卷6','层城起丽谯，凭览出重霄。
兹地多形胜，中天宛寂寥。
四荣摩鹳鹤，百拱厉风飙。
北际燕王馆，东连秦帝桥。
晴光七郡满，春色两河遥。
傲睨非吾土，踌躇适远嚣。
离居欲有赠，春草寄长谣。','',''),('quantangshi-05118','塞北二首 一','沈佺期','quantangshi','','卷6','虏障天骄起，秦城地脉分。
柏坛飞五将，梅吹动三军。
锋刃奔涛色，旌旗焰火文。
朔风吹汗漫，飘砾洒轒輼。
海气如秋雨，边烽似夏云。
二庭无岁月，百战有功勋。
形影随鱼贯，音书在雁羣。
归来拜天子，凯乐助南薰。','',''),('quantangshi-05119','塞北二首 二','沈佺期','quantangshi','','卷6','胡骑犯边埃，风从丑上来。
五原烽火急，六郡羽书催。
冰壮飞狐[冷]，霜浓候雁哀。
将军朝授钺，战士夜衔枚。
紫塞金河里，葱山铁勒隈。
莲花秋劒发，桂叶晓旗开。
秘略三军动，妖氛百战摧。
何言投笔去，终作勒铭回。','',''),('quantangshi-05120','李员外秦援宅观妓','沈佺期','quantangshi','','卷6','盈盈粉署郎，五日宴春光。
选客虚前馆，征声徧后堂。
玉钗翠羽饰，罗袖郁金香。
拂黛随时广，挑鬟出意长。
啭歌遥合态，度舞暗成行。
巧落梅庭里，斜光暎晓妆。','',''),('quantangshi-05121','送韦商州弼','沈佺期','quantangshi','','卷6','会府应文昌，商山镇国阳。
闻君监郡史，蹔罢尚书郎。
王事嗟相失，人情贵不忘。
累年同画省，四海接文场。
点翰芳春色，传杯明月光。
故交从此去，遥忆紫芝香。','',''),('quantangshi-05122','夏日梁王席送张岐州','沈佺期','quantangshi','','卷6','秦鸡常下雍，周凤昔鸣岐。
此地推雄抚，惟良寄在斯。
家传七豹贵，人擅八龙奇。
高传生光彩，长林叹别离。
天人开祖席，朝寀候征麾。
翠帟当郊敞，彤幨向野披。
芃芃秋麦盛，苒苒夏条垂。
奏计何时入？台阶望羽仪。','',''),('quantangshi-05123','夏日都门送司马员外逸客孙员外佺北征','沈佺期','quantangshi','','卷6','二庭追虏骑，六月动周师。
庙略天人授，军麾相国持。
复言征二妙，才命重当时。
画省连征橐，横门共别词。
云迎出塞马，风卷度河旗。
计日方夷寇，旋闻杕杜诗。','',''),('quantangshi-05124','送卢管记仙客北伐','沈佺期','quantangshi','','卷6','羽檄西北飞，交城日夜围。
庙堂盛征选，戎幕生光辉。
雁行度函谷，马首向金微。
湛湛山川暮，萧萧凉气稀。
饯途予悯默，赴敌子英威。
今日杨朱泪，无将洒铁衣。','',''),('quantangshi-05125','移禁司刑','沈佺期','quantangshi','','卷6','畴昔参乡赋，中年忝吏途。
丹唇曾学史，白首不成儒。
天子开昌箓，羣生偶大炉。
散材仍葺厦，弱羽遽[抟]扶。
宠迈乘轩鹤，荣过食稻凫。
何功游画省，何德理黄枢。
吊影慙非据，倾心事远图。
盗泉宁止渴，恶木匪投躯。
任直翻多毁，安身遂少徒。
一朝逢糺谬，三省竟无虞。
白简初心屈，黄纱始望孤。
患平终不怒，持劾每相驱。
埋劒谁当辨，偷金以自诬。
诱言虽委答，流议亦真符。
首夏方忧圄，高秋独向隅。
严城看熠耀，圜户对蜘蛛。
累饷唯妻子，披冤是友于。
物情牵倚伏，人事限荣枯。
门客心谁在，隣交迹倘无。
抚襟双涕落，危坐日忧趋。
圣旨垂明德，冤囚岂滥诛。
会希恩免理，终望罪矜愚。
司寇宜哀狱，台庭幸恤辜。
汉皇虚诏上，容有报恩珠。','',''),('quantangshi-05126','入鬼门关','沈佺期','quantangshi','','卷6','昔传瘴江路，今到鬼门关。
土地无人老，流移几客还。
自从别京洛，颓鬓与衰颜。
夕宿含沙里，晨行冈路间。
马危千仞谷，舟险万重湾。
问我投何地？西南尽百蛮。','',''),('quantangshi-05127','三日独坐驩州思忆旧游','沈佺期','quantangshi','','卷6','两京多节物，三日最遨游。
丽日风徐卷，香尘雨暂收。
红桃初下地，绿柳半垂沟。
童子成春服，宫人罢射鞲。
禊堂通汉苑，解席绕秦楼。
束皙言谈妙，张华史汉遒。
无亭不驻马，何浦不横舟。
舞龠千门度，帷屏百道流。
金丸向鸟落，芳饵接鱼投。
濯秽怜清浅，迎祥乐献酬。
灵刍陈欲弃，神药曝应休。
谁念招魂节，翻为御魅囚。
朋从天外尽，心赏日南求。
铜柱威丹徼，朱崖镇火陬。
炎蒸连晓夕，瘴疠满冬秋。
西水何时贷？南方讵可留。
无人对炉酒，宁缓去乡忧。','',''),('quantangshi-05128','从驩州廨宅移住山间水亭赠苏使君','沈佺期','quantangshi','','卷6','遇坎即乘流，西南到火洲。
鬼门应苦夜，瘴浦不宜秋。
岁贷胸穿老，朝飞鼻饮头。
死生离骨肉，荣辱间朋游。
弃置一身在，平生万事休。
鹰鹯遭误逐，豺虎怯真投。
忆昨京华子，伤今边地囚。
愿陪鹦鹉乐，希并鹧鸪留。
日月渝乡思，烟花换客愁。
幸逢苏伯玉，回借水亭幽。
山柏张青盖，江蕉卷绿油。
乘闲无火宅，因放有渔舟。
适越心当是，居夷迹可求。
古来尧禅舜，何必罪驩兜。','',''),('quantangshi-05129','赦到不得归题江上石','沈佺期','quantangshi','','卷6','家住东京里，身投南海西。
风烟万里隔，朝夕几行啼。
圣主讴歌洽，贤臣法令齐。
忽闻铜柱使，走马报金鸡。
弃市沾皇渥，投荒漏紫泥。
魂疲山鹤路，心醉[跕]鸢溪。
天鉴诛元恶，宸慈恤远黎。
五方思寄刃，万姓喜然脐。
自幼输丹恳，何尝玷白圭。
承言窜遐魅，雪枉间深狴。
坟壠无由谒，京华岂重跻。
炎方谁谓广，地尽觉天低。
百卉杂殊怪，昆虫理赖暌。
闭藏元不蛰，摇落反生荑。
疟瘴因兹苦，穷愁益复迷。
火云蒸毒雾，阳雨濯阴霓。
周乘安交趾，王恭辑画题。
少宽穷涸鲋，犹愍触藩羝。
配宅隣州廨，斑苗接野畦。
山空闻鬬象，江静见游犀。
翰墨思诸季，裁缝忆老妻。
小儿应离褓，幼女未攀筓。
梦蝶翻无定，蓍龟讵有倪。
谁能竟此曲，曲尽气酸嘶。','',''),('quantangshi-05130','答魑魅代书寄家人','沈佺期','quantangshi','','卷6','魑魅来相问，君何失帝乡。
龙钟辞北阙，蹭蹬守南荒。
览镜怜双鬓，沾衣惜万行。
抱愁那去国，将老更垂裳。
影答余他岁，恩私宦洛阳。
三春给事省，五载尚书郎。
黄合游鸾署，青缣御史香。
扈巡行太液，陪宴坐明光。
渭北升高苑，河南祓禊场。
烟花恒献赋，泉石每称觞。
暇日从休澣，高车暎道傍。
迎宾就丞相，选士谒昭王。
侍宠言犹得，承欢谓不忘。
一朝贻厚谴，五宅竟同防。
凶竖曾躯策，权豪岂易当。
款颜因侍从，接武在文章。
且惧威非贙，宁知心是狼。
身犹纳履误，情为覆盆伤。
可叹缘成业，非关行昧藏。
喜逢今改旦，正朔复归唐。
河谶随龙马，天书逐凤皇。
朝容欣旧则，宸化美初纲。
告善雕旌建，收冤锦斾张。
宰臣更献纳，郡守各明扬。
礼乐移三统，舟车会八方。
云沙降白遂，秦陇献烧当。
三赦重天造，千推极国详。
大招思复楚，于役限维桑。
涨海缘真腊，崇山压古棠。
雕题飞栋宇，儋耳间衣裳。
伏枕神余劣，加餐力未强。
空庭游翡翠，穷巷倚桄榔。
缘体分殊昔，回眸宛异常。
吉凶恒委郑，年寿会询唐。
家本传清白，官移重挂牀。
上京无薄产，故里绝穷庄。
碧玉先时费，苍头此自将。
兴言叹家口，何处待赢粮？
计吏从都出，传闻大小康。
降除沾二弟，离拆已三房。
劒外悬销骨，荆南预断肠。
音尘黄耳间，梦想白眉良。
复此单栖鹤，衔雏愿远翔。
何堪万里外，云海已溟茫。
戚属甘胡越，声名任粃糠。
由来休愤命，命也信苍苍。
独坐寻周易，清晨咏老庄。
此中因悟道，无问入猖狂。','',''),('quantangshi-05131','度安海入龙编','沈佺期','quantangshi','','卷6','我来交趾郡，南与贯胸连。
四气分寒少，三光置日偏。
尉佗曾驭国，翁仲久游泉。
邑屋遗甿在，鱼盐旧产传。
越人遥捧翟，汉将下看鸢。
北斗崇山挂，南风涨海牵。
别离频破月，容鬓骤催年。
昆弟推由命，妻孥割付缘。
梦来魂尚扰，愁委疾空缠。
虚道崩城泪，明心不应天。','',''),('quantangshi-05132','从崇山向越常','沈佺期','quantangshi','','卷6','朝发崇山下，暮坐越常阴。
西从杉谷度，北上竹溪深。
竹溪道明水，杉谷古崇岑。
差池将不合，缭绕复相寻。
桂叶藏金屿，藤花闭石林。
天窗虚的的，云窦下沈沈。
造化功偏厚，真仙迹每临。
岂徒探怪异，聊欲缓归心。','',''),('quantangshi-05133','哭苏眉州崔司业二公','沈佺期','quantangshi','','卷6','涣汗天中发，伶俜海外旋。
长沙遇太守，问旧几人全。
国宝亡双杰，天才丧两贤。
大名齐弱岁，高德并中年。
礼乐羊叔子，文章王仲宣。
相看尚玄鬓，相次入黄泉。
流放蛮陬阔，乡关帝里偏。
亲朋云雾拥，生死岁时传。
崔昔挥宸翰，苏尝济巨川。
绛衣陪下列，黄合谬差肩。
及此俱冥昧，云谁叙播迁。
隼舆怀旧辙，鳣馆想虚筵。
家爱方休杵，皇慈更撤县。
铭旌西蜀路，骑吹北邙田。
陇树应秋矣，江帆故杳然。
罢琴明月夜，留劒白云天。
涕泗湘潭水，凄凉衡峤烟。
古来修短分，神理竟难筌。','',''),('quantangshi-05134','哭道土刘无得','沈佺期','quantangshi','','卷6','闻有玄都客，成仙不易祈。
蓬莱向清浅，桃杏欲芳菲。
缩地黄泉出，升天白日飞。
少微星夜落，高掌露朝曦。
吐甲龙应出，衔符鸟自归。
国人思负局，天子惜被衣。
花月留丹洞，琴笙阁翠微。
嗟来子桑扈，尔独返于几。','',''),('quantangshi-05135','寒食','沈佺期','quantangshi','','卷6','普天皆灭焰，匝地尽藏烟。
不知何处火？来就客心然。','',''),('quantangshi-05136','回波词','沈佺期','quantangshi','','卷6','回波尔时佺期，流向岭外生归。
身名已蒙齿录，袍笏未复牙绯。','',''),('quantangshi-05137','上巳日祓禊渭滨应制','沈佺期','quantangshi','','卷6','宝马香车清渭滨，红桃碧柳禊堂春。
皇情尚忆垂竿佐，天祚先呈捧劒人。','',''),('quantangshi-05138','奉和幸韦嗣立山庄应制','沈佺期','quantangshi','','卷6','东山朝日翠屏开，北阙晴空彩仗来。
喜遇天文七曜动，少微今夜近三台。','',''),('quantangshi-05139','夜宴安乐公主宅','沈佺期','quantangshi','','卷6','濯龙门外主家亲，鸣凤楼中天上人。
自有金杯迎甲夜，还将绮席代阳春。','',''),('quantangshi-05140','苑中遇雪应制','沈佺期','quantangshi','','卷6','北阙彤云掩曙霞，东风吹雪舞仙家。
琼章定少千人和，银树长芳六出花。','',''),('quantangshi-05141','饯唐永昌','沈佺期','quantangshi','','卷6','洛阳旧有神明宰，辇毂由来天地中。
余邑政成何足贵，因君取则四方同。','',''),('quantangshi-05142','狱中闻驾幸长安二首 一','沈佺期','quantangshi','','卷6','传闻圣旨向秦京，谁念羁囚滞洛城。
扈从由来是方朔，为申冤气在长平。','',''),('quantangshi-05143','狱中闻驾幸长安二首 二','沈佺期','quantangshi','','卷6','无事今朝来下狱，谁期十月是横河。
君看鹰隼俱堪击，为报蜘蛛收网罗。','',''),('quantangshi-05144','邙山','沈佺期','quantangshi','','卷6','北邙山上列坟茔，万古千秋对洛城。
城中日夕歌钟起，山上唯闻松栢声。','',''),('quantangshi-05145','句','沈佺期','quantangshi','','卷6','周原五稼起，云海百川归。
愿此零陵燕，长随征斾飞。','',''),('quantangshi-05146','陪张燕公登南楼','趙冬曦','quantangshi','','卷6','抑郁何以欢，阴氛亦登望。
孤岛轻雾里，行舟白波上。
目劳西北云，心醉东南嶂。
昔日青溪子，胡然此无状。','',''),('quantangshi-05147','酬燕公出湖见寄','趙冬曦','quantangshi','','卷6','纶綍有成命，旌麾不可攀。
湘川朝目断，荆阙夕波还。
果枉东瞻唱，兴言夕放闲。
携琴仙洞中，置酒㴩湖上。
芳景恣行乐，谪居忽如忘。
聚散本相因，离情自悲怅。
鸾翮非常戢，鹏天会昭旷。
永怀宛洛游，曾是弹冠望。','',''),('quantangshi-05148','奉和张燕公早霁南楼','趙冬曦','quantangshi','','卷6','方曙跻南楼，凭轩肆遐瞩。
物华荡暄气，春景媚晴旭。
川霁湘山孤，林芳楚郊缛。
列岩重叠翠，远岸逶迤绿。
风帆摩天垠，鱼艇散弯曲。
鸿归鹤舞送，猨叫莺声续。
羣动皆熙熙，噫予独羁束。
常钦才子意，忌鵩伤蜷局。
雅尚骚人文，怀沙何迫促。
未知二贤意，去矣从所欲。','',''),('quantangshi-05149','㴩湖作','趙冬曦','quantangshi','','卷6','三湖返入两山间，畜作㴩湖弯复弯。
暑雨奔流潭正满，微霜及潦水初还。
水还波卷溪潭涸，绿草芊芊岸崭岝。
适来飞棹共回旋，已复扬鞭恣行乐。
道旁耆老步跹跹，楚言兹事不知年。
试就湖边披草径，莫疑东海变桑田。
君讶今时尽陵陆，我看明岁更沦涟。
来今自昔无终始，人事回环常若是。
应思阙下声华日，谁谓江潭旅游子。
初贞正喜固当然，往蹇来誉宜可俟。
盈虚用舍轮舆旋，勿学灵均远问天。','',''),('quantangshi-05150','和燕公岳州山城','趙冬曦','quantangshi','','卷6','为吏恩犹旧，投沙惠此蒙。
江边悠尔处，泗上宛然同。
访道精言合，论经大义通。
鸣琴有真气，况已沐清风。','',''),('quantangshi-05151','和尹懋秋夜游㴩湖二首 一','趙冬曦','quantangshi','','卷6','政理常多暇，方舟此溯洄。
吹笙虚洞答，举楫便风催。
山暗云犹辨，潭幽月稍来。
清溪无数曲，未尽莫先回。','',''),('quantangshi-05152','和尹懋秋夜游㴩湖二首 二','趙冬曦','quantangshi','','卷6','烟霭夕微蒙，幽湾赏未穷。
舣舟待初月，褰幌招远风。
鹤声聒前浦，渔火明暗丛。
东山云壑意，不谓尔来同。','',''),('quantangshi-05153','陪燕公游㴩湖','趙冬曦','quantangshi','','卷6','江上多山水，招要步马来。
琴将天籁合，酒共鸟声催。
岩坐攀红药，溪行爱绿苔。
所怀非此地，游望亦裴回。','',''),('quantangshi-05154','答张燕公翻着葛巾见呈之作','趙冬曦','quantangshi','','卷6','美酒值芳春，醒余气益真。
降欢时倒履，乘兴偶翻巾。
徐榻思方建，左车理自均。
傲然歌一曲，一醉濯缨人。','',''),('quantangshi-05155','奉答燕公','趙冬曦','quantangshi','','卷6','语别意凄凄，零陵湘水西。
佳人金谷返，爱子洞庭迷。
旧馆逢花发，他山值鸟啼。
江天千里望，谁见绿苹齐。','',''),('quantangshi-05156','奉和圣制同二相已下羣官乐游园宴','趙冬曦','quantangshi','','卷6','爽垲三秦地，芳华二月初。
酺承奠璧罢，宴是合钱余。
柳翠垂堪结，桃红卷欲舒。
从容会鵷鹭，延曼戏龙鱼。
喜气流云物，欢声浃里闾。
圣恩将报厚，请述记言书。','',''),('quantangshi-05157','奉和圣制答张说扈从南出雀鼠谷','趙冬曦','quantangshi','','卷6','轩辕应顺动，力牧正趋陪。
道合殷为砺，时行楚有材。
省方西礼设，振旅北京回。
地理分中壤，天文照上台。
寒依汾谷去，春入晋郊来。
窃比康衢者，长歌仰大哉。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-05158','奉和圣制送张说上集贤学士赐宴赋得莲字','趙冬曦','quantangshi','','卷6','浅术方观海，深恩忽见天。
学开丹殿籍，名与石渠贤。
良辅膺休命，微生谬采甄。
春余仍哢鸟，夏近未舒莲。
牋札来宸禁，衣冠集诏筵。
史臣知醉德，欲记升中年。','',''),('quantangshi-05159','奉答燕公','趙冬曦','quantangshi','','卷6','谁道零陵守，东过此地游。
友僚同省阁，昆弟接荆州。
我逐江潭雁，君随海上鸥。
屡伤神气阻，久别鬓毛秋。
疑岭春应徧，阳台雨欲收。
主人情未尽，高驾少淹留。','',''),('quantangshi-05160','陪张燕公行郡竹篱','趙冬曦','quantangshi','','卷6','良臣乃国宝，麾守去承明。
外户人无闭，浮江兽已行。
随来晋盗逸，民化蜀风清。
郛郭从彝典，州闾荷德声。
小人投天涯，流落巴丘城。
所赖中和作，优游凿与耕。','',''),('quantangshi-05161','和燕公别㴩湖','趙冬曦','quantangshi','','卷6','南湖美泉石，君子翫幽奇。
湾澳陪临泛，岩峿共践窥。
秋风赬桂竦，春景绿杨垂。
郢路委分竹，湘滨拥去麾。
枉帆怀胜赏，留景惜差池。
水木且不弃，情由良可知。','',''),('quantangshi-05162','奉酬燕公见归田赋垂赠之作','趙冬曦','quantangshi','','卷6','穷鸟婴笼缀，孤飞任播迁。
鹪鹩王佐用，复此挫冲天。
楚云何掩郁，湘水亦回邅。
怀哉愧木雁，忽尔枉兰荃。
愈疾同枚叔，销忧比仲宣。
归途书可畏，弱操石犹坚。
覆载虽云广，涔阳直块然。','',''),('quantangshi-05163','和张燕公耗磨日饮 一','趙冬曦','quantangshi','','卷6','上月今朝减，流传耗磨辰。
还将不事事，同醉俗中人。','',''),('quantangshi-05164','和张燕公耗磨日饮 二','趙冬曦','quantangshi','','卷6','春来半月度，俗忌一朝闲。
不酌他乡酒，无堪对楚山。','',''),('quantangshi-05165','奉陪张燕公登南楼','尹懋','quantangshi','','卷6','君子每垂眷，江山共流眄。
水远林外明，岩近雾中见。
终日西北望，何处是京县。
屡登高春台，徒使泪如霰。','',''),('quantangshi-05166','秋夜陪张丞相赵侍御游㴩湖二首 一','尹懋','quantangshi','','卷6','熊轼巴陵地，鷁舟湘水浔。
江山与势远，泉石自幽深。
杳霭入天壑，冥茫见道心。
超然无俗事，清宴有空林。','',''),('quantangshi-05167','秋夜陪张丞相赵侍御游㴩湖二首 二','尹懋','quantangshi','','卷6','江上饶奇山，巑罗云水间。
风和树色杂，苔古石文斑。
巴俗将千溠，㴩湖凡几湾。
嬉游竟不尽，乘月泛舟还。','',''),('quantangshi-05168','同燕公泛洞庭','尹懋','quantangshi','','卷6','风光淅淅草中飘，日彩荧荧水上摇。
幸奏潇湘云壑意，山旁容与动仙桡。','',''),('quantangshi-05169','奉答燕公','王琚','quantangshi','','卷6','郡远途且艰，宜悲良自得。
胡为心独尔，惠好在南国。
亦既清颜披，冏然良愿克。
与君兰时会，羣物如藻饰。
烟景惜欢赏，云山起翰墨。
接艺奇思微，偶谈玄言直。
永日不知倦，逾旬犹谓亟。
如何酌离尊，移棹巴城侧。
浦口劳长望，舟中独太息。
疾风吹飞帆，倏忽南与北。
目尽不复见，怀哉无终极。
唯当衡峰上，遥辨湖水色。','',''),('quantangshi-05170','美女篇','王琚','quantangshi','','卷6','东邻美女实名倡，绝代容华无比方。
浓纤得中非短长，红素天生谁饰妆。
桂楼椒阁木兰堂，绣户雕轩文杏梁。
屈曲屏风绕象牀，萎蕤翠帐缀香囊。
玉台龙镜洞彻光，金炉沈烟酷烈芳。
遥闻行佩音锵锵，含娇欲笑出洞房。
二八三五闺心切，褰帘卷幔迎春节。
清歌始发词怨咽，鸣琴一弄心断绝。
借问哀怨何所为，盛年情多心自悲。
须臾破颜倏敛态，一悲一喜倂相宜。
何能见此不注心，惜无媒氏为传音。
可怜盈盈直千金，谁家君子为藁砧。','',''),('quantangshi-05171','自荆湖入朝至岳阳奉别张燕公','王琚','quantangshi','','卷6','五载朝天子，三湘逢旧僚。
扁舟方辍棹，清论遂终朝。
远树烟间没，长江地际遥。
帝城驰梦想，归帆满风飙。','',''),('quantangshi-05172','游㴩湖上寺','王琚','quantangshi','','卷6','春山临远壑，水木自幽清。
夙昔怀微尚，兹焉一放情。
云间听弄鸟，烟上摘初英。
地僻方无闷，逾知道思精。','',''),('quantangshi-05173','和张燕公湘中九日登高','陰行先','quantangshi','','卷6','重阳初启节，无射正飞灰。
寂寞风蝉至，连翩霜雁来。
山棠红叶下，岸菊紫花开。
今日桓公座，多愧孟嘉才。','',''),('quantangshi-05174','奉别张岳州说二首 一','王熊','quantangshi','','卷6','长沙辞旧国，洞庭逢故人。
薰兰敦久要，披雾转相亲。
岁月空嗟老，江山不惜春。
忽闻黄鹤曲，更作白头新。','',''),('quantangshi-05175','奉别张岳州说二首 二','王熊','quantangshi','','卷6','平生共风月，倏忽间山川。
不期交淡水，暂得欵忘年。
兴逸方罢钓，帆开欲解船。
离心若危斾，朝夕为君悬。','',''),('quantangshi-05176','入朝别张燕公','梁知微','quantangshi','','卷6','华容佳山水，之子厌承明。
符竹纡小郡，江湖被德声。
三年计吏入，路指巴丘城。
凫舟才结缆，驺驾已相迎。
别离他乡酒，委曲故人情。
孤屿早烟薄，长波晚气清。
辛勤方远骛，胜赏屡难并。
回瞻洞庭浦，日暮愁云生。','',''),('quantangshi-05177','桐竹赠张燕公','李伯魚','quantangshi','','卷6','北竹青桐北，南桐绿竹南。
竹林君早爱，桐树我初贪。
凤栖桐不愧，凤食竹何慙。
栖食更如此，余非凤所堪。','',''),('quantangshi-05178','正朝上左相张燕公','楊重玄','quantangshi','','卷6','岁去愁终在，春还命不来。
长吁问丞相，东阁几时开。','',''),('quantangshi-05179','道峡似巫山','朱使欣','quantangshi','','卷6','江如晓天静，石似暮云张。
征帆一流览，宛若巫山阳。
楚客思归路，秦人谪异乡。
猨鸣孤月夜，再使泪霑裳。','',''),('quantangshi-05180','巫山高','張循之','quantangshi','','卷6','巫山高不极，合沓状奇新。
暗谷疑风雨，阴崖若鬼神。
月明三峡晓，潮满九江春。
为问阳台客，应知入梦人。','',''),('quantangshi-05181','送泉州李使君之任','張循之','quantangshi','','卷6','傍海皆荒服，分符重汉臣。
云山百越路，市井十洲人。
执玉来朝远，还珠入贡频。
连年不见雪，到处即行春。','',''),('quantangshi-05182','长门怨','張循之','quantangshi','','卷6','长门落景尽，洞房秋月明。
玉阶草露积，金屋网尘生。
妾妬今应改，君恩惜未平。
寄语临邛客，何时作赋成。','',''),('quantangshi-05183','巫山','張循之','quantangshi','','卷6','流景一何速，年华不可追。
解佩安所赠，怨咽空自悲。','',''),('quantangshi-05184','送王汶宰江阴','張循之','quantangshi','','卷6','郡北乘流去，花间竟日行。
海鱼朝满市，江鸟夜喧城。
让酒非关病，援琴不在声。
应缘五斗米，数日滞渊明。','',''),('quantangshi-05185','婺州留别邓使君','張循之','quantangshi','','卷6','西掖驰名久，东阳出守时。
江山婺女分，风月隐侯诗。
别恨双溪急，留欢五马迟。
回舟暎沙屿，未远剩相思。','',''),('quantangshi-05186','祭汾阴乐章 太和','王晙','quantangshi','','卷6','于穆圣皇，六叶重光。
太原刻颂，后土疏场。
宝鼎呈符，歊云孕祥。
礼乐备矣，降福穰穰。','',''),('quantangshi-05187','大堤曲','張柬之','quantangshi','','卷6','南国多佳人，莫若大堤女。
玉牀翠羽帐，宝袜莲花距。
魂处自目成，色授开心许。
迢迢不可见，日暮空愁予。','',''),('quantangshi-05188','东飞伯劳歌','張柬之','quantangshi','','卷6','青田白鹤丹山凤，婺女姮娥两相送。
谁家绝世绮帐前，艳粉红脂映宝钿。
窈窕玉堂褰翠幙，参差绣户悬珠箔。
绝世三五爱红妆，冶袖长裙兰麝香。
春去花枝俄易改，可叹年光不相待。','',''),('quantangshi-05189','出塞','張柬之','quantangshi','','卷6','侠客重恩光，骢马饰金装。
瞥闻传羽檄，驰突救边荒。
歙野山川动，嚣天旌斾扬。
吴钩明似月，楚劒利如霜。
电断冲胡塞，风飞出洛阳。
转战磨笄俗，横行戴斗乡。
手擒郅支长，面缚谷蠡王。
将军占太白，小妇怨流黄。
騕褭青丝骑，娉婷红粉妆。
三春莺度曲，八月雁成行。
谁堪坐愁思，罗袖拂空牀。','',''),('quantangshi-05190','与国贤良夜歌二首 一','張柬之','quantangshi','','卷6','柳台临新堰，楼堞相重复。
窈窕凤皇姝，倾城复倾国。','',''),('quantangshi-05191','与国贤良夜歌二首 二','張柬之','quantangshi','','卷6','杏间花照灼，楼上月裴回。
带娇移玉柱，含笑捧金杯。','',''),('quantangshi-05192','咏屏风','袁恕己','quantangshi','','卷6','绮阁云霞满，芳林草树新。
鸟惊疑欲曙，花笑不关春。
山对弹琴客，溪留垂钓人。
请看车马客，行处有风尘。','',''),('quantangshi-05193','书怀','劉幽求','quantangshi','','卷6','心为明时尽，君门尚不容。
田园迷径路，归去欲何从。','',''),('quantangshi-05194','流所赠张锡','章玄同','quantangshi','','卷6','黄叶因风下，甘从洛浦隈。
白云何所为，还出帝乡来。','',''),('quantangshi-05195','临高台','王易從','quantangshi','','卷6','汉主事[祁]连，良人在高阙。
空台寂已暮，愁坐变容髪。
泛艳春幌风，裴回秋户月。
可怜军书断，空使流芳歇。','',''),('quantangshi-05196','初出京邑有怀旧林','盧僎','quantangshi','','卷6','赋生期独得，素业守微班。
外忝文学知，鸿渐鵷鹭间。
内倾水木趣，筑室依近山。
晨趋天日[晏]，夕卧江海闲。
松风生坐隅，仙禽舞亭湾。
曙云林下客，霁月池上颜。
虽曰坐郊园，静默非人寰。
时步苍龙阙，宁异白云关。
语济岂时顾，默善忘世攀。
世网余何触，天涯谪南蛮。
回首思洛阳，喟然悲贞艰。','',''),('quantangshi-05197','稍秋晓坐阁遇舟东下扬州既事寄上族父江阳令','盧僎','quantangshi','','卷6','虎啸山城晚，猨鸣江树秋。
红林架落照，青峡送归流。
归流赴淮海，征帆下扬州。
族父江阳令，盛业继前修。
文掩崔亭伯，德齐陈太丘。
时哉惜未与，千载且为俦。
忆昔山阳会，长怀东上游。
称觞阮林下，赋雪谢庭幽。
道浓礼自略，气舒文转遒。
高情薄云汉，酣态坐芳洲。
接席复连轸，出入陪华輈。
独善与兼济，语默奉良筹。
岁月欢无已，风雨暗飕飕。
掌宪时持节，为邦邈海头。
子人惠虽树，苍生望且留。
微躬趋直道，神甸忝清猷。
仙台适西步，蛮徼忽南浮。
宇内皆安乐，天涯独远投。
忠信徒坚仗，神明岂默酬。
观生海漫漫，稽命天悠悠。
云昏巴子峡，月远吴王楼。
怀昔明不寐，悲令岁属周。
喟无排云翮，暂得抒离忧。
空洒霑红泪，万里逐行舟。','',''),('quantangshi-05198','让帝挽歌词二首 一','盧僎','quantangshi','','卷6','泰伯玄风远，延州德让行。
阖棺追大节，树羽册鸿名。
地户迎天仗，皇阶失帝兄。
还闻汉明主，遗劒泣东平。','',''),('quantangshi-05199','让帝挽歌词二首 二','盧僎','quantangshi','','卷6','朝天驰马绝，册帝□宫祖。
恍惚陵庙新，萧条池馆古。
万化一朝空，哀乐此路同。
西园有明月，修竹韵悲风。','',''),('quantangshi-05200','十月梅花书赠','盧僎','quantangshi','','卷6','君不见巴乡气候与华别，年年十月梅花发。
上苑今应雪作花，宁知此地花为雪。
自从迁播落黔巴，三见江上开新花。
故园风花虚洛汭，穷峡凝雪度岁华。
花情纵似河阳好，客心倍伤边候早。
春候飒惊楼上梅，霜威未落江潭草。
江水侵天去不还，楼花覆帘空坐攀。
一向花前看白发，几回梦里忆红颜。
红颜白发云泥改，何异桑田移碧海。
却想华年故国时，唯余一片空心在。
空心吊影向谁陈，云台仙阁旧游人。
傥知巴树连冬发，应怜南国气长春。','',''),('quantangshi-05201','岁晚还京台望城阙成口号先赠交亲','盧僎','quantangshi','','卷6','紫陌开行树，朱城出晚霞。
犹怜惯去国，疑是梦还家。
风弱知催柳，林青觉待花。
交亲望归骑，几处拥年华。','',''),('quantangshi-05202','送苏八给事出牧徐州用芳韵','盧僎','quantangshi','','卷6','金鼎属元方，璅闱连季常。
畏盈聊出守，分命乃维良。
晓骑辞朝远，春帆向楚常。
贤哉谦自牧，天下咏余芳。','',''),('quantangshi-05203','上幸皇太子新院应制','盧僎','quantangshi','','卷6','佳气晓葱葱，干行入震宫。
前星移北极，少海被南风。
视膳铜楼下，吹笙玉座中。
训深家以正，义举俗为公。
父子成钊合，君臣禹启同。
仰天歌圣道，犹愧乏雕虫。','',''),('quantangshi-05204','奉和李令扈从温泉宫赐游骊山韦侍郎别业','盧僎','quantangshi','','卷6','风后轩皇佐，云峰谢客居。
承恩来翠岭，缔赏出丹除。
飞盖松溪寂，清笳玉洞虚。
窥岩详雾豹，过水略泉鱼。
乡入无何有，时还上古初。
伊臯羞过狭，魏丙服麤疎。
白雪缘情降，青霞落卷舒。
多惭郎署在，輙继国风余。','',''),('quantangshi-05205','季冬送户部郎中使黔府选补','盧僎','quantangshi','','卷6','握镜均荒服，分衡得大同。
征贤一台上，补吏五溪中。
雨露将天泽，文章播国风。
汉庭睽直谅，楚峡望清通。
马逐霜鸿渐，帆沿晓月空。
还期凤池拜，照耀列星宫。','',''),('quantangshi-05206','途中口号','盧僎','quantangshi','','卷6','抱玉三朝楚，怀书十上秦。
年年洛阳陌，花鸟弄归人。','',''),('quantangshi-05207','南望楼','盧僎','quantangshi','','卷6','去国三巴远，登楼万里春。
伤心江上客，不是故乡人。','',''),('quantangshi-05208','临川送别','盧僎','quantangshi','','卷6','秋郊日半隐，野树烟初映。
风水正萧条，那堪动离咏。','',''),('quantangshi-05209','题殿前桂叶','盧僎','quantangshi','','卷6','桂树生南海，芳香隔楚山。
今朝天上见，疑是月中攀。','',''),('quantangshi-05210','奉和受图温洛应制','牛鳳及','quantangshi','','卷6','八神扶玉辇，六羽警瑶溪。
戒道伊川北，通津涧水西。
御图开洛匮，刻石与天齐。
瑞日波中上，仙禽雾里低。
微臣矫羽翮，拚舞接鸾鹥。','',''),('quantangshi-05211','雅琴篇','司馬逸客','quantangshi','','卷6','亭亭峄阳树，落落千万寻。
独抱出云节，孤生不作林。
影摇绿波水，彩绚丹霞岑。
直干思有托，雅志期所任。
匠者果留盼，雕斵为雅琴。
文以楚山玉，错以昆吾金。
虬凤吐奇状，商征含清音。
清音雅调感君子，一抚一弄怀知己。
不知钟期百年余，还忆朝朝几千里。
马卿台上应芜没，阮籍帷前空已矣。
山情水意君不知，拂匣调弦为谁理。
调弦拂匣倍含情，况复空山秋月明。
陇水悲风已呜咽，离鵾别鹤更凄清。
将军塞外多奇操，中散林间有正声。
正声谐风雅，欲竟此曲谁知者。
自言幽隐乏先容，不道人物知音寡。
谁能一奏和天地，谁能再抚欢朝野。
朝野欢娱乐未央，车马骈阗盛彩章。
岁岁汾川事箫鼓，朝朝伊水听笙簧。
窈窕楼台临上路，妖娆歌舞出平阳。
弹弦本自称仁祖，吹管由来许季长。
犹怜雅歌淡无味，渌水白云谁相贵。
还将逸词赏幽心，不觉繁声论远意。
传闻帝乐奏钧天，傥冀微躬备五弦。
愿持东武宫商韵，长奉南熏亿万年。','',''),('quantangshi-05212','三妇艳','王紹宗','quantangshi','','卷6','大妇能调瑟，中妇咏新诗。
小妇独无事，花庭曳履綦。
上客且安坐，春日正迟迟。','',''),('quantangshi-05213','别离怨','鄭遂初','quantangshi','','卷6','荡子戍辽东，连年信不通。
尘生锦步障，花送玉屏风。
只怨红颜改，宁辞玉簟空。
系书春雁足，早晚到云中。','',''),('quantangshi-05214','寒食','李崇嗣','quantangshi','','卷6','普天皆灭焰，匝地尽藏烟。
不知何处火？来就客心然。','',''),('quantangshi-05215','览镜','李崇嗣','quantangshi','','卷6','岁去红颜尽，愁来白发新。
今朝开镜匣，疑是别逢人。','',''),('quantangshi-05216','独愁','李崇嗣','quantangshi','','卷6','闻道成都酒，无钱亦可求。
不知将几斗，销得此来愁。','',''),('quantangshi-05217','昭君怨三首 一','東方虬','quantangshi','','卷6','汉道方全盛，朝廷足武臣。
何须薄命妾，辛苦事和亲。','',''),('quantangshi-05218','昭君怨三首 二','東方虬','quantangshi','','卷6','揜泪辞丹凤，衔悲向白龙。
单于浪惊喜，无复旧时容。','',''),('quantangshi-05219','昭君怨三首 三','東方虬','quantangshi','','卷6','胡地无花草，春来不似春。
自然衣带缓，非是为腰身。','',''),('quantangshi-05220','春雪','東方虬','quantangshi','','卷6','春雪满空来，触处似花开。
不知园里树，若个是真梅。','',''),('quantangshi-05221','逸人歌赠李山人','張楚金','quantangshi','','卷6','上有尧兮下有田，眠松阳兮漱颍流。
其貌古，其心幽，浩歌一曲兮林壑秋。
道险可惊兮人莫用，乐天知命兮守岩洞。
时击磬兮嗟鸣凤，吾欲知往古之不可追，自悠悠于凡梦。','',''),('quantangshi-05222','谪南海过始兴广胜寺果上人房','房融','quantangshi','','卷6','零落嗟残命，萧条托胜因。
方烧三界火，遽洗六情尘。
隔岭天花发，凌空月殿新。
谁令乡国梦，终此学分身。','',''),('quantangshi-05223','咏院中藂竹','呂太一','quantangshi','','卷6','擢擢当轩竹，青青重岁寒。
心贞徒见赏，箨小未成竿。','',''),('quantangshi-05224','和吕御史咏院中藂竹','張紘','quantangshi','','卷6','闻君庭竹咏，幽意岁寒多。
叹息为冠小，良工将奈何。','',''),('quantangshi-05225','闺怨','張紘','quantangshi','','卷6','去年离别雁初归，今夜裁缝萤已飞。
征客近来音信断，不知何处寄寒衣。','',''),('quantangshi-05226','行路难','張紘','quantangshi','','卷6','君不见温家玉镜台，提携抱屋九重来。
君不见相如绿绮琴，一抚一拍凤凰音。
人生意气须及早，莫负当年行乐心。
荆王奏曲楚妃叹，曲尽欢终夜将半。
朱楼银阁正平生，碧草青苔坐芜漫。
当春对酒不须疑，视日相看能几时。
春风吹尽燕初至，此时自为称君意。
秋露萎草鸿始归，此时衰暮与君违。
人生翻覆何常定，谁保容颜无是非。','',''),('quantangshi-05227','别亲朋','鄭蜀賓','quantangshi','','卷6','畏途方万里，生涯近百年。
不知将白首，何处入黄泉。','',''),('quantangshi-05228','海上作','務光','quantangshi','','卷6','旷哉潮汐池，大矣干坤力。
浩浩去无际，沄沄深不测。
崩腾翕众流，泱漭环中国。
鳞介错殊品，氛霞饶诡色。
天波混莫分，岛树遥难识。
汉主探灵怪，秦王恣游陟。
搜奇大壑东，竦望成山北。
方术徒相误，蓬莱安可得。
吾君略仙道，至化孚淳默。
惊浪晏穷溟，飞航通绝域。
马韩底厥贡，龙伯修其职。
粤我遘休明，匪躬期正直。
敢输鹰隼执，以间豺狼忒。
海路行已殚，輶轩未皇息。
劳歌玄月暮，旅睇沧浪极。
魏阙渺云端，驰心附归冀。','',''),('quantangshi-05229','回波辞','李景伯','quantangshi','','卷6','回波尔时酒巵，微臣职在箴规。
侍宴既过三爵，喧哗窃恐非仪。','',''),('quantangshi-05230','秋晚度废关','李行言','quantangshi','','卷6','秦郊平旧险，周德眷遗黎。
始闻清夜柝，俄见落封泥。
物色来无限，津途去不迷。
空亭谁问马，闲戍但鸣鸡。
山月寒弥净，河风晓更凄。
赠言杨伯起，非复是关西。','',''),('quantangshi-05231','上元','郭利貞','quantangshi','','卷6','九陌连灯影，千门度月华。
倾城出宝骑，匝路转香车。
烂熳惟愁晓，周游不问家。
更逢清管发，处处落梅花。','',''),('quantangshi-05232','赠皇甫侍御赴都八首 一','希聲','quantangshi','','卷6','东南之美，生于会稽。
牛斗之气，蓄于昆溪。
有瑶者玉，连城是齐。
有威者凤，非梧不栖。','',''),('quantangshi-05233','赠皇甫侍御赴都八首 二','希聲','quantangshi','','卷6','猗嗟众珍，以况君子。
公侯之胄，必复其始。
利器长材，温仪峻峙。','',''),('quantangshi-05234','赠皇甫侍御赴都八首 三','希聲','quantangshi','','卷6','道心惟微，厥用允塞。
德辉不泯，而映邦国。
静以有神，动而作则。
九臯千里，其声不忒。','',''),('quantangshi-05235','赠皇甫侍御赴都八首 四','希聲','quantangshi','','卷6','粤在古昔，分官厥初。
刺邪矫枉，非贤勿居。
棱棱直指，烈烈方书。
苍玉鸣佩，绣衣登车。','',''),('quantangshi-05236','赠皇甫侍御赴都八首 五','希聲','quantangshi','','卷6','绰绰夫君，是膺柱下。
准绳有望，名器无假。
宠盖伯山，气雄公雅。
立朝正色，俟我能者。','',''),('quantangshi-05237','赠皇甫侍御赴都八首 六','希聲','quantangshi','','卷6','载怀朋情，尝接闲宴。
好洽昆弟，官联州县。
如彼松竹，春荣冬蒨。
柯叶蔼然，不渝霜霰。','',''),('quantangshi-05238','赠皇甫侍御赴都八首 七','希聲','quantangshi','','卷6','会合非我，关山坐违。
离鸿晓引，别叶秋飞。
騑骖徐动，尊饯相依。
远情超忽，岐路光辉。','',''),('quantangshi-05239','赠皇甫侍御赴都八首 八','希聲','quantangshi','','卷6','金石其心，芝兰其室。
言语方间，音徽自溢。
肃子风威，严子霜质。
赠言岁暮，以保贞吉。','',''),('quantangshi-05240','秋庭夜月有怀','李澄之','quantangshi','','卷6','游客三江外，单栖百虑违。
山川忆处近，形影梦中归。
夜月明虚帐，秋风入捣衣。
从来不惯别，况属雁南飞。','',''),('quantangshi-05241','明月','李如璧','quantangshi','','卷6','三五月华流炯光，可怜怀归郢路长。
逾江越汉津无梁，遥遥永夜思茫茫。
昭君失宠辞上宫，蛾眉婵娟卧毡穹。
胡人琵琶弹北风，汉家音信绝南鸿。
昭君此时怨画工，可怜明月光[朣]胧。
节既秋兮天向寒，沅有漪兮湘有澜。
沅湘糺合淼漫漫，洛阳才子忆长安。
可怜明月复团团，逐臣恋主心愈恪。
弃妻思君情不薄，已悲芳岁徒沦落。
复恐红颜坐销铄，可怜明月方照灼，向影倾身比葵藿。','',''),('quantangshi-05242','严陵祠','洪子輿','quantangshi','','卷6','汉主召子陵，归宿洛阳殿。
客星今安在，隐迹犹可见。
水石空潺湲，松篁尚葱蒨。
岸深翠阴合，川回白云徧。
幽径滋芜没，荒祠幂霜霰。
垂钓想遗芳，掇苹羞野荐。
高风激终古，语理忘荣贱。
方騐道可尊，山林情不变。','',''),('quantangshi-05243','度涂山','寇泚','quantangshi','','卷6','小年弄文墨，不识戎旅难。
一朝事鞞鼓，策马度涂山。
涂山横地轴，万里留荒服。
悠悠征斾远，騑骖一何速。
流月挥金戈，惊风折寒木。
行闻汉飞将，还向臯兰宿。','',''),('quantangshi-05244','永泰公主挽歌二首 一','吳兢','quantangshi','','卷6','穠华从妇道，厘降适诸侯。
河汉天孙合，潇湘帝子游。
关雎方作训，鸣凤自相求。
可叹凌波迹，东川遂不流。','',''),('quantangshi-05245','永泰公主挽歌二首 二','吳兢','quantangshi','','卷6','舜华徂北渚，宸思结南阳。
盩绶哀荣备，游轩宠悼彰。
三川谋远日，八水宅连冈。
无复秦楼上，吹箫下凤皇。','',''),('quantangshi-05246','妾薄命','武平一','quantangshi','','卷6','有女妖且丽，裴回湘水湄。
水湄兰杜芳，采之将寄谁。
瓠犀发皓齿，双蛾颦翠眉。
红脸如开莲，素肤若凝脂。
绰约多逸态，轻盈不自持。
尝矜绝代色，复恃倾城姿。
子夫前入侍，飞燕复当时。
正悦掌中舞，宁哀团扇诗。
洛川昔云遇，高唐今尚违。
幽合禽雀噪，闲阶草露滋。
流景一何速，年华不可追。
解佩安所赠，怨咽空自悲。','',''),('quantangshi-05247','奉和登骊山高顶寓目应制','武平一','quantangshi','','卷6','銮舆上碧天，翠帟拖晴烟。
绝崿纡仙径，层岩敞御筵。
云披丹凤阙，日下黑龙川。
更覩南熏奏，流声入管弦。','',''),('quantangshi-05248','幸梨园观打球应制','武平一','quantangshi','','卷6','令节重遨游，分镳应彩球。
骖驔廻上苑，蹀躞绕通沟。
影就红尘没，光随赭汗流。
赏阑清景暮，歌舞乐时休。','',''),('quantangshi-05249','奉和幸白鹿观应制','武平一','quantangshi','','卷6','玉府凌三曜，金坛驻六龙。
彩旒悬倒景，羽盖偃乔松。
玄圃灵芝秀，华池瑞液浓。
谬因沾舜渥，长愿奉尧封。','',''),('quantangshi-05250','侍宴安乐公主新宅应制','武平一','quantangshi','','卷6','紫汉秦楼敞，黄山鲁馆开。
簪裾分上席，歌舞列平台。
马既如龙至，人疑学凤来。
幸兹联棣萼，何以接邹枚。','',''),('quantangshi-05251','送金城公主适西蕃','武平一','quantangshi','','卷6','广化三边静，通烟四海安。
还将膝下爱，特副域中欢。
圣念飞玄藻，仙仪下白兰。
日斜征盖没，归骑动鸣鸾。','',''),('quantangshi-05252','奉和幸新丰温泉宫应制','武平一','quantangshi','','卷6','秦王登碣石，周后袭昆仑。
何必在遐远，方称万宇尊。
我皇顺时豫，星驾动轩辕。
雄戟交驰道，清笳度国门。
回舆长乐观，校猎上林园。
行漏移三象，连营总八屯。
旌摇鹦鹉谷，骑转凤皇原。
绝壁苍苔古，灵泉碧溜温。
参差开水殿，䆗窱敞岩轩。
丰邑模犹在，骊宫迹尚存。
烟松衔翠幄，雪径遶花源。
侍从推玄草，文章召虎贲。
深仁浃夷夏，洪造溢干坤。
谬忝王枚列，多慙雨露恩。','',''),('quantangshi-05253','奉和幸韦嗣立山庄侍宴应制','武平一','quantangshi','','卷6','三光回斗极，万骑肃钩陈。
地若游汾水，畋疑历渭滨。
圆塘冰写镜，遥树露成春。
弦奏鱼听曲，机忘鸟狎人。
筑岩思感梦，磻石想垂纶。
落景摇红壁，层阴结翠筠。
素风纷可尚，玄泽蔼无垠。
薄暮清笳动，天文焕紫宸。','',''),('quantangshi-05254','兴庆池侍宴应制','武平一','quantangshi','','卷6','銮舆羽驾直城隈，帐殿旌门此地开。
皎洁灵潭图日月，参差画舸结楼台。
波摇岸影随桡转，风送荷香逐酒来。
愿奉圣情欢不极，长游云汉几昭回。','',''),('quantangshi-05255','奉和立春内出彩花树应制','武平一','quantangshi','','卷6','銮辂青旗下帝台，东郊上苑望春来。
黄莺未解林间啭，红蘂先从殿里开。
画阁条风初变柳，银塘曲水半含苔。
欣逢睿藻光韶律，更促霞觞畏景催。','',''),('quantangshi-05256','奉和正旦赐宰臣栢叶应制','武平一','quantangshi','','卷6','绿叶迎春绿，寒枝历岁寒。
愿持柏叶寿，长奉万年欢。','',''),('quantangshi-05257','游泾川琴溪','武平一','quantangshi','','卷6','环潭澄晓色，叠嶂照秋影。
幽致欣所逢，纷虑自兹屏。','',''),('quantangshi-05258','夜宴安乐公主宅','武平一','quantangshi','','卷6','王孙帝女下仙台，金牓珠帘入夜开。
遽惜琼筵欢正洽，唯愁银箭晓相催。','',''),('quantangshi-05259','奉和圣制幸韦嗣立山庄应制','武平一','quantangshi','','卷6','鸣銮赫奕下重楼，羽盖逍遥向一丘。
汉日唯闻白衣宠，唐年更覩赤松游。','',''),('quantangshi-05260','饯唐永昌','武平一','quantangshi','','卷6','闻君墨绶出丹墀，双舃飞来伫有期。
寄谢铜街攀柳日，无忘粉署握兰时。','',''),('quantangshi-05261','奉和圣制立春日侍宴内殿出剪彩花应制','趙彥昭','quantangshi','','卷6','剪彩迎初候，攀条故写真。
花随红意发，叶就绿情新。
嫩色惊衔燕，轻香误采人。
应为熏风拂，能令芳树春。','',''),('quantangshi-05262','奉和人日清晖阁宴羣臣遇雪应制','趙彥昭','quantangshi','','卷6','出震乘东陆，凭高御北辰。
祥云应早岁，瑞雪候初旬。
庭树千花发，阶蓂七叶新。
幸承今日宴，长奉万年春。','',''),('quantangshi-05263','奉和七夕两仪殿会宴应制','趙彥昭','quantangshi','','卷6','青女三秋节，黄姑七日期。
星桥度玉佩，云阁掩罗帷。
河气通仙掖，天文入睿词。
今宵望灵汉，应得见蛾眉。','',''),('quantangshi-05264','奉和九日幸临渭亭登高应制','趙彥昭','quantangshi','','卷6','秋豫凝仙览，宸游转翠华。
呼鹰下鸟路，戏马出龙沙。
紫菊宜新寿，丹萸辟旧邪。
须陪长久宴，岁岁奉吹花。','',''),('quantangshi-05265','奉和九月九日登慈恩寺浮屠应制','趙彥昭','quantangshi','','卷6','出豫乘秋节，登高陟梵宫。
皇心满尘界，佛迹现虚空。
日月宜长寿，人天得大通。
喜闻题宝偈，受记莫由同。','',''),('quantangshi-05266','安乐公主移入新宅侍宴应制同用开字','趙彥昭','quantangshi','','卷6','云物中京晓，天人外馆开。
飞桥象河汉，悬牓学蓬莱。
北阙临仙槛，南山送寿杯。
一窥轮奂毕，惭恧栋梁材。','',''),('quantangshi-05267','奉和送金城公主适西蕃应制','趙彥昭','quantangshi','','卷6','圣后经纶远，谋臣计画多。
受降追汉策，筑馆许戎和。
俗化乌孙垒，春生积石河。
六龙今出饯，双鹤愿为歌。','',''),('quantangshi-05268','奉和圣制登骊山高顶寓目应制','趙彥昭','quantangshi','','卷6','皇情遍九垓，御辇驻昭回。
路若随天转，人疑近日来。
河看大禹凿，山见巨灵开。
愿扈登封驾，常持荐寿杯。','',''),('quantangshi-05269','奉和幸白鹿观应制','趙彥昭','quantangshi','','卷6','云骖驱半景，星跸坐中天。
国诞玄宗圣，家寻碧落仙。
玉杯鸾荐寿，宝算鹤知年。
一覩光华旦，欣承道德篇。','',''),('quantangshi-05270','哭仆射鄂公杨再思','趙彥昭','quantangshi','','卷6','两揆光天秩，三朝奉帝熙。
何言集大鸟，忽此丧元龟。
坐叹公槐落，行闻宰树悲。
壑舟今已去，宁有济川期。','',''),('quantangshi-05271','人日侍宴大明宫应制','趙彥昭','quantangshi','','卷6','宝契无为属圣人，雕舆出幸玩芳辰。
平楼半入南山雾，飞合旁临东墅春。
夹路穠花千树发，垂轩弱柳万条新。
处处风光今日好，年年愿奉属车尘。','',''),('quantangshi-05272','奉和初春幸太平公主南庄应制','趙彥昭','quantangshi','','卷6','主第岩扃驾鹊桥，天门阊阖降鸾镳。
历乱旌旗转云树，参差台榭入烟霄。
林间花杂平阳舞，谷里莺和弄玉箫。
已陪沁水追欢日，行奉茅山访道朝。','',''),('quantangshi-05273','奉和幸安乐公主山庄应制','趙彥昭','quantangshi','','卷6','六龙齐轸御朝曦，双鷁维舟下绿池。
飞观仰看云外耸，浮桥直见海中移。
灵泉巧凿天孙渚，孝笋能抽帝女枝。
幸愿一生同草树，年年岁岁乐于斯。','',''),('quantangshi-05274','奉和幸大荐福寺','趙彥昭','quantangshi','','卷6','宝地龙飞后，金身佛现时。
千花开国界，万善累皇基。
北阙承行幸，西园属住持。
天衣拂旧石，王舍起新祠。
刹凤迎雕辇，幡虹驻彩旗。
同沾小雨润，窃仰大风诗。','',''),('quantangshi-05275','奉和幸长安故城未央宫应制','趙彥昭','quantangshi','','卷6','夙驾移天跸，凭轩览汉都。
寒烟收紫禁，春色绕黄图。
旧史遗陈迹，前王失霸符。
山河寸土尽，宫观尺椽无。
崇高惟在德，壮丽岂为谟。
茨室留皇鉴，熏歌盛有虞。','',''),('quantangshi-05276','奉和幸韦嗣立山庄侍燕应制','趙彥昭','quantangshi','','卷6','贤族唯题里，儒门但署乡。
何如表岩洞，宸翰发辉光。
地在兹山曲，家临郃水阳。
六龙驻旌罕，四牡耀旗常。
北斗临台座，东山入庙堂。
天高羽翼近，主圣股肱良。
野竹池亭气，村花涧谷香。
纵然怀豹隐，空愧蹑鵷行。','',''),('quantangshi-05277','奉和元日赐羣臣栢叶应制','趙彥昭','quantangshi','','卷6','器乏雕梁器，材非构厦材。
但将千岁叶，常奉万年杯。','',''),('quantangshi-05278','苑中人日遇雪应制','趙彥昭','quantangshi','','卷6','始见青云干律吕，俄逢瑞雪应阳春。
今日回看上林树，梅花柳絮一时新。','',''),('quantangshi-05279','奉和圣制幸韦嗣立山庄应制','趙彥昭','quantangshi','','卷6','廊庙心存岩壑中，銮舆瞩在灞城东。
逍遥自在蒙庄子，汉主徒言河上公。','',''),('quantangshi-05280','秋朝木芙蓉','趙彥昭','quantangshi','','卷6','水面芙蓉秋已衰，繁条偏是着花迟。
平明露滴垂红脸，似有朝愁暮落时。','',''),('quantangshi-05281','侍宴桃花园咏桃花应制','趙彥昭','quantangshi','','卷6','红萼竞燃春苑曙，粉茸新吐御筵开。
长年愿奉西王母，近侍惭无东朔才。','',''),('quantangshi-05282','奉和九日幸临渭亭登高应制得余字','蕭至忠','quantangshi','','卷6','望幸三秋暮，登高九日初。
朱旗巡汉苑，翠帟俯秦墟。
宠极萸房遍，恩深菊酎余。
承欢何以答，万亿奉宸居。','',''),('quantangshi-05283','奉和九月九日登慈恩寺浮图应制','蕭至忠','quantangshi','','卷6','天跸三乘启，星舆六辔行。
登高凌宝塔，极目徧王城。
神衞空中遶，仙歌云外清。
重阳千万寿，率舞颂升平。','',''),('quantangshi-05284','奉和幸安乐公主山庄应制','蕭至忠','quantangshi','','卷6','西郊窈窕凤皇台，北渚平明法驾来。
匝地金声初度曲，周堂玉溜好传杯。
湾路分游画舟转，岸门相向碧亭开。
微臣此时承宴乐，仿髴疑从星汉回。','',''),('quantangshi-05285','送张亶赴朔方应制','蕭至忠','quantangshi','','卷6','命将择耆年，图功胜必全。
光辉万乘饯，威武二庭宣。
中衢横鼓角，旷野蔽旌旃。
推食天厨至，投醪御酒传。
凉风过雁苑，杀气下鸡田。
分阃恩何极，临岐动睿篇。','',''),('quantangshi-05286','陪幸长宁公主林亭','蕭至忠','quantangshi','','卷6','公主林亭地，清晨降玉舆。
画桥飞渡水，仙阁逈临虚。
新晴看蛱蝶，早夏摘芙蕖。
文酒娱游盛，忻叨侍从余。','',''),('quantangshi-05287','陪幸五王宅','蕭至忠','quantangshi','','卷6','北斗枢机任，西京肺腑亲。
畴昔王门下，今兹制幸晨。
恩来山水被，圣作管弦新。
遶座薰红药，当轩暗绿筠。
摘荷才早夏，听鸟尚余春。
行漏金徒晓，风烟是观津。','',''),('quantangshi-05288','三会寺应制','蕭至忠','quantangshi','','卷6','岧嶤仓史台，敞朗绀园开。
戒旦壶人警，翻霜羽骑来。
下辇登三袭，褰旒望九垓。
林披馆陶牓，水浸昆明灰。
网户飞花缀，幡竿度鸟回。
豫游仙唱动，潇洒初尘埃。','',''),('quantangshi-05289','荐福寺应制','蕭至忠','quantangshi','','卷6','地灵传景福，天驾俨钩陈。
佳哉藩邸旧，赫矣梵宫新。
香塔鱼山下，禅堂雁水滨。
珠幡映白日，镜殿写青春。
甚懽延故吏，大觉拯生人。
幸承歌颂末，长奉属车[尘]。','',''),('quantangshi-05290','陪游上苑遇雪','蕭至忠','quantangshi','','卷6','龙骖晓入望春宫，正逢春雪舞春风。
花光倂在天文上，寒气行销御酒中。','',''),('quantangshi-05291','奉和九日幸临渭亭登高应制得风字','李迥秀','quantangshi','','卷6','重九临商节，登高出汉宫。
正逢萸实满，还对菊花丛。
霁云开就日，仙藻丽秋风。
微臣预在镐，窃拚遂无穷。','',''),('quantangshi-05292','奉和九月九日登慈恩寺浮图应制','李迥秀','quantangshi','','卷6','沙界人王塔，金绳梵帝游。
言从[只]树赏，行翫菊丛秋。
御酒调甘露，天花拂彩旒。
尧年将佛日，同此庆时休。','',''),('quantangshi-05293','奉和幸安乐公主山庄应制','李迥秀','quantangshi','','卷6','诘旦重门闻警跸，传言太主奏山林。
是日回舆罗万骑，此时欢喜赐千金。
鹭羽凤箫参乐曲，荻园竹径接帷阴。
手舞足蹈方无已，万年千岁奉薰琴。','',''),('quantangshi-05294','夜宴安乐公主宅','李迥秀','quantangshi','','卷6','金牓岧嶤云里开，玉箫参差天际回。
莫惊侧弁还归路，秖为平阳歌舞催。','',''),('quantangshi-05295','奉和九日幸临渭亭登高应制得亭字','楊廉','quantangshi','','卷6','远目瞰秦坰，重阳坐灞亭。
既开黄菊酒，还降紫微星。
箫鼓谙仙曲，山河入画屏。
幸兹陪宴喜，无以效丹青。','',''),('quantangshi-05296','奉和九月九日登慈恩寺浮图应制','楊廉','quantangshi','','卷6','万乘临真境，重阳眺远空。
慈云浮雁塔，定水映龙宫。
宝铎含飙响，仙轮带日红。
天文将瑞色，辉焕满寰中。','',''),('quantangshi-05297','奉和九日幸临渭亭登高应制得枝字','韋安石','quantangshi','','卷6','重九开秋节，得一动宸仪。
金风飘菊蘂，玉露泫萸枝。
睿览八纮外，天文七曜披。
临深应在即，居高岂忘危。','',''),('quantangshi-05298','侍宴旋师喜捷应制','韋安石','quantangshi','','卷6','蜂蚁屯夷落，熊罴逐汉飞。
忘躯百战后，屈指一年归。
厚眷纾天藻，深慈解御衣。
兴酣歌舞出，朝野叹光辉。','',''),('quantangshi-05299','梁王宅侍宴应制同用风字','韋安石','quantangshi','','卷6','梁园开胜景，轩驾动宸衷。
早荷承湛露，修竹引薰风。
九酝倾钟石，百兽协丝桐。
小臣陪宴镐，献寿奉维嵩。','',''),('quantangshi-05300','奉和九日幸临渭亭登高应制得明字','竇希玠','quantangshi','','卷6','銮舆巡上苑，凤驾瞰层城。
御座丹乌丽，宸居白鹤惊。
玉旗萦桂叶，金杯泛菊英。
九晨陪圣膳，万岁奉承明。','',''),('quantangshi-05301','奉和九日幸临渭亭登高应制得臣字','陸景初','quantangshi','','卷6','九秋光顺豫，重节霁良辰。
登高识汉苑，问道侍轩臣。
菊花浮秬鬯，萸房插缙绅。
圣化边陲谧，长洲鸿雁宾。','',''),('quantangshi-05302','奉和九日幸临渭亭登高应制得日字','鄭南金','quantangshi','','卷6','重阳玉律应，万乘金舆出。
风起韵虞弦，云开吐尧日。
菊花浮圣酒，茱香挂衰质。
欲知恩煦多，顺动观秋实。','',''),('quantangshi-05303','奉和九日幸临渭亭登高应制得直字','李咸','quantangshi','','卷6','重阳乘令序，四野开晴色。
日月数初并，干坤圣登极。
菊黄迎酒泛，松翠凌霜直。
游海难为深，负山徒倦力。','',''),('quantangshi-05304','奉和九日幸临渭亭登高应制得花字','趙彥伯','quantangshi','','卷6','九日报仙家，三秋转岁华。
呼鹰下鸟路，戏马出龙沙。
簪挂丹萸蘂，杯浮紫菊花。
所愿同微物，年年共辟邪。','',''),('quantangshi-05305','从宴桃花园咏桃花应制','趙彥伯','quantangshi','','卷6','红萼竞燃春苑曙，䒠茸新吐御筵开。
长年愿奉西王宴，近侍惭无东朔才。','',''),('quantangshi-05306','苑中遇雪应制','趙彥伯','quantangshi','','卷6','千钟圣酒御筵披，六出祥英乱遶枝。
即此神仙对琼圃，何烦辙迹向瑶池。','',''),('quantangshi-05307','奉和九日幸临渭亭登高应制得樽字','于經野','quantangshi','','卷6','御气三秋节，登高九曲门。
桂筵罗玉俎，菊醴溢芳樽。
遵渚归鸿度，承云舞鹤骞。
微臣滥陪赏，空荷圣明恩。','',''),('quantangshi-05308','奉和九日幸临渭亭登高应制得还字','盧懷慎','quantangshi','','卷6','时和素秋节，宸豫紫机关。
鹤似闻琴至，人疑宴镐还。
旷望临平野，潺湲俯瞑湾。
无因酬大德，空此愧崇班。','',''),('quantangshi-05309','奉和圣制龙池篇','盧懷慎','quantangshi','','卷6','代邸东南龙跃泉，清漪碧浪远浮天。
楼台影就波中出，日月光疑镜里悬。
雁沼洄流成舜海，龟书荐社应尧年。
大川既济慙为楫，报德空思奉细涓。','',''),('quantangshi-05310','奉和九月九日登慈恩寺浮图应制','辛替否','quantangshi','','卷6','洪慈均动植，至德俯深玄。
出豫从初地，登高适梵天。
白云飞御藻，慧日暖皇编。
别有秋原藿，长倾雨露缘。','',''),('quantangshi-05311','奉和九月九日登慈恩寺浮图应制','王景','quantangshi','','卷6','玉辇移中禁，珠梯览四禅。
重阶清汉接，飞窦紫霄悬。
缀叶披天藻，吹花散御筵。
无因銮跸暇，俱舞鹤林前。','',''),('quantangshi-05312','奉和九月九日登慈恩寺浮图应制','畢乾泰','quantangshi','','卷6','鹦林花塔启，凤辇顺时游。
重九昭皇庆，大千扬帝休。
耆闍妙法阐，王舍睿文流。
至德覃无极，小臣歌讵酬。','',''),('quantangshi-05313','奉和九月九日登慈恩寺浮图应制','麴瞻','quantangshi','','卷6','扈跸游玄地，陪仙瞰紫微。
似迈铢衣刼，将同羽化飞。
雕戈秋日丽，宝劒晓霜霏。
献觞乘菊序，长愿奉天晖。','',''),('quantangshi-05314','奉和九月九日登慈恩寺浮图应制','樊忱','quantangshi','','卷6','净境重阳节，仙游万乘来。
插萸登鹫岭，把菊坐蜂台。
十地祥云合，三天瑞景开。
秋风词更远，窃拚乐康哉。','',''),('quantangshi-05315','奉和九月九日登慈恩寺浮图应制','孫佺','quantangshi','','卷6','应节萸房满，初寒菊圃新。
龙旗焕辰极，凤驾俨香闉。
莲井偏宜夏，梅梁更若春。
一忻陪雁塔，还似得天身。','',''),('quantangshi-05316','奉和九月九日登慈恩寺浮图应制','李從遠','quantangshi','','卷6','九月从时豫，三乘为法开。
中霄日天子，半座宝如来。
摘果珠盘献，攀萸玉辇回。
愿将尘露点，遥奉光明台。','',''),('quantangshi-05317','奉和九月九日登慈恩寺浮图应制','周利用','quantangshi','','卷6','出豫乘金节，飞文焕日宫。
萸房开圣酒，杏苑被玄功。
塔向三天迥，禅收八解空。
叨恩奉兰藉，终愧洽薰风。','',''),('quantangshi-05318','奉和九月九日登慈恩寺浮图应制','張景源','quantangshi','','卷6','飞塔凌霄起，宸游一届焉。
金壶新泛菊，宝座即披莲。
就日摇香辇，凭云出梵天。
祥氛与佳色，相伴杂炉烟。','',''),('quantangshi-05319','奉和九月九日登慈恩寺浮图应制','李恆','quantangshi','','卷6','宝地隣丹掖，香台瞰碧云。
河山天外出，城阙树中分。
睿藻兰英秀，仙杯菊蘂薰。
愿将今日乐，长奉圣明君。','',''),('quantangshi-05320','奉和九月九日登慈恩寺浮图应制','張錫','quantangshi','','卷6','九秋霜景净，千门晓望通。
仙游光御路，瑞塔迥凌空。
菊彩扬尧日，萸香遶舜风。
天文丽辰象，窃拚仰层穹。','',''),('quantangshi-05321','晦日宴高文学林亭','張錫','quantangshi','','卷6','雪尽铜驼路，花照石崇家。
年光开柳色，池影泛云华。
赏洽情方远，春归景未赊。
欲知多暇日，尊酒渍澄霞。','',''),('quantangshi-05322','奉和九月九日登慈恩寺浮图应制','解琬','quantangshi','','卷6','瑞塔临初地，金舆幸上方。
空边有清净，觉处无馨香。
雨霁微尘歛，风秋定水凉。
兹辰采仙菊，荐寿庆重阳。','',''),('quantangshi-05323','晦日宴高氏林亭','解琬','quantangshi','','卷6','主第簪裾出，王畿春照华。
山亭一以眺，城阙带烟霞。
横堤列锦帐，傍浦驻香车。
欢娱属晦节，酩酊未还家。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-05324','侍宴长宁公主东庄应制','鄭愔','quantangshi','','卷6','公门袭汉环，主第称秦玉。
池架祥鳣序，山吹鸣凤曲。
拂席萝薜垂，回舟芰荷触。
平阳妙舞处，日暮清歌续。','',''),('quantangshi-05325','采莲曲','鄭愔','quantangshi','','卷6','锦䋏沙棠舰，罗带石榴帬。
绿潭采荷芰，清江日稍曛。
鱼鸟争唼喋，花叶相芬氲。
不觉芳洲暮，菱歌处处闻。','',''),('quantangshi-05326','夜游曲','鄭愔','quantangshi','','卷6','汉室欢娱盛，魏国文雅遒。
许史多暮宿，应陈从夜游。
西园宴公子，北里召王侯。
讵似将军猎，空嗟亭尉留。','',''),('quantangshi-05327','少年行','鄭愔','quantangshi','','卷6','颍川豪横客，咸阳轻薄儿。
田窦方贵幸，赵李新相知。
轩盖终朝集，笙竽此夜吹。
黄金盈箧笥，白日忽西驰。','',''),('quantangshi-05328','中宗降诞日长宁公主满月侍宴应制','鄭愔','quantangshi','','卷6','春殿猗兰美，仙阶柏树荣。
地逢芳节应，时覩圣人生。
月满增祥荚，天长发瑞灵。
南山遥可献，常愿奉皇明。','',''),('quantangshi-05329','奉和幸上官昭容院献诗四首 一','鄭愔','quantangshi','','卷6','地轴楼居远，天台阙路赊。
何如游帝宅，即此对仙家。
座拂金壶电，池摇玉酒霞。
无云秦汉隔，别访武陵花。','',''),('quantangshi-05330','奉和幸上官昭容院献诗四首 二','鄭愔','quantangshi','','卷6','尧茨姑射近，汉苑建章连。
十五蓂知月，三千桃纪年。
鸾歌随凤吹，鹤舞向鵾弦。
更觅琼妃伴，来过玉女泉。','',''),('quantangshi-05331','奉和幸上官昭容院献诗四首 三','鄭愔','quantangshi','','卷6','宫掖贤才重，山林高尚难。
不言辞辇地，更有结庐欢。
池栋清温燠，岩窗起冱寒。
幽亭有仙桂，圣主万年看。','',''),('quantangshi-05332','奉和幸上官昭容院献诗四首 四','鄭愔','quantangshi','','卷6','槎流天上转，茅宇禁中开。
河鹊填桥至，山熊避槛来。
庭花采菉蓐，岩石步莓苔。
愿奉舆图泰，长开锦翰裁。','',''),('quantangshi-05333','送金城公主适西蕃应制','鄭愔','quantangshi','','卷6','下嫁戎庭远，和亲汉礼优。
笳声出虏塞，箫曲背秦楼。
贵主悲黄鹤，征人怨紫骝。
皇情眷亿兆，割念俯怀柔。','',''),('quantangshi-05334','奉和幸望春宫送朔方大总管张仁亶','鄭愔','quantangshi','','卷6','御跸下都门，军麾出塞垣。
长杨跨武骑，细柳接戎轩。
睿曲风云动，边威鼓吹喧。
坐帷将阃外，俱是报明恩。','',''),('quantangshi-05335','奉和九月九日登慈恩寺浮图应制','鄭愔','quantangshi','','卷6','涌霄开宝塔，倒影驻仙舆。
雁子乘堂处，龙王起藏初。
秋风圣主曲，佳气史官书。
愿献重阳寿，承欢万岁余。','',''),('quantangshi-05336','铜雀妓','鄭愔','quantangshi','','卷6','日斜漳浦望，风起邺台寒。
玉座平生晚，金尊妓吹阑。
舞余依帐泣，歌罢向陵看。
萧索松风暮，愁烟入井阑。','',''),('quantangshi-05337','胡笳曲','鄭愔','quantangshi','','卷6','汉将留边朔，遥遥岁序深。
谁堪牧马思，正是胡笳吟。
曲断关山月，声悲雨雪阴。
传书问苏武，陵也独何心。','',''),('quantangshi-05338','折杨柳','鄭愔','quantangshi','','卷6','青柳映红颜，黄云蔽紫关。
忽闻边使出，枝叶为君攀。
舞腰愁欲断，春心望不还。
风花滚成雪，罗绮乱斑斑。','',''),('quantangshi-05339','秋闺','鄭愔','quantangshi','','卷6','征客向轮台，幽闺寂不开。
音书秋雁断，机杼夜蛩催。
虚幌风吹叶，闲阶露湿苔。
自怜愁思影，常共月裴回。','',''),('quantangshi-05340','人日重宴大明宫恩赐彩缕人胜应制','鄭愔','quantangshi','','卷6','琼殿含光映早轮，玉鸾严跸望初晨。
池开冻水仙宫丽，树发寒花禁苑新。
佳气裴回笼细网，残霙淅沥染轻尘。
良时荷泽皆迎胜，穷谷曦阳犹未春。','',''),('quantangshi-05341','奉和春日幸望春宫','鄭愔','quantangshi','','卷6','晨跸凌高转翠旌，春楼望远背朱城。
忽排花上游天苑，却坐云边看帝京。
百草香心初罥蝶，千林嫩叶始藏莺。
幸同葵藿倾阳早，愿比盘根应候荣。','',''),('quantangshi-05342','奉和幸三会寺应制','鄭愔','quantangshi','','卷6','鸟籀遗新阁，龙旗访古台。
造书臣颉往，观迹帝羲来。
睿览山川匝，宸心宇宙该。
梵音随驻辇，天步接乘杯。
旧苑经寒露，残池问劫灰。
散花将捧日，俱喜圣慈开。','',''),('quantangshi-05343','奉和幸大荐福寺','鄭愔','quantangshi','','卷6','旧邸三乘辟，佳辰万骑留。
兰图奉叶偈，芝盖拂花楼。
国会人王法，宫还天帝游。
紫云成宝界，白水作禅流。
雁塔昌基远，鹦林睿藻抽。
欣承大风曲，窃预小童讴。','',''),('quantangshi-05344','同韦舍人早朝','鄭愔','quantangshi','','卷6','瑞阙龙居峻，宸庭凤掖深。
才良寄天綍，趋拜侣朝簪。
飞马看来影，喧车识驻音。
重轩轻雾入，洞户落花侵。
闻有题新翰，依然想旧林。
同声慙卞玉，谬此托韦金。','',''),('quantangshi-05345','塞外三首 一','鄭愔','quantangshi','','卷6','塞外萧条望，征人此路赊。
边声乱朔马，秋色引胡笳。
遥嶂侵归日，长城带晚霞。
断蓬飞古戍，连雁聚寒沙。
海暗云无叶，山春雪作花。
丈夫期报主，万里独辞家。','',''),('quantangshi-05346','塞外三首 二','鄭愔','quantangshi','','卷6','荒垒三秋夕，穷郊万里平。
海阴凝独树，日气下连营。
戎斾霜旋重，边裘夜更轻。
将军犹转战，都尉不成名。
折柳悲春曲，吹笳断夜声。
明年汉使返，须筑受降城。','',''),('quantangshi-05347','塞外三首 三','鄭愔','quantangshi','','卷6','阳鸟南飞夜，阴山北地寒。
汉家征戍客，年岁在楼兰。
玉塞朔风起，金河秋月团。
边声入鼓吹，霜气下旌竿。
海外归书断，天涯旅鬓残。
子卿犹奉使，常向节旄看。','',''),('quantangshi-05348','春怨','鄭愔','quantangshi','','卷6','春朝物候妍，愁妇镜台前。
风吹数蝶乱，露洗百花鲜。
试出褰罗幌，还来着锦筵。
曲中愁夜夜，楼上别年年。
不及随萧史，高飞向紫烟。','',''),('quantangshi-05349','贬降至汝州广城驿','鄭愔','quantangshi','','卷6','近郊凭汝海，遐服指江干。
尚忆趋朝贵，方知失路难。
曙宫平乐远，秋泽广城寒。
岸苇新花白，山梨晚叶丹。
乡关千里暮，岁序四时阑。
函塞云间别，旋门雾里看。
夙年追騄骥，暮节仰鵷鸾。
疲驽劳垂耳，骞腾讵矫翰。
将调梅铉实，不正李园冠。
荆玉终无玷，随珠忽已弹。
晓装违巩洛，夕梦在长安。
北上频伤阮，西征未学潘。
倾车无共辙，同派有殊澜。
去去怀知己，何由报一餐。','',''),('quantangshi-05350','哭郎着作','鄭愔','quantangshi','','卷6','诗礼康成学，文章贾谊才。
巳年人得梦，庚日鸟为灾。
书草藏天阁，琴声入夜台。
荒阶罗驳藓，虚座网浮埃。
白马宾徒散，青乌陇隧开。
空怜门下客，怀旧几迟回。','',''),('quantangshi-05351','咏黄莺儿','鄭愔','quantangshi','','卷6','欲啭声犹涩，将飞羽未调。
高风不借便，何处得迁乔。','',''),('quantangshi-05352','百舌','鄭愔','quantangshi','','卷6','百舌鸣高树，弄音无常则。
借问声何烦，末俗不尚默。','',''),('quantangshi-05353','奉和圣制送张说上集贤学士赐宴','源乾曜','quantangshi','','卷6','盛业光书府，征人尽国英。
丝纶贤得相，羣俊学为名。
宠命垂天锡，崇恩发睿情。
熏风清禁籞，文殿述皇明。
日霁庭阴出，池曛水气生。
欢娱此无限，诗酒自相迎。','',''),('quantangshi-05354','奉和御制干曜与张说宋璟同日上官命宴都堂赐诗','源乾曜','quantangshi','','卷6','睿作超千古，湛恩育万人。
递迁俱荷泽，同拜忽为邻。
道合徽音畅，芳辰景命新。
鼓钟崇享礼，鵷鹭集朝伦。
窃位思官谤，凋容谢木春。
慙多无以叙，拙备实难陈。
进绶怀三少，承光尽百身。
自当归第日，何幸列宫臣。','',''),('quantangshi-05355','奉和圣制送张尚书巡边','源乾曜','quantangshi','','卷6','匈奴迩河朔，汉地须戎旅。
天子择英才，朝端出监抚。
流星下阊阖，宝钺专公辅。
礼物生光辉，宸章备恩诩。
有征视矛戟，制胜唯樽俎。
彼美何壮哉，桓桓擅斯举。
声华振台阁，功德标文武。
奉国知命轻，忘家以身许。
安人在勤恤，保大殚襟俯。
此外无异言，同情报明主。','',''),('quantangshi-05356','禅社首乐章','源乾曜','quantangshi','','卷6','灵具醉，杳熙熙。
灵将往，眇禗禗。
愿明德，吐正词。
烂遗光，流祯祺。','',''),('quantangshi-05357','奉和圣制送张说赴集贤院学士赐宴赋得虚字','徐堅','quantangshi','','卷6','崇文德化洽，新殿集贤初。
庸菲参高选，首滥承明庐。
殊私光辅弼，荣送列簪裾。
座引中厨馔，杯锡上尊余。
翠叶浓丹苑，晴空卷碧虚。
忝同文史地，愿草登封书。','',''),('quantangshi-05358','奉和圣制送张说巡边','徐堅','quantangshi','','卷6','至德抚遐荒，神兵赴朔方。
帝思元帅重，爰择股肱良。
累相承安世，深筹协子房。
寄崇专斧钺，礼备设坛场。
鼙鼓喧雷电，戈劒凛风霜。
四騑将戒道，十乘启先行。
圣锡加恒数，天文耀宠光。
出郊开帐饮，寅饯盛离章。
雨濯梅林润，风清麦野凉。
燕山应勒颂，麟阁伫名扬。','',''),('quantangshi-05359','奉和送金城公主适西蕃应制','徐堅','quantangshi','','卷6','星汉下天孙，车服降殊蕃。
匣中词易切，马上曲虚繁。
关塞移朱帐，风尘暗锦轩。
箫声去日远，万里望河源。','',''),('quantangshi-05360','饯许州宋司马赴任','徐堅','quantangshi','','卷6','旧许星车转，神京祖帐开。
断烟伤别望，零雨送离杯。
辞燕依空遶，宾鸿入听哀。
分襟与秋气，日夕共悲哉。','',''),('quantangshi-05361','饯唐永昌','徐堅','quantangshi','','卷6','郎官出宰赴伊瀍，征传骎骎灞水前。
此时怅望新丰道，握手相看共黯然。','',''),('quantangshi-05362','送考功武员外学士使嵩山置舍利塔歌','徐堅','quantangshi','','卷6','伊川别骑，灞岸分筵。
对三春之花月，览千里之风烟。
望青山兮分地，见白云兮在天。
寄愁心于樽酒，怆离绪于清弦。
共握手而相顾，各衔凄而黯然。','',''),('quantangshi-05363','棹歌行','徐堅','quantangshi','','卷6','棹女饰银钩，新妆下翠楼。
霜丝青桂檝，兰栧紫霞舟。
水落金陵曙，风起洞庭秋。
扣舷过曲浦，飞帆越回流。
影入桃花浪，香飘杜若洲。
洲长殊未返，萧散云霞晚。
日下大江平，烟生归岸远。
岸远闻潮波，争途游戏多。
因声赵津女，来听采菱歌。','',''),('quantangshi-05364','送武进郑明府','徐堅','quantangshi','','卷6','弦歌试宰日，城阙赏心违。
北谢苍龙去，南随黄鹄飞。
夏云海中出，吴山江上微。
甿谣岂云远，从此庆缁衣。','',''),('quantangshi-05365','仪坤庙乐章','徐堅','quantangshi','','卷6','于穆清庙，肃雍严祀。
合福受厘，介以繁祉。','',''),('quantangshi-05366','祭汾阴乐章','源光裕','quantangshi','','卷6','方丘既膳，嘉飨载谧。
斋敬毕诚，陶匏贵质。
秀毕丰荐，芳俎盈实。
永永福流，其升如日。','',''),('quantangshi-05367','奉和圣制送张说上集贤学士赐宴','李元紘','quantangshi','','卷6','硕儒延凤沼，金马被鸿私。
馔玉趋丹禁，牋花降紫墀。
衔恩倾旨酒，鼓舞咏康时。
暂觏羣书缉，逾昭盛业丕。
接筵欣有命，搦管愧无词。
自惊一何幸，太阳还及葵。','',''),('quantangshi-05368','绿墀怨','李元紘','quantangshi','','卷6','征马噪金珂，嫖姚向北河。
绿苔行迹少，红粉泪痕多。
宝屋粘花絮，银筝覆网罗。
别君如昨日，青海雁频过。','',''),('quantangshi-05369','相思怨','李元紘','quantangshi','','卷6','望月思氛氲，朱衾嬾更熏。
春生翡翠帐，花点石榴裠。
燕语时惊妾，莺啼转忆君。
交河一万里，仍隔数重云。','',''),('quantangshi-05370','奉和圣制送张说上集贤学士赐宴','裴漼','quantangshi','','卷6','问道图书盛，尊儒礼教兴。
石渠因学广，金殿为贤升。
日月恩光照，风云宠命膺。
谋谟言可范，舟檝事斯凭。
宴喜明时洽，光辉湛露凝。
大哉尧作主，天下颂歌称。','',''),('quantangshi-05371','奉和御制旋师喜捷','裴漼','quantangshi','','卷6','殊类骄无长，王师示有征。
中军才受律，妖寇已亡精。
斩虏还遮塞，绥降更筑城。
从来攻必克，天策振奇兵。','',''),('quantangshi-05372','奉和御制平胡','裴漼','quantangshi','','卷6','玄漠圣恩通，由来书轨同。
忽闻窥月满，相聚寇云中。
庙略占黄气，神兵出绛宫。
将军行逐虏，使者亦和戎。
一举轒輼灭，再麾沙漠空。
直将威禁暴，非用武为雄。
饮至明军礼，醻勋锡武功。
干戈还载戢，文德在唐风。','',''),('quantangshi-05373','奉和圣制龙池篇','裴漼','quantangshi','','卷6','干坤启圣吐龙泉，泉水年年胜一年。
始看鱼跃方成海，即覩飞龙利在天。
洲渚遥将银汉接，楼台直与紫微连。
休气荣光恒不散，悬知此地是神仙。','',''),('quantangshi-05374','奉和圣制送张说上集贤学士赐宴','劉昇','quantangshi','','卷6','图书应明主，策府宴嘉宾。
台曜临东壁，干光自北辰。
网罗穷象系，述作究天人。
圣酒千钟洽，仙厨百味陈。
成山徒可仰，涉海讵知津。
幸逢文教盛，还覩颂声新。','',''),('quantangshi-05375','奉和圣制送张说上集贤学士赐宴','蕭嵩','quantangshi','','卷6','帝曰简才能，旌贤在股肱。
文章体一变，礼乐道逾弘。
芸阁英华入，宾门鵷鹭登。
恩筵过所望，圣泽实超恒。
夏叶开红药，余花发紫藤。
微臣亦何幸，叨此预文朋。','',''),('quantangshi-05376','奉和御制左丞相说右丞相璟太子少傅干曜同日上官命宴都堂赐诗','蕭嵩','quantangshi','','卷6','审官思共理，多士属惟唐。
历选台庭旧，来熙帝业昌。
入朝师百辟，论道协三光。
垂拱咨元老，亲贤辅少阳。
登庸崇礼送，宠德耀宸章。
御酒飞觞洽，仙闱雅乐张。
荷恩思有报，陈力愧无良。
愿罄公忠节，同心奉我皇。','',''),('quantangshi-05377','奉和圣制送张说上集贤学士赐宴','韋抗','quantangshi','','卷6','广庭临璧沼，多士侍金闺。
英宰文儒叶，明君日月齐。
集贤光首拜，改殿发新题。
早夏初移律，余花尚拂溪。
壶觞接云上，经术引关西。
圣德鸿名远，将陪玉检泥。','',''),('quantangshi-05378','奉和圣制送张说上集贤学士赐宴','李暠','quantangshi','','卷6','偃武尧风接，崇文汉道恢。
集贤更内殿，清选自中台。
佐命留侯业，词华博物才。
天厨千品降，御酒百壶催。
鵷鹭方成列，神仙喜暂陪。
复欣同拜首，叨此颂良哉。','',''),('quantangshi-05379','奉和圣制送张说上集贤学士赐宴','韋述','quantangshi','','卷6','修文中禁启，改字令名加。
台座征人杰，书坊应国华。
赋诗开广宴，赐酒酌流霞。
云散明金阙，池开照玉沙。
掖垣留宿鸟，温树落余花。
谬此天光及，衔恩醉日斜。','',''),('quantangshi-05380','晚渡伊水','韋述','quantangshi','','卷6','悠悠涉伊水，伊水清见石。
是时春向深，两岸草如积。
迢遰望洲屿，逶迤亘津陌。
新树落疎红，遥原上深碧。
回瞻洛阳苑，遽有长山隔。
烟雾犹辨家，风尘已为客。
登陟多异趣，往来见行役。
云起早已昏，鸟飞日将夕。
光阴逝不借，超然慕畴昔。
远游亦何为？归来存竹帛。','',''),('quantangshi-05381','春日山庄','韋述','quantangshi','','卷6','初岁开韶月，田家喜载阳。
晚晴摇水态，迟景荡山光。
浦净渔舟远，花飞樵路香。
自然成野趣，都使俗情忘。','',''),('quantangshi-05382','广陵送别宋员外佐越郑舍人还京','韋述','quantangshi','','卷6','朱绂临秦望，皇华赴洛桥。
文章南渡越，书奏北归朝。
树入江云尽，城衔海月遥。
秋风将客思，川上晚萧萧。','',''),('quantangshi-05383','奉和圣制送张说上集贤学士赐宴','陸堅','quantangshi','','卷6','圣主崇文教，层霄降德音。
尊贤泽既厚，式宴宠逾深。
复有夔龙相，良哉简帝心。
得人惟迈昔，多士谅推今。
书殿荣光满，儒门喜气临。
顾惟诚滥吹，徒此接衣簪。','',''),('quantangshi-05384','句 千秋节应制','陸堅','quantangshi','','卷6','风移覃土宇，云上浃羣臣。','',''),('quantangshi-05385','奉和圣制送张说上集贤学士赐宴','程行諶','quantangshi','','卷6','圣主崇文化，锵锵得盛才。
相因归梦立，殿以集贤开。
象系微言阐，诗书至道该。
尧尊承帝泽，禹膳自天来。
礼洽欢逾长，风恬暑更回。
国朝将舜颂，同是一康哉。','',''),('quantangshi-05386','奉和圣制送张说上集贤学士赐宴','褚秀','quantangshi','','卷6','讲习延东观，趋陪盛北宫。
惟师恢帝则，敷教叶天工。
宣室恩尝异，金华礼更崇。
洞门清永日，华绶接微风。
萐降尧厨翠，榴开舜酒红。
文思光万宇，高议待升中。','',''),('quantangshi-05387','奉和御制左丞相说右丞相璟太子少傅干曜同日上官命都堂赐诗','裴光庭','quantangshi','','卷6','乐贤闻往诰，褒德偶兹辰。
端揆升元老，师谋择累仁。
紫庭崇让毕，粉署礼容陈。
既荷恩荣旧，俱承宠命新。
天文悬瑞色，圣酒泛华茵。
杂遝喧箫鼓，欢娱洽搢绅。
掖垣招近侍，虚薄[厕]清尘。
共保坚贞节，常期雨露均。','',''),('quantangshi-05388','奉和圣制左丞相说右丞相璟太子少傅干曜同日上官命宴都堂赐诗','宇文融','quantangshi','','卷6','申甫生周日，宣慈举舜年。
何如偶昌运，比德迈前贤。
宠获元良密，荣瞻端揆迁。
职优三事老，位在百僚先。
北极回宸渥，南宫饰御筵。
飞文瑶札降，赐酒玉杯传。
谬列台衡重，俱承雨露偏。
誓将同竭力，相与效尘涓。','',''),('quantangshi-05389','奉和圣制同二相已下羣官乐游园宴','崔沔','quantangshi','','卷6','五日酺才毕，千年乐未央。
复承天所赐，终宴国之阳。
地胜春逾好，恩深乐更张。
落花飞广座，垂柳拂行觞。
庶尹陪三史，诸侯具万方。
酒酣同拚跃，歌舞咏时康。','',''),('quantangshi-05390','奉和圣制同二相已下羣臣乐游园宴','崔尚','quantangshi','','卷6','春日照长安，皇恩宠庶官。
合钱承罢宴，赐帛复追欢。
供帐凭高列，城池入迥宽。
花催相国醉，鸟和乐人弹。
北阙云中见，南山树杪看。
乐游宜缔赏，舞咏惜将阑。','',''),('quantangshi-05391','奉和圣制同二相以下羣官乐游园宴','胡皓','quantangshi','','卷6','五酺终宴集，三锡又欢娱。
仙阜崇高异，神州眺览殊。
南山临皓雪，北阙对明珠。
广座鵷鸿满，昌庭驷马趋。
绮罗含草树，丝竹吐郊衢。
衔杯不能罢，歌舞乐唐虞。','',''),('quantangshi-05392','奉和圣制送张尚书巡边','胡皓','quantangshi','','卷6','燕公为汉将，武德奉文思。
利用经戎莽，英图叶圣诒。
塞沙制长策，穷石卷摇旗。
万里要相贺，三边又在兹。
棱威方逐逐，谈笑坐怡怡。
宠饯纷郊道，充厨竭御司。
尝醪企行迈，听乐罢涟洏。
衮旒垂翰墨，缨蕤迭赋诗。
金山无积阻，玉树有华滋。
请迨炎风暮，归旌候此时。','',''),('quantangshi-05393','和宋之问寒食题临江驿','胡皓','quantangshi','','卷6','闻道山阴会，仍为火忌辰。
途中甘弃日，江上苦伤春。
流水飜催泪，寒灰更伴人。
丹心终不改，白发为谁新。','',''),('quantangshi-05394','出峡','胡皓','quantangshi','','卷6','巴东三峡尽，旷望九江开。
楚塞云中出，荆门水上来。
鱼龙潜啸雨，凫雁动成雷。
南国秋风晚，客思几悠哉。','',''),('quantangshi-05395','同蔡孚起居咏鹦鹉','胡皓','quantangshi','','卷6','鹦鹉殊姿致，鸾皇得比肩。
常寻金殿里，每话玉阶前。
贾谊才方达，扬雄老未迁。
能言既有地，何惜为闻天。','',''),('quantangshi-05396','大漠行','胡皓','quantangshi','','卷6','单于犯蓟堧，虏骑略萧边。
南山木叶飞下地，北海蓬根乱上天。
科斗连营太原道，鱼丽合阵武威川。
三军遥倚伏，万里相驰逐。
旌斾悠悠静潮源，鼙鼓喧喧动卢谷。
穷徼出幽陵，吁嗟倦寝兴。
马蹄冻溜石，胡毳暖生冰。
云沙泱漭天光闭，河塞阴沈海色凝。
崆峒北国谁能托，萧索边心常不乐。
近见行人畏白龙，遥闻公主愁黄鹤。
阳春半，岐路间，瑶台苑，玉门关。
百花芳树红将歇，二月兰臯绿未还。
阵云不散鱼龙水，雨雪犹飞鸿鹄山。
山嶂緜连那可极，路远辛勤梦颜色。
北堂萱草不寄来，东园桃李长相忆。
汉将纷纭攻战盈，胡寇萧条幽朔清。
韩昌拜节偏知送，郑吉驱旌坐见迎。
火绝烟沈左西极，谷静山空右北平。
但得将军能百胜，不须天子筑长城。','',''),('quantangshi-05397','朝退','李適之','quantangshi','','卷6','朱门长不闭，亲友恣相过。
年今将半百，不乐复如何。','',''),('quantangshi-05398','罢相作','李適之','quantangshi','','卷6','避贤初罢相，乐圣且衔杯。
为问门前客，今朝几个来。','',''),('quantangshi-05399','题汉州西湖','房琯','quantangshi','','卷6','高流缠峻隅，城下缅丘墟。
决渠信浩荡，潭岛成江湖。
结宇依回渚，水中信可居。
三伏气不蒸，四达暑自徂。
同人千里驾，邻国五马车。
月出共登舟，风生随所如。
举麾指极浦，欲极更盘纡。
缭绕各殊致，夜尽情有余。
遭乱意不开，即理还暂祛。
安得长晤语，使我忧更除。','',''),('quantangshi-05400','咏方圆动静','李泌','quantangshi','','卷6','方如行义，圆如用智。
动如逞才，静如遂意。','',''),('quantangshi-05401','长歌行','李泌','quantangshi','','卷6','天覆吾，地载吾，天地生吾有意无。
不然绝粒升天衢，不然鸣珂游帝都。
焉能不贵复不去，空作昂藏一丈夫。
一丈夫兮一丈夫，千生气志是良图。
请君看取百年事，业就扁舟泛五湖。','',''),('quantangshi-05402','奉和圣制中和节曲江宴百僚','李泌','quantangshi','','卷6','风俗时有变，中和节惟新。
轩车双阙下，宴会曲江滨。
金石何铿锵，簪缨亦纷纶。
皇恩降自天，品物感知春。
慈恩匝寰瀛，歌咏同君臣。','',''),('quantangshi-05403','奉和圣制重阳赐会聊示所怀','李泌','quantangshi','','卷6','大唐造昌运，品物荷时成。
乘秋逢令节，锡宴欢羣情。
俯临秦山川，高会汉公卿。
未追赤松子，且泛黄菊英。
赓歌圣人作，海内同休明。','',''),('quantangshi-05404','句','李泌','quantangshi','','卷6','青青东门柳，岁晏复憔悴。
良弓摧折久，谁识是龙韬。
旋沫翻成碧玉池，添酥散出琉璃眼。','',''),('quantangshi-05405','享太庙乐章 广运舞','郭子儀','quantangshi','','卷6','于赫皇祖，昭明有融。
惟文之德，惟武之功。
河海静谧，车书混同。
虔恭孝飨，穆穆玄风。','',''),('quantangshi-05406','享太庙乐章 保大舞','郭子儀','quantangshi','','卷6','于穆文考，圣神昭彰。
箫勺羣慝，含光远方。
万物茂遂，九夷宾王。
愔愔云韶，德音不忘。','',''),('quantangshi-05407','百子池','張諤','quantangshi','','卷6','旧闻百子汉家池，汉家渌水今逶迤。
宫女厌镜笑窥池，身前影后不相见。','',''),('quantangshi-05408','东封山下宴羣臣','張諤','quantangshi','','卷6','万里扈封峦，羣公遇此欢。
幔城连夜静，霜仗满空寒。
辇路宵烟合，旌门晓月残。
明朝陪圣主，山下礼圆坛。','',''),('quantangshi-05409','三日岐王宅','張諤','quantangshi','','卷6','玉女贵妃生，嫛婗始发声。
金盆浴未了，綳子绣初成。
翡翠雕芳缛，真珠帖小缨。
何时学健步？鬬取落花轻。','',''),('quantangshi-05410','满月','張諤','quantangshi','','卷6','社金流茂祉，庭玉表奇才。
竹似因谈植，兰疑入梦栽。
乌将八子去，凤逐九雏来。
今夜明珠色，当随满月开。','',''),('quantangshi-05411','岐王山亭','張諤','quantangshi','','卷6','王家傍绿池，春色正相宜。
岂有楼台好，兼看草树奇。
石榴天上叶，椰子日南枝。
出入千门里，年年乐未移。','',''),('quantangshi-05412','岐王席上咏美人','張諤','quantangshi','','卷6','半额画双蛾，盈盈烛下歌。
玉杯寒意少，金屋夜情多。
香艳王分帖，裙娇敕赐罗。
平阳莫相妬，唤出不如他。','',''),('quantangshi-05413','还京','張諤','quantangshi','','卷6','朱绂临秦望，皇华赴洛桥。
文章南渡越，书奏北归朝。
树入江云尽，城衔海月遥。
秋风将客思，川上晚萧萧。','',''),('quantangshi-05414','赠吏部孙员外济','張諤','quantangshi','','卷6','天子爱贤才，星郎入拜来。
明光朝半下，建礼直初回。
名带含香发，文随绮幕开。
披云自有镜，从此照仙台。','',''),('quantangshi-05415','送李着作倅杭州','張諤','quantangshi','','卷6','辍史空三署，题舆佐一方。
祖筵开霁景，征陌直朝光。
水陆风烟隔，秦吴道路长。
伫闻敷善政，邦国咏惟康。','',''),('quantangshi-05416','九日','張諤','quantangshi','','卷6','秋来林下不知春，一种佳游事也均。
绛叶从朝飞着夜，黄花开日未成旬。
将曛陌树频惊鸟，半醉归途数问人。
城远登高倂九日，茱萸凡作几年新。','',''),('quantangshi-05417','延平门高斋亭子应岐王教','張諤','quantangshi','','卷6','花源药屿凤城西，翠幕纱窗莺乱啼。
昨夜蒲萄初上架，今朝杨柳半垂堤。
片片仙云来渡水，双双燕子共衔泥。
请语东风催后骑，倂将歌舞向前溪。','',''),('quantangshi-05418','九日宴','張諤','quantangshi','','卷6','秋叶风吹黄飒飒，晴云日照白鳞鳞。
归来得问茱萸女，今日登高醉几人。','',''),('quantangshi-05419','从军','劉庭琦','quantangshi','','卷6','朔风吹寒塞，胡沙千万里。
阵云出岱山，孤月生海水。
决胜方求敌，衔恩本轻死。
萧萧牧马鸣，中夜拔劒起。','',''),('quantangshi-05420','奉和圣制瑞雪篇','劉庭琦','quantangshi','','卷6','紫宸飞雪晓裴回，层阁重门雪照开。
九衢皛耀浮埃尽，千品差池贽帛来。
何处田中非种玉，谁家院里不生梅？
埋云翳景无穷已，因风落地吹还起。
先过翡翠宝房中，转入鸳鸯金殿里。
美人含笑出联翩，艳逸相轻鬬容止。
罗衣点着浑是花，玉手抟来半成水。
奕奕纷纷何所如，顿忆杨园二月初。
羞同班女高秋扇，欲照明王乙夜书。
姑射山中符圣寿，芙蓉阙下降神车。
愿随睿泽流无限，长报丰年贵有余。','',''),('quantangshi-05421','咏木槿树题武进文明府厅','劉庭琦','quantangshi','','卷6','物情良可见，人事不胜悲。
莫恃朝荣好，君看暮落时。','',''),('quantangshi-05422','铜雀台','劉庭琦','quantangshi','','卷6','铜台宫观委灰尘，魏主园林漳水滨。
即今西望犹堪思，况复当时歌舞人。','',''),('quantangshi-05423','失白鹰','鄭繇','quantangshi','','卷6','白锦文章乱，丹霄羽翮齐。
云中呼暂下，雪里放还迷。
梁苑惊池鹜，陈仓拂野鸡。','',''),('quantangshi-05424','经慈涧题','鄭繇','quantangshi','','卷6','岸与恩同广，波将慈共深。
涓涓劳日夜，长似下流心。','',''),('quantangshi-05425','奉和御制平胡','韓休','quantangshi','','卷6','南牧正纷纷，长河起塞氛。
玉符征选士，金钺拜将军。
叠鼓摇边吹，连旌暗朔云。
祆星乘夜落，害气入朝分。
始见幽烽警，俄看烈火焚。
功成奏凯乐，战罢策归勋。
盛德陈清庙，神谟属大君。
叨荣逢偃羽，率舞咏时文。','',''),('quantangshi-05426','奉和圣制送张说巡边','韓休','quantangshi','','卷6','一德光台象，三军掌夏卿。
来威申庙略，出总叶师贞。
受钺辞金殿，凭轩去鼎城。
曙光摇组甲，疎吹绕云旌。
左律方先凯，中鼙即训兵。
定功彰武事，陈颂纪天声。
祖宴初留赏，宸章更宠行。
车徒零雨送，林野夕阴生。
路极河流远，川长朔气平。
南辕迟返斾，归奏谒承明。','',''),('quantangshi-05427','祭汾阴乐章','韓休','quantangshi','','卷6','于穆浚哲，维清缉熙。
肃事昭配，永言孝思。
涤濯静嘉，馨香在兹。
神之听之，用受福厘。','',''),('quantangshi-05428','征君宅','許景先','quantangshi','','卷6','征君昔嘉遯，抗迹遗俗尘。
了心悟有物，乘化游无垠。
道丧历千载，复存颍阳真。
上虞佳山水，晚岁耽隐沦。
内史既解绶，支公亦相亲。
儒道匪远理，意胜聊自欣。
洄沿南溪夕，流浪东山春。
石壁践丹景，金潭冒绿苹。
探炼备海峤，赏心寓情人。
奈何灵仙骨，锹翮瑶池津。
寥寥虚白宇，夙剏招提因。
家风缅多尚，玄德谢无邻。
谬陪金门彦，矫迹侍紫宸。
皇恩竟已矣，遗烈庶不泯。','',''),('quantangshi-05429','折柳篇','許景先','quantangshi','','卷6','春色东来度渭桥，青门垂柳百千条。
长杨西连建章路，汉家林苑纷无数。
萦花始遍合欢枝，游丝半罥相思树。
春楼初日照南隅，柔条垂绿扫金铺。
宝钗新梳倭堕髻，锦带交垂连理襦。
自怜柳塞淹戎幕，银烛长啼愁梦着。
芳树朝催玉管新，春风夜染罗衣薄。
城头杨柳已如丝，今年花落去年时。
折芳远寄相思曲，为惜容华难再持。','',''),('quantangshi-05430','奉和御制春台望','許景先','quantangshi','','卷6','睿德在青阳，高居视中县。
秦城连凤阙，汉寝疏龙殿。
文物照光辉，郊畿郁葱蒨。
千门望成锦，八水明如练。
复道晓光披，宸游出禁移。
瑞气朝浮五云阁，祥光夜吐万年枝。
兰叶负龟初荐祉，桐花集凤更来仪。
秦汉生人凋力役，阿房甘泉构云碧。
汾祠雍畤望通天，玉堂宣室坐长年。
鼓钟西接咸阳观，苑囿南通鄠杜田。
明主卑宫诫前失，辅德钦贤政惟一。
昆虫不夭在春搜，稼穑常艰重农术。
邦家已荷圣谟新，犹闻俭陋惜中人。
豫奉北辰齐七政，长歌东武拚千春。','',''),('quantangshi-05431','阳春怨','許景先','quantangshi','','卷6','红树晓莺蹄，春风暖翠闺。
雕笼熏绣被，珠履踏金堤。
芍药花初吐，菖蒲叶正齐。
藁砧当此日，行役向辽西。','',''),('quantangshi-05432','奉和圣制送张尚书巡边','許景先','quantangshi','','卷6','文武承邦式，风云感国祯。
王师亲赋政，庙略久论兵。
汉主知三杰，周官统六卿。
四方分阃受，千里坐谋成。
介胄辞前殿，壶觞宿左营。
赏延颁赐重，宸赠出车荣。
龙武三军气，鱼铃五校名。
郊云驻旌羽，边吹引金钲。
训旅方称德，安人更克贞。
伫看铭石罢，同听凯歌声。','',''),('quantangshi-05433','咏史','王丘','quantangshi','','卷6','高洁非养正，盛名亦险艰。
伟哉谢安石，携妓入东山。
云岩响金奏，空水灧朱颜。
兰露滋香泽，松风鸣佩环。
歌声入空尽，舞影到池闲。
杳眇同天上，繁华非代间。
卷舒混名迹，纵诞无忧患。
何必苏门子，冥然闭清关。','',''),('quantangshi-05434','奉和圣制答张说扈从南出鼠雀谷之作','王丘','quantangshi','','卷6','襟带三秦接，旗常万乘过。
阳原淑气早，阴谷冱寒多。
花缛前茅仗，霜严后殿戈。
代云开晋岭，江雁入汾河。
北土分尧俗，南风动舜歌。
一闻天乐唱，恭逐万人和。','',''),('quantangshi-05435','奉和圣制送张尚书巡边','王丘','quantangshi','','卷6','德业蕴时宗，幽符梦象通。
台司计祈父，师律总元戎。
出入敷能政，谋猷体至公。
赠行光睿什，宴别感宸衷。
文炳高天曜，恩垂湛露融。
建牙之塞表，鸣鼓接云中。
策密鬼神祕，威成剑骑雄。
朔门正炎月，兵气已秋风。
肃杀从此始，方知胡运穷。','',''),('quantangshi-05436','过贾六','蘇晉','quantangshi','','卷6','主人病且闲，客来情弥适。
一酌复一笑，不知日将夕。
昨来属欢游，于今尽成昔。
努力持所趣，空名定何益。','',''),('quantangshi-05437','奉和圣制送张说巡边','蘇晉','quantangshi','','卷6','方汉比周年，兴王合在宣。
亟闻降虏拜，复覩出师篇。
祈父万邦式，英猷三略传。
算车申夏政，茇舍启戎田。
严问盟胡苑，军容济洛川。
皇情怅关斾，诏饯列郊筵。
路接禁园草，池分御井莲。
离声轸去角，居念断归蝉。
三捷岂云尔，七擒良信然。
具僚诚寄望，奏凯秋风前。','',''),('quantangshi-05438','奉和圣制送张说巡边','崔禹錫','quantangshi','','卷6','供帐何煌煌，公其抚朔方。
羣僚咸饯酌，明主降离章。
关塞重门下，郊岐禁苑傍。
练兵宜雨洗，卧鼓候风凉。
炎景宁云惮，神谋肃所将。
旌摇天月迥，骑入塞云长。
赫赫皇威振，油油圣泽滂。
非惟按车甲，兼以正封疆。
叱诧阴山道，澄清翰海阳。
虏垣行决胜，台座伫为光。','',''),('quantangshi-05439','恩敕尚书省僚宴昆明池应制','張嘉貞','quantangshi','','卷6','灵沼初开汉，神池旧浴尧。
昔人徒习武，明代此闻韶。
地脉山川胜，天恩雨露饶。
时光牵利舸，春淑覆柔条。
芳酝酲千日，华牋落九霄。
幸承欢赉重，不觉醉归遥。','',''),('quantangshi-05440','奉和早登太行山中言志应制','張嘉貞','quantangshi','','卷6','明发扈山巅，飞龙高在天。
山南平对巩，山北远通燕。
瞻彼冈峦峻，凭兹士马妍。
九圻行若砥，万谷辗如川。
罗网开三面，闾阎问百年。
泽将春雪比，文共晓星连。
徯后逢今圣，登台谢曩贤。
唯余事君节，不让古人先。','',''),('quantangshi-05441','奉和圣制送张说巡边','張嘉貞','quantangshi','','卷6','天锡我宗盟，元戎付夏卿。
多才兼将相，必勇独横行。
经纬称人杰，文章作代英。
山川看是阵，草木想为兵。
不待河冰合，犹防塞月明。
有谋当系丑，无战且绥氓。
阃外传三略，云中冀一平。
感恩同义激，怅别屡魂惊。
直视前旌掣，遥闻后骑鸣。
还期方定日，复此出郊迎。','',''),('quantangshi-05442','句','張嘉貞','quantangshi','','卷6','河鱼未上冻，江蛰已闻雷。','',''),('quantangshi-05443','奉和圣制送张说巡边','盧從愿','quantangshi','','卷6','上将发文昌，中军静朔方。
占星引旌节，择日拜坛场。
礼乐临轩送，威声出塞扬。
安边俟帷幄，制胜在岩廊。
作鼓将军气，投醪壮士觞。
戒途遵六月，离赠动三光。
槐路清梅暑，蘅臯起麦凉。
时文仰雄伯，耀武震遐荒。
衽席知无战，兵戈示不忘。
伫闻歌杕杜，凯入系名王。','',''),('quantangshi-05444','祭汾阴乐章','盧從愿','quantangshi','','卷6','坤元载物，阳乐发生。
播植资始，品汇咸亨。
列俎棊布，方坛砥平。
神歆禋祀，后德惟明。','',''),('quantangshi-05445','长门怨','袁暉','quantangshi','','卷6','早知君爱歇，本自无萦妒。
谁使恩情深，今来反相误。
愁眠罗帐晓，泣坐金闺暮。
独有梦中魂，犹言意如故。','',''),('quantangshi-05446','铜雀妓','袁暉','quantangshi','','卷6','君爱本相饶，从来似舞腰。
那堪攀玉座，肠断望陵朝。
怨着情无主，哀凝曲不调。
况临松日暮，悲吹坐萧萧。','',''),('quantangshi-05447','正月闺情','袁暉','quantangshi','','卷6','正月金闺里，微风绣户间。
晓魂怜别梦，春思逼啼颜。
遶砌梅堪折，当轩树未攀。
岁华庭北上，何日度阳关。','',''),('quantangshi-05448','二月闺情','袁暉','quantangshi','','卷6','二月韶光好，春风香气多。
园中花巧笑，林里鸟能歌。
有恨离琴瑟，无情着绮罗。
更听春燕语，妾亦不如他。','',''),('quantangshi-05449','三月闺情','袁暉','quantangshi','','卷6','三月春将尽，空房妾独居。
蛾眉愁自结，鬓髪没情梳。
□□□□□，□□□□□。
□□□□□，□□□□□。','',''),('quantangshi-05450','七月闺情','袁暉','quantangshi','','卷6','七月坐凉宵，金波满丽谯。
容华芳意改，枕席怨情饶。
锦字沾愁泪，罗裙缓细腰。
不如银汉女，岁岁鹊成桥。','',''),('quantangshi-05451','奉和圣制答张说扈从南出雀鼠谷之作','袁暉','quantangshi','','卷6','魏国山河险，周王警跸回。
九旗云际出，万骑谷中来。
石路行将尽，烟郊望忽开。
赏矜垂柳报，春畏落花催。
兴逸横汾什，恩褒作颂才。
小臣瞻日月，延首咏康哉。','',''),('quantangshi-05452','奉和圣制送张尚书巡边','袁暉','quantangshi','','卷6','出师宣九命，分阃用三台。
始应幕中画，言从天上来。
丹青不独任，韬略遂双该。
坐见威棱洽，弥彰事业恢。
旌旗晓云送，鞞鼓朔风催。
虏气消残月，边声韵落梅。
羽书雄北地，龙漠寝南垓。
宠战黄金尽，输诚白日回。
离章宸翰发，祖宴国门开。
欲识恩华盛，平生文武材。','',''),('quantangshi-05453','奉和圣制答张说扈从南出雀鼠谷','王光庭','quantangshi','','卷6','省俗恩将遍，巡方路稍回。
寒随汾谷尽，春逐晋郊来。
云骑传行漏，烟旄引从台。
惠风初应律，和气正调梅。
雅颂通宸咏，天文接曙台。
灞陵桃李色，应待日华开。','',''),('quantangshi-05454','奉和圣制送张说巡边','王光庭','quantangshi','','卷6','贤相德符充，朝推文武雄。
海波先若镜，关草豫从风。
钺助将军勇，威成天子功。
琼章九霄发，锡宴五衢通。
玉辗龙盘带，金装凤勒骢。
虎貔纷儗儗，河洛振熊熊。
戈剑千霜白，旌旗万火红。
示刑夷夏变，流惠鬼方同。
寇息军容偃，尘销朔野空。
用师敷礼乐，非是为獯戎。','',''),('quantangshi-05455','奉和圣制送张说巡边','徐知仁','quantangshi','','卷6','圣德膺三统，皇恩被八埏。
大明均照物，小丑未宁边。
国相台衡重，元戎庙略宣。
紫泥方受命，黄石乃推贤。
问辠阴山下，安人属国前。
度关行照月，乘障坐消烟。
北阙纡宸藻，南桥列祖筵。
耀威当夏日，杀气指秋天。
鞞鼓鼋鼍振，旌旗鸟兽悬。
由来词翰手，今见勒燕然。','',''),('quantangshi-05456','奉和勅赐公主镜','席豫','quantangshi','','卷6','令节颁龙镜，仙辉下凤台。
含灵万象入，写照百花开。
色与皇明散，光随圣泽来。
妍媸冰鉴里，从此愧非才。','',''),('quantangshi-05457','江行纪事二首 一','席豫','quantangshi','','卷6','飘颻任舟楫，回合傍江津。
后浦情犹在，前山赏更新。
树深烟幂幂，滩浅石磷磷。
川路南行远，淹留惜此辰。','',''),('quantangshi-05458','江行纪事二首 二','席豫','quantangshi','','卷6','江汛春风势，山楼曙月辉。
猿攀紫岩饮，鸟拂清潭飞。
古树崩沙岸，新苔覆石矶。
津途赏无限，征客蹔忘归。','',''),('quantangshi-05459','奉和圣制答张说南出雀鼠谷','席豫','quantangshi','','卷6','鸣銮初幸代，旋盖欲横汾。
山尽千旗出，郊平五校分。
前林已暄景，后壑尚寒氛。
风送箫韶曲，花铺黼黻文。
盐梅推上宰，礼乐统中军。
献赋纡天札，飘颻飞白云。','',''),('quantangshi-05460','奉和圣制送张说巡边','席豫','quantangshi','','卷6','圣主重兵权，分符属大贤。
中军仍执政，丞相复巡边。
翕习戎装动，张皇庙略宣。
朝荣承睿札，野饯转行旃。
亭障东缘海，沙场北际天。
春冬见岩雪，朝夕候烽烟。
已勒封山记，犹闻遣戍篇。
五营将月合，八阵与云连。
经略图方远，怀柔道更全。
归来画麟阁，蔼蔼武功传。','',''),('quantangshi-05461','祭汾阴乐章','韓思復','quantangshi','','卷6','大乐和畅，殷荐明神。
一降通感，八变必臻。
有求斯应，无德不亲。
降灵醉止，休征万人。','',''),('quantangshi-05462','祭汾阴乐章','劉晃','quantangshi','','卷6','大君出震，有事郊禋。
斋戒既肃，馨香毕陈。
乐和礼备，候暖风春。
恭惟降福，实赖明神。','',''),('quantangshi-05463','唐禅社首乐章 顺和','賀知章','quantangshi','','卷6','至哉含柔德，万物资以生。
常顺称厚载，流谦通变盈。
圣心事能察，增广陈厥诚。
黄只僾如在，泰折俟咸亨。','',''),('quantangshi-05464','太和','賀知章','quantangshi','','卷6','肃我成命，于昭黄只。
裘冕而祀，陟降在斯。
五音克备，八变聿施。
缉熙肆靖，厥心匪离。','',''),('quantangshi-05465','太和 肃和','賀知章','quantangshi','','卷6','黄只是祗，我其夙夜。
夤畏诚絜，匪遑宁舍。
礼以琮玉，荐厥茅藉。
念兹降康，胡宁克暇。','',''),('quantangshi-05466','太和 雍和','賀知章','quantangshi','','卷6','夙夜宥密，不敢宁宴。
五齐既陈，八音在县。
粢盛以絜，房俎斯荐。
惟德惟馨，尚兹克徧。','',''),('quantangshi-05467','太和 寿和','賀知章','quantangshi','','卷6','惟以明发，有怀载殷。
乐盈而反，礼顺其禋。
立清以献，荐欲是亲。
于穆不已，裒对斯臻。','',''),('quantangshi-05468','太和 福和','賀知章','quantangshi','','卷6','穆穆天子，告成岱宗。
大裘如濡，执珽有颙。
乐以平志，礼以和容。
上帝临我，云胡肃邕。','',''),('quantangshi-05469','太和 太和','賀知章','quantangshi','','卷6','昭昭有唐，天俾万国。
列祖应命，四宗顺则。
申锡无疆，宗我同德。
曾孙继绪，享神配极。','',''),('quantangshi-05470','太和 晚发','賀知章','quantangshi','','卷6','江臯闻曙钟，轻栧理还舼。
海潮夜约约，川露晨溶溶。
始见沙上鸟，犹埋云外峰。
故乡杳无际，明发怀朋从。','',''),('quantangshi-05471','奉和御制春台望','賀知章','quantangshi','','卷6','青阳布王道，玄览陶真性。
欣若天下春，高逾域中圣。
神臯类观赏，帝里如悬镜。
缭绕八川浮，岧峣双阙映。
晓色徧昭阳，晴云卷建章。
华滋的皪丹青树，颢气氤氲金玉堂。
尚有灵蛇下鄜畤，还征瑞宝入陈仓。
自昔秦奢汉穷武，后庭万余宫百数。
旗回五丈殿千门，连绵南隥出西垣。
广画螓蛾夸窈窕，罗生玳瑁象昆仑。
廼睠天晴兴隐恤，古来土木良非一。
荆临章观赵丛台，何如尧阶将禹室。
层栏䆗窱下龙舆，清管逶迤半绮疏。
一听南风引鸾舞，长谣北极仰鹑居。','',''),('quantangshi-05472','望人家桃李花','賀知章','quantangshi','','卷6','山源夜雨度仙家，朝发东园桃李花。
桃花红兮李花白，照灼城隅复南陌。
南陌青楼十二重，春风桃李为谁容。
弃置千金轻不顾，踟蹰五马谢相逢。
徒言南国容华晚，遂叹西家飘落远。
的皪长奉明光殿，氛氲半入披香苑。
苑中珍木元自奇，黄金作叶白银枝。
千年万岁不凋落，还将桃李更相宜。
桃李从来露井傍，成蹊结影矜艳阳。
莫道春花不可树，会持仙实荐君王。','',''),('quantangshi-05473','送人之军','賀知章','quantangshi','','卷6','常经绝脉塞，复见断肠流。
送子成今别，令人起昔愁。
陇云晴半雨，边草夏先秋。
万里长城寄，无贻汉国忧。','',''),('quantangshi-05474','奉和圣制送张说上集贤学士赐宴赋得谟字','賀知章','quantangshi','','卷6','西学垂玄览，东堂发圣谟。
天光烛武殿，时宰集鸿都。
枯朽霑皇泽，翾飞舞帝梧。
迹同游汗漫，荣是出泥涂。
三叹承汤鼎，千欢接舜壶。
微躯不可答，空欲咏依蒲。','',''),('quantangshi-05475','奉和圣制送张说巡边','賀知章','quantangshi','','卷6','荒憬尽怀忠，梯航已自通。
九攻虽不战，五月尚持戎。
遣戍征周牒，恢边重汉功。
选车命元宰，授律取文雄。
胄出天弧上，谋成帝幄中。
诏旗分夏物，专土锡唐弓。
帐宿伊川右，钲传晋苑东。
饔人藉蕡实，乐正理丝桐。
岐陌涵余雨，离川照晚虹。
恭闻咏方叔，千载舞皇风。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-05476','题袁氏别业','賀知章','quantangshi','','卷6','主人不相识，偶坐为林泉。
莫谩愁沽酒，囊中自有钱。','',''),('quantangshi-05477','咏柳','賀知章','quantangshi','','卷6','碧玉妆成一树高，万条垂下绿丝縧。
不知细叶谁裁出，二月春风似剪刀。','',''),('quantangshi-05478','采莲曲','賀知章','quantangshi','','卷6','稽山罢雾郁嵯峨，镜水无风也自波。
莫言春度芳菲尽，别有中流采芰荷。','',''),('quantangshi-05479','回乡偶书二首 一','賀知章','quantangshi','','卷6','少小离家老大回，乡音难改鬓毛衰。
儿童相见不相识，笑问客从何处来。','',''),('quantangshi-05480','回乡偶书二首 二','賀知章','quantangshi','','卷6','离别家乡岁月多，近来人事半销磨。
唯有门前镜湖水，春风不改旧时波。','',''),('quantangshi-05481','答朝士','賀知章','quantangshi','','卷6','鈒镂银盘盛蛤蜊，镜湖莼菜乱如丝。
乡曲近来隹此味，遮渠不道是吴儿。','',''),('quantangshi-05482','句','賀知章','quantangshi','','卷6','落花真好些，一醉一回颠。','',''),('quantangshi-05483','敬酬张九龄当涂界留赠之作','裴耀卿','quantangshi','','卷6','茂先寔王佐，仲举信时英。
气覩冲天发，人将下榻迎。
圭符肃有命，江国远徂征。
九派期方越，千钧或所轻。
高帆出风迥，孤屿入云平。
遄迈嗟于役，离忧空自情。
餙簪陪早岁，接壤厕专城。
旷别心弥轸，宏规义转倾。
徒然恨饥渴，况乃讽瑶琼。','',''),('quantangshi-05484','酬张九龄使风见示','裴耀卿','quantangshi','','卷6','兹地五湖隣，艰哉万里人。
惊飙翻是托，危浪亦相因。
宣室才华子，金闺讽议臣。
承明有三人，去去速归轮。','',''),('quantangshi-05485','赠张丞相','鼎','quantangshi','','卷6','汉上登飞幰，荆南历旧居。
已尝临砌橘，更覩跃池鱼。
盛德继微渺，深衷能卷舒。
义申蓬阁际，情切庙堂初。
郡挹文章美，人怀燮理余。
皇恩傥照亮，岂厌承明庐。','',''),('quantangshi-05486','酬故人还山','鼎','quantangshi','','卷6','举棹乘春水，归山抚岁华。
碧潭宵见月，红树晚开花。
肃穆轻风度，依微隐径斜。
危亭暗松石，幽涧落云霞。
思鸟吟高树，游鱼戏浅沙。
安知余兴尽，相望紫烟赊。','',''),('quantangshi-05487','和张荆州九龄晨出郡舍林下','崔頌','quantangshi','','卷6','优闲表政清，林薄赏秋成。
江上悬晓月，往来亏复盈。
天云抗真意，郡阁晦高名。
坐啸应无欲，宁辜济物情。','',''),('quantangshi-05488','奉酬张洪州九龄江上见赠','孫翃','quantangshi','','卷6','受命谳封疆，逢君牧豫章。
于焉审虞芮，复尔共舟航。
怅别秋阴尽，怀归客思长。
江臯枉离赠，持此慰他乡。','',''),('quantangshi-05489','古意赠孙翃','徐仁友','quantangshi','','卷6','南望缑氏岭，山居共涧阴。
东西十数里，缅邈方寸心。
云日落广厦，莺花对孤琴。
琴中多苦调，凄切谁复寻。','',''),('quantangshi-05490','奉和姚令公驾幸温汤喜雪应制','蘇綰','quantangshi','','卷6','汉主新丰邑，周王尚父师。
云符沛童唱，雪应海神期。
林变惊春早，山明讶夕迟。
况逢温液霈，恩重御裘诗。','',''),('quantangshi-05491','咏月','康庭芝','quantangshi','','卷6','天使下西楼，光含万里秋。
台前疑挂镜，帘外似悬钩。
张尹将眉学，班姬取扇俦。
佳期应借问，为报在刀头。','',''),('quantangshi-05492','山行见孤松成咏','張宣明','quantangshi','','卷6','孤松郁山椒，肃爽凌清霄。
既挺千丈干，亦生百尺条。
青青恒一色，落落非一朝。
大厦今已构，惜哉无人招。
寒霜十二月，枝叶独不凋。','',''),('quantangshi-05493','使至三姓咽面','張宣明','quantangshi','','卷6','昔闻班家子，笔砚忽然投。
一朝抚长劒，万里入荒陬。
岂不服艰险，只思清国讐。
山川去何岁，霜露几逢秋。
玉塞已遐廓，铁关方阻修。
东都日窅窅，西海此悠悠。
卒使功名建，长封万里侯。','',''),('quantangshi-05494','新都南亭别郭大元振','盧崇道','quantangshi','','卷6','竹径女萝蹊，莲洲文石堤。
静深人俗断，寻翫往还迷。
碧潭秀初月，素林惊夕栖。
褰幌纳鸟侣，罢琴听猨啼。
佳辰改宿昔，胜寄在暌携。
长怀赏心爱，如玉复如圭。','',''),('quantangshi-05495','登翅头山题俨公石壁','包融','quantangshi','','卷6','晨登翅头山，山曛黄雾起。
却瞻迷向背，直下失城市。
暾日衔东郊，朝光生邑里。
扫除诸烟氛，照出众楼雉。
青为洞庭山，白是太湖水。
苍茫远郊树，倏忽不相似。
万象以区别，森然共盈几。
坐令开心胸，渐觉落尘滓。
北岩千余仞，结庐谁家子。
愿陪中峯游，朝暮白云里。','',''),('quantangshi-05496','阮公啸台','包融','quantangshi','','卷6','荒台森荆杞，蒙笼无上路。
传是古人迹，阮公长啸处。
至今清风来，时时动林树。
逝者共已远，升攀想遗趣。
静然荒榛门，久之若有悟。
灵光未歇灭，千载知仰慕。','',''),('quantangshi-05497','酬忠公林亭','包融','quantangshi','','卷6','江外有真隐，寂居岁已侵。
结庐近西术，种树久成阴。
人迹乍及户，车声遥隔林。
自言解尘事，咫尺能辎尘。
为道岂庐霍，会静由吾心。
方秋院木落，仰望日萧森。
持我兴来趣，采菊行相寻。
尘念到门尽，远情对君深。
一谈入理窟，再索破幽襟。
安得山中信，致书移尚禽。','',''),('quantangshi-05498','送国子张主簿','包融','quantangshi','','卷6','湖岸缆初解，莺啼别离处。
遥见舟中人，时时一回顾。
坐悲芳岁晚，花落青轩树。
春梦随我心，悠扬逐君去。','',''),('quantangshi-05499','和陈校书省中翫雪','包融','quantangshi','','卷6','芸阁朝来雪，飘颻正满空。
褰开明月下，校理落花中。
色向怀铅白，光因翰简融。
能令草玄者，回思入流风。','',''),('quantangshi-05500','和崔会稽咏王兵曹厅前涌泉势城中字','包融','quantangshi','','卷6','茂德来征应，流泉入咏歌。
含灵符上善，作字表中和。
有草恒垂露，无风欲偃波。
为看人共水，清白定谁多。','',''),('quantangshi-05501','赋得岸花临水发','包融','quantangshi','','卷6','笑笑傍溪花，丛丛逐岸斜。
朝开川上日，夜发浦中霞。
照灼如临镜，䒠茸胜浣纱。
春来武陵道，几树落仙家。','',''),('quantangshi-05502','武陵桃源送人','包融','quantangshi','','卷6','武陵川径入幽遐，中有鸡犬秦人家。
先时见者为谁耶，源水今流桃复花。','',''),('quantangshi-05503','和荐福寺英公新构禅堂','丁仙芝','quantangshi','','卷6','上人久弃世，中道自忘筌。
寂照出羣有，了心清众缘。
所以于此地，筑馆开青莲。
果药罗砌下，烟虹垂户前。
咒中洒甘露，指处流香泉。
禅远目无事，体清宵不眠。
枳闻庐山法，松入汉阳禅。
一枕西山外，虚舟常浩然。','',''),('quantangshi-05504','赠朱中书','丁仙芝','quantangshi','','卷6','十年种田滨五湖，十年遭涝尽为芜。
频年井税常不足，今年缗钱谁为输。
东邻转谷五之利，西邻贩缯日已贵。
而我守道不迁业，谁能肯敢效此事。
紫微侍郎白虎殿，出入通籍回天眷。
晨趋彩笔柏梁篇，昼出雕盘大官膳。
会应怜尔居素约，可即长年守贫贱。','',''),('quantangshi-05505','戏赠姚侍御','丁仙芝','quantangshi','','卷6','繁霜晓幕鸣柏乌，待子兽炭然金炉。
重门启锁紫髯胡，新披骢马陇西驹。
头戴獬豸急晨趋，明光殿前见天子，今日应弹佞幸夫。','',''),('quantangshi-05506','余杭醉歌赠吴山人','丁仙芝','quantangshi','','卷6','晓幕红襟燕，春城白项乌。
只来梁上语，不向府中趋。
城头坎坎鼓声曙，满庭新种樱桃树。
桃花昨夜撩乱开，当轩发色映楼台。
十千兑得余杭酒，二月春城长命杯。
酒后留君待明月，还将明月送君回。','',''),('quantangshi-05507','京中守岁','丁仙芝','quantangshi','','卷6','守岁多然烛，通宵莫掩扉。
客愁当暗满，春色向明归。
玉斗巡初匝，银河落渐微。
开正献岁酒，千里间庭闱。','',''),('quantangshi-05508','渡扬子江','丁仙芝','quantangshi','','卷6','桂檝中流望，空波两畔明。
林开扬子驿，山出润州城。
海尽边阴静，江寒朔吹生。
更闻风叶下，淅沥度秋声。','',''),('quantangshi-05509','长宁公主旧山池','丁仙芝','quantangshi','','卷6','平阳旧池馆，寂寞使人愁。
座卷流黄簟，帘垂白玉钩。
庭闲花自落，门闭水空流。
追想吹箫处，应随仙鹤游。','',''),('quantangshi-05510','剡溪馆闻笛','丁仙芝','quantangshi','','卷6','夜久闻羗笛，寥寥虚客堂。
山空响不散，溪静曲宜长。
草木生边气，城池泛夕凉。
虚然异风出，仿髴宿平阳。','',''),('quantangshi-05511','越裳贡白雉','丁仙芝','quantangshi','','卷6','圣哲承休运，伊夔列上台。
覃恩丹徼远，入贡素翚来。
北阙欣初见，南枝顾未回。
歛容残雪净，矫翼片云开。
驯扰将无惧，翻飞幸不猜。
甘从上林里，饮啄自徘徊。','',''),('quantangshi-05512','江南曲五首 一','丁仙芝','quantangshi','','卷6','长干斜路北，近浦是儿家。
有意来相访，明朝出浣纱。','',''),('quantangshi-05513','江南曲五首 二','丁仙芝','quantangshi','','卷6','发向横塘口，船开值急流。
知郎旧时意，且请拢船头。','',''),('quantangshi-05514','江南曲五首 三','丁仙芝','quantangshi','','卷6','昨暝逗南陵，风声波浪阻。
入浦不逢人，归家谁信汝。','',''),('quantangshi-05515','江南曲五首 四','丁仙芝','quantangshi','','卷6','未晓已成妆，乘潮去茫茫。
因从京口渡，使报邵陵王。','',''),('quantangshi-05516','江南曲五首 五','丁仙芝','quantangshi','','卷6','始下芙蓉楼，言发琅琊岸。
急为打船开，恶许傍人见。','',''),('quantangshi-05517','句','丁仙芝','quantangshi','','卷6','穷花常闭户，秋城闻捣衣。
树回早秋色，川长迟落晖。','',''),('quantangshi-05518','石桥琪树','蔡隱丘','quantangshi','','卷6','山上天将近，人间路渐遥。
谁当云里见，知欲渡仙桥。','',''),('quantangshi-05519','句','蔡隱丘','quantangshi','','卷6','整巾千嶂耸，曳履百泉鸣。','',''),('quantangshi-05520','奉和扈从温泉宫承恩赐浴','蔡希周','quantangshi','','卷6','天行云从指骊宫，浴日余波锡诏同。
彩殿氤氲拥香溜，纱窗宛转闭和风。
来将兰气冲皇泽，去引星文捧碧空。
自怜遇坎便能止，愿托仙槎路未通。','',''),('quantangshi-05521','同家兄题渭南王公别业','蔡希寂','quantangshi','','卷6','好闲知在家，退迹何必深。
不出人境外，萧条江海心。
轩车自来往，空名对清阴。
川涘将钓玉，乡亭期散金。
素晖射流濑，翠色緜森林。
曾为诗书癖，宁惟耕稼任。
吾兄许微尚，枉道来相寻。
朝庆老莱服，夕闲安道琴。
文章遥颂美，寤寐增所钦。
既郁苍生望，明时岂陆沈。','',''),('quantangshi-05522','登福先寺上方然公禅室','蔡希寂','quantangshi','','卷6','名都标佛刹，梵构临河干。
举目上方峻，森森青翠攒。
步登诸劫尽，忽造浮云端。
当暑敞扃闼，却嫌絺綌寒。
禅房最高顶，静者殊闲安。
疎雨向空城，数峯帘外盘。
午钟振衣坐，招我同一餐。
真味杂饴露，众香唯茝兰。
晚来恣偃俛，茶果仍留欢。','',''),('quantangshi-05523','陕中作','蔡希寂','quantangshi','','卷6','西别秦关近，东行陕服长。
川原余让畔，歌吹忆遗棠。
河水流城下，山云起路傍。
更怜栖泊处，池馆绕林篁。','',''),('quantangshi-05524','洛阳客舍逢祖咏留宴','蔡希寂','quantangshi','','卷6','緜緜钟漏洛阳城，客舍贫居绝送迎。
逢君贳酒因成醉，醉后焉知世上情。','',''),('quantangshi-05525','赠张敬微','蔡希寂','quantangshi','','卷6','大河东北望桃林，杂树冥冥结翠阴。
不知君作神仙尉，特讶行来云雾深。','',''),('quantangshi-05526','江风行','張潮','quantangshi','','卷6','壻贫如珠玉，壻富如埃尘。
贫时不忘旧，富日多宠新。
妾本富家女，与君为偶匹。
惠好一何深，中门不曾出。
妾有绣衣裳，葳蕤金缕光。
念君贫且贱，易此从远方。
远方三千里，思君心未已。
日暮情更来，空望去时水。
孟夏麦始秀，江上多南风。
商贾归欲尽，君今尚巴东。
巴东有巫山，窈窕神女颜。
常恐游此方，果然不知还。','',''),('quantangshi-05527','襄阳行','張潮','quantangshi','','卷6','玉盘转明珠，君心无定准。
昨见襄阳客，剩说襄阳好无尽。
襄汉水，岘山垂，汉水东流风北吹。
只言一世长娇宠，那悟今朝见别离。
君渡清羗渚，知人独不语。
妾见鸟栖林，忆君相思深。
莫作云间鸿，离声顾俦侣。
尚如匣中劒，分形会同处。
是君妇，识君情，怨君恨君为此行。
下牀一宿不可保，况乃万里襄阳城。
襄阳传近大堤北，君到襄阳莫回惑。
大堤诸女儿，怜钱不怜德。','',''),('quantangshi-05528','采莲词','張潮','quantangshi','','卷6','朝出沙头日正红，晚来云起半江中。
赖逢邻女曾相识，并着莲舟不畏风。','',''),('quantangshi-05529','江南行','張潮','quantangshi','','卷6','茨菰叶烂别西湾，莲子花开犹未还。
妾梦不离江水上，人传郎在凤凰山。','',''),('quantangshi-05530','长干行','張潮','quantangshi','','卷6','忆昔深闺里，烟尘不曾识。
嫁与长干人，沙头候风色。
五月南风兴，思君下巴陵。
八月西风起，想君发[扬]子。
去来悲如何，见少离别多。
湘潭几日到，妾梦越风波。
昨夜狂风度，吹折江头树。
淼淼暗无边，行人在何处。
北客真三公，朱衣满江中。
薄暮来投宿，数朝不肯东。
好乘浮云骢，佳期兰渚东。
鸳鸯绿浦上，翡翠锦屏中。
自怜十五余，颜色桃花红。
那作商人妇，愁水复愁风。','',''),('quantangshi-05531','句','張潮','quantangshi','','卷6','寒林苞晚橘，风絮露垂杨。','',''),('quantangshi-05532','游栖霞寺','張翬','quantangshi','','卷6','跻险入幽林，翠微含竹殿。
泉声无休歇，山色时隐见。
潮来杂风雨，梅落成霜霰。
一从方外游，顿觉尘心变。','',''),('quantangshi-05533','绝句','張翬','quantangshi','','卷6','茫茫烟上水，日暮阴云飞。
孤坐正愁绪，湖南谁捣衣。','',''),('quantangshi-05534','潘司马别业','周瑀','quantangshi','','卷6','门对青山近，汀牵绿草长。
寒深包晚橘，风紧落垂杨。
湖畔闻渔唱，天边数雁行。
萧然有高士，清思满书堂。','',''),('quantangshi-05535','送潘三入京','周瑀','quantangshi','','卷6','故人嗟此别，相送出烟坰。
柳色分官路，荷香入水亭。
离歌未尽曲，酌酒共忘形。
把手河桥上，孤山日暮青。','',''),('quantangshi-05536','临川山行','周瑀','quantangshi','','卷6','朝见青山雪，暮见青山云。
云山无断绝，秋思日纷纷。','',''),('quantangshi-05537','清溪馆作','談戭','quantangshi','','卷6','指途清溪里，左右唯深林。
云蔽望乡处，雨愁为客心。
遇人多物役，听鸟时幽音。
何必沧浪水，庶兹浣尘襟。','',''),('quantangshi-05538','句','談戭','quantangshi','','卷6','清清江潭树，日夕增所思。','',''),('quantangshi-05539','塞上','殷遙','quantangshi','','卷6','万里颓城在，三边虏气衰。
沙填孤嶂角，烧断故关碑。
马色经寒惨，雕声带晚悲。
将军正闲暇，留客换歌辞。','',''),('quantangshi-05540','送友人下第归省','殷遙','quantangshi','','卷6','君此卜行日，高堂应梦归。
莫将和氏泪，滴着老莱衣。
岳雨连河细，田禽出麦飞。
到家调膳后，吟好送斜晖。','',''),('quantangshi-05541','送杜士瞻楚州觐省','殷遙','quantangshi','','卷6','风流与才思，俱似晋时人。
淮月归心促，江花入兴新。
云深苍海暮，柳暗白门春。
共道官犹小，怜君孝养亲。','',''),('quantangshi-05542','友人山亭','殷遙','quantangshi','','卷6','故人虽薄宦，往往涉清溪。
凿牖对山月，褰裳拂涧霓。
游鱼逆水上，宿鸟向风栖。
一见桃花发，能令秦汉迷。','',''),('quantangshi-05543','春晚山行','殷遙','quantangshi','','卷6','寂历青山晚，山行趣不稀。
野花成子落，江燕引雏飞。
暗草薰苔径，晴杨扫石矶。
俗人犹语此，余亦转忘归。','',''),('quantangshi-05544','寄张征古','沈如筠','quantangshi','','卷6','寂历远山意，微冥半空碧。
绿萝无冬春，彩云竟朝夕。
张子海内奇，久为岩中客。
圣君当梦想，安得老松石。','',''),('quantangshi-05545','闺怨二首 一','沈如筠','quantangshi','','卷6','雁尽书难寄，愁多梦不成。
愿随孤月影，流照伏波营。','',''),('quantangshi-05546','闺怨二首 二','沈如筠','quantangshi','','卷6','陇底嗟长别，流襟一动君。
何言幽咽所，更作死生分。','',''),('quantangshi-05547','寄天台司马道士','沈如筠','quantangshi','','卷6','河洲花艳爚，庭树光彩蒨。
白云天台山，可思不可见。','',''),('quantangshi-05548','句','沈如筠','quantangshi','','卷6','思酸寒雁断，淅沥秋树空。
渔阳燕旧都，美女花不如。','',''),('quantangshi-05549','咏黄莺','孫處玄','quantangshi','','卷6','欲啭声犹涩，将飞羽未调。
高风不借便，何处得迁乔。','',''),('quantangshi-05550','失题','孫處玄','quantangshi','','卷6','汉家轻壮士，无状杀彭王。
一遇风尘起，令谁守四方。','',''),('quantangshi-05551','句','孫處玄','quantangshi','','卷6','残花与露落，堕叶随风翻。
日侧南涧幽，风凝北林暮。','',''),('quantangshi-05552','折杨柳','徐延壽','quantangshi','','卷6','大道连国门，东西种杨柳。
葳蕤君不见，袅娜垂来久。
缘枝栖暝禽，雄去雌独吟。
余花怨春尽，微月起秋阴。
坐望窗中蝶，起攀枝上叶。
好风吹长条，婀娜何如妾。
妾见柳园新，高楼四五春。
莫吹胡塞曲，愁杀陇头人。','',''),('quantangshi-05553','南州行','徐延壽','quantangshi','','卷6','摇艇至南国，国门连大江。
中洲西边岸，数步一垂杨。
金钏越溪女，罗衣胡粉香。
织缣春卷幔，采蕨暝提筐。
弄瑟娇垂幌，迎人笑下堂。
河头浣衣处，无数紫鸳鸯。','',''),('quantangshi-05554','人日剪彩','徐延壽','quantangshi','','卷6','闺妇持刀坐，自怜裁剪新。
叶催情缀色，花寄手成春。
帖燕留妆户，黏鸡待饷人。
擎来问夫壻，何处不如真。','',''),('quantangshi-05555','南中感怀','樊晃','quantangshi','','卷6','南路磋跎客未回，常嗟物候暗相催。
四时不变江头草，十月先开岭上梅。','',''),('quantangshi-05556','句','樊晃','quantangshi','','卷6','巧裁蝉鬓畏风吹，尽作蛾眉恐人妒。','',''),('quantangshi-05557','和户部杨员外伯成寓直','李憕','quantangshi','','卷6','落日弥纶地，公才画省郎。
词惊起草笔，坐引护衣香。
双阙天河近，千门夕漏长。
遥知台上宿，不独有文强。','',''),('quantangshi-05558','同望幸新亭赐钱公宴','李憕','quantangshi','','卷6','感梦通玄化，覃恩降紫宸。
赐钱开汉府，分帛醉尧人。
地隔朝宗庆，亭临卜洛新。
行看广云雨，二月次东巡。','',''),('quantangshi-05559','奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制','李憕','quantangshi','','卷6','别馆春还淑气催，三宫路转凤皇台。
云飞北阙轻阴散，雨歇南山积翠来。
御柳遥随天仗发，林花不待晓风开。
已知圣泽深无限，更喜年芳入睿才。','',''),('quantangshi-05560','铜雀妓','李邕','quantangshi','','卷6','西陵望何及，弦管徒在兹。
谁言死者乐，但令生者悲。
丈夫有余志，儿女焉足私。
扰扰多俗情，投迹互相师。
直节岂感激，荒淫乃凄其。
颍水有许由，西山有伯夷。
颂声何寥寥，唯闻铜雀诗。
君举良未易，永为后代嗤。','',''),('quantangshi-05561','咏云','李邕','quantangshi','','卷6','彩云惊岁晚，缭绕孤山头。
散作五般色，凝为一段愁。
影虽沈涧底，形在天际游。
风动必飞去，不应长此留。','',''),('quantangshi-05562','登历下古城员外孙新亭','李邕','quantangshi','','卷6','吾宗固神秀，体物写谋长。
形制开古迹，曾冰延乐方。
太山雄地理，巨壑眇云庄。
高兴汨烦促，永怀清典常。
含弘知四大，出入见三光。
负郭喜秔稻，安时歌吉祥。','',''),('quantangshi-05563','奉和初春幸太平公主南庄应制','李邕','quantangshi','','卷6','传闻银汉支机石，复见金舆出紫微。
织女桥边乌鹊起，仙人楼上凤皇飞。
流风入座飘歌扇，瀑水侵阶溅舞衣。
今日还同犯牛斗，乘槎共逐海潮归。','',''),('quantangshi-05564','奉使登终南山','王灣','quantangshi','','卷6','常爱南山游，因而尽原隰。
数朝至林岭，百仞登嵬岌。
石壮马径穷，苔色步缘入。
物奇春状改，气远天香集。
虚洞策杖鸣，低云拂衣湿。
倚岩见庐舍，入户欣拜揖。
问性矜勤劳，示心教澄习。
玉英时共饭，芝草为余拾。
境绝人不行，潭深鸟空立。
一乘从此授，九转兼是给。
辞处若轻飞，憩来唯吐吸。
闲襟超已胜，回路倏而及。
烟色松上深，水流山下急。
渐平逢车骑，向晚睨城邑。
峯在野趣繁，尘飘宦情澁。
辛苦久为吏，劳生何妄执。
日暮怀此山，悠然赋斯什。','',''),('quantangshi-05565','晚夏马嵬卿叔池亭即事寄京都一二知己','王灣','quantangshi','','卷6','忝职畿甸淹，滥陪时俊后。
才轻策疲劣，势薄常驱走。
牵役劳风尘，秉心在岩薮。
宗贤开别业，形胜代希偶。
竹绕清渭滨，泉流白渠口。
逡巡期赏会，挥忽变星斗。
逮此乘务闲，因而访幽叟。
入来殊景物，行复洗纷垢。
林静秋色多，潭深月光厚。
盛香莲近拆，新味瓜初剖。
滞拙怀隐沦，书之寄良友。','',''),('quantangshi-05566','丽正殿赐宴同勒天前烟年四韵应制','王灣','quantangshi','','卷6','金殿忝陪贤，琼羞忽降天。
鼎罗仙掖里，觞拜琐闱前。
院逼青霄路，厨和紫禁烟。
酒酣空忭舞，何以答昌年。','',''),('quantangshi-05567','奉和贺监林月清酌','王灣','quantangshi','','卷6','华月当秋满，朝英假兴同。
净林新霁入，规院小凉通。
碎影行筵里，摇花落酒中。
清宵凝爽意，倂此助文雄。','',''),('quantangshi-05568','次北固山下','王灣','quantangshi','','卷6','客路青山外，行舟绿水前。
潮平两岸阔，风正一帆悬。
海日生残夜，江春入旧年。
乡书何处达，归雁洛阳边。','',''),('quantangshi-05569','观搊筝','王灣','quantangshi','','卷6','虚室有秦筝，筝新月复清。
弦多弄委曲，柱促语分明。
晓怨凝繁手，春娇入曼声。
近来唯此乐，传得美人情。','',''),('quantangshi-05570','晚春诣苏州敬赠武员外','王灣','quantangshi','','卷6','苏台忆季常，飞棹历江乡。
持此功曹掾，初离华省郎。
贵门生礼乐，明代秉文章。
嘉郡位先进，鸿儒名重扬。
爰从姻娅贬，岂失忠信防。
万里行骥足，十年暌凤翔。
回迁翊元圣，入拜伫惟良。
别业对南浦，羣书满北堂。
意深投辖盛，才重接筵光。
陋学叨铅简，弱龄许翰场。
神驰劳旧国，颜展别殊方。
际晓杂氛散，残春众物芳。
烟和疎树满，雨续小溪长。
旅拙感成慰，通贤顾不忘。
从来琴曲罢，开匣为君张。','',''),('quantangshi-05571','秋夜寓直即事怀赠萧令公裴侍郎兼通简南省诸友人','王灣','quantangshi','','卷6','圣主万年兴，贤臣数载升。
古灵传岳秀，宏量禀川澄。
畿甸举长策，风霜秉直绳。
出车遥俗震，登阁满朝称。
赋简流亡辑，农安政理凭。
还家新长幼，巡壠旧沟塍。
忠梗大勋立，寰瀛堕业惩。
焚香兼御史，悬镜委中丞。
旟隼当朝立，台骢发郡乘。
司徒汉家重，国典颍川征。
云路俄平入，台阶忽上凌。
秉钧调造化，宣綍慰黎烝。
金省方秋作，瑶轩直夜凭。
中书赠陈准，右相简王陵。
三杰贤更穆，百僚欢且兢。
摇怀及宾友，计曲辨淄渑。
阊阖暝阴散，钩陈爽气凝。
月深宫树转，河近禁楼冰。
卑吏夙驱策，微涓效斗升。
望麾宵继火，书板曙怀蒸。
彼此虽流盼，规模转服膺。
惠将霄汉隔，劳或岁时矜。
位重恩宁滥，才轻慑不胜。
林峦甘独往，疵贱苦相仍。
敢忘衔花雀，思同附骥蝇。
平生逐鸟雀，何日嗣苍鹰。','',''),('quantangshi-05572','哭补阙亡友綦毋学士','王灣','quantangshi','','卷6','明代资多士，儒林得异才。
书从金殿出，人向玉墀来。
词学张平子，风仪褚彦回。
崇仪希上德，近侍接元台。
曩契心期早，今游宴赏陪。
屡迁君擢桂，分尉我从梅。
忽遇乘轺客，云倾构厦材。
泣为洹水化，叹作泰山颓。
冀善初将慰，寻言半始猜。
位联情易感，交密痛难裁。
远日寒旌暗，长风古挽哀。
寰中无旧业，行处有新苔。
反哭魂犹寄，终丧子尚孩。
葬田门吏给，坟木路人栽。
遽泄悲成往，俄传宠令回。
玄经贻石室，朱绂耀泉台。
地古春长闭，天明夜不开。
登山一临哭，挥泪满蒿莱。','',''),('quantangshi-05573','闰月七日织女','王灣','quantangshi','','卷6','耿耿曙河微，神仙此夜稀。
今年七月闰，应得两回归。','',''),('quantangshi-05574','句','王灣','quantangshi','','卷6','月华照杵空随妾，风响传砧不到君。','',''),('quantangshi-05575','应诏赋得除夜','史青','quantangshi','','卷6','今岁今宵尽，明年明日催。
寒随一夜去，春逐五更来。
气色空中改，容颜暗里回。
风光人不觉，已着后园梅。','',''),('quantangshi-05576','汴堤柳','王泠然','quantangshi','','卷6','隋家天子忆扬州，厌坐深宫傍海游。
穿地凿山开御路，鸣笳叠鼓泛清流。
流从巩北分河口，直到淮南种官柳。
功成力尽人旋亡，代谢年移树空有。
当时彩女侍君王，绣帐旌门对柳行。
青叶交垂连幔色，白花飞度染衣香。
今日摧残何用道，数里曾无一枝好。
驿骑征帆损更多，山精野魅藏应老。
凉风八月露为霜，日夜孤舟入帝乡。
河畔时时闻木落，客中无不泪沾裳。','',''),('quantangshi-05577','夜光篇','王泠然','quantangshi','','卷6','游人夜到汝阳间，夜色冥蒙不解颜。
谁家暗起寒山烧，因此明中得见山。
山头山下须臾满，历险缘深无暂断。
焦声散着羣树鸣，炎气傍林一川暖。
是时西北多海风，吹上连天光更雄。
浊烟熏月黑，高艳爇云红。
初谓炼丹仙竈里，还疑铸劒神溪中。
划为飞电来照物，乍作流星并上空。
西山无草光已灭，东顶荧荧犹未绝。
沸汤空谷数道水，融盖阴崖几年雪。
两京贫病若为居，四壁皆成凿照余。
未得贵游同秉烛，唯将半影借披书。','',''),('quantangshi-05578','古木卧平沙','王泠然','quantangshi','','卷6','古木卧平沙，摧残岁月赊。
有根横水石，无叶拂烟霞。
春至苔为叶，冬来雪作花。
不逢星汉使，谁辨是灵槎。','',''),('quantangshi-05579','淮南寄舍弟','王泠然','quantangshi','','卷6','昔予从不调，经岁旅淮源。
念尔长相失，何时返故园。
寄书迷处所，分袂隔凉温。
远道俱为客，他乡共在原。
归情春伴雁，愁泣夜随猨。
愧见高堂上，朝朝独倚门。','',''),('quantangshi-05580','句','王泠然','quantangshi','','卷6','林狖欺童子，山精试老僧。
陈兵劒阁山将动，饮马珠江水不流。
官微思倚玉，文浅怯投珠。','',''),('quantangshi-05581','春江花月夜二首 一','張子容','quantangshi','','卷6','林花发岸口，气色动江新。
此夜江中月，流光花上春。
分明石潭里，宜照浣纱人。','',''),('quantangshi-05582','春江花月夜二首 二','張子容','quantangshi','','卷6','交甫怜瑶佩，仙妃难重期。
沈沈绿江晚，惆怅碧云姿。
初逢花上月，言是弄珠时。','',''),('quantangshi-05583','云阳驿陪崔使君邵道士夜宴','張子容','quantangshi','','卷6','一尉东南远，谁知此夜欢。
诸侯倾皂盖，仙客整黄冠。
染翰灯花满，飞觞云气寒。
欣承国士遇，更借美人看。','',''),('quantangshi-05584','除夜乐城逢孟浩然','張子容','quantangshi','','卷6','远客襄阳郡，来过海岸家。
樽开柏叶酒，灯发九枝花。
妙曲逢卢女，高才得孟嘉。
东山行乐意，非是竞繁华。','',''),('quantangshi-05585','送苏倩游天台','張子容','quantangshi','','卷6','灵异寻沧海，笙歌访翠微。
江鸥迎共狎，云鹤待将飞。
琪树尝仙果，琼楼试羽衣。
遥知神女问，独怪阮郎归。','',''),('quantangshi-05586','泛永嘉江日暮回舟','張子容','quantangshi','','卷6','无云天欲暮，轻鷁大江清。
归路烟中远，回舟月上行。
傍潭窥竹暗，出屿见沙明。
更值微风起，乘流丝管声。','',''),('quantangshi-05587','永嘉即事寄赣县袁少府瓘','張子容','quantangshi','','卷6','山绕楼台出，溪通里閈斜。
曾为谢客郡，多有逐臣家。
海气朝成雨，江天晚作霞。
题书报贾谊，此湿似长沙。','',''),('quantangshi-05588','乐城岁日赠孟浩然','張子容','quantangshi','','卷6','土地穷瓯越，风光肇建寅。
插桃销瘴疠，移竹近阶墀。
半是吴风俗，仍为楚岁时。
更逢习凿齿，言在汉川湄。','',''),('quantangshi-05589','永嘉作','張子容','quantangshi','','卷6','拙宦从江左，投荒更海边。
山将孤屿近，水共恶溪连。
地湿梅多雨，潭蒸竹起烟。
未应悲晚髪，炎瘴苦华年。','',''),('quantangshi-05590','送孟八浩然归襄阳二首 一','張子容','quantangshi','','卷6','东越相逢地，西亭送别津。
风潮看解缆，云海去愁人。
乡在桃林岸，山连枫树春。
因怀故园意，归与孟家邻。','',''),('quantangshi-05591','送孟八浩然归襄阳二首 二','張子容','quantangshi','','卷6','杜门不欲出，久与世情疎。
以此为长策，劝君归旧庐。
醉歌田舍酒，笑读古人书。
好是一生事，无劳献子虚。','',''),('quantangshi-05592','贬乐城尉日作','張子容','quantangshi','','卷6','窜谪边穷海，川原近恶溪。
有时闻虎啸，无夜不猿啼。
地暖花长发，岩高日易低。
故乡可忆处，遥指斗牛西。','',''),('quantangshi-05593','自乐城赴永嘉枉路泛白湖寄松阳李少府','張子容','quantangshi','','卷6','西行碍浅石，北转入溪桥。
树色烟轻重，湖光风动摇。
百花乱飞雪，万岭叠青霄。
猿挂临潭筱，鸥迎出浦桡。
惟应赏心客，兹路不言遥。','',''),('quantangshi-05594','九日陪润州邵使君登北固山','張子容','quantangshi','','卷6','五马向西椒，重阳坐丽谯。
徐州带绿水，楚国在青霄。
张幕连江树，开筵接海潮。
凌云词客语，回雪无人娇。
梅福惭仙吏，羊公赏下僚。
新丰酒旧美，况是菊花朝。','',''),('quantangshi-05595','璧池望秋月','張子容','quantangshi','','卷6','凉夜窥清沼，池空水月秋。
满轮沈玉镜，半魄落银钩。
蟾影摇轻浪，菱花渡浅流。
漏移光渐洁，云敛色偏浮。
似璧悲三献，疑珠怯再投。
能持千里意，来照楚乡愁。','',''),('quantangshi-05596','长安早春','張子容','quantangshi','','卷6','开国维东井，城池起北辰。
咸歌太平日，共乐建寅春。
雪尽黄山树，冰开黑水津。
草迎金埒马，花伴玉楼人。
鸿渐看无数，莺歌听欲频。
何当桂枝擢，还及柳条新。','',''),('quantangshi-05597','赠司勋萧郎中','張子容','quantangshi','','卷6','作相开黄阁，为郎奏赤墀。
君臣道合体，父子贵同时。
国以推贤答，家无内举疑。
凤池真水镜，兰省得华滋。
未覩风流日，先闻新赋诗。
江山清谢朓，花木媚丘迟。
吏部来何暮，王言念在兹。
丹青无不可，霖雨亦相期。
昔我投荒处，孤烟望岛夷。
羣鸥终日狎，落叶数年悲。
渔父留歌咏，江妃入兴词。
今将献知己，相感勿吾欺。','',''),('quantangshi-05598','巫山','張子容','quantangshi','','卷6','巫岭岧峣天际重，佳期宿昔愿相从。
朝云暮雨连天暗，神女知来第几峯。','',''),('quantangshi-05599','除日','張子容','quantangshi','','卷6','腊月今知晦，流年此夕除。
拾樵供岁火，帖牖作春书。
柳觉东风至，花疑小雪余。
忽逢双鲤赠，言是上冰鱼。','',''),('quantangshi-05600','清溪泛舟','張旭','quantangshi','','卷6','旅人倚征棹，薄暮起劳歌。
笑揽清溪月，清辉不厌多。','',''),('quantangshi-05601','桃花溪','張旭','quantangshi','','卷6','隐隐飞桥隔野烟，石矶西畔问渔船。
桃花尽日随流水，洞在清溪何处边。','',''),('quantangshi-05602','山行留客','張旭','quantangshi','','卷6','山光物态弄春辉，莫为轻阴便拟归。
纵使晴明无雨色，入云深处亦沾衣。','',''),('quantangshi-05603','春游值雨','張旭','quantangshi','','卷6','欲寻轩槛列清尊，江上烟云向晚昏。
须倩东风吹散雨，明朝却待入华园。','',''),('quantangshi-05604','春草','張旭','quantangshi','','卷6','春草青青万里余，边城落日见离居。
情知海上三年别，不寄云间一纸书。','',''),('quantangshi-05605','柳','張旭','quantangshi','','卷6','濯濯烟条拂地垂，城边楼畔结春思。
请君细看风流意，未减灵和殿里时。','',''),('quantangshi-05606','南山','賀朝','quantangshi','','卷6','湖北雨初晴，湖南山尽见。
岩岩石帆影，如得海风便。
仙穴茅山峯，彩云时一见。
邀君共探此，异箓残几卷。','',''),('quantangshi-05607','孤兴','賀朝','quantangshi','','卷6','晴日暖珠箔，夭桃色正新。
红粉青镜中，娟娟可怜嚬。
君子在遐险，蕙心谁见珍。
罗幕空掩昼，玉颜静移春。
江瑟语幽独，再三情未申。
黄鹄千里翅，芳音迟所因。','',''),('quantangshi-05608','从军行','賀朝','quantangshi','','卷6','朔胡乘月寇边城，军书插羽刺中京。
天子金坛拜飞将，单于玉塞振佳兵。
骑射先鸣推任侠，龙韬决胜伫时英。
闻有河湟客，愔愔理帷帟。
常山启霸图，汜水先天策。
衔珠浴铁向桑干，衅旗膏劒指乌丸。
鸣鸡已报关山晓，来雁遥传沙塞寒。
直为甘心从苦节，陇头流水鸣呜咽。
边树萧萧不觉春，天山漠漠长飞雪。
鱼丽阵接塞云平，雁翼营通海月明。
始看晋幕飞鹅入，旋闻齐垒啼乌声。
自从一戍燕支山，春光几度晋阳关。
金河未转青丝骑，玉筯应啼红粉颜。
鸿归燕相续，池边芳草绿。
已见氛清细柳营，莫更春歌落梅曲。
烽沈竈减静边亭，海[晏]山空肃已宁。
行望凤京旋凯捷，重来麟阁画丹青。','',''),('quantangshi-05609','赋得游人久不归','賀朝','quantangshi','','卷6','乡关眇天末，引领怅怀归。
羇旅久淫滞，物色屡芳菲。
稍觉出意尽，行看蓬鬓稀。
如何千里外，伫立霑裳衣。','',''),('quantangshi-05610','宿香山阁','賀朝','quantangshi','','卷6','暝上春山阁，梯云宿半空。
轩窗闭潮海，枕席拂烟虹。
朱网防栖鸽，纱灯护夕虫。
一闻鸡唱晓，已见日曈曈。','',''),('quantangshi-05611','赠酒店胡姬','賀朝','quantangshi','','卷6','胡姬春酒店，弦管夜锵锵。
红毾铺新月，貂裘坐薄霜。
玉盘初鲙鲤，金鼎正烹羊。
上客无劳散，听歌乐世娘。','',''),('quantangshi-05612','赋得春莺送友人二首 一','賀朝','quantangshi','','卷6','翅掩飞莺舞，啼恼婕妤悲。
料取金闺意，因君问所思。','',''),('quantangshi-05613','赋得春莺送友人二首 二','賀朝','quantangshi','','卷6','流莺拂绣羽，二月上林期。
待雪销金禁，衔花向玉墀。','',''),('quantangshi-05614','三日绿潭篇','萬齊融','quantangshi','','卷6','春潭滉漾接隋宫，宫阙连延潭水东。
苹苔嫩色涵波绿，桃李新花照底红。
垂菱布藻如妆镜，丽日晴天相照暎。
素影沈沈对蝶飞，金沙砾砾窥鱼泳。
佳人祓禊赏韶年，倾国倾城并可怜。
拾翠总来芳树下，踏青争遶绿潭边。
公子王孙恣游翫，沙阳水曲情无厌。
禽浮似挹羽觞杯，鳞跃疑投水心劒。
金鞍玉勒骋轻肥，落絮红尘拥路飞。
绿水残霞催席散，画楼初月待人归。','',''),('quantangshi-05615','仗劒行','萬齊融','quantangshi','','卷6','昨夜星官动紫微，今年天子用武威。
登车一呼风雷动，遥震阴山撼巍巍。
胡骄子，当见旄头蚀应死。
愿骑单马仗天威，挼取长绳缚虏归。
仗劒遥叱路傍子，匈奴头血溅君衣。','',''),('quantangshi-05616','赠别江头','萬齊融','quantangshi','','卷6','东南飞鸟处，言是故乡天。
江上风花晚，君行定几千。
计程频破月，数别屡开年。
明岁浔阳水，相思寄采莲。','',''),('quantangshi-05617','送陈七还广陵','萬齊融','quantangshi','','卷6','风流谁代子，虽有旧无双。
欢酒言相送，愁弦意不降。
落花馥河道，垂杨拂水窗。
海潮与春梦，朝夕广陵江。','',''),('quantangshi-05618','游春','邢巨','quantangshi','','卷6','海岳三峯古，春皇二月寒。
绿潭渔子钓，红树美人攀。
弱蔓环沙屿，飞花点石关。
溪山游未厌，琴酌弄晴湾。','',''),('quantangshi-05619','游宣州琴溪同武平一作','邢巨','quantangshi','','卷6','灵溪非人迹，仙意素所秉。
鳞岭森翠微，澄潭照秋景。','',''),('quantangshi-05620','春江花月夜','張若虛','quantangshi','','卷6','春江潮水连海平，海上明月共潮生。
滟滟随波千万里，何处春江无月明？
江流宛转遶芳甸，月照花林皆似霰。
空里流霜不觉飞，汀上白沙看不见。
江天一色无纤尘，皎皎空中孤月轮。
江畔何人初见月，江月何年初照人？
人生代代无穷已，江月年年秖相似。
不知江月待何人？但见长江送流水。
白云一片去悠悠，青枫浦上不胜愁。
谁家今夜扁舟子，何处相思明月楼？
可怜楼上月裴回，应照离人妆镜台。
玉户帘中卷不去，捣衣砧上拂还来。
此时相望不相闻，愿逐月华流照君。
鸿雁长飞光不度，鱼龙潜跃水成文。
昨夜闲潭梦落花，可怜春半不还家。
江水流春去欲尽，江潭落月复西斜。
斜月沈沈藏海雾，碣石潇湘无限路。
不知乘月几人归，落月摇情满江树。','',''),('quantangshi-05621','代答闺梦还','張若虛','quantangshi','','卷6','关塞年华早，楼台别望违。
试衫着暖气，开镜觅春晖。
燕入窥罗幕，蜂来上画衣。
情催桃李艳，心寄管弦飞。
妆洗朝相待，风花暝不归。
梦魂何处入，寂寂掩重扉。','',''),('quantangshi-05622','洪州客舍寄柳博士芳','薛業','quantangshi','','卷6','去年燕巢主人屋，今年花发路傍枝。
年年为客不到舍，旧国存亡那得知。','',''),('quantangshi-05623','晚秋赠张折冲','薛業','quantangshi','','卷6','都尉今无事，时清但闭关。
夜霜戎马瘦，秋草射堂闲。
位以穿杨得，名因折桂还。
冯唐真不遇，叹息鬓毛斑。','',''),('quantangshi-05624','和左司张员外自洛使入京中路先赴长安逢立春日赠韦侍御等诸公','孫逖','quantangshi','','卷6','拜郎登省闼，奉使驰车乘。
遥瞻使者星，便是郎官应。
台妙时相许，皇华德弥称。
二陕听风谣，三秦望形胜。
此中暌益友，是日多诗兴。
寒尽岁阴催，春归物华证。','',''),('quantangshi-05625','和登会稽山','孫逖','quantangshi','','卷6','稽山碧湖上，势入东溟尽。
烟景昼清明，九峰争隐嶙。
望中厌朱绂，俗内探玄牝。
野老听鸣驺，山童拥行轸。
仙花寒未落，古蔓柔堪引。
竹磵入山多，松崖向天近。
云从海天去，日就江村陨。
能赋丘尝闻，和歌参不敏。
冥搜信冲漠，多士期标准。
愿奉濯缨心，长谣反招隐。','',''),('quantangshi-05626','送杨法曹按括州','孫逖','quantangshi','','卷6','东海天台山，南方缙云驿。
溪澄问人隐，岩险烦登陟。
潭壑随星使，轩车绕春色。
傥寻琪树人，为报长相忆。','',''),('quantangshi-05627','葛山潭','孫逖','quantangshi','','卷6','圆潭写流月，晴明涵万象。
仙翁何时还，绿水空荡漾。
凉哉草木腓，白露沾人衣。
犹醉空山里，时闻笙鹤飞。','',''),('quantangshi-05628','丹阳行','孫逖','quantangshi','','卷6','丹阳古郡洞庭阴，落日扁舟此路寻。
传是东南旧都处，金陵中断碧江深。
在昔风尘起，京都乱如毁。
双阙戎虏间，千门战场里。
传闻一马化为龙，南渡衣冠亦愿从。
石头横帝里，京口拒戎锋。
青枫林下回天跸，杜若洲前转国容。
都门不见河阳树，辇道唯闻建业钟。
中原悠悠几千里，欲扫欃枪未云已。
英雄倾夺何纷然，一盛一衰如逝川。
可怜宫观重江里，金镜相传三百年。
自从龙见圣人出，六合车书混为一。
昔年王气今何在，并向长安就尧日。
荆榛古木闭荒阡，共道繁华不复全。
赤县唯余江树月，黄图半入海人烟。
暮来山水登临遍，览古愁吟泪如霰。
唯有空城多白云，春风淡荡无人见。','',''),('quantangshi-05629','山阴县西楼','孫逖','quantangshi','','卷6','都邑西楼芳树间，逶迤霁色遶江山。
山月夜从公署出，江云晚对讼庭还。
谁知春色朝朝好，二月飞花满江草。
一见湖边杨柳风，遥忆青青洛阳道。','',''),('quantangshi-05630','夜宿浙江','孫逖','quantangshi','','卷6','扁舟夜入江潭泊，露白风高气萧索。
富春渚上潮未还，天姥岑边月初落。
烟水茫茫多苦辛，更闻江上越人吟。
洛阳城阙何时见，西北浮云朝暝深。','',''),('quantangshi-05631','春日留别','孫逖','quantangshi','','卷6','春路逶迤花柳前，孤舟晚泊就人烟。
东山白云不可见，西陵江月夜娟娟。
春江夜尽潮声度，征帆遥从此中去。
越国山川看渐无，可怜愁思江南树。','',''),('quantangshi-05632','奉和四月三日上阳水窗赐宴应制得春字','孫逖','quantangshi','','卷6','今日逢初夏，欢游续旧旬。
气和先作雨，恩厚别成春。
凤吹临清洛，龙舆下紫宸。
此中歌在藻，还见跃潜鳞。','',''),('quantangshi-05633','奉和登会昌山应制','孫逖','quantangshi','','卷6','岩磴列云旗，吾君访道时。
干行万物覩，日驭六龙迟。
望远回天顾，登高动睿词。
愿因山作寿，长保会昌期。','',''),('quantangshi-05634','正月十五日夜应制','孫逖','quantangshi','','卷6','洛城三五夜，天子万年春。
彩仗移双阙，琼筵会九宾。
舞成苍颉字，灯作法王轮。
不觉东方日，遥垂御藻新。','',''),('quantangshi-05635','奉和御制登鸳鸯楼即目应制','孫逖','quantangshi','','卷6','玉辇下离宫，琼楼上半空。
方巡五年狩，更辟四门聪。
井邑观秦野，山河念禹功。
停銮留睿作，轩槛起南风。','',''),('quantangshi-05636','进船泛洛水应制','孫逖','quantangshi','','卷6','禁园纡睿览，仙棹叶时游。
洛北风花树，江南彩画舟。
芳生兰蕙草，春入凤凰楼。
兴尽离宫暮，烟光起夕流。','',''),('quantangshi-05637','和常州崔使君寒食夜','孫逖','quantangshi','','卷6','闻道清明近，春庭向夕阑。
行游昼不厌，风物夜宜看。
斗柄更初转，梅香暗里残。
无劳秉华烛，清月在南端。','',''),('quantangshi-05638','和韦兄春日南亭宴兄弟','孫逖','quantangshi','','卷6','台阁升高位，园林隔旧乡。
忽闻歌棣萼，还比报琼芳。
门向宜春近，郊连御宿长。
德星常有会，相望在文昌。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-05639','奉和崔司马游云门寺','孫逖','quantangshi','','卷6','系马清溪树，禅门春气浓。
香台花下出，讲坐竹间逢。
觉路山童引，经行谷鸟从。
更言穷寂灭，回策上南峰。','',''),('quantangshi-05640','酬万八贺九云门下归溪中作','孫逖','quantangshi','','卷6','晚从灵境出，林壑曙云飞。
稍觉清溪尽，回瞻画刹微。
独园余兴在，孤棹宿心违。
更忆登攀处，天香满袖归。','',''),('quantangshi-05641','春初送吕补阙往西岳勒碑得云字','孫逖','quantangshi','','卷6','刻石记天文，朝推谷子云。
箧中缄圣札，岩下揖神君。
语别梅初艳，为期草欲薰。
往来春不尽，离思莫氛氲。','',''),('quantangshi-05642','送越州裴参军充使入京','孫逖','quantangshi','','卷6','日落川径寒，离心苦未安。
客愁西向尽，乡梦北归难。
霜果林中变，秋花水上残。
明朝渡江后，云物向南看。','',''),('quantangshi-05643','送周判官往台州','孫逖','quantangshi','','卷6','吾宗长作赋，登陆访天台。
星使行看入，云仙意转催。
饮冰攀璀璨，驱传历莓苔。
日暮东郊别，真情去不回。','',''),('quantangshi-05644','送魏骑曹充宇文侍御判官分按山南','孫逖','quantangshi','','卷6','云雨阳台路，光华驿骑巡。
劝农开梦土，恤隐惠荆人。
楼迥吟黄鹤，江长望白苹。
观风布明诏，更是汉南春。','',''),('quantangshi-05645','送苏郎中绾出佐荆州','孫逖','quantangshi','','卷6','神仙久留滞，清切伫飞翻。
忽佐南方牧，何时西掖垣。
高车自兰省，便道出荆门。
不见河梁别，空销郢路魂。','',''),('quantangshi-05646','冬末送魏起居赴京','孫逖','quantangshi','','卷6','大名将起魏，良史更逢迁。
驿骑朝丹阙，关亭望紫烟。
西京春色近，东观物华偏。
早赴王正月，挥毫记首年。','',''),('quantangshi-05647','送李补阙摄御史充河西节度判官','孫逖','quantangshi','','卷6','昔年叨补衮，边地亦埋轮。
官序慙先达，才名畏后人。
西戎虽献款，上策耻和亲。
早赴前军幕，长清外域尘。','',''),('quantangshi-05648','送赵评事摄御史监军岭南','孫逖','quantangshi','','卷6','议狱持邦典，临戎假宪威。
风从阊阖去，霜入洞庭飞。
篁竹迎金鼓，楼船引绣衣。
明年拜真月，南斗使星归。','',''),('quantangshi-05649','送靳十五侍御使蜀','孫逖','quantangshi','','卷6','天使出霜台，行人择吏才。
传车春色送，离兴夕阳催。
驿遶巴江转，关迎劒道开。
西南一何幸，前后二龙来。','',''),('quantangshi-05650','送李给事归徐州觐省','孫逖','quantangshi','','卷6','列位登青琐，还乡复彩衣。
共言晨省日，便是昼游归。
春水经梁宋，晴山入海沂。
莫愁东路远，四牡正騑騑。','',''),('quantangshi-05651','送杜侍御赴上都','孫逖','quantangshi','','卷6','避马台中贵，登车岭外遥。
还因贡赋礼，来谒大明朝。
地入商山路，乡连渭水桥。
承恩返南越，尊酒重相邀。','',''),('quantangshi-05652','送张环摄御史监南选','孫逖','quantangshi','','卷6','汉使得张纲，威名摄远方。
恩霑柱下史，荣比选曹郎。
江带黔中阔，山连峡水长。
莫愁炎暑地，秋至有严霜。','',''),('quantangshi-05653','宴越府陈法曹西亭','孫逖','quantangshi','','卷6','公府西岩下，红亭间白云。
雪梅初度腊，烟竹稍迎曛。
水木涵澄景，帘栊引霁氛。
江南归思逼，春雁不堪闻。','',''),('quantangshi-05654','同邢判官寻龙湍观归湖中','孫逖','quantangshi','','卷6','星使下仙京，云湖喜昼晴。
更从探穴处，还作棹歌行。
丝管荷风入，帘帷竹气清。
莫愁归路远，水月夜虚明。','',''),('quantangshi-05655','寻龙湍','孫逖','quantangshi','','卷6','仙穴寻遗迹，轻舟爱水乡。
溪流一曲尽，山路九峰长。
渔父歌金洞，江妃舞翠房。
遥怜葛仙宅，真气共微茫。','',''),('quantangshi-05656','宿云门寺阁','孫逖','quantangshi','','卷6','香阁东山下，烟花象外幽。
悬灯千嶂夕，卷幔五湖秋。
画壁余鸿雁，纱窓宿斗牛。
更疑天路近，梦与白云游。','',''),('quantangshi-05657','扬子江楼','孫逖','quantangshi','','卷6','扬子何年邑，雄图作楚关。
江连二妃渚，云近八公山。
驿道[青]枫外，人烟绿屿间。
晚来潮正满，数处落帆还。','',''),('quantangshi-05658','淮阴夜宿二首 一','孫逖','quantangshi','','卷6','水国南无畔，扁舟北未期。
乡情淮上失，归梦郢中疑。
木落知寒近，山长见日迟。
客行心绪乱，不及洛阳时。','',''),('quantangshi-05659','淮阴夜宿二首 二','孫逖','quantangshi','','卷6','永夕卧烟塘，萧条天一方。
秋风淮水落，寒夜楚歌长。
宿莽非中土，鲈鱼岂我乡。
孤舟行已倦，南越尚茫茫。','',''),('quantangshi-05660','下京口埭夜行','孫逖','quantangshi','','卷6','孤帆度绿氛，寒浦落红曛。
江树朝来出，吴歌夜渐闻。
南溟接潮水，北斗近乡云。
行役从兹去，归情入雁羣。','',''),('quantangshi-05661','山行遇雨','孫逖','quantangshi','','卷6','骤雨昼氤氲，空天望不分。
暗山唯觉电，穷海但生云。
涉涧猜行潦，缘崖畏宿氛。
夜来江月霁，棹唱此中闻。','',''),('quantangshi-05662','夜到润州','孫逖','quantangshi','','卷6','夜入丹阳郡，天高气象秋。
海隅云汉转，江畔火星流。
城郭传金柝，闾阎闭绿洲。
客行凡几夜，新月再如钩。','',''),('quantangshi-05663','和常州崔使君咏后庭梅二首 一','孫逖','quantangshi','','卷6','闻唱梅花落，江南春意深。
更传千里外，来入越人吟。
弱干红妆倚，繁香翠羽寻。
庭中自公日，歌舞向芳阴。','',''),('quantangshi-05664','和常州崔使君咏后庭梅二首 二','孫逖','quantangshi','','卷6','梅院重门掩，遥遥歌吹边。
庭深人不见，春至曲能传。
花落弹棋处，香来荐枕前。
使君停五马，行乐此中偏。','',''),('quantangshi-05665','同和咏楼前海石榴二首 一','孫逖','quantangshi','','卷6','客自新亭郡，朝来数物华。
传君妓楼好，初落海榴花。
露色珠帘映，香风粉壁遮。
更宜林下雨，日晚逐行车。','',''),('quantangshi-05666','同和咏楼前海石榴二首 二','孫逖','quantangshi','','卷6','海上移珍木，楼前咏所思。
遥闻下车日，正在落花时。
旧绿香行盖，新红洒步綦。
从来寒不易，终见久逾滋。','',''),('quantangshi-05667','故右丞相赠太师燕文贞公挽词二首 一','孫逖','quantangshi','','卷6','海内文章伯，朝端礼乐英。
一言兴宝运，三入济羣生。
命与才相偶，年将位不并。
台星忽已坼，流恸轸皇情。','',''),('quantangshi-05668','故右丞相赠太师燕文贞公挽词二首 二','孫逖','quantangshi','','卷6','甲第三重戟，高门四列侯。
已成冠盖里，更有凤皇楼。
人世方为乐，生涯遽若休。
空余掌纶地，传庆百千秋。','',''),('quantangshi-05669','故陈州刺史赠兵部尚书韦公挽词','孫逖','quantangshi','','卷6','奕叶金章贵，连枝鼎位尊。
台庭为凤穴，相府是鸰原。
世阅空悲命，泉幽不返魂。
惟余汉臣史，继术赞韦门。','',''),('quantangshi-05670','故程将军妻南阳郡夫人樊氏挽歌','孫逖','quantangshi','','卷6','德配程休甫，名高鲁季姜。
宠荣苍玉佩，宴梦郁金堂。
白日期偕老，幽泉忽悼亡。
国风犹在咏，江汉近南阳。','',''),('quantangshi-05671','和上巳连寒食有怀京洛','孫逖','quantangshi','','卷6','天津御柳碧遥遥，轩骑相从半下朝。
行乐光辉寒食借，太平歌舞晚春饶。
红妆楼下东郊道，青草洲边南渡桥。
坐见司空扫西第，看君侍从落花朝。','',''),('quantangshi-05672','和左司张员外自洛使入京中路先赴长安逢立春日赠韦侍御等诸公','孫逖','quantangshi','','卷6','忽覩云间数雁回，更逢山上正花开。
河边淑气迎芳草，林下轻风待落梅。
秋宪府中高唱入，春卿署里和歌来。
共言东阁招贤地，自有西征谢傅才。','',''),('quantangshi-05673','和崔司马登称心山寺','孫逖','quantangshi','','卷6','郡府乘休日，王城访道初。
觉花迎步履，香草藉行车。
倚阁观无际，寻山坐太虚。
岩空迷禹迹，海静望秦余。
翡翠巢珠网，鵾鸡间绮疏。
地灵资净土，水若护真如。
宝树谁攀折，禅云自卷舒。
晴分五湖势，烟合九夷居。
生灭纷无象，窥临已得鱼。
尝闻宝刀赠，今日奉琼琚。','',''),('quantangshi-05674','奉和李右相中书壁画山水','孫逖','quantangshi','','卷6','庙堂多暇日，山水契中情。
欲写高深趣，还因藻绘成。
九江临户牖，三峡绕檐楹。
花柳穷年发，烟云逐意生。
能令万里近，不觉四时行。
气染荀香馥，光含乐镜清。
咏歌齐出处，图画表冲盈。
自保千年遇，何论八载荣。','',''),('quantangshi-05675','奉和李右相赏会昌林亭','孫逖','quantangshi','','卷6','贤相初陪跸，灵山本降神。
作京雄近县，开阁宠平津。
地胜林亭好，时清宴赏频。
百泉萦草木，万井布郊畛。
德与春和盛，功将造化邻。
还嗤渭滨叟，岁晚独垂纶。','',''),('quantangshi-05676','和左衞武仓曹衞中对雨创韵赠右衞李骑曹','孫逖','quantangshi','','卷6','林父同官意，宣尼久敬交。
文场刊玉篆，武事掌金铙。
道合宜连茹，时清岂系匏。
克勤居簿领，多暇屏讙譊。
美酒怀公宴，玄谈俟客嘲。
薄云生北阙，飞雨自西郊。
院暑便清旷，庭芜觉渐苞。
高门关讵闭，逸韵柱难胶。
枳棘鸾无叹，椅梧凤必巢。
忽闻征竝作，观海愧堂坳。','',''),('quantangshi-05677','送新罗法师还国','孫逖','quantangshi','','卷6','异域今无外，高僧代所稀。
苦心归寂灭，宴坐得精微。
持钵何年至，传灯是日归。
上卿挥别藻，中禁下禅衣。
海阔杯还度，云遥锡更飞。
此行迷处所，何以慰虔祈。','',''),('quantangshi-05678','送赵大夫护边','孫逖','quantangshi','','卷6','外域分都护，中台命职方。
欲传清庙略，先取剧曹郎。
已佩登坛印，犹怀伏奏香。
百壶开祖饯，驷牡戒戎装。
青海连西掖，黄河带北凉。
关山瞻汉月，戈劒宿胡霜。
体国才先着，论兵策复长。
果持文武术，还继杜当阳。','',''),('quantangshi-05679','立秋日题安昌寺北山亭','孫逖','quantangshi','','卷6','楼观倚长霄，登攀及霁朝。
高如石门顶，胜拟赤城标。
天路云虹近，人寰气象遥。
山围伯禹庙，江落伍胥潮。
徂暑迎秋薄，凉风是日飘。
果林余苦李，萍水覆甘蕉。
览古嗟夷漫，凌空爱泬寥。
更闻金刹下，钟梵晚萧萧。','',''),('quantangshi-05680','登越州城','孫逖','quantangshi','','卷6','越嶂绕层城，登临万象清。
封圻沧海合，廛市碧湖明。
晓日渔歌满，芳春棹唱行。
山风吹美箭，田雨润香秔。
代阅英灵尽，人闲吏隐并。
赠言王逸少，已见曲池平。','',''),('quantangshi-05681','江行有怀','孫逖','quantangshi','','卷6','秋水明川路，轻舟转石圻。
霜多山橘熟，寒至浦禽稀。
飞席乘风势，回流荡日晖。
昼行疑海若，夕梦识江妃。
野霁看吴尽，天长望洛非。
不知何岁月，一似暮潮归。','',''),('quantangshi-05682','长洲苑','孫逖','quantangshi','','卷6','吴王初鼎峙，羽猎骋雄才。
辇道阊门出，军容茂苑来。
山从列嶂转，江自绕林回。
劒骑缘汀入，旌门隔屿开。
合离纷若电，驰逐溢成雷。
胜地虞人守，归舟汉女陪。
可怜夷漫处，犹在洞庭隈。
山静吟猿父，城空应雉媒。
戎行委乔木，马迹尽黄埃。
揽涕问遗老，繁华安在哉。','',''),('quantangshi-05683','和咏廨署有樱桃','孫逖','quantangshi','','卷6','上林天禁里，芳树有红樱。
江国今来见，君门春意生。
香从花绶转，色绕佩珠明。
海鸟衔初实，吴姬扫落英。
切将稀取贵，羞与众同荣。
为此堪攀折，芳蹊处处成。','',''),('quantangshi-05684','同洛阳李少府观永乐公主入蕃','孫逖','quantangshi','','卷6','边地莺花少，年来未觉新。
美人天上落，龙塞始应春。','',''),('quantangshi-05685','途中口号','孫逖','quantangshi','','卷6','邺城东北望陵台，珠翠繁华去不回。
无复新妆艳红粉，空余故垄满青苔。','',''),('quantangshi-05686','晦日湖塘','孫逖','quantangshi','','卷6','吉日初成晦，方塘遍是春。
落花迎二月，芳树历三旬。
公子能留客，巫阳好解神。
夜还何虑暗，秉烛向城闉。','',''),('quantangshi-05687','句','孫逖','quantangshi','','卷6','野烟出炉上，山花落镜中。','',''),('quantangshi-05688','从军行','崔國輔','quantangshi','','卷6','塞北胡霜下，营州索兵救。
夜里偷道行，将军马亦瘦。
刀光照塞月，阵色明如昼。
传闻贼满山，已共前锋鬬。','',''),('quantangshi-05689','杂诗','崔國輔','quantangshi','','卷6','逢着平乐儿，论交鞍马前。
与酤一斗酒，恰用十千钱。
后余在关内，作事多迍邅。
何肯相救援，徒闻宝劒篇。','',''),('quantangshi-05690','古意','崔國輔','quantangshi','','卷6','红荷楚水曲，彪炳烁晨霞。
未得两回摘，秋风吹却花。
时芳不待妾，玉佩无处夸。
悔不盛年时，嫁与青楼家。','',''),('quantangshi-05691','宿法华寺','崔國輔','quantangshi','','卷6','松雨时复滴，寺门清且凉。
此心竟谁证，回憩支公牀。
壁画感灵迹，龛经传异香。
独游寄象外，忽忽归南昌。','',''),('quantangshi-05692','题豫章馆','崔國輔','quantangshi','','卷6','杨柳映春江，江南转佳丽。
吴门绿波里，越国青山际。
游宦常往来，津亭暂临憩。
驿前苍石没，浦外湖沙细。
向晚宴且久，孤舟冏然逝。
云留西北客，气歇东南帝。
独有萋萋心，谁知怨芳岁。','',''),('quantangshi-05693','石头滩作','崔國輔','quantangshi','','卷6','怅矣秋风时，余临石头濑。
因高见远境，尽此数州内。
羽山数点青，海岸杂光碎。
离离树木少，漭漭湖波大。
日暮千里帆，南飞落天外。
须臾遂入夜，楚色有微霭。
寻远迹已穷，遗荣事多昧。
一身犹未理，安得济时代。
且泛朝夕潮，荷衣蕙为带。','',''),('quantangshi-05694','漂母岸','崔國輔','quantangshi','','卷6','泗水入淮处，南边古岸存。
秦时有漂母，于此饭王孙。
王孙初未遇，寄食何足论。
后为楚王来，黄金答母恩。
事迹遗在此，空伤千载魂。
茫茫水中渚，上有一孤墩。
遥望不可到，苍苍烟树昏。
几年崩冢色，每日落潮痕。
古地多陻圮，时哉不敢言。
向夕泪霑裳，遂宿芦洲村。','',''),('quantangshi-05695','对酒吟','崔國輔','quantangshi','','卷6','行行日将夕，荒村古冢无人迹。
蒙笼荆棘一鸟吟，屡唱提壶沽酒吃。
古人不达酒不足，遗恨精灵传此曲。
寄言世上诸少年，平生且尽杯中醁。','',''),('quantangshi-05696','奉和华清宫观行香应制','崔國輔','quantangshi','','卷6','天子蘂珠宫，楼台碧落通。
豫游皆汗漫，斋处即崆峒。
云物三光里，君臣一气中。
道言何所说，宝历自无穷。','',''),('quantangshi-05697','七夕','崔國輔','quantangshi','','卷6','太守仙潢族，含情七夕多。
扇风生玉漏，置水写银河。
阁下陈书籍，闺中曝绮罗。
遥思汉武帝，青鸟几时过。','',''),('quantangshi-05698','宿范浦','崔國輔','quantangshi','','卷6','月暗潮又落，西陵渡暂停。
村烟和海雾，舟火乱江星。
路转定山遶，塘连范浦横。
鸱夷近何去，空山临沧溟。','',''),('quantangshi-05699','奉和圣制上巳祓禊应制','崔國輔','quantangshi','','卷6','元巳秦中节，吾君灞上游。
鸣銮通禁苑，别馆遶芳洲。
鵷鹭千官列，鱼龙百戏浮。
桃花春欲尽，谷雨夜来收。
庆向尧樽祝，欢从楚棹讴。
逸诗何足对，窅作掩东周。','',''),('quantangshi-05700','九日侍宴应制','崔國輔','quantangshi','','卷6','运偶千年圣，时传九日神。
尧樽列钟鼓，汉阙辟钩陈。
金箓三清降，琼筵五老巡。
始惊兰佩出，复咏柏梁新。
云雁楼前晚，霜花酒里春。
欢娱无限极，书劒太平人。','',''),('quantangshi-05701','杭州北郭戴氏荷池送侯愉','崔國輔','quantangshi','','卷6','秋近万物肃，况当临水时。
折花赠归客，离绪断荷丝。
谁谓江国永，故人感在兹。
道存过北郭，情极望东菑。
乔木故园意，鸣蝉穷巷悲。
扁舟竟何待，中路每迟迟。','',''),('quantangshi-05702','怨词二首 一','崔國輔','quantangshi','','卷6','妾有罗衣裳，秦王在时作。
为舞春风多，秋来不堪着。','',''),('quantangshi-05703','怨词二首 二','崔國輔','quantangshi','','卷6','楼头桃李疎，池上芙蓉落。
织锦犹未成，蛩声入罗幕。','',''),('quantangshi-05704','古意二首 一','崔國輔','quantangshi','','卷6','玉笼薰绣裳，着罢眠洞房。
不能春风里，吹却兰麝香。','',''),('quantangshi-05705','古意二首 二','崔國輔','quantangshi','','卷6','种棘遮蘼芜，畏人来采杀。
比至狂夫还，看看几花发。','',''),('quantangshi-05706','襄阳曲二首 一','崔國輔','quantangshi','','卷6','蕙草娇红萼，时光舞碧鸡。
城中美年少，相见白铜鞮。','',''),('quantangshi-05707','襄阳曲二首 二','崔國輔','quantangshi','','卷6','少年襄阳地，来往襄阳城。
城中轻薄子，知妾解秦筝。','',''),('quantangshi-05708','魏宫词','崔國輔','quantangshi','','卷6','朝日照红妆，拟上铜雀台。
画眉犹未了，魏帝使人催。','',''),('quantangshi-05709','长信草','崔國輔','quantangshi','','卷6','长信宫中草，年年愁处生。
故侵珠履迹，不使玉阶行。','',''),('quantangshi-05710','长乐少年行','崔國輔','quantangshi','','卷6','遗却珊瑚鞭，白马骄不行。
章台折杨柳，春日路傍情。','',''),('quantangshi-05711','湖南曲','崔國輔','quantangshi','','卷6','湖南送君去，湖北送君归。
湖里鸳鸯鸟，双双他自飞。','',''),('quantangshi-05712','中流曲','崔國輔','quantangshi','','卷6','归时日尚早，更欲向芳洲。
渡口水流急，回船不自由。','',''),('quantangshi-05713','王孙游','崔國輔','quantangshi','','卷6','自与王孙别，频看黄鸟飞。
应由春草误，着处不成归。','',''),('quantangshi-05714','采莲曲','崔國輔','quantangshi','','卷6','玉溆花争发，金塘水乱流。
相逢畏相失，并着采莲舟。','',''),('quantangshi-05715','子夜冬歌','崔國輔','quantangshi','','卷6','寂寥抱冬心，裁罗又褧褧。
夜久频挑灯，霜寒剪刀冷。','',''),('quantangshi-05716','丽人曲','崔國輔','quantangshi','','卷6','红颜称绝代，欲并真无侣。
独有镜中人，由来自相许。','',''),('quantangshi-05717','小长干曲','崔國輔','quantangshi','','卷6','月暗送潮风，相寻路不通。
菱歌唱不彻，知在此塘中。','',''),('quantangshi-05718','王昭君','崔國輔','quantangshi','','卷6','汉使南还尽，胡中妾独存。
紫台绵望绝，秋草不堪论。','',''),('quantangshi-05719','秦女卷衣','崔國輔','quantangshi','','卷6','虽入秦帝宫，不上秦帝牀。
夜夜玉窗里，与他卷衣裳。','',''),('quantangshi-05720','今别离','崔國輔','quantangshi','','卷6','送别未能旋，相望连水口。
船行欲映洲，几度急摇手。','',''),('quantangshi-05721','衞艳词','崔國輔','quantangshi','','卷6','淇上桑叶青，青楼含白日。
比时遥望君，车马城中出。','',''),('quantangshi-05722','渭水西别李仑','崔國輔','quantangshi','','卷6','陇右长亭堠，山阴古塞秋。
不知呜咽水，何事向西流。','',''),('quantangshi-05723','古意','崔國輔','quantangshi','','卷6','净扫黄金阶，飞霜皎如雪。
下帘弹箜篌，不忍见秋月。','',''),('quantangshi-05724','送韩十四被鲁王推递往济南府','崔國輔','quantangshi','','卷6','西候情何极，南冠怨有余。
梁王虽好事，不察狱中书。','',''),('quantangshi-05725','白紵辞二首 一','崔國輔','quantangshi','','卷6','洛阳梨花落如霰，河阳桃叶生复齐。
坐惜玉楼春欲尽，红绵粉絮裛妆啼。','',''),('quantangshi-05726','白紵辞二首 二','崔國輔','quantangshi','','卷6','董贤女弟在椒风，窈窕繁华贵后宫。
璧带金釭皆翡翠，一朝零落变成空。','',''),('quantangshi-05727','九日','崔國輔','quantangshi','','卷6','江边枫落菊花黄，少长登高一望乡。
九日陶家虽载酒，三年楚客已霑裳。','',''),('quantangshi-05728','王昭君','崔國輔','quantangshi','','卷6','一回望月一回悲，望月月移人不移。
何时得见汉朝使，为妾传书斩画师。','',''),('quantangshi-05729','孤寝怨','崔珪','quantangshi','','卷6','征戍动经年，含情拂玳筵。
花飞织锦处，月落捣衣边。
灯暗愁孤坐，牀空怨独眠。
自君辽海去，玉匣闭春弦。','',''),('quantangshi-05730','题武陵草堂','楊浚','quantangshi','','卷6','草堂列仙楼，上在青山顶。
户外窥数峯，阶前对双井。
雨来花尽湿，风度松初冷。
登栈行不疲，入溪语弥静。
云能去尘服，兼欲事金鼎。
正直心所存，谄谀长自省。
适知幽遁趣，已觉烦虑屏。
更爱云林间，吾将卧南颍。','',''),('quantangshi-05731','广武怀古','楊浚','quantangshi','','卷6','河水城下流，登城望弥惬。
海云飞不断，岸草绿相接。
龙门无旧塲，武牢有遗堞。
扼喉兵易守，扪指计何捷。
天夺项氏谋，卒成汉家业。
乡山遥可见，西顾泪盈睫。','',''),('quantangshi-05732','赠李郎中','楊浚','quantangshi','','卷6','仙郎早朝退，直省卧南轩。
院竹自成赏，阶庭寂不喧。
焚香开后阁，起草闭前门。
礼乐风流美，光华星位尊。
荣兼朱绂贵，交乃布衣存。
是日登龙客，无忘君子恩。','',''),('quantangshi-05733','咏王大娘戴卒','劉晏','quantangshi','','卷6','楼前百戏竞争新，唯有长竿妙入神。
谁谓绮罗[翻]有力，犹自嫌轻更着人。','',''),('quantangshi-05734','享太庙乐章','劉晏','quantangshi','','卷6','汉祚惟永，神功中兴。
夙驱氛祲，天覆黎蒸。
三光再朗，庶绩其凝。
重熙累叶，景命是膺。','',''),('quantangshi-05735','鸿门行','袁瓘','quantangshi','','卷6','少年买意气，百金不辞费。
学劒西入秦，结交北游魏。
秦魏多豪人，与代亦殊伦。
由来不相识，皆是暗相亲。
宝马青丝辔，狐裘貂鼠服。
晨过剧孟游，暮投咸阳宿。
然诺本云云，诸侯莫不闻。
犹思百战术，更逐李将军。
始从灞陵下，遥遥度朔野。
北风闻楚歌，南庭见胡马。
胡马秋正肥，相邀夜合围。
战酣烽火灭，路断救兵稀。
白刃纵横逼，黄尘飞不息。
虏骑血洒衣，单于泪沾臆。
献凯云台中，自言塞上雄。
将军行失势，部曲遂无功。
新人不如旧，旧人不相救。
万里长飘颻，十年计不就。
弃置难重论，驱马度鸿门。
行看楚汉事，不觉风尘昏。
宝劒中夜抚，悲歌聊自舞。
此曲不可终，曲终泪如雨。','',''),('quantangshi-05736','惠文太子挽歌','袁瓘','quantangshi','','卷6','寒仗丹旄引，阴堂白日违。
暗灯明象物，画水湿灵衣。
羽化淮王去，仙迎太子归。
空余燕衔土，朝夕向陵飞。','',''),('quantangshi-05737','从军行','李昂','quantangshi','','卷6','汉家未得燕支山，征戍年年沙朔间。
塞下长驱汗血马，云中恒闭玉门关。
阴山翰海千万里，此日桑河冻流水。
稽洛川边胡骑来，渔阳戍里烽烟起。
长途羽檄何相望，天子按劒思北方。
羽林练士拭金甲，将军校战出玉堂。
幽陵异域风烟改，亭障连连古今在。
夜闻鸿雁南渡河，晓望旌旗北临海。
塞沙飞淅沥，遥裔连穷碛。
玄漠云平初合阵，西山月出闻鸣镝。
城南百战多苦辛，路傍死卧黄沙人。
戎衣不脱随霜雪，汗马䟃𧽼长被铁。
杨叶楼中不寄书，莲花劒上空流血。
匈奴未灭不言家，驱逐行行边徼赊。
归心海外见明月，别思天边梦落花。
天边回望何悠悠，芳树无人渡陇头。
春云不变阳关雪，桑叶先知胡地秋。
田畴不卖卢龙策，窦宪思勒燕然石。
麾兵静北垂，此日交河湄。
欲令塞上无干戚，会待单于系颈时。','',''),('quantangshi-05738','赋戚夫人楚舞歌','李昂','quantangshi','','卷6','定陶城中是妾家，妾年二八颜如花。
闺中歌舞未终曲，天下死人如乱麻。
汉王此地因征战，未出帘栊人已荐。
风花菡萏落辕门，云雨裴回入行殿。
日夕悠悠非旧乡，飘飘处处逐君王。
闺门向里通归梦，银烛迎来在战场。
相从顾恩不顾己，何异浮萍寄深水。
逐战曾迷只轮下，随君几陷重围里。
此时平楚复平齐，咸阳宫阙到关西。
珠帘夕殿闻钟磬，白日秋天忆鼓鼙。
君王纵恣翻成误，吕后由来有深妬。
不奈君王容鬓衰，相存相顾能几时。
黄泉白骨不可报，雀钗翠羽从此辞。
君楚歌兮妾楚舞，脉脉相看两心苦。
曲未终兮袂更扬，君流涕兮妾断肠。
已见储君归惠帝，徒留爱子付周昌。','',''),('quantangshi-05739','句','李昂','quantangshi','','卷6','耳临清渭洗，心向白云闲。','',''),('quantangshi-05740','夏晚初霁南省寓直用余字','厙狄履溫','quantangshi','','卷6','薄宦因时泰，凉宵寓直初。
沈沈仙阁闭，的的暗更徐。
霁色连空上，炎氛入夜除。
星回南斗落，月度北窗虚。
待漏残灯照，含芳袭气余。
寐来冠不解，奏罢草仍书。
幕府慙良策，明曹愧散樗。
命轻徒有报，义重更难疎。
燕厦欣成托，鵷行滥所如。
晨趋当及早，复此戒朝车。','',''),('quantangshi-05741','同皇甫兵曹天官寺浴室新成招友人赏会','寇坦','quantangshi','','卷6','温室欢初就，兰交托胜因。
共听无漏法，兼濯有为尘。
水洁三空性，香沾四大身。
清心多善友，颂德慰同人。','',''),('quantangshi-05742','同张少府和厍狄员外夏晚初霁南省寓直时兼充节度判官之作','寇坦','quantangshi','','卷6','黄绶归休日，仙郎复奏余。
晏居当夏晚，寓直会晴初。
露散星文发，云披水镜虚。
高才推独唱，嘉会喜连茹。
月色摇春闼，香烟霭暝庐。
千门传夜警，万象照阶除。
少孺嘉能赋，文强阅赐书。
兼曹谋未展，入幕志方摅。
为奉灵台帛，恭先待漏车。
贞标不可仰，空此乐樵渔。','',''),('quantangshi-05743','咏铜柱','李休烈','quantangshi','','卷6','天门街里倒天枢，火急先须卸火珠。
计合一条丝线挽，何劳两县索人夫。','',''),('quantangshi-05744','送贺监归四明应制','李林甫','quantangshi','','卷6','挂冠知止足，岂独汉疏贤。
入道求真侣，辞恩访列仙。
睿文含日月，宸翰动云烟。
鹤驾吴乡远，遥遥南斗边。','',''),('quantangshi-05745','奉和圣制次琼岳应制','李林甫','quantangshi','','卷6','东幸从人望，西巡顺物回。
云收二华出，天转五星来。
十月农初罢，三驱礼复开。
更看琼岳上，佳气接神台。','',''),('quantangshi-05746','秋夜望月忆韩席等诸侍郎因以投赠','李林甫','quantangshi','','卷6','秋天碧云夜，明月悬东方。
皓皓庭际色，稍稍林下光。
桂华澄远近，璧彩散池塘。
鸿雁飞难度，关山曲易长。
揆予秉孤直，虚薄忝文昌。
握镜惭先照，持衡愧后行。
多才众君子，载笔久词场。
作赋推潘岳，题诗许谢康。
当时陪宴语，今夕恨相望。
愿欲接高论，清晨朝建章。','',''),('quantangshi-05747','流崖州至鬼门关作','楊炎','quantangshi','','卷6','一去一万里，千知千不还。
崖州何处在？生度鬼门关。','',''),('quantangshi-05748','赠元载歌妓','楊炎','quantangshi','','卷6','雪面淡眉天上女，凤箫鸾翅欲飞去。
玉山翘翠步无尘，楚腰如柳不胜春。','',''),('quantangshi-05749','别妻王韫秀','載','quantangshi','','卷6','年来谁不厌龙钟，虽在侯门似不容。
看取海山寒翠树，苦遭霜霰到秦封。','',''),('quantangshi-05750','赋得云生栋梁间','陳希烈','quantangshi','','卷6','一片苍梧意，氤氲生栋梁。
下帘山足暗，开户日添光。
偏使衣裘润，能令枕簟凉。
无心伴行雨，何必梦荆王。','',''),('quantangshi-05751','奉和圣制三月三日','陳希烈','quantangshi','','卷6','上巳迂龙驾，中流泛羽觞。
酒因朝太子，诗为乐贤王。
锦缆方舟渡，琼筵大乐张。
风摇垂柳色，花发异林香。
野老歌无事，朝臣饮岁芳。
皇情被羣物，中外洽恩光。','',''),('quantangshi-05752','省试白云起封中','陳希烈','quantangshi','','卷6','千年泰山顶，云起汉王封。
不作奇峰状，宁分触石容。
为霖虽易得，表圣自难逢。
冉冉排空上，依依叠影重。
素光非曳练，灵贶是从龙。
岂学无心出，东西任所从。','',''),('quantangshi-05753','朗月行','張漸','quantangshi','','卷6','朗月照帘幌，清夜有余姿。
洞房怨孤枕，挟琴爱前墀。
萱草已数叶，梨花复徧枝。
去岁草始荣，与君新相知。
今年花未落，谁分生别离。
代情难重论，人事好乖移。
合比月华满，分同月易亏。
亏月当再圆，人别星陨天。
吾欲竟此曲，意深不可传。
叹息孤鸾鸟，伤心明镜前。','',''),('quantangshi-05754','晓次荆江','昱','quantangshi','','卷6','孤舟大江水，水涉无昏曙。
雨暗迷津时，云生望乡处。
渔翁闲自乐，樵客纷多虑。
秋色湖上山，归心日边树。
徒称竹箭美，未得枫林趣。
向夕垂钓还，吾从落潮去。','',''),('quantangshi-05755','题石窟寺','昱','quantangshi','','卷6','梵宇开金地，香龛凿铁围。
影中羣象动，空里众灵飞。
檐牖笼朱旭，房廊挹翠微。
瑞莲生佛步，瑶树挂天衣。
邀福功虽在，兴王代久非。
谁知云朔外，更覩化胡归。','',''),('quantangshi-05756','樟亭观涛','昱','quantangshi','','卷6','涛来势转雄，猎猎驾长风。
雷震云霓里，山飞霜雪中。
激流起平地，吹涝上侵空。
翕辟干坤异，盈虚日月同。
艅艎从陆起，洲浦隔阡通。
跳沫喷岩翠，翻波带景红。
怒湍初抵北，却浪复归东。
寂听堪增勇，晴看自发蒙。
伍生传或谬，枚叟说难穷。
来信应无已，申威亦匪躬。
冲腾如决胜，回合似相攻。
委质任平视，谁能涯始终。','',''),('quantangshi-05757','赠程秘书','盧象','quantangshi','','卷6','客自岐阳来，吐音若鸣凤。
孤飞畏不偶，独立谁见用。
忽从被褐中，召入承明宫。
圣人借颜色，言事无不通。
殷勤拯黎庶，感激论诸公。
将相猜贾谊，图书归马融。
顾余久寂寞，一岁麒麟阁。
且共歌太平，勿嗟名宦薄。','',''),('quantangshi-05758','家叔征君东溪草堂二首 一','盧象','quantangshi','','卷6','开山十余里，青壁森相倚。
欲识尧时天，东溪白云是。
雷声转幽壑，云气杳流水。
涧影生龙蛇，岩端翳柽梓。
大道终不易，君恩曷能已。
鹤羡无老时，龟言摄生理。
浮年笑六甲，元化潜一指。
未暇扫云梯，空慙阮氏子。','',''),('quantangshi-05759','家叔征君东溪草堂二首 二','盧象','quantangshi','','卷6','今朝共游者，得性闲未归。
已到仙人家，莫惊鸥鸟飞。
水深严子钓，松挂巢父衣。
云气转幽寂，溪流无是非。
名理未足羡，腥臊讵所希。
自惟负贞意，何岁当食薇。','',''),('quantangshi-05760','乡试后自巩还田家因谢邻友见过之作','盧象','quantangshi','','卷6','鸡鸣出东邑，马倦登南峦。
落日见桑柘，翳然丘中寒。
邻家多旧识，投暝来相看。
且问春税苦，兼陈行路难。
园场近阴壑，草木易凋残。
峰晴雪犹积，涧深冰已团。
浮名知何用，岁晏不成欢。
置酒共君饮，当歌聊自宽。','',''),('quantangshi-05761','青雀歌','盧象','quantangshi','','卷6','啾啾青雀儿，飞来飞去仰天池。
逍遥饮啄安涯分，何假扶摇九万为。','',''),('quantangshi-05762','杂诗二首 一','盧象','quantangshi','','卷6','家居五原上，征战是平生。
独负山西勇，谁当塞下名。
死生辽海战，雨雪蓟门行。
诸将封侯尽，论功独不成。','',''),('quantangshi-05763','杂诗二首 二','盧象','quantangshi','','卷6','君家御沟上，垂柳夹朱门。
列鼎会中贵，鸣珂朝至尊。
死生在片议，穷达由一言。
须识苦寒士，莫矜狐白温。','',''),('quantangshi-05764','赠广川马先生','盧象','quantangshi','','卷6','经书满腹中，吾识广川翁。
年老甘无位，家贫懒发蒙。
人归洙泗学，歌盛舞雩风。
愿接诸生礼，三年事马融。','',''),('quantangshi-05765','峡中作','盧象','quantangshi','','卷6','高唐几百里，树色接阳台。
晚见江山霁，宵闻风雨来。
云从三峡起，天向数峰开。
灵境信难见，轻舟那可回。','',''),('quantangshi-05766','竹里馆','盧象','quantangshi','','卷6','江南冰不闭，山泽气潜通。
腊月闻山鸟，寒崖见蛰熊。
柳林春半合，荻笋乱无丛。
回首金陵岸，依依向北风。','',''),('quantangshi-05767','永城使风','盧象','quantangshi','','卷6','长风起秋色，细雨含落晖。
夕鸟向林去，晚帆相逐飞。
虫声出乱草，水气薄行衣。
一别故乡道，悠悠今始归。','',''),('quantangshi-05768','和徐侍郎丛筱咏','盧象','quantangshi','','卷6','中禁夕沈沈，幽篁别作林。
色连鸡树近，影落凤池深。
为重凌霜节，能虚应物心。
年年承雨露，长对紫庭阴。','',''),('quantangshi-05769','驾幸温泉','盧象','quantangshi','','卷6','传闻圣主幸新丰，清跸鸣銮出禁中。
细草终朝随步辇，垂杨几处绕行宫。
千官扈从骊山北，万国来朝渭水东。
此日小臣徒献赋，汉家谁复重[扬]雄。','',''),('quantangshi-05770','奉和张使君宴加朝散','盧象','quantangshi','','卷6','佐理星辰贵，分荣涣汗深。
言从大夫后，用答圣人心。
骑拥轩裳客，鸾惊翰墨林。
停杯歌麦秀，秉烛醉棠阴。
爽气凌秋笛，轻寒散暝砧。
秪应将四子，讲德谢知音。','',''),('quantangshi-05771','赠张均员外','盧象','quantangshi','','卷6','公门世绪昌，才子冠裴王。
出自平津邸，还为吏部郎。
神仙余气色，列宿动辉光。
夜直南宫静，朝趋北禁长。
时人归水镜，明主赐衣裳。
翰苑飞鹦鹉，天池待凤凰。
承欢畴日顾，未纪后时伤。
去去图南远，微才幸不忘。','',''),('quantangshi-05772','送祖咏','盧象','quantangshi','','卷6','田家宜伏腊，岁晏子言归。
石路雪初下，荒村鸡共飞。
东原多烟火，北涧隐寒晖。
满酌野人酒，倦闻邻女机。
胡为困樵采，几日罢朝衣。','',''),('quantangshi-05773','送綦毋潜','盧象','quantangshi','','卷6','夫君不得意，本自沧海来。
高足未云骋，虚舟空复回。
淮南枫叶落，灞岸桃花开。
出处暂为耳，沈浮安系哉。
如何天覆物，还遣世遗才。
欲识秦将汉，尝闻王与裴。
离筵对寒食，别雨乘春雷。
会有征书到，荷衣且漫裁。','',''),('quantangshi-05774','送赵都护赴安西','盧象','quantangshi','','卷6','下客候旌麾，元戎复在斯。
门开都护府，兵动羽林儿。
黠虏多翻覆，谋臣有别离。
智同天所授，恩共日相随。
汉使开宾幕，胡笳送酒巵。
风霜迎马首，雨雪事鱼丽。
上策应无战，深情属载驰。
不应行万里，明主寄安危。','',''),('quantangshi-05775','追凉历下古城西北隅此地有清泉乔木','盧象','quantangshi','','卷6','谢朓出华省，王祥贻佩刀。
前贤真可慕，衰病意空劳。
贞悔不自卜，游随共尔曹。
未能齐得丧，时复诵离骚。
闲荫七贤地，醉餐三士桃。
苍苔虞舜井，乔木古城壕。
渔父偏相狎，尧年不可逃。
蝉鸣秋雨霁，云白晓山高。
咫尺传双鲤，吹嘘借一毛。
故人皆得路，谁肯念同袍。','',''),('quantangshi-05776','戏赠邵使君张郎','盧象','quantangshi','','卷6','少妇石榴裙，新妆白玉面。
能迷张公子，不许时相见。','',''),('quantangshi-05777','同王维过崔处士林亭','盧象','quantangshi','','卷6','映竹时闻转辘轳，当窗只见网蜘蛛。
主人非病常高卧，环堵蒙笼一老儒。','',''),('quantangshi-05778','寄河上段十六','盧象','quantangshi','','卷6','与君相识即相亲，闻道君家住孟津。
为见行舟试借问，客中时有洛阳人。','',''),('quantangshi-05779','寒食','盧象','quantangshi','','卷6','子推言避世，山火遂焚身。
四海同寒食，千秋为一人。
深冤何用道，峻迹古无邻。
魂魄山河气，风雷御宇神。
光烟榆柳灭，怨曲龙虵新。
可叹文公霸，平生负此臣。','',''),('quantangshi-05780','八月十五日象自江东止田园移庄庆会未几归汶上小弟幼妹尤嗟其别兼赋是诗三首 一','盧象','quantangshi','','卷6','谢病始告归，依然入桑梓。
家人皆伫立，相候衡门里。
畴类皆长年，成人旧童子。
上堂家庆毕，愿与亲姻迩。
论旧或余悲，思存且相喜。
田园转芜没，但有寒泉水。
衰柳日萧条，秋光清邑里。
入门乍如客，休骑非便止。
中饮顾王程，离忧从此始。','',''),('quantangshi-05781','八月十五日象自江东止田园移庄庆会未几归汶上小弟幼妹尤嗟其别兼赋是诗三首 二','盧象','quantangshi','','卷6','两妹日长成，双鬟将及人。
已能持宝瑟，自解掩罗巾。
念昔别时小，未知疎与亲。
今来识离恨，掩泪方殷勤。','',''),('quantangshi-05782','八月十五日象自江东止田园移庄庆会未几归汶上小弟幼妹尤嗟其别兼赋是诗三首 三','盧象','quantangshi','','卷6','小弟更孩幼，归来不相识。
同居虽渐惯，见人犹默默。
宛作越人言，殊乡甘水食。
别此最为难，泪尽有余忆。','',''),('quantangshi-05783','叹白发','盧象','quantangshi','','卷6','我年一何长，鬓发日已白。
俛仰天地间，能为几时客。
惆怅故山云，裴回空日夕。
何事与时人，东城复南陌。','',''),('quantangshi-05784','早秋宴张郎中海亭即事','盧象','quantangshi','','卷6','邑有弦歌宰，翔鸾狎野鸥。
眷言华省旧，暂滞海池游。
郁岛藏深竹，前溪对舞楼。
更闻书即事，云物是新秋。','',''),('quantangshi-05785','句','盧象','quantangshi','','卷6','吴越山多秀，新安江甚清。
书名会粹才偏逸，酒号屠苏味更醇。
初疑轻烟淡古松，又似山开万仞峰。','',''),('quantangshi-05786','嵩山十志十首 其一','盧鴻一','quantangshi','','卷6','山为宅兮草为堂，芝兰兮药房。
罗蘼芜兮拍薜荔，荃壁兮兰砌。
蘼芜薜荔兮成草堂，阴阴邃兮馥馥香。
中有人兮信宜常，读金书兮饮玉浆，童颜幽操兮不易长。','',''),('quantangshi-05787','嵩山十志十首 其二','盧鴻一','quantangshi','','卷6','天门豁兮仙台耸，杰屹崒兮零澒涌。
穷三休兮旷一观，忽若登昆仑兮中期汗漫仙。
耸天关兮倒景台，鲨颢气兮轶嚣埃。
皎皎之子兮自独立，云可朋兮赮可吸，曾何荣辱之所及。','',''),('quantangshi-05788','嵩山十志十首 其三','盧鴻一','quantangshi','','卷6','紫岩隈兮青溪侧，云松烟茑兮千古色。
芳靃蘼兮荫蒙茏，幽人构馆兮在其中。
靃蘼蒙茏兮开樾馆，卧风霄兮坐赮旦。
粤有宾兮时戾止，樵苏不爨兮清淡已，永岁终朝兮常若此。','',''),('quantangshi-05789','嵩山十志十首 其四','盧鴻一','quantangshi','','卷6','临泱漭兮背青荧，吐云烟兮合窅冥。
怳欻翕兮杳幽霭，意缥缈兮羣仙会。
窅冥仙会兮枕烟庭，竦魂形兮凝视听。
闻夫至诚必感兮祈此巅，契颢气，养丹田，终彷像兮觏灵仙。','',''),('quantangshi-05790','嵩山十志十首 其五','盧鴻一','quantangshi','','卷6','水攒冲兮石丛耸，焕云锦兮喷汹涌。
苔驳荦兮草夤缘，芳幂幂兮濑溅溅。
石攒丛兮云锦淙，波连珠兮文沓綘。
有洁冥者媚此幽，漱灵液兮乐天休，实获我心兮夫何求。','',''),('quantangshi-05791','嵩山十志十首 其六','盧鴻一','quantangshi','','卷6','霏微阴壑兮气腾虹，迤逦危磴兮上凌空。
青霞杪兮紫云垂，鸾歌凤舞兮吹参差。
鸾吹凤舞兮期仙磴，鸿驾迎兮瑶华赠。
山中人兮好神仙，想像闻此兮欲升烟，铸月炼液兮竚还年。','',''),('quantangshi-05792','嵩山十志十首 其七','盧鴻一','quantangshi','','卷6','灵矶盘礴兮溜奔错漱，冷风兮镇冥壑。
研苔滋兮泉珠洁，一饮一憩兮气想灭。
磷涟清淬兮涤烦矶，灵仙境兮仁智归。
中有琴兮徽以玉，峨峨汤汤兮弹此曲，寄声知音兮同所欲。','',''),('quantangshi-05793','嵩山十志十首 其八','盧鴻一','quantangshi','','卷6','青崖阴兮月磵曲，重幽叠邃兮隐沦躅。
草树緜幂兮翠蒙茏，当其无兮庭在中。
当无有用兮幂翠庭，神可谷兮道可冥。
有幽人兮张素琴，皇徽兮绿水阴，德之愔兮澹多心。','',''),('quantangshi-05794','嵩山十志十首 其九','盧鴻一','quantangshi','','卷6','岚气肃兮岩翠冥，空阴虚兮户芳迎。
披蕙帐兮促萝筵，谈空空兮核元元。
蕙帐萝筵兮洞元室，祕而幽兮真可吉。
返自然兮道可冥，泽妙思兮草玄经，结幽门兮在黄庭。','',''),('quantangshi-05795','嵩山十志十首 其十','盧鴻一','quantangshi','','卷6','水碧色兮石金光，滟熠熠兮濙湟湟。
泉葩映兮烟茑临，红灼灼，翠阴阴。
翠相鲜兮金碧潭，霜天洞兮烟景涵。
有幽人兮好冥绝，炳其焕兮凝其洁，悠悠千古长不灭。','',''),('quantangshi-05796','书殿赐宴应制','徐安貞','quantangshi','','卷6','校文常近日，赐宴忽升天。
酒正传杯至，饔人捧案前。
玉阶鸣溜水，清阁引归烟。
共惜芸香暮，春风几万年。','',''),('quantangshi-05797','从驾温泉宫','徐安貞','quantangshi','','卷6','神女调温液，年年待圣人。
试开临水殿，来洗属车尘。
暖气随明主，恩波浃近臣。
灵威自无极，从此献千春。','',''),('quantangshi-05798','送吕向补阙西岳勒碑','徐安貞','quantangshi','','卷6','圣作西山颂，君其出使年。
勒碑悬日月，驱传接云烟。
寒尽函关路，春归洛水边。
别离能几许，朝暮玉墀前。','',''),('quantangshi-05799','送丹阳采访','徐安貞','quantangshi','','卷6','郡县分南国，皇华出圣朝。
为怜乡棹近，不道使车遥。
旧俗吴三让，遗风汉六条。
愿言除疾苦，天子听歌谣。','',''),('quantangshi-05800','送王判官','徐安貞','quantangshi','','卷6','明月开三峡，花源出五溪。
城池青壁里，烟火绿林西。
不畏王程促，惟愁仙路迷。
巴东下归棹，莫待夜猨啼。','',''),('quantangshi-05801','题襄阳图','徐安貞','quantangshi','','卷6','画得襄阳郡，依然见昔游。
岘山思驻马，汉水忆回舟。
丹壑常含霁，青林不换秋。
图书空咫尺，千里意悠悠。','',''),('quantangshi-05802','程将军夫人挽诗','徐安貞','quantangshi','','卷6','琴瑟调双凤，和鸣不独飞。
正歌春可乐，行泣露先曦。
环佩声犹在，房栊梦不归。
将军休沐日，谁劝着新衣。','',''),('quantangshi-05803','奉和喜雪应制','徐安貞','quantangshi','','卷6','两宫斋祭近登临，雨雪纷纷天昼阴。
祗为经寒无瑞色，顿教正月满春林。
蓬莱北上旌门暗，花萼南归马迹深。
自有三农歌帝力，还将万庾答尧心。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-05804','闻邻家理筝','徐安貞','quantangshi','','卷6','北斗横天夜欲阑，愁人倚月思无端。
忽闻画阁秦筝逸，知是邻家赵女弹。
曲成虚忆青蛾敛，调急遥怜玉指寒。
银锁重关听未辟，不如眠去梦中看。','',''),('quantangshi-05805','奉和圣制早度蒲津关','徐安貞','quantangshi','','卷6','仙掌临秦甸，虹桥辟晋关。
两都分地险，一曲度河湾。
路得津门要，时称古戍闲。
城花春正发，岸柳曙堪攀。
后乘犹临水，前旌欲换山。
长安回望日，宸御六龙还。','',''),('quantangshi-05806','奉和圣制答二相出雀鼠谷','徐安貞','quantangshi','','卷6','两臣初入梦，二月扈巡边。
涧北寒犹在，山南春半传。
颂声先奉御，辰象复回天。
云日明千里，旌旗照一川。
柳阴低辇路，草色变新田。
还望汾阳近，宸游自窅然。','',''),('quantangshi-05807','句','徐安貞','quantangshi','','卷6','暮雨衣犹湿，春风帆正开。','',''),('quantangshi-05808','奉和圣制答张说南出雀鼠谷','崔翹','quantangshi','','卷6','硖路绕河汾，晴光拂曙氛。
笳吟中岭树，仗入半峰云。
顿觉山原尽，平看邑里分。
早行芳草迥，晚憩好风熏。
嘉颂推英宰，春游扈圣君。
共欣承睿渥，日月照天文。','',''),('quantangshi-05809','送友人使夷陵','崔翹','quantangshi','','卷6','猨鸣三峡里，行客旧霑裳。
复道从兹去，思君不暂忘。
开襟春叶短，分手夏条长。
独有幽庭桂，年年空自芳。','',''),('quantangshi-05810','郑郎中山亭','崔翹','quantangshi','','卷6','篆笔飞章暇，园亭染翰游。
地奇人境别，事远俗尘收。
书阁山云起，琴斋涧月留。
泉清鳞影见，树密鸟声幽。
杜馥熏梅雨，荷香送麦秋。
无劳置驿骑，文酒可相求。','',''),('quantangshi-05811','奉和圣制答张说扈从南出雀鼠谷','梁昇卿','quantangshi','','卷6','何意重关道，千年过圣皇。
幽林承睿泽，闲客见清光。
日御仙途远，山灵寿域长。
寒云入晋薄，春树隔汾香。
国佐同时雨，天文属岁阳。
从来汉家盛，未若此巡方。','',''),('quantangshi-05812','白云溪','吳鞏','quantangshi','','卷6','山径入修篁，深林蔽日光。
夏云生嶂远，瀑水引溪长。
秀迹逢皆胜，清芬坐转凉。
回看玉樽夕，归路赏前忘。','',''),('quantangshi-05813','题奉国寺','陸海','quantangshi','','卷6','新秋夜何爽，露下风转凄。
一磐竹林外，千灯花塔西。','',''),('quantangshi-05814','题龙门寺','陸海','quantangshi','','卷6','窗灯林霭里，闻磬水声中。
更与龙华会，炉烟满夕风。','',''),('quantangshi-05815','句','陸海','quantangshi','','卷6','忽然一曲称君心，破却中人百家产。
城外平人驱欲尽，帐中犹打衮花球。','',''),('quantangshi-05816','白牡丹','裴士淹','quantangshi','','卷6','长安年少惜春残，争认慈恩紫牡丹。
别有玉盘乘露冷，无人起就月中看。','',''),('quantangshi-05817','和从叔禄愔元日早朝','李元操','quantangshi','','卷6','铜浑变秋节，玉律动年灰。
暧暧城霞旦，隐隐禁门开。
众灵凑仙府，百神朝帝台。
叶令双凫至，梁王驷马来。
戈鋋映林阙，歌管拂尘埃。
保章望瑞气，尚书免火灾。
冠冕多秀士，簪裾饶上才。
谁怜张仲蔚，日暮反蒿莱。','',''),('quantangshi-05818','昭君怨','顧朝陽','quantangshi','','卷6','莫将铅粉匣，不用镜花光。
一去边城路，何情更画妆。
影销胡地月，衣尽汉宫香。
妾死非关命，都缘怨断肠。','',''),('quantangshi-05819','西塞山下回舟作','陶峴','quantangshi','','卷6','匡庐旧业是谁主，吴越新居安此生。
白发数茎归未得，青山一望计还成。
鸦翻枫叶夕阳动，鹭立芦花秋水明。
从此舍舟何所诣，酒旗歌扇正相迎。','',''),('quantangshi-05820','酬诸公见过','王維','quantangshi','','卷6','嗟予未丧，哀此孤生。
屏居蓝田，薄地躬耕。
岁[晏]输税，以奉粢盛。
晨往东臯，草露未曦。
暮看烟火，负担来归。
我闻有客，足埽荆扉。
箪食伊何，疈瓜抓枣。
仰厕羣贤，皤然一老。
愧无莞簟，班荆席藁。
泛泛登陂，折彼荷花。
静观素鲔，俯映白沙。
山鸟羣飞，日隐轻霞。
登车上马，倏忽云散。
雀噪荒村，鸡鸣空馆。
还复幽独，重欷累叹。','',''),('quantangshi-05821','奉和圣制登降圣观与宰臣等同望应制','王維','quantangshi','','卷6','凤扆朝碧落，龙图耀金镜。
维岳降二臣，戴天临万姓。
山川八校满，井邑三农竟。
比屋皆可封，谁家不相庆。
林疎远村出，野旷寒山静。
帝城云里深，渭水天边映。
佳气含风景，颂声溢歌咏。
端拱能任贤，弥彰圣君圣。','',''),('quantangshi-05822','奉和圣制御春明楼临右相园亭赋乐贤诗应制','王維','quantangshi','','卷6','复道通长乐，青门临上路。
遥闻凤吹喧，暗识龙舆度。
褰旒明四目，伏槛纡三顾。
小苑接侯家，飞甍暎宫树。
商山原上碧，浐水林端素。
银汉下天章，琼筵承湛露。
将非富人宠，信以平戎故。
从来简帝心，讵得回天步。','',''),('quantangshi-05823','奉和圣制送不蒙都护兼鸿胪卿归安西应制','王維','quantangshi','','卷6','上卿增命服，都护扬归斾。
杂虏尽朝周，诸胡皆自郐。
鸣笳瀚海曲，按节阳关外。
落日下河源，寒山静秋塞。
万方氛祲息，六合干坤大。
无战是天心，天心同覆载。','',''),('quantangshi-05824','扶南曲歌词五首 一','王維','quantangshi','','卷6','翠羽流苏帐，春眠曙不开。
羞从面色起，娇逐语声来。
早向昭阳殿，君王中使催。','',''),('quantangshi-05825','扶南曲歌词五首 二','王維','quantangshi','','卷6','堂上青弦动，堂前绮席陈。
齐歌卢女曲，双舞洛阳人。
倾国徒相看，宁知心所亲。','',''),('quantangshi-05826','扶南曲歌词五首 三','王維','quantangshi','','卷6','香气传空满，妆华影箔通。
歌闻天仗外，舞出御楼中。
日暮归何处，花间长乐宫。','',''),('quantangshi-05827','扶南曲歌词五首 四','王維','quantangshi','','卷6','宫女还金屋，将眠复畏明。
入春轻衣好，半夜薄妆成。
拂曙朝前殿，玉墀多佩声。','',''),('quantangshi-05828','扶南曲歌词五首 五','王維','quantangshi','','卷6','朝日照绮窗，佳人坐临镜。
散黛恨犹轻，插钗嫌未正。
同心勿遽游，幸待春妆竟。','',''),('quantangshi-05829','陇西行','王維','quantangshi','','卷6','十里一走马，五里一扬鞭。
都护军书至，匈奴围酒泉。
关山正飞雪，烽戍断无烟。','',''),('quantangshi-05830','从军行','王維','quantangshi','','卷6','吹角动行人，喧喧行人起。
笳悲马嘶乱，争渡金河水。
日暮沙漠陲，战声烟尘里。
尽系名王颈，归来献天子。','',''),('quantangshi-05831','早春行','王維','quantangshi','','卷6','紫梅发初遍，黄鸟歌犹澁。
谁家折杨女，弄春如不及。
爱水看妆坐，羞人映花立。
香畏风吹散，衣愁露霑湿。
玉闺青门里，日落香车入。
游衍益相思，含啼向彩帷。
忆君长入梦，归晚更生疑。
不及红檐燕，双栖绿草时。','',''),('quantangshi-05832','早朝','王維','quantangshi','','卷6','皎洁明星高，苍茫远天曙。
槐雾暗不开，城鸦鸣稍去。
始闻高阁声，莫辨更衣处。
银烛已成行，金门俨驺驭。','',''),('quantangshi-05833','献始兴公','王維','quantangshi','','卷6','宁栖野树林，宁饮涧水流。
不用坐[粱]肉，崎岖见王侯。
鄙哉匹夫节，布褐将白头。
任智诚则短，守任固其优。
侧闻大君子，安问党与讐。
所不卖公器，动为苍生谋。
贱子跪自陈，可为帐下不。
感激有公议，曲私非所求。','',''),('quantangshi-05834','赠从弟司库员外絿','王維','quantangshi','','卷6','少年识事浅，强学干名利。
徒闻跃马年，苦无出人智。
即事岂徒言，累官非不试。
既寡遂性欢，恐招负时累。
清冬见远山，积雪凝苍翠。
浩然出东林，发我遗世意。
惠连素清赏，夙语尘外事。
欲缓携手期，流年一何驶。','',''),('quantangshi-05835','座上走笔赠薛璩慕容损','王維','quantangshi','','卷6','希世无高节，绝迹有卑栖。
君徒视人文，吾固和天倪。
缅然万物始，及与羣物齐。
分地依后稷，用天信重黎。
春风何豫人，令我思东溪。
草色有佳意，花枝稍含荑。
更待风景好，与君藉萋萋。','',''),('quantangshi-05836','赠李颀','王維','quantangshi','','卷6','闻君饵丹砂，甚有好颜色。
不知从今去，几时生羽翼。
王母翳华芝，望尔昆仑侧。
文螭从赤豹，万里方一息。
悲哉世上人，甘此膻腥食。','',''),('quantangshi-05837','赠刘蓝田','王維','quantangshi','','卷6','篱间犬迎吠，出屋候荆扉。
岁晏输井税，山村人夜归。
晚田始家食，余布成我衣。
讵肯无公事，烦君问是非。','',''),('quantangshi-05838','赠房卢氏琯','王維','quantangshi','','卷6','达人无不可，忘己爱苍生。
岂复少十室，弦歌在两楹。
浮人日已归，但坐事农耕。
桑榆郁相望，邑里多鸡鸣。
秋山一何净，苍翠临寒城。
视事兼偃卧，对书不簪缨。
萧条人吏疎，鸟雀下空庭。
鄙夫心所尚，晚节异平生。
将从海岳居，守静解天刑。
或可累安邑，茅茨君试营。','',''),('quantangshi-05839','赠祖三咏','王維','quantangshi','','卷6','蟏蛸挂虚牖，蟋蟀鸣前除。
岁晏凉风至，君子复何如。
高馆阒无人，离居不可道。
闲门寂已闭，落日照秋草。
虽有近音信，千里阻河关。
中复客汝颍，去年归旧山。
结交二十载，不得一日展。
贫病子既深，契阔余不浅。
仲秋虽未归，暮秋以为期。
良会讵几日，终日长相思。','',''),('quantangshi-05840','春夜竹亭赠钱少府归蓝田','王維','quantangshi','','卷6','夜静羣动息，时闻隔林犬。
却忆山中时，人家涧西远。
羡君明发去，采蕨轻轩冕。','',''),('quantangshi-05841','戏赠张五弟諲三首 一','王維','quantangshi','','卷6','吾弟东山时，心尚一何远。
日高犹自卧，钟动始能饭。
领上髪未梳，牀头书不卷。
清川兴悠悠，空林对偃蹇。
青苔石上净，细草松下软。
窗外鸟声闲，阶前虎心善。
徒然万象多，澹尔太虚缅。
一知与物平，自顾为人浅。
对君忽自得，浮念不烦遣。','',''),('quantangshi-05842','戏赠张五弟諲三首 二','王維','quantangshi','','卷6','张弟五车书，读书仍隐居。
染翰过草圣，赋诗轻子虚。
闭门二室下，隐居十年余。
宛是野人野，时从渔夫渔。
秋风自萧索，五柳高且疎。
望此去人世，渡水向吾庐。
岁晏同携手，只应君与予。','',''),('quantangshi-05843','戏赠张五弟諲三首 三','王維','quantangshi','','卷6','设罝守毚兔，垂钓伺游鳞。
此是安口腹，非关慕隐沦。
吾生好清净，蔬食去情尘。
今子方豪荡，思为鼎食人。
我家南山下，动息自遗身。
入鸟不相乱，见兽皆相亲。
云霞成伴侣，虚白侍衣巾。
何事须夫子，邀予谷口真。','',''),('quantangshi-05844','胡居士卧病遗米因赠','王維','quantangshi','','卷6','了观四大因，根性何所有。
妄计苟不生，是身孰休咎。
色声何谓客，阴界复谁守。
徒言莲花目，岂恶杨枝肘。
既饱香积饭，不醉声闻酒。
有无断常见，生灭幻梦受。
即病即实相，趋空定狂走。
无有一法真，无有一法垢。
居士素通达，随宜善抖擞。
牀上无氊卧，镉中有粥否。
斋时不乞食，定应空漱口。
聊持数斗米，且救浮生取。','',''),('quantangshi-05845','赠裴十迪','王維','quantangshi','','卷6','风景日夕佳，与君赋新诗。
澹然望远空，如意方支颐。
春风动百草，兰蕙生我篱。
暧暧日暖闺，田家来致词。
欣欣春还臯，淡淡水生陂。
桃李虽未开，荑萼满芳枝。
请君理还策，敢告将农时。','',''),('quantangshi-05846','与胡居士皆病寄此诗兼示学人二首 一','王維','quantangshi','','卷6','一兴微尘念，横有朝露身。
如是覩阴界，何方置我人。
碍有固为主，趣空宁舍宾。
洗心讵悬解，悟道正迷津。
因爱果生病，从贪始觉贫。
色声非彼妄，浮幻即吾真。
四达竟何遣，万殊安可尘。
胡生但高枕，寂寞与谁邻。
战胜不谋食，理齐甘负薪。
予若未始异，讵论疎与亲。','',''),('quantangshi-05847','与胡居士皆病寄此诗兼示学人二首 二','王維','quantangshi','','卷6','浮空徒漫漫，泛有定悠悠。
无乘及乘者，所谓智人舟。
讵舍贫病域，不疲生死流。
无烦君喻马，任以我为牛。
植福祠迦叶，求仁笑孔丘。
何津不鼓棹，何路不摧輈。
念此闻思者，胡为多阻修。
空虚花聚散，烦恼树稀稠。
灭相成无记，生心坐有求。
降吴复归蜀，不到莫相尤。','',''),('quantangshi-05848','奉寄韦太守陟','王維','quantangshi','','卷6','荒城自萧索，万里山河空。
天高秋日逈，嘹唳闻归鸿。
寒塘映衰草，高馆落疎桐。
临此岁方[晏]，顾景咏悲翁。
故人不可见，寂寞平陵东。','',''),('quantangshi-05849','林园即事寄舍弟紞','王維','quantangshi','','卷6','寓目一萧散，销忧冀俄顷。
青草肃澄陂，白云移翠岭。
后沔通河渭，前山包鄢郢。
松含风里声，花对池中影。
地多齐后㿉，人带荆州瘿。
徒思赤笔书，讵有丹砂井。
心悲常欲绝，髪乱不能整。
青簟日何长，闲门昼方静。
颓思茅檐下，弥伤好风景。','',''),('quantangshi-05850','至滑州隔河望黎阳忆丁三宇','王維','quantangshi','','卷6','隔河见桑柘，蔼蔼黎阳川。
望望行渐远，孤峰没云烟。
故人不可见，河水复悠然。
赖有政声远，时闻行路传。','',''),('quantangshi-05851','秋夜独坐怀内弟崔兴宗','王維','quantangshi','','卷6','夜静羣动息，蟪蛄声悠悠。
庭槐北风响，日夕方高秋。
思子整羽翰，及时当云浮。
吾生将白首，岁晏思沧州。
高足在旦暮，肯为南亩俦。','',''),('quantangshi-05852','和使君五郎西楼望远思归','王維','quantangshi','','卷6','高楼望所思，目极情未毕。
枕上见千里，窗中窥万室。
悠悠长路人，暧暧远郊日。
惆怅极浦外，迢递孤烟出。
能赋属上才，思归同下秩。
故乡不可见，云水空如一。','',''),('quantangshi-05853','酬黎居士淅川作','王維','quantangshi','','卷6','侬家真个去，公定随侬否。
着处是莲花，无心变杨柳。
松龛藏药裹，石唇安茶臼。
气味当共知，那能不携手。','',''),('quantangshi-05854','送魏郡李太守赴任','王維','quantangshi','','卷6','与君伯氏别，又欲与君离。
君行无几日，当复隔山陂。
苍茫秦川尽，日落桃林塞。
独树临关门，黄河向天外。
前经洛阳陌，宛洛故人稀。
故人离别尽，淇上转骖騑。
企予悲送远，惆怅睢阳路。
古木官渡平，秋城邺宫故。
想君行县日，其出从如云。
遥思魏公子，复忆李将军。','',''),('quantangshi-05855','送陆员外','王維','quantangshi','','卷6','郎署有伊人，居然古人风。
天子顾河北，诏书除征东。
拜手辞上官，缓步出南宫。
九河平原外，七国蓟门中。
阴风悲枯桑，古塞多飞蓬。
万里不见虏，萧条胡地空。
无为费中国，更欲邀奇功。
迟迟前相送，握手嗟异同。
行当对侯归，肯访商山翁。','',''),('quantangshi-05856','送宇文太守赴宣城','王維','quantangshi','','卷6','寥落云外山，迢递舟中赏。
铙吹发西江，秋空多清响。
地迥古城芜，月明寒潮广。
时赛敬亭神，复解罟师网。
何处寄相思？南风吹五两。','',''),('quantangshi-05857','送綦毋秘书弃官还江东','王維','quantangshi','','卷6','明时久不达，弃置与君同。
天命无怨色，人生有素风。
念君拂衣去，四海将安穷。
秋天万里净，日暮澄江空。
清夜何悠悠，扣舷明月中。
和光鱼鸟际，澹尔蒹葭丛。
无庸客昭世，衰鬓日如蓬。
顽疎暗人事，僻陋远天聪。
微物纵可采，其谁为至公。
余亦从此去，归耕为老农。','',''),('quantangshi-05858','奉送六舅归陆浑','王維','quantangshi','','卷6','伯舅吏淮泗，卓鲁方喟然。
悠哉自不竞，退耕东臯田。
条桑腊月下，种杏春风前。
酌醴赋归去，共知陶令贤。','',''),('quantangshi-05859','送别','王維','quantangshi','','卷6','下马饮君酒，问君何所之。
君言不得意，归卧南山陲。
但去莫复问，白云无尽时。','',''),('quantangshi-05860','送张五归山','王維','quantangshi','','卷6','送君尽惆怅，复送何人归。
几日同携手，一朝先拂衣。
东山有茅屋，幸为埽荆扉。
当亦谢官去，岂令心事违。','',''),('quantangshi-05861','齐州送祖三','王維','quantangshi','','卷6','相逢方一笑，相送还成泣。
祖帐已伤离，荒城复愁入。
天寒远山净，日暮长河急。
解缆君已遥，望君犹伫立。','',''),('quantangshi-05862','送缙云苗太守','王維','quantangshi','','卷6','手疏谢明主，腰章为长吏。
方从会稽邸，更发汝南骑。
按节下松阳，清江响铙吹。
露冕见三吴，方知百城贵。','',''),('quantangshi-05863','送从弟蕃游淮南','王維','quantangshi','','卷6','读书复骑射，带劒游淮阴。
淮阴少年辈，千里远相寻。
高义难自隐，明时宁陆沈。
岛夷九州外，泉馆三山深。
席帆聊问罪，卉服尽成擒。
归来见天子，拜爵赐黄金。
忽思鲈鱼鲙，复有沧洲心。
天寒蒹葭渚，日落云梦林。
江城下枫叶，淮上闻秋砧。
送归青门外，车马去骎骎。
惆怅新丰树，空余天际禽。','',''),('quantangshi-05864','送高适弟耽归临淮作','王維','quantangshi','','卷6','少年客淮泗，落魄居下邳。
遨游向燕赵，结客过临淄。
山东诸侯国，迎送纷交驰。
自尔厌游侠，闭户方垂帷。
深明戴家礼，颇学毛公诗。
备知轻济道，高卧陶唐时。
圣主诏天下，贤人不得遗。
公吏奉纁组，安车去茅茨。
君王苍龙阙，九门十二逵。
羣公朝谒罢，冠劒下丹墀。
野鹤终踉跄，威凤徒参差。
或问理人术，但致还山词。
天书降北阙，赐帛归东菑。
都门谢亲故，行路日逶迟。
孤帆万里外，淼漫将何之。
江天海陵郡，云日淮南祠。
杳冥沧洲上，荡漭无人知。
纬萧或卖药，出处安能期。','',''),('quantangshi-05865','送綦毋潜落第还乡','王維','quantangshi','','卷6','圣代无隐者，英灵尽来归。
遂令东山客，不得顾采薇。
既至君门远，孰云吾道非。
江淮度寒食，京洛缝春衣。
置酒临长道，同心与我违。
行当浮桂棹，未几拂荆扉。
远树带行客，孤村当落晖。
吾谋适不用，勿谓知音稀。','',''),('quantangshi-05866','送张舍人佐江州同薛璩十韵','王維','quantangshi','','卷6','束带趋承明，守官唯谒者。
清晨听银蚪，薄暮辞金马。
受辞未尝易，当是方知寡。
清范何风流，高文有风雅。
忽佐江上州，当自浔阳下。
逆旅到三湘，长途应百舍。
香炉远峰出，石镜澄湖泻。
董奉杏成林，陶潜菊盈把。
范蠡常好之，庐山我心也。
送君思远道，欲以数行洒。','',''),('quantangshi-05867','送韦大夫东京留守','王維','quantangshi','','卷6','人外遗世虑，空端结遐心。
曾是巢许浅，始知尧舜深。
苍生讵有物，黄屋如乔林。
上德抚神运，冲和穆宸襟。
云雷康屯难，江海遂飞沈。
天工寄人英，龙衮瞻君临。
名器苟不假，保厘固其任。
素质贯方领，清景照华簪。
慷慨念王室，从容献官箴。
云旗蔽三川，画角发龙吟。
晨扬天汉声，夕卷大河阴。
穷人业已宁，逆虏遗之擒。
然后解金组，拂衣东山岑。
给事黄门省，秋光正沈沈。
壮心与身退，老病随年侵。
君子从相访，重玄其可寻。','',''),('quantangshi-05868','资圣寺送甘二','王維','quantangshi','','卷6','浮生信如寄，薄宦夫何有。
来往本无归，别离方此受。
柳色蔼春余，槐阴清夏首。
不觉御沟上，衔悲执杯酒。','',''),('quantangshi-05869','留别山中温古上人兄并示舍弟缙','王維','quantangshi','','卷6','解薜登天朝，去师偶时哲。
岂惟山中人，兼负松上月。
宿昔同游止，致身云霞末。
开轩临颍阳，卧视飞鸟没。
好依盘石饭，屡对瀑泉渴。
理齐小狎隐，道胜宁外物。
舍弟官崇高，宗兄此削髪。
荆扉但洒扫，乘闲当过歇。','',''),('quantangshi-05870','观别者','王維','quantangshi','','卷6','青青杨柳陌，陌上别离人。
爱子游燕赵，高堂有老亲。
不行无可养，行去百忧新。
切切委兄弟，依依向四邻。
都门帐饮毕，从此谢亲宾。
挥涕逐前侣，含凄动征轮。
车徒望不见，时见起行尘。
吾亦辞家久，看之泪满巾。','',''),('quantangshi-05871','别弟缙后登青龙寺望蓝田山','王維','quantangshi','','卷6','陌上新离别，苍茫四郊晦。
登高不见君，故山复云外。
远树蔽行人，长天隐秋塞。
心悲宦游子，何处飞征盖。','',''),('quantangshi-05872','别綦毋潜','王維','quantangshi','','卷6','端笏明光宫，历稔朝云陛。
诏刊延阁书，高议平津邸。
适意偶轻人，虚心削繁礼。
盛得江左风，弥工建安体。
高张多绝弦，截河有清济。
严冬爽羣木，伊洛方清泚。
渭水冰下流，潼关雪中启。
荷蓧几时还，尘缨待君洗。','',''),('quantangshi-05873','晦日游大理韦卿城南别业四声依次用各六韵 一','王維','quantangshi','','卷6','与世澹无事，自然江海人。
侧闻尘外游，解骖𨋗朱轮。
平野照暄景，上天垂春云。
张组竟北阜，泛舟过东邻。
故乡信高会，牢醴及佳辰。
幸同击壤乐，心荷尧为君。','',''),('quantangshi-05874','晦日游大理韦卿城南别业四声依次用各六韵 二','王維','quantangshi','','卷6','郊居杜陵下，永日同携手。
仁里霭川阳，平原见峰首。
园庐鸣春鸠，林薄媚新柳。
上卿始登席，故老前为寿。
临当游南陂，约略执杯酒。
归欤绌微官，惆怅心自咎。','',''),('quantangshi-05875','晦日游大理韦卿城南别业四声依次用各六韵 三','王維','quantangshi','','卷6','冬中余雪在，墟上春流驶。
风日畅怀抱，山川多秀气。
雕胡先晨炊，庖脍亦云至。
高情浪海岳，浮生寄天地。
君子外簪缨，埃尘良不啻。
所乐衡门中，陶然忘其贵。','',''),('quantangshi-05876','晦日游大理韦卿城南别业四声依次用各六韵 四','王維','quantangshi','','卷6','高馆临澄陂，旷然荡心目。
淡荡动云天，玲珑映墟曲。
鹊巢结空林，雉雊响幽谷。
应接无闲暇，徘徊以踯躅。
纡组上春堤，侧弁倚乔木。
弦望忽已晦，后期洲应绿。','',''),('quantangshi-05877','冬日游览','王維','quantangshi','','卷6','步出城东门，试骋千里目。
青山横苍林，赤日团平陆。
渭北走邯郸，关东出函谷。
秦地万方会，来朝九州牧。
鸡鸣咸阳中，冠盖相追逐。
丞相过列侯，羣公饯光禄。
相如方老病，独归茂陵宿。','',''),('quantangshi-05878','华岳','王維','quantangshi','','卷6','西岳出浮云，积雪在太清。
连天凝黛色，百里遥青冥。
白日为之寒，森沈华阴城。
昔闻干坤闭，造化生巨灵。
右足踏方止，左手推削成。
天地忽开拆，大河注东溟。
遂为西峙岳，雄雄镇秦京。
大君包覆载，至德被羣生。
上帝伫昭告，金天思奉迎。
人只望幸久，何独禅云亭。','',''),('quantangshi-05879','同卢拾遗过韦给事东山别业二十韵给事首春休沐维已陪游及乎是行亦预闻命会无车马不果斯诺','王維','quantangshi','','卷6','托身侍云陛，昧旦趋华轩。
遂陪鵷鸿侣，霄汉同飞翻。
君子垂惠顾，期我于田园。
侧闻景龙际，亲降南面尊。
万乘驻山外，顺风祈一言。
高阳多夔龙，荆山积璵璠。
盛德启前烈，大贤钟后昆。
侍郎文昌宫，给事东掖垣。
谒帝俱来下，冠盖盈丘樊。
闺风首邦族，庭训延乡村。
采地包山河，树井竟川原。
岩端回绮槛，谷口开朱门。
阶下羣峰首，云中瀑水源。
鸣玉满春山，列筵先朝暾。
会舞何飒沓，击钟弥朝昏。
是时阳和节，清昼犹未暄。
蔼蔼树色深，嘤嘤鸟声繁。
顾己负宿诺，延颈慙芳荪。
蹇步守穷巷，高驾难攀援。
素是独往客，脱冠情弥敦。','',''),('quantangshi-05880','蓝田山石门精舍','王維','quantangshi','','卷6','落日山水好，漾舟信归风。
探奇不觉远，因以缘源穷。
遥爱云木秀，初疑路不同。
安知清流转，偶与前山通。
舍舟理轻策，果然惬所适。
老僧四五人，逍遥荫松栢。
朝梵林未曙，夜禅山更寂。
道心及牧童，世事问樵客。
暝宿长林下，焚香卧瑶席。
涧芳袭人衣，山月暎石壁。
再寻畏迷误，明发更登历。
笑谢桃源人，花红复来觌。','',''),('quantangshi-05881','青溪','王維','quantangshi','','卷6','言入黄花川，每逐青溪水。
随山将万转，趣途无百里。
声喧乱石中，色静深松里。
漾漾泛菱荇，澄澄映葭苇。
我心素已闲，清川澹如此。
请留盘石上，垂钓将已矣。','',''),('quantangshi-05882','崔濮阳兄季重前山兴','王維','quantangshi','','卷6','秋色有佳兴，况君池上闲。
悠悠西林下，自识门前山。
千里横黛色，数峰出云间。
嵯峨对秦国，合沓藏荆关。
残雨斜日照，夕岚飞鸟还。
故人今尚尔，叹息此颓颜。','',''),('quantangshi-05883','李处士山居','王維','quantangshi','','卷6','君子盈天阶，小人甘自免。
方随炼金客，林上家绝巘。
背岭花未开，入云树深浅。
清昼犹自眠，山鸟时一啭。','',''),('quantangshi-05884','丁宇田家有赠','王維','quantangshi','','卷6','君心尚栖隐，久欲傍归路。
在朝每为言，解印果成趣。
晨鸡鸣邻里，羣动从所务。
农夫行饷田，闺妾起缝素。
开轩御衣服，散帙理章句。
时吟招隐诗，或制闲居赋。
新晴望郊郭，日暎桑榆暮。
阴昼小苑城，微明渭川树。
揆予宅闾井，幽赏何由屡。
道存终不忘，迹异难相遇。
此时惜离别，再来芳菲度。','',''),('quantangshi-05885','渭川田家','王維','quantangshi','','卷6','斜阳照墟落，穷巷牛羊归。
野老念牧童，倚杖候荆扉。
雉雊麦苗秀，蚕眠桑叶稀。
田夫荷锄至，相见语依依。
即此羡闲逸，怅然吟式微。','',''),('quantangshi-05886','春中田园作','王維','quantangshi','','卷6','屋上春鸠鸣，村边杏花白。
持斧伐远扬，荷锄觇泉脉。
归燕识故巢，旧人看新历。
临觞忽不御，惆怅远行客。','',''),('quantangshi-05887','过李楫宅','王維','quantangshi','','卷6','闲门秋草色，终日无车马。
客来深巷中，犬吠寒林下。
散髪时未簪，道书行尚把。
与我同心人，乐道安贫者。
一罢宜城酌，还归洛阳社。','',''),('quantangshi-05888','韦侍郎山居','王維','quantangshi','','卷6','幸忝君子顾，遂陪尘外踪。
闲花满岩谷，瀑水映杉松。
啼鸟忽临涧，归云时抱峰。
良游盛簪绂，继迹多夔龙。
讵枉青门道，胡闻长乐钟。
清晨去朝谒，车马何从容。','',''),('quantangshi-05889','饭覆釜山僧','王維','quantangshi','','卷6','晚知清净理，日与人羣疎。
将候远山僧，先期埽弊庐。
果从云峰里，顾我蓬蒿居。
藉草饭松屑，焚香看道书。
然灯昼欲尽，鸣磬夜方初。
一悟寂为乐，此日闲有余。
思归何必深，身世犹空虚。','',''),('quantangshi-05890','谒璇上人','王維','quantangshi','','卷6','少年不足言，识道年已长。
事往安可悔，余生幸能养。
誓从断臂血，不复婴世网。
浮名寄缨佩，空性无羁鞅。
夙承大导师，焚香此瞻仰。
颓然居一室，覆载纷万象。
高柳早鸎啼，长廊春雨响。
牀下阮家屐，窗前筇竹杖。
方将见身云，陋彼示天壤。
一心在法要，愿以无生奖。','',''),('quantangshi-05891','瓜园诗','王維','quantangshi','','卷6','余适欲锄瓜，倚锄听叩门。
鸣驺导骢马，常从夹朱轩。
穷巷正传呼，故人傥相存。
携手追凉风，放心望干坤。
蔼蔼帝王州，宫观一何繁。
林端出绮道，殿顶摇华幡。
素怀在青山，若值白云屯。
回风城西雨，返景原上村。
前酌盈尊酒，往往闻清言。
黄鹂啭深木，朱槿照中园。
犹羡松下客，石上闻清猿。','',''),('quantangshi-05892','自大散以往深林密竹磴道盘曲四五十里至黄牛岭见黄花川','王維','quantangshi','','卷6','危径几万转，数里将三休。
回环见徒侣，隐暎隔林丘。
飒飒松上雨，潺潺石中流。
静言深溪里，长啸高山头。
望见南山阳，白露霭悠悠。
青臯丽已净，绿树郁如浮。
曾是厌蒙密，旷然销人忧。','',''),('quantangshi-05893','新晴野望','王維','quantangshi','','卷6','新晴原野旷，极目无氛垢。
郭门临渡头，村树连溪口。
白水明田外，碧峰出山后。
农月无闲人，倾家事南亩。','',''),('quantangshi-05894','宿郑州','王維','quantangshi','','卷6','朝与周人辞，暮投郑人宿。
他乡绝俦侣，孤客亲僮仆。
宛洛望不见，秋霖晦平陆。
田父草际归，村童雨中牧。
主人东臯上，时稼遶茅屋。
虫思机杼悲，雀喧禾黍熟。
明当渡京水，昨晚犹金谷。
此去欲何言，穷边狥微禄。','',''),('quantangshi-05895','早入荥阳界','王維','quantangshi','','卷6','泛舟入荥泽，兹邑乃雄藩。
河曲闾阎隘，川中烟火繁。
因人见风俗，入境闻方言。
秋野田畴盛，朝光市井喧。
渔商波上客，鸡犬岸旁村。
前路白云外，孤帆安可论。','',''),('quantangshi-05896','渡河到清河作','王維','quantangshi','','卷6','泛舟大河里，积水穷天涯。
天波忽开拆，郡邑千万家。
行复见城市，宛然有桑麻。
回瞻旧乡国，淼漫连云霞。','',''),('quantangshi-05897','苦热','王維','quantangshi','','卷6','赤日满天地，火云成山岳。
草木尽焦卷，川泽皆竭涸。
轻纨觉衣重，密树苦阴薄。
莞簟不可近，絺綌再三濯。
思出宇宙外，旷然在寥廓。
长风万里来，江海荡烦浊。
却顾身为患，始知心未觉。
忽入甘露门，宛然清凉乐。','',''),('quantangshi-05898','纳凉','王維','quantangshi','','卷6','乔木万余株，清流贯其中。
前临大川口，豁达来长风。
涟漪涵白沙，素鲔如游空。
偃卧盘石上，翻涛沃微躬。
漱流复濯足，前对钓鱼翁。
贪饵凡几许，徒思莲叶东。','',''),('quantangshi-05899','西施咏','王維','quantangshi','','卷6','艳色天下重，西施宁久微。
朝仍越溪女，暮作吴宫妃。
贱日岂殊众，贵来方悟稀。
邀人傅香粉，不自着罗衣。
君宠益娇态，君怜无是非。
当时浣纱伴，莫得同车归。
持谢邻家子，效颦安可希。','',''),('quantangshi-05900','李陵咏','王維','quantangshi','','卷6','汉家李将军，三代将门子。
结发有奇策，少年成壮士。
长驱塞上儿，深入单于垒。
旌旗列相向，箫鼓悲何已。
日暮沙漠陲，战声烟尘里。
将令骄虏灭，岂独名王侍。
既失大军援，遂婴穹庐耻。
少小蒙汉恩，何堪坐思此。
深衷欲有报，投躯未能死。
引领望子卿，非君谁相理。','',''),('quantangshi-05901','济上四贤咏 崔录事','王維','quantangshi','','卷6','解印归田里，贤哉此丈夫。
少年曾任侠，晚节更为儒。
遯迹东山下，因家沧海隅。
已闻能狎鸟，余欲共乘桴。','',''),('quantangshi-05902','济上四贤咏 成文学','王維','quantangshi','','卷6','宝劒千金装，登君白玉堂。
身为平原客，家有邯郸娼。
使气公卿坐，论心游侠场。
中年不得意，谢病客游梁。','',''),('quantangshi-05903','济上四贤咏 郑霍二山人','王維','quantangshi','','卷6','翩翩繁华子，多出金张门。
幸有先人业，早蒙明主恩。
童年且未学，肉食骛华轩。
岂乏中林士，无人荐至尊。
郑公老泉石，霍子安丘樊。
卖药不二价，着书盈万言。
息阴无恶木，饮水必清源。
吾贱不及议，斯人竟谁论。','',''),('quantangshi-05904','过太乙观贾生房','王維','quantangshi','','卷6','昔余栖遯日，之子烟霞邻。
共携松叶酒，俱篸竹皮巾。
攀林遍岩洞，采药无冬春。
谬以道门子，征为骖御臣。
常恐丹液就，先我紫阳宾。
夭促万涂尽，哀伤百虑新。
迹峻不容俗，才多反累真。
泣对双泉水，还山无主人。','',''),('quantangshi-05905','燕子龛禅师','王維','quantangshi','','卷6','山中燕子龛，路剧羊肠恶。
裂地竞盘屈，插天多峭崿。
瀑泉吼而喷，怪石看欲落。
伯禹访未知，五丁愁不凿。
上人无生缘，生长居紫阁。
六时自捶磬，一饮常带索。
种田烧白云，斫漆响丹壑。
行随拾栗猿，归对巢松鹤。
时许山神请，偶逢洞仙博。
救世多慈悲，即心无行作。
周商倦积阻，蜀物多淹泊。
岩腹乍旁穿，涧唇时外拓。
桥因倒树架，栅值垂藤缚。
鸟道悉已平，龙宫为之涸。
跳波谁揭厉，绝壁免扪摸。
山木日阴阴，结跏归旧林。
一向石门里，任君春草深。','',''),('quantangshi-05906','羽林骑闺人','王維','quantangshi','','卷6','秋月临高城，城中管弦思。
离人堂上愁，稚子阶前戏。
出门复暎户，望望青丝骑。
行人过欲尽，狂夫终不至。
左右寂无言，相看共垂泪。','',''),('quantangshi-05907','偶然作六首 一','王維','quantangshi','','卷6','楚国有狂夫，茫然无心想。
散髪不冠带，行歌南陌上。
孔丘与之言，仁义莫能奖。
未尝肯问天，何事须击壤。
复笑采薇人，胡为乃长往。','',''),('quantangshi-05908','偶然作六首 二','王維','quantangshi','','卷6','田舍有老翁，垂白衡门里。
有时农事闲，斗酒呼邻里。
喧聒茅檐下，或坐或复起。
短褐不为薄，园葵固足美。
动则长子孙，不曾向城市。
五帝与三王，古来称天子。
干戈将揖让，毕竟何者是。
得意苟为乐，野田安足鄙。
且当放怀去，行行没余齿。','',''),('quantangshi-05909','偶然作六首 三','王維','quantangshi','','卷6','日夕见太行，沈吟未能去。
问君何以然，世网婴我故。
小妹日成长，兄弟未有娶。
家贫禄既薄，储蓄非有素。
几回欲奋飞，踟蹰复相顾。
孙登长啸台，松竹有遗处。
相去讵几许，故人在中路。
爱染日已薄，禅寂日已固。
忽乎吾将行，宁俟岁云暮。','',''),('quantangshi-05910','偶然作六首 四','王維','quantangshi','','卷6','陶潜任天真，其性颇躭酒。
自从弃官来，家贫不能有。
九月九日时，菊花空满手。
中心窃自思，傥有人送否。
白衣携壶觞，果来遗老叟。
且喜得斟酌，安问升与斗。
奋衣野田中，今日嗟无负。
兀傲迷东西，蓑笠不能守。
倾倒强行行，酣歌归五柳。
生事不曾问，肯愧家中妇。','',''),('quantangshi-05911','偶然作六首 五','王維','quantangshi','','卷6','赵女弹箜篌，复能邯郸舞。
夫壻轻薄儿，鬬鸡事齐主。
黄金买歌笑，用钱不复数。
许史相经过，高门盈四牡。
客舍有儒生，昂藏出邹鲁。
读书三十年，腰间无尺组。
被服圣人教，一生自穷苦。','',''),('quantangshi-05912','偶然作六首 六','王維','quantangshi','','卷6','老来懒赋诗，惟有老相随。
宿世谬词客，前身应画师。
不能舍余习，偶被世人知。
名字本皆是，此心还不知。','',''),('quantangshi-05913','寓言二首 一','王維','quantangshi','','卷6','朱绂谁家子，无乃金张孙。
骊驹从白马，出入铜龙门。
问尔何功德，多承明主恩。
鬬鸡平乐馆，射雉上林园。
曲陌车骑盛，高堂珠翠繁。
奈何轩冕贵，不与布衣言。','',''),('quantangshi-05914','寓言二首 二','王維','quantangshi','','卷6','君家御沟上，垂柳夹朱门。
列鼎会中贵，鸣珂朝至尊。
生死在八议，穷达由一言。
须识苦寒士，莫矜狐白温。','',''),('quantangshi-05915','冬夜书怀','王維','quantangshi','','卷6','冬宵寒且永，夜漏宫中发。
草白霭繁霜，木衰澄清月。
丽服暎颓颜，朱灯照华髪。
汉家方尚少，顾影慙朝谒。','',''),('quantangshi-05916','送康太守','王維','quantangshi','','卷6','城下沧江水，江边黄鹤楼。
朱阑将粉堞，江水映悠悠。
铙吹发夏口，使君居上头。
郭门隐枫岸，候吏趋芦洲。
何异临川郡，还劳康乐侯。','',''),('quantangshi-05917','送权二','王維','quantangshi','','卷6','高人不可有，清论复何深。
一见如旧识，一言知道心。
明时当薄宦，解薜去中林。
芳草空隐处，白云余故岑。
韩侯久携手，河岳共幽寻。
怅别千余里，临堂鸣素琴。','',''),('quantangshi-05918','休假还旧业便使','王維','quantangshi','','卷6','谢病始告归，依依入桑梓。
家人皆竚立，相候衡门里。
时辈皆长年，成人旧童子。
上堂嘉庆毕，顾与姻亲齿。
论旧忽余悲，目存皆相喜。
田园转芜没，但有寒泉水。
衰柳日萧条，秋光清邑里。
入门乍如客，休骑非便止。
中饮顾王程，离忧从此始。','',''),('quantangshi-05919','叹白髪','王維','quantangshi','','卷6','我年一何长，鬓髪日已白。
俛仰天地间，能为几时客。
惆怅故山云，俳徊空日夕。
何事与时人，东城复南陌。','',''),('quantangshi-05920','别弟妹二首 一','王維','quantangshi','','卷6','两妹日成长，双鬟将及人。
已能持宝瑟，自解掩罗巾。
念昔别时小，未知疎与亲。
今来始离恨，拭泪方殷勤。','',''),('quantangshi-05921','别弟妹二首 二','王維','quantangshi','','卷6','小弟更孩幼，归来不相识。
同居虽渐惯，见人犹未觅。
宛作越人语，殊甘水乡食。
别此最为难，泪尽有余忆。','',''),('quantangshi-05922','哭殷遥','王維','quantangshi','','卷6','人生能几何，毕竟归无形。
念君等为死，万事伤人情。
慈母未及葬，一女才十龄。
泱漭寒郊外，萧条闻哭声。
浮云为苍茫，飞鸟不能鸣。
行人何寂寞，白日自凄清。
忆昔君在时，问我学无生。
劝君苦不早，令君无所成。
故人各有赠，又不及生平。
负尔非一途，恸哭返柴荆。','',''),('quantangshi-05923','故南阳夫人樊氏挽歌','王維','quantangshi','','卷6','石窌恩荣重，金吾车骑盛。
将朝每赠言，入室还相敬。
叠鼓秋城动，悬旌寒日映。
不言长不归，环佩犹将听。','',''),('quantangshi-05924','夷门歌','王維','quantangshi','','卷6','七雄雄雌犹未分，攻城杀将何纷纷。
秦兵益围邯郸急，魏王不救平原君。
公子为嬴停驷马，执辔愈恭意愈下。
亥为屠肆鼓刀人，嬴乃夷门抱关者。
非但慷慨献良谋，意气兼将身命酬。
向风刎颈送公子，七十老翁何所求。','',''),('quantangshi-05925','陇头吟','王維','quantangshi','','卷6','长安少年游侠客，夜上戍楼看太白。
陇头明月迥临关，陇上行人夜吹笛。
关西老将不胜愁，驻马听之双泪流。
身经大小百余战，麾下偏裨万户侯。
苏武才为典属国，节旄落尽海西头。','',''),('quantangshi-05926','老将行','王維','quantangshi','','卷6','少年十五二十时，步行夺得胡马射。
射杀中山白额虎，肯数邺下黄须儿。
一身转战三千里，一劒曾当百万师。
汉兵奋迅如霹雳，虏骑崩腾畏蒺藜。
衞青不败由天幸，李广无功缘数奇。
自从弃置便衰朽，世事磋跎成白首。
昔时飞箭无全目，今日垂杨生左肘。
路傍时卖故侯瓜，门前学种先生柳。
苍茫古木连穷巷，寥落寒山对虚牖。
誓令疏勒出飞泉，不似颍川空使酒。
贺兰山下阵如云，羽檄交驰日夕闻。
节使三河募年少，诏书五道出将军。
试拂铁衣如雪色，聊持宝劒动星文。
愿得燕弓射天将，耻令越甲鸣吴军。
莫嫌旧日云中守，犹堪一战取功勋。','',''),('quantangshi-05927','燕支行','王維','quantangshi','','卷6','汉家天将才且雄，来时谒帝明光宫。
万乘亲推双阙下，千官出饯五陵东。
誓辞甲第金门里，身作长城玉塞中。
衞霍才堪一骑将，朝廷不数贰师功。
赵魏燕韩多劲卒，关西侠少何咆勃。
报讐只是闻尝胆，饮酒不曾妨刮骨。
画戟雕戈白日寒，连旗大斾黄尘没。
叠鼓遥翻瀚海波，鸣笳乱动天山月。
麒麟锦带佩吴钩，飒沓青骊跃紫骝。
拔劒已断天骄臂，归鞍共饮月支头。
汉兵大呼一当百，虏骑相看哭且愁。
教战虽令赴汤火，终知上将先伐谋。','',''),('quantangshi-05928','桃源行','王維','quantangshi','','卷6','渔舟逐水爱山春，两岸桃花夹去津。
坐看红树不知远，行尽青溪不见人。
山口潜行始隈隩，山开旷望旋平陆。
遥看一处攒云树，近入千家散花竹。
樵客初传汉姓名，居人未改秦衣服。
居人共住武陵源，还从物外起田园。
月明松下房栊静，日出云中鸡犬喧。
惊闻俗客争来集，竞引还家问都邑。
平明闾巷埽花开，薄暮渔樵乘水入。
初因避地去人间，及至成仙遂不还。
峡里谁知有人事，世中遥望空云山。
不疑灵境难闻见，尘心未尽思乡县。
出洞无论隔山水，辞家终拟长游衍。
自谓经过旧不迷，安知峰壑今来变。
当时只记入山深，青溪几曲到云林。
春来遍是桃花水，不辨仙源何处寻。','',''),('quantangshi-05929','洛阳女儿行','王維','quantangshi','','卷6','洛阳女儿对门居，才可容颜十五余。
良人玉勒乘骢马，侍女金盘鲙鲤鱼。
画阁朱楼尽相望，红桃绿柳垂檐向。
罗帏送上七香车，宝扇迎归九华帐。
狂夫富贵在青春，意气骄奢剧季伦。
自怜碧玉亲教舞，不惜珊瑚持与人。
春窗曙灭九微火，九微片片飞花璅。
戏罢曾无理曲时，妆成秪是薰香坐。
城中相识尽繁华，日夜经过赵李家。
谁怜越女颜如玉，贫贱江头自浣纱。','',''),('quantangshi-05930','同崔傅答贤弟','王維','quantangshi','','卷6','洛阳才子姑苏客，桂苑殊非故乡陌。
九江枫树几回青，一片扬州五湖白。
扬州时有下江兵，兰陵镇前吹笛声。
夜火人归富春郭，秋风鹤唳石头城。
周郎陆弟为俦侣，对舞前溪歌白紵。
曲几书留小史家，草堂棋赌山阴墅。
衣冠若话外台臣，先数夫君席上珍。
更闻台阁求三语，遥想风流第一人。','',''),('quantangshi-05931','赠吴官','王維','quantangshi','','卷6','长安客舍热如煮，无个茗糜难御暑。
空摇白团其谛苦，欲向缥囊还归旅。
江乡鲭鲊不寄来，秦人汤饼那堪许。
不如侬家任挑达，草屩捞虾富春渚。','',''),('quantangshi-05932','故人张諲工诗善易卜兼能丹青草隶顷以诗见赠聊获酬之','王維','quantangshi','','卷6','不逐城东游侠儿，隐囊纱帽坐弹棋。
蜀中夫子时开卦，洛下书生解咏诗。
药阑花迳衡门里，时复据梧聊隐几。
屏风误点惑孙郎，团扇草书轻内史。
故园高枕度三春，永日垂帷绝四邻。
自想蔡邕今已老，更将书籍使何人。','',''),('quantangshi-05933','送崔五太守','王維','quantangshi','','卷6','长安厩吏来到门，朱文露网动行轩。
黄花县西九折坂，玉树宫南五丈原。
襃斜谷中不容幰，唯有白云当露冕。
子午山里杜鹃啼，嘉陵水头行客饭。
劒门忽断蜀川开，万井双流满眼来。
雾中远树刀州出，天际澄江巴字回。
使君年纪三十余，少年白皙专城居。
欲持画省郎官笔，回与临邛父老书。','',''),('quantangshi-05934','寒食城东即事','王維','quantangshi','','卷6','清溪一道穿桃李，演漾绿蒲涵白芷。
溪上人家凡几家，落花半落东流水。
蹴鞠屡过飞鸟上，秋千竞出垂杨里。
少年分日作遨游，不用清明兼上巳。','',''),('quantangshi-05935','不遇咏','王維','quantangshi','','卷6','北阙献书寝不报，南山种田时不登。
百人会中身不预，五侯门前心不能。
身投河朔饮君酒，家在茂陵平安否。
且此登山复临水，莫问春风动杨柳。
今人昨人多自私，我心不说君应知。
济人然后拂衣去，肯作徒尔一男儿。','',''),('quantangshi-05936','赠裴迪','王維','quantangshi','','卷6','不相见，不相见来久。
日日泉水头，常忆同携手。
携手本同心，复叹忽分襟。
相忆今如此，相思深不深。','',''),('quantangshi-05937','青雀歌','王維','quantangshi','','卷6','青雀翅羽短，未能远食玉山禾。
犹胜黄雀争上下，唧唧空仓复若何。','',''),('quantangshi-05938','黄雀痴','王維','quantangshi','','卷6','黄雀痴，黄雀痴，谓言青鷇是我儿。
一一口衔食，养得成毛衣。
到大啁啾解游扬，各自东西南北飞。
薄暮空巢上，羇雌独自归。
凤凰九雏亦如此，慎莫愁思顦顇损容辉。','',''),('quantangshi-05939','新秦郡松树歌','王維','quantangshi','','卷6','青青山上松，数里不见今更逢。
不见君，心相忆，此心向君君应识。
为君颜色高且闲，亭亭迥出浮云间。','',''),('quantangshi-05940','楡林郡歌','王維','quantangshi','','卷6','山头松柏林，山下泉声伤客心。
千里万里春草色，黄河东流流不息。
黄龙戍上游侠儿，愁逢汉使不相识。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-05941','问寇校书双溪','王維','quantangshi','','卷6','君家少室西，为复少室东。
别来几日今春风，新买双溪定何似。','',''),('quantangshi-05942','寄崇梵僧','王維','quantangshi','','卷6','崇梵僧，崇梵僧，秋归覆釜春不还。
落花啼鸟纷纷乱，涧户山窗寂寂闲。
峡里谁知有人事，郡中遥望空云山。','',''),('quantangshi-05943','同比部杨员外十五夜游有怀静者季','王維','quantangshi','','卷6','承明少休沐，建礼省文书。
夜漏行人息，归鞍落日余。
悬知三五夕，万户千门辟。
夜出曙翻归，倾城满南陌。
陌头驰骋尽繁华，王孙公子五侯家。
由来月明如白日，共道春灯胜百花。
聊看侍中千宝骑，强识小妇七香车。
香车宝马共喧阗，个里多情侠少年。
竞向长杨柳市北，肯过精舍竹林前。
独有仙郎心寂寞，却将宴坐为行乐。
傥觉忘怀共往来，幸霑同舍甘藜藿。','',''),('quantangshi-05944','答张五弟','王維','quantangshi','','卷6','终南有茅屋，前对终南山。
终年无客常闭关，终日无心长自闲。
不妨饮酒复垂钓，君但能来相往还。','',''),('quantangshi-05945','雪中忆李楫','王維','quantangshi','','卷6','积雪满阡陌，故人不可期。
长安千门复万户，何处躞蹀黄金羁。','',''),('quantangshi-05946','送李睢阳','王維','quantangshi','','卷6','将置酒，思悲翁。
使君去，出城东。
麦渐渐，雉子斑。
槐阴阴，到潼关。
骑连连，车迟迟。
心中悲，宋又远。
周间之，南淮夷。
东齐儿，碎碎织练与素丝。
游人贾客信难持，五谷前熟方可为。
下车闭合君当思，天子当殿俨衣裳。
大官尚食陈羽觞，彤庭散绶垂鸣璫。
黄纸诏书出东厢，轻纨叠绮烂生光。
宗室子弟君最贤，分忧当为百辟先。
布衣一言相为死，何况圣主恩如天。
鸾声哕哕鲁侯旗，明年上计朝京师。
须忆今日斗酒别，慎勿富贵忘我为。','',''),('quantangshi-05947','奉和圣制天长节赐宰臣歌应制','王維','quantangshi','','卷6','太阳升兮照万方，开阊阖兮临玉堂。
俨冕旒兮垂衣裳，金天净兮丽三光。
彤庭曙兮延八荒，德合天兮礼神徧。
灵芝生兮庆云见，唐尧后兮稷卨臣。
匝宇宙兮华胥人，尽九服兮皆四邻，干降瑞兮坤降珍。','',''),('quantangshi-05948','登楼歌','王維','quantangshi','','卷6','聊上君兮高楼，飞甍鳞次兮在下。
俯十二兮通衢，绿槐参差兮车马。
却瞻兮龙首，前眺兮宜春。
王畿郁兮千里，山河壮兮咸秦。
舍人下兮青宫，据胡牀兮书空。
执戟疲于下位，老夫好隐兮墙东。
亦幸有张伯英草圣兮龙腾蚪跃，摆长云兮捩回风。
琥珀酒兮雕胡饭，君不御兮日将晚。
秋风兮吹衣，夕鸟兮争返。
孤砧发兮东城，林薄暮兮蝉声远。
时不可兮再得，君何为兮偃蹇。','',''),('quantangshi-05949','双黄鹄歌送别','王維','quantangshi','','卷6','天路来兮双黄鹄，云上飞兮水上宿。
抚翼和鸣整羽族，不得已，忽分飞。
家在玉京朝紫微，主人临水送将归。
悲笳嘹唳垂舞衣，宾欲散兮复相依。
几往返兮极浦，尚裴回兮落晖。
岸上火兮相迎，将夜入兮边城。
鞍马归兮佳人散，怅离忧兮独含情。','',''),('quantangshi-05950','赠徐中书望终南山歌','王維','quantangshi','','卷6','晚下兮紫微，怅尘事兮多违。
驻马兮双树，望青山兮不归。','',''),('quantangshi-05951','送友人归山歌二首 一','王維','quantangshi','','卷6','山寂寂兮无人，又苍苍兮多木。
羣龙兮满朝，君何为兮空谷。
文寡和兮思深，道难知兮行独。
悦石上兮流泉，与松间兮草屋。
入云中兮养鸡，上山头兮抱犊。
神与枣兮如瓜，虎卖杏兮收谷。
愧不才兮妨贤，嫌既老兮贪禄。
誓解印兮相从，何詹尹兮何卜。','',''),('quantangshi-05952','送友人归山歌二首 二','王維','quantangshi','','卷6','山中人兮欲归，云冥冥兮雨霏霏，水惊波兮翠菅靡。
白鹭忽兮翻飞，君不可兮褰衣。
山万重兮一云，混天地兮不分。
树暗暧兮氛氲，猿不见兮空闻。
忽山西兮夕阳，见东臯兮远村。
平芜绿兮千里，眇惆怅兮思君。','',''),('quantangshi-05953','鱼山神女祠歌 迎神','王維','quantangshi','','卷6','坎坎击鼓，鱼山之下。
吹洞箫，望极浦，女巫进，纷屡舞。
陈瑶席，湛清酤，风凄凄兮夜雨。
不知神之来兮不来，使我心兮苦复苦。','',''),('quantangshi-05954','鱼山神女祠歌 送神','王維','quantangshi','','卷6','纷进舞兮堂前，目眷眷兮琼筵。
来不言兮意不传，作暮雨兮愁空山。
悲急管兮思繁弦，神之驾兮俨欲旋。
倏云收兮雨歇，山青青兮水潺湲。','',''),('quantangshi-05955','白鼋涡','王維','quantangshi','','卷6','南山之瀑水兮，激石瀥瀑似雷惊。
人相对兮，不闻语声。
翻涡跳沫兮苍苔湿，藓老且厚，春草为之不生。
兽不敢惊动，鸟不敢飞鸣。
白鼋涡涛戏濑兮，委身以纵横。
王人之仁兮，不网不钓，得遂性以生成。','',''),('quantangshi-05956','宋进马哀词','王維','quantangshi','','卷6','背春涉夏兮，众木蔼以繁阴。
连金华与玉堂兮，宫阁郁其沈沈。
百官并入兮，何语笑之哑哑。
君独静嘿以伤心，草王言兮不得辞。
我悲减思兮少时，仆夫命驾兮。
出阊阖，历通逵，陌上人兮如故。
识不识兮往来，眼中不见兮吾儿。
骖紫骝兮从青骊，低光垂彩兮。
怳不知其所之，辟朱户兮望华轩。
意斯子兮候门，忽思瘗兮城南。
心瞀乱兮重昏，仰诉天之不仁兮。
家唯一身，身止一子。
何胤嗣之不繁，就单尠而又死。
将清白兮遗谁，问诗礼兮已矣。
哀从中兮不可胜，岂暇料余年兮复几。
日黯黯兮颓晔，鸟翩翩兮疾飞。
邈穷天兮不返，疑有日兮来归。
静言思兮永绝，复惊叫兮沾衣。
客有吊之者曰：观未始兮有物，同委蜕兮胡悲。
且延陵兮未至，况西河兮不知。
学无生兮庶可，幸能听于吾师。','',''),('quantangshi-05957','奉和圣制赐史供奉曲江宴应制','王維','quantangshi','','卷6','侍从有邹枚，琼筵就水开。
言陪柏梁宴，新下建章来。
对酒山河满，移舟草树廻。
天文同丽日，驻景惜行杯。','',''),('quantangshi-05958','从岐王过杨氏别业应教','王維','quantangshi','','卷6','杨子谈经所，淮王载酒过。
兴阑啼鸟换，坐久落花多。
迳转廻银烛，林开散玉珂。
严城时未启，前路拥笙歌。','',''),('quantangshi-05959','从岐王夜宴衞家山池应教','王維','quantangshi','','卷6','座客香貂满，宫娃绮幔张。
涧花轻粉色，山月少灯光。
积翠纱窗暗，飞泉绣户凉。
还将歌舞出，归路莫愁长。','',''),('quantangshi-05960','早朝','王維','quantangshi','','卷6','柳暗百花明，春深五凤城。
城乌睥睨晓，宫井辘轳声。
方朔金门侍，班姬玉辇迎。
仍闻遣方士，东海访蓬瀛。','',''),('quantangshi-05961','同崔员外秋宵寓直','王維','quantangshi','','卷6','建礼高秋夜，承明候晓过。
九门寒漏彻，万井曙钟多。
月迥藏珠斗，云消出绛河。
更慙衰朽质，南陌共鸣珂。','',''),('quantangshi-05962','辋川闲居赠裴秀才迪','王維','quantangshi','','卷6','寒山转苍翠，秋水日潺湲。
倚杖柴门外，临风听暮蝉。
渡头余落日，墟里上孤烟。
复值接舆醉，狂歌五柳前。','',''),('quantangshi-05963','寄荆州张丞相','王維','quantangshi','','卷6','所思竟何在，怅望深荆门。
举世无相识，终身思旧恩。
方将与农圃，艺植老丘园。
目尽南飞雁，何由寄一言。','',''),('quantangshi-05964','冬晚对雪忆胡居士家','王維','quantangshi','','卷6','寒更传晓箭，清镜览衰颜。
隔牖风惊竹，开门雪满山。
洒空深巷静，积素广庭闲。
借问袁安舍，翛然尚闭关。','',''),('quantangshi-05965','和尹谏议史馆山池','王維','quantangshi','','卷6','云馆接天居，霓裳侍玉除。
春池百子外，芳树万年余。
洞有仙人箓，山藏太史书。
君恩深汉帝，且莫上空虚。','',''),('quantangshi-05966','奉和杨驸马六郎秋夜即事','王維','quantangshi','','卷6','高楼月似霜，秋夜郁金堂。
对坐弹卢女，同看舞凤凰。
少儿多送酒，小玉更焚香。
结束平阳骑，明朝入建章。','',''),('quantangshi-05967','酬虞部苏员外过蓝田别业不见留之作','王維','quantangshi','','卷6','贫居依谷口，乔木带荒村。
石路枉廻驾，山家谁候门。
渔舟胶冻浦，猎火烧寒原。
唯有白云外，疎钟闻夜猿。','',''),('quantangshi-05968','酬比部杨员外暮宿琴台朝跻书阁率尔见赠之作','王維','quantangshi','','卷6','旧简拂尘看，鸣琴候月弹。
桃源迷汉姓，松树有秦官。
空谷归人少，青山背日寒。
羡君栖隐处，遥望白云端。','',''),('quantangshi-05969','酬严少尹徐舍人见过不遇','王維','quantangshi','','卷6','公门暇日少，穷巷故人稀。
偶值乘篮轝，非关避白衣。
不知炊黍谷，谁解埽荆扉。
君但倾茶椀，无妨骑马归。','',''),('quantangshi-05970','酬张少府','王維','quantangshi','','卷6','晚年唯好静，万事不关心。
自顾无长策，空知返旧林。
松风吹解带，山月照弹琴。
君问穷通理，渔歌入浦深。','',''),('quantangshi-05971','酬贺四赠葛巾之作','王維','quantangshi','','卷6','野巾传惠好，兹贶重兼金。
嘉此幽栖物，能齐隐吏心。
早朝方暂挂，晚沐复来簪。
坐觉嚣尘远，思君共入林。','',''),('quantangshi-05972','送丘为落第归江东','王維','quantangshi','','卷6','怜君不得意，况复柳条春。
为客黄金尽，还家白发新。
五湖三亩宅，万里一归人。
知尔不能荐，羞称献纳臣。','',''),('quantangshi-05973','送李判官赴东江','王維','quantangshi','','卷6','闻道皇华使，方随皂盖臣。
封章通左语，冠冕化文身。
树色分扬子，潮声满富春。
遥知辨璧吏，恩到泣珠人。','',''),('quantangshi-05974','送封太守','王維','quantangshi','','卷6','忽解羊头削，聊驰熊首轓。
扬舲发夏口，按节向吴门。
帆暎丹阳郭，枫攒赤岸村。
百村多候吏，露冕一何尊。','',''),('quantangshi-05975','送严秀才还蜀','王維','quantangshi','','卷6','宁亲为令子，似舅即贤甥。
别路经花县，还乡入锦城。
山临青塞断，江向白云平。
献赋何时至，明君忆长卿。','',''),('quantangshi-05976','送张判官赴河西','王維','quantangshi','','卷6','单车曾出塞，报国敢邀勋。
见逐张征虏，今思霍冠军。
沙平连白雪，蓬卷入黄云。
慷慨倚长劒，高歌一送君。','',''),('quantangshi-05977','送岐州源长史归','王維','quantangshi','','卷6','握手一相送，心悲安可论。
秋风正萧索，客散孟尝门。
故驿通槐里，长亭下槿原。
征西旧旌节，从此向河源。','',''),('quantangshi-05978','送张道士归山','王維','quantangshi','','卷6','先生何处去，王屋访茅君。
别妇留丹诀，驱鸡入白云。
人间若剩住，天上复离羣。
当作辽城鹤，仙歌使尔闻。','',''),('quantangshi-05979','同崔兴宗送衡岳瑗公南归','王維','quantangshi','','卷6','言从石菌阁，新下穆陵关。
独向池阳去，白云留故山。
绽衣秋日里，洗钵古松间。
一施传心法，唯将戒定还。','',''),('quantangshi-05980','送钱少府还蓝田','王維','quantangshi','','卷6','草色日向好，桃源人去稀。
手持平子赋，目送老莱衣。
每候山樱发，时同海燕归。
今年寒食酒，应是返柴扉。','',''),('quantangshi-05981','送丘为往唐州','王維','quantangshi','','卷6','宛洛有风尘，君行多苦辛。
四愁连汉水，百口寄随人。
槐色阴清昼，杨花惹暮春。
朝端肯相送，天子绣衣臣。','',''),('quantangshi-05982','送元中丞转运江淮','王維','quantangshi','','卷6','薄赋归天府，轻徭赖使臣。
欢霑赐帛老，恩及卷绡人。
去问珠官俗，来经石𧉧春。
东南御亭上，莫使有风尘。','',''),('quantangshi-05983','送崔九兴宗游蜀','王維','quantangshi','','卷6','送君从此去，转觉故人稀。
徒御犹廻首，田园方掩扉。
出门当旅食，中路授寒衣。
江汉风流地，游人何岁归。','',''),('quantangshi-05984','送崔兴宗','王維','quantangshi','','卷6','已恨亲皆远，谁怜友复稀。
君王未西顾，游宦尽东归。
塞迥山河净，天长云树微。
方同菊花节，相待洛阳扉。','',''),('quantangshi-05985','送平澹然判官','王維','quantangshi','','卷6','不识阳关路，新从定远侯。
黄云断春色，画角起边愁。
瀚海经年到，交河出塞流。
须令外国使，知饮月氏头。','',''),('quantangshi-05986','送刘司直赴安西','王維','quantangshi','','卷6','绝域阳关道，胡沙与塞尘。
三春时有雁，万里少行人。
苜蓿随天马，葡萄逐汉臣。
当令外国惧，不敢觅和亲。','',''),('quantangshi-05987','送赵都督赴代州得青字','王維','quantangshi','','卷6','天官动将星，汉上柳条青。
万里鸣刁斗，三军出井陉。
忘身辞凤阙，报国取龙庭。
岂学书生辈，窗间老一经。','',''),('quantangshi-05988','送方城韦明府','王維','quantangshi','','卷6','遥思葭菼际，寥落楚人行。
高鸟长淮水，平芜故郢城。
使车听雉乳，县鼓应鸡鸣。
若见州从事，无嫌手板迎。','',''),('quantangshi-05989','送李员外贤郎','王維','quantangshi','','卷6','少年何处去，负米上铜梁。
借问阿戎父，知为童子郎。
鱼牋请诗赋，幢布作衣裳。
薏苡扶衰病，归来幸可将。','',''),('quantangshi-05990','送梓州李使君','王維','quantangshi','','卷6','万壑树参天，千山响杜鹃。
山中一夜雨，树杪百重泉。
汉女输幢布，巴人讼芋田。
文翁翻教授，不敢倚先贤。','',''),('quantangshi-05991','送张五諲归宣城','王維','quantangshi','','卷6','五湖千万里，况复五湖西。
渔浦南陵郭，人家春谷溪。
欲归江淼淼，未到草萋萋。
忆想兰陵镇，可宜猿更啼。','',''),('quantangshi-05992','送友人南归','王維','quantangshi','','卷6','万里春应尽，三江雁亦稀。
连天汉水广，孤客郢城归。
郧国稻苗秀，楚人菰米肥。
悬知倚门望，遥识老莱衣。','',''),('quantangshi-05993','送贺遂员外外甥','王維','quantangshi','','卷6','南国有归舟，荆门溯上流。
苍茫葭菼外，云水与昭丘。
樯带城乌去，江连暮雨愁。
猿声不可听，莫待楚山秋。','',''),('quantangshi-05994','送杨长史赴果州','王維','quantangshi','','卷6','襃斜不容幰，之子去何之。
鸟道一千里，猿声十二时。
官桥祭酒客，山木女郎祠。
别后同明月，君应听子规。','',''),('quantangshi-05995','送邢桂州','王維','quantangshi','','卷6','铙吹喧京口，风波下洞庭。
赭圻将赤岸，击汰复扬舲。
日落江湖白，潮来天地青。
明珠归合浦，应逐使臣星。','',''),('quantangshi-05996','送宇文三赴河西充行军司马','王維','quantangshi','','卷6','横吹杂繁笳，边风卷塞沙。
还闻田司马，更逐李轻车。
蒲类成秦地，莎车属汉家。
当令犬戎国，朝聘学昆邪。','',''),('quantangshi-05997','送孙二','王維','quantangshi','','卷6','郊外谁相送，夫君道术亲。
书生邹鲁客，才子洛阳人。
祖席依寒草，行车起暮尘。
山川何寂寞，长望泪沾巾。','',''),('quantangshi-05998','送崔三往密州觐省','王維','quantangshi','','卷6','南陌去悠悠，东郊不少留。
同怀扇枕恋，独念倚门愁。
路遶天山雪，家临海树秋。
鲁连功未报，且莫蹈沧洲。','',''),('quantangshi-05999','送孟六归襄阳','王維','quantangshi','','卷6','杜门不复出，久与世情疎。
以此为良策，劝君归旧庐。
醉歌田舍酒，笑读古人书。
好是一生事，无劳献子虚。','',''),('quantangshi-06000','初出济州别城中故人','王維','quantangshi','','卷6','微官易得罪，谪去济川阴。
执政方持法，明君照此心。
闾阎河润上，井邑海云深。
纵有归来日，各愁年鬓侵。','',''),('quantangshi-06001','与卢象集朱家','王維','quantangshi','','卷6','主人能爱客，终日有逢迎。
贳得新丰酒，复闻秦女筝。
柳条疎客舍，槐叶下秋城。
语笑且为乐，吾将达此生。','',''),('quantangshi-06002','登裴秀才迪小台','王維','quantangshi','','卷6','端居不出户，满目望云山。
落日鸟边下，秋原人外闲。
遥知远林际，不见此檐间。
好客多乘月，应门莫上关。','',''),('quantangshi-06003','游李山人所居因题屋壁','王維','quantangshi','','卷6','世上皆如梦，狂来止自歌。
问年松树老，有地竹林多。
药倩韩康卖，门容尚子过。
翻嫌枕席上，无那白云何。','',''),('quantangshi-06004','过崔驸马山池','王維','quantangshi','','卷7','画楼吹笛妓，金椀酒家胡。
锦石称贞女，青松学大夫。
脱貂贳桂醑，射雁与山厨。
闻道高阳会，愚公谷正愚。','',''),('quantangshi-06005','过福禅师兰若','王維','quantangshi','','卷7','岩壑转微迳，云林隐法堂。
羽人飞奏乐，天女跪焚香。
竹外峰偏曙，藤阴水更凉。
欲知禅坐久，行路长春芳。','',''),('quantangshi-06006','过香积寺','王維','quantangshi','','卷7','不知香积寺，数里入云峰。
古木无人迳，深山何处钟。
泉声咽危石，日色冷青松。
薄暮空潭曲，安禅制毒龙。','',''),('quantangshi-06007','过感化寺昙兴上人山院','王維','quantangshi','','卷7','暮持筇竹杖，相待虎溪头。
催客闻山响，归房逐水流。
野花丛发好，谷鸟一声幽。
夜坐空林寂，松风直似秋。','',''),('quantangshi-06008','夏日过青龙寺谒操禅师','王維','quantangshi','','卷7','龙钟一老翁，徐步谒禅宫。
欲问义心义，遥知空病空。
山河天眼里，世界法身中。
莫怪销炎热，能生大地风。','',''),('quantangshi-06009','登辨觉寺','王維','quantangshi','','卷7','竹径从初地，莲峰出化城。
窗中三楚尽，林上九江平。
软草承趺坐，长松响梵声。
空居法云外，观世得无生。','',''),('quantangshi-06010','喜祖三至留宿','王維','quantangshi','','卷7','门前洛阳客，下马拂征衣。
不枉故人驾，平生多掩扉。
行人返深巷，积雪带余晖。
早岁同袍者，高车何处归。','',''),('quantangshi-06011','黎拾遗昕裴秀才迪见过秋夜对雨之作','王維','quantangshi','','卷7','促织鸣已急，轻衣行向重。
寒灯坐高馆，秋雨闻疎钟。
白法调狂象，玄言问老龙。
何人顾蓬径，空愧求羊踪。','',''),('quantangshi-06012','慕容承携素馔见过','王維','quantangshi','','卷7','纱帽乌皮几，闲居懒赋诗。
门看五柳识，年筭六身知。
灵寿君王赐，雕胡弟子炊。
空劳酒食馔，持底解人颐。','',''),('quantangshi-06013','晚春严少尹与诸公见过','王維','quantangshi','','卷7','松菊荒三迳，图书共五车。
烹葵邀上客，看竹到贫家。
鹊乳先春草，莺啼过落花。
自怜黄髪暮，一倍惜年华。','',''),('quantangshi-06014','郑果州相过','王維','quantangshi','','卷7','丽日照残春，初晴草木新。
牀前磨镜客，树下灌园人。
五马惊穷巷，双童逐老身。
中厨办麤饭，当恕阮家贫。','',''),('quantangshi-06015','山居秋暝','王維','quantangshi','','卷7','空山新雨后，天气晚来秋。
明月松间照，清泉石上流。
竹喧归浣女，莲动下渔舟。
随意春芳歇，王孙自可留。','',''),('quantangshi-06016','终南别业','王維','quantangshi','','卷7','中岁颇好道，晚家南山陲。
兴来每独往，胜事空自知。
行到水穷处，坐看云起时。
偶然值林叟，谈笑无还期。','',''),('quantangshi-06017','归嵩山作','王維','quantangshi','','卷7','清川带长薄，车马去闲闲。
流水如有意，暮禽相与还。
荒城临古渡，落日满秋山。
迢递嵩高下，归来且闭关。','',''),('quantangshi-06018','归辋川作','王維','quantangshi','','卷7','谷口疎钟动，渔樵稍欲稀。
悠然远山暮，独向白云归。
菱蔓弱难定，杨花轻易飞。
东臯春草色，惆怅掩柴扉。','',''),('quantangshi-06019','韦给事山居','王維','quantangshi','','卷7','幽寻得此地，讵有一人曾。
大壑随阶转，羣山入户登。
庖厨出深竹，印绶隔垂藤。
即事辞轩冕，谁云病未能。','',''),('quantangshi-06020','山居即事','王維','quantangshi','','卷7','寂寞掩柴扉，苍茫对落晖。
鹤巢松树遍，人访荜门稀。
绿竹含新粉，红莲落故衣。
渡头烟火起，处处采菱归。','',''),('quantangshi-06021','终南山','王維','quantangshi','','卷7','太乙近天都，连山接海隅。
白云回望合，青霭入看无。
分野中峰变，阴晴众壑殊。
欲投人处宿，隔水问樵夫。','',''),('quantangshi-06022','辋川闲居','王維','quantangshi','','卷7','一从归白社，不复到青门。
时倚檐前树，远看原上村。
青菰临水拔，白鸟向山翻。
寂寞于陵子，桔槔方灌园。','',''),('quantangshi-06023','春园即事','王維','quantangshi','','卷7','宿雨乘轻屐，春寒着弊袍。
开畦分白水，间柳发红桃。
草际成棋局，林端举桔槔。
还持鹿皮几，日暮隐蓬蒿。','',''),('quantangshi-06024','淇上田园即事','王維','quantangshi','','卷7','屏居淇水上，东野旷无山。
日隐桑柘外，河明闾井间。
牧童望村去，猎犬随人还。
静者亦何事，荆扉乘昼关。','',''),('quantangshi-06025','凉州郊外游望','王維','quantangshi','','卷7','野老才三户，边村少四邻。
婆娑依里社，箫鼓赛田神。
洒酒浇刍狗，焚香拜木人。
女巫纷屡舞，罗袜自生尘。','',''),('quantangshi-06026','观猎','王維','quantangshi','','卷7','风劲角弓鸣，将军猎渭城。
草枯鹰眼疾，雪尽马蹄轻。
忽过新丰市，还归细柳营。
回看射雕处，千里暮云平。','',''),('quantangshi-06027','春日上方即事','王維','quantangshi','','卷7','好读高僧传，时看辟谷方。
鸠形将刻杖，龟壳用支牀。
柳色春山暎，梨花夕鸟藏。
北窗桃李下，闲坐但焚香。','',''),('quantangshi-06028','汉江临泛','王維','quantangshi','','卷7','楚塞三湘接，荆门九派通。
江流天地外，山色有无中。
郡邑浮前浦，波澜动远空。
襄阳好风日，留醉与山翁。','',''),('quantangshi-06029','泛前陂','王維','quantangshi','','卷7','秋空自明迥，况复远人间。
畅以沙际鹤，兼之云外山。
澄波澹将夕，清月皓方闲。
此夜任孤棹，夷犹殊未还。','',''),('quantangshi-06030','登河北城楼作','王維','quantangshi','','卷7','井邑傅岩上，客亭云雾间。
高城眺落日，极浦暎苍山。
岸火孤舟宿，渔家夕鸟还。
寂寥天地暮，心与广川闲。','',''),('quantangshi-06031','千塔主人','王維','quantangshi','','卷7','逆旅逢佳节，征帆未可前。
窗临汴河水，门渡楚人船。
鸡犬散墟落，桑榆荫远田。
所居人不见，枕席生云烟。','',''),('quantangshi-06032','使至塞上','王維','quantangshi','','卷7','单车欲问边，属国过居延。
征蓬出汉塞，归雁入胡天。
大漠孤烟直，长河落日圆。
萧关逢候吏，都护在燕然。','',''),('quantangshi-06033','使至塞上','王維','quantangshi','','卷7','衔命辞天阙，单车欲问边。
征蓬出汉塞，归雁入胡天。
大漠孤烟直，长河落日圆。
萧关逢候吏，都护在燕然。','',''),('quantangshi-06034','晚春归思','王維','quantangshi','','卷7','新妆可怜色，落日卷罗帷。
炉气清珍簟，墙阴上玉墀。
春虫飞网户，暮雀隐花枝。
向晚多愁思，闲窗桃李时。','',''),('quantangshi-06035','戏题示萧氏甥','王維','quantangshi','','卷7','怜尔解临池，渠爷未学诗。
老夫何足似，弊宅倘因之。
芦笋穿荷叶，菱花罥雁儿。
郗公不易胜，莫着外家欺。','',''),('quantangshi-06036','秋夜独坐','王維','quantangshi','','卷7','独坐悲双鬓，空堂欲二更。
雨中山果落，灯下草虫鸣。
白发终难变，黄金不可成。
欲知除老病，唯有学无生。','',''),('quantangshi-06037','待储光羲不至','王維','quantangshi','','卷7','重门朝已启，起坐听车声。
要欲闻清佩，方将出户迎。
晚钟鸣上苑，疎雨过春城。
了自不相顾，临堂空复情。','',''),('quantangshi-06038','听宫莺','王維','quantangshi','','卷7','春树遶宫墙，宫莺啭曙光。
忽惊啼暂断，移处弄还长。
隐叶栖承露，攀花出未央。
游人未应返，为此始思乡。','',''),('quantangshi-06039','杂诗','王維','quantangshi','','卷7','双燕初命子，五桃新作花。
王昌是东舍，宋玉次西家。
小小能织绮，时时出浣纱。
亲劳使君问，南陌驻香车。','',''),('quantangshi-06040','留别钱起','王維','quantangshi','','卷7','卑栖却得性，每与白云归。
徇禄仍怀橘，看山免采薇。
暮禽先去马，新月待开扉。
霄汉时回首，知音青琐闱。','',''),('quantangshi-06041','留别丘为','王維','quantangshi','','卷7','归鞍白云外，缭绕出前山。
今日又明日，自知心不闲。
亲劳簪组送，欲趂莺花还。
一步一回首，迟迟向近关。','',''),('quantangshi-06042','愚公谷三首 一','王維','quantangshi','','卷7','愚谷与谁去，唯将黎子同。
非须一处住，不那两心空。
宁问春将夏，谁论西复东。
不知吾与子，若个是愚公。','',''),('quantangshi-06043','愚公谷三首 二','王維','quantangshi','','卷7','吾家愚谷里，此谷本来平。
虽则行无迹，还能响应声。
不随云色暗，只待日光明。
缘底名愚谷，都由愚所成。','',''),('quantangshi-06044','愚公谷三首 三','王維','quantangshi','','卷7','借问愚公谷，与君聊一寻。
不寻翻到谷，此谷不离心。
行处曾无险，看时岂有深。
寄言尘世客，何处欲归临。','',''),('quantangshi-06045','酬慕容十一','王維','quantangshi','','卷7','行行西陌返，驻幰问车公。
挟毂双官骑，应门五尺僮。
老年如塞北，强起离墙东。
为报壶丘子，来人道姓蒙。','',''),('quantangshi-06046','过始皇墓','王維','quantangshi','','卷7','古墓成苍岭，幽宫象紫台。
星辰七曜隔，河汉九泉开。
有海人宁渡，无春雁不廻。
更闻松韵切，疑是大夫哀。','',''),('quantangshi-06047','恭懿太子挽歌五首 一','王維','quantangshi','','卷7','何悟藏环早，才知拜璧年。
翀天王子去，对日圣君怜。
树转宫犹出，笳悲马不前。
虽蒙绝驰道，京兆别开阡。','',''),('quantangshi-06048','恭懿太子挽歌五首 二','王維','quantangshi','','卷7','兰殿新恩切，椒宫夕临幽。
白云随凤管，明月在龙楼。
人向青山哭，天临渭水愁。
鸡鸣常问膳，今恨玉京留。','',''),('quantangshi-06049','恭懿太子挽歌五首 三','王維','quantangshi','','卷7','骑吹凌霜发，旌旗夹路陈。
凯容金节护，册命玉符新。
傅母悲香褓，君家拥画轮。
射熊今梦帝，秤象问何人。','',''),('quantangshi-06050','恭懿太子挽歌五首 四','王維','quantangshi','','卷7','苍舒留帝宠，子晋有仙才。
五岁过人智，三天使鹤催。
心悲阳禄馆，目断望思台。
若道长安近，何为更不来。','',''),('quantangshi-06051','恭懿太子挽歌五首 五','王維','quantangshi','','卷7','西望昆池阔，东瞻下杜平。
山朝豫章馆，树转凤凰城。
五校连旗色，千门叠鼓声。
金环如有验，还向画堂生。','',''),('quantangshi-06052','故太子太师徐公挽歌四首 一','王維','quantangshi','','卷7','功德冠羣英，弥纶有大名。
轩皇用风后，傅说是星精。
就第优遗老，来朝诏不名。
留侯常辟谷，何苦不长生。','',''),('quantangshi-06053','故太子太师徐公挽歌四首 二','王維','quantangshi','','卷7','谋猷为相国，翊戴奉宸舆。
劒履升前殿，貂蝉托后车。
齐侯疏土宇，汉室赖图书。
僻处留田宅，仍才十顷余。','',''),('quantangshi-06054','故太子太师徐公挽歌四首 三','王維','quantangshi','','卷7','旧里趋庭日，新年置酒辰。
闻诗鸾渚客，献赋凤楼人。
北首辞明主，东堂哭大臣。
犹思御朱辂，不惜[污]车茵。','',''),('quantangshi-06055','故太子太师徐公挽歌四首 四','王維','quantangshi','','卷7','久践中台座，终登上将坛。
谁言断车骑，空忆盛衣冠。
风日咸阳惨，笳箫渭水寒。
无人当便阙，应罢太师官。','',''),('quantangshi-06056','故西河郡杜太守挽歌三首 一','王維','quantangshi','','卷7','天上去西征，云中护北平。
生擒白马将，连破黑雕城。
忽见刍灵苦，徒闻竹使荣。
空留左氏传，谁继卜商名。','',''),('quantangshi-06057','故西河郡杜太守挽歌三首 二','王維','quantangshi','','卷7','返葬金符守，同归石窌妻。
卷衣悲画翟，持翣待鸣鸡。
容衞都人惨，山川驷马嘶。
犹闻陇上客，相对哭征西。','',''),('quantangshi-06058','故西河郡杜太守挽歌三首 三','王維','quantangshi','','卷7','涂刍去国门，祕器出东园。
太守留金印，夫人罢锦轩。
旌旗转衰木，箫鼓上寒原。
坟树应西靡，长思魏阙恩。','',''),('quantangshi-06059','故南阳夫人樊氏挽歌','王維','quantangshi','','卷7','锦衣余翟茀，绣毂罢鱼轩。
淑女诗长在，夫人法尚存。
凝笳随晓斾，行哭向秋原。
归去将何见，谁能返戟门。','',''),('quantangshi-06060','达奚侍郎夫人寇氏挽词二首 一','王維','quantangshi','','卷7','束带将朝日，鸣环映牖辰。
能令谏明主，相劝识贤人。
遗挂空留壁，廻文日覆尘。','',''),('quantangshi-06061','达奚侍郎夫人寇氏挽词二首 二','王維','quantangshi','','卷7','女史悲彤管，夫人罢锦轩。
卜茔占二室，行哭度千门。
秋日光能淡，寒川波自翻。
一朝成万古，松柏暗平原。','',''),('quantangshi-06062','送孙秀才','王維','quantangshi','','卷7','帝城风日好，况复建平家。
玉枕双文簟，金盘五色瓜。
山中无鲁酒，松下饭胡麻。
莫厌田家苦，归期远复赊。','',''),('quantangshi-06063','奉和圣制庆玄元皇帝玉像之作应制','王維','quantangshi','','卷7','明君梦帝先，宝命上齐天。
秦后徒闻乐，周王耻卜年。
玉京移大像，金箓会羣仙。
承露调天供，临空敞御筵。
斗廻迎寿酒，山近起炉烟。
愿奉无为化，斋心学自然。','',''),('quantangshi-06064','奉和圣制与太子诸王三月三日龙池春禊应制','王維','quantangshi','','卷7','故事修春禊，新宫展豫游。
明君移凤辇，太子出龙楼。
赋掩陈王作，杯如洛水流。
金人来捧劒，画鷁去回舟。
苑树浮宫阙，天池照冕旒。
宸章在云表，垂象满皇州。','',''),('quantangshi-06065','奉和圣制上巳于望春亭观禊饮应制','王維','quantangshi','','卷7','长乐青门外，宜春小苑东。
楼开万井上，辇过百花中。
画鷁移仙妓，金貂列上公。
清歌邀落日，妙舞向春风。
渭水明秦甸，黄山入汉宫。
君王来祓禊，灞浐亦朝宗。','',''),('quantangshi-06066','奉和圣制暮春送朝集使归郡应制','王維','quantangshi','','卷7','万国仰宗周，衣冠拜冕旒。
玉乘迎大客，金节送诸侯。
祖席倾三省，褰帷向九州。
杨花飞上路，槐色荫通沟。
来预钧天乐，归分汉主忧。
宸章类河汉，垂象满中州。','',''),('quantangshi-06067','三月三日曲江侍宴应制','王維','quantangshi','','卷7','万乘亲斋祭，千官喜豫游。
奉迎从上苑，祓禊向中流。
草树连容衞，山河对冕旒。
画旗摇浦溆，春服满汀洲。
仙籞龙媒下，神臯凤跸留。
从今亿万岁，天宝纪春秋。','',''),('quantangshi-06068','奉和圣制重阳节宰臣及羣官上寿应制','王維','quantangshi','','卷7','四海方无事，三秋大有年。
百生无此日，万寿愿齐天。
芍药和金鼎，茱萸插玳筵。
玉堂开右个，天乐动宫悬。
御柳疎秋景，城鸦拂曙烟。
无穷菊花节，长奉柏梁篇。','',''),('quantangshi-06069','三月三日勤政楼侍宴应制','王維','quantangshi','','卷7','彩仗连宵合，琼楼拂曙通。
年光三月里，宫殿百花中。
不数秦王日，谁将洛水同。
酒筵嫌落絮，舞袖怯春风。
天保无为德，人欢不战功。
仍临九衢宴，更达四门聪。','',''),('quantangshi-06070','奉和圣制十五夜然灯继以酺宴应制','王維','quantangshi','','卷7','上路笙歌满，春城漏刻长。
游人多昼日，明月让灯光。
鱼钥通翔凤，龙舆出建章。
九衢陈广乐，百福透名香。
仙伎来金殿，都人遶玉堂。
定应偷妙舞，从此学新妆。
奉引迎三事，司仪列万方。
愿将天地寿，同以献君王。','',''),('quantangshi-06071','奉和圣制幸玉真公主山庄因题石壁十韵之作应制','王維','quantangshi','','卷7','碧落风烟外，瑶台道路赊。
如何连帝苑，别自有仙家。
此地回鸾驾，缘溪转翠华。
洞中开日月，窗里发云霞。
庭养冲天鹤，溪流上汉查。
种田生白玉，泥竈化丹砂。
谷静泉逾响，山深日易斜。
御羹和石髓，香饭进胡麻。
大道今无外，长生讵有涯。
还瞻九霄上，来往五云车。','',''),('quantangshi-06072','春日直门下省早朝','王維','quantangshi','','卷7','骑省直明光，鸡鸣谒建章。
遥闻侍中佩，暗识令君香。
玉漏随铜史，天书拜夕郎。
旌旗暎阊阖，歌吹满昭阳。
官舍梅初紫，宫门柳欲黄。
愿将迟日意，同与圣恩长。','',''),('quantangshi-06073','和仆射晋公扈从温汤','王維','quantangshi','','卷7','天子幸新丰，旌旗渭水东。
寒山天仗外，温谷幔城中。
奠玉羣仙座，焚香太乙宫。
出游逢牧马，罢猎见非熊。
上宰无为化，明时太古同。
灵芝三秀紫，陈粟万箱红。
王礼奠儒教，天兵小战功。
谋犹归哲匠，词赋属文宗。
司谏方无阙，陈诗且未工。
长吟吉甫颂，朝夕仰清风。','',''),('quantangshi-06074','和宋中丞夏日游福贤观天长寺寺即陈左相宅所施之作','王維','quantangshi','','卷7','已相殷王国，空余尚父溪。
钓矶开月殿，筑道出云梯。
积水浮香象，深山鸣白鸡。
虚空陈伎乐，衣服制虹霓。
墨点三千界，丹飞六一泥。
桃源勿遽返，再访恐君迷。','',''),('quantangshi-06075','和陈监四郎秋雨中思从弟据','王維','quantangshi','','卷7','袅袅秋风动，凄凄烟雨繁。
声连鳷鹊观，色暗凤凰原。
细柳疎高阁，轻槐落洞门。
九衢行欲断，万井寂无喧。
忽有愁霖唱，更陈多露言。
平原思令弟，康乐谢贤昆。
逸兴方三接，衰颜强七奔。
相如今老病，归守茂陵园。','',''),('quantangshi-06076','上张令公','王維','quantangshi','','卷7','珥笔趋丹陛，垂璫上玉除。
步檐青琐闼，方幰画轮车。
市阅千金字，朝闻五色书。
致君光帝典，荐士满公车。
伏奏回金驾，横经重石渠。
从兹罢角抵，且复幸储胥。
天统知尧后，王章笑鲁初。
匈奴遥俯伏，汉相俨簪裾。
贾生非不遇，汲黯自堪疎。
学易思求我，言诗或起予。
当从大夫后，何惜隶人余。','',''),('quantangshi-06077','赠焦道士','王維','quantangshi','','卷7','海上游三岛，淮南预八公。
坐知千里外，跳向一壶中。
缩地朝珠阙，行天使玉童。
饮人聊割酒，送客乍分风。
天老能行气，吾师不养空。
谢君徒雀跃，无可问鸿蒙。','',''),('quantangshi-06078','赠东岳焦炼师','王維','quantangshi','','卷7','先生千岁余，五岳遍曾居。
遥识齐侯鼎，新过王母庐。
不能师孔墨，何事问长沮。
玉管时来凤，铜盘即钓鱼。
竦身空里语，明目夜中书。
自有还丹术，时论太素初。
频蒙露版诏，时降软轮车。
山静泉逾响，松高枝转疎。
搘颐问樵客，世上复何如。','',''),('quantangshi-06079','送祕书晁监还日本国','王維','quantangshi','','卷7','积水不可极，安知沧海东。
九州何处远，万里若乘空。
向国唯看日，归帆但信风。
鳌身暎天黑，鱼眼射波红。
乡树扶桑外，主人孤岛中。
别离方异域，音信若为通。','',''),('quantangshi-06080','送禰郎中','王維','quantangshi','','卷7','东郊春草色，驱马去悠悠。
况复乡山外，猿啼湘水流。
岛夷传露版，江馆候鸣驺。
卉服为诸吏，珠官拜本州。
孤鸎吟远墅，野杏发山邮。
早晚方归奏，南中才忌秋。','',''),('quantangshi-06081','送李太守赴上洛','王維','quantangshi','','卷7','商山包楚邓，积翠蔼沈沈。
驿路飞泉洒，关门落照深。
野花开古戍，行客响空林。
板屋春多雨，山城昼欲阴。
丹泉通虢略，白羽抵荆岑。
若见西山爽，应知黄绮心。','',''),('quantangshi-06082','送熊九赴任安阳','王維','quantangshi','','卷7','魏国应刘后，寂寥文雅空。
漳河如旧日，之子继清风。
阡陌铜台下，闾阎金虎中。
送车盈灞上，轻骑出关东。
相去千余里，西园明月同。','',''),('quantangshi-06083','山中示弟','王維','quantangshi','','卷7','山林吾丧我，冠带尔成人。
莫学嵇康懒，且安原宪贫。
山阴多北户，泉水在东邻。
缘合妄相有，性空无所亲。
安知广成子，不是老夫身。','',''),('quantangshi-06084','青龙寺昙璧上人兄院集','王維','quantangshi','','卷7','高处敞招提，虚空讵有倪。
坐看南陌骑，下听秦城鸡。
眇眇孤烟起，芊芊远树齐。
青山万井外，落日五陵西。
眼界今无染，心空安可迷。','',''),('quantangshi-06085','济州过赵叟家宴','王維','quantangshi','','卷7','虽与人境接，闭门成隐居。
道言庄叟事，儒行鲁人余。
深巷斜晖静，闲门高柳疎。
荷锄修药圃，散帙曝农书。
上客摇芳翰，中厨馈野蔬。
夫君第高饮，景晏出林闾。','',''),('quantangshi-06086','春过贺遂员外药园','王維','quantangshi','','卷7','前年槿篱故，新作药栏成。
香草为君子，名花是长卿。
水穿盘石透，藤系古松生。
画畏开厨走，来蒙到屣迎。
蔗浆菰米饭，蒟酱露葵羹。
颇识灌园意，于陵不自轻。','',''),('quantangshi-06087','过卢四员外宅看饭僧共题七韵','王維','quantangshi','','卷7','三贤异七贤，青眼慕青莲。
乞饭从香积，裁衣学水田。
上人飞锡杖，檀越施金钱。
趺作檐前日，焚香竹下烟。
寒空法云地，秋色净居天。
身逐因缘法，心过次第禅。
不须愁日暮，自有一灯然。','',''),('quantangshi-06088','河南严尹弟见宿弊庐访别人赋十韵','王維','quantangshi','','卷7','上客能论道，吾生学养蒙。
贫交世情外，才子古人中。
冠上方簪豸，车边已画熊。
拂衣迎五马，垂手凭双童。
花醥和松屑，茶香透竹丛。
薄霜澄夜月，残雪带春风。
古壁苍苔黑，寒山远烧红。
眼看东候别，心事北川同。
为学轻先辈，何能访老翁。
欲知今日后，不乐为车公。','',''),('quantangshi-06089','投道一师兰若宿','王維','quantangshi','','卷7','一公栖太白，高顶出风烟。
梵流诸壑遍，花雨一峰偏。
迹为无心隐，名因立教传。
鸟来还语法，客去更安禅。
昼涉松路尽，暮投兰若边。
洞房隐深竹，清夜闻遥泉。
向是云霞里，今成枕席前。
岂唯暂留宿，服事将穷年。','',''),('quantangshi-06090','游感化寺','王維','quantangshi','','卷7','翡翠香烟合，琉璃宝地平。
龙宫连栋宇，虎穴傍檐楹。
谷静唯松响，山深无鸟声。
琼峰当户拆，金涧透林明。
郢路云端逈，秦川雨外晴。
雁王衔果献，鹿女踏花行。
抖擞辞贫里，归依宿化城。
绕篱生野蕨，空馆发山樱。
香饭青菰米，嘉蔬绿笋茎。
誓陪清梵末，端坐学无生。','',''),('quantangshi-06091','游悟真寺','王維','quantangshi','','卷7','闻道黄金地，仍开白玉田。
掷山移巨石，呪岭出飞泉。
猛虎同三迳，愁猿学四禅。
买香然绿桂，乞火踏红莲。
草色摇霞上，松声泛月边。
山河穷百二，世界接三千。
梵宇聊凭视，王城遂渺然。
灞陵才出树，渭水欲连天。
远县分诸郭，孤村起白烟。
望云思圣主，披雾隐羣贤。
薄宦惭尸素，终身拟尚玄。
谁知草庵客，曾和柏梁篇。','',''),('quantangshi-06092','与苏卢二员外期游方丈寺而苏不至因有是作','王維','quantangshi','','卷7','共仰头陀行，能忘世谛情。
回看双凤阙，相去一牛鸣。
法向空林说，心随宝地平。
手巾花氎净，香帔稻畦成。
闻道邀同舍，相期宿化城。
安知不来往，翻得似无生。','',''),('quantangshi-06093','晓行巴峡','王維','quantangshi','','卷7','际晓投巴峡，余春忆帝京。
晴江一女浣，朝日众鸡鸣。
水国舟中市，山桥树杪行。
登高万井出，眺迥二流明。
人作殊方语，鸎为故国声。
赖多山水趣，稍解别离情。','',''),('quantangshi-06094','清如玉壶冰','王維','quantangshi','','卷7','玉壶何用好，偏许素冰居。
未共销丹日，还同照绮疏。
抱明中不隐，含净外疑虚。
气似庭霜积，光言砌月余。
晓凌飞鹊镜，宵暎聚萤书。
若向夫君比，清心尚不如。','',''),('quantangshi-06095','赋得秋日悬清光','王維','quantangshi','','卷7','寥廓凉天静，晶明白日秋。
圆光含万象，碎影入闲流。
迥与青冥合，遥同江甸浮。
昼阴殊众木，斜影下危楼。
宋玉登高怨，张衡望远愁。
余辉如可托，云路岂悠悠。','',''),('quantangshi-06096','东溪玩月','王維','quantangshi','','卷7','月从断山口，遥吐柴门端。
万木分空霁，流阴中夜攒。
光连虚象白，气与风露寒。
谷静秋泉响，岩深青霭残。
清灯入幽梦，破影抱空峦。
恍惚琴窗里，松溪晓思难。','',''),('quantangshi-06097','田家','王維','quantangshi','','卷7','旧谷行将尽，良苗未可希。
老年方爱粥，卒岁且无衣。
雀乳青苔井，鸡鸣白板扉。
柴车驾羸牸，草屩牧豪狶。
夕雨红榴拆，新秋绿芋肥。
饷田桑下憩，旁舍草中归。
住处名愚谷，何烦问是非。','',''),('quantangshi-06098','沈十四拾遗新竹生读经处同诸公之作','王維','quantangshi','','卷7','闲居日清静，修竹自檀栾。
嫩节留余箨，新丛出旧阑。
细枝风响乱，疎影月光寒。
乐府裁龙笛，渔家伐钓竿。
何如道门里，青翠拂仙坛。','',''),('quantangshi-06099','杂诗','王維','quantangshi','','卷7','朝因折杨柳，相见洛阳隅。
楚国无如妾，秦家自有夫。
对人传玉腕，暎烛解罗襦。
人见东方骑，皆言夫壻殊。
持谢金吾子，烦君提玉壶。','',''),('quantangshi-06100','哭褚司马','王維','quantangshi','','卷7','妄识皆心累，浮生定死媒。
谁言老龙吉，未免伯牛灾。
故有求仙药，仍余遯俗杯。
山川秋树苦，窗户夜泉哀。
尚忆青骡去，宁知白马来。
汉臣修史记，莫蔽褚生才。','',''),('quantangshi-06101','过沈居士山居哭之','王維','quantangshi','','卷7','杨朱来此哭，桑扈返于真。
独自成千古，依然旧四邻。
闲檐喧鸟鹊，故榻满埃尘。
曙月孤莺啭，空山五柳春。
野花愁对客，泉水咽迎人。
善卷明时隐，黔娄在日贫。
逝川嗟尔命，丘井叹吾身。
前后徒言隔，相悲讵几晨。','',''),('quantangshi-06102','哭祖六自虚','王維','quantangshi','','卷7','否极尝闻泰，嗟君独不然。
悯凶才稚齿，羸疾主中年。
余力文章秀，生知礼乐全。
翰留天帐览，词入帝宫传。
国讶终军少，人知贾谊贤。
公卿尽虚左，朋识共推先。
不恨依穷辙，终期济巨川。
才雄望羔雁，寿促背貂蝉。
福善闻前录，歼良昧上玄。
何辜铩鸾翮，底事碎龙泉。
鵩起长沙赋，麟终曲阜编。
域中君道广，海内我情偏。
乍失疑犹见，沈思悟绝缘。
生前不忍别，死后向谁宣。
为此情难尽，弥令忆更缠。
本家清渭曲，归葬旧茔边。
永去长安道，徒闻京兆阡。
旌车出郊甸，乡国隐云天。
定作无期别，宁同旧日旋。
候门家属苦，行路国人怜。
送客哀难进，征途泥复前。
赠言为挽曲，奠席是离筵。
念昔同携手，风期不暂捐。
南山俱隐逸，东洛类神仙。
未省音容间，那堪生死迁。
花时金谷饮，月夜竹林眠。
满地传都赋，倾朝看药船。
羣公咸属目，微物敢齐肩。
谬合同人旨，而将玉树连。
不期先挂劒，长恐后施鞭。
为善吾无矣，知音子绝焉。
琴声纵不没，终亦继悲弦。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-06103','奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制','王維','quantangshi','','卷7','渭水自萦秦塞曲，黄山旧遶汉宫斜。
銮舆迥出千门柳，阁道廻看上苑花。
云里帝城双凤阙，雨中春树万人家。
为乘阳气行时令，不是宸游玩物华。','',''),('quantangshi-06104','大同殿柱产玉芝龙池上有庆云神光照殿百官共覩圣恩便赐宴乐敢书即事','王維','quantangshi','','卷7','欲笑周文歌宴镐，遥轻汉武乐横汾。
岂知玉殿生三秀，讵有铜池出五云。
陌上尧樽倾北斗，楼前舜乐动南薰。
共欢天意同人意，万岁千秋奉圣君。','',''),('quantangshi-06105','敕赐百官樱桃','王維','quantangshi','','卷7','芙蓉阙下会千官，紫禁朱樱出上[兰]。
才是寝园春荐后，非关御苑鸟衔残。
归鞍竞带青丝笼，中使频倾赤玉盘。
饱食不须愁内热，大官还有蔗浆寒。','',''),('quantangshi-06106','敕借岐王九成宫避暑应教','王維','quantangshi','','卷7','帝子远辞丹凤阙，天书遥借翠微宫。
隔窗云雾生衣上，卷幔山泉入镜中。
林下水声喧语笑，岩间树色隐房栊。
仙家未必能胜此，何事吹笙向碧空。','',''),('quantangshi-06107','和贾舍人早朝大明宫之作','王維','quantangshi','','卷7','绛帻鸡人送晓筹，尚衣方进翠云裘。
九天阊阖开宫殿，万国衣冠拜冕旒。
日色才临仙掌动，香烟欲傍衮龙浮。
朝罢须裁五色诏，佩声归向凤池头。','',''),('quantangshi-06108','和太常韦主簿五郎温汤寓目之作','王維','quantangshi','','卷7','汉主离宫接露台，秦川一半夕阳开。
青山尽是朱旗绕，碧涧翻从玉殿来。
新丰树里行人度，小苑城边猎骑廻。
闻道甘泉能献赋，悬知独有子云才。','',''),('quantangshi-06109','苑舍人能书梵字兼达梵音皆曲尽其妙戏为之赠','王維','quantangshi','','卷7','名儒待诏满公车，才子为郎典石渠。
莲花法藏心悬悟，贝叶经文手自书。
楚词共许胜杨马，梵字何人辨鲁鱼。
故旧相望在三事，愿君莫厌承明庐。','',''),('quantangshi-06110','重酬苑郎中','王維','quantangshi','','卷7','何幸含香奉至尊，多慙未报主人恩。
草木尽能酬雨露，荣枯安敢问干坤。
仙郎有意怜同舍，丞相无私断埽门。
扬子解嘲徒自遣，冯唐已老复何论。','',''),('quantangshi-06111','酬郭给事','王維','quantangshi','','卷7','洞门高阁霭余辉，桃李阴阴柳絮飞。
禁里疎钟官舍晚，省中啼鸟吏人稀。
晨摇玉佩趋金殿，夕奉天书拜琐闱。
强欲从君无那老，将因卧病解朝衣。','',''),('quantangshi-06112','出塞','王維','quantangshi','','卷7','居延城外猎天骄，白草连山野火烧。
暮云空碛时驱马，秋日平原好射雕。
护羗校尉朝乘障，破虏将军夜渡辽。
玉靶角弓珠勒马，汉家将赐霍嫖姚。','',''),('quantangshi-06113','既蒙宥罪旋复拜官伏感圣恩窃书鄙意兼奉简新除使君等诸公','王維','quantangshi','','卷7','忽蒙汉诏还冠冕，始觉殷王解网罗。
日比皇明犹自暗，天齐圣寿未云多。
花迎喜气皆知笑，鸟识欢心亦解歌。
闻道百城新佩印，还来双阙共鸣珂。','',''),('quantangshi-06114','送方尊师归嵩山','王維','quantangshi','','卷7','仙官欲往九龙潭，旄节朱幡倚石龛。
山压天中半天上，洞穿江底出江南。
瀑布杉松常带雨，夕阳苍翠忽成岚。
借问迎来双白鹤，已曾衡岳送苏耽。','',''),('quantangshi-06115','送杨少府贬郴州','王維','quantangshi','','卷7','明到衡山与洞庭，若为秋月听猿声。
愁看北渚三湘远，恶说南风五两轻。
青草瘴时过夏口，白头浪里出湓城。
长沙不久留才子，贾谊何须吊屈平。','',''),('quantangshi-06116','过乘如禅师萧居士嵩丘兰若','王維','quantangshi','','卷7','无着天亲弟与兄，嵩丘兰若一峰晴。
食随鸣磬巢乌下，行踏空林落叶声。
迸水定侵香案湿，雨花应共石牀平。
深洞长松何所有，俨然天竺古先生。','',''),('quantangshi-06117','春日与裴迪过新昌里访吕逸人不遇','王維','quantangshi','','卷7','桃源一向绝风尘，柳市南头访隐沦。
到门不敢题凡鸟，看竹何须问主人。
城上青山如屋里，东家流水入西邻。
闭户着书多岁月，种松皆老作龙鳞。','',''),('quantangshi-06118','酌酒与裴迪','王維','quantangshi','','卷7','酌酒与君君自宽，人情翻覆似波澜。
白首相知犹按劒，朱门先达笑弹冠。
草色全经细雨湿，花枝欲动春风寒。
世事浮云何足问，不如高卧且加餐。','',''),('quantangshi-06119','辋川别业','王維','quantangshi','','卷7','不到东山向一年，归来才及种春田。
雨中草色绿堪染，水上桃花红欲然。
优娄比丘经论学，伛偻丈人乡里贤。
披衣倒屣且相见，相欢语笑衡门前。','',''),('quantangshi-06120','早秋山中作','王維','quantangshi','','卷7','无才不敢累明时，思向东溪守故篱。
岂厌尚平婚嫁早，却嫌陶令去官迟。
草间蛩响临秋急，山里蝉声薄暮悲。
寂寞柴门人不到，空林独与白云期。','',''),('quantangshi-06121','积雨辋川庄作','王維','quantangshi','','卷7','积雨空林烟火迟，蒸藜炊黍饷东菑。
漠漠水田飞白鹭，阴阴夏木啭黄鹂。
山中习静观朝槿，松下清斋折露葵。
野老与人争席罢，海鸥何事更相疑。','',''),('quantangshi-06122','听百舌鸟','王維','quantangshi','','卷7','上兰门外草萋萋，未央宫中花里栖。
亦有相随过御苑，不知若个向金堤。
入春解作千般语，拂曙能先百鸟啼。
万户千门应觉晓，建章何必听鸣鸡。','',''),('quantangshi-06123','息夫人','王維','quantangshi','','卷7','莫以今时宠，难忘旧日恩。
看花满眼泪，不共楚王言。','',''),('quantangshi-06124','班婕妤三首 一','王維','quantangshi','','卷7','玉窗萤影度，金殿人声绝。
秋夜守罗帷，孤灯耿不灭。','',''),('quantangshi-06125','班婕妤三首 二','王維','quantangshi','','卷7','宫殿生秋草，君王恩幸疎。
那堪闻凤吹，门外度金舆。','',''),('quantangshi-06126','班婕妤三首 三','王維','quantangshi','','卷7','怪来妆阁闭，朝下不相迎。
总向春园里，花间笑语声。','',''),('quantangshi-06127','辋川集 孟城坳','王維','quantangshi','','卷7','新家孟城口，古木余衰柳。
来者复为谁，空悲昔人有。','',''),('quantangshi-06128','辋川集 华子冈','王維','quantangshi','','卷7','飞鸟去不穷，连山复秋色。
上下华子冈，惆怅情何极。','',''),('quantangshi-06129','辋川集 文杏馆','王維','quantangshi','','卷7','文杏裁为梁，香茅结为宇。
不知栋里云，去作人间雨。','',''),('quantangshi-06130','辋川集 斤竹岭','王維','quantangshi','','卷7','檀栾暎空曲，青翠漾涟漪。
暗入商山路，樵人不可知。','',''),('quantangshi-06131','辋川集 鹿柴','王維','quantangshi','','卷7','空山不见人，但闻人语响。
返景入深林，复照青苔上。','',''),('quantangshi-06132','辋川集 木兰柴','王維','quantangshi','','卷7','秋山敛余照，飞鸟逐前侣。
彩翠时分明，夕岚无处所。','',''),('quantangshi-06133','辋川集 茱萸沜','王維','quantangshi','','卷7','结实红且绿，复如花更开。
山中傥留客，置此芙蓉杯。','',''),('quantangshi-06134','辋川集 宫槐陌','王維','quantangshi','','卷7','仄迳荫宫槐，幽阴多绿苔。
应门但迎埽，畏有山僧来。','',''),('quantangshi-06135','辋川集 临湖亭','王維','quantangshi','','卷7','轻舸迎上客，悠悠湖上来。
当轩对尊酒，四面芙蓉开。','',''),('quantangshi-06136','辋川集 南垞','王維','quantangshi','','卷7','轻舟南垞去，北垞淼难即。
隔浦望人家，遥遥不相识。','',''),('quantangshi-06137','辋川集 欹湖','王維','quantangshi','','卷7','吹箫凌极浦，日暮送夫君。
湖上一回首，青山卷白云。','',''),('quantangshi-06138','辋川集 柳浪','王維','quantangshi','','卷7','分行接绮树，倒影入清漪。
不学御沟上，春风伤别离。','',''),('quantangshi-06139','辋川集 栾家濑','王維','quantangshi','','卷7','飒飒秋雨中，浅浅石溜泻。
跳波自相溅，白鹭惊复下。','',''),('quantangshi-06140','辋川集 金屑泉','王維','quantangshi','','卷7','日饮金屑泉，少当千余岁。
翠凤翊文螭，羽节朝玉帝。','',''),('quantangshi-06141','辋川集 白石滩','王維','quantangshi','','卷7','清浅白石滩，绿蒲向堪把。
家住水东西，浣纱明月下。','',''),('quantangshi-06142','辋川集 北垞','王維','quantangshi','','卷7','北垞湖水北，杂树暎朱阑。
逶迤南川水，明灭青林端。','',''),('quantangshi-06143','辋川集 竹里馆','王維','quantangshi','','卷7','独坐幽篁里，弹琴复长啸。
深林人不知，明月来相照。','',''),('quantangshi-06144','辋川集 辛夷坞','王維','quantangshi','','卷7','木末芙蓉花，山中发红萼。
涧户寂无人，纷纷开且落。','',''),('quantangshi-06145','辋川集 漆园','王維','quantangshi','','卷7','古人非傲吏，自阙经世务。
偶寄一微官，婆娑数株树。','',''),('quantangshi-06146','辋川集 椒园','王維','quantangshi','','卷7','桂尊迎帝子，杜若赠佳人。
椒浆奠瑶席，欲下云中君。','',''),('quantangshi-06147','皇甫岳云溪杂题五首 鸟鸣涧','王維','quantangshi','','卷7','人闲桂花落，夜静春山空。
月出惊山鸟，时鸣春涧中。','',''),('quantangshi-06148','皇甫岳云溪杂题五首 莲花坞','王維','quantangshi','','卷7','日日采莲去，洲长多暮归。
弄篙莫溅水，畏湿红莲衣。','',''),('quantangshi-06149','皇甫岳云溪杂题五首 鸬鹚堰','王維','quantangshi','','卷7','乍向红莲没，复出清蒲扬。
独立何䙰褷，衔鱼古查上。','',''),('quantangshi-06150','皇甫岳云溪杂题五首 上平田','王維','quantangshi','','卷7','朝耕上平田，暮耕上平田。
借问问津者，宁知沮溺贤。','',''),('quantangshi-06151','皇甫岳云溪杂题五首 萍池','王維','quantangshi','','卷7','春池深且广，会待轻舟回。
靡靡绿萍合，垂杨埽复开。','',''),('quantangshi-06152','答裴迪辋口遇雨忆终南山之作','王維','quantangshi','','卷7','淼淼寒流广，苍苍秋雨晦。
君问终南山，心知白云外。','',''),('quantangshi-06153','山中寄诸弟妹','王維','quantangshi','','卷7','山中多法侣，禅诵自为羣。
城郭遥相望，唯应见白云。','',''),('quantangshi-06154','闻裴秀才迪吟诗因戏赠','王維','quantangshi','','卷7','猿吟一何苦，愁朝复悲夕。
莫作巫峡声，肠断秋江客。','',''),('quantangshi-06155','赠韦穆十八','王維','quantangshi','','卷7','与君青眼客，共有白云心。
不相东山去，日令春草深。','',''),('quantangshi-06156','送别','王維','quantangshi','','卷7','山中相送罢，日暮掩柴扉。
春草明年绿，王孙归不归。','',''),('quantangshi-06157','临高台送黎拾遗','王維','quantangshi','','卷7','相送临高台，川原杳何极。
日暮飞鸟还，行人去不息。','',''),('quantangshi-06158','别辋川别业','王維','quantangshi','','卷7','依迟动车马，惆怅出松萝。
忍别青山去，其如绿水何。','',''),('quantangshi-06159','崔九弟欲往南山马上口号与别','王維','quantangshi','','卷7','城隅一分手，几日还相见。
山中有桂花，莫待花如霰。','',''),('quantangshi-06160','题友人云母障子','王維','quantangshi','','卷7','君家云母障，时向野庭开。
自有山泉入，非因采画来。','',''),('quantangshi-06161','红牡丹','王維','quantangshi','','卷7','绿艳闲且静，红衣浅复深。
