朱实初传九华殿，繁花旧杂万年枝。
未胜晏子江南橘，莫比潘家大谷梨。
闻道令人好颜色，神农本草自应知。','',''),('quantangshi-06246','留别王维','崔興宗','quantangshi','','卷7','驻马欲分襟，清寒御沟上。
前山景气佳，独往还惆怅。','',''),('quantangshi-06247','酬王维卢象见过林亭','崔興宗','quantangshi','','卷7','穷巷空林常闭关，悠然独卧对前山。
今朝忽枉嵇生驾，倒屣开门遥解颜。','',''),('quantangshi-06248','送大理正摄御史判凉州别驾','苑咸','quantangshi','','卷7','天子念西疆，咨君去不遑。
垂银棘庭印，持斧柏台纲。
雪下天山白，泉枯塞草黄。
伫闻河陇外，还继海沂康。','',''),('quantangshi-06249','酬王维','苑咸','quantangshi','','卷7','莲花梵字本从天，华省仙郎早悟禅。
三点成伊犹有想，一观如幻自忘筌。
为文已变当时体，入用还推间气贤。
应同罗汉无名欲，故作冯唐老岁年。','',''),('quantangshi-06250','寻西山隐者不遇','丘爲','quantangshi','','卷7','绝顶一茅茨，直[上]三十里。
扣关无僮仆，窥室唯案几。
若非巾柴车，应是钓秋水。
差池不相见，黾勉空仰止。
草色新雨中，松声晚牕里。
及兹契幽绝，自足荡心耳。
虽无宾主意，颇得清净理。
兴尽方下山，何必待之子。','',''),('quantangshi-06251','题农父庐舍','丘爲','quantangshi','','卷7','东风何时至，已绿湖上山。
湖上春已早，田家日不闲。
沟塍流水处，耒耜平芜间。
薄暮饭牛罢，归来还闭关。','',''),('quantangshi-06252','泛若耶溪','丘爲','quantangshi','','卷7','结庐若耶里，左右若耶水。
无日不钓鱼，有时向城市。
溪中水流急，渡口水流宽。
每得樵风便，往来殊不难。
一川草长绿，四时那得辨。
短褐衣妻儿，余粮及鸡犬。
日暮鸟雀稀，稚子呼牛归。
住处无邻里，柴门独掩扉。','',''),('quantangshi-06253','湖中寄王侍御','丘爲','quantangshi','','卷7','日日湖水上，好登湖上楼。
终年不向郭，过午始梳头。
尝自爱杯酒，得无相献酬。
小僮能脍鲤，少妾事莲舟。
每有南浦信，仍期后月游。
方春转摇荡，孤兴时淹留。
骢马真傲吏，翛然无所求。
晨趋玉阶下，心许沧江流。
少别如昨日，何言经数秋。
应知方外事，独往非悠悠。','',''),('quantangshi-06254','登润州城','丘爲','quantangshi','','卷7','天末江城晚，登临客望迷。
春潮平岛屿，残雨隔虹霓。
鸟与孤帆远，烟和独树低。
乡山何处是？目断广陵西。','',''),('quantangshi-06255','寻庐山崔征君','丘爲','quantangshi','','卷7','日高鸡犬静，门掩向寒塘。
夜竹深茅宇，秋亭冷石牀。
住山年已远，服药寿偏长。
虚弃浮生者，相逢益自伤。','',''),('quantangshi-06256','留别王维','丘爲','quantangshi','','卷7','归鞍白云外，缭绕出前山。
今日又明日，自知心不闲。
亲劳簪组送，欲趂莺花还。
一步一回首，迟迟向近关。','',''),('quantangshi-06257','竹下残雪','丘爲','quantangshi','','卷7','一点消未尽，孤月在竹阴。
晴光夜转莹，寒气晓仍深。
还对读书牖，且关乘兴心。
已能依此地，终不傍瑶琴。','',''),('quantangshi-06258','送阎校书之越','丘爲','quantangshi','','卷7','南入剡中路，草云应转微。
湖边好花照，山口细泉飞。
此地饶古迹，世人多忘归。
经年松雪在，永日世情稀。
芸阁应相望，芳时不可违。','',''),('quantangshi-06259','省试夏日可畏','丘爲','quantangshi','','卷7','赫赫温风扇，炎炎夏日徂。
火威驰迥野，畏景烁遥途。
势矫翔阳翰，功分造化炉。
禁城千品烛，黄道一轮孤。
落照频空簟，余晖卷夕梧。
如何倦游子，中路独踟蹰。','',''),('quantangshi-06260','左掖梨花','丘爲','quantangshi','','卷7','冷艳全欺雪，余香乍入衣。
春风且莫定，吹向玉阶飞。','',''),('quantangshi-06261','渡汉江','丘爲','quantangshi','','卷7','漾舟汉江上，挂席候风生。
临泛何容与，爱此江水清。
芦洲隐遥嶂，露日隐孤城。
自顾疎野性，难忘鸥鸟情。
聊复与时顾，暂欲解尘缨。
跋涉非吾愿，虚怀浩已盈。','',''),('quantangshi-06262','冬至下寄舍弟时应赴入京','丘爲','quantangshi','','卷7','去去知未远，依依甚初别。
他乡至下心，昨夜堦前雪。
终日读书仍少孤，家贫兄弟未当途。
适远才过宿舂料，相随惟一平头奴。
男儿出门事四海，立身世业文章在。
莫漫忆柴扉，驷马高车朝紫微。
江南驿使不曾断，迎前为尔非春衣。','',''),('quantangshi-06263','送晁补阙归日本国','趙驊','quantangshi','','卷7','西掖承休澣，东隅返故林。
来称郯子学，归是越人吟。
马上秋郊远，舟中曙海阴。
知君怀魏阙，万里独摇心。','',''),('quantangshi-06264','古游侠呈军中诸将','崔顥','quantangshi','','卷7','少年负胆气，好勇复知机。
仗剑出门去，孤城逢合围。
杀人辽水上，走马渔阳归。
错落金锁甲，蒙茸貂鼠衣。
还家行且猎，弓矢速如飞。
地迥鹰犬疾，草深狐兔肥。
腰间带两绶，转盼生光辉。
顾谓今日战，何如随建威。','',''),('quantangshi-06265','赠轻车','崔顥','quantangshi','','卷7','悠悠远行归，经春涉长道。
幽冀桑始青，洛阳蚕欲老。
忆昨戎马地，别时心草草。
烽火从北来，边城闭常早。
平生少相遇，未得展怀抱。
今日杯酒间，见君交情好。','',''),('quantangshi-06266','赠王威古','崔顥','quantangshi','','卷7','三十羽林将，出身常事边。
春风吹浅草，猎骑何翩翩。
插羽两相顾，鸣弓新上弦。
射麋入深谷，饮马投荒泉。
马上共倾酒，野中聊割鲜。
相看未及饮，杂虏寇幽燕。
烽火去不息，胡尘高际天。
长驱救东北，战解城亦全。
报国行赴难，古来皆共然。','',''),('quantangshi-06267','赠怀一上人','崔顥','quantangshi','','卷7','法师东南秀，世实豪家子。
削发十二年，诵经峨眉里。
自此照羣蒙，卓然为道雄。
观生尽入妄，悟有皆成空。
净体无众染，苦心归妙宗。
一朝敕书至，召入承明宫。
说法金殿里，焚香清禁中。
传灯遍都邑，杖锡游王公。
天子揖妙道，羣僚趋下风。
我法本无着，时来出林壑。
因心得化城，随病皆与药。
上启黄屋心，下除苍生缚。
一从入君门，说法无朝昏。
帝作转轮王，师为持戒尊。
轩风洒甘露，佛雨生慈根。
但有灭度理，而生开济恩。
复闻江海曲，好杀成风俗。
帝曰我上人，为除膻腥欲。
是日发西秦，东南至蕲春。
风将衡桂接，地与吴楚邻。
旧少清信士，实多渔猎人。
一闻吾师至，舍网江湖滨。
作礼忏前恶，洁诚期后因。
因成日既久，事济身不守。
更出淮楚间，复来荆河口。
荆河马卿岑，兹地近道林。
入讲鸟常狎，坐禅兽不侵。
都非缘未尽，曾是教所任。
故我一来事，永承微妙音。
竹房见衣钵，松宇清身心。
早悔业至浅，晚成计可寻。
善哉远公义，清净如黄金。','',''),('quantangshi-06268','游天竺寺','崔顥','quantangshi','','卷7','晨登天竺山，山殿朝阳晓。
厓泉争喷薄，江岫相萦绕。
直上孤顶高，平看众峰小。
南州十二月，地暖冰雪少。
青翠满寒山，藤萝覆冬沼。
花龛瀑布侧，青壁石林杪。
鸣钟集人天，施饭聚猨鸟。
洗意归清净，澄心悟空了。
始知世上人，万物一何扰。','',''),('quantangshi-06269','入若耶溪','崔顥','quantangshi','','卷7','轻舟去何疾，已到云林境。
起坐鱼鸟间，动摇山水影。
岩中响自答，溪里言弥静。
事事令人幽，停桡向余景。','',''),('quantangshi-06270','杂诗','崔顥','quantangshi','','卷7','可怜青铜镜，挂在白玉堂。
玉堂有美女，娇弄明月光。
罗袖拂金鹊，彩屏点红妆。
妆罢含情坐，春风桃李香。','',''),('quantangshi-06271','结定襄郡狱效陶体','崔顥','quantangshi','','卷7','我在河东时，使往定襄里。
定襄诸小儿，争讼纷城市。
长老莫敢言，太守不能理。
谤书盈几案，文墨相填委。
牵引肆中翁，追呼田家子。
我来折此狱，五听辨疑似。
小大必以情，未尝施鞭棰。
是时三月暮，遍野农桑起。
里巷鸣春鸠，田园引流水。
此乡多杂俗，戎夏殊音旨。
顾问边塞人，劳情曷云已。','',''),('quantangshi-06272','长安道','崔顥','quantangshi','','卷7','长安甲第高入云，谁家居住霍将军。
日晚朝回拥宾从，路傍揖拜何纷纷。
莫言炙手手可热，须臾火尽灰亦灭。
莫言贫贱即可欺，人生富贵自有时。
一朝天子赐眼色，世上悠悠应始知。','',''),('quantangshi-06273','行路难','崔顥','quantangshi','','卷7','君不见建章宫中金明枝，万万长条拂地垂。
二月三月花如霰，九重幽深君不见。
艳彩朝含四宝宫，香风旦入朝云殿。
汉家宫女春未阑，爱此芳香朝暮看。
看来看去心不忘，攀折将安镜台上。
双双素手剪不成，两两红妆笑相向。
建章昨夜起春风，一花飞落长信宫。
长信丽人见花泣，忆此珍树何嗟及。
我昔初在昭阳时，朝攀暮折登玉墀。
只言岁岁长相对，不悟今朝遥相思。','',''),('quantangshi-06274','孟门行','崔顥','quantangshi','','卷7','黄雀衔黄花，翩翩傍檐隙。
本拟报君恩，如何反弹射。
金罍美酒满座春，平原爱才多众宾。
满堂尽是忠义士，何意得有谗谀人。
谀言反覆那可道，能令君心不自保。
北园新栽桃李枝，根株未固何转移。
成阴结实君自取，若问傍人那得知。','',''),('quantangshi-06275','渭城少年行','崔顥','quantangshi','','卷7','洛阳三月梨花飞，秦地行人春忆归。
扬鞭走马城南陌，朝逢驿使秦川客。
驿使前日发章台，传道长安春早来。
棠梨宫中燕初至，葡萄馆里花正开。
念此使人归更早，三月便达长安道。
长安道上春可怜，摇风荡日曲江边。
万户楼台临渭水，五陵花柳满秦川。
秦川寒食盛繁华，游子春来不见家。
鬬鸡下杜尘初合，走马章台日半斜。
章台帝城称贵里，青楼日晚歌钟起。
贵里豪家白马骄，五陵年少不相饶。
双双挟弹来金市，两两鸣鞭上渭桥。
渭城桥头酒新熟，金鞍白马谁家宿。
可怜锦瑟筝琵琶，玉壶清酒就倡家。
小妇春来不解羞，娇歌一曲杨柳花。','',''),('quantangshi-06276','卢姬篇','崔顥','quantangshi','','卷7','卢姬少小魏王家，绿鬓红唇桃李花。
魏王绮楼十二重，水晶帘箔绣芙蓉。
白玉栏干金作柱，楼上朝朝学歌舞。
前堂后堂罗袖人，南窗北窗花发春。
翠幌珠帘鬬丝管，一弹一奏云欲断。
君王日晚下朝归，鸣环佩玉生光辉。
人生今日得娇贵，谁道卢姬身细微。','',''),('quantangshi-06277','江畔老人愁','崔顥','quantangshi','','卷7','江南年少十八九，乘舟欲渡青溪口。
青溪口边一老翁，鬓眉皓白已衰朽。
自言家代仕梁陈，垂朱拖紫三十人。
两朝出将复入相，五世叠鼓乘朱轮。
父兄三叶皆尚主，子女四代为妃嫔。
南山赐田接御苑，北宫甲第连紫宸。
直言荣华未休歇，不觉山崩海将竭。
兵戈乱入建康城，烟火连烧未央阙。
衣冠士子陷锋刃，良将名臣尽埋没。
山川改易失市朝，衢路纵横填白骨。
老人此时尚少年，脱身走得投海边。
罢兵岁余未敢出，去乡三载方来旋。
蓬蒿忘却五城宅，草木不识青溪田。
虽然得归到乡土，零丁贫贱长辛苦。
采樵屡入历阳山，刈稻常过新林浦。
少年欲知老人岁，岂知今年一百五。
君今少壮我已衰，我昔少年君不睹。
人生贵贱各有时，莫见羸老相轻欺。
感君相问为君说，说罢不觉令人悲。','',''),('quantangshi-06278','邯郸宫人怨','崔顥','quantangshi','','卷7','邯郸陌上三月春，暮行逢见一妇人。
自言乡里本燕赵，少小随家西入秦。
母兄怜爱无俦侣，五岁名为阿娇女。
七岁丰茸好颜色，八岁黠惠能言语。
十三兄弟教诗书，十五青楼学歌舞。
我家青楼临道傍，纱窗绮幔暗闻香。
日暮笙歌君驻马，春日妆梳妾断肠。
不用城南使君壻，本求三十侍中郎。
何知汉帝好容色，玉辇携登归建章。
建章宫殿不知数，万户千门深且长。
百堵涂椒接青琐，九华阁道连洞房。
水晶帘箔云母扇，琉璃窗牖玳瑁牀。
岁岁年年奉欢宴，娇贵荣华谁不羡。
恩情莫比陈皇后，宠爱全胜赵飞燕。
瑶房侍寝世莫知，金屋更衣人不见。
谁言一朝复一日，君王弃世市朝变。
宫车出葬茂陵田，贱妾独留长信殿。
一朝太子升至尊，宫中人事如掌翻。
同时侍女见谗毁，后来新人莫敢言。
兄弟印绶皆被夺，昔年赏赐不复存。
一旦放归旧乡里，乘车垂泪还入门。
父母愍我曾富贵，嫁与西舍金王孙。
念此翻覆复何道，百年盛衰谁能保。
忆昨尚如春日花，悲今已作秋时草。
少年去去莫停鞭，人生万事由上天。
非我今日独如此，古今歇薄皆共然。','',''),('quantangshi-06279','川上女','崔顥','quantangshi','','卷7','川上女，晚妆鲜。
日落青渚试轻檝，汀长花满正回船。
暮来浪起风转紧，自言此去横塘近。
绿江无伴夜独行，独行心绪愁无尽。','',''),('quantangshi-06280','雁门胡人歌','崔顥','quantangshi','','卷7','高山代郡东接燕，雁门胡人家近边。
解放胡鹰逐塞鸟，能将代马猎秋田。
山头野火寒多烧，雨里孤峰湿作烟。
闻道辽西无鬬战，时时醉向酒家眠。','',''),('quantangshi-06281','代闺人答轻薄少年','崔顥','quantangshi','','卷7','妾家近隔凤凰池，粉壁纱窗杨柳垂。
本期汉代金吾壻，误嫁长安游侠儿。
儿家夫壻多轻薄，借客探丸重然诺。
平明挟弹入新丰，日晚挥鞭出长乐。
青丝白马冶游园，能使行人驻马看。
自矜陌上繁华盛，不念闺中花鸟阑。
花间陌上春将晚，走马鬬鸡犹未返。
三时出望无消息，一去那知行近远。
桃李花开覆井栏，朱楼落日卷帘看。
愁来欲奏相思曲，抱得秦筝不忍弹。','',''),('quantangshi-06282','七夕','崔顥','quantangshi','','卷7','长安城中月如练，家家此夜持针线。
仙裙玉佩空自知，天上人间不相见。
长信深阴夜转幽，瑶堦金阁数萤流。
班姬此夕愁无限，河汉三更看斗牛。','',''),('quantangshi-06283','长门怨','崔顥','quantangshi','','卷7','君王宠初歇，弃妾长门宫。
紫殿青苔满，高楼明月空。
夜愁生枕席，春意罢帘栊。
泣尽无人问，容华落镜中。','',''),('quantangshi-06284','王家少妇','崔顥','quantangshi','','卷7','十五嫁王昌，盈盈入画堂。
自矜年最少，复倚壻为郎。
舞爱前溪绿，歌怜子夜长。
闲来鬬百草，度日不成妆。','',''),('quantangshi-06285','岐王席观妓','崔顥','quantangshi','','卷7','二月春来半，宫中日渐长。
柳垂金屋暖，花发玉楼香。
拂匣先临镜，调笙更炙簧。
还将歌舞态，只拟奉君王。','',''),('quantangshi-06286','上巳','崔顥','quantangshi','','卷7','巳日帝城春，倾都祓禊晨。
停车须傍水，奏乐要惊尘。
弱柳障行骑，浮桥拥看人。
犹言日尚早，更向九龙津。','',''),('quantangshi-06287','赠梁州张都督','崔顥','quantangshi','','卷7','闻君为汉将，虏骑罢南侵。
出塞清沙漠，还家拜羽林。
风霜臣节苦，岁月主恩深。
为语西河使，知余报国心。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-06288','赠卢八象','崔顥','quantangshi','','卷7','客从巴水渡，传尔溯行舟。
是日风波霁，高堂雨半收。
青山满蜀道，绿水向荆州。
不作书相问，谁能慰别愁。','',''),('quantangshi-06289','题潼关楼','崔顥','quantangshi','','卷7','客行逢雨霁，歇马上津楼。
山势雄三辅，关门扼九州。
川从陕路去，河遶华阴流。
向晚登临处，风烟万里愁。','',''),('quantangshi-06290','题沈隐侯八咏楼','崔顥','quantangshi','','卷7','梁日东阳守，为楼望越中。
绿窗明月在，青史古人空。
江静闻山狖，川长数塞鸿。
登临白云晚，流恨此遗风。','',''),('quantangshi-06291','晚入汴水','崔顥','quantangshi','','卷7','昨晚南行楚，今朝北溯河。
客愁能几日，乡路渐无多。
晴景摇津树，春风起棹歌。
长淮亦已尽，宁复畏潮波。','',''),('quantangshi-06292','发锦沙村','崔顥','quantangshi','','卷7','北上途未半，南行岁已阑。
孤舟下建德，江水入新安。
海近山常雨，溪深地早寒。
行行泊不可，须及子陵滩。','',''),('quantangshi-06293','送单于裴都护赴西河','崔顥','quantangshi','','卷7','征马去翩翩，城秋月正圆。
单于莫近塞，都护欲临边。
汉驿通烟火，胡沙乏井泉。
功成须献捷，未必去经年。','',''),('quantangshi-06294','黄鹤楼','崔顥','quantangshi','','卷7','昔人已乘白云去，此地空余黄鹤楼。
黄鹤一去不复返，白云千载空悠悠。
晴川历历汉阳树，春草萋萋鹦鹉洲。
日暮乡关何处是，烟波江上使人愁。','',''),('quantangshi-06295','行经华阴','崔顥','quantangshi','','卷7','岧嶤太华俯咸京，天外三峰削不成。
武帝祠前云欲散，仙人掌上雨初晴。
河山北枕秦关险，驿树西连汉畤平。
借问路傍名利客，无如此处学长生。','',''),('quantangshi-06296','相逢行','崔顥','quantangshi','','卷7','妾年初二八，家住洛桥头。
玉户临驰道，朱门近御沟。
使君何假问，夫壻大长秋。
女弟新承宠，诸兄近拜侯。
春生百子殿，花发五城楼。
出入千门里，年年乐未休。','',''),('quantangshi-06297','辽西作','崔顥','quantangshi','','卷7','燕郊芳岁晚，残雪冻边城。
四月青草合，辽阳春水生。
胡人正牧马，汉将日征兵。
露重宝刀湿，沙虚金鼓鸣。
寒衣着已尽，春服与谁成。
寄语洛阳使，为传边塞情。','',''),('quantangshi-06298','奉和许给事夜直简诸公','崔顥','quantangshi','','卷7','西掖黄枢近，东曹紫禁连。
地因才子拜，人用省郎迁。
夜直千门静，河明万象悬。
建章宵漏急，阊阖晓钟传。
宠列貂蝉位，恩深侍从年。
九重初起草，五夜即成篇。
顾己无官次，循涯但自怜。
远陪兰署作，空此仰神仙。','',''),('quantangshi-06299','舟行入剡','崔顥','quantangshi','','卷7','鸣棹下东阳，回舟入剡乡。
青山行不尽，绿水去何长。
地气秋仍湿，江风晚渐凉。
山梅犹作雨，溪橘未知霜。
谢客文逾盛，林公未可忘。
多惭越中好，流恨阅时芳。','',''),('quantangshi-06300','澄水如鉴','崔顥','quantangshi','','卷7','圣贤将立喻，上善贮情深。
洁白依全德，澄清有片心。
浇浮知不挠，滥浊固难侵。
方寸悬高鉴，生涯讵陆沈。
对泉能自诫，如镜静相临。
廉慎传家政，流芳合古今。','',''),('quantangshi-06301','长干曲四首 一','崔顥','quantangshi','','卷7','君家何处住？妾住在横塘。
停船暂借问，或恐是同乡。','',''),('quantangshi-06302','长干曲四首 二','崔顥','quantangshi','','卷7','家临九江水，来去九江侧。
同是长干人，自小不相识。','',''),('quantangshi-06303','长干曲四首 三','崔顥','quantangshi','','卷7','下渚多风浪，莲舟渐觉稀。
那能不相待，独自逆潮归。','',''),('quantangshi-06304','长干曲四首 四','崔顥','quantangshi','','卷7','三江潮水急，五湖风浪涌。
由来花性轻，莫畏莲舟重。','',''),('quantangshi-06305','维扬送友还苏州','崔顥','quantangshi','','卷7','长安南下几程途，得到邗沟吊绿芜。
渚畔鲈鱼舟上钓，羡君归老向东吴。','',''),('quantangshi-06306','古意二首 一','祖詠','quantangshi','','卷7','夫差日淫放，举国求妃嫔。
自谓得王宠，代间无美人。
碧罗象天阁，坐辇乘芳春。
宫女数千骑，常游江水滨。
年深玉颜老，时薄花妆新。
拭泪下金殿，娇多不顾身。
生前妬歌舞，死后同灰尘。
冢墓令人哀，哀于铜雀台。','',''),('quantangshi-06307','古意二首 二','祖詠','quantangshi','','卷7','楚王竟何去，独自留巫山。
偏使世人见，迢迢江汉间。
驻舟春溪里，誓愿拜灵颜。
梦寐覩神女，金沙鸣佩环。
闲艳绝世姿，令人气力微。
含笑默不语，化作朝云飞。','',''),('quantangshi-06308','渡淮河寄平一','祖詠','quantangshi','','卷7','天色混波涛，岸阴匝村墅。
微微汉祖庙，隐隐江陵渚。
云树森已重，时明郁相拒。','',''),('quantangshi-06309','归汝坟山庄留别卢象','祖詠','quantangshi','','卷7','淹留岁将[晏]，久废南山期。
旧业不见弃，还山从此辞。
沤麻入南涧，刈麦向东菑。
对酒鸡黍熟，闭门风雪时。
非君一延首，谁慰遥相思。','',''),('quantangshi-06310','夕次圃田店','祖詠','quantangshi','','卷7','前路入郑郊，尚经百余里。
马烦时欲歇，客归程未已。
落日桑柘阴，遥村烟火起。
西还不遑宿，中夜渡泾水。','',''),('quantangshi-06311','田家即事','祖詠','quantangshi','','卷7','旧居东臯上，左右俯荒村。
樵路前傍岭，田家遥对门。
欢娱始披拂，惬意在郊原。
余霁荡川雾，新秋仍昼昏。
攀条憩林麓，引水开泉源。
稼穑岂云倦，桑麻今正繁。
方求静者赏，偶与潜夫论。
鸡黍何必具，吾心知道尊。','',''),('quantangshi-06312','扈从御宿池','祖詠','quantangshi','','卷7','君王既巡狩，辇道入秦京。
远树低枪垒，孤峯入幔城。
寒疎清禁漏，夜警羽林兵。
谁念迷方客，长怀魏阙情。','',''),('quantangshi-06313','赠苗发员外','祖詠','quantangshi','','卷7','宿雨朝来歇，空山天气清。
盘云双鹤下，隔水一蝉鸣。
古道黄花落，平芜赤烧生。
茂陵虽有病，犹得伴君行。','',''),('quantangshi-06314','答王维留宿','祖詠','quantangshi','','卷7','四年不相见，相见复何为。
握手言未毕，却令伤别离。
升堂还驻马，酌醴便呼儿。
语嘿自相对，安用傍人知。','',''),('quantangshi-06315','长乐驿留别卢象裴总','祖詠','quantangshi','','卷7','朝来已握手，宿别更伤心。
灞水行人渡，商山驿路深。
故情君且足，谪宦我难任。
直道皆如此，谁能泪满襟。','',''),('quantangshi-06316','送刘高邮棁使入都','祖詠','quantangshi','','卷7','常闻积归思，昨夜又兼秋。
乡路京华远，王程江水流。
吴歌喧两岸，楚客醉孤舟。
渐觉潮初上，凄然多暮愁。','',''),('quantangshi-06317','宴吴王宅','祖詠','quantangshi','','卷7','吴王承国宠，列第禁城东。
连夜征词客，当春试舞童。
砌分池水岸，牕度竹林风。
更待西园月，金尊乐未终。','',''),('quantangshi-06318','观华岳','祖詠','quantangshi','','卷7','西入秦关口，南瞻驿路连。
彩云生阙下，松树到祠边。
作镇当官道，雄都俯大川。
莲峯径上处，彷佛有神仙。','',''),('quantangshi-06319','泗上冯使君南楼作','祖詠','quantangshi','','卷7','井邑连淮泗，南楼向晚过。
望滩沙鹭起，寻岸浴童歌。
近海云偏出，兼秋雨更多。
明晨拟回棹，乡思恨风波。','',''),('quantangshi-06320','苏氏别业','祖詠','quantangshi','','卷7','别业居幽处，到来生隐心。
南山当户牖，沣水映园林。
屋覆经冬雪，庭昏未夕阴。
寥寥人境外，闲坐听春禽。','',''),('quantangshi-06321','汝坟别业','祖詠','quantangshi','','卷7','失路农为业，移家到汝坟。
独愁常废卷，多病久离羣。
鸟雀垂窻柳，虹霓出涧云。
山中无外事，樵唱有时闻。','',''),('quantangshi-06322','陆浑水亭','祖詠','quantangshi','','卷7','昼眺伊川曲，岩间霁色明。
浅沙平有路，流水漫无声。
浴鸟沿波聚，潜鱼触钓惊。
更怜春岸绿，幽意满前楹。','',''),('quantangshi-06323','过郑曲','祖詠','quantangshi','','卷7','路向荣川谷，晴来望尽通。
细烟生水上，圆月在舟中。
岸势迷行客，秋声乱草虫。
旅怀劳自慰，淅淅有凉风。','',''),('quantangshi-06324','宿陈留李少府揆厅','祖詠','quantangshi','','卷7','相知有叔卿，讼简夜弥清。
旅泊倦愁卧，堂空闻曙更。
风帘摇烛影，秋雨带虫声。
归思那堪说，悠悠限洛城。','',''),('quantangshi-06325','题韩少府水亭','祖詠','quantangshi','','卷7','梅福幽栖处，佳期不忘还。
鸟吟当户竹，花绕傍池山。
水气侵阶冷，松阴覆座闲。
宁知武陵趣，宛在市朝间。','',''),('quantangshi-06326','题远公经台','祖詠','quantangshi','','卷7','兰若无人到，真僧出复稀。
苔侵行道席，云湿坐禅衣。
涧鼠缘香案，山蝉噪竹扉。
世间长不见，宁止暂忘归。','',''),('quantangshi-06327','中峯居喜见苗发','祖詠','quantangshi','','卷7','自得中峰住，深林亦闭关。
经秋无客到，入夜有僧还。
暗涧泉声小，荒冈树影闲。
高窻不可望，星月满空山。','',''),('quantangshi-06328','江南旅情','祖詠','quantangshi','','卷7','楚山不可极，归路但萧条。
海色晴看雨，江声夜听潮。
劒留南斗近，书寄北风遥。
为报空潭橘，无媒寄洛桥。','',''),('quantangshi-06329','泊扬子津','祖詠','quantangshi','','卷7','才入维扬郡，乡关此路遥。
林藏初过雨，风退欲归潮。
江火明沙岸，云帆碍浦桥。
客衣今日薄，寒气近来饶。','',''),('quantangshi-06330','晚泊金陵水亭','祖詠','quantangshi','','卷7','江亭当废国，秋景倍萧骚。
夕照明残垒，寒潮涨古濠。
就田看鹤大，隔水见僧高。
无限前朝事，醒吟易觉劳。','',''),('quantangshi-06331','七夕','祖詠','quantangshi','','卷7','闺女求天女，更阑意未阑。
玉庭开粉席，罗袖捧金盘。
向月穿针易，临风整线难。
不知谁得巧，明旦试相看。','',''),('quantangshi-06332','望蓟门','祖詠','quantangshi','','卷7','燕台一望客心惊，箫鼓喧喧汉将营。
万里寒光生积雪，三边曙色动危旌。
沙场烽火连胡月，海畔云山拥蓟城。
少小虽非投笔吏，论功还欲请长缨。','',''),('quantangshi-06333','家园夜坐寄郭微','祖詠','quantangshi','','卷7','前堦微雨歇，开户散窥林。
月出夜方浅，水凉池更深。
余风生竹树，清露薄衣襟。
遇物遂遥叹，怀人滋远心。
依稀成梦想，影响绝徽音。
谁念穷居者，明时嗟陆沈。','',''),('quantangshi-06334','酬汴州李别驾赠','祖詠','quantangshi','','卷7','秋风多客思，行旅厌艰辛。
自洛非才子，游梁得主人。
文章参末议，荣贱岂同伦。
叹逝逢三演，怀贤忆四真。
情因恩旧好，契托死生亲。
所愧能投赠，清言益润身。','',''),('quantangshi-06335','清明宴司勋刘郎中别业','祖詠','quantangshi','','卷7','田家复近臣，行乐不违亲。
霁日园林好，清明烟火新。
以文长会友，唯德自成邻。
池照窻阴晚，杯香药味春。
檐前花覆地，竹外鸟窥人。
何必桃源里，深居作隐沦。','',''),('quantangshi-06336','汝坟秋同仙州王长史翰闻百舌鸟','祖詠','quantangshi','','卷7','秋天闻好鸟，惊起出帘帷。
却念殊方月，能鸣已后时。
迁乔诚可早，出谷此何迟。
顾影慙无对，怀羣空所思。
凄凉岁欲晚，萧索燕将辞。
留听未终曲，弥令心独悲。
高飞凭力致，巧啭任天姿。
返覆知而静，间关断若遗。
花繁上林路，霜落汝川湄。
且长凌风翮，乘春自有期。','',''),('quantangshi-06337','送丘为下第','祖詠','quantangshi','','卷7','沧江一身客，献赋空十年。
明主岂能好，今人谁举贤。
国门税征驾，旅食谋归旋。
皦日媚春水，绿苹香客船。
无媒既不达，予亦思归田。','',''),('quantangshi-06338','赠苗发员外','祖詠','quantangshi','','卷7','朱户敞高扉，青槐碍落晖。
八龙乘庆重，三虎递朝归。
坐竹人声绝，横琴鸟语稀。
花慙潘岳貌，年称老莱衣。
叶暗朱樱熟，丝长粉蝶飞。
应怜鲁儒贱，空与故山违。','',''),('quantangshi-06339','寄王长史','祖詠','quantangshi','','卷7','汝颍俱宿好，往来托层峦。
终日何寂寞，绕篱生蕙兰。','',''),('quantangshi-06340','别怨','祖詠','quantangshi','','卷7','送别到中流，秋船倚渡头。
相看尚不远，未可即回舟。','',''),('quantangshi-06341','终南望余雪','祖詠','quantangshi','','卷7','终南阴岭秀，积雪浮云端。
林表明霁色，城中增暮寒。','',''),('quantangshi-06342','句','祖詠','quantangshi','','卷7','不知叠嶂夜来雨，清晓石楠花乱流。','',''),('quantangshi-06343','湘夫人','李頎','quantangshi','','卷7','九嶷日已暮，三湘云复愁。
窅霭罗袂色，潺湲江水流。
佳期来北渚，捐佩在芳洲。','',''),('quantangshi-06344','塞下曲','李頎','quantangshi','','卷7','黄云雁门郡，日暮风沙里。
千骑黑貂裘，皆称羽林子。
金笳吹朔雪，铁马嘶云水。
帐下饮蒲萄，平生寸心是。','',''),('quantangshi-06345','古塞下曲','李頎','quantangshi','','卷7','行人朝走马，直指蓟城傍。
蓟城通漠北，万里别吾乡。
海上千烽火，沙中百战场。
军书发上郡，春色度河阳。
褭褭汉宫柳，青青胡地桑。
琵琶出塞曲，横笛断君肠。','',''),('quantangshi-06346','渔父歌','李頎','quantangshi','','卷7','白首何老人，蓑笠蔽其身。
避世长不仕，钓鱼清江滨。
浦沙明濯足，山月静垂纶。
寓宿湍与濑，行歌秋复春。
持竿湘岸竹，爇火芦洲薪。
绿水饭香稻，青荷包紫鳞。
于中还自乐，所欲全吾真。
而笑独醒者，临流多苦辛。','',''),('quantangshi-06347','东京寄万楚','李頎','quantangshi','','卷7','濩落久无用，隐身甘采薇。
仍闻薄宦者，还事田家衣。
颍水日夜流，故人相见稀。
春山不可望，黄鸟东南飞。
濯足岂长往，一樽聊可依。
了然潭上月，适我胷中机。
在昔同门友，如今出处非。
优游白虎殿，偃息青琐闱。
且有荐君表，当看携手归。
寄书不待面，兰茝空芳菲。','',''),('quantangshi-06348','寄焦炼师','李頎','quantangshi','','卷7','得道凡百岁，烧丹惟一身。
悠悠孤峰顶，日见三花春。
白鹤翠微里，黄精幽涧滨。
始知世上客，不及山中人。
仙境若在梦，朝云如可亲。
何由覩颜色，挥手谢风尘。','',''),('quantangshi-06349','望鸣臯山白云寄洛阳卢主簿','李頎','quantangshi','','卷7','饮马伊水中，白云鸣臯上。
氛氲山绝顶，行子时一望。
照日龙虎姿，攒空冰雪状。
嵡嵸殊未已，崚嶒忽相向。
皎皎横绿林，霏霏澹青嶂。
远映村更失，孤高鹤来傍。
胜气欣有逢，仙游且难访。
故人吏京剧，每事多闲放。
室画峨眉峯，心格洞庭浪。
惜哉清兴里，不见予所尚。','',''),('quantangshi-06350','寄万齐融','李頎','quantangshi','','卷7','名高不择仕，委世随虚舟。
小邑常叹屈，故乡行可游。
青枫半村户，香稻盈田畴。
为政日清净，何人同海鸥。
摇巾北林夕，把菊东山秋。
对酒池云满，向家湖水流。
岸阴止鸣鹄，山色映潜虬。
靡靡俗中理，萧萧川上幽。
昔年至吴郡，常隐临江楼。
我有一书札，因之芳杜洲。','',''),('quantangshi-06351','赠张旭','李頎','quantangshi','','卷7','张公性嗜酒，豁达无所营。
皓首穷草隶，时称太湖精。
露顶据胡牀，长呌三五声。
兴来洒素壁，挥笔如流星。
下舍风萧条，寒草满户庭。
问家何所有，生事如浮萍。
左手持蟹螯，右手执丹经。
瞪目视霄汉，不知醉与醒。
诸宾且方坐，旭日临东城。
荷叶裹江鱼，白瓯贮香秔。
微禄心不屑，放神于八纮。
时人不识者，即是安期生。','',''),('quantangshi-06352','赠苏明府','李頎','quantangshi','','卷7','苏君年几许，状貌如玉童。
采药傍梁宋，共言随日翁。
常辞小县宰，一往东山东。
不复有家室，悠悠人世中。
子孙皆老死，相识悲转蓬。
发白还更黑，身轻行若风。
泛然无所系，心与孤云同。
出入虽一杖，安然知始终。
愿闻素女事，去采山花丛。
诱我为弟子，逍遥寻葛洪。','',''),('quantangshi-06353','登首阳山谒夷齐庙','李頎','quantangshi','','卷7','古人已不见，乔木竟谁过。
寂寞首阳山，白云空复多。
苍苔归地骨，皓首采薇歌。
毕命无怨色，成仁其若何。
我来入遗庙，时候微清和。
落日吊山鬼，回风吹女萝。
石崖向西豁，引领望黄河。
千里一飞鸟，孤光东逝波。
驱车层城路，惆怅此岩阿。','',''),('quantangshi-06354','谒张果先生','李頎','quantangshi','','卷7','先生谷神者，甲子焉能计。
自说轩辕师，于今几千岁。
寓游城郭里，浪迹希夷际。
应物云无心，逢时舟不系。
餐霞断火粒，野服兼荷制。
白雪净肌肤，青松养身世。
韬精殊豹隐，炼骨同蝉蜕。
忽去不知谁，偶来宁有契。
二仪齐寿考，六合随休憩。
彭耼犹婴孩，松期且微细。
尝闻穆天子，更忆汉皇帝。
亲屈万乘尊，将穷四海裔。
车徒徧草木，锦帛招谈说。
八骏空往还，三山转亏蔽。
吾君感至德，玄老欣来诣。
受箓金殿开，清斋玉堂闭。
笙歌迎拜首，羽帐崇严衞。
禁柳垂香炉，宫花拂仙袂。
祈年宝祚广，致福苍生惠。
何必待龙髯，鼎成方取济。','',''),('quantangshi-06355','光上座廊下众山五韵','李頎','quantangshi','','卷7','名岳在庑下，吾师居一牀。
每闻楞伽经，只对清翠光。
百谷聚雪色，莓苔侵屋梁。
气盘古壁转，势引幽堦长。
愿游薜叶下，日见金炉香。','',''),('quantangshi-06356','九月九日刘十八东堂集','李頎','quantangshi','','卷7','风俗尚九日，此情安可忘。
菊花辟恶酒，汤饼茱萸香。
云入授衣假，风吹闲宇凉。
主人尽欢意，林景昼微茫。
清切晚砧动，东西归鸟行。
淹留怅为别，日醉秋云光。','',''),('quantangshi-06357','宋少府东溪泛舟','李頎','quantangshi','','卷7','登岸还入舟，水禽惊笑语。
晚叶低众色，湿云带残暑。
落日乘醉归，溪流复几许。','',''),('quantangshi-06358','与诸公游济渎泛舟','李頎','quantangshi','','卷7','济水出王屋，其源来不穷。
洑泉数眼沸，平地流清通。
皇帝崇祀典，诏书视三公。
分官祷灵庙，奠璧沈河宫。
神应每如答，松篁气葱茏。
苍螭送飞雨，赤鲤喷回风。
洒酒布瑶席，吹箫下玉童。
玄冥掌阴事，祝史告年丰。
百谷趋潭底，三光悬镜中。
浅深露沙石，苹藻生虚空。
晚景临泛美，亭臯轻霭红。
晴山傍舟楫，白鹭惊丝桐。
我本家颍北，开门见维嵩。
焉知松峰外，又有天坛东。
左手正接䍦，浩歌眄青穹。
夷犹傲清吏，偃仰狎渔翁。
对此川上闲，非君谁与同。
霜凝远村渚，月静蒹葭丛。
兹境信难遇，为欢殊未终。
淹留怅言别，烟屿夕微蒙。','',''),('quantangshi-06359','送綦毋三谒房给事','李頎','quantangshi','','卷7','夫子大名下，家无钟石储。
惜哉湖海上，曾校蓬莱书。
外物非本意，此生空澹如。
所思但乘兴，远适唯单车。
高道时坎坷，故交愿吹嘘。
徒言青琐闼，不爱承明庐。
百里人户满，片言争讼疎。
手持莲花经，目送飞鸟余。
晚景南路别，炎云中伏初。
此行傥不遂，归食芦洲鱼。','',''),('quantangshi-06360','送刘四','李頎','quantangshi','','卷7','爱君少岐嶷，高视白云乡。
九岁能属文，谒帝游明光。
奉诏赤墀下，拜为童子郎。
尔来屡迁易，三度尉洛阳。
洛阳十二门，官寺郁相望。
青槐罗四面，渌水贯中央。
听讼破秋毫，应物利干将。
辞满如脱屣，立言无否臧。
岁暮风雪暗，秦中川路长。
行人饮腊酒，立马带晨霜。
生事岂须问，故园寒草荒。
从今署右职，莫笑在农桑。','',''),('quantangshi-06361','送裴腾','李頎','quantangshi','','卷7','养德为众许，森然此丈夫。
放情白云外，爽气连虬须。
衡镜合知子，公心谁谓无。
还令不得意，单马遂长驱。
桑野蚕忙时，怜君久踟蹰。
新晴荷卷叶，孟夏雉将雏。
令弟为县尹，高城汾水隅。
相将簿领闲，倚望恒峰孤。
香露团百草，紫梨分万株。
归来授衣假，莫使故园芜。','',''),('quantangshi-06362','送司农崔丞','李頎','quantangshi','','卷7','黄鹂鸣官寺，香草色未已。
同时皆省郎，而我独留此。
维监太仓粟，常对府小史。
清阴罗广庭，政事如流水。
奉使往长安，今承朝野欢。
宰臣应记识，明主必迁官。
塞外貔将虎，池中鸳与鸾。
词人洞箫赋，公子鵕䴊冠。
邑里春方晚，昆明花欲阑。
行行取高位，当使路傍看。','',''),('quantangshi-06363','送崔侍御赴京','李頎','quantangshi','','卷7','绿槐荫长路，骏马垂青丝。
柱史谒承明，翩翩将有期。
千官大朝日，奏事临赤墀。
肃肃仪仗里，风生鹰隼姿。
一从登甲科，三拜皆宪司。
按俗又如此，为郎何太迟。
送君暮春月，花落城南陲。
惜别醉芳草，前山劳梦思。','',''),('quantangshi-06364','春送从叔游襄阳','李頎','quantangshi','','卷7','言别恨非一，弃置我宗英。
向用五经笥，今为千里行。
裹粮顾庭草，羸马诘朝鸣。
斗酒对寒食，杂花宜晚晴。
春衣采洲路，夜饮南阳城。
客梦岘山晓，渔歌江水清。
楚俗少相知，远游难称情。
同人应馆谷，刺史在郊迎。
只合侍丹扆，翻令辞上京。
时方春欲暮，叹息向流莺。','',''),('quantangshi-06365','赠别高三十五','李頎','quantangshi','','卷7','五十无产业，心轻百万资。
屠酤亦与羣，不问君是谁。
饮酒或垂钓，狂歌兼咏诗。
焉知汉高士，莫识越鸱夷。
寄迹栖霞山，蓬头睢水湄。
忽然辟命下，众谓趋丹墀。
沐浴着赐衣，西来马行迟。
能令相府重，且有函关期。
僶俛从寸禄，旧游梁宋时。
皤皤邑中叟，相候鬓如丝。
官舍柳林静，河梁杏叶滋。
摘芳云景[晏]，把手秋蝉悲。
小县情未惬，折腰君莫辞。
吾观主人意，不久召京师。','',''),('quantangshi-06366','崔五宅送刘跂入京','李頎','quantangshi','','卷7','行人惜寸景，系马暂留欢。
昨日辞小沛，何时到长安。
乡中饮酒礼，客里行路难。
清洛云鸿度，故关风日寒。
维将道可乐，不念身无官。
生事东山远，田园芳岁阑。
东归余谢病，西去子加餐。
宋伯非徒尔，明时正可干。
躬耕守贫贱，失计在林端。
宿昔奉颜色，慙无双玉盘。','',''),('quantangshi-06367','送马录事赴永阳','李頎','quantangshi','','卷7','子为郡从事，主印清淮边。
谈笑一州里，从容羣吏先。
手持三尺令，遣决如流泉。
太守既相许，诸公谁不然。
孤城连海树，万室带山烟。
春日溪湖净，芳洲葭菼连。
炊秔蟹螯熟，下筯鲈鱼鲜。
野鹤宿檐际，楚云飞面前。
听歌送离曲，且驻木兰船。
赠尔八行字，当闻佳政传。','',''),('quantangshi-06368','临别送张諲入蜀','李頎','quantangshi','','卷7','出门便为客，惘然悲徒御。
四海维一身，茫茫欲何去？
经山复历水，百恨将千虑。
劒阁望梁州，是君断肠处。
孤云伤客心，落日感君深。
梦里蒹葭渚，天边橘柚林。
蜀江流不测，蜀路险难寻。
木有相思号，猿多愁苦音。
莫向愚山隐，愚山地非近。
故乡可归来，眼见芳菲尽。','',''),('quantangshi-06369','送王昌龄','李頎','quantangshi','','卷7','漕水东去远，送君多暮情。
淹留野寺出，向背孤山明。
前望数千里，中无蒲稗生。
夕阳满舟檝，但爱微波清。
举酒林月上，解衣沙鸟鸣。
夜来莲花界，梦里金陵城。
叹息此离别，悠悠江海行。','',''),('quantangshi-06370','留别王卢二拾遗','李頎','quantangshi','','卷7','此别不可道，此心当报谁。
春风灞水上，饮马桃花时。
误作好文士，只令游宦迟。
留书下朝客，我有故山期。','',''),('quantangshi-06371','赠别穆元林','李頎','quantangshi','','卷7','贰职久辞满，藏名三十年。
丹墀策频献，白首官不迁。
明主日征士，吏曹何忽贤。
空怀济世业，欲棹沧浪船。
举酒洛门外，送君春海边。
彼乡有令弟，小邑试烹鲜。
转浦云壑媚，涉江花岛连。
绿芳暗楚水，白鸟飞吴烟。
赠赆亦奚贵，流乱期早旋。
金闺会通籍，生事岂徒然。','',''),('quantangshi-06372','不调归东川别业','李頎','quantangshi','','卷7','寸禄言可取，托身将见遗。
慙无匹夫志，悔与名山辞。
绂冕谢知己，林园多后时。
葛巾方濯足，蔬食但垂帷。
十室对河岸，渔樵祗在兹。
青郊香杜若，白水映茅茨。
昼景彻云树，夕阴澄古逵。
渚花独开晚，田鹤静飞迟。
且复乐生事，前贤为我师。
清歌聊鼓楫，永日望佳期。','',''),('quantangshi-06373','晚归东园','李頎','quantangshi','','卷7','出郭喜见山，东行亦未远。
夕阳带归路，霭霭秋稼晚。
樵者乘霁归，野夫及星饭。
请谢朱轮客，垂竿不复返。','',''),('quantangshi-06374','龙门西峰晓望刘十八不至','李頎','quantangshi','','卷7','春台临永路，跂足望行子。
片片云触峯，离离鸟渡水。
丛林远山上，霁景杂花里。
不见携手人，下山采绿芷。','',''),('quantangshi-06375','裴尹东溪别业','李頎','quantangshi','','卷7','公才廊庙器，官亚河南守。
别墅临都门，惊湍激前后。
旧交与羣从，十日一携手。
幅巾望寒山，长啸对高柳。
清欢信可尚，散吏亦何有。
岸雪清城阴，水光远林首。
闲观野人筏，或饮川上酒。
幽云澹徘徊，白鹭飞左右。
庭竹垂卧内，村烟隔南阜。
始知物外情，簪绂同刍狗。','',''),('quantangshi-06376','无尽上人东林禅居','李頎','quantangshi','','卷7','草堂每多暇，时谒山僧门。
所对但羣木，终朝无一言。
我心爱流水，此地临清源。
含吐山上日，蔽亏松外村。
孤峯隔身世，百衲老寒暄。
禅户积朝雪，花龛来暮猿。
顾余守耕稼，十载隐田园。
萝筱慰舂汲，岩潭恣讨论。
泄云岂知限，至道莫探元。
且愿启关锁，于焉微尚存。','',''),('quantangshi-06377','题綦毋校书别业','李頎','quantangshi','','卷7','常称挂冠吏，昨日归沧洲。
行客暮帆远，主人庭树秋。
岂伊问天命，但欲为山游。
万物我何有，白云空自幽。
萧条江海上，日夕见丹丘。
生事非渔钓，赏心随去留。
惜哉旷微月，欲济无轻舟。
倏忽令人老，相思河水流。','',''),('quantangshi-06378','题卢道士房','李頎','quantangshi','','卷7','秋砧响落木，共坐茅君家。
惟见两童子，林前汲井华。
空坛静白日，神鼎飞丹砂。
麈尾拂霜草，金铃摇霁霞。
上章人世隔，看[弈]桐阴斜。
稽首问仙要，黄精堪饵花。','',''),('quantangshi-06379','题神力师院','李頎','quantangshi','','卷7','大师神杰貌，五岳森禅房。
坚持日月珠，豁见沧江长。
随病拔诸苦，致身如法王。
阶庭药草徧，饭食天花香。
树色向高阁，昼阴横半墙。
每闻第一义，心净琉璃光。','',''),('quantangshi-06380','题僧房双桐','李頎','quantangshi','','卷7','青桐双拂日，傍带凌霄花。
绿叶传僧磬，清阴润井华。
谁能事音律，焦尾蔡邕家。','',''),('quantangshi-06381','粲公院各赋一物得初荷','李頎','quantangshi','','卷7','微风和众草，大叶长圆阴。
晴露珠共合，夕阳花映深。
从来不着水，清净本因心。','',''),('quantangshi-06382','李兵曹壁画山水各赋得桂水帆','李頎','quantangshi','','卷7','片帆浮桂水，落日天涯时。
飞鸟看共度，闲云相与迟。
长波无晓夜，泛泛欲何之。','',''),('quantangshi-06383','题合欢','李頎','quantangshi','','卷7','开花复卷叶，艳眼又惊心。
蝶遶西枝露，风披东干阴。
黄衫漂细蘂，时拂女郎砧。','',''),('quantangshi-06384','古从军行','李頎','quantangshi','','卷7','白日登山望烽火，黄昏饮马傍交河。
行人刁斗风沙暗，公主琵琶幽怨多。
野云万里无城郭，雨雪纷纷连大漠。
胡雁哀鸣夜夜飞，胡儿眼泪双双落。
闻道玉门犹被遮，应将性命逐轻车。
年年战骨埋荒外，空见蒲桃入汉家。','',''),('quantangshi-06385','行路难','李頎','quantangshi','','卷7','汉家名臣杨德祖，四代五公享茅土。
父子兄弟绾银黄，跃马鸣珂朝建章。
火浣单衣绣方领，茱萸锦带玉盘囊。
宾客填街复满座，片言出口生辉光。
世人逐势争奔走，沥胆堕肝惟恐后。
当时一顾登青云，自谓生死长随君。
一朝谢病还乡里，穷巷苍苔绝知己。
秋风落叶闭重门，昨日论交竟谁是。
薄俗嗟嗟难重陈，深山麋鹿可为邻。
鲁连所以蹈东海，古往今来称达人。','',''),('quantangshi-06386','缓歌行','李頎','quantangshi','','卷7','小来托身攀贵游，倾财破产无所忧。
暮拟经过石渠署，朝将出入铜龙楼。
结交杜陵轻薄子，谓言可生复可死。
一沈一浮会有时，弃我翻然如脱屣。
男儿立身须自强，十年闭户颍水阳。
业就功成见明主，击钟鼎食坐华堂。
二八蛾眉梳堕马，美酒清歌曲房下。
文昌宫中赐锦衣，长安陌上退朝归。
五陵宾从莫敢视，三省官僚揖者稀。
早知今日读书是，悔作从前任侠非。','',''),('quantangshi-06387','琴歌','李頎','quantangshi','','卷7','主人有酒欢今夕，请奏鸣琴广陵客。
月照城头乌半飞，霜凄万树风入衣。
铜炉华烛烛增辉，初弹渌水后楚妃。
一声已动物皆静，四座无言星欲稀。
清淮奉使千余里，敢告云山从此始。','',''),('quantangshi-06388','放歌行答从弟墨卿','李頎','quantangshi','','卷7','小来好文耻学武，世上功名不解取。
虽沾寸禄已后时，徒欲出身事明主。
柏梁赋诗不及宴，长楸走马谁相数。
歛迹俛眉心自甘，高歌击节声半苦。
由是蹉跎一老夫，养鸡牧豕东城隅。
空歌汉代萧相国，肯事霍家冯子都。
徒尔当年声籍籍，滥作词林两京客。
故人斗酒安陵桥，黄鸟春风洛阳陌。
吾家令弟才不羁，五言破的人共推。
兴来逸气若涛涌，千里长江归海时。
别离短景何萧索，佳句相思能间作。
举头遥望鲁阳山，木叶纷纷向人落。','',''),('quantangshi-06389','王母歌','李頎','quantangshi','','卷7','武皇斋戒承华殿，端拱须臾王母见。
霓旌照耀麒麟车，羽盖淋漓孔雀扇。
手指交梨遣帝食，可以长生临宇县。
头上复戴九星冠，总领玉童坐南面。
欲闻要言今告汝，帝乃焚香请此语。
若能炼魄去三尸，后当见我天皇所。
顾谓侍女董双成，酒阑可奏云和笙。
红霞白日俨不动，七龙五凤纷相迎。
惜哉志骄神不悦，叹息马蹄与车辙。
复道歌钟杳将暮，深宫桃李花成雪。
为看青玉五枝灯，蟠螭吐火光欲绝。','',''),('quantangshi-06390','鲛人歌','李頎','quantangshi','','卷7','鲛人潜织水底居，侧身上下随游鱼。
轻绡文彩不可识，夜夜澄波连月色。
有时寄宿来城市，海岛青冥无极已。
泣珠报恩君莫辞，今年相见明年期。
始知万族无不有，百尺深泉架户牖。
鸟没空山谁复望，一望云涛堪白首。','',''),('quantangshi-06391','夏宴张兵曹东堂','李頎','quantangshi','','卷7','重林华屋堪避暑，况乃烹鲜会佳客。
主人三十朝大夫，满座森然见矛戟。
北窓卧簟连心花，竹里蝉鸣西日斜。
羽扇摇风却珠汗，玉盆贮水割甘瓜。
云峰峨峨自冰雪，坐对芳樽不知热。
醉来但挂葛巾眠，莫道明朝有离别。','',''),('quantangshi-06392','同张员外諲酬答之作','李頎','quantangshi','','卷7','洛中高士日沈冥，手自灌园方带经。
王湛牀头见周易，长康传里好丹青。
鹖冠葛屦无名位，博[弈]赋诗聊遣意。
清言只到衞家儿，用笔能夸钟太尉。
东篱二月种兰荪，穷巷人稀鸟雀喧。
闻道郎官问生事，肯令鬓发老柴门。','',''),('quantangshi-06393','欲之新乡答崔颢綦毋潜','李頎','quantangshi','','卷7','数年作吏家屡空，谁道黑头成老翁。
男儿在世无产业，行子出门如转蓬。
吾属交欢此何夕，南家捣衣动归客。
铜炉将炙相欢饮，星宿纵横露华白。
寒风卷叶度滹沱，飞雪布地悲峨峨。
孤城日落见栖鸟，马上时闻渔者歌。
明朝东路把君手，腊日辞君期岁首。
自知寂寞无去思，敢望县人致牛酒。','',''),('quantangshi-06394','答高三十五留别便呈于十一','李頎','quantangshi','','卷7','累荐贤良皆不就，家近陈留访耆旧。
韩康虽复在人间，王霸终思隐岩窦。
清冷池水灌园蔬，万物沧江心澹如。
妻子欢同五株柳，云山老对一牀书。
昨日公车见三事，明君赐衣遣为吏。
怀章不使郡邸惊，待诏初从阙庭至。
散诞由来自不羁，低头授职尔何为。
故园壁挂乌纱帽，官舍尘生白接䍦。
寄书寂寂于陵子，蓬蒿没身胡不仕。
藜羹被褐环堵中，岁晚将贻故人耻。','',''),('quantangshi-06395','送康洽入京进乐府歌','李頎','quantangshi','','卷7','识子十年何不遇，只爱欢游两京路。
朝吟左氏娇女篇，夜诵相如美人赋。
长安春物旧相宜，小苑蒲萄花满枝。
柳色偏浓九华殿，莺声醉杀五陵儿。
曳裾此日从何所，中贵由来尽相许。
白裌春衫仙吏赠，乌皮隐几台郎与。
新诗乐府唱堪愁，御妓应传鳷鹊楼。
西上虽因长公主，终须一见曲陵侯。','',''),('quantangshi-06396','送刘十','李頎','quantangshi','','卷7','三十不官亦不娶，时人焉识道高下。
房中唯有老氏经，枥上空余少游马。
往来嵩华与函秦，放歌一曲前山春。
西林独鹤引闲步，南涧飞泉清角巾。
前年上书不得意，归卧东窓兀然醉。
诸兄相继掌青史，第五之名齐骠骑。
烹葵摘果告我行，落日夏云纵复横。
闻道谢安掩口笑，知君不免为苍生。','',''),('quantangshi-06397','送王道士还山','李頎','quantangshi','','卷7','嵩阳道士餐柏实，居处三花对石室。
心穷伏火阳精丹，口诵淮王万毕术。
自言神诀不可求，我师闻之玄圃游。
出入彤庭佩金印，承恩赫赫如王侯。
双峰树下曾受业，应传肘后长生法。
吾闻仙地多后身，安知不是具茨人。
玉膏清泠瀑泉水，白云溪中日方此。
后今不见数十年，鬓发颜容只如是。
先生舍我欲何归，竹杖黄裳登翠微。
当有岩前白蝙蝠，迎君日暮双来飞。','',''),('quantangshi-06398','别梁鍠','李頎','quantangshi','','卷7','梁生倜傥心不羁，途穷气盖长安儿。
回头转眄似雕鹗，有志飞鸣人岂知。
虽云四十无禄位，曾与大军掌书记。
抗辞请刃诛部曲，作色论兵犯二帅。
一言不合龙頟侯，击劒拂衣从此弃。
朝朝饮酒黄公垆，脱帽露顶争叫呼。
庭中犊鼻昔尝挂，怀里琅玕今在无。
时人见子多落魄，共笑狂歌非远图。
忽然遣跃紫骝马，还是昂藏一丈夫。
洛阳城头晓霜白，层冰峨峨满川泽。
但闻行路吟新诗，不叹举家无担石。
莫言贫贱长可欺，覆篑成山当有时。
莫言富归长可托，木槿朝看暮还落。
不见古时塞上翁，倚伏由来任天作。
去去沧波勿复陈，五湖三江愁杀人。','',''),('quantangshi-06399','送从弟游江淮兼谒鄱阳刘太守','李頎','quantangshi','','卷7','都门柳色朝朝新，念尔今为江上人。
穆陵关带清风远，彭蠡湖连芳草春。
泊舟借问西林寺，晓听猿声在山翠。
浔阳北望鸿雁回，湓水东流客心醉。
须知圣代举贤良，不使遗才滞一方。
应见鄱阳虎符守，思归共指白云乡。','',''),('quantangshi-06400','双笋歌送李回兼呈刘四','李頎','quantangshi','','卷7','并抽新笋色渐绿，迥出空林双碧玉。
春风解箨雨润根，一枝半叶清露痕。
为君当面拂云日，孤生四远何足论。
再三抱此怅为别，嵩洛故人与之说。','',''),('quantangshi-06401','送刘四赴夏县','李頎','quantangshi','','卷7','九霄特立红鸾姿，万仞孤生玉树枝。
刘侯致身能若此，天骨自然多叹美。
声名播扬二十年，足下长途几千里。
举世皆亲丞相阁，我心独爱伊川水。
脱略势利犹埃尘，啸傲时人而已矣。
新诗数岁即文雄，上书昔召蓬莱宫。
明主拜官麒麟阁，光车骏马看玉童。
高人往来庐山远，隐士往来张长公。
扶南甘蔗甜如蜜，杂以荔枝龙州橘。
赤县繁词满剧曹，白云孤峯晖永日。
朝持手板望飞鸟，暮诵楞伽对空室。
一朝出宰汾河间，明府下车人吏闲。
端坐讼庭更无事，开门咫尺巫咸山。
男耕女织蒙惠化，麦熟雉鸣长秋稼。
明年九府议功时，五辟三征当在兹。
闻道桐乡有遗老，邑中还欲置生祠。','',''),('quantangshi-06402','少室雪晴送王宁','李頎','quantangshi','','卷7','少室众峯几峰别，一峰晴见一峰雪。
隔城半山连青松，素色峨峨千万重。
过景斜临不可道，白云欲尽难为容。
行人与我翫幽境，北风切切吹衣冷。
惜别浮桥驻马时，举头试望南山岭。','',''),('quantangshi-06403','送陈章甫','李頎','quantangshi','','卷7','四月南风大麦黄，枣花未落桐阴长。
青山朝别暮还见，嘶马出门思旧乡。
陈侯立身何坦荡，虬须虎眉仍大颡。
腹中贮书一万卷，不肯低头在草莽。
东门酤酒饮我曹，心轻万事皆鸿毛。
醉卧不知白日暮，有时空望孤云高。
长河浪头连天黑，津口停舟渡不得。
郑国游人未及家，洛阳行子空叹息。
闻道故林相识多，罢官昨日今如何。','',''),('quantangshi-06404','听安万善吹觱篥歌','李頎','quantangshi','','卷7','南山截竹为觱篥，此乐本自龟兹出。
流传汉地曲转奇，凉州胡人为我吹。
傍邻闻者多叹息，远客思乡皆泪垂。
世人解听不解赏，长飙风中自来往。
枯桑老柏寒飕飗，九雏鸣凤乱啾啾。
龙吟虎啸一时发，万籁百泉相与秋。
忽然更作渔阳掺，黄云萧条白日暗。
变调如闻杨柳春，上林繁花照眼新。
岁夜高堂列明烛，美酒一杯声一曲。','',''),('quantangshi-06405','魏仓曹东堂柽树','李頎','quantangshi','','卷7','爱君双柽一树奇，千叶齐生万叶垂。
长头拂石带烟雨，独立空山人莫知。
攒青蓄翠阴满屋，紫穗红英曾断目。
洛阳墨客游云间，若到麻源第三谷。','',''),('quantangshi-06406','照公院双橙','李頎','quantangshi','','卷7','种橙夹阶生得地，细叶隔帘见双翠。
抽条向长未及肩，泉水遶根日三四。
青青何必楚人家，带雨凝烟新着花。
永愿香炉洒甘露，夕阳时映东枝斜。','',''),('quantangshi-06407','爱敬寺古藤歌','李頎','quantangshi','','卷7','古藤池水盘树根，左攫右拏龙虎蹲。
横空直上相陵突，丰茸离纚若无骨。
风雷霹雳连黑枝，人言其下藏妖魑。
空庭落叶乍开合，十月苦寒常倒垂。
忆昨花飞满空殿，密叶吹香饭僧遍。
南阶双桐一百尺，相与年年老霜霰。','',''),('quantangshi-06408','崔五六图屏风各赋一物得乌孙佩刀','李頎','quantangshi','','卷7','乌孙腰间佩两刀，刃可吹毛锦为带。
握手枕宿穹庐室，马上割飞翳螉塞。
执之魍魉谁能前，气凛清风沙漠边。
磨用阴山一片玉，洗将胡地独流泉。
主人屏风写奇状，铁鞘金镮俨相向。
回头瞪目时一看，使予心在江湖上。','',''),('quantangshi-06409','古意','李頎','quantangshi','','卷7','男儿事长征，少小幽燕客。
赌胜马蹄下，由来轻七尺。
杀人莫敢前，须如猬毛磔。
黄云陇底白雪飞，未得报恩不能归。
辽东小妇年十五，惯弹琵琶解歌舞。
今为羗笛出塞声，使我三军泪如雨。','',''),('quantangshi-06410','采莲','李頎','quantangshi','','卷7','越溪女，越溪莲，齐菡萏，双婵娟。
嬉游向何处，采摘且同船。
浩唱发容与，清波生漪涟。
时逢岛屿泊，几伴鸯鸳眠。
襟袖既盈溢，馨香亦相传。
薄暮归去来，苎罗生碧烟。','',''),('quantangshi-06411','杂兴','李頎','quantangshi','','卷7','沈沈牛渚矶，旧说多灵怪。
行人夜秉生犀烛，洞照洪深辟滂湃。
乘车驾马往复旋，赤绂朱冠何伟然。
波惊海若潜幽石，龙抱胡髯卧黑泉。
水滨丈人曾有语，物或恶之当害汝。
武昌妖梦果为灾，百代英威埋鬼府。
青青兰艾本殊香，察见泉鱼固不祥。
济水自清河自浊，周公大圣接舆狂。
千年魑魅逢华表，九日茱萸作佩囊。
善恶死生齐一贯，祗应斗酒任苍苍。','',''),('quantangshi-06412','绝缨歌','李頎','quantangshi','','卷7','楚王宴客章华台，章华美人善歌舞。
玉颜艳艳空相向，满堂目成不得语。
红烛灭，芳酒阑，罗衣半醉春夜寒。
绝缨解带一为欢，君王赦过不之罪。
暗中珠翠鸣珊珊，宁爱贤，不爱色。
青娥买死谁能识，果却一军全社稷。','',''),('quantangshi-06413','郑樱桃歌','李頎','quantangshi','','卷7','石季龙，僭天禄，擅雄豪，美人姓郑名樱桃。
樱桃美颜香且泽，娥娥侍寝专宫掖。
后庭卷衣三万人，翠眉清镜不得亲。
宫军女骑一千匹，繁花照耀漳河春。
织成花映红纶巾，红旗掣曳卤簿新。
鸣鼙走马接飞鸟，铜驮瑟瑟随去尘。
凤阳重门如意馆，百尺金梯倚银汉。
自言富贵不可量，女为公主男为王。
赤花双簟珊瑚牀，盘龙斗帐琥珀光。
淫昏伪位神所恶，灭石者陵终不悟。
邺城苍苍白露微，世事翻覆黄云飞。','',''),('quantangshi-06414','送刘昱','李頎','quantangshi','','卷7','八月寒苇花，秋江浪头白。
北风吹五两，谁是浔阳客。
鸬鷀山头微雨晴，扬州郭里暮潮生。
行人夜宿金陵渚，试听沙边有雁声。','',''),('quantangshi-06415','送郝判官','李頎','quantangshi','','卷7','楚城木叶落，夏口青山遍。
鸿雁向南时，君乘使者传。
枫林带水驿，夜火明山县。
千里送行人，蔡州如眼见。
江连清汉东逶迤，遥望荆云相蔽亏。
应问襄阳旧风俗，为余骑马习家池。','',''),('quantangshi-06416','送刘方平','李頎','quantangshi','','卷7','绮纨游上国，多作少年行。
二十二词赋，惟君着美名。
童颜且白皙，佩德如瑶琼。
荀氏风流盛，胡家公子清。
有才不偶谁之过，肯即藏锋事高卧。
洛阳草色犹自春，游子东归喜拜亲。
漳水桥头值鸣雁，朝歌县北少行人。
别离斗酒心相许，落日青郊半微雨。
请君骑马望西陵，为我殷勤吊魏武。','',''),('quantangshi-06417','听董大弹胡笳声兼寄语弄房给事','李頎','quantangshi','','卷7','蔡女昔造胡笳声，一弹一十有八拍。
胡人落泪沾边草，汉使断肠对归客。
古戍苍苍烽火寒，大荒沈沈飞雪白。
先拂商弦后角羽，四郊秋叶惊摵摵。
董夫子，通神明，深山窃听来妖精。
言迟更速皆应手，将往复旋如有情。
空山百鸟散还合，万里浮云阴且晴。
嘶酸雏雁失羣夜，断绝胡儿恋母声。
川为净其波，鸟亦罢其鸣。
乌孙部落家乡远，逻娑沙尘哀怨生。
幽音变调忽飘洒，长风吹林雨堕瓦。
迸泉飒飒飞木末，野鹿呦呦走堂下。
长安城连东掖垣，凤凰池对青琐门。
高才脱略名与利，日夕望君抱琴至。','',''),('quantangshi-06418','弹棋歌','李頎','quantangshi','','卷7','崔侯善弹棋，巧妙尽于此。
蓝田美玉清如砥，白黑相分十二子。
联翩百中皆造微，魏文手巾不足比。
缘边度陇未可嘉，鸟跂星悬危复斜。
回飙转指速飞电，拂四取五旋风花。
坐中齐声称绝艺，仙人六博何能继。
一别常山道路遥，为余更作三五势。','',''),('quantangshi-06419','送山阴姚丞携妓之任兼寄苏少府','李頎','quantangshi','','卷7','东风香草路，南客心容与。
白皙吴王孙，青蛾柳家女。
都门数骑出，河口片帆举。
夜簟眠橘洲，春衫傍枫屿。
山阴政简甚从容，到罢惟求物外踪。
落日花边剡溪水，晴烟竹里会稽峰。
才子风流苏伯玉，同官晓暮应相逐。
加飡共爱鲈鱼肥，醒酒仍怜甘蔗熟。
知君练思本清新，季子如今得为邻。
他日知寻始宁墅，题诗早晚寄西人。','',''),('quantangshi-06420','塞下曲','李頎','quantangshi','','卷7','少年学骑射，勇冠并州儿。
直爱出身早，边功沙漠垂。
戎鞭腰下插，羌笛雪中吹。
膂力今应尽，将军犹未知。','',''),('quantangshi-06421','寄镜湖朱处士','李頎','quantangshi','','卷7','澄霁晚流阔，微风吹绿苹。
鳞鳞远峰见，淡淡平湖春。
芳草日堪把，白云心所亲。
何时可为乐，梦里东山人。','',''),('quantangshi-06422','宴陈十六楼','李頎','quantangshi','','卷7','西楼对金谷，此地古人心。
白日落庭内，黄花生涧阴。
四邻见疎木，万井度寒砧。
石上题诗处，千年留至今。','',''),('quantangshi-06423','送相里造入京','李頎','quantangshi','','卷7','子月过秦正，寒云覆洛城。
嗟君未得志，犹作苦辛行。
暖酒嫌衣薄，瞻风候雨晴。
春官含笑待，驱马速前程。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-06424','送钱子入京','李頎','quantangshi','','卷7','夜梦还京北，乡心恨捣衣。
朝逢入秦使，走马唤君归。
驿路清霜下，关门黄叶稀。
还家应信宿，看子速如飞。','',''),('quantangshi-06425','送綦毋三寺中赋得纱灯','李頎','quantangshi','','卷7','禅室吐香烬，轻纱笼翠烟。
长绳挂青竹，百尺垂红莲。
熠爚众星下，玲珑双塔前。
含光待明发，此别岂徒然。','',''),('quantangshi-06426','送人尉闽中','李頎','quantangshi','','卷7','可叹芳菲日，分为万里情。
阊门折垂柳，御苑听残莺。
海戍通闽邑，江航过楚城。
客心君莫问，春草是王程。','',''),('quantangshi-06427','送人归沔南','李頎','quantangshi','','卷7','梅花今正发，失路复何如。
旧国云山在，新年风景余。
春饶汉阳梦，日寄武陵书。
可即明时老，临川莫羡鱼。','',''),('quantangshi-06428','送卢逸人','李頎','quantangshi','','卷7','洛阳为此别，携手更何时。
不复人间见，祗应海上期。
清溪入云木，白首卧茅茨。
共惜卢敖去，天边望所思。','',''),('quantangshi-06429','送顾朝阳还吴','李頎','quantangshi','','卷7','寂寞俱不偶，裹粮空入秦。
宦途已可识，归卧包山春。
旧国指飞鸟，沧波愁旅人。
开樽洛水上，怨别柳花新。','',''),('quantangshi-06430','送窦参军','李頎','quantangshi','','卷7','城南送归客，举酒对林峦。
暄鸟迎风啭，春衣度雨寒。
桃花开翠幕，柳色拂金鞍。
公子何时至，无令芳草阑。','',''),('quantangshi-06431','望秦川','李頎','quantangshi','','卷7','秦川朝望迥，日出正东峰。
远近山河净，逶迤城阙重。
秋声万户竹，寒色五陵松。
客有归欤叹，凄其霜露浓。','',''),('quantangshi-06432','晚归东园','李頎','quantangshi','','卷7','荆扉带郊郭，稼穑满东葘。
倚杖寒山暮，鸣梭秋叶时。
回云覆阴谷，返景照霜梨。
澹泊真吾事，清风别自兹。','',''),('quantangshi-06433','觉公院施鸟石台','李頎','quantangshi','','卷7','石台置香饭，斋后施诸禽。
童子亦知善，众生无惧心。
苔痕苍晓露，盘势出香林。
锡杖或围绕，吾师一念深。','',''),('quantangshi-06434','篱笋','李頎','quantangshi','','卷7','东园长新笋，映日复穿篱。
迸出依青嶂，攒生半绿池。
色因林向背，行逐地高卑。
但恐春将老，青青独尔为。','',''),('quantangshi-06435','达奚吏部夫人寇氏挽歌','李頎','quantangshi','','卷7','存殁令名传，青青松柏田。
事姑称孝妇，生子继先贤。
露湿铭旌重，风吹卤簿前。
阴堂从此闭，谁诵女师篇。','',''),('quantangshi-06436','寄司勋卢员外','李頎','quantangshi','','卷7','流澌腊月下河阳，草色新年发建章。
秦地立春传太史，汉宫题柱忆仙郎。
归鸿欲度千门雪，侍女新添五夜香。
早晚荐雄文似者，故人今已赋长杨。','',''),('quantangshi-06437','寄綦毋三','李頎','quantangshi','','卷7','新加大邑绶仍黄，近与单车去洛阳。
顾眄一过丞相府，风流三接令公香。
南川稉稻花侵县，西岭云霞色满堂。
共道进贤蒙上赏，看君几岁作台郎。','',''),('quantangshi-06438','送魏万之京','李頎','quantangshi','','卷7','朝闻游子唱离歌，昨夜微霜初渡河。
鸿雁不堪愁里听，云山况是客中过。
关城树色催寒近，御苑砧声向晚多。
莫见长安行乐处，空令岁月易蹉跎。','',''),('quantangshi-06439','送李回','李頎','quantangshi','','卷7','知君官属大司农，诏幸骊山职事雄。
岁发金钱供御府，昼看仙液注离宫。
千岩曙雪旌门上，十月寒花辇路中。
不覩声明与文物，自伤流滞去关东。','',''),('quantangshi-06440','宿莹公禅房闻梵','李頎','quantangshi','','卷7','花宫仙梵远微微，月隐高城钟漏稀。
夜动霜林惊落叶，晓闻天籁发清机。
萧条已入寒空静，飒沓仍随秋雨飞。
始觉浮生无住着，顿令心地欲皈依。','',''),('quantangshi-06441','题璇公山池','李頎','quantangshi','','卷7','远公遯迹庐山岑，开士幽居只树林。
片石孤峯窥色相，清池皓月照禅心。
指挥如意天花落，坐卧闲房春草深。
此外俗尘都不染，惟余玄度得相寻。','',''),('quantangshi-06442','题卢五旧居','李頎','quantangshi','','卷7','物在人亡无见期，闲庭系马不胜悲。
窓前绿竹生空地，门外青山如旧时。
怅望秋天鸣坠叶，巑岏枯柳宿寒鸱。
忆君泪落东流水，岁岁花开知为谁。','',''),('quantangshi-06443','赠别张兵曹','李頎','quantangshi','','卷7','汉家萧相国，功盖五诸侯。
勋业河山重，丹青锡命优。
君为禁脔壻，争看玉人游。
荀令焚香日，潘郎振藻秋。
新成鹦鹉赋，能衣鷫鸘裘。
不惮轩车远，仍寻薜荔幽。
苑梨飞绛叶，伊水净寒流。
雪满故关道，云遮祥凤楼。
一身轻寸禄，万物任虚舟。
别后如相问，沧波双白鸥。','',''),('quantangshi-06444','宿香山寺石楼','李頎','quantangshi','','卷7','夜宿翠微半，高楼闻暗泉。
渔舟带远火，山磬发孤烟。
衣拂云松外，门清河汉边。
峰峦低枕席，世界接人天。
霭霭花出雾，辉辉星映川。
东林曙莺满，惆怅欲言旋。','',''),('quantangshi-06445','圣善阁送裴迪入京','李頎','quantangshi','','卷7','云华满高阁，苔色上鈎栏。
药草空阶静，梧桐返照寒。
清吟可愈疾，携手暂同欢。
堕叶和金磬，饥乌鸣露盘。
伊流惜东别，灞水向西看。
旧托含香署，云霄何足难。','',''),('quantangshi-06446','奉送漪叔游颍川兼谒淮阳太守','李頎','quantangshi','','卷7','罢吏今何适，辞家方独行。
嵩阳入归梦，颍水半前程。
闻道淮阳守，东南卧理清。
郡斋观政日，人马望乡情。
叠岭雪初霁，寒砧霜后鸣。
临川嗟拜手，寂寞事躬耕。','',''),('quantangshi-06447','二妃庙送裴侍御使桂阳','李頎','quantangshi','','卷7','沅上秋草晚，苍苍尧女祠。
无人见精魄，万古寒猿悲。
桂水身殁后，椒浆神降时。
回云迎赤豹，骤雨飒文狸。
受命出炎海，焚香征楚词。
乘骢感遗迹，一吊清川湄。','',''),('quantangshi-06448','送暨道士还玉清观','李頎','quantangshi','','卷7','仙宫有名籍，度世吴江濆。
大道本无我，青春长与君。
中州俄已到，至理得而闻。
明主降黄屋，时人看白云。
空山何窈窕，三秀日氛氲。
遂此留书客，超遥烟驾分。','',''),('quantangshi-06449','送刘主簿归金坛','李頎','quantangshi','','卷7','与子十年旧，其如离别何。
宦游邻故国，归梦是沧波。
京口青山远，金陵芳草多。
云帆晓容裔，江日昼清和。
县郭舟人饮，津亭渔者歌。
茅山有仙洞，羡尔再经过。','',''),('quantangshi-06450','送卢少府赴延陵','李頎','quantangshi','','卷7','问君从宦所，何日府中趋。
遥指金陵县，青山天一隅。
行人怀寸禄，小吏献新图。
北固波涛险，南天风俗殊。
春江连橘柚，晚景媚菰蒲。
漠漠花生渚，亭亭云过湖。
滩沙映村火，水雾歛樯乌。
回首东门路，乡书不可无。','',''),('quantangshi-06451','送皇甫曾游襄阳山水兼谒韦太守','李頎','quantangshi','','卷7','岘山枕襄阳，滔滔江汉长。
山深卧龙宅，水净斩蛟乡。
元凯春秋传，昭明文选堂。
风流满今古，烟岛思微茫。
白雁暮冲雪，青林寒带霜。
芦花独戍晚，柑实万家香。
旧国欲兹别，轻舟眇未央。
百花亭漫漫，一柱观苍苍。
按俗荆南牧，持衡吏部郎。
逢君立五马，应醉习家塘。','',''),('quantangshi-06452','龙门送裴侍御监五岭选','李頎','quantangshi','','卷7','万里番禺地，官人继帝忧。
君为柱下史，将命出东周。
歇马傍川路，张灯临石楼。
棱棱静疎木，濞濞响寒流。
榔叶四荒外，梅花五岭头。
明珠尉佗国，翠羽夜郎洲。
夷俗富珍产，土风资宦游。
心清物不杂，弊革事无留。
举善必称最，持奸当去尤。
何辞桂江远，今日用贤秋。','',''),('quantangshi-06453','送乔琳','李頎','quantangshi','','卷7','草绿小平津，花开伊水滨。
今君不得意，孤负帝乡春。
口不言金帛，心常任屈伸。
阮公惟饮酒，陶令肯羞贫。
阳羡风流地，沧海游寓人。
菱歌五湖远，桂树八公邻。
青鸟迎孤棹，白云随一身。
潮随秣陵上，月映石头新。
未可逃名利，应须在缙绅。
汀洲芳杜色，劝尔暂垂纶。','',''),('quantangshi-06454','题少府监李丞山池','李頎','quantangshi','','卷7','能向府亭内，置兹山与林。
他人驌驦马，而我薜萝心。
雨止禁门肃，莺啼官柳深。
长廊閟军器，积水背城阴。
窓外王孙草，牀头中散琴。
清风多仰慕，吾亦尔知音。','',''),('quantangshi-06455','长寿寺粲公院新甃井','李頎','quantangshi','','卷7','僧房来往久，露井每同观。
白石抱新甃，苍苔依旧栏。
空瓶宛转下，长绠辘轳盘。
境界因心净，泉源见底寒。
钟鸣时灌顶，对此日闲安。','',''),('quantangshi-06456','魏仓曹宅各赋一物得当轩石竹','李頎','quantangshi','','卷7','罗生殊众色，独为表华滋。
虽杂蕙兰处，无争桃李时。
同人趋府暇，落日后庭期。
密叶散红点，灵条惊紫蕤。
芳菲看不厌，采摘愿来兹。','',''),('quantangshi-06457','奉送五叔入京兼寄綦毋三','李頎','quantangshi','','卷7','云阴带残日，怅别此何时。
欲望黄山道，无由见所思。','',''),('quantangshi-06458','寄韩鹏','李頎','quantangshi','','卷7','为政心闲物自闲，朝看飞鸟暮飞还。
寄书河上神明宰，羡尔城头姑射山。','',''),('quantangshi-06459','百花原','李頎','quantangshi','','卷7','百花原头望京师，黄河水流无已时。
穷秋旷野行人绝，马首东来知是谁。','',''),('quantangshi-06460','遇刘五','李頎','quantangshi','','卷7','洛阳一别梨花新，黄鸟飞飞逢故人。
携手当年共为乐，无惊蕙草惜残春。','',''),('quantangshi-06461','送崔婴赴汉阳','李頎','quantangshi','','卷7','中外相连弟与兄，新加小县子男名。
才年三十佩铜印，知尔弦歌汉水清。','',''),('quantangshi-06462','送五叔入京兼寄綦毋三','李頎','quantangshi','','卷7','吏部明年拜官后，西城必与故人期。
寄书春草年年色，莫道相逢玉女祠。','',''),('quantangshi-06463','野老曝背','李頎','quantangshi','','卷7','百岁老翁不种田，惟知曝背乐残年。
有时扪虱独搔首，目送归鸿篱下眠。','',''),('quantangshi-06464','送东阳王太守','李頎','quantangshi','','卷7','江臯杜蘅绿，芳草日迟迟。
桧楫今何去，星郎出守时。
彤襜问风俗，明主寄惸嫠。
令下不徒尔，人和当在兹。
昔年经此地，微月有佳期。
洞口桂花白，岩前春草滋。
素沙静津濑，青壁带川坻。
野鹤每孤立，林鼯常昼悲。','',''),('quantangshi-06465','咏张諲山水','李頎','quantangshi','','卷7','小山破体闲支策，落日梨花照空壁。
诗堪记室妬风流，画与将军作勍敌。','',''),('quantangshi-06466','失题','李頎','quantangshi','','卷7','紫极殿前朝伏奏，龙华会里日相望。
别离岁岁如流水，谁辨他乡与故乡。','',''),('quantangshi-06467','冬夜寓居寄储太祝','綦毋潛','quantangshi','','卷7','自为洛阳客，夫子吾知音。
尽义能下士，时人无此心。
奈何离居夜，巢鸟悲空林。
愁坐至月上，复闻南邻砧。','',''),('quantangshi-06468','春泛若耶溪','綦毋潛','quantangshi','','卷7','幽意无断绝，此去随所偶。
晚风吹行舟，花路入溪口。
际夜转西壑，隔山望南斗。
潭烟飞溶溶，林月低向后。
生事且弥漫，愿为持竿叟。','',''),('quantangshi-06469','题鹤林寺','綦毋潛','quantangshi','','卷7','道林隐形胜，向背临层霄。
松覆山殿[冷]，花藏溪路遥。
珊珊宝幡挂，焰焰明灯烧。
迟日半空谷，春风连上潮。
少凭水木兴，暂令身心调。
愿谢携手客，兹山禅诵饶。','',''),('quantangshi-06470','题栖霞寺','綦毋潛','quantangshi','','卷7','南山势回合，灵境依此住。
殿转云崖阴，僧探石泉度。
龙蛇争翕习，神鬼皆密护。
万壑奔道场，羣峰向双树。
天花飞不着，水月白成路。
今日观身我，归心复何处。','',''),('quantangshi-06471','送储十二还庄城','綦毋潛','quantangshi','','卷7','西坂何缭绕，青林问子家。
天寒噪野雀，日晚度城鸦。
寂历道傍树，曈昽原上霞。
兹情不可说，长恨隐沦赊。','',''),('quantangshi-06472','送章彝下第','綦毋潛','quantangshi','','卷7','长安渭桥路，行客别时心。
献赋温泉毕，无媒魏阙深。
黄莺啼就马，白日暗归林。
三十名未立，君还惜寸阴。','',''),('quantangshi-06473','送崔员外黔中监选','綦毋潛','quantangshi','','卷7','持衡出帝畿，星指夜郎飞。
神女云迎马，荆门雨湿衣。
听猿收泪罢，系雁待书稀。
蛮貊虽殊俗，知君肝胆微。','',''),('quantangshi-06474','送贾恒明府兼寄温张二司户','綦毋潛','quantangshi','','卷7','越客新安别，秦人旧国情。
舟乘晚风便，月带上潮平。
花路西施石，云峰句践城。
明州报两掾，相忆二毛生。','',''),('quantangshi-06475','送宋秀才','綦毋潛','quantangshi','','卷7','冠古积荣盛，当时数戟门。
旧交丞相子，继世五侯孙。
长劒倚天外，短书盈万言。
秋风一送别，江上黯消魂。','',''),('quantangshi-06476','送平判官入秦','綦毋潛','quantangshi','','卷7','谪远自安命，三年已忘归。
同声愿执手，驿骑到门扉。
云是帝乡去，军书谒紫微。
曾为金马客，向日泪沾衣。','',''),('quantangshi-06477','送郑务拜伯父','綦毋潛','quantangshi','','卷7','名公作逐臣，驱马拂行尘。
旧国问郧子，劳歌过郢人。
一川花送客，二月柳宜春。
奉料竹林兴，宽怀此别晨。','',''),('quantangshi-06478','题招隐寺绚公房','綦毋潛','quantangshi','','卷7','开士度人久，空岩花雾深。
徒知燕坐处，不见有为心。
兰若门对壑，田家路隔林。
还言证法性，归去比黄金。','',''),('quantangshi-06479','宿太平观','綦毋潛','quantangshi','','卷7','夕到玉京寝，窅冥云汉低。
魂交仙室蝶，曙听羽人鸡。
滴沥花上露，清泠松下溪。
明当访真隐，挥手入无倪。','',''),('quantangshi-06480','题灵隐寺山顶禅院','綦毋潛','quantangshi','','卷7','招提此山顶，下界不相闻。
塔影挂清汉，钟声和白云。
观空静室掩，行道众香焚。
且驻西来驾，人天日未曛。','',''),('quantangshi-06481','若耶溪逢孔九','綦毋潛','quantangshi','','卷7','相逢此溪曲，胜托在烟霞。
潭影竹间动，岩阴檐外斜。
人言上皇代，犬吠武陵家。
借问淹留日，春风满若耶。','',''),('quantangshi-06482','宿龙兴寺','綦毋潛','quantangshi','','卷7','香刹夜忘归，松青古殿扉。
灯明方丈室，珠系比丘衣。
白日传心静，青莲喻法微。
天花落不尽，处处鸟衔飞。','',''),('quantangshi-06483','题沈东美员外山池','綦毋潛','quantangshi','','卷7','仙郎偏好道，凿沼象瀛洲。
鱼乐随情性，船行任去留。
秦人辨鸡犬，尧日识巢由。
归客衡门外，仍怜返景幽。','',''),('quantangshi-06484','茅山洞口','綦毋潛','quantangshi','','卷7','华阳仙洞口，半岭拂云看。
窈窕穿苔壁，差池对石坛。
方随地脉转，稍觉水晶寒。
未果变金骨，归来兹路难。','',''),('quantangshi-06485','过方尊师院','綦毋潛','quantangshi','','卷7','羽客北山寻，草堂松径深。
养神宗示法，得道不知心。
洞户逢双履，寥天有一琴。
更登玄圃上，仍种杏成林。','',''),('quantangshi-06486','经陆补阙隐居','綦毋潛','quantangshi','','卷7','不敢要君征亦起，致君全得似唐虞。
谠言昨叹离天听，新象今闻入县图。
琴锁坏窗风自响，鹤归乔木隐难呼。
学书弟子何人在，点检犹存谏草无。','',''),('quantangshi-06487','登天竺寺','綦毋潛','quantangshi','','卷7','郡有化城最，西穷叠嶂深。
松门当涧口，石路在峰心。
幽见夕阳霁，高逢暮雨阴。
佛身瞻绀发，宝地践黄金。
云向竹溪尽，月从花洞临。
因物成真悟，遗世在兹岑。','',''),('quantangshi-06488','满公房','綦毋潛','quantangshi','','卷7','世界莲花藏，行人香火缘。
灯王照不尽，中夜寂相传。','',''),('quantangshi-06489','过融上人兰若','綦毋潛','quantangshi','','卷7','山头禅室挂僧衣，窗外无人溪鸟飞。
黄昏半在下山路，却听钟声连翠微。','',''),('quantangshi-06490','早发上东门','綦毋潛','quantangshi','','卷7','十五能行西入秦，三十无家作路人。
时命不将明主合，布衣空染洛阳尘。','',''),('quantangshi-06491','只园寺','綦毋潛','quantangshi','','卷7','宝坊求往迹，神理驻沿洄。
雁塔酬前愿，王身更后来。
加持将暝合，朗悟豁然开。
两世分明见，余生复几哉。','',''),('quantangshi-06492','送集贤学士伊阙史少府放归江东觐省','綦毋潛','quantangshi','','卷7','墨客钟张侣，材高吴越珍。
千门来谒帝，驷马去荣亲。
吏邑沿清洛，乡山指白苹。
归期应不远，当及未央春。','',''),('quantangshi-06493','述韦昭应画犀牛','儲光羲','quantangshi','','卷7','遐方献文犀，万里随南金。
大邦柔远人，以之居山林。
食棘无秋冬，绝流无浅深。
双角前崭崭，三蹄下骎骎。
朝贤壮其容，未能辨其音。
有我衰鸟郎，新邑长鸣琴。
陛阁飞嘉声，丘甸盈仁心。
闲居命国工，作绘北堂阴。
眈眈若有神，庶比来仪禽。
昔有舞天庭，为君奏龙吟。','',''),('quantangshi-06494','献王威仪','儲光羲','quantangshi','','卷7','入与真主言，有骑天马来。
但有华清宫，不用神明台。
肃肃长自闲，门静无人开。','',''),('quantangshi-06495','野田黄雀行','儲光羲','quantangshi','','卷7','啧啧野田雀，不知躯体微。
闲穿深蒿里，争食复争飞。
穷老一颓舍，枣多桑树稀。
无枣犹可食，无桑何以衣。
萧条空仓暮，相引时来归。
斜路岂不捷，渚田岂不肥。
水长路且坏，恻恻与心违。','',''),('quantangshi-06496','樵父词','儲光羲','quantangshi','','卷7','山北饶朽木，山南多枯枝。
枯枝作采薪，爨室私自知。
诘朝砺斧寻，视暮行歌归。
先雪隐薜荔，迎暄卧茅茨。
清涧日濯足，乔木时曝衣。
终年登险阻，不复忧安危。
荡漾与神游，莫知是与非。','',''),('quantangshi-06497','渔父词','儲光羲','quantangshi','','卷7','泽鱼好鸣水，溪鱼好上流。
渔梁不得意，下渚潜垂钩。
乱荇时碍楫，新芦复隐舟。
静言念终始，安坐看沈浮。
素发随风扬，远心与云游。
逆浪还极浦，信潮下沧洲。
非为徇形役，所乐在行休。','',''),('quantangshi-06498','牧童词','儲光羲','quantangshi','','卷7','不言牧田远，不道牧陂深。
所念牛驯扰，不乱牧童心。
圆笠覆我首，长蓑披我襟。
方将忧暑雨，亦以惧寒阴。
大牛隐层坂，小牛穿近林。
同类相鼓舞，触物成讴吟。
取乐须臾间，宁问声与音。','',''),('quantangshi-06499','采莲词','儲光羲','quantangshi','','卷7','浅渚荇花繁，深潭菱叶疎。
独往方自得，耻邀淇上姝。
广江无术阡，大泽绝方隅。
浪中海童语，流下鲛人居。
春雁时隐舟，新萍复满湖。
采采乘日暮，不思贤与愚。','',''),('quantangshi-06500','采菱词','儲光羲','quantangshi','','卷7','浊水菱叶肥，清水菱叶鲜。
义不游浊水，志士多苦言。
潮没具区薮，潦深云梦田。
朝随北风去，暮逐南风旋。
浦口多渔家，相与邀我船。
饭稻以终日，羹莼将永年。
方冬水物穷，又欲休山樊。
尽室相随从，所贵无忧患。','',''),('quantangshi-06501','射雉词','儲光羲','quantangshi','','卷7','曝暄理新翳，迎春射鸣雉。
原田遥一色，臯陆旷千里。
遥闻咿喔声，时见双飞起。
幂䍥疎蒿下，毰毸深丛里。
顾敌已忘生，争雄方决死。
仁心贵勇义，岂能复伤此。
超遥下故墟，迢递回高畤。
大夫昔何苦，取笑欢妻子。','',''),('quantangshi-06502','猛虎词','儲光羲','quantangshi','','卷7','寒亦不忧雪，饥亦不食人。
人肉岂不甘，所恶伤明神。
太室为我宅，孟门为我邻。
百兽为我膳，五龙为我宾。
蒙马一何威，浮江一以仁。
彩章耀朝日，爪牙雄武臣。
高云逐气浮，厚地随声震。
君能贾余勇，日夕长相亲。','',''),('quantangshi-06503','渭桥北亭作','儲光羲','quantangshi','','卷7','停车渭阳暮，望望入秦京。
不见鵷鸾道，如闻歌吹声。
乡魂涉江水，客路指蒲城。
独有故楼月，今来亭上明。','',''),('quantangshi-06504','述华清宫五首 一','儲光羲','quantangshi','','卷7','上在蓬莱宫，莫若居华清。
朝朝礼玄阁，日日闻体轻。
大圣不私己，精禋为羣氓。','',''),('quantangshi-06505','述华清宫五首 二','儲光羲','quantangshi','','卷7','上出蓬莱时，六龙俨齐首。
长道舒羽仪，彤云暎前后。
天声殷宇宙，真气到林薮。','',''),('quantangshi-06506','述华清宫五首 三','儲光羲','quantangshi','','卷7','昔在轩辕朝，五城十二楼。
今我神泉宫，独在骊山陬。
羣方趋顺动，百辟随天游。','',''),('quantangshi-06507','述华清宫五首 四','儲光羲','quantangshi','','卷7','正月开阳和，通门缉元化。
穆穆睟容归，岂为明灯夜。
高山大风起，肃肃随龙驾。','',''),('quantangshi-06508','述华清宫五首 五','儲光羲','quantangshi','','卷7','上林神君宫，此地即明庭。
山开鸿蒙色，天转招摇星。
三雪报大有，孰为非我灵。','',''),('quantangshi-06509','杂咏五首 石子松','儲光羲','quantangshi','','卷7','盘石青岩下，松生盘石中。
冬春无异色，朝暮有清风。
五鬣何人采，西山旧两童。','',''),('quantangshi-06510','杂咏五首 架檐藤','儲光羲','quantangshi','','卷7','得从轩墀下，殊胜松柏林。
生枝逐架远，吐叶向门深。
何许答君子，檐间朝暝阴。','',''),('quantangshi-06511','杂咏五首 池边鹤','儲光羲','quantangshi','','卷7','舞鹤傍池边，水清毛羽鲜。
立如依岸雪，飞似向池泉。
江海虽言旷，无如君子前。','',''),('quantangshi-06512','杂咏五首 钓鱼湾','儲光羲','quantangshi','','卷7','垂钓绿湾春，春深杏花乱。
潭清疑水浅，荷动知鱼散。
日暮待情人，维舟绿杨岸。','',''),('quantangshi-06513','杂咏五首 幽人居','儲光羲','quantangshi','','卷7','幽人下山径，去去夹青林。
滑处莓苔湿，暗中萝薜深。
春朝烟雨散，犹带浮云阴。','',''),('quantangshi-06514','题太玄观','儲光羲','quantangshi','','卷7','门外车马喧，门里宫殿清。
行即翳若木，坐即吹玉笙。
所喧既非我，真道其冥冥。','',''),('quantangshi-06515','至嵩阳观观即天皇故宅','儲光羲','quantangshi','','卷7','真人上清室，乃在中峰前。
花雾生玉井，霓裳画列仙。
念兹宫故宇，多此地新泉。
松柏有清阴，薜萝亦自妍。
一闻步虚子，又话逍遥篇。
忽若在云汉，风中意泠然。','',''),('quantangshi-06516','贻韦炼师','儲光羲','quantangshi','','卷7','精思莫知日，意静如空虚。
三鸟自来去，九光遥卷舒。
新池近天井，玉宇停云车。
余亦苦山路，洗心祈道书。','',''),('quantangshi-06517','霁后贻马十二巽','儲光羲','quantangshi','','卷7','高天风雨散，清气在园林。
况我夜初静，当轩鸣绿琴。
云开北堂月，庭满南山阴。
不见长裾者，空歌游子吟。','',''),('quantangshi-06518','题陆山人楼','儲光羲','quantangshi','','卷7','暮声杂初雁，夜色涵早秋。
独见海中月，照君池上楼。
山云拂高栋，天汉入云流。
不惜朝光满，其如千里游。','',''),('quantangshi-06519','献八舅东归','儲光羲','quantangshi','','卷7','高位莫能舍，舍之世所贤。
云车游日华，岂比龙楼前。
寝疾乃就枕，情感唯灵仙。
帝鸿思道宗，臣彭亦长年。
天书加羽服，又许归东川。
镜水涵太清，禹山朝上玄。
诚亡真混沌，玉立方婵娟。
素业作仙居，子孙当自传。
门多松柏树，箧有逍遥篇。
独往不可羣，沧海成桑田。','',''),('quantangshi-06520','泛茅山东溪','儲光羲','quantangshi','','卷7','清晨登仙峰，峰远行未极。
江海霁初景，草木含新色。
而我任天和，此时聊动息。
望乡白云里，发棹清溪侧。
松柏生深山，无心自贞直。','',''),('quantangshi-06521','吃茗粥作','儲光羲','quantangshi','','卷7','当昼暑气盛，鸟雀静不飞。
念君高梧阴，复解山中衣。
数片远云度，曾不蔽炎晖。
淹留膳茶粥，共我饭蕨薇。
敝庐既不远，日暮徐徐归。','',''),('quantangshi-06522','游茅山五首 一','儲光羲','quantangshi','','卷7','十年别乡县，西去入皇州。
此意在观国，不言空远游。
九衢平若水，利往无轻舟。
北洛反初路，东江还故丘。
春山多秀木，碧涧尽清流。
不见子桑扈，当从方外求。','',''),('quantangshi-06523','游茅山五首 二','儲光羲','quantangshi','','卷7','世业传儒行，行成非不荣。
其如怀独善，况以闻长生。
家近华阳洞，早年深此情。
巾车云路入，理棹瑶溪行。
天地朝光满，江山春色明。
王庭有轩冕，此日方知轻。','',''),('quantangshi-06524','游茅山五首 三','儲光羲','quantangshi','','卷7','平生非作者，望古怀清芬。
心以道为际，行将时不羣。
兹山在人境，灵贶久传闻。
远势一峰出，近形千嶂分。
冬春有茂草，朝暮多鲜云。
此去亦何极，但言西日曛。','',''),('quantangshi-06525','游茅山五首 四','儲光羲','quantangshi','','卷7','昔贤居柱下，今我去人间。
良以直心旷，兼之外视闲。
垂纶非钓国，好学异希颜。
落日登高屿，悠然望远山。
溪流碧水去，云带清阴还。
想见中林士，岩扉长不关。','',''),('quantangshi-06526','游茅山五首 五','儲光羲','quantangshi','','卷7','名岳征仙事，清都访道书。
山门入松柏，天路涵空虚。
南极见朝采，西潭闻夜渔。
远心尚云宿，浪迹出林居。
为己存实际，忘形同化初。
此行良已矣，不乐复何如。','',''),('quantangshi-06527','述降圣观','儲光羲','quantangshi','','卷7','一山尽天苑，一峰开道宫。
道花飞羽衞，天鸟游云空。
玉殿俯玄水，春旗摇素风。
夹门小松柏，覆井新梧桐。
自昔大仙下，乃知元化功。
神皇作桂馆，此意与天通。','',''),('quantangshi-06528','题眄上人禅居','儲光羲','quantangshi','','卷7','真王清净子，燕居复行心。
结宇邻居邑，寤言非远寻。
丹青丈室满，草树一庭深。
秀色玄冬发，交枝白日阴。
江流暎朱户，山鸟鸣香林。
独住已寂寂，安知浮与沈。','',''),('quantangshi-06529','过新丰道中','儲光羲','quantangshi','','卷7','西下长乐坂，东入新丰道。
雨多车马稀，道上生秋草。
太阴蔽臯陆，莫知晚与早。
雷雨杳冥冥，川谷漫浩浩。
诏书植嘉木，众言桃李好。
自愧无此容，归从汉阴老。','',''),('quantangshi-06530','夜到洛口入黄河','儲光羲','quantangshi','','卷7','河洲多青草，朝暮增客愁。
客愁惜朝暮，枉渚蹔停舟。
中宵大川静，解缆逐归流。
浦溆既清旷，沿洄非阻修。
登舻望落月，击汰悲新秋。
倘遇乘槎客，永言星汉游。','',''),('quantangshi-06531','使过弹筝峡作','儲光羲','quantangshi','','卷7','鸟雀知天雪，羣飞复羣鸣。
原田无遗粟，日暮满空城。
达士忧世务，鄙夫念王程。
晨过弹筝峡，马足凌兢行。
双壁隐灵曜，莫能知晦明。
皑皑坚冰白，漫漫阴云平。
始信古人言，苦节不可贞。','',''),('quantangshi-06532','泊舟贻潘少府','儲光羲','quantangshi','','卷7','行子苦风潮，维舟未能发。
宵分卷前幔，卧视清秋月。
四泽蒹葭深，中洲烟火绝。
苍苍水雾起，落落疎星没。
所遇尽渔商，与言多楚越。
其如念极浦，又以思明哲。
常若千里余，况之异乡别。','',''),('quantangshi-06533','仲夏入园中东陂','儲光羲','quantangshi','','卷7','方塘深且广，伊昔俯吾庐。
环岸垂绿柳，盈泽发红蕖。
上延北原秀，下属幽人居。
暑雨若混沌，清明如空虚。
此乡多隐逸，水陆见樵渔。
废赏亦何贵，为欢良易摅。
且言重观国，当此赋归欤。','',''),('quantangshi-06534','效古二首 一','儲光羲','quantangshi','','卷7','晨登凉风台，暮走邯郸道。
曜灵何赫烈，四野无青草。
大军北集燕，天子西居镐。
妇人役州县，丁男事征讨。
老幼相别离，哭泣无昏早。
稼穑既殄绝，川泽复枯槁。
旷哉远此忧，冥冥商山皓。','',''),('quantangshi-06535','效古二首 二','儲光羲','quantangshi','','卷7','东风吹大河，河水如倒流。
河洲尘沙起，有若黄云浮。
赬霞烧广泽，洪曜赫高丘。
野老泣相语，无地可荫休。
翰林有客卿，独负苍生忧。
中夜起踯躅，思欲献厥谋。
君门峻且深，踠足空夷犹。','',''),('quantangshi-06536','杂诗二首 一','儲光羲','quantangshi','','卷7','混沌本无象，末路多是非。
达士志寥廓，所在能忘禨。
耕凿时未至，还山聊采薇。
虎豹对我蹲，鸑鷟旁我飞。
仙人空中来，谓我勿复归。
格泽为君驾，虹霓为君衣。
西游昆仑墟，可与世人违。','',''),('quantangshi-06537','杂诗二首 二','儲光羲','quantangshi','','卷7','秋气肃天地，太行高崔嵬。
猨狖清夜吟，其声一何哀。
寂寞掩圭荜，梦寐游蓬莱。
琪树远亭亭，玉堂云中开。
洪崖吹箫管，玉女飘颻来。
雨师既先后，道路无纤埃。
鄙哉楚襄王，独好阳云台。','',''),('quantangshi-06538','陆着作挽歌 一','儲光羲','quantangshi','','卷7','世业江湖侧，郊原休沐处。
独言五日归，未道千秋去。
乡亭春水绿，昌阁寒光暮。
昔为昼锦游，今成逝川路。','',''),('quantangshi-06539','陆着作挽歌 二','儲光羲','quantangshi','','卷7','归路秦城下，寒云惨平田。
故园沧海边，绿柳覆平川。
送客异他日，还舟殊昔年。
华亭有明月，长向陇头悬。','',''),('quantangshi-06540','陆着作挽歌 三','儲光羲','quantangshi','','卷7','剑水千人石，荆江万里流。
英英有君子，才德满中州。
明道俟良佐，惟贤初薄游。
生涯一朝尽，寂寞夜台幽。','',''),('quantangshi-06541','陆着作挽歌 四','儲光羲','quantangshi','','卷7','金堂策令名，仙掖居清位。
鸣玉朝双阙，垂缨游两地。
朝夕既论思，春秋仍书事。
何言鲁声伯，忽下琼珠泪。','',''),('quantangshi-06542','陆着作挽歌 五','儲光羲','quantangshi','','卷7','令德弃人世，明朝降宠章。
起居存有位，着作没为郎。
寒水落南浦，月华虚北堂。
松门一长想，彷佛见清扬。','',''),('quantangshi-06543','山居贻裴十二迪','儲光羲','quantangshi','','卷7','落叶满山砌，苍烟埋竹扉。
远怀青冥士，书劒常相依。
霜卧眇兹地，琴言纷已违。
衡阳今万里，南雁将何归。
出径惜松引，入舟怜钓矶。
西林有明月，夜久空微微。','',''),('quantangshi-06544','秦中岁晏马舍人宅宴集','儲光羲','quantangshi','','卷7','冬暮久无乐，西行至长安。
故人处东第，清夜多新欢。
广庭竹阴静，华池月色寒。
知音尽词客，方见交情难。','',''),('quantangshi-06545','荐玄德公庙','儲光羲','quantangshi','','卷7','神道本无已，成化亦自然。
君居寥天上，德在玉华泉。
真游践王豫，永日迟云仙。
表微在营道，明祀将祈年。
灵山俯新邑，松上生彩烟。
岂知穆天子，远去瑶池边。','',''),('quantangshi-06546','上长史王公责躬','儲光羲','quantangshi','','卷7','覆舟无伯夷，覆车无仲尼。
自咎失明义，宁由贝锦诗。
松柏日已坚，桃李日以滋。
顾己独暗昧，所居成蒺藜。
大贤荐时文，丑妇用蛾眉。
惕惕愧不已，岂敢论其私。
方朔既有言，子建亦有诗。
恻隐及先世，析薪成自悲。
灵鸟酬德辉，黄雀报仁慈。
若公庶伏罪，此事安能迟。','',''),('quantangshi-06547','至岳寺即大通大照禅塔上温上人','儲光羲','quantangshi','','卷7','秋山下暎宫，宫色宜朝阳。
迢递在半岭，参差非一行。
燕息云满门，出游花隐房。
二尊此成道，禅宇遥相望。
凤铎天中鸣，岩梯松下长。
山墟响信鼓，蘅薄生蕙香。
起灭一以雪，往来亦诚亡。
悲哉门弟子，要自知心长。','',''),('quantangshi-06548','终南幽居献苏侍郎三首时拜太祝未上 一','儲光羲','quantangshi','','卷7','暮春天气和，登岭望层城。
朝日悬清景，巍峨宫殿明。
圣君常临朝，达士复悬衡。
道近燕艮足，归来卧山楹。
灵堦曝仙书，深室炼金英。
春岩松柏秀，晨路鵾鸡鸣。
羽化既有言，无然悲不成。','',''),('quantangshi-06549','终南幽居献苏侍郎三首时拜太祝未上 二','儲光羲','quantangshi','','卷7','中岁尚微道，始知将谷神。
抗策还南山，水木自相亲。
深林开一道，青嶂成四邻。
平明去采薇，日入行刈薪。
云归万壑暗，雪罢千崖春。
始看玄鸟来，已见瑶华新。
寄言搴芳者，无乃后时人。','',''),('quantangshi-06550','终南幽居献苏侍郎三首时拜太祝未上 三','儲光羲','quantangshi','','卷7','卜筑青岩里，云萝四垂阴。
虚室若无人，乔木自成林。
时有清风至，侧闻樵采音。
凤皇鸣南冈，望望隔层岑。
既言山路远，复道溪流深。
偓佺空中游，虬龙水间吟。
何当见轻翼，为我达远心。','',''),('quantangshi-06551','题应圣观','儲光羲','quantangshi','','卷7','空中望小山，山下见余雪。
皎皎河汉女，在兹养真骨。
登门骇天书，启龠问仙诀。
池光摇水雾，灯色连松月。
合甎起花台，折草成玉节。
天鸡弄白羽，王母垂玄发。
北有上年宫，一路在云霓。
上心方向道，时复朝金阙。','',''),('quantangshi-06552','至闲居精舍呈正上人','儲光羲','quantangshi','','卷7','太室三招提，其趣皆不同。
不同非一趣，况是天游宫。
双岭前夹门，阁道复横空。
宝坊若花积，宛转不可穷。
流泉自成池，清松信饶风。
秋晏景气逈，皛明丹素功。
将近隐者邻，远与西山通。
大师假惠照，念以息微躬。','',''),('quantangshi-06553','酬綦毋校书梦耶溪见赠之作','儲光羲','quantangshi','','卷7','校文在仙掖，每有沧洲心。
况以北窗下，梦游清溪阴。
春看湖水漫，夜入回塘深。
往往缆垂葛，出舟望前林。
山人松下饭，钓客芦中吟。
小隐何足贵，长年固可寻。
还车首东道，惠言若黄金。
以我采薇意，传之天姥岑。','',''),('quantangshi-06554','田家即事','儲光羲','quantangshi','','卷7','蒲叶日已长，杏花日已滋。
老农要看此，贵不违天时。
迎晨起饭牛，双驾耕东菑。
蚯蚓土中出，田乌随我飞。
羣合乱啄噪，嗷嗷如道饥。
我心多恻隐，顾此两伤悲。
拨食与田乌，日暮空筐归。
亲戚更相诮，我心终不移。','',''),('quantangshi-06555','同王十三维偶然作十首 一','儲光羲','quantangshi','','卷7','仲夏日中时，草木看欲燋。
田家惜工力，把锄来东臯。
顾望浮云阴，往往误伤苗。
归来悲困极，兄嫂共相譊。
无钱可沽酒，何以解劬劳？
夜深星汉明，庭宇虚寥寥。
高柳三五株，可以独逍遥。','',''),('quantangshi-06556','同王十三维偶然作十首 二','儲光羲','quantangshi','','卷7','北山种松柏，南山种蒺藜。
出入虽同趣，所向各有宜。
孔丘贵仁义，老氏好无为。
我心若虚空，此道将安施。
暂过伊阙间，晼晚三伏时。
高阁入云中，芙蓉满清池。
要自非我室，还望南山陲。','',''),('quantangshi-06557','同王十三维偶然作十首 三','儲光羲','quantangshi','','卷7','野老本贫贱，冒暑锄瓜田。
一畦未及终，树下高枕眠。
荷蓧者谁子，皤皤来息肩。
不复问乡墟，相见但依然。
腹中无一物，高话羲皇年。
落日临层隅，逍遥望晴川。
使妇提蚕筐，呼儿榜渔船。
悠悠泛绿水，去摘浦中莲。
莲花艳且美，使我不能还。','',''),('quantangshi-06558','同王十三维偶然作十首 四','儲光羲','quantangshi','','卷7','浮云在虚空，随风复卷舒。
我心方处顺，动作何忧虞。
但言婴世网，不复得间居。
迢递别东国，超遥来西都。
见人乃恭敬，曾不问贤愚。
虽若不能言，中心亦难诬。
故乡满亲戚，道远情日疎。
偶欲陈此意，复无南飞凫。','',''),('quantangshi-06559','同王十三维偶然作十首 五','儲光羲','quantangshi','','卷7','草木花叶生，相与命为春。
当非草木意，信是故时人。
静念恻羣物，何由知至真。
狂歌问夫子，夫子莫能陈。
凤皇飞且鸣，容裔下天津。
清净无言语，兹焉庶可亲。','',''),('quantangshi-06560','同王十三维偶然作十首 六','儲光羲','quantangshi','','卷7','黄河流向东，弱水流向西。
趋舍各有异，造化安能齐。
妾本邯郸女，生长在丛台。
既闻容见宠，复想玄为妻。
刻画尚风流，幸会君招携。
逶迤歌舞座，婉娈芙蓉闺。
日月方向除，恩爱忽焉暌。
弃置谁复道，但悲生不谐。
羡彼匹妇意，偕老常同栖。','',''),('quantangshi-06561','同王十三维偶然作十首 七','儲光羲','quantangshi','','卷7','日暮登春山，山鲜云复轻。
远近看春色，踟蹰新月明。
仙人浮丘公，对月时吹笙。
丹鸟飞熠熠，苍蝇乱营营。
羣动汩吾真，讹言伤我情。
安得如子晋，与之游太清。','',''),('quantangshi-06562','同王十三维偶然作十首 八','儲光羲','quantangshi','','卷7','耽耽铜鞮宫，遥望长数里。
宾客无多少，出入皆珠履。
朴儒亦何为，辛苦读旧史。
不道无家舍，效他养妻子。
冽冽玄冬暮，衣裳无准拟。
偶然着道书，神人养生理。
公卿时见赏，赐赉难具纪。
莫问身后事，且论朝夕是。','',''),('quantangshi-06563','同王十三维偶然作十首 九','儲光羲','quantangshi','','卷7','空山暮雨来，众鸟竟栖息。
斯须照夕阳，双双复抚翼。
我念天时好，东田有稼穑。
浮云蔽川原，新流集沟洫。
裴回顾衡宇，僮仆邀我食。
卧览牀头书，睡看机中织。
想见明膏煎，中夜起唧唧。','',''),('quantangshi-06564','同王十三维偶然作十首 十','儲光羲','quantangshi','','卷7','四邻竞丰屋，我独好卑室。
窈窕高台中，时闻抚新瑟。
狂飙动地起，拔木乃非一。
相顾始知悲，中心忧且栗。
蚩蚩命子弟，恨不居高秩。
日入宾从归，清晨冠盖出。
中庭有奇树，荣早衰复疾。
此道犹不知，微言安可述。','',''),('quantangshi-06565','升天行贻卢六健','儲光羲','quantangshi','','卷7','真人居阆风，时奏清商音。
听者即王母，泠泠和瑟琴。
坐对三花枝，行随五云阴。
天长昆仑小，日久蓬莱深。
上由玉华宫，下视首阳岑。
神州亦清净，要自有浮沈。
恻恻苦哉行，呱呱游子吟。
庐山逢若士，思欲化黄金。
雨雪没太山，谁能无归心。
逍遥在云汉，可以来相寻。','',''),('quantangshi-06566','田家杂兴八首 一','儲光羲','quantangshi','','卷7','春至鸧鹒鸣，薄言向田墅。
不能自力作，黾勉娶邻女。
既念生子孙，方思广田圃。
闲时相顾笑，喜悦好禾黍。
夜夜登啸台，南望洞庭渚。
百草被霜露，秋山响砧杵。
却羡故年时，中情无所取。','',''),('quantangshi-06567','田家杂兴八首 二','儲光羲','quantangshi','','卷7','众人耻贫贱，相与尚膏腴。
我情既浩荡，所乐在畋渔。
山泽时晦暝，归家蹔闲居。
满园植葵藿，绕屋树桑榆。
禽雀知我闲，翔集依我庐。
所愿在优游，州县莫相呼。
日与南山老，兀然倾一壶。','',''),('quantangshi-06568','田家杂兴八首 三','儲光羲','quantangshi','','卷7','逍遥阡陌上，远近无相识。
落日照秋山，千岩同一色。
网罟绕深莽，鹰鹯始轻翼。
猎马既如风，奔兽莫敢息。
驻旗沧海上，犒士吴宫侧。
楚国有夫人，性情本贞直。
鲜禽徒自致，终岁竟不食。','',''),('quantangshi-06569','田家杂兴八首 四','儲光羲','quantangshi','','卷7','田家趋壠亩，当昼掩虚关。
邻里无烟火，儿童共幽闲。
桔槔悬空圃，鸡犬满桑间。
时来农事隙，采药游名山。
但言所采多，不念路险艰。
人生如蜉蝣，一往不可攀。
君看西王母，千载美容颜。','',''),('quantangshi-06570','田家杂兴八首 五','儲光羲','quantangshi','','卷7','平生养情性，不复计忧乐。
去家行卖畚，留滞南阳郭。
秋至黍苗黄，无人可刈获。
稚子朝未饭，把竿逐鸟雀。
忽见梁将军，乘车出宛洛。
意气轶道路，光辉满墟落。
安知负薪者，咥咥笑轻薄。','',''),('quantangshi-06571','田家杂兴八首 六','儲光羲','quantangshi','','卷7','楚山有高士，梁国有遗老。
筑室既相邻，向田复同道。
糗糒常共饭，儿孙每更抱。
忘此耕耨劳，愧彼风雨好。
蟪蛄鸣空泽，鶗鴂伤秋草。
日夕寒风来，衣裳苦不早。','',''),('quantangshi-06572','田家杂兴八首 七','儲光羲','quantangshi','','卷7','梧桐荫我门，薜荔网我屋。
迢迢两夫妇，朝出暮还宿。
稼穑既自种，牛羊还自牧。
日旰懒耕锄，登高望川陆。
空山足禽兽，墟落多乔木。
白马谁家儿，联翩相驰逐。','',''),('quantangshi-06573','田家杂兴八首 八','儲光羲','quantangshi','','卷7','种桑百余树，种黍三十亩。
衣食既有余，时时会亲友。
夏来菰米饭，秋至菊花酒。
孺人喜逢迎，稚子解趋走。
日暮闲园里，团团荫榆柳。
酩酊乘夜归，凉风吹户牖。
清浅望河汉，低昂看北斗。
数瓮犹未开，明朝能饮否。','',''),('quantangshi-06574','题辨觉精舍','儲光羲','quantangshi','','卷7','朝随秋云阴，乃至青松林。
花阁空中远，方池岩下深。
竹风乱天语，溪响成龙吟。
试问真君子，游山非世心。','',''),('quantangshi-06575','题慎言法师故房','儲光羲','quantangshi','','卷7','精庐不住子，自有无生乡。
过客知何道，裴回雁子堂。
浮云归故岭，落月还西方。
日夕虚空里，时时闻异香。','',''),('quantangshi-06576','石瓮寺','儲光羲','quantangshi','','卷7','遥山起真宇，西向尽花林。
下见宫殿小，上看廊庑深。
苑花落池水，天语闻松音。
君子又知我，焚香期化心。','',''),('quantangshi-06577','题崔山人别业','儲光羲','quantangshi','','卷7','南阳隐居者，筑室丹溪源。
溪冷惧秋[晏]，室寒欣景暾。
山鸡鸣菌阁，水雾入衡门。
东岭或舒啸，北窗时讨论。
封君渭阳竹，逸士汉阴园。
何必崆峒上，独为尧所尊。','',''),('quantangshi-06578','行次田家澳梁作','儲光羲','quantangshi','','卷7','田家俯长道，邀我避炎氛。
当暑日方昼，高天无片云。
桑间禾黍气，柳下牛羊羣。
野雀栖空屋，晨昏不复闻。
前登澳梁坂，极望温泉分。
逆旅方三舍，西山犹未曛。','',''),('quantangshi-06579','昭圣观','儲光羲','quantangshi','','卷7','主家隐溪口，微路入花源。
数日朝青阁，彩云犹在门。
双楼夹一殿，玉女侍玄元。
扶橑尽蟠木，步櫩多画翻。
新松引天籁，小柏绕山樊。
坐弄竹阴远，行随溪水喧。
石池辨春色，林兽知人言。
未逐凤皇去，真宫在此原。','',''),('quantangshi-06580','题辛道士房','儲光羲','quantangshi','','卷7','全神不言命，所尚道家流。
迨此远南楚，遂令思北游。
先生秀衡岳，玉立居玄丘。
门带江山静，房随瑶草幽。
逍遥三花发，罔象五云浮。
自有太清纪，曾垂华发忧。
大年方橐龠，小智即蜉蝣。
七日赤龙至，莫令余独留。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-06581','登秦岭作时陷贼归国','儲光羲','quantangshi','','卷7','朝出猛兽林，躨跜登高峰。
僮仆履云雾，随我行太空。
羲和舒灵晖，倏忽西极通。
回首望泾渭，隐隐如长虹。
九逵合苍芜，五陵遥瞳蒙。
鹿游大明殿，雾湿华清宫。
网罗蠛蠓时，顾齿熊罴锋。
失途走江汉，不能有其功。
气逐招遥星，魂随阊阖风。
惟言宇宙清，复使车书同。
林木被繁霜，合沓连山红。
鹏鹗励羽翼，俯视荆棘丛。
誓将食鸧鸮，然后归崆峒。','',''),('quantangshi-06582','晦日任桥池亭','儲光羲','quantangshi','','卷7','温泉作天邑，直北开新洲。
未有菰蒲生，即闻凫雁游。
六亭在高岸，数岛居中流。
晦日望清波，相与期泛游。
西道苦转毂，北堤疲行舟。
清泠水木阴，才可适我忧。','',''),('quantangshi-06583','望幸亭','儲光羲','quantangshi','','卷7','五年一巡狩，西幸过东畿。
周国易居守，周人多怨思。
君王敷惠政，程作贵从时。
大厦非一木，沈沈临九逵。
庆云宿飞栋，嘉树罗青墀。
疎屏宜朝享，方塘堪水嬉。
云中仰华盖，桁下望春旗。
天意知如此，星言归洛师。','',''),('quantangshi-06584','哥舒大夫颂德','儲光羲','quantangshi','','卷7','天纪启真命，君生臣亦生。
乃知赤帝子，复有苍龙精。
神武建皇极，文昌开将星。
超超渭滨器，落落山西名。
画阃入受脤，凿门出捍城。
戎人昧正朔，我有轩辕兵。
陇路起丰镐，关云随斾旌。
河湟训兵甲，义勇方横行。
韩魏多锐士，蹶张在幕庭。
大非四决轧，石堡高峥嵘。
攻伐若振槁，孰云非神明。
嘉谋即天意，骤胜由师贞。
枯草被西陆，烈风昏太清。
戢戈旄头落，牧马昆仑平。
宾从俨冠盖，封山纪天声。
来朝芙蓉阙，鸣玉飘华缨。
直道济时宪，天邦遂轻刑。
抗书报知己，松柏亦以荣。
嘉命列上第，德辉照天京。
在车持简墨，粲粲皆词英。
顾我抢榆者，莫能翔青冥。
游燕非骐骥，踯躅思长鸣。','',''),('quantangshi-06585','安宜园林献高使君','儲光羲','quantangshi','','卷7','直道已三出，幸从江上回。
新居茅茨逈，起见秋云开。
十里次舟楫，二桥交往来。
楚言满邻里，雁呌喧池台。
鱼鳖乐仁政，浮沈亦至哉。
小山宜大隐，要自望蓬莱。','',''),('quantangshi-06587','河中望鸟滩作贻吕四郎中','儲光羲','quantangshi','','卷7','河流有深曲，舟子莫能知。
弭棹临沙屿，微吟西日驰。
平明春色霁，两岸好风吹。
去去川途尽，悠悠亲友离。
汉宫成羽翼，伊水弄参差。
为惜淮南子，如何攀桂枝。','',''),('quantangshi-06588','秦中初霁献给事二首 一','儲光羲','quantangshi','','卷7','渭水收暮雨，处处多新泽。
宫苑傍山明，云林带天碧。
君子耸高驾，英声邈今昔。
锵佩出中台，彯缨入仙掖。
夙心幸清鉴，晚志欣良觌。
鸣盗非足征，愿言同下客。','',''),('quantangshi-06589','秦中初霁献给事二首 二','儲光羲','quantangshi','','卷7','南国久为思，西都尝作宾。
云开天地色，日照山河春。
善听在知己，扬光唯达人。
妙年弄柔翰，弱冠偶良晨。
擢第文昌阁，还家沧海滨。
寸心何所望，东掖有贤臣。','',''),('quantangshi-06590','晚次东亭献郑州宋使君文','儲光羲','quantangshi','','卷7','自初宾上国，乃到邹人乡。
曾点与曾子，俱升阙里堂。
武皇恢大略，逸翮思寥廓。
三居清宪台，两拜文昌阁。
为道既贞信，处名犹謇谔。
铁柱励风威，锦轴含光辉。
夜闻持简立，朝看伏奏归。
洞门清佩响，广路玉珂飞。
骧首入丹掖，抟空趋太微。
丝纶逢圣主，出入飘华组。
愔愔宿帝梧，侃侃居文府。
海内语三独，朝端谋六户。
善计在弘羊，清严归仲举。
侍郎跨方朔，中丞蔑周处。
天眷择循良，惟贤降宠章。
分符指聊摄，为政本农桑。
籍籍歌五袴，祁祁颂千箱。
随车微雨洒，逐扇清风扬。
既以迁列国，复兹邻帝乡。
褰帷乃仍旧，坐啸非更张。
居敬物无扰，履端人自康。
薄游出京邑，引领东南望。
林晚鸟雀噪，田秋稼穑黄。
成臯天地险，广武征战场。
道丧苦兵赋，时来开井疆。
霏霏渠门色，暗暗制岩光。
徒念京索近，犹悲溱洧长。
大明潜照耀，淑慝自昭彰。
昔岁幸西土，今兹归洛阳。
同焉知郑伯，当辅我周王。','',''),('quantangshi-06591','秋次霸亭寄申大','儲光羲','quantangshi','','卷7','橘柚植寒陵，芙蓉蔕修坂。
无言不得意，得意何由展。
况我行且徒，而君往犹蹇。
既伤人事近，复言天道远。
薄暮入空亭，中夜不能饭。
南听鸿雁尽，西见招摇转。
千门汉主宫，百里周王苑。
杲杲初景出，油油鲜云卷。
会朝幸岁正，校猎从新狝。
念君久京国，双涕如露泫。
无人荐子云，太息竟谁辨。','',''),('quantangshi-06592','舟中别武金坛','儲光羲','quantangshi','','卷7','曰予轻皎洁，坦率宾混元。
忽乃异羣萃，高歌信陵门。
信陵好宾客，清夜开华轩。
月光丽池阁，野气浮林园。
偶坐烂明星，归志潜崩奔。
漾舟清潭里，慰我别离魂。
落日下西山，左右惨无言。
萧条风雨散，窅霭江湖昏。
秋荷尚幽郁，暮鸟复翩翻。
纸笔亦何为，写我心中冤。','',''),('quantangshi-06593','巩城东庄道中作','儲光羲','quantangshi','','卷7','北陵散寒鸟，西山照初日。
婉娈晋阳京，踟蹰野人室。
南轩草间去，后乘林中出。
霭霭长路暖，迟迟狭路归。
蜉蝣时蔽月，枳棘复伤衣。
城上东风起，河边早雁飞。
夏王纪冬令，殷人乃正月。
涯口度新云，山阴留故雪。
幸逢耆耋话，余待亲隣别。
总辔出丛薄，歇鞍登峻隅。
春源既荡漭，伏战亦睢盱。
未获遵平道，徒言信薄夫。','',''),('quantangshi-06594','赴冯翊作','儲光羲','quantangshi','','卷7','本自江海人，且无寥廓志。
大明耀天宇，霭霭风雨被。
迢递别荆吴，飘颻涉沂泗。
广川俟舟檝，峻坂伤骐骥。
蹭蹬失归道，崎岖从下位。
西出太华阴，北走少梁地。
葱茏墟落色，泱漭关河气。
耻从侠烈游，甘为刀笔吏。
宝劒茱萸匣，岂忘知音贵。
大道且泛然，沈浮未云异。','',''),('quantangshi-06595','晚霁中园喜赦作','儲光羲','quantangshi','','卷7','五月黄梅时，阴气蔽远迩。
浓云连晦朔，菰菜生隣里。
落日烧霞明，农夫知雨止。
几悲衽席湿，长叹垣墙毁。
曭朗天宇开，家族跃以喜。
涣汗发大号，坤元更资始。
散衣出中园，小径尚滑履。
池光摇万象，倏忽灭复起。
嘉树如我心，欣欣岂云已。','',''),('quantangshi-06596','观范阳递俘','儲光羲','quantangshi','','卷7','北河旄星陨，鬼方狝林胡。
羣师舞弓矢，电发归燕墟。
皇皇轩辕君，赞赞臯陶谟。
方思壮军实，远近递生俘。
车马践大逵，合沓成深渠。
牧人过橐駞，校正引騊駼。
烈风朝送寒，云雪霭天隅。
草木同一色，谁能辨荣枯。
四履封元戎，百金酬勇夫。
大邦武功爵，固与炎皇殊。','',''),('quantangshi-06597','次天元十载华阴发兵作时有郎官点发','儲光羲','quantangshi','','卷7','鬼方生猃狁，时寇卢龙营。
帝念霍嫖姚，诏发咸林兵。
天星下文阁，简师临我城。
三陌观勇夫，五饵谋长缨。
雷野大车发，震云灵鼓鸣。
太华色莽苍，清渭风交横。
胡马悲雨雪，诗人歌斾旌。
阏氏为女奴，单于作边氓。
神皇麒麟阁，大将不书名。','',''),('quantangshi-06598','送丘健至州敕放作时任下邽县','儲光羲','quantangshi','','卷7','太史登观台，天街耀旄头。
大君忽霆震，诏爵冠军侯。
南必梁孙源，西将圉昆丘。
河陇征击卒，虎符到我州。
朝集咸林城，师言乱啁啾。
杀气变木德，凛凛如高秋。
元戎启神皇，庙堂发嘉谋。
息兵业稼穑，归马复休牛。
和风开阴雪，大耀中天流。
欢声殷河岳，涵荡非烟浮。
邦牧新下车，德礼彼甿讴。
干坤日交泰，吾亦遂优游。','',''),('quantangshi-06599','登商丘','儲光羲','quantangshi','','卷7','河水日夜流，客心多殷忧。
维梢历宋国，结缆登商丘。
汉皇封子弟，周室命诸侯。
摇摇世祀怨，伤古复兼秋。
鸣鸿念极浦，征旅慕前俦。
太息梁王苑，时非牧马游。','',''),('quantangshi-06600','羣鸦咏','儲光羲','quantangshi','','卷7','新宫骊山阴，龙衮时出豫。
朝阳照羽仪，清吹肃逵路。
羣鸦随天车，夜满新丰树。
所思在腐余，不复忧霜露。
河低宫阁深，灯影鼓钟曙。
缤纷集寒枝，矫翼时相顾。
冢宰收琳琅，侍臣尽鸳鹭。
高举摩太清，永绝矰缴惧。
兹禽亦翱翔，不以微小故。','',''),('quantangshi-06601','尚书省受誓诫贻太庙裴丞','儲光羲','quantangshi','','卷7','皇家有恒宪，斋祭崇明祀。
严车伊洛间，受誓文昌里。
沈沈云阁见，稍稍城乌起。
曙色照衣冠，虚庭鸣劒履。
裴回念私觌，怅望临清汜。
点翰欲何言，相思从此始。','',''),('quantangshi-06602','夏日寻蓝田唐丞登高宴集','儲光羲','quantangshi','','卷7','东望春明门，驾言聊出游。
南行小径尽，绿竹临清流。
君出罢六安，居此澹忘忧。
园林与城市，闾里随人幽。
披颜辟衡闱，置酒登崇丘。
山河临咫尺，宇宙穷寸眸。
是时春载阳，佳气满皇州。
宫殿碧云里，鸳鸯初命俦。
良辰方在兹，志士安得休。
成名苟有地，何必东陵侯。','',''),('quantangshi-06603','田家即事答崔二东臯作四首 一','儲光羲','quantangshi','','卷7','玄鸟双双飞，杏林初发花。
喣偷命僮仆，可以树桑麻。
清旦理犂锄，日入未还家。','',''),('quantangshi-06604','田家即事答崔二东臯作四首 二','儲光羲','quantangshi','','卷7','有客山中至，言传故人讯。
荡漾敷远情，飘颻吐清韵。
猗欤春臯上，无乃成秋兴。','',''),('quantangshi-06605','田家即事答崔二东臯作四首 三','儲光羲','quantangshi','','卷7','念别求须臾，忽至嘤鸣时。
菜田烧故草，初树养新枝。
所寓非幽深，梦寐相追随。','',''),('quantangshi-06606','田家即事答崔二东臯作四首 四','儲光羲','quantangshi','','卷7','依依亲陇亩，寂寂无隣里。
不闻鸡犬音，日见和风起。
赖君遗掞藻，忧来散能弭。','',''),('quantangshi-06607','敬酬陈掾亲家翁秋夜有赠','儲光羲','quantangshi','','卷7','大姬配胡公，位乃三恪宾。
盛德百代祀，斯言良不泯。
敬仲为齐卿，当国名益震。
仲举登宰辅，太丘荣缙绅。
武皇受瑶图，爵士封其新。
繁祉既骤集，裔孙生贤臣。
特达逾圭璋，节操方松筠。
云汉一矫翼，天池三振鳞。
曳裾朝赤墀，酌醴侍紫宸。
大君锡车马，时复过平津。
言则广台阶，道亦资天均。
清秋忽高兴，震藻若有神。
曜曜趋宫廷，洸洸迈徐陈。
镐京既赐第，门巷交朱轮。
方将袭伊臯，永以崇夏殷。
宗党无远近，敬恭依仁人。
雪尽宇宙暄，雁归沧海春。
沈吟白华颂，帝闼降丝纶。
驿骑及芜城，相逢在郊鄄。
别离旷南北，谴谪罹苦辛。
昼游还荆吴，迷方客咸秦。
惟贤惠重义，男女期嘉姻。
梧桐生朝阳，鶗鴂鸣萧晨。
岂不畏时暮，坎壈无与邻。
中夜凉风来，顾我阙音尘。
琼瑶不遐弃，寤寐如日新。','',''),('quantangshi-06608','苏十三瞻登玉泉寺峰入寺中见赠作','儲光羲','quantangshi','','卷7','庆门叠华组，盛列钟英彦。
贞信发天姿，文明叶邦选。
为情贵深远，作德齐隐见。
别业在春山，怀归出芳甸。
逖听多时友，招邀及浮贱。
朝沿霸水穷，暮瞩蓝田徧。
百花照阡陌，万木森乡县。
涧净绿萝深，岩暄新鸟转。
依然造华薄，豁尔开灵院。
淹留火禁辰，愉乐弦歌宴。
肃肃列樽俎，锵锵引缨弁。
天籁激微风，阳光轹奔箭。
以兹小人腹，不胜君子馔。
是日既低迷，中宵方眄眩。
枕上思独往，胸中理交战。
碧云暗雨来，旧原芳色变。
欢然自此绝，心赏何由见。
鸿蒙已笑云，列缺仍挥电。
忽与去人远，俄逢归者便。
想像玉泉宫，依稀明月殿。
峰峦如登陟，水木以游衍。
息心幸自忘，点翰仍留眷。
恨无荆文璧，以答丹青绚。','',''),('quantangshi-06609','酬李处士山中见赠','儲光羲','quantangshi','','卷7','厥初游太学，相与极周旋。
含采共朝暮，知言同古先。
孟阳题劒阁，子云献甘泉。
斯须旷千里，婉娩将十年。
今来艳阳月，好鸟鸣翩翩。
同声既求友，不肖亦怀贤。
引领迟芳信，果枉瑶华篇。
成颂非其德，高文徒自妍。
声尘邈超越，比兴起孤绝。
始信郢中人，乃能歌白雪。
跂予北堂夜，摇笔酬明哲。
绿竹动清风，层轩静华月。
想像南山下，恬然谢朝列。
犹恐鶗鴂鸣，坐看芳草歇。
邀以青松色，同之白华洁。
永愿登龙门，相将持此节。','',''),('quantangshi-06610','同诸公秋日游昆明池思古','儲光羲','quantangshi','','卷7','仆人理车骑，西出金光逵。
苍苍白帝郊，我将游灵池。
太阴连晦朔，雨与天根违。
凄风披田原，横污益山陂。
农畯尽颠沛，顾望稼穑悲。
皇灵恻羣甿，神政张天维。
坤纪戮屏翳，元纲扶逶迤。
回塘清沧流，大曜悬金晖。
秋色浮浑沌，清光随涟漪。
豫章尽莓苔，柳杞成枯枝。
骤闻汉天子，征彼西南夷。
伐棘开洪渊，秉旄训我师。
震云灵鼍鼓，照水蛟龙旗。
锐士千万人，猛气如熊罴。
刑罚一以正，干戈自有仪。
坐作河汉倾，进退楼船飞。
羽发鸿雁落，桧动芙蓉披。
峨峨三云宫，肃肃振旅归。
恶德忽小丑，器用穷地赀。
上兵贵伐谋，此道不能为。
吁哉蒸人苦，始曰征伐非。
穆穆轩辕朝，耀德守方陲。
君臣日安闲，远近无怨思。
石鲸既蹭蹬，女牛亦流离。
獱獭游渚隅，葭芦生漘湄。
坎埳四十里，填淤今已微。
江伯方翱翔，天吴亟往来。
桑榆惨无色，伫立暮霏霏。
老幼樵木还，宾从回鞿羁。
帝梦鲜鱼索，明月当报时。','',''),('quantangshi-06611','同诸公登慈恩寺塔','儲光羲','quantangshi','','卷7','金祠起真宇，直上青云垂。
地静我亦闲，登之秋清时。
苍芜宜春苑，片碧昆明池。
谁道天汉高，逍遥方在兹。
虚形宾太极，携手行翠微。
雷雨傍杳冥，鬼神中躨跜。
灵变在倏忽，莫能穷天涯。
冠上阊阖开，履下鸿雁飞。
宫室低逦迤，羣山小参差。
俯仰宇宙空，庶随了义归。
崱屴非大厦，久居亦以危。','',''),('quantangshi-06612','同诸公秋霁曲江俯见南山','儲光羲','quantangshi','','卷7','天静终南高，俯暎江水明。
有若蓬莱下，浅深见澄瀛。
羣峰悬中流，石壁如瑶琼。
鱼龙隐苍翠，鸟兽游清泠。
菰蒲林下秋，薜荔波中轻。
山戛浴兰址，水若居云屏。
岚气浮渚宫，孤光随曜灵。
阴阴豫章馆，宛宛百花亭。
大君及羣臣，[宴]乐方嘤鸣。
吾党二三子，萧辰怡性情。
逍遥沧洲时，乃在长安城。','',''),('quantangshi-06613','同诸公送李云南伐蛮','儲光羲','quantangshi','','卷7','昆明滨滇池，蠢尔敢逆常。
天星耀鈇锧，吊彼西南方。
冢宰统元戎，太守齿军行。
囊括千万里，矢谟在庙堂。
耀耀金虎符，一息到炎荒。
搜兵自交趾，茇舍出泸阳。
羣山高崭岩，凌越如鸟翔。
封豕骤跧伏，巨象遥披攘。
回溪深天渊，揭厉逾舟梁。
玄武扫孤蜮，蛟龙除方良。
雷霆随神兵，硼磕动穹苍。
斩伐若草木，系缧同犬羊。
余丑隐弭河，啁啾乱行藏。
君子恶薄险，王师耻重伤。
广车设罝梁，太白收光芒。
边吏静县道，新书行纪纲。
劒关掉鞅归，武弁朝建章。
龙楼加命服，獬豸拥秋霜。
邦人颂灵旗，侧听何洋洋。
京观在七德，休哉我神皇。','',''),('quantangshi-06614','奉和韦判官献侍郎叔除河东采访使','儲光羲','quantangshi','','卷7','天卿小冢宰，道大名亦大。
丑正在权臣，建旟千里外。
楚山俯江汉，汴水连谯沛。
两持方伯圭，再转诸侯盖。
恬淡轻黜陟，优游邈千载。
干象变台衡，羣贤尽交泰。
聿徕股肱郡，河岳即襟带。
盛德滋冀方，仁风清汾浍。
四封尽高足，相府轺车最。
超超青云器，婉婉竹林会。
贱士敢知言，成颂文明代。
燕雀依大厦，期之保贞悔。','',''),('quantangshi-06615','同王十三维哭殷遥','儲光羲','quantangshi','','卷7','生理无不尽，念君在中年。
游道虽未深，举世莫能贤。
筮仕苦贫贱，为客少田园。
膏腴不可求，乃在许西偏。
四邻尽桑柘，咫尺开墙垣。
内艰未及虞，形影随化迁。
茅茨俯苫盖，双殡两楹间。
时闻孤女号，逈出陌与阡。
慈乌乱飞鸣，猛兽亦以跧。
故人王夫子，静念无生篇。
哀乐久已绝，闻之将泫然。
太阳蔽空虚，雨雪浮苍山。
迢遰亲灵榇，顾予悲绝弦。
处顺与安时，及此乃空言。','',''),('quantangshi-06616','贻丁主簿仙芝别','儲光羲','quantangshi','','卷7','赫赫明天子，翘翘羣秀才。
昭昭皇宇广，隐隐云门开。
摇曳君初起，联翩予复来。
兹年不得意，相命游灵台。
骅骝多逸气，琳琅有清响。
联行击水飞，独影凌虚上。
关河施芳听，江海徼新赏。
歛袵归故山，敷言播天壤。
云峰虽有异，楚越幸相亲。
既别复游处，道深情更殷。
下愚忝闻见，上德犹邅迍。
偃仰东城曲，栖迟依水滨。
脱巾从会府，结绶归海裔。
亲知送河门，邦族迎江澨。
夫子安恬淡，他人怅迢递。
飞艎既眇然，洲渚徒亏蔽。
人谋固无准，天德谅难知。
高名处下位，逸翮栖卑枝。
去去水中沚，摇摇天一涯。
蓬壶不可见，来泛跃龙池。','',''),('quantangshi-06617','京口送别王四谊','儲光羲','quantangshi','','卷7','江上枫林秋，江中秋水流。
清晨惜分袂，秋日尚同舟。
落潮洗鱼浦，倾荷枕驿楼。
明年菊花熟，洛东泛觞游。','',''),('quantangshi-06618','同房宪部应旋','儲光羲','quantangshi','','卷7','衡山法王子，慧见息诸苦。
落发自南州，燕居在西土。
养正不因晦，得中宁患旅。
旷然长虚闲，即理寄行补。
四句了自性，一音亦非取。
橘柚故园枝，随人植庭户。
我地少安住，念天时启处。
宪卿文昌归，愉悦来晤语。
车骑践香草，仆人沐花雨。
长风散繁云，万里静天宇。
起灭信易觉，清真知有所。
逍遥高殿阴，六月无炎暑。
微言发新偈，粲粲如悬圃。
直心视惠光，在此大法鼓。','',''),('quantangshi-06619','奉别长史庾公太守徐公应召','儲光羲','quantangshi','','卷7','烈风起江汉，白浪忽如山。
方伯骤勤王，杞人亦忧天。
酆镐顷霾晦，云龙召我贤。
车骑北艰苦，艅艎西溯沿。
水灵静湍濑，猛兽趋后先。
龙楼开新阳，万里出云间。
宇宙既焜耀，崇德济巨川。
受命在神宗，振兵犹轩辕。
煌煌逾涿鹿，穆穆更坤元。
明王朝太阶，远迩望嘉言。
游子淡何思，江湖将永年。','',''),('quantangshi-06620','狱中贻姚张薛李郑柳诸公','儲光羲','quantangshi','','卷7','直道时莫亲，起羞见谗口。
舆人是非怪，西子言有咎。
诬善不足悲，失听一何丑。
大来敢遐望，小往且虚受。
中夜囹圄深，初秋缧绁久。
疎萤出暗草，朔风鸣衰柳。
河汉低在户，蟏蛸垂向牖。
雁声远天末，凉气生霁后。
负户愁读书，劒光忿冲斗。
哀哀害神理，恻恻伤慈母。
妻子垂涕泣，家僮日奔走。
书词苦人吏，馈食劳交友。
寒服犹未成，繁霜渐将厚。
吉凶问詹尹，倚伏信北叟。
鬼哭知己冤，鸟言诚所诱。
诸公深惠爱，朝夕相左右。
束湿虽欲操，钩金庶无负。
伤罗念摇翮，踠足思骧首。
瑾瑜颇匿瑕，邦国方含垢。
眷言出深穽，永日常携手。','',''),('quantangshi-06621','贻鼓吹李丞时信安王北伐李公王之所器者也','儲光羲','quantangshi','','卷7','北伐昧天造，王师示有征。
辕门统元律，帝室命宗英。
灵威方首事，仗钺按边城。
膏雨被春草，黄云浮太清。
文儒托后乘，武旅趋前旌。
出车发西洛，营军临北平。
曰予深固陋，志气颇纵横。
尝思骠骑幕，愿逐嫖姚兵。
惟贤美无度，海内依扬声。
河间旧相许，车骑日逢迎。
折节下谋士，深心论客卿。
忠言虽未列，庶以知君诚。','',''),('quantangshi-06622','贻王侍御出台掾丹阳','儲光羲','quantangshi','','卷7','高高琅琊台，台下生箘簵。
照车十二乘，光彩不足谕。
既当少微星，复隐高山雾。
金丘华阳下，仙伯养晦处。
茅茨对三峰，梧桐开一路。
神溪绕臯陆，樵牧自成趣。
时登青冥游，若从天江度。
墟里献薇蕨，羣公致衣缕。
深沈复清净，偃仰视太素。
猛兽识宾仆，赬霞知早暮。
峨峨云龙开，忽有方伯遇。
达人无不可，壮志且驰骛。
融泄长鸡鸣，缤纷大鹏翥。
赤墀高崱屴，一见如三顾。
礼服正邦祀，刑冠肃王度。
三辰明昭代，光启玄元祚。
章台收杞梓，太液满鵷鹭。
丰泽耀纯仁，八方晏黔庶。
沈沈阊阖起，殷殷蓬莱曙。
旌戟俨成行，鸡人传发煦。
翔翼一如鹗，百辟莫不惧。
清庙奉烝尝，灵山扈銮辂。
天街时蹴鞠，直指宴梐枑。
四月纯阳初，雷雨始奋豫。
逆星孛皇极，鈇锧静天步。
酆镐舒曜灵，干戈藏武库。
析㯕增广运，直道有好恶。
廻迹清宪台，传骑东南去。
列城异畴昔，近饯寡徒御。
缠绵西关道，婉娈新丰树。
伊洛不敢息，淮河任沿溯。
乡亭茱萸津，先后非疏附。
炎时方怵惕，有若践霜露。
惆怅长岑长，寂寞梁王傅。
纷吾家延州，结友在童孺。
岑阳沐天德，邦邑持民务。
踯躅望朝阴，如何复沦误。
牙旷三千里，击辕非所慕。
秋涛联沧溟，舟檝凑北固。
江汜日绵眇，朝夕空寐寤。
中洞松栝新，东臯阡陌故。
余辉方焜耀，可以欢邑聚。
南华在濠上，谁辩魏王瓠。
登陟芙蓉楼，为我时一赋。','',''),('quantangshi-06623','贻刘高士别','儲光羲','quantangshi','','卷7','夙驾出东城，城傍早霞散。
初日照龙阙，峨峨在天半。
壮哉丽百常，美矣崇两观。
俯视趋朝客，簪佩何璀璨。
而我送将归，裴回霸陵岸。
北云去吴越，南雁离江汉。
伊昔蹈丘园，翩翩理文翰。
高谈闵仲叔，逸气刘公干。
每言竹柏贞，尝轻朝市玩。
山昼猿狖静，溪曛鱼鸟乱。
宁止卧崆峒，直云期汗漫。
圣君既理历，族士咸炳焕。
矫首来天池，振羽泛漪澜。
元淑命不达，伯鸾吟可叹。
东去姑苏台，乃过陟阳馆。
舍辔函关道，浮舟沧海畔。
耳目旷暄凉，怀抱盈悲惋。
沈沈青岁晚，霭霭秋云换。
自言永遁栖，无复从羁绊。
挥手谢知己，知己莫能赞。','',''),('quantangshi-06624','山中贻崔六琪华','儲光羲','quantangshi','','卷7','恍惚登高岭，裴回看落日。
遥想仲长园，如亲幼安室。
春渚菖蒲登，山中拨谷鸣。
相思不道远，太息未知情。
意君来此地，时复疎林薄。
中夜扫闲门，迎晨闭菌阁。
屣履清池上，家童奉信归。
忧随落花散，目送归云飞。
故交在天末，心知复千里。
无人暂往来，独作中林士。','',''),('quantangshi-06625','贻余处士','儲光羲','quantangshi','','卷7','故园至新浦，遥复未百里。
北望是他邦，纷吾即游士。
潮来津门启，罢楫信流水。
客意乃成欢，舟人亦相喜。
迟迟菱荇上，泛泛孤蒲里。
渐闻商旅喧，犹见凫鹥起。
市亭忽云构，方物如山峙。
吴王昔丧元，隋帝又灭祀。
停舻一以眺，太息兴亡理。
秋苑故池田，宫门新柳杞。
我行苦炎月，乃及清昊始。
此地日逢迎，终思隐君子。
莫言异舒卷，形音在心耳。','',''),('quantangshi-06626','刘先生闲居','儲光羲','quantangshi','','卷7','高第后归道，乃居玉华宫。
逍遥人间世，不异浮丘公。
甘寝何秉羽，出门忽从戎。
方将游昆仑，又欲小崆峒。
进退既在我，归来长安中。
焚香东海君，侍坐西山童。
善行无辙迹，吾亦安能穷。
但见神色闲，中心如虚空。
期之比天老，真德辅帝鸿。','',''),('quantangshi-06627','京口题崇上人山亭','儲光羲','quantangshi','','卷7','清旦历香岩，岩径纡复直。
花林开宿雾，游目清霄极。
分明窗户中，远近山川色。
金沙童子戏，香饭诸天食。
呌呌海鸿声，轩轩江燕翼。
寄言清静者，闾阎徒自踣。','',''),('quantangshi-06628','朝邑蔡主簿期不会二首 一','儲光羲','quantangshi','','卷7','下位日趋走，久之宾会疎。
空迟偶词赋，所愧比园庐。
朝念池上酌，暮逢林下书。
方将固封守，暂欲混畋渔。
衰柳隐长路，秋云满太虚。
遥遥望左右，日入未回车。','',''),('quantangshi-06629','朝邑蔡主簿期不会二首 二','儲光羲','quantangshi','','卷7','日入清风至，知君在西偏。
车舆既成列，宾仆复能贤。
迢递下墟坂，逍遥看井田。
苍山起暮雨，极浦浮长烟。
服义大如志，交欢数尽年。
宁言十余里，不见空来还。','',''),('quantangshi-06630','巩城南河作寄徐三景晖','儲光羲','quantangshi','','卷7','初年雨候迟，巩洛河流小。
摇摇芳草岸，屡见春山晓。
清露洗云林，轻波戏鱼鸟。
唯言故人远，不念乡川眇。
舟檝去潆廻，湍溆行奔峭。
寄书千里路，莫道南鸿少。','',''),('quantangshi-06631','贻阎处士防卜居终南','儲光羲','quantangshi','','卷7','春风摇杂树，言别还江汜。
坚冰生绿潭，又客三千里。
兆梦唯颜色，悬情乃文史。
涤耳贵清言，披欢迟玉趾。
秦城疑旧庐，伫立问焉如。
稚子跪而说，还山将隐居。
竹林既深远，松宇复清虚。
迹逈事多逸，心安趣有余。
石门动高韵，草堂新着书。
骞飞久超绝，蹇足空踌躇。
犹有昔时意，望君当照车。
驱车当六国，何以须潜默。
圣主常征贤，羣公每举德。
此时方独往，身志将何欲。
愿谢山中人，廻车首归躅。','',''),('quantangshi-06632','新丰作贻殷四校书','儲光羲','quantangshi','','卷7','汉皇思旧邑，秦地作新丰。
南出华阳路，西分长乐宫。
安知天地久，不与昔年同。
鸡犬暮声合，城池秋霁空。
纷吾从此去，望极咸阳中。
不见芸香阁，徒思文雅雄。','',''),('quantangshi-06633','华阳作贻祖三咏','儲光羲','quantangshi','','卷7','朝行敷水上，暮出华山东。
高馆宿初静，长亭秋转空。
日余久沦汨，重此闻霜风。
淅沥入溪树，飕飗惊夕鸿。
[凄]然望伊洛，如见息阳宫。
旧识无高位，新知尽固穷。
夫君独轻举，远近善文雄。
岂念千里驾，崎岖秦塞中。','',''),('quantangshi-06634','贻袁三拾遗谪作','儲光羲','quantangshi','','卷7','倾盖洛之滨，依然心事亲。
龙门何以峻，曾是好词人。
珥笔朝文陛，含章讽紫宸。
帝城多壮观，被服长如春。
天子俭为德，而能清约身。
公卿尽虚位，天下自趣尘。
如君物望美，令德声何已。
高帝黜儒生，文皇谪才子。
朝廷非不盛，谴谪良难恃。
路出大江阴，川行碧峰里。
斯言徒自玷，白玉岂为滓。
希声尽众人，深识唯知己。
知己怨生离，悠悠天一涯。
寸心因梦断，孤愤为年移。
花满芙蓉阙，春深朝夕池。
空令千万里，长望白云垂。','',''),('quantangshi-06635','洛中贻朝校书衡朝即日本人也','儲光羲','quantangshi','','卷7','万国朝天中，东隅道最长。
吾生美无度，高驾仕春坊。
出入蓬山里，逍遥伊水傍。
伯鸾游太学，中夜一相望。
落日悬高殿，秋风入洞房。
屡言相去远，不觉生朝光。','',''),('quantangshi-06636','贻崔太祝','儲光羲','quantangshi','','卷7','天都分礼阁，肃肃临清渠。
春山照前屏，高槐荫内除。
惟贤尚廪禄，弟去兄来居。
文雅更骧首，风流信有余。
中年幸从事，乃遇两吹嘘。
何以知君子，交情复淡如。','',''),('quantangshi-06637','贻王处士子文','儲光羲','quantangshi','','卷7','春草生洞渚，春风入上林。
春臯有黄鹤，抚翮未扬音。
王屋尝嘉遁，伊川复陆沈。
张弦鵾鸡弄，闭室蓬蒿深。
避地歌三乐，游山赋九吟。
大君思左右，无乃化黄金。','',''),('quantangshi-06638','献华阴罗丞别','儲光羲','quantangshi','','卷7','华山薄游者，玄发当青春。
道德同仙吏，尊卑即丈人。
县城俯京路，获见官舍里。
淹留琼树枝，谑浪春泉水。
昔余在天目，总角奉游从。
寒暑递来往，今复莲花峰。
别情无远近，道别方愁予。
孰想古人言，乃知悲风雨。','',''),('quantangshi-06639','闲居','儲光羲','quantangshi','','卷7','薄游何所愧，所愧在闲居。
亲故不来往，中园时读书。
步栏滴余雪，春塘抽新蒲。
梧桐渐覆井，时鸟自相呼。
悠然念故乡，乃在天一隅。
安得如浮云，来往方须臾。','',''),('quantangshi-06640','送恂上人还吴','儲光羲','quantangshi','','卷7','洛城本天邑，洛水即天池。
君王既行幸，法子复来仪。
虚室香花满，清川杨柳棰。
乘闲道归去，远意谁能知。','',''),('quantangshi-06641','送周十一','儲光羲','quantangshi','','卷7','秋风陨羣木，众草下严霜。
复问子何如？自言之帝乡。
岂无亲所爱，将欲济时康。
握手别征驾，返悲岐路长。','',''),('quantangshi-06642','新丰主人','儲光羲','quantangshi','','卷7','新丰主人新酒熟，旧客还归旧堂宿。
满酌香含北砌花，盈尊色泛南轩竹。
云散天高秋月明，东家少女解秦筝。
醉来忘却巴陵道，梦中疑是洛阳城。','',''),('quantangshi-06643','登戏马台作','儲光羲','quantangshi','','卷7','君不见宋公仗钺诛燕后，英雄踊跃争趋走。
小会衣冠吕梁壑，大征甲卒碻磝口。
天门神武树元勋，九日茱萸飨六军。
泛泛楼船游极浦，摇摇歌吹动浮云。
居人满目市朝变，覇业犹存齐楚甸。
泗水南流桐柏川，沂山北走琅琊县。
沧海沈沈晨雾开，彭城烈烈秋风来。
少年自古未得意，日暮萧条登古台。','',''),('quantangshi-06644','贻从军行','儲光羲','quantangshi','','卷7','取胜小非用，来朝明光殿，东平不足先。
梦出凤林间，梦还沧海阙。
万里尽阴色，岂为我离别。
马上吹笛起寒风，道傍舞劒飞春雪。
男儿悬弧非一日，君去成高节。','',''),('quantangshi-06645','酬李壶关奉使行县忆诸公','儲光羲','quantangshi','','卷7','青枫江上沧浪吟，白月宫中鹦鹉林。
非有净清心，同道同房若断金。
离居忽有云山意，清韵遥转舟檝事。
去时能忆竹园游，来时莫忘桃园记。','',''),('quantangshi-06646','蔷薇','儲光羲','quantangshi','','卷7','袅袅长数寻，青青不作林。
一茎独秀当庭心，数枝分作满庭阴。
春日迟迟欲将半，庭影离离正堪玩。
枝上莺娇不畏人，叶底蛾飞自相乱。
秦家女儿爱芳菲，画眉相伴采葳蕤。
高处红须欲就手，低边绿刺已牵衣。
蒲萄架上朝光满，杨柳园中暝鸟飞。
连袂踏歌从此去，风吹香气逐人归。','',''),('quantangshi-06647','同张侍御宴北楼','儲光羲','quantangshi','','卷7','今之太守古诸侯，出入双旌垂七旒。
朝览干戈时听讼，暮延宾客复登楼。
西山漠漠崦嵫色，北渚沈沈江汉流。
良宵清净方高会，绣服光辉联皂盖。
鱼龙恍惚堦墀下，云雾杳冥窗户外。
水灵慷慨行泣珠，游女飘颻思解佩。
苍苍低月半遥城，落落疎星满太清。
不分开襟悲楚奏，愿言吹笛退胡兵。
轩后青丘埋䝟貐，周王白羽扫欃枪。
期君武节朝龙阙，余亦翱翔归玉京。','',''),('quantangshi-06648','临江亭五咏 一','儲光羲','quantangshi','','卷7','晋家南作帝，京镇北为关。
江水中分地，城楼下带山。
金陵事已往，青盖理无还。
落日空亭上，愁看龙尾湾。','',''),('quantangshi-06649','临江亭五咏 二','儲光羲','quantangshi','','卷7','山横小苑前，路尽大江边。
此地兴王业，无如宋主贤。
潮生建业水，风散广陵烟。
直望[清]波里，秪言别有天。','',''),('quantangshi-06650','临江亭五咏 三','儲光羲','quantangshi','','卷7','城头落暮晖，城外捣秋衣。
江水青云挹，芦花白雪飞。
南州王气疾，东国海风微。','',''),('quantangshi-06651','临江亭五咏 四','儲光羲','quantangshi','','卷7','古木啸寒禽，层城带夕阴。
梁园多绿柳，楚岸尽枫林。
山际空为险，江流长自深。
平生何以恨，天地本无心。','',''),('quantangshi-06652','临江亭五咏 五','儲光羲','quantangshi','','卷7','京山千里过，孤愤望中来。
江势将天合，城门向水开。
落霞明楚岸，夕露湿吴台。','',''),('quantangshi-06653','饯张七琚任宗城即环之季也同产八人俱以才名知','儲光羲','quantangshi','','卷7','他日曾游魏，魏家余趾存。
可怜宫殿所，但见桑榆繁。
此去拜新职，为荣近故园。
高阳八才子，况复在君门。','',''),('quantangshi-06654','留别安庆李太守','儲光羲','quantangshi','','卷7','明牧念行子，又言悲解携。
初筵方落日，醉止到鸣鸡。
过客来自北，大军居在西。
兵家如讨逆，敢以庶盘溪。','',''),('quantangshi-06655','洛阳东门送别','儲光羲','quantangshi','','卷7','东城别故人，腊月迟芳辰。
不惜孤舟去，其如两地春。
花明洛阳苑，水绿小平津。
是日不相见，莺声徒自新。','',''),('quantangshi-06656','汉阳即事','儲光羲','quantangshi','','卷7','楚国千里远，孰知方寸违。
春游欢有客，夕寝赋无衣。
江水带冰绿，桃花随雨飞。
九歌有深意，捐佩乃言归。','',''),('quantangshi-06657','泊江潭贻马校书','儲光羲','quantangshi','','卷7','明月挂青天，遥遥如目前。
故人游画阁，却望似云边。
水宿依渔父，歌声好采莲。
采莲江上曲，今夕为君传。','',''),('quantangshi-06658','送沈校书吴中搜书','儲光羲','quantangshi','','卷7','郊外亭臯远，野中岐路分。
苑门临渭水，山翠杂春云。
秦阁多遗典，吴台访阙文。
君王思校理，莫滞清江濆。','',''),('quantangshi-06659','寒夜江口泊舟','儲光羲','quantangshi','','卷7','寒潮信未起，出浦缆孤舟。
一夜苦风浪，自然增旅愁。
吴山迟海月，楚火照江流。
欲有知音者，异乡谁可求。','',''),('quantangshi-06660','苑外至龙兴院作','儲光羲','quantangshi','','卷7','朝游天苑外，忽见法筵开。
山势当空出，云阴满地来。
疎钟清月殿，幽梵静花台。
日暮香林下，飘飘仙步回。','',''),('quantangshi-06661','题虬上人房','儲光羲','quantangshi','','卷7','禅宫分两地，释子一为心。
入道无来去，清言见古今。
江寒池水绿，山[暝]竹园深。
别有中天月，遥遥散夕阴。','',''),('quantangshi-06662','咏山泉','儲光羲','quantangshi','','卷7','山中有流水，借问不知名。
映地为天色，飞空作雨声。
转来深涧满，分出小池平。
恬澹无人见，年年长自清。','',''),('quantangshi-06663','贻主客吕郎中','儲光羲','quantangshi','','卷7','上士既开天，中朝为得贤。
青云方羽翼，画省比神仙。
委佩云霄里，含香日月前。
君王傥借问，客有上林篇。','',''),('quantangshi-06664','京口留别徐大补阙赵二零陵','儲光羲','quantangshi','','卷7','皇州月初晓，处处鼓钟喧。
树出蓬莱殿，城开阊阖门。
近臣朝琐闼，词客向文园。
独有三川路，空伤游子魂。','',''),('quantangshi-06665','答王十三维','儲光羲','quantangshi','','卷7','门生故来往，知欲命浮觞。
忽奉朝青阁，回车入上阳。
落花满春水，疎柳映新塘。
是日归来暮，劳君奏雅章。','',''),('quantangshi-06666','奉和中书徐侍郎中书省玩白云寄頴阳赵大','儲光羲','quantangshi','','卷7','青阙朝初退，白云遥在天。
非关取雷雨，故欲伴神仙。
泛滟鵷池曲，飘颻琐闼前。
犹多远山意，幸入侍臣篇。','',''),('quantangshi-06667','和张太祝冬祭马步','儲光羲','quantangshi','','卷7','故坛何肃肃，中野自无喧。
烈火见陈信，扬言闻永存。
房星隐曙色，朔风动寒原。
今日歌天马，非关征大宛。','',''),('quantangshi-06668','祭风伯坛应张太祝作','儲光羲','quantangshi','','卷7','圣主御青春，纶言命使臣。
将修风伯祀，更福太平人。
帟幕宵联事，坛场晓降神。
帝心矜动物，非为属车人。','',''),('quantangshi-06669','寻徐山人遇马舍人','儲光羲','quantangshi','','卷7','泊舟伊川右，正见野人归。
日暮春山绿，我心清且微。
岩声风雨度，水气云霞飞。
复有金门客，来参萝薜衣。','',''),('quantangshi-06670','夜观妓','儲光羲','quantangshi','','卷7','白雪宜新舞，清宵召楚妃。
娇童携锦荐，侍女整罗衣。
花映垂鬟转，香迎步履飞。
徐徐歛长袖，双烛送将归。','',''),('quantangshi-06671','洛桥送别','儲光羲','quantangshi','','卷7','河桥送客舟，河水正安流。
远见轻桡动，遥怜故国游。
海禽逢早雁，江月值新秋。
一听南津曲，分明散别愁。','',''),('quantangshi-06672','秦中送人觐省','儲光羲','quantangshi','','卷7','二月清江外，遥遥饯故人。
南山晴有雪，东陌霁无尘。
骑别章台晚，舟行洛水春。
知君梁苑去，日见白华新。','',''),('quantangshi-06673','洛中送人还江东','儲光羲','quantangshi','','卷7','洛城春雨霁，相送下江乡。
树绿天津道，山明伊水阳。
孤舟从此去，客思一何长。
直望清波里，唯余落日光。','',''),('quantangshi-06674','送姚六昆客任会稽何大蹇任孟县','儲光羲','quantangshi','','卷7','越城临渤澥，晋国在河汾。
仙绶两乡意，青郊一路分。
野棠春未发，田雀暮成羣。
他日思吴会，尝因西北云。','',''),('quantangshi-06675','洛潭送人觐省','儲光羲','quantangshi','','卷7','清洛带芝田，东流入大川。
舟轻水复急，别望杳如仙。
细草生春岸，明霞散早天。
送君唯一曲，当是白华篇。','',''),('quantangshi-06676','送人随大夫和蕃','儲光羲','quantangshi','','卷7','西方有六国，国国愿来宾。
圣主今无外，怀柔遣使臣。
大夫开幕府，才子作行人。
解劒聊相送，边城二月春。','',''),('quantangshi-06677','仲夏饯魏四河北觐叔','儲光羲','quantangshi','','卷7','落日临御沟，送君还北州。
树凉征马去，路暝归人愁。
吴岳夏云尽，渭河秋水流。
东篱摘芳菊，想见竹林游。','',''),('quantangshi-06678','送人寻裴斐','儲光羲','quantangshi','','卷7','柱史回清宪，谪居临汉川。
迟君千里驾，方外赏云泉。
路断因春水，山深隔暝烟。
湘江见游女，寄摘一枝莲。','',''),('quantangshi-06679','陇头水送别','儲光羲','quantangshi','','卷7','相送陇山头，东西陇水流。
从来心胆盛，今日为君愁。
暗雪迷征路，寒云隐戍楼。
唯余旌斾影，相逐去悠悠。','',''),('quantangshi-06680','送王上人还襄阳','儲光羲','quantangshi','','卷7','朝看法云散，知有至人还。
送客临伊水，行车出故关。
天花满南国，精舍在空山。
虽复时来去，中心长日闲。','',''),('quantangshi-06681','官庄池观竞渡','儲光羲','quantangshi','','卷7','落日吹箫管，清池发棹歌。
船争先后渡，岸激去来波。
水叶藏鱼鸟，林花间绮罗。
踟蹰仙女处，犹似望天河。','',''),('quantangshi-06682','重寄虬上人','儲光羲','quantangshi','','卷7','一作云峰别，三看花柳朝。
青山隔远路，明月空长霄。
鹊浴西江雨，鸡鸣东海潮。
此情劳梦寐，况道双林遥。','',''),('quantangshi-06683','蓝上茅茨期王维补阙','儲光羲','quantangshi','','卷7','山中人不见，云去夕阳过。
浅濑寒鱼少，丛兰秋蝶多。
老年疎世事，幽性乐天和。
酒熟思才子，溪头望玉珂。','',''),('quantangshi-06684','大酺得长字韵时任安宜尉','儲光羲','quantangshi','','卷7','大道启元命，时人居太康。
中朝发玄泽，下国被天光。
明诏始端午，初筵当履霜。
鼓鼙迎爽气，羽龠映新阳。
太守即悬圃，淮夷成葆疆。
小臣慙下位，拜手颂灵长。','',''),('quantangshi-06685','同张侍御鼎和京兆萧兵曹华岁晚南园','儲光羲','quantangshi','','卷7','公府传休沐，私庭效陆沈。
方知从大隐，非复在幽林。
阙下忠贞志，人间孝友心。
既将冠盖雅，仍与薜萝深。
寒变中园柳，春归上苑禽。
池涵青草色，山带白云阴。
潘岳闲居赋，钟期流水琴。
一经当自足，何用遗黄金。','',''),('quantangshi-06686','奉酬张五丈垂赠','儲光羲','quantangshi','','卷7','彩服去江汜，白云生大梁。
星辰动异色，羔雁成新行。
日望天朝近，时忧郢路长。
情言间薖轴，惠念及沧浪。
松柏以之茂，江湖亦自忘。
贾生方吊屈，岂敢比南昌。','',''),('quantangshi-06687','秦中守岁','儲光羲','quantangshi','','卷7','众星已穷次，青帝方行春。
永感易成戚，离居难重陈。
阖门守初夜，燎火到清晨。
或念无生法，多伤未出尘。
广庭日将晏，虚室自为宾。
愿以桑榆末，常逢甲子新。','',''),('quantangshi-06688','献高使君大酺作','儲光羲','quantangshi','','卷7','肃穆郊禋毕，工歌赏事并。
三朝遵湛露，一道洽仁明。
布德言皆应，无为物自成。
花添罗绮色，莺乱管弦声。
独有同高唱，空陪乐太平。','',''),('quantangshi-06689','荥阳马氏二子','儲光羲','quantangshi','','卷7','圣君封太岳，十月建行旃。
辇路开千里，寒云霁九天。
故人多侍从，二子留伊川。
河兖冰初合，关城月屡圆。
暝过荥水上，闻说郑卿贤。
材蔽行人右，名居东里先。
制岩开别业，桑柘亦依然。
待至金园侧，相将居一廛。','',''),('quantangshi-06690','观竞渡','儲光羲','quantangshi','','卷7','大夫沈楚水，千祀国人哀。
习棹江流长，迎神雨雾开。
标随绿云动，船逆清波来。
下怖鱼龙起，上惊凫雁回。
能令秋大有，鼓吹远相催。','',''),('quantangshi-06691','太学贻张筠','儲光羲','quantangshi','','卷7','璧池忝门子，俄顷变炎凉。
绿竹深虚馆，清流响洞房。
园林在建业，新友去咸阳。
中夜鼓钟静，初秋漏刻长。
浮云开太室，华盖上明堂。
空此远相望，劳歌还自伤。','',''),('quantangshi-06692','田家即事','儲光羲','quantangshi','','卷7','桑柘悠悠水蘸堤，晚风晴景不妨犂。
高机犹织卧蚕子，下坂饥逢饷饁妻。
杏色满林羊酪熟，麦凉浮壠雉媒低。
生时乐死皆由命，事在皇天志不迷。','',''),('quantangshi-06693','洛阳道五首献吕四郎中 一','儲光羲','quantangshi','','卷7','洛水春冰开，洛城春水绿。
朝看大道上，落花乱马足。','',''),('quantangshi-06694','洛阳道五首献吕四郎中 二','儲光羲','quantangshi','','卷7','剧孟不知名，千金买宝剑/。
出入平津邸，自言娇且艳。','',''),('quantangshi-06695','洛阳道五首献吕四郎中 三','儲光羲','quantangshi','','卷7','大道直如发，春日佳气多。
五陵贵公子，双双鸣玉珂。','',''),('quantangshi-06696','洛阳道五首献吕四郎中 四','儲光羲','quantangshi','','卷7','春风二月时，道傍柳堪把。
上枝覆官阁，下枝覆车马。','',''),('quantangshi-06697','洛阳道五首献吕四郎中 五','儲光羲','quantangshi','','卷7','洛水照千门，千门碧空里。
少年不得志，走马游新市。','',''),('quantangshi-06698','同武平一员外游湖','儲光羲','quantangshi','','卷7','竹吹留歌扇，莲香入舞衣。
前溪多曲溆，乘兴莫先归。','',''),('quantangshi-06699','长安道 一','儲光羲','quantangshi','','卷7','鸣鞭过酒肆，袨服游倡门。
百万一时尽，含情无片言。','',''),('quantangshi-06700','长安道 二','儲光羲','quantangshi','','卷7','西行一千里，暝色生寒树。
暗闻歌吹声，知是长安路。','',''),('quantangshi-06701','江南曲四首 一','儲光羲','quantangshi','','卷7','绿江深见底，高浪直翻空。
惯是湖边住，舟轻不畏风。','',''),('quantangshi-06702','江南曲四首 二','儲光羲','quantangshi','','卷7','逐流牵荇叶，绿岸摘芦苗。
为惜鸳鸯鸟，轻轻动画桡。','',''),('quantangshi-06703','江南曲四首 三','儲光羲','quantangshi','','卷7','日暮长江里，相邀归渡头。
落花如有意，来去逐船流。','',''),('quantangshi-06704','江南曲四首 四','儲光羲','quantangshi','','卷7','隔江看树色，沿月听歌声。
不是长干住，那从此路行。','',''),('quantangshi-06705','关山月','儲光羲','quantangshi','','卷7','一雁过连营，繁霜覆古城。
胡笳在何处？半夜起边声。','',''),('quantangshi-06706','玉真公主山居','儲光羲','quantangshi','','卷7','山北天泉苑，山西凤女家。
不言沁园好，独隐武陵花。','',''),('quantangshi-06707','沧浪峡','儲光羲','quantangshi','','卷7','沧浪临古道，道上若成尘。
自有沧浪峡，谁为无事人。','',''),('quantangshi-06708','奉真观','儲光羲','quantangshi','','卷7','真门逈向北，驰道直向西。
为与天光近，云色成虹霓。','',''),('quantangshi-06709','明妃曲四首 一','儲光羲','quantangshi','','卷7','西行陇上泣胡天，南向云中指渭川。
毳幕夜来时宛转，何由得似汉王边。','',''),('quantangshi-06710','明妃曲四首 二','儲光羲','quantangshi','','卷7','胡王知妾不胜悲，乐府皆传汉国辞。
朝来马上箜篌引，稍似宫中闲夜时。','',''),('quantangshi-06711','明妃曲四首 三','儲光羲','quantangshi','','卷7','日暮惊沙乱雪飞，傍人相劝易罗衣。
强来前殿看歌舞，共待单于夜猎归。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-06712','明妃曲四首 四','儲光羲','quantangshi','','卷7','彩骑双双引宝车，羌笛两两奏胡笳。
若为别得横桥路，莫隐宫中玉树花。','',''),('quantangshi-06713','同武平一员外游湖五首时武贬金坛令 一','儲光羲','quantangshi','','卷7','红荷碧筱夜相鲜，皂盖兰桡浮翠筵。
舟中对舞邯郸曲，月下双弹卢女弦。','',''),('quantangshi-06714','同武平一员外游湖五首时武贬金坛令 二','儲光羲','quantangshi','','卷7','青林碧屿暗相期，缓楫挥觥欲赋诗。
借问高歌凡几转，河低月落五更时。','',''),('quantangshi-06715','同武平一员外游湖五首时武贬金坛令 三','儲光羲','quantangshi','','卷7','朝来仙阁听弦歌，暝入花亭见绮罗。
池边命酒怜风月，浦口回船惜芰荷。','',''),('quantangshi-06716','同武平一员外游湖五首时武贬金坛令 四','儲光羲','quantangshi','','卷7','朦胧竹影蔽岩扉，淡荡荷风飘舞衣。
舟寻绿水宵将半，月隐青林人未归。','',''),('quantangshi-06717','同武平一员外游湖五首时武贬金坛令 五','儲光羲','quantangshi','','卷7','花潭竹屿傍幽蹊，画檝浮空入夜溪。
芰荷覆水船难进，歌舞留人月易低。','',''),('quantangshi-06718','题茅山华阳洞','儲光羲','quantangshi','','卷7','华阳洞口片云飞，细雨蒙蒙欲湿衣。
玉箫遍满仙坛上，应是茅家兄弟归。','',''),('quantangshi-06719','寄孙山人','儲光羲','quantangshi','','卷7','新林二月孤舟还，水满清江花满山。
借问故园隐君子，时时来往住人间。','',''),('quantangshi-06720','变行路难','王昌齡','quantangshi','','卷7','向晚横吹悲，风动马嘶合。
前趋引旗节，千里阵云帀。
单于下阴山，砂砾空飒飒。
封侯取一战，岂复念闺合。','',''),('quantangshi-06721','塞下曲四首 一','王昌齡','quantangshi','','卷7','蝉鸣空桑林，八月萧关道。
出塞入塞寒，处处黄芦草。
从来幽并客，皆共尘沙老。
莫学游侠儿，矜夸紫骝好。','',''),('quantangshi-06722','塞下曲四首 二','王昌齡','quantangshi','','卷7','饮马渡秋水，水寒风似刀。
平沙日未没，黯黯见临洮。
昔日长城战，咸言意气高。
黄尘足今古，白骨乱蓬蒿。','',''),('quantangshi-06723','塞下曲四首 三','王昌齡','quantangshi','','卷7','奉诏甘泉宫，总征天下兵。
朝廷备礼出，郡国豫郊迎。
纷纷几万人，去者无全生。
臣愿节宫廐，分以赐边城。','',''),('quantangshi-06724','塞下曲四首 四','王昌齡','quantangshi','','卷7','边头何惨惨，已葬霍将军。
部曲皆相吊，燕南代北闻。
功勋多被黜，兵马亦寻分。
更遣黄龙戍，唯当哭塞云。','',''),('quantangshi-06725','塞上曲','王昌齡','quantangshi','','卷7','秋风夜渡河，吹却雁门桑。
遥见胡地猎，鞲马宿严霜。
五道分兵去，孤军百战场。
功多翻下狱，士卒但心伤。','',''),('quantangshi-06726','从军行二首 一','王昌齡','quantangshi','','卷7','向夕临大荒，朔风轸归虑。
平沙万里余，飞鸟宿何处？
虏骑猎长原，翩翩傍河去。
边声摇白草，海气生黄雾。
百战苦风尘，十年履霜露。
虽投定远笔，未坐将军树。
早知行路难，悔不理章句。','',''),('quantangshi-06727','从军行二首 二','王昌齡','quantangshi','','卷7','秋草马蹄轻，角弓持弦急。
去为龙城战，正值胡兵袭。
军气横大荒，战酣日将入。
长风金鼓动，白露铁衣湿。
四起愁边声，南庭时伫立。
断蓬孤自转，寒雁飞相及。
万里云沙涨，平原冰霰涩。
惟闻汉使还，独向刀环泣。','',''),('quantangshi-06728','少年行二首 一','王昌齡','quantangshi','','卷7','西陵侠少年，送客短长亭。
青槐夹两道，白马如流星。
闻道羽书急，单于寇井陉。
气高轻赴难，谁顾燕山铭。','',''),('quantangshi-06729','少年行二首 二','王昌齡','quantangshi','','卷7','走马远相寻，西楼下夕阴。
结交期一劒，留意赠千金。
高阁歌声远，重门柳色深。
夜阑须尽饮，莫负百年心。','',''),('quantangshi-06730','长歌行','王昌齡','quantangshi','','卷7','旷野饶悲风，飕飕黄蒿草。
系马倚白杨，谁知我怀抱。
所是同袍者，相逢尽衰老。
北登汉家陵，南望长安道。
下有枯树根，上有鼯鼠窠。
高皇子孙尽，千载无人过。
宝玉频发掘，精灵其奈何？
人生须达命，有酒且长歌。','',''),('quantangshi-06731','悲哉行','王昌齡','quantangshi','','卷7','勿听白头吟，人间易忧怨。
若非沧浪子，安得从所愿。
北上太行山，临风阅吹万。
长云数千里，倏忽还肤寸。
观其微灭时，精意莫能论。
百年不容息，是处生意蔓。
始悟海上人，辞君永飞遯。','',''),('quantangshi-06732','古意','王昌齡','quantangshi','','卷7','桃花四面发，桃叶一枝开。
欲暮黄鹂啭，伤心玉镜台。
清筝向明月，半夜春风来。','',''),('quantangshi-06733','放歌行','王昌齡','quantangshi','','卷7','南渡洛阳津，西望十二楼。
明堂坐天子，月朔朝诸侯。
清乐动千门，皇风被九州。
庆云从东来，泱漭抱日流。
升平贵论道，文墨将何求？
有诏征草泽，微诚将献谋。
冠冕如星罗，拜揖曹与周。
望尘非吾事，入赋且迟留。
幸蒙国士识，因脱负薪裘。
今者放歌行，以慰梁甫愁。
但营数斗禄，奉养每丰羞。
若得金膏遂，飞云亦何俦。','',''),('quantangshi-06734','越女','王昌齡','quantangshi','','卷7','越女作桂舟，还将桂为楫。
湖上水渺漫，清江不可涉。
摘取芙蓉花，莫摘芙蓉叶。
将归问夫壻，颜色何如妾。','',''),('quantangshi-06735','郑县宿陶太公馆中赠冯六元二','王昌齡','quantangshi','','卷7','儒有轻王侯，脱略当事务。
本家蓝田下，非为渔弋故。
无何困躬耕，且欲驰永路。
幽居与君近，出谷同所骛。
昨日辞石门，五年变秋露。
云龙未相感，干谒亦已屡。
子为黄绶羁，余忝蓬山顾。
京门望西岳，百里见郊树。
飞雨祠上来，霭然关中暮。
驱车郑城宿，秉烛论往素。
山月出华阴，开此河渚雾。
清光比故人，豁达展心晤。
冯公尚戢翼，元子仍局步。
拂衣易为高，沦迹难有趣。
张范善终始，吾等岂不慕。
罢酒当凉风，屈伸备冥数。','',''),('quantangshi-06736','听弹风入松阕赠杨补阙','王昌齡','quantangshi','','卷7','商风入我弦，夜竹深有露。
弦悲与林寂，清景不可度。
寥落幽居心，飕飗青松树。
松风吹草白，溪水寒日暮。
声意去复还，九变待一顾。
空山多雨雪，独立君始悟。','',''),('quantangshi-06737','缑氏尉沈兴宗置酒南溪留赠','王昌齡','quantangshi','','卷7','林色与溪古，深篁引幽翠。
山尊在渔舟，棹月情已醉。
始穷清源口，壑绝人境异。
春泉滴空崖，萌草拆阴地。
久之风榛寂，远闻樵声至。
海雁时独飞，永然沧洲意。
古时青冥客，灭迹沦一尉。
吾子踌躇心，岂其纷埃事。
缑峯信所克，济北余乃遂。
齐物意已会，息肩理犹未。
卷舒形性表，脱略贤哲议。
仲月期角巾，饭僧嵩阳寺。','',''),('quantangshi-06738','为张僓赠阎使臣','王昌齡','quantangshi','','卷7','哀哀献玉人，楚国同悲辛。
泣尽继以血，何由辨其真。
赖承琢磨惠，复使光辉新。
犹畏谗口疾，弃之如埃尘。','',''),('quantangshi-06739','赠史昭','王昌齡','quantangshi','','卷7','东林月未升，廓落星与汉。
是夕鸿始来，斋中起长叹。
怀哉望南浦，眇然夜将半。
但有秋水声，愁使心神乱。
握中何为赠，瑶草已衰散。
海鳞未化时，各在天一岸。','',''),('quantangshi-06740','秋山寄陈谠言','王昌齡','quantangshi','','卷7','岩间寒事早，众山木已黄。
北风何萧萧，兹夕露为霜。
感激未能寐，中宵时慨慷。
黄虫初悲鸣，玄鸟去我梁。
独卧时易晚，离羣情更伤。
思君若不及，鸿雁今南翔。','',''),('quantangshi-06741','出郴山口至叠石湾野人室中寄张十一','王昌齡','quantangshi','','卷7','槠柟无冬春，柯叶连峯稠。
阴壁下苍黑，烟含清江楼。
景开独沿曳，响答随兴酬。
旦夕望吾友，如何迅孤舟。
叠沙积为岗，崩剥雨露幽。
石脉尽横亘，潜潭何时流。
既见万古色，颇尽一物由。
永与世人远，气还草木收。
盈缩理无余，今往何必忧。
郴土羣山高，耆老如中州。
孰云议舛降，岂是娱宦游。
阴火昔所伏，丹砂将尔谋。
昨临苏耽井，复向衡阳求。
同疚来相依，脱身当有筹。
数月乃离居，风湍成阻修。
野人善竹器，童子能溪讴。
寒夜波荡漾，羇鸿去悠悠。','',''),('quantangshi-06742','宿灞上寄侍御璵弟','王昌齡','quantangshi','','卷7','独饮灞上亭，寒山青门外。
长云骤落日，桑枣寂已晦。
古人驱驰者，宿此凡几代。
佐邑由东南，岂不知进退。
吾宗秉全璞，楚得璆琳最。
茅山就一征，柏署起三载。
道契非物理，神交无留碍。
知我沧溟心，脱略腐儒辈。
孟冬銮舆出，阳谷羣臣会。
半夜驰道喧，五侯拥轩盖。
是时燕齐客，献术蓬瀛内。
甚悦我皇心，得与王母对。
贱臣欲干谒，稽首期殒碎。
哲弟感我情，问易穷否泰。
良马足尚踠，宝刀光未淬。
昨闻羽书飞，兵气连朔塞。
诸将多失律，庙堂始追悔。
安能召书生，愿得论要害。
戎夷非草木，侵逐使狼狈。
虽有屠城功，亦有降虏辈。
兵粮如山积，恩泽如雨霈。
羸卒不可兴，碛地无足爱。
若用匹夫策，坐令军围溃。
不费黄金资，宁求白璧赉。
明主忧既远，边事亦可大。
荷宠务推诚，离言深慷慨。
霜摇直指草，烛引明光佩。
公论日夕阻，朝廷磋跎会。
孤城海门月，万里流光带。
不应百尺松，空老钟山霭。','',''),('quantangshi-06743','次汝中寄河南陈赞府','王昌齡','quantangshi','','卷7','汝山方联延，伊水才明灭。
遥见入楚云，又此空馆月。
纷然驰梦想，不谓远离别。
京邑多欢娱，衡湘蹔沿越。
明湖春草遍，秋桂白花发。
岂惟长思君，日夕在魏阙。','',''),('quantangshi-06744','同从弟销南斋玩月忆山阴崔少府','王昌齡','quantangshi','','卷7','高卧南斋时，开帷月初吐。
清辉淡水木，演漾在窗户。
苒苒几盈虚，澄澄变今古。
美人清江畔，是夜越吟苦。
千里其如何，微风吹兰杜。','',''),('quantangshi-06745','代扶风主人答','王昌齡','quantangshi','','卷7','杀气凝不流，风悲日彩寒。
浮埃起四远，游子弥不欢。
依然宿扶风，沽酒聊自宽。
寸心亦未理，长铗谁能弹。
主人就我饮，对我还慨叹。
便泣数行泪，因歌行路难。
十五役边地，三回讨楼兰。
连年不解甲，积日无所餐。
将军降匈奴，国使没桑干。
去时三十万，独自还长安。
不信沙场苦，君看刀箭瘢。
乡亲悉零落，冢墓亦摧残。
仰攀青松枝，恸绝伤心肝。
禽兽悲不去，路傍谁忍看。
幸逢休明代，寰宇静波澜。
老马思伏枥，长鸣力已殚。
少年与运会，何事发悲端。
天子初封禅，贤良刷羽翰。
三边悉如此，否泰亦须观。','',''),('quantangshi-06746','酬鸿胪裴主簿雨后北楼见赠','王昌齡','quantangshi','','卷7','暮霞照新晴，归云犹相逐。
有怀晨昏暇，想见登眺目。
问礼侍彤襜，题诗访茅屋。
高楼多古今，陈事满陵谷。
地久微子封，台余孝王筑。
裴回顾霄汉，豁达俯川陆。
远水对孤城，长天向乔木。
公门何清静，列戟森已肃。
不叹携手稀，常思着鞭速。
终当拂羽翰，轻举随鸿鹄。','',''),('quantangshi-06747','送任五之桂林','王昌齡','quantangshi','','卷7','楚客醉孤舟，越水将引棹。
山为两乡别，月带千里貌。
羇谴同缯纶，僻幽闻虎豹。
桂林寒色在，苦节知所效。','',''),('quantangshi-06748','山中别庞十','王昌齡','quantangshi','','卷7','幽娟松筱径，月出寒蝉鸣。
散发卧其下，谁知孤隐情。
吟时白云合，钓处玄潭清。
琼树方杳霭，凤兮保其贞。','',''),('quantangshi-06749','留别伊阙张少府郭大都尉','王昌齡','quantangshi','','卷7','迁客就一醉，主人空金罍。
江湖青山底，欲去仍裴回。
郭侯未相识，策马伊川来。
把手相劝勉，不应老尘埃。
孟阳逢山旧，仙馆留清才。
日晚劝趣别，风长云逐开。
幸随板舆远，负谴何忧哉。
唯有仗忠信，音书报云雷。','',''),('quantangshi-06750','送韦十二兵曹','王昌齡','quantangshi','','卷7','县职如长缨，终日检我身。
平明趋郡府，不得展故人。
故人念江湖，富贵如埃尘。
迹在戎府掾，心游天台春。
独立浦边鹤，白云长相亲。
南风忽至吴，分散还入秦。
寒夜天光白，海净月色真。
对坐论岁暮，弦悲岂无因。
平生驰驱分，非谓杯酒仁。
出处两不合，忠贞何由伸。
看君孤舟去，且欲歌垂纶。','',''),('quantangshi-06751','东京府县诸公与綦毋潜李颀相送至白马寺宿','王昌齡','quantangshi','','卷7','鞍马上东门，裴回入孤舟。
贤豪相追送，即棹千里流。
赤岸落日在，空波微烟收。
薄宦忘机括，醉来即淹留。
月明见古寺，林外登高楼。
南风开长廊，夏夜如凉秋。
江月照吴县，西归梦中游。','',''),('quantangshi-06752','送东林廉上人归庐山','王昌齡','quantangshi','','卷7','石溪流已乱，苔径人渐微。
日暮东林下，山僧还独归。
昔为庐峰意，况与远公违。
道性深寂寞，世情多是非。
会寻名山去，岂复望清辉。','',''),('quantangshi-06753','留别武陵袁丞','王昌齡','quantangshi','','卷7','皇恩暂迁谪，待罪逢知己。
从此武陵溪，孤舟二千里。
桃花遗古岸，金涧流春水。
谁识马将军，忠贞抱生死。','',''),('quantangshi-06754','别刘谞','王昌齡','quantangshi','','卷7','天地寒更雨，苍茫楚城阴。
一尊广陵酒，十载衡阳心。
倚仗不可料，悲欢岂易寻。
相逢成远别，后会何如今。
身在江海上，云连京国深。
行当务功业，策马何骎骎。','',''),('quantangshi-06755','岳阳别李十七越宾','王昌齡','quantangshi','','卷7','相逢楚水寒，舟在洞庭驿。
具陈江波事，不异沦弃迹。
杉上秋雨声，悲切蒹葭夕。
弹琴收余响，来送千里客。
平明孤帆心，岁晚济代策。
时在身未充，潇湘不盈画。
湖小洲渚联，澹淡烟景碧。
鱼鳖自有性，龟龙无能易。
谴黜同所安，风土任所适。
闭门观玄化，携手遗损益。','',''),('quantangshi-06756','留别岑参兄弟','王昌齡','quantangshi','','卷7','江城建业楼，山尽沧海头。
副职守兹县，东南棹孤舟。
长安故人宅，秣马经前秋。
便以风雪暮，还为纵饮留。
貂蝉七叶贵，鸿鹄万里游。
何必念钟鼎，所在烹肥牛。
为君啸一曲，且莫弹箜篌。
徒见枯者艳，谁言直如钩。
岑家双琼树，腾光难为俦。
谁言青门悲，俯期吴山幽。
日西石门峤，月吐金陵洲。
追随探灵怪，岂不骄王侯。','',''),('quantangshi-06757','送刘眘虚归取宏词解','王昌齡','quantangshi','','卷7','太清闻海鹤，游子引乡眄。
声随羽仪远，势与归云便。
青桂春再荣，白云暮来变。
迁飞在礼仪，岂复泪如霰。','',''),('quantangshi-06758','巴陵别刘处士','王昌齡','quantangshi','','卷7','刘生隐岳阳，心远洞庭水。
偃帆入山郭，一宿楚云里。
竹映秋馆深，月寒江风起。
烟波桂阳接，日夕数千里。
袅袅清夜猿，孤舟坐如此。
湘中有来雁，雨雪候音旨。','',''),('quantangshi-06759','宿裴氏山庄','王昌齡','quantangshi','','卷7','苍苍竹林暮，吾亦知所投。
静坐山斋月，清溪闻远流。
西峰下微雨，向晓白云收。
遂解尘中组，终南春可游。','',''),('quantangshi-06760','淇上酬薛据兼寄郭微','王昌齡','quantangshi','','卷7','自从别京华，我心乃萧索。
十年守章句，万里空寥落。
北上登蓟门，茫茫见沙漠。
倚劒对风尘，慨然思衞霍。
拂衣去燕赵，驱马怅不乐。
天长沧洲路，日暮邯郸郭。
酒肆或淹留，渔泽屡栖泊。
独行备艰难，孰辞千鼎镬。
皇情念淳古，时俗何浮薄。
理道须任贤，安人在求瘼。
故交负奇才，逸气包謇谔。
隐轸经济策，纵横建安作。
才望忽先鸣，风期无宿诺。
飘颻劳州县，迢递限言谑。
东驰眇贝丘，西顾弥虢略。
淇水徒自深，浮云不堪托。
吾谋适可用，天道岂辽廓。
不然买山田，一身与耕凿。','',''),('quantangshi-06761','咏史','王昌齡','quantangshi','','卷7','荷畚至洛阳，杖策游北门。
天下尽兵甲，豺狼满中原。
明夷方遘患，顾我徒崩犇。
自慙菲薄才，误蒙国士恩。
位重任亦重，时危志弥敦。
西北未及终，东南不可吞。
进则耻保躬，退乃为触藩。
叹息嵩山老，而后知其尊。','',''),('quantangshi-06762','杂兴','王昌齡','quantangshi','','卷7','握中铜匕首，粉锉楚山铁。
义士频报雠，杀人不曾缺。
可悲燕丹事，终被狼虎灭。
一举无两全，荆轲遂为血。
诚知匹夫勇，何取万人杰。
无道吞诸侯，坐见九州裂。','',''),('quantangshi-06763','秋兴','王昌齡','quantangshi','','卷7','日暮西北堂，凉风洗修木。
着书在南窗，门馆常肃肃。
苔草延古意，视听转幽独。
或问余所营，刈黍就寒谷。','',''),('quantangshi-06764','斋心','王昌齡','quantangshi','','卷7','女萝覆石壁，溪水幽蒙胧。
紫葛蔓黄花，娟娟寒露中。
朝饮花上露，夜卧松下风。
云英化为水，光采与我同。
日月荡精魄，寥寥天宇空。','',''),('quantangshi-06765','独游','王昌齡','quantangshi','','卷7','林卧情每闲，独游景常晏。
时从灞陵下，垂钓往南涧。
手携双鲤鱼，目送千里雁。
悟彼飞有适，知此罹忧患。
放之清冷泉，因得省疎慢。
永怀青岑客，廻首白云间。
神超物无违，岂系名与宦。','',''),('quantangshi-06766','香积寺礼拜万廻平等二圣僧塔','王昌齡','quantangshi','','卷7','真无御化来，借有乘化归。
如彼双塔内，孰能知是非。
愚也骇苍生，圣哉为帝师。
当为时世出，不由天地资。
万廻主此方，平等性无违。
今我一礼心，亿劫同不移。
肃肃松柏下，诸天来有时。','',''),('quantangshi-06767','就道士问周易参同契','王昌齡','quantangshi','','卷7','仙人骑白鹿，发短耳何长。
时余采菖蒲，忽见嵩之阳。
稽首求丹经，乃出怀中方。
披读了不悟，归来问嵇康。
嗟余无道骨，发我入太行。','',''),('quantangshi-06768','诸官游招隐寺','王昌齡','quantangshi','','卷7','山馆人已空，青萝换风雨。
自从永明世，月向龙宫吐。
凿井长幽泉，白云今如古。
应真坐松柏，锡杖挂窗户。
口云七十余，能救诸有苦。
回指岩树花，如闻道场鼓。
金色身壤灭，真如性无主。
僚友同一心，清光遣谁取。','',''),('quantangshi-06769','宴南亭','王昌齡','quantangshi','','卷7','寒江暎村林，亭上纳鲜洁。
楚客共闲饮，静坐金管阕。
酣竟日入山，暝来云归穴。
城楼空杳霭，猿鸟备清切。
物状如丝纶，上心为予决。
访君东溪事，早晚樵路绝。','',''),('quantangshi-06770','何九于客舍集','王昌齡','quantangshi','','卷7','客有住桂阳，亦如巢林鸟。
罍觞且终宴，功业曾未了。
山月空霁时，江明高楼晓。
门前泊舟檝，行次入松筱。
此意投赠君，沧波风褭褭。','',''),('quantangshi-06771','洛阳尉刘晏与府掾诸公茶集天宫寺岸道上人房','王昌齡','quantangshi','','卷7','良友呼我宿，月明悬天宫。
道安风尘外，洒扫青林中。
削去府县理，豁然神机空。
自从三湘还，始得今夕同。
旧居太行北，远宦沧溟东。
各有四方事，白云处处通。','',''),('quantangshi-06772','观江淮名胜图','王昌齡','quantangshi','','卷7','刻意吟云山，尤知隐沦妙。
远公何为者，再诣临海峤。
而我高其风，披图得遗照。
援毫无逃境，遂展千里眺。
淡扫荆门烟，明标赤城烧。
青葱林间岭，隐见淮海徼。
但指香炉顶，无闻白猿啸。
沙门既云灭，独往岂殊调。
感对怀拂衣，胡宁事渔钓。
安期始遗舃，千古谢荣耀。
投迹庶可齐，沧浪有孤棹。','',''),('quantangshi-06773','灞上闲居','王昌齡','quantangshi','','卷7','鸿都有归客，偃卧滋阳村。
轩冕无枉顾，清川照我门。
空林网夕阳，寒鸟赴荒园。
廓落时得意，怀哉莫与言。
庭前有孤鹤，欲啄常翩翻。
为我衔素书，吊彼颜与原。
二君既不朽，所以慰其魂。','',''),('quantangshi-06774','风凉原上作','王昌齡','quantangshi','','卷7','阴岑宿云归，烟雾湿松柏。
风凄日初晓，下岭望川泽。
远山无晦明，秋水千里白。
佳气盘未央，圣人在凝碧。
关门阻天下，信是帝王宅。
海内方晏然，庙堂有奇策。
时贞守全运，罢去游说客。
予忝兰台人，幽寻免贻责。','',''),('quantangshi-06775','裴六书堂','王昌齡','quantangshi','','卷7','闲堂闭空阴，竹林但清响。
窗下长啸客，区中无遗想。
经纶精微言，兼济当独往。','',''),('quantangshi-06776','江上闻笛','王昌齡','quantangshi','','卷7','横笛怨江月，扁舟何处寻。
声长楚山外，曲绕胡关深。
相去万余里，遥传此夜心。
寥寥浦溆寒，响尽惟幽林。
不知谁家子，复奏邯郸音。
水客皆拥棹，空霜遂盈襟。
羸马望北走，迁人悲越吟。
何当边草白，旌节陇城阴。','',''),('quantangshi-06777','太湖秋夕','王昌齡','quantangshi','','卷7','水宿烟雨寒，洞庭霜落微。
月明移舟去，夜静魂梦归。
暗觉海风度，萧萧闻雁飞。','',''),('quantangshi-06778','赵十四兄见访','王昌齡','quantangshi','','卷7','客来舒长簟，开合延清风。
但有无弦琴，共君尽尊中。
晚来常读易，顷者欲还嵩。
世事何须道，黄精且养蒙。
嵇康殊寡识，张翰独知终。
忽忆鲈鱼鲙，扁舟往江东。','',''),('quantangshi-06779','过华阴','王昌齡','quantangshi','','卷7','云起太华山，云山互明灭。
东峯始含景，了了见松雪。
羇人感幽栖，窅暎转奇绝。
欣然忘所疲，永望吟不辍。
信宿百余里，出关玩新月。
何意昨来心，遇物遂迁别。
人生屡如此，何以肆愉悦。','',''),('quantangshi-06780','九江口作','王昌齡','quantangshi','','卷7','漭漭江势阔，雨开浔阳秋。
驿门是高岸，望尽黄芦洲。
水与五溪合，心期万里游。
明时无弃才，谪去随孤舟。
鸷鸟立寒木，丈夫佩吴钩。
何当报君恩，却系单于头。','',''),('quantangshi-06781','大梁途中作','王昌齡','quantangshi','','卷7','怏怏步长道，客行渺无端。
郊原欲下雪，天地棱棱寒。
当时每酣醉，不觉行路难。
今日无酒钱，凄惶向谁叹。','',''),('quantangshi-06782','途中作','王昌齡','quantangshi','','卷7','游人愁岁晏，早起遵王畿。
坠叶吹未晓，疎林月微微。
惊禽栖不定，寒兽相因依。
叹此霜露下，复闻鸿雁飞。
渺然江南意，惜与中途违。
羇旅悲壮发，别离念征衣。
永图岂劳止，明节期所归。
宁厌楚山曲，无人长掩扉。','',''),('quantangshi-06783','山行入泾州','王昌齡','quantangshi','','卷7','倦此山路长，停骖问宾御。
林峦信回惑，白日落何处。
徙倚望长风，滔滔引归虑。
微雨随云收，蒙蒙傍山去。
西临有边邑，北走尽亭戍。
泾水横白烟，州城隐寒树。
所嗟异风俗，已自少情趣。
岂伊怀土多，触目忻所遇。','',''),('quantangshi-06784','小敷谷龙潭祠作','王昌齡','quantangshi','','卷7','崖谷歕疾流，地中有雷集。
百泉势相荡，巨石皆却立。
跳波沸峥嵘，深处不可挹。
昏为蛟龙怒，清见云雨入。
灵怪祟偏祠，废兴自兹邑。
沈淫顷多昧，檐宇遂不葺。
吾闻被明典，盛德惟世及。
生人载山川，血食报原隰。
岂伊骇微险，将以循甿揖。
口飞振吕梁，忠信亦我习。
波流浸已广，悔吝在所汲。
溪水有清源，褰裳靡沾湿。','',''),('quantangshi-06785','段宥廰孤桐','王昌齡','quantangshi','','卷7','凤皇所宿处，月暎孤桐寒。
槁叶零落尽，空柯苍翠残。
虚心谁能见，直影非无端。
响发调尚苦，清商劳一弹。','',''),('quantangshi-06786','琴','王昌齡','quantangshi','','卷7','孤桐秘虚鸣，朴素传幽真。
仿髴弦指外，遂见初古人。
意远风雪苦，时来江山春。
高宴未终曲，谁能辨经纶。','',''),('quantangshi-06787','初日','王昌齡','quantangshi','','卷7','初日净金闺，先照牀前暖。
斜光入罗幕，稍稍亲丝管。
云发不能梳，杨花更吹满。','',''),('quantangshi-06788','失题','王昌齡','quantangshi','','卷7','奸雄乃得志，遂使羣心摇。
赤风荡中原，烈火无遗巢。
一人计不用，万里空萧条。','',''),('quantangshi-06789','赠宇文中丞','王昌齡','quantangshi','','卷7','仆本濩落人，辱当州郡使。
量力颇及早，谢归今即已。
萧萧若凌虚，衿带顷消靡。
车服卒然来，涔阳作游子。
郁郁寡开颜，默默独行李。
忽逢平生友，一笑方在此。
秋清宁风日，楚思浩云水。
为语弋林者，冥冥鸿远矣。','',''),('quantangshi-06790','箜篌引','王昌齡','quantangshi','','卷7','卢溪郡南夜泊舟，夜闻两岸羌戎讴。
其时月黑猿啾啾，微雨霑衣令人愁。
有一迁客登高楼，不言不寐弹箜篌。
弹作蓟门桑叶秋，风沙飒飒青冢头。
将军铁骢汗血流，深入匈奴战未休。
黄旗一点兵马收，乱杀胡人积如丘。
疮病驱来配边州，仍披漠北羔羊裘。
颜色饥枯掩面羞，眼眶泪滴深两眸。
思还本乡食牦牛，欲语不得指咽喉。
或有强壮能吚嚘，意说被他边将雠。
五世属藩汉主留，碧毛毡帐河曲游。
橐駞五万部落稠，勅赐飞凤金兜鍪。
为君百战如过筹，静扫阴山无鸟投。
家藏铁券特承优，黄金千斤不称求。
九族分离作楚囚，深溪寂寞弦苦幽。
草木悲感声飕飗，仆本东山为国忧。
明光殿前论九畴，簏读兵书尽冥搜。
为君掌上施权谋，洞晓山川无与俦。
紫宸诏发远怀柔，摇笔飞霜如夺钩。
鬼神不得知其由，怜爱苍生比蚍蜉。
朔河屯兵须渐抽，尽遣降来拜御沟。','',''),('quantangshi-06791','乌栖曲','王昌齡','quantangshi','','卷7','白马逐朱车，黄昏入狭邪。
柳树乌争宿，争枝未得飞上屋。
东房少妇壻从军，每听乌啼知夜分。','',''),('quantangshi-06792','城傍曲','王昌齡','quantangshi','','卷7','秋风鸣桑条，草白狐兔骄。
邯郸饮来酒未消，城北原平掣皂雕。
射杀空营两腾虎，廻身却月佩弓弰。','',''),('quantangshi-06793','行路难','王昌齡','quantangshi','','卷7','双丝作绠系银瓶，百尺寒泉辘轳上。
悬丝一绝不可望，似妾倾心在君掌。
人生意气好迁捐，只重狂花不重贤。
宴罢调筝奏离鹤，廻娇转盼泣君前。
君不见眼前事，岂保须臾心勿异。
西山日下雨足稀，侧有浮云无所寄。
但愿莫忘前者言，锉骨黄尘亦无愧。
行路难，劝君酒，莫辞烦，美酒千钟犹可尽，心中片愧何可论。
一闻汉主思故剑，使妾长嗟万古魂。','',''),('quantangshi-06794','奉赠张荆州','王昌齡','quantangshi','','卷7','祝融之峯紫云衔，翠如何其雪崭嵓。
邑西有路缘石壁，我欲从之卧穹嵌。
鱼有心兮脱网罟，江无人兮鸣枫杉。
王君飞舄仍未去，苏耽宅中意遥缄。','',''),('quantangshi-06795','驾出长安','王昌齡','quantangshi','','卷7','圣德超千古，皇风扇九围。
天廻万象出，驾动六龙飞。
淑气来黄道，祥云覆紫微。
太平多扈从，文物有光辉。','',''),('quantangshi-06796','驾幸河东','王昌齡','quantangshi','','卷7','晋水千庐合，汾桥万国从。
开唐天业盛，入沛圣恩浓。
下辇廻三象，题碑任六龙。
睿明悬日月，千岁此时逢。','',''),('quantangshi-06797','胡笳曲','王昌齡','quantangshi','','卷7','城南虏已合，一夜几重围。
自有金笳引，能霑出塞衣。
听临关月苦，清入海风微。
三奏高楼晓，胡人掩涕归。','',''),('quantangshi-06798','潞府客亭寄崔凤童','王昌齡','quantangshi','','卷7','萧条郡城闭，旅馆空寒烟。
秋月对愁客，山钟摇暮天。
新知偶相访，斗酒情依然。
一宿阻长会，清风徒满川。','',''),('quantangshi-06799','和振上人秋夜怀士会','王昌齡','quantangshi','','卷7','白露伤草木，山风吹夜寒。
遥林梦亲友，高兴发云端。
郭外秋声急，城边月色残。
瑶琴多远思，更为客中弹。','',''),('quantangshi-06800','送李擢游江东','王昌齡','quantangshi','','卷7','清洛日夜涨，微风引孤舟。
离肠便千里，远梦生江楼。
楚国橙橘暗，吴门烟雨愁。
东南具今古，归望山云秋。','',''),('quantangshi-06801','沙苑南渡头','王昌齡','quantangshi','','卷7','秋雾连云白，归心浦溆悬。
津人空守缆，村馆复临川。
篷隔苍茫雨，波连演漾田。','',''),('quantangshi-06802','客广陵','王昌齡','quantangshi','','卷7','楼头广陵近，九月在南徐。
秋色明海县，寒烟生里闾。
夜帆归楚客，昨日度江书。
为问易名叟，垂纶不见鱼。','',''),('quantangshi-06803','静法师东斋','王昌齡','quantangshi','','卷7','筑室在人境，遂得真隐情。
春尽草木变，雨来池馆清。
琴书全雅道，视听已无生。
闭户脱三界，白云自虚盈。','',''),('quantangshi-06804','素上人影塔','王昌齡','quantangshi','','卷7','物化同枯木，希夷明月珠。
本来生灭尽，何者是虚无。
一坐看如故，千龄独向隅。
至人非别有，方外不应殊。','',''),('quantangshi-06805','遇薛明府谒聪上人','王昌齡','quantangshi','','卷7','欣逢柏梁故，共谒聪公禅。
石室无人到，绳牀见虎眠。
阴崖常抱雪，枯涧为生泉。
出处虽云异，同欢在法筵。','',''),('quantangshi-06806','谒焦炼师','王昌齡','quantangshi','','卷7','中峯青苔壁，一点云生时。
岂意石堂里，得逢焦炼师。
炉香净琴案，松影闲瑶墀。
拜受长年药，翩翻西海期。','',''),('quantangshi-06807','宿京江口期刘昚虚不至','王昌齡','quantangshi','','卷7','霜天起长望，残月生海门。
风静夜潮满，城高寒气昏。
故人何寂寞，久已乖清言。
明发不能寐，徒盈江上尊。','',''),('quantangshi-06808','寒食即事','王昌齡','quantangshi','','卷7','晋阳寒食地，风俗旧来传。
雨灭龙蛇火，春生鸿雁天。
泣多流水涨，歌发舞云旋。
西见之推庙，空为人所怜。','',''),('quantangshi-06809','九日登高','王昌齡','quantangshi','','卷7','青山远近带皇州，霁景重阳上北楼。
雨歇亭臯仙菊润，霜飞天苑御梨秋。
茱萸插鬓花宜寿，翡翠横钗舞作愁。
谩说陶潜篱下醉，何曾得见此风流。','',''),('quantangshi-06810','万岁楼','王昌齡','quantangshi','','卷7','江上巍巍万岁楼，不知经历几千秋。
年年喜见山长在，日日悲看水独流。
猿狖何曾离暮岭，鸬鹚空自泛寒洲。
谁堪登望云烟里，向晚茫茫发旅愁。','',''),('quantangshi-06811','夏月花萼楼酺宴应制','王昌齡','quantangshi','','卷7','土德三元正，尧心万国同。
汾阴备冬礼，长乐应和风。
赐庆垂天泽，流欢旧渚宫。
楼台生海上，箫鼓出天中。
雾晓筵初接，宵长曲未终。
雨随青幕合，月照舞罗空。
玉陛分朝列，文章发圣聪。
愚臣忝书赋，歌咏颂丝桐。','',''),('quantangshi-06812','送欧阳会稽之任','王昌齡','quantangshi','','卷7','怀禄贵心赏，东流山水长。
官移会稽郡，地迩上虞乡。
缓带屏纷杂，渔舟临讼堂。
逶迤回溪趣，猿啸飞鸟行。
万室霁朝雨，千峰迎夕阳。
辉辉远洲暎，暧暧澄湖光。
白发有高士，青春期上皇。
应须枉车歇，为我访荷裳。','',''),('quantangshi-06813','同王维集青龙寺昙壁上人兄院五韵','王昌齡','quantangshi','','卷7','本来清净所，竹树引幽阴。
檐外含山翠，人间出世心。
圆通无有象，圣境不能侵。
真是吾兄法，何妨友弟深。
天香自然会，灵异识钟音。','',''),('quantangshi-06814','东溪翫月','王昌齡','quantangshi','','卷7','月从断山口，遥吐柴门端。
万木分空霁，流阴中夜攒。
光连虚象白，气与风露寒。
谷静秋泉响，岩深青霭残。
澄清入幽梦，破影抱空峦。
恍惚琴窗里，松溪晓思难。','',''),('quantangshi-06815','朝来曲','王昌齡','quantangshi','','卷7','月昃鸣珂动，花连绣户春。
盘龙玉台镜，唯待画眉人。','',''),('quantangshi-06816','从军行','王昌齡','quantangshi','','卷7','大将军出战，白日暗榆关。
三面黄金甲，单于破胆还。','',''),('quantangshi-06817','答武陵田太守','王昌齡','quantangshi','','卷7','仗劒行千里，微躯感一言。
曾为大梁客，不负信陵恩。','',''),('quantangshi-06818','题灞池二首 一','王昌齡','quantangshi','','卷7','腰镰欲何之，东园刈秋韭。
世事不复论，悲歌和樵叟。','',''),('quantangshi-06819','题灞池二首 二','王昌齡','quantangshi','','卷7','开门望长川，薄暮见渔者。
借问白头翁，垂纶几年也。','',''),('quantangshi-06820','题僧房','王昌齡','quantangshi','','卷7','椶榈花满院，苔藓入闲房。
彼此名言绝，空中闻异香。','',''),('quantangshi-06821','击磬老人','王昌齡','quantangshi','','卷7','双峰褐衣久，一磬白眉长。
谁识野人意，徒看春草芳。','',''),('quantangshi-06822','送胡大','王昌齡','quantangshi','','卷7','荆门不堪别，况乃潇湘秋。
何处遥望君，江边明月楼。','',''),('quantangshi-06823','送郭司仓','王昌齡','quantangshi','','卷7','暎门淮水绿，留骑主人心。
明月随良掾，春潮夜夜深。','',''),('quantangshi-06824','送李十五','王昌齡','quantangshi','','卷7','怨别秦楚深，江中秋云起。
天长杳无隔，月影在寒水。','',''),('quantangshi-06825','送张四','王昌齡','quantangshi','','卷7','枫林已愁暮，楚水复堪悲。
别后冷山月，清猿无断时。','',''),('quantangshi-06826','武陵田太守席送司马卢溪','王昌齡','quantangshi','','卷7','诸侯分楚郡，饮饯五溪春。
山水清晖远，俱怜一逐臣。','',''),('quantangshi-06827','送谭八之桂林','王昌齡','quantangshi','','卷7','客心仍在楚，江馆复临湘。
别意猿鸟外，天寒桂水长。','',''),('quantangshi-06828','送刘十五之郡','王昌齡','quantangshi','','卷7','平明江雾寒，客马江上发。
扁舟事洛阳，窅窅含楚月。','',''),('quantangshi-06829','从军行七首 一','王昌齡','quantangshi','','卷7','烽火城西百尺楼，黄昏独上海风秋。
更吹羌笛关山月，无那金闺万里愁。','',''),('quantangshi-06830','从军行七首 二','王昌齡','quantangshi','','卷7','琵琶起舞换新声，总是关山旧别情。
撩乱边愁听不尽，高高秋月照长城。','',''),('quantangshi-06831','从军行七首 三','王昌齡','quantangshi','','卷7','关城榆叶早疎黄，日暮云沙古战场。
表请回军掩尘骨，莫教兵士哭龙荒。','',''),('quantangshi-06832','从军行七首 四','王昌齡','quantangshi','','卷7','青海长云暗雪山，孤城遥望玉门关。
黄沙百战穿金甲，不破楼兰终不还。','',''),('quantangshi-06833','从军行七首 五','王昌齡','quantangshi','','卷7','大漠风尘日色昏，红旗半卷出辕门。
前军夜战洮河北，已报生擒吐谷浑。','',''),('quantangshi-06834','从军行七首 六','王昌齡','quantangshi','','卷7','胡瓶落膊紫薄汗，碎叶城西秋月团。
明敕星驰封宝劒，辞君一夜取楼兰。','',''),('quantangshi-06835','从军行七首 七','王昌齡','quantangshi','','卷7','玉门山嶂几千重，山北山南总是烽。
人依远戍须看火，马踏深山不见踪。','',''),('quantangshi-06836','出塞二首 一','王昌齡','quantangshi','','卷7','秦时明月汉时关，万里长征人未还。
但使龙城飞将在，不教胡马度阴山。','',''),('quantangshi-06837','出塞二首 二','王昌齡','quantangshi','','卷7','骝马新跨白玉鞍，战罢沙场月色寒。
城头铁鼓声犹振，匣里金刀血未干。','',''),('quantangshi-06838','采莲曲二首 一','王昌齡','quantangshi','','卷7','吴姬越艳楚王妃，争弄莲舟水湿衣。
来时浦口花迎入，采罢江头月送归。','',''),('quantangshi-06839','采莲曲二首 二','王昌齡','quantangshi','','卷7','荷叶罗裙一色裁，芙蓉向脸两边开。
乱入池中看不见，闻歌始觉有人来。','',''),('quantangshi-06840','殿前曲二首 一','王昌齡','quantangshi','','卷7','贵人妆梳殿前催，香风吹入殿后来。
仗引笙歌大宛马，白莲花发照池台。','',''),('quantangshi-06841','殿前曲二首 二','王昌齡','quantangshi','','卷7','胡部笙歌西殿头，梨园弟子和凉州。
新声一段高楼月，圣主千秋乐未休。','',''),('quantangshi-06842','春宫曲','王昌齡','quantangshi','','卷7','昨夜风开露井桃，未央前殿月轮高。
