斜抱云和深见月，朦胧树色隐昭阳。','',''),('quantangshi-06844','西宫秋怨','王昌齡','quantangshi','','卷7','芙蓉不及美人妆，水殿风来珠翠香。
谁分含啼掩秋扇，空悬明月待君王。','',''),('quantangshi-06845','长信秋词五首 一','王昌齡','quantangshi','','卷7','金井梧桐秋叶黄，珠帘不卷夜来霜。
熏笼玉枕无颜色，卧听南宫清漏长。','',''),('quantangshi-06846','长信秋词五首 二','王昌齡','quantangshi','','卷7','高殿秋砧响夜阑，霜深犹忆御衣寒。
银灯青琐裁缝歇，还向金城明主看。','',''),('quantangshi-06847','长信秋词五首 三','王昌齡','quantangshi','','卷7','奉帚平明金殿开，且将团扇暂裴回。
玉颜不及寒鸦色，犹带[昭]阳日影来。','',''),('quantangshi-06848','长信秋词五首 四','王昌齡','quantangshi','','卷7','真成薄命久寻思，梦见君王觉后疑。
