金章紫绶千余骑，夫壻朝回初拜侯。','',''),('quantangshi-06852','青楼怨','王昌齡','quantangshi','','卷7','香帏风动花入楼，高调鸣筝缓夜愁。
肠断关山不解说，依依残月下帘钩。','',''),('quantangshi-06853','浣纱女','王昌齡','quantangshi','','卷7','钱塘江边是谁家，江上女儿全胜花。
吴王在时不得出，今日公然来浣纱。','',''),('quantangshi-06854','闺怨','王昌齡','quantangshi','','卷7','闺中少妇不曾愁，春日凝妆上翠楼。
