INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-06878','送十五舅','王昌齡','quantangshi','','卷7','深林秋水近日空，归棹演漾清阴中。
