穷秋旷野行人绝，马首东来知是谁。','',''),('quantangshi-06897','题朱炼师山房','王昌齡','quantangshi','','卷7','叩齿焚香出世尘，斋坛鸣磬步虚人。
百花仙酝能留客，一饭胡麻度几春。','',''),('quantangshi-06898','武陵开元观黄炼师院三首 一','王昌齡','quantangshi','','卷7','松间白发黄尊师，童子烧香禹步时。
欲访桃源入溪路，忽闻鸡犬使人疑。','',''),('quantangshi-06899','武陵开元观黄炼师院三首 二','王昌齡','quantangshi','','卷7','先贤盛说桃花源，尘忝何堪武陵郡。
闻道秦时避地人，至今不与人通问。','',''),('quantangshi-06900','武陵开元观黄炼师院三首 三','王昌齡','quantangshi','','卷7','山观空虚清静门，从官役吏扰尘喧。
暂因问俗到真境，便欲投诚依道源。','',''),('quantangshi-06901','河上老人歌','王昌齡','quantangshi','','卷7','河上老人坐古槎，合丹只用青莲花。
至今八十如四十，口道沧溟是我家。','',''),('quantangshi-06902','春怨','王昌齡','quantangshi','','卷7','音书杜绝白狼西，桃李无颜黄鸟啼。
寒雁春深归去尽，出门肠断草萋萋。','',''),('quantangshi-06903','句','王昌齡','quantangshi','','卷7','朝荐抱良策，独倚江城楼。
昨从金陵邑，远谪沅溪滨。
娟魄已三孕。
驾幸温泉日，严霜子月初。
长亭酒未醒，千里风动地。
苍荻寒沧江，石头岸边饮。
天仗森森练雪凝，身骑铁骢自臂鹰。','',''),('quantangshi-06904','送陆擢','常建','quantangshi','','卷7','圣代多才俊，陆生何考盘。
南山高松树，不合空摧残。
九月湖上别，北风秋雨寒。
殷勤叹孤凤，早食金琅玕。','',''),('quantangshi-06905','送李十一尉临溪','常建','quantangshi','','卷7','泠泠花下琴，君唱渡江吟。
天际一帆影，预悬离别心。
以言神仙尉，因致瑶华音。
回轸抚商调，越溪澄碧林。','',''),('quantangshi-06906','江上琴兴','常建','quantangshi','','卷7','江上调玉琴，一弦清一心。
泠泠七弦遍，万木澄幽阴。
能使江月白，又令江水深。
始知梧桐枝，可以徽黄金。','',''),('quantangshi-06907','湖中晚霁','常建','quantangshi','','卷7','湖广舟自轻，江天欲澄霁。
是时清楚望，气色犹霾曀。
踟蹰金霞白，波上日初丽。
烟虹落镜中，树木生天际。
杳杳涯欲辨，蒙蒙云复闭。
言乘星汉明，又覩寰瀛势。
微兴从此惬，悠然不知岁。
试歌沧浪清，遂觉干坤细。
岂念客衣薄，将期永投袂。
迟回渔父间，一雁声嘹唳。','',''),('quantangshi-06908','宿王昌龄隐居','常建','quantangshi','','卷7','清溪深不测，隐处唯孤云。
松际露微月，清光犹为君。
茅亭宿花影，药院滋苔纹。
余亦谢时去，西山鸾鹤羣。','',''),('quantangshi-06909','送楚十少府','常建','quantangshi','','卷7','微风吹霜气，寒影明前除。
落日未能别，萧萧林木虚。
愁烟闭千里，仙尉其何如。
因送别鹤操，赠之双鲤鱼。
鲤鱼在金盘，别鹤哀有余。
心事则如此，请君开素书。','',''),('quantangshi-06910','张山人弹琴','常建','quantangshi','','卷7','君去芳草绿，西峰弹玉琴。
岂惟丘中赏，兼得清烦襟。
朝从山口还，出岭闻清音。
了然云霞气，照见天地心。
玄鹤下澄空，翩翩舞松林。
改弦扣商声，又听飞龙吟。
稍觉此身妄，渐知仙事深。
其将炼金鼎，永矣投吾簪。','',''),('quantangshi-06911','白湖寺后溪宿云门','常建','quantangshi','','卷7','落日山水清，乱流鸣淙淙。
旧蒲雨抽节，新花水对窓。
溪中日已没，归鸟多为双。
杉松引直路，出谷临前湖。
洲渚晚色静，又观花与蒲。
入溪复登岭，草浅寒流速。
圆月明高峰，春山因独宿。
松阴澄初夜，曙色分远目。
日出城南隅，青青媚川陆。
乱花覆东郭，碧气销长林。
四郊一清影，千里归寸心。
前瞻王程促，却恋云门深。
毕景有余兴，到家弹玉琴。','',''),('quantangshi-06912','闲斋卧病行药至山馆稍次湖亭二首 一','常建','quantangshi','','卷7','旬时结阴霖，帘外初白日。
斋沐清病容，心魂畏虚室。
闲梅照前户，明镜悲旧质。','',''),('quantangshi-06913','闲斋卧病行药至山馆稍次湖亭二首 二','常建','quantangshi','','卷7','行药至石壁，东风变萌芽。
主人门外绿，小隐湖中花。
时物堪独往，春帆宜别家。
辞君向沧海，烂熳从天涯。','',''),('quantangshi-06914','塞上曲','常建','quantangshi','','卷7','翩翩云中使，来问太原卒。
百战苦不归，刀头怨明月。
塞云随阵落，寒日傍城没。
城下有寡妻，哀哀哭枯骨。','',''),('quantangshi-06915','仙谷遇毛女意知是秦宫人','常建','quantangshi','','卷7','溪口水石浅，泠泠明药丛。
入溪双峰峻，松栝疎幽风。
垂岭枝袅袅，翳泉花蒙蒙。
夤缘霁人目，路尽心弥通。
盘石横阳崖，前流殊未穷。
回潭清云影，弥漫长天空。
水边一神女，千岁为玉童。
羽毛经汉代，珠翠逃秦宫。
目觌神已寓，鹤飞言未终。
祈君青云祕，愿谒黄仙翁。
尝以耕玉田，龙鸣西顶中。
金梯与天接，几日来相逢。','',''),('quantangshi-06916','梦太白西峰','常建','quantangshi','','卷7','梦寐升九崖，杳霭逢元君。
遗我太白峰，寥寥辞垢氛。
结宇在星汉，宴林闭氤氲。
檐楹覆余翠，巾舄生片云。
时往溪水间，孤亭昼仍曛。
松峰引天影，石濑清霞文。
恬目缓舟趣，霁心投鸟羣。
春风又摇棹，潭岛花纷纷。','',''),('quantangshi-06917','鄂渚招王昌龄张偾','常建','quantangshi','','卷7','刈芦旷野中，沙土飞黄云。
天晦无精光，茫茫悲远君。
楚山隔湘水，湖畔落日曛。
春雁又北飞，音书固难闻。
谪居未为叹，谗枉何由分。
午日逐蛟龙，宜为吊冤文。
翻覆古共然，名宦安足云。
贫士任枯槁，捕鱼清江濆。
有时荷鉏犂，旷野自耕耘。
不然春山隐，溪涧花氤氲。
山鹿自有场，贤达亦顾羣。
二贤归去来，世上徒纷纷。','',''),('quantangshi-06918','春词二首 一','常建','quantangshi','','卷7','菀菀黄柳丝，蒙蒙杂花垂。
日高红妆卧，倚对春光迟。
宁知傍淇水，騕褭黄金羁。','',''),('quantangshi-06919','春词二首 二','常建','quantangshi','','卷7','翳翳陌上桑，南枝交北堂。
美人金梯出，素手自提筐。
非但畏蚕饥，盈盈娇路傍。','',''),('quantangshi-06920','晦日马镫曲稍次中流作','常建','quantangshi','','卷7','夜寒宿芦苇，晓色明西林。
初日在川上，便澄游子心。
秦天无纤翳，郊野浮春阴。
波静随钓鱼，舟小绿水深。
出浦见千里，旷然谐远寻。
扣船应渔父，因唱沧浪吟。','',''),('quantangshi-06921','古意','常建','quantangshi','','卷7','牧马古道傍，道傍多古墓。
萧条愁杀人，蝉鸣白杨树。
回头望京邑，合沓生尘雾。
富贵安可常，归来保贞素。','',''),('quantangshi-06922','宿五度溪仙人得道处','常建','quantangshi','','卷7','五度溪上花，生根依两崖。
二月寻片云，愿宿秦人家。
上见悬崖崩，下见白水湍。
仙人弹碁处，石上青萝盘。
无处求玉童，翳翳唯林峦。
前溪遇新月，聊取玉琴弹。','',''),('quantangshi-06923','西山','常建','quantangshi','','卷7','一身为轻舟，落日西山际。
常随去帆影，远接长天势。
物象归余清，林峦分夕丽。
亭亭碧流暗，日入孤霞继。
渚日远阴映，湖云尚明霁。
林昏楚色来，岸远荆门闭。
至夜转清逈，萧萧北风厉。
沙边雁鹭泊，宿处蒹葭蔽。
圆月逗前浦，孤琴又摇曳。
泠然夜遂深，白露霑人袂。','',''),('quantangshi-06924','春词','常建','quantangshi','','卷7','阶下草犹短，墙头梨花白。
织女高楼上，停梭顾行客。
问君在何所，青鸟舒锦翮。','',''),('quantangshi-06925','赠三侍御','常建','quantangshi','','卷7','高山临大泽，正月芦花干。
阳色薰两崖，不改青松寒。
士贤守孤贞，古来皆共难。
明君错甚才，台上飞三鸾。
操与霜雪明，量与江海宽。
束身视天涯，安能穷波澜。
孤鹤在枳棘，一枝非所安。
逸翮望绝霄，见欲凌云端。
层台何其高，山石流洪湍。
固知非天池，鸣跃同所欢。
谁念独枯槁，四十长江干。
责躬贵知己，效拙从一官。
折翮悲高风，苦饥候朝飡。
湖月映大海，天空何漫漫。
托身未知所，谋道庶不刊。
吟彼乔木诗，一夕常三叹。','',''),('quantangshi-06926','第三峰','常建','quantangshi','','卷7','西山第三顶，茅宇依双松。
杳杳欲至天，云梯升几重。
莹魄澄玉虚，以求鸾鹤踪。
逶迤非天人，执节乘赤龙。
旁映白日光，缥缈轻霞容。
孤辉上烟雾，余影明心胸。
愿与黄麒麟，欲飞而莫从。
因寂清万象，轻云自中峰。
山暝学栖鸟，月来随暗蛬。
寻空静余响，袅袅云溪钟。','',''),('quantangshi-06927','古兴','常建','quantangshi','','卷7','汉上逢老翁，江口为僵尸。
白发沾黄泥，遗骸集乌鸱。
机巧自此忘，精魄今何之。
风吹钓竿折，鱼跃安能施。
白水明汀洲，菰蒲冒深陂。
唯留扁舟影，系在长江湄。
突兀枯松枝，悠扬女萝丝。
托身难凭依，生死焉相知。
徧观今时人，举世皆尔为。
将军死重围，汉卒犹争驰。
百马同一衔，万轮同一规。
名与身孰亲，君子宜固思。','',''),('quantangshi-06928','高楼夜弹筝','常建','quantangshi','','卷7','高楼百余尺，直上江水平。
明月照人苦，开帘弹玉筝。
山高猿狖急，天静鸿雁鸣。
曲度犹未终，东峰霞半生。','',''),('quantangshi-06929','客有自燕而归哀其老而赠之','常建','quantangshi','','卷7','羸马朝自燕，一身为二连。
忆亲拜孤冢，移葬双陵前。
幽愿从此毕，劒心因获全。
孟冬寒气盛，抚辔告言旋。
碣石海北门，余寇惟朝鲜。
离离一寒骑，袅袅驰白天。
生别皆自取，况为士卒先。
寸心渔阳兴，落日旌竿悬。','',''),('quantangshi-06930','白龙窟泛舟寄天台学道者','常建','quantangshi','','卷7','夕映翠山深，余晖在龙窟。
扁舟沧浪意，澹澹花影没。
西浮入天色，南望对云阙。
因忆莓苔峰，初阳濯玄发。
泉萝两幽映，松鹤间清越。
碧海莹子神，玉膏泽人骨。
忽然为枯木，微兴遂如兀。
应寂中有天，明心外无物。
环回从所泛，夜静犹不歇。
澹然意无限，身与波上月。','',''),('quantangshi-06931','张天师草堂','常建','quantangshi','','卷7','灵溪宴清宇，傍倚枯松根。
花药绕方丈，瀑泉飞至门。
四气闭炎热，两崖改明昏。
夜深月蹔皎，亭午朝始暾。
信是天人居，幽幽寂无喧。
万壑应鸣磬，诸峰接一魂。
遂登仙子谷，因醉田生樽。
时节开玉书，窅映飞天言。
心化便无影，目精焉累烦。
忽而与霄汉，寥落空南轩。','',''),('quantangshi-06932','古意三首 一','常建','quantangshi','','卷7','二妃方访舜，万里南方悬。
远道隔江汉，孤舟无岁年。
不知苍梧处，气尽呼青天。
愁泪变楚竹，蛾眉丧湘川。
后人立为庙，累世称其贤。
过客设祠祭，孤狸来坐边。
怀古未忍还，猿吟彻空山。','',''),('quantangshi-06933','古意三首 二','常建','quantangshi','','卷7','明月照高阁，彩女褰罗幕。
歌舞临碧云，箫声沸珠箔。
青鸾临南海，天上双白鹤。
万里齐翼飞，意求君门乐。
玉霄九重闭，金锁夜不开。
两翅自无力，愁鸣云外来。
态深入空贵，世屈无良媒。
俛仰顾中禁，东飞白玉台。','',''),('quantangshi-06934','古意三首 三','常建','quantangshi','','卷7','楚王竟何去，独自留巫山。
偏使世人见，迢迢江汉间。
驻舟春溪里，皆愿拜灵颜。
寤寐见神女，金沙鸣佩环。
闲艳绝世姿，令人气力微。
含笑竟不语，化作朝云飞。','',''),('quantangshi-06935','渔浦','常建','quantangshi','','卷7','春至百草绿，陂泽闻鸧鹒。
别家投钓翁，今世沧浪情。
沤紵为緼袍，折麻为长缨。
荣誉失本真，怪人浮此生。
碧水月自阔，安流净而平。
扁舟与天际，独往谁能名。','',''),('quantangshi-06936','空灵山应田叟','常建','quantangshi','','卷7','湖南无村落，山舍多黄茆。
淳朴如太古，其人居鸟巢。
牧童唱巴歌，野老亦献嘲。
泊舟问溪口，言语皆哑咬。
土俗不尚农，岂暇论肥硗。
莫傜射禽兽，浮客烹鱼鲛。
余亦罘罝人，获麋今尚苞。
敬君中国来，愿以充其庖。
日入闻虎鬬，空山满咆哮。
怀人虽共安，异域终难交。
白水可洗心，采薇可为肴。
曳策背落日，江风鸣梢梢。','',''),('quantangshi-06937','太公哀晚遇','常建','quantangshi','','卷7','日出渭流白，文王畋猎时。
钓翁在芦苇，川泽无熊罴。
诏书起遗贤，匹马令致辞。
因称江海人，臣老筋力衰。
迟迟诣天车，快快悟灵龟。
兵马更不猎，君臣皆共怡。
同车至咸阳，心影无磷缁。
四牡玉墀下，一言为帝师。
王侯拥朱门，轩盖曜长逵。
古来荣华人，遭遇谁知之。
落日悬桑榆，光景有顿亏。
倏忽天地人，虽贵将何为。','',''),('quantangshi-06938','昭君墓','常建','quantangshi','','卷7','汉宫岂不死，异域伤独没。
万里驮黄金，蛾眉为枯骨。
回车夜出塞，立马皆不发。
共恨丹青人，坟上哭明月。','',''),('quantangshi-06939','吊王将军墓','常建','quantangshi','','卷7','嫖姚北伐时，深入强千里。
战余落日黄，军败鼓声死。
尝闻汉飞将，可夺单于垒。
今与山鬼邻，残兵哭辽水。','',''),('quantangshi-06940','古意','常建','quantangshi','','卷7','井底玉冰洞地明，琥珀辘轳青丝索。
仙人骑凤披彩霞，挽上银瓶照天阁。
黄金作身双飞龙，口衔明月喷芙蓉。
一时渡海望不见，晓上青楼十二重。','',''),('quantangshi-06941','古兴','常建','quantangshi','','卷7','辘轳井上双梧桐，飞鸟衔花日将没。
深闺女儿莫愁年，玉指泠泠怨金碧。
石榴裙裾蛱蝶飞，见人不语颦蛾眉。
青丝素丝红绿丝，织成锦衾当为谁。','',''),('quantangshi-06942','张公子行','常建','quantangshi','','卷7','日出乘钓舟，袅袅持钓竿。
涉淇傍荷花，骢马闲金鞍。
侠客白云中，腰间悬辘轳。
出门事嫖姚，为君西击胡。
胡兵汉骑相驰逐，转战孤军西海北。
百尺旌竿沈黑云，边笳落日不堪闻。','',''),('quantangshi-06943','题破山寺后禅院','常建','quantangshi','','卷7','清晨入古寺，初日照高林。
竹迳通幽处，禅房花木深。
山光悦鸟性，潭影空人心。
万籁此都寂，但余钟磬音。','',''),('quantangshi-06944','送李大都护','常建','quantangshi','','卷7','单于虽不战，都护事边深。
君执幕中秘，能为高士心。
海头近初月，碛里多愁阴。
西望郭犹子，将分泪满襟。','',''),('quantangshi-06945','潭州留别','常建','quantangshi','','卷7','贤达不相识，偶然交已深。
宿帆谒郡佐，怅别依禅林。
湘水流入海，楚云千里心。
望君杉松夜，山月清猿吟。','',''),('quantangshi-06946','听琴秋夜赠寇尊师','常建','quantangshi','','卷7','琴当秋夜听，况是洞中人。
一指指应法，一声声爽神。
寒虫临砌急，清吹褭灯频。
何必钟期耳，高闲自可亲。','',''),('quantangshi-06947','泊舟盱眙','常建','quantangshi','','卷7','泊舟淮水次，霜降夕流清。
夜久潮侵岸，天寒月近城。
平沙依雁宿，候馆听鸡鸣。
乡国云霄外，谁堪羁旅情。','',''),('quantangshi-06948','江行','常建','quantangshi','','卷7','平湖四无际，此夜泛孤舟。
明月异方意，吴歌令客愁。
乡园碧云外，兄弟渌江头。
万里无归信，伤心看斗牛。','',''),('quantangshi-06949','燕居','常建','quantangshi','','卷7','青苔常满路，流水复入林。
远与市朝隔，日闻鸡犬深。
寥寥丘中想，渺渺湖上心。
啸傲转无欲，不知成陆沈。','',''),('quantangshi-06950','送宇文六','常建','quantangshi','','卷7','花映垂杨汉水清，微风林里一枝轻。
即今江北还如此，愁杀江南离别情。','',''),('quantangshi-06951','落第长安','常建','quantangshi','','卷7','家园好在尚留秦，耻作明时失路人。
恐逢故里莺花笑，且向长安度一春。','',''),('quantangshi-06952','塞下','常建','quantangshi','','卷7','铁马胡裘出汉营，分麾百道救龙城。
左贤未遁旌竿折，过在将军不在兵。','',''),('quantangshi-06953','题法院','常建','quantangshi','','卷7','胜景门闲对远山，竹深松老半含烟。
皓月殿中三度磬，水晶宫里一僧禅。','',''),('quantangshi-06954','岭猿','常建','quantangshi','','卷7','杳杳褭褭清且切，鹧鸪飞处又斜阳。
相思岭上相思泪，不到三声合断肠。','',''),('quantangshi-06955','三日寻李九庄','常建','quantangshi','','卷7','雨歇杨林东渡头，永和三日荡轻舟。
故人家在桃花岸，直到门前溪水流。','',''),('quantangshi-06956','塞下曲四首 一','常建','quantangshi','','卷7','玉帛朝回望帝乡，乌孙归去不称王。
天涯静处无征战，兵气销为日月光。','',''),('quantangshi-06957','塞下曲四首 二','常建','quantangshi','','卷7','北海阴风动地来，明君祠上望龙堆。
髑髅皆是长城卒，日暮沙场飞作灰。','',''),('quantangshi-06958','塞下曲四首 三','常建','quantangshi','','卷7','龙鬬雌雄势已分，山崩鬼哭恨将军。
黄河直北千余里，冤气苍茫成黑云。','',''),('quantangshi-06959','塞下曲四首 四','常建','quantangshi','','卷7','因嫁单于怨在边，蛾眉万古葬胡天。
汉家此去三千里，青冢常无草木烟。','',''),('quantangshi-06960','戏题湖上','常建','quantangshi','','卷7','湖上老人坐矶头，湖里桃花水却流。
竹竿袅袅白波际，不知何者吞吾鈎。','',''),('quantangshi-06961','吴故宫','常建','quantangshi','','卷7','越女歌长君且听，芙蓉香满水边城。
岂知一日终非主，犹自如今有怨声。','',''),('quantangshi-06962','从军行','杜頠','quantangshi','','卷7','秋草马蹄轻，角弓持弦急。
去为龙城候，正值胡兵袭。
军气横大荒，战酣日将入。
长风金鼓动，白露铁衣湿。
四起愁边声，南辕时伫立。
断蓬孤自转，寒雁飞相及。
万里云沙涨，平川冰霰溢。
夜闻汉使归，独向刀环泣。','',''),('quantangshi-06963','故绛行','杜頠','quantangshi','','卷7','君不见铜鞮观，数里城池已芜漫。
君不见虒祁宫，几重台榭亦微蒙。
介马兵车全盛时，歌童舞女妖艳姿。
一代繁华皆共绝，九原唯望冢累累。','',''),('quantangshi-06964','少年行三首 一','李嶷','quantangshi','','卷7','十八羽林郎，戎衣侍汉王。
臂鹰金殿侧，挟弹玉舆傍。
驰道春风起，陪游出建章。','',''),('quantangshi-06965','少年行三首 二','李嶷','quantangshi','','卷7','侍猎长杨下，承恩更射飞。
尘生马影灭，箭落雁行稀。
薄暮随天仗，联翩入琐闱。','',''),('quantangshi-06966','少年行三首 三','李嶷','quantangshi','','卷7','玉劒膝边横，金杯马上倾。
朝游茂陵道，夜宿凤凰城。
豪吏多猜忌，无劳问姓名。','',''),('quantangshi-06967','淮南秋夜呈周偘','李嶷','quantangshi','','卷7','天净河汉高，夜闲砧杵发。
清秋忽如此，离恨应难歇。
风乱池上萍，露光竹间月。
与君共游处，勿作他乡别。','',''),('quantangshi-06968','林园秋夜作','李嶷','quantangshi','','卷7','林卧避残暑，白云长在天。
赏心既如此，对酒非徒然。
月色徧秋露，竹声兼夜泉。
凉风怀袖里，兹意与谁传。','',''),('quantangshi-06969','读前汉外戚传','李嶷','quantangshi','','卷7','人录尚书事，家临御路傍。
凿池通渭水，避暑借明光。
印绶妻封邑，轩车子拜郎。
宠因宫掖里，势极必先亡。','',''),('quantangshi-06970','春怨','崔亘','quantangshi','','卷7','夜尽梦初惊，纱窗早雾明。
晓妆脂粉薄，春服绮罗轻。
妾有今朝恨，君无旧日情。
愁来理弦管，皆是断肠声。','',''),('quantangshi-06971','古歌二首 一','蔣維翰','quantangshi','','卷7','美人怨何深，含情倚金阁。
不嚬复不语，红泪双双落。','',''),('quantangshi-06972','古歌二首 二','蔣維翰','quantangshi','','卷7','美人闭红烛，独作裁新锦。
频放剪刀声，夜寒知未寝。','',''),('quantangshi-06973','春夜裁缝','蔣維翰','quantangshi','','卷7','珠箔因风起，飞蛾入最能。
不教人夜作，方便杀明灯。','',''),('quantangshi-06974','春女怨','蔣維翰','quantangshi','','卷7','白玉堂前一树梅，今朝忽见数花开。
儿家门户寻常闭，春色因何入得来。','',''),('quantangshi-06975','怨歌','蔣維翰','quantangshi','','卷7','百尺珠楼临狭斜，新妆能唱美人车。
皆言贱妾红颜好，要自狂夫不忆家。','',''),('quantangshi-06976','小山歌','萬楚','quantangshi','','卷7','人说淮南有小山，淮王昔日此登仙。
城中鸡犬皆飞去，山上坛场今宛然。
世人贵身不贵寿，共笑华阳洞天口。
不知金石变长年，谩在人间恋携手。
君能举帆至淮南，家住盱眙余先谙。
桐柏乱流平入海，茱萸一曲沸成潭。
忆记来时魂悄悄，想见仙山众峰小。
今日长歌思不堪，君行为报三青鸟。','',''),('quantangshi-06977','题江潮庄壁','萬楚','quantangshi','','卷7','田家喜秋熟，岁[晏]林叶稀。
禾黍积场圃，𣙁梨垂户扉。
野闲犬时吠，日暮牛自归。
时复落花酒，茅斋堪解衣。','',''),('quantangshi-06978','咏帘','萬楚','quantangshi','','卷7','玳瑁昔称华，玲珑薄绛纱。
钩衔门势曲，节乱水纹斜。
日弄长飞鸟，风摇不卷花。
自当分内外，非是为骄奢。','',''),('quantangshi-06979','茱萸女','萬楚','quantangshi','','卷7','山阴柳家女，九日采茱萸。
复得东邻伴，双为陌上姝。
插枝着高髻，结子置长裾。
作性常迟缓，非关诧丈夫。
平明折林樾，日入返城隅。
侠客要罗袖，行人挑短书。
蛾眉自有主，年少莫踟蹰。','',''),('quantangshi-06980','五日观妓','萬楚','quantangshi','','卷7','西施谩道浣春纱，碧玉今时鬬丽华。
眉黛夺将萱草色，红裙妬杀石榴花。
新歌一曲令人艳，醉舞双眸敛鬓斜。
谁道五丝能续命，却令今日死君家。','',''),('quantangshi-06981','骢马','萬楚','quantangshi','','卷7','金络青骢白玉鞍，长鞭紫陌野游盘。
