正见离人别，春心相向生。','',''),('quantangshi-06983','河上逢落花','萬楚','quantangshi','','卷7','河水浮落花，花流东不息。
应见浣纱人，为道长相忆。','',''),('quantangshi-06984','宁王山池','范朝','quantangshi','','卷7','水势临阶转，峰形对路开。
槎从天上得，石是海边来。
瑞草分丛种，祥花间色栽。
旧传词赋客，唯见有邹枚。','',''),('quantangshi-06985','题石瓮寺','范朝','quantangshi','','卷7','胜境宜长望，迟春好散愁。
关连四塞起，河带八川流。
复磴承香阁，重岩映彩楼。
为临温液近，偏美圣君游。','',''),('quantangshi-06986','田家','楊顔','quantangshi','','卷7','小园足生事，寻胜日倾壶。
莳蔬利于鬻，才青摘已无。
四邻依野竹，日夕采其枯。
田家心适时，春色徧桑榆。','',''),('quantangshi-06987','后庭怨','王諲','quantangshi','','卷7','君不见红闺少女端正时，夭夭桃李仙容姿。
幸得君王怜巧笑，披香殿里荐蛾眉。
蛾眉双双人共进，常恐妾身从此摈。
甄妃为妬出层宫，班女因猜下长信。
长信宫门闭不开，昭阳歌吹风送来。
梦中魂魄犹言是，觉后精神尚未回。
念君娇爱无终始，使妾长啼后庭里。
独立每看斜日尽，孤眠直至残灯死。
秋日闻虫翡翠帘，春晴照面鸳鸯水。
红颜旧来花不胜，白发如今雪相似。
传闻纨扇恩未歇，预想蛾眉上初月。
如君贵伪不贵真，还同弃妾逐新人。
借问南山松叶意，何如北砌槿花新。','',''),('quantangshi-06988','夜坐看搊筝','王諲','quantangshi','','卷7','调筝夜坐灯光里，却挂罗帷露纤指。
朱弦一一声不同，玉柱连连影相似。
不知何处学新声？曲曲弹来未覩名。
应是石家金谷里，流传未满洛阳城。','',''),('quantangshi-06989','长信怨','王諲','quantangshi','','卷7','飞燕倚身轻，争人巧笑名。
生君弃妾意，增妾怨君情。
日落昭阳壁，秋来长信城。
寥寥金殿里，歌吹夜无声。','',''),('quantangshi-06990','闺情','王諲','quantangshi','','卷7','日暮裁缝歇，深嫌气力微。
才能收箧笥，嬾起下帘帷。
怨坐空然烛，愁眠不解衣。
昨来频梦见，夫婿莫应知。','',''),('quantangshi-06991','十五夜观灯','王諲','quantangshi','','卷7','暂得金吾夜，通看火树春。
停车傍明月，走马入红尘。
妓杂歌偏胜，场移舞更新。
应须尽记取，说向不来人。','',''),('quantangshi-06992','除夜','王諲','quantangshi','','卷7','今岁今宵尽，明年明日催。
寒随一夜去，春逐五更来。
气色空中改，容颜暗里回。
风光人不觉，已着后园梅。','',''),('quantangshi-06993','闻漏','王岳靈','quantangshi','','卷7','建礼含香处，重城待漏臣。
徐闻传凤诏，晓唱辨鸡人。
银箭残将尽，铜壶漏更新。
催筹当午夜，移刻及三辰。
杳杳从天远，泠泠出禁频。
直疑残漏曙，肃肃对钩陈。','',''),('quantangshi-06994','送沈芳谒李观察求仕进','周萬','quantangshi','','卷7','往日长安路，欢游不惜年。
为贪卢女曲，用尽沈郎钱。
身老方投刺，途穷始着鞭。
犹闻有知己，此去不徒然。','',''),('quantangshi-06995','古塞下曲','陶翰','quantangshi','','卷7','进军飞狐北，穷寇势将变。
日落沙尘昏，背河更一战。
騂马黄金勒，雕弓白羽箭。
射杀左贤王，归奏未央殿。
欲言塞下事，天子不召见。
东出咸阳门，哀哀泪如霰。','',''),('quantangshi-06996','燕歌行','陶翰','quantangshi','','卷7','请君留楚调，听我吟燕歌。
家在辽水头，边风意气多。
出身为汉将，正值戎未和。
雪中凌天山，冰上渡交河。
大小百余战，封侯竟蹉跎。
归来灞陵下，故旧无相过。
雄劒委尘匣，空门垂雀罗。
玉簪还赵女，宝瑟付齐娥。
昔日不为乐，时哉今奈何。','',''),('quantangshi-06997','望太华赠卢司仓','陶翰','quantangshi','','卷7','行吏到西华，乃观三峯壮。
削成元气中，杰出天河上。
如有飞动色，不知青冥状。
巨灵安在哉，厥迹犹可望。
方此顾行旅，末由饬仙装。
葱茏记星坛，明灭数云嶂。
良友垂真契，宿心所微尚。
敢投归山吟，霞径一相访。','',''),('quantangshi-06998','赠郑员外','陶翰','quantangshi','','卷7','骢马拂绣裳，按兵辽水阳。
西分雁门骑，北逐楼烦王。
闻道五军集，相邀百战场。
风沙暗天起，虏骑森已行。
儒服揖诸将，雄谋吞大荒。
金门来见谒，朱绂生辉光。
数年侍御史，稍迁尚书郎。
人生志气立，所贵功业昌。
何必守章句，终年事铅黄。
同时献赋客，尚在东陵傍。','',''),('quantangshi-06999','赠房侍御','陶翰','quantangshi','','卷7','志士固不羁，与道常周旋。
进则天下仰，已之能晏然。
褐衣东府召，执简南台先。
雄义每特立，犯颜岂图全。
谪居东南远，逸气吟芳荃。
适会寥廓趣，清波更夤缘。
扁舟入五湖，发缆洞庭前。
浩荡临海曲，迢遥济江壖。
征奇忽忘返，遇兴将弥年。
乃悟范生智，足明渔父贤。
郡临新安渚，佳赏此城偏。
日夕对层岫，云霞映晴川。
闲居恋秋色，偃卧含贞坚。
倚伏聊自化，行藏互推迁。
君其振羽翮，岁晏将冲天。','',''),('quantangshi-07000','晚出伊阙寄河南裴中丞','陶翰','quantangshi','','卷7','退无偃息资，进无当代策。
冉冉时将暮，坐为周南客。
前登阙塞门，永眺伊城陌。
长川黯已空，千里寒气白。
家本渭水西，异日同所适。
秉志师禽尚，微言祖庄易。
一辞林壑间，共系风尘役。
交朋忽先进，天道何纷剧。
岂念嘉遯时，依依偶沮溺。','',''),('quantangshi-07001','送朱大出关','陶翰','quantangshi','','卷7','楚客西上书，十年不得意。
平生相知者，晚节心各异。
长揖五侯门，拂衣谢中贵。
丈夫多别离，各有四方事。
拔劒因高歌，萧萧北风至。
故人有斗酒，是夜共君醉。
努立强加餐，当年莫相弃。','',''),('quantangshi-07002','宿天竺寺','陶翰','quantangshi','','卷7','松柏乱岩口，山西微径通。
天开一峯见，宫阙生虚空。
正殿倚霞壁，千楼标石丛。
夜来猨鸟静，钟梵响云中。
岑翠映湖月，泉声乱溪风。
心超诸境外，了与悬解同。
明发唯改视，朝日长崖东。
湖色浓荡漾，海光渐曈朦。
葛仙迹尚在，许氏道犹崇。
独往古来事，幽怀期二公。','',''),('quantangshi-07003','出萧关怀古','陶翰','quantangshi','','卷7','驱马击长劒，行役至萧关。
悠悠五原上，永眺关河前。
北虏三十万，此中常控弦。
秦城亘宇宙，汉帝理旌旃。
刁斗鸣不息，羽书日夜传。
五军计莫就，三策议空全。
大漠横万里，萧条绝人烟。
孤城当瀚海，落日照[祁]连。
怆矣苦寒奏，怀哉式微篇。
更悲秦楼月，夜夜出胡天。','',''),('quantangshi-07004','南楚怀古','陶翰','quantangshi','','卷7','南国久芜漫，我来空郁陶。
君看章华宫，处处生黄蒿。
但见陵与谷，岂知贤与豪。
精魂托古木，宝玉捐江臯。
倚棹下晴景，回舟随晚涛。
碧云暮寥落，湖上秋天高。
往事那堪问，此心徒自劳。
独余湘水上，千载闻离骚。','',''),('quantangshi-07005','经杀子谷','陶翰','quantangshi','','卷8','扶苏秦帝子，举代称其贤。
百万犹在握，可争天下权。
束身就一劒，壮志皆弃捐。
塞下有遗迹，千龄人共传。
疎芜尽荒草，寂历空寒烟。
到此尽垂泪，非我独潸然。','',''),('quantangshi-07006','早过临淮','陶翰','quantangshi','','卷8','夜来三渚风，晨过临淮岛。
湖中海气白，城上楚云早。
鳞鳞鱼浦帆，漭漭芦洲草。
川路日浩荡，惄焉心如捣。
且言任倚伏，何暇念枯槁。
范子名屡移，蘧公志常保。
古人去已久，此理今难道。','',''),('quantangshi-07007','乘潮至渔浦作','陶翰','quantangshi','','卷8','舣棹乘早潮，潮来如风雨。
樟台忽已隐，界峯莫及覩。
崩腾心为失，浩荡目无主。
豗𢟸浪始闻，漾漾入鱼浦。
云景共澄霁，江山相吞吐。
伟哉造化工，此事从终古。
流沫诚足诫，商歌调易苦。
颇因忠信全，客心犹栩栩。','',''),('quantangshi-07008','秋山夕兴','陶翰','quantangshi','','卷8','山月松筱下，月明山景鲜。
聊为高秋酌，复此清夜弦。
晤语方获志，栖心亦弥年。
尚言兴未逸，更理逍遥篇。','',''),('quantangshi-07009','送集贤学士伊阙史少府敕放归江东觐省','陶翰','quantangshi','','卷8','墨客钟张侣，材高吴越珍。
千门来谒帝，驷马去荣亲。
吏邑沿清洛，乡山指白苹。
归期应不远，当及未央春。','',''),('quantangshi-07010','送金卿归新罗','陶翰','quantangshi','','卷8','奉义朝中国，殊恩及远臣。
乡心遥渡海，客路再经春。
落日谁同望，孤舟独可亲。
拂波衔木鸟，偶宿泣珠人。
礼乐夷风变，衣冠汉制新。
青云已干吕，知汝重来宾。','',''),('quantangshi-07011','柳陌听早莺','陶翰','quantangshi','','卷8','忽来枝上啭，还似谷中声。
乍使香闺静，偏伤远客情。
间关难辨处，断续若频惊。
玉勒留将久，青楼梦不成。
千门候晓发，万井报春生。
徒有知音赏，慙非臯鹤鸣。','',''),('quantangshi-07012','逢雪宿芙蓉山主人','劉長卿','quantangshi','','卷8','日暮苍山远，天寒白屋贫。
柴门闻犬吠，风雪夜归人。','',''),('quantangshi-07013','送张起崔载华之闽中','劉長卿','quantangshi','','卷8','朝无寒士达，家在旧山贫。
相送天涯里，怜君更远人。','',''),('quantangshi-07014','赠秦系征君','劉長卿','quantangshi','','卷8','羣公谁让位，五柳独知贫。
惆怅青山路，烟霞老此人。','',''),('quantangshi-07015','秦系顷以家事获谤因出旧山每荷观察崔公见知欲归未遂感其流寓诗以赠之','劉長卿','quantangshi','','卷8','初迷武陵路，复出孟尝门。
回首江南岸，青山与旧恩。','',''),('quantangshi-07016','夜中对雪赠秦系时秦初与谢氏离婚谢氏在越','劉長卿','quantangshi','','卷8','月明花满地，君自忆山阴。
谁遣因风起，纷纷乱此心。','',''),('quantangshi-07017','湘妃','劉長卿','quantangshi','','卷8','帝子不可见，秋风来暮思。
婵娟湘江月，千载空蛾眉。','',''),('quantangshi-07018','斑竹','劉長卿','quantangshi','','卷8','苍梧千载后，斑竹对湘沅。
欲识湘妃怨，枝枝满泪痕。','',''),('quantangshi-07019','春草宫怀古','劉長卿','quantangshi','','卷8','君王不可见，芳草旧宫春。
犹带罗裙色，青青向楚人。','',''),('quantangshi-07020','正朝览镜作','劉長卿','quantangshi','','卷8','憔悴逢新岁，茅扉见旧春。
朝来明镜里，不忍白头人。','',''),('quantangshi-07021','瓜洲道中送李端公南渡后归扬州道中寄','劉長卿','quantangshi','','卷8','片帆何处去，匹马独归迟。
惆怅江南北，青山欲暮时。','',''),('quantangshi-07022','送张十八归桐庐','劉長卿','quantangshi','','卷8','归人乘野艇，带月过江村。
正落寒潮水，相随夜到门。','',''),('quantangshi-07023','过白鹤观寻岑秀才不遇','劉長卿','quantangshi','','卷8','不知方外客，何事锁空房。
应向桃源里，教他唤阮郎。','',''),('quantangshi-07024','听弹琴','劉長卿','quantangshi','','卷8','泠泠七丝上，静听松风寒。
古调虽自爱，今人多不弹。','',''),('quantangshi-07025','游南园偶见在阴墙下葵因以成咏','劉長卿','quantangshi','','卷8','此地常无日，青青独在阴。
太阳偏不及，非是未倾心。','',''),('quantangshi-07026','入百丈涧见桃花晚开','劉長卿','quantangshi','','卷8','百丈深涧里，过时花欲妍。
应缘地势下，遂使春风偏。','',''),('quantangshi-07027','送子壻崔真甫李穆往扬州四首 一','劉長卿','quantangshi','','卷8','渡口发梅花，山中动泉脉。
芜城春草生，君作扬州客。','',''),('quantangshi-07028','送子壻崔真甫李穆往扬州四首 二','劉長卿','quantangshi','','卷8','半逻莺满树，新年人独还。
落花逐流水，共到茱萸湾。','',''),('quantangshi-07029','送子壻崔真甫李穆往扬州四首 三','劉長卿','quantangshi','','卷8','雁还空渚在，人去落潮翻。
临水独挥手，残阳归掩门。','',''),('quantangshi-07030','送子壻崔真甫李穆往扬州四首 四','劉長卿','quantangshi','','卷8','狎鸟携稚子，钓鱼终老身。
殷勤嘱归客，莫话桃源人。','',''),('quantangshi-07031','寄龙山道士许法棱','劉長卿','quantangshi','','卷8','悠悠白云里，独住青山客。
林下昼焚香，桂花同寂寂。','',''),('quantangshi-07032','送方外上人','劉長卿','quantangshi','','卷8','孤云将野鹤，岂向人间住。
莫买沃洲山，时人已知处。','',''),('quantangshi-07033','送灵澈上人','劉長卿','quantangshi','','卷8','苍苍竹林寺，杳杳钟声晚。
荷笠带夕阳，青山独归远。','',''),('quantangshi-07034','茱萸湾北答崔载华问','劉長卿','quantangshi','','卷8','荒凉野店绝，迢遰人烟远。
苍苍古木中，多是隋家苑。','',''),('quantangshi-07035','赴楚州次自田途中阻浅问张南史','劉長卿','quantangshi','','卷8','楚城今近远，积霭寒塘暮。
水浅舟且迟，淮潮至何处。','',''),('quantangshi-07036','江中对月','劉長卿','quantangshi','','卷8','空洲夕烟敛，望月秋江里。
历历沙上人，月中孤渡水。','',''),('quantangshi-07037','碧涧别墅喜皇甫侍御相访','劉長卿','quantangshi','','卷8','荒村带返照，落叶乱纷纷。
古路无行客，寒山独见君。
野桥经雨断，涧水向田分。
不为怜同病，何人到白云。','',''),('quantangshi-07038','初到碧涧招明契上人','劉長卿','quantangshi','','卷8','渐老知身累，初寒曝背眠。
白云留永日，黄叶减余年。
猨护窗前树，泉浇谷后田。
沃洲能共隐，不用道林钱。','',''),('quantangshi-07039','送少微上人游天台','劉長卿','quantangshi','','卷8','石桥人不到，独往更迢迢。
乞食山家少，寻钟野路遥。
松门风自埽，瀑布雪难消。
秋夜闻清梵，余音逐海潮。','',''),('quantangshi-07040','却归睦州至七里滩下作','劉長卿','quantangshi','','卷8','南归犹谪宦，独上子陵滩。
江树临洲晚，沙禽对水寒。
山开斜照在，石浅乱流难。
惆怅梅花发，年年此地看。','',''),('quantangshi-07041','对酒寄严维','劉長卿','quantangshi','','卷8','陋巷喜阳和，衰颜对酒歌。
嬾从华发乱，闲任白云多。
郡简容垂钓，家贫学弄梭。
门前七里濑，早晚子陵过。','',''),('quantangshi-07042','新年作','劉長卿','quantangshi','','卷8','乡心新岁切，天畔独潸然。
老至居人下，春归在客先。
岭猨同旦暮，江柳共风烟。
已是长沙傅，从今又几年。','',''),('quantangshi-07043','朱放自杭州与故里相使君立碑回因以奉简吏部杨侍郎制文','劉長卿','quantangshi','','卷8','片石羊公后，凄凉江水滨。
好辞千古事，堕泪万家人。
鵩集占书久，鸾回刻篆新。
不堪相顾恨，文字日生尘。','',''),('quantangshi-07044','送宣尊师醮毕归越','劉長卿','quantangshi','','卷8','吹箫江上晚，惆怅别茅君。
踏火能飞雪，登刀入白云。
晨香长日在，夜磬满山闻。
挥手桐溪路，无情水亦分。','',''),('quantangshi-07045','送裴使君赴荆南充行军司马','劉長卿','quantangshi','','卷8','盛府南门寄，前程积水中。
月明临夏口，山晚望巴东。
故节辞江郡，寒笳发渚宫。
汉川风景好，遥羡逐羊公。','',''),('quantangshi-07046','送裴郎中贬吉州','劉長卿','quantangshi','','卷8','乱军交白刃，一骑出黄尘。
汉节同归阙，江帆共逐臣。
猨愁歧路晚，梅作异方春。
知己酇侯在，应怜脱粟人。','',''),('quantangshi-07047','酬皇甫侍御见寄时前相国姑臧公初临郡','劉長卿','quantangshi','','卷8','离别江南北，汀洲叶再黄。
路遥云共水，砧迥月如霜。
岁俭依仁政，年衰忆故乡。
伫看宣室召，汉法倚张纲。','',''),('quantangshi-07048','月下呈章秀才','劉長卿','quantangshi','','卷8','自古悲摇落，谁人奈此何。
夜蛬偏傍枕，寒鸟数移柯。
向老三年谪，当秋百感多。
家贫惟好月，空愧子猷过。','',''),('quantangshi-07049','酬张夏','劉長卿','quantangshi','','卷8','几岁依穷海，颓年惜故阴。
剑寒空有气，松老欲无心。
玩雪劳相访，看山正独吟。
孤舟且莫去，前路水云深。','',''),('quantangshi-07050','送李使君贬连州','劉長卿','quantangshi','','卷8','独过长沙去，谁堪此路愁。
秋风散千骑，寒雨泊孤舟。
贾谊辞明主，萧何识故侯。
汉廷当自召，湘水但空流。','',''),('quantangshi-07051','秋夜北山精舍观体如师梵','劉長卿','quantangshi','','卷8','焚香奏仙呗，向夕遍空山。
清切兼秋远，威仪对月闲。
静分岩响答，散逐海潮还。
幸得风吹去，随人到世间。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-07052','酬张夏雪夜赴州访别途中苦寒作','劉長卿','quantangshi','','卷8','扁舟乘兴客，不惮苦寒行。
晚暮相依分，江潮欲别情。
水声冰下咽，砂路雪中平。
旧劒锋铓尽，应嫌赠脱轻。','',''),('quantangshi-07053','寻洪尊师不遇','劉長卿','quantangshi','','卷8','古木无人地，来寻羽客家。
道书堆玉案，仙帔叠青霞。
鹤老难知岁，梅寒未作花。','',''),('quantangshi-07054','喜鲍禅师自龙山至','劉長卿','quantangshi','','卷8','故居何日下，春草欲芊芊。
犹对山中月，谁听石上泉。
猨声知后夜，花发见流年。
杖锡闲来往，无心到处禅。','',''),('quantangshi-07055','送方外上人之常州依萧使君','劉長卿','quantangshi','','卷8','宰臣思得度，鸥鸟恋为羣。
远客回飞锡，空山卧白云。
夕阳孤艇去，秋水两溪分。
归共临川史，同翻贝叶文。','',''),('quantangshi-07056','宿北山禅寺兰若','劉長卿','quantangshi','','卷8','上方鸣夕磬，林下一僧还。
密行传人少，禅心对虎闲。
青松临古路，白月满寒山。
旧识窗前桂，经霜更待攀。','',''),('quantangshi-07057','赴新安别梁侍郎','劉長卿','quantangshi','','卷8','新安君莫问，此路水云深。
江海无行迹，孤舟何处寻。
青山空向泪，白月岂知心。
纵有余生在，终伤老病侵。','',''),('quantangshi-07058','江州留别薛六柳八二员外','劉長卿','quantangshi','','卷8','江海相逢少，东南别处长。
独行风袅袅，相去水茫茫。
白首辞同舍，青山背故乡。
离心与潮信，每日到浔阳。','',''),('quantangshi-07059','和州留别穆郎中','劉長卿','quantangshi','','卷8','播迁悲远道，摇落感衰容。
今日犹多难，何年更此逢。
世交黄叶散，乡路白云重。
明发看烟树，唯闻江北钟。','',''),('quantangshi-07060','和州送人归复郢','劉長卿','quantangshi','','卷8','因家汉水曲，相送掩柴扉。
故郢生秋草，寒江澹落晖。
绿林行客少，赤壁住人稀。
独过浔阳去，潮归人不归。','',''),('quantangshi-07061','送金昌宗归钱塘','劉長卿','quantangshi','','卷8','新家浙江上，独泛落潮归。
秋水照华发，凉风生褐衣。
柴门嘶马少，藜杖拜人稀。
惟有陶潜柳，萧条对掩扉。','',''),('quantangshi-07062','酬张夏别后道中见寄','劉長卿','quantangshi','','卷8','离羣方岁晏，谪宦在天涯。
暮雪同行少，寒潮欲上迟。
海鸥知吏傲，砂鹤见人衰。
只畏生秋草，西归亦未期。','',''),('quantangshi-07063','新安奉送穆谕德归朝赋得行字','劉長卿','quantangshi','','卷8','九重宣室召，万里建溪行。
事直皇天在，归迟白发生。
用材身复起，覩圣眼犹明。
离别寒江上，潺湲若有情。','',''),('quantangshi-07064','偶然作','劉長卿','quantangshi','','卷8','野寺长依止，田家或往还。
老农开古地，夕鸟入寒山。
书劒身同废，烟霞吏共闲。
岂能将白发，扶杖出人间。','',''),('quantangshi-07065','送州人孙沅自本州却归句章新营所居','劉長卿','quantangshi','','卷8','故里归成客，新家去未安。
诗书满蜗舍，征税及渔竿。
火种山田薄，星居海岛寒。
怜君不得已，步步别离难。','',''),('quantangshi-07066','送李员外使还苏州兼呈前袁州李使君赋得长字袁州即员外之从兄','劉長卿','quantangshi','','卷8','别离共成怨，衰老更难忘。
夜月留同舍，秋风在远乡。
朱弦徐向烛，白发强临觞。
归献西陵作，谁知此路长。','',''),('quantangshi-07067','酬李员外从崔录事载华宿三河戍先见寄','劉長卿','quantangshi','','卷8','寒江鸣石濑，归客夜初分。
人语空山答，猨声独戍闻。
迟来朝及暮，愁去水连云。
岁晚心谁在，青山见此君。','',''),('quantangshi-07068','见秦系离婚后出山居作','劉長卿','quantangshi','','卷8','岂知偕老重，垂老绝良姻。
郗氏诚难负，朱家自愧贫。
绽衣留欲故，织锦罢经春。
何况蘼芜绿，空山不见人。','',''),('quantangshi-07069','酬秦系','劉長卿','quantangshi','','卷8','鹤书犹未至，那出白云来。
旧路经年别，寒潮每日回。
家空归海燕，人老发江梅。
最忆门前柳，闲居手自栽。','',''),('quantangshi-07070','岁日作','劉長卿','quantangshi','','卷8','建寅回北斗，看历占春风。
律变沧江外，年加白发中。
春衣试稚子，寿酒劝衰翁。
今日阳和发，荣枯岂不同。','',''),('quantangshi-07071','题元录事开元所居','劉長卿','quantangshi','','卷8','幽居萝薜情，高卧纪纲行。
鸟散秋鹰下，人闲春草生。
冒风归野寺，收印出山城。
今日新安郡，因君水更清。','',''),('quantangshi-07072','送崔载华张起之闽中','劉長卿','quantangshi','','卷8','不识闽中路，遥知别后心。
猨声入岭切，鸟道问人深。
旅食过夷落，方言会越音。
西征开幕府，早晚用陈琳。','',''),('quantangshi-07073','送张司直赴岭南谒张尚书','劉長卿','quantangshi','','卷8','番禺万里路，远客片帆过。
盛府依横海，荒祠拜伏波。
人经秋瘴变，鸟坠火云多。
诚惮炎洲里，无如一顾何。','',''),('quantangshi-07074','寄会稽公徐侍郎','劉長卿','quantangshi','','卷8','摇落淮南叶，秋风想越吟。
皱枚入梁苑，逸少在山阴。
老鹤无衰貌，寒松有本心。
圣朝难税驾，惆怅白云深。','',''),('quantangshi-07075','送朱山人放越州贼退后归山阴别业','劉長卿','quantangshi','','卷8','越州初罢战，江上送归桡。
南渡无来客，西陵自落潮。
空城垂故柳，旧业废春苗。
闾里相逢少，莺花共寂寥。','',''),('quantangshi-07076','秋夜肃公房喜普门上人自阳羡山至','劉長卿','quantangshi','','卷8','山栖久不见，林下偶同游。
早晚来香积，何人住沃洲。
寒禽惊后夜，古木带高秋。
却入千峰去，孤云不可留。','',''),('quantangshi-07077','送李秘书却赴南中','劉長卿','quantangshi','','卷8','却到番禺日，应伤昔所依。
炎洲百口住，故国几人归。
路识梅花在，家存棣萼稀。
独逢回雁去，犹作旧行飞。','',''),('quantangshi-07078','过前安宜张明府郊居','劉長卿','quantangshi','','卷8','寂寥东郭外，白首一先生。
解印孤琴在，移家五柳成。
夕阳临水钓，春雨向田耕。','',''),('quantangshi-07079','使回次杨柳过元八所居','劉長卿','quantangshi','','卷8','君家杨柳渡，来往落帆过。
绿竹经寒在，青山欲暮多。
薜萝诚可恋，婚嫁复如何。
无奈闲门外，渔翁夜夜歌。','',''),('quantangshi-07080','送李侍御贬郴州','劉長卿','quantangshi','','卷8','洞庭波渺渺，君去吊灵均。
几路三湘水，全家万里人。
听猨明月夜，看柳故年春。
忆想汀洲畔，伤心向白苹。','',''),('quantangshi-07081','寄普门上人','劉長卿','quantangshi','','卷8','白云幽卧处，不向世人传。
闻在千峰里，心知独夜禅。
辛勤羞薄禄，依止爱闲田。
惆怅王孙草，青青又一年。','',''),('quantangshi-07082','逢郴州使因寄郑协律','劉長卿','quantangshi','','卷8','相思楚天外，梦寐楚猨吟。
更落淮南叶，难为江上心。
衡阳问人远，湘水向君深。','',''),('quantangshi-07083','岳阳馆中望洞庭湖','劉長卿','quantangshi','','卷8','万古巴丘戍，平湖此望长。
问人何淼淼，愁暮更苍苍。
叠浪浮元气，中流没太阳。
孤舟有归客，早晚达潇湘。','',''),('quantangshi-07084','巡去岳阳却归鄂州使院留别郑洵侍御先曾谪居此州','劉長卿','quantangshi','','卷8','何事长沙谪，相逢楚水秋。
暮帆归夏口，寒雨对巴丘。
帝子椒浆奠，骚人木叶愁。
惟怜万里外，离别洞庭头。','',''),('quantangshi-07085','夏口送屈突司直使湖南','劉長卿','quantangshi','','卷8','共悲来夏口，何事更南征。
雾露行人少，潇湘春草生。
莺啼何处梦，猨啸若为声。
风月新年好，悠悠远客情。','',''),('quantangshi-07086','代边将有怀','劉長卿','quantangshi','','卷8','少年辞魏阙，白首向沙场。
瘦马恋秋草，征人思故乡。
暮笳吹寒月，晓甲带胡霜。
自到云中郡，于今百战强。','',''),('quantangshi-07087','雨中过员稷巴陵山居赠别','劉長卿','quantangshi','','卷8','怜君洞庭上，白发向人垂。
积雨悲幽独，长江对别离。
牛羊归故道，猨鸟聚寒枝。
明发遥相望，云山不可知。','',''),('quantangshi-07088','送李中丞之襄州','劉長卿','quantangshi','','卷8','流落征南将，曾驱十万师。
罢归无旧业，老去恋明时。
独立三朝识，轻生一劒知。
茫茫汉江上，日暮复何之。','',''),('quantangshi-07089','奉使至申州伤经陷没','劉長卿','quantangshi','','卷8','举目伤芜没，何年此战争。
归人失旧里，老将守孤城。
废戍山烟出，荒田野火行。
独怜浉水上，时乱亦能清。','',''),('quantangshi-07090','穆陵关北逢人归渔阳','劉長卿','quantangshi','','卷8','逢君穆陵路，匹马向桑干。
楚国苍山古，幽州白日寒。
城池百战后，耆旧几家残。
处处蓬蒿遍，归人掩泪看。','',''),('quantangshi-07091','安州道中经浐水有怀','劉長卿','quantangshi','','卷8','征途逢浐水，忽似到秦川。
借问朝天处，犹看落日边。
映沙晴漾漾，出涧夜溅溅。
欲寄西归恨，微波不可传。','',''),('quantangshi-07092','步登夏口古城作','劉長卿','quantangshi','','卷8','平芜连古堞，远客此沾衣。
高树朝光上，空城秋气归。
微明汉水极，摇落楚人稀。
但见荒郊外，寒鵶暮暮飞。','',''),('quantangshi-07093','赠别卢司直之闽中','劉長卿','quantangshi','','卷8','尔来多不见，此去又何之。
华发同今日，流芳似旧时。
洲长春色遍，汉广夕阳迟。
岁岁王孙草，空怜无处期。','',''),('quantangshi-07094','酬郭夏人日长沙感怀见赠','劉長卿','quantangshi','','卷8','旧俗欢犹在，怜君恨独深。
新年向国泪，今日倚门心。
岁去随湘水，春生近桂林。
流莺且莫弄，江畔正行吟。','',''),('quantangshi-07095','赴巴南书情寄故人','劉長卿','quantangshi','','卷8','南过三湘去，巴人此路偏。
谪居秋瘴里，归处夕阳边。
直道天何在，愁容镜亦怜。
裁书欲谁诉，无泪可潸然。','',''),('quantangshi-07096','余干旅舍','劉長卿','quantangshi','','卷8','摇落暮天迥，青枫霜叶稀。
孤城向水闭，独鸟背人飞。
渡口月初上，邻家渔未归。
乡心正欲绝，何处捣寒衣。','',''),('quantangshi-07097','登思禅寺上方题修竹茂松','劉長卿','quantangshi','','卷8','上方幽且暮，台殿隐蒙笼。
远磬秋山里，清猨古木中。
众溪连竹路，诸岭共松风。
傥许栖林下，甘成白首翁。','',''),('quantangshi-07098','恩敕重推使牒追赴苏州次前溪馆作','劉長卿','quantangshi','','卷8','渐入云峰里，愁看驿路闲。
乱鵶投落日，疲马向空山。
且喜怜非罪，何心恋末班。
天南一万里，谁料得生还。','',''),('quantangshi-07099','北归次秋浦界清溪馆','劉長卿','quantangshi','','卷8','万里猨啼断，孤村客暂依。
雁过彭蠡暮，人向宛陵稀。
旧路青山在，余生白首归。
渐知行近北，不见鹧鸪飞。','',''),('quantangshi-07100','谪官后却归故村将过虎丘怅然有作','劉長卿','quantangshi','','卷8','万事依然在，无如岁月何。
邑人怜白发，庭树长新柯。
故老相逢少，同官不见多。
唯余旧山路，惆怅枉帆过。','',''),('quantangshi-07101','重推后却赴岭外待进止寄元侍郎','劉長卿','quantangshi','','卷8','却访巴人路，难期国士恩。
白云从出岫，黄叶已辞根。
大造功何薄，长年气尚冤。
空令数行泪，来往落湘沅。','',''),('quantangshi-07102','秋杪江亭有作','劉長卿','quantangshi','','卷8','寂寞江亭下，江枫秋气斑。
世情何处澹，湘水向人闲。
寒渚一孤雁，夕阳千万山。
扁舟如落叶，此去未知还。','',''),('quantangshi-07103','送郑司直归上都','劉長卿','quantangshi','','卷8','岁岁逢离别，蹉跎江海滨。
宦游成楚老，乡思逐秦人。
马首归何日，莺啼又一春。
因君报情旧，闲慢欲垂纶。','',''),('quantangshi-07104','送灵澈上人归嵩阳兰若','劉長卿','quantangshi','','卷8','南地随缘久，东林几岁空。
暮山门独掩，春草路难通。
作梵连松韵，焚香入桂丛。
唯将旧瓶钵，却寄白云中。','',''),('quantangshi-07105','却赴南邑留别苏台知己','劉長卿','quantangshi','','卷8','又过梅岭上，岁岁此枝寒。
落日孤舟去，青山万里看。
猨声湘水静，草色洞庭宽。
已料生涯事，唯应把钓竿。','',''),('quantangshi-07106','和灵一上人新泉','劉長卿','quantangshi','','卷8','东林一泉出，复与远公期。
石浅寒流处，山空夜落时。
梦闲闻细响，虑澹对清漪。
动静皆无意，唯应达者知。','',''),('quantangshi-07107','送李挚赴延陵令','劉長卿','quantangshi','','卷8','清风季子邑，想见下车时。
向水弹琴静，看山采菊迟。
明君加印绶，廉使托惸[嫠]。
旦暮华阳洞，云峰若有期。','',''),('quantangshi-07108','奉送裴员外赴上都','劉長卿','quantangshi','','卷8','彤襜江上远，万里诏书催。
独过浔阳去，空怜潮信回。
离心秋草绿，挥手暮帆开。
想见秦城路，人看五马来。','',''),('quantangshi-07109','长沙桓王墓下别李纾张南史','劉長卿','quantangshi','','卷8','长沙千载后，春草独萋萋。
流水朝将暮，行人东复西。
碑苔几字灭，山木万株齐。
伫立伤今古，相看惜解携。','',''),('quantangshi-07110','送侯御赴黔中充判官','劉長卿','quantangshi','','卷8','不识黔中路，今看遣使臣。
猨啼万里客，鸟似五湖人。
地远官无法，山深俗岂淳。
须令荒徼外，亦解惧埋轮。','',''),('quantangshi-07111','秋日登吴公台上寺远眺寺即陈将吴明彻战场','劉長卿','quantangshi','','卷8','古台摇落后，秋日望乡心。
野寺人来少，云峰水隔深。
夕阳依旧垒，寒磬满空林。
惆怅南朝事，长江独至今。','',''),('quantangshi-07112','淮上送梁二恩命追赴上都','劉長卿','quantangshi','','卷8','贾生年最少，儒行汉庭闻。
拜手卷黄纸，回身谢白云。
故关无去客，春草独随君。
淼淼长淮水，东西自此分。','',''),('quantangshi-07113','送崔升归上都','劉長卿','quantangshi','','卷8','旧寺寻遗绪，归心逐去尘。
早莺何处客，古木几家人。
白发经多难，沧洲欲暮春。
临期数行泪，为尔一霑巾。','',''),('quantangshi-07114','过李将军南郑林园观妓','劉長卿','quantangshi','','卷8','郊原风日好，百舌弄何频。
小妇秦家女，将军天上人。
鸦归长郭暮，草映大堤春。
客散垂杨下，通桥车马尘。','',''),('quantangshi-07115','送严侍御充东畿观察判官','劉長卿','quantangshi','','卷8','洛阳征战后，君去问凋残。
云月临南至，风霜向北寒。
故园经乱久，古木隔林看。
谁访江城客，年年守一官。','',''),('quantangshi-07116','送王端公入奏上都','劉長卿','quantangshi','','卷8','旧国无家访，临歧亦羡归。
途经百战后，客过二陵稀。
秋草通征骑，寒城背落晖。
行当蒙顾问，吴楚岁频饥。','',''),('quantangshi-07117','送营田判官郑侍御赴上都','劉長卿','quantangshi','','卷8','上国三千里，西还及岁芳。
故山经乱在，春日送归长。
晓奏趋双阙，秋成报万箱。
幸论开济力，已实海陵仓。','',''),('quantangshi-07118','送李校书赴东浙幕府','劉長卿','quantangshi','','卷8','方从大夫后，南去会稽行。
淼淼沧江外，青青春草生。
芸香辞乱事，梅吹听军声。
应访王家宅，空怜江水平。','',''),('quantangshi-07119','清明后登城眺望','劉長卿','quantangshi','','卷8','风景清明后，云山睥睨前。
百花如旧日，万井出新烟。
草色无空地，江流合远天。
长安在何处？遥指夕阳边。','',''),('quantangshi-07120','陪王明府泛舟','劉長卿','quantangshi','','卷8','花县弹琴暇，樵风载酒时。
山含秋色近，鸟度夕阳迟。
出没凫成浪，蒙笼竹亚枝。
云峰逐人意，来去解相随。','',''),('quantangshi-07121','送度支留后若侍御之歙州便赴信州省觐','劉長卿','quantangshi','','卷8','国用忧钱谷，朝推此任难。
即山榆荚变，降雨稻花残。
林响朝登岭，江喧夜过滩。
遥知骢马色，应待倚门看。','',''),('quantangshi-07122','余干夜宴奉饯前苏州韦使君新除婺州作','劉長卿','quantangshi','','卷8','复拜东阳郡，遥驰北阙心。
行春五马急，向夜一猨深。
山过康郎近，星看婺女临。
幸容栖托分，犹恋旧棠阴。','',''),('quantangshi-07123','晚次苦竹馆却忆干越旧游','劉長卿','quantangshi','','卷8','匹马风尘色，千峰旦暮时。
遥看落日尽，独向远山迟。
故驿花临道，荒村竹映篱。
谁怜却回首，步步恋南枝。','',''),('quantangshi-07124','送李二十四移家之江州','劉長卿','quantangshi','','卷8','烟尘犹满目，歧路易霑衣。
逋客多南渡，征鸿自北飞。
九江春草绿，千里暮潮归。
别后难相访，全家隐钓矶。','',''),('quantangshi-07125','送卢判官南湖','劉長卿','quantangshi','','卷8','漾舟仍载酒，愧尔意相宽。
草色南湖绿，松声小署寒。
水禽前后起，花屿往来看。
已作沧洲调，无心恋一官。','',''),('quantangshi-07126','送张栩扶侍之睦州','劉長卿','quantangshi','','卷8','遥忆新安旧，扁舟复却还。
浅深看水石，来往逐云山。
入县余花在，过门故柳闲。
东征随子去，皆隐薜萝间。','',''),('quantangshi-07127','集梁耿开元寺所居院','劉長卿','quantangshi','','卷8','到君幽卧处，为我埽莓苔。
花雨晴天落，松风终日来。
路经深竹过，门向远山开。
岂得长高枕，中朝正用才。','',''),('quantangshi-07128','赠西邻卢少府','劉長卿','quantangshi','','卷8','篱落能相近，渔樵偶复同。
苔封三径绝，溪向数家通。
犬吠寒烟里，鵶鸣夕照中。
时因杖藜次，相访竹林东。','',''),('quantangshi-07129','游休禅师双峰寺','劉長卿','quantangshi','','卷8','双扉碧峰际，遥向夕阳开。
飞锡方独往，孤云何事来。
寒潭映白月，秋雨上青苔。
相送东郊外，羞看骢马回。','',''),('quantangshi-07130','廨中见桃花南枝已开北枝未发因寄杜副端','劉長卿','quantangshi','','卷8','何意同根本，开花每后时。
应缘去日远，独自发春迟。
结实恩难忘，无言恨岂知。
年光不可待，空羡向南枝。','',''),('quantangshi-07131','奉送卢员外之饶州','劉長卿','quantangshi','','卷8','天书万里至，旌斾上江飞。
日向鄱阳近，应看吴岫微。
暮帆何处落？潮水背人归。
风土无劳问，南枝黄叶稀。','',''),('quantangshi-07132','送处士归州因寄林山人','劉長卿','quantangshi','','卷8','陵阳不可见，独往复如何。
旧邑云山里，扁舟来去过。
鸟声春谷静，草色太湖多。
傥宿荆溪夜，相思渔者歌。','',''),('quantangshi-07133','移使鄂州次岘阳馆怀旧居','劉長卿','quantangshi','','卷8','多慙恩未报，敢问路何长。
万里通秋雁，千峰共夕阳。
旧游成远道，此去更违乡。
草露深山里，朝朝落客裳。','',''),('quantangshi-07134','送齐郎中赴海州','劉長卿','quantangshi','','卷8','华省占星动，孤城望日遥。
直庐收旧草，行县及新苗。
沧海天连水，青山暮与朝。
闾阎几家散，应待下车招。','',''),('quantangshi-07135','重阳日鄂城楼送屈突司直','劉長卿','quantangshi','','卷8','登高复送远，惆怅洞庭秋。
风景同前古，云山满上游。
苍苍来暮雨，淼淼逐寒流。
今日关中事，萧何共尔忧。','',''),('quantangshi-07136','更被奏留淮南送从弟罢使江东','劉長卿','quantangshi','','卷8','又作淮南客，还悲木叶声。
寒潮落瓜步，秋色上芜城。
王事何时尽？沧洲羡尔行。
青山将绿水，惆怅不胜情。','',''),('quantangshi-07137','经漂母墓','劉長卿','quantangshi','','卷8','昔贤怀一饭，兹事已千秋。
古墓樵人识，前朝楚水流。
渚苹行客荐，山木杜鹃愁。
春草茫茫绿，王孙旧此游。','',''),('quantangshi-07138','送李端公赴东都','劉長卿','quantangshi','','卷8','轩辕征战后，江海别离长。
远客归何处，平芜满故乡。
夕阳帆杳杳，旧里树苍苍。
惆怅蓬山下，琼枝不可忘。','',''),('quantangshi-07139','送王员外归朝','劉長卿','quantangshi','','卷8','往来无尽目，离别要逢春。
海内罹多事，天涯见近臣。
芳时万里客，乡路独归人。
魏阙心常在，随君亦向秦。','',''),('quantangshi-07140','送蒋侍御入秦','劉長卿','quantangshi','','卷8','朝见及芳菲，恩荣出紫微。
晚光临仗奏，春色共西归。
楚客移家老，秦人访旧稀。
因君乡里去，为埽故园扉。','',''),('quantangshi-07141','洞庭驿逢郴州使还寄李汤司马','劉長卿','quantangshi','','卷8','洞庭秋水阔，南望过衡峰。
远客潇湘里，归人何处逢。
孤云飞不定，落叶去无踪。
莫使沧浪叟，长歌笑尔容。','',''),('quantangshi-07142','送舍弟之鄱阳居','劉長卿','quantangshi','','卷8','鄱阳寄家处，自别掩柴扉。
故里人何在，沧波孤客稀。
湖山春草遍，云木夕阳微。
南去逢回雁，应怜相背飞。','',''),('quantangshi-07143','送裴二十端公使岭南','劉長卿','quantangshi','','卷8','苍梧万里路，空见白云来。
远国知何在，怜君去未回。
桂林无叶落，梅岭自花开。
陆贾千年后，谁看朝汉台。','',''),('quantangshi-07144','过桃花夫人庙','劉長卿','quantangshi','','卷8','寂寞应千岁，桃花想一枝。
路人看古木，江月向空祠。
云雨飞何处，山川是旧时。
独怜春草色，犹似忆佳期。','',''),('quantangshi-07145','鄂渚送池州程使君','劉長卿','quantangshi','','卷8','萧萧五马动，欲别谢临川。
落日芜湖色，空山梅冶烟。
江湖通廨舍，楚老拜戈船。
风化东南满，行舟来去传。','',''),('quantangshi-07146','送友人西上','劉長卿','quantangshi','','卷8','羁心不自解，有别会霑衣。
春草连天积，五陵远客归。
十年经转战，几处便芳菲。
想见函关路，行人去亦稀。','',''),('quantangshi-07147','送梁郎中赴吉州','劉長卿','quantangshi','','卷8','遥想庐陵郡，还听叔度歌。
旧官移上象，新令布中和。
看竹经霜少，闻猨带雨多。
但愁征拜日，无奈借留何。','',''),('quantangshi-07148','过湖南羊处士别业','劉長卿','quantangshi','','卷8','杜门成白首，湖上寄生涯。
秋草芜三径，寒塘独一家。
鸟归村落尽，水向县城斜。
自有东篱菊，年年解作花。','',''),('quantangshi-07149','送河南元判官赴河南句当苗税充百官俸钱','劉長卿','quantangshi','','卷8','春草长河曲，离心共渺然。
方收汉家俸，独向汶阳田。
鸟雀空城在，榛芜旧路迁。
山东征战苦，几处有人烟。','',''),('quantangshi-07150','夏中崔中丞宅见海红摇落一花独开','劉長卿','quantangshi','','卷8','何事一花残，闲庭百草阑。
绿滋经雨发，红艳隔林看。
竟日余香在，过时独秀难。
共怜芳意晚，秋露未须团。','',''),('quantangshi-07151','使还至菱陂驿渡浉水作','劉長卿','quantangshi','','卷8','清川已再涉，疲马共西还。
何事行人倦，终年流水闲。
孤烟飞广泽，一鸟向空山。
愁入云峰里，苍苍闭古关。','',''),('quantangshi-07152','送齐郎中典括州','劉長卿','quantangshi','','卷8','星象移何处，旌麾独向东。
劝耕沧海畔，听讼白云中。
树色双溪合，猨声万岭同。
石门康乐住，几里枉帆通。','',''),('quantangshi-07153','过隐空和尚故居','劉長卿','quantangshi','','卷8','自从飞锡去，人到沃洲稀。
林下期何在，山中春独归。
踏花寻旧径，映竹掩空扉。
寥落东峰上，犹堪静者依。','',''),('quantangshi-07154','过萧尚书故居见李花感而成咏','劉長卿','quantangshi','','卷8','手植已芳菲，心伤故径微。
往年啼鸟至，今日主人非。
满地谁当埽，随风岂复归。
空怜旧阴在，门客共霑衣。','',''),('quantangshi-07155','送袁处士','劉長卿','quantangshi','','卷8','闲田北川下，静者去躬耕。
万里空江菼，孤舟过郢城。
种荷依野水，移柳待山莺。
出处安能问，浮云岂有情。','',''),('quantangshi-07156','酬李侍御登岳阳见寄','劉長卿','quantangshi','','卷8','想见孤舟去，无由此路寻。
暮帆遥在眼，春色独何心。
绿水潇湘阔，青山鄠杜深。
谁当北风至，为尔一开襟。','',''),('quantangshi-07157','喜晴','劉長卿','quantangshi','','卷8','晓日西风转，秋天万里明。
湖天一种色，林鸟百般声。
霁景浮云满，游丝暎水轻。
今朝江上客，凡慰几人情。','',''),('quantangshi-07158','夏口送徐郎中归朝','劉長卿','quantangshi','','卷8','星象南宫远，风流上客稀。
九重思晓奏，万里见春归。
棹发空江响，城孤落日晖。
离心与杨柳，临水更依依。','',''),('quantangshi-07159','鄂渚听杜别驾弹胡琴','劉長卿','quantangshi','','卷8','文姬留此曲，千载一知音。
不解胡人语，空留楚客心。
听随边草动，意入陇云深。
何事长江上，萧萧出塞吟。','',''),('quantangshi-07160','过鹦鹉洲王处士别业','劉長卿','quantangshi','','卷8','白首此为渔，青山对结庐。
问人寻野笋，留客馈家蔬。
古柳依沙发，春苗带雨锄。
共怜芳杜色，终日伴闲居。','',''),('quantangshi-07161','寄万州崔使君','劉長卿','quantangshi','','卷8','时艰方用武，儒者任浮沈。
摇落秋江暮，怜君巴峡深。
丘门多白首，蜀郡满青襟。
自解书生咏，愁猨莫夜吟。','',''),('quantangshi-07162','送马秀才移家京洛便赴举','劉長卿','quantangshi','','卷8','自从为楚客，不复扫荆扉。
劒共丹诚在，书随白发归。
旧游经乱静，后进识君稀。
空把相如赋，何人荐礼闱。','',''),('quantangshi-07163','送南特进赴归行营','劉長卿','quantangshi','','卷8','闻道军书至，扬鞭不问家。
虏云连白草，汉月到黄沙。
汗马河源饮，烧羌陇坻遮。
翩翩新结束，去逐李轻车。','',''),('quantangshi-07164','送道标上人归南岳','劉長卿','quantangshi','','卷8','悠然倚孤棹，却忆卧中林。
江草将归远，湘山独往深。
白云留不住，渌水去无心。
衡岳千峰乱，禅房何处寻。','',''),('quantangshi-07165','送梁侍御巡永州','劉長卿','quantangshi','','卷8','萧萧江雨暮，客散野亭空。
忧国天涯去，思乡岁暮同。
到时猨未断，回处水应穷。
莫望零陵路，千峰万木中。','',''),('quantangshi-07166','岁夜喜魏万成郭夏雪中相寻','劉長卿','quantangshi','','卷8','新年欲变柳，旧客共霑衣。
岁夜犹难尽，乡春又独归。
寒灯映虚牖，暮雪掩闲扉。
且莫乘船去，平生相访稀。','',''),('quantangshi-07167','送蔡侍御赴上都','劉長卿','quantangshi','','卷8','迟迟立驷马，久客恋潇湘。
明日谁同路，新年独到乡。
孤烟向驿远，积雪去关长。
秦地看春色，南枝不可忘。','',''),('quantangshi-07168','晦日陪辛大夫宴南亭','劉長卿','quantangshi','','卷8','月晦逢休澣，年光逐宴移。
早莺留客醉，春日为人迟。
蓂草全无叶，梅花遍压枝。
政闲风景好，莫比岘山时。','',''),('quantangshi-07169','送独孤判官赴岭','劉長卿','quantangshi','','卷8','伏波初树羽，待尔静川鳞。
岭海看飞鸟，天涯问远人。
苍梧云里夕，青草嶂中春。
遥想文身国，迎舟拜使臣。','',''),('quantangshi-07170','长沙馆中与郭夏对雨','劉長卿','quantangshi','','卷8','长沙积雨晦，深巷绝人幽。
润上春衣冷，声连暮角愁。
云横全楚地，树暗古湘洲。
杳蔼江天外，空堂生百忧。','',''),('quantangshi-07171','陪辛大夫西亭宴观妓','劉長卿','quantangshi','','卷8','歌舞怜迟日，旌麾映早春。
莺窥陇西将，花对洛阳人。
醉罢知何事，恩深忘此身。
任他行雨去，归路裛香尘。','',''),('quantangshi-07172','题魏万成江亭','劉長卿','quantangshi','','卷8','萧条方岁晏，牢落对空洲。
才出时人右，家贫湘水头。
苍山隐暮雪，白鸟没寒流。
不是莲花府，冥冥不可求。','',''),('quantangshi-07173','春过裴虬郊园','劉長卿','quantangshi','','卷8','郊原春欲暮，桃杏落纷纷。
何处随芳草，留家寄白云。
听莺情念友，看竹恨无君。
长啸高台上，南风冀尔闻。','',''),('quantangshi-07174','送韦赞善使岭南','劉長卿','quantangshi','','卷8','欲逐楼船将，方安卉服夷。
炎洲经瘴远，春水上泷迟。
岁贡随重译，年芳徧四时。
番禺静无事，空咏饮泉诗。','',''),('quantangshi-07175','送乔判官赴福州','劉長卿','quantangshi','','卷8','扬帆向何处，插羽逐征东。
夷落人烟迥，王程鸟路通。
江流回涧底，山色聚闽中。
君去凋残后，应怜百越空。','',''),('quantangshi-07176','送李补阙之上都','劉長卿','quantangshi','','卷8','独归西掖去，难接后尘游。
向日三千里，朝天十二楼。
路看新柳夕，家对旧山秋。
惆怅离心远，沧江空自流。','',''),('quantangshi-07177','送袁明府之任','劉長卿','quantangshi','','卷8','既有亲人术，还逢试吏年。
蓬蒿千里闭，村树几家全。
雪覆淮南道，春生颍谷烟。
何时当莅政，相府待闻天。','',''),('quantangshi-07178','海盐官舍早春','劉長卿','quantangshi','','卷8','小邑沧洲吏，新年白首翁。
一官如远客，万事极飘蓬。
柳色孤城里，莺声细雨中。
羁心早已乱，何事更春风。','',''),('quantangshi-07179','南湖送徐二十七西上','劉長卿','quantangshi','','卷8','家在横塘曲，那能万里违。
门临秋水掩，帆带夕阳飞。
傲俗宜纱帽，干时倚布衣。
独将湖上月，相逐去还归。','',''),('quantangshi-07180','曲阿对月别岑况徐说','劉長卿','quantangshi','','卷8','金陵已芜没，函谷复烟尘。
犹见南朝月，还随上国人。
白云心自远，沧海意相亲。
何事须成别，汀洲欲暮春。','',''),('quantangshi-07181','送李侍御贬鄱阳','劉長卿','quantangshi','','卷8','回车仍昨日，谪去已秋风。
干越知何处，云山只向东。
暮天江色里，田鹤稻花中。
却见鄱阳吏，犹应旧马骢。','',''),('quantangshi-07182','送路少府使东京便应制举','劉長卿','quantangshi','','卷8','故人西奉使，胡骑正纷纷。
旧国无来信，春江独送君。
五言淩白雪，六翮向青云。
谁念沧州吏，忘机鸥鸟羣。','',''),('quantangshi-07183','松江独宿','劉長卿','quantangshi','','卷8','洞庭初下叶，孤客不胜愁。
明月天涯夜，青山江上秋。
一官成白首，万里寄沧洲。
久被浮名系，能无愧海鸥。','',''),('quantangshi-07184','寻白石山真禅师旧草堂','劉長卿','quantangshi','','卷8','惆怅云山暮，闲门独不开。
何时飞杖锡，终日闭苍苔。
隔岭春犹在，无人燕亦来。
谁堪暝投处，空复一猨哀。','',''),('quantangshi-07185','送行军张司马罢使回','劉長卿','quantangshi','','卷8','时危身赴敌，事往任浮沈。
末路三江去，当时百战心。
春风吴苑绿，古木剡山深。
千里沧波上，孤舟不可寻。','',''),('quantangshi-07186','喜李翰自越至','劉長卿','quantangshi','','卷8','南浮沧海上，万里到吴台。
久别长相忆，孤舟何处来。
春风催客醉，江月向人开。
羡尔无羁束，沙鸥独不猜。','',''),('quantangshi-07187','罪所留系寄张十四','劉長卿','quantangshi','','卷8','不见君来久，冤深意未传。
冶长空得罪，夷甫岂言钱。
直道天何在，愁容镜亦怜。
因书欲自诉，无泪可潸然。','',''),('quantangshi-07188','送勤照和尚往睢阳赴太守请','劉長卿','quantangshi','','卷8','燃灯传七祖，杖锡为诸侯。
来去云无意，东西水自流。
青山春满目，白日夜随舟。
知到梁园下，苍生赖此游。','',''),('quantangshi-07189','长门怨','劉長卿','quantangshi','','卷8','何事长门闭，珠帘只自垂。
月移深殿早，春向后宫迟。
蕙草生闲地，梨花发旧枝。
芳菲自恩幸，看着被风吹。','',''),('quantangshi-07190','过横山顾山人草堂','劉長卿','quantangshi','','卷8','只见山相掩，谁言路尚通。
人来千嶂外，犬吠百花中。
细草香飘雨，垂杨闲卧风。
却寻樵径去，惆怅绿溪东。','',''),('quantangshi-07191','送李校书适越谒杜中丞','劉長卿','quantangshi','','卷8','江风处处尽，旦暮水空波。
摇落行人去，云山向越多。
陈蕃悬榻待，谢客枉帆过。
相见耶溪路，逶迤入薜萝。','',''),('quantangshi-07192','秋夜雨中诸公过灵光寺所居','劉長卿','quantangshi','','卷8','晤语青莲舍，重门闭夕阴。
向人寒烛静，带雨夜钟沈。
流水从他事，孤云任此心。
不能捐斗粟，终日愧瑶琴。','',''),('quantangshi-07193','西庭夜燕喜评事兄拜会','劉長卿','quantangshi','','卷8','犹是南州吏，江城又一春。
隔帘湖上月，对酒眼中人。
棘寺初衔命，梅仙已误身。
无心羡荣禄，唯待却垂纶。','',''),('quantangshi-07194','寻南溪常山道人隐居','劉長卿','quantangshi','','卷8','一路经行处，莓苔见履痕。
白云依静渚，春草闭闲门。
过雨看松色，随山到水源。
溪花与禅意，相对亦忘言。','',''),('quantangshi-07195','扬州雨中张十宅观妓','劉長卿','quantangshi','','卷8','夜色带春烟，灯花拂更然。
残妆添石黛，艳舞落金钿。
掩笑频欹扇，迎歌乍动弦。
不知巫峡雨，何事海西边。','',''),('quantangshi-07196','赴宣州使院夜宴寂上人房留辞前苏州韦使君','劉長卿','quantangshi','','卷8','白云乖始愿，沧海有微波。
恋旧争趋府，临危欲负戈。
春归花殿暗，秋傍竹房多。
耐可机心息，其如羽檄何。','',''),('quantangshi-07197','送薛承矩秩满北游','劉長卿','quantangshi','','卷8','匹马向何处，北游殊未还。
寒云带飞雪，日暮雁门关。
一路傍汾水，数州看晋山。
知君喜初服，秪爱此身闲。','',''),('quantangshi-07198','饯别王十一南游','劉長卿','quantangshi','','卷8','望君烟水阔，挥手泪霑巾。
飞鸟没何处，青山空向人。
长江一帆远，落日五湖春。
谁见汀洲上，相思愁白苹。','',''),('quantangshi-07199','送严维尉诸暨','劉長卿','quantangshi','','卷8','爱尔文章远，还家印绶荣。
退公兼色养，临下带乡情。
乔木映官舍，春山宜县城。
应怜钓台石，闲却为浮名。','',''),('quantangshi-07200','送李七之莋水谒张相公','劉長卿','quantangshi','','卷8','惆怅青春晚，殷勤浊酒垆。
后时长劒涩，斜日片帆孤。
东阁邀才子，南昌老腐儒。
梁国旧相识，谁忆卧江湖。','',''),('quantangshi-07201','送崔处士先适越','劉長卿','quantangshi','','卷8','山阴好云物，此去又春风。
越鸟闻花里，曹娥想镜中。
小江潮易满，万井水皆通。
徒羡扁舟客，微官事不同。','',''),('quantangshi-07202','奉陪使君西庭送淮西魏判官','劉長卿','quantangshi','','卷8','羽檄催归恨，春风醉别颜。
能邀五马送，自逐一星还。
破竹从军乐，看花听讼闲。
遥知用兵处，多在八公山。','',''),('quantangshi-07203','狱中见壁画佛','劉長卿','quantangshi','','卷8','不谓衔冤处，而能窥大悲。
独栖丛棘下，还见雨花时。
地狭青莲小，城高白日迟。
幸亲方便力，犹畏毒龙欺。','',''),('quantangshi-07204','送许拾遗还京','劉長卿','quantangshi','','卷8','万里辞三殿，金陵到旧居。
文星出西掖，卿月在南徐。
故里惊朝服，高堂捧诏书。
暂容乘驷马，谁许恋鲈鱼。','',''),('quantangshi-07205','送张七判官还京觐省','劉長卿','quantangshi','','卷8','春兰方可采，此去叶初齐。
函谷莺声里，秦山马首西。
庭闱新栢署，门馆旧桃蹊。
春色长安道，相随入禁闺。','',''),('quantangshi-07206','送孙莹京监擢第归蜀觐省','劉長卿','quantangshi','','卷8','适贺一枝新，旋惊万里分。
礼闱称独步，太学许能文。
征马望春草，行人看暮云。
遥知倚门处，江树正氛氲。','',''),('quantangshi-07207','送史九赴任宁陵兼呈单父史八时监察五兄初入台','劉長卿','quantangshi','','卷8','趋府弟联兄，看君此去荣。
春随千里道，河带万家城。
绣服棠花映，青袍草色迎。
梁园修竹在，持赠结交情。','',''),('quantangshi-07208','卧病喜田九见寄','劉長卿','quantangshi','','卷8','卧来能几日，春事已依然。
不解谢公意，翻令静者便。
庭阴残旧雪，柳色带新年。
寂寞深村里，唯君相访偏。','',''),('quantangshi-07209','重过宣峰寺山房寄灵一上人','劉長卿','quantangshi','','卷8','西陵潮信满，岛屿入中流。
越客依风水，相思南渡头。
寒光生极浦，暮雪映沧洲。
何事扬帆去，空惊海上鸥。','',''),('quantangshi-07210','云门寺访灵一上人','劉長卿','quantangshi','','卷8','所思劳日夕，惆怅去西东。
禅客知何在，春山到处同。
独行残雪里，相见白云中。
请近东林寺，穷年事远公。','',''),('quantangshi-07211','送陆羽之茅山寄李延陵','劉長卿','quantangshi','','卷8','延陵衰草遍，有路问茅山。
鸡犬驱将去，烟霞拟不还。
新家彭泽县，旧国穆陵关。
处处逃名姓，无名亦是闲。','',''),('quantangshi-07212','寄灵一上人初还云门','劉長卿','quantangshi','','卷8','寒霜白云里，法侣自相携。
竹迳通城下，松风隔水西。
方同沃洲去，不作武陵迷。
仿髴知心处，高峰是会稽。','',''),('quantangshi-07213','寄灵一上人','劉長卿','quantangshi','','卷8','高僧本姓竺，开士旧名林。
一去春山里，千峰不可寻。
新年芳草遍，终日白云深。
欲徇微官去，悬知讶此心。','',''),('quantangshi-07214','送韩司直','劉長卿','quantangshi','','卷8','游吴还入越，来往任风波。
复送王孙去，其如春草何。
岸明残雪在，潮满夕阳多。
季子杨柳庙，停舟试一过。','',''),('quantangshi-07215','酬李郎中夜登苏州城楼见寄','劉長卿','quantangshi','','卷8','辛勤万里道，萧索九秋残。
日照闽中夜，天凝海上寒。
客程无地远，主意在人安。
遥寄登楼作，空知行路难。','',''),('quantangshi-07216','送人游越','劉長卿','quantangshi','','卷8','未习风波事，初为吴越游。
露霑湖色晓，月照海门秋。
梅市门何在，兰亭水尚流。
西陵待潮处，落日满扁舟。','',''),('quantangshi-07217','赠普门上人','劉長卿','quantangshi','','卷8','支公身欲老，长在沃洲多。
惠力堪传教，禅心久伏魔。
山云随坐夏，江草伴头陀。
借问回心后，贤愚去几何。','',''),('quantangshi-07218','送康判官往新安','劉長卿','quantangshi','','卷8','不向新安去，那知江路长。
猨声近庐霍，水色胜潇湘。
驿路收残雨，渔家带夕阳。
何须愁旅泊，使者有辉光。','',''),('quantangshi-07219','送顾长','劉長卿','quantangshi','','卷8','由来山水客，复道向新安。
半是乘槎便，全非行路难。
晨装林月在，野饭浦沙寒。
严子千年后，何人钓旧滩。','',''),('quantangshi-07220','九日登李明府北楼','劉長卿','quantangshi','','卷8','九日登高望，苍苍远树低。
人烟湖草里，山翠县楼西。
霜降鸿声切，秋深客思迷。
无劳白衣酒，陶令自相携。','',''),('quantangshi-07221','同诸公登楼','劉長卿','quantangshi','','卷8','秋草行将暮，登楼客思惊。
千家同霁色，一雁报寒声。
北望无乡信，东游滞客行。
今君佩铜墨，还有越乡情。','',''),('quantangshi-07222','送友人南游','劉長卿','quantangshi','','卷8','不愁寻水远，自爱逐连山。
虽在春风里，犹从芳草间。
去程何用计，胜事且相关。
旅逸同羣鸟，悠悠往复还。','',''),('quantangshi-07223','送裴二十一','劉長卿','quantangshi','','卷8','多病长无事，开筵暂送君。
正愁帆带雨，莫望水连云。
客思闲偏极，川程远更分。
不须论早晚，惆怅又离羣。','',''),('quantangshi-07224','送张判官罢使东归','劉長卿','quantangshi','','卷8','白首辞知己，沧洲忆旧居。
落潮回野艇，积雪卧官庐。
范叔寒犹在，周王岁欲除。
春山数亩地，归去带经鉏。','',''),('quantangshi-07225','早春','劉長卿','quantangshi','','卷8','微雨夜来歇，江南春色回。
本惊时不住，还恐老相催。
人好千场醉，花无百日开。
岂堪沧海畔，为客十年来。','',''),('quantangshi-07226','送青苗郑判官归江西','劉長卿','quantangshi','','卷8','三苗余古地，五稼满秋田。
来问周公税，归输汉俸钱。
江城寒背日，湓水暮连天。
南楚凋残后，疲民赖尔怜。','',''),('quantangshi-07227','过包尊师山院','劉長卿','quantangshi','','卷8','卖药曾相识，吹萧此复闻。
杏花谁是主，桂树独留君。
漱玉临丹井，围碁访白云。
道经今为写，不虑惜鹅羣。','',''),('quantangshi-07228','故女道士婉仪太原郭氏挽歌词 一','劉長卿','quantangshi','','卷8','作范宫闱睦，归真道艺超。
驭风仙路远，背日帝宫遥。
鸾殿空留处，霓裳已罢朝。
淮王哀不尽，松柏但萧萧。','',''),('quantangshi-07229','故女道士婉仪太原郭氏挽歌词 二','劉長卿','quantangshi','','卷8','宫禁恩长隔，神仙道已分。
人间惊早露，天上失朝云。
逝水年无限，佳城日易曛。
箫声将薤曲，哀断不堪闻。','',''),('quantangshi-07230','少年行','劉長卿','quantangshi','','卷8','射飞夸侍猎，行乐爱联镳。
荐枕青蛾艳，鸣鞭白马骄。
曲房珠翠合，深巷管弦调。
日晚春风里，衣香满路飘。','',''),('quantangshi-07231','归弋阳山居留别卢邵二侍御','劉長卿','quantangshi','','卷8','渺渺归何处，沿流附客船。
久依鄱水住，频税越人田。
偶俗机偏少，安闲性所便。
祗应君少惯，又欲寄林泉。','',''),('quantangshi-07232','赴江西湖上赠皇甫曾之宣州','劉長卿','quantangshi','','卷8','莫恨扁舟去，川途我更遥。
东西潮渺渺，离别雨萧萧。
流水通春谷，青山过板桥。
天涯有来客，迟尔访渔樵。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-07233','湘中纪行十首 湘妃庙','劉長卿','quantangshi','','卷8','荒祠古木暗，寂寂此江濆。
未作湘南雨，知为何处云。
苔痕断珠履，草色带罗裙。
莫唱迎仙曲，空山不可闻。','',''),('quantangshi-07234','湘中纪行十首 斑竹岩','劉長卿','quantangshi','','卷8','苍梧在何处，斑竹自成林。
点点留残泪，枝枝寄此心。
寒山响易满，秋水影偏深。
欲觅樵人路，蒙笼不可寻。','',''),('quantangshi-07235','湘中纪行十首 洞山阳','劉長卿','quantangshi','','卷8','旧日仙成处，荒林客到稀。
白云将犬去，芳草任人归。
空谷无行径，深山少落晖。
桃园几家住，谁为扫荆扉。','',''),('quantangshi-07236','湘中纪行十首 云母溪','劉長卿','quantangshi','','卷8','云母映溪水，溪流知几春。
深藏武陵客，时过洞庭人。
白发惭皎镜，清光媚奫沦。
寥寥古松下，岁晚挂头巾。','',''),('quantangshi-07237','湘中纪行十首 赤沙湖','劉長卿','quantangshi','','卷8','茫茫葭菼外，一望一霑衣。
秋水连天阔，涔阳何处归。
沙鸥积暮雪，川日动寒晖。
楚客来相问，孤舟泊钓矶。','',''),('quantangshi-07238','湘中纪行十首 秋云岭','劉長卿','quantangshi','','卷8','山色无定姿，如烟复如黛。
孤峰夕阳后，翠岭秋天外。
云起遥蔽亏，江回频向背。
不知今远近，到处犹相对。','',''),('quantangshi-07239','湘中纪行十首 花石潭','劉長卿','quantangshi','','卷8','江枫日摇落，转爱寒潭静。
水色淡如空，山光复相映。
人闲流更慢，鱼戏波难定。
楚客往来多，偏知白鸥性。','',''),('quantangshi-07240','湘中纪行十首 石围峰','劉長卿','quantangshi','','卷8','前山带秋色，独往秋江晚。
叠嶂入云多，孤峰去人远。
[夤]缘不可到，苍翠空在眼。
渡口问渔家，桃源路深浅。','',''),('quantangshi-07241','湘中纪行十首 浮石濑','劉長卿','quantangshi','','卷8','秋月照潇湘，月明闻荡桨。
石横晚濑急，水落寒沙广。
众岭猨啸重，空江人语响。
清晖朝复暮，如待扁舟赏。','',''),('quantangshi-07242','湘中纪行十首 横龙渡','劉長卿','quantangshi','','卷8','空传古岸下，曾见蛟龙去。
秋水晚沈沈，犹疑在深处。
乱声沙上石，倒影云中树。
独见一扁舟，樵人往来渡。','',''),('quantangshi-07243','杂咏八首上礼部李侍郎 幽琴','劉長卿','quantangshi','','卷8','月色满轩白，琴声宜夜阑。
飗飗青丝上，静听松风寒。
古调虽自爱，今人多不弹。
向君投此曲，所贵知音难。','',''),('quantangshi-07244','杂咏八首上礼部李侍郎 晚桃','劉長卿','quantangshi','','卷8','四月深涧底，桃花方欲然。
宁知地势下，遂使春风偏。
此意颇堪惜，无言谁为传。
过时君未赏，空媚幽林前。','',''),('quantangshi-07245','杂咏八首上礼部李侍郎 疲马','劉長卿','quantangshi','','卷8','玄黄一疲马，筋力尽胡尘。
骧首北风夕，徘徊鸣向人。
谁怜弃置久，欲与驽骀亲。
犹恋长城外，青青寒草春。','',''),('quantangshi-07246','杂咏八首上礼部李侍郎 春镜','劉長卿','quantangshi','','卷8','宝镜凌曙开，含虚净如水。
独悬秦台上，万象清光里。
岂虑高鉴偏，但防流尘委。
不知娉婷色，回照今何似。','',''),('quantangshi-07247','杂咏八首上礼部李侍郎 古劒','劉長卿','quantangshi','','卷8','龙泉闲古匣，苔藓沦此地。
何意久藏锋，翻令世人弃。
铁衣今正涩，宝刃犹可试。
傥遇拂拭恩，应知剸犀利。','',''),('quantangshi-07248','杂咏八首上礼部李侍郎 旧井','劉長卿','quantangshi','','卷8','旧井依旧城，寒水深洞彻。
下看百余尺，一镜光不灭。
素绠久未垂，清凉尚含洁。
岂能无汲引，长讶君恩绝。','',''),('quantangshi-07249','杂咏八首上礼部李侍郎 白鹭','劉長卿','quantangshi','','卷8','亭亭常独立，川上时延颈。
秋水寒白毛，夕阳吊孤影。
幽姿闲自媚，逸翮思一骋。
如有长风吹，青云在俄顷。','',''),('quantangshi-07250','杂咏八首上礼部李侍郎 寒釭','劉長卿','quantangshi','','卷8','向夕灯稍进，空堂弥寂寞。
光寒对愁人，时复一花落。
但恐明见累，何愁暗难托。
恋君秋夜永，无使兰膏薄。','',''),('quantangshi-07251','寄李侍御','劉長卿','quantangshi','','卷8','旧国人未归，芳洲草还碧。
年年湖上亭，怅望江南客。
骢马入关西，白云独何适。
相思烟水外，唯有心不隔。','',''),('quantangshi-07252','晚泊湘江怀故人','劉長卿','quantangshi','','卷8','天涯片云去，遥指帝乡忆。
惆怅增暮情，潇湘复秋色。
扁舟宿何处，落日羡归翼。
万里无故人，江鸥不相识。','',''),('quantangshi-07253','过鄥三湖上书斋','劉長卿','quantangshi','','卷8','何事东南客，忘机一钓竿。
酒香开瓮老，湖色对门寒。
向郭青山送，临池白鸟看。
见君能浪迹，予亦厌微官。','',''),('quantangshi-07254','从军六首 一','劉長卿','quantangshi','','卷8','回看虏骑合，城下汉兵稀。
白刃两相向，黄云愁不飞。
手中无尺铁，徒欲突重围。','',''),('quantangshi-07255','从军六首 二','劉長卿','quantangshi','','卷8','目极雁门道，青青边草春。
一身事征战，匹马同苦辛。
末路成白首，功归天下人。','',''),('quantangshi-07256','从军六首 三','劉長卿','quantangshi','','卷8','倚劒白日暮，望乡登戍楼。
北风吹羌笛，此夜关山愁。
回首不无意，滹河空自流。','',''),('quantangshi-07257','从军六首 四','劉長卿','quantangshi','','卷8','黄沙一万里，白首无人怜。
报国劒已折，归乡身幸全。
单于古台下，边色寒苍然。','',''),('quantangshi-07258','从军六首 五','劉長卿','quantangshi','','卷8','落日更萧条，北风动枯草。
将军追虏骑，夜失阴山道。
战败仍树勋，韩彭但空老。','',''),('quantangshi-07259','从军六首 六','劉長卿','quantangshi','','卷8','草枯秋塞上，望见渔阳郭。
胡马嘶一声，汉兵泪双落。
谁为吮疮者，此事今人薄。','',''),('quantangshi-07260','龙门八咏 阙口','劉長卿','quantangshi','','卷8','秋山日摇落，秋水急波澜。
独见鱼龙气，长令烟雨寒。
谁穷造化力，空向两崖看。','',''),('quantangshi-07261','龙门八咏 水东渡','劉長卿','quantangshi','','卷8','山叶傍崖赤，千峰秋色多。
夜泉发清响，寒渚生微波。
稍见沙上月，归人争渡河。','',''),('quantangshi-07262','龙门八咏 福公塔','劉長卿','quantangshi','','卷8','寂寞对伊水，经行长未还。
东流自朝暮，千载空云山。
谁见白鸥鸟，无心洲渚间。','',''),('quantangshi-07263','龙门八咏 远公龛','劉長卿','quantangshi','','卷8','松路向精舍，花龛归老僧。
闲云随锡杖，落日低金绳。
入夜翠微里，千峰明一灯。','',''),('quantangshi-07264','龙门八咏 石楼','劉長卿','quantangshi','','卷8','隐隐见花阁，隔河映青林。
水田秋雁下，山寺夜钟深。
寂寞羣动息，风泉清道心。','',''),('quantangshi-07265','龙门八咏 下山','劉長卿','quantangshi','','卷8','谁识往来意，孤云长自闲。
风寒未渡水，日暮更看山。
木落众峰出，龙宫苍翠间。','',''),('quantangshi-07266','龙门八咏 水西渡','劉長卿','quantangshi','','卷8','伊水摇镜光，纤鳞如不隔。
千龛道傍古，一鸟沙上白。
何事还山云，能留向城客。','',''),('quantangshi-07267','龙门八咏 渡水','劉長卿','quantangshi','','卷8','日暮下山来，千山暮钟发。
不知波上棹，还弄山中月。
伊水连白云，东南远明灭。','',''),('quantangshi-07268','月下听砧','劉長卿','quantangshi','','卷8','夜静掩寒城，清砧发何处？
声声捣秋月，肠断卢龙戍。
未得寄征人，愁霜复愁露。','',''),('quantangshi-07269','送丘为赴上都','劉長卿','quantangshi','','卷8','帝乡何处是，歧路空垂泣。
楚思愁暮多，川程带潮急。
潮归人不归，独向空塘立。','',''),('quantangshi-07270','题大理黄主簿湖上高斋','劉長卿','quantangshi','','卷8','闭门湖水畔，自与白鸥亲。
竟日窗中岫，终年林下人。
俗轻儒服弊，家厌法官贫。
多雨茅檐夜，空洲草径春。
桃源君莫爱，且作汉朝臣。','',''),('quantangshi-07271','平蕃曲三首 一','劉長卿','quantangshi','','卷8','吹角报蕃营，回军欲洗兵。
已教青海外，自筑汉家城。','',''),('quantangshi-07272','平蕃曲三首 二','劉長卿','quantangshi','','卷8','渺渺戍烟孤，茫茫塞草枯。
陇头那用闭，万里不防胡。','',''),('quantangshi-07273','平蕃曲三首 三','劉長卿','quantangshi','','卷8','绝漠大军还，平沙独戍闲。
空留一片石，万古在燕山。','',''),('quantangshi-07274','送郑说之歙州谒薛侍郎','劉長卿','quantangshi','','卷8','漂泊来千里，讴谣满百城。
汉家尊太守，鲁国重诸生。
俗变人难理，江传水至清。
船经危石住，路入乱山行。
老得沧州趣，春伤白首情。
尝闻马南郡，门下有康成。','',''),('quantangshi-07275','题独孤使君湖上林亭','劉長卿','quantangshi','','卷8','出树倚朱阑，吹铙引上官。
老农持锸拜，时稼卷帘看。
水对登龙净，山当建隼寒。
夕阳湖草动，秋色渚田宽。
渤海人无事，荆州客独安。
谢公何足比，来往石门难。','',''),('quantangshi-07276','酬滁州李十六使君见赠','劉長卿','quantangshi','','卷8','满镜悲华发，空山寄此身。
白云家自有，黄卷业长贫。
嬾任垂竿老，狂因酿黍春。
桃花迷圣代，桂树狎幽人。
幢盖方临郡，柴荆忝作邻。
但愁千骑至，石路却生尘。','',''),('quantangshi-07277','送严维赴河南充严中丞幕府','劉長卿','quantangshi','','卷8','久别耶溪客，来乘使者轩。
用才荣入幕，扶病喜同樽。
山屐留何处，江帆去独翻。
暮情辞镜水，秋梦识云门。
莲府开花萼，桃园寄子孙。
何当举严助，徧沐汉朝恩。','',''),('quantangshi-07278','酬包谏议佶见寄之什','劉長卿','quantangshi','','卷8','佐郡愧顽疎，殊方亲里闾。
家贫寒未度，身老岁将除。
过雪山僧至，依阳野客舒。
药陈随远宦，梅发对幽居。
落日栖鸮鸟，行人遗鲤鱼。
高文不可和，空愧学相如。','',''),('quantangshi-07279','栖霞寺东峰寻南齐明征君故居','劉長卿','quantangshi','','卷8','山人今不见，山鸟自相从。
长啸辞明主，终身卧此峰。
泉源通石径，磵户掩尘容。
古墓依寒草，前朝寄老松。
片云生断壁，万壑遍疎钟。
惆怅空归去，犹疑林下逢。','',''),('quantangshi-07280','奉和赵给事使君留赠李婺州舍人兼谢舍人别驾之什','劉長卿','quantangshi','','卷8','便道访情亲，东方千骑尘。
禁深分直夜，地远独行春。
绛阙辞明主，沧洲识近臣。
云山随候吏，鸡犬逐归人。
庭顾婆娑老，邦传蔽芾新。
玄晖翻佐理，闻到郡斋频。','',''),('quantangshi-07281','行营酬吕侍御时尚书问罪襄阳军次汉东境上侍御以州邻寇贼复有水火迫于征税诗以见谕','劉長卿','quantangshi','','卷8','不敢淮南卧，来趋汉将营。
受辞瞻左钺，扶疾往前旌。
井税鹑衣乐，壶浆鹤发迎。
水归余断岸，烽至掩孤城。
晚日归千骑，秋风合五兵。
孔璋才素健，早晚檄书成。','',''),('quantangshi-07282','登迁仁楼酬子壻李穆','劉長卿','quantangshi','','卷8','临风敞丽谯，落日听吹铙。
归路空回首，新章已在腰。
非才受官谤，无政作人谣。
俭岁安三户，余年寄六条。
春芜生楚国，古树过隋朝。
赖有东牀客，池塘免寂寥。','',''),('quantangshi-07283','别李氏女子','劉長卿','quantangshi','','卷8','念尔嫁犹近，稚年那别亲。
临歧方教诲，所贵和六姻。
俛首戴荆钗，欲拜凄且嚬。
本来儒家子，莫耻梁鸿贫。
汉川若可涉，水清石磷磷。
天涯远乡妇，月下孤舟人。','',''),('quantangshi-07284','长沙早春雪后临湘水呈同游诸子','劉長卿','quantangshi','','卷8','汀洲暖渐渌，烟景淡相和。
举目方如此，归心岂奈何。
日华浮野雪，春色染湘波。
北渚生芳草，东风变旧柯。
江山古思远，猨鸟暮情多。
君问渔人意，沧浪自有歌。','',''),('quantangshi-07285','自道林寺西入石路至麓山寺过法崇禅师故居','劉長卿','quantangshi','','卷8','山僧候谷口，石路拂莓苔。
深入泉源去，遥从树杪回。
香随青霭散，钟过白云来。
野雪空斋掩，山风古殿开。
桂寒知自发，松老问谁栽。
惆怅湘江水，何人更渡杯。','',''),('quantangshi-07286','和袁郎中破贼后军行过剡中山水谨上太尉','劉長卿','quantangshi','','卷8','剡路除荆棘，王师罢鼓鼙。
农归沧海畔，围解赤城西。
赦罪春阳发，收兵太白低。
远峰来马首，横笛入猨啼。
兰渚催新幄，桃源识故蹊。
已闻开阁待，谁许卧东溪。','',''),('quantangshi-07287','送郑十二还庐山别业','劉長卿','quantangshi','','卷8','浔阳数亩宅，归卧掩柴关。
谷口何人待，门前秋草闲。
忘机卖药罢，无语杖藜还。
旧笋成寒竹，空斋向暮山。
水流经舍下，云去到人间。
桂树花应发，因行寄一攀。','',''),('quantangshi-07288','至饶州寻陶十七不在寄赠','劉長卿','quantangshi','','卷8','谪宦投东道，逢君已北辕。
孤蓬向何处，五柳不开门。
去国空回首，怀贤欲诉冤。
梅枝横岭峤，竹路过湘源。
月下高秋雁，天南独夜猨。
离心与流水，万里共朝昏。','',''),('quantangshi-07289','奉陪郑中丞自宣州解印与诸侄宴余干后溪','劉長卿','quantangshi','','卷8','迹远亲鱼鸟，功成厌鼓鼙。
林中阮生集，池上谢公题。
户牖垂藤合，藩离插槿齐。
夕阳山向背，春草水东西。
度雨诸峰出，看花几路迷。
何劳问秦汉，更入武陵溪。','',''),('quantangshi-07290','同诸公袁郎中宴筵喜加章服','劉長卿','quantangshi','','卷8','手诏来筵上，腰金向粉闱。
勋名传旧阁，蹈舞着新衣。
白社同游在，沧洲此会稀。
寒笳发后殿，秋草送西归。
世难常摧敌，时闲已息机。
鲁连功可让，千载一相挥。','',''),('quantangshi-07291','毗陵送邹结先赴河南充判官','劉長卿','quantangshi','','卷8','王事相逢少，云山奈别何。
芳年临水怨，瓜步上潮过。
客路方经楚，乡心共渡河。
凋残春草在，离乱故城多。
罢战逢时泰，轻徭伫俗和。
东西此分手，惆怅恨烟波。','',''),('quantangshi-07292','送徐大夫赴广州','劉長卿','quantangshi','','卷8','上将坛场拜，南荒羽檄招。
远人来百越，元老事三朝。
雾绕龙山暗，山连象郡遥。
路分江淼淼，军动马萧萧。
画角知秋气，楼船逐暮潮。
当令输贡赋，不使外夷骄。','',''),('quantangshi-07293','九日题蔡国公主楼','劉長卿','quantangshi','','卷8','主第人何在，重阳客暂寻。
水余龙镜色，云罢凤箫音。
暗牖藏昏晓，苍苔换古今。
晴山卷幔出，秋草闭门深。
篱菊仍新吐，庭槐尚旧阴。
年年画梁燕，来去岂无心。','',''),('quantangshi-07294','送荀八过山阴旧县兼寄剡中诸官','劉長卿','quantangshi','','卷8','访旧山阴县，扁舟到海涯。
故林嗟满岁，春草忆佳期。
晚景千峰乱，晴江一鸟迟。
桂香留客处，枫暗泊舟时。
旧石曹娥篆，空山夏禹祠。
剡溪多隐吏，君去道相思。','',''),('quantangshi-07295','奉饯元侍郎加豫章采访兼赐章服','劉長卿','quantangshi','','卷8','任重兼乌府，时平偃豹韬。
澄清湘水变，分别楚山高。
花对彤襜发，霜和白雪操。
黄金装旧马，青草换新袍。
岭暗猿啼月，江寒鹭映涛。
豫章生宇下，无使翳篷蒿。','',''),('quantangshi-07296','奉饯郎中四兄罢余杭太守承恩加侍御史充行军司马赴汝南行营','劉長卿','quantangshi','','卷8','星使三江上，天波万里通。
权分金节重，恩借铁冠雄。
梅吹前军发，棠阴旧府空。
残春锦障外，初日羽旗东。
岸柳遮浮鷁，江花隔避骢。
离心在何处，芳草满吴宫。','',''),('quantangshi-07297','送贾侍御克复后入京','劉長卿','quantangshi','','卷8','对酒心不乐，见君动行舟。
回看暮帆隐，独向空江愁。
晴云淡初夜，春塘深慢流。
温颜风霜霁，喜气烟尘收。
驰馹数千里，朝天十二楼。
因之报亲爱，白发生沧洲。','',''),('quantangshi-07298','会稽王处士草堂壁画衡霍诸山','劉長卿','quantangshi','','卷8','粉壁衡霍近，羣峰如可攀。
能令堂上客，见尽湖南山。
青翠数千仞，飞来方丈间。
归云无处灭，去鸟何时还？
胜事日相对，主人常独闲。
稍看林壑晚，佳气生重关。','',''),('quantangshi-07299','惠福寺与陈留诸官茶会','劉長卿','quantangshi','','卷8','到此机事遣，自嫌尘网迷。
因知万法幻，尽与浮云齐。
疎竹映高枕，空花随杖藜。
香飘诸天外，日隐双林西。
傲吏方见狎，真僧幸相携。
能令归客意，不复还东溪。','',''),('quantangshi-07300','金陵西泊舟临江楼','劉長卿','quantangshi','','卷8','萧条金陵郭，旧是帝王州。
日暮望乡处，云边江树秋。
楚云不可托，楚水只堪愁。
行客千万里，沧波朝暮流。
迢迢洛阳梦，独卧清川楼。
异乡共如此，孤帆难久游。','',''),('quantangshi-07301','题灵佑上人法华院木兰花','劉長卿','quantangshi','','卷8','庭种南中树，年华几度新。
已依初地长，独发旧园春。
映日成华盖，摇风散锦茵。
色空荣落处，香醉往来人。
菡萏千灯遍，芳菲一雨均。
高柯傥为檝，渡海有良因。','',''),('quantangshi-07302','宿严维宅送包佶','劉長卿','quantangshi','','卷8','江湖同避地，分首自依依。
尽室今为客，惊秋空念归。
岁储无别墅，寒服羡邻机。
草色春桥晚，蝉声江树稀。
夜深宜共醉，时难忍相违。
何事随阳雁，汀洲忽背飞。','',''),('quantangshi-07303','送从弟贬袁州','劉長卿','quantangshi','','卷8','何事成迁客，思归不见乡。
游吴经万里，吊屈向三湘。
水与荆巫接，山通鄢郢长。
名羞黄绶系，身是白眉郎。
独结南枝恨，应思北雁行。
忧来沽楚酒，老鬓莫凝霜。','',''),('quantangshi-07304','无锡东郭送友人游越','劉長卿','quantangshi','','卷8','客路风霜晓，郊原春兴余。
平芜不可望，游子去何如。
烟水乘湖阔，云山适越初。
旧都怀作赋，古穴觅藏书。
碑缺曹娥宅，林荒逸少居。
江湖无限意，非独为樵渔。','',''),('quantangshi-07305','送邵州判官往南','劉長卿','quantangshi','','卷8','看君发原隰，驷牡志皇皇。
始罢沧江令，还随粉署郎。
海沂军未息，河兖岁仍荒。
征税人全少，榛芜虏近亡。
新知行宋远，相望隔淮长。
早晚裁书寄，银钩伫八行。','',''),('quantangshi-07306','出丰县界寄韩明府','劉長卿','quantangshi','','卷8','回首古原上，未能辞旧乡。
西风收暮雨，隐隐分芒砀。
贤友此为邑，令名满徐方。
音容想在眼，暂若升琴堂。
疲马顾春草，行人看夕阳。
自非传尺素，谁为论中肠。','',''),('quantangshi-07307','别陈留诸官','劉長卿','quantangshi','','卷8','恋此东道主，能令西上迟。
徘徊暮郊别，惆怅秋风时。
上国邈千里，夷门难再期。
行人望落日，归马嘶空陂。
不愧宝刀赠，维怀琼树枝。
音尘倘未接，梦寐徒相思。','',''),('quantangshi-07308','观李凑所画美人障子','劉長卿','quantangshi','','卷8','爱尔含天姿，丹青有殊智。
无间已得象，象外更生意。
西子不可见，千载无重还。
空令浣沙态，犹在含毫间。
一笑岂易得，双蛾如有情。
窗风不举袖，但觉罗衣轻。
华堂翠幕春风来，内阁金屏曙色开。
此中一见乱人目，只疑行到云阳台。','',''),('quantangshi-07309','送史判官奏事之灵武兼寄巴西亲故','劉長卿','quantangshi','','卷8','中州日纷梗，天地何时泰。
独有西归心，遥悬夕阳外。
故人奉章奏，此去论利害。
阳雁南渡江，征骖去相背。
因君欲寄远，何处问亲爱。
空使沧洲人，相思减衣带。','',''),('quantangshi-07310','自鄱阳还道中寄褚征君','劉長卿','quantangshi','','卷8','南风日夜起，万里孤帆漾。
元气连洞庭，夕阳落波上。
故人烟水隔，复此遥相望。
江信久寂寥，楚云独惆怅。
爱君清川口，弄月时棹唱。
白首无子孙，一生自疎旷。','',''),('quantangshi-07311','石梁湖有寄','劉長卿','quantangshi','','卷8','故人千里道，沧波一年别。
夜上明月楼，相思楚天阔。
潇潇清秋暮，袅袅凉风发。
湖色淡不流，沙鸥远还灭。
烟波日已远，音问日已绝。
岁晏空含情，江臯绿芳歇。','',''),('quantangshi-07312','送沈少府之任淮南','劉長卿','quantangshi','','卷8','惜君滞南楚，枳棘徒栖凤。
独与千里帆，春风远相送。
此行山水好，时物亦应众。
一鸟飞长淮，百花满云梦。
相期丹霄路，遥听清风颂。
勿为州县卑，时来自为用。','',''),('quantangshi-07313','严子濑东送马处直归苏','劉長卿','quantangshi','','卷8','望君舟已远，落日潮未退。
目送沧海帆，人行白云外。
江中远回首，波上生微霭。
秋色姑苏台，寒流子陵濑。
相送苦易散，动别知难会。
从此日相思，空令减衣带。','',''),('quantangshi-07314','宿怀仁县南湖寄东海荀处士','劉長卿','quantangshi','','卷8','向夕歛微雨，晴开湖上天。
离人正惆怅，新月愁婵娟。
伫立白沙曲，相思沧海边。
浮云自来去，此意谁能传。
一水不相见，千峰随客船。
寒塘起孤雁，夜色分盐田。
时复一延首，忆君如眼前。','',''),('quantangshi-07315','初至洞庭怀灞陵别业','劉長卿','quantangshi','','卷8','长安邈千里，日夕怀双阙。
已是洞庭人，犹看灞陵月。
谁堪去乡意，亲戚想天末。
昨夜梦中归，烟波觉来阔。
江臯见芳草，孤客心欲绝。
岂讶青春来，但伤经时别。
长天不可望，鸟与浮云没。','',''),('quantangshi-07316','题萧郎中开元寺新构幽寂亭','劉長卿','quantangshi','','卷8','康乐爱山水，赏心千载同。
结茅依翠微，伐木开蒙笼。
孤峰倚青霄，一径去不穷。
候客石苔上，礼僧云树中。
旷然见沧洲，自远来清风。
五马留谷口，双旌薄烟虹。
沈沈众香积，眇眇诸天空。
独往应未遂，苍生思谢公。','',''),('quantangshi-07317','同姜浚题裴式微余干东斋','劉長卿','quantangshi','','卷8','世事终成梦，生涯欲半过。
白云心已矣，沧海意如何。
藜杖全吾道，榴花养太和。
春风骑马醉，江月钓鱼歌。
散帙看虫蠹，开门见雀罗。
远山终日在，芳草傍人多。
吏体庄生傲，方言楚俗譌。
屈平君莫吊，肠断洞庭波。','',''),('quantangshi-07318','赠元容州','劉長卿','quantangshi','','卷8','拥旌临合浦，上印卧长沙。
海徼长无戍，湘山独种畲。
政传通岁贡，才惜过年华。
万里依孤劒，千峰寄一家。
累征期旦暮，未起恋烟霞。
避世歌芝草，休官醉菊花。
旧游如梦里，此别是天涯。
何事沧波上，漂漂逐海槎。','',''),('quantangshi-07319','夏口送长宁杨明府归荆南因寄幕府诸公','劉長卿','quantangshi','','卷8','关西杨太尉，千载德犹闻。
白日俱终老，清风独至君。
身承远祖遗，才出众人羣。
举世贪荆玉，全家恋楚云。
向烟帆杳杳，临水叶纷纷。
草覆昭丘绿，江从夏口分。
高名光盛府，异姓宠殊勋。
百越今无事，南征欲罢军。','',''),('quantangshi-07320','奉和杜相公新移长兴宅呈元相公','劉長卿','quantangshi','','卷8','间世生贤宰，同心奉至尊。
功高开北第，机静灌中园。
入并蝉冠影，归分骑士喧。
窗闻汉宫漏，家识杜陵源。
献替常焚藁，优闲独对萱。
花香逐荀令，草色对王孙。
有地先开阁，何人不扫门。
江湖难自退，明主托元元。','',''),('quantangshi-07321','湖南使还留辞辛大夫','劉長卿','quantangshi','','卷8','王师劳近甸，兵食仰诸侯。
天子无南顾，元勋在上游。
大才生间气，盛业拯横流。
风景随摇笔，山川入运筹。
羽觞交饯席，旄节对归舟。
莺识春深恨，猿知日去愁。
别离花寂寂，南北水悠悠。
唯有家兼国，终身共所忧。','',''),('quantangshi-07322','泛曲阿后湖简同游诸公','劉長卿','quantangshi','','卷8','元气浮积水，沈沈深不流。
春风万顷绿，映带至徐州。
为客难适意，逢君方暂游。
夤缘白苹际，日暮沧浪舟。
渡口微月进，林西残雨收。
水云去仍湿，沙鹤鸣相留。
且习子陵隐，能忘生事忧。
此中深有意，非为钓鱼钩。','',''),('quantangshi-07323','北游酬孟云卿见寄','劉長卿','quantangshi','','卷8','忽忽忘前事，事愿能相乖。
衣马日羸弊，谁辨行与才。
善道居贫贱，洁服蒙尘埃。
行行无定止，懔坎难归来。
慈母忧疾疹，室家念栖莱。
幸君夙姻亲，深见中外怀。
俟子惜时节，怅望临高台。','',''),('quantangshi-07324','冬夜宿扬州开元寺烈公房送李侍御之江东','劉長卿','quantangshi','','卷8','迁客投百越，穷阴淮海凝。
中原驰困兽，万里栖饥鹰。
寂寂连宇下，爱君心自弘。
空堂来霜气，永夜清明灯。
发后望烟水，相思劳寝兴。
暮帆背楚郭，江色浮金陵。
此去尔何恨，近名予未能。
炉峰若便道，为访东林僧。','',''),('quantangshi-07325','南楚怀古','劉長卿','quantangshi','','卷8','南国久芜没，我来空郁陶。
君看章华宫，处处生蓬蒿。
但见陵与谷，岂知贤与豪。
精魂托古木，宝劒捐江臯。
倚棹下晴景，回舟随晚涛。
碧云暮寥落，湖上秋天高。
往事那堪问，此心徒自劳。
独余湘水上，千载闻离骚。','',''),('quantangshi-07326','上湖田馆南楼忆朱晏','劉長卿','quantangshi','','卷8','漂泊日复日，洞庭今更秋。
白云如有意，万里望孤舟。
何事爱成别，空令登此楼。
天光映波动，月影随江流。
鹤唳静寒渚，猿啼深夜洲。
归期诚已促，清景仍相留。
顷者慕独往，尔来悲远游。
风波自此去，桂水空离忧。','',''),('quantangshi-07327','送姚八之句容旧任便归江南','劉長卿','quantangshi','','卷8','故人还水国，春色动离忧。
碧草千万里，沧江朝暮流。
桃花迷旧路，萍叶荡归舟。
远戍看京口，空城问石头。
折芳佳丽地，望月西南楼。
猨鸟共孤屿，烟波连数州。
谁家过楚老，何处恋江鸥。
尺素能相报，湖山若个忧。','',''),('quantangshi-07328','睢阳赠李司仓','劉長卿','quantangshi','','卷8','白露变时候，蛬声暮啾啾。
飘飘洛阳客，惆怅梁园秋。
只为乏生计，尔来成远游。
一身不家食，万事从人求。
且喜接余论，足堪资小留。
寒城落日后，砧杵令人愁。
归路岁时尽，长河朝夕流。
非君深意愿，谁复能相忧。','',''),('quantangshi-07329','杪秋洞庭中怀亡道士谢太虚','劉長卿','quantangshi','','卷8','漂泊日复日，洞庭今更秋。
青枫亦何意，此夜催人愁。
惆怅客中月，徘徊江上楼。
心知楚天远，目送沧波流。
羽客久已殁，微言无处求。
空余白云在，容与随孤舟。
千里杳难望，一身当独游。
故园复何许，江海徒迟留。','',''),('quantangshi-07330','同郭参谋咏崔仆射淮南节度使厅前竹','劉長卿','quantangshi','','卷8','昔种梁王苑，今移汉将坛。
蒙笼低冕过，青翠卷帘看。
得地移根远，经霜抱节难。
开花成凤实，嫩笋长鱼竿。
蔼蔼军容静，萧萧郡宇宽。
细音和角暮，疎影上门寒。
湘浦何年变，山阳几处残。
不知轩屏侧，岁晚对袁安。','',''),('quantangshi-07331','硖石遇雨宴前主簿从兄子英宅','劉長卿','quantangshi','','卷8','县城苍翠里，客路两崖开。
硖石云漠漠，东风吹雨来。
吾兄此为吏，薄宦知无媒。
方寸抱秦镜，声名传楚材。
折腰五斗间，僶俛随尘埃。
秩满少余俸，家贫仍散财。
谁言次东道，暂预倾金罍。
虽欲少留此，其如归限催。','',''),('quantangshi-07332','江中晚钓寄荆南一二相识','劉長卿','quantangshi','','卷8','楚郭微雨收，荆门遥在目。
漾舟水云里，日暮春江绿。
霁华静洲渚，暝色连松竹。
月出波上时，人归渡头宿。
一身已无累，万事更何欲。
渔父自夷犹，白鸥不羁束。
既怜沧浪水，复爱沧浪曲。
不见眼中人，相思心断续。','',''),('quantangshi-07333','九日岳阳待黄遂张涣','劉長卿','quantangshi','','卷8','别君颇已久，离念与时积。
楚水空浮烟，江楼望归客。
徘徊正伫想，仿髴如暂觌。
心目徒自亲，风波尚相隔。
青林泊舟处，猿鸟愁孤驿。
遥见郭外山，苍然雨中夕。
季鹰久疎旷，叔度早畴昔。
反棹来何迟，黄花候君摘。','',''),('quantangshi-07334','题王少府尧山隐处简陆鄱阳','劉長卿','quantangshi','','卷8','故人沧洲吏，深与世情薄。
解印二十年，委身在丘壑。
买田楚山下，妻子自耕凿。
羣动心有营，孤云本无着。
因收溪上钓，遂接林中酌。
对酒春日长，山村杏花落。
陆生鄱阳令，独步建溪作。
早晚休此官，随君永栖托。','',''),('quantangshi-07335','晚次湖口有怀','劉長卿','quantangshi','','卷8','霭然空水合，目极平江暮。
南望天无涯，孤帆落何处。
顷为衡湘客，颇见湖山趣。
朝气和楚云，夕阳映江树。
帝乡劳想望，万里心来去。
白发生扁舟，沧波满归路。
秋风今已至，日夜雁南度。
木叶辞洞庭，纷纷落无数。','',''),('quantangshi-07336','陪元侍御游支硎山寺','劉長卿','quantangshi','','卷8','支公去已久，寂寞龙华会。
古木闭空山，苍然暮相对。
林峦非一状，水石有余态。
密竹藏晦明，羣峰争向背。
峰峰带落日，步步入青霭。
香气空翠中，猿声暮云外。
留连南台客，想像西方内。
因逐溪水还，观心两无碍。','',''),('quantangshi-07337','桂阳西州晚泊古桥村住人','劉長卿','quantangshi','','卷8','洛阳别离久，江上心可得。
惆怅增暮情，潇湘复秋色。
故山隔何处，落日羡归翼。
沧海空自流，白鸥不相识。
悲蛬满荆渚，辍棹徒沾臆。
行客念寒衣，主人愁夜织。
帝乡片云去，遥寄千里忆。
南路随天长，征帆杳无极。','',''),('quantangshi-07338','夕次檐石湖梦洛阳亲故','劉長卿','quantangshi','','卷8','天涯望不尽，日暮愁独去。
万里云海空，孤帆向何处。
寄身烟波里，颇得湖山趣。
江气和楚云，秋声乱枫树。
如何异乡县，日复怀亲故。
遥与洛阳人，相逢梦中路。
不堪明月里，更值清秋暮。
倚棹对沧波，归心共谁语。','',''),('quantangshi-07339','按覆后归睦州赠苗侍御','劉長卿','quantangshi','','卷8','地远心难达，天高谤易成。
羊肠留覆辙，虎口脱余生。
直氏偷金枉，于家决狱明。
一言知己重，片议杀身轻。
日下人谁忆，天涯客独行。
年光销蹇步，秋气入衰情。
建德知何在，长江问去程。
孤舟百口渡，万里一猿声。
落日开乡路，空山向郡城。
岂令冤气积，千古在长平。','',''),('quantangshi-07340','奉寄婺州李使君舍人','劉長卿','quantangshi','','卷8','建隼罢鸣珂，初传来暮歌。
渔樵识太古，草树得阳和。
东道诸生从，南依远客过。
天清婺女出，土厚绛人多。
永日空相望，流年复几何。
崖开当夕照，叶去逐寒波。
眼暗经难受，身闲劒懒磨。
似鸮占贾谊，上马试廉颇。
穷分安藜藿，衰容胜薜萝。
只应随越鸟，南翥托高柯。','',''),('quantangshi-07341','哭魏兼遂','劉長卿','quantangshi','','卷8','古今俱此去，修短竟谁分。
樽酒空如在，弦琴肯重闻。
一门同逝水，万事共浮云。
旧馆何人宅，空山远客坟。
艰危贫且共，少小秀而文。
独行依穷巷，全身出乱军。
岁时长寂寞，烟月自氛氲。
壠树随人古，山门对日曛。
泛舟悲向子，留劒赠徐君。
来去云阳路，伤心江水濆。','',''),('quantangshi-07342','负谪后登干越亭作','劉長卿','quantangshi','','卷8','天南愁望绝，亭上柳条新。
落日独归鸟，孤舟何处人。
生涯投越徼，世业陷胡尘。
杳杳钟陵暮，悠悠鄱水春。
秦台悲白首，楚泽怨青苹。
草色迷征路，莺声伤逐臣。
独醒空取笑，直道不容身。
得罪风霜苦，全生天地仁。
青山数行泪，沧海一穷鳞。
牢落机心尽，惟怜鸥鸟亲。','',''),('quantangshi-07343','留题李明府霅溪水堂','劉長卿','quantangshi','','卷8','寥寥此堂上，幽意复谁论。
落日无王事，青山在县门。
云峰向高枕，渔钓入前轩。
晚竹疎帘影，春苔双履痕。
荷香随坐卧，湖色映晨昏。
虚牖闲生白，鸣琴静对言。
暮禽飞上下，春水带清浑。
远岸谁家柳，孤烟何处村。
谪居投瘴疠，离思过湘沅。
从此扁舟去，谁堪江浦猿。','',''),('quantangshi-07344','入白沙渚夤缘二十五里至石窟山下怀天台陆山人','劉長卿','quantangshi','','卷8','远屿霭将夕，玩幽行自迟。
归人不计日，流水闲相随。
辍棹古崖口，扪萝春景迟。
偶因回舟次，宁与前山期。
对此瑶草色，怀君琼树枝。
浮云去寂寞，白鸟相因依。
何事爱高隐，但令劳远思。
穷年卧海峤，永望愁天涯。
吾亦从此去，扁舟何所之？
迢迢江上帆，千里东风吹。','',''),('quantangshi-07345','禅智寺上方怀演和尚寺即和尚所创','劉長卿','quantangshi','','卷8','绝巘东林寺，高僧惠远公。
买园隋苑下，持钵楚城中。
斗极千灯近，烟波万井通。
远山低月殿，寒木露花宫。
绀宇焚香净，沧州摆雾空。
雁来秋色里，曙起早潮东。
飞锡今何在？苍生待发蒙。
白云翻送客，庭树自辞风。
舍筏追开士，回舟狎钓翁。
平生江海意，惟共白鸥同。','',''),('quantangshi-07346','贾侍郎自会稽使回篇什盈卷兼蒙见寄一首与余有挂冠之期因书数事率成十韵','劉長卿','quantangshi','','卷8','江上逢星使，南来自会稽。
惊年一叶落，按俗五花嘶。
上国悲芜梗，中原动鼓鼙。
报恩看铁劒，衔命出金闺。
风物催归绪，云峰发咏题。
天长百越外，潮上小江西。
鸟道通闽岭，山光落剡溪。
暮帆千里思，秋夜一猨啼。
柏树荣新壠，桃源忆故蹊。
若能为休去，行复草萋萋。','',''),('quantangshi-07347','秋日夏口涉汉阳献李相公','劉長卿','quantangshi','','卷8','日望衡门处，心知汉水濆。
偶乘青雀舫，还在白鸥羣。
间气生灵秀，先朝翼戴勋。
藏弓身已退，焚藳事难闻。
旧业成青草，全家寄白云。
松萝长稚子，风景逐新文。
山带寒城出，江依古岸分。
楚歌悲远客，羌笛怨孤军。
鼎罢调梅久，门看种药勤。
十年犹去国，黄叶又纷纷。','',''),('quantangshi-07348','归沛县道中晚泊留侯城','劉長卿','quantangshi','','卷8','访古此城下，子房安在哉？
白云去不反，危堞空崔嵬。
伊昔楚汉时，颇闻经济才。
运筹风尘下，能使天地开。
蔓草日已积，长松日已摧。
功名满青史，祠庙唯苍苔。
百里暮程远，孤舟川上回。
进帆东风便，转岸前山来。
楚水澹相引，沙鸥闲不猜。
扣舷从此去，延首仍裴回。','',''),('quantangshi-07349','关门望华山','劉長卿','quantangshi','','卷8','客路瞻太华，三峰高际天。
夏云亘百里，合沓遥相连。
雷雨飞半腹，太阳在其巅。
翠微关上近，瀑布林梢悬。
爱此众容秀，能令西望偏。
徘徊忘暝色，泱漭成阴烟。
会是朝百灵，亦闻会羣仙。
琼浆岂易挹，毛女非空传。
仿髴仍伫想，幽期如眼前。
金天有青庙，松柏隐苍然。','',''),('quantangshi-07350','奉陪萧使君入鲍达洞寻灵山寺','劉長卿','quantangshi','','卷8','山居秋更鲜，秋江相映碧。
独临沧洲路，如待挂帆客。
遂使康乐侯，披榛着双屐。
入云开岭道，永日寻泉脉。
古寺隐青冥，空中寒磬夕。
苍苔绝行径，飞鸟无去迹。
树杪下归人，水声过幽石。
任情趣逾远，移步奇屡易。
萝木静蒙蒙，风烟深寂寂。
徘徊未能去，畏共桃源隔。','',''),('quantangshi-07351','孙权故城下怀古兼送友人归建业','劉長卿','quantangshi','','卷8','雄图争割据，神器终不守。
上下武昌城，长江竟何有。
古来壮台榭，事往悲陵阜。
寥落几家人，犹依数株柳。
威灵绝想像，芜没空林薮。
野径春草中，郊扉夕阳后。
逢君从此去，背楚方东走。
烟际指金陵，潮时过湓口。
行人已何在，临水徒挥手。
惆怅不能归，孤帆没云久。','',''),('quantangshi-07352','宿双峰寺寄卢七李十六','劉長卿','quantangshi','','卷8','寥寥禅诵处，满室虫丝结。
独与山中人，无心生复灭。
徘徊双峰下，惆怅双峰月。
杳杳暮猿深，苍苍古松列。
玩奇不可尽，渐远更幽绝。
林暗僧独归，石寒泉且咽。
竹房响轻吹，萝径阴余雪。
卧涧晓何迟，背岩春未发。
此游诚多趣，独往共谁阅。
得意空自归，非君岂能说。','',''),('quantangshi-07353','京口怀洛阳旧居兼寄广陵二三知己','劉長卿','quantangshi','','卷8','川阔悲无梁，蔼然沧波夕。
天涯一飞鸟，日暮南徐客。
气混京口云，潮吞海门石。
孤帆候风进，夜色带江白。
一水阻佳期，相望空脉脉。
那堪岁芳尽，更使春梦积。
故国胡尘飞，远山楚云隔。
家人想何在，庭草为谁碧。
惆怅空伤情，沧浪有余迹。
严陵七里滩，携手同所适。','',''),('quantangshi-07354','登扬州栖灵寺塔','劉長卿','quantangshi','','卷8','北塔凌空虚，雄观压川泽。
亭亭楚云外，千里看不隔。
遥对黄金台，浮辉乱相射。
盘梯接元气，半壁栖夜魄。
稍登诸劫尽，若骋排霄翮。
向是沧洲人，已为青云客。
雨飞千栱霁，日在万家夕。
鸟处高却低，天涯远如迫。
江流入空翠，海峤现微碧。
向暮期下来，谁堪复行役。','',''),('quantangshi-07355','湖上遇郑田','劉長卿','quantangshi','','卷8','故人青云器，何意常窘迫。
三十犹布衣，怜君头已白。
谁言此相见，暂得话畴昔。
旧业今已芜，还乡返为客。
扁舟伊独往，斗酒君自适。
沧洲不可涯，孤帆去无迹。
杯中忽复醉，湖上生月魄。
湛湛江色寒，蒙蒙水云夕。
风波易迢遰，千里如咫尺。
回首人已遥，南看楚天隔。','',''),('quantangshi-07356','雨中登沛县楼赠表兄郭少府','劉長卿','quantangshi','','卷8','楚泽秋更远，云雷有时作。
晚陂带残雨，白水昏漠漠。
伫立收烟氛，洗然静寥廓。
卷帘高楼上，万里看日落。
为客频改弦，辞家尚如昨。
故山今不见，此鸟那可托。
小邑务常闲，吾兄宦何薄。
高标青云器，独立沧江鹤。
惠爱原上情，殷勤丘中诺。
何当遂良愿，归卧青山郭。','',''),('quantangshi-07357','灞东晚晴简同行薛弃朱训','劉長卿','quantangshi','','卷8','客心豁初霁，霁色暝玄灞。
西向看夕阳，曈曈映桑柘。
二贤诚逸足，千里陪征驾。
古树枳道傍，人烟杜陵下。
伊余在羁束，且复随造化。
好道当有心，营生苦无暇。
高贤幸兹偶，英达穷王霸。
迢遰客王程，裴回主人夜。
一薫知异质，片玉谁齐价。
同结丘中缘，尘埃自兹谢。','',''),('quantangshi-07358','对雨赠济阴马少府考城蒋少府兼献成武五兄南华二兄','劉長卿','quantangshi','','卷8','繁云兼家思，弥望连济北。
日暮微雨中，州城带秋色。
萧条主人静，落叶飞不息。
乡梦寒更频，虫声夜相逼。
二贤纵横器，久滞徒劳职。
笑语和风骚，雍容事文墨。
吾兄即时彦，前路良未测。
秋水百丈清，寒松一枝直。
此心欲引托，谁为生羽翼。
且复顿归鞍，杯中雪胸臆。','',''),('quantangshi-07359','李侍御河北使回至东京相访','劉長卿','quantangshi','','卷8','故人南台秀，夙擅中朝美。
拥传从北来，飞霜日千里。
贫居幸相访，顾我柴门里。
却讶绣衣人，仍交布衣士。
王程遽尔迫，别恋从此始。
浊酒未暇斟，清文颇垂示。
回瞻骢马速，但见行尘起。
日暮汀洲寒，春风渡流水。
草色官道边，桃花御沟里。
天涯一鸟夕，惆怅知何已。','',''),('quantangshi-07360','吴中闻潼关失守因奉寄淮南萧判官','劉長卿','quantangshi','','卷8','一雁飞吴天，羁人伤暮律。
松江风袅袅，波上片帆疾。
木落姑苏台，霜收洞庭橘。
萧条长洲外，唯见寒山出。
胡马嘶秦云，汉兵乱相失。
关中因窃据，天下共忧栗。
南楚有琼枝，相思怨瑶瑟。
一身寄沧洲，万里看白日。
赴敌甘负戈，论兵勇投笔。
临风但攘臂，择木将委质。
不如归远山，云卧饭松栗。','',''),('quantangshi-07361','哭张员外继','劉長卿','quantangshi','','卷8','恸哭钟陵下，东流与别离。
二星来不返，双劒没相随。
独继先贤传，谁刊有道碑。
故园荒岘曲，旅榇寄天涯。
白简曾连拜，沧洲每共思。
抚孤怜齿穉，叹逝顾身衰。
泉壤成终古，云山若在时。
秋风邻笛发，寒日寝门悲。
世难愁归路，家贫缓葬期。
旧宾伤未散，夕临咽常迟。
自此辞张邵，何由见戴逵。
独闻山吏部，流涕访孤儿。','',''),('quantangshi-07362','登东海龙兴寺高顶望海简演公','劉長卿','quantangshi','','卷8','朐山压海口，永望开禅宫。
元气远相合，太阳生其中。
豁然万里余，独为百川雄。
白波走雷电，黑雾藏鱼龙。
变化非一状，晴明分众容。
烟开秦帝桥，隐隐横残虹。
蓬岛如在眼，羽人那可逢。
偶闻真僧言，甚与静者同。
幽意颇相惬，赏心殊未穷。
花间午时梵，云外春山钟。
谁念遽成别，自怜归所从。
他时相忆处，惆怅西南峯。','',''),('quantangshi-07363','奉送从兄罢官之淮南','劉長卿','quantangshi','','卷8','何事浮溟渤，元戎弃镆鎁。
渔竿吾道在，鸥鸟世情赊。
玄发他乡换，沧洲此路遐。
溯沿随桂檝，醒醉任松华。
离别谁堪道，艰危更可嗟。
兵锋摇海内，王命隔天涯。
钟漏移长乐，衣冠接永嘉。
还当拂氛祲，那复卧云霞。
溪路漫冈转，夕阳归鸟斜。
万艘江县郭，一树海人家。
挥袂看朱绂，扬帆指白沙。
春风独回首，愁思极如麻。','',''),('quantangshi-07364','落第赠杨侍御兼拜员外仍充安大夫判官赴范阳','劉長卿','quantangshi','','卷8','职副旌旄重，才兼识量通。
使车遥肃物，边策远和戎。
掷地金声着，从军宝劒雄。
官成稽古力，名达济时功。
肃穆乌台上，雍容粉署中。
含香初待漏，持简旧生风。
黠吏偏惊隼，贪夫辄避骢。
且知荣已隔，谁谓道仍同。
念旧追连茹，谋生任转蓬。
泣连三献玉，疮惧再伤弓。
恋土函关外，瞻尘灞水东。
他时书一札，犹冀问途穷。','',''),('quantangshi-07365','初贬南巴至鄱阳题李嘉佑江亭','劉長卿','quantangshi','','卷8','巴峤南行远，长江万里随。
不才甘谪去，流水亦何之。
地远明君弃，天高酷吏欺。
清山独往路，芳草未归时。
流落还相见，悲懽话所思。
猜嫌伤薏苡，愁暮向江篱。
柳色迎高坞，荷衣照下帷。
水云初起重，暮鸟远来迟。
白首看长劒，沧洲寄钓丝。
沙鸥惊小吏，湖月上高枝。
稚子能吴语，新文怨楚辞。
怜君不得意，川谷自逶迤。','',''),('quantangshi-07366','初贬南巴至鄱阳题李嘉佑江亭','劉長卿','quantangshi','','卷8','南出巴人徼，长江万里随。
不才甘谪去，流水亦何之。
地逺明君弃，天髙酷吏欺。
青山独往路，芳草未归时。
流落还相见，悲欢话所思。
猜谗伤薏苡，愁暮向江蓠。
泪尽㸔长劔，心闲寄钓𢇁。
水云初起重，暮鸟逺来迟。
稚子能吴语，新文怨楚词。
怜君不得意，客鬓老南枝。','',''),('quantangshi-07367','自紫阳观至华阳洞宿侯尊师草堂简同游李延年','劉長卿','quantangshi','','卷8','石门媚烟景，句曲盘江甸。
南向佳气浓，数峰遥隐见。
渐临华阳口，云路入葱蒨。
七曜悬洞宫，五云抱仙殿。
银函竟谁发，金液徒堪荐。
千载空桃花，秦人深不见。
东溪喜相遇，贞白如会面。
青鸟来去闲，红霞朝夕变。
一从换仙骨，万里乘飞电。
萝月延步虚，松花醉闲宴。
幽人即长往，茂宰应交战。
明发归琴堂，知君嬾为县。','',''),('quantangshi-07368','奉使新安自桐庐县经严陵钓台宿七里滩下寄使院诸公','劉長卿','quantangshi','','卷8','悠然钓台下，怀古时一望。
江水自潺湲，行人独惆怅。
新安从此始，桂檝方荡漾。
回转百里间，青山千万状。
连崖去不断，对岭遥相向。
夹岸黛色愁，沈沈绿波上。
夕阳留古木，水鸟拂寒浪。
月下扣舷声，烟中采菱唱。
犹怜负羁束，未暇依清旷。
牵役徒自劳，近名非所向。
何时故山里，却醉松花酿。
回首唯白云，孤舟复谁访。','',''),('quantangshi-07369','题虎丘寺','劉長卿','quantangshi','','卷8','青林虎丘寺，林际翠微路。
仰见山僧来，遥从飞鸟处。
兹峰沦宝玉，千载唯丘墓。
埋劒人空传，凿山龙已去。
扪萝披翳荟，路转夕阳遽。
虎啸崖谷寒，猿鸣杉松暮。
裴回北楼上，江海穷一顾。
日映千里帆，鸦归万家树。
蹔因惬所适，果得损外虑。
庭暗栖闲云，檐香滴甘露。
久迷空寂理，多为繁华故。
永欲投死生，余生岂能误。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-07370','奉饯郑中丞罢浙西节度还京','劉長卿','quantangshi','','卷8','天上移将星，元戎罢龙节。
三军含怨慕，横吹声断绝。
五马嘶城隅，万人卧车辙。
沧洲浮云暮，杳杳去帆发。
回首不问家，归心遥向阙。
烟波限吴楚，日夕事淮越。
吊影失所依，侧身随下列。
孤蓬飞不定，长劒光未灭。
绿绮为谁弹，绿芳堪自撷。
怅然江南春，独此湖上月。
千里怀去思，百忧变华发。
颂声满江海，今古流不竭。','',''),('quantangshi-07371','送裴四判官赴河西军试','劉長卿','quantangshi','','卷8','吏道岂易惬，如君谁与俦。
逢时将骋骥，临事无全牛。
鲍叔幸相知，田苏颇同游。
英资挺孤秀，清论含古流。
出塞佐持简，辞家拥鸣驺。
宪台贵公举，幕府资良筹。
武士伫明试，皇华难久留。
阳关望天尽，洮水令人愁。
万里看一鸟，旷然烟霞收。
晚花对古戍，春雪含边州。
道路难暂隔，音尘那可求。
他时相望处，明月西南楼。','',''),('quantangshi-07372','旅次丹阳郡遇康侍御宣慰召募兼别岑单父','劉長卿','quantangshi','','卷8','客心暮千里，回首烟花繁。
楚水渡归梦，春江连故园。
羁人怀上国，骄虏窥中原。
胡马暂为害，汉臣多负恩。
羽书昼夜飞，海内风尘昏。
双鬓日已白，孤舟心且论。
绣衣从此来，汗马宣王言。
忧愤激忠勇，悲欢动黎元。
南徐争赴难，发卒如云屯。
倚劒看太白，洗兵临海门。
故人亦沧洲，少别堪伤魂。
积翠下京口，归潮落山根。
如何天外帆，又此波上尊。
空使忆君处，莺声催泪痕。','',''),('quantangshi-07373','客舍赠别韦九建赴任河南韦十七造赴任郑县就便觐省','劉長卿','quantangshi','','卷8','与子颇畴昔，常时仰英髦。
弟兄尽公器，诗赋凌风骚。
顷者游上国，独能光选曹。
香名冠二陆，精鉴逢山涛。
且副倚门望，莫辞趋府劳。
桃花照彩服，草色连青袍。
征马临素浐，离人倾浊醪。
华山微雨霁，祠上残云高。
而我倦栖屑，别君良郁陶。
春风亦未已，旅思空滔滔。
拙分甘弃置，穷居长蓬蒿。
人生未鵾化，物议如鸿毛。
迢递两乡别，殷勤一宝刀。','',''),('quantangshi-07374','送元八游汝南','劉長卿','quantangshi','','卷8','元生实奇迈，幸此论畴昔。
刀笔素推高，锋铓久无敌。
纵横济时意，跌宕过人迹。
破产供酒钱，盈门皆食客。
田园顷失计，资用深相迫。
生事诚可忧，严装远何适。
世情薄恩义，俗态轻穷厄。
四海金虽多，其如向人惜。
迢递朗陵道，怅望都门夕。
向别伊水南，行看楚云隔。
繁蝉动高柳，疋马嘶平泽。
潢潦今正深，陂湖未澄碧。
人生不得已，自可甘形役。
勿复尊前酒，离居剩凄戚。','',''),('quantangshi-07375','奉和李大夫同吕评事太行苦热行兼寄院中诸公仍呈王员外','劉長卿','quantangshi','','卷8','迢递太行路，自古称险恶。
千骑俨欲前，羣峰望如削。
火云从中出，仰视飞鸟落。
汗马卧高原，危旌倚长薄。
清风竟不至，赤日方煎铄。
石枯山木燋，鳞穷水泉涸。
九重今旰食，万里传明略。
诸将候轩车，元凶愁鼎镬。
何劳短兵接，自有长缨缚。
通越事岂难，渡泸功未博。
朝辞羊肠阪，夕望贝丘郭。
漳水斜遶营，常山遥入幕。
永怀姑苏下，遥寄建安作。
白雪和难成，沧波意空托。
陈琳书记好，王粲从军乐。
早晚归汉廷，随公上麟阁。','',''),('quantangshi-07376','洛阳主簿叔知和驿承恩赴选伏辞一首','劉長卿','quantangshi','','卷8','仲父王佐材，屈身仇香位。
一从理京剧，万事皆容易。
则知无不可，通变有余地。
器宇溟渤宽，文锋镆铘利。
憧憧洛阳道，日夕皇华使。
二载出江亭，一心奉王事。
功成良可录，道在知无愧。
天府留香名，铨闱就明试。
赋诗皆旧友，攀辙多新吏。
彩服辞高堂，青袍拥征骑。
此行季春月，时物正鲜媚。
官柳阴相连，桃花色如醉。
长安想在目，前路遥仿髴。
落日看华山，关门逼青翠。
行襜稍已隔，结恋无能慰。
谁念尊酒间，裴回竹林意。','',''),('quantangshi-07377','题冤句宋少府厅留别','劉長卿','quantangshi','','卷8','宋侯人之秀，独步南曹吏。
世上无此才，天生一公器。
尚甘黄绶屈，未适青云意。
洞澈万顷陂，昂藏千里骥。
从宦闻苦节，应物推高谊。
薄俸不自资，倾家共人费。
顾予倦栖托，终日忧穷匮。
开口即有求，私心岂无愧。
幸逢东道主，因辍西征骑。
对话堪息机，披文欲忘味。
壶觞招过客，几案无留事。
绿树映层城，苍苔覆闲地。
一言重然诺，累夕陪宴慰。
何意秋风来，飒然动归思。
留欢殊自惬，去念能为累。
草色愁别时，槐花落行次。
临期仍把手，此会良不易。
他日琼树枝，相思劳梦寐。','',''),('quantangshi-07378','罢摄官后将还旧居留辞李侍御','劉長卿','quantangshi','','卷8','江海今为客，风波失所依。
白云心已负，黄绶计仍非。
累辱羣公荐，频霑一尉微。
去缘焚玉石，来为采葑菲。
州县名何在，渔樵事亦违。
故山桃李月，初服薜萝衣。
熊轼分朝寄，龙韬解贼围。
风谣传吏体，云物助兵威。
白云飘辞律，青春发礼闱。
引军横吹动，援翰捷书挥。
草映翻营绿，花临檄羽飞。
全吴争转战，狂虏怯知机。
忆昨趋金节，临时废玉徽。
俗流应不厌，静者或相讥。
世难慵干谒，时闲喜放归。
潘郎悲白发，谢客爱清辉。
樗散材因弃，交亲迹已稀。
独愁看五柳，无事掩双扉。
世累多行路，生涯向钓矶。
榜连溪水碧，家羡渚田肥。
旅食伤飘梗，岩栖忆采薇。
悠然独归去，回首望旌旗。','',''),('quantangshi-07379','赠别于羣投笔赴安西','劉長卿','quantangshi','','卷8','风流一才子，经史仍满腹。
心镜万象生，文锋众人服。
顷游灵台下，频弃荆山玉。
蹭蹬空数年，裴回冀微禄。
朅来投笔砚，长揖谢亲族。
且欲图变通，安能守拘束。
本持乡曲誉，肯料泥涂辱。
谁谓命迍邅，还令计反覆。
西戎今未弭，胡骑屯山谷。
坐恃龙豹韬，全轻蜂虿毒。
拂衣从此去，拥传一何速。
元帅许提携，他人伫瞻瞩。
出门寡俦侣，矧乃无僮仆。
黠虏时相逢，黄沙暮愁宿。
萧条远回首，万里如在目。
汉境天西穷，[胡]山海边绿。
想闻羌笛处，泪尽关山曲。
地阔鸟飞迟，风寒马毛缩。
边愁殊浩荡，离思空断续。
塞上归限赊，尊前别期促。
知君志不小，一举凌鸿鹄。
且愿乐从军，功名在殊俗。','',''),('quantangshi-07380','送薛据宰涉县','劉長卿','quantangshi','','卷8','故人河山秀，独立风神异。
人许白眉长，天姿青云器。
雄辞变文名，高价喧时议。
下笔盈万言，皆合古人意。
一从负能名，数载犹卑位。
宝劒诚可用，烹鲜是虚弃。
昔闻在河上，高卧自无事。
几案终日闲，蒲鞭使人畏。
顷因岁月满，方谢风尘吏。
颂德有舆人，荐贤逢八使。
栖鸾往已屈，驯雀今可嗣。
此道如不移，云霄坐应致。
县前漳水绿，郭外晋山翠。
日得谢客游，时堪陶令醉。
前期今尚远，握手空宴慰。
驿路疎柳长，春城百花媚。
裴回白日隐，暝色含天地。
一鸟向灞陵，孤云送行骑。
夫君多述作，而我常讽味。
赖有琼瑶资，能宽别离思。
槐阴覆堂殿，苔色上阶砌。
鸟倦自归飞，云闲独空㵝。
既将慕幽绝，兼欲看定慧。
遇物忘世缘，还家嬾生计。
无生妄已息，有妄心可制。
心镜常虚明，时人自沦翳。','',''),('quantangshi-07381','早春赠别赵居士还江左时长卿下第归嵩阳旧居','劉長卿','quantangshi','','卷8','见君风尘里，意出风尘外。
自有沧洲期，含情十余载。
深居凤城曲，日预龙华会。
果得僧家缘，能遗俗人态。
一身今已适，万物知何爱。
悟法电已空，看心水无碍。
且将穷妙理，兼欲寻胜概。
何独谢客游，当为远公辈。
放舟驰楚郭，负杖辞秦塞。
目送南飞云，令人想吴会。
遥思旧游处，仿髴疑相对。
夜火金陵城，春烟石头濑。
沧波极天末，万里明如带。
一片孤客帆，飘然向青霭。
楚天合江气，云色常霮䨴。
隐见湖中山，相连数州内。
君行意可得，全与时人背。
归路随枫林，还乡念莼菜。
顾予尚羁束，何幸承眄睐。
素愿徒自勤，清机本难逮。
累幸忝宾荐，末路逢沙汰。
濩落名不成，裴回意空大。
逢时虽贵达，守道甘易退。
逆旅乡梦频，春风客心碎。
别君日已远，离念无明晦。
予亦返柴荆，山田事耕耒。','',''),('quantangshi-07382','夜宴洛阳程九主簿宅送杨三山人往天台寻智者禅师隐居','劉長卿','quantangshi','','卷8','东林问逋客，何处栖幽偏？
满腹万余卷，息机三十年。
志图良已久，鬓发空苍然。
调啸寄疎旷，形骸如弃捐。
本家关西族，别业嵩阳田。
云卧能独往，山栖幸周旋。
垂竿不在鱼，卖药不为钱。
藜杖闲倚壁，松花常醉眠。
顷辞青溪隐，来访赤县仙。
南亩自甘贱，中朝唯爱贤。
仍空世谛法，远结天台缘。
魏阙从此去，沧洲知所便。
主人琼枝秀，宠别瑶华篇。
落日扫尘榻，春风吹客船。
此行颇自适，物外谁能牵。
弄棹白苹里，挂帆飞鸟边。
落潮见孤屿，彻底观澄涟。
雁过湖上月，猿声峰际天。
羣峰趋海峤，千里黛相连。
遥倚赤城上，曈曈初日圆。
昔闻智公隐，此地常安禅。
千载已如梦，一灯今尚传。
云龛闭遗影，石窟无人烟。
古寺暗乔木，春崖鸣细泉。
流尘既寂寞，缅想增婵娟。
山鸟怨庭树，门人思步莲。
夷犹怀永路，怅望临清川。
渔人来梦里，沙鸥飞眼前。
独游岂易惬，羣动多相缠。
羡尔五湖夜，往来闲扣舷。','',''),('quantangshi-07383','瓜洲驿奉饯张侍御公拜膳部郎中却复宪台充贺兰大夫留后使之岭南时侍御先在淮南幕府','劉長卿','quantangshi','','卷8','太华高标峻，青阳淑气盘。
属辞倾渤澥，称价掩琅玕。
杨叶频推中，芸香早拜官。
后来惭辙迹，先达仰门阑。
佐剧劳黄绶，提纲疾素餐。
风生趋府步，笔偃触邪冠。
骨鲠知难屈，锋铓岂易干。
伫将调玉铉，翻自落金丸。
异议那容直，专权本畏弹。
寸心宁有负，三黜竟无端。
适喜鸿私降，旋惊羽檄攒。
国怜朝市易，人怨虎狼残。
天地龙初见，风尘虏未殚。
随川归少海，就日背长安。
副相荣分寄，输忠义不刊。
击胡驰汗马，迁蜀扈鸣銮。
月罢名卿署，星悬上将坛。
三军摇斾出，百越画图观。
茅茹能相引，泥沙肯再蟠。
兼荣知任重，交辟许才难。
劲直随台柏，芳香动省兰。
璧从全赵去，鹏自北溟抟。
星象衔新宠，风霜带旧寒。
是非生倚伏，荣辱系悲欢。
畴昔偏殊眄，屯蒙独永叹。
不才成拥肿，失计似邯郸。
江国伤移律，家山忆考盘。
一为鸥鸟误，三见露华团。
回首青云里，应怜浊水澜。
愧将生事托，羞向鬓毛看。
知己伤愆素，他人自好丹。
乡春连楚越，旅宿寄风湍。
世路东流水，沧江一钓竿。
松声伯禹穴，草色子陵滩。
度岭情何遽，临流兴未阑。
梅花分路远，扬子上潮宽。
梦想怀依倚，烟波限渺漫。
且愁无去雁，宁翼少回鸾。
极浦春帆迥，空郊晚骑单。
独怜南渡月，今夕送归鞍。','',''),('quantangshi-07384','至德三年春正月时谬蒙差摄海盐令闻王师收二京因书事寄上浙西节度李侍郎中丞行营五十韵','劉長卿','quantangshi','','卷8','天上胡星孛，人间反气横。
风尘生汗马，河洛纵长鲸。
本谓才非据，谁知祸已萌。
食参将可待，诛错輙为名。
万里兵锋接，三时羽檄惊。
负恩殊鸟兽，流毒遍黎氓。
朝市成芜没，干戈起战争。
人心悬反覆，天道暂虚盈。
略地侵中土，传烽到上京。
王师陷魑魅，帝座逼欃枪。
渭水嘶胡马，秦山泣汉兵。
关原驰万骑，烟火乱千甍。
凤驾瞻西幸，龙楼议北征。
自将行破竹，谁学去吹笙。
白日重轮庆，玄穹再造荣。
鬼神潜释愤，夷狄远输诚。
海内戎衣卷，关中贼垒平。
山川随转战，草木困横行。
区宇神功立，讴歌帝业成。
天回万象庆，龙见五云迎。
小苑春犹在，长安日更明。
星辰归正位，雷雨发残生。
文物登前古，箫韶下太清。
未央新柳色，长乐旧钟声。
八使推邦彦，中司案国程。
苍生属伊吕，明主仗韩彭。
凶丑将除蔓，奸豪已负荆。
世危看柱石，时难识忠贞。
薄伐征貔虎，长驱拥斾旌。
吴山依重镇，江月带行营。
金石悬词律，烟云动笔精。
运筹初减竈，调鼎未和羹。
北虏传初解，东人望已倾。
池塘催谢客，花木待春卿。
昔忝登龙首，能伤困骥鸣。
艰难悲伏劒，提握喜悬衡。
巴曲谁堪听，秦台自有情。
遂令辞短褐，仍欲请长缨。
久客田园废，初官印绶轻。
榛芜上国路，苔藓北山楹。
嬾慢羞趋府，驱驰忆退耕。
榴花无暇醉，蓬发带愁萦。
地僻方言异，身微俗虑并。
家怜双鲤断，才愧小鳞烹。
沧海今犹滞，青阳岁又更。
洲香生杜若，溪暖戏䴔䴖。
烟水宜春候，褰关值晚晴。
潮声来万井，山色映孤城。
旅梦亲乔木，归心乱早莺。
倘无知己在，今已访蓬瀛。','',''),('quantangshi-07385','寻张逸人山居','劉長卿','quantangshi','','卷8','危石才通鸟道，空山更有人家。
桃源定在深处，涧水浮来落花。','',''),('quantangshi-07386','发越州赴润州使院留别鲍侍御','劉長卿','quantangshi','','卷8','对水看山别离，孤舟日暮行迟。
江南江北春草，独向金陵去时。','',''),('quantangshi-07387','送陆[澧]还吴中','劉長卿','quantangshi','','卷8','瓜步寒潮送客，杨柳暮雨沾衣。
故山南望何处，秋草连天独归。','',''),('quantangshi-07388','苕溪酬梁耿别后见寄','劉長卿','quantangshi','','卷8','清川永路何极，落日孤舟解携。
鸟向平芜远近，人随流水东西。
白云千里万里，明月前溪后溪。
惆怅长沙谪去，江潭芳草萋萋。','',''),('quantangshi-07389','蛇浦桥下重送严维','劉長卿','quantangshi','','卷8','秋风飒飒鸣条，风月相和寂寥。
黄叶一离一别，青山暮暮朝朝。
寒江渐出高岸，古木犹依断桥。
明日行人已远，空余泪滴回潮。','',''),('quantangshi-07390','七里滩重送','劉長卿','quantangshi','','卷8','秋江渺渺水空波，越客孤舟欲榜歌。
手折衰杨悲老大，故人零落已无多。','',''),('quantangshi-07391','家园瓜熟是故萧相公所遗瓜种凄然感旧因赋此诗','劉長卿','quantangshi','','卷8','事去人亡迹自留，黄花绿蒂不胜愁。
