寂寂江山摇落处，怜君何事到天涯。','',''),('quantangshi-07451','奉酬辛大夫喜湖南腊月连日降雪见示之作','劉長卿','quantangshi','','卷8','长沙耆旧拜旌麾，喜见江潭积雪时。
