初开窗阁寒光满，欲掩军城暮色迟。
闾里何人不相庆，万家同唱郢中词。','',''),('quantangshi-07452','登余干古县城','劉長卿','quantangshi','','卷8','孤城上与白云齐，万古荒凉楚水西。
