平江渺渺来人远，落日亭亭向客低。
沙鸟不知陵谷变，朝飞暮去弋阳溪。','',''),('quantangshi-07453','将赴岭外留题萧寺远公院','劉長卿','quantangshi','','卷8','竹房遥闭上方幽，苔径苍苍访昔游。
内史旧山空日暮，南朝古木向人秋。
天香月色同僧室，叶落猨啼傍客舟。
此去播迁明主意，白云何事欲相留。','',''),('quantangshi-07454','初闻贬谪续喜量移登干越亭赠郑校书','劉長卿','quantangshi','','卷8','青青草色满江洲，万里伤心水自流。
