何事还邀迁客醉，春风日夜待归舟。','',''),('quantangshi-07455','北归入至德州界偶逢洛阳邻家李光宰','劉長卿','quantangshi','','卷8','生涯心事已蹉跎，旧路依然此重过。
近北始知黄叶落，向南空见白云多。
炎州日日人将老，寒渚年年水自波。
华发相逢俱若是，故园秋草复如何。','',''),('quantangshi-07456','自江西归至旧任官舍赠袁赞府','劉長卿','quantangshi','','卷8','却见同官喜复悲，此生何幸有归期。
空庭客至逢摇落，旧邑人稀经乱离。
湘路来过回雁处，江城卧听捣衣时。
南方风土劳君问，贾谊长沙岂不知。','',''),('quantangshi-07457','赴南中题褚少府湖上亭子','劉長卿','quantangshi','','卷8','种田东郭傍春陂，万事无情把钓丝。
绿竹放侵行径里，青山常对卷帘时。
纷纷花落门空闭，寂寂莺啼日更迟。
从此别君千万里，白云流水忆佳期。','',''),('quantangshi-07458','上巳日越中与鲍侍郎泛舟耶溪','劉長卿','quantangshi','','卷8','兰桡缦转傍汀沙，应接云峰到若耶。
旧浦满来移渡口，垂杨深处有人家。
永和春色千年在，曲水乡心万里赊。
君见渔船时借问，前洲几路入烟花。','',''),('quantangshi-07459','双峰下哭故人李宥','劉長卿','quantangshi','','卷8','怜君孤壠寄双峰，埋骨穷泉复几重。
白露空霑九原草，青山犹闭数株松。
图书经乱知何在，妻子因贫失所从。
惆怅东臯却归去，人间无处更相逢。','',''),('quantangshi-07460','使次安陆寄友人','劉長卿','quantangshi','','卷8','新年草色远萋萋，久客将归失路蹊。
暮雨不知涢口处，春风只到穆陵西。
孤城尽日空花落，三户无人自鸟啼。
君在江南相忆否，门前五柳几枝低。','',''),('quantangshi-07461','哭陈歙州','劉長卿','quantangshi','','卷8','千秋万古葬平原，素业清风及子孙。
旅榇归程伤道路，举家行哭向田园。
空山寂寂开新壠，乔木苍苍掩旧门。
儒行公才竟何在，独怜棠树一枝存。','',''),('quantangshi-07462','酬屈突陜','劉長卿','quantangshi','','卷8','落叶纷纷满四邻，萧条环堵绝风尘。
乡看秋草归无路，家对寒江病且贫。
藜杖懒迎征骑客，菊花能醉去官人。
怜君计画谁知者，但见蓬蒿空没身。','',''),('quantangshi-07463','送惠法师游天台因怀智大师故居','劉長卿','quantangshi','','卷8','翠屏瀑水知何在，鸟道猨啼过几重。
落日独摇金策去，深山谁向石桥逢。
定攀岩下丛生桂，欲买云中若个峰。
忆想东林禅诵处，寂寥惟听旧时钟。','',''),('quantangshi-07464','自夏口至鹦鹉洲夕望岳阳寄源中丞','劉長卿','quantangshi','','卷8','[汀]洲无浪复无烟，楚客相思益渺然。
汉口夕阳斜渡鸟，洞庭秋水远连天。
孤城背岭寒吹角，独戍临江夜泊船。
贾谊上书忧汉室，长沙谪去古今怜。','',''),('quantangshi-07465','送侯中丞流康州','劉長卿','quantangshi','','卷8','长江极目带枫林，匹马孤云不可寻。
迁播共知臣道枉，猜谗却为主恩深。
辕门画角三军思，驿路青山万里心。
北阙九重谁许屈，独看湘水泪霑襟。','',''),('quantangshi-07466','别严士元','劉長卿','quantangshi','','卷8','春风倚棹阖闾城，水国春寒阴复晴。
细雨湿衣看不见，闲花落地听无声。
日斜江上孤帆影，草绿湖南万里情。
东道若逢相识问，青袍今日误儒生。','',''),('quantangshi-07467','避地江东留别淮南使院诸公','劉長卿','quantangshi','','卷8','长安路绝鸟飞通，万里孤云西复东。
旧业已应成茂草，余生只是任飘蓬。
何辞向物开秦镜，却使他人得楚弓。
此去行持一竿竹，等闲将狎钓渔翁。','',''),('quantangshi-07468','罪所上御史惟则','劉長卿','quantangshi','','卷8','误因微禄滞南昌，幽系圜扉昼夜长。
黄鹤翅垂同燕雀，青松心在任风霜。
斗间谁与看冤气，盆下无由见太阳。
贤达不能同感激，更于何处问苍苍。','',''),('quantangshi-07469','送台州李使君兼寄题国清寺','劉長卿','quantangshi','','卷8','露冕新承明主恩，山城别是武陵源。
花间五马时行县，山外千峰常在门。
晴江洲渚带春草，古寺杉松深暮猨。
知到应真飞锡处，因君一想已忘言。','',''),('quantangshi-07470','狱中闻收东京有赦','劉長卿','quantangshi','','卷8','传闻阙下降丝纶，为报关东灭虏尘。
壮志已怜成白首，余生犹待发青春。
风霜何事偏伤物，天地无情亦爱人。
持法不须张密网，恩波自解惜枯鳞。','',''),('quantangshi-07471','温汤客舍','劉長卿','quantangshi','','卷8','冬狩温泉岁欲阑，宫城佳气晚宜看。
汤熏仗里千旗暖，雪照山边万井寒。
君门献赋谁相达，客舍无钱輙自安。
且喜礼闱秦镜在，还将妍丑付春官。','',''),('quantangshi-07472','送孙逸归庐山','劉長卿','quantangshi','','卷8','炉峰绝顶楚云衔，楚客东归栖此岩。
彭蠡湖边香橘柚，浔阳郭外暗枫杉。
青山不断三湘道，飞鸟空随万里帆。
常爱此中多胜事，新诗他日伫开缄。','',''),('quantangshi-07473','送马秀才落第归江南','劉長卿','quantangshi','','卷8','南客怀归乡梦频，东门怅别柳条新。
殷勤斗酒城阴暮，荡漾孤舟楚水春。
湘竹旧斑思帝子，江蓠初绿怨骚人。
怜君此去未得意，陌上愁看泪满巾。','',''),('quantangshi-07474','送常十九归嵩少故林','劉長卿','quantangshi','','卷8','迢迢此恨杳无涯，楚泽嵩丘千里赊。
岐路别时惊一叶，云林归处忆三花。
秋天苍翠寒飞雁，古堞萧条晚噪鵶。
他日山中逢胜事，桃源洞里几人家。','',''),('quantangshi-07475','送宇文迁明府赴洪州张观察追摄丰城令','劉長卿','quantangshi','','卷8','送君不复远为心，余亦扁舟湘水阴。
路逐山光何处尽，春随草色向南深。
陈蕃待客应悬榻，宓贱之官独抱琴。
傥见主人论谪宦，尔来空有白头吟。','',''),('quantangshi-07476','送李将军','劉長卿','quantangshi','','卷8','征西诸将一如君，报德谁能不顾勋。
身逐塞鸿来万里，手披荒草看孤坟。
擒生绝漠经胡雪，怀旧长沙哭楚云。
归去萧条灞陵上，几人看葬李将军。','',''),('quantangshi-07477','西陵寄一上人','劉長卿','quantangshi','','卷8','东山访道成开士，南渡隋阳作本师。
了义惠心能善诱，吴风越俗罢淫祠。
室中时见天人命，物外长悬海岳期。
多谢清言异玄度，悬河高论有谁持。','',''),('quantangshi-07478','赋得','劉長卿','quantangshi','','卷8','莺啼燕语报新年，马邑龙堆路几千。
家住层城临汉苑，[心]随明月到胡天。
机中锦字论长恨，楼上花枝笑独眠。
为问元戎窦车骑，何时返斾勒燕然。','',''),('quantangshi-07479','三月李明府后亭泛舟','劉長卿','quantangshi','','卷8','江南风景复如何，闻道新亭更欲过。
处处纫兰春浦渌，萋萋籍草远山多。
壶觞须就陶彭泽，时俗犹传晋永和。
更待持桡徐转去，微风落日水增波。','',''),('quantangshi-07480','喜朱拾遗承恩拜命赴任上都','劉長卿','quantangshi','','卷8','诏书征拜脱荷裳，身去东山闭草堂。
阊阖九天通奏籍，华亭一鹤在朝行。
沧洲离别风烟远，青琐幽深漏刻长。
今日却回垂钓处，海鸥相见已高翔。','',''),('quantangshi-07481','郧上送韦司士归上都旧业','劉長卿','quantangshi','','卷8','前朝旧业想遗尘，今日他乡独尔身。
郧地国除为过客，杜陵家在有何人。
苍苔白露生三径，古木寒蝉满四邻。
西去茫茫问归路，关河渐近泪盈巾。','',''),('quantangshi-07482','感怀','劉長卿','quantangshi','','卷8','秋风落叶正堪悲，黄菊残花欲待谁。
水近偏逢寒气早，山深常见日光迟。
愁中卜命看周易，梦里招魂读楚词。
自笑不如湘浦雁，飞来即是北归时。','',''),('quantangshi-07483','送杨于陵归宋汴州别业','劉長卿','quantangshi','','卷8','半山溪雨带斜晖，向水残花映客衣。
旅食嗟余当岁晚，能文似汝少年稀。
新河柳色千株暗，故国云帆万里归。
离乱要知君到处，寄书须及雁南飞。','',''),('quantangshi-07484','送崔使君赴寿州','劉長卿','quantangshi','','卷8','列郡专城分国忧，彤幨皂盖古诸侯。
仲华遇主年犹少，公瑾论功位已酬。
草色青青迎建隼，蝉声处处杂鸣驺。
千里相思如可见，淮南木叶正惊秋。','',''),('quantangshi-07485','上阳宫望幸','劉長卿','quantangshi','','卷8','玉辇西巡久未还，春光犹入上阳间。
万木长承新雨露，千门空对旧河山。
深花寂寂宫城闭，细草青青御路闲。
独见彩云飞不尽，只应来去候龙颜。','',''),('quantangshi-07486','过裴舍人故居','劉長卿','quantangshi','','卷8','惨惨天寒独掩扃，纷纷黄叶满空庭。
孤坟何处依山木，百口无家学水萍。
篱花犹及重阳发，邻笛那堪落日听。
书幌无人长不卷，秋来芳草自为萤。','',''),('quantangshi-07487','登松江驿楼北望故园','劉長卿','quantangshi','','卷8','泪尽江楼北望归，田园已陷百重围。
平芜万里无人去，落日千山空鸟飞。
孤舟漾漾寒潮小，极浦苍苍远树微。
白鸥渔父徒相待，未扫欃枪嬾息机。','',''),('quantangshi-07488','秋夜有怀高三十五适兼呈空上人','劉長卿','quantangshi','','卷8','晚节逢君趣道深，结茅栽树近东林。
吾师几度曾摩顶，高士何年遂发心。
北渚三更闻过雁，西城万里动寒砧。
不见支公与玄度，相思拥膝坐长吟。','',''),('quantangshi-07489','送孔巢父赴河南军','劉長卿','quantangshi','','卷8','江南相送隔烟波，况复新秋一雁过。
闻道全军征北虏，又言诗将会南河。
边心冉冉乡人绝，寒色青青战马多。
共许陈琳工奏记，知君名行未蹉跎。','',''),('quantangshi-07490','登润州万岁楼','劉長卿','quantangshi','','卷8','高楼独上思依依，极浦遥山合翠微。
江客不堪频北望，寒鸿何事又南飞。
垂山古渡寒烟积，瓜步空洲远树稀。
闻道王师犹转战，更能谈笑解重围。','',''),('quantangshi-07491','江楼送太康郭主簿赴岭南','劉長卿','quantangshi','','卷8','对酒怜君安可论，当官爱士如平原。
料钱用尽却为谤，食客空多谁报恩。
万里孤舟向南越，苍梧云中暮帆灭。
树色应无江北秋，天涯尚见淮阳月。
驿路南随桂水流，猨声不绝到炎州。
青山落日那堪望，谁见思君江上楼。','',''),('quantangshi-07492','客舍喜郑三见寄','劉長卿','quantangshi','','卷8','客舍逢君未换衣，闭门愁见桃花飞。
遥想故园今已尔，家人应念行人归。
寂寞垂杨映深曲，长安日暮灵台宿。
穷巷无人鸟雀闲，空庭新雨莓苔绿。
北中分与故交疎，何幸仍回长者车。
十年未称平生意，好得辛勤谩读书。','',''),('quantangshi-07493','送贾三北游','劉長卿','quantangshi','','卷8','贾生未达犹窘迫，身驰匹马邯郸陌。
片云郊外遥送人，斗酒城边暮留客。
顾予他日仰时髦，不堪此别相思劳。
雨色新添漳水绿，夕阳远照苏门高。
把袂相看衣共缁，穷愁只是惜良时。
亦知到处逢下榻，莫滞秋风西上期。','',''),('quantangshi-07494','齐一和尚影堂','劉長卿','quantangshi','','卷8','一公住世忘世纷，暂来复去谁能分。
身寄虚空如过客，心将生灭是浮云。
萧散浮云往不还，凄凉遗教殁仍传。
旧地愁看双树在，空堂只是一灯悬。
一灯长照恒河沙，双树犹落诸天花。
天花寂寂香深殿，苔藓苍苍閟虚院。
昔余精念访禅扉，常接微言清道机。
今来寂寞无所得，唯共门人泪满衣。','',''),('quantangshi-07495','颍川留别司仓李万','劉長卿','quantangshi','','卷8','故人早负干将器，谁言未展平生意。
想君畴昔高步时，肯料如今折腰事。
且知投刃皆若虚，日挥案牍常有余。
槐暗公庭趋小吏，荷香陂水脍鲈鱼。
客里相逢款话深，如何岐路剩霑襟。
白云西上催归念，颍水东流是别心。
落日征骖随去尘，含情挥手背城闉。
已恨良时空此别，不堪秋草更愁人。','',''),('quantangshi-07496','听笛歌','劉長卿','quantangshi','','卷8','旧游怜我长沙谪，载酒沙头送迁客。
天涯望月自霑衣，江上何人复吹笛。
横笛能令孤客愁，渌波淡淡如不流。
商声寥亮羽声苦，江天寂历江枫秋。
静听关山闻一叫，三湘月色悲猨啸。
又吹杨柳激繁音，千里春色伤人心。
随风飘向何处落，唯见曲尽平湖深。
明发与君离别后，马上一声堪白首。','',''),('quantangshi-07497','时平后送范伦归安州','劉長卿','quantangshi','','卷8','昨闻战罢图麟阁，破虏收兵卷戎幕。
沧海初看汉月明，紫微已见胡星落。
忆昔扁舟此南渡，荆棘烟尘满归路。
与君携手姑苏台，望乡一日登几回。
白云飞鸟去寂寞，吴山楚岫空崔嵬。
事往时平还旧丘，青青春草近家愁。
洛阳举目今谁在，颍水无情应自流。
吴苑西人去欲稀，留连一日空知非。
江潭岁尽愁不尽，鸿雁春归身未归。
万里遥悬帝乡忆，五年空带风尘色。
却到长安逢故人，不道姓名应不识。','',''),('quantangshi-07498','小鸟篇上裴尹','劉長卿','quantangshi','','卷8','藩篱小鸟何甚微，翩翩日夕空此飞。
只缘六翮不自致，长似孤云无所依。
西城黯黯斜晖落，众鸟纷纷皆有托。
独立虽轻燕雀羣，孤飞远惧鹰鹯搏。
自怜天上青云路，吊影徘徊独愁暮。
衔花纵有报恩时，择木谁容托身处。
岁月蹉跎飞不进，羽毛鹪顇何人问。
遶树空随乌鹊惊，巢林只有鹪鹩分。
主人庭中荫乔木，爱此清阴欲栖宿。
少年挟弹遥相猜，遂使惊飞往复回。
不辞奋翼向君去，唯怕金丸随后来。','',''),('quantangshi-07499','登吴古城歌','劉長卿','quantangshi','','卷8','登古城兮思古人，感贤达兮同埃尘。
望平原兮寄远目，叹姑苏兮聚麋鹿。
黄池高会事未终，沧海横流人荡覆。
伍员杀身谁不冤，竟看墓树如所言。
越王尝胆安可敌，远取石田何所益。
一朝空谢会稽人，万古犹伤甬东客。
黍离离兮城坡坨，牛羊践兮牧竖歌。
野无人兮秋草绿，园为墟兮古木多。
白杨萧萧悲故柯，黄雀啾啾争晚禾。
荒阡断兮谁重过，孤舟逝兮愁若何。
天寒日暮江枫落，叶去辞风水自波。','',''),('quantangshi-07500','疲兵篇','劉長卿','quantangshi','','卷8','骄虏乘秋下蓟门，阴山日夕烟尘昏。
三军疲马力已尽，百战残兵功未论。
阵云泱漭屯塞北，羽书纷纷来不息。
孤城望处增断肠，折剑看时可霑臆。
元戎日夕且歌舞，不念关山久辛苦。
自矜倚剑气凌云，却笑闻笳泪如雨。
万里飘颻空此身，十年征战老胡尘。
赤心报国无片赏，白首还家有几人。
朔风萧萧动枯草，旌旗猎猎榆关道。
汉月何曾照客心，胡笳只解催人老。
军前仍欲破重围，闺里犹应愁未归。
小妇十年啼夜织，行人九月忆寒衣。
饮马滹河晚更清，行吹羗笛远归营。
只恨汉家多苦战，徒遗金镞满长城。','',''),('quantangshi-07501','新安送陆[澧]归江阴','劉長卿','quantangshi','','卷8','新安路，人来去。
早潮复晚潮，明日知何处。
潮水无情亦解归，自怜长在新安住。','',''),('quantangshi-07502','弄白鸥歌','劉長卿','quantangshi','','卷8','泛泛江上鸥，毛衣皓如雪。
朝飞潇湘水，夜宿洞庭月。
归客正夷犹，爱此沧江闲白鸥。','',''),('quantangshi-07503','长沙赠衡岳祝融峰般若禅师','劉長卿','quantangshi','','卷8','般若公，般若公，负钵何时下祝融。
归路却看飞鸟外，禅房空掩白云中。
桂花寥寥闲自落，流水无心西复东。','',''),('quantangshi-07504','赠湘南渔父','劉長卿','quantangshi','','卷8','闻君何所适，暮暮逢烟水。
独与不系舟，往来楚云里。
钓鱼非一岁，终日只如此。
日落江清桂檝迟，纤鳞百尺深可窥。
沈钩垂饵不在得，白首沧浪空自知。','',''),('quantangshi-07505','明月湾寻贺九不遇','劉長卿','quantangshi','','卷8','楚水日夜绿，傍江春草滋。
青青遥满目，万里伤心归。
故人川上复何之，明月湾南空所思。
故人不在明月在，谁见孤舟来去时。','',''),('quantangshi-07506','题曲阿三昧王佛殿前孤石','劉長卿','quantangshi','','卷8','孤石自何处，对之疑旧游。
氛氲岘首夕，苍翠剡中秋。
迥出羣峰当殿前，雪山灵鹫慙贞坚。
一片孤云长不去，莓苔古色空苍然。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-07507','送友人东归','劉長卿','quantangshi','','卷8','对酒灞亭暮，相看愁自深。
河边草已绿，此别难为心。
关路迢迢匹马归，垂杨寂寂数莺飞。
怜君献策十余载，今日犹为一布衣。','',''),('quantangshi-07508','入桂渚次砂牛石穴','劉長卿','quantangshi','','卷8','扁舟傍归路，日暮潇湘深。
湘水清见底，楚云淡无心。
片帆落桂渚，独夜依枫林。
枫林月出猨声苦，桂渚天寒桂花吐。
此中无处不堪愁，江客相看泪如雨。','',''),('quantangshi-07509','严陵钓台送李康成赴江东使','劉長卿','quantangshi','','卷8','潺湲子陵濑，仿髴如在目。
七里人已非，千年水空绿。
新安江上孤帆远，应逐枫林万余转。
古台落日共萧条，寒水无波更清浅。
台上渔竿不复持，却令猨鸟向人悲。
滩声山翠至今在，迟尔行舟晚泊时。','',''),('quantangshi-07510','送姨子弟往南郊','劉長卿','quantangshi','','卷8','一展慰久阔，寸心仍未伸。
别时两童稚，及此俱成人。
那堪适会面，遽已悲分首。
客路向楚云，河桥对衰柳。
送君匹马别河桥，汝南山郭寒萧条。
今我单车复西上，郎去灞陵转惆怅。
何处共伤离别心，明月亭亭两乡望。','',''),('quantangshi-07511','铜雀台','劉長卿','quantangshi','','卷8','娇爱更何日，高台空数层。
含啼映双袖，不忍看西陵。
漳河东流无复来，百花辇路为苍苔。
[青]楼月夜长寂寞，碧云日暮空徘徊。
君不见邺中万事非昔时，古人不在今人悲。
春风不逐君王去，草色年年旧宫路。
宫中歌舞已浮云，空指行人往来处。','',''),('quantangshi-07512','王昭君歌','劉長卿','quantangshi','','卷8','自矜娇艳色，不顾丹青人。
那知粉绘能相负，却使容华翻误身。
上马辞君嫁骄虏，玉颜对人啼不语。
北风雁急浮云秋，万里独见黄河流。
纤腰不复汉宫宠，双蛾长向胡天愁。
琵琶弦中苦调多，萧萧羌笛声相和。
谁怜一曲传乐府，能使千秋伤绮罗。','',''),('quantangshi-07513','送杜越江佐觐省往新安江','劉長卿','quantangshi','','卷8','去帆楚天外，望远愁复积。
想见新安江，扁舟一行客。
清流数千丈，底下看白石。
色混元气深，波连洞庭碧。
鸣桹去未已，前路行可觌。
猨鸟悲啾啾，杉松雨声夕。
送君东赴归宁期，新安江水远相随。
见说江中孤屿在，此行应赋谢公诗。','',''),('quantangshi-07514','湘中忆归','劉長卿','quantangshi','','卷8','终日空理棹，经年犹别家。
顷来行已远，弥觉天无涯。
白云意自深，沧海梦难隔。
迢递万里帆，飘颻一行客。
独怜西江外，远寄风波里。
平湖流楚天，孤雁渡湘水。
湘流澹澹空愁予，猨啼啾啾满南楚。
扁舟泊处闻此声，江客相看泪如雨。','',''),('quantangshi-07515','送郭六侍从之武陵郡','劉長卿','quantangshi','','卷8','常爱武陵郡，羡君将远寻。
空怜世界迫，孤负桃源心。
洛阳遥想桃源隔，野水闲流春自碧。
花下常迷楚客船，洞中时见秦人宅。
落日相看斗酒前，送君南望但依然。
河梁马首随春草，江路猨声愁暮天。
丈人别乘佐分忧，才子趋庭兼胜游。
澧浦荆门行可见，知君诗兴满沧洲。','',''),('quantangshi-07516','山鸜鹆歌','劉長卿','quantangshi','','卷8','山鸜鹆，长在此山吟古木。
嘲唽相呼响空谷，哀鸣万变如成曲。
江南逐臣悲放逐，倚树听之心断续。
巴人峡里自闻猨，燕客水头空击筑。
山鸜鹆，一生不及双黄鹄。
朝去秋田啄残粟，暮入寒林啸羣族。
鸣相逐，啄残粟，食不足。
青云杳杳无力飞，白露苍苍抱枝宿。
不知何事守空山，万壑千峰自愁独。','',''),('quantangshi-07517','望龙山怀道士许法棱','劉長卿','quantangshi','','卷8','心惆怅，望龙山。
云之际，鸟独还。
悬崖绝壁几千丈，绿萝袅袅不可攀。
龙山高，谁能践。
灵原中，苍翠晚。
岚烟瀑水如向人，终日迢迢空在眼。
中有一人披霓裳，诵经山顶飧琼浆。
空林闲坐独焚香，真官列侍俨成行。
朝入青霄礼玉堂，夜扫白云眠石牀。
桃花洞里居人满，桂树山中住日长，龙山高高遥相望。','',''),('quantangshi-07518','戏赠干越尼子歌','劉長卿','quantangshi','','卷8','鄱阳女子年十五，家本秦人今在楚。
厌向春江空浣沙，龙宫落发披袈裟。
五年持戒长一食，至今犹自颜如花。
亭亭独立青莲下，忍草禅枝绕精舍。
自用黄金买地居，能嫌碧玉随人嫁。
北客相逢疑姓秦，铅花抛却仍青春。
一花一竹如有意，不语不笑能留人。
黄鹂欲栖白日暮，天香未散经行处。
却对香炉闲诵经，春泉漱玉寒泠泠。
云房寂寂夜钟后，吴音清切令人听。
人听吴音歌一曲，杳然如在诸天宿。
谁堪世事更相牵，惆怅回船江水渌。','',''),('quantangshi-07519','游四窗','劉長卿','quantangshi','','卷8','四明山绝奇，自古说登陆。
苍崖倚天立，覆石如覆屋。
玲珑开户牖，落落明四目。
箕星分南野，有斗挂檐北。
日月居东西，朝昏互出没。
我来游其间，寄傲巾半幅。
白云本无心，悠然伴幽独。
对此脱尘鞅，顿忘荣与辱。
长笑天地宽，仙风吹佩玉。','',''),('quantangshi-07520','和中丞出使恩命过终南别业','劉長卿','quantangshi','','卷8','不过林园久，多因宠遇偏。
故山长寂寂，春草过年年。
花待朝衣间，云迎驿骑连。
松萝深旧合，樵木散闲田。
拜阙贪摇佩，看琴懒更弦。
君恩催早入，已梦[傅]岩边。','',''),('quantangshi-07521','岳阳楼','劉長卿','quantangshi','','卷8','行尽清溪日已蹉，云容山影两嵯峨。
楼前归客怨秋梦，湖上美人疑夜歌。
独坐高高风势急，平湖渺渺月明多。
终期一艇载樵去，来往片帆愁白波。','',''),('quantangshi-07522','春望寄王涔阳','劉長卿','quantangshi','','卷8','清明别后雨晴时，极浦空颦一望眉。
湖畔春山烟点点，云中远树墨离离。
依微水戍闻钲鼓，掩映沙村见酒旗。
风暖草长愁自醉，行吟无处寄相思。','',''),('quantangshi-07523','留辞','劉長卿','quantangshi','','卷8','南楚迢迢通汉口，西江淼淼去扬州。
春风已遣归心促，纵复芳菲不可留。','',''),('quantangshi-07524','题杼山癸亭得暮字','顏真卿','quantangshi','','卷8','杼山多幽绝，胜事盈跬步。
前者虽登攀，淹留恨晨暮。
及兹纡胜引，曾是美无度。
歘构三癸亭，实为陆生故。
高贤能剏物，疏凿皆有趣。
不越方丈间，居然云霄遇。
巍峨倚修岫，旷望临古渡。
左右苔石攒，低昂桂枝蠹。
山僧狎猨狖，巢鸟来枳椇。
俯视何楷台，傍瞻戴颙路。
迟回未能下，夕照明村树。','',''),('quantangshi-07525','谢陆处士杼山折青桂花见寄之什','顏真卿','quantangshi','','卷8','羣子游杼山，山寒桂花白。
绿荑含素蕚，采折自逋客。
忽枉岩中诗，芳香润金石。
全高南越蠹，岂谢东堂策。
会惬名山期，从君恣幽觌。','',''),('quantangshi-07526','赠裴将军','顏真卿','quantangshi','','卷8','大君制六合，猛将清九垓。
战马若龙虎，腾凌何壮哉。
将军临八荒，烜赫耀英材。
劒舞若游电，随风萦且回。
登高望天山，白云正崔巍。
入阵破骄虏，威名雄震雷。
一射百马倒，再射万夫开。
匈奴不敢敌，相呼归去来。
功成报天子，可以画麟台。','',''),('quantangshi-07527','赠僧皎然','顏真卿','quantangshi','','卷8','秋意西山多，别岑萦左次。
缮亭历三癸，趾趾邻什寺。
元化隐灵踪，始君启高致。
诛榛养翘楚，鞭草理芳穗。
俯砌披水容，逼天扫峰翠。
境新耳目换，物远风尘异。
倚石忘世情，援云得真意。
嘉林幸勿剪，禅侣欣可庇。
卫法大臣过，佐游羣英萃。
龙池护清激，虎节到深邃。
徒想嵊顶期，于今没遗记。','',''),('quantangshi-07528','咏陶渊明','顏真卿','quantangshi','','卷8','张良思报韩，龚胜耻事新。
狙击不肯就，舍生悲缙绅。
呜呼陶渊明，奕叶为晋臣。
自以公相后，每怀宗国屯。
题诗庚子岁，自谓羲皇人。
手持山海经，头戴漉酒巾。
兴逐孤云外，心随还鸟泯。','',''),('quantangshi-07529','三言拟五杂组二首 一','顏真卿','quantangshi','','卷8','五杂组，绣与锦。
往复还，兴又寝。
不得已，病伏枕。','',''),('quantangshi-07530','三言拟五杂组二首 二','顏真卿','quantangshi','','卷8','五杂组，甘咸醋。
往复还，乌与兔。
不得已，韶光度。','',''),('quantangshi-07531','使过瑶台寺有怀圆寂上人','顏真卿','quantangshi','','卷8','上人居此寺，不出三十年。
万法元无着，一心唯趣禅。
忽纡尘外轸，远访区中缘。
及尔不复见，支提犹岌然。','',''),('quantangshi-07532','登平望桥下作','顏真卿','quantangshi','','卷8','登桥试长望，望极与天平。
际海蒹葭色，终朝凫雁声。
近山犹仿髴，远水忽微明。
更览诸公作，知高题柱名。','',''),('quantangshi-07533','刻清远道士诗因而继作','顏真卿','quantangshi','','卷8','不到东西寺，于今五十春。
朅来从旧赏，林壑宛相亲。
吴子多藏日，秦王厌胜辰。
劒池穿万仞，盘石坐千人。
金气腾为虎，琴台化若神。
登坛仰生一，舍宅叹珣珉。
中岭分双树，回峦绝四邻。
窥临江海接，崇饰四时新。
客有神仙者，于兹雅丽陈。
名高清远峡，文聚斗牛津。
迹异心宁间，声同质岂均。
悠然千载后，知我揖光尘。','',''),('quantangshi-07534','杂诗六首 一','李華','quantangshi','','卷8','黄钟扣元音，律吕更循环。
邪气悖正声，郑卫生其间。
典乐忽涓微，波浪与天浑。
嘈嘈鸱枭动，好鸟徒緜蛮。
王吉归乡里，甘心长闭关。','',''),('quantangshi-07535','杂诗六首 二','李華','quantangshi','','卷8','玄黄与丹青，五气之正色。
圣人端其源，上下皆有则。
齐侯好紫衣，魏帝妇人饰。
女奴厌金翠，倾海未满臆。
何忍严子陵，羊裘死荆棘。','',''),('quantangshi-07536','杂诗六首 三','李華','quantangshi','','卷8','甘酸不私人，元和运五行。
生人受其用，味正心亦平。
爪牙相践伤，日与性命争。
圣人不能绝，钻燧与炮烹。
嗜欲乘此炽，百金资一倾。
正销神耗衰，邪胜体充盈。
颜子有余乐，瓢中寒水清。','',''),('quantangshi-07537','杂诗六首 四','李華','quantangshi','','卷8','阴魄沦宇宙，太阳假其明。
臣道不敢专，由此见亏盈。
未闻东菑稼，一气嘉谷成。
上天降寒暑，地利乃可生。
葛藟附柔木，繁阴蔽曾原。
风霜摧枝干，不复庇本根。
女萝依松柏，然后得长存。','',''),('quantangshi-07538','杂诗六首 五','李華','quantangshi','','卷8','孔光尊董贤，胡广惭李固。
儒风冠天下，而乃败王度。
绛侯与愽陆，忠朴受遗顾。
求名不考实，文弊反成蠹。','',''),('quantangshi-07539','杂诗六首 六','李華','quantangshi','','卷8','结交得书生，书生钝且直。
争权复争利，终不得其力。
我逢纵横者，是我牙与翼。
相旋如疾风，竝命趋紫极。
奔车得停轨，风火何相逼。
仁义岂有常，肝胆反为贼。
勿嫌书生直，钝直深可忆。','',''),('quantangshi-07540','咏史十一首 一','李華','quantangshi','','卷8','昂藏獬豸兽，出自太平年。
乱代乃潜伏，纵人为祸愆。
尝闻断马劒，每壮朱云贤。
身死名不灭，寒风吹[墓]田。
精灵如有在，幽愤满松烟。','',''),('quantangshi-07541','咏史十一首 二','李華','quantangshi','','卷8','汉皇修雅乐，乘舆临太学。
三老与五更，天王亲割牲。
一人调风俗，万国和且平。
单于骤款塞，武库欲销兵。
文物此朝盛，君臣何穆清。
至今壝坛下，如有箫韶声。','',''),('quantangshi-07542','咏史十一首 三','李華','quantangshi','','卷8','巢许在嵩颍，陶唐不得臣。
九州尚洗耳，一命安能亲。
緜邈数千祀，丘中谁隐沦。
朝游公卿府，夕是山林人。
蒲帛扬侧陋，薜萝为缙绅。
九重念入梦，三事思降神。
且设庭中燎，宁窥泉下鳞。','',''),('quantangshi-07543','咏史十一首 四','李華','quantangshi','','卷8','汉时征百粤，杨仆将楼船。
幕府功未立，江湖已骚然。
岛夷非敢乱，政暴地仍偏。
得罪因怀璧，防身辄控弦。
三军求裂土，万里讵闻天。
魏阙心犹在，旗门首已悬。
如何得良吏，一为制方圆。','',''),('quantangshi-07544','咏史十一首 五','李華','quantangshi','','卷8','秦灭汉帝兴，南山有遗老。
危冠揖万乘，幸得厌征讨。
当君逐鹿时，臣等已枯槁。
宁知市朝变，但觉林泉好。
高卧三十年，相看成四皓。
帝言翁甚善，见顾何不早。
咸称太子仁，重义亦尊道。
侧闻骊姬事，申生不自保。
暂出商山云，朅来趋洒扫。
东宫成羽翼，楚舞伤怀抱。
后代无其人，戾园满秋草。','',''),('quantangshi-07545','咏史十一首 六','李華','quantangshi','','卷8','日照昆仑上，羽人披羽衣。
乘龙驾云雾，欲往心无违。
此山在西北，乃是神仙国。
灵气皆自然，求之不可得。
何为汉武帝，精思徧羣山。
糜费巨万计，宫车终不还。
苍苍茂陵树，足以戒人间。','',''),('quantangshi-07546','咏史十一首 七','李華','quantangshi','','卷8','天生忠与义，本以佐雍熙。
何意李司隶，而当昏乱时。
古坟襄城野，斜径横秋陂。
况不禁樵采，茅莎无孑遗。
高标尚可仰，精爽今何之。
一忤中常侍，衔冤谁见知。
尝观党锢传，抚卷不胜悲。','',''),('quantangshi-07547','咏史十一首 八','李華','quantangshi','','卷8','文侯耽郑卫，一听一忘餐。
白雪燕姬舞，朱弦赵女弹。
淫声流不返，慆荡日无端。
献岁受朝时，鸣钟宴百官。
两牀陈管磬，九奏殊未阑。
对此唯恐卧，更能整衣冠。','',''),('quantangshi-07548','咏史十一首 九','李華','quantangshi','','卷8','蜀主相诸葛，功高名亦尊。
驱驰千万众，怒目瞰中原。
曹伯任公孙，国亡身不存。
社宫久芜没，白雁犹飞翻。
勿言君臣合，可以济黎元。
为蜀谅不易，如曹难复论。','',''),('quantangshi-07549','咏史十一首 十','李華','quantangshi','','卷8','六国韩最弱，末年尤畏秦。
郑生为韩计，且欲疲秦人。
利物可分社，原情堪灭身。
咸阳古城下，万顷稻苗新。','',''),('quantangshi-07550','咏史十一首 十一','李華','quantangshi','','卷8','沂水春可涉，泮宫映杨叶。
丽色异人间，珊珊摇佩环。
展禽恒独处，深巷生禾黍。
城上飞海云，城中暗春雨。
适来鸣佩者，复是谁家女。
泥沾珠缀履，雨湿翠毛簪。
电影开莲脸，雷声飞蕙心。
自言沂水曲，采萍兼采菉。
归迳虽可寻，天阴光景促。
怜君贞且独，愿许君家宿。
徒劳惜衾枕，了不顾双蛾。
艳质诚可重，淫风如礼何。
周王惑襃姒，城阙成陂陁。','',''),('quantangshi-07551','云母泉诗','李華','quantangshi','','卷8','晨登玄石岭，岭上寒松声。
朗日风雨霁，高秋天地清。
山门开古寺，石窦含纯精。
洞彻净金界，夤缘流玉英。
泽药滋畦茂，气染茶瓯馨。
饮液尽眉寿，飡和皆体平。
琼浆驻容发，甘露莹心灵。
岱谷谢巧妙，匡山徒有名。
愿言构蓬荜，荷锸引泠泠。
访道出人世，招贤依福庭。
此心不能已，寤寐见吾兄。
曾结颍阳契，穷年无所成。
东西同放逐，蛇豕尚纵横。
江汉阻携手，天涯万里情。
恩光起憔悴，西上谒承明。
秋色变江树，相思纷以盈。
猨啼巴丘戍，月上武陵城。
共恨川路永，无由会友生。
云泉不可忘，何日遂躬耕。','',''),('quantangshi-07552','寄赵七侍御','李華','quantangshi','','卷8','摇桨曙江流，江清山复重。
心惬赏未足，川迥失前峰。
淩滩出极浦，旷若天池通。
君阳青嵯峨，开拆混元中。
九潭鱼龙窟，仙成羽人宫。
阴奥潜鬼物，精光动烟空。
玄猨啼深茏，白鸟戏葱蒙。
飞湍鸣金石，激溜鼓雷风。
雨濯万木鲜，霞照千山浓。
草闲长余绿，花静落幽红。
渚烟见晨钓，山月闻夜舂。
覆溪窈窕波，涵石淘溶溶。
丹丘忽聚散，素壁相奔冲。
白日破昏霭，灵山出其东。
势排昊苍上，气压吴越雄。
回头望云卿，此恨发吾衷。
昔日萧邵游，四人才成童。
属词慕孔门，入仕希上公。
纬卿陷非罪，折我昆吾锋。
茂挺独先觉，拔身渡京虹。
斯人谢明代，百代坠鵷鸿。
世故坠横流，与君哀路穷。
相顾无死节，蒙恩逐殊封。
天波洗其瑕，朱衣备朝容。
一别凡十年，岂期复相从。
余生得携手，遗此两孱翁。
羣迁失莺羽，后凋惜长松。
衰旅难重别，凄凄满心胸。
遇胜悲独游，贪奇怅孤逢。
禽尚彼何人，胡为束樊笼。
吾师度门教，投弁蹑遐踪。','',''),('quantangshi-07553','仙游寺','李華','quantangshi','','卷8','舍事入樵迳，云木深谷口。
万壑移晦明，千峰转前后。
嶷然龙潭上，石势若奔走。
开拆秋天光，崩腾夏雷吼。
灵溪自兹去，纡直互纷纠。
听声静复喧，望色无更有。
冥冥翠微下，高殿映杉柳。
滴滴洞穴中，悬泉响相扣。
昔时秦王女，羽化年代久。
日暮松风来，箫声生左右。
早窥神仙箓，愿结芝术友。
安得羡门方，青囊系吾肘。','',''),('quantangshi-07554','春游吟','李華','quantangshi','','卷8','初春遍芳甸，千里蔼盈瞩。
美人摘新英，步步翫春绿。
所思杳何处，宛在吴江曲。
可怜不得共芳菲，日暮归来泪满衣。','',''),('quantangshi-07555','长门怨','李華','quantangshi','','卷8','弱体鸳鸯荐，啼妆翡翠衾。
鸦鸣秋殿晓，人静禁门深。
每忆椒房宠，那堪永巷阴。
自惊罗带缓，非复旧来心。','',''),('quantangshi-07556','奉使朔方赠郭都护','李華','quantangshi','','卷8','绝塞临光禄，孤营佐贰师。
铁衣山月冷，金鼓朔风悲。
都护征兵日，将军破虏时。
扬鞭玉关道，回首望旌旗。','',''),('quantangshi-07557','尚书都堂瓦松','李華','quantangshi','','卷8','华省祕仙踪，高堂露瓦松。
叶因春后长，花为雨来浓。
影混鸳鸯色，光含翡翠容。
天然斯所寄，地势太无从。
接栋临双阙，连甍近九重。
宁知深涧底，霜雪岁兼封。','',''),('quantangshi-07558','海上生明月','李華','quantangshi','','卷8','皎皎秋中月，团团海上生。
影开金镜满，轮抱玉壶清。
渐出三山岊，将凌一汉横。
素娥尝药去，乌鹊遶枝惊。
照水光偏白，浮云色最明。
此时尧砌下，蓂荚自将荣。','',''),('quantangshi-07559','晚日湖上寄所思','李華','quantangshi','','卷8','与君为近别，不啻远相思。
落日平湖上，看山对此时。','',''),('quantangshi-07560','寄从弟','李華','quantangshi','','卷8','眼病身亦病，浮生已半空。
迢迢千里月，应与惠连同。','',''),('quantangshi-07561','奉寄彭城公','李華','quantangshi','','卷8','公子三千客，人人愿报恩。
应怜抱关者，贫病老夷门。','',''),('quantangshi-07562','春行寄兴','李華','quantangshi','','卷8','宜阳城下草萋萋，涧水东流复向西。
芳树无人花自落，春山一路鸟空啼。','',''),('quantangshi-07563','江有枫一篇十章 一','蕭穎士','quantangshi','','卷8','江有枫，其叶蒙蒙。
我友自东，于以游从。','',''),('quantangshi-07564','江有枫一篇十章 二','蕭穎士','quantangshi','','卷8','山有槭，其叶漠漠。
我友徂北，于以休息。','',''),('quantangshi-07565','江有枫一篇十章 三','蕭穎士','quantangshi','','卷8','想彼槭矣，亦类其枫。
矧伊怀人，而忘其东。','',''),('quantangshi-07566','江有枫一篇十章 四','蕭穎士','quantangshi','','卷8','东可游矣，会之丘矣。
于山于水，于庙于寺。
于亭于里，君子游焉。
于以宴喜，其乐亹亹。','',''),('quantangshi-07567','江有枫一篇十章 五','蕭穎士','quantangshi','','卷8','粤东可居，彼吴之墟。
有田有庭，有朋有书。
有莼有鱼，君子居焉。
惟以宴醑，其乐徐徐。','',''),('quantangshi-07568','江有枫一篇十章 六','蕭穎士','quantangshi','','卷8','我朋在矣，彼陆之子。
如松如杞，淑问不已。','',''),('quantangshi-07569','江有枫一篇十章 七','蕭穎士','quantangshi','','卷8','我友于征，彼郑之子。
如琇如英，德音孔明。','',''),('quantangshi-07570','江有枫一篇十章 八','蕭穎士','quantangshi','','卷8','我思震泽，菱芡幕幕。
寤寐如觌，我思剡溪。
杉筱萋萋，寤寐无迷。','',''),('quantangshi-07571','江有枫一篇十章 九','蕭穎士','quantangshi','','卷8','有鸟有鸟，粤鸥与鹭。
浮湍戏渚，皓然洁素。
忘其猜妒，彼何人斯，曾足伤惧。','',''),('quantangshi-07572','江有枫一篇十章 十','蕭穎士','quantangshi','','卷8','此惧惟何，惧置于罗。
彼骄者子，谗言孔多。
我闻先师，体命委和。
公伯之愬，则如予何。
怅然山河，惟以啸歌，其忧也哉。','',''),('quantangshi-07573','菊荣一篇五章 一','蕭穎士','quantangshi','','卷8','采采者菊，芬其荣斯。
紫英黄萼，照灼丹墀。
恺悌君子，佩服攸宜。
王国是维，大君是毗。
贻尔子孙，百禄萃之。','',''),('quantangshi-07574','菊荣一篇五章 二','蕭穎士','quantangshi','','卷8','采采者菊，于邑之城。
旧根新茎，布叶垂英。
彼美淑人，应家之祯。
有弦既鸣，我政则平。
宜尔栋崇，必复其庆。','',''),('quantangshi-07575','菊荣一篇五章 三','蕭穎士','quantangshi','','卷8','采采者菊，于邦之府。
阴槐翳柳，迩楹近宇。
彼劳者子，喧卑是处。
慨其莫知，蕴结谁语。
企彼高人，色斯遐举。','',''),('quantangshi-07576','菊荣一篇五章 四','蕭穎士','quantangshi','','卷8','采采者菊，于宾之馆。
既低其枝，又弱其干。
有斐君子，是焉披翫。
良辰旨酒，宴饮无算。
怆其仳别，终然永叹。','',''),('quantangshi-07577','菊荣一篇五章 五','蕭穎士','quantangshi','','卷8','岁方晏矣，霜露残促。
谁其荣斯，有英者菊。
岂微春华，懿此贞色。
人之侮我，混于薪棘。
诗人有言，好是正直。','',''),('quantangshi-07578','凉雨一章','蕭穎士','quantangshi','','卷8','习习凉风，泠泠浮飙。
君子乐胥，于其宾僚。
有女斯夭，式歌且谣。
欲言终宥，惟以招邀，于胥乐兮。','',''),('quantangshi-07579','有竹一篇七章','蕭穎士','quantangshi','','卷8','有竹斯竿，于阁之前。
君子秉心，惟其贞坚兮。
有竿斯竹，于阁之侧。
君子秉操，惟其正直兮。
彼蔚者竹，萧其森矣。
有开者合，宛其深矣。
回檐幽砌，如翼如齿。
冬之霄，霰雪斯瀌。
我有金炉，熺其以歊。
夏之日，炎景斯郁。
我有珍簟，凄其以栗。
彼纷者务，体其豫矣。
有旨者酒，欢其且矣。
友僚萃止，跗蕚载韡。
彼美公之姓兮，那欤应积庆兮，期子惟去之柄兮。','',''),('quantangshi-07580','有竹一篇七章 一','蕭穎士','quantangshi','','卷8','有竹斯竿，于阁之前。
君子秉心，惟其贞坚兮。','',''),('quantangshi-07581','有竹一篇七章 二','蕭穎士','quantangshi','','卷8','有竿斯竹，于阁之侧。
君子秉操，惟其正直兮。','',''),('quantangshi-07582','有竹一篇七章 三','蕭穎士','quantangshi','','卷8','彼蔚者竹，萧其森矣。
有开者合，宛其深矣。
回檐幽砌，如翼如齿。','',''),('quantangshi-07583','有竹一篇七章 四','蕭穎士','quantangshi','','卷8','冬之霄，霰雪斯瀌。
我有金炉，熺其以歊。','',''),('quantangshi-07584','有竹一篇七章 五','蕭穎士','quantangshi','','卷8','夏之日，炎景斯郁。
我有珍簟，凄其以栗。','',''),('quantangshi-07585','有竹一篇七章 六','蕭穎士','quantangshi','','卷8','彼纷者务，体其豫矣。
有旨者酒，欢其且矣。
友僚萃止，跗蕚载韡。','',''),('quantangshi-07586','有竹一篇七章 七','蕭穎士','quantangshi','','卷8','彼美公之姓兮，那欤应积庆兮，期子惟去之柄兮。','',''),('quantangshi-07587','江有归舟三章 一','蕭穎士','quantangshi','','卷8','江有归舟，亦乱其流。
之子言旋，嘉名孔修。
扬于王庭，允焯其休。','',''),('quantangshi-07588','江有归舟三章 二','蕭穎士','quantangshi','','卷8','舟既归止，人亦荣止。
兄矣弟矣，孝斯践矣。
称觞燕喜，于岵于屺。','',''),('quantangshi-07589','江有归舟三章 三','蕭穎士','quantangshi','','卷8','彼游惟帆，匪风不扬。
有彬伊父，匪学不彰。
予其怀而，勉尔无忘。','',''),('quantangshi-07590','过河滨和文学张志尹','蕭穎士','quantangshi','','卷8','隆古日以远，举世丧其淳。
慷慨怀黄虞，化理何由臻。
步出城西门，裴回见河滨。
当其侧陋时，河水清且潾。
沧桑一以变，莽然翳荆榛。
至化无苦窳，宇宙将陶甄。
太息感悲泉，人往迹未湮。
瑟瑟寒原暮，冷风吹衣巾。
顾我谫劣质，希圣杳无因。
且尽登临意，斗酒欢相亲。','',''),('quantangshi-07591','舟中遇陆棣兄西归数日得广陵二三子书知迟晚次沙垫西岸作','蕭穎士','quantangshi','','卷8','林乌遥岸鸣，早知东方曙。
波上风雨歇，舟人叫将去。
苍苍前洲日，的的回沙鹭。
水气清晓阴，滩声隐川雾。
旧山劳魂想，忆人阻洄溯。
信宿千里余，佳期曷由遇。
前程入楚乡，弭棹问维扬。
但见土音异，始知程路长。
寥寥晚空静，漫漫风淮凉。
云景信可美，风潮殊未央。
故人江臯上，永日念容光。
中路枉尺书，谓余琼树芳。
深期结晤语，竟夕恨相望。
冀愿崇朝霁，吾其一苇航。','',''),('quantangshi-07592','重阳日陪元鲁山德秀登北城瞩对新霁因以赠别','蕭穎士','quantangshi','','卷8','山县遶古堞，悠悠快登望。
雨余秋天高，目尽无隐状。
绵连滍川回，杳渺鸦路深。
彭泽兴不浅，临风动归心。
赖兹琴堂暇，傲睨倾菊酒。
人和岁已登，从政复何有。
远山十里碧，一道衔长云。
青霞半落日，混合疑晴曛。
渐闻惊栖羽，坐叹清夜月。
中欢怆有违，行子念明发。
仅能泯宠辱，未免伤别离。
江湖不可忘，风雨劳相思。
明时当盛才，短伎安所设。
何日谢百里，从君汉之澨。','',''),('quantangshi-07593','留别二三子得韵字','蕭穎士','quantangshi','','卷8','二纪尚雌伏，徒然忝先进。
英英尔众贤，名实郁双振。
残春惜将别，清洛行不近。
相与爱后时，无令孤逸韵。','',''),('quantangshi-07594','仰答韦司业垂访五首 一','蕭穎士','quantangshi','','卷8','呦呦食苹鹿，常饮清泠川。
但悦丰草美，宁知牢馔鲜。
主人有幽意，将以充林泉。
罗网幸免伤，蒙君复羁牵。
高堂列众宾，广座鸣清弦。
俯仰转惊惕，裴回独忧煎。
缅怀云岩路，欲往无由缘。
物各有所好，违之伤自然。','',''),('quantangshi-07595','仰答韦司业垂访五首 二','蕭穎士','quantangshi','','卷8','神龟在南国，缅邈湘川阴。
游止莲叶上，岁时嘉树林。
毒虫且不近，斤斧何由寻。
错落负奇文，荧煌耀丹金。
江山万里余，淮海阻且深。
独保贞素质，不为寒暑侵。
一逢盛明代，应见通灵心。','',''),('quantangshi-07596','仰答韦司业垂访五首 三','蕭穎士','quantangshi','','卷8','晋代有儒臣，当年富词藻。
立言寄青史，将以赞王道。
辽落缅岁时，辛勤历江岛。
且言风波倦，探涉岂为宝。
不遇庾征西，云谁展怀抱。
士贫乏知己，安得成所好。','',''),('quantangshi-07597','仰答韦司业垂访五首 四','蕭穎士','quantangshi','','卷8','彭阳昔游说，愿谒南郢都。
王果尚未达，况从夷节谟。
岂知晋叔向，无罪婴囚拘。
临难俟解纷，独知[祁]大夫。
举讐且不弃，何必论亲疎。
夫子觉者也，其能遗我乎。','',''),('quantangshi-07598','仰答韦司业垂访五首 五','蕭穎士','quantangshi','','卷8','关西一公子，年貌独青春。
被褐来上京，翳然声未振。
中郎何为者，倒屣惊座宾。
词赋岂不佳，盛名亦相因。
为君奏此曲，此曲多苦辛。
千载不可诬，孰言今无人。','',''),('quantangshi-07599','答邹象先','蕭穎士','quantangshi','','卷8','桂枝常共擢，茅茨冀同荐。
一命何阻修，载驰各川县。
壮图悲岁月，明代耻贫贱。
回首无津梁，祗令二毛变。','',''),('quantangshi-07600','蒙山作','蕭穎士','quantangshi','','卷8','东蒙镇海沂，合沓余百里。
清秋净氛霭，崖崿隐天起。
于役劳往还，息徒暂攀跻。
将穷绝迹处，偶得冥心理。
云气杂虹霓，松声乱风水。
微明绿林际，杳窱丹洞里。
仙鸟时可闻，羽人邈难视。
此焉多深邃，贤达昔所止。
子尚捐俗纷，季随蹑遐轨。
蕴真道弥旷，怀古情未已。
白鹿凡几游，黄精复奚似。
顾予尚牵缠，家业重书史。
少学务从师，壮年贵趋仕。
方驰桂林誉，未暇桃源美。
岁暮期再寻，幽哉羡门子。','',''),('quantangshi-07601','早春过七岭寄题硖石裴丞厅壁','蕭穎士','quantangshi','','卷8','出硖寄趣少，晚行偏忆君。
依然向来处，官路溪边云。
兹路岂不剧，能无俗累纷。
槐阴永未合，泉声细犹闻。
弥叹春罢酒，牵卑从此分。
登高望城入，斜影半风薰。','',''),('quantangshi-07602','送张翚下第归江东','蕭穎士','quantangshi','','卷8','俱飞仍失路，彩服迩清波。
地积东南美，朝遗甲乙科。
客愁千里别，春色五湖多。
明日旧山去，其如相望何。','',''),('quantangshi-07603','越江秋曙','蕭穎士','quantangshi','','卷8','扁舟东路远，晓月下江濆。
潋滟信潮上，苍茫孤屿分。
林声寒动叶，水气曙连云。
暾日浪中出，榜歌天际闻。
伯鸾常去国，安道惜离羣。
延首剡溪近，咏言怀数君。','',''),('quantangshi-07604','山庄月夜作','蕭穎士','quantangshi','','卷8','献书嗟弃置，疲拙归田园。
且事计然策，将符公冶言。
桑榆清暮景，鸡犬应遥村。
蚕罢里闾晏，麦秋田野喧。
涧声连枕簟，峯势入阶轩。
未奏东山妓，先倾北海尊。
陇瓜香早熟，庭果落初繁。
更惬野人意，农谈朝竟昏。','',''),('quantangshi-07605','古意','崔曙','quantangshi','','卷8','绿笋总成竹，红花亦成子。
能当此时好，独自幽闺里。
夜夜苦更长，愁来不如死。','',''),('quantangshi-07606','宿大通和尚塔敬赠如上人兼呈常孙二山人','崔曙','quantangshi','','卷8','支公已寂灭，影塔山上古。
更有真僧来，道场救诸苦。
一承微妙法，寓宿清净土。
身心能自观，色相了无取。
森森松映月，漠漠云近户。
岭外飞电明，夜来前山雨。
然灯见栖鸽，作礼闻信鼓。
晓霁南轩开，秋华净天宇。
愿言出世尘，谢尔申及甫。','',''),('quantangshi-07607','送薛据之宋州','崔曙','quantangshi','','卷8','无媒嗟失路，有道亦乘流。
客处不堪别，异乡应共愁。
我生早孤贱，沦落居此州。
风土至今忆，山河皆昔游。
一从文章事，两京春复秋。
君去问相识，几人今白头。','',''),('quantangshi-07608','山下晚晴','崔曙','quantangshi','','卷8','寥寥远天净，溪路何空蒙。
斜光照疎雨，秋气生白虹。
云尽山色暝，萧条西北风。
故林归宿处，一叶下梧桐。','',''),('quantangshi-07609','颍阳东溪怀古','崔曙','quantangshi','','卷8','灵溪氛雾歇，皎镜清心颜。
空色不映水，秋声多在山。
世人久疎旷，万物皆自闲。
白鹭寒更浴，孤云晴未还。
昔时让王者，此地闭玄关。
无以蹑高步，凄凉岑壑间。','',''),('quantangshi-07610','早发交崖山还太室作','崔曙','quantangshi','','卷8','东林气微白，寒鸟急高翔。
吾亦自兹去，北山归草堂。
仲冬正三五，日月遥相望。
萧萧过颍上，昽昽辨少阳。
川冰生积雪，野火出枯桑。
独往路难尽，穷阴人易伤。
伤此无衣客，如何蒙雪霜。','',''),('quantangshi-07611','奉试明堂火珠','崔曙','quantangshi','','卷8','正位开重屋，凌空出火珠。
夜来双月满，曙后一星孤。
天净光难灭，云生望欲无。
遥知太平代，国宝在名都。','',''),('quantangshi-07612','途中晓发','崔曙','quantangshi','','卷8','晓霁长风里，劳歌赴远期。
云轻归海疾，月满下山迟。
旅望因高尽，乡心遇物悲。
故林遥不见，况在落花时。','',''),('quantangshi-07613','缑山庙','崔曙','quantangshi','','卷8','遗庙宿阴阴，孤峰映绿林。
步随仙路远，意入道门深。
涧水流年月，山云变古今。
祗闻风竹里，犹有凤笙音。','',''),('quantangshi-07614','同诸公谒启母祠','崔曙','quantangshi','','卷8','閟宫凌紫微，芳草闭闲扉。
帝子复何在，王孙游不归。
春风鸣玉佩，暮雨拂灵衣。
岂但湘江口，能令怀二妃。','',''),('quantangshi-07615','九日登望仙台呈刘明府容','崔曙','quantangshi','','卷8','汉文皇帝有高台，此日登临曙色开。
三晋云山皆北向，二陵风雨自东来。
关门令尹谁能识，河上仙翁去不回。
且欲近寻彭泽宰，陶然共醉菊花杯。','',''),('quantangshi-07616','奉酬中书相公至日圆丘摄事合于中书后阁宿斋移止于集贤院叙怀见寄之作','崔曙','quantangshi','','卷8','典籍开书府，恩荣避鼎司。
郊丘资有事，斋戒守无为。
宿雾蒙琼树，余香覆玉墀。
进经逢乙夜，展礼值明时。
勋共山河列，名同竹帛垂。
年年佐尧舜，相与致雍熙。','',''),('quantangshi-07617','登水门楼见亡友张贞期题望黄河诗因以感兴','崔曙','quantangshi','','卷8','吾友东南美，昔闻登此楼。
人随川上逝，书向壁中留。
严子好真隐，谢公耽远游。
清风初作颂，暇日复销忧。
时与文字古，迹将山水幽。
已孤苍生望，空见黄河流。
流落年将晚，悲凉物已秋。
天高不可问，掩泣赴行舟。','',''),('quantangshi-07618','对雨送郑陵','崔曙','quantangshi','','卷8','别愁复经雨，别泪还如霰。
寄心海上云，千里常相见。','',''),('quantangshi-07619','嵩山寻冯炼师不遇','崔曙','quantangshi','','卷8','青溪访道凌烟曙，王子仙成已飞去。
更值空山雷雨时，云林薄暮归何处。','',''),('quantangshi-07620','赠唐祖二子','王翰','quantangshi','','卷8','鸿飞遵枉渚，鹿鸣思故羣。
物情尚劳爱，况乃予别君。
别时花始发，别后兰再薰。
瑶觞滋白露，宝瑟凝凉氛。
裴徊北林月，怅望南山云。
云月渺千里，音徽不可闻。','',''),('quantangshi-07621','飞燕篇','王翰','quantangshi','','卷8','孝成皇帝本娇奢，行幸平阳公主家。
可怜女儿三五许，䒠茸惜是一园花。
歌舞向来人不贵，一旦逢君感君意。
君心见赏不见忘，姊妹双飞入紫房。
紫房彩女不得见，专荣固宠昭阳殿。
红妆宝镜珊瑚台，青琐银簧云母扇。
日夕风传歌舞声，祗扰长信忧人情。
长信忧人气欲绝，君王歌吹终不歇。
朝弄琼箫下彩云，夜踏金梯上明月。
明月薄蚀阳精昏，娇妬倾城惑至尊。
已见白虹横紫极，复闻飞燕啄皇孙。
皇孙不死燕啄折，女弟一朝如火绝。
明明天子咸戒之，赫赫宗周襃姒灭。
古来贤圣叹狐裘，一国荒淫万国羞。
安得上方断马劒，斩取朱门公子头。','',''),('quantangshi-07622','饮马长城窟行','王翰','quantangshi','','卷8','长安少年无远图，一生惟羡执金吾。
麒麟前殿拜天子，走马西击长城胡。
胡沙猎猎吹人面，汉虏相逢不相见。
遥闻鼙鼓动地来，传道单于夜犹战。
此时顾恩宁顾身，为君一行摧万人。
壮士挥戈回白日，单于溅血染朱轮。
归来饮马长城窟，长城道傍多白骨。
问之耆老何代人，云是秦王筑城卒。
黄昏塞北无人烟，鬼哭啾啾声沸天。
无罪见诛功不赏，孤魂流落此城边。
当昔秦王按劒起，诸侯膝行不敢视。
富国强兵二十年，筑怨兴徭九千里。
秦王筑城何太愚，天实亡秦非北胡。
一朝祸起萧墙内，渭水咸阳不复都。','',''),('quantangshi-07623','赋得明星玉女坛送廉察尉华阴','王翰','quantangshi','','卷8','洪河之南曰秦镇，发地削成五千仞。
三峰离地皆倚天，唯独中峰特修峻。
上有明星玉女祠，祠坛高眇路逶迤。
三十六梯入河汉，樵人往往见蛾眉。
蛾眉婵娟又宜笑，一见樵人下灵庙。
仙车欲驾五云飞，香扇斜开九华照。
含情迟伫惜韶年，愿侍君边复中旋。
江妃玉佩留为念，嬴女银箫空自怜。
仙俗途殊两情遽，感君无尽辞君去。
遥见明星是妾家，风飘雪散不知处。
故人家在西长安，卖药往来投此山。
彩云荡漾不可见，绿萝蒙茸鸟绵蛮。
欲求玉女长生法，日夜烧香应自还。','',''),('quantangshi-07624','春女行','王翰','quantangshi','','卷8','紫台穹跨连绿波，红轩铪匝垂纤罗。
中有一人金作面，隔幌玲珑遥可见。
忽闻黄鸟鸣且悲，镜边含笑着春衣。
罗袖婵娟似无力，行拾落花比容色。
落花一度无再春，人生作乐须及辰。
君不见楚王台上红颜子，今日皆成狐兔尘。','',''),('quantangshi-07625','古娥眉怨','王翰','quantangshi','','卷8','君不见宜春苑中九华殿，飞阁连连直如发。
白日全含朱鸟窓，流云半入苍龙阙。
宫中彩女夜无事，学凤吹箫弄清越。
珠帘北卷待凉风，绣户南开向明月。
忽闻天子忆蛾眉，宝凤衔花揲两螭。
传声走马开金屋，夹路鸣环上玉墀。
长乐彤庭宴华寝，三千美人曳花锦。
灯前含笑更罗衣，帐里承恩荐瑶枕。
不意君心半路回，求仙别作望仙台。
琳琅禁闼遥相忆，紫翠岩房昼不开。
欲向人间种桃实，先从海底觅蓬莱。
蓬来可求不可上，孤舟飘缈知何往。
黄金作盘铜作茎，青天白露掌中擎。
王母嫣然感君意，云车羽斾欲相迎。
飞廉观前空怨慕，少君何事须相误。
一朝埋没茂陵田，贱妾蛾眉不重顾。
宫车晚出向南山，仙卫逶迤去不还。
朝晡泣对麒麟树，树下苍苔日渐斑。
人生百年夜将半，对酒长歌莫长叹。
情知白日不可私，一死一生何足筭。','',''),('quantangshi-07626','子夜春歌','王翰','quantangshi','','卷8','春气满林香，春游不可忘。
落花吹欲尽，垂柳折还长。
桑女淮南曲，金鞍塞北装。
行行小垂手，日暮渭川阳。','',''),('quantangshi-07627','奉和圣制同二相已下羣官乐游园宴','王翰','quantangshi','','卷8','未极人心畅，如何帝道明。
仍嫌酺宴促，复宠乐游行。
陆海披珍藏，天河直斗城。
四关青霭合，数处白云生。
饪餗调元气，歌钟溢雅声。
空惭尧舜日，至德杳难名。','',''),('quantangshi-07628','奉和圣制送张说上集贤院学士赐宴得筵字','王翰','quantangshi','','卷8','东堂起集贤，贵得从神仙。
首命台阶老，将崇御府员。
送人锵玉佩，中使拂琼筵。
和乐薰风解，湛恩时雨连。
长材成磊落，短翮强翩翾。
徒仰蓬莱地，何阶不让缘。','',''),('quantangshi-07629','奉和圣制送张尚书巡边','王翰','quantangshi','','卷8','紫绶尚书印，朱軿丞相车。
登朝身许国，出阃将辞家。
不惮炎蒸苦，亲尝走集赊。
选徒军有政，誓卒尔无哗。
帝乐风初起，王城日半斜。
宠行流圣作，寅饯照台华。
骑历河南树，旌摇塞北沙。
荣怀应尽服，严杀已先加。
业峻灵只保，功成道路嗟。
宁如凿空使，远致石榴花。','',''),('quantangshi-07630','凉州词二首 一','王翰','quantangshi','','卷8','葡萄美酒夜光杯，欲饮琵琶马上催。
醉卧沙场君莫笑，古来征战几人回。','',''),('quantangshi-07631','凉州词二首 二','王翰','quantangshi','','卷8','秦中花鸟已应阑，塞外风沙犹自寒。
夜听胡笳折杨柳，教人意气忆长安。','',''),('quantangshi-07632','春日归思','王翰','quantangshi','','卷8','杨柳青青杏发花，年光误客转思家。
不知湖上菱歌女，几个春舟在若耶。','',''),('quantangshi-07633','观蛮童为伎之作','王翰','quantangshi','','卷8','长裙锦带还留客，广额青蛾亦效嚬。
共惜不成金谷妓，虚令看杀玉车人。','',''),('quantangshi-07634','古别离','孟雲卿','quantangshi','','卷8','朝日上高台，离人怨秋草。
但见万里天，不见万里道。
君行本迢远，苦乐良难保。
宿昔梦同衾，忧心常倾倒。
含酸欲谁诉，展转伤怀抱。
结发年已迟，征行去何早。
寒暄有时谢，憔悴难再好。
人皆算年寿，死者何曾老。
少壮无见期，水深风浩浩。','',''),('quantangshi-07635','今别离','孟雲卿','quantangshi','','卷8','结发生别离，相思复相保。
如何日已久，五变庭中草。
渺渺大海途，悠悠吴江岛。
但恐不出门，出门无远道。
远道行既难，家贫衣复单。
严风吹积雪，晨起鼻何酸。
人生各有志，岂不怀所安。
分明天上日，生死愿同欢。','',''),('quantangshi-07636','悲哉行','孟雲卿','quantangshi','','卷8','孤儿去慈亲，远客丧主人。
莫吟苦辛曲，此曲谁忍闻。
可闻不可说，去去无期别。
行人念前程，不待参辰没。
朝亦常苦饥，暮亦常苦饥。
飘飘万余里，贫贱多是非。
少年莫远游，远游多不归。','',''),('quantangshi-07637','行行且游猎篇','孟雲卿','quantangshi','','卷8','少年多武力，勇气冠幽州。
何以纵心赏，马啼春草头。
迟迟平原上，狐兔奔林丘。
猛虎忽前逝，俊鹰连下韝。
俯身逐南北，轻捷固难俦。
所发无不中，失之如我讐。
岂唯务驰骋，猗尔暴田畴。
残杀非不痛，古来良有由。','',''),('quantangshi-07638','古挽歌','孟雲卿','quantangshi','','卷8','草草闾巷喧，涂车俨成位。
冥冥何所须，尽我生人意。
北邙路非远，此别终天地。
临穴频抚棺，至哀反无泪。
尔形未衰老，尔息才童稚。
骨肉安可离，皇天若容易。
房帷即灵帐，庭宇为哀次。
薤露歌若斯，人生尽如寄。','',''),('quantangshi-07639','放歌行','孟雲卿','quantangshi','','卷8','吾观天地图，世界亦可小。
落落大海中，飘浮数洲岛。
贤愚与蚁虱，一种同草草。
地脉日夜流，天衣有时扫。
东山谒居士，了我生死道。
目见难噬脐，心通可亲脑。
轩皇竟磨灭，周孔亦衰老。
永谢当时人，吾将宝非宝。','',''),('quantangshi-07640','伤怀赠故人','孟雲卿','quantangshi','','卷8','稍稍晨鸟翔，淅淅草上霜。
人生早罹苦，寿命恐不长。
二十学已成，三十名不彰。
岂无同门友，贵贱易中肠。
驱马行万里，悠悠过帝乡。
幸因弦歌末，得上君子堂。
众乐互喧奏，独子备笙簧。
坐中无知音，安得神扬扬。
愿因高风起，上感白日光。','',''),('quantangshi-07641','邺城怀古','孟雲卿','quantangshi','','卷8','朝发淇水南，将寻北燕路。
魏家旧城阙，寥落无人住。
伊昔天地屯，曹公独中据。
羣臣将北面，白日忽西暮。
三台竟寂寞，万事良难固。
雄图安在哉？衰草霑霜露。
崔嵬长河北，尚见应刘墓。
古树藏龙蛇，荒茅伏狐兔。
永怀故池馆，数子连章句。
逸兴驱山河，雄词变云雾。
我行覩遗迹，精爽如可遇。
斗酒将酹君，悲风白杨树。','',''),('quantangshi-07642','伤情','孟雲卿','quantangshi','','卷8','为长心易忧，早孤意常伤。
出门先踌躇，入户亦彷徨。
此生一何苦，前事安可忘。
兄弟先我没，孤幼盈我傍。
旧居近东南，河水新为梁。
松柏今在兹，安忍思故乡。
四时与日月，万物各有常。
秋风已一起，草木无不霜。
行行当自勉，不忍再思量。','',''),('quantangshi-07643','伤时二首 一','孟雲卿','quantangshi','','卷8','徘回宋郊上，不覩平生亲。
独立正伤心，悲风来孟津。
大方载羣物，生死有常伦。
虎豹不相食，哀哉人食人。
岂伊逢世运，天道亮云云。','',''),('quantangshi-07644','伤时二首 二','孟雲卿','quantangshi','','卷8','太空流素月，三五何明明。
光耀侵白日，贤愚迷至精。
四时更变化，天道有亏盈。
常恐今夜没，须臾还复生。','',''),('quantangshi-07645','田园观雨兼晴后作','孟雲卿','quantangshi','','卷8','贫贱少情欲，借荒种南陂。
我非老农圃，安得良土宜。
秋成不廉俭，岁余多馁饥。
顾视仓廪间，有粮不成炊。
晨登南园上，暮歇清蝉悲。
早苗既芃芃，晚田尚离离。
五行孰堪废，万物当及时。
贤哉数夫子，开翅慎勿迟。','',''),('quantangshi-07646','汴河阻风','孟雲卿','quantangshi','','卷8','清晨自梁宋，挂席之楚荆。
出浦风渐恶，傍滩舟欲横。
大河喷东注，羣动皆窅冥。
白雾鱼龙气，黑云牛马形。
苍茫迷所适，危安惧暂宁。
信此天地内，孰为身命轻。
丈夫苟未达，所向须存诚。
前路舍舟去，东南仍晓晴。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-07647','行路难','孟雲卿','quantangshi','','卷8','君不见高山万仞连苍旻，天长地久成埃尘。
君不见长松百尺多劲节，狂风暴雨终摧折。
古今何事无圣贤，吾爱伯阳真乃天。
金堂玉阙朝羣仙，拍手东海成桑田。
海中之水慎勿枯，乌鸢啄蚌伤明珠。
行路难，艰险莫踟蹰。','',''),('quantangshi-07648','途中寄友人','孟雲卿','quantangshi','','卷8','昔时闻远路，谓是等闲行。
及到求人地，始知为客情。
事将公道背，尘遶马蹄生。
傥使长如此，便堪休去程。','',''),('quantangshi-07649','寒食','孟雲卿','quantangshi','','卷8','二月江南花满枝，他乡寒食远堪悲。
贫居往往无烟火，不独明朝为子推。','',''),('quantangshi-07650','新安江上寄处士','孟雲卿','quantangshi','','卷8','深潭与浅滩，万转出新安。
人远禽鱼静，山空水木寒。
啸起青苹末，吟瞩白云端。
即事遂幽赏，何必挂儒冠。','',''),('quantangshi-07651','句','孟雲卿','quantangshi','','卷8','羣物归大化，六龙颓西荒。
安知浮云外，日月不运行。','',''),('quantangshi-07652','闻笛','張巡','quantangshi','','卷8','岧嶤试一临，虏骑附城阴。
不辨风尘色，安知天地心。
营开边月近，战苦阵云深。
旦夕更楼上，遥闻横笛音。','',''),('quantangshi-07653','守睢阳作','張巡','quantangshi','','卷8','接战春来苦，孤城日渐危。
合围侔月晕，分守若鱼丽。
屡厌黄尘起，时将白羽挥。
裹疮犹出阵，饮血更登陴。
忠信应难敌，坚贞谅不移。
无人报天子，心计欲何施。','',''),('quantangshi-07654','题衡阳泗州寺','張抃','quantangshi','','卷8','一水悠悠百粤通，片帆无奈信秋风。
几层峡浪寒舂月，尽日江天雨打篷。
漂泊渐摇青草外，乡关谁念雪园东。
未知今夜依何处，一点渔灯出苇丛。','',''),('quantangshi-07655','古意二首 一','賀蘭進明','quantangshi','','卷8','秦庭初指鹿，羣盗满山东。
忤意皆诛死，所言谁肯忠。
武关犹未启，兵入望夷宫。
为祟非泾水，人君道自穷。','',''),('quantangshi-07656','古意二首 二','賀蘭進明','quantangshi','','卷8','崇兰生涧底，香气满幽林。
采采欲为赠，何人是同心。
日暮徙盈把，裴回忧思深。
慨然纫杂佩，重奏丘中琴。','',''),('quantangshi-07657','行路难五首 一','賀蘭進明','quantangshi','','卷8','君不见岩下井，百尺不及泉。
君不见山上苗，数寸凌云烟。
人生赋命亦如此，何苦太息自忧煎。
但愿亲友长含笑，相逢不乏杖头钱。
寒夜邀欢须秉烛，岂得常思花柳年。','',''),('quantangshi-07658','行路难五首 二','賀蘭進明','quantangshi','','卷8','君不见门前柳，荣耀暂时萧索久。
君不见陌上花，狂风吹去落谁家。
邻家思妇见之叹，蓬首不梳心历乱。
盛年夫壻长别离，岁暮相逢色已换。','',''),('quantangshi-07659','行路难五首 三','賀蘭進明','quantangshi','','卷8','君不见芳树枝，春花落尽蜂不窥。
君不见梁上泥，秋风始高燕不栖。
荡子从军事征战，[蛾]眉婵娟守空闺。
独宿自然堪下泪，况复时闻乌夜啼。','',''),('quantangshi-07660','行路难五首 四','賀蘭進明','quantangshi','','卷8','君不见云中月，暂盈还复缺。
君不见林下风，声远意难穷。
亲故平生或聚散，欢娱未尽尊酒空。
叹息青青陵上柏，岁寒能有几人同。','',''),('quantangshi-07661','行路难五首 五','賀蘭進明','quantangshi','','卷8','君不见东流水，一去无穷已。
君不见西郊云，日夕空氛氲。
羣雁裴回不能去，一雁悲鸣复失羣。
人生结交在终始，莫以升沈中路分。','',''),('quantangshi-07662','夜渡江','閭丘曉','quantangshi','','卷8','舟人自相报，落日下芳潭。
夜火连淮市，春风满客帆。
水穷沧海畔，路尽小山南。
且喜乡园近，言荣意未甘。','',''),('quantangshi-07663','奉和刘采访缙云南岭作','庾光先','quantangshi','','卷8','百越城池枕海圻，永嘉山水复相依。
悬萝弱筱垂清浅，宿雨朝暾和翠微。
鸟讶山经传不尽，花随月令数仍稀。
幸陪谢客题诗句，谁与王孙此地归。','',''),('quantangshi-07664','思归寄东林澈上人','韋丹','quantangshi','','卷8','王事纷纷无暇日，浮生冉冉只如云。
已为平子归休计，五老岩前必共闻。','',''),('quantangshi-07665','答澈公','韋丹','quantangshi','','卷8','空山泉落松窗静，闲地草生春日迟。
白发渐多身未退，依依常在永禅师。','',''),('quantangshi-07666','洛出书','蕭昕','quantangshi','','卷8','海内昔凋瘵，天网斯浡潏。
龟灵启圣图，龙马负书出。
大哉明德盛，远矣彝伦秩。
地敷作乂功，人免为鱼恤。
既彰千国理，岂止百川溢。
永赖至于今，畴庸未云毕。','',''),('quantangshi-07667','临风舒锦','蕭昕','quantangshi','','卷8','丽锦疋云终，襜襜展向风。
花开翻覆翠，色乱动摇红。
缕散悠扬里，文回照灼中。
低垂疑步障，吹起作晴虹。
既与丘迟梦，深知卓氏功。
还乡将制服，从此表亨通。','',''),('quantangshi-07668','东皇太一词','李希仲','quantangshi','','卷8','吉日初齐戒，灵巫穆上皇。
焚香布瑶席，鸣佩奠椒浆。
缓舞花飞满，清歌水去长。
回波送神曲，云雨满潇湘。','',''),('quantangshi-07669','蓟北行二首 一','李希仲','quantangshi','','卷8','旄头有精芒，胡骑猎秋草。
羽檄南渡河，边庭用兵早。
汉家爱征战，宿将今已老。
辛苦羽林儿，从戎榆关道。','',''),('quantangshi-07670','蓟北行二首 二','李希仲','quantangshi','','卷8','一身救边速，烽火通蓟门。
前军飞鸟断，格鬬尘沙昏。
寒日鼓声急，单于夜将奔。
当须徇忠义，身死报国恩。','',''),('quantangshi-07671','送妻','楊志堅','quantangshi','','卷8','平生志业在琴诗，头上如今有二丝。
渔父尚知溪谷暗，山妻不信出身迟。
荆钗任意撩新鬓，明镜从他别画眉。
今日便同行路客，相逢即是下山时。','',''),('quantangshi-07672','从张丞相游南纪城猎戏赠裴迪张参军','孟浩然','quantangshi','','卷8','从禽非吾乐，不好云梦田。
岁暮登城望，偏令相思悬。
公卿有几几，车骑何翩翩。
世禄金张贵，官曹幕府贤。
顺时行杀气，飞刃争割鲜。
十里届宾馆，征声匝妓筵。
高标回落日，平楚散芳烟。
何意狂歌客，从公亦在旃。','',''),('quantangshi-07673','登江中孤屿赠白云先生王迥','孟浩然','quantangshi','','卷8','悠悠清水江，水落沙屿出。
回潭石下深，绿筱岸傍密。
鲛人潜不见，渔父歌自逸。
忆与君别时，泛舟如昨日。
夕阳开返照，中坐兴非一。
南望鹿门山，归来恨如失。','',''),('quantangshi-07674','晚春卧病寄张八','孟浩然','quantangshi','','卷8','南陌春将晚，北窗犹卧病。
林园久不游，草木一何盛。
狭迳花障迷，闲庭竹扫净。
翠羽戏兰苕，赬鳞动荷柄。
念我平生好，江乡远从政。
云山阻梦思，衾枕劳歌咏。
歌咏复何为，同心恨别离。
世途皆自媚，流俗寡相知。
贾谊才空逸，安仁鬓欲丝。
遥情每东注，奔晷复西驰。
常恐填沟壑，无由振羽仪。
穷通若有命，欲向论中推。','',''),('quantangshi-07675','秋登兰山寄张五','孟浩然','quantangshi','','卷8','北山白云里，隐者自怡悦。
相望试登高，心飞逐鸟灭。
愁因薄暮起，兴是清秋发。
时见归村人，沙行渡头歇。
天边树若荠，江畔舟如月。
何当载酒来，共醉重阳节。','',''),('quantangshi-07676','入峡寄弟','孟浩然','quantangshi','','卷8','吾昔与尔辈，读书常闭门。
未尝冒湍险，岂顾垂堂言。
自此历江湖，辛勤难具论。
往来行旅弊，开凿禹功存。
壁立千峰峻，潨流万壑奔。
我来凡几宿，无夕不闻猿。
浦上摇归恋，舟中失梦魂。
泪沾明月峡，心断鹡鸰原。
离阔星难聚，秋深露已繁。
因君下南楚，书此示乡园。','',''),('quantangshi-07677','湖中旅泊寄阎九司户防','孟浩然','quantangshi','','卷8','桂水通百越，扁舟期晓发。
荆云蔽三巴，夕望不见家。
襄王梦行雨，才子谪长沙。
长沙饶瘴疠，胡为苦留滞。
久别思款颜，承欢怀接袂。
接袂杳无由，徒增旅泊愁。
清猿不可听，沿月下湘流。','',''),('quantangshi-07678','大堤行寄万七','孟浩然','quantangshi','','卷8','大堤行乐处，车马相驰突。
岁岁春草生，踏青二三月。
王孙挟珠弹，游女矜罗袜。
携手今莫同，江花为谁发。','',''),('quantangshi-07679','仲夏归汉南园寄京邑耆旧','孟浩然','quantangshi','','卷8','尝读高士传，最嘉陶征君。
日耽田园趣，自谓羲皇人。
予复何为者，栖栖徒问津。
中年废丘壑，上国旅风尘。
忠欲事明主，孝思侍老亲。
归来当炎夏，耕稼不及春。
扇枕北窗下，采芝南涧滨。
因声谢同列，吾慕颍阳真。','',''),('quantangshi-07680','题云门山寄越府包户曹徐起居','孟浩然','quantangshi','','卷8','我行适诸越，梦寐怀所欢。
久负独往愿，今来恣游盘。
台岭践磴石，耶溪溯林湍。
舍舟入香界，登阁憩旃檀。
晴山秦望近，春水镜湖宽。
远怀伫应接，卑位徒劳安。
白云日夕滞，沧海去来观。
故国眇天末，良朋在朝端。','',''),('quantangshi-07681','宿扬子津寄润州长山刘隐士','孟浩然','quantangshi','','卷8','所思在建业，欲往大江深。
日夕望京口，烟波愁我心。
心驰茅山洞，目极枫树林。
不见少微星，星霜劳夜吟。','',''),('quantangshi-07682','书怀贻京邑同好','孟浩然','quantangshi','','卷8','维先自邹鲁，家世重儒风。
诗体袭遗训，趋庭霑末躬。
昼夜常自强，词翰颇亦工。
三十既成立，嗟吁命不通。
慈亲向羸老，喜惧在深衷。
甘脆朝不足，箪瓢夕屡空。
执鞭慕夫子，捧檄怀毛公。
感激遂弹冠，安能守固穷。
当途诉知己，投剌匪求蒙。
秦楚邈离异，飜飞何日同。','',''),('quantangshi-07683','还山贻湛法师','孟浩然','quantangshi','','卷8','幼闻无生理，常欲观此身。
心迹罕兼遂，[崎岖]多在尘。
晚途归旧壑，偶与支公邻。
导以微妙法，结为清净因。
烦恼业顿舍，山林情转殷。
朝来问疑义，夕话得清真。
墨妙称古绝，词华惊世人。
禅房闭虚静，花药连冬春。
平石籍琴砚，落泉洒衣巾。
欲知冥灭意，朝夕海鸥驯。','',''),('quantangshi-07684','夏日南亭怀辛大','孟浩然','quantangshi','','卷8','山光忽西落，池月渐东上。
散发乘夕凉，开轩卧闲敞。
荷风送香气，竹露滴清响。
欲取鸣琴弹，恨无知音赏。
感此怀故人，中宵劳梦想。','',''),('quantangshi-07685','秋宵月下有怀','孟浩然','quantangshi','','卷8','秋空明月悬，光彩露霑湿。
惊鹊栖未定，飞萤卷帘入。
庭槐寒影疎，邻杵夜声急。
佳期旷何许，望望空伫立。','',''),('quantangshi-07686','将适天台留别临安李主簿','孟浩然','quantangshi','','卷8','枳棘君尚栖，匏瓜吾岂系。
念离当夏首，漂泊指炎裔。
江海非堕游，田园失归计。
定山既早发，渔浦亦宵济。
泛泛随波澜，行行任舻枻。
故林日已远，羣木坐成翳。
羽人在丹丘，吾亦从此逝。','',''),('quantangshi-07687','送丁大凤进士赴举呈张九龄','孟浩然','quantangshi','','卷8','吾观鹪鹩赋，君负王佐才。
惜无金张援，十上空归来。
弃置乡园老，翻飞羽翼摧。
故人今在位，歧路莫迟回。','',''),('quantangshi-07688','送吴悦游韶阳','孟浩然','quantangshi','','卷8','五色怜凤雏，南飞适鹧鸪。
楚人不相识，何处求椅梧。
去去日千里，茫茫天一隅。
安能与斥鷃，决起但枪榆。','',''),('quantangshi-07689','适越留别谯县张主簿申屠少府','孟浩然','quantangshi','','卷8','朝乘汴河流，夕次谯县界。
幸值西风吹，得与故人会。
君学梅福隐，余从伯鸾迈。
别后能相思，浮云在吴会。','',''),('quantangshi-07690','送陈七赴西军','孟浩然','quantangshi','','卷8','吾观非常者，碌碌在目前。
君负鸿鹄志，蹉跎书劒年。
一闻边烽动，万里忽争先。
余亦赴京国，何当献凯还。','',''),('quantangshi-07691','送从弟邕下第后寻会稽','孟浩然','quantangshi','','卷8','疾风吹征帆，倏尔向空没。
千里在俄顷，三江坐超忽。
向来共欢娱，日夕成楚越。
落羽更分飞，谁能不惊骨。','',''),('quantangshi-07692','送辛大之鄂渚不及','孟浩然','quantangshi','','卷8','送君不相见，日暮独愁绪。
江上空裴回，天边迷处所。
郡邑经樊邓，山河入嵩汝。
蒲轮去渐遥，石径徒延伫。','',''),('quantangshi-07693','江上别流人','孟浩然','quantangshi','','卷8','以我越乡客，逢君谪居者。
分飞黄鹤楼，流落苍梧野。
驿使乘云去，征帆沿溜下。
不知从此分，还袂何时把。','',''),('quantangshi-07694','宴包二融宅','孟浩然','quantangshi','','卷8','闲居枕清洛，左右接大野。
门庭无杂宾，车辙多长者。
是时方盛夏，风物自潇洒。
五日休沐归，相携竹林下。
开襟成欢趣，对酒不能罢。
烟暝栖鸟迷，余将归白社。','',''),('quantangshi-07695','与王昌龄宴王道士房','孟浩然','quantangshi','','卷8','归来卧青山，常梦游清都。
漆园有傲吏，惠好在招呼。
书幌神仙箓，画屏山海图。
酌霞复对此，宛似入蓬壶。','',''),('quantangshi-07696','襄阳公宅饮','孟浩然','quantangshi','','卷8','窈窕夕阳佳，䒠茸春色好。
欲觅淹留处，无过狭斜道。
绮席卷龙须，香杯浮码碯。
北林积修树，南池生别岛。
手拨金翠花，心迷玉红草。
谈笑光六义，发论明三倒。
座非陈子惊，门还魏公扫。
荣辱应无间，欢娱当共保。','',''),('quantangshi-07697','寻香山湛上人','孟浩然','quantangshi','','卷8','朝游访名山，山远在空翠。
氛氲亘百里，日入行始至。
杖策寻故人，解鞭暂停骑。
石门殊豁险，篁迳转森邃。
法侣欣相逢，清谈晓不寐。
平生慕真隐，累日探奇异。
野老朝入田，山僧暮归寺。
松泉多逸响，苔壁饶古意。
谷口闻钟声，林端识香气。
愿言投此山，身世两相弃。','',''),('quantangshi-07698','云门寺西六七里闻符公兰若最幽与薛八同往','孟浩然','quantangshi','','卷8','谓予独迷方，逢子亦在野。
结交指松柏，问法寻兰若。
小溪劣容舟，怪石屡惊马。
所居最幽绝，所住皆静者。
云簇兴座隅，天空落阶下。
上人亦何闻，尘念都已舍。
四禅合真如，一切是虚假。
愿承甘露润，喜得惠风洒。
依止托山门，谁能效丘也。','',''),('quantangshi-07699','宿天台桐柏观','孟浩然','quantangshi','','卷8','海行信风帆，夕宿逗云岛。
缅寻沧洲趣，近爱赤城好。
扪萝亦践苔，辍棹恣探讨。
息阴憩桐柏，采秀弄芝草。
鹤唳清露垂，鸡鸣信潮早。
愿言解缨绂，从此去烦恼。
高步凌四明，玄踪得三老。
纷吾远游意，学彼长生道。
日夕望三山，云涛空浩浩。','',''),('quantangshi-07700','岘潭作','孟浩然','quantangshi','','卷8','石潭傍隈隩，沙岸晓夤缘。
试垂竹竿钓，果得槎头鳊。
美人骋金错，纤手脍红鲜。
因谢陆内史，莼羹何足传。','',''),('quantangshi-07701','题终南翠微寺空上人房','孟浩然','quantangshi','','卷8','翠微终南里，雨后宜返照。
闭关久沈冥，杖策一登眺。
遂造幽人室，始知静者妙。
儒道虽异门，云林颇同调。
两心相喜得，毕景共谈笑。
暝还高窗眠，时见远山烧。
缅怀赤城标，更忆临海峤。
风泉有清音，何必苏门啸。','',''),('quantangshi-07702','初春汉中漾舟','孟浩然','quantangshi','','卷8','羊公岘山下，神女汉臯曲。
雪罢冰复开，春潭千丈绿。
轻舟恣来往，探翫无厌足。
波影摇妓钗，沙光逐人目。
倾杯鱼鸟醉，联句鸎花续。
良会难再逢，日入须秉烛。','',''),('quantangshi-07703','宿业师山房期丁大不至','孟浩然','quantangshi','','卷8','夕阳度西岭，羣壑倏已暝。
松月生夜凉，风泉满清听。
樵人归欲尽，烟鸟栖初定。
之子期宿来，孤琴候萝迳。','',''),('quantangshi-07704','耶溪泛舟','孟浩然','quantangshi','','卷8','落景馀清辉，轻桡弄溪渚。
澄明爱水物，临泛何容与。
白首垂钓翁，新妆浣纱女。
相看似相识，脉脉不得语。','',''),('quantangshi-07705','彭蠡湖中望庐山','孟浩然','quantangshi','','卷8','太虚生月晕，舟子知天风。
挂席候明发，眇漫平湖中。
中流见匡阜，势压九江雄。
黤黕容霁色，峥嵘当晓空。
香炉初上日，瀑布喷成虹。
久欲追尚子，况兹怀远公。
我来限于役，未暇息微躬。
淮海途将半，星霜岁欲穷。
寄言岩栖者，毕趣当来同。','',''),('quantangshi-07706','登鹿门山','孟浩然','quantangshi','','卷8','清晓因兴来，乘流越江岘。
沙禽近方识，浦树遥莫辨。
渐至鹿门山，山明翠微浅。
岩潭多屈曲，舟檝屡回转。
昔闻庞德公，采药遂不返。
金涧饵芝术，石牀卧苔藓。
纷吾感耆旧，结揽事攀践。
隐迹今尚存，高风邈已远。
白云何时去，丹桂空偃蹇。
探讨意未穷，回艇夕阳晚。','',''),('quantangshi-07707','游明禅师西山兰若','孟浩然','quantangshi','','卷8','西山多奇状，秀出倚前楹。
停午收彩翠，夕阳照分明。
吾师住其下，禅坐证无生。
结庐就嵌窟，剪苕通往行。
谈空对樵叟，授法与山精。
日暮方辞去，田园归冶城。','',''),('quantangshi-07708','登望楚山最高顶','孟浩然','quantangshi','','卷8','山水观形胜，襄阳美会稽。
最高唯望楚，曾未一攀跻。
石壁疑削成，众山比全低。
晴明试登陟，目极无端倪。
云梦掌中小，武陵花处迷。
暝还归骑下，萝月映深溪。','',''),('quantangshi-07709','疾愈过龙泉寺精舍呈易业二公','孟浩然','quantangshi','','卷8','停午闻山钟，起行散愁疾。
寻林采芝去，转谷松翠密。
傍见精舍开，长廊饭僧毕。
石渠流雪水，金子耀霜橘。
竹房思旧游，过憩终永日。
入洞窥石髓，傍崖采蜂蜜。
日暮辞远公，虎溪相送出。','',''),('quantangshi-07710','万山潭作','孟浩然','quantangshi','','卷8','垂钓坐盘石，水清心亦闲。
鱼行潭树下，猿挂岛藤间。
游女昔解佩，传闻于此山。
求之不可得，沿月棹歌还。','',''),('quantangshi-07711','与黄侍御北津泛舟','孟浩然','quantangshi','','卷8','津无蛟龙患，日夕常安流。
本欲避骢马，何如同鷁舟。
岂伊今日幸，曾是昔年游。
莫奏琴中鹤，且随波上鸥。
堤缘九里郭，山面百城楼。
自顾躬耕者，才非管乐俦。
闻君荐草泽，从此泛沧洲。','',''),('quantangshi-07712','洗然弟竹亭','孟浩然','quantangshi','','卷8','吾与二三子，平生结交深。
俱怀鸿鹄志，昔有鹡鸰心。
逸气假毫翰，清风在竹林。
达是酒中趣，琴上偶然音。','',''),('quantangshi-07713','山中逢道士云公','孟浩然','quantangshi','','卷8','春余草木繁，耕种满田园。
酌酒聊自劝，农夫安与言。
忽闻荆山子，时出桃花源。
采樵过北谷，卖药来西村。
村烟日云夕，榛路有归客。
杖策前相逢，依然是畴昔。
邂逅欢觏止，殷勤叙离隔。
谓予搏扶桑，轻举振六翮。
奈何偶昌运，独见遗草泽。
既笑接舆狂，仍怜孔丘厄。
物情趋势利，吾道贵闲寂。
偃息西山下，门庭罕人迹。
何时还清溪，从尔炼丹液。','',''),('quantangshi-07714','越中逢天台太乙子','孟浩然','quantangshi','','卷8','仙穴逢羽人，停舻向前拜。
问余涉风水，何处远行迈。
登陆寻天台，顺流下吴会。
兹山夙所尚，安得问灵怪。
上逼青天高，俯临沧海大。
鸡鸣见日出，常觌仙人斾。
往来赤城中，逍遥白云外。
莓苔异人间，瀑布当空界。
福庭长自然，华顶旧称最。
永此从之游，何当济所届。','',''),('quantangshi-07715','家园卧疾毕太祝曜见寻','孟浩然','quantangshi','','卷8','伏枕旧游旷，笙簧劳梦思。
平生重交结，迨此令人疑。
冰室无暖气，炎云空赫曦。
隙驹不暂驻，日听凉蝉悲。
壮图哀未立，斑白恨吾衰。
夫子自南楚，缅怀嵩汝期。
顾予衡茅下，兼致禀物资。
脱分趋庭礼，殷勤伐木诗。
脱君车前鞅，设我园中葵。
斗酒须寒兴，明朝难重持。','',''),('quantangshi-07716','白云先生王迥见访','孟浩然','quantangshi','','卷8','闲归日无事，云卧昼不起。
有客款柴扉，自云巢居子。
居闲好芝术，采药来城市。
家在鹿门山，常游涧泽水。
手持白羽扇，脚步青芒履。
闻道鹤书征，临流还洗耳。','',''),('quantangshi-07717','田园作','孟浩然','quantangshi','','卷8','弊庐隔尘喧，惟先养恬素。
卜邻近三径，植果盈千树。
粤余任推迁，三十犹未遇。
书劒时将晚，丘园日已暮。
晨兴自多怀，昼坐常寡悟。
冲天羡鸿鹄，争食羞鸡骛。
望断金马门，劳歌采樵路。
乡曲无知己，朝端乏亲故。
谁能为扬雄，一荐甘泉赋。','',''),('quantangshi-07718','采樵作','孟浩然','quantangshi','','卷8','采樵入深山，山深树重叠。
桥崩卧槎拥，路险垂藤接。
日落伴将稀，山风拂萝衣。
长歌负轻策，平野望烟归。','',''),('quantangshi-07719','自浔阳泛舟经明海','孟浩然','quantangshi','','卷8','大江分九流，淼淼成水乡。
舟子乘利涉，往来至浔阳。
因之泛五湖，流浪经三湘。
观涛壮枚发，吊屈痛沈湘。
魏阙心恒在，金门诏不忘。
遥怜上林雁，冰泮也回翔。','',''),('quantangshi-07720','早发渔浦潭','孟浩然','quantangshi','','卷8','东旭早光芒，渚禽已惊聒。
卧闻渔浦口，桡声暗相拨。
日出气象分，始知江湖阔。
美人常晏起，照影弄流沫。
饮水畏惊猿，祭鱼时见獭。
舟行自无闷，况值晴景豁。','',''),('quantangshi-07721','经七里滩','孟浩然','quantangshi','','卷8','予奉垂堂诫，千金非所轻。
为多山水乐，频作泛舟行。
五岳追向子，三湘吊屈平。
湖经洞庭阔，江入新安清。
复闻严陵濑，乃在兹湍路。
叠障数百里，沿洄非一趣。
彩翠相氛氲，别流乱奔注。
钓矶平可坐，苔磴滑难步。
猨饮石下潭，鸟还日边树。
观奇恨来晚，倚棹惜将暮。
挥手弄潺湲，从兹洗尘虑。','',''),('quantangshi-07722','岁暮海上作','孟浩然','quantangshi','','卷8','仲尼既云殁，余亦浮于海。
昏见斗柄回，方知岁星改。
虚舟任所适，垂钓非有待。
为问乘槎人，沧洲复谁在。','',''),('quantangshi-07723','南归阻雪','孟浩然','quantangshi','','卷8','我行滞宛许，日夕望京豫。
旷野莽茫茫，乡山在何处。
孤烟村际起，归雁天边去。
积雪复平臯，饥鹰捉寒兔。
少年弄文墨，属意在章句。
十上耻还家，裴回守归路。','',''),('quantangshi-07724','听郑五愔弹琴','孟浩然','quantangshi','','卷8','阮籍推名饮，清风满竹林。
半酣下衫袖，拂拭龙唇琴。
一杯弹一曲，不觉夕阳沈。
予意在山水，闻之谐夙心。','',''),('quantangshi-07725','同张明府清镜叹','孟浩然','quantangshi','','卷8','妾有盘龙镜，清光常昼发。
自从生尘埃，有若雾中月。
愁来试取照，坐叹生白发。
寄语边塞人，如何久离别。','',''),('quantangshi-07726','庭橘','孟浩然','quantangshi','','卷8','明发览羣物，万木何阴森。
凝霜渐渐水，庭橘似悬金。
女伴争攀摘，摘窥碍叶深。
竝生怜共蒂，相示感同心。
骨刺红罗被，香黏翠羽簪。
擎来玉盘里，全胜在幽林。','',''),('quantangshi-07727','早梅','孟浩然','quantangshi','','卷8','园中有早梅，年例犯寒开。
少妇曾攀折，将归插镜台。
犹言看不足，更欲剪刀裁。','',''),('quantangshi-07728','清明即事','孟浩然','quantangshi','','卷8','帝里重清明，人心自愁思。
车声上路合，柳色东城翠。
花落草齐生，鸎飞蝶双戏。
空堂坐相忆，酌茗聊代醉。','',''),('quantangshi-07729','和卢明府送郑十三还京兼寄之什','孟浩然','quantangshi','','卷8','昔时风景登临地，今日衣冠送别筵。
醉坐自倾彭泽酒，思归长望白云天。
洞庭一叶惊秋早，濩落空嗟滞江岛。
寄语朝廷当世人，何时重见长安道。','',''),('quantangshi-07730','高阳池送朱二','孟浩然','quantangshi','','卷8','当昔襄阳雄盛时，山公常醉习家池。
池边钓女日相随，妆成照影竞来窥。
澄波澹澹芙蓉发，绿岸毵毵杨柳垂。
一朝物变人亦非，四面荒凉人径稀。
意气豪华何处在，空余草露湿罗衣。
此地朝来饯行者，翻向此中牧征马。
征马分飞日渐斜，见此空为人所嗟。
殷勤为访桃源路，予亦归来松子家。','',''),('quantangshi-07731','鹦鹉洲送王九之江左','孟浩然','quantangshi','','卷8','昔登江上黄鹤楼，遥爱江中鹦鹉洲。
洲势逶迤遶碧流，鸳鸯鸂鶒满滩头。
滩头日落沙碛长，金沙熠熠动飙光。
舟人牵锦缆，浣女结罗裳。
月明全见芦花白，风起遥闻杜若香，君行采采莫相忘。','',''),('quantangshi-07732','送王七尉松滋得阳台云','孟浩然','quantangshi','','卷8','君不见巫山神女作行云，霏红沓翠晓氛氲。
婵娟流入楚王梦，倏忽还随零雨分。
空中飞去复飞来，朝朝暮暮下阳台。
愁君此去为仙尉，便逐行云去不回。','',''),('quantangshi-07733','夜归鹿门山歌','孟浩然','quantangshi','','卷8','山寺钟鸣昼已昏，渔梁渡头争渡喧。
人随沙路向江村，余亦乘舟归鹿门。
鹿门月照开烟树，忽到庞公栖隐处。
岩扉松径长寂寥，惟有幽人夜来去。','',''),('quantangshi-07734','长乐宫','孟浩然','quantangshi','','卷8','秦城旧来称窈窕，汉家更衣应不少。
红粉邀君在何处，青楼苦夜长难晓。
长乐宫中钟暗来，可怜歌舞惯相催。
欢娱此事今寂寞，惟有年年陵树哀。','',''),('quantangshi-07735','示孟郊','孟浩然','quantangshi','','卷8','蔓草蔽极野，兰芝结孤根。
众音何其繁，伯牙独不喧。
当时高深意，举世无能分。
钟期一见知，山水千秋闻。
尔其保静节，薄俗徒云云。','',''),('quantangshi-07736','和张丞相春朝对雪','孟浩然','quantangshi','','卷8','迎气当春至，承恩喜雪来。
润从河汉下，花逼艳阳开。
不覩丰年瑞，焉知燮理才。
撒盐如可拟，愿糁和羹梅。','',''),('quantangshi-07737','和张明府登鹿门作','孟浩然','quantangshi','','卷8','忽示登高作，能宽旅寓情。
弦歌既多暇，山水思微清。
草得风光动，虹因雨气成。
谬承巴里和，非敢应同声。','',''),('quantangshi-07738','和张二自穰县还途中遇雪','孟浩然','quantangshi','','卷8','风吹沙海雪，渐作柳园春。
宛转随香骑，轻盈伴玉人。
歌疑郢中客，态比洛川神。
今日南归楚，双飞似入秦。','',''),('quantangshi-07739','和贾主簿弁九日登岘山','孟浩然','quantangshi','','卷8','楚万重阳日，羣公赏宴来。
共乘休沐暇，同醉菊花杯。
逸思高秋发，欢情落景催。
国人咸寡和，遥愧洛阳才。','',''),('quantangshi-07740','望洞庭湖赠张丞相','孟浩然','quantangshi','','卷8','八月湖水平，涵虚混太清。
气蒸云梦泽，波撼岳阳城。
欲济无舟楫，端居耻圣明。
坐观垂钓者，空有羡鱼情。','',''),('quantangshi-07741','赠道士参寥','孟浩然','quantangshi','','卷8','蜀琴久不弄，玉匣细尘生。
丝脆弦将断，金徽色尚荣。
知音徒自惜，聋俗本相轻。
不遇钟期听，谁知鸾凤声。','',''),('quantangshi-07742','京还赠张维','孟浩然','quantangshi','','卷8','拂衣何处去，高枕南山南。
欲徇五斗禄，其如七不堪。
早朝非晚起，束带异抽簪。
因向智者说，游鱼思旧潭。','',''),('quantangshi-07743','题李十四庄兼赠綦毋校书','孟浩然','quantangshi','','卷8','闻君息阴地，东郭柳林间。
左右瀍涧水，门庭缑氏山。
抱琴来取醉，垂钓坐乘闲。
归客莫相待，寻源殊未还。','',''),('quantangshi-07744','九日龙沙作寄刘大眘虚','孟浩然','quantangshi','','卷8','龙沙豫章北，九日挂帆过。
风俗因时见，湖山发兴多。
客中谁送酒，棹里自成歌。
歌竟乘流去，滔滔任夕波。','',''),('quantangshi-07745','寄赵正字','孟浩然','quantangshi','','卷8','正字芸香阁，幽人竹素园。
经过宛如昨，归卧寂无喧。
高鸟能择木，羚羊漫触藩。
物情今已见，从此愿忘言。','',''),('quantangshi-07746','洞庭湖寄阎九','孟浩然','quantangshi','','卷8','洞庭秋正阔，余欲泛归船。
莫辨荆吴地，唯余水共天。
渺弥江树没，合沓海潮连。
迟尔为舟楫，相将济巨川。','',''),('quantangshi-07747','秦中感秋寄远上人','孟浩然','quantangshi','','卷8','一丘常欲卧，三径苦无资。
北土非吾愿，东林怀我师。
黄金然桂尽，壮志逐年衰。
日夕凉风至，闻蝉但益悲。','',''),('quantangshi-07748','宿永嘉江寄山阴崔少府国辅','孟浩然','quantangshi','','卷8','我行穷水国，君使入京华。
相去日千里，孤帆天一涯。
卧闻海潮至，起视江月斜。','',''),('quantangshi-07749','上巳洛中寄王九迥','孟浩然','quantangshi','','卷8','卜洛成周地，浮杯上巳筵。
鬬鸡寒食下，走马射堂前。
垂柳金堤合，平沙翠幕连。
不知王逸少，何处会羣贤。','',''),('quantangshi-07750','闻裴侍御朏自襄州司户除豫州司户因以投寄','孟浩然','quantangshi','','卷8','故人荆府掾，尚有柏台威。
移职自樊衍，芳声闻帝畿。
昔余卧林巷，载酒过柴扉。
松菊无时赏，乡园欲懒归。','',''),('quantangshi-07751','江上寄山阴崔少府国辅','孟浩然','quantangshi','','卷8','春堤杨柳发，忆与故人期。
草木本无意，荣枯自有时。
山阴定远近，江上日相思。
不及兰亭会，空吟祓禊诗。','',''),('quantangshi-07752','夜泊庐江闻故人在东寺以诗寄之','孟浩然','quantangshi','','卷8','江路经庐阜，松门入虎溪。
闻君寻寂乐，清夜宿招提。
石镜山精怯，禅枝怖鸽栖。
一灯如悟道，为照客心迷。','',''),('quantangshi-07753','宿桐庐江寄广陵旧游','孟浩然','quantangshi','','卷8','山暝闻猿愁，沧江急夜流。
风鸣两岸叶，月照一孤舟。
建德非吾土，维扬忆旧游。
还将两行泪，遥寄海西头。','',''),('quantangshi-07754','南还舟中寄袁太祝','孟浩然','quantangshi','','卷8','沿溯非便习，风波厌苦辛。
忽闻迁谷鸟，来报五陵春。
岭北回征帆，巴东问故人。
桃源何处是，游子正迷津。','',''),('quantangshi-07755','东陂遇雨率尔贻谢南池','孟浩然','quantangshi','','卷8','田家春事起，丁壮就东陂。
殷殷雷声作，森森雨足垂。
海虹晴始见，河柳润初移。
予意在耕凿，因君问土宜。','',''),('quantangshi-07756','行至汝坟寄卢征君','孟浩然','quantangshi','','卷8','行乏憩予驾，依然见汝坟。
洛川方罢雪，嵩嶂有残云。
曳曳半空里，明明五色分。
聊题一时兴，因寄卢征君。','',''),('quantangshi-07757','寄天台道士','孟浩然','quantangshi','','卷8','海上求仙客，三山望几时。
焚香宿华顶，裛露采灵芝。
屡蹑莓苔滑，将寻汗漫期。
倘因松子去，长与世人辞。','',''),('quantangshi-07758','唐城馆中早发寄杨使君','孟浩然','quantangshi','','卷8','犯霜驱晓驾，数里见唐城。
旅馆归心逼，荒村客思盈。
访人留后信，策蹇赴前程。
欲识离魂断，长空听雁声。','',''),('quantangshi-07759','涧南即事贻皎上人','孟浩然','quantangshi','','卷8','弊庐在郭外，素产惟田园。
左右林野旷，不闻朝市喧。
钓竿垂北涧，樵唱入南轩。
书取幽栖事，将寻静者论。','',''),('quantangshi-07760','重酬李少府见赠','孟浩然','quantangshi','','卷8','养疾衡檐下，由来浩气真。
五行将禁火，十步任寻春。
致敬惟桑梓，邀欢即主人。
回看后雕色，青翠有松筠。','',''),('quantangshi-07761','九日怀襄阳','孟浩然','quantangshi','','卷8','去国似如昨，倏然经杪秋。
岘山不可见，风景令人愁。
谁采篱下菊，应闲池上楼。
宜城多美酒，归与葛彊游。','',''),('quantangshi-07762','初出关旅亭夜坐怀王大校书','孟浩然','quantangshi','','卷8','向夕槐烟起，葱茏池馆曛。
客中无偶坐，关外惜离羣。
烛至萤光灭，荷枯雨滴闻。
永怀芸阁友，寂寞滞[扬]云。','',''),('quantangshi-07763','人日登南阳驿门亭子怀汉川诸友','孟浩然','quantangshi','','卷8','朝来登陟处，不似艳阳时。
异县殊风物，羁怀多所思。
剪花惊岁早，看柳讶春迟。
未有南飞雁，裁书欲寄谁。','',''),('quantangshi-07764','早寒江上有怀','孟浩然','quantangshi','','卷8','木落雁南度，北风江上寒。
我家襄水上，遥隔楚云端。
乡泪客中尽，孤帆天际看。
迷津欲有问，平海夕漫漫。','',''),('quantangshi-07765','闲园怀苏子','孟浩然','quantangshi','','卷8','林园虽少事，幽独自多违。
向夕开帘坐，庭阴落景微。
鸟过烟树宿，萤傍水轩飞。
感念同怀子，京华去不归。','',''),('quantangshi-07766','同卢明府饯张郎中除义王府司马海园作','孟浩然','quantangshi','','卷8','上国山河列，贤王邸第开。
故人分职去，潘令宠行来。
冠盖趋梁苑，江湘失楚材。
豫愁轩骑动，宾客散池台。','',''),('quantangshi-07767','送张子容进士赴举','孟浩然','quantangshi','','卷8','夕曛山照灭，送客出柴门。
惆怅野中别，殷勤岐路言。
茂林予偃息，乔木尔飞翻。
无使谷风诮，须令友道存。','',''),('quantangshi-07768','送张参明经举兼向泾州觐省','孟浩然','quantangshi','','卷8','十五彩衣年，承欢慈母前。
孝廉因岁贡，怀橘向秦川。
四座推文举，中郎许仲宣。
泛舟江上别，谁不仰神仙。','',''),('quantangshi-07769','送张祥之房陵','孟浩然','quantangshi','','卷8','我家南渡头，惯习野人舟。
日夕弄清浅，林湍逆上流。
山河据形胜，天地生豪酋。
君意在利往，知音期自投。','',''),('quantangshi-07770','送吴宣从事','孟浩然','quantangshi','','卷8','才有幕中士，宁无塞上勋。
汉兵将灭虏，王粲始从军。
旌斾边庭去，山川地脉分。
平生一匕首，感激赠夫君。','',''),('quantangshi-07771','送桓子之郢城礼','孟浩然','quantangshi','','卷8','闻君驰彩骑，躞蹀指南荆。
为结潘杨好，言过鄢郢城。
摽梅诗有赠，羔雁礼将行。
今夜神仙女，应来感梦情。','',''),('quantangshi-07772','留别王侍御维','孟浩然','quantangshi','','卷8','寂寂竟何待，朝朝空自归。
欲寻芳草去，惜与故人违。
当路谁相假，知音世所稀。
秪应守索寞，还掩故园扉。','',''),('quantangshi-07773','早春润州送从弟还乡','孟浩然','quantangshi','','卷8','兄弟游吴国，庭闱恋楚关。
已多新岁感，更饯白眉还。
归泛西江水，离筵北固山。
乡园欲有赠，梅柳着先攀。','',''),('quantangshi-07774','岘山饯房琯崔宗之','孟浩然','quantangshi','','卷8','贵贱平生隔，轩车是日来。
青阳一觏止，云路豁然开。
祖道衣冠列，分亭驿骑催。
方期九日聚，还待二星回。','',''),('quantangshi-07775','送谢录事之越','孟浩然','quantangshi','','卷8','清旦江天迥，凉风西北吹。
白云向吴会，征帆亦相随。
想到耶溪日，应探禹穴奇。
仙书倘相示，予在此山陲。','',''),('quantangshi-07776','洛中送奚三还扬州','孟浩然','quantangshi','','卷8','水国无边际，舟行共使风。
羡君从此去，朝夕见乡中。
予亦离家久，南归恨不同。
音书若有问，江上会相逢。','',''),('quantangshi-07777','送告八从军','孟浩然','quantangshi','','卷8','男儿一片气，何必五车书。
好勇方过我，多才便起予。
运筹将入幕，养拙就闲居。
正待功名遂，从君继两疎。','',''),('quantangshi-07778','送元公之鄂渚寻观主张骖鸾','孟浩然','quantangshi','','卷8','桃花春水涨，之子忽乘流。
岘首辞蛟浦，江中问鹤楼。
赠君青竹杖，送尔白苹洲。
应是神仙子，相期汗漫游。','',''),('quantangshi-07779','送王五昆季省觐','孟浩然','quantangshi','','卷8','公子恋庭闱，劳歌涉海涯。
水乘舟檝去，亲望老莱归。
斜日催乌鸟，清江照彩衣。
平生急难意，遥仰鹡鸰飞。','',''),('quantangshi-07780','送崔遏','孟浩然','quantangshi','','卷8','片玉来夸楚，治中作主人。
江山增润色，词赋动阳春。
别馆当虚敞，离情任吐伸。
因声两京旧，谁念卧漳滨。','',''),('quantangshi-07781','送卢少府使入秦','孟浩然','quantangshi','','卷8','楚关望秦国，相去千里余。
州县勤王事，山河转使车。
祖筵江上列，离恨别前书。
愿及芳年赏，娇莺二月初。','',''),('quantangshi-07782','送袁十岭南寻弟','孟浩然','quantangshi','','卷8','早闻牛渚咏，今见鹡鸰心。
羽翼嗟零落，悲鸣别故林。
苍梧白云远，烟水洞庭深。
万里独飞去，南风迟尔音。','',''),('quantangshi-07783','永嘉别张子容','孟浩然','quantangshi','','卷8','旧国余归楚，新年子北征。
挂帆愁海路，分手恋朋情。
日夕故园意，汀洲春草生。','',''),('quantangshi-07784','东京留别诸公','孟浩然','quantangshi','','卷8','吾道昧所适，驱车还向东。
主人开旧馆，留客醉新丰。
树绕温泉绿，尘遮晚日红。
拂衣从此去，高步蹑华嵩。','',''),('quantangshi-07785','送袁太祝尉豫章','孟浩然','quantangshi','','卷8','何幸遇休明，观光来上京。
相逢武陵客，独送豫章行。
随牒牵黄绶，离羣会墨卿。
江南佳丽地，山水旧难名。','',''),('quantangshi-07786','都下送辛大之鄂','孟浩然','quantangshi','','卷8','南国辛居士，言归旧竹林。
未逢调鼎用，徒有济川心。
予亦忘机者，田园在汉阴。
因君故乡去，遥寄式微吟。','',''),('quantangshi-07787','送席大','孟浩然','quantangshi','','卷8','惜尔怀其宝，迷邦倦客游。
江山历全楚，河洛越成周。
道路疲千里，乡园老一丘。
知君命不偶，同病亦同忧。','',''),('quantangshi-07788','送贾升主簿之荆府','孟浩然','quantangshi','','卷8','奉使推能者，勤王不暂闲。
观风随按察，乘骑度荆关。
送别登何处，开筵旧岘山。
征轩明日远，空望郢门间。','',''),('quantangshi-07789','送王大校书','孟浩然','quantangshi','','卷8','导漾自嶓冢，东流为汉川。
维桑君有意，解缆我开筵。
云雨从兹别，林端意渺然。
尺书能不恡，时望鲤鱼传。','',''),('quantangshi-07790','游江西留别富阳裴刘二少府','孟浩然','quantangshi','','卷8','西上游江西，临流恨解携。
千山叠成嶂，万水泻为溪。
石浅流难溯，藤长险易跻。
谁怜问津者，岁晏此中迷。','',''),('quantangshi-07791','广陵别薛八','孟浩然','quantangshi','','卷8','士有不得志，栖栖吴楚间。
广陵相遇罢，彭蠡泛舟还。
樯出江中树，波连海上山。
风帆明日远，何处更追攀。','',''),('quantangshi-07792','送洗然弟进士举','孟浩然','quantangshi','','卷8','献策金门去，承欢彩服违。
以吾一日长，念尔聚星稀。
昏定须温席，寒多未授衣。
桂枝如已擢，早逐雁南飞。','',''),('quantangshi-07793','崔明府宅夜观妓','孟浩然','quantangshi','','卷8','白日既云暮，朱颜亦已酡。
画堂初点烛，金幌半垂罗。
长袖平阳曲，新声子夜歌。
从来惯留客，兹夕为谁多。','',''),('quantangshi-07794','同卢明府早秋宴张郎中海亭','孟浩然','quantangshi','','卷8','侧听弦歌宰，文书游夏徒。
故园欣赏竹，为邑幸来苏。
华省曾联事，仙舟复与俱。
欲知临泛久，荷露渐成珠。','',''),('quantangshi-07795','卢明府早秋宴张郎中海园即事得秋字','孟浩然','quantangshi','','卷8','邑有弦歌宰，翔鸾狎野鸥。
眷言华省旧，暂拂海池游。
郁岛藏深竹，前溪对舞楼。
更闻书即事，云物是清秋。','',''),('quantangshi-07796','宴荣二山池','孟浩然','quantangshi','','卷8','甲第开金穴，荣期乐自多。
枥嘶支遁马，池养右军鹅。
竹引携琴入，花邀载酒过。
山公来取醉，时唱接䍦歌。','',''),('quantangshi-07797','夏日与崔二十一同集卫明府宅','孟浩然','quantangshi','','卷8','言避一时暑，池亭五月开。
喜逢金马客，同饮玉人杯。
舞鹤乘轩至，游鱼拥钓来。
座中殊未起，箫管莫相催。','',''),('quantangshi-07798','清明日宴梅道士房','孟浩然','quantangshi','','卷8','林卧愁春尽，开轩览物华。
忽逢青鸟使，邀入赤松家。
丹竈初开火，仙桃正落花。
童颜若可驻，何惜醉流霞。','',''),('quantangshi-07799','寒夜张明府宅宴','孟浩然','quantangshi','','卷8','瑞雪初盈尺，寒宵始半更。
列筵邀酒伴，刻烛限诗成。
香炭金炉暖，娇弦玉指清。
醉来方欲卧，不觉晓鸡鸣。','',''),('quantangshi-07800','宴张别驾新斋','孟浩然','quantangshi','','卷8','世业传圭组，江城佐股肱。
高斋征学问，虚薄滥先登。
讲论陪诸子，文章得旧朋。
士元多赏激，衰病恨无能。','',''),('quantangshi-07801','与诸子登岘山','孟浩然','quantangshi','','卷8','人事有代谢，往来成古今。
江山留胜迹，我辈复登临。
水落鱼梁浅，天寒梦泽深。
羊公碑字在，读罢泪沾襟。','',''),('quantangshi-07802','与杭州薛司户登樟亭楼作','孟浩然','quantangshi','','卷8','水楼一登眺，半出青林高。
帟幕英僚敞，芳筵下客叨。
山藏伯禹穴，城压伍胥涛。
今日观溟涨，垂纶学钓鳌。','',''),('quantangshi-07803','寻天台山','孟浩然','quantangshi','','卷8','吾友太乙子，餐霞卧赤城。
欲寻华顶去，不惮恶溪名。
歇马凭云宿，扬帆截海行。
高高翠微里，遥见石梁横。','',''),('quantangshi-07804','同曹三御史行泛湖归越','孟浩然','quantangshi','','卷8','秋入诗人意，巴歌和者稀。
泛湖同逸旅，吟会是思归。
白简徒推荐，沧洲已拂衣。
杳冥云外去，谁不羡鸿飞。','',''),('quantangshi-07805','晚泊浔阳望庐山','孟浩然','quantangshi','','卷8','挂席几千里，名山都未逢。
泊舟浔阳郭，始见香炉峰。
尝读远公传，永怀尘外踪。
东林精舍近，日暮但闻钟。','',''),('quantangshi-07806','陪张丞相登嵩阳楼','孟浩然','quantangshi','','卷8','独步人何在，嵩阳有故楼。
岁寒问耆旧，行县拥诸候。
林莽北弥望，沮漳东会流。
客中遇知己，无复越乡忧。','',''),('quantangshi-07807','武陵泛舟','孟浩然','quantangshi','','卷8','武陵川路狭，前棹入花林。
莫测幽源里，仙家信几深。
水回青嶂合，云度绿溪阴。
坐听闲猿啸，弥清尘外心。','',''),('quantangshi-07808','与颜钱塘登障楼望潮作','孟浩然','quantangshi','','卷8','百里闻雷震，鸣弦暂辍弹。
府中连骑出，江上待潮观。
照日秋云廻，浮天渤澥宽。
惊涛来似雪，一坐凛生寒。','',''),('quantangshi-07809','姚开府山池','孟浩然','quantangshi','','卷8','主人新邸第，相国旧池台。
馆是招贤辟，楼因教舞开。
轩车人已散，箫管凤初来。
今日龙门下，谁知文举才。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-07810','夏日浮舟过陈大水亭','孟浩然','quantangshi','','卷8','水亭凉气多，闲棹晚来过。
涧影见松竹，潭香闻芰荷。
野童扶醉舞，山鸟助酣歌。
幽赏未云徧，烟光奈夕何。','',''),('quantangshi-07811','与白明府游江','孟浩然','quantangshi','','卷8','故人来自远，邑宰复初临。
执手恨为别，同舟无异心。
沿洄洲渚趣，演漾弦歌音。
谁识躬耕者，年年梁甫吟。','',''),('quantangshi-07812','游凤林寺西岭','孟浩然','quantangshi','','卷8','共喜年华好，来游水石间。
烟容开远树，春色满幽山。
壶酒朋情洽，琴歌野兴闲。
莫愁归路暝，招月伴人还。','',''),('quantangshi-07813','秋日陪李侍御渡松滋江','孟浩然','quantangshi','','卷8','南纪西江阔，皇华御史雄。
截流宁假楫，挂席自生风。
僚宷争攀鷁，鱼龙亦避骢。
坐听白[雪]唱，翻入棹歌中。','',''),('quantangshi-07814','陪独孤使君同与萧员外证登万山亭','孟浩然','quantangshi','','卷8','万山青嶂曲，千骑使君游。
神女鸣环佩，仙郎接献酬。
遍观云梦野，自爱江城楼。
何必东南守，空传沈隐侯。','',''),('quantangshi-07815','秋登张明府海亭','孟浩然','quantangshi','','卷8','海亭秋日望，委曲见江山。
染翰聊题壁，倾壶一解颜。
歌逢彭泽令，归赏故园间。
予亦将琴史，栖迟共取闲。','',''),('quantangshi-07816','临涣裴明府席遇张十一房六','孟浩然','quantangshi','','卷8','河县柳林边，河桥晚泊船。
文叨才子会，官喜故人连。
笑语同今夕，轻肥异往年。
晨风理归棹，吴楚各依然。','',''),('quantangshi-07817','梅道士水亭','孟浩然','quantangshi','','卷8','傲吏非凡吏，名流即道流。
隐居不可见，高论莫能酬。
水接仙源近，山藏鬼谷幽。
再来迷处所，花下问渔舟。','',''),('quantangshi-07818','游景空寺兰若','孟浩然','quantangshi','','卷8','龙象经行处，山腰度石关。
屡迷青嶂合，时爱绿萝闲。
宴息花林下，高谈竹屿间。
寥寥隔尘事，疑是入鸡山。','',''),('quantangshi-07819','陪李侍御访聪上人禅居','孟浩然','quantangshi','','卷8','欣逢柏台友，共谒聪公禅。
石室无人到，绳牀见虎眠。
阴崖常抱雪，枯涧为生泉。
出处虽云异，同欢在法筵。','',''),('quantangshi-07820','游精思观回王白云在后','孟浩然','quantangshi','','卷8','出谷未停午，到家日已曛。
回瞻下山路，但见牛羊羣。
樵子暗相失，草虫寒不闻。
衡门犹未掩，伫立望夫君。','',''),('quantangshi-07821','夏日辨玉法师茅斋','孟浩然','quantangshi','','卷8','夏日茅斋里，无风坐亦凉。
竹林深笋穊，藤架引梢长。
燕觅巢窠处，蜂来造蜜房。
物华皆可翫，花橤四时芳。','',''),('quantangshi-07822','与张折冲游耆闍寺','孟浩然','quantangshi','','卷8','释子弥天秀，将军武库才。
横行塞北尽，独步汉南来。
贝叶传金口，山楼作赋开。
因君振嘉藻，江楚气雄哉。','',''),('quantangshi-07823','游精思题观主山房','孟浩然','quantangshi','','卷8','误入桃源里，初怜竹迳深。
方知仙子宅，未有世人寻。
舞鹤过闲砌，飞猿啸密林。
渐通玄妙理，深得坐忘心。','',''),('quantangshi-07824','宿立公房','孟浩然','quantangshi','','卷8','支遁初求道，深公笑买山。
何如石岩趣，自入户庭间。
苔润春泉满，萝轩夜月闲。
能令许玄度，吟卧不知还。','',''),('quantangshi-07825','寻陈逸人故居','孟浩然','quantangshi','','卷8','人事一朝尽，荒芜三径休。
始闻漳浦卧，奄作岱宗游。
池水犹含墨，风云已落秋。
今宵泉壑里，何处觅藏舟。','',''),('quantangshi-07826','寻梅道士','孟浩然','quantangshi','','卷8','彭泽先生柳，山阴道士鹅。
我来从所好，停策汉阴多。
重以观鱼乐，因之鼓枻歌。
崔徐迹未朽，千载揖清波。','',''),('quantangshi-07827','陪姚使君题惠上人房','孟浩然','quantangshi','','卷8','带雪梅初暖，含烟柳尚青。
来窥童子偈，得听法王经。
会理知无我，观空厌有形。
迷心应觉悟，客思未遑宁。','',''),('quantangshi-07828','晚春题远上人南亭','孟浩然','quantangshi','','卷8','给园支遁隐，虚寂养身和。
春晚羣木秀，间关黄鸟歌。
林栖居士竹，池养右军鹅。
炎月北窗下，清风期再过。','',''),('quantangshi-07829','题大禹寺义公禅房','孟浩然','quantangshi','','卷8','义公习禅处，结构依空林。
户外一峰秀，阶前羣壑深。
夕阳连雨足，空翠落庭阴。
看取莲花净，应知不染心。','',''),('quantangshi-07830','寻白鹤岩张子容隐居','孟浩然','quantangshi','','卷8','白鹤青岩半，幽人有隐居。
阶庭空水石，林壑罢樵渔。
岁月青松老，风霜苦竹疎。
覩兹怀旧业，回策返吾庐。','',''),('quantangshi-07831','题融公兰若','孟浩然','quantangshi','','卷8','精舍买金开，流泉遶砌回。
芰荷薰讲席，松柏映香台。
法雨晴飞去，天花昼下来。
谈玄殊未已，归骑夕阳催。','',''),('quantangshi-07832','过景空寺故融公兰若','孟浩然','quantangshi','','卷8','池上青莲宇，林间白马泉。
故人成异物，过客独潸然。
既礼新松塔，还寻旧石筵。
平生竹如意，犹挂草堂前。','',''),('quantangshi-07833','题张野人园庐','孟浩然','quantangshi','','卷8','与君园庐竝，微尚颇亦同。
耕钓方自逸，壶觞趣不空。
门无俗士驾，人有上皇风。
何处先贤传，惟称庞德公。','',''),('quantangshi-07834','李少府与杨九再来','孟浩然','quantangshi','','卷8','弱岁早登龙，今来喜再逢。
如何春月柳，犹忆岁寒松。
烟火临寒食，笙歌达曙钟。
喧喧鬬鸡道，行乐羡朋从。','',''),('quantangshi-07835','寻张五回夜园作','孟浩然','quantangshi','','卷8','闻就庞公隐，移居近洞湖。
兴来林是竹，归卧谷名愚。
挂席樵风便，开轩琴月孤。
岁寒何用赏，霜落故园芜。','',''),('quantangshi-07836','裴司士员司户见寻','孟浩然','quantangshi','','卷8','府僚能枉驾，家酝复新开。
落日池上酌，清风松下来。
厨人具鸡黍，稚子摘杨梅。
谁道山公醉，犹能骑马回。','',''),('quantangshi-07837','春中喜王九相寻','孟浩然','quantangshi','','卷8','二月湖水清，家家春鸟鸣。
林花扫更落，径草踏还生。
酒伴来相命，开尊共解酲。
当杯已入手，歌妓莫停声。','',''),('quantangshi-07838','李氏园林卧疾','孟浩然','quantangshi','','卷8','我爱陶家趣，园林无俗情。
春雷百卉坼，寒食四邻清。
伏枕嗟公干，归山羡子平。
年年白社客，空滞洛阳城。','',''),('quantangshi-07839','过故人庄','孟浩然','quantangshi','','卷8','故人具鸡黍，邀我至田家。
绿树村边合，青山郭外斜。
开筵面场圃，把酒话桑麻。
待到重阳日，还来就菊花。','',''),('quantangshi-07840','张七及辛大见寻南亭醉作','孟浩然','quantangshi','','卷8','山公能饮酒，居士好弹筝。
世外交初得，林中契已并。
纳凉风飒至，逃暑日将倾。
便就南亭里，余尊惜解酲。','',''),('quantangshi-07841','岁暮归南山','孟浩然','quantangshi','','卷8','北阙休上书，南山归敝庐。
不才明主弃，多病故人疎。
白发催年老，青阳逼岁除。
永怀愁不寐，松月夜窗虚。','',''),('quantangshi-07842','南山下与老圃期种瓜','孟浩然','quantangshi','','卷8','樵牧南山近，林闾北郭赊。
先人留素业，老圃作邻家。
不种千株橘，惟资五色瓜。
邵平能就我，开径剪蓬麻。','',''),('quantangshi-07843','溯江至武昌','孟浩然','quantangshi','','卷8','家本洞湖上，岁时归思催。
客心徒欲速，江路苦邅回。
残冻因风解，新正度腊开。
行看武昌柳，仿髴映楼台。','',''),('quantangshi-07844','舟中晓望','孟浩然','quantangshi','','卷8','挂席东南望，青山水国遥。
舳舻争利涉，来往接风潮。
问我今何去，天台访石桥。
坐看霞色晓，疑是赤城标。','',''),('quantangshi-07845','自洛之越','孟浩然','quantangshi','','卷8','皇皇三十载，书劒两无成。
山水寻吴越，风尘厌洛京。
扁舟泛湖海，长揖谢公卿。
且乐杯中物，谁论世上名。','',''),('quantangshi-07846','途中遇晴','孟浩然','quantangshi','','卷8','已失巴陵雨，犹逢蜀坂泥。
天开斜景遍，山出晚云低。
余湿犹霑草，残流尚入溪。
今宵有明月，乡思远凄凄。','',''),('quantangshi-07847','归至郢中','孟浩然','quantangshi','','卷8','远游经海峤，返棹归山阿。
日夕见乔木，乡关在伐柯。
愁随江路尽，喜入郢门多。
左右看桑土，依然即匪他。','',''),('quantangshi-07848','夕次蔡阳馆','孟浩然','quantangshi','','卷8','日暮马行疾，城荒人住稀。
听歌知近楚，投馆忽如归。
鲁堰田畴广，章陵气色微。
明朝拜嘉庆，须着老莱衣。','',''),('quantangshi-07849','他乡七夕','孟浩然','quantangshi','','卷8','他乡逢七夕，旅馆益羇愁。
不见穿针妇，空怀故国楼。
绪风初减热，新月始临秋。
谁忍窥河汉，迢迢问斗牛。','',''),('quantangshi-07850','夜泊牛渚趁薛八船不及','孟浩然','quantangshi','','卷8','星罗牛渚夕，风退鷁舟迟。
浦溆尝同宿，烟波忽间之。
榜歌空里失，船火望中疑。
明发泛潮海，茫茫何处期。','',''),('quantangshi-07851','晓入南山','孟浩然','quantangshi','','卷8','瘴气晓氛氲，南山复水云。
鲲飞今始见，鸟堕旧来闻。
地接长沙近，江从汨渚分。
贾生曾吊屈，予亦痛斯文。','',''),('quantangshi-07852','夜渡湘水','孟浩然','quantangshi','','卷8','客舟贪利涉，暗里渡湘川。
露气闻芳杜，歌声识采莲。
榜人投岸火，渔子宿潭烟。
行侣时相问，浔阳何处边。','',''),('quantangshi-07853','赴京途中遇雪','孟浩然','quantangshi','','卷8','迢递秦京道，苍茫藏暮天。
穷阴连晦朔，积雪满山川。
落雁迷沙渚，饥乌集野田。
客愁空伫立，不见有人烟。','',''),('quantangshi-07854','途次望乡','孟浩然','quantangshi','','卷8','客行愁落日，乡思重相催。
况在他山外，天寒夕鸟来。
雪深迷郢路，云暗失阳台。
可叹凄惶子，高歌谁为媒。','',''),('quantangshi-07855','永嘉上浦馆逢张八子容','孟浩然','quantangshi','','卷8','逆旅相逢处，江村日暮时。
众山遥对酒，孤屿共题诗。
廨宇邻蛟室，人烟接岛夷。
乡园万余里，失路一相悲。','',''),('quantangshi-07856','宿武阳即事','孟浩然','quantangshi','','卷8','川暗夕阳尽，孤舟泊岸初。
岭猿相呌啸，潭嶂似空虚。
就枕灭明烛，扣舷闻夜渔。
鸡鸣问何处，人物是秦余。','',''),('quantangshi-07857','渡扬子江','孟浩然','quantangshi','','卷8','桂檝中流望，京江两畔明。
林开扬子驿，山出润州城。
海尽边阴静，江寒朔吹生。
更闻枫叶下，淅沥度秋声。','',''),('quantangshi-07858','田家元日','孟浩然','quantangshi','','卷8','昨夜斗回北，今朝岁起东。
我年已强仕，无禄尚忧农。
桑野就耕父，荷锄随牧童。
田家占气候，共说此年丰。','',''),('quantangshi-07859','九日得新字','孟浩然','quantangshi','','卷8','初九未成旬，重阳即此晨。
登高闻古事，载酒访幽人。
落帽恣欢饮，授衣同试新。
茱萸正可佩，折取寄情亲。','',''),('quantangshi-07860','除夜乐城逢张少府','孟浩然','quantangshi','','卷8','云海泛瓯闽，风潮泊岛滨。
何知岁除夜，得见故乡亲。
余是乘槎客，君为失路人。
平生复能几，一别十余春。','',''),('quantangshi-07861','岁除夜会乐城张少府宅','孟浩然','quantangshi','','卷8','畴昔通家好，相知无间然。
续明催画烛，守岁接长筵。
旧曲梅花唱，新正柏酒传。
客行随处乐，不见度年年。','',''),('quantangshi-07862','寒夜','孟浩然','quantangshi','','卷8','闺夕绮窗闭，佳人罢缝衣。
理琴开宝匣，就枕卧重帏。
夜久灯花落，薰笼香气微。
锦衾重自暖，遮莫晓霜飞。','',''),('quantangshi-07863','赋得盈盈楼上女','孟浩然','quantangshi','','卷8','夫壻久离别，青楼空望归。
妆成卷帘坐，愁思嬾缝衣。
燕子家家入，杨花处处飞。
空牀难独守，谁为报金徽。','',''),('quantangshi-07864','春意','孟浩然','quantangshi','','卷8','佳人能画眉，妆罢出帘帷。
照水空自爱，折花将遗谁。
春情多艳逸，春意倍相思。
愁心极杨柳，一种乱如丝。','',''),('quantangshi-07865','闺情','孟浩然','quantangshi','','卷8','一别隔炎凉，君衣忘短长。
裁缝无处等，以意忖情量。
畏瘦疑伤窄，防寒更厚装。
半啼封裹了，知欲寄谁将。','',''),('quantangshi-07866','美人分香','孟浩然','quantangshi','','卷8','艳色本倾城，分香更有情。
髻鬟垂欲解，眉黛拂能轻。
舞学平阳态，歌翻子夜声。
春风狭斜道，含笑待逢迎。','',''),('quantangshi-07867','伤岘山云表观主','孟浩然','quantangshi','','卷8','少小学书劒，秦吴多岁年。
归来一登眺，陵谷尚依然。
岂意餐霞客，溘随朝露先。
因之问闾里，把臂几人全。','',''),('quantangshi-07868','题梧州陈司马山斋','孟浩然','quantangshi','','卷8','南国无霜霰，连年对物华。
青林暗换叶，红橤亦开花。
春去无山鸟，秋来见海槎。
流芳虽可悦，会自泣长沙。','',''),('quantangshi-07869','岁除夜有怀','孟浩然','quantangshi','','卷8','迢递三巴路，羁危万里身。
乱山残雪夜，孤灯异乡人。
渐与骨肉远，转于奴仆亲。
那堪正飘泊，来日岁华新。','',''),('quantangshi-07870','登安阳城楼','孟浩然','quantangshi','','卷8','县城南面汉江流，江涨开成南雍州。
才子乘春来骋望，羣公暇日坐销忧。
楼台晚映青山郭，罗绮晴骄绿水洲。
向夕波摇明月动，更疑神女弄珠游。','',''),('quantangshi-07871','登万岁楼','孟浩然','quantangshi','','卷8','万岁楼头望故乡，独令乡思更茫茫。
天寒雁度堪垂泪，日落猿啼欲断肠。
曲引古堤临冻浦，斜分远岸近枯杨。
今朝偶见同袍友，却喜家书寄八行。','',''),('quantangshi-07872','除夜有怀','孟浩然','quantangshi','','卷8','五更钟漏欲相催，四气推迁往复回。
帐里残灯才去熖，炉中香气尽成灰。
渐看春逼芙蓉枕，顿觉寒销竹叶杯。
守岁家家应未卧，相思那得梦魂来。','',''),('quantangshi-07873','春情','孟浩然','quantangshi','','卷8','青楼晓日珠帘映，红粉春妆宝镜催。
已厌交欢怜枕席，相将游戏绕池台。
坐时衣带萦纤草，行即裙裾扫落梅。
更道明朝不当作，相期共鬬管弦来。','',''),('quantangshi-07874','长安早春','孟浩然','quantangshi','','卷8','关戍惟东井，城池起北辰。
咸歌太平日，共乐建寅春。
雪尽青山树，冰开黑水滨。
草迎金埒马，花伴玉楼人。
鸿渐看无数，莺歌听欲频。
何当遂荣擢，归及柳条新。','',''),('quantangshi-07875','荆门上张丞相','孟浩然','quantangshi','','卷8','共理分荆国，招贤愧不材。
召南风更阐，丞相阁还开。
觏止欣眉睫，沈沦拔草莱。
坐登徐孺榻，频接李膺杯。
始慰蝉鸣柳，俄看雪间梅。
四时年龠尽，千里客程催。
日下瞻归翼，沙边厌曝鳃。
伫闻宣室召，星象列三台。','',''),('quantangshi-07876','陪张丞相登荆城楼因寄蓟州张使君及浪泊戍主刘家','孟浩然','quantangshi','','卷8','蓟门天北畔，铜柱日南端。
出守声弥远，投荒法未宽。
侧身聊倚望，携手莫同欢。
白璧无瑕玷，青松有岁寒。
府中丞相阁，江上使君滩。
兴尽回舟去，方知行路难。','',''),('quantangshi-07877','陪张丞相祠紫盖山途经玉泉寺','孟浩然','quantangshi','','卷8','望秩宣王命，斋心待漏行。
青衿列胄子，从事有参卿。
五马寻归路，双林指化城。
闻钟度门近，照胆玉泉清。
皂盖依松憩，缁徒拥锡迎。
天宫上兜率，沙界豁迷明。
欲就终焉志，恭闻智者名。
人随逝水没，波逐覆舟倾。
想像若在眼，周流空复情。
谢公还欲卧，谁与济苍生。','',''),('quantangshi-07878','陪张丞相自松滋江东泊渚宫','孟浩然','quantangshi','','卷8','放溜下松滋，登舟命檝师。
讵忘经济日，不惮冱寒时。
洗帻岂独古，濯缨良在兹。
政成人自理，机息鸟无疑。
云物凝孤屿，江山辨四维。
晚来风稍急，冬至日行迟。
腊响惊云梦，渔歌激楚辞。
渚宫何处是，川暝欲安之。','',''),('quantangshi-07879','和张判官登万山亭因赠洪府都督韩公','孟浩然','quantangshi','','卷8','韩公是襄士，日赏城西岑。
结构意不浅，岩潭趣转深。
皇华一动咏，荆国几谣吟。
旧径兰勿剪，新堤柳欲阴。
砌傍余怪石，沙上有闲禽。
自牧豫章郡，空瞻枫树林。
因声寄流水，善听在知音。
耆旧眇不接，崔徐无处寻。
物情多贵远，贤俊岂无今。
迟尔长江暮，澄清一洗心。','',''),('quantangshi-07880','和宋太史北楼新亭','孟浩然','quantangshi','','卷8','返耕意未遂，日夕登城隅。
谁道山林近，坐为符竹拘。
丽谯非改作，轩槛是新图。
远水自嶓冢，长云吞具区。
愿随江燕贺，羞逐府僚趋。
欲识狂歌者，丘园一竖儒。','',''),('quantangshi-07881','赠萧少府','孟浩然','quantangshi','','卷8','上德如流水，安仁道若山。
闻君秉高节，而得奉清颜。
鸿渐升仪羽，牛刀列下班。
处腴能不润，居剧体常闲。
去诈人无谄，除邪吏息奸。
欲知清与洁，明月照澄湾。','',''),('quantangshi-07882','秦中苦雨思归赠袁左丞贺侍郎','孟浩然','quantangshi','','卷8','苦学三十载，闭门江汉阴。
用贤遭圣日，羇旅属秋霖。
岂直昏垫苦，亦为权势沈。
二毛催白发，百镒罄黄金。
泪忆岘山堕，愁怀湘水深。
谢公积愤懑，庄舃空谣吟。
跃马非吾事，狎鸥宜我心。
寄言当路者，去矣北山岑。','',''),('quantangshi-07883','同张明府碧溪赠答','孟浩然','quantangshi','','卷8','别业闻新制，同声和者多。
还看碧溪答，不羡绿珠歌。
自有阳台女，朝朝拾翠过。
绮筵铺锦绣，妆牖闭藤萝。
秩满休闲日，春余景气和。
仙凫能作伴，罗袜共凌波。
曲岛寻花药，回潭折芰荷。
更怜斜日照，红粉艳青娥。','',''),('quantangshi-07884','久滞越中贻谢南池会稽贺少府','孟浩然','quantangshi','','卷8','陈平无产业，尼父倦东西。
负郭昔云翳，问津今亦迷。
未能忘魏阙，空此滞秦稽。
两见夏云起，再闻春鸟啼。
怀仙梅福市，访旧若耶溪。
圣主贤为宝，君何隐遯栖。','',''),('quantangshi-07885','送韩使君除洪州都曹','孟浩然','quantangshi','','卷8','述职抚荆衡，分符袭宠荣。
往来看拥传，前后赖专城。
勿翦棠犹在，波澄水更清。
重推江汉理，旋改豫章行。
召父多遗爱，羊公有令名。
衣冠列祖道，耆旧拥前旌。
岘首晨风送，江陵夜火迎。
无才慙孺子，千里愧同声。','',''),('quantangshi-07886','送莫甥兼诸昆弟从韩司马入西军','孟浩然','quantangshi','','卷8','念尔习诗礼，未曾违户庭。
平生早偏露，万里更飘零。
坐弃三牲养，行观八阵形。
饰装辞故里，谋策赴边庭。
壮志吞鸿鹄，遥心伴鹡鸰。
所从文且武，不战自应宁。','',''),('quantangshi-07887','岘山送萧员外之荆州','孟浩然','quantangshi','','卷8','岘山江岸曲，郢水郭门前。
自古登临处，非今独黯然。
亭楼明落照，井邑秀通川。
涧竹生幽兴，林风入管弦。
再飞鹏激水，一举鹤冲天。
伫立三荆使，看君驷马旋。','',''),('quantangshi-07888','送王昌龄之岭南','孟浩然','quantangshi','','卷8','洞庭去远近，枫叶早惊秋。
岘首羊公爱，长沙贾谊愁。
土毛无缟紵，乡味有槎头。
已抱沈痼疾，更贻魑魅忧。
数年同笔砚，兹夕间衾裯。
意气今何在，相思望斗牛。','',''),('quantangshi-07889','岘山送张去非游巴东','孟浩然','quantangshi','','卷8','岘山南郭外，送别每登临。
沙岸江村近，松门山寺深。
一言予有赠，三峡尔将寻。
祖席宜城酒，征途云梦林。
蹉跎游子意，眷恋故人心。
去矣勿淹滞，巴东猿夜吟。','',''),('quantangshi-07890','奉先张明府休沐还乡海亭宴集','孟浩然','quantangshi','','卷8','自君理畿甸，予亦经江淮。
万里书信断，数年云雨乖。
归来休澣日，始得赏心谐。
朱绂恩虽重，沧州趣每怀。
树低新舞阁，山对旧书斋。
何以发秋兴，阴虫鸣夜堦。','',''),('quantangshi-07891','宴张记室宅','孟浩然','quantangshi','','卷8','甲第金张馆，门庭车骑多。
家封汉阳郡，文会楚材过。
曲岛浮觞酌，前山入咏歌。
妓堂花映发，书阁柳逶迤。
玉指调筝柱，金泥饰舞罗。
宁知书劒者，岁月独蹉跎。','',''),('quantangshi-07892','宴崔明府宅夜观妓','孟浩然','quantangshi','','卷8','画堂观妙妓，长夜正留宾。
烛吐莲花艳，妆成桃李春。
髻鬟低舞席，衫袖掩歌唇。
汗湿偏宜粉，罗轻讵着身。
调移筝柱促，欢会酒杯频。
倘使曹王见，应嫌洛浦神。','',''),('quantangshi-07893','卢明府九日岘山宴袁使君张郎中崔员外','孟浩然','quantangshi','','卷8','宇宙谁开辟，江山此郁盘。
登临今古用，风俗岁时观。
地理荆州分，天涯楚塞宽。
百城今刺史，华省旧郎官。
共美重阳节，俱怀落帽欢。
酒邀彭泽载，琴辍武城弹。
献寿先浮菊，寻幽或藉兰。
烟虹铺藻翰，松竹挂衣冠。
叔子神如在，山公兴未阑。
传闻骑马醉，还向习池看。','',''),('quantangshi-07894','登龙兴寺阁','孟浩然','quantangshi','','卷8','阁道乘空出，披轩远目开。
逶迤见江势，客至屡缘回。
兹郡何填委，遥山复几哉。
苍苍皆草木，处处尽楼台。
骤雨一阳散，行舟四海来。
鸟归余兴远，周览更裴回。','',''),('quantangshi-07895','登总持寺浮图','孟浩然','quantangshi','','卷8','半空跻宝塔，晴望尽京华。
竹遶渭川遍，山连上苑斜。
四门开帝宅，阡陌俯人家。
累劫从初地，为童忆聚沙。
一窥功德见，弥益道心加。
坐觉诸天近，空香送落花。','',''),('quantangshi-07896','与崔二十一游镜湖寄包贺二公','孟浩然','quantangshi','','卷8','试览镜湖物，中流到底清。
不知鲈鱼味，但识鸥鸟情。
帆得樵风送，春逢谷雨晴。
将探夏禹穴，稍背越王城。
府掾有包子，文章推贺生。
沧浪醉后唱，因此寄同声。','',''),('quantangshi-07897','夜登孔伯昭南楼时沈太清朱升在座','孟浩然','quantangshi','','卷8','谁家无风月，此地有琴尊。
山水会稽郡，诗书孔氏门。
再来值秋杪，高阁夜无喧。
华烛罢然蜡，清弦方奏鵾。
沈生隐侯胤，朱子买臣孙。
好我意不浅，登兹共话言。','',''),('quantangshi-07898','陪卢明府泛舟回作','孟浩然','quantangshi','','卷8','百里行春返，清流逸兴多。
鷁舟随雁泊，江火共星罗。
已救田家旱，仍医俗化讹。
文章推后辈，风雅激颓波。
高岸迷陵谷，新声满棹歌。
犹怜不才子，白首未登科。','',''),('quantangshi-07899','腊月八日于剡县石城寺礼拜','孟浩然','quantangshi','','卷8','石壁开金像，香山倚铁围。
下生弥勒见，回向一心归。
竹柏禅庭古，楼台世界稀。
夕岚增气色，余照发光辉。
讲席邀谈柄，泉堂施浴衣。
愿承功德水，从此濯尘机。','',''),('quantangshi-07900','同独孤使君东斋作','孟浩然','quantangshi','','卷8','郎官旧华省，天子命分忧。
襄土岁频旱，随车雨再流。
云阴自南楚，河润及东周。
廨宇宜新霁，田家贺有秋。
竹间残照入，池上夕阳浮。
寄谢东阳守，何如八咏楼。','',''),('quantangshi-07901','同王九题就师山房','孟浩然','quantangshi','','卷8','晚憩支公室，故人逢右军。
轩窗避炎暑，翰墨动新文。
竹蔽檐前日，雨随堦下云。
周游清荫徧，吟卧夕阳曛。
江静棹歌歇，溪深樵语闻。
归途未忍去，携手恋清芬。','',''),('quantangshi-07902','冬至后过吴张二子檀溪别业','孟浩然','quantangshi','','卷8','卜筑因自然，檀溪不更穿。
园庐二友接，水竹数家连。
直与南山对，非关选地偏。
草堂时偃曝，兰枻日周旋。
外事情都远，中流性所便。
闲垂太公钓，兴发子猷船。
余亦幽栖者，经过窃慕焉。
梅花残腊月，柳色半春天。
鸟泊随阳雁，鱼藏缩项鳊。
停杯问山简，何似习池边。','',''),('quantangshi-07903','韩大使东斋会岳上人诸学士','孟浩然','quantangshi','','卷8','郡守虚陈榻，林间召楚材。
山川祈雨毕，云物喜晴开。
抗礼尊缝掖，临流揖渡杯。
徒攀朱仲李，谁荐和羹梅。
翰墨缘情制，高深以意裁。
沧洲趣不远，何必问蓬莱。','',''),('quantangshi-07904','上巳日涧南园期王山人陈七诸公不至','孟浩然','quantangshi','','卷8','摇艇候明发，花源弄晚春。
在山怀绮季，临汉忆荀陈。
上巳期三月，浮杯兴十旬。
坐歌空有待，行乐恨无邻。
日晚兰亭北，烟开曲水滨。
浴蚕逢姹女，采艾值幽人。
石壁堪题序，沙场好解绅。
羣公望不至，虚掷此芳晨。','',''),('quantangshi-07905','齿坐呈山南诸隐','孟浩然','quantangshi','','卷8','习公有遗坐，高在白云陲。
樵子不见识，山僧赏自知。
以余为好事，携手一来窥。
竹露闲夜滴，松风清昼吹。
从来抱微尚，况复感前规。
于此无奇策，苍生奚以为。','',''),('quantangshi-07906','来闍黎新亭作','孟浩然','quantangshi','','卷8','八解禅林秀，三明给苑才。
地偏香界远，心净水亭开。
傍险山查立，寻幽石迳回。
瑞花长自下，灵药岂须栽。
碧网交红树，清泉尽绿苔。
戏鱼闻法聚，闲鸟诵经来。
弃象玄应悟，忘言理必该。
静中何所得，吟咏也徒哉。','',''),('quantangshi-07907','西山寻辛谔','孟浩然','quantangshi','','卷8','漾舟寻水便，因访故人居。
落日清川里，谁言独羡鱼。
石潭窥洞彻，沙岸历纡徐。
竹屿见垂钓，茅斋闻读书。
款言忘景夕，清兴属凉初。
回也一瓢饮，贤哉常晏如。','',''),('quantangshi-07908','题长安主人壁','孟浩然','quantangshi','','卷8','久废南山田，叨陪东阁贤。
欲随平子去，犹未献甘泉。
枕籍琴书满，褰帷远岫连。
我来如昨日，庭树忽鸣蝉。
促织惊寒女，秋风感长年。
授衣当九月，无褐竟谁怜。','',''),('quantangshi-07909','行出东山望汉川','孟浩然','quantangshi','','卷8','异县非吾土，连山尽绿篁。
平田出郭少，盘坂入云长。
万壑归于汉，千峰划彼苍。
猿声乱楚峡，人语带巴乡。
石上攒椒树，藤间缀蜜房。
雪余春未暖，岚解昼初阳。
征马疲登顿，归帆爱渺茫。
坐欣沿溜下，信宿见维桑。','',''),('quantangshi-07910','夜泊宣城界','孟浩然','quantangshi','','卷8','西塞沿江岛，南陵问驿楼。
湖平津济阔，风止客帆收。
去去怀前浦，茫茫泛夕流。
石逢罗刹碍，山泊敬亭幽。
火识梅根冶，烟迷杨叶洲。
离家复水宿，相伴赖沙鸥。','',''),('quantangshi-07911','下灨石','孟浩然','quantangshi','','卷8','灨石三百里，沿洄千嶂间。
沸声常活活，洊势亦潺潺。
跳沫鱼龙沸，垂藤猿狖攀。
榜人苦奔峭，而我忘险难。
放溜情弥惬，登舻目自闲。
暝帆何处宿，遥指落星湾。','',''),('quantangshi-07912','初年乐城馆中卧疾怀归作','孟浩然','quantangshi','','卷8','异县天隅僻，孤帆海畔过。
往来乡信断，留滞客情多。
腊月闻雷震，东风感岁和。
蛰虫惊户穴，巢鹊眄庭柯。
徒对芳尊酒，其如伏枕何。
归屿理舟楫，江海正无波。','',''),('quantangshi-07913','醉后赠马四','孟浩然','quantangshi','','卷8','四海重然诺，吾尝闻白眉。
秦城游侠客，相得半酣时。','',''),('quantangshi-07914','赠王九','孟浩然','quantangshi','','卷8','日暮田家远，山中勿久淹。
归人须早去，稚子望陶潜。','',''),('quantangshi-07915','登岘山亭寄晋陵张少府','孟浩然','quantangshi','','卷8','岘首风湍急，云帆若鸟飞。
凭轩试一问，张翰欲来归。','',''),('quantangshi-07916','送朱大入秦','孟浩然','quantangshi','','卷8','游人武陵去，宝劒直千金。
分手脱相赠，平生一片心。','',''),('quantangshi-07917','送友人之京','孟浩然','quantangshi','','卷8','君登青云去，予望青山归。
云山从此别，泪湿薜萝衣。','',''),('quantangshi-07918','送张郎中迁京','孟浩然','quantangshi','','卷8','碧溪常共赏，朱邸忽迁荣。
豫有相思意，闻君琴上声。','',''),('quantangshi-07919','同张将蓟门观灯','孟浩然','quantangshi','','卷8','异俗非乡俗，新年改故年。
蓟门看火树，疑是烛龙然。','',''),('quantangshi-07920','张郎中梅园中','孟浩然','quantangshi','','卷8','绮席铺兰杜，珠盘折芰荷。
故园留不住，应是恋弦歌。','',''),('quantangshi-07921','北涧泛舟','孟浩然','quantangshi','','卷8','北涧流恒满，浮舟触处通。
沿洄自有趣，何必五湖中。','',''),('quantangshi-07922','春晓','孟浩然','quantangshi','','卷8','春眠不觉晓，处处闻啼鸟。
夜来风雨声，花落知多少。','',''),('quantangshi-07923','洛中访袁拾遗不遇','孟浩然','quantangshi','','卷8','洛阳访才子，江岭作流人。
闻说梅花早，何如北地春。','',''),('quantangshi-07924','寻菊花潭主人不遇','孟浩然','quantangshi','','卷8','行至菊花潭，村西日已斜。
主人登高去，鸡犬空在家。','',''),('quantangshi-07925','檀溪寻故人','孟浩然','quantangshi','','卷8','花伴成龙竹，池分跃马溪。
田园人不见，疑向洞中栖。','',''),('quantangshi-07926','扬子津望京口','孟浩然','quantangshi','','卷8','北固临京口，夷山近海滨。
江风白浪起，愁杀渡头人。','',''),('quantangshi-07927','同储十二洛阳道中作','孟浩然','quantangshi','','卷8','珠弹繁华子，金羁游侠人。
酒酣白日暮，走马入红尘。','',''),('quantangshi-07928','初下浙江舟中口号','孟浩然','quantangshi','','卷8','八月观潮罢，三江越海浔。
回瞻魏阙路，空复子牟心。','',''),('quantangshi-07929','宿建德江','孟浩然','quantangshi','','卷8','移舟泊烟渚，日暮客愁新。
野旷天低树，江清月近人。','',''),('quantangshi-07930','问舟子','孟浩然','quantangshi','','卷8','向夕问舟子，前程复几多。
湾头正堪泊，淮里足风波。','',''),('quantangshi-07931','戏题','孟浩然','quantangshi','','卷8','客醉眠未起，主人呼解酲。
已言鸡黍熟，复道瓮头清。','',''),('quantangshi-07932','凉州词 一','孟浩然','quantangshi','','卷8','浑成紫檀金屑文，作得琵琶声入云。
胡地迢迢三万里，那堪马上送明君。','',''),('quantangshi-07933','凉州词 二','孟浩然','quantangshi','','卷8','异方之乐令人悲，羌笛胡笳不用吹。
坐看今夜关山月，思杀边城游侠儿。','',''),('quantangshi-07934','送新安张少府归秦中','孟浩然','quantangshi','','卷8','试登秦岭望秦川，遥忆青门春可怜。
仲月送君从此去，瓜时须及邵平田。','',''),('quantangshi-07935','送杜十四之江南','孟浩然','quantangshi','','卷8','荆吴相接水为乡，君去春江正淼茫。
日暮征帆何处泊，天涯一望断人肠。','',''),('quantangshi-07936','渡浙江问舟中人','孟浩然','quantangshi','','卷8','潮落江平未有风，扁舟共济与君同。
时时引领望天末，何处青山是越中。','',''),('quantangshi-07937','初秋','孟浩然','quantangshi','','卷8','不觉初秋夜渐长，清风习习重凄凉。
炎炎暑退茅斋静，堦下丛莎有露光。','',''),('quantangshi-07938','过融上人兰若','孟浩然','quantangshi','','卷8','山头禅室挂僧衣，窗外无人水鸟飞。
黄昏半在下山路，却听泉声恋翠微。','',''),('quantangshi-07939','句','孟浩然','quantangshi','','卷8','微云淡河汉，疎雨滴梧桐。
逐逐怀良驭，萧萧顾乐鸣。','',''),('quantangshi-07940','古风 一','李白','quantangshi','','卷8','大雅久不作，吾衰竟谁陈。
王风委蔓草，战国多荆榛。
龙虎相啖食，兵戈逮狂秦。
正声何微茫，哀怨起骚人。
扬马激颓波，开流荡无垠。
废兴虽万变，宪章亦已沦。
自从建安来，绮丽不足珍。
圣代复元古，垂衣贵清真。
羣才属休明，乘运共跃鳞。
文质相炳焕，众星罗秋旻。
我志在删述，垂辉暎千春。
希圣如有立，绝笔于获麟。','',''),('quantangshi-07941','古风 二','李白','quantangshi','','卷8','蟾蜍薄太清，蚀此瑶台月。
圆光亏中天，金魄遂沦没。
螮蝀入紫微，大明夷朝晖。
浮云隔两曜，万象昏阴霏。
萧萧长门宫，昔是今已非。
桂蠹花不实，天霜下严威。
沈叹终永夕，感我涕沾衣。','',''),('quantangshi-07942','古风 三','李白','quantangshi','','卷8','秦皇扫六合，虎视何雄哉。
飞劒决浮云，诸侯尽西来。
明断自天启，大略驾羣才。
收兵铸金人，函谷正东开。
铭功会稽岭，骋望琅琊台。
刑徒七十万，起土骊山隈。
尚采不死药，茫然使心哀。
连弩射海鱼，长鲸正崔嵬。
额鼻象五岳，扬波喷云雷。
鬐鬣蔽青天，何由覩蓬莱。
徐[巿]载秦女，楼船几时迥。
但见三泉下，金棺葬寒灰。','',''),('quantangshi-07943','古风 四','李白','quantangshi','','卷8','凤飞九千仞，五章备彩珍。
衔书且虚归，空入周与秦。
横绝历四海，所居未得邻。
吾营紫河车，千载落风尘。
药物秘海岳，采铅青溪滨。
时登大楼山，举手望仙真。
羽驾灭去影，飙车绝廻轮。
尚恐丹液迟，志愿不及申。
徒霜镜中发，羞彼鹤上人。
桃李何处开，此花非我春。
唯应清都境，长与韩众亲。','',''),('quantangshi-07944','古风 五','李白','quantangshi','','卷8','太白何苍苍，星辰上森列。
去天三百里，邈尔与世绝。
中有绿发翁，披云卧松雪。
不笑亦不语，冥栖在岩穴。
我来逢真人，长跪问宝诀。
粲然启玉齿，授以炼药说。
铭骨传其语，竦身已电灭。
仰望不可及，苍然五情热。
吾将营丹砂，永与世人别。','',''),('quantangshi-07945','古风 六','李白','quantangshi','','卷8','代马不思越，越禽不恋燕。
情性有所习，土风固其然。
昔别雁门关，今戍龙庭前。
惊沙乱海日，飞雪迷胡天。
虮虱生虎鹖，心魂逐旌旃。
苦战功不赏，忠诚难可宣。
谁怜李飞将，白首没三边。','',''),('quantangshi-07946','古风 七','李白','quantangshi','','卷8','五鹤西北来，飞飞凌太清。
仙人绿云上，自道安期名。
两两白玉童，双吹紫鸾笙。
去影忽不见，回风送天声。
我欲一问之，飘然若流星。
愿餐金光草，寿与天齐倾。','',''),('quantangshi-07947','古风 八','李白','quantangshi','','卷8','咸阳二三月，宫柳黄金枝。
绿帻谁家子，卖珠轻薄儿。
日暮醉酒归，白马骄且驰。
意气人所仰，冶游方及时。
子云不晓事，晚献长杨辞。
赋达身已老，草玄鬓若丝。
投阁良可叹，但为此辈嗤。','',''),('quantangshi-07948','古风 九','李白','quantangshi','','卷8','庄周梦胡蝶，胡蝶为庄周。
一体更变易，万事良悠悠。
乃知蓬莱水，复作清浅流。
青门种瓜人，旧日东陵侯。
富贵故如此，营营何所求。','',''),('quantangshi-07949','古风 十','李白','quantangshi','','卷8','齐有倜傥生，鲁连特高妙。
明月出海底，一朝开光曜。
却秦振英声，后世仰末照。
意轻千金赠，愿向平原笑。
吾亦澹荡人，拂衣可同调。','',''),('quantangshi-07950','古风 十一','李白','quantangshi','','卷8','黄河走东溟，白日落西海。
逝川与流光，飘忽不相待。
春容舍我去，秋发已衰改。
人生非寒松，年貌岂长在。
吾当乘云螭，吸景驻光彩。','',''),('quantangshi-07951','古风 十二','李白','quantangshi','','卷8','松柏本孤直，难为桃李颜。
昭昭严子陵，垂钓沧波间。
身将客星隐，心与浮云闲。
长揖万乘君，还归富春山。
清风洒六合，邈然不可攀。
使我长叹息，冥栖岩石间。','',''),('quantangshi-07952','古风 十三','李白','quantangshi','','卷8','君平既弃世，世亦弃君平。
观变穷太易，探元化羣生。
寂寞缀道论，空帘闭幽情。
驺虞不虚来，鸑鷟有时鸣。
安知天汉上，白日悬高名。
海客去已久，谁人测沈冥。','',''),('quantangshi-07953','古风 十四','李白','quantangshi','','卷8','胡关饶风沙，萧索竟终古。
木落秋草黄，登高望戎虏。
荒城空大漠，边邑无遗堵。
白骨横千霜，嵯峨蔽榛莽。
借问谁凌虐，天骄毒威武。
赫怒我圣皇，劳师事鼙鼓。
阳和变杀气，发卒骚中土。
三十六万人，哀哀泪如雨。
且悲就行役，安得营农圃。
不见征戍儿，岂知关山苦。
李牧今不在，边人饲豺虎。','',''),('quantangshi-07954','古风 十五','李白','quantangshi','','卷8','燕昭延郭隗，遂筑黄金台。
剧辛方赵至，邹衍复齐来。
奈何青云士，弃我如尘埃。
珠玉买歌笑，糟糠养贤才。
方知黄鹤举，千里独裴回。','',''),('quantangshi-07955','古风 十六','李白','quantangshi','','卷8','宝劒双蛟龙，雪花照芙蓉。
精光射天地，雷腾不可冲。
一去别金匣，飞沈失相从。
风胡灭已久，所以潜其锋。
吴水深万丈，楚山邈千重。
雌雄终不隔，神物会当逢。','',''),('quantangshi-07956','古风 十七','李白','quantangshi','','卷8','金华牧羊儿，乃是紫烟客。
我愿从之游，未去发已白。
不知繁华子，扰扰何所迫。
昆山采琼蘂，可以炼精魄。','',''),('quantangshi-07957','古风 十八','李白','quantangshi','','卷8','天津三月时，千门桃与李。
朝为断肠花，暮逐东流水。
前水复后水，古今相续流。
新人非旧人，年年桥上游。
鸡鸣海色动，谒帝罗公侯。
月落西上阳，余辉半城楼。
衣冠照云日，朝下散皇州。
鞍马如飞龙，黄金络马头。
行人皆辟易，志气横嵩丘。
入门上高堂，列鼎错珍羞。
香风引赵舞，清管随齐讴。
七十紫鸳鸯，双双戏庭幽。
行乐争昼夜，自言度千秋。
功成身不退，自古多愆尤。
黄犬空叹息，绿珠成衅讐。
何如鸱夷子，散发棹扁舟。','',''),('quantangshi-07958','古风 十九','李白','quantangshi','','卷8','西岳莲花山，迢迢见明星。
素手把芙蓉，虚步蹑太清。
霓裳曳广带，飘拂升天行。
邀我登云台，高揖卫叔卿。
恍恍与之去，驾鸿凌紫冥。
俯视洛阳川，茫茫走胡兵。
流血涂野草，豺狼尽冠缨。','',''),('quantangshi-07959','古风 二十','李白','quantangshi','','卷8','昔我游齐都，登华不注峯。
兹山何峻秀，绿翠如芙蓉。
萧飒古仙人，了知是赤松。
借予一白鹿，自挟两青龙。
含笑凌倒景，欣然愿相从。
泣与亲友别，欲语再三咽。
勖君青松心，努力保霜雪。
世路多险艰，白日欺红颜。
分手各千里，去去何时还。
在世复几时，倏如飘风度。
空闻紫金经，白首愁相误。
抚己忽自笑，沈吟为谁故。
名利徒煎熬，安得闲余步。
终留赤玉舄，东上蓬莱路。
秦帝如我求，苍苍但烟雾。','',''),('quantangshi-07960','古风 二十一','李白','quantangshi','','卷8','郢客吟白雪，遗响飞青天。
徒劳歌此曲，举世谁为传。
试为巴人唱，和者乃数千。
吞声何足道，叹息空凄然。','',''),('quantangshi-07961','古风 二十二','李白','quantangshi','','卷8','秦水别陇首，幽咽多悲声。
胡马顾朔雪，躞蹀长嘶鸣。
感物动我心，缅然含归情。
昔视秋蛾飞，今见春蚕生。
袅袅桑柘叶，萋萋柳垂荣。
急节谢流水，羁心摇悬旌。
挥涕且复去，恻怆何时平。','',''),('quantangshi-07962','古风 二十三','李白','quantangshi','','卷8','秋露白如玉，团团下庭绿。
我行忽见之，寒早悲岁促。
人生鸟过目，胡乃自结束。
景公一何愚，牛山泪相续。
物苦不知足，得陇又望蜀。
人心若波澜，世路有屈曲。
三万六千日，夜夜当秉烛。','',''),('quantangshi-07963','古风 二十四','李白','quantangshi','','卷8','大车扬飞尘，亭午暗阡陌。
中贵多黄金，连云开甲宅。
路逢鬬鸡者，冠盖何辉赫。
鼻息干虹霓，行人皆怵惕。
世无洗耳翁，谁知尧与跖。','',''),('quantangshi-07964','古风 二十五','李白','quantangshi','','卷8','世道日交丧，浇风散淳源。
不采芳桂枝，反栖恶木根。
所以桃李树，吐花竟不言。
大运有兴没，羣动争飞奔。
归来广成子，去入无穷门。','',''),('quantangshi-07965','古风 二十六','李白','quantangshi','','卷8','碧荷生幽泉，朝日艳且鲜。
秋花冒绿水，密叶罗青烟。
秀色空绝世，馨香竟谁传。
坐看飞霜满，凋此红芳年。
结根未得所，愿托华池边。','',''),('quantangshi-07966','古风 二十七','李白','quantangshi','','卷8','燕赵有秀色，绮楼青云端。
眉目艳皎月，一笑倾城欢。
常恐碧草晚，坐泣秋风寒。
纤手怨玉琴，清晨起长叹。
焉得偶君子，共乘双飞鸾。','',''),('quantangshi-07967','古风 二十八','李白','quantangshi','','卷8','容颜若飞电，时景如飘风。
草绿霜已白，日西月复东。
华鬓不耐秋，飒然成衰蓬。
古来贤圣人，一一谁成功。
君子变猿鹤，小人为沙虫。
不及广成子，乘云驾轻鸿。','',''),('quantangshi-07968','古风 二十九','李白','quantangshi','','卷8','三季分战国，七雄成乱麻。
王风何怨怒，世道终纷拏。
至人洞玄象，高举凌紫霞。
仲尼欲浮海，吾祖之流沙。
圣贤共沦没，临岐胡咄嗟。','',''),('quantangshi-07969','古风 三十','李白','quantangshi','','卷8','玄风变太古，道丧无时还。
扰扰季叶人，鸡鸣趋四关。
但识金马门，谁知蓬莱山。
白首死罗绮，笑歌无时闲。
绿酒哂丹液，青娥凋素颜。
大儒挥金椎，琢之诗礼间。
苍苍三株树，冥目焉能攀。','',''),('quantangshi-07970','古风 三十一','李白','quantangshi','','卷8','郑客西入关，行行未能已。
白马华山君，相逢平原里。
璧遗镐池君，明年祖龙死。
秦人相谓曰，吾属可去矣。
一往桃花源，千春隔流水。','',''),('quantangshi-07971','古风 三十二','李白','quantangshi','','卷8','蓐收肃金气，西陆弦海月。
秋蝉号阶轩，感物忧不歇。
良辰竟何许，大运有沦忽。
天寒悲风生，夜久众星没。
恻恻不忍言，哀歌逮明发。','',''),('quantangshi-07972','古风 三十三','李白','quantangshi','','卷8','北溟有巨鱼，身长数千里。
仰喷三山雪，横吞百川水。
凭陵随海运，燀赫因风起。
吾观摩天飞，九万方未已。','',''),('quantangshi-07973','古风 三十四','李白','quantangshi','','卷8','羽檄如流星，虎符合专城。
喧呼救边急，羣鸟皆夜鸣。
白日曜紫微，三公运权衡。
天地皆得一，澹然四海清。
借问此何为，答言楚征兵。
渡泸及五月，将赴云南征。
怯卒非战士，炎方难远行。
长号别严亲，日月惨光晶。
泣尽继以血，心摧两无声。
困兽当猛虎，穷鱼饵奔鲸。
千去不一回，投躯岂全生。
如何舞干戚，一使有苗平。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-07974','古风 三十五','李白','quantangshi','','卷8','丑女来效颦，还家惊四隣。
寿陵失本步，笑杀邯郸人。
一曲斐然子，雕虫丧天真。
棘刺造沐猴，三年费精神。
功成无所用，楚楚且华身。
大雅思文王，颂声久崩沦。
安得郢中质，一挥成斧斤。','',''),('quantangshi-07975','古风 三十六','李白','quantangshi','','卷8','抱玉入楚国，见疑古所闻。
良宝终见弃，徒劳三献君。
直木忌先伐，芳兰哀自焚。
盈满天所损，沈冥道为羣。
东海沈碧水，西关乘紫云。
鲁连及柱史，可以蹑清芬。','',''),('quantangshi-07976','古风 三十七','李白','quantangshi','','卷8','燕臣昔恸哭，五月飞秋霜。
庶女号苍天，震风击齐堂。
精诚有所感，造化为悲伤。
而我竟何辜，远身金殿傍。
浮云蔽紫闼，白日难回光。
羣沙秽明珠，众草凌孤芳。
古来共叹息，流泪空霑裳。','',''),('quantangshi-07977','古风 三十八','李白','quantangshi','','卷8','孤兰生幽园，众草共芜没。
虽照阳春晖，复悲高秋月。
飞霜早淅沥，绿艳恐休歇。
若无清风吹，香气为谁发。','',''),('quantangshi-07978','古风 三十九','李白','quantangshi','','卷8','登高望四海，天地何漫漫。
霜被羣物秋，风飘大荒寒。
荣华东流水，万事皆波澜。
白日掩徂辉，浮云无定端。
梧桐巢燕雀，枳棘栖鸳鸾。
且复归去来，劒歌行路难。','',''),('quantangshi-07979','古风 四十','李白','quantangshi','','卷8','凤饥不啄粟，所食唯琅玕。
焉能与羣鸡，刺蹙争一餐。
朝鸣昆丘树，夕饮砥柱湍。
归飞海路远，独宿天霜寒。
幸遇王子晋，结交青云端。
怀恩未得报，感别空长叹。','',''),('quantangshi-07980','古风 四十一','李白','quantangshi','','卷8','朝弄紫沂海，夕披丹霞裳。
挥手折若木，拂此西日光。
云卧游八极，玉颜已千霜。
飘飘入无倪，稽首祈上皇。
呼我游太素，玉杯赐琼浆。
一餐历万岁，何用还故乡。
永随长风去，天外恣飘扬。','',''),('quantangshi-07981','古风 四十二','李白','quantangshi','','卷8','摇裔双白鸥，鸣飞沧江流。
宜与海人狎，岂伊云鹤俦。
寄形宿沙月，沿芳戏春洲。
吾亦洗心者，忘机从尔游。','',''),('quantangshi-07982','古风 四十三','李白','quantangshi','','卷8','周穆八荒意，汉皇万乘尊。
淫乐心不极，雄豪安足论。
西海宴王母，北宫邀上元。
瑶水闻遗歌，玉杯竟空言。
灵迹成蔓草，徒悲千载魂。','',''),('quantangshi-07983','古风 四十四','李白','quantangshi','','卷8','绿萝纷葳蕤，缭绕松栢枝。
草木有所托，岁寒尚不移。
奈何夭桃色，坐叹葑菲诗。
玉颜艳红彩，云发非素丝。
君子恩已毕，贱妾将何为。','',''),('quantangshi-07984','古风 四十五','李白','quantangshi','','卷8','八荒驰惊飙，万物尽凋落。
浮云蔽颓阳，洪波振大壑。
龙凤脱罔罟，飘颻将安托。
去去乘白驹，空山咏场藿。','',''),('quantangshi-07985','古风 四十六','李白','quantangshi','','卷8','一百四十年，国容何赫然。
隐隐五凤楼，峨峨横三川。
王侯象星月，宾客如云烟。
鬬鸡金宫里，蹴鞠瑶台边。
举动摇白日，指挥回青天。
当涂何翕忽，失路长弃捐。
独有扬执戟，闭关草太玄。','',''),('quantangshi-07986','古风 四十七','李白','quantangshi','','卷8','桃花开东园，含笑夸白日。
偶蒙东风荣，生此艳阳质。
岂无佳人色，但恐花不实。
宛转龙火飞，零落早相失。
讵知南山松，独立自萧飋。','',''),('quantangshi-07987','古风 四十八','李白','quantangshi','','卷8','秦皇按宝劒，赫怒震威神。
逐日巡海右，驱石驾沧津。
征卒空九宇，作桥伤万人。
但求蓬岛药，岂思农鳸春。
力尽功不赡，千载为悲辛。','',''),('quantangshi-07988','古风 四十九','李白','quantangshi','','卷8','美人出南国，灼灼芙蓉姿。
皓齿终不发，芳心空自持。
由来紫宫女，共妬青蛾眉。
归去潇湘沚，沈吟何足悲。','',''),('quantangshi-07989','古风 五十','李白','quantangshi','','卷8','宋国梧台东，野人得燕石。
夸作天下珍，却哂赵王璧。
赵璧无缁磷，燕石非贞真。
流俗多错误，岂知玉与珉。','',''),('quantangshi-07990','古风 五十一','李白','quantangshi','','卷8','殷后乱天纪，楚怀亦已昏。
夷羊满中野，菉葹盈高门。
比干谏而死，屈平窜湘源。
虎口何婉娈，女嬃空婵媛。
彭咸久沦没，此意与谁论。','',''),('quantangshi-07991','古风 五十二','李白','quantangshi','','卷8','青春流惊湍，朱明骤回薄。
不忍看秋蓬，飘扬竟何托。
光风灭兰蕙，白露洒葵藿。
美人不我期，草木日零落。','',''),('quantangshi-07992','古风 五十三','李白','quantangshi','','卷8','战国何纷纷，兵戈乱浮云。
赵倚两虎鬬，晋为六卿分。
奸臣欲窃位，树党自相羣。
果然田成子，一旦杀齐君。','',''),('quantangshi-07993','古风 五十四','李白','quantangshi','','卷8','倚劒登高台，悠悠送春目。
苍榛蔽层丘，琼草隐深谷。
凤鸟鸣西海，欲集无珍木。
鸒斯得所居，蒿下盈万族。
晋风日已颓，穷途方恸哭。','',''),('quantangshi-07994','古风 五十五','李白','quantangshi','','卷8','齐瑟弹东吟，秦弦弄西音。
慷慨动颜魄，使人成荒淫。
彼美佞邪子，婉娈来相寻。
一笑双白璧，再歌千黄金。
珍色不贵道，讵惜飞光沈。
安识紫霞客，瑶台鸣素琴。','',''),('quantangshi-07995','古风 五十六','李白','quantangshi','','卷8','越客采明珠，提携出南隅。
清辉照海月，美价倾皇都。
献君君按劒，怀宝空长吁。
鱼目复相哂，寸心增烦纡。','',''),('quantangshi-07996','古风 五十七','李白','quantangshi','','卷8','羽族禀万化，小大各有依。
周周亦何辜，六翮掩不挥。
愿衔众禽翼，一向黄河飞。
飞者莫我顾，叹息将安归。','',''),('quantangshi-07997','古风 五十八','李白','quantangshi','','卷8','我到巫山渚，寻古登阳台。
天空彩云灭，地远清风来。
神女去已久，襄王安在哉。
荒淫竟沦替，樵牧徒悲哀。','',''),('quantangshi-07998','古风 五十九','李白','quantangshi','','卷8','恻恻泣路岐，哀哀悲素丝。
路岐有南北，素丝易变移。
万事固如此，人生无定期。
田窦相倾夺，宾客互盈亏。
世途多飜覆，交道方嶮巇。
斗酒强然诺，寸心终自疑。
张陈竟火灭，萧朱亦星离。
众鸟集荣柯，穷鱼守枯池。
嗟嗟失权客，勤问何所规。','',''),('quantangshi-07999','远别离','李白','quantangshi','','卷8','远别离，古有皇英之二女，乃在洞庭之南，潇湘之浦。
海水直下万里深，谁人不言此离苦。
日惨惨兮云冥冥，猩猩啼烟兮鬼啸雨。
我纵言之将何补，皇穹窃恐不照余之忠诚。
云凭凭兮欲吼怒，尧舜当之亦禅禹。
君失臣兮龙为鱼，权归臣兮鼠变虎。
或言尧幽囚，舜野死。
九疑联绵皆相似，重瞳孤坟竟何是。
帝子泣兮绿云间，随风波兮去无还。
恸哭兮远望，见苍梧之深山。
苍梧山崩湘水绝，竹上之泪乃可灭。','',''),('quantangshi-08000','公无渡河','李白','quantangshi','','卷8','黄河西来决昆仑，咆哮万里触龙门。
波滔天，尧咨嗟，大禹理百川，儿啼不窥家。
杀湍烟洪水，九州始蚕麻。
其害乃去，茫然风沙。
被发之叟狂而痴，清晨临流欲奚为。
旁人不惜妻止之，公无渡河苦渡之。
虎可搏，河难凭，公果溺死流海湄。
有长鲸白齿若雪山，公乎公乎挂罥于其间，箜篌所悲竟不还。','',''),('quantangshi-08001','蜀道难','李白','quantangshi','','卷8','噫吁戏！危乎高哉！蜀道之难难于上青天！蚕丛及鱼凫，开国何茫然。
尔来四万八千岁，不与秦塞通人烟。
西当太白有鸟道，可以横绝峨眉巅。
地崩山摧壮士死，然后天梯石栈相钩连。
上有六龙回日之高标，下有冲波逆折之回川。
黄鹤之飞尚不得过，猨猱欲度愁攀援。
青泥何盘盘，百步九折萦岩峦。
扪参历井仰胁息，以手抚膺坐长叹。
问君西游何时还？畏途巉岩不可攀。
但见悲鸟号古木，雄飞雌从绕林间。
又闻子规啼夜月，愁空山，蜀道之难难于上青天，使人听此凋朱颜。
连峯去天不盈尺，枯松倒挂倚绝壁。
飞湍瀑流争喧豗，砅厓转石万壑雷。
其险也如此，嗟尔远道之人胡为乎来哉！劒阁峥嵘而崔嵬，一夫当关，万夫莫开。
所守或匪亲，化为狼与豺。
朝避猛虎，夕避长蛇。
磨牙吮血，杀人如麻。
锦城虽云乐，不如早还家。
蜀道之难难于上青天，侧身西望长咨嗟。','',''),('quantangshi-08002','梁甫吟','李白','quantangshi','','卷8','长啸梁甫吟，何时见阳春。
君不见朝歌屠叟辞棘津，八十西来钓渭滨。
宁羞白发照清水，逢时吐气思经纶。
广张三千六百钓，风期暗与文王亲。
大贤虎变愚不测，当年颇似寻常人。
君不见高阳酒徒起草中，长揖山东隆准公。
入门不拜骋雄辩，两女辍洗来趋风。
东下齐城七十二，指挥楚汉如旋蓬。
狂客落魄尚如此，何况壮士当羣雄。
我欲攀龙见明主，雷公砰訇震天鼓。
帝傍投壶多玉女，三时大笑开电光。
倏烁晦冥起风雨，阊阖九门不可通。
以额扣关阍者怒，白日不照吾精诚。
杞国无事忧天倾，䝟貐磨牙竞人肉。
驺虞不折生草茎，手接飞猱搏雕虎。
侧足焦原未言苦，智者可卷愚者豪。
世人见我轻鸿毛，力排南山三壮士，齐相杀之费二桃。
吴楚弄兵无剧孟，亚夫咍尔为徒劳。
梁甫吟，梁甫吟，声正悲。
张公两龙劒，神物合有时。
风云感会起屠钓，大人𡸣屼当安之。','',''),('quantangshi-08003','乌夜啼','李白','quantangshi','','卷8','黄云城边乌欲栖，归飞哑哑枝上啼。
机中织锦秦川女，碧纱如烟隔窗语。
停梭怅然忆远人，独宿孤房泪如雨。','',''),('quantangshi-08004','乌栖曲','李白','quantangshi','','卷8','姑苏台上乌栖时，吴王宫里醉西施。
吴歌楚舞欢未毕，青山欲衔半边日。','',''),('quantangshi-08005','战城南','李白','quantangshi','','卷8','去年战桑干源，今年战葱河道。
洗兵条支海上波，放马天山雪中草。
万里长征战，三军尽衰老。
匈奴以杀戮为耕作，古来唯见白骨黄沙田。
秦家筑城避胡处，汉家还有烽火然。
烽火然不息，征战无已时。
野战格鬬死，败马号鸣向天悲。
乌鸢啄人肠，衔飞上挂枯树枝。
士卒涂草莽，将军空尔为。
乃知兵者是凶器，圣人不得已而用之。','',''),('quantangshi-08006','将进酒','李白','quantangshi','','卷8','君不见黄河之水天上来，奔流到海不复回。
君不见高堂明镜悲白发，朝如青丝暮成雪。
人生得意须尽欢，莫使金樽空对月。
天生我材必有用，千金散尽还复来。
烹羊宰牛且为乐，会须一饮三百杯。
岑夫子，丹丘生，将进酒，君莫停。
与君歌一曲，请君为我侧耳听。
钟鼓馔玉不足贵，但愿长醉不愿醒。
古来圣贤皆寂寞，惟有饮者留其名。
陈王昔时宴平乐，斗酒十千恣讙谑。
主人何为言少钱，径须沽取对君酌。
五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。','',''),('quantangshi-08007','行行游且猎篇','李白','quantangshi','','卷8','边城儿，生年不读一字书，但将游猎夸轻趫。
胡马秋肥宜白草，骑来蹑影何矜骄。
金鞭拂雪挥鸣鞘，半酣呼鹰出远郊。
弓弯满月不虚发，双鸧迸落连飞髇。
海边观者皆辟易，猛气英风振沙碛。
儒生不及游侠人，白首下帷复何益。','',''),('quantangshi-08008','飞龙引二首 一','李白','quantangshi','','卷9','黄帝铸鼎于荆山，炼丹砂。
丹砂成黄金，骑龙飞上太清家。
云愁海思令人嗟，宫中彩女颜如花。
飘然挥手凌紫霞，从风纵体登鸾车。
登鸾车，侍轩辕。
遨游青天中，其乐不可言。','',''),('quantangshi-08009','飞龙引二首 二','李白','quantangshi','','卷9','鼎湖流水清且闲，轩辕去时有弓劒。
古人传道留其间，后宫婵娟多花颜。
乘鸾飞烟亦不还，骑龙攀天造天关。
造天关，闻天语，长云河车载玉女。
载玉女，过紫皇，紫皇乃赐白兔所捣之药方，后天而老雕三光。
下视瑶池见王母，蛾眉萧飒如秋霜。','',''),('quantangshi-08010','天马歌','李白','quantangshi','','卷9','天马来出月支窟，背为虎文龙翼骨。
嘶青云，振绿发，兰筋权奇走灭没。
腾昆仑，历西极，四足无一蹶。
鸡鸣刷燕晡秣越，神行电迈蹑慌惚。
天马呼，飞龙趋，目明长庚臆双凫。
尾如流星首渴乌，口喷红光汗沟朱。
曾陪时龙蹑天衢，羁金络月照皇都。
逸气棱棱淩九区，白璧如山谁敢沽。
回头笑紫燕，但觉尔辈愚。
天马奔，恋君轩，駷跃惊矫浮云飜。
万里足踯躅，遥瞻阊阖门。
不逢寒风子，谁采逸景孙。
白云在青天，丘陵远崔嵬。
盐车上峻坂，倒行逆施畏日晚。
伯乐翦拂中道遗，少尽其力老弃之。
愿逢田子方，恻然为我悲。
虽有玉山禾，不能疗苦饥。
严霜五月凋桂枝，伏枥衔冤摧两眉。
请君赎献穆天子，犹堪弄影舞瑶池。','',''),('quantangshi-08011','行路难三首 一','李白','quantangshi','','卷9','金樽清酒斗十千，玉盘珍羞直万钱。
停杯投筯不能食，拔劒四顾心茫然。
欲渡黄河冰塞川，将登太行雪满山。
闲来垂钓碧溪上，忽复乘舟梦日边。
行路难，行路难，多岐路，今安在。
长风破浪会有时，直挂云帆济沧海。','',''),('quantangshi-08012','行路难三首 二','李白','quantangshi','','卷9','大道如青天，我独不得出。
羞逐长安社中儿，赤鸡白狗赌梨栗。
弹劒作歌奏苦声，曳裾王门不称情。
淮阴市井笑韩信，汉朝公卿忌贾生。
君不见昔时燕家重郭隗，拥彗折节无嫌猜。
剧辛乐毅感恩分，输肝剖胆效英才。
昭王白骨萦烂草，谁人更扫黄金台。
行路难，归去来。','',''),('quantangshi-08013','行路难三首 三','李白','quantangshi','','卷9','有耳莫洗颍川水，有口莫食首阳蕨。
含光混世贵无名，何用孤高比云月。
吾观自古贤达人，功成不退皆殒身。
子胥既弃吴江上，屈原终投湘水滨。
陆机雄才岂自保，李斯税驾苦不早。
华亭鹤唳讵可闻，上蔡苍鹰何足道。
君不见吴中张翰称达生，秋风忽忆江东行。
且乐生前一杯酒，何须身后千载名。','',''),('quantangshi-08014','长相思','李白','quantangshi','','卷9','长相思，在长安，络纬秋啼金井阑。
微霜凄凄簟色寒，孤灯不明思欲绝。
卷帷望月空长叹，美人如花隔云端。
上有青冥之长天，下有渌水之波澜。
天长路远魂飞苦，梦魂不到关山难。
长相思，摧心肝。','',''),('quantangshi-08015','上留田行','李白','quantangshi','','卷9','行至上留田，孤坟何峥嵘。
积此万古恨，春草不复生。
悲风四边来，肠断白杨声。
借问谁家地，埋没蒿里茔。
古老向余言，言是上留田。
蓬科马鬣今已平，昔之弟死兄不葬，他人于此举铭旌。
一鸟死，百鸟鸣，一兽走，百兽惊。
桓山之禽别离苦，欲去回翔不能征。
田氏仓卒骨肉分，青天白日摧紫荆。
交柯之木本同形，东枝顦顇西枝荣。
无心之物尚如此，参商胡乃寻天兵。
孤竹延陵，让国扬名。
高风缅邈，颓波激清。
尺布之谣，塞耳不能听。','',''),('quantangshi-08016','春日行','李白','quantangshi','','卷9','深宫高楼入紫清，金作蛟龙盘绣楹。
佳人当窗弄白日，弦将手语弹鸣筝。
春风吹落君王耳，此曲乃是升天行。
因出天池泛蓬瀛，楼船蹙沓波浪惊。
三千双蛾献歌笑，挝钟考鼓宫殿倾。
万姓聚舞歌太平，我无为，人自宁。
三十六帝欲相迎，仙人飘翩下云軿。
帝不去，留镐京。
安能为轩辕，独往入窅冥。
小臣拜献南山寿，陛下万古垂鸿名。','',''),('quantangshi-08017','前有一樽酒行二首 一','李白','quantangshi','','卷9','春风东来忽相过，金樽渌酒生微波。
落花纷纷稍觉多，美人欲醉朱颜酡。
青轩桃李能几何，流光欺人忽蹉砣。
君起舞，日西夕，当年意气不肯平，白发如丝叹何益。','',''),('quantangshi-08018','前有一樽酒行二首 二','李白','quantangshi','','卷9','琴奏龙门之绿桐，玉壶美酒清若空。
催弦拂柱与君饮，看朱成碧颜始红。
胡姬貌如花，当垆笑春风。
笑春风，舞罗衣，君今不醉将安归。','',''),('quantangshi-08019','夜坐吟','李白','quantangshi','','卷9','冬夜夜寒觉夜长，沈吟久坐坐北堂。
冰合井泉月入闺，金缸青凝照悲啼。
金缸灭，啼转多。
掩妾泪，听君歌。
歌有声，妾有情。
情声合，两无违。
一语不入意，从君万曲梁尘飞。','',''),('quantangshi-08020','野田黄雀行','李白','quantangshi','','卷9','游莫逐炎洲翠，栖莫近吴宫燕。
吴宫火起焚巢窠，炎洲逐翠遭网罗。
萧条两翅蓬蒿下，纵有鹰鹯奈若何。','',''),('quantangshi-08021','箜篌谣','李白','quantangshi','','卷9','攀天莫登龙，走山莫骑虎。
贵贱结交心不移，唯有严陵及光武。
周公称大圣，管蔡宁相容。
汉谣一斗粟，不与淮南舂。
兄弟尚路人，吾心安所从。
他人方寸间，山海几千重。
轻言托朋友，对面九疑峯。
开花必早落，桃李不如松。','',''),('quantangshi-08022','雉朝飞','李白','quantangshi','','卷9','麦陇青青三月时，白雉朝飞挟两雌。
锦衣绣翼何离褷，犊牧采薪感之悲。
春天和，白日暖。
啄食饮泉勇气满，争雄鬬死绣颈断。
雉子班奏急管弦，倾心酒美尽玉椀。
枯杨枯杨尔生稊，我独七十而孤栖。
弹弦写恨意不尽，瞑目归黄泥。','',''),('quantangshi-08023','上云乐','李白','quantangshi','','卷9','金天之西，白日所没。
康老胡雏，生彼月窟。
巉岩容仪，戌削风骨。
碧玉炅炅双目瞳，黄金拳拳两鬓红。
华盖垂下睫，嵩岳临上唇。
不覩诡谲貌，岂知造化神。
大道是文康之严父，元气乃文康之老亲。
抚顶弄盘古，推车转天轮。
云见日月初生时，铸冶火精与水银。
阳乌未出谷，顾兔半藏身。
女娲戏黄土，团作愚下人。
散在六合间，蒙蒙若沙尘。
生死了不尽，谁明此胡是仙真。
西海栽若木，东溟植扶桑。
别来几多时，枝叶万里长。
中国有七圣，半路颓洪荒。
陛下应运起，龙飞入咸阳。
赤眉立盆子，白水兴汉光。
叱咤四海动，洪涛为簸扬。
举足蹋紫微，天关自开张。
老胡感至德，东来进仙倡。
五色师子，九苞凤皇。
是老胡鸡犬，鸣舞飞帝乡。
淋漓飒沓，进退成行。
能胡歌，献汉酒。
跪双膝，立两肘。
散花指天举素手，拜龙颜，献圣寿。
北斗戾，南山摧。
天子九九八十一万岁，长倾万岁杯。','',''),('quantangshi-08024','白鸠辞','李白','quantangshi','','卷9','铿鸣钟，考朗鼓。
歌白鸠，引拂舞。
白鸠之白谁与隣，霜衣雪襟诚可珍。
含哺七子能平均，食不噎，性安驯，首农政，鸣阳春。
天子刻玉杖，镂形赐耆人。
白鹭之白非纯真，外洁其色心匪仁。
阙五德，无司晨，胡为啄我葭下之紫鳞。
鹰鹯雕鹗，贪而好杀。
凤凰虽大圣，不愿以为臣。','',''),('quantangshi-08025','日出行','李白','quantangshi','','卷9','日出东方隈，似从地底来。
历天又入海，六龙所舍安在哉？
其始与终古不息，人非元气安得与之久裴徊。
草不谢荣于春风，木不怨落于秋天。
谁挥鞭策驱四运，万物兴歇皆自然。
羲和羲和，汝奚汨没于荒淫之波。
鲁阳何德，驻景挥戈。
逆道违天，矫诬实多。
吾将囊括大块，浩然与溟涬同科。','',''),('quantangshi-08026','胡无人','李白','quantangshi','','卷9','严风吹霜海草凋，筋干精坚胡马骄。
汉家战士三十万，将军兼领霍嫖姚。
流星白羽腰间插，劒花秋莲光出匣。
天兵照雪下玉关，虏箭如沙射金甲。
云龙风虎尽交回，太白入月敌可摧。
敌可摧，旄头灭，履胡之肠涉胡血。
悬胡青天上，埋胡紫塞傍。
胡无人，汉道昌。','',''),('quantangshi-08027','北风行','李白','quantangshi','','卷9','烛龙栖寒门，光曜犹旦开。
日月照之何不及此，唯有北风号怒天上来。
燕山雪花大如席，片片吹落轩辕台。
幽州思妇十二月，停歌罢笑双蛾摧。
倚门望行人，念君长城苦寒良可哀。
别时提劒救边去，遗此虎纹金鞞靫。
中有一双白羽箭，蜘蛛结网生尘埃。
箭空在，人今战死不复回。
不忍见此物，焚之已成灰。
黄河捧土尚可塞，北风雨雪恨难裁。','',''),('quantangshi-08028','侠客行','李白','quantangshi','','卷9','赵客缦胡缨，吴钩霜雪明。
银鞍照白马，飒沓如流星。
十步杀一人，千里不留行。
事了拂衣去，深藏身与名。
闲过信陵饮，脱劒膝前横。
将炙啖朱亥，持觞劝侯嬴。
三杯吐然诺，五岳倒为轻。
眼花耳热后，意气素霓生。
救赵挥金槌，邯郸先震惊。
千秋二壮士，烜赫大梁城。
纵死侠骨香，不慙世上英。
谁能书合下，白首太玄经。','',''),('quantangshi-08029','关山月','李白','quantangshi','','卷9','明月出天山，苍茫云海间。
长风几万里，吹度玉门关。
汉下白登道，胡窥青海湾。
由来征战地，不见有人还。
[戍]客望边色，思归多苦颜。
高楼当此夜，叹息未应闲。','',''),('quantangshi-08030','独漉篇','李白','quantangshi','','卷9','独漉水中泥，水浊不见月。
不见月尚可，水深行人没。
越鸟从南来，胡鹰亦北渡。
我欲弯弓向天射，惜其中道失归路。
落叶别树，飘零随风。
客无所托，悲与此同。
罗帏舒卷，似有人开。
明月直入，无心可猜。
雄劒挂壁，时时龙鸣。
不断犀象，绣涩苔生。
国耻未雪，何由成名。
神鹰梦泽，不顾鸱鸢。
为君一击，鹏[抟]鹏九天。','',''),('quantangshi-08031','登高丘而望远','李白','quantangshi','','卷9','登高丘，望远海。
六鳌骨已霜，三山流安在。
扶桑半摧折，白日沈光彩。
银台金阙如梦中，秦皇汉武空相待。
精卫费木石，鼋鼍无所凭。
君不见骊山茂陵尽灰灭，牧羊之子来攀登。
盗贼劫宝玉，精灵竟何能。
穷兵黩武今如此，鼎湖飞龙安可乘。','',''),('quantangshi-08032','阳春歌','李白','quantangshi','','卷9','长安白日照春空，绿杨结烟垂袅风。
披香殿前花始红，流芳发色绣户中。
绣户中，相经过，飞燕皇后轻身舞，紫宫夫人绝世歌。','',''),('quantangshi-08033','杨叛儿','李白','quantangshi','','卷9','君歌杨叛儿，妾劝新丰酒。
何许最关人，乌啼白门柳。
乌啼隐杨花，君醉留妾家。
博山炉中沈香火，双烟一气凌紫霞。','',''),('quantangshi-08034','双燕离','李白','quantangshi','','卷9','双燕复双燕，双飞令人羡。
玉楼珠阁不独栖，金窗绣户长相见。
柏梁失火去，因入吴王宫。
吴宫又焚荡，雏尽巢亦空。
憔悴一身在，孀雌忆故雄。
双飞难再得，伤我寸心中。','',''),('quantangshi-08035','山人劝酒','李白','quantangshi','','卷9','苍苍云松，落落绮皓。
春风尔来为阿谁，蝴蝶忽然满芳草。
秀眉霜雪颜桃花，骨青髓绿长美好。
称是秦时避世人，劝酒相欢不知老。
各守麋鹿志，耻随龙虎争。
歘起佐太子，汉王乃复惊。
顾谓戚夫人，彼翁羽翼成。
归来商山下，泛若云无情。
举觞酹巢由，洗耳何独清。
浩歌望嵩岳，意气还相倾。','',''),('quantangshi-08036','于阗采花','李白','quantangshi','','卷9','于阗采花人，自言花相似。
明妃一朝西入胡，胡中美女多羞死。
乃知汉地多名姝，胡中无花可方比。
丹青能令丑者妍，无盐翻在深宫里。
自古妬蛾眉，胡沙埋皓齿。','',''),('quantangshi-08037','鞠歌行','李白','quantangshi','','卷9','玉不自言如桃李，鱼目笑之卞和耻。
楚国青蝇何太多，连城白璧遭谗毁。
荆山长号泣血人，忠臣死为刖足鬼。
听曲知宁戚，夷吾因小妻。
秦穆五羊皮，买死百里奚。
洗拂青云上，当时贱如泥。
朝歌鼓刀叟，虎变磻溪中。
一举钓六合，遂荒营丘东。
平生渭水曲，谁识此老翁。
奈何今之人，双目送飞鸿。','',''),('quantangshi-08038','幽涧泉','李白','quantangshi','','卷9','拂彼白石，弹吾素琴。
幽涧愀兮流泉深，善手明徽高张清。
心寂历似千古，松飕飗兮万寻。
中见愁猨吊影而危处兮，呌秋木而长吟。
客有哀时失职而听者，泪淋浪以霑襟。
乃缉商辍羽，潺湲成音。
吾但写声发情于妙指，殊不知此曲之古今。
幽涧泉，鸣深林。','',''),('quantangshi-08039','王昭君二首 一','李白','quantangshi','','卷9','汉家秦地月，流影照明妃。
一上玉关道，天涯去不归。
汉月还从东海出，明妃西嫁无来日。
燕支长寒雪作花，蛾眉憔悴没胡沙。
生乏黄金枉图画，死留青冢使人嗟。','',''),('quantangshi-08040','王昭君二首 二','李白','quantangshi','','卷9','昭君拂玉鞍，上马啼红颊。
今日汉宫人，明朝胡地妾。','',''),('quantangshi-08041','中山孺子妾歌','李白','quantangshi','','卷9','中山孺子妾，特以色见珍。
虽然不如延年妹，亦是当时绝世人。
桃李出深井，花艳惊上春。
一贵复一贱，关天岂由身。
芙蓉老秋霜，团扇羞网尘。
戚姬髡发入舂市，万古共悲辛。','',''),('quantangshi-08042','荆州歌','李白','quantangshi','','卷9','白帝城边足风波，瞿塘五月谁敢过。
荆州麦熟茧成蛾，缫丝忆君头绪多，拨谷飞鸣奈妾何。','',''),('quantangshi-08043','雉子斑','李白','quantangshi','','卷9','辟邪伎作鼓吹惊，雉子班之奏曲成，喔咿振迅欲飞鸣。
扇锦翼，雄风生。
双雌同饮啄，趫悍谁能争。
乍向草中耿介死，不求黄金笼下生。
天地至广大，何惜遂物情。
善卷让天子，务光亦逃名。
所贵旷士怀，朗然合太清。','',''),('quantangshi-08044','相逢行','李白','quantangshi','','卷9','相逢红尘内，高揖黄金鞭。
万户垂杨里，君家阿那边。','',''),('quantangshi-08045','有所思','李白','quantangshi','','卷9','我思仙人乃在碧海之东隅，海寒多天风，白波连山倒蓬壶。
长鲸喷涌不可涉，抚心茫茫泪如珠。
西来青鸟东飞去，愿寄一书谢麻姑。','',''),('quantangshi-08046','久别离','李白','quantangshi','','卷9','别来几春未还家，玉窗五见樱桃花。
况有锦字书，开缄使人嗟。
至此肠断彼心绝，云鬟绿鬓罢梳结，愁如回飙乱白雪。
去年寄书报阳台，今年寄书重相催。
东风兮东风，为我吹行云使西来。
待来竟不来，落花寂寂委清苔。','',''),('quantangshi-08047','白头吟','李白','quantangshi','','卷9','锦水东北流，波荡双鸳鸯。
雄巢汉宫树，雌弄秦草芳。
宁同万死碎绮翼，不忍云间两分张。
此时阿娇正娇妬，独坐长门愁日暮。
但愿君恩顾妾深，岂惜黄金买词赋。
相如作赋得黄金，丈夫好新多异心。
一朝将聘茂陵女，文君因赠白头吟。
东流不作西归水，落花辞条羞故林。
兔丝固无情，随风任倾倒。
谁使女萝枝，而来强萦抱。
两草犹一心，人心不如草。
莫卷龙须席，从他生网丝。
且留琥珀枕，或有梦来时。
覆水再收岂满杯，弃妾已去难重回。
古来得意不相负，只今惟见青陵台。','',''),('quantangshi-08048','采莲曲','李白','quantangshi','','卷9','若耶溪傍采莲女，笑隔荷花共人语。
日照新妆水底明，风飘香袂空中举。
岸上谁家游冶郎，三三五五暎垂杨。
紫骝嘶入落花去，见此踟蹰空断肠。','',''),('quantangshi-08049','临江王节士歌','李白','quantangshi','','卷9','洞庭白波木叶稀，燕鸿始入吴云飞。
吴云寒，燕鸿苦，风号沙宿潇湘浦。
节士悲秋泪如雨，白日当天心。
照之可以事明主，壮士愤，雄风生。
安得倚天劒，跨海斩长鲸。','',''),('quantangshi-08050','司马将军歌','李白','quantangshi','','卷9','狂风吹古月，窃弄章华台。
北落明星动光彩，南征猛将如云雷。
手中电击倚天劒，直斩长鲸海水开。
我见楼船壮心目，颇似龙骧下三蜀。
扬兵习战张虎旗，江中白浪如银屋。
身居玉帐临河魁，紫髯若戟冠崔嵬。
细柳开营揖天子，始知灞上为婴孩。
羌笛横吹阿嚲回，向月楼中吹落梅。
将军自起舞长劒，壮士呼声动九垓。
功成献凯见明主，丹青画象麒麟台。','',''),('quantangshi-08051','君道曲','李白','quantangshi','','卷9','大君若天覆，广运无不至。
轩后爪牙尝先太山稽，如心之使臂。
小白鸿翼于夷吾，刘葛鱼水本无二。
土校可成墙，积德为厚地。','',''),('quantangshi-08052','结袜子','李白','quantangshi','','卷9','燕南壮士吴门豪，筑中置铅鱼隐刀。
感君恩重许君命，太山一掷轻鸿毛。','',''),('quantangshi-08053','结客少年场行','李白','quantangshi','','卷9','紫燕黄金瞳，啾啾摇绿鬉。
平明相驰逐，结客洛门东。
少年学劒术，凌轹白猨公。
珠袍曳锦带，匕首插吴鸿。
由来万夫勇，挟此生雄风。
托交从剧孟，买醉入新丰。
笑尽一杯酒，杀人都市中。
羞道易水寒，从令日贯虹。
燕丹事不立，虚没秦帝宫。
舞阳死灰人，安可与成功。','',''),('quantangshi-08054','长干行二首 一','李白','quantangshi','','卷9','妾发初覆额，折花门前剧。
郎骑竹马来，绕牀弄青梅。
同居长干里，两小无嫌猜。
十四为君妇，羞颜未尝开。
低头向暗壁，千唤不一回。
十五始展眉，愿同尘与灰。
常存抱柱信，岂上望夫台。
十六君远行，瞿塘滟滪堆。
五月不可触，猨声天上哀。
门前迟行迹，一一生绿苔。
苔深不能扫，落叶秋风早。
八月胡蝶来，双飞西园草。
感此伤妾心，坐愁红颜老。
早晚下三巴，预将书报家。
相迎不道远，直至长风沙。','',''),('quantangshi-08055','长干行二首 二','李白','quantangshi','','卷9','忆妾深闺里，烟尘不曾识。
嫁与长干人，沙头候风色。
五月南风兴，思君下巴陵。
八月西风起，想君发扬子。
去来悲如何，见少离别多。
湘潭几日到，妾梦越风波。
昨夜狂风度，吹折江头树。
淼淼暗无边，行人在何处？
好乘浮云骢，佳期兰渚东。
鸳鸯绿蒲上，翡翠锦屏中。
自怜十五余，颜色桃花红。
那作商人妇，愁水复愁风。','',''),('quantangshi-08056','古朗月行','李白','quantangshi','','卷9','小时不识月，呼作白玉盘。
又疑瑶台镜，飞在白云端。
仙人垂两足，桂树作团团。
白兔捣药成，问言与谁餐。
蟾蜍蚀圆影，大明夜已残。
羿昔落九乌，天人清且安。
阴精此沦惑，去去不足观。
忧来其如何，凄怆摧心肝。','',''),('quantangshi-08057','上之回','李白','quantangshi','','卷9','三十六离宫，楼台与天通。
阁道步行月，美人愁烟空。
恩疎宠不及，桃李伤春风。
淫乐意何极，金舆向回中。
万乘出黄道，千旗扬彩虹。
前军细柳北，后骑甘泉东。
岂问渭川老，宁邀襄野童。
但慕瑶池宴，归来乐未穷。','',''),('quantangshi-08058','独不见','李白','quantangshi','','卷9','白马谁家子，黄龙边塞儿。
天山三丈雪，岂是远行时。
春蕙忽秋草，莎鸡鸣西池。
风摧寒椶响，月入霜闺悲。
忆与君别年，种桃齐蛾眉。
桃今百余尺，花落成枯枝。
终然独不见，流泪空自知。','',''),('quantangshi-08059','白紵辞三首 一','李白','quantangshi','','卷9','扬清歌，发皓齿，北方佳人东隣子。
且吟白紵停绿水，长袖拂面为君起。
寒云夜卷霜海空，胡风吹天飘塞鸿。
玉颜满堂乐未终，馆娃日落歌吹蒙。','',''),('quantangshi-08060','白紵辞三首 二','李白','quantangshi','','卷9','月寒江清夜沈沈，美人一笑千黄金。
垂罗舞縠扬哀音，郢中白雪且莫吟。
子夜吴歌动君心，动君心，冀君赏。
愿作天池双鸳鸯，一朝飞去青云上。','',''),('quantangshi-08061','白紵辞三首 三','李白','quantangshi','','卷9','吴刀剪彩缝舞衣，明妆丽服夺春晖。
扬眉转袖若雪飞，倾城独立世所稀。
激楚结风醉忘归，高堂月落烛已微，玉钗挂缨君莫违。','',''),('quantangshi-08062','鸣雁行','李白','quantangshi','','卷9','胡雁鸣，辞燕山，昨发委羽朝度关。
一一衔芦枝，南飞散落天地间。
连行接翼往复还，客居烟波寄湘吴。
凌霜触雪毛体枯，畏逢矰缴惊相呼。
闻弦虚坠良可吁，君更弹射何为乎。','',''),('quantangshi-08063','妾薄命','李白','quantangshi','','卷9','汉帝宠阿娇，贮之黄金屋。
咳唾落九天，随风生珠玉。
宠极爱还歇，妬深情却疎。
长门一步地，不肯暂回车。
雨落不上天，水覆难再收。
君情与妾意，各自东西流。
昔日芙蓉花，今成断根草。
以色事他人，能得几时好。','',''),('quantangshi-08064','幽州胡马客歌','李白','quantangshi','','卷9','幽州胡马客，绿眼虎皮冠。
笑拂两只箭，万人不可干。
弯弓若转月，白雁落云端。
双双掉鞭行，游猎向楼兰。
出门不顾后，报国死何难。
天骄五单于，狼戾好凶残。
牛马散北海，割鲜若虎餐。
虽居燕支山，不道朔雪寒。
妇女马上笑，颜如赬玉盘。
飜飞射鸟兽，花月醉雕鞍。
旄头四光芒，争战若蜂攒。
白刃洒赤血，流沙为之丹。
名将古谁是，疲兵良可叹。
何时天狼灭，父子得闲安。','',''),('quantangshi-08065','门有车马客行','李白','quantangshi','','卷9','门有车马宾，金鞍曜朱轮。
谓从丹霄落，乃是故乡亲。
呼儿扫中堂，坐客论悲辛。
对酒两不饮，停觞泪盈巾。
叹我万里游，飘飘三十春。
空谈帝王略，紫绶不挂身。
雄劒藏玉匣，阴符生素尘。
廓落无所合，流离湘水滨。
借问宗党间，多为泉下人。
生苦百战役，死托万鬼隣。
北风扬胡沙，埋翳周与秦。
大运且如此，苍穹宁匪仁。
恻怆竟何道，存亡任大钧。','',''),('quantangshi-08066','君子有所思行','李白','quantangshi','','卷9','紫阁连终南，青冥天倪色。
凭崖望咸阳，宫阙罗北极。
万井惊画出，九衢如弦直。
渭水银河清，横天流不息。
朝野盛文物，衣冠何翕赩。
厩马散连山，军容威绝域。
伊臯运元化，卫霍输筋力。
歌钟乐未休，荣去老还逼。
圆光过满缺，太阳移中昃。
不散东海金，何争西飞匿。
无作牛山悲，恻怆泪沾臆。','',''),('quantangshi-08067','东海有勇妇','李白','quantangshi','','卷9','梁山感杞妻，恸哭为之倾。
金石忽蹔开，都由激深情。
东海有勇妇，何惭苏子卿。
学劒越处子，超然若流星。
损躯报夫雠，万死不顾生。
白刃耀素雪，苍天感精诚。
十步两躩跃，三呼一交兵。
斩首掉国门，蹴踏五藏行。
豁此伉俪愤，粲然大义明。
北海李使君，飞章奏天庭。
舍罪警风俗，流芳播沧瀛。
名在列女籍，竹帛已光荣。
淳于免诏狱，汉主为缇萦。
津妾一棹歌，脱父于严刑。
十子若不肖，不如一女英。
豫让斩空衣，有心竟无成。
要离杀庆忌，壮夫所素轻。
妻子亦何辜，焚之买虚声。
岂如东海妇，事立独扬名。','',''),('quantangshi-08068','黄葛篇','李白','quantangshi','','卷9','黄葛生洛溪，黄花自绵幂。
青烟蔓长条，缭绕几百尺。
闺人费素手，采缉作絺綌。
缝为绝国衣，远寄日南客。
苍梧大火落，暑服莫轻掷。
此物虽过时，是妾手中迹。','',''),('quantangshi-08069','白马篇','李白','quantangshi','','卷9','龙马花雪毛，金鞍五陵豪。
秋霜切玉劒，落日明珠袍。
鬬鸡事万乘，轩盖一何高。
弓摧南山虎，手接太行猱。
酒后竞风采，三杯弄宝刀。
杀人如剪草，剧孟同游遨。
发愤去函谷，从军向临洮。
叱咤万战场，匈奴尽奔逃。
归来使酒气，未肯拜萧曹。
羞入原宪室，荒淫隐蓬蒿。','',''),('quantangshi-08070','凤吹笙曲','李白','quantangshi','','卷9','仙人十五爱吹笙，学得昆丘彩凤鸣。
始闻炼气餐金液，复道朝天赴玉京。
玉京迢迢几千里，凤笙去去无穷已。
欲叹离声发绛唇，更嗟别调流纤指。
此时惜别讵堪闻，此地相看未忍分。
重吟真曲和清吹，却奏仙歌响绿云。
绿云紫气向函关，访道应寻缑氏山。
莫学吹笙王子晋，一遇浮丘断不还。','',''),('quantangshi-08071','怨歌行','李白','quantangshi','','卷9','十五入汉宫，花颜笑春红。
君王选玉色，侍寝金屏中。
荐枕娇夕月，卷衣恋春风。
宁知赵飞燕，夺宠恨无穷。
沈忧能伤人，绿鬓成霜蓬。
一朝不得意，世事徒为空。
鷫鸘换美酒，舞衣罢雕龙。
寒苦不忍言，为君奏丝桐。
肠断弦亦绝，悲心夜忡忡。','',''),('quantangshi-08072','塞下曲六首 一','李白','quantangshi','','卷9','五月天山雪，无花祗有寒。
笛中闻折柳，春色未曾看。
晓战随金鼓，宵眠抱玉鞍。
愿将腰下劒，直为斩楼兰。','',''),('quantangshi-08073','塞下曲六首 二','李白','quantangshi','','卷9','天兵下北荒，胡马欲南饮。
横戈从百战，直为衔恩甚。
握雪海上餐，拂沙陇头寝。
何当破月氏，然后方高枕。','',''),('quantangshi-08074','塞下曲六首 三','李白','quantangshi','','卷9','骏马似风飙，鸣鞭出渭桥。
弯弓辞汉月，插羽破天骄。
阵解星芒尽，营空海雾消。
功成画麟阁，独有霍嫖姚。','',''),('quantangshi-08075','塞下曲六首 四','李白','quantangshi','','卷9','白马黄金塞，云砂遶梦思。
那堪愁苦节，远忆边城儿。
萤飞秋窗满，月度霜闺迟。
摧残梧桐叶，萧飒沙棠枝。
无时独不见，流泪空自知。','',''),('quantangshi-08076','塞下曲六首 五','李白','quantangshi','','卷9','塞虏乘秋下，天兵出汉家。
将军分虎竹，战士卧龙沙。
边月随弓影，胡霜拂劒花。
玉关殊未入，少妇莫长嗟。','',''),('quantangshi-08077','塞下曲六首 六','李白','quantangshi','','卷9','烽火动沙漠，连照甘泉云。
汉皇按劒起，还召李将军。
兵气天上合，鼓声陇底闻。
横行负勇气，一战净妖氛。','',''),('quantangshi-08078','来日大难','李白','quantangshi','','卷9','来日一身，携粮负薪。
道长食尽，苦口焦唇。
今日醉饱，乐过千春。
仙人相存，诱我远学。
海淩三山，陆憩五岳。
乘龙天飞，目瞻两角。
授以仙药，金丹满握。
蟪蛄蒙恩，深愧短促。
思填东海，强衔一木。
道重天地，轩师广成。
蝉翼九五，以求长生。
下士大笑，如苍蝇声。','',''),('quantangshi-08079','塞上曲','李白','quantangshi','','卷9','大汉无中策，匈奴犯渭桥。
五原秋草绿，胡马一何骄。
命将征西极，横行阴山侧。
燕支落汉家，妇女无华色。
转战渡黄河，休兵乐事多。
萧条清万里，瀚海寂无波。','',''),('quantangshi-08080','玉阶怨','李白','quantangshi','','卷9','玉阶生白露，夜久侵罗袜。
却下水晶帘，玲珑望秋月。','',''),('quantangshi-08081','襄阳曲四首 一','李白','quantangshi','','卷9','襄阳行乐处，歌舞白铜鞮。
江城回渌水，花月使人迷。','',''),('quantangshi-08082','襄阳曲四首 二','李白','quantangshi','','卷9','山公醉酒时，酩酊高阳下。
头上白接䍦，倒着还骑马。','',''),('quantangshi-08083','襄阳曲四首 三','李白','quantangshi','','卷9','岘山临汉江，水绿沙如雪。
上有堕泪碑，青苔久磨灭。','',''),('quantangshi-08084','襄阳曲四首 四','李白','quantangshi','','卷9','且醉习家池，莫看堕泪碑。
山公欲上马，笑杀襄阳儿。','',''),('quantangshi-08085','大堤曲','李白','quantangshi','','卷9','汉水临襄阳，花开大堤暖。
佳期大堤下，泪向南云满。
春风无复情，吹我梦魂散。
不见眼中人，天长音信断。','',''),('quantangshi-08086','宫中行乐词八首 一','李白','quantangshi','','卷9','小小生金屋，盈盈在紫微。
山花插宝髻，石竹绣罗衣。
每出深宫里，常随步辇归。
只愁歌舞散，化作彩云飞。','',''),('quantangshi-08087','宫中行乐词八首 二','李白','quantangshi','','卷9','柳色黄金嫩，梨花白雪香。
玉楼巢翡翠，金殿锁鸳鸯。
选妓随雕辇，征歌出洞房。
宫中谁第一，飞燕在昭阳。','',''),('quantangshi-08088','宫中行乐词八首 三','李白','quantangshi','','卷9','卢橘为秦树，蒲萄出汉宫。
烟花宜落日，丝管醉春风。
笛奏龙吟水，箫鸣凤下空。
君王多乐事，还与万方同。','',''),('quantangshi-08089','宫中行乐词八首 四','李白','quantangshi','','卷9','玉树春归日，金宫乐事多。
后庭朝未入，轻辇夜相过。
笑出花间语，娇来竹下歌。
莫教明月去，留着醉嫦蛾。','',''),('quantangshi-08090','宫中行乐词八首 五','李白','quantangshi','','卷9','绣户香风暖，纱窗曙色新。
宫花争笑日，池草暗生春。
绿树闻歌鸟，青楼见舞人。
昭阳桃李月，罗绮自相亲。','',''),('quantangshi-08091','宫中行乐词八首 六','李白','quantangshi','','卷9','今日明光里，还须结伴游。
春风开紫殿，天乐下朱楼。
艳舞全知巧，娇歌半欲羞。
更怜花月夜，宫女笑藏钩。','',''),('quantangshi-08092','宫中行乐词八首 七','李白','quantangshi','','卷9','寒雪梅中尽，春风柳上归。
宫莺娇欲醉，檐燕语还飞。
迟日明歌席，新花艳舞衣。
晚来移彩仗，行乐泥光辉。','',''),('quantangshi-08093','宫中行乐词八首 八','李白','quantangshi','','卷9','水绿南薰殿，花红北阙楼。
莺歌闻太液，凤吹绕瀛洲。
素女鸣珠佩，天人弄彩球。
今朝风日好，宜入未央游。','',''),('quantangshi-08094','清平调词三首 一','李白','quantangshi','','卷9','云想衣裳花想容，春风拂槛露华浓。
若非羣玉山头见，会向瑶台月下逢。','',''),('quantangshi-08095','清平调词三首 二','李白','quantangshi','','卷9','一枝穠艳露凝香，云雨巫山枉断肠。
借问汉宫谁得似，可怜飞燕倚新妆。','',''),('quantangshi-08096','清平调词三首 三','李白','quantangshi','','卷9','名花倾国两相欢，长得君王带笑看。
觧释春风无限恨，沈香亭北倚阑干。','',''),('quantangshi-08097','入朝曲','李白','quantangshi','','卷9','金陵控海浦，渌水带吴京。
铙歌列骑吹，飒沓引公卿。
槌钟速严妆，伐鼓启重城。
天子凭玉几，劒履若云行。
日出照万户，簪裾烂明星。
朝罢沐浴闲，遨游阆风亭。
济济双阙下，欢娱乐恩荣。','',''),('quantangshi-08098','秦女休行','李白','quantangshi','','卷9','西门秦氏女，秀色如琼花。
手挥白杨刀，清昼杀讐家。
罗袖洒赤血，英气凌紫霞。
直上西山去，关吏相邀遮。
壻为燕国王，身被诏狱加。
犯刑若履虎，不畏落爪牙。
素颈未及断，摧眉伏泥沙。
金鸡忽放赦，大辟得宽赊。
何慙聂政姊，万古共惊嗟。','',''),('quantangshi-08099','秦女卷衣','李白','quantangshi','','卷9','天子居未央，妾侍卷衣裳。
顾无紫宫宠，敢拂黄金牀。
水至亦不去，熊来尚可当。
微身奉日月，飘若萤之光。
愿君采葑菲，无以下体妨。','',''),('quantangshi-08100','东武吟','李白','quantangshi','','卷9','好古笑流俗，素闻贤达风。
方希佐明主，长揖辞成功。
白日在高天，回光烛微躬。
恭承凤凰诏，歘起云萝中。
清切紫霄迥，优游丹禁通。
君王赐颜色，声价凌烟虹。
乘舆拥翠盖，扈从金城东。
宝马丽绝景，锦衣入新丰。
依岩望松雪，对酒鸣丝桐。
因学扬子云，献赋甘泉宫。
天书美片善，清芬播无穷。
归来入咸阳，谈笑皆王公。
一朝去金马，飘落成飞蓬。
宾客日疎散，玉樽亦已空。
才力犹可倚，不慙世上雄。
闲作东武吟，曲尽情未终。
书此谢知己，吾寻黄绮翁。','',''),('quantangshi-08101','邯郸才人嫁为厮养卒妇','李白','quantangshi','','卷9','妾本崇台女，扬蛾入丹阙。
自倚颜如花，宁知有凋歇。
一辞玉阶下，去若朝云没。
每忆邯郸城，深宫梦秋月。
君王不可见，惆怅至明发。','',''),('quantangshi-08102','出自蓟北门行','李白','quantangshi','','卷9','虏阵横北荒，胡星耀精芒。
羽书速惊电，烽火昼连光。
虎竹救边急，戎车森已行。
明主不安席，按劒心飞扬。
推毂出猛将，连旗登战场。
兵威冲绝幕，杀气凌穹苍。
列卒赤山下，开营紫塞傍。
孟冬风沙紧，旌旗飒凋伤。
画角悲海月，征衣卷天霜。
挥刃斩楼兰，弯弓射贤王。
单于一平荡，种落自奔亡。
收功报天子，行歌归咸阳。','',''),('quantangshi-08103','洛阳陌','李白','quantangshi','','卷9','白玉谁家郎，回车渡天津。
看花东陌上，惊动洛阳人。','',''),('quantangshi-08104','北上行','李白','quantangshi','','卷9','北上何所苦，北上缘太行。
磴道盘且峻，巉岩凌穹苍。
马足蹶侧石，车轮摧高冈。
沙尘接幽州，烽火连朔方。
杀气毒劒戟，严风裂衣裳。
奔鲸夹黄河，凿齿屯洛阳。
前行无归日，返顾思旧乡。
惨戚冰雪里，悲号绝中肠。
尺布不掩体，皮肤剧枯桑。
汲水涧谷阻，采薪陇坂长。
猛虎又掉尾，磨牙皓秋霜。
草木不可餐，饥饮零露浆。
叹此北上苦，停骖为之伤。
何日王道平，开颜覩天光。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-08105','短歌行','李白','quantangshi','','卷9','白日何短短，百年苦易满。
苍穹浩茫茫，万劫太极长。
麻姑垂两鬓，一半已成霜。
天公见玉女，大笑亿千场。
吾欲揽六龙，回车挂扶桑。
北斗酌美酒，劝龙各一觞。
富贵非所愿，与人驻颜光。','',''),('quantangshi-08106','空城雀','李白','quantangshi','','卷9','嗷嗷空城雀，身计何戚促。
本与鹪鹩羣，不随凤凰族。
提携四黄口，饮乳未尝足。
食君糠粃余，尝恐乌鸢逐。
耻涉太行险，羞营覆车粟。
天命有定端，守分绝所欲。','',''),('quantangshi-08107','发白马','李白','quantangshi','','卷9','将军发白马，旌节度黄河。
箫鼓聒川岳，沧溟涌涛波。
武安有振瓦，易水无寒歌。
铁骑若雪山，饮流涸滹沱。
扬兵猎月窟，转战略朝那。
倚劒登燕然，边烽列嵯峨。
萧条万里外，耕作五原多。
一扫清大漠，包虎戢金戈。','',''),('quantangshi-08108','陌上桑','李白','quantangshi','','卷9','美女渭桥东，春还事蚕作。
五马如飞龙，青丝结金络。
不知谁家子，调笑来相谑。
妾本秦罗敷，玉颜艳名都。
绿条映素手，采桑向城隅。
使君且不顾，况复论秋胡。
寒螿爱碧草，鸣凤栖青梧。
托心自有处，但怪旁人愚。
徒令白日暮，高驾空踟蹰。','',''),('quantangshi-08109','枯鱼过河泣','李白','quantangshi','','卷9','白龙改常服，偶被豫且制。
谁使尔为鱼，徒劳诉天帝。
作书报鲸鲵，勿恃风涛势。
涛落归泥沙，翻遭蝼蚁噬。
万乘慎出入，柏人以为识。','',''),('quantangshi-08110','丁督护歌','李白','quantangshi','','卷9','云阳上征去，两岸饶商贾。
吴牛喘月时，拖船一何苦。
水浊不可饮，壶浆半成土。
一唱督护歌，心摧泪如雨。
万人凿磐石，无由达江浒。
君看石芒砀，掩泪悲千古。','',''),('quantangshi-08111','相逢行','李白','quantangshi','','卷9','朝骑五花马，谒帝出银台。
秀色谁家子，云车珠箔开。
金鞭遥指点，玉勒近迟回。
夹毂相借问，疑从天上来。
蹙入青绮门，当歌共衔杯。
衔杯暎歌扇，似月云中见。
相见不得亲，不如不相见。
相见情已深，未语可知心。
胡为守空闺，孤眠愁锦衾。
锦衾与罗帏，缠绵会有时。
春风正澹荡，暮雨来何迟。
愿因三青鸟，更报长相思。
光景不待人，须臾发成丝。
当年失行乐，老去徒伤悲。
持此道密意，毋令旷佳期。','',''),('quantangshi-08112','千里思','李白','quantangshi','','卷9','李陵没胡沙，苏武还汉家。
迢迢五原关，朔雪乱边花。
一去隔绝国，思归但长嗟。
鸿雁向西北，因书报天涯。','',''),('quantangshi-08113','树中草','李白','quantangshi','','卷9','鸟衔野田草，误入枯桑里。
客土植危根，逢春犹不死。
草木虽无情，因依尚可生。
如何同枝叶，各自有枯荣。','',''),('quantangshi-08114','君马黄','李白','quantangshi','','卷9','君马黄，我马白。
马色虽不同，人心本无隔。
共作游冶盘，双行洛阳陌。
长劒既照曜，高冠何赩赫。
各有千金裘，俱为五侯客。
猛虎落陷穽，壮夫时屈厄。
相知在急难，独好亦何益。','',''),('quantangshi-08115','拟古','李白','quantangshi','','卷9','融融白玉辉，暎我青蛾眉。
宝镜似空水，落花如风吹。
出门望帝子，荡漾不可期。
安得黄鹤羽，一报佳人知。','',''),('quantangshi-08116','折杨柳','李白','quantangshi','','卷9','垂杨拂绿水，摇艳东风年。
花明玉关雪，叶暖金牕烟。
美人结长想，对此心凄然。
攀条折春色，远寄龙庭前。','',''),('quantangshi-08117','少年子','李白','quantangshi','','卷9','青云年少子，挟弹章台左。
鞍马四边开，突如流星过。
金丸落飞鸟，夜入琼楼卧。
夷齐是何人，独守西山饿。','',''),('quantangshi-08118','紫骝马','李白','quantangshi','','卷9','紫骝行且嘶，双翻碧玉蹄。
卧流不肯渡，似惜锦障泥。
白雪关山远，黄云海戍迷。
挥鞭万里去，安得念春闺。','',''),('quantangshi-08119','少年行二首 一','李白','quantangshi','','卷9','击筑饮美酒，劒歌易水湄。
经过燕太子，结托并州儿。
少年负壮气，奋烈自有时。
因击鲁句践，争博勿相欺。','',''),('quantangshi-08120','少年行二首 二','李白','quantangshi','','卷9','五陵年少金市东，银鞍白马度春风。
落花踏尽游何处，笑入胡姬酒肆中。','',''),('quantangshi-08121','白鼻騧','李白','quantangshi','','卷9','银鞍白鼻騧，绿地障泥锦。
细雨春风花落时，挥鞭直就胡姬饮。','',''),('quantangshi-08122','豫章行','李白','quantangshi','','卷9','胡风吹代马，北拥鲁阳关。
吴兵照海雪，西讨何时还。
半渡上辽津，黄云惨无颜。
老母与子别，呼天野草间。
白马绕旌旗，悲鸣相追攀。
白杨秋月苦，早落豫章山。
本为休明人，斩虏素不闲。
岂惜战鬬死，为君扫凶顽。
精感石没羽，岂云惮险艰。
楼船若鲸飞，波荡落星湾。
此曲不可奏，三军鬓成斑。','',''),('quantangshi-08123','沐浴子','李白','quantangshi','','卷9','沐芳莫弹冠，浴兰莫振衣。
处世忌太洁，至人贵藏晖。
沧浪有钓叟，吾与尔同归。','',''),('quantangshi-08124','高句骊','李白','quantangshi','','卷9','金花折风帽，白马小迟回。
翩翩舞广袖，似鸟海东来。','',''),('quantangshi-08125','舍利弗','李白','quantangshi','','卷9','金绳界宝地，珍木荫瑶池。
云间妙音奏，天际法蠡吹。','',''),('quantangshi-08126','静夜思','李白','quantangshi','','卷9','牀前看月光，疑是地上霜。
举头望山月，低头思故乡。','',''),('quantangshi-08127','渌水曲','李白','quantangshi','','卷9','渌水明秋月，南湖采白苹。
荷花娇欲语，愁杀荡舟人。','',''),('quantangshi-08128','凤凰曲','李白','quantangshi','','卷9','嬴女吹玉箫，吟弄天上春。
青鸾不独去，更有携手人。
影灭彩云断，遗声落西秦。','',''),('quantangshi-08129','凤台曲','李白','quantangshi','','卷9','尝闻秦帝女，传得凤凰声。
是日逢仙子，当时别有情。
人吹彩箫去，天借绿云迎。
曲在身不返，空余弄玉名。','',''),('quantangshi-08130','从军行','李白','quantangshi','','卷9','从军玉门道，逐虏金微山。
笛奏梅花曲，刀开明月环。
鼓声鸣海上，兵气拥云间。
愿斩单于首，长驱静铁关。','',''),('quantangshi-08131','秋思','李白','quantangshi','','卷9','春阳如昨日，碧树鸣黄鹂。
芜然蕙草暮，飒尔凉风吹。
天秋木叶下，月冷莎鸡悲。
坐愁羣芳歇，白露凋华滋。','',''),('quantangshi-08132','春思','李白','quantangshi','','卷9','燕草如碧丝，秦桑低绿枝。
当君怀归日，是妾断肠时。
春风不相识，何事入罗帏。','',''),('quantangshi-08133','秋思','李白','quantangshi','','卷9','燕支黄叶落，妾望自登台。
海上碧云断，单于秋色来。
胡兵沙塞合，汉使玉关回。
征客无归日，空悲蕙草摧。','',''),('quantangshi-08134','子夜吴歌 春歌','李白','quantangshi','','卷9','秦地罗敷女，采桑绿水边。
素手青条上，红妆白日鲜。
蚕饥妾欲去，五马莫留连。','',''),('quantangshi-08135','子夜吴歌 夏歌','李白','quantangshi','','卷9','镜湖三百里，菡萏发荷花。
五月西施采，人看隘若耶。
回舟不待月，归去越王家。','',''),('quantangshi-08136','子夜吴歌 秋歌','李白','quantangshi','','卷9','长安一片月，万户捣衣声。
秋风吹不尽，总是玉关情。
何日平胡虏，良人罢远征。','',''),('quantangshi-08137','子夜吴歌 冬歌','李白','quantangshi','','卷9','明朝驿使发，一夜絮征袍。
素手抽针冷，那堪把剪刀。
裁缝寄远道，几日到临洮。','',''),('quantangshi-08138','对酒行','李白','quantangshi','','卷9','松子栖金华，安期入蓬海。
此人古之仙，羽化竟何在。
浮生速流电，倏忽变光彩。
天地无凋换，容颜有迁改。
对酒不肯饮，含情欲谁待。','',''),('quantangshi-08139','估客行','李白','quantangshi','','卷9','海客乘天风，将船远行役。
譬如云中鸟，一去无踪迹。','',''),('quantangshi-08140','捣衣篇','李白','quantangshi','','卷9','闺里佳人年十余，嚬蛾对影恨离居。
忽逢江上春归燕，衔得云中尺素书。
玉手开缄长叹息，狂夫犹戍交河北。
万里交河水北流，愿为双燕泛中洲。
君边云拥青丝骑，妾处苔生红粉楼。
楼上春风日将歇，谁能揽镜看愁发。
晓吹员管随落花，夜捣戎衣向明月。
明月高高刻漏长，真珠帘箔掩兰堂。
横垂宝幄同心结，半拂琼筵苏合香。
琼筵宝幄连枝锦，灯烛荧荧照孤寝。
有便凭将金剪刀，为君留下相思枕。
摘尽庭兰不见君，红巾拭泪生氤氲。
明年若更征边塞，愿作阳台一叚云。','',''),('quantangshi-08141','少年行','李白','quantangshi','','卷9','君不见淮南少年游侠客，白日球猎夜拥掷。
呼卢百万终不惜，报雠千里如咫尺。
少年游侠好经过，浑身装束皆绮罗。
蕙兰相随喧妓女，风光去处满笙歌。
骄矜自言不可有，侠士堂中养来久。
好鞍好马乞与人，十千五千旋沽酒。
赤心用尽为知己，黄金不惜栽桃李。
桃李栽来几度春，一回花落一回新。
府县尽为门下客，王侯皆是平交人。
男儿百年且乐命，何须徇书受贫病。
男儿百年且荣身，何须徇节甘风尘。
衣冠半是征战士，穷儒浪作林泉民。
遮莫枝根长百丈，不如当代多还往。
遮莫姻亲连帝城，不如当身自簪缨。
看取富贵眼前者，何用悠悠身后名。','',''),('quantangshi-08142','长歌行','李白','quantangshi','','卷9','桃李待日开，荣华照当年。
东风动百物，草木尽欲言。
枯枝无丑叶，涸水吐清泉。
大力运天地，羲和无停鞭。
功名不早着，竹帛将何宣。
桃李务青春，谁能贯白日。
富贵与神仙，蹉跎成两失。
金石犹销铄，风霜无久质。
畏落日月后，强欢歌与酒。
秋霜不惜人，倏忽侵蒲柳。','',''),('quantangshi-08143','长相思 一','李白','quantangshi','','卷9','日色已尽花含烟，月明欲素愁不眠。
赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。
此曲有意无人传，愿随春风寄燕然，忆君迢迢隔青天。
昔日横波目，今成流泪泉。
不信妾肠断，归来看取明镜前。','',''),('quantangshi-08144','长相思 二','李白','quantangshi','','卷9','美人在时花满堂，美人去后空余牀。
牀中绣被卷不寝，至今三载犹闻香。
香亦竟不灭，人亦竟不来。
相思黄叶落，白露点青苔。','',''),('quantangshi-08145','猛虎行','李白','quantangshi','','卷9','朝作猛虎行，暮作猛虎吟。
肠断非关陇头水，泪下不为雍门琴。
旌旗缤纷两河道，战鼓惊山欲颠倒。
秦人半作燕地囚，胡马翻衔洛阳草。
一输一失关下兵，朝降夕叛幽蓟城。
巨鳌未斩海水动，鱼龙奔走安得宁。
颇似楚汉时，翻覆无定止。
朝过博浪沙，暮入淮阴市。
张良未遇韩信贫，刘项存亡在两臣。
蹔到下邳受兵略，来投漂母作主人。
贤哲栖栖古如此，今时亦弃青云士。
有策不敢犯龙鳞，窜身南国避胡尘。
宝书玉劒挂高阁，金鞍骏马散故人。
昨日方为宣城客，掣铃交通二千石。
有时六博快壮心，遶牀三匝呼一掷。
楚人每道张旭奇，心藏风云世莫知。
三吴邦伯皆顾盼，四海雄侠两追随。
萧曹曾作沛中吏，攀龙附凤当有时。
溧阳酒楼三月春，杨花茫茫愁杀人。
胡雏绿眼吹玉笛，吴歌白紵飞梁尘。
丈夫相见且为乐，槌牛挝鼓会众宾。
我从此去钓东海，得鱼笑寄情相亲。','',''),('quantangshi-08146','去妇词','李白','quantangshi','','卷9','古来有弃妇，弃妇有归处。
今日妾辞君，辞君遣何去。
本家零落尽，恸哭来时路。
忆昔未嫁君，闻君却周旋。
绮罗锦绣段，有赠黄金千。
十五许嫁君，二十移所天。
自从结发日未几，离君缅山川。
家家尽欢喜，孤妾长自怜。
幽闺多怨思，盛色无十年。
相思若循还，枕席生流泉。
流泉咽不扫，独梦关山道。
及此见君归，君归妾已老。
物情恶衰贱，新宠方妍好。
掩泪出故房，伤心剧秋草。
自妾为君妻，君东妾在西。
罗帏到晓恨，玉貌一生啼。
自从离别久，不觉尘埃厚。
尝嫌玳瑁孤，犹羡鸳鸯偶。
岁华逐霜霰，贱妾何能久。
寒沼落芙蓉，秋风散杨柳。
以比顦顇颜，空持旧物还。
余生欲何寄，谁肯相牵攀。
君恩既断绝，相见何年月。
悔倾连理杯，虚作同心结。
女萝附青松，贵欲相依投。
浮萍失绿水，教作若为流。
不叹君弃妾，自叹妾缘业。
忆昔初嫁君，小姑才倚牀。
今日妾辞君，小姑如妾长。
回头语小姑，莫嫁如兄夫。','',''),('quantangshi-08147','襄阳歌','李白','quantangshi','','卷9','落日欲没岘山西，倒着接䍦花下迷。
襄阳小儿齐拍手，拦街争唱白铜鞮。
傍人借问笑何事，笑杀山翁醉似泥。
鸬鷀杓，鹦鹉杯，百年三万六千日，一日须倾三百杯。
遥看汉水鸭头绿，恰似葡萄初发醅。
此江若变作春酒，垒麴便筑糟丘台。
千金骏马换小妾，笑坐雕鞍歌落梅。
车傍侧挂一壶酒，凤笙龙管行相摧。
咸阳市中叹黄犬，何如月下倾金罍。
君不见晋朝羊公一片石，龟头剥落生莓苔。
泪亦不能为之堕，心亦不能为之哀。
清风朗月不用一钱买，玉山自倒非人推。
舒州杓，力士铛，李白与尔同死生。
襄王云雨今安在，江水东流猨夜声。','',''),('quantangshi-08148','南都行','李白','quantangshi','','卷9','南都信佳丽，武阙横西关。
白水真人居，万商罗鄽闤。
高楼对紫陌，甲第连青山。
此地多英豪，邈然不可攀。
陶朱与五羖，名播天壤间。
丽华秀玉色，汉女娇朱颜。
清歌遏流云，艳舞有余闲。
遨游盛宛洛，冠盖随风还。
走马红阳城，呼鹰白河湾。
谁识卧龙客，长吟愁鬓斑。','',''),('quantangshi-08149','江上吟','李白','quantangshi','','卷9','木兰之枻沙棠舟，玉箫金管坐两头。
美酒尊中置千斛，载妓随波任去留。
仙人有待乘黄鹤，海客无心随白鸥。
屈平词赋悬日月，楚王台榭空山丘。
兴酣落笔摇五岳，诗成笑傲凌沧洲。
功名富贵若长在，汉水亦应西北流。','',''),('quantangshi-08150','侍从宜春苑奉诏赋龙池柳色初青听新莺百啭歌','李白','quantangshi','','卷9','东风已绿瀛洲草，紫殿红楼觉春好，池南柳色半青青。
萦烟袅娜拂绮城，垂丝百尺挂雕楹。
上有好鸟相和鸣，间关早得春风情。
春风卷入碧云去，千门万户皆春声。
是时君王在镐京，五云垂晖耀紫清。
仗出金宫随日转，天回玉辇绕花行。
始向蓬莱看舞鹤，还过茝石听新莺。
新莺飞绕上林苑，愿入箫韶杂凤笙。','',''),('quantangshi-08151','玉壶吟','李白','quantangshi','','卷9','烈士击玉壶，壮心惜暮年。
三杯拂劒舞秋月，忽然高咏涕泗涟。
凤凰初下紫泥诏，谒帝称觞登御筵。
揄扬九重万乘主，谑浪赤墀青琐贤。
朝天数换飞龙马，勅赐珊瑚白玉鞭。
世人不识东方朔，大隐金门是谪仙。
西施宜笑复宜嚬，丑女效之徒累身。
君王虽爱蛾眉好，无奈宫中妬杀人。','',''),('quantangshi-08152','豳歌行上新平长史兄粲','李白','quantangshi','','卷9','豳谷稍稍振庭柯，泾水浩浩扬湍波。
哀鸿酸嘶暮声急，愁云苍惨寒气多。
忆昨去家此为客，荷花初红柳条碧。
中宵出饮三百杯，明朝归揖二千石。
宁知流寓变光辉，胡霜萧飒绕客衣。
寒灰寂寞凭谁暖，落叶飘扬何处归。
吾兄行乐穷曛旭，满堂有美颜如玉。
赵女长歌入彩云，燕姬醉舞娇红烛。
狐裘兽炭酌流霞，壮士悲吟宁见嗟。
前荣后枯相翻覆，何惜余光及棣华。','',''),('quantangshi-08153','西岳云台歌送丹丘子','李白','quantangshi','','卷9','西岳峥嵘何壮哉，黄河如丝天际来。
黄河万里触山动，盘涡毂转秦地雷。
荣光休气纷五彩，千年一清圣人在。
巨灵咆哮擘两山，洪波喷箭射东海。
三峯却立如欲摧，翠崖丹谷高掌开。
白帝金精运元气，石作莲花云作台。
云台阁道连窈冥，中有不死丹丘生。
明星玉女备洒扫，麻姑搔背指爪轻。
我皇手把天地户，丹丘谈天与天语。
九重出入生光辉，东来蓬莱复西归。
玉浆傥惠故人饮，骑二茅龙上天飞。','',''),('quantangshi-08154','元丹丘歌','李白','quantangshi','','卷9','元丹丘，爱神仙，朝饮颍川之清流，暮还嵩岑之紫烟，三十六峰长周旋。
长周旋，蹑星虹，身骑飞龙耳生风。
横河跨海与天通，我知尔游心无穷。','',''),('quantangshi-08155','扶风豪士歌','李白','quantangshi','','卷9','洛阳三月飞胡沙，洛阳城中人怨嗟。
天津流水波赤血，白骨相撑如乱麻。
我亦东奔向吴国，浮云四塞道路赊。
东方日出啼早鸦，城门人开扫落花。
梧桐杨柳拂金井，来醉扶风豪士家。
扶风豪士天下奇，意气相倾山可移。
作人不倚将军势，饮酒岂顾尚书期。
雕盘绮食会众客，吴歌赵舞香风吹。
原尝春陵六国时，开心写意君所知。
堂中各有三千士，明日报恩知是谁。
抚长劒，一扬眉，清水白石何离离。
脱吾帽，向君笑，饮君酒，为君吟。
张良未逐赤松去，桥边黄石知我心。','',''),('quantangshi-08156','同族弟金城尉叔卿烛照山水壁画歌','李白','quantangshi','','卷9','高堂粉壁图蓬瀛，烛前一见沧洲清。
洪波汹涌山峥嵘，皎若丹丘隔海望赤城。
光中乍喜岚气灭，谓逢山阴晴后雪。
回溪碧流寂无喧，又如秦人月下窥花源。
了然不觉清心魂，祗将叠嶂鸣秋猨。
与君对此欢未歇，放歌行吟达明发。
却顾海客扬云帆，便欲因之向溟渤。','',''),('quantangshi-08157','白毫子歌','李白','quantangshi','','卷9','淮南小山白毫子，乃在淮南小山里。
夜卧松下云，朝餐石中髓。
小山连緜向江开，碧峰巉岩绿水回。
余配白毫子，独酌流霞杯。
拂花弄琴坐青苔，绿萝树下春风来。
南窗萧飒松声起，凭崖一听清心耳。
可得见，未得亲。
八公携手五云去，空余桂树愁杀人。','',''),('quantangshi-08158','梁园吟','李白','quantangshi','','卷9','我浮黄云去京阙，挂席欲进波连山。
天长水阔厌远涉，访古始及平台间。
平台为客忧思多，对酒遂作梁园歌。
却忆蓬池阮公咏，因吟渌水扬洪波。
洪波浩荡迷旧国，路远西归安可得。
人生达命岂暇愁，且饮美酒登高楼。
平头奴子摇大扇，五月不热疑清秋。
玉盘杨梅为君设，吴盐如花皎白雪。
持盐把酒但饮之，莫学夷齐事高洁。
昔人豪贵信陵君，今人耕种信陵坟。
荒城虚照碧山月，古木尽入苍梧云。
粱王宫阙今安在？枚马先归不相待。
舞影歌声散绿池，空余汴水东流海。
沈吟此事泪满衣，黄金买醉未能归。
连呼五白行六博，分曹赌酒酣驰辉。
歌且谣，意方远，东山高卧时起来，欲济苍生未应晚。','',''),('quantangshi-08159','鸣臯歌送岑征君','李白','quantangshi','','卷9','若有人兮思鸣臯，阻积雪兮心烦劳。
洪河凌竞不可以径度，冰龙鳞兮难容舠。
邈仙山之峻极兮，闻天籁之嘈嘈。
霜厓缟皓以合沓兮，若长风扇海涌沧溟之波涛。
玄猨绿罴，舔舕崟岌。
危柯振石，骇胆栗魄，羣呼而相号。
峯峥嵘以路绝，挂星辰于岩㟼。
送君之归兮，动鸣臯之新作。
交鼓吹兮弹丝，觞清泠之池阁。
君不行兮何待，若反顾之黄鹤。
扫梁园之羣英，振大雅于东洛。
巾征轩兮历阻折，寻幽居兮越巘崿。
盘白石兮坐素月，琴松风兮寂万壑。
望不见兮心氛氲，萝冥冥兮霰纷纷。
水横洞以下渌，波小声而上闻。
虎啸谷而生风，龙藏溪而吐云。
寡鹤清唳，饥鼯嚬呻。
魂独处此幽默兮，愀空山而愁人。
鸡聚族以争食，凤孤飞而无隣。
蝘蜓嘲龙，鱼目混珍。
嫫母衣锦，西施负薪。
若使巢由桎梏于轩冕兮，亦奚异乎夔龙蹩躠于风尘。
哭何苦而救楚，笑何夸而却秦。
吾诚不能学二子沽名矫节以耀世兮，固将弃天地而遗身。
白鸥兮飞来，长与君兮相亲。','',''),('quantangshi-08160','鸣臯歌奉饯从翁清归五厓山居','李白','quantangshi','','卷9','忆昨鸣臯梦里还，手弄素月清潭间。
觉时枕席非碧山，侧身西望阻秦关。
麒膦阁上春还早，着书却忆伊阳好。
青松来风吹古道，绿萝飞花覆烟草。
我家仙翁爱清真，才雄草圣凌古人，欲卧鸣臯绝世尘。
鸣臯微茫在何处？五厓峡水横樵路。
身披翠云裘，袖拂紫烟去。
去时应过嵩少间，相思为折三花树。','',''),('quantangshi-08161','劳劳亭歌','李白','quantangshi','','卷9','金陵劳劳送客堂，蔓草离离生道傍。
古情不尽东流水，此地悲风愁白杨。
我乘素舸同康乐，朗咏清川飞夜霜。
昔闻牛渚吟五章，今来何谢袁家郎。
苦竹寒声动秋月，独宿空帘归梦长。','',''),('quantangshi-08162','横江词六首 一','李白','quantangshi','','卷9','人道横江好，侬道横江恶。
一风三日吹倒山，白浪高于瓦官阁。','',''),('quantangshi-08163','横江词六首 二','李白','quantangshi','','卷9','海潮南去过浔阳，牛渚由来险马当。
横江欲渡风波恶，一水牵愁万里长。','',''),('quantangshi-08164','横江词六首 三','李白','quantangshi','','卷9','横江西望阻西秦，汉水东连扬子津。
白浪如山那可渡，狂风愁杀峭帆人。','',''),('quantangshi-08165','横江词六首 四','李白','quantangshi','','卷9','海神来过恶风回，浪打天门石壁开。
浙江八月何如此，涛似连山喷雪来。','',''),('quantangshi-08166','横江词六首 五','李白','quantangshi','','卷9','横江馆前津吏迎，向余东指海云生。
郎今欲渡缘何事，如此风波不可行。','',''),('quantangshi-08167','横江词六首 六','李白','quantangshi','','卷9','月晕天风雾不开，海鲸东蹙百川回。
惊波一起三山动，公无渡河归去来。','',''),('quantangshi-08168','金陵城西楼月下吟','李白','quantangshi','','卷9','金陵夜寂凉风发，独上高楼望吴越。
白云暎水摇空城，白露垂珠滴秋月。
月下沈吟久不归，古来相接眼中稀。
解道澄江净如练，令人长忆谢玄晖。','',''),('quantangshi-08169','东山吟','李白','quantangshi','','卷9','携妓东土山，怅然悲谢安。
我妓今朝如花月，他妓古坟荒草寒。
白鸡梦后三百岁，洒酒浇君同所欢。
酣来自作青海舞，秋风吹落紫绮冠。
彼亦一时，此亦一时，浩浩洪流之咏何必奇。','',''),('quantangshi-08170','僧伽歌','李白','quantangshi','','卷9','真僧法号号僧伽，有时与我论三车。
问言诵咒几千徧，口道恒河沙复沙。
此僧本住南天竺，为法头陀来此国。
戒得长天秋月明，心如世上青莲色。
意清净，貌棱棱，亦不减，亦不增。
瓶里千年铁柱骨，手中万岁胡孙藤。
嗟予落魄江淮久，罕遇真僧说空有。
一言散尽波罗夷，再礼浑除犯轻垢。','',''),('quantangshi-08171','白云歌送刘十六归山','李白','quantangshi','','卷9','楚山秦山皆白云，白云处处长随君。
长随君，君入楚山里，云亦随君渡湘水。
湘水上，女萝衣，白云堪卧君早归。','',''),('quantangshi-08172','白云歌送友人','李白','quantangshi','','卷9','楚山秦山多白云，白云䖏䖏长随君。
君今还入楚山里，云亦随君渡湘水。
水上女萝衣白云，早卧早行君早起。','',''),('quantangshi-08173','金陵歌送别范宣','李白','quantangshi','','卷9','石头巉岩如虎踞，凌波欲过沧江去。
钟山龙盘走势来，秀色横分历阳树。
四十余帝三百秋，功名事迹随东流。
白马小儿谁家子，泰清之岁来关囚。
金陵昔时何壮哉，席卷英豪天下来。
冠盖散为烟雾尽，金舆玉座成寒灰。
扣劒悲吟空咄嗟，梁陈白骨乱如麻。
天子龙沈景阳井，谁歌玉树后庭花。
此地伤心不能道，目下离离长春草。
送尔长江万里心，他年来访南山老。','',''),('quantangshi-08174','笑歌行','李白','quantangshi','','卷9','笑矣乎，笑矣乎！君不见曲如钩，古人知尔封公侯。
君不见直如弦，古人知尔死道边。
张仪所以只掉三寸舌，苏秦所以不垦二倾田。
笑矣乎，笑矣乎！君不见沧浪老人歌一曲，还道沧浪濯吾足。
平生不解谋此身，虚作离骚遣人读。
笑矣乎，笑矣乎！赵有豫让楚屈平，卖身买得千年名。
巢由洗耳有何益，夷齐饿死终无成。
君爱身后名，我爱眼前酒。
饮酒眼前乐，虚名何处有。
男儿穷通当有时，曲腰向君君不知。
猛虎不看几上肉，洪炉不铸囊中锥。
笑矣乎，笑矣乎！甯武子，朱买臣，扣角行歌背负薪。
今日逢君君不识，岂得不如佯狂人。','',''),('quantangshi-08175','悲歌行','李白','quantangshi','','卷9','悲来乎，悲来乎！主人有酒且莫斟，听我一曲悲来吟。
悲来不吟还不笑，天下无人知我心。
君有数斗酒，我有三尺琴。
琴鸣酒乐两相得，一杯不啻千钧金。
悲来乎，悲来乎！天虽长，地虽久，金玉满堂应不守。
富贵百年能几何，死生一度人皆有。
孤猨坐啼坟上月，且须一尽杯中酒。
悲来乎，悲来乎！凤皇不至河无图，微子去之箕子奴。
汉帝不忆李将军，楚王放却屈大夫。
悲来乎，悲来乎！秦家李斯早追悔，虚名拨向身之外。
范子何曾爱五湖，功成名遂身自退。
劒是一夫用，书能知姓名。
惠施不肯干万乘，卜式未必穷一经。
还须黑头取方伯，莫谩白首为儒生。','',''),('quantangshi-08176','秋浦歌十七首 一','李白','quantangshi','','卷9','秋浦长似秋，萧条使人愁。
客愁不可度，行上东大楼。
正西望长安，下见江水流。
寄言向江水，汝意忆侬不。
遥传一掬泪，为我达扬州。','',''),('quantangshi-08177','秋浦歌十七首 二','李白','quantangshi','','卷9','秋浦猨夜愁，黄山堪白头。
清溪非陇水，翻作断肠流。
欲去不得去，薄游成久游。
何年是归日，雨泪下孤舟。','',''),('quantangshi-08178','秋浦歌十七首 三','李白','quantangshi','','卷9','秋浦锦驼鸟，人间天上稀。
山鸡羞渌水，不敢照毛衣。','',''),('quantangshi-08179','秋浦歌十七首 四','李白','quantangshi','','卷9','两鬓入秋浦，一朝飒已衰。
猨声催白发，长短尽成丝。','',''),('quantangshi-08180','秋浦歌十七首 五','李白','quantangshi','','卷9','秋浦多白猨，超腾若飞雪。
牵引条上儿，饮弄水中月。','',''),('quantangshi-08181','秋浦歌十七首 六','李白','quantangshi','','卷9','愁作秋浦客，强看秋浦花。
