水急客舟（一作“行”）疾，山花拂面香。','',''),('quantangshi-08187','秋浦歌十七首 十二','李白','quantangshi','','卷9','水如一匹练，此地即平天。
耐可乘明月，看花上酒船。','',''),('quantangshi-08188','秋浦歌十七首 十三','李白','quantangshi','','卷9','渌水净素月，月明白鹭飞。
郎听采菱女，一道夜歌归。','',''),('quantangshi-08189','秋浦歌十七首 十四','李白','quantangshi','','卷9','炉火照天地，红星乱紫烟。
赧郎明月夜，歌曲动寒川。','',''),('quantangshi-08190','秋浦歌十七首 十五','李白','quantangshi','','卷9','白发三千丈，缘愁似个长。
