妻子张白鹇，结罝暎深竹。','',''),('quantangshi-08192','秋浦歌十七首 十七','李白','quantangshi','','卷9','桃波（一作“陂”）一步地，了了语声闻。
暗与山僧别，低头礼白云。','',''),('quantangshi-08193','当涂赵炎少府粉图山水歌','李白','quantangshi','','卷9','峨眉高出西极天，罗浮直与南溟连。
名公绎思挥彩笔，驱山走海置眼前。
满堂空翠如可扫，赤城霞气苍梧烟。
洞庭潇湘意渺绵，三江七泽情洄沿。
惊涛汹涌向何处，孤舟一去迷归年。
征帆不动亦不旋，飘如随风落天边。
心摇目断兴难尽，几时可到三山巅。
西峯峥嵘喷流泉，横石蹙水波潺湲。
东厓合沓蔽轻雾，深林杂树空芊绵。
此中冥昧失昼夜，隐几寂听无鸣蝉。
长松之下列羽客，对坐不语南昌仙。
南昌仙人赵夫子，妙年历落青云士。
讼庭无事罗众宾，杳然如在丹青里。
五色粉图安足珍，真仙可以全吾身。
若待功成拂衣去，武陵桃花笑杀人。','',''),('quantangshi-08194','永王东巡歌十一首 一','李白','quantangshi','','卷9','永王正月东出师，天子遥分龙虎旗。
楼船一举风波静，江汉翻为雁鹜池。','',''),('quantangshi-08195','永王东巡歌十一首 二','李白','quantangshi','','卷9','三川北虏乱如麻，四海南奔似永嘉。
但用东山谢安石，为君谈笑静胡沙。','',''),('quantangshi-08196','永王东巡歌十一首 三','李白','quantangshi','','卷9','雷鼓嘈嘈喧武昌，云旗猎猎过寻阳。
