地转锦江成渭水，天回玉垒作长安。','',''),('quantangshi-08209','上皇西巡南京歌十首 五','李白','quantangshi','','卷9','万国同风共一时，锦江何谢曲江池。
石镜更明天上月，后宫亲得照蛾眉。','',''),('quantangshi-08210','上皇西巡南京歌十首 六','李白','quantangshi','','卷9','濯锦清江万里流，云帆龙舸下扬州。
北地虽夸上林苑，南京还有散花楼。','',''),('quantangshi-08211','上皇西巡南京歌十首 七','李白','quantangshi','','卷9','锦水东流绕锦城，星桥北挂象天星。
四海此中朝圣主，峨眉山下列仙庭。','',''),('quantangshi-08212','上皇西巡南京歌十首 八','李白','quantangshi','','卷9','秦开蜀道置金牛，汉水元通星汉流。
天子一行遗圣迹，锦城长作帝王州。','',''),('quantangshi-08213','上皇西巡南京歌十首 九','李白','quantangshi','','卷9','水绿天青不起尘，风光和暖胜三秦。
万国烟花随玉辇，西来添作锦江春。','',''),('quantangshi-08214','上皇西巡南京歌十首 十','李白','quantangshi','','卷9','劒阁重关蜀北门，上皇归马若云屯。
少帝长安开紫极，双悬日月照干坤。','',''),('quantangshi-08215','峨眉山月歌','李白','quantangshi','','卷9','峨眉山月半轮秋，影入平羌江水流。
夜发清溪向三峡，思君不见下渝州。','',''),('quantangshi-08216','峨眉山月歌送蜀僧晏入中京','李白','quantangshi','','卷9','我在巴东三峡时，西看明月忆峨眉。
月出峨眉照沧海，与人万里长相随。
黄鹤楼前月华白，此中忽见峨眉客。
峨眉山月还送君，风吹西到长安陌。
长安大道横九天，峨眉山月照秦川。
黄金狮子乘高座，白玉麈尾谈重玄。
我似浮云殢吴越，君逢圣主游丹阙。
一振高名满帝都，归时还弄峨眉月。','',''),('quantangshi-08217','赤壁歌送别','李白','quantangshi','','卷9','二龙争战决雌雄，赤壁楼船扫地空。
烈火张天照云海，周瑜于此破曹公。
君去沧江望澄碧，鲸鲵唐突留余迹。
一一书来报故人，我欲因之壮心魄。','',''),('quantangshi-08218','江夏行','李白','quantangshi','','卷9','忆昔娇小姿，春心亦自持。
为言嫁夫壻，得免长相思。
谁知嫁商贾，令人却愁苦。
自从为夫妻，何曾在乡土。
去年下扬州，相送黄鹤楼。
眼看帆去远，心逐江水流。
只言期一载，谁谓历三秋。
使妾肠欲断，恨君情悠悠。
东家西舍同时发，北去南来不逾月。
未知行李游何方，作个音书能断绝。
适来往南浦，欲问西江船。
正见当垆女，红妆二八年。
一种为人妻，独自多悲凄。
对镜便垂泪，逢人只欲啼。
不如轻薄儿，旦暮长相随。
悔作商人妇，青春长别离。
如今正好同懽乐，君去容华谁得知。','',''),('quantangshi-08219','怀仙歌','李白','quantangshi','','卷9','一鹤东飞过沧海，放心散漫知何在。
仙人浩歌望我来，应攀玉树长相待。
尧舜之事不足惊，自余嚣嚣直可轻。
巨鳌莫戴三山去，我欲蓬莱顶上行。','',''),('quantangshi-08220','玉真仙人词','李白','quantangshi','','卷9','玉真之仙人，时往太华峰。
清晨鸣天鼓，飙歘腾双龙。
弄电不辍手，行云本无踪。
几时入少室，王母应相逢。','',''),('quantangshi-08221','清溪行','李白','quantangshi','','卷9','清溪清我心，水色异诸水。
借问新安江，见底何如此。
人行明镜中，鸟度屏风里。
向晚猩猩啼，空悲远游子。','',''),('quantangshi-08222','酬殷明佐见赠五云裘歌','李白','quantangshi','','卷9','我吟谢朓诗上语，朔风飒飒吹飞雨。
谢朓已没青山空，后来继之有殷公。
粉图珍裘五云色，晔如晴天散彩虹。
文章彪炳光陆离，应是素娥玉女之所为。
轻如松花落金粉，浓似苔锦含碧滋。
远山积翠横海岛，残霞飞丹暎江草。
凝毫采掇花露容，几年功成夺天造。
故人赠我我不违，着令山水含清晖。
顿惊谢康乐，诗兴生我衣。
襟前林壑敛暝色，袖上云霞收夕霏。
羣仙长叹惊此物，千厓万岭相萦郁。
身骑白鹿行飘颻，手翳紫芝笑披拂。
相如不足跨鷫鸘，王恭鹤氅安可方。
瑶台雪花数千点，片片吹落春风香。
为君持此凌苍苍，上朝三十六玉皇。
下窥夫子不可及，矫首相思空断肠。','',''),('quantangshi-08223','临路歌','李白','quantangshi','','卷9','大鹏飞兮振八裔，中天摧兮力不济。
余风激兮万世，游扶桑兮挂石袂。
后人得之传此，仲尼亡兮谁为出涕。','',''),('quantangshi-08224','古意','李白','quantangshi','','卷9','君为女萝草，妾作兔丝花。
轻条不自引，为逐春风斜。
百丈托远松，缠绵成一家。
谁言会面易，各在青山厓。
女萝发馨香，兔丝断人肠。
枝枝相纠结，叶叶竞飘扬。
生子不知根，因谁共芬芳。
中巢双翡翠，上宿紫鸳鸯。
若识二草心，海潮亦可量。','',''),('quantangshi-08225','山鹧鸪词','李白','quantangshi','','卷9','苦竹岭头秋月辉，苦竹南枝鹧鸪飞。
嫁得燕山胡雁壻，欲衔我向雁门归。
山鸡翟雉来相劝，南禽多被北禽欺。
紫塞严霜如劒戟，苍梧欲巢难背违。
我今誓死不能去，哀鸣惊呌泪沾衣。','',''),('quantangshi-08226','历阳壮士勤将军名思齐歌','李白','quantangshi','','卷9','太古历阳郡，化为洪川在。
江山犹郁盘，龙虎祕光彩。
蓄泄数千载，风云何霮䨴。
特生勤将军，神力百夫倍。','',''),('quantangshi-08227','草书歌行','李白','quantangshi','','卷9','少年上人号怀素，草书天下称独步。
墨池飞出北溟鱼，笔锋杀尽中山兔。
八月九月天气凉，酒徒词客满高堂。
牋麻素绢排数厢，宣州石砚墨色光。
吾师醉后倚绳牀，须臾扫尽数千张。
飘风骤雨惊飒飒，落花飞雪何茫茫。
起来向壁不停手，一行数字大如斗。
怳怳如闻神鬼惊，时时只见龙蛇走。
左盘右蹙如惊电，状同楚汉相攻战。
湖南七郡凡几家，家家屏障书题徧。
王逸少，张伯英，古来几许浪得名。
张颠老死不足数，我师此义不师古。
古来万事贵天生，何必要公孙大娘浑脱舞。','',''),('quantangshi-08228','和卢侍御通塘曲','李白','quantangshi','','卷9','君夸通塘好，通塘胜耶溪。
通塘在何处，远在寻阳西。
青萝袅袅挂烟树，白鹇处处聚沙堤。
石门中断平湖出，百丈金潭照云日。
何处沧浪垂钓翁，鼓棹渔歌趣非一。
相逢不相识，出没绕通塘。
浦边清水明素足，别有浣沙吴女郎。
行尽绿潭潭转幽，疑是武陵春碧流。
秦人鸡犬桃花里，将比通塘渠见羞。
通塘不忍别，十去九迟回。
偶逢佳境心已醉，忽有一鸟从天来。
月出青山送行子，四边苦竹秋声起。
长吟白雪望星河，双垂两足扬素波。
梁鸿德耀会稽日，宁知此中乐事多。','',''),('quantangshi-08229','赠孟浩然','李白','quantangshi','','卷9','吾爱孟夫子，风流天下闻。
红颜弃轩冕，白首卧松云。
醉月频中圣，迷花不事君。
高山安可仰，徒此揖清芬。','',''),('quantangshi-08230','赠从兄襄阳少府皓','李白','quantangshi','','卷9','结发未识事，所交尽豪雄。
却秦不受赏，击晋宁为功。
小节岂足言，退耕舂陵东。
归来无产业，生事如转蓬。
一朝乌裘敝，百镒黄金空。
弹劒徒激昂，出门悲路穷。
吾兄青云士，然诺闻诸公。
所以陈片言，片言贵情通。
棣华傥不接，甘与秋草同。','',''),('quantangshi-08231','淮海对雪赠傅霭','李白','quantangshi','','卷9','朔雪落吴天，从风渡溟渤。
海树成阳春，江沙浩明月。
兴从剡溪起，思绕梁园发。
寄君郢中歌，曲罢心断绝。','',''),('quantangshi-08232','赠徐安宜','李白','quantangshi','','卷9','白田见楚老，歌咏徐安宜。
制锦不择地，操刀良在兹。
清风动百里，惠化闻京师。
浮人若云归，耕种满郊岐。
川光净麦陇，日色明桑枝。
讼息但长啸，宾来或解颐。
青橙拂户牖，白水流园池。
游子滞安邑，怀恩未忍辞。
翳君树桃李，岁晚托深期。','',''),('quantangshi-08233','赠任城卢主簿','李白','quantangshi','','卷9','海鸟知天风，窜身鲁门东。
临觞不能饮，矫翼思凌空。
钟鼓不为乐，烟霜谁与同。
归飞未忍去，流泪谢鸳鸿。','',''),('quantangshi-08234','早秋赠裴十七仲堪','李白','quantangshi','','卷9','远海动风色，吹愁落天涯。
南星变大火，热气余丹霞。
光景不可回，六龙转天车。
荆人泣美玉，鲁叟悲匏瓜。
功业若梦里，抚琴发长嗟。
裴生信英迈，屈起多才华。
历抵海岱豪，结交鲁朱家。
复携两少女，艳色惊荷葩。
双歌入青云，但惜白日斜。
穷溟出宝贝，大泽饶龙蛇。
明主傥见收，烟霞路非赊。
时命若不会，归应炼丹砂。','',''),('quantangshi-08235','赠范金卿二首 一','李白','quantangshi','','卷9','君子枉清盼，不知东走迷。
离家来几月，络纬鸣中闺。
桃李君不言，攀花愿成蹊。
那能吐芳信，惠好相招携。
我有结绿珍，久藏浊水泥。
时人弃此物，乃与燕珉齐。
摭拭欲赠之，申眉路无梯。
辽东慙白豕，楚客羞山鸡。
徒有献芹心，终流泣玉啼。
祗应自索漠，留舌示山妻。','',''),('quantangshi-08236','赠范金卿二首 二','李白','quantangshi','','卷9','范宰不买名，弦歌对前楹。
为邦默自化，日觉冰壶清。
百里鸡犬静，千庐机杼鸣。
浮人少荡析，爱客多逢迎。
游子覩嘉政，因之听颂声。','',''),('quantangshi-08237','赠瑕丘王少府','李白','quantangshi','','卷9','皎皎鸾凤姿，飘飘神仙气。
梅生亦何事，来作南昌尉。
清风佐鸣琴，寂寞道为贵。
一见过所闻，操持难与羣。
毫挥鲁邑讼，目送瀛洲云。
我隐屠钓下，尔当玉石分。
无由接高论，空此仰清芬。','',''),('quantangshi-08238','东鲁见狄博通','李白','quantangshi','','卷9','去年别我向何处，有人传道游江东。
谓言挂席度沧海，却来应是无长风。','',''),('quantangshi-08239','见京兆韦参军量移东阳二首 一','李白','quantangshi','','卷9','潮水还归海，流人却到吴。
相逢问愁苦，泪尽日南珠。','',''),('quantangshi-08240','见京兆韦参军量移东阳二首 二','李白','quantangshi','','卷9','闻说金华渡，东连五百滩。
全胜若耶好，莫道此行难。
猨啸千溪合，松风五月寒。
他年一携手，摇艇入新安。','',''),('quantangshi-08241','赠丹阳横山周处士惟长','李白','quantangshi','','卷9','周子横山隐，开门临城隅。
连峯入户牖，胜概凌方壶。
时作白紵词，放歌丹阳湖。
水色傲溟渤，川光秀菰蒲。
当其得意时，心与天壤俱。
闲云随舒卷，安识身有无。
抱石耻献玉，沈泉笑探珠。
羽化如可作，相携上清都。','',''),('quantangshi-08242','玉真公主别馆苦雨赠卫尉张卿二首 一','李白','quantangshi','','卷9','秋坐金张馆，繁阴昼不开。
空烟迷雨色，萧飒望中来。
翳翳昏垫苦，沈沈忧恨催。
清秋何以慰，白酒盈吾杯。
吟咏思管乐，此人已成灰。
独酌聊自勉，谁贵经纶才。
弹劒谢公子，无鱼良可哀。','',''),('quantangshi-08243','玉真公主别馆苦雨赠卫尉张卿二首 二','李白','quantangshi','','卷9','苦雨思白日，浮云何由卷。
稷卨和天人，阴阳乃骄蹇。
秋霖剧倒井，昏雾横绝巘。
欲往咫尺涂，遂成山川限。
潨潨奔溜闻，浩浩惊波转。
泥沙塞中途，牛马不可辨。
饥从漂母食，闲缀羽陵简。
园家逢秋蔬，藜藿不满眼。
蟏蛸结思幽，蟋蟀伤褊浅。
厨竈无青烟，刀机生绿藓。
投筯解鷫鸘，换酒醉北堂。
丹徒布衣者，慷慨未可量。
何时黄金盘，一斛荐槟榔。
功成拂衣去，摇曳沧洲傍。','',''),('quantangshi-08244','赠韦祕书子春二首 一','李白','quantangshi','','卷9','谷口郑子真，躬耕在岩石。
高名动京师，天下皆籍籍。
斯人竟不起，云卧从所适。
苟无济代心，独善亦何益。
惟君家世者，偃息逢休明。
谈天信浩荡，说劒纷纵横。
谢公不徒然，起来为苍生。
祕书何寂寂，无乃羁豪英。
且复归碧山，安能恋金阙。
旧宅樵渔地，蓬蒿已应没。
却顾女几峯，胡颜见云月。','',''),('quantangshi-08245','赠韦祕书子春二首 二','李白','quantangshi','','卷9','徒为风尘苦，一官已白须。
气同万里合，访我来琼都。
披云覩青天，扪虱话良图。
留侯将绮里，出处未云殊。
终与安社稷，功成去五湖。','',''),('quantangshi-08246','赠韦侍御黄裳二首 一','李白','quantangshi','','卷9','太华生长松，亭亭凌霜雪。
天与百尺高，岂为微飙折。
桃李卖阳艳，路人行且迷。
春光扫地尽，碧叶成黄泥。
愿君学长松，慎勿作桃李。
受屈不改心，然后知君子。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-08247','赠韦侍御黄裳二首 二','李白','quantangshi','','卷9','见君乘骢马，知上太山道。
此地果摧轮，全身以为宝。
我如丰年玉，弃置秋田草。
但勖冰壶心，无为叹衰老。','',''),('quantangshi-08248','赠薛校书','李白','quantangshi','','卷9','我有吴越曲，无人知此音。
姑苏成蔓草，麋鹿空悲吟。
未夸观涛作，空郁钓鳌心。
举手谢东海，虚行归故林。','',''),('quantangshi-08249','赠何七判官昌浩','李白','quantangshi','','卷9','有时忽惆怅，匡坐至夜分。
平明空啸咤，思欲解世纷。
心随长风去，吹散万里云。
羞作济南生，九十诵古文。
不然拂劒起，沙漠收奇勋。
老死阡陌间，何因扬清芬。
夫子今管乐，英才冠三军。
终与同出处，岂将沮溺羣。','',''),('quantangshi-08250','读诸葛武侯传书怀赠长安崔少府叔封昆季','李白','quantangshi','','卷9','汉道昔云季，羣雄方战争。
霸图各未立，割据资豪英。
赤伏起颓运，卧龙得孔明。
当其南阳时，陇亩躬自耕。
鱼水三顾合，风云四海生。
武侯立岷蜀，壮志吞咸京。
何人先见许，但有崔州平。
余亦草间人，颇怀拯物情。
晚途值子玉，华发同衰荣。
托意在经济，结交为弟兄。
毋令管与鲍，千载独知名。','',''),('quantangshi-08251','赠郭将军','李白','quantangshi','','卷9','将军少年出武威，入掌银台护紫微。
平明拂劒朝天去，薄暮垂鞭醉酒归。
爱子临风吹玉笛，美人向月舞罗衣。
畴昔雄豪如梦里，相逢且欲醉春晖。','',''),('quantangshi-08252','驾去温泉后赠杨山人','李白','quantangshi','','卷9','少年落魄楚汉间，风尘萧瑟多苦颜。
自言管葛竟谁许，长吁莫错还闭关。
一朝君王垂拂拭，剖心输丹雪胸臆。
忽蒙白日回景光，直上青云生羽翼。
幸陪鸾辇出鸿都，身骑飞龙天马驹。
王公大人借颜色，金璋紫绶来相趋。
当时结交何纷纷，片言道合惟有君。
待吾尽节报明主，然后相携卧白云。','',''),('quantangshi-08253','温泉侍从归逢故人','李白','quantangshi','','卷9','汉帝长杨苑，夸胡羽猎归。
子云叨侍从，献赋有光辉。
激赏摇天笔，承恩赐御衣。
逢君奏明主，他日共飜飞。','',''),('quantangshi-08254','赠裴十四','李白','quantangshi','','卷9','朝见裴叔则，朗如行玉山。
黄河落天走东海，万里写入胸怀间。
身骑白鼋不敢度，金高南山买君顾。
裴回六合无相知，飘若浮云且西去。','',''),('quantangshi-08255','赠崔侍郎','李白','quantangshi','','卷9','黄河二尺鲤，本在孟津居。
点额不成龙，归来伴凡鱼。
故人东海客，一见借吹嘘。
风涛傥相见，更欲凌昆墟。','',''),('quantangshi-08256','述德兼陈情上哥舒大夫','李白','quantangshi','','卷9','天为国家孕英才，森森矛戟拥灵台。
浩荡深谋喷江海，纵横逸气走风雷。
丈夫立身有如此，一呼三军皆披靡。
卫青谩作大将军，白起真成一竖子。','',''),('quantangshi-08257','雪谗诗赠友人','李白','quantangshi','','卷9','嗟予沈迷，猖獗已久。
五十知非，古人尝有。
立言补过，庶存不朽。
包荒匿瑕，蓄此顽丑。
月出致讥，贻愧皓首。
感悟遂晚，事往日迁。
白璧何辜，青蝇屡前。
羣轻折轴，下沈黄泉。
众毛飞骨，上凌青天。
萋斐暗成，贝锦粲然。
泥沙聚埃，珠玉不鲜。
洪焰烁山，发自纤烟。
苍波荡日，起于微涓。
交乱四国，播于八埏。
拾尘掇蜂，疑圣猜贤。
哀哉悲夫！谁察予之贞坚。
彼妇人之猖狂，不如鹊之彊彊。
彼妇人之淫昏，不如鹑之奔奔。
坦荡君子，无悦簧言。
擢发续罪，罪乃孔多。
倾海流恶，恶无以过。
人生实难，逢此织罗。
积毁销金，沈忧作歌。
天未丧文，其如余何。
妲己灭纣，褒女惑周。
天维荡覆，职此之由。
汉祖吕氏，食其在傍。
秦皇太后，毐亦淫荒。
螮蝀作昏，遂掩太阳。
万乘尚尔，匹夫何伤。
辞殚意穷，心切理直。
如或妄谈，昊天是殛。
子野善听，离娄至明。
神靡遁响，鬼无逃形。
不我遐弃，庶昭忠诚。','',''),('quantangshi-08258','赠参寥子','李白','quantangshi','','卷9','白鹤飞天书，南荆访高士。
五云在岘山，果得参寥子。
肮脏辞故园，昂藏入君门。
天子分玉帛，百官接话言。
毫墨时洒落，探玄有奇作。
着论穷天人，千春祕麟阁。
长揖不受官，拂衣归林峦。
余亦去金马，藤萝同所欢。
相思在何处，桂树青云端。','',''),('quantangshi-08259','赠饶阳张司户燧','李白','quantangshi','','卷9','朝饮苍梧泉，夕栖碧海烟。
宁知鸾凤意，远托椅桐前。
慕蔺岂曩古，攀嵇是当年。
愧非黄石老，安识子房贤。
功业嗟落日，容华弃徂川。
一语已道意，三山期着鞭。
蹉跎人间世，寥落壶中天。
独见游物祖，探元穷化先。
何当共携手，相与排冥筌。','',''),('quantangshi-08260','赠清漳明府侄聿','李白','quantangshi','','卷9','我李百万叶，柯条布中州。
天开青云器，日为苍生忧。
小邑且割鸡，大刀伫烹牛。
雷声动四境，惠与清漳流。
弦歌咏唐尧，脱落隐簪组。
心和得天真，风俗犹太古。
牛羊散阡陌，夜寝不扃户。
问此何以然，贤人宰吾土。
举邑树桃李，垂阴亦流芬。
河堤绕绿水，桑柘连青云。
赵女不冶容，提笼昼成羣。
缲丝鸣机杼，百里声相闻。
讼息鸟下堦，高卧披道帙。
蒲鞭挂檐枝，示耻无扑抶。
琴清月当户，人寂风入室。
长啸无一言，陶然上皇逸。
白玉壶冰水，壶中见底清。
清光洞毫发，皎洁照羣情。
赵北美佳政，燕南播高名。
过客览行谣，因之诵德声。','',''),('quantangshi-08261','赠临洺县令皓弟','李白','quantangshi','','卷9','陶令去彭泽，茫然太古心。
大音自成曲，但奏无弦琴。
钓水路非远，连鳌意何深。
终期龙伯国，与尔相招寻。','',''),('quantangshi-08262','赠郭季鹰','李白','quantangshi','','卷9','河东郭有道，于世若浮云。
盛德无我位，清光独暎君。
耻将鸡并食，长与凤为羣。
一击九千仞，相期凌紫氛。','',''),('quantangshi-08263','邺中赠王大','李白','quantangshi','','卷9','一身竟无托，远与孤蓬征。
千里失所依，复将落叶并。
中途偶良朋，问我将何行。
欲献济时策，此心谁见明。
君王制六合，海塞无交兵。
壮士伏草间，沈忧乱纵横。
飘飘不得意，昨发南都城。
紫燕枥下嘶，青萍匣中鸣。
投躯寄天下，长啸寻豪英。
耻学琅琊人，龙蟠事躬耕。
富贵吾自取，建功及春荣。
我愿执尔手，尔方达我情。
相知同一己，岂惟弟与兄。
抱子弄白云，琴歌发清声。
临别意难尽，各希存令名。','',''),('quantangshi-08264','赠华州王司士','李白','quantangshi','','卷9','淮水不绝涛澜高，盛德未泯生英髦。
知君先负庙堂器，今日还须赠宝刀。','',''),('quantangshi-08265','赠卢征君昆弟','李白','quantangshi','','卷9','明主访贤逸，云泉今已空。
二卢竟不起，万乘高其风。
河上喜相得，壶中趣每同。
沧州即此地，观化游无穷。
水落海上清，鳌背覩方蓬。
与君弄倒景，携手凌星虹。','',''),('quantangshi-08266','赠新平少年','李白','quantangshi','','卷9','韩信在淮阴，少年相欺凌。
屈体若无骨，壮心有所凭。
一遭龙颜君，啸咤从此兴。
千金答漂母，万古共嗟称。
而我竟何为，寒苦坐相仍。
长风入短袂，两手如怀冰。
故友不相恤，新交宁见矜。
摧残槛中虎，羁绁韝上鹰。
何时腾风云，搏击申所能。','',''),('quantangshi-08267','赠崔侍郎','李白','quantangshi','','卷9','长劒一杯酒，男儿方寸心。
洛阳因剧孟，托宿话胸襟。
但仰山岳秀，不知江海深。
长安复携手，再顾重千金。
君乃輶轩佐，予叨翰墨林。
高风摧秀木，虚弹落惊禽。
不取回舟兴，而来命驾寻。
扶摇应借力，桃李愿成阴。
笑吐张仪舌，愁为庄舃吟。
谁怜明月夜，肠断听秋砧。','',''),('quantangshi-08268','走笔赠独孤驸马','李白','quantangshi','','卷9','都尉朝天跃马归，香风吹人花乱飞。
银鞍紫鞚照云日，左顾右盼生光辉。
是时仆在金门里，待诏公车谒天子。
长揖蒙垂国士恩，壮心剖出酬知己。
一别蹉跎朝市间，青云之交不可攀。
傥其公子重回顾，何必侯嬴长抱关。','',''),('quantangshi-08269','赠嵩山焦炼师','李白','quantangshi','','卷9','二室凌青天，三花含紫烟。
中有蓬海客，宛疑麻姑仙。
道在喧莫染，迹高想已绵。
时餐金鹅蘂，屡读青苔篇。
八极恣游憩，九垓长周旋。
下瓢酌颍水，舞鹤来伊川。
还归空山上，独拂秋霞眠。
萝月挂朝镜，松风鸣夜弦。
潜光隐嵩岳，炼魄栖云幄。
霓裳何飘颻，凤吹转緜邈。
愿同西王母，下顾东方朔。
紫书傥可传，铭骨誓相学。','',''),('quantangshi-08270','口号赠征君鸿','李白','quantangshi','','卷9','陶令辞彭泽，梁鸿入会稽。
我寻高士传，君与古人齐。
云卧留丹壑，天书降紫泥。
不知杨伯起，早晚向关西。','',''),('quantangshi-08271','上李邕','李白','quantangshi','','卷9','大鹏一日同风起，抟摇直上九万里。
假令风歇时下来，犹能簸却沧溟水。
世人见我恒殊调，闻余大言皆冷笑。
宣父犹能畏后生，丈夫未可轻年少。','',''),('quantangshi-08272','赠张公洲革处士','李白','quantangshi','','卷9','列子居郑圃，不将众庶分。
革侯遁南浦，常恐楚人闻。
抱瓮灌秋蔬，心闲游天云。
每将瓜田叟，耕种汉水濆。
时登张公洲，入兽不乱羣。
井无桔槔事，门绝刺绣文。
长揖二千石，远辞百里君。
斯为真隐者，吾党慕清芬。','',''),('quantangshi-08273','秋日炼药院镊白发赠元六兄林宗','李白','quantangshi','','卷9','木落识岁秋，瓶冰知天寒。
桂枝日已绿，拂雪凌云端。
弱龄接光景，矫翼攀鸿鸾。
投分三十载，荣枯同所欢。
长吁望青云，镊白坐相看。
秋颜入晓镜，壮发凋危冠。
穷与鲍生贾，饥从漂母餐。
时来极天人，道在岂吟叹。
乐毅方适赵，苏秦初说韩。
卷舒固在我，何事空摧残。','',''),('quantangshi-08274','书情题蔡舍人雄','李白','quantangshi','','卷9','尝高谢太傅，携妓东山门。
楚舞醉碧云，吴歌断清猨。
蹔因苍生起，谈笑安黎元。
余亦爱此人，丹霄冀飞飜。
遭逢圣明主，敢进兴亡言。
白璧竟何辜，青蝇遂成冤。
一朝去京国，十载客梁园。
猛犬吠九关，杀人愤精魂。
皇穹雪冤枉，白日开氛昏。
泰阶得夔龙，桃李满中原。
倒海索明月，凌山采芳荪。
愧无横草功，虚负雨露恩。
迹谢云台阁，心随天马辕。
夫子王佐才，而今复谁论。
层飙振六翮，不日思腾骞。
我纵五湖棹，烟涛恣崩奔。
梦钓子陵湍，英风缅犹存。
彼希客星隐，弱植不足援。
千里一回首，万里一长歌。
黄鹤不复来，清风愁奈何。
舟浮潇湘月，山倒洞庭波。
投汨笑古人，临濠得天和。
闲时田亩中，搔背牧鸡鹅。
别离解相访，应在武陵多。','',''),('quantangshi-08275','忆襄阳旧游赠马少府巨','李白','quantangshi','','卷9','昔为大堤客，曾上山公楼。
开牕碧嶂满，拂镜沧江流。
高冠佩雄劒，长揖韩荆州。
此地别夫子，今来思旧游。
朱颜君未老，白发我先秋。
壮志恐蹉跎，功名若云浮。
归心结远梦，落日悬春愁。
空思羊叔子，堕泪岘山头。','',''),('quantangshi-08276','对雪献从兄虞城宰','李白','quantangshi','','卷9','昨夜梁园里，弟寒兄不知。
庭前看玉树，肠断忆连枝。','',''),('quantangshi-08277','访道安陵遇盖还为余造真箓临别留赠','李白','quantangshi','','卷9','清水见白石，仙人识青童。
安陵盖夫子，十岁与天通。
悬河与微言，谈论安可穷。
能令二千石，抚背惊神聪。
挥毫赠新诗，高价掩山东。
至今平原客，感激慕清风。
学道北海仙，传书蘂珠宫。
丹田了玉阙，白日思云空。
为我草真箓，天人慙妙工。
七元洞豁落，八角辉星虹。
三灾荡璇玑，蛟龙翼微躬。
举手谢天地，虚无齐始终。
黄金满高堂，答荷难克充。
下笑世上士，沈魂北罗酆。
昔日万乘坟，今成一科蓬。
赠言若可重，实此轻华嵩。','',''),('quantangshi-08278','赠崔郎中宗之','李白','quantangshi','','卷9','胡雁拂海翼，翱翔鸣素秋。
惊云辞沙朔，飘荡迷河洲。
有如飞蓬人，去逐万里游。
登高望浮云，彷佛如旧丘。
日从海傍没，水向天边流。
长啸倚孤劒，目极心悠悠。
岁晏归去来，富贵安可求。
仲尼七十说，历聘莫见收。
鲁连逃千金，圭组岂可酬。
时哉苟不会，草木为我俦。
希君同携手，长往南山幽。','',''),('quantangshi-08279','赠崔谘议','李白','quantangshi','','卷9','绿骥本天马，素非伏枥驹。
长嘶向清风，倏忽凌九区。
何言西北至，却走东南隅。
世道有飜覆，前期难豫图。
希君一翦拂，犹可骋中衢。','',''),('quantangshi-08280','赠升州王使君忠臣','李白','quantangshi','','卷9','六代帝王国，三吴佳丽城。
贤人当重寄，天子借高名。
巨海一边静，长江万里清。
应须救赵策，未肯弃侯嬴。','',''),('quantangshi-08281','赠别从甥高五','李白','quantangshi','','卷9','鱼目高泰山，不如一璵璠。
贤甥即明月，声价动天门。
能成吾宅相，不减魏阳元。
自顾寡筹略，功名安所存。
五木思一掷，如绳系穷猨。
枥中骏马空，堂上醉人喧。
黄金久已罄，为报故交恩。
闻君陇西行，使我惊心魂。
与尔共飘颻，云天各飞飜。
江水流或卷，此心难具论。
贫家羞好客，语拙觉辞繁。
三朝空错莫，对饭却惭冤。
自笑我非夫，生事多契阔。
蓄积万古愤，向谁得开豁。
天地一浮云，此身乃毫末。
忽见无端倪，太虚可包括。
去去何足道，临岐空复愁。
肝胆不楚越，山河亦衾裯。
云龙若相从，明主会见收。
成功解相访，溪水桃花流。','',''),('quantangshi-08282','赠裴司马','李白','quantangshi','','卷9','翡翠黄金缕，绣成歌舞衣。
若无云间月，谁可比光辉。
秀色一如此，多为众女讥。
君恩移昔爱，失宠秋风归。
愁苦不窥隣，泣上流黄机。
天寒素手冷，夜长烛复微。
十日不满匹，鬓蓬乱若丝。
犹是可怜人，容华世中稀。
向君发皓齿，顾我莫相违。','',''),('quantangshi-08283','叙旧赠江阳宰陆调','李白','quantangshi','','卷9','泰伯让天下，仲雍扬波涛。
清风荡万古，迹与星辰高。
开吴食东溟，陆氏世英髦。
多君秉古节，岳立冠人曹。
风流少年时，京洛事游遨。
腰间延陵劒，玉带明珠袍。
我昔鬬鸡徒，连延五陵豪。
邀遮相组织，呵吓来煎熬。
君开万丛人，鞍马皆辟易。
告急清宪台，脱余北门厄。
间宰江阳邑，翦棘树兰芳。
城门何肃穆，五月飞秋霜。
好鸟集珍木，高才列华堂。
时从府中归，丝管俨成行。
但苦隔远道，无由共衔觞。
江北荷花开，江南杨梅熟。
正好饮酒时，怀贤在心目。
挂席拾海月，乘风下长川。
多沽新丰醁，满载剡溪船。
中途不遇人，直到尔门前。
大笑同一醉，取乐平生年。','',''),('quantangshi-08284','赠从孙义兴宰铭','李白','quantangshi','','卷9','天子思茂宰，天枝得英才。
朗然清秋月，独出映吴台。
落笔生绮绣，操刀振风雷。
蠖屈虽百里，鹏骞望三台。
退食无外事，琴堂向山开。
绿水寂以闲，白云有时来。
河阳富奇藻，彭泽纵名杯。
所恨不见之，犹如仰昭回。
元恶昔滔天，疲人散幽草。
惊川无活鳞，举邑罕遗老。
誓雪会稽耻，将奔宛陵道。
亚相素所重，投刃应桑林。
独坐伤激扬，神融一开襟。
弦歌欣再理，和乐醉人心。
蠹政除害马，倾巢有归禽。
壶浆候君来，聚舞共讴吟。
农人弃簔笠，蚕女堕缨簪。
欢笑相拜贺，则知惠爱深。
历职吾所闻，称贤尔为最。
化洽一邦上，名驰三江外。
峻节贯云霄，通方堪远大。
能文变风俗，好客留轩盖。
他日一来游，因之严光濑。','',''),('quantangshi-08285','草创大还赠柳官迪','李白','quantangshi','','卷9','天地为橐龠，周流行太易。
造化合元符，交媾腾精魄。
自然成妙用，孰知其指的。
罗络四季间，绵微无一隙。
日月更出没，双光岂云只。
姹女乘河车，黄金充辕轭。
执枢相管辖，摧伏伤羽翮。
朱鸟张炎威，白虎守本宅。
相煎成苦老，消铄凝津液。
仿髴明窗尘，死灰同至寂。
捣冶入赤色，十二周律历。
赫然称大还，与道本无隔。
白日可抚弄，清都在咫尺。
北酆落死名，南斗上生籍。
抑予是何者，身在方士格。
才术信纵横，世途自轻掷。
吾求仙弃俗，君晓损胜益。
不向金阙游，思为玉皇客。
鸾车速风电，龙骑无鞭策。
一举上九天，相携同所适。','',''),('quantangshi-08286','赠崔司户文昆季','李白','quantangshi','','卷9','双珠出海底，俱是连城珍。
明月两特达，余辉傍照人。
英声振名都，高价动殊邻。
岂伊箕山故，特以风期亲。
惟昔不自媒，担簦西入秦。
攀龙九天上，忝列岁星臣。
布衣侍丹墀，密勿草丝纶。
才微惠渥重，谗巧生缁磷。
一去已十载，今来复盈旬。
清霜入晓鬓，白露生衣巾。
侧见绿水亭，开门列华茵。
千金散义士，四坐无凡宾。
欲折月中桂，持为寒者薪。
路傍已窃笑，天路将何因。
垂恩傥丘山，报德有微身。','',''),('quantangshi-08287','赠溧阳宋少府陟','李白','quantangshi','','卷9','李斯未相秦，且逐东门兔。
宋玉事襄王，能为高唐赋。
常闻绿水曲，忽此相逢遇。
扫洒青天开，豁然披云雾。
葳甤紫鸾鸟，巢在昆山树。
惊风西北吹，飞落南溟去。
早怀经济策，特受龙颜顾。
白玉栖青蝇，君臣忽行路。
人生感分义，贵欲呈丹素。
何日清中原，相期廓天步。','',''),('quantangshi-08288','戏赠郑溧阳','李白','quantangshi','','卷9','陶令日日醉，不知五柳春。
素琴本无弦，漉酒用葛巾。
清风北牕下，自谓羲皇人。
何时到栗里，一见平生亲。','',''),('quantangshi-08289','赠僧崖公','李白','quantangshi','','卷9','昔在朗陵东，学禅白眉空。
大地了镜彻，回旋寄轮风。
揽彼造化力，持为我神通。
晚谒泰山君，亲见日没云。
中夜卧山月，拂衣逃人羣。
授余金仙道，旷劫未始闻。
冥机发天光，独朗谢垢氛。
虚舟不系物，观化游江濆。
江濆遇同声，道崖乃僧英。
说法动海岳，游方化公卿。
手秉玉麈尾，如登白楼亭。
微言注百川，亹亹信可听。
一风鼓羣有，万籁各自鸣。
启闭八牕牖，托宿掣电霆。
自言历天台，搏壁蹑翠屏。
凌兢石桥去，恍惚入青冥。
昔往今来归，绝景无不经。
何日更携手，乘杯向蓬瀛。','',''),('quantangshi-08290','游溧阳北湖亭望瓦屋山怀古赠同旅','李白','quantangshi','','卷9','朝登北湖亭，遥望瓦屋山。
天清白露下，始觉秋风还。
游子托主人，仰观眉睫间。
目色送飞鸿，邈然不可攀。
长吁相劝勉，何事来吴关。
闻有贞义女，振穷溧水湾。
清光了在眼，白日如披颜。
高坟五六墩，崒兀栖猛虎。
遗迹翳九泉，芳名动千古。
子胥昔乞食，此女倾壶浆。
运开展宿愤，入楚鞭平王。
凛冽天地间，闻名若怀霜。
壮夫或未达，十步九太行。
与君拂衣去，万里同翱翔。','',''),('quantangshi-08291','醉后赠从甥高镇','李白','quantangshi','','卷9','马上相逢揖马鞭，客中相见客中怜。
欲邀击筑悲歌饮，正值倾家无酒钱。
江东风光不借人，枉杀落花空自春。
黄金逐手快意尽，昨日破产今朝贫。
丈夫何事空啸傲，不如烧却头上巾。
君为进士不得进，我被秋霜生旅鬓。
时清不及英豪人，三尺童儿重廉蔺。
匣中盘劒装䱜鱼，闲在腰间未用渠。
且将换酒与君醉，醉归托宿吴专诸。','',''),('quantangshi-08292','崔秋浦柳少府','李白','quantangshi','','卷9','秋浦旧萧索，公庭人吏稀。
因君树桃李，此地忽芳菲。
摇笔望白云，开帘当翠微。
时来引山月，纵酒酣清晖。
而我爱夫子，淹留未忍归。','',''),('quantangshi-08293','赠崔秋浦三首 一','李白','quantangshi','','卷9','吾爱崔秋浦，宛然陶令风。
门前五杨柳，井上二梧桐。
山鸟下厅事，檐花落酒中。
怀君未忍去，惆怅意无穷。','',''),('quantangshi-08294','赠崔秋浦三首 二','李白','quantangshi','','卷9','崔令学陶令，北牕常昼眠。
抱琴时弄月，取意任无弦。
见客但倾酒，为官不爱钱。
东臯春事起，种黍早归田。','',''),('quantangshi-08295','赠崔秋浦三首 三','李白','quantangshi','','卷9','河阳花作县，秋浦玉为人。
地逐名贤好，风随惠化春。
水从天汉落，山逼画屏新。
应念金门客，投沙吊楚臣。','',''),('quantangshi-08296','望九华赠青阳韦仲堪','李白','quantangshi','','卷9','昔在九江上，遥望九华峰。
天河挂绿水，秀出九芙蓉。
我欲一挥手，谁人可相从。
君为东道主，于此卧云松。','',''),('quantangshi-08297','赠王判官时余归隐居庐山屏风叠','李白','quantangshi','','卷9','昔别黄鹤楼，蹉跎淮海秋。
俱飘零落叶，各散洞庭流。
中年不相见，蹭蹬游吴越。
何处我思君，天台绿萝月。
会稽风月好，却遶剡溪回。
云山海上出，人物镜中来。
一度浙江北，十年醉楚台。
荆门倒屈宋，梁苑倾邹枚。
苦笑我夸诞，知音安在哉。
大盗割鸿沟，如风扫秋叶。
吾非济代人，且隐屏风叠。
中夜天中望，忆君思见君。
明朝拂衣去，永与海鸥羣。','',''),('quantangshi-08298','在水军宴赠幕府诸侍御','李白','quantangshi','','卷9','月化五白龙，翻飞凌九天。
胡沙惊北海，电扫洛阳川。
虏箭雨宫阙，皇舆成播迁。
英王受庙略，秉钺清南边。
云旗卷海雪，金戟罗江烟。
聚散百万人，弛张在一贤。
霜台降羣彦，水国奉戎旃。
绣服开宴语，天人借楼船。
如登黄金台，遥谒紫霞仙。
卷身编蓬下，冥机四十年。
宁知草间人，腰下有龙泉。
浮云在一决，誓欲清幽燕。
愿与四座公，静谈金匮篇。
齐心戴朝恩，不惜微躯捐。
所冀旄头灭，功成追鲁连。','',''),('quantangshi-08299','赠武十七谔并序','李白','quantangshi','','卷9','马如一匹练，明日过吴门。
乃是要离客，西来欲报恩。
笑开燕匕首，拂拭竟无言。
狄犬吠清洛，天津成塞垣。
爱子隔东鲁，空悲断肠猨。
林回弃白璧，千里阻同奔。
君为我致之，轻赍涉淮原。
精诚合天道，不愧远游魂。','',''),('quantangshi-08300','赠闾丘宿松','李白','quantangshi','','卷9','阮籍为太守，乘驴上东平。
剖竹十日间，一朝风化清。
偶来拂衣去，谁测主人情。
夫子理宿松，浮云知古城。
扫地物莽然，秋来百草生。
飞鸟还旧巢，迁人返躬耕。
何慙宓子贱，不减陶渊明。
吾知千载后，却掩二贤名。','',''),('quantangshi-08301','狱中上崔相涣','李白','quantangshi','','卷9','胡马渡洛水，血流征战场。
千门闭秋景，万姓危朝霜。
贤相燮元气，再欣海县康。
台庭有夔龙，列宿粲成行。
羽翼三元圣，发辉两太阳。
应念覆盆下，雪泣拜天光。','',''),('quantangshi-08302','中丞宋公以吴兵三千赴河南军次寻阳脱余之囚参谋幕府因赠之','李白','quantangshi','','卷9','独坐清天下，专征出海隅。
九江皆渡虎，三郡尽还珠。
组练明秋浦，楼船入郢都。
风高初选将，月满欲平胡。
杀气横千里，军声动九区。
白猨慙劒术，黄石借兵符。
戎虏行当翦，鲸鲵立可诛。
自怜非剧孟，何以佐良图。','',''),('quantangshi-08303','流夜郎赠辛判官','李白','quantangshi','','卷9','昔在长安醉花柳，五侯七贵同杯酒。
气岸遥凌豪士前，风流肯落他人后。
夫子红颜我少年，章台走马着金鞭。
文章献纳麒麟殿，歌舞淹留玳瑁筵。
与君自谓长如此，宁知草动风尘起。
函谷忽惊胡马来，秦宫桃李向明开。
我愁远谪夜郎去，何日金鸡放赦回。','',''),('quantangshi-08304','赠刘都使','李白','quantangshi','','卷9','东平刘公干，南国秀余芳。
一鸣即朱绂，五十佩银章。
饮冰事戎幕，衣锦华水乡。
铜官几万人，诤讼清玉堂。
吐言贵珠玉，落笔回风霜。
而我谢明主，衔哀投夜郎。
归家酒债多，门客粲成行。
高谈满四座，一日倾千觞。
所求竟无绪，裘马欲摧藏。
主人若不顾，明发钓沧浪。','',''),('quantangshi-08305','赠常侍御','李白','quantangshi','','卷9','安石在东山，无心济天下。
一起振横流，功成复潇洒。
大贤有卷舒，季叶轻风雅。
匡复属何人，君为知音者。
传闻武安将，气振长平瓦。
燕赵期洗清，周秦保宗社。
登朝若有言，为访南迁贾。','',''),('quantangshi-08306','赠易秀才','李白','quantangshi','','卷9','少年解长劒，投赠即分离。
何不断犀象，精光暗往时。
蹉跎君自惜，窜逐我因谁。
地远虞翻老，秋深宋玉悲。
空摧芳桂色，不屈古松姿。
感激平生意，劳歌寄此辞。','',''),('quantangshi-08307','经乱离后天恩流夜郎忆旧游书怀赠江夏韦太守良宰','李白','quantangshi','','卷9','天上白玉京，十二楼五城。
仙人抚我顶，结发受长生。
误逐世间乐，颇穷理乱情。
九十六圣君，浮云挂空名。
天地赌一掷，未能望战争。
试涉霸王略，将期轩冕荣。
时命乃大谬，弃之海上行。
学劒翻自哂，为文竟何成。
劒非万人敌，文窃四海声。
儿戏不足道，五噫出西京。
临当欲去时，慷慨泪沾缨。
叹君倜傥才，标举冠羣英。
开筵引祖帐，慰此远徂征。
鞍马若浮云，送余骠骑亭。
歌钟不尽意，白日落昆明。
十月到幽州，戈鋋若罗星。
君王弃北海，扫地借长鲸。
呼吸走百川，燕然可摧倾。
心知不得语，却欲栖蓬瀛。
弯弧惧天狼，挟矢不敢张。
揽涕黄金台，呼天哭昭王。
无人贵骏骨，騄耳空腾骧。
乐毅傥再生，于今亦奔亡。
蹉跎不得意，驱马还贵乡。
逢君听弦歌，肃穆坐华堂。
百里独太古，陶然卧羲皇。
征乐昌乐馆，开筵列壶觞。
贤豪间青娥，对烛俨成行。
醉舞纷绮席，清歌绕飞梁。
欢娱未终朝，秩满归咸阳。
祖道拥万人，供帐遥相望。
一别隔千里，荣枯异炎凉。
炎凉几度改，九土中横溃。
汉甲连胡兵，沙尘暗云海。
草木摇杀气，星辰无光彩。
白骨成丘山，苍生竟何罪。
函关壮帝居，国命悬哥舒。
长戟三十万，开门纳凶渠。
公卿如犬羊，忠谠醢与葅。
二圣出游豫，两京遂丘墟。
帝子许专征，秉旄控强楚。
节制非桓文，军师拥熊虎。
人心失去就，贼势腾风雨。
惟君固房陵，诚节冠终古。
仆卧香炉顶，餐霞漱瑶泉。
门开九江转，枕下五湖连。
半夜水军来，浔阳满旌旃。
空名适自误，迫胁上楼船。
徒赐五百金，弃之若浮烟。
辞官不受赏，飜谪夜郎天。
夜郎万里道，西上令人老。
扫荡六合清，仍为负霜草。
日月无偏照，何由诉苍昊。
良牧称神明，深仁恤交道。
一忝青云客，三登黄鹤楼。
顾慙禰处士，虚对鹦鹉洲。
樊山霸气尽，寥落天地秋。
江带峨眉雪，川横三峡流。
万舸此中来，连帆过扬州。
送此万里目，旷然散我愁。
纱窗倚天开，水树绿如发。
窥日畏衔山，促酒喜得月。
吴娃与越艳，窈窕夸铅红。
呼来上云梯，含笑出帘栊。
对客小垂手，罗衣舞春风。
宾跪请休息，主人情未极。
览君荆山作，江鲍堪动色。
清水出芙蓉，天然去雕饰。
逸兴横素襟，无时不招寻。
朱门拥虎士，列戟何森森。
剪凿竹石开，萦流涨清深。
登台坐水阁，吐论多英音。
片辞贵白壁，一诺轻黄金。
谓我不愧君，青鸟明丹心。
五色云间鹊，飞鸣天上来。
传闻赦书至，却放夜郎回。
暖气变寒谷，炎烟生死灰。
君登凤池去，忽弃贾生才。
桀犬尚吠尧，匈奴笑千秋。
中夜四五叹，常为大国忧。
旌斾夹两山，黄河当中流。
连鸡不得进，饮马空夷犹。
安得羿善射，一箭落旄头。','',''),('quantangshi-08308','江夏使君叔席上赠史郎中','李白','quantangshi','','卷9','凤凰丹禁里，衔出紫泥书。
昔放三湘去，今还万死余。
仙郎久为别，客舍问何如。
涸辙思流水，浮云失旧居。
多慙华省贵，不以逐臣疎。
复如竹林下，叨陪芳宴初。
希君生羽翼，一化北溟鱼。','',''),('quantangshi-08309','博平郑太守自庐山千里相寻入江夏北市门见访却之武陵立马赠别','李白','quantangshi','','卷9','大梁贵公子，气盖苍梧云。
若无三千客，谁道信陵君。
救赵复存魏，英威天下闻。
邯郸能屈节，访博从毛薛。
夷门得隐沦，而与侯生亲。
仍要鼓刀者，乃是袖槌人。
好士不尽心，何能保其身。
多君重然诺，意气遥相托。
五马入市门，金鞍照城郭。
都忘虎竹贵，且与荷衣乐。
去去桃花源，何时见归轩。
相思无终极，肠断朗江猨。','',''),('quantangshi-08310','江上赠窦长史','李白','quantangshi','','卷9','汉求季布鲁朱家，楚逐伍胥去章华。
万里南迁夜郎国，三年归及长风沙。
闻道青云贵公子，锦帆游戏西江水。
人疑天上坐楼船，水净霞明两重绮。
相约相期何太深，棹歌摇艇月中寻。
不同珠履三千客，别欲论交一片心。','',''),('quantangshi-08311','赠王汉阳','李白','quantangshi','','卷9','天落白玉棺，王乔辞叶县。
一去未千年，汉阳复相见。
犹乘飞凫舃，尚识仙人面。
鬓发何青青，童颜皎如练。
吾曾弄海水，清浅嗟三变。
果惬麻姑言，时光速流电。
与君数杯酒，可以穷欢宴。
白云归去来，何事坐交战。','',''),('quantangshi-08312','赠汉阳辅录事二首 一','李白','quantangshi','','卷9','闻君罢官意，我抱汉川湄。
借问久疎索，何如听讼时。
天清江月白，心静海鸥知。
应念投沙客，空余吊屈悲。','',''),('quantangshi-08313','赠汉阳辅录事二首 二','李白','quantangshi','','卷9','鹦鹉洲横汉阳渡，水引寒烟没江树。
南浦登楼不见君，君今罢官在何处？
汉口双鱼白锦鳞，令传尺素报情人。
其中字数无多少，祗是相思秋复春。','',''),('quantangshi-08314','江夏赠韦南陵冰','李白','quantangshi','','卷9','胡骄马惊沙尘起，胡雏饮马天津水。
君为张掖近酒泉，我窜三巴九千里。
天地再新法令宽，夜郎迁客带霜寒。
西忆故人不可见，东风吹梦到长安。
宁期此地忽相遇，惊喜茫如堕烟雾。
玉箫金管喧四筵，苦心不得申长句。
昨日绣衣倾绿尊，病如桃李竟何言。
昔骑天子大宛马，今乘款段诸侯门。
赖遇南平豁方寸，复兼夫子持清论。
有似山开万里云，四望青天解人闷。
人闷还心闷，苦辛长苦辛。
愁来饮酒二千石，寒灰重暖生阳春。
山公醉后能骑马，别是风流贤主人。
头陀云月多僧气，山水何曾称人意。
不然鸣笳按鼓戏沧流，呼取江南女儿歌棹讴。
我且为君槌碎黄鹤楼，君亦为吾倒却鹉鹦洲。
赤壁争雄如梦里，且须歌舞宽离忧。','',''),('quantangshi-08315','赠卢司户','李白','quantangshi','','卷9','秋色无远近，出门尽寒山。
白云遥相识，待我苍梧间。
借问卢耽鹤，西飞几岁还。','',''),('quantangshi-08316','赠从弟南平太守之遥二首 一','李白','quantangshi','','卷9','少年不得意，落魄无安居。
愿随任公子，欲钓吞舟鱼。
常时饮酒逐风景，壮心遂与功名疎。
兰生谷底人不锄，云在高山空卷舒。
汉家天子驰驷马，赤军蜀道迎相如。
天门九重谒圣人，龙颜一解四海春。
彤庭左右呼万岁，拜贺明主收沈沦。
翰林秉笔回英眄，麟阁峥嵘谁可见。
承恩初入银台门，着书独在金銮殿。
龙钩雕镫白玉鞍，象牀绮席黄金盘。
当时笑我微贱者，却来请谒为交欢。
一朝谢病游江海，畴昔相知几人在。
前门长揖后门关，今日结交明日改。
爱君山岳心不移，随君云雾迷所为。
梦得池塘生春草，使我长价登楼诗。
别后遥传临海作，可见羊何共和之。','',''),('quantangshi-08317','赠从弟南平太守之遥二首 二','李白','quantangshi','','卷9','东平与南平，今古两步兵。
素心爱美酒，不是顾专城。
谪官桃源去，寻花几处行。
秦人如旧识，出户笑相迎。','',''),('quantangshi-08318','赠潘侍御论钱少阳','李白','quantangshi','','卷9','绣衣柱史何昂藏，铁冠白笔横秋霜。
三军论事多引纳，堦前虎士罗干将。
虽无二十五老者，且有一翁钱少阳。
眉如松雪齐四皓，调笑可以安储皇。
君能礼此最下士，九州拭目瞻清光。','',''),('quantangshi-08319','赠柳圆','李白','quantangshi','','卷9','竹实满秋浦，凤来何苦饥。
还同月下鹊，三绕未安枝。
夫子即琼树，倾柯拂羽仪。
怀君恋明德，归去日相思。','',''),('quantangshi-08320','流夜郎半道承恩放还兼欣克复之美书怀示息秀才','李白','quantangshi','','卷9','黄口为人罗，白龙乃鱼服。
得罪岂怨天，以愚陷网目。
鲸鲵未翦灭，豺狼屡翻覆。
悲作楚地囚，何日秦庭哭。
遭逢二明主，前后两迁逐。
去国愁夜郎，投身窜荒谷。
半道雪屯蒙，旷如鸟出笼。
遥欣克复美，光武安可同。
天子巡劒阁，储皇守扶风。
扬袂正北辰，开襟揽羣雄。
胡兵出月窟，雷破关之东。
左扫因右拂，旋收洛阳宫。
回舆入咸京，席卷六合通。
叱咤开帝业，手成天地功。
大驾还长安，两日忽再中。
一朝让宝位，劒玺传无穷。
愧无秋豪力，谁念矍铄翁。
弋者何所慕，高飞仰冥鸿。
弃劒学丹砂，临炉双玉童。
寄言息夫子，岁晚陟方蓬。','',''),('quantangshi-08321','赠张相镐二首 一','李白','quantangshi','','卷9','神器难窃弄，天狼窥紫宸。
六龙迁白日，四海暗胡尘。
昊穹降元宰，君子方经纶。
澹然养浩气，歘起持大钧。
秀骨象山岳，英谋合鬼神。
佐汉解鸿门，生唐为后身。
拥旄秉金钺，伐鼓乘朱轮。
虎将如雷霆，总戎向东巡。
诸侯拜马首，猛士骑鲸鳞。
泽被鱼鸟悦，令行草木春。
圣智不失时，建功及良辰。
丑虏安足纪，可贻帼与巾。
倒泻溟海珠，尽为入幕珍。
冯异献赤伏，邓生倏来臻。
庶同昆阳举，再覩汉仪新。
昔为管将鲍，中奔吴隔秦。
一生欲报主，百代思荣亲。
其事竟不就，哀哉难重陈。
卧病宿松山，苍茫空四邻。
风云激壮志，枯槁惊常伦。
闻君自天来，目张气益振。
亚夫得剧孟，敌国空无人。
扪虱对桓公，愿得论悲辛。
大块方噫气，何辞鼓青苹。
斯言傥不合，归老汉江滨。','',''),('quantangshi-08322','赠张相镐二首 二','李白','quantangshi','','卷9','本家陇西人，先为汉边将。
功略葢天地，名飞青云上。
苦战竟不侯，富年颇惆怅。
世传崆峒勇，气激金风壮。
英烈遗厥孙，百代神犹王。
十五观奇书，作赋凌相如。
龙颜惠殊宠，麟阁凭天居。
晚途未云已，蹭蹬遭谗毁。
想像晋末时，崩腾胡尘起。
衣冠陷锋镝，戎虏盈朝市。
石勒窥神州，刘聪劫天子。
抚劒夜吟啸，雄心日千里。
誓欲斩鲸鲵，澄清洛阳水。
六合洒霖雨，万物无雕枯。
我挥一杯水，自笑何区区。
因人耻成事，贵欲决良图。
灭虏不言功，飘然陟蓬壶。
惟有安期舃，留之沧海隅。','',''),('quantangshi-08323','闻谢杨儿吟猛虎词因此有赠','李白','quantangshi','','卷9','同州隔秋浦，闻吟猛虎词。
晨朝来借问，知是谢杨儿。','',''),('quantangshi-08324','宿清溪主人','李白','quantangshi','','卷9','夜到清溪宿，主人碧岩里。
檐楹挂星斗，枕席响风水。
月落西山时，啾啾夜猨起。','',''),('quantangshi-08325','系寻阳上崔相涣三首 一','李白','quantangshi','','卷9','邯郸四十万，同日陷长平。
能回造化笔，或冀一人生。','',''),('quantangshi-08326','系寻阳上崔相涣三首 二','李白','quantangshi','','卷9','毛遂不堕井，曾参宁杀人。
虚言误公子，投杼惑慈亲。
白璧双明月，方知一玉真。','',''),('quantangshi-08327','系寻阳上崔相涣三首 三','李白','quantangshi','','卷9','虚传一片雨，枉作阳台神。
纵为梦里相随去，不是襄王倾国人。','',''),('quantangshi-08328','巴陵赠贾舍人','李白','quantangshi','','卷9','贾生西望忆京华，湘浦南迁莫怨嗟。
圣主恩深汉文帝，怜君不遣到长沙。','',''),('quantangshi-08329','赠别舍人弟台卿之江南','李白','quantangshi','','卷9','去国客行远，还山秋梦长。
梧桐落金井，一叶飞银牀。
觉罢揽明镜，鬓毛飒已霜。
良图委蔓草，古貌成枯桑。
欲道心下事，时人疑夜光。
因为洞庭叶，飘落之潇湘。
令弟经济士，谪居我何伤。
潜虬隐尺水，着论谈兴亡。
客遇王子乔，口传不死方。
入洞过天地，登真朝玉皇。
吾将抚尔背，挥手遂翱翔。','',''),('quantangshi-08330','醉后赠王历阳','李白','quantangshi','','卷9','书秃千兔毫，诗裁两牛腰。
笔踪起龙虎，舞袖拂云霄。
双歌二胡姬，更奏远清朝。
举酒挑朔雪，从君不相饶。','',''),('quantangshi-08331','赠历阳褚司马','李白','quantangshi','','卷9','北堂千万寿，侍奉有光辉。
先同稚子舞，更着老莱衣。
因为小儿啼，醉倒月下归。
人闻无此乐，此乐世中稀。','',''),('quantangshi-08332','对雪醉后赠王历阳','李白','quantangshi','','卷9','有身莫犯飞龙鳞，有手莫辫猛虎须。
君看昔日汝南市，白头仙人隐玉壶。
子猷闻风动窻竹，相邀共醉杯中绿。
历阳何异山阴时，白雪飞花乱人目。
君家有酒我何愁，客多乐酣秉烛游。
谢尚自能鸜鹆舞，相如免脱鷫鸘裘。
清晨鼓棹过江去，千里相思明月楼。','',''),('quantangshi-08333','赠宣城宇文太守兼呈崔侍御','李白','quantangshi','','卷9','白若白鹭鲜，清如清唳蝉。
受气有本性，不为外物迁。
饮水箕山上，食雪首阳颠。
回车避朝歌，掩口去盗泉。
岧峣广成子，倜傥鲁仲连。
卓绝二公外，丹心无间然。
昔攀六龙飞，今作百炼铅。
怀恩欲报主，投佩向北燕。
弯弓绿弦开，满月不惮坚。
闲骑骏马猎，一射两虎穿。
回旋若流光，转背落双鸢。
胡虏三叹息，兼知五兵权。
枪枪突云将，却掩我之妍。
多逢剿绝儿，先着祖生鞭。
据鞍空矍铄，壮志竟谁宣。
蹉跎复来归，忧恨坐相煎。
无风难破浪，失计长江边。
危苦惜颓光，金波忽三圆。
时游敬亭上，闲听松风眠。
或弄宛溪月，虚舟信洄沿。
颜公二十万，尽付酒家钱。
兴发每取之，聊向醉中仙。
过此无一事，静谈秋水篇。
君从九卿来，水国有丰年。
鱼盐满市井，布帛如云烟。
下马不作威，冰壶照清川。
霜眉邑中叟，皆美太守贤。
时时慰风俗，往往出东田。
竹马数小儿，拜迎白鹿前。
含笑问使君，日晚可回旋。
遂归池上酌，掩抑清风弦。
曾标横浮云，下抚谢朓肩。
楼高碧海出，树古青萝悬。
光禄紫霞杯，伊昔忝相传。
良图扫沙漠，别梦绕旌旃。
富贵日成疎，愿言杳无缘。
登龙有直道，倚玉阻芳筵。
敢献绕朝策，思同郭泰船。
何言一水浅，似隔九重天。
崔生何傲岸，纵酒复谈玄。
身为名公子，英才苦迍邅。
鸣凤托高梧，凌风何翩翩。
安知慕羣客，弹劒拂秋莲。','',''),('quantangshi-08334','赠宣城赵太守悦','李白','quantangshi','','卷9','赵得宝符盛，山河功业存。
三千堂上客，出入拥平原。
六国扬清风，英声何喧喧。
大贤茂远业，虎竹光南藩。
错落千丈松，虬龙盘古根。
枝下无俗草，所植唯兰荪。
忆在南阳时，始承国士恩。
公为柱下史，脱绣归田园。
伊昔簪白笔，幽都逐游魂。
持斧冠三军，霜清天北门。
差池宰两邑，鹗立重飞翻。
焚香入兰台，起草多芳言。
夔龙一顾重，矫翼凌翔鵷。
赤县扬雷声，彊项闻至尊。
惊飙颓秀木，迹屈道弥敦。
出牧历三郡，所居猛兽奔。
迁人同卫鹤，谬上懿公轩。
自笑东郭履，侧慙狐白温。
闲吟步竹石，精义忘朝昏。
顦顇成丑士，风云何足论。
狝猴骑土牛，羸马夹双辕。
愿借羲皇景，为人照覆盆。
溟海不振荡，何由纵鹏鲲。
所期玄津白，倜傥假腾骞。','',''),('quantangshi-08335','赠从弟宣州长史昭','李白','quantangshi','','卷9','淮南望江南，千里碧山对。
我行倦过之，半落青天外。
宗英佐雄郡，水陆相控带。
长川豁中流，千里泻吴会。
君心亦如此，包纳无小大。
摇笔起风霜，推诚结仁爱。
讼庭垂桃李，宾馆罗轩盖。
何意苍梧云，飘然忽相会。
才将圣不偶，命与时俱背。
独立山海间，空老圣明代。
知音不易得，抚劒增感慨。
当结九万期，中途莫先退。','',''),('quantangshi-08336','于五松山赠南陵常赞府','李白','quantangshi','','卷9','为草当作兰，为木当作松。
兰秋香风远，松寒不改容。
松兰相因依，萧艾徒丰茸。
鸡与鸡并食，鸾与鸾同枝。
拣珠去沙砾，但有珠相随。
远客投名贤，真堪写怀抱。
若惜方寸心，待谁可倾倒。
虞卿弃赵相，便与魏齐行。
海上五百人，同日死田横。
当时不好贤，岂传千古名。
愿君同心人，于我少留情。
寂寂还寂寂，出门迷所适。
长铗归来乎，秋风思归客。','',''),('quantangshi-08337','自梁园至敬亭山见会公谈陵阳山水兼期同游因有此赠','李白','quantangshi','','卷9','我随秋风来，瑶草恐衰歇。
中途寡名山，安得弄云月。
渡江如昨日，黄叶向人飞。
敬亭惬素尚，弭棹流清辉。
冰谷明且秀，陵峦抱江城。
粲粲吴与史，衣冠耀天京。
水国饶英奇，潜光卧幽草。
会公真名僧，所在即为宝。
开堂振白拂，高论横青云。
雪山扫粉壁，墨客多新文。
为余话幽栖，且述陵阳美。
天开白龙潭，月映清秋水。
黄山望石柱，突兀谁开张。
黄鹤久不来，子安在苍茫。
东南焉可穷，山鸟飞绝处。
稠叠千万峰，相连入云去。
闻此期振策，归来空闭关。
相思如明月，可望不可攀。
何当移白足，早晚凌苍山。
且寄一书札，令予解愁颜。','',''),('quantangshi-08338','赠友人三首 一','李白','quantangshi','','卷9','兰生不当户，别是闲庭草。
夙被霜露欺，红荣已先老。
谬接瑶华枝，结根君王池。
顾无馨香美，叨沐清风吹。
余芳若可佩，卒岁长相随。','',''),('quantangshi-08339','赠友人三首 二','李白','quantangshi','','卷9','袖中赵匕首，买自徐夫人。
玉匣闭霜雪，经燕复历秦。
其事竟不捷，沦落归沙尘。
持此愿投赠，与君同急难。
荆卿一去后，壮士多摧残。
长号易水上，为我扬波澜。
凿井当及泉，张帆当济川。
廉夫唯重义，骏马不劳鞭。
人生贵相知，何必金与钱。','',''),('quantangshi-08340','赠友人三首 三','李白','quantangshi','','卷9','慢世薄功业，非无胷中画。
谑浪万古贤，以为儿童剧。
立产如广费，匡君怀长策。
但苦山北寒，谁知道南宅。
岁酒上逐风，霜鬓两边白。
蜀主思孔明，晋家望安石。
时人列五鼎，谈笑期一掷。
虎伏被胡尘，渔歌游海滨。
弊裘耻妻嫂，长劒托交亲。
夫子秉家义，羣公难与隣。
莫持西江水，空许东溟臣。
他日青云去，黄金报主人。','',''),('quantangshi-08341','陈情赠友人','李白','quantangshi','','卷9','延陵有宝劒，价重千黄金。
观风历上国，暗许故人深。
归来挂坟松，万古知其心。
懦夫感达节，壮士激青衿。
鲍生荐夷吾，一举置齐相。
斯人无良朋，岂有青云望。
临财不苟取，推分固词让。
后世称其贤，英风邈难尚。
论交但若此，友道孰云丧。
多君骋逸藻，掩映当时人。
舒文振颓波，秉德冠彝伦。
卜居乃此地，共井为比隣。
清琴弄云月，美酒娱冬春。
薄德中见捐，忽之如遗尘。
英豪未豹变，自古多艰辛。
他人纵以疎，君意宜独亲。
奈何成离居，相去复几许。
飘风吹云霓，蔽目不得语。
投珠冀相报，按劒恐相距。
所思采芳兰，欲赠隔荆渚。
沈忧心若醉，积恨泪如雨。
愿假东壁辉，余光照贫女。','',''),('quantangshi-08342','赠从弟冽','李白','quantangshi','','卷9','楚人不识凤，重价求山鸡。
献主昔云是，今来方觉迷。
自居漆园北，久别咸阳西。
风飘落日去，节变流莺啼。
桃李寒未开，幽关岂来蹊。
逢君发花萼，若与青云齐。
及此桑叶绿，春蚕起中闺。
日出布谷鸣，田家拥锄犂。
顾余乏尺土，东作谁相携。
傅说降霖雨，公输造云梯。
羌戎事未息，君子悲涂泥。
报国有长策，成功羞执圭。
无由谒明主，杖策还蓬藜。
他年尔相访，知我在磻溪。','',''),('quantangshi-08343','赠闾丘处士','李白','quantangshi','','卷9','贤人有素业，乃在沙塘陂。
竹影扫秋月，荷衣落古池。
闲读山海经，散帙卧遥帷。
且耽田家乐，遂旷林中期。
野酌劝芳酒，园蔬烹露葵。
如能树桃李，为我结茅茨。','',''),('quantangshi-08344','赠钱征君少阳','李白','quantangshi','','卷9','白玉一杯酒，绿杨三月时。
春风余几日，两鬓各成丝。
秉烛唯须饮，投竿也未迟。
如逢渭川猎，犹可帝王师。','',''),('quantangshi-08345','赠宣州灵源寺仲浚公','李白','quantangshi','','卷9','敬亭白云气，秀色连苍梧。
下映双溪水，如天落镜湖。
此中积龙象，独许浚公殊。
风韵逸江左，文章动海隅。
观心同水月，解领得明珠。
今日逢支遁，高谈出有无。','',''),('quantangshi-08346','赠僧朝美','李白','quantangshi','','卷9','水客凌洪波，长鲸涌溟海。
百川随龙舟，嘘吸竟安在。
中有不死者，探得明月珠。
高价倾宇宙，余辉照江湖。
苞卷金缕褐，萧然若空无。
谁人识此宝，窃笑有狂夫。
了心何言说，各勉黄金躯。','',''),('quantangshi-08347','赠僧行融','李白','quantangshi','','卷9','梁有汤惠休，常从鲍照游。
峨眉史怀一，独映陈公出。
卓绝二道人，结交凤与麟。
行融亦俊发，吾知有英骨。
海若不隐珠，骊龙吐明月。
大海乘虚舟，随波任安流。
赋诗旃檀阁，纵酒鹦鹉洲。
待我适东越，相携上白楼。','',''),('quantangshi-08348','赠黄山胡公求白鹇','李白','quantangshi','','卷9','请以双白璧，买君双白鹇。
白鹇白如锦，白雪耻容颜。
照影玉潭里，刷毛琪树间。
夜栖寒月静，朝步落花闲。
我愿得此鸟，翫之坐碧山。
胡公能辍赠，笼寄野人还。','',''),('quantangshi-08349','登敬亭山南望怀古赠窦主簿','李白','quantangshi','','卷9','敬亭一回首，目尽天南端。
仙者五六人，常闻此游盘。
溪流琴高水，石耸麻姑坛。
白龙降陵阳，黄鹤呼子安。
羽化骑日月，云行翼鸳鸾。
下视宇宙间，四溟皆波澜。
汰绝目下事，从之复何难。
百岁落半途，前期浩漫漫。
彊食不成味，清晨起长叹。
愿随子明去，炼火烧金丹。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-08350','经乱后将避地剡中留赠崔宣城','李白','quantangshi','','卷9','双鹅飞洛阳，五马渡江徼。
何意上东门，胡雏更长啸。
中原走豺虎，烈火焚宗庙。
太白昼经天，颓阳掩余照。
王城皆荡覆，世路成奔峭。
四海望长安，嚬眉寡西笑。
苍生疑落叶，白骨空相吊。
连兵似雪山，破敌谁能料。
我垂北溟翼，且学南山豹。
崔子贤主人，欢娱每相召。
胡牀紫玉笛，却坐青云呌。
杨花满州城，置酒同临眺。
忽思剡溪去，水石远清妙。
雪尽天地明，风开湖山貌。
闷为洛生咏，醉发吴越调。
赤霞动金光，日足森海峤。
独散万古意，闲垂一溪钓。
猨近天上啼，人移月边棹。
无以墨绶苦，来求丹砂要。
华发长折腰，将贻陶公诮。','',''),('quantangshi-08351','献从叔当涂宰阳冰','李白','quantangshi','','卷9','金镜霾六国，亡新乱天经。
焉知高光起，自有羽翼生。
萧曹安𡸣屼，耿贾摧欃枪。
吾家有季父，杰出圣代英。
虽无三台位，不借四豪名。
激昂风云气，终协龙虎精。
弱冠燕赵来，贤彦多逢迎。
鲁连善谈笑，季布折公卿。
遥知礼数绝，常恐不合并。
惕想结宵梦，素心久已冥。
顾慙青云器，谬奉玉樽倾。
山阳五百年，绿竹忽再荣。
高歌振林木，大笑喧雷霆。
落笔洒篆文，崩云使人惊。
吐辞又炳焕，五色罗华星。
秀句满江国，高才掞天庭。
宰邑艰难时，浮云空古城。
居人若剃草，扫地无纤茎。
惠泽及飞走，农夫尽归耕。
广汉水万里，长流玉琴声。
雅颂播吴越，还如泰阶平。
小子别金陵，来时白下亭。
羣凤怜客鸟，差池相哀鸣。
各拔五色毛，意重泰山轻。
赠微所费广，斗水浇长鲸。
弹劒歌苦寒，严风起前楹。
月衔天门晓，霜落牛渚清。
长叹即归路，临川空屏营。','',''),('quantangshi-08352','书怀赠南陵常赞府','李白','quantangshi','','卷9','岁星入汉年，方朔见明主。
调笑当时人，中天谢云雨。
一去麒麟阁，遂将朝市乖。
故交不过门，秋草日上阶。
当时何特达，独与我心谐。
置酒凌歊台，欢娱未曾歇。
歌动白紵山，舞回天门月。
问我心中事，为君前致辞。
君看我才能，何似鲁仲尼。
大圣犹不遇，小儒安足悲。
云南五月中，频丧渡泸师。
毒草杀汉马，张兵夺云旗。
至今西二河，流血拥僵尸。
将无七擒略，鲁女惜园葵。
咸阳天下枢，累岁人不足。
虽有数斗玉，不如一盘粟。
赖得契宰衡，持钓慰风俗。
自顾无所用，辞家方来归。
霜惊壮士发，泪满逐臣衣。
以此不安席，蹉跎身世违。
终当灭卫谤，不受鲁人讥。','',''),('quantangshi-08353','赠汪伦','李白','quantangshi','','卷9','李白乘舟将欲行，忽闻岸上踏歌声。
桃花潭水深千尺，不及汪伦送我情。','',''),('quantangshi-08354','安陆白兆山桃花岩寄刘侍御绾','李白','quantangshi','','卷9','云卧三十年，好闲复爱仙。
蓬壶虽冥绝，鸾鹤心悠然。
归来桃花岩，得憩云窗眠。
对岭人共语，饮潭猨相连。
时升翠微上，邈若罗浮巅。
两岑抱东壑，一嶂横西天。
树杂日易隐，崖倾月难圆。
芳草换野色，飞萝摇春烟。
入远构石室，选幽开上田。
独此林下意，杳无区中缘。
永辞霜台客，千载方来旋。','',''),('quantangshi-08355','淮南卧病书怀寄蜀中赵征君蕤','李白','quantangshi','','卷9','吴会一浮云，飘如远行客。
功业莫从就，岁光屡奔迫。
良图俄弃损，衰疾乃绵剧。
古琴藏虚匣，长劒挂空壁。
楚冠怀钟仪，越吟比庄舃。
国门遥天外，乡路远山隔。
朝忆相如台，夜梦子云宅。
旅情初结缉，秋气方寂历。
风入松下清，露出草间白。
故人不可见，幽梦谁与适。
寄书西飞鸿，赠尔慰离析。','',''),('quantangshi-08356','寄弄月溪吴山人','李白','quantangshi','','卷9','尝闻庞德公，家住洞湖水。
终身栖鹿门，不入襄阳市。
夫君弄明月，灭景清淮里。
高踪邈难追，可与古人比。
清扬杳莫覩，白云空望美。
待我辞人间，携手访松子。','',''),('quantangshi-08357','秋山寄卫尉张卿及王征君','李白','quantangshi','','卷9','何以折相赠，白花青桂枝。
月华若夜雪，见此令人思。
虽然剡溪兴，不异山阴时。
明发怀二子，空吟招隐诗。','',''),('quantangshi-08358','望终南山寄紫阁隐者','李白','quantangshi','','卷9','出门见南山，引领意无限。
秀色难为名，苍翠日在眼。
有时白云起，天际自舒卷。
心中与之然，托兴每不浅。
何当造幽人，灭迹栖绝巘。','',''),('quantangshi-08359','夕霁杜陵登楼寄韦繇','李白','quantangshi','','卷9','浮阳灭霁景，万物生秋容。
登楼送远目，伏槛观羣峰。
原野旷超缅，关河纷杂重。
清晖映竹日，翠色明云松。
蹈海寄遐想，还山迷旧踪。
徒然迫晚暮，未果谐心胷。
结桂空伫立，折麻恨莫从。
思君达永夜，长乐闻疎钟。','',''),('quantangshi-08360','秋夜宿龙门香山寺奉寄王方城十七丈奉国莹上人从弟幼成令问','李白','quantangshi','','卷9','朝发汝海东，暮栖龙门中。
水寒夕波急，木落秋山空。
望极九霄迥，赏幽万壑通。
目皓沙上月，心清松下风。
玉斗横网户，银河耿花宫。
兴在趣方逸，欢余情未终。
凤驾忆王子，虎溪怀远公。
桂枝坐萧瑟，棣华不复同。
流恨寄伊水，盈盈焉可穷。','',''),('quantangshi-08361','春日独坐寄郑明府','李白','quantangshi','','卷9','燕麦青青游子悲，河堤弱柳郁金枝。
长条一拂春风去，尽日飘扬无定时。
我在河南别离久，那堪坐此对窻牖。
情人道来竟不来，何人共醉新丰酒。','',''),('quantangshi-08362','寄淮南友人','李白','quantangshi','','卷9','红颜悲旧国，青岁歇芳洲。
不待金门诏，空持宝劒游。
海云迷驿道，江月隐乡楼。
复作淮南客，因逢桂树留。','',''),('quantangshi-08363','沙丘城下寄杜甫','李白','quantangshi','','卷9','我来竟何事，高卧沙丘城。
城边有古树，日夕连秋声。
鲁酒不可醉，齐歌空复情。
思君若汶水，浩荡寄南征。','',''),('quantangshi-08364','闻丹丘子于城北营石门幽居中有高凤遗迹仆离羣远怀亦有栖遁之志因叙旧以寄之','李白','quantangshi','','卷9','春华沧江月，秋色碧海云。
离居盈寒暑，对此长思君。
思君楚水南，望君淮山北。
梦魂虽飞来，会面不可得。
畴昔在嵩阳，同衾卧羲皇。
绿萝笑簪绂，丹壑贱岩廊。
晚途各分析，乘兴任所适。
仆在雁门关，君为峨眉客。
心悬万里外，影滞两乡隔。
长劒复归来，相逢洛阳陌。
陌上何喧喧，都令心意烦。
迷津觉路失，托势随风飜。
以兹谢朝列，长啸归故园。
故园恣闲逸，求古散缥帙。
久欲入名山，婚娶殊未毕。
人生信多故，世事岂惟一。
念此忧如焚，怅然若有失。
闻君卧石门，宿昔契弥敦。
方从桂树隐，不羡桃花源。
高风起遐旷，幽人迹复存。
松风清瑶瑟，溪月湛芳樽。
安居偶佳赏，丹心期此论。','',''),('quantangshi-08365','淮阴书怀寄王宗成','李白','quantangshi','','卷9','沙墩至梁苑，二十五长亭。
大舶夹双橹，中流鹅鹳鸣。
云天扫空碧，川岳涵余清。
飞凫从西来，适与佳兴并。
眷言王乔舃，婉娈故人情。
复此亲懿会，而增交道荣。
沿洄且不定，飘忽怅徂征。
暝投淮阴宿，欣得漂母迎。
斗酒烹黄鸡，一餐感素诚。
予为楚壮士，不是鲁诸生。
有德必报之，千金耻为轻。
缅书羇孤意，远寄棹歌声。','',''),('quantangshi-08366','闻王昌龄左迁龙标遥有此寄','李白','quantangshi','','卷9','杨花落尽子规啼，闻道龙标过五溪。
我寄愁心与明月，随风直到夜郎西。','',''),('quantangshi-08367','寄王屋山人孟大融','李白','quantangshi','','卷9','我昔东海上，劳山餐紫霞。
亲见安期公，食枣大如瓜。
中年谒汉主，不惬还归家。
朱颜谢春辉，白发见生涯。
所期就金液，飞步登云车。
愿随夫子天坛上，闲与仙人扫落花。','',''),('quantangshi-08368','忆旧游寄谯郡元参军','李白','quantangshi','','卷9','忆昔洛阳董糟丘，为余天津桥南造酒楼。
黄金白璧买歌笑，一醉累月轻王侯。
海内贤豪青云客，就中与君心莫逆。
迥山转海不作难，倾情倒意无所惜。
我向淮南攀桂枝，君留洛北愁梦思。
不忍别，还相随，相随迢迢访仙城。
三十六曲水回萦，一溪初入千花明。
万壑度尽松风声，银鞍金络倒平地，汉东太守来相迎。
紫阳之真人，邀我吹玉笙。
餐霞楼上动仙乐，嘈然宛似鸾凤鸣。
袖长管催欲轻举，汉中太守醉起舞。
手持锦袍覆我身，我醉横眠枕其股。
当筵意气凌九霄，星离雨散不终朝，分飞楚关山水遥。
余既还山寻故巢，君亦归家渡渭桥。
君家严君勇貔虎，作尹并州遏戎虏。
五月相呼度太行，摧轮不道羊肠苦。
行来北凉岁月深，感君贵义轻黄金。
琼杯绮食青玉案，使我醉饱无归心。
时时出向城西曲，晋祠流水如碧玉。
浮舟弄水箫鼓鸣，微波龙鳞莎草绿。
兴来携妓恣经过，其若杨花似雪何。
红妆欲醉宜斜日，百尺清潭写翠娥。
翠娥婵娟初月辉，美人更唱舞罗衣。
清风吹歌人空去，歌曲自绕行云飞。
此时行乐难再遇，西游因献长杨赋。
北阙青云不可期，东山白首还归去。
渭桥南头一遇君，酇台之北又离羣。
问余别恨知多少，落花春暮争纷纷。
言亦不可尽，情亦不可极。
呼儿长跪缄此辞，寄君千里遥相忆。','',''),('quantangshi-08369','月夜江行寄崔员外宗之','李白','quantangshi','','卷9','飘飘江风起，萧飒海树秋。
登舻美清夜，挂席移轻舟。
月随碧山转，水合青天流。
杳如星河上，但觉云林幽。
归路方浩浩，徂川去悠悠。
徒悲蕙草歇，复听菱歌愁。
岸曲迷后浦，沙明瞰前洲。
怀君不可见，望远增离忧。','',''),('quantangshi-08370','宿白鹭洲寄杨江宁','李白','quantangshi','','卷9','朝别朱雀门，暮栖白鹭洲。
波光摇海月，星影入城楼。
望美金陵宰，如思琼树忧。
徒令魂入梦，飜觉夜成秋。
绿水解人意，为余西北流。
因声玉琴里，荡漾寄君愁。','',''),('quantangshi-08371','新林浦阻风寄友人','李白','quantangshi','','卷9','潮水定可信，天风难与期。
清晨西北转，薄暮东南吹。
以此难挂席，佳期益相思。
海月破圆影，菰蒋生绿池。
昨日北湖梅，开花已满枝。
今朝东门柳，夹道垂青丝。
岁物忽如此，我来定几时。
纷纷江上雪，草草客中悲。
明发新林浦，空吟谢朓诗。','',''),('quantangshi-08372','寄韦南陵冰余江上乘兴访之遇寻颜尚书笑有此赠','李白','quantangshi','','卷9','南船正东风，北船来自缓。
江上相逢借问君，语笑未了风吹断。
闻君携伎访情人，应为尚书不顾身。
堂上三千珠履客，瓮中百斛金陵春。
恨我阻此乐，淹留楚江滨。
月色醉远客，山花开欲然。
春风狂杀人，一日剧三年。
乘兴嫌太迟，焚却子猷船。
梦见五柳枝，已堪挂马鞭。
何日到彭泽，长歌陶令前。','',''),('quantangshi-08373','题情深树寄象公','李白','quantangshi','','卷9','肠断枝上猨，泪添山下樽。
白云见我去，亦为我飞翻。','',''),('quantangshi-08374','北山独酌寄韦六','李白','quantangshi','','卷9','巢父将许由，未闻买山隐。
道存迹自高，何惮去人近。
纷吾下兹岭，地闲喧亦泯。
门横羣岫开，水凿众泉引。
屏高而在云，窦深莫能准。
川光昼昏凝，林气夕凄紧。
于焉摘朱果，兼得养玄牝。
坐月观宝书，拂霜弄瑶轸。
倾壶事幽酌，顾影还独尽。
念君风尘游，傲尔令自哂。','',''),('quantangshi-08375','寄当涂赵少府炎','李白','quantangshi','','卷9','晚登高楼望，木落双江清。
寒山饶积翠，秀色连州城。
目送楚云尽，心悲胡雁声。
相思不可见，回首故人情。','',''),('quantangshi-08376','寄东鲁二稚子','李白','quantangshi','','卷9','吴地桑叶绿，吴蚕已三眠。
我家寄东鲁，谁种龟阴田。
春事已不及，江行复茫然。
南风吹归心，飞堕酒楼前。
楼东一株桃，枝叶拂青烟。
此树我所种，别来向三年。
桃今与楼齐，我行尚未旋。
娇女字平阳，折花倚桃边。
折花不见我，泪下如流泉。
小儿名伯禽，与姊亦齐肩。
双行桃树下，抚背复谁怜。
念此失次第，肝肠日忧煎。
裂素写远意，因之汶阳川。','',''),('quantangshi-08377','独酌清溪江石上寄权昭夷','李白','quantangshi','','卷9','我携一樽酒，独上江祖石。
自从天地开，更长几千尺。
举杯向天笑，天回日西照。
永愿坐此石，长垂严陵钓。
寄谢山中人，可与尔同调。','',''),('quantangshi-08378','禅房怀友人岑伦','李白','quantangshi','','卷9','婵娟罗浮月，摇艳桂水云。
美人竟独往，而我安得羣。
一朝语笑隔，万里懽情分。
沈吟彩霞没，梦寐羣芳歇。
归鸿渡三湘，游子在百粤。
边尘染衣劒，白日雕华发。
春风变楚关，秋声落吴山。
草木结悲绪，风沙凄苦颜。
朅来已永久，颓思如循环。
飘飘限江裔，想像空留滞。
离忧每醉心，别泪徒盈袂。
坐愁青天末，出望黄云蔽。
目极何悠悠，梅花南岭头。
空长灭征鸟，水阔无还舟。
宝劒终难托，金囊非易求。
归来傥有问，桂树山之幽。','',''),('quantangshi-08379','庐山谣寄卢侍御虚舟','李白','quantangshi','','卷9','我本楚狂人，凤歌笑孔丘。
手持绿玉杖，朝别黄鹤楼。
五岳寻仙不辞远，一生好入名山游。
庐山秀出南斗傍，屏风九叠云锦张，影落明湖青黛光。
金阙前开二峰长，银河倒挂三石梁。
香炉瀑布遥相望，回厓沓嶂凌苍苍。
翠影红霞映朝日，鸟飞不到吴天长。
登高壮观天地间，大江茫茫去不还。
黄云万里动风色，白波九道流雪山。
好为庐山谣，兴因庐山发。
闲窥石镜清我心，谢公行处苍苔没。
早服还丹无世情，琴心三叠道初成。
遥见仙人彩云里，手把芙蓉朝玉京。
先期汗漫九垓上，愿接卢敖游太清。','',''),('quantangshi-08380','下寻阳城泛彭蠡寄黄判官','李白','quantangshi','','卷9','浪动灌婴井，寻阳江上风。
开帆入天镜，直向彭湖东。
落景转疎雨，晴云散远空。
名山发佳兴，清赏亦何穷。
石镜挂遥月，香炉灭彩虹。
相思俱对此，举目与君同。','',''),('quantangshi-08381','书情寄从弟邠州长史昭','李白','quantangshi','','卷9','自笑客行久，我行定几时。
绿杨已可折，攀取最长枝。
翩翩弄春色，延伫寄相思。
谁言贵此物，意愿重琼蕤。
昨梦见惠连，朝吟谢公诗。
东风引碧草，不觉生华池。
临翫忽云夕，杜鹃夜鸣悲。
怀君芳岁歇，庭树落红滋。','',''),('quantangshi-08382','寄王汉阳','李白','quantangshi','','卷9','南湖秋月白，王宰夜相邀。
锦帐郎官醉，罗衣舞女娇。
笛声喧沔鄂，歌曲上云霄。
别后空愁我，相思一水遥。','',''),('quantangshi-08383','春日归山寄孟浩然','李白','quantangshi','','卷9','朱绂遗尘境，青山谒梵筵。
金绳开觉路，宝筏度迷川。
岭树攒飞栱，岩花覆谷泉。
墖形标海月，楼势出江烟。
香气三天下，钟声万壑连。
荷秋珠已满，松密盖初圆。
鸟聚疑闻法，龙参若护禅。
愧非流水韵，叨入伯牙弦。','',''),('quantangshi-08384','流夜郎永华寺寄寻阳羣官','李白','quantangshi','','卷9','朝别凌烟楼，贤豪满行舟。
暝投永华寺，宾散予独醉。
愿结九江流，添成万行泪。
写意寄庐岳，何当来此地。
天命有所悬，安得苦愁思。','',''),('quantangshi-08385','流夜郎至西塞驿寄裴隐','李白','quantangshi','','卷9','扬帆借天风，水驿苦不缓。
平明及西塞，已先投沙伴。
回峦引羣峰，横蹙楚山断。
砯冲万壑会，震沓百川满。
龙怪潜溟波，俟时救炎旱。
我行望雷雨，安得霑枯散。
鸟去天路长，人愁春光短。
空将泽畔吟，寄尔江南管。','',''),('quantangshi-08386','自汉阳病酒归寄王明府','李白','quantangshi','','卷9','去岁左迁夜郎道，琉璃砚水长枯槁。
今年敕放巫山阳，蛟龙笔翰生辉光。
圣主还听子虚赋，相如却与论文章。
愿扫鹦鹉洲，与君醉百场。
啸起白云飞七泽，歌吟渌水动三湘。
莫惜连船沽美酒，千金一掷买春芳。','',''),('quantangshi-08387','望汉阳柳色寄王宰','李白','quantangshi','','卷9','汉阳江上柳，望客引东枝。
树树花如雪，纷纷乱若丝。
春风传我意，草木别前知。
寄谢弦歌宰，西来定未迟。','',''),('quantangshi-08388','江夏寄汉阳辅录事','李白','quantangshi','','卷9','谁道此水广，狭如一匹练。
江夏黄鹤楼，青山汉阳县。
大语犹可闻，故人难可见。
君草陈琳檄，我书鲁连箭。
报国有壮心，龙颜不回眷。
西飞精卫鸟，东海何由填。
鼓角徒悲鸣，楼船习征战。
抽劒步霜月，夜行空庭徧。
长呼结浮云，埋没顾荣扇。
他日观军容，投壶接高宴。','',''),('quantangshi-08389','早春寄王汉阳','李白','quantangshi','','卷9','闻道春还未相识，走傍寒梅访消息。
昨夜东风入武阳，陌头杨柳黄金色。
碧水浩浩云茫茫，美人不来空断肠。
预拂青山一片石，与君连日醉壶觞。','',''),('quantangshi-08390','江上寄巴东故人','李白','quantangshi','','卷9','汉水波浪远，巫山云雨飞。
东风吹客梦，西落此中时。
觉后思白帝，佳人与我违。
瞿塘饶贾客，音信莫令稀。','',''),('quantangshi-08391','江上寄元六林宗','李白','quantangshi','','卷9','霜落江始寒，枫叶绿未脱。
客行悲清秋，永路苦不达。
沧波眇川汜，白日隐天末。
停棹依林峦，惊猿相呌聒。
夜分河汉转，起视溟涨阔。
凉风何萧萧，流水鸣活活。
浦沙净如洗，海月明可掇。
兰交空怀思，琼树讵解渴。
勖哉沧洲心，岁晚庶不夺。
幽赏颇自得，兴远与谁豁。','',''),('quantangshi-08392','寄从弟宣州长史昭','李白','quantangshi','','卷9','尔佐宣州郡，守官清且闲。
常夸云月好，邀我敬亭山。
五落洞庭叶，三江游未还。
相思不可见，叹息损朱颜。','','');